INSERT INTO characters (char, data) VALUES ('淇', '{"9000": "4001.0", "Chữ Trung Quốc": "淇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 水 | thủy | biểu nghĩa | nước | 其 | kỳ | biểu âm | (biểu âm: qí) | 淇 = 水/氵 (Thủy, biểu nghĩa: nước) + 其 (Kỳ, biểu âm: qí); chữ hình thanh. Bộ 氵 cho biết đây là tên sông, 其 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": nước (氵) kỳ (其) bí — sông Kỳ (淇) trong Kinh Thi là con sông huyền thoại, gắn với những bài thơ tình cổ nhất Trung Quốc. | Gương Hán-Việt | kỳ — ít dùng riêng trong tiếng Việt; biết qua sông Kỳ (淇水) trong Kinh Thi. | Mở khoá kiến thức | Biết 淇 giúp đọc và cảm thụ Kinh Thi: nhiều bài thơ nhắc đến 淇水 (sông Kỳ) như bối cảnh tình yêu và chia ly.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 水 (thủy — nước) là thành phần biểu nghĩa, 其 (kỳ) là thành phần biểu âm (qí). 淇 là tên sông ở tỉnh Hà Nam — 淇水/淇河, con sông xuất hiện nhiều trong Kinh Thi (诗经). Câu thơ nổi tiếng: 淇水汤汤，渐车帷裳 (nước sông Kỳ cuồn cuộn...). Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kỳ Hà (tên sông, ở tỉnh Hà Nam, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4001.0", "Tần Suất % (Jun Da)": "99.744682821", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淇", "Unihan_Traditional (Chữ Phồn thể)": "淇", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ tên sông Kỳ Hà hoặc dùng trong tên người, tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓒', '{"9000": "4002.0", "Chữ Trung Quốc": "瓒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 20 | nét | 瓒 | tán | tượng hình | muôi ngọc dùng trong lễ tế | 瓒 không có phân tích thành phần rõ ràng từ Wiktionary. Có thể chứa bộ 玨/王 (ngọc) là biểu nghĩa, nhưng cấu trúc không được xác nhận học thuật. Là đồ ngọc dùng trong nghi lễ tế tự cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\": ngọc tán (tán — phân tán, không thuần nhất) — 瓒 là ngọc pha tạp hoặc đồ ngọc tế lễ, không phải ngọc thuần khiết. | Gương Hán-Việt | tán — ít dùng trong tiếng Việt; 瓒 là từ chuyên ngành lịch sử, chỉ đồ ngọc tế lễ. | Mở khoá kiến thức | Biết 瓒 giúp đọc văn bản lịch sử và nghi lễ Trung Quốc cổ đại: 璋瓒 (chương tán — các loại đồ ngọc nghi lễ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 瓒 có nghĩa ngọc không hoàn toàn tinh khiết (impure jade) hoặc muôi/cốc làm bằng ngọc dùng trong lễ tế. Glyph tiểu triện và lục thư thông xác nhận. Đây là từ chuyên môn của lịch sử và nghi lễ cổ đại Trung Quốc. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cốc để tưới rượu xuống đất khi tế", "Hạng Tần Suất (Jun Da)": "4002.0", "Tần Suất % (Jun Da)": "99.7449789389", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 赞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王赞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瓒", "Unihan_Traditional (Chữ Phồn thể)": "瓚", "Pinyin_Xie": "zàn", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong văn cổ chỉ loại chén ngọc dùng để rót rượu tế lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篓', '{"9000": "4003.0", "Chữ Trung Quốc": "篓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 婁 | lâu | biểu âm | (biểu âm: lóu → lǒu) | 篓 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 婁 (Lâu, biểu âm: lóu); chữ hình thanh. Bộ 竹 cho biết đây là đồ vật làm bằng tre, 婁 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": trúc (竹) đan lâu (lâu) công — 篓 là giỏ tre đan tỉ mỉ, đựng trà, cá, hay rác; 字纸篓 là sọt giấy. | Gương Hán-Việt | lâu — ít dùng riêng trong tiếng Việt; 篓 dịch là giỏ tre, sọt tre. | Mở khoá kiến thức | Biết 篓 giúp hiểu 字纸篓 (sọt giấy), 茶篓 (giỏ đựng trà), 鱼篓 (giỏ đựng cá) — đồ vật quen thuộc trong đời sống truyền thống.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 竹 (trúc — tre) là thành phần biểu nghĩa, 婁 là thành phần biểu âm (lǒu). 篓 chỉ giỏ tre hoặc sọt tre — đồ đựng truyền thống làm từ tre đan. Thường gặp trong nông thôn Trung Quốc và Việt Nam. Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọt", "Hạng Tần Suất (Jun Da)": "4003.0", "Tần Suất % (Jun Da)": "99.74527454", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篓", "Unihan_Traditional (Chữ Phồn thể)": "簍", "Pinyin_Xie": "lǒu", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu như tre, nứa để chỉ các loại giỏ, sọt đựng đồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虱', '{"9000": "4004.0", "Chữ Trung Quốc": "虱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 8 | nét | 卂 | tấn | biểu âm | (biểu âm: xùn → shī) | 䖵 | côn | biểu nghĩa | côn trùng (dạng cổ) | 虱 = 卂 (Tấn, biểu âm) + 䖵 (Côn, biểu nghĩa: côn trùng); chữ hình thanh. Bộ 䖵 (dạng cổ của 虫虫) cho biết đây là côn trùng, 卂 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": côn trùng (䖵) tấn (卂) công đầu — 虱子 là con rận/chấy bám chặt vào tóc. | Gương Hán-Việt | tất — ít dùng riêng trong tiếng Việt; 虱子 dịch là con rận, con chấy. | Mở khoá kiến thức | Biết 虱 giúp hiểu 虱子 (rận/chấy), 头虱 (rận đầu — chấy trên tóc), và thành ngữ 如蚤得虱 (gặp đúng loại).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 䖵 (côn — côn trùng, dạng cổ) là thành phần biểu nghĩa, 卂 là thành phần biểu âm. 虱 chỉ con rận, con chấy — loại ký sinh trùng nhỏ sống trên tóc và da người/động vật. Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rệp, con rận", "Hạng Tần Suất (Jun Da)": "4004.0", "Tần Suất % (Jun Da)": "99.7455701411", "GavinGrover_Once (Chiết tự trực tiếp)": "㇠ + 䖝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴㇠䖝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㇠", "Unihan_Simplified (Chữ Giản thể)": "虱", "Unihan_Traditional (Chữ Phồn thể)": "虱", "Pinyin_Xie": "shī", "Âm Hán Việt_Xie": "sắt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ các loài ký sinh trùng nhỏ hút máu như chấy, rận. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跻', '{"9000": "4005.0", "Chữ Trung Quốc": "跻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 跻 | tề | tượng hình | leo lên, tiến lên cao | 跻 là chữ giản thể của 躋. Bộ thủ 足 (túc, chân) là thành phần ngữ nghĩa; phần còn lại biểu âm. Chữ hình thanh. Chưa có nguồn cấu trúc rõ ràng trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tề\": bộ 足 (chân) bước lên — ai muốn vươn lên (跻身) phải dùng đôi chân mà trèo. | Gương Hán-Việt | 跻身 (tề thân) — vươn lên, gia nhập hàng ngũ | Mở khoá kiến thức | Biết 跻 mở khoá từ 跻身 (chen vào hàng ngũ, vươn lên địa vị).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 跻 là dạng giản của 躋 — chữ dùng trong văn học cổ mang nghĩa ''leo lên, vươn lên tầm cao''. Bộ 足 (chân) gợi ý hành động di chuyển lên phía trên. Chưa có nguồn học thuật cụ thể về glyph origin cho dạng giản này. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "leo lên, lên cao; mọc lên", "Hạng Tần Suất (Jun Da)": "4005.0", "Tần Suất % (Jun Da)": "99.7458657422", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跻", "Unihan_Traditional (Chữ Phồn thể)": "躋", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết để chỉ việc thăng tiến hoặc đạt đến một vị trí, đẳng cấp cao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龛', '{"9000": "4006.0", "Chữ Trung Quốc": "龛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 11 | nét | 合 | cáp | biểu âm | hợp lại | 龍 | long | biểu nghĩa | rồng, chỉ vật thiêng liêng | 龛 = 合 (Cáp, biểu âm) + 龍 (Long, biểu nghĩa: chỉ vật linh thiêng, tôn quý). Chữ hình thanh — 合 cho âm gần với kān, 龍 cho nghĩa thiêng liêng tôn kính. Theo Thuyết Văn, có thể là dạng biến âm của chữ có 今 thay 合.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kham\": con Rồng (龍) thu mình vào hốc 合 — đó là cái khám thờ, nơi tôn nghiêm chứa tượng Phật. | Gương Hán-Việt | khám thờ — hốc tường để thờ Phật, tượng thần | Mở khoá kiến thức | Biết 龛 mở khoá từ 佛龛 (phật kham — khám thờ Phật), 壁龛 (bích kham — hốc tường).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Thuyết Văn (dẫn qua Wiktionary): 龕 là chữ hình thanh gồm 合 (biểu âm) và 龍 (biểu nghĩa, chỉ sự linh thiêng). Duan Yucai cho rằng đây là dạng biến hình của chữ 𪚕 (今 + 龍). Nghĩa gốc là cái hốc, tháp nhỏ để thờ Phật hoặc thần linh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tháp thờ Phật", "Hạng Tần Suất (Jun Da)": "4006.0", "Tần Suất % (Jun Da)": "99.7461608265", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱合龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龙", "Unihan_Simplified (Chữ Giản thể)": "龛", "Unihan_Traditional (Chữ Phồn thể)": "龕", "Pinyin_Xie": "kān", "Âm Hán Việt_Xie": "kham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cái khám thờ hoặc hốc nhỏ trên tường để đặt tượng Phật, bài vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹒', '{"9000": "4007.0", "Chữ Trung Quốc": "蹒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 蹒 | bàn | tượng hình | đi khập khiễng, bước chân chậm chạp | 蹒 là dạng giản của 蹣. Bộ 足 (túc, chân) gợi ý hành động đi lại; phần còn lại biểu âm. Chữ hình thanh. Anchor không có cấu trúc chi tiết cho dạng giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàn\": bộ 足 (chân) bước đi vòng vèo — 蹒跚 là dáng đi loạng choạng như người say. | Gương Hán-Việt | 蹒跚 (bàn san) — đi khập khiễng, loạng choạng | Mở khoá kiến thức | Biết 蹒 mở khoá từ 蹒跚 (pán shān — bước đi loạng choạng, dùng tả người già hoặc trẻ học đi).", "Tự nguyên_Xie": "蹒 là dạng giản thể của 蹣 — chữ văn học chỉ dáng đi khập khiễng, chậm chạp. Bộ 足 (chân) xác nhận nghĩa liên quan đến dáng đi. Thường dùng trong từ 蹒跚 (pán shān) — bước đi loạng choạng. Chưa có nguồn học thuật cụ thể về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vượt qua", "Hạng Tần Suất (Jun Da)": "4007.0", "Tần Suất % (Jun Da)": "99.7464559108", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蹒", "Unihan_Traditional (Chữ Phồn thể)": "蹣", "Pinyin_Xie": "pán", "Âm Hán Việt_Xie": "bàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ sân để làm động từ mô tả dáng đi lảo đảo, không vững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髯', '{"9000": "4008.0", "Chữ Trung Quốc": "髯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 15 | nét | 髯 | nhẹm | tượng hình | râu, ria mép mọc hai bên mặt | 髯 có bộ 髟 (biêu, tóc dài) là gốc ý nghĩa chỉ tóc/râu. Phần còn lại biểu âm. Chữ hình thanh. Chỉ có ảnh Lục thư thông, chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẹm\": bộ 髟 (tóc) rủ xuống hai bên má — đó là bộ râu ria oai phong của tướng soái. | Gương Hán-Việt | râu nhẹm — râu ria mép dài | Mở khoá kiến thức | Biết 髯 mở khoá từ 美髯公 (mỹ nhẹm công — người râu đẹp, chỉ Quan Vũ), 虯髯 (cầu nhẹm — râu xoăn).", "Tự nguyên_Xie": "Lục thư thông | 髯 chỉ râu hai bên mép, khác với 须 (râu cằm). Bộ 髟 (tóc dài, biểu nghĩa) kết hợp với phần âm. Chữ xuất hiện trong Lục thư thông — chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Dùng nhiều trong văn học cổ để tả mặt người oai vệ có râu đẹp (như 美髯公 — người có bộ râu đẹp, chỉ Quan Vũ). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ria mép", "Hạng Tần Suất (Jun Da)": "4008.0", "Tần Suất % (Jun Da)": "99.7467509951", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 冉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟冉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髯", "Unihan_Traditional (Chữ Phồn thể)": "髥", "Pinyin_Xie": "rán", "Âm Hán Việt_Xie": "nhiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn học cổ để miêu tả người đàn ông có bộ râu quai nón rậm rạp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞠', '{"9000": "4009.0", "Chữ Trung Quốc": "瞠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 目 | mục | biểu nghĩa | mắt | 堂 | đường | biểu âm | 瞠 = 目 (Mục, biểu nghĩa: mắt) + 堂 (Đường, biểu âm). Chữ hình thanh — bộ 目 xác định nghĩa liên quan đến nhìn, 堂 cho âm gần chēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sảng\" (hoặc \"thảng\"): đôi mắt 目 mở to như cái sảnh đường 堂 — 瞠目结舌 là trợn mắt há mồm vì quá kinh ngạc. | Gương Hán-Việt | 瞠目 (sảng mục) — trợn mắt ngạc nhiên | Mở khoá kiến thức | Biết 瞠 mở khoá thành ngữ 瞠目结舌 (trợn mắt há miệng — ngạc nhiên đến mức không nói được).", "Tự nguyên_Xie": "瞠 là chữ hình thanh theo Wiktionary: 目 (mắt, biểu nghĩa) + 堂 (biểu âm). Nghĩa là nhìn thẳng, trợn mắt ngó — diễn tả cái nhìn ngạc nhiên hoặc bất lực, thường dùng trong thành ngữ 瞠目结舌 (trợn mắt há miệng, không nói được gì). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông thẳng, nhìn thẳng", "Hạng Tần Suất (Jun Da)": "4009.0", "Tần Suất % (Jun Da)": "99.7470445291", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞠", "Unihan_Traditional (Chữ Phồn thể)": "瞠", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "sanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ liên kết trong các thành ngữ để chỉ trạng thái trợn mắt nhìn vì kinh ngạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痫', '{"9000": "4010.0", "Chữ Trung Quốc": "痫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 痫 | hãn | tượng hình | bệnh động kinh, co giật | 痫 là dạng giản của 癇. Bộ 疒 (nạch, chỉ bệnh tật) là thành phần ngữ nghĩa. Phần còn lại (giản từ 閒/闲) biểu âm. Chữ hình thanh, chữ giản thể hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãn\": bộ 疒 (bệnh) báo hiệu đây là chứng co giật — 癫痫 là bệnh động kinh. | Gương Hán-Việt | động kinh (癫痫) — bệnh gây co giật | Mở khoá kiến thức | Biết 痫 mở khoá từ 癫痫 (diên hãn — bệnh động kinh), 痫症 (hãn chứng — chứng co giật).", "Tự nguyên_Xie": "Tiểu triện | 痫 là dạng giản thể của 癇, chính thể của nó là 癇 = 疒 (bệnh, biểu nghĩa) + 閒 (biểu âm). Chữ chỉ bệnh động kinh (癫痫 — diên hãn), một chứng bệnh thần kinh gây co giật. Ảnh tiểu triện cho thấy dạng cổ của chữ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điên, động kinh", "Hạng Tần Suất (Jun Da)": "4010.0", "Tần Suất % (Jun Da)": "99.747338063", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 闲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒闲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痫", "Unihan_Traditional (Chữ Phồn thể)": "癇", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong y học để chỉ chứng bệnh co giật hoặc động kinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掂', '{"9000": "4011.0", "Chữ Trung Quốc": "掂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 店 | điếm | biểu âm | 掂 = 扌 (Thủ, bộ tay, biểu nghĩa: dùng tay) + 店 (Điếm, biểu âm). Chữ hình thanh — bộ 扌 xác định nghĩa liên quan đến hành động của tay, 店 cho âm gần diān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giếm\": đôi tay 扌 nâng lên hạ xuống như cân hàng ở cửa điếm 店 — đó là 掂量, cân nhắc xem nặng nhẹ thế nào. | Gương Hán-Việt | 掂量 (giếm lượng) — cân nhắc, ước lượng bằng tay | Mở khoá kiến thức | Biết 掂 mở khoá từ 掂量 (diān liang — cân nhắc, ước tính), 掂掂 (nâng thử xem nặng nhẹ).", "Tự nguyên_Xie": "掂 là chữ hình thanh theo Wiktionary: 扌 (tay, biểu nghĩa) + 店 (biểu âm, âm diān). Nghĩa là cầm trên tay để ước tính trọng lượng — động tác nâng nhẹ một vật lên xuống nhiều lần để cảm nhận độ nặng, từ đó mở rộng nghĩa ước lượng, cân nhắc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ước lượng; áng chừng; ước chừng (trọng lượng bằng tay)", "Hạng Tần Suất (Jun Da)": "4011.0", "Tần Suất % (Jun Da)": "99.7476310802", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 店", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌店", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "店", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掂", "Unihan_Traditional (Chữ Phồn thể)": "掂", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động đặt vật lên lòng bàn tay và khẽ nhấc lên nhấc xuống để đoán sức nặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潼', '{"9000": "4012.0", "Chữ Trung Quốc": "潼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 潼 | đồng | tượng hình | địa danh, ải Đồng Quan; cao lớn, ẩm ướt | 潼 có bộ 氵 (thủy, nước) là thành phần ngữ nghĩa chỉ sông nước. Phần còn lại (童 hoặc 同 biến thể) biểu âm. Chữ hình thanh, chủ yếu dùng làm địa danh. Anchor không có cấu trúc rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": bộ 氵 (nước) chảy qua chỗ cao ngất — đó là ải Đồng Quan (潼關), nơi hiểm yếu bên sông. | Gương Hán-Việt | Đồng Quan (潼關) — ải quan nổi tiếng trong lịch sử Trung Hoa | Mở khoá kiến thức | Biết 潼 mở khoá địa danh 潼关 (Đồng Quan — cửa ải quan trọng ở Thiểm Tây) và 临潼 (Lâm Đồng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 潼 là chữ hình thanh với bộ 氵 (nước, biểu nghĩa) chỉ sông ngòi hay địa hình sông nước. Nghĩa cơ bản là cao, nguy nga, ẩm ướt — nhưng dùng chủ yếu làm địa danh: Đồng Quan (潼關), ải quan hiểm yếu nổi tiếng ở Thiểm Tây. Chưa có nguồn học thuật chi tiết về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tử đồng 梓潼)", "Hạng Tần Suất (Jun Da)": "4012.0", "Tần Suất % (Jun Da)": "99.7479240974", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潼", "Unihan_Traditional (Chữ Phồn thể)": "潼", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ tên sông, tên đất hoặc cửa ải cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酰', '{"9000": "4013.0", "Chữ Trung Quốc": "酰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 酉 | dậu | biểu nghĩa | chỉ hóa chất, axit | 先 | tiên | biểu âm | 酰 = 酉 (Dậu, biểu nghĩa: chỉ rượu/hóa chất) + 先 (Tiên, biểu âm). Chữ hình thanh — 酉 trong hóa học hiện đại chỉ nhóm chất liên quan đến axit hữu cơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: bộ 酉 (dậu — chỉ chất hóa học) + 先 cho âm — 酰 là tên gọi nhóm acyl trong hóa học hữu cơ. | Gương Hán-Việt | acyl (酰基) — nhóm chức hóa học | Mở khoá kiến thức | Biết 酰 mở khoá thuật ngữ hóa học 酰胺 (tiên tinh — amide), 酰基 (tiên cơ — nhóm acyl).", "Tự nguyên_Xie": "酰 là chữ hình thanh hiện đại: 酉 (biểu nghĩa, gốc chỉ rượu, nay dùng cho hóa chất hữu cơ) + 先 (biểu âm, âm xiān). Chữ chỉ nhóm acyl trong hóa học hữu cơ — dạng mới hơn so với 醯 (chữ cũ cùng nghĩa). Thuật ngữ khoa học tự nhiên, không có lịch sử chữ viết cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gốc a-xít", "Hạng Tần Suất (Jun Da)": "4013.0", "Tần Suất % (Jun Da)": "99.7482171145", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 先", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "先", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酰", "Unihan_Traditional (Chữ Phồn thể)": "酰", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học để chỉ gốc axit hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镁', '{"9000": "4014.0", "Chữ Trung Quốc": "镁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 美 | mỹ | biểu âm | 镁 = 金 (Kim, biểu nghĩa: kim loại) + 美 (Mỹ, biểu âm, âm měi). Chữ hình thanh — bộ 金 xác định đây là kim loại, 美 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mỹ\": kim loại 金 đẹp như vẻ 美 — 镁 là magie, kim loại nhẹ sáng rực khi đốt cháy. | Gương Hán-Việt | magie (镁) — nguyên tố Mg | Mở khoá kiến thức | Biết 镁 mở khoá từ 镁合金 (mỹ hợp kim — hợp kim magie), 镁光灯 (mỹ quang đăng — đèn magie, ánh sáng rực).", "Tự nguyên_Xie": "镁 là chữ hình thanh hiện đại: 金 (kim loại, biểu nghĩa) + 美 (biểu âm, âm měi). Chữ dùng để phiên dịch tên nguyên tố Magnesium (Mg) vào tiếng Trung — đặt tên theo nguyên tắc: bộ 金 chỉ kim loại + phần âm 美 gần với âm gốc. Không có lịch sử chữ viết cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "magie; ma-giê; họ Mỹ", "Hạng Tần Suất (Jun Da)": "4014.0", "Tần Suất % (Jun Da)": "99.7485101317", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 美", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅美", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "美", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镁", "Unihan_Traditional (Chữ Phồn thể)": "鎂", "Pinyin_Xie": "měi", "Âm Hán Việt_Xie": "mĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nguyên tố hóa học magie hoặc các hợp chất liên quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灸', '{"9000": "4015.0", "Chữ Trung Quốc": "灸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 7 | nét | 火 | hoả | biểu nghĩa | lửa | 久 | cửu | biểu âm | lâu dài | 灸 = 火 (Hoả, biểu nghĩa: lửa) + 久 (Cửu, biểu âm). Chữ hình thanh — 火 xác định nghĩa liên quan đến lửa, 久 cho âm jiǔ. Phép cứu ngải dùng ngải đốt lửa trên huyệt đạo, hơi nóng truyền lâu (久) vào da.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cứu\": lửa 火 đốt lâu 久 trên huyệt — đó là phép cứu ngải, thuật chữa bệnh bằng ngải đốt. | Gương Hán-Việt | cứu ngải — phép đốt ngải trị bệnh; châm cứu (针灸) | Mở khoá kiến thức | Biết 灸 mở khoá từ 针灸 (châm cứu — acupuncture and moxibustion), 灸法 (phép cứu ngải).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary và Kanjigen: 灸 là chữ hình thanh gồm 火 (lửa, biểu nghĩa) và 久 (biểu âm, âm jiǔ). Nghĩa là phép cứu ngải — dùng ngải cứu đốt trên các huyệt để chữa bệnh theo y học cổ truyền. Chữ có hình tiểu triện, là chữ y học quan trọng trong Đông y. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cứu (lấy ngải cứu châm lửa đốt vào các huyệt để chữa bệnh)", "Hạng Tần Suất (Jun Da)": "4015.0", "Tần Suất % (Jun Da)": "99.7488026321", "GavinGrover_Once (Chiết tự trực tiếp)": "久 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱久火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "久", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "灸", "Unihan_Traditional (Chữ Phồn thể)": "灸", "Pinyin_Xie": "jiǔ", "Âm Hán Việt_Xie": "cứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ phương pháp châm cứu bằng cách đốt lá ngải hoặc làm danh từ chỉ phép cứu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腆', '{"9000": "4016.0", "Chữ Trung Quốc": "腆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腆 | điển | tượng hình | hậu hĩnh, đầy đặn; ưỡn ngực | 腆 có bộ 月/肉 (nhục, thịt/thân thể) là thành phần ngữ nghĩa chỉ hình thể, thể xác. Phần còn lại biểu âm tiǎn. Anchor không có cấu trúc rõ ràng; chỉ có ảnh tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điển\": bộ 肉 (thịt) đầy đặn, căng tròn — 腆着脸 là ưỡn mặt trơ tráo xin xỏ. | Gương Hán-Việt | 腆脸 (điển kiểm) — mặt dày, trơ tráo | Mở khoá kiến thức | Biết 腆 mở khoá cụm 腆着脸 (ưỡn mặt trơ tráo) và 腆胸 (ưỡn ngực, tư thế oai vệ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 腆 có bộ 肉 (thịt/thân thể, biểu nghĩa). Nghĩa cổ là hậu hĩnh, đầy đặn, thịnh vượng — dùng trong văn cổ với nghĩa tốt lành, sung túc. Nay hay gặp trong 腆着脸 (ưỡn mặt ra, trơ tráo) hoặc 腆胸 (ưỡn ngực). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hậu, đầy đặn; khéo, hay", "Hạng Tần Suất (Jun Da)": "4016.0", "Tần Suất % (Jun Da)": "99.7490951325", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 典", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月典", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "典", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腆", "Unihan_Traditional (Chữ Phồn thể)": "腆", "Pinyin_Xie": "tiǎn", "Âm Hán Việt_Xie": "thiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ mô tả sự đầy đặn, hậu hĩnh hoặc trạng thái e thẹn, ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筱', '{"9000": "4017.0", "Chữ Trung Quốc": "筱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre | 攸 | du | biểu âm | 筱 = 竹 (Trúc, biểu nghĩa: tre) + 攸 (Du, biểu âm). Chữ hình thanh — bộ 竹 xác định đây là loài tre, 攸 cho âm xiǎo. Chỉ loài tre mảnh, nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ 竹 (tre) mảnh khảnh như cây sáo tiêu 攸 — 筱 là tre nhỏ, thân mảnh dùng làm sáo. | Gương Hán-Việt | 筱竹 (tiêu trúc) — loài tre nhỏ mảnh | Mở khoá kiến thức | Biết 筱 mở khoá từ 筱竹 (tre nhỏ mảnh) và nhận ra nó trong tên người Trung Quốc (筱 hay dùng đặt tên).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary: 筱 là chữ hình thanh gồm 竹 (tre, biểu nghĩa) và 攸 (biểu âm). Nghĩa gốc là tre mảnh, tre nhỏ. Cũng có nghĩa phụ là dạng thay thế của 小. Chỉ có ảnh Lục thư thông — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tre nhỏ", "Hạng Tần Suất (Jun Da)": "4017.0", "Tần Suất % (Jun Da)": "99.7493876329", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 攸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮攸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筱", "Unihan_Traditional (Chữ Phồn thể)": "筱", "Pinyin_Xie": "xiǎo", "Âm Hán Việt_Xie": "tiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại tre nhỏ hoặc thường xuất hiện trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谆', '{"9000": "4018.0", "Chữ Trung Quốc": "谆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 言 | ngôn | biểu nghĩa | lời nói | 𦎧 | biểu âm | 谆 = 言 (Ngôn, biểu nghĩa: lời nói) + 𦎧 (biểu âm, âm zhūn). Chữ hình thanh — bộ 言 xác định nghĩa liên quan đến lời nói, cách nói. 谆谆 là lối nói ân cần, không mệt mỏi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": bộ 言 (lời) nói đi nói lại thuần thuần — 谆谆教导 là lời dạy bảo ân cần không mỏi. | Gương Hán-Việt | 谆谆 (thuần thuần) — ân cần tha thiết, lời dạy không biết mỏi | Mở khoá kiến thức | Biết 谆 mở khoá thành ngữ 谆谆教导 (lời dạy bảo ân cần, kiên nhẫn) và 谆谆告诫 (lời căn dặn thiết tha).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary: 谆 (chính thể 諄) là chữ hình thanh gồm 言 (lời nói, biểu nghĩa) và 𦎧 (biểu âm). Nghĩa là ân cần, thành khẩn, kiên nhẫn — dùng trong 谆谆 (zhūn zhūn) chỉ cách dạy dỗ hay khuyên bảo tha thiết, lặp đi lặp lại. Chỉ có ảnh Lục thư thông — chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khẩn thiết; tha thiết; ân cần; thành khẩn", "Hạng Tần Suất (Jun Da)": "4018.0", "Tần Suất % (Jun Da)": "99.7496796165", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谆", "Unihan_Traditional (Chữ Phồn thể)": "諄", "Pinyin_Xie": "zhūn", "Âm Hán Việt_Xie": "truân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường làm phó từ bổ nghĩa cho động từ nói, khuyên bảo để thể hiện sự ân cần, tận tình. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骋', '{"9000": "4019.0", "Chữ Trung Quốc": "骋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 10 | nét | 骋 | sính | tượng hình | phi ngựa, phóng nhanh | 骋 có bộ 馬 (mã, ngựa) là thành phần ngữ nghĩa chỉ hành động liên quan đến ngựa. Phần còn lại biểu âm chěng. Chữ hình thanh. Chỉ có ảnh tiểu triện và lục thư thông — không có nguồn glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sính\": bộ 馬 (ngựa) phóng hết sức — 驰骋 là phi ngựa tung hoành, tung tẩy tài năng không giới hạn. | Gương Hán-Việt | 驰骋 (trì sính) — phi ngựa tung hoành, thỏa sức tung tẩy | Mở khoá kiến thức | Biết 骋 mở khoá từ 驰骋 (phi ngựa tung hoành, tung tẩy) và 骋目 (sính mục — phóng tầm mắt ra xa).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 骋 có bộ 馬 (ngựa, biểu nghĩa) gợi ý hành động phi ngựa, lao nhanh. Nghĩa là phi ngựa hết tốc lực, phóng miết — mở rộng thành ý phóng khoáng, tung tẩy tài năng (驰骋). Chỉ có ảnh tiểu triện, không có giáp cốt/kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phi, phóng miết", "Hạng Tần Suất (Jun Da)": "4019.0", "Tần Suất % (Jun Da)": "99.7499710833", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 甹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马甹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骋", "Unihan_Traditional (Chữ Phồn thể)": "騁", "Pinyin_Xie": "chěng", "Âm Hán Việt_Xie": "sính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động phi ngựa nhanh hoặc thỏa sức bày tỏ tâm chí, tài năng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壬', '{"9000": "4020.0", "Chữ Trung Quốc": "壬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 士 | Số nét | 4 | nét | 壬 | nhăm | tượng hình | can Nhâm — thứ 9 trong Thiên Can; vật hình thoi, cọc dệt | 壬 là chữ tượng hình (指事/象形). Theo Wiktionary: hình dáng gốc có thể là cái suốt dệt (ống chỉ), đòn gánh, hoặc rìu hai lưỡi. Nghĩa nguyên thủy chưa rõ; dùng chủ yếu làm can thứ 9 trong Thiên Can.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhăm\": 壬 trông như cái suốt dệt đặt ngang — can thứ chín Nhâm, năm Nhâm Thìn, Nhâm Tý. | Gương Hán-Việt | Nhâm (壬) — can thứ 9 trong Thiên Can | Mở khoá kiến thức | Biết 壬 mở khoá hệ Thiên Can: 壬午年 (năm Nhâm Ngọ), 壬辰 (Nhâm Thìn) và thành ngữ 左壬 (người cực tả, tiếng lóng mạng).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Theo Wiktionary: 壬 là chữ tượng hình, nghĩa gốc chưa xác định rõ. Các giải thích đề xuất: (1) cái suốt dệt/ống chỉ, liên quan đến 榺; (2) đòn gánh, dạng gốc của 任; (3) rìu hai lưỡi. Ảnh giáp cốt, kim văn và bạch thư cho thấy hình dạng qua các thời kỳ. Nay dùng chủ yếu làm can thứ 9 (Nhâm) trong hệ Thiên Can. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "647.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phiệt (613) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có nét phẩy ở trên chữ Thổ (đất). Tượng hình cái mầm non vừa nhô lên khỏi mặt đất, đây là điềm báo điều tốt lành. Giải thích sự chuyển ý: Đây là chữ Tượng hình / Hội ý (chữ Sính 𡈼). Sự sinh trưởng nhú mầm lên. Sính mang nghĩa tốt lành, tài giỏi, ngay thẳng.", "Nghĩa Tiếng Việt_Xie": "Nhâm (ngôi thứ 9 hàng Can); to lớn; gian nịnh", "Hạng Tần Suất (Jun Da)": "4020.0", "Tần Suất % (Jun Da)": "99.7502625501", "GavinGrover_Once (Chiết tự trực tiếp)": "㇒ + 士", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㇒士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "士", "Unihan_Simplified (Chữ Giản thể)": "壬", "Unihan_Traditional (Chữ Phồn thể)": "壬", "Pinyin_Xie": "rén", "Âm Hán Việt_Xie": "nhâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ thiên can Nhâm trong hệ thống lịch pháp cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茗', '{"9000": "4021.0", "Chữ Trung Quốc": "茗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây cỏ | 名 | danh | biểu âm | 茗 = 艸/艹 (Tháu, biểu nghĩa: cây cỏ) + 名 (Danh, biểu âm, âm míng). Chữ hình thanh — bộ 艹 xác định đây là loài thực vật, 名 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": cỏ 艹 có danh 名 thơm — 茗 là búp trà quý, tao nhã hơn chữ 茶 thường dùng. | Gương Hán-Việt | trà minh (茗) — búp trà, trà quý trong thơ văn | Mở khoá kiến thức | Biết 茗 mở khoá từ 香茗 (hương minh — trà thơm), 品茗 (phẩm minh — thưởng trà), 茗茶 (trà búp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary: 茗 là chữ hình thanh gồm 艸 (cỏ/cây, biểu nghĩa) và 名 (biểu âm). Nghĩa gốc là nõn chè, búp trà — đặc biệt là búp trà hái muộn. Mở rộng thành nghĩa trà nói chung, dùng trong thơ văn với sắc thái thanh nhã hơn 茶. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nõn chè, mầm chè; chè, trà", "Hạng Tần Suất (Jun Da)": "4021.0", "Tần Suất % (Jun Da)": "99.7505540169", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 名", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹名", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "名", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茗", "Unihan_Traditional (Chữ Phồn thể)": "茗", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "mính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại trà ngon hoặc lá trà non nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椋', '{"9000": "4022.0", "Chữ Trung Quốc": "椋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 椋 | lương | tượng hình | cây sơn thù du (dogwood); chim sáo | 椋 có bộ 木 (mộc, cây) là thành phần ngữ nghĩa. Phần còn lại biểu âm liáng. Chữ hình thanh. Không có ảnh etymology. Dùng để chỉ cây sơn thù du (Cornus) và chim sáo (椋鸟).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lương\": bộ 木 (cây) mang âm lương — 椋鸟 là chim sáo, loài chim thường đậu trên cây lương mộc. | Gương Hán-Việt | 椋鸟 (lương điểu) — chim sáo | Mở khoá kiến thức | Biết 椋 mở khoá từ 椋鸟 (chim sáo — starling) và tên loài cây 椋子木 (cây dogwood).", "Tự nguyên_Xie": "椋 có bộ 木 (cây, biểu nghĩa) kết hợp phần biểu âm liáng. Chỉ loài cây dogwood (Cornus spp.) và chim sáo (椋鸟 — starling). Chưa có nguồn học thuật chi tiết về glyph origin. Chữ ít phổ biến, chủ yếu gặp trong tên động thực vật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim sáo", "Hạng Tần Suất (Jun Da)": "4022.0", "Tần Suất % (Jun Da)": "99.7508454837", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椋", "Unihan_Traditional (Chữ Phồn thể)": "椋", "Pinyin_Xie": "liáng", "Âm Hán Việt_Xie": "lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu kết hợp với các chữ khác để cấu tạo danh từ chỉ loài chim sáo hoặc một loại cây gỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛔', '{"9000": "4023.0", "Chữ Trung Quốc": "蛔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛔 | hồi | tượng hình | giun đũa, giun ký sinh | 蛔 có bộ 虫 (trùng, côn trùng/sâu bọ) là thành phần ngữ nghĩa. Phần còn lại biểu âm huí. Chữ hình thanh. Ảnh kim văn và tiểu triện cho thấy bộ 虫 hiện diện từ sớm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồi\": con trùng 虫 cuộn 回 trong bụng — 蛔虫 là giun đũa ký sinh trong ruột. | Gương Hán-Việt | 蛔虫 (hồi trùng) — giun đũa | Mở khoá kiến thức | Biết 蛔 mở khoá từ 蛔虫 (hồi trùng — giun đũa), 驱蛔 (khu hồi — thuốc tẩy giun).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 蛔 là chữ hình thanh với bộ 虫 (sâu bọ, biểu nghĩa) chỉ loài sinh vật ký sinh. Âm gốc gần với huí (quay vòng) — có thể ám chỉ hình dạng cuộn tròn của giun. Ảnh kim văn và tiểu triện cho thấy chữ đã tồn tại từ cổ đại. Nay chủ yếu dùng trong từ 蛔虫 (giun đũa). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con giun trong bụng", "Hạng Tần Suất (Jun Da)": "4023.0", "Tần Suất % (Jun Da)": "99.7511364338", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 回", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "回", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛔", "Unihan_Traditional (Chữ Phồn thể)": "痐", "Pinyin_Xie": "huí", "Âm Hán Việt_Xie": "hồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài ký sinh trùng đường ruột là giun đũa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潺', '{"9000": "4024.0", "Chữ Trung Quốc": "潺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 潺 | sờn | tượng hình | tiếng nước chảy rỉ rách | 潺 có bộ 氵 (thủy, nước) là thành phần ngữ nghĩa chỉ nước chảy. Phần còn lại biểu âm chán. Chữ hình thanh. Ảnh tiểu triện xác nhận bộ 氵 từ thời cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sờn\": bộ 氵 (nước) chảy sờn sờn — 潺潺 là tiếng suối róc rách, nhẹ nhàng không dứt. | Gương Hán-Việt | 潺潺 (sờn sờn) — tiếng nước chảy róc rách | Mở khoá kiến thức | Biết 潺 mở khoá từ 潺潺 (tiếng nước chảy rỉ rách) và 潺湲 (nước chảy uốn lượn lặng lẽ).", "Tự nguyên_Xie": "Tiểu triện | 潺 là chữ hình thanh với bộ 氵 (nước, biểu nghĩa) chỉ âm thanh của nước chảy. Nghĩa trong 潺潺 (chán chán) là tiếng nước chảy rỉ rách, róc rách liên tục — âm thanh tượng thanh gắn với cảnh nước suối, mưa nhỏ. Chưa có nguồn học thuật chi tiết về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sàn sàn 潺潺)", "Hạng Tần Suất (Jun Da)": "4024.0", "Tần Suất % (Jun Da)": "99.751426867", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 孱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵孱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潺", "Unihan_Traditional (Chữ Phồn thể)": "潺", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "sàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Chữ này thường dùng làm tính từ miêu tả âm thanh hoặc trạng thái nước chảy róc rách, chủ yếu xuất hiện trong từ láy 潺潺. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扉', '{"9000": "4025.0", "Chữ Trung Quốc": "扉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戶 | Số nét | 12 | nét | 戶 | hộ | biểu nghĩa | cửa, cánh cửa | 非 | phi | biểu âm | 扉 = 戶 (Hộ, biểu nghĩa: cửa một cánh) + 非 (Phi, biểu âm). Chữ hình thanh — bộ 戶 xác định nghĩa là cánh cửa, 非 cho âm fēi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": cánh cửa 戶 mở ra như đôi cánh phi 非 — 扉 là tấm cánh cửa, thi văn hay dùng 心扉 — cánh cửa tâm hồn. | Gương Hán-Việt | tâm phi (心扉) — cánh cửa tâm hồn; sài phi (柴扉) — cửa rào tranh | Mở khoá kiến thức | Biết 扉 mở khoá từ 心扉 (tâm phi — tâm hồn), 扉页 (phi trang — trang lót sách), 柴扉 (cổng tre/rào tranh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary: 扉 là chữ hình thanh gồm 戶 (cửa một cánh, biểu nghĩa) và 非 (biểu âm, âm fēi). Nghĩa là cánh cửa (door panel/leaf) — chỉ từng tấm cánh của cánh cửa hai cánh. Dùng trong thơ văn: 柴扉 (cửa rào tranh), 心扉 (cánh cửa tâm hồn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh cửa", "Hạng Tần Suất (Jun Da)": "4025.0", "Tần Suất % (Jun Da)": "99.7517167835", "GavinGrover_Once (Chiết tự trực tiếp)": "户 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴户非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "户", "Unihan_Simplified (Chữ Giản thể)": "扉", "Unihan_Traditional (Chữ Phồn thể)": "扉", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ cánh cửa, thường dùng trong văn viết hoặc kết hợp thành từ ghép như môn phi, tâm phi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耘', '{"9000": "4026.0", "Chữ Trung Quốc": "耘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 10 | nét | 耘 | vân | tượng hình | làm cỏ, nhổ cỏ ruộng | 耘 có bộ 耒 (lỗi, cái cày) là thành phần ngữ nghĩa chỉ công việc đồng áng. Phần còn lại biểu âm yún. Chữ hình thanh. Chỉ có ảnh lục thư thông — chữ tạo muộn, không có giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": cái cày 耒 vun vén đám mây 云 cỏ dại — 耕耘 là cày bừa vun đắp, ẩn dụ cho công sức lao động không ngừng. | Gương Hán-Việt | 耕耘 (canh vân) — cày cấy làm cỏ; ẩn dụ lao động bền bỉ | Mở khoá kiến thức | Biết 耘 mở khoá từ 耕耘 (canh vân — cày bừa, ẩn dụ công sức), 辛勤耕耘 (chăm chỉ vun đắp).", "Tự nguyên_Xie": "Lục thư thông | 耘 có bộ 耒 (công cụ nông nghiệp, biểu nghĩa) chỉ hành động làm cỏ ruộng bằng dụng cụ. Nghĩa là nhổ cỏ, làm cỏ — công việc nông nghiệp truyền thống. Dùng trong cặp 耕耘 (cày cấy và làm cỏ) — ẩn dụ cho công sức lao động bền bỉ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm cỏ", "Hạng Tần Suất (Jun Da)": "4026.0", "Tần Suất % (Jun Da)": "99.7520061831", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耘", "Unihan_Traditional (Chữ Phồn thể)": "耘", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hoạt động làm cỏ trong nông nghiệp, thường đi kèm với canh trong cụm canh vân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槟', '{"9000": "4027.0", "Chữ Trung Quốc": "槟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 槟 | tân | tượng hình | cây cau, quả cau | 槟 là dạng giản của 檳. Bộ 木 (mộc, cây) là thành phần ngữ nghĩa. Phần còn lại (giản từ 賓/宾) biểu âm bīn. Chữ hình thanh. Anchor là dạng giản, không có ảnh etymology.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": cây 木 đón khách 賓 (tân) — 槟榔 là quả cau, xưa dùng trong lễ đón tiếp khách quý và lễ cưới. | Gương Hán-Việt | tân lang (槟榔) — cây cau, quả cau | Mở khoá kiến thức | Biết 槟 mở khoá từ 槟榔 (tân lang — cau), 槟城 (tân thành — thành phố Penang Malaysia).", "Tự nguyên_Xie": "槟 là dạng giản thể của 檳, chính thể gồm 木 (cây, biểu nghĩa) và 賓 (biểu âm, âm bīn). Nghĩa là cây cau, quả cau — tiếng Trung gọi là 槟榔 (빈랑 — betel nut/areca nut). Tên thành phố Penang (Pinang) của Malaysia cũng có gốc từ chữ này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cau", "Hạng Tần Suất (Jun Da)": "4027.0", "Tần Suất % (Jun Da)": "99.752295066", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槟", "Unihan_Traditional (Chữ Phồn thể)": "檳", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây cau hoặc quả cau, thường xuất hiện trong từ ghép tân lang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雹', '{"9000": "4028.0", "Chữ Trung Quốc": "雹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 13 | nét | 雨 | vũ | biểu nghĩa | mưa | 包 | bao | biểu âm | gói, bao | 雹 = 雨 (Vũ, biểu nghĩa: mưa) + 包 (Bao, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 雨 cho nghĩa (hiện tượng mưa), 包 cho âm báo. Chữ hình thanh điển hình, có nguồn gốc từ rất sớm (giáp cốt văn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": mưa (雨) bao bọc (包) những viên đá nhỏ từ trên trời — đó là mưa đá 冰雹. | Gương Hán-Việt | \"bạc\" trong 冰雹 (băng bạc — mưa đá) | Mở khoá kiến thức | Biết 雹 mở khoá 冰雹 (mưa đá), 雹灾 (thiên tai mưa đá), 雹子 (những viên đá nhỏ từ mưa đá).", "Tự nguyên_Xie": "Giáp cốt văn | Bạch thư | Đại triện | Tiểu triện | Chữ 雹 (bạc) là chữ hình thanh (ls=psc): bộ 雨 (Vũ — mưa) biểu nghĩa; 包 (Bao) biểu âm cho âm báo. Nghĩa gốc: mưa đá — những viên đá nhỏ rơi xuống từ trời trong cơn mưa giông. Giáp cốt văn, bạch thư, đại triện và tiểu triện đều được lưu lại, chứng minh chữ xuất hiện từ thời rất sớm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa đá", "Hạng Tần Suất (Jun Da)": "4028.0", "Tần Suất % (Jun Da)": "99.7525834321", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雹", "Unihan_Traditional (Chữ Phồn thể)": "雹", "Pinyin_Xie": "báo", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hiện tượng mưa đá, thường kết hợp thành từ ghép băng bạc hoặc hạ bạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甬', '{"9000": "4029.0", "Chữ Trung Quốc": "甬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 用 | Số nét | 7 | nét | 甬 | dũng | tượng hình | cái chuông đồng; lối đi; địa danh Ninh Ba | 甬 là chữ tượng hình — hình ảnh cái chuông đồng. Trong kim văn, phần dưới tiến hoá thành 用 (dụng), vừa là phần âm. Tương tự nhưng không liên quan đến 用 hay 角. Chữ tượng hình cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũng\": hình chiếc chuông đồng 甬 treo thẳng — 甬道 là lối đi trung tâm như trục chuông, 甬 cũng là tên tắt của Ninh Ba. | Gương Hán-Việt | 甬道 (dũng đạo) — lối đi trung tâm, hành lang | Mở khoá kiến thức | Biết 甬 mở khoá địa danh 甬 (Ninh Ba), từ 甬道 (lối đi trung tâm trong cung điện/lăng mộ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary: 甬 là chữ tượng hình mô tả cái chuông đồng. Trong kim văn, phần dưới tiến hoá thành 用, đóng vai trò biểu âm. Nghĩa gốc là chuông đồng lớn. Mở rộng thành lối đi ở giữa (甬道), và dùng làm tên tắt của Ninh Ba (Ningbo) — thành phố cảng lịch sử. Giáp cốt văn, kim văn đã có hình dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "532.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dụng (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Dụng (số 142 - dùng) ở dưới và một nét gấp khúc ở trên. Giải thích sự chuyển ý: Chữ Dụng (dùng) chỉ âm, nét gấp khúc ở trên chỉ ý. Lối đi nhỏ hẹp và quanh co gọi là đường ngõ (Dũng). (Biến âm Hán Việt: Dụng -> Dũng)", "Nghĩa Tiếng Việt_Xie": "lối đi ở giữa", "Hạng Tần Suất (Jun Da)": "4029.0", "Tần Suất % (Jun Da)": "99.7528717982", "GavinGrover_Once (Chiết tự trực tiếp)": "龴 + 用", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龴用", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "用", "Unihan_Simplified (Chữ Giản thể)": "甬", "Unihan_Traditional (Chữ Phồn thể)": "甬", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lối đi nhỏ hoặc đường hành lang có mái che, cũng là tên gọi tắt của thành phố Ninh Ba. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谥', '{"9000": "4030.0", "Chữ Trung Quốc": "谥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 谥 | thụy | tượng hình | tên thụy, tên đặt sau khi chết | 谥 là dạng giản của 諡. Bộ 言 (ngôn, lời nói) là thành phần ngữ nghĩa — thụy hiệu là lời đánh giá cuối cùng về một người sau khi mất. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụy\": bộ 言 (lời) phán quyết sau khi chết — 谥号 là tên thụy, lời đời sau phong cho bậc vua chúa. | Gương Hán-Việt | thụy hiệu (谥号) — tên phong sau khi mất | Mở khoá kiến thức | Biết 谥 mở khoá từ 谥号 (thụy hiệu — tên thụy của vua/quan), 上谥 (phong thụy).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 谥 là dạng giản thể, chính thể là 謚 (hay 諡). Bộ 言 (lời nói, biểu nghĩa) phản ánh bản chất: thụy hiệu là lời đánh giá trang trọng đặt cho vua, quan sau khi qua đời. Ví dụ: Hán Cao Tổ, Đường Thái Tông đều là thụy hiệu. Ảnh tiểu triện và lục thư thông cho thấy dạng cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên cúng cơm, tên thuỵ đặt sau khi chết để cúng giỗ", "Hạng Tần Suất (Jun Da)": "4030.0", "Tần Suất % (Jun Da)": "99.7531596476", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谥", "Unihan_Traditional (Chữ Phồn thể)": "諡", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thuỵ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ tên thụy của người đã khuất hoặc làm động từ với nghĩa ban tặng tên thụy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淞', '{"9000": "4031.0", "Chữ Trung Quốc": "淞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thủy | biểu nghĩa | nước, sông | 松 | tùng | biểu âm | 淞 = 氵 (Thủy, biểu nghĩa: sông nước) + 松 (Tùng, biểu âm, âm sōng). Chữ hình thanh — bộ 氵 xác định đây là địa danh sông nước, 松 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tùng\": nước 氵 chảy qua rừng thông 松 — 淞 là sông Tùng, con sông lịch sử ở Thượng Hải (吴淞). | Gương Hán-Việt | 吴淞 (Ngô Tùng) — địa danh lịch sử ở Thượng Hải | Mở khoá kiến thức | Biết 淞 mở khoá địa danh 吴淞 (Ngô Tùng), 淞沪之战 (Trận Tùng Hộ 1932/1937).", "Tự nguyên_Xie": "Theo Wiktionary: 淞 là chữ hình thanh gồm 氵 (nước, biểu nghĩa) và 松 (biểu âm). Dùng chủ yếu làm địa danh: sông Tùng (淞江 — nay là Ngô Tùng Giang/Suzhou River ở Thượng Hải). Nổi tiếng trong lịch sử với Trận Tùng Hộ (淞沪之战 — tháng 1/1932 và 8/1937). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tùng", "Hạng Tần Suất (Jun Da)": "4031.0", "Tần Suất % (Jun Da)": "99.7534474969", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 松", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵松", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "松", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淞", "Unihan_Traditional (Chữ Phồn thể)": "淞", "Pinyin_Xie": "sōng", "Âm Hán Việt_Xie": "tùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên sông Tùng Giang ở Trung Quốc, thường dùng trong địa danh như Ngô Tùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燎', '{"9000": "4032.0", "Chữ Trung Quốc": "燎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 16 | nét | 火 | hoả | biểu nghĩa | lửa | 尞 | biểu âm | 燎 = 火 (Hoả, biểu nghĩa: lửa) + 尞 (biểu âm, âm liáo). Chữ hình thanh — bộ 火 xác định nghĩa liên quan đến lửa cháy lan, 尞 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"leo\": lửa 火 leo 尞 cháy lan — 燎原 là lửa thiêu đốt cả thảo nguyên; 星星之火，可以燎原. | Gương Hán-Việt | 燎原 (leo nguyên) — lửa cháy lan thảo nguyên; ẩn dụ sức mạnh nhỏ thành lớn | Mở khoá kiến thức | Biết 燎 mở khoá thành ngữ 星星之火可以燎原 (ngọn lửa nhỏ đốt cháy nguyên) và 燎原之火 (lửa thiêu nguyên).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary: 燎 là chữ hình thanh gồm 火 (lửa, biểu nghĩa) và 尞 (biểu âm). Nghĩa là đốt lửa ngoài trời, lửa cháy lan rộng — ví dụ điển hình là thành ngữ 星星之火，可以燎原 (ngọn lửa nhỏ có thể đốt cháy cả cánh đồng). Ảnh giáp cốt và tiểu triện cho thấy lịch sử lâu đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháy lan ra", "Hạng Tần Suất (Jun Da)": "4032.0", "Tần Suất % (Jun Da)": "99.7537348294", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "燎", "Unihan_Traditional (Chữ Phồn thể)": "燎", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động thiêu đốt hoặc lửa cháy lan, thường dùng trong văn viết hoặc thành ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕙', '{"9000": "4033.0", "Chữ Trung Quốc": "蕙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艹 | tháu | biểu nghĩa | cỏ, cây cỏ | 惠 | huệ | biểu âm | 蕙 = 艹 (Tháu, biểu nghĩa: cây cỏ) + 惠 (Huệ, biểu âm, âm huì). Chữ hình thanh — bộ 艹 xác định đây là loài thực vật thơm, 惠 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huệ\": cỏ 艹 ân huệ 惠 dịu dàng — 蕙 là hoa huệ lan thơm, biểu tượng phụ nữ thanh lịch; 蕙质兰心. | Gương Hán-Việt | 蕙兰 (huệ lan) — phong lan thơm; 蕙质兰心 (tâm hồn thơm như lan huệ) | Mở khoá kiến thức | Biết 蕙 mở khoá từ 蕙兰 (phong lan thơm), thành ngữ 蕙质兰心 (phẩm chất thơm như lan — người phụ nữ đức hạnh).", "Tự nguyên_Xie": "Theo Wiktionary: 蕙 là chữ hình thanh gồm 艹 (cỏ/cây, biểu nghĩa) và 惠 (biểu âm, cùng âm huì). Nghĩa là cỏ huệ — loài phong lan thơm (蕙兰). Trong thơ văn cổ, 蕙 tượng trưng cho người phụ nữ thanh lịch, đức hạnh (蕙质兰心 — tâm hồn thơm như lan huệ). Tiếng Việt vay mượn qua 蕙 → huệ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "281.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (276) Huệ", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảo (số 276) và chữ Huệ (ân huệ) . Theo người xưa, hoa huệ (thảo) là loài hoa biểu tượng của tấm lòng nhân ái, ân huệ. Giải thích sự chuyển ý: Chữ Huệ (ân huệ) chỉ âm, chữ Thảo (cỏ) chỉ ý. Tên một loài cỏ (Thảo) có mùi thơm ngát (Huệ).", "Nghĩa Tiếng Việt_Xie": "cỏ huệ", "Hạng Tần Suất (Jun Da)": "4033.0", "Tần Suất % (Jun Da)": "99.754022162", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 惠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹惠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕙", "Unihan_Traditional (Chữ Phồn thể)": "蕙", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "huệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cỏ thơm cổ đại, thường dùng để ví với phẩm hạnh cao khiết của người phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚪', '{"9000": "4034.0", "Chữ Trung Quốc": "蚪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚪 | đẩu | tượng hình | con nòng nọc | 蚪 có bộ 虫 (trùng, côn trùng/sinh vật nhỏ) là thành phần ngữ nghĩa. Phần còn lại biểu âm dǒu. Chữ hình thanh. Dùng trong từ 蝌蚪 (nòng nọc). Anchor không có cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đẩu\": con trùng 虫 nhỏ như cái đẩu 斗 — 蝌蚪 là nòng nọc, con nòng nọc chưa mọc chân. | Gương Hán-Việt | 蝌蚪 (khoa đẩu) — nòng nọc | Mở khoá kiến thức | Biết 蚪 mở khoá từ 蝌蚪 (khoa đẩu — nòng nọc) và 蝌蚪文 (chữ nòng nọc — chỉ chữ viết cổ khó đọc).", "Tự nguyên_Xie": "蚪 là chữ hình thanh với bộ 虫 (sinh vật nhỏ, biểu nghĩa) chỉ ấu trùng dưới nước. Phần âm dǒu. Chỉ dùng trong từ 蝌蚪 (kē dǒu — nòng nọc). Ít gặp độc lập. Chưa có nguồn học thuật chi tiết về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khoa đẩu 蝌蚪)", "Hạng Tần Suất (Jun Da)": "4034.0", "Tần Suất % (Jun Da)": "99.7543094945", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚪", "Unihan_Traditional (Chữ Phồn thể)": "蚪", "Pinyin_Xie": "dǒu", "Âm Hán Việt_Xie": "đẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ nhưng hầu như không đứng độc lập mà phải kết hợp thành từ ghép khoa đẩu để chỉ con nòng nọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜻', '{"9000": "4035.0", "Chữ Trung Quốc": "蜻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 青 | thanh | biểu âm | 蜻 = 虫 (Trùng, biểu nghĩa: côn trùng) + 青 (Thanh, biểu âm, âm qīng). Chữ hình thanh — bộ 虫 xác định đây là loài côn trùng, 青 cho âm và gợi màu xanh của chuồn chuồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thanh\": con trùng 虫 xanh 青 — 蜻蜓 là con chuồn chuồn, đôi cánh xanh mỏng như tia nắng. | Gương Hán-Việt | 蜻蜓 (thanh đình) — con chuồn chuồn | Mở khoá kiến thức | Biết 蜻 mở khoá từ 蜻蜓 (thanh đình — chuồn chuồn) và thành ngữ 蜻蜓点水 (chuồn chuồn chấm nước — làm qua loa).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary: 蜻 là chữ hình thanh gồm 虫 (côn trùng, biểu nghĩa) và 青 (biểu âm, âm qīng). 青 cũng gợi màu xanh đặc trưng của chuồn chuồn. Dùng trong từ 蜻蜓 (qīng tíng — chuồn chuồn). Ảnh tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "845.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (287) Thanh (439)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 287 - côn trùng) ở bên trái chữ Thanh (số 439 - màu xanh/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thanh chỉ âm, bộ Trùng chỉ ý. Tinh là con côn trùng (tinh đình = con chuồn chuồn).", "Nghĩa Tiếng Việt_Xie": "(xem: tinh linh 蜻蛉, tinh đình 蜻蜓)", "Hạng Tần Suất (Jun Da)": "4035.0", "Tần Suất % (Jun Da)": "99.7545963102", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜻", "Unihan_Traditional (Chữ Phồn thể)": "蜻", "Pinyin_Xie": "qīng", "Âm Hán Việt_Xie": "thanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chuồn chuồn, thường kết hợp với đình để tạo thành từ ghép thanh đình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郸', '{"9000": "4036.0", "Chữ Trung Quốc": "郸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 10 | nét | 單 | đơn | biểu âm | 阝 | ấp | biểu nghĩa | thành ấp, địa danh | 郸 = 單 (Đơn, biểu âm) + 阝/邑 (Ấp, biểu nghĩa: thành ấp, chỉ địa danh). Chữ hình thanh — bộ 阝 (邑) xác định đây là địa danh, 單 cho âm dān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đan\": bộ 邑 (ấp, thành) + 單 (đơn, biểu âm) — 郸 là chữ trong địa danh 邯郸, kinh đô nước Triệu thời Chiến Quốc. | Gương Hán-Việt | 邯郸 (Hàm Đan) — cố đô nước Triệu | Mở khoá kiến thức | Biết 郸 mở khoá địa danh 邯郸 và thành ngữ 邯郸学步 (học đi kiểu Hàm Đan — bắt chước mất gốc).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary: 鄲 (chính thể) là chữ hình thanh gồm 單 (biểu âm) và 邑/阝 (thành ấp, biểu nghĩa). Dùng trong địa danh 邯鄲 (Hàm Đan — thành phố tỉnh Hà Bắc), kinh đô nước Triệu thời Chiến Quốc. Nổi tiếng qua thành ngữ 邯郸学步 (học theo Hàm Đan mà quên cả đi — bắt chước vụng về). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hàm đan 邯鄲,邯郸)", "Hạng Tần Suất (Jun Da)": "4036.0", "Tần Suất % (Jun Da)": "99.7548826092", "GavinGrover_Once (Chiết tự trực tiếp)": "单 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰单阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郸", "Unihan_Traditional (Chữ Phồn thể)": "鄲", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong địa danh cổ Hàm Đan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轶', '{"9000": "4037.0", "Chữ Trung Quốc": "轶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轶 | dật | tượng hình | vượt qua, siêu xuất; sự tích lưu truyền | 轶 có bộ 車 (xa, xe) là thành phần ngữ nghĩa chỉ xe cộ nhanh, vượt qua. Phần còn lại biểu âm yì. Chữ hình thanh. Chỉ có ảnh tiểu triện. Nghĩa mở rộng: sự tích chưa được ghi chép chính thức (轶事).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\": xe 車 lao dật dật vượt qua — 轶事 là những chuyện ''vượt khỏi'' sử sách chính thống, chuyện giai thoại lưu truyền. | Gương Hán-Việt | 轶事 (dật sự) — giai thoại, chuyện bên lề lịch sử | Mở khoá kiến thức | Biết 轶 mở khoá từ 轶事 (dật sự — giai thoại, chuyện ngoài sử sách), 超轶 (siêu dật — vượt trội).", "Tự nguyên_Xie": "Tiểu triện | 轶 có bộ 車 (xe, biểu nghĩa) gợi ý hành động xe vượt qua, tiến lên nhanh. Nghĩa gốc là xe vượt qua, siêu vượt. Mở rộng thành: (1) xuất chúng, vượt trội; (2) mất mát, thất lạc; (3) 轶事 — chuyện lưu truyền ngoài sử sách. Không có nguồn glyph origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vượt qua; tiến đánh, tấn công", "Hạng Tần Suất (Jun Da)": "4037.0", "Tần Suất % (Jun Da)": "99.7551689082", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轶", "Unihan_Traditional (Chữ Phồn thể)": "軼", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động vượt trội hoặc làm tính từ trong các từ ghép chỉ sự việc tản mát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狰', '{"9000": "4038.0", "Chữ Trung Quốc": "狰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 犬 | khuyển | biểu nghĩa | chó, thú dữ | 爭 | tranh | biểu âm | 狰 = 犬/犭 (Khuyển, biểu nghĩa: chó, thú dữ hung hăng) + 爭 (Tranh, biểu âm, âm zhēng). Chữ hình thanh — bộ 犬 xác định nghĩa liên quan đến thú dữ hung hãn, 爭 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": con chó 犬 tranh 爭 cắn xé — 狰狞 là bộ mặt hung tợn đáng sợ. | Gương Hán-Việt | 狰狞 (tranh nịnh) — hung tợn, mặt mũi dữ tợn | Mở khoá kiến thức | Biết 狰 mở khoá từ 狰狞 (tranh nịnh — hung tợn, dữ dằn) và 面目狰狞 (mặt mũi hung ác).", "Tự nguyên_Xie": "Theo Wiktionary: 狰 (chính thể 猙) là chữ hình thanh gồm 犬 (chó/thú dữ, biểu nghĩa) và 爭 (biểu âm, âm zhēng). Nghĩa là hung tợn, dữ dằn, bộ mặt hung ác. Trong Sơn hải kinh có mô tả con thú 猙: giống báo đỏ, năm đuôi một sừng. Thường gặp trong từ 猙狞/狰狞 — hung tợn xấu xí. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tranh ninh 猙獰,猙狞)", "Hạng Tần Suất (Jun Da)": "4038.0", "Tần Suất % (Jun Da)": "99.7554546904", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 争", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭争", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "争", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狰", "Unihan_Traditional (Chữ Phồn thể)": "猙", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ Ninh tạo thành tính từ mô tả vẻ mặt hung dữ, đáng sợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楣', '{"9000": "4039.0", "Chữ Trung Quốc": "楣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楣 | me | tượng hình | xà ngang trên/dưới cửa, ô cửa | 楣 có bộ 木 (mộc, gỗ/cây) là thành phần ngữ nghĩa chỉ vật liệu xây dựng bằng gỗ. Phần còn lại biểu âm méi. Chữ hình thanh. Nghĩa là thanh xà ngang trên hoặc dưới khung cửa (lintel).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"me\": thanh gỗ 木 nằm ngang trên me cửa — 门楣 là khung cửa, ẩn dụ cho thể diện danh giá của gia đình. | Gương Hán-Việt | 门楣 (môn me) — khung cửa; ẩn dụ danh giá gia đình | Mở khoá kiến thức | Biết 楣 mở khoá từ 门楣 (môn me — khung cửa, thể diện gia đình) và 光耀门楣 (rạng danh cửa nhà).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 楣 có bộ 木 (gỗ, biểu nghĩa) chỉ cấu kiện bằng gỗ trong kiến trúc. Nghĩa là thanh xà ngang trên/dưới khung cửa (lintel/crossbeam). Dùng trong 门楣 (ngưỡng cửa, khung cửa) — ẩn dụ cho danh dự, thể diện gia đình. Trong bóng đá tiếng Quảng Đông: 中楣 là bắn trúng xà ngang. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cạnh cửa; mép cửa; bậu cửa", "Hạng Tần Suất (Jun Da)": "4039.0", "Tần Suất % (Jun Da)": "99.7557404725", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楣", "Unihan_Traditional (Chữ Phồn thể)": "楣", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận kiến trúc cửa hoặc trong các từ ghép liên quan đến nhà cửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捋', '{"9000": "4040.0", "Chữ Trung Quốc": "捋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 捋 | lõa | tượng hình | vuốt dọc theo vật dài; gỡ từng cái | 捋 có bộ 扌/手 (thủ, tay) là thành phần ngữ nghĩa chỉ hành động bằng tay. Phần còn lại biểu âm lǚ/luō. Chữ hình thanh. Có nhiều âm đọc tùy theo phương ngữ và ý nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lõa\": đôi tay 手 vuốt dọc từ gốc đến ngọn — 捋袖子 là kéo tay áo lên, 捋胡子 là vuốt râu. | Gương Hán-Việt | 捋袖子 (lõa tụ tử) — kéo tay áo lên; 捋须 (lõa tu) — vuốt râu | Mở khoá kiến thức | Biết 捋 mở khoá cụm 捋袖子 (kéo tay áo lên — chuẩn bị làm việc), 捋胡子 (vuốt râu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 捋 là chữ hình thanh với bộ 手 (tay, biểu nghĩa) chỉ hành động dùng tay. Hai âm đọc chính: luō (nắm và trượt dọc theo vật dài, như kéo tay áo lên) và lǚ (vuốt dọc để làm phẳng, như vuốt râu). Chữ đa âm với nhiều sắc thái hành động tay khác nhau tùy phương ngữ (Tiếng Mân Nam, Khách Gia). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỡ từng cái ra; vuốt ve", "Hạng Tần Suất (Jun Da)": "4040.0", "Tần Suất % (Jun Da)": "99.7560257379", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 寽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌寽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捋", "Unihan_Traditional (Chữ Phồn thể)": "捋", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "loát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ động tác vuốt râu, vuốt tóc hoặc tuốt lá cây. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涓', '{"9000": "4041.0", "Chữ Trung Quốc": "涓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 涓 | quen | tượng hình | dòng nước nhỏ; chọn lựa; trong sạch | 涓 có bộ 氵 (thủy, nước) là thành phần ngữ nghĩa chỉ dòng nước. Phần còn lại biểu âm juān. Chữ hình thanh. Ảnh tiểu triện và lục thư thông xác nhận bộ 氵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quen\": bộ 氵 (nước) chảy quen quen — 涓涓细流 là dòng nước nhỏ chảy mãi không dứt, ẩn dụ tích lũy bền bỉ. | Gương Hán-Việt | 涓涓 (quen quen) — dòng chảy nhỏ, tí tách liên tục | Mở khoá kiến thức | Biết 涓 mở khoá từ 涓涓细流 (dòng chảy nhỏ bền bỉ), 涓滴 (từng giọt nhỏ), 涓滴归公 (liêm khiết từng xu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 涓 là chữ hình thanh với bộ 氵 (nước, biểu nghĩa). Nghĩa gốc là dòng nước nhỏ, suối nhỏ. Mở rộng thành: tinh khiết, trong sạch; chọn lựa kỹ càng. Thành ngữ 涓涓细流 (dòng chảy nhỏ mà lâu dài) ám chỉ sự tích lũy bền bỉ. 涓滴归公 (từng giọt nhỏ đều thuộc về công quỹ) nói về liêm khiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng nước nhỏ; kén chọn", "Hạng Tần Suất (Jun Da)": "4041.0", "Tần Suất % (Jun Da)": "99.7563110033", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涓", "Unihan_Traditional (Chữ Phồn thể)": "涓", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ dòng nước chảy nhỏ hoặc làm tính từ chỉ sự nhỏ bé, tinh khiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荪', '{"9000": "4042.0", "Chữ Trung Quốc": "荪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荪 | tôn | tượng hình | cỏ thơm; hoa diên vỹ | 荪 có bộ 艹 (tháu, cỏ/cây) là thành phần ngữ nghĩa. Phần còn lại biểu âm sūn. Chữ hình thanh. Ảnh đại triện và tiểu triện. Chỉ loài cỏ thơm hoặc hoa diên vỹ (iris), dùng nhiều trong thơ Sở (Sở Từ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": cỏ 艹 thơm tôn quý — 荪 xuất hiện trong Sở Từ, ví người quân tử có đức hạnh như cỏ thơm. | Gương Hán-Việt | 荪草 (tôn thảo) — cỏ thơm trong thơ cổ Trung Hoa | Mở khoá kiến thức | Biết 荪 mở khoá hình ảnh thơ Sở Từ: cỏ thơm tượng trưng phẩm hạnh; tên người (荪 hay dùng đặt tên).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 荪 là chữ hình thanh với bộ 艹 (cỏ, biểu nghĩa) chỉ loài thực vật thơm. Không có glyph origin chi tiết — nguồn anchor là null. Chữ xuất hiện trong thơ Sở Từ (楚辞) của Khuất Nguyên, tượng trưng cho người quân tử có phẩm hạnh thơm tho. Ảnh đại triện và tiểu triện cho thấy hình dạng cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ cỏ thơm)", "Hạng Tần Suất (Jun Da)": "4042.0", "Tần Suất % (Jun Da)": "99.7565962687", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 孙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹孙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荪", "Unihan_Traditional (Chữ Phồn thể)": "蓀", "Pinyin_Xie": "sūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài thực vật có hương thơm trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娄', '{"9000": "4043.0", "Chữ Trung Quốc": "娄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 娄 | lâu | tượng hình | sao Lâu (một trong 28 tú); họ; mặc | 娄 có bộ 女 (nữ) là thành phần liên quan. Chữ tượng hình/chỉ sự, ý nghĩa gốc chưa rõ. Dùng chủ yếu làm tên sao (sao Lâu — nhị thập bát tú), họ người và nghĩa ''mặc'' (cổ văn). Chỉ có ảnh tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": bộ 女 trong chữ 娄 — 娄 là sao Lâu trong 28 tú, và là gốc âm của nhiều chữ như 楼 (lầu), 漏 (rò rỉ). | Gương Hán-Việt | sao Lâu (娄宿) — chòm sao trong nhị thập bát tú | Mở khoá kiến thức | Biết 娄 mở khoá nhóm chữ đồng âm lóu: 楼 (lầu), 漏 (rò), 搂 (ôm), 镂 (khắc) — 娄 là gốc âm chung.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 娄 không có glyph origin chi tiết — anchor là null. Có bộ 女 (nữ) nhưng bản chất nghĩa gốc chưa rõ. Chủ yếu dùng: (1) sao Lâu (nhị thập bát tú — chòm sao thứ 16); (2) họ người; (3) nghĩa cổ là mặc, kéo. Cũng là thành phần trong nhiều chữ: 楼, 漏, 搂, 镂 (đều có âm lóu). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao Lâu (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "4043.0", "Tần Suất % (Jun Da)": "99.7568810173", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱米女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "娄", "Unihan_Traditional (Chữ Phồn thể)": "婁", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chủ yếu dùng làm danh từ riêng chỉ chòm sao hoặc họ người, đôi khi làm tính từ chỉ sự trống rỗng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麝', '{"9000": "4044.0", "Chữ Trung Quốc": "麝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 21 | nét | 鹿 | lộc | biểu nghĩa | hươu, nai | 射 | xạ | biểu âm | 麝 = 鹿 (Lộc, biểu nghĩa: hươu/nai) + 射 (Xạ, biểu âm, cùng âm shè/xạ). Chữ hình thanh — bộ 鹿 xác định đây là loài hươu, 射 cho âm và gợi ý xạ hương (mùi thơm ''bắn ra'').", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xạ\": con hươu 鹿 xạ 射 hương thơm — 麝香 là xạ hương, nguyên liệu nước hoa quý từ hươu xạ. | Gương Hán-Việt | 麝香 (xạ hương) — xạ hương, mùi thơm quý từ hươu xạ | Mở khoá kiến thức | Biết 麝 mở khoá từ 麝香 (xạ hương — musk), 麝香草 (xạ hương thảo — thyme), 麝猫 (cầy xạ hương).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 麝 là chữ hình thanh gồm 鹿 (hươu, biểu nghĩa) và 射 (biểu âm, âm shè). Chỉ con hươu xạ (musk deer) — loài hươu nhỏ sống ở vùng núi Trung Á, con đực tiết ra xạ hương (麝香) từ túi tuyến — một trong những nguyên liệu nước hoa quý nhất thế giới. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hươu xạ", "Hạng Tần Suất (Jun Da)": "4044.0", "Tần Suất % (Jun Da)": "99.7571657659", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 射", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿射", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "射", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麝", "Unihan_Traditional (Chữ Phồn thể)": "麝", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "xạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài hươu xạ hoặc chất xạ hương dùng trong y học và hương liệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚤', '{"9000": "4045.0", "Chữ Trung Quốc": "蚤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 㕚 | biểu hình | móng vuốt | 虫 | trùng | biểu nghĩa | côn trùng, sâu bọ | 蚤 = 㕚 (móng vuốt, biểu hình) + 虫 (Trùng, biểu nghĩa: côn trùng). Chữ hội ý — móng vuốt + côn trùng = sinh vật cào gãi, ký sinh. Mô tả hành vi đặc trưng của bọ chét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": móng vuốt 㕚 của con trùng 虫 cào gãi — 蚤 là con bọ chét, loài ký sinh cắn ngứa nổi tiếng. | Gương Hán-Việt | 蚤虱 (tao sắt) — bọ chét và rận, loài ký sinh | Mở khoá kiến thức | Biết 蚤 mở khoá từ 跳蚤 (khiêu tao — bọ chét nhảy), 蚤市 (tao thị — chợ trời, chợ bọ chét/flea market).", "Tự nguyên_Xie": "Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary: 蚤 là chữ hội ý (ic) gồm 㕚 (móng vuốt, biểu hình) và 虫 (côn trùng, biểu nghĩa) — mô tả ''côn trùng có móng cào''. Đây là hình ảnh trực quan của con bọ chét cào gãi da. Ảnh bạch thư, đại triện và tiểu triện cho thấy lịch sử lâu đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con bọ chét, con rệp", "Hạng Tần Suất (Jun Da)": "4045.0", "Tần Suất % (Jun Da)": "99.7574489642", "GavinGrover_Once (Chiết tự trực tiếp)": "叉 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱叉虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚤", "Unihan_Traditional (Chữ Phồn thể)": "蚤", "Pinyin_Xie": "zǎo", "Âm Hán Việt_Xie": "tảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Dùng làm danh từ chỉ loài côn trùng ký sinh hoặc làm phó từ chỉ thời gian sớm trong cổ văn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醮', '{"9000": "4046.0", "Chữ Trung Quốc": "醮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 19 | nét | 醮 | tiêu | tượng hình | lễ tế rượu, hình vẽ bình rượu và nghi lễ | 醮 là chữ độc lập, bộ 酉 (dậu) gợi rượu và nghi lễ uống rượu. Nguồn gốc cụ thể chưa được phân tích rõ ràng trong tài liệu học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ rượu (酉) trong nghi lễ tế tự — 醮 là buổi lễ Đạo giáo có rượu dâng thần. | Gương Hán-Việt | 醮 ít dùng độc lập trong tiếng Việt Hán-Việt; xuất hiện trong 齋醮 (trai tiêu — lễ chay tịnh). | Mở khoá kiến thức | Biết 醮 mở khoá từ 打醮 (làm lễ Đạo giáo), 齋醮 (lễ chay tịnh cầu an).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích cấu tạo chi tiết cho 醮. Chữ có bộ 酉 liên quan đến rượu, nghĩa gốc chỉ nghi lễ uống rượu cầu thần hoặc lễ tế Đạo giáo. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1284.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dậu (1217) Tiêu (1283)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Dậu (số 1217 - rượu/chỉ ý) ở bên trái chữ Tiêu (số 1283 - cháy đen/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tiêu chỉ âm, bộ Dậu chỉ ý. Tiếu là lễ tế, rót rượu cúng thời xưa trong nghi thức quốc lễ hoặc đám cưới.", "Nghĩa Tiếng Việt_Xie": "uống rượu với ai mà không phải thù tạc", "Hạng Tần Suất (Jun Da)": "4046.0", "Tần Suất % (Jun Da)": "99.7580153607", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醮", "Unihan_Traditional (Chữ Phồn thể)": "醮", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "tiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ nghi thức cúng tế đạo giáo hoặc việc uống cạn rượu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搪', '{"9000": "4047.0", "Chữ Trung Quốc": "搪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搪 | đường | tượng hình | bộ thủ gợi hành động tay, cả chữ chỉ việc chặn, né tránh | 搪 có bộ 手 (thủ, tay) gợi hành động dùng tay. Nguồn Wiktionary không cung cấp phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": tay (手) đẩy ra như tường (đường) chắn — 搪 là chặn, né tránh, đẩy lùi. | Gương Hán-Việt | 搪 ít dùng trong tiếng Việt Hán-Việt; liên quan đến 搪瓷 (đường từ — đồ tráng men). | Mở khoá kiến thức | Biết 搪 mở khoá 搪塞 (đối phó qua loa), 搪瓷 (đồ tráng men, enamelware).", "Tự nguyên_Xie": "Wiktionary không phân tích cấu tạo chi tiết cho 搪. Bộ 手 chỉ hành động dùng tay để chặn, né, hoặc bôi phủ lên bề mặt. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường đột", "Hạng Tần Suất (Jun Da)": "4047.0", "Tần Suất % (Jun Da)": "99.7582980422", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搪", "Unihan_Traditional (Chữ Phồn thể)": "搪", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động trì hoãn, đối phó hoặc tráng một lớp bảo vệ lên bề mặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谧', '{"9000": "4048.0", "Chữ Trung Quốc": "谧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 谧 | mịch | tượng hình | bộ 言 gợi lời nói yên lặng, tĩnh lặng | 谧 (dạng giản thể của 謐) có bộ 言 (ngôn, lời nói). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mịch\": khi mọi lời nói (言) đều lặng đi — 谧 là sự tĩnh mịch, yên lặng sâu. | Gương Hán-Việt | 谧 xuất hiện trong 静谧 (tĩnh mịch — yên tĩnh hoàn toàn), 安谧 (an mịch — bình yên tĩnh lặng). | Mở khoá kiến thức | Biết 谧 mở khoá 静谧 (tĩnh mịch), 宁谧 (ninh mịch — thanh bình).", "Tự nguyên_Xie": "Tiểu triện | 谧 là dạng giản thể của 謐. Wiktionary không cung cấp phân tích cấu tạo chi tiết. Bộ 言 liên quan đến lời nói, toàn chữ mang nghĩa yên tĩnh, lặng lẽ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên lặng", "Hạng Tần Suất (Jun Da)": "4048.0", "Tần Suất % (Jun Da)": "99.7585802068", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 𥁑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠𥁑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𥁑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谧", "Unihan_Traditional (Chữ Phồn thể)": "謐", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mật, mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ hoặc đi kèm với các từ chỉ trạng thái yên tĩnh như tĩnh mịch. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湮', '{"9000": "4049.0", "Chữ Trung Quốc": "湮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 土 | thổ | biểu nghĩa | đất | 垔 | nhân | biểu âm | 湮 = 土 (Thổ, biểu nghĩa: đất) + 垔 (biểu âm); chữ hình thanh. Bộ thổ chỉ đất, gợi ý nghĩa bị chôn vùi dưới đất. Lưu ý chữ hiện tại dùng bộ 水, nhưng nguồn gốc từ bộ 土.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": đất (土) phủ lên vùi lấp tất cả — 湮 là mai một, chôn vùi, bị lãng quên. | Gương Hán-Việt | 湮 xuất hiện trong 湮没 (nhân một — bị vùi lấp, mai một), 湮灭 (nhân diệt — tiêu tan, hủy diệt). | Mở khoá kiến thức | Biết 湮 mở khoá 湮没 (bị mai một, vùi lấp theo thời gian), 湮灭 (tiêu tan).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 湮 là chữ hình thanh: 土 (thổ, đất) biểu nghĩa, 垔 biểu âm. Nghĩa gốc là bị chôn vùi dưới đất, bị vùi lấp. Từ đó mở rộng nghĩa: mai một, bị lãng quên theo thời gian. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mai một mất, chôn vùi", "Hạng Tần Suất (Jun Da)": "4049.0", "Tần Suất % (Jun Da)": "99.7588623715", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 垔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵垔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湮", "Unihan_Traditional (Chữ Phồn thể)": "湮", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết để chỉ sự chìm ngập, biến mất hoặc bị lãng quên theo thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辍', '{"9000": "4050.0", "Chữ Trung Quốc": "辍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 車 | xa | biểu nghĩa | xe, xe ngựa | 叕 | chuyết | biểu âm | 辍 = 車 (Xa, biểu nghĩa: xe, xe ngựa) + 叕 (biểu âm); chữ hình thanh. Bộ 車 gợi hình ảnh xe dừng lại giữa đường, không tiếp tục — từ đó mang nghĩa bỏ dở, ngừng lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuyết\": xe (車) đột ngột dừng lại (叕 biểu âm) — 辍 là bỏ dở, ngừng việc giữa chừng. | Gương Hán-Việt | 辍 xuất hiện trong 辍学 (xuyết học — bỏ học giữa chừng), 辍笔 (xuyết bút — bỏ bút, ngừng viết). | Mở khoá kiến thức | Biết 辍 mở khoá 辍学 (bỏ học), 中辍 (trung xuyết — bỏ dở), 辍笔 (ngừng viết).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 辍 (dạng giản thể của 輟) là chữ hình thanh: 車 (xa, xe) biểu nghĩa, 叕 biểu âm. Hình ảnh xe dừng hẳn gợi nghĩa thôi, ngừng, bỏ dở giữa chừng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thôi, nghỉ, bỏ dở", "Hạng Tần Suất (Jun Da)": "4050.0", "Tần Suất % (Jun Da)": "99.7591445362", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辍", "Unihan_Traditional (Chữ Phồn thể)": "輟", "Pinyin_Xie": "chuò", "Âm Hán Việt_Xie": "chuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các danh từ chỉ việc học hành hoặc công việc để biểu thị sự gián đoạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞌', '{"9000": "4051.0", "Chữ Trung Quốc": "瞌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 目 | mục | biểu nghĩa | mắt | 盍 | hạp | biểu âm | 瞌 = 目 (Mục, biểu nghĩa: mắt) + 盍 (Hạp, biểu âm); chữ hình thanh. Bộ 目 chỉ mắt, toàn chữ gợi trạng thái mắt díp lại buồn ngủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": mắt (目) díp lại (hạp — đậy lại) — 瞌 là ngủ gật, mắt không mở được. | Gương Hán-Việt | 瞌 xuất hiện trong 瞌睡 (hạp thụy — ngủ gật), thường dùng 打瞌睡 (đánh hạp thụy). | Mở khoá kiến thức | Biết 瞌 mở khoá 打瞌睡 (ngủ gật), 瞌睡虫 (con sâu ngủ — người hay ngủ gật).", "Tự nguyên_Xie": "Theo Wiktionary, 瞌 là chữ hình thanh: 目 (mục, mắt) biểu nghĩa, 盍 biểu âm. Nghĩa là mắt nặng trĩu, díp lại vì buồn ngủ — trạng thái ngủ gật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngủ gật", "Hạng Tần Suất (Jun Da)": "4051.0", "Tần Suất % (Jun Da)": "99.7594267009", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 盍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞌", "Unihan_Traditional (Chữ Phồn thể)": "瞌", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp với từ ngủ để tạo thành động từ ly hợp chỉ trạng thái ngủ gật hoặc buồn ngủ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梆', '{"9000": "4052.0", "Chữ Trung Quốc": "梆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 邦 | bang | biểu âm | 梆 = 木 (Mộc, biểu nghĩa: gỗ) + 邦 (Bang, biểu âm); chữ hình thanh. Bộ 木 chỉ vật bằng gỗ, đây là cái mõ dài bằng gỗ dùng đánh báo hiệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bương\": gỗ (木) gõ thành tiếng bang (邦 biểu âm) — 梆 là cái mõ gỗ, tiếng gõ mõ vọng xa. | Gương Hán-Việt | 梆 ít dùng trong tiếng Việt Hán-Việt; liên quan đến âm nhạc dân gian. | Mở khoá kiến thức | Biết 梆 mở khoá 梆子 (bương tử — cái mõ, nhạc khí gỗ), 梆子腔 (lối hát kinh kịch miền Bắc).", "Tự nguyên_Xie": "Theo Wiktionary, 梆 là chữ hình thanh: 木 (mộc, gỗ) biểu nghĩa, 邦 biểu âm. Chỉ cái mõ dài bằng gỗ, tiếng gõ mõ phát ra âm thanh ''bang'' — cũng là từ tượng thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái mõ dài", "Hạng Tần Suất (Jun Da)": "4052.0", "Tần Suất % (Jun Da)": "99.7597083488", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 邦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木邦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梆", "Unihan_Traditional (Chữ Phồn thể)": "梆", "Pinyin_Xie": "bāng", "Âm Hán Việt_Xie": "bang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại nhạc cụ gõ bằng gỗ hoặc dùng làm định ngữ trong các từ liên quan đến kịch nghệ cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樟', '{"9000": "4053.0", "Chữ Trung Quốc": "樟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 章 | chương | biểu âm | 樟 = 木 (Mộc, biểu nghĩa: cây) + 章 (Chương, biểu âm); chữ hình thanh. Bộ 木 chỉ loài cây, đây là cây long não (camphor).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": cây (木) có chương (章 — dấu ấn đặc biệt) là mùi long não — 樟 là cây long não thơm đặc trưng. | Gương Hán-Việt | 樟 xuất hiện trong 樟脑 (chương não — long não, camphor), 香樟 (hương chương — cây long não thơm). | Mở khoá kiến thức | Biết 樟 mở khoá 樟脑 (long não/camphor), 樟树 (cây long não), 香樟 (cây long não thơm).", "Tự nguyên_Xie": "Theo Wiktionary, 樟 là chữ hình thanh: 木 (mộc, cây) biểu nghĩa, 章 biểu âm. Chỉ cây long não (Cinnamomum camphora), loài cây gỗ có mùi thơm đặc trưng, gỗ dùng chống mối mọt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây long não", "Hạng Tần Suất (Jun Da)": "4053.0", "Tần Suất % (Jun Da)": "99.7599899967", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樟", "Unihan_Traditional (Chữ Phồn thể)": "樟", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ để chỉ các sản phẩm làm từ cây long não. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茉', '{"9000": "4054.0", "Chữ Trung Quốc": "茉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 末 | mạt | biểu âm | 茉 = 艹 (Thảo, biểu nghĩa: thực vật) + 末 (Mạt, biểu âm); chữ hình thanh. Bộ thảo chỉ loài cây, chỉ dùng trong từ 茉莉 (hoa nhài trắng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": cây (艹) tận cùng (末 — ngọn, cuối) nở hoa trắng — 茉 chỉ dùng trong 茉莉 (hoa nhài). | Gương Hán-Việt | 茉 xuất hiện trong 茉莉 (mạt lợi — hoa nhài trắng), 茉莉花茶 (trà hoa nhài). | Mở khoá kiến thức | Biết 茉 mở khoá 茉莉 (hoa nhài), 茉莉花茶 (trà hoa nhài), 茉莉花 (bài dân ca nổi tiếng Trung Quốc).", "Tự nguyên_Xie": "Theo Wiktionary, 茉 là chữ hình thanh: 艹 (thảo, cỏ) biểu nghĩa, 末 biểu âm. Chỉ dùng trong từ ghép 茉莉, chỉ cây hoa nhài trắng (jasmine). Đây là chữ phiên âm tên nước ngoài qua tiếng Phạn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hoa nhài trắng", "Hạng Tần Suất (Jun Da)": "4054.0", "Tần Suất % (Jun Da)": "99.7602716446", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茉", "Unihan_Traditional (Chữ Phồn thể)": "茉", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ lị để tạo thành danh từ chỉ hoa nhài hoặc làm định ngữ chỉ hương thơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岖', '{"9000": "4055.0", "Chữ Trung Quốc": "岖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 岖 | khư | tượng hình | núi dốc, hiểm trở — dạng giản thể của 嶇 | 岖 là dạng giản thể của 嶇, bộ 山 (sơn, núi) + 区. Chỉ dùng trong từ 崎岖 chỉ đường núi gồ ghề, hiểm trở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khư\": núi (山) phân khu (区) gồ ghề — 岖 chỉ dùng trong 崎岖 tả đường dốc hiểm. | Gương Hán-Việt | 岖 xuất hiện trong 崎岖 (kỳ khư — đường núi gồ ghề, cuộc đời gian truân). | Mở khoá kiến thức | Biết 岖 mở khoá 崎岖 (kỳ khư — con đường gập ghềnh, gian nan).", "Tự nguyên_Xie": "岖 là dạng giản thể của 嶇 (bộ 山 + 區 → 山 + 区). Chữ truyền thống 嶇 có bộ 山 (núi) biểu nghĩa, chỉ sườn núi gồ ghề, hiểm trở. Chưa có nguồn học thuật chi tiết từ Wiktionary. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khi khu 崎嶇,崎岖)", "Hạng Tần Suất (Jun Da)": "4055.0", "Tần Suất % (Jun Da)": "99.7605527757", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岖", "Unihan_Traditional (Chữ Phồn thể)": "嶇", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ khi để tạo thành tính từ mô tả đường xá miền núi quanh co, hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臼', '{"9000": "4056.0", "Chữ Trung Quốc": "臼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 6 | nét | 臼 | cối | tượng hình | cái cối giã — hình vẽ lỗ hõm hình cối | 臼 là chữ tượng hình độc lập, hình vẽ cái cối giã — lỗ hõm có viền quanh. Không liên quan đến bộ trên cùng của 學, 兒, 鼠, 叟. Là bộ thủ riêng trong hệ thống chữ Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cối\": hình vẽ cái cối (臼) có hai bên vành và lỗ giữa — 臼 là cối giã gạo, vật hõm. | Gương Hán-Việt | 臼 xuất hiện trong 臼齿 (cối xỉ — răng hàm), 杵臼 (chử cối — chày và cối). | Mở khoá kiến thức | Biết 臼 mở khoá 臼齿 (răng hàm), 杵臼 (chày và cối), 脱臼 (trật khớp).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 臼 là chữ tượng hình (tượng hình): hình vẽ cái cối giã — một lỗ hõm có viền. Có thể thấy trong chữ 舂 nguyên bản có chày ở trên. Nghĩa gốc: cái cối; sau mở rộng sang các vật hõm tương tự (khớp xương hình cối). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "610.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình cái cối giã gạo. Bốn nét ở trong biểu thị những hạt gạo. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Mô phỏng trực tiếp hình ảnh cái cối có hạt gạo bên trong (Cữu).", "Nghĩa Tiếng Việt_Xie": "cái cối để giã", "Hạng Tần Suất (Jun Da)": "4056.0", "Tần Suất % (Jun Da)": "99.76083339", "GavinGrover_Once (Chiết tự trực tiếp)": "彐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴彐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "臼", "Unihan_Traditional (Chữ Phồn thể)": "臼", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ dụng cụ giã gạo hoặc dùng trong y học để chỉ các khớp xương có hình dạng giống cái cối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癣', '{"9000": "4057.0", "Chữ Trung Quốc": "癣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 19 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 鮮 | tiên | biểu âm | 癣 = 疒 (Nạch, biểu nghĩa: bệnh) + 鮮 (Tiên, biểu âm); chữ hình thanh. Bộ nạch (疒) chỉ bệnh tật, toàn chữ chỉ bệnh ghẻ lở, nấm da.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": bệnh (疒) tươi sáng (鮮 — tiên) trên da — thực ra là ghẻ lở, 癣 là bệnh da nấm đỏ. | Gương Hán-Việt | 癣 xuất hiện trong 牛皮癣 (ngưu bì tiên — bệnh vẩy nến), 头癣 (đầu tiên — nấm da đầu). | Mở khoá kiến thức | Biết 癣 mở khoá 牛皮癣 (vẩy nến), 头癣 (nấm da đầu), 体癣 (hắc lào thân).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 癣 (dạng giản thể của 癬) là chữ hình thanh: 疒 (bệnh) biểu nghĩa, 鮮 (tiên) biểu âm. Chỉ bệnh da do nấm gây ra — ghẻ lở, hắc lào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghẻ lở", "Hạng Tần Suất (Jun Da)": "4057.0", "Tần Suất % (Jun Da)": "99.7611140044", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 鲜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒鲜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癣", "Unihan_Traditional (Chữ Phồn thể)": "癬", "Pinyin_Xie": "xuǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận cơ thể hoặc nguyên nhân để chỉ các loại bệnh ngoài da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穑', '{"9000": "4058.0", "Chữ Trung Quốc": "穑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 16 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 嗇 | sắc | biểu âm | 穑 = 禾 (Hòa, biểu nghĩa: lúa, ngũ cốc) + 嗇 (Sắc, biểu âm); chữ hình thanh. Bộ hòa chỉ lúa gạo, toàn chữ gợi việc thu hoạch mùa màng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": lúa (禾) gặt về cất (嗇 — sắc, tiết kiệm, giữ lại) — 穑 là thu hoạch, gặt mùa. | Gương Hán-Việt | 穑 xuất hiện trong 稼穑 (giá sắc — trồng trọt và thu hoạch), là cặp từ nông nghiệp cổ. | Mở khoá kiến thức | Biết 穑 mở khoá 稼穑 (trồng và gặt), 耕稼 (canh tác) trong văn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 穑 (dạng giản thể của 穡) là chữ hình thanh: 禾 (hòa, lúa) biểu nghĩa, 嗇 biểu âm. Là sự chuyên biệt hóa của 嗇. Nghĩa: thu hoạch ngũ cốc, gặt hái mùa màng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gặt hái", "Hạng Tần Suất (Jun Da)": "4058.0", "Tần Suất % (Jun Da)": "99.7613946187", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 啬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾啬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穑", "Unihan_Traditional (Chữ Phồn thể)": "穡", "Pinyin_Xie": "sè", "Âm Hán Việt_Xie": "sắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường kết hợp với chữ tường để chỉ việc cày cấy gặt hái hoặc dùng làm động từ chỉ hoạt động thu hoạch nông sản. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玷', '{"9000": "4059.0", "Chữ Trung Quốc": "玷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 𤣩 | ngọc | biểu nghĩa | ngọc (bộ ngọc bên trái) | 占 | chiêm | biểu âm | 玷 = 𤣩 (bộ Ngọc, biểu nghĩa: ngọc bích) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ ngọc chỉ đá quý, toàn chữ gợi vết tỳ, khiếm khuyết trên ngọc — từ đó mở rộng sang vết nhơ về phẩm hạnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đém\": ngọc (𤣩) bị chiếm (占 — biểu âm) bởi vết nứt — 玷 là tỳ vết trên ngọc, ô nhục phẩm hạnh. | Gương Hán-Việt | 玷 xuất hiện trong 玷污 (đém ô — làm ô nhục, vấy bẩn), 玷辱 (đém nhục — làm hổ nhục). | Mở khoá kiến thức | Biết 玷 mở khoá 玷污 (làm ô nhục), 玷辱 (hổ nhục), 白璧无瑕 (ngọc trắng không tỳ vết — tương phản).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 玷 là chữ hình thanh: 𤣩 (bộ ngọc) biểu nghĩa, 占 biểu âm. Nghĩa gốc: vết nứt, tỳ vết trên ngọc. Mở rộng: làm ô danh, hổ danh, làm ô nhục. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc có vết", "Hạng Tần Suất (Jun Da)": "4059.0", "Tần Suất % (Jun Da)": "99.7616741994", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "玷", "Unihan_Traditional (Chữ Phồn thể)": "玷", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ vết nhơ hoặc làm động từ với nghĩa làm hoen ố danh dự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馍', '{"9000": "4060.0", "Chữ Trung Quốc": "馍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 馍 | mạc | tượng hình | bộ thực (食) gợi đồ ăn, đặc biệt là bánh mì hấp | 馍 (dạng giản thể của 饃) có bộ 食 (thực, đồ ăn). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": đồ ăn (食) bánh hấp miền Bắc — 馍 là màn thầu, bánh mì dẹt ăn no bụng. | Gương Hán-Việt | 馍 ít dùng trong tiếng Việt Hán-Việt; là từ ngữ miền Bắc Trung Quốc chỉ bánh. | Mở khoá kiến thức | Biết 馍 mở khoá 馍馍 (mạc mạc — bánh mì hấp), 肉夹馍 (nhục giáp mạc — bánh mì kẹp thịt kiểu Tây An).", "Tự nguyên_Xie": "馍 (dạng giản thể của 饃) là chữ có bộ 食 (thực, ăn uống). Chỉ bánh mì dẹt hoặc bánh bao hấp ở miền Bắc Trung Quốc. Nguồn gốc cấu tạo chưa được phân tích rõ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màn thầu, bánh mì hấp", "Hạng Tần Suất (Jun Da)": "4060.0", "Tần Suất % (Jun Da)": "99.7619532634", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馍", "Unihan_Traditional (Chữ Phồn thể)": "饃", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại bánh bột mì hấp ở miền bắc Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呷', '{"9000": "4061.0", "Chữ Trung Quốc": "呷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 甲 | giáp | biểu âm | 呷 = 口 (Khẩu, biểu nghĩa: miệng) + 甲 (Giáp, biểu âm); chữ hình thanh. Bộ 口 chỉ miệng, toàn chữ gợi hành động hút, uống nhỏ giọt bằng miệng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": miệng (口) kẹp chặt (甲 — giáp) từng giọt — 呷 là hút, uống từng ngụm nhỏ. | Gương Hán-Việt | 呷 ít dùng trong tiếng Việt Hán-Việt; là từ ngữ miêu tả hành động uống nhỏ giọt. | Mở khoá kiến thức | Biết 呷 mở khoá cách dùng trong văn học: 呷了一口茶 (uống một ngụm trà nhỏ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 呷 là chữ hình thanh: 口 (khẩu, miệng) biểu nghĩa, 甲 biểu âm. Nghĩa: hít vào, uống từng ngụm nhỏ, hút vào miệng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hít vào, hút vào", "Hạng Tần Suất (Jun Da)": "4061.0", "Tần Suất % (Jun Da)": "99.7622318106", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呷", "Unihan_Traditional (Chữ Phồn thể)": "呷", "Pinyin_Xie": "gā", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đồ uống như trà hoặc rượu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萼', '{"9000": "4062.0", "Chữ Trung Quốc": "萼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 萼 | ngạc | tượng hình | bộ thảo gợi thực vật, đài hoa | 萼 có bộ 艹 (thảo, cỏ/thực vật). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": cỏ xanh (艹) ôm bao quanh — 萼 là đài hoa, phần xanh nâng đỡ cánh hoa. | Gương Hán-Việt | 萼 xuất hiện trong 花萼 (hoa ngạc — đài hoa), 萼片 (ngạc phiến — cánh đài). | Mở khoá kiến thức | Biết 萼 mở khoá 花萼 (đài hoa), 萼片 (cánh đài), 华萼 (hoa ngạc).", "Tự nguyên_Xie": "Wiktionary không phân tích cấu tạo chi tiết cho 萼. Bộ 艹 chỉ thực vật. Chữ có nghĩa là đài hoa — phần bao bọc, nâng đỡ cánh hoa. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đài hoa", "Hạng Tần Suất (Jun Da)": "4062.0", "Tần Suất % (Jun Da)": "99.762509841", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 咢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹咢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萼", "Unihan_Traditional (Chữ Phồn thể)": "萼", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên hoa hoặc kết hợp thành từ ghép chỉ bộ phận của hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妩', '{"9000": "4063.0", "Chữ Trung Quốc": "妩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 妩 | vũ | tượng hình | bộ 女 gợi người phụ nữ nũng nịu, duyên dáng | 妩 (dạng giản thể của 嫵) có bộ 女 (nữ, phụ nữ). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": người phụ nữ (女) múa vũ (vũ — duyên dáng) — 妩 là nũng nịu, quyến rũ dịu dàng. | Gương Hán-Việt | 妩 xuất hiện trong 妩媚 (vũ mị — nũng nịu, quyến rũ), cặp từ thường dùng. | Mở khoá kiến thức | Biết 妩 mở khoá 妩媚 (nũng nịu, quyến rũ), dùng để tả nét duyên của phụ nữ.", "Tự nguyên_Xie": "妩 là dạng giản thể của 嫵. Wiktionary không cung cấp phân tích cấu tạo chi tiết. Bộ 女 liên quan đến phụ nữ, toàn chữ mang nghĩa quyến rũ, duyên dáng, nũng nịu. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nũng nịu", "Hạng Tần Suất (Jun Da)": "4063.0", "Tần Suất % (Jun Da)": "99.7627878714", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 无", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女无", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "无", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妩", "Unihan_Traditional (Chữ Phồn thể)": "嫵", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép miêu tả vẻ đẹp của phụ nữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伫', '{"9000": "4064.0", "Chữ Trung Quốc": "伫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 伫 | trữ | tượng hình | bộ nhân gợi người đứng im chờ đợi | 伫 (dạng giản thể từ 佇, tiếp tục rút gọn) có bộ 亻(nhân, người). Dạng giản thể rút phần phải thành 㝉 (宀+一) để phân biệt với 宁. Chữ chỉ việc đứng yên một chỗ lâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": người (亻) đứng chờ trữ (trữ — để dành, tích lũy) niềm mong đợi — 伫 là đứng im trông chờ. | Gương Hán-Việt | 伫 xuất hiện trong 伫立 (trữ lập — đứng yên), 伫望 (trữ vọng — đứng trông đợi). | Mở khoá kiến thức | Biết 伫 mở khoá 伫立 (đứng yên, đứng lặng), 伫候 (chờ đợi), 伫望 (trông ngóng từ xa).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 伫 là dạng giản thể rút gọn của 佇. Phần phải rút thành 㝉 (宀 + 一) để phân biệt với 宁 (dạng giản của 寧). Bộ 亻 (nhân) chỉ người. Nghĩa: đứng im một chỗ chờ đợi lâu, trông đợi. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứng yên", "Hạng Tần Suất (Jun Da)": "4064.0", "Tần Suất % (Jun Da)": "99.763065385", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 㝉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻㝉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㝉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伫", "Unihan_Traditional (Chữ Phồn thể)": "佇", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các từ chỉ phương hướng hoặc trạng thái đứng yên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彤', '{"9000": "4065.0", "Chữ Trung Quốc": "彤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彡 | Số nét | 7 | nét | 彤 | đồng | tượng hình | chữ tượng hình hoặc hội ý: màu đỏ son, hình ảnh vật nhuộm đỏ với bộ 彡 (sọc vẽ) | 彤 không có phân tích hội ý hay hình thanh rõ ràng trong nguồn Wiktionary hiện có. Bộ 彡 gợi đường sọc, màu sắc rực rỡ. Chữ có nghĩa là đỏ son, đỏ thắm trong văn học cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": bộ sọc vẽ (彡) phủ màu đỏ son — 彤 là đỏ thắm, màu son tươi trong thơ cổ. | Gương Hán-Việt | 彤 xuất hiện trong 彤管 (đồng quản — ống bút son đỏ), 彤云 (đồng vân — mây đỏ), 红彤彤 (hồng đồng đồng — đỏ rực). | Mở khoá kiến thức | Biết 彤 mở khoá 红彤彤 (đỏ rực rỡ), 彤管 (ống bút đỏ — biểu tượng tình yêu trong Kinh Thi).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary không phân tích cấu tạo chi tiết cho 彤. Bộ 彡 liên quan đến đường sọc, hoa văn. Nghĩa cổ điển: màu đỏ son, đỏ thắm — dùng trong thơ kinh để tả trang phục và đồ vật màu đỏ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tông", "Hạng Tần Suất (Jun Da)": "4065.0", "Tần Suất % (Jun Da)": "99.7633423819", "GavinGrover_Once (Chiết tự trực tiếp)": "丹 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丹彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "彤", "Unihan_Traditional (Chữ Phồn thể)": "彤", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả màu sắc đỏ hồng của mây, trời hoặc hoa văn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莓', '{"9000": "4066.0", "Chữ Trung Quốc": "莓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莓 | mội | tượng hình | bộ 艹 gợi thực vật, quả mọng hoặc rêu | 莓 có bộ 艹 (thảo, cỏ/thực vật). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mội\": thực vật (艹) sinh ra quả nhỏ tròn — 莓 là quả mọng, dâu tây, quả berry. | Gương Hán-Việt | 莓 xuất hiện trong 草莓 (thảo mội — dâu tây), 蓝莓 (lam mội — việt quất), 树莓 (thụ mội — mâm xôi). | Mở khoá kiến thức | Biết 莓 mở khoá 草莓 (dâu tây), 蓝莓 (việt quất), 蔓越莓 (nam việt quất/cranberry).", "Tự nguyên_Xie": "Wiktionary không phân tích cấu tạo chi tiết cho 莓. Bộ 艹 chỉ thực vật. Nghĩa: quả mọng, rêu hoặc các loại quả nhỏ mọc trên cây bụi thấp. Hay dùng nhất trong 草莓 (dâu tây). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rêu; quả dâu tây", "Hạng Tần Suất (Jun Da)": "4066.0", "Tần Suất % (Jun Da)": "99.7636188619", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莓", "Unihan_Traditional (Chữ Phồn thể)": "莓", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "môi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên loại quả để chỉ các loại quả mọng như dâu tây, việt quất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岬', '{"9000": "4067.0", "Chữ Trung Quốc": "岬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 山 | sơn | biểu nghĩa | núi | 甲 | giáp | biểu âm | 岬 = 山 (Sơn, biểu nghĩa: núi) + 甲 (Giáp, biểu âm); chữ hình thanh. Bộ 山 chỉ địa hình núi, toàn chữ gợi phần đất nhô ra biển như sườn núi — mũi đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": núi (山) nhô ra như áo giáp (甲 — biểu âm) chắn biển — 岬 là mũi đất, vệ núi nhô ra. | Gương Hán-Việt | 岬 xuất hiện trong 岬角 (giáp giác — mũi đất nhô ra biển), 海岬 (hải giáp — mũi đất ven biển). | Mở khoá kiến thức | Biết 岬 mở khoá 岬角 (mũi đất), 海岬 (mũi đất ven biển) trong địa lý.", "Tự nguyên_Xie": "Theo Wiktionary, 岬 là chữ hình thanh: 山 (sơn, núi) biểu nghĩa, 甲 biểu âm. Nghĩa: sườn núi; mũi đất nhô ra biển (cape, headland). Thường dùng trong địa danh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vệ núi; mũi đất (ở biển)", "Hạng Tần Suất (Jun Da)": "4067.0", "Tần Suất % (Jun Da)": "99.763895342", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岬", "Unihan_Traditional (Chữ Phồn thể)": "岬", "Pinyin_Xie": "jiǎ", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong địa lý để chỉ các mũi đất nhô ra phía biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媛', '{"9000": "4068.0", "Chữ Trung Quốc": "媛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 爰 | vươn | biểu âm | 媛 = 女 (Nữ, biểu nghĩa: phụ nữ) + 爰 (Vươn, biểu âm); chữ hình thanh. Bộ 女 chỉ phụ nữ, toàn chữ gợi người con gái đẹp, giai nhân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": người phụ nữ (女) vươn tới (爰 — biểu âm) cái đẹp — 媛 là giai nhân, mỹ nữ. | Gương Hán-Việt | 媛 xuất hiện trong 名媛 (danh viên — giai nhân danh tiếng), 才媛 (tài viên — giai nhân tài sắc). | Mở khoá kiến thức | Biết 媛 mở khoá 名媛 (danh nữ nổi tiếng), 才媛 (phụ nữ tài giỏi), 淑媛 (thục viên — giai nhân đoan trang).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 媛 là chữ hình thanh: 女 (nữ, phụ nữ) biểu nghĩa, 爰 biểu âm. Nghĩa văn học: giai nhân, người phụ nữ xinh đẹp. Cũng có nghĩa: xinh đẹp, thanh tao. Xuất hiện trong Kinh Thi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gái đẹp", "Hạng Tần Suất (Jun Da)": "4068.0", "Tần Suất % (Jun Da)": "99.764171822", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 爰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女爰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "媛", "Unihan_Traditional (Chữ Phồn thể)": "媛", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "viện, viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ người phụ nữ quý phái hoặc dùng trong tên riêng của nữ giới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惆', '{"9000": "4069.0", "Chữ Trung Quốc": "惆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 惆 | trù | tượng hình | bộ 心 gợi tâm trạng sầu não | 惆 có bộ 忄(tâm, tim/lòng). Nguồn Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": tâm (忄) trù (trù — lo lắng, tính toán) mà không ra kết quả — 惆 là buồn bã, thất vọng. | Gương Hán-Việt | 惆 chỉ dùng trong 惆怅 (trù trướng — buồn bã, thất vọng), không dùng độc lập. | Mở khoá kiến thức | Biết 惆 mở khoá 惆怅 (tâm trạng buồn bã, trống rỗng), hay gặp trong thơ văn.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu tạo chi tiết cho 惆. Bộ 忄(tâm) chỉ cảm xúc, tâm trạng. Chỉ dùng trong từ ghép 惆怅 — trù trướng, tâm trạng buồn bã, thất vọng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trù trướng 惆悵)", "Hạng Tần Suất (Jun Da)": "4069.0", "Tần Suất % (Jun Da)": "99.7644477853", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惆", "Unihan_Traditional (Chữ Phồn thể)": "惆", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ kết hợp với các từ chỉ tâm trạng để diễn tả sự buồn bã, tiếc nuối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳎', '{"9000": "4070.0", "Chữ Trung Quốc": "鳎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 魚 | ngư | biểu nghĩa | cá | 鳎 = 魚 (Ngư, biểu nghĩa: cá) + 𦐇 (biểu âm); chữ hình thanh. Bộ 魚 chỉ loài cá, toàn chữ là tên một loài cá bơn dẹt (sole/flatfish).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\": cá (魚) dẹt nằm úp (tháp — thấp, dẹp) — 鳎 là cá bơn, cá dẹt nằm im dưới đáy. | Gương Hán-Việt | 鳎 ít dùng trong tiếng Việt Hán-Việt; là tên khoa học loài cá bơn cát. | Mở khoá kiến thức | Biết 鳎 mở khoá 鰨沙 (tháp sa — cá bơn), 鰨鱼 (tháp ngư — cá bơn cát).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鳎 (dạng giản thể của 鰨) là chữ hình thanh: 魚 (ngư, cá) biểu nghĩa, 𦐇 biểu âm. Chỉ cá bơn cát (sole), loài cá dẹt sống dưới đáy biển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá bơn cát", "Hạng Tần Suất (Jun Da)": "4070.0", "Tần Suất % (Jun Da)": "99.7647237485", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳎", "Unihan_Traditional (Chữ Phồn thể)": "鰨", "Pinyin_Xie": "tǎ", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ loài cá bơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啾', '{"9000": "4071.0", "Chữ Trung Quốc": "啾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 秋 | thu | biểu âm | 啾 = 口 (Khẩu, biểu nghĩa: miệng/âm thanh) + 秋 (Thu, biểu âm); chữ hình thanh. Bộ 口 gợi âm thanh phát ra, toàn chữ là từ tượng thanh: tiếng khóc trẻ em hoặc tiếng chim hót.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": miệng (口) kêu tiếng mùa thu (秋 — biểu âm) — 啾 là tiếng chim chiếu, tiếng khóc nhỏ. | Gương Hán-Việt | 啾 ít dùng độc lập; dùng trong 啾啾 (thu thu — tiếng chim hót), 啁啾 (trêu thu — tiếng chim). | Mở khoá kiến thức | Biết 啾 mở khoá 啾啾 (tiếng chim hót ríu rít), 啁啾 (tiếng chim hót đa dạng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 啾 là chữ hình thanh: 口 (khẩu, miệng) biểu nghĩa, 秋 biểu âm. Là từ tượng thanh: tiếng khóc nhỏ của trẻ, tiếng chíu chíu của chim non, hoặc tiếng hôn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng khóc hu hu", "Hạng Tần Suất (Jun Da)": "4071.0", "Tần Suất % (Jun Da)": "99.764999195", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啾", "Unihan_Traditional (Chữ Phồn thể)": "啾", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả tiếng chim kêu hoặc tiếng khóc nỉ non. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囔', '{"9000": "4072.0", "Chữ Trung Quốc": "囔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 25 | nét | 囔 | nang | tượng hình | bộ 口 lớn gợi âm thanh rì rầm trong miệng | 囔 là chữ phức tạp (25 nét) có bộ 口. Không có nguồn Wiktionary và không có anchor ngữ nguyên. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nang\": miệng (口) kêu nang nang (rì rầm) — 囔 là lẩm bẩm, rì rầm, nói không rõ ràng. | Gương Hán-Việt | 囔 ít dùng trong tiếng Việt Hán-Việt; là từ khẩu ngữ tả tiếng rì rầm. | Mở khoá kiến thức | Biết 囔 mở khoá 囔囔 (nang nang — rì rầm, lầm bầm), 嘟囔 (đô nang — lầm bầm phàn nàn).", "Tự nguyên_Xie": "囔 không có nguồn ngữ nguyên trong Wiktionary. Là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ 口 gợi âm thanh miệng. Nghĩa: rì rầm, thì thầm, lầm bầm. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rì rầm, thì thầm, lẩm nhẩm", "Hạng Tần Suất (Jun Da)": "4072.0", "Tần Suất % (Jun Da)": "99.7652746415", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 囊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口囊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "囔", "Unihan_Traditional (Chữ Phồn thể)": "囔", "Pinyin_Xie": "nāng", "Âm Hán Việt_Xie": "nang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước lời nói để chỉ hành động nói nhỏ trong miệng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜓', '{"9000": "4073.0", "Chữ Trung Quốc": "蜓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蜓 | đình | tượng hình | bộ 虫 gợi côn trùng, con chuồn chuồn | 蜓 có bộ 虫 (trùng, sâu bọ/côn trùng). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Chỉ dùng trong từ 蜻蜓 (con chuồn chuồn). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": sâu bọ (虫) đình lại (đình — dừng) trên cành — 蜓 chỉ dùng trong 蜻蜓 (chuồn chuồn đậu im). | Gương Hán-Việt | 蜓 chỉ dùng trong 蜻蜓 (thanh đình — con chuồn chuồn), không dùng độc lập. | Mở khoá kiến thức | Biết 蜓 mở khoá 蜻蜓 (chuồn chuồn), 蜻蜓点水 (chuồn chuồn chấm nước — làm qua loa).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu tạo chi tiết cho 蜓. Bộ 虫 chỉ côn trùng. Chỉ dùng trong từ ghép 蜻蜓 — con chuồn chuồn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "846.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (287) Đình (697)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 287 - côn trùng) ở bên trái chữ Đình (số 697 - triều đình/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đình chỉ âm, bộ Trùng chỉ ý. Đĩnh/Đình là tên côn trùng (Tinh đình = con chuồn chuồn).", "Nghĩa Tiếng Việt_Xie": "(xem: tinh đình 蜻蜓)", "Hạng Tần Suất (Jun Da)": "4073.0", "Tần Suất % (Jun Da)": "99.765550088", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜓", "Unihan_Traditional (Chữ Phồn thể)": "蜓", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ chỉ con chuồn chuồn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孺', '{"9000": "4074.0", "Chữ Trung Quốc": "孺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 17 | nét | 孺 | nhọ | tượng hình | bộ 子 gợi trẻ con, bộ 需 gợi cần bú mớm | 孺 có bộ 子 (tử, con/trẻ em). Nguồn Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhọ\": đứa trẻ (子) còn nhỏ nhọ (nhọ — yếu ớt, non nớt) cần mớm bú — 孺 là trẻ nhỏ, ấu nhi. | Gương Hán-Việt | 孺 xuất hiện trong 孺子 (nhọ tử — đứa trẻ), 孺子牛 (nhọ tử ngưu — con bò phục vụ trẻ, nghĩa bóng: người cống hiến hết mình). | Mở khoá kiến thức | Biết 孺 mở khoá 孺子 (trẻ nhỏ), 孺子牛 (hình tượng người tận tụy phục vụ nhân dân), 妇孺 (phụ nữ và trẻ em).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không phân tích cấu tạo chi tiết cho 孺. Bộ 子 (tử) chỉ trẻ em. Nghĩa gốc: trẻ nhỏ cần bú mớm, mầm non. Mở rộng: huyết thống gần, tình thân yêu. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mớm cơm cho trẻ", "Hạng Tần Suất (Jun Da)": "4074.0", "Tần Suất % (Jun Da)": "99.7658250176", "GavinGrover_Once (Chiết tự trực tiếp)": "子 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰子需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孺", "Unihan_Traditional (Chữ Phồn thể)": "孺", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ trẻ nhỏ hoặc tính từ chỉ sự non nớt trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徇', '{"9000": "4075.0", "Chữ Trung Quốc": "徇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 9 | nét | 彳 | xích | biểu nghĩa | bước đi, di chuyển | 旬 | tuần | biểu âm | 徇 = 彳 (Xích, biểu nghĩa: đi, di chuyển) + 旬 (Tuần, biểu âm); chữ hình thanh. Bộ 彳 gợi hành động đi theo, tuân theo. Nghĩa: phục tùng, làm theo; hoặc tuần hành trưng bày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": đi (彳) tuần (旬 — biểu âm) theo lệnh người trên — 徇 là phục tùng, làm theo, tuân thủ. | Gương Hán-Việt | 徇 xuất hiện trong 徇私 (tuần tư — thiên vị cá nhân), 徇私枉法 (tuần tư uổng pháp — bẻ cong luật pháp vì tư lợi). | Mở khoá kiến thức | Biết 徇 mở khoá 徇私 (thiên vị), 徇私舞弊 (gian lận vì tư lợi), 徇情枉法 (bóp méo luật pháp vì tình cảm).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 徇 là chữ hình thanh: 彳 (xích, đi) biểu nghĩa, 旬 biểu âm. Nghĩa: phục tùng, làm theo; tuần hành; hoặc hy sinh vì (dạng thay thế của 殉). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng ý theo, làm theo", "Hạng Tần Suất (Jun Da)": "4075.0", "Tần Suất % (Jun Da)": "99.7660994306", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徇", "Unihan_Traditional (Chữ Phồn thể)": "徇", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tuẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ việc làm theo tư lợi hoặc hy sinh vì nghĩa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焊', '{"9000": "4076.0", "Chữ Trung Quốc": "焊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 焊 | hàn | tượng hình | bộ 火 gợi lửa dùng để nối kim loại | 焊 có bộ 火 (hỏa, lửa). Nguồn Wiktionary không phân tích cấu tạo chi tiết. Bộ 火 gợi hành động dùng lửa hoặc nhiệt để hàn nối kim loại. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàn\": lửa (火) nối liền kim loại — 焊 là hàn, công việc của thợ hàn điện/hàn hơi. | Gương Hán-Việt | 焊 xuất hiện trong 焊接 (hàn tiếp — hàn nối), 电焊 (điện hàn — hàn điện), 焊工 (hàn công — thợ hàn). | Mở khoá kiến thức | Biết 焊 mở khoá 焊接 (hàn nối), 电焊 (hàn điện), 焊枪 (súng hàn), 焊锡 (thiếc hàn).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu tạo chi tiết cho 焊. Bộ 火 (hỏa) chỉ lửa/nhiệt. Nghĩa: hàn (welding/soldering) — dùng nhiệt để nối liền các chi tiết kim loại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàn", "Hạng Tần Suất (Jun Da)": "4076.0", "Tần Suất % (Jun Da)": "99.7666477396", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 旱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焊", "Unihan_Traditional (Chữ Phồn thể)": "焊", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động dùng nhiệt để kết nối các chi tiết kim loại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岱', '{"9000": "4077.0", "Chữ Trung Quốc": "岱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 代 | đại | biểu âm | 山 | sơn | biểu nghĩa | núi | 岱 = 代 (Đại, biểu âm) + 山 (Sơn, biểu nghĩa: núi); chữ hình thanh. Bộ 山 chỉ núi, 代 cho âm. Là tên riêng của núi Thái Sơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồi\": núi (山) đại (代 — biểu âm) danh thiên hạ — 岱 là Thái Sơn, ngọn núi thiêng số một Trung Hoa. | Gương Hán-Việt | 岱 xuất hiện trong 岱宗 (đồi tông — Thái Sơn, tông chủ núi), 海岱 (hải đồi — vùng biển và núi Đông Trung Quốc). | Mở khoá kiến thức | Biết 岱 mở khoá 岱宗 (Thái Sơn), 岱嶽 (Thái Nhạc — tên cổ của Thái Sơn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 岱 là chữ hình thanh: 代 biểu âm, 山 (sơn, núi) biểu nghĩa. Là tên riêng chỉ núi Thái Sơn (Taishan) — một trong Ngũ Nhạc của Trung Quốc. Cũng viết 岱宗 (đại tông — Tông chủ các núi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi Đại (tức núi Thái Sơn)", "Hạng Tần Suất (Jun Da)": "4077.0", "Tần Suất % (Jun Da)": "99.7669216357", "GavinGrover_Once (Chiết tự trực tiếp)": "代 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱代山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "代", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岱", "Unihan_Traditional (Chữ Phồn thể)": "岱", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ núi Thái Sơn hoặc trong tên người, tên đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昵', '{"9000": "4078.0", "Chữ Trung Quốc": "昵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 昵 | nặc | tượng hình | bộ 日 gợi ánh sáng ấm áp, sự gần gũi thân mật | 昵 có bộ 日 (nhật, mặt trời/ngày). Nguồn Wiktionary chỉ có {{Han etym}} mà không phân tích chi tiết. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nặc\": ánh mặt trời (日) ấm áp gần gũi — 昵 là thân mật, gần gũi như nắng sưởi ấm. | Gương Hán-Việt | 昵 xuất hiện trong 亲昵 (thân nặc — thân mật, gần gũi), 昵称 (nặc xưng — biệt danh thân mật). | Mở khoá kiến thức | Biết 昵 mở khoá 亲昵 (thân mật), 昵称 (tên gọi thân mật/nickname), 昵友 (bạn thân).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không phân tích cấu tạo chi tiết cho 昵. Bộ 日 (nhật) gợi ánh sáng ấm áp. Nghĩa: thân mật, gần gũi, tiếp cận. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân mật; thân thiết", "Hạng Tần Suất (Jun Da)": "4078.0", "Tần Suất % (Jun Da)": "99.7671955318", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 尼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日尼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昵", "Unihan_Traditional (Chữ Phồn thể)": "昵", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ mối quan hệ thân mật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卅', '{"9000": "4079.0", "Chữ Trung Quốc": "卅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 十 | Số nét | 4 | nét | 卅 | tạp | tượng hình | ba thanh 十 (mười) đặt cạnh nhau = ba mươi | 卅 là chữ tượng hình: chữ 十 (mười) lặp lại ba lần, ghép vào nhau = 30. Tương tự cách 廿 = hai chữ 十 = 20. Là chữ số cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạp\": ba gạch mười (十十十) ghép lại — 卅 là ba mươi, dễ nhớ vì đếm ba nét dọc. | Gương Hán-Việt | 卅 xuất hiện trong 五卅运动 (Ngũ tạp vận động — Phong trào 30 tháng 5 năm 1925). | Mở khoá kiến thức | Biết 卅 mở khoá 廿 (nhị thập — hai mươi), hệ thống chữ số tắt trong văn bản cổ/hành chính.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 卅 là chữ tượng hình: chữ 十 (thập, mười) lặp ba lần. Cũng như 廿 (hai mươi) là hai chữ 十 ghép. Nghĩa: ba mươi. Có thể thấy rõ trong giáp cốt văn và kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ba mươi, 30", "Hạng Tần Suất (Jun Da)": "4079.0", "Tần Suất % (Jun Da)": "99.7674689112", "GavinGrover_Once (Chiết tự trực tiếp)": "川 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: lock", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "川一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "一", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "川", "Unihan_Simplified (Chữ Giản thể)": "卅", "Unihan_Traditional (Chữ Phồn thể)": "卅", "Pinyin_Xie": "sà", "Âm Hán Việt_Xie": "tạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Dùng làm số từ biểu thị số lượng ba mươi trong văn bản cổ hoặc lịch. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飙', '{"9000": "4080.0", "Chữ Trung Quốc": "飙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 16 | nét | 飙 | tiêu | tượng hình | dạng giản thể của 飆: ba chó chạy (猋) + gió (風) = gió cuồng | 飙 là dạng giản thể của 飆. Chữ truyền thống 飆 = 猋 (ba con chó chạy — gợi tốc độ mãnh liệt) + 風 (gió). Nghĩa: gió táp, lốc xoáy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": gió (风) mạnh như ba chó chạy — 飙 là gió táp, lốc xoáy, và cũng nghĩa bóng là tăng vọt. | Gương Hán-Việt | 飙 xuất hiện trong 飙升 (tiêu thăng — tăng vọt), 飙车 (tiêu xa — phóng xe tốc độ cao). | Mở khoá kiến thức | Biết 飙 mở khoá 飙升 (tăng vọt), 飙车 (phóng xe tốc độ cao), 狂飙 (cuồng tiêu — lốc xoáy mạnh).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 飙 là dạng giản thể của 飆, rút 風 thành 风. Chữ truyền thống 飆 = 猋 (ba chó chạy, gợi sức mạnh và tốc độ) + 風 (gió). Nghĩa: cơn lốc xoáy, gió giật mạnh. Nguồn Wiktionary. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió táp, gió giật", "Hạng Tần Suất (Jun Da)": "4080.0", "Tần Suất % (Jun Da)": "99.7677422905", "GavinGrover_Once (Chiết tự trực tiếp)": "猋 + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰猋风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "猋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飙", "Unihan_Traditional (Chữ Phồn thể)": "飆", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cơn gió mạnh hoặc động từ chỉ sự di chuyển nhanh như gió. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邙', '{"9000": "4081.0", "Chữ Trung Quốc": "邙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 5 | nét | 亡 | vong | biểu âm | 阝 | ấp | biểu nghĩa | khu vực, địa danh | 邙 = 亡 (Vong, biểu âm) + 阝(Ấp, biểu nghĩa: địa danh, khu vực); chữ hình thanh. Bộ 阝 (phải) chỉ địa danh, toàn chữ là tên núi Mang ở Hà Nam, Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mương\": vùng đất (阝) của người vong (亡 — biểu âm) — 邙 là núi Mang, nơi chôn cất người chết. | Gương Hán-Việt | 邙 xuất hiện trong 北邙 (Bắc Mương — núi ở phía bắc Lạc Dương, nơi chôn hoàng gia), 邙山 (núi Mang). | Mở khoá kiến thức | Biết 邙 mở khoá 邙山 (núi Mang), 北邙 (Bắc Mang — nơi an táng hoàng gia), dùng trong thơ văn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 邙 là chữ hình thanh: 亡 biểu âm, 邑 (ấp, khu vực) biểu nghĩa — viết tắt thành 阝. Là tên riêng của núi Mang (邙山) ở Lạc Dương, Hà Nam — ngọn núi nổi tiếng nơi chôn cất hoàng tộc thời xưa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi Mang", "Hạng Tần Suất (Jun Da)": "4081.0", "Tần Suất % (Jun Da)": "99.7680156698", "GavinGrover_Once (Chiết tự trực tiếp)": "亡 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亡阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邙", "Unihan_Traditional (Chữ Phồn thể)": "邙", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh núi Mang Sơn ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痞', '{"9000": "4082.0", "Chữ Trung Quốc": "痞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 否 | phủ | biểu âm | 痞 = 疒 (Nạch, biểu nghĩa: bệnh) + 否 (Phủ, biểu âm); chữ hình thanh. Bộ nạch chỉ bệnh tật, toàn chữ chỉ bệnh đầy bụng, tức ngực (dyspepsia).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bỉ\": bệnh (疒) không (否 — biểu âm: phủ định) thông — 痞 là bệnh đầy trướng, và bóng là đứa ''không ra gì''. | Gương Hán-Việt | 痞 xuất hiện trong 痞子 (bỉ tử — đứa lưu manh), 地痞 (địa bỉ — du côn địa phương), 痞块 (bỉ khối — khối tức ngực). | Mở khoá kiến thức | Biết 痞 mở khoá 地痞 (du côn địa phương), 痞子 (kẻ lưu manh), 流氓痞棍 (bọn du thủ du thực).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 痞 là chữ hình thanh: 疒 (bệnh) biểu nghĩa, 否 biểu âm. Nghĩa y học: bệnh đầy trướng bụng (dyspepsia), nhiễm trùng lách. Nghĩa bóng (hiện đại): kẻ lưu manh, du côn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại bệnh)", "Hạng Tần Suất (Jun Da)": "4082.0", "Tần Suất % (Jun Da)": "99.7682880156", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 否", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒否", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "否", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痞", "Unihan_Traditional (Chữ Phồn thể)": "痞", "Pinyin_Xie": "pǐ", "Âm Hán Việt_Xie": "bĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ kẻ lưu manh hoặc tính từ chỉ hành vi vô lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隼', '{"9000": "4083.0", "Chữ Trung Quốc": "隼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 10 | nét | 隼 | thuần | tượng hình | hình vẽ chim cắt đuôi ngắn — vừa biểu nghĩa vừa biểu âm | 隼 là chữ độc lập. Theo Wiktionary, phần trên là hình vẽ chim đuôi ngắn (chim cắt), vừa mang nghĩa vừa cho âm. Chữ gốc viết là 鵻, sau biến thành 隼, rồi 鶽.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": chim cắt (隹) đuôi ngắn (一) thuần — 隼 là chim cắt nhỏ, bay nhanh chính xác. | Gương Hán-Việt | 隼 ít dùng độc lập trong tiếng Việt Hán-Việt; là tên loài chim cắt. | Mở khoá kiến thức | Biết 隼 mở khoá 游隼 (du thuần — chim cắt lữ hành, peregrine falcon), 隼形目 (bộ chim cắt).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 隼 có phần trên là hình vẽ chim đuôi ngắn — gợi chim cắt (falcon). Vừa là thành phần ngữ nghĩa vừa là thành phần ngữ âm. Chữ gốc là 鵻, tiến hóa thành 隼 và cuối cùng là 鶽. Là chữ tượng hình/hội ý kết hợp. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài chim cắt nhỏ", "Hạng Tần Suất (Jun Da)": "4083.0", "Tần Suất % (Jun Da)": "99.7685603614", "GavinGrover_Once (Chiết tự trực tiếp)": "隹 + 十", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱隹十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "十", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "隼", "Unihan_Traditional (Chữ Phồn thể)": "隼", "Pinyin_Xie": "sǔn", "Âm Hán Việt_Xie": "chuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim săn mồi thuộc họ cắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恫', '{"9000": "4084.0", "Chữ Trung Quốc": "恫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 恫 | đổng | tượng hình | chữ độc thể, bộ tâm (心) ẩn trong cấu trúc, biểu thị nỗi đau tinh thần | 恫 là chữ ít tài liệu cấu trúc rõ ràng. Bộ 心 (tâm) ngầm liên quan đến cảm xúc đau đớn, sợ hãi. Chưa xác định được quan hệ hình thanh hay hội ý từ nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổng\": bộ Tâm (心) kết hợp với âm, gợi tiếng đau đớn vang lên từ lòng — 恫嚇 là đe dọa, khiến lòng run sợ. | Gương Hán-Việt | 恫嚇 (đổng hách) — đe dọa, khiếp sợ | Mở khoá kiến thức | Biết 恫 (đổng) mở khoá từ 恫嚇 (đổng hách: đe dọa, uy hiếp) dùng trong văn ngôn và thành ngữ cổ.", "Tự nguyên_Xie": "Tiểu triện | Chưa có nguồn học thuật mô tả nguồn gốc tự dạng của 恫 một cách hệ thống. Wiktionary chỉ ghi nhận phát âm và các từ ghép như 恫嚇 (đe dọa), 恫疑 (nghi ngờ khiếp sợ). Chữ có thể liên quan bộ tâm (心) chỉ trạng thái tâm lý đau khổ, nhưng chưa có tài liệu giáp cốt hay kim văn xác nhận. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "doạ nạt", "Hạng Tần Suất (Jun Da)": "4084.0", "Tần Suất % (Jun Da)": "99.7688321903", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恫", "Unihan_Traditional (Chữ Phồn thể)": "恫", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đỗng, thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành vi đe dọa hoặc làm cho khiếp sợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怆', '{"9000": "4085.0", "Chữ Trung Quốc": "怆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 心 | tâm | biểu nghĩa | tim, cảm xúc | 倉 | thương | biểu âm | kho lương — cho âm | 怆 = 心 (Tâm, biểu nghĩa: cảm xúc) + 倉 (Thương, biểu âm); chữ hình thanh. Bộ tâm (心) chỉ trạng thái tâm lý; 倉 cho âm gần với chuàng/thảng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảng\": bộ Tâm (心) mang nỗi đau như kho (倉) chứa đầy bi thương — 悲怆 là âm thanh não lòng, bi thảng. | Gương Hán-Việt | 悲怆 (bi thảng) — bi thương, não lòng | Mở khoá kiến thức | Biết 怆 (thảng) mở khoá từ 悲怆 (bi thảng: bi thương thống thiết) và 惆怅 (trù thảng: buồn bã, nhớ nhung).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Theo Wiktionary, 怆 là dạng giản thể của 愴. Cấu trúc: 心 (biểu nghĩa: tâm, cảm xúc) + 倉 (biểu âm). Chữ 愴 có bạch thư (Mã Vương Đôi) và tiểu triện, cho thấy xuất hiện từ thời Chiến Quốc. Nghĩa gốc: buồn thương, đau xót trong lòng. Hình thức cổ 愴 dùng bộ tâm đứng (忄) thay vì tâm nằm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thương xót", "Hạng Tần Suất (Jun Da)": "4085.0", "Tần Suất % (Jun Da)": "99.7691035025", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怆", "Unihan_Traditional (Chữ Phồn thể)": "愴", "Pinyin_Xie": "chuàng", "Âm Hán Việt_Xie": "sảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị trạng thái đau buồn, thường dùng trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桀', '{"9000": "4086.0", "Chữ Trung Quốc": "桀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 匄 | biểu âm | cho âm (nay biến thành 舛 trong dạng chữ hiện đại) | 木 | mộc | biểu nghĩa | cây, gỗ | 桀 = 匄 (biểu âm, nay viết là 舛 do dị hóa) + 木 (Mộc, biểu nghĩa: gỗ, giá đỡ); chữ hình thanh. Trong thẻ tre Sở (Chiến Quốc), 匄 là thành phần âm chưa bị biến dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiệt\": 木 (gỗ) đỡ bên dưới như cái giá — Kiệt Vương nhà Hạ, kẻ bạo chúa đứng trên xương người như trên giá gỗ. | Gương Hán-Việt | 桀驁 (kiệt ngạo) — ngoan cố hung hăng; Kiệt Vương (桀) — vua cuối nhà Hạ | Mở khoá kiến thức | Biết 桀 (kiệt) mở khoá từ 桀骜 (kiệt ngạo: hung hãn, không chịu khuất phục) và điển tích Kiệt Trụ (桀纣: hai bạo vương trong lịch sử TQ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, trong thẻ tre Sở (Guodian Chu Slips), 桀 được cấu thành từ 匄 (biểu âm) + 木 (biểu nghĩa: gỗ/giá cây). Trong chữ hiện đại, 匄 đã bị biến dạng thành 舛. Nghĩa gốc: giá đỡ bằng gỗ để gác vật; sau chuyển thành tên vị vua tàn bạo cuối nhà Hạ (Kiệt Vương). Cũng có nghĩa cái chuồng gà bằng gỗ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vua Kiệt (đời nhà Hạ)", "Hạng Tần Suất (Jun Da)": "4086.0", "Tần Suất % (Jun Da)": "99.7693748147", "GavinGrover_Once (Chiết tự trực tiếp)": "舛 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱舛木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舛", "Unihan_Simplified (Chữ Giản thể)": "桀", "Unihan_Traditional (Chữ Phồn thể)": "桀", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ riêng chỉ vua Kiệt hoặc làm tính từ chỉ sự hung bạo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绶', '{"9000": "4087.0", "Chữ Trung Quốc": "绶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绶 | thụ | tượng hình | dây lụa gắn vào ấn quan — chữ độc thể với bộ Mịch (糸) ẩn trong cấu trúc | 绶 là chữ ít tài liệu cấu trúc rõ ràng trong nguồn hiện có. Bộ 糸 (mịch: sợi tơ, lụa) ngầm liên quan đến nghĩa dây lụa. Chưa xác định quan hệ hình thanh hay hội ý từ nguồn học thuật. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụ\": dải lụa đỏ (绶) buộc vào ấn quan — nhận thụ (受) ấn tín là nhận dải thụ (绶), cùng gốc âm. | Gương Hán-Việt | 印绶 (ấn thụ) — ấn tín và dải lụa của quan lại | Mở khoá kiến thức | Biết 绶 (thụ) mở khoá từ 印绶 (ấn thụ: ấn và dải lụa quan), 绶带 (thụ đái: dải lụa huân chương) trong văn ngôn và lịch sử.", "Tự nguyên_Xie": "Kim văn | Wiktionary ghi nhận 绶 là dây lụa buộc vào ấn tín quan chức (official seal) hoặc huy chương. Dạng phồn thể là 綬, có bộ 糸 (mịch: tơ lụa). Dải lụa này có màu sắc phân biệt cấp bậc quan lại trong chế độ phong kiến Trung Hoa. Chưa có glyph origin học thuật từ Wiktionary. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây thao đỏ", "Hạng Tần Suất (Jun Da)": "4087.0", "Tần Suất % (Jun Da)": "99.7696456101", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 受", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟受", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "受", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绶", "Unihan_Traditional (Chữ Phồn thể)": "綬", "Pinyin_Xie": "shòu", "Âm Hán Việt_Xie": "thụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dải lụa màu dùng để buộc ấn tín thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裆', '{"9000": "4088.0", "Chữ Trung Quốc": "裆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 衣 | y | biểu nghĩa | quần áo | 當 | đương | biểu âm | cho âm dāng/đương | 裆 = 衣 (Y, biểu nghĩa: quần áo) + 當 (Đương, biểu âm); chữ hình thanh. Bộ y (衣) chỉ liên quan đến trang phục; 當 cho âm dāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đương\": bộ Y (衣: quần áo) + Đương (當: đúng chỗ) — phần \"đúng chỗ\" của quần, tức đũng quần (裆). | Gương Hán-Việt | 裆部 (đương bộ) — vùng đũng, bộ phận ở giữa hai chân | Mở khoá kiến thức | Biết 裆 (đương) mở khoá từ 裤裆 (quần đương: đũng quần) và 裆部 (đương bộ: vùng giữa hai chân).", "Tự nguyên_Xie": "Theo Wiktionary, 裆 (phồn thể: 襠) được cấu thành từ 衣 (biểu nghĩa: quần áo) + 當 (biểu âm). Chữ chỉ phần giữa hai ống quần — vùng đũng quần hoặc chỗ nối hai ống. Xuất hiện trong văn bản trung đại; không thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái trôn quần, ngã ba khố", "Hạng Tần Suất (Jun Da)": "4088.0", "Tần Suất % (Jun Da)": "99.7699158888", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 当", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤当", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "当", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裆", "Unihan_Traditional (Chữ Phồn thể)": "襠", "Pinyin_Xie": "dāng", "Âm Hán Việt_Xie": "đang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần đũng quần hoặc đáy quần. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盂', '{"9000": "4089.0", "Chữ Trung Quốc": "盂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 8 | nét | 于 | vu | biểu âm | cho âm yú/vu | 皿 | mãnh | biểu nghĩa | đồ đựng, bát đĩa | 盂 = 于 (Vu, biểu âm) + 皿 (Mãnh, biểu nghĩa: đồ đựng, bát); chữ hình thanh. Bộ mãnh (皿) chỉ loại đồ vật; 于 cho âm yú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": bộ Mãnh (皿: đồ đựng) với âm Vu (于) — cái bát vu (盂) đựng nước rửa tay, như trong thành ngữ 漱口盂 (bát nhổ). | Gương Hán-Việt | 漱口盂 (thấu khẩu vu) — bát nhổ, cốc súc miệng | Mở khoá kiến thức | Biết 盂 (vu) mở khoá từ 漱口盂 (thấu khẩu vu: bát nhổ) và 钵盂 (bát vu: bát khất thực của nhà sư).", "Tự nguyên_Xie": "Giáp cốt | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 盂 = 于 (biểu âm) + 皿 (biểu nghĩa: đồ đựng, bát đĩa), là chữ hình thanh. Trong giáp cốt văn và kim văn đã có dạng gần giống chữ hiện đại, chỉ loại bát hoặc chậu đựng nước/thức ăn. Tiểu triện củng cố cấu trúc hiện tại. Nghĩa cơ bản: cái bát, cái chén, cái chậu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "565.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vu (564) Mãnh (98)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vu (số 564 - ở/tại) nằm ở trên chữ Mãnh (số 98 - cái chậu/đĩa). Giải thích sự chuyển ý: Chữ Vu (tại) chỉ âm, chữ Mãnh (đồ đựng) chỉ ý. Vu là các dụng cụ chứa đựng nước hoặc đồ vật như cái âu, cái ống, cái chậu.", "Nghĩa Tiếng Việt_Xie": "cái chén", "Hạng Tần Suất (Jun Da)": "4089.0", "Tần Suất % (Jun Da)": "99.7701856506", "GavinGrover_Once (Chiết tự trực tiếp)": "于 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱于皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盂", "Unihan_Traditional (Chữ Phồn thể)": "盂", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại đồ đựng hình tròn, miệng rộng như bát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桧', '{"9000": "4090.0", "Chữ Trung Quốc": "桧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桧 | cối | tượng hình | chữ độc thể hoặc hình thanh chưa phân tích được từ nguồn hiện có | 桧 ít tài liệu cấu trúc rõ ràng trong nguồn hiện có. Wiktionary liệt kê như tên riêng (nước Cối) và loài cây tùng bách. Chưa xác định được quan hệ hình thanh hay hội ý. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cối\": cây cối (桧) như cây tùng xanh quanh năm — nước Cối (桧) trong Kinh Thi, tên địa danh cổ Trung Hoa. | Gương Hán-Việt | 桧柏 (cối bách) — cây tùng bách; Tần Cối (秦桧) — tên nhân vật lịch sử | Mở khoá kiến thức | Biết 桧 (cối) mở khoá từ 桧柏 (cối bách: cây tùng bách) và tên Tần Cối (秦桧) — gian thần nhà Tống nổi tiếng trong lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 桧 có hai âm: guì (tiêu chuẩn Đại lục) và kuài (tiêu chuẩn Đài Loan). Nghĩa: cây tùng bách Trung Quốc (Chinese juniper/cypress). Cũng là tên nước Cối thời Xuân Thu. Chưa có glyph origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cối (một loài thông); nước cối", "Hạng Tần Suất (Jun Da)": "4090.0", "Tần Suất % (Jun Da)": "99.7704554125", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桧", "Unihan_Traditional (Chữ Phồn thể)": "檜", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "cối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cây thuộc họ bách hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚓', '{"9000": "4091.0", "Chữ Trung Quốc": "蚓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 引 | dẫn | biểu âm | cho âm yǐn/dẫn | 蚓 = 虫 (Trùng, biểu nghĩa: sinh vật nhỏ) + 引 (Dẫn, biểu âm); chữ hình thanh. Bộ trùng (虫) chỉ loại sinh vật; 引 cho âm yǐn gần với âm đọc hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dẫn\": bộ Trùng (虫) + Dẫn (引: kéo dài) — con giun đất (蚯蚓) kéo dài thân mình qua đất như kéo sợi dây. | Gương Hán-Việt | 蚯蚓 (khưu dẫn) — con giun đất | Mở khoá kiến thức | Biết 蚓 (dẫn) mở khoá từ 蚯蚓 (khưu dẫn: giun đất) — từ luôn đi cùng 蚯, hiếm dùng độc lập.", "Tự nguyên_Xie": "Theo Wiktionary, 蚓 = 虫 (biểu nghĩa: sinh vật nhỏ) + 引 (biểu âm), là chữ hình thanh. Chữ dùng chủ yếu trong từ ghép 蚯蚓 (qiūyǐn: giun đất). Đây là sinh vật sống trong đất, có thân mềm dài. Không tìm thấy trong giáp cốt văn; xuất hiện trong văn bản trung đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khưu dẫn 蚯蚓)", "Hạng Tần Suất (Jun Da)": "4091.0", "Tần Suất % (Jun Da)": "99.7707246575", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 引", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫引", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "引", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚓", "Unihan_Traditional (Chữ Phồn thể)": "蚓", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "dẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ xuất hiện trong từ ghép để chỉ con giun đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抠', '{"9000": "4092.0", "Chữ Trung Quốc": "抠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 抠 | khu | tượng hình | chữ có bộ 手 (thủ) ẩn, hành động dùng tay moi móc | 抠 ít tài liệu cấu trúc từ nguồn hiện có. Bộ 手/扌 (thủ: tay) ngầm liên quan đến hành động dùng tay; phần còn lại chưa xác định rõ. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khu\": tay (扌) moi vào góc khuất — 抠门 là kẻ bủn xỉn, tay chặt chẽ không chịu móc tiền ra. | Gương Hán-Việt | 抠门 (khu môn) — keo kiệt, bủn xỉn | Mở khoá kiến thức | Biết 抠 (khu) mở khoá từ 抠门 (khu môn: keo kiệt), 抠图 (khu đồ: cắt ghép ảnh) và 抠字眼 (khu tự nhãn: bới lông tìm vết trong ngôn từ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp glyph origin chi tiết cho 抠. Chữ thuộc bộ 手 (扌), biểu thị hành động dùng tay: moi, móc ra, khắc chạm. Cũng có nghĩa bủn xỉn (tight-fisted). Đây là chữ muộn, không thấy trong giáp cốt hay kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "moi, móc; khắc, chạm", "Hạng Tần Suất (Jun Da)": "4092.0", "Tần Suất % (Jun Da)": "99.7709933858", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抠", "Unihan_Traditional (Chữ Phồn thể)": "摳", "Pinyin_Xie": "kōu", "Âm Hán Việt_Xie": "khu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động móc, khoét hoặc làm tính từ chỉ tính cách keo kiệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kōu | / | đào ra | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗷', '{"9000": "4093.0", "Chữ Trung Quốc": "嗷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗷 | ngao | tượng hình | chữ hình thanh với bộ Khẩu (口) biểu thị tiếng kêu to | 嗷 có bộ 口 (khẩu: miệng, tiếng kêu) liên quan đến nghĩa âm thanh ồn ào. Phần âm chưa được xác định rõ ràng từ nguồn học thuật. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": miệng (口) kêu to như tiếng ngao ngán — 嗷嗷待哺 là tiếng chim non kêu khóc đòi ăn, inh ỏi khắp nơi. | Gương Hán-Việt | 嗷嗷 (ngao ngao) — tiếng kêu inh ỏi, ồn ào | Mở khoá kiến thức | Biết 嗷 (ngao) mở khoá từ 嗷嗷待哺 (ngao ngao đãi bộ: kêu khóc đợi cho ăn — chỉ tình trạng thiếu thốn cấp bách) và 嗷嗷叫 (kêu ầm ĩ).", "Tự nguyên_Xie": "Wiktionary không cung cấp glyph origin chi tiết cho 嗷. Chữ thuộc bộ 口 (khẩu), biểu thị tiếng kêu, tiếng ồn ào. Dùng chủ yếu trong từ ghép 嗷嗷 (tiếng kêu to, khóc inh ỏi) và 嗷嗷待哺 (chim non kêu đói chờ mồi). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng om sòm", "Hạng Tần Suất (Jun Da)": "4093.0", "Tần Suất % (Jun Da)": "99.7712621141", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 敖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口敖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗷", "Unihan_Traditional (Chữ Phồn thể)": "嗷", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô phỏng tiếng kêu khóc thảm thiết hoặc tiếng kêu đói. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槌', '{"9000": "4094.0", "Chữ Trung Quốc": "槌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 追 | đôi | biểu âm | cho âm chuí/đôi | 槌 = 木 (Mộc, biểu nghĩa: gỗ) + 追 (Đôi, biểu âm); chữ hình thanh. Bộ mộc (木) chỉ vật liệu làm từ gỗ; 追 cho âm chuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đôi\": bộ Mộc (木: gỗ) mang âm Đôi (追) — cái vồ gỗ nặng (槌) đập xuống, tiếng đôi đôi vang lên. | Gương Hán-Việt | 木槌 (mộc đôi) — cái vồ gỗ; 槌击 (đôi kích) — đập bằng vồ | Mở khoá kiến thức | Biết 槌 (đôi) mở khoá từ 木槌 (mộc đôi: vồ gỗ), 鼓槌 (cổ đôi: dùi trống) và 槌球 (đôi cầu: môn thể thao dùng vồ đánh bóng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 槌 = 木 (biểu nghĩa: gỗ) + 追 (biểu âm), là chữ hình thanh. Nghĩa: cái vồ, cái búa gỗ lớn; đánh bằng vồ. Trong tiểu triện đã có dạng gần chữ hiện đại. Dụng cụ làm từ gỗ để đập, đánh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vồ lớn; đánh đập", "Hạng Tần Suất (Jun Da)": "4094.0", "Tần Suất % (Jun Da)": "99.7715308423", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 追", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木追", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "追", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槌", "Unihan_Traditional (Chữ Phồn thể)": "槌", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chuỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ dụng cụ gõ hoặc động từ chỉ hành động gõ, nện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痘', '{"9000": "4095.0", "Chữ Trung Quốc": "痘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | biểu nghĩa | bộ bệnh, chỉ bệnh tật | 豆 | đậu | biểu âm | hạt đậu — cho âm dòu/đậu | 痘 = 疒 (bộ bệnh, biểu nghĩa: bệnh tật) + 豆 (Đậu, biểu âm và biểu nghĩa bổ sung); chữ hình thanh kiêm hội ý. Bộ bệnh (疒) chỉ đây là bệnh; 豆 (hạt đậu) vừa cho âm vừa mô tả nốt phỏng tròn như hạt đậu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đậu\": bộ Bệnh (疒) + Đậu (豆: hạt đậu) — bệnh đậu mùa (痘) tạo nốt tròn như hạt đậu trên da. | Gương Hán-Việt | 天花痘 (thiên hoa đậu) — bệnh đậu mùa; 水痘 (thủy đậu) — thủy đậu | Mở khoá kiến thức | Biết 痘 (đậu) mở khoá từ 水痘 (thủy đậu: bệnh thủy đậu), 天花 hay 痘疹 (đậu chẩn: bệnh đậu mùa), 牛痘 (ngưu đậu: vaccine đậu bò).", "Tự nguyên_Xie": "Theo Wiktionary, 痘 = 疒 (biểu nghĩa: bệnh) + 豆 (biểu âm và gợi ý hình dạng: hạt đậu). Bệnh đậu mùa (天花) gây ra các nốt phỏng tròn trên da trông như hạt đậu, nên chữ vừa mang nghĩa bệnh (疒) vừa mô tả triệu chứng qua hình ảnh hạt đậu (豆). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh đậu mùa", "Hạng Tần Suất (Jun Da)": "4095.0", "Tần Suất % (Jun Da)": "99.7717990538", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痘", "Unihan_Traditional (Chữ Phồn thể)": "痘", "Pinyin_Xie": "dòu", "Âm Hán Việt_Xie": "đậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ bệnh đậu mùa hoặc các nốt mụn mủ trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痢', '{"9000": "4096.0", "Chữ Trung Quốc": "痢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | biểu nghĩa | bộ bệnh, chỉ bệnh tật | 利 | lợi | biểu âm | cho âm lì/lợi | 痢 = 疒 (bộ bệnh, biểu nghĩa: bệnh tật) + 利 (Lợi, biểu âm); chữ hình thanh. Bộ bệnh (疒) chỉ đây là loại bệnh; 利 cho âm lì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lị\": bộ Bệnh (疒) mang âm Lợi (利) — bệnh lị (痢) tên đọc gần giống lị, bệnh đường ruột nguy hiểm. | Gương Hán-Việt | 痢疾 (lị tật) — bệnh kiết lị; 赤痢 (xích lị) — lị đỏ (có máu) | Mở khoá kiến thức | Biết 痢 (lị) mở khoá từ 痢疾 (lị tật: bệnh kiết lị), 赤痢 (xích lị: lị ra máu) và 细菌性痢疾 (vi khuẩn tính lị tật: lị vi khuẩn).", "Tự nguyên_Xie": "Theo Wiktionary, 痢 = 疒 (biểu nghĩa: bệnh) + 利 (biểu âm), là chữ hình thanh chỉ bệnh lỵ (kiết lị). Bệnh đặc trưng bởi tiêu chảy ra máu, đau bụng dữ dội. Không thấy trong giáp cốt hay kim văn; xuất hiện trong y thư trung đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh kiết lị", "Hạng Tần Suất (Jun Da)": "4096.0", "Tần Suất % (Jun Da)": "99.7720672653", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 利", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒利", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痢", "Unihan_Traditional (Chữ Phồn thể)": "痢", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác để chỉ bệnh kiết lị hoặc chứng tiêu chảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芮', '{"9000": "4097.0", "Chữ Trung Quốc": "芮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 內 | nội | biểu âm | cho âm ruì/nội | 芮 = 艸 (Thảo, biểu nghĩa: cỏ, thực vật) + 內 (Nội, biểu âm); chữ hình thanh. Bộ thảo (艸/草字头) chỉ liên quan thực vật; 內 cho âm ruì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuế\": bộ Thảo (艸) + Nội (內) — ngọn cỏ nhỏ xíu (芮) mới nhú lên, mảnh như đầu kim. | Gương Hán-Việt | 芮芮 (nhuế nhuế) — mọc nhiều, nhỏ xíu; Nước Nhuế (芮) — chư hầu thời Chu | Mở khoá kiến thức | Biết 芮 (nhuế) mở khoá tên họ Nhuế (芮 họ người) và địa danh Nhuế Thành trong lịch sử nhà Chu. Hiếm dùng ngoài tên riêng và văn ngôn.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 芮 = 艸 (biểu nghĩa: cỏ) + 內 (biểu âm), là chữ hình thanh. Nghĩa gốc: nhỏ xíu (chỉ cỏ non mới mọc). Cũng là tên nước Nhuế thời Chu và họ người. Trong kim văn và tiểu triện đã có dạng tương đương. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ xíu; bến sông; nước Nhuế", "Hạng Tần Suất (Jun Da)": "4097.0", "Tần Suất % (Jun Da)": "99.7723354768", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芮", "Unihan_Traditional (Chữ Phồn thể)": "芮", "Pinyin_Xie": "ruì", "Âm Hán Việt_Xie": "nhuế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự nhỏ bé hoặc làm danh từ riêng chỉ tên nước cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚣', '{"9000": "4098.0", "Chữ Trung Quốc": "蚣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 公 | công | biểu âm | cho âm gōng/công | 蚣 = 虫 (Trùng, biểu nghĩa: sinh vật nhỏ) + 公 (Công, biểu âm); chữ hình thanh. Bộ trùng (虫) chỉ loại sinh vật; 公 cho âm gōng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"công\": bộ Trùng (虫) + Công (公) — con rết (蜈蚣) có nhiều chân nhanh nhẹn như \"công nhân\" đa năng dưới đất. | Gương Hán-Việt | 蜈蚣 (ngô công) — con rết | Mở khoá kiến thức | Biết 蚣 (công) mở khoá từ 蜈蚣 (ngô công: con rết) — chữ này hầu như chỉ xuất hiện trong từ ghép này.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 蚣 = 虫 (biểu nghĩa: sinh vật) + 公 (biểu âm), là chữ hình thanh. Chữ dùng chủ yếu trong từ ghép 蜈蚣 (wúgōng: con rết). Con rết là loài chân nhiều đốt, nọc độc. Tiểu triện và lưu thư thông đều có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngô công 蜈蚣)", "Hạng Tần Suất (Jun Da)": "4098.0", "Tần Suất % (Jun Da)": "99.7726036883", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 公", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫公", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚣", "Unihan_Traditional (Chữ Phồn thể)": "蚣", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "công", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng trong từ ghép ngô công để chỉ con rết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闩', '{"9000": "4099.0", "Chữ Trung Quốc": "闩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 4 | nét | 門 | môn | biểu nghĩa | cửa, cổng | 一 | nhất | biểu nghĩa | một thanh ngang — then cài | 闩 = 門 (Môn, biểu nghĩa: cửa) + 一 (Nhất, biểu nghĩa: thanh ngang); chữ hội ý. Hình ảnh một thanh ngang (一) cài ngang cửa (門) — biểu thị then cửa. Rõ ràng trực quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyên\": Môn (門: cửa) + Nhất (一: một thanh) — thanh ngang cài ngang cửa là then (闩 thuyên); cài then là động từ. | Gương Hán-Việt | 门闩 (môn thuyên) — then cửa; 闩门 (thuyên môn) — cài then cửa | Mở khoá kiến thức | Biết 闩 (thuyên) mở khoá từ 门闩 (môn thuyên: then cửa) và 闩上门 (thuyên thượng môn: cài chặt cửa lại).", "Tự nguyên_Xie": "Theo Wiktionary, 闩 = 門 (cửa) + 一 (thanh ngang), là chữ hội ý. Hình tượng: thanh ngang cài ngang cổng để đóng chặt. So sánh với 關 (quan: đóng), cùng ý niệm đóng cửa. Nghĩa gốc và nghĩa hiện đại đều là: then cài cửa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái then cửa", "Hạng Tần Suất (Jun Da)": "4099.0", "Tần Suất % (Jun Da)": "99.7728708662", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "一", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闩", "Unihan_Traditional (Chữ Phồn thể)": "閂", "Pinyin_Xie": "shuān", "Âm Hán Việt_Xie": "soan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ cái then cửa hoặc làm động từ chỉ hành động cài then. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铿', '{"9000": "4100.0", "Chữ Trung Quốc": "铿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 铿 | khanh | tượng hình | chữ hình thanh với bộ Kim (金) biểu thị tiếng kim loại kêu | 铿 là chữ có bộ 金/钅 (kim: kim loại) liên quan đến tiếng đàn hoặc nhạc cụ kim loại. Phần âm chưa được xác định rõ từ nguồn học thuật. Dùng chủ yếu trong từ láy 铿锵. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khanh\": bộ Kim (钅: kim loại) gõ ra tiếng khanh — 铿锵有力 là giọng nói hay tiếng nhạc vang khanh khách, mạnh mẽ. | Gương Hán-Việt | 铿锵 (khanh thương) — âm thanh vang vọng, hùng hồn | Mở khoá kiến thức | Biết 铿 (khanh) mở khoá từ 铿锵有力 (khanh thương hữu lực: vang vọng có lực — lời nói hoặc âm nhạc hùng hồn) thường dùng trong văn học.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi nhận phát âm nhưng không có glyph origin học thuật cho 铿. Chữ thuộc bộ 金/钅 (kim: kim loại), chỉ tiếng khua kim loại, tiếng đàn sắt đàn cầm. Dùng trong 铿锵 mô tả âm thanh hùng hồn, vang vọng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn; chỉ thấy trong lục thư thông. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng đàn cầm, đàn sắt; khua, đánh", "Hạng Tần Suất (Jun Da)": "4100.0", "Tần Suất % (Jun Da)": "99.7731380441", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 坚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅坚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铿", "Unihan_Traditional (Chữ Phồn thể)": "鏗", "Pinyin_Xie": "kēng", "Âm Hán Việt_Xie": "khanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô tả tiếng kim khí va chạm hoặc động từ chỉ hành động gõ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飓', '{"9000": "4101.0", "Chữ Trung Quốc": "飓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 12 | nét | 飓 | cự | tượng hình | chữ giản thể của 颶, bộ Phong (风) chỉ gió mạnh | 飓 là giản thể của 颶. Bộ 风 (phong: gió) liên quan đến nghĩa gió bão. Wiktionary ghi rõ 飓 = {{Han simp|颶|f=風|t=风}}, tức giản hóa từ 颶 bằng cách thay 風 thành 风. chưa có nguồn học thuật về cấu trúc gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": bộ Phong (风: gió) mạnh cự (大) — 飓风 là cơn bão lớn, sức gió cực mạnh. | Gương Hán-Việt | 飓风 (cự phong) — bão, siêu bão | Mở khoá kiến thức | Biết 飓 (cự) mở khoá từ 飓风 (cự phong: bão nhiệt đới, hurricane) dùng thường xuyên trong tin tức thời tiết.", "Tự nguyên_Xie": "飓 là dạng giản thể của 颶. Theo Wiktionary, 颶 (phồn thể) = 風 (biểu nghĩa: gió) + một thành phần khác. Nghĩa: bão nhiệt đới, gió xoáy (hurricane/typhoon). Chữ tạo muộn để chỉ hiện tượng thời tiết. Không thấy trong giáp cốt hay kim văn. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió bão, giông, lốc", "Hạng Tần Suất (Jun Da)": "4101.0", "Tần Suất % (Jun Da)": "99.7734047052", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 具", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风具", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "具", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飓", "Unihan_Traditional (Chữ Phồn thể)": "颶", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với từ phong tạo thành cự phong để chỉ gió bão lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疱', '{"9000": "4102.0", "Chữ Trung Quốc": "疱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疱 | bào | tượng hình | chữ giản thể của 皰, bộ Nạch (疒) chỉ bệnh ngoài da | 疱 là giản thể của 皰. Bộ 疒 (nạch: bệnh) liên quan đến bệnh ngoài da. Wiktionary ghi 疱 = {{zh-see|皰}} — xem 皰. Chưa có cấu trúc chi tiết từ nguồn học thuật cho dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": bộ Nạch (疒: bệnh) gợi nốt bào (bọc nước) — 疱疹 là mụn rộp, nốt phỏng mọc trên da. | Gương Hán-Việt | 疱疹 (bào chẩn) — mụn rộp, herpes | Mở khoá kiến thức | Biết 疱 (bào) mở khoá từ 疱疹 (bào chẩn: mụn rộp/herpes) và 水疱 (thủy bào: bọng nước trên da).", "Tự nguyên_Xie": "Tiểu triện | 疱 là giản thể của 皰 (phồn thể). Nghĩa: mụn nước, nốt phỏng trên da; mụn trứng cá. Bộ 疒 (nạch) chỉ bệnh ngoài da. Tiểu triện có dạng 皰. Không tìm thấy trong giáp cốt văn. chưa có nguồn học thuật chi tiết cho dạng giản. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trứng cá, mụn nước; nốt", "Hạng Tần Suất (Jun Da)": "4102.0", "Tần Suất % (Jun Da)": "99.7736703328", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疱", "Unihan_Traditional (Chữ Phồn thể)": "皰", "Pinyin_Xie": "pào", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các nốt mụn nước hoặc vết phồng rộp trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝌', '{"9000": "4103.0", "Chữ Trung Quốc": "蝌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝌 | khoa | tượng hình | chữ hình thanh với bộ Trùng (虫) chỉ sinh vật thủy sinh | 蝌 có bộ 虫 (trùng: sinh vật nhỏ) liên quan đến sinh vật dưới nước. Phần âm chưa xác định rõ từ nguồn. Dùng chủ yếu trong từ 蝌蚪 (nòng nọc). chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoa\": bộ Trùng (虫) + âm Khoa — 蝌蚪 (khoa đẩu) là con nòng nọc, đầu to như chữ nòng nọc cổ đại. | Gương Hán-Việt | 蝌蚪 (khoa đẩu) — con nòng nọc; chữ nòng nọc (khoa đẩu văn) | Mở khoá kiến thức | Biết 蝌 (khoa) mở khoá từ 蝌蚪 (khoa đẩu: nòng nọc) và 蝌蚪文 (khoa đẩu văn: chữ nòng nọc — chữ cổ đại).", "Tự nguyên_Xie": "Wiktionary ghi nhận 蝌 chỉ dùng trong từ 蝌蚪 (nòng nọc). Bộ 虫 (trùng) chỉ đây là sinh vật nhỏ sống dưới nước. Không thấy trong giáp cốt hay kim văn; là chữ tương đối muộn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khoa đẩu 蝌蚪)", "Hạng Tần Suất (Jun Da)": "4103.0", "Tần Suất % (Jun Da)": "99.7739359603", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 科", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫科", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "科", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝌", "Unihan_Traditional (Chữ Phồn thể)": "蝌", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ dùng trong từ ghép khoa đẩu để chỉ con nòng nọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撅', '{"9000": "4104.0", "Chữ Trung Quốc": "撅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 撅 | quết | tượng hình | chữ có bộ Thủ (扌) chỉ hành động tay; vểnh lên, bẻ gãy | 撅 có bộ 手/扌 (thủ: tay) liên quan đến hành động thể chất. Phần còn lại chưa xác định rõ từ nguồn. Nghĩa chính: vểnh/bĩu môi, bẻ gãy, đào. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quết\": tay (扌) vểnh lên như quệt — 撅嘴 là bĩu môi, 撅起屁股 là chổng mông lên. | Gương Hán-Việt | 撅嘴 (quết chủy) — bĩu môi, méo miệng (khi giận) | Mở khoá kiến thức | Biết 撅 (quết) mở khoá từ 撅嘴 (quết chủy: bĩu môi) và 撅断 (quết đoạn: bẻ gãy) trong khẩu ngữ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm juē cho 撅 nhưng không có glyph origin. Bộ 扌 (thủ: tay) chỉ hành động dùng tay hoặc hành động vật lý. Nghĩa: vểnh lên (môi, mông), bẻ gãy, đào. Tiểu triện có dạng gần chữ hiện đại. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bĩu, giảu, vểnh, vênh, cong; bẻ gãy; đào; vạch áo; đánh", "Hạng Tần Suất (Jun Da)": "4104.0", "Tần Suất % (Jun Da)": "99.7742010711", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撅", "Unihan_Traditional (Chữ Phồn thể)": "撅", "Pinyin_Xie": "juē", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động bĩu môi, vểnh đuôi hoặc bẻ gãy vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚯', '{"9000": "4105.0", "Chữ Trung Quốc": "蚯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚯 | khưu | tượng hình | chữ hình thanh với bộ Trùng (虫), dùng trong từ 蚯蚓 (giun đất) | 蚯 có bộ 虫 (trùng: sinh vật nhỏ) liên quan đến giun đất. Chữ chỉ dùng trong từ ghép 蚯蚓. Phần âm chưa xác định rõ từ nguồn. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khưu\": bộ Trùng (虫) + âm Khưu — 蚯蚓 (khưu dẫn) là con giun đất, âm tiết đầu trong tên của nó. | Gương Hán-Việt | 蚯蚓 (khưu dẫn) — con giun đất | Mở khoá kiến thức | Biết 蚯 (khưu) mở khoá từ 蚯蚓 (khưu dẫn: giun đất) — chữ hầu như chỉ xuất hiện trong từ ghép này.", "Tự nguyên_Xie": "Wiktionary ghi nhận 蚯 chỉ dùng trong 蚯蚓 (qiūyǐn: giun đất). Bộ 虫 (trùng) chỉ đây là sinh vật nhỏ sống trong đất. Không thấy trong giáp cốt hay kim văn; là chữ muộn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khưu dẫn 蚯蚓)", "Hạng Tần Suất (Jun Da)": "4105.0", "Tần Suất % (Jun Da)": "99.7744661819", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 丘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫丘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚯", "Unihan_Traditional (Chữ Phồn thể)": "蚯", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "khâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng trong từ ghép khưu dẫn để chỉ con giun đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斡', '{"9000": "4106.0", "Chữ Trung Quốc": "斡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 斗 | Số nét | 14 | nét | 倝 | biểu âm | cho âm wò/át | 斗 | đẩu | biểu nghĩa | cái gáo múc, hình tượng xoay tròn | 斡 = 倝 (biểu âm, thành phần chưa có HV rõ) + 斗 (Đẩu, biểu nghĩa: cái gáo/cái muôi, hình tượng xoay); chữ hình thanh. Bộ đẩu (斗) gợi chuyển động xoay tròn; 倝 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"át\": cái gáo (斗) xoay vần (斡) — 斡旋 là xoay chuyển, dàn xếp trung gian giữa hai bên. | Gương Hán-Việt | 斡旋 (át triền) — dàn xếp, hòa giải, trung gian | Mở khoá kiến thức | Biết 斡 (át) mở khoá từ 斡旋 (át triền: hòa giải, làm trung gian) dùng nhiều trong ngoại giao và văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 斡 = 倝 (biểu âm) + 斗 (biểu nghĩa: cái gáo múc), là chữ hình thanh. Nghĩa gốc: xoay, quay, vần vũ. Trong tiểu triện có dạng gần chữ hiện đại. Từ 斡旋 (áp triền/át triền) nghĩa là hòa giải, trung gian — hình ảnh xoay chuyển tình thế. chưa có nguồn học thuật chi tiết ngoài cấu trúc cơ bản. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quay, vần", "Hạng Tần Suất (Jun Da)": "4106.0", "Tần Suất % (Jun Da)": "99.7747307759", "GavinGrover_Once (Chiết tự trực tiếp)": "龺 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "斡", "Unihan_Traditional (Chữ Phồn thể)": "斡", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "oát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong văn viết cổ hoặc dùng trong từ ghép để chỉ sự xoay chuyển tình thế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窠', '{"9000": "4107.0", "Chữ Trung Quốc": "窠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 13 | nét | 窠 | khoa | tượng hình | chữ có bộ Huyệt (穴) chỉ hốc hang; tổ chim trong hang | 窠 có bộ 穴 (huyệt: hốc, hang) bên trên liên quan đến nghĩa tổ chim trong hang/hốc. Phần dưới chưa xác định rõ từ nguồn. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoa\": bộ Huyệt (穴: hang) bên trên — 窠臼 (khoa cữu) là cái khuôn mẫu sáo rỗng, như tổ chim (窠) cũ ai cũng biết. | Gương Hán-Việt | 窠臼 (khoa cữu) — khuôn sáo, cũ rích; tổ chim (窠) | Mở khoá kiến thức | Biết 窠 (khoa) mở khoá từ 老套窠臼 (lão sáo khoa cữu: sáo cũ, không sáng tạo) dùng trong phê bình văn học/nghệ thuật.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 窠 nghĩa: tổ chim trong hốc; hang ổ. Bộ 穴 (huyệt: hốc, hang) chỉ không gian trú ẩn bên trong. Phần âm/nghĩa dưới chưa có glyph origin học thuật. Tiểu triện có dạng gần chữ hiện đại. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tổ; tổ chim; ổ chim; chuồng", "Hạng Tần Suất (Jun Da)": "4107.0", "Tần Suất % (Jun Da)": "99.7749953699", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窠", "Unihan_Traditional (Chữ Phồn thể)": "窠", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ tổ của chim thú hoặc làm lượng từ cho cây cối trong văn thơ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荚', '{"9000": "4108.0", "Chữ Trung Quốc": "荚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荚 | giáp | tượng hình | chữ có bộ Thảo (艸) chỉ thực vật; vỏ quả cây họ đậu | 荚 có bộ 艸/草字头 (thảo: cỏ, thực vật) liên quan đến thực vật. Phần âm/cấu trúc bên dưới chưa xác định rõ từ nguồn. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": bộ Thảo (艸) bao bên ngoài như giáp (갑: vỏ bọc) — vỏ quả đậu (荚) như tấm giáp xanh bảo vệ hạt bên trong. | Gương Hán-Việt | 豆荚 (đậu giáp) — vỏ quả đậu, cây đậu | Mở khoá kiến thức | Biết 荚 (giáp) mở khoá từ 豆荚 (đậu giáp: vỏ quả đậu) và 荚果 (giáp quả: quả họ đậu) trong nông nghiệp và thực vật học.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 荚 nghĩa: vỏ quả cây họ đậu (pods of leguminous plants). Bộ 艸 (thảo) chỉ đây là bộ phận thực vật. Tiểu triện có dạng gần chữ hiện đại. Không thấy trong giáp cốt văn. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả", "Hạng Tần Suất (Jun Da)": "4108.0", "Tần Suất % (Jun Da)": "99.7752594471", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荚", "Unihan_Traditional (Chữ Phồn thể)": "莢", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên các loại cây họ đậu để chỉ phần quả có vỏ bao bọc hạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耷', '{"9000": "4109.0", "Chữ Trung Quốc": "耷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 9 | nét | 耷 | đa | tượng hình | chữ hội ý: 大 (lớn) + 耳 (tai) — tai to, tai rủ xuống | 耷 trông có cấu trúc 大 (đại: lớn) bên trên + 耳 (nhĩ: tai) bên dưới — hội ý trực tiếp: tai (耳) to (大), tai rủ. Wiktionary không cung cấp glyph origin học thuật nhưng cấu trúc trực quan rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đa\": 大 (đại: to lớn) + 耳 (nhĩ: tai) — tai to rủ xuống như tai chó basset; 耷拉 là rủ xuống, cụp xuống. | Gương Hán-Việt | 耷拉 (đa lạp) — cụp xuống, rủ xuống (tai, đuôi động vật) | Mở khoá kiến thức | Biết 耷 (đa) mở khoá từ 耷拉 (đa lạp: rủ xuống, cụp xuống) dùng miêu tả tai hoặc đuôi động vật cụp lại.", "Tự nguyên_Xie": "耷 là chữ tương đối muộn, không thấy trong giáp cốt hay kim văn. Cấu trúc 大 (lớn) + 耳 (tai) gợi nghĩa tai to, tai rủ xuống. Wiktionary không có glyph origin học thuật cho chữ này. Dùng chủ yếu để mô tả tai động vật (chó, thỏ...) rủ xuống. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tai to; tai lớn", "Hạng Tần Suất (Jun Da)": "4109.0", "Tần Suất % (Jun Da)": "99.7755230075", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "耷", "Unihan_Traditional (Chữ Phồn thể)": "耷", "Pinyin_Xie": "dā", "Âm Hán Việt_Xie": "đạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ kết hợp với bộ phận cơ thể như tai hoặc đầu để miêu tả trạng thái rủ xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砚', '{"9000": "4110.0", "Chữ Trung Quốc": "砚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砚 | nghiễn | tượng hình | chữ có bộ Thạch (石) chỉ đá; nghiên mực đá | 砚 (phồn: 硯) có bộ 石 (thạch: đá) liên quan đến nghiên mực bằng đá. Phần âm/cấu trúc chưa xác định rõ từ nguồn. Chữ chỉ vật dụng bằng đá dùng trong văn phòng. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiễn\": bộ Thạch (石: đá) — nghiên mực (砚) là tấm đá quý dùng mài mực, một trong văn phòng tứ bảo. | Gương Hán-Việt | 砚台 (nghiễn đài) — nghiên mực; 文房四宝 (văn phòng tứ bảo) gồm bút, mực, giấy, nghiên | Mở khoá kiến thức | Biết 砚 (nghiễn) mở khoá từ 砚台 (nghiễn đài: nghiên mực), 端砚 (đoan nghiễn: nghiên Đoan Khê nổi tiếng) trong nghệ thuật thư pháp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 砚 (giản thể của 硯) nghĩa: nghiên mực (inkstone) — phiến đá dùng để mài mực khi viết thư pháp. Bộ 石 (thạch: đá) chỉ chất liệu làm từ đá. Tiểu triện có dạng 硯. Nghiên mực là một trong bốn báu vật của người học (文房四宝). chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bát; cái nghiên mực", "Hạng Tần Suất (Jun Da)": "4110.0", "Tần Suất % (Jun Da)": "99.7757860511", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砚", "Unihan_Traditional (Chữ Phồn thể)": "硯", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nghiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ dụng cụ mài mực viết chữ Hán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牒', '{"9000": "4111.0", "Chữ Trung Quốc": "牒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 片 | Số nét | 13 | nét | 牒 | điệp | tượng hình | chữ có bộ Phiến (片) chỉ tấm gỗ mỏng; văn thư, tờ trình | 牒 có bộ 片 (phiến: tấm mỏng, bảng gỗ) liên quan đến văn bản viết trên bảng/thẻ. Phần còn lại chưa xác định rõ từ nguồn. Chữ chỉ loại văn thư hành chính. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệp\": bộ Phiến (片: tấm mỏng) — điệp văn (牒文) là tờ trình quan, văn thư như những tấm gỗ mỏng chồng lên nhau. | Gương Hán-Việt | 通牒 (thông điệp) — tối hậu thư; 牒文 (điệp văn) — văn thư công vụ | Mở khoá kiến thức | Biết 牒 (điệp) mở khoá từ 通牒 (thông điệp: tối hậu thư) dùng trong ngoại giao và 度牒 (độ điệp: giấy chứng nhận thọ giới của nhà sư).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 牒 nghĩa: thẻ viết chữ, tờ văn thư chính thức (writing slip, dispatch). Bộ 片 (phiến: tấm mỏng) chỉ vật liệu viết bằng gỗ mỏng thời cổ. Tiểu triện có dạng gần chữ hiện đại. Trong chế độ quan liêu cổ đại, 牒 là một loại công văn, tờ trình từ cấp dưới lên cấp trên. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tờ trát, tờ trình", "Hạng Tần Suất (Jun Da)": "4111.0", "Tần Suất % (Jun Da)": "99.7760490948", "GavinGrover_Once (Chiết tự trực tiếp)": "片 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰片枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "片", "Unihan_Simplified (Chữ Giản thể)": "牒", "Unihan_Traditional (Chữ Phồn thể)": "牒", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại văn bản hành chính, hồ sơ hoặc gia phả thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赈', '{"9000": "4112.0", "Chữ Trung Quốc": "赈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 11 | nét | 赈 | chẩn | tượng hình | chữ giản thể của 賑, bộ Bối (贝) chỉ tiền tài; cứu trợ người nghèo | 赈 là giản thể của 賑. Bộ 贝/貝 (bối: tiền, tài sản) liên quan đến việc phân phát tài sản cứu trợ. Wiktionary ghi 赈 = {{Han simp|賑|f=貝|t=贝}} — giản hóa từ 賑 bằng cách thay 貝 thành 贝.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": bộ Bối (贝: tiền) dùng để cứu — 赈灾 là phát chẩn cứu trợ thiên tai, trao tiền và lương thực cho dân khổ. | Gương Hán-Việt | 赈灾 (chẩn tai) — cứu trợ thiên tai; 赈济 (chẩn tế) — cứu tế, phát chẩn | Mở khoá kiến thức | Biết 赈 (chẩn) mở khoá từ 赈灾 (chẩn tai: cứu trợ thiên tai), 赈济 (chẩn tế: cứu tế), 赈粮 (chẩn lương: gạo cứu trợ) dùng nhiều trong tin tức.", "Tự nguyên_Xie": "Tiểu triện | 赈 là giản thể của 賑 (phồn thể). Theo Wiktionary, 賑 = 貝 (biểu nghĩa: tiền, tài sản) + thành phần âm. Bộ bối (貝/贝) chỉ liên quan đến tài chính/tài sản. Tiểu triện có dạng 賑. Nghĩa gốc: giàu có; sau chuyển sang nghĩa cứu trợ, phát chẩn người đói nghèo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giàu; cấp giúp, phát chẩn", "Hạng Tần Suất (Jun Da)": "4112.0", "Tần Suất % (Jun Da)": "99.7763116216", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 辰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赈", "Unihan_Traditional (Chữ Phồn thể)": "賑", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đối tượng nghèo khổ hoặc vùng gặp thiên tai để chỉ việc phát lương thực cứu trợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煦', '{"9000": "4113.0", "Chữ Trung Quốc": "煦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 昫 | biểu âm | cho âm xù/hú | 灬 | biểu nghĩa | lửa (dạng biến thể của 火 ở dưới chữ) | 煦 = 昫 (biểu âm) + 灬 (dạng biến thể của 火: lửa, biểu nghĩa); chữ hình thanh. Lửa (灬) bên dưới gợi hơi ấm nhẹ nhàng; 昫 cho âm xù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hú\": lửa (灬) ấm áp từ dưới lên — 煦暖 là ấm áp dịu nhẹ, như nắng sớm mùa xuân. | Gương Hán-Việt | 和煦 (hòa hú) — ấm áp dịu nhẹ (thường dùng cho nắng, gió) | Mở khoá kiến thức | Biết 煦 (hú) mở khoá từ 和煦 (hòa hú: ấm áp dịu dàng), 煦暖 (hú noãn: ấm áp) trong thơ văn và mô tả thời tiết.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 煦 = 昫 (biểu âm) + 火/灬 (biểu nghĩa: lửa, hơi ấm), là chữ hình thanh. Nghĩa gốc: hơi ấm dịu, khí ấm; sau mở rộng sang nghĩa tử tế, nhân từ. Trong tiểu triện đã có dạng gần chữ hiện đại. Không thấy trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí ấm, hơi ấm", "Hạng Tần Suất (Jun Da)": "4113.0", "Tần Suất % (Jun Da)": "99.7765741484", "GavinGrover_Once (Chiết tự trực tiếp)": "昫 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱昫灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "煦", "Unihan_Traditional (Chữ Phồn thể)": "煦", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "hú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả thời tiết ấm áp hoặc làm động từ chỉ sự sưởi ấm, nuôi dưỡng sinh linh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗫', '{"9000": "4114.0", "Chữ Trung Quốc": "嗫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗫 | nhiếp | tượng hình | chữ có bộ Khẩu (口) chỉ miệng, giọng nói thì thầm | 嗫 có bộ 口 (khẩu: miệng) liên quan đến âm thanh từ miệng — nói thì thầm, hấp háy môi. Phần âm/cấu trúc bên dưới chưa xác định rõ. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiếp\": bộ Khẩu (口) mấp máy — 嗫嚅 là hấp háy môi nói không ra lời, như người nhiếp lấy dũng khí nhưng miệng vẫn không mở được. | Gương Hán-Việt | 嗫嚅 (nhiếp nhụ) — hấp háy môi, ấp úng không nói nên lời | Mở khoá kiến thức | Biết 嗫 (nhiếp) mở khoá từ 嗫嚅 (nhiếp nhụ: ấp úng, mấp máy môi không thốt ra lời) dùng trong văn học mô tả tâm lý.", "Tự nguyên_Xie": "Wiktionary ghi nhận 嗫 nghĩa: giọng nhỏ không rõ, hấp háy môi; cử động môi (chưa thốt ra thành tiếng). Bộ 口 (khẩu) chỉ liên quan đến miệng và giọng nói. Không thấy trong giáp cốt hay kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hấp háy môi", "Hạng Tần Suất (Jun Da)": "4114.0", "Tần Suất % (Jun Da)": "99.7768361585", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 聂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口聂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗫", "Unihan_Traditional (Chữ Phồn thể)": "囁", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "chiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng lặp lại thành dạng láy để làm động từ miêu tả điệu bộ ngập ngừng, muốn nói lại thôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耙', '{"9000": "4115.0", "Chữ Trung Quốc": "耙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 10 | nét | 耒 | lỗi | biểu nghĩa | nông cụ, cái cày | 巴 | ba | biểu âm | cho âm bà/ba | 耙 = 耒 (Lỗi, biểu nghĩa: nông cụ cày bừa) + 巴 (Ba, biểu âm); chữ hình thanh. Bộ lỗi (耒) chỉ đây là nông cụ; 巴 cho âm bà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bà\": bộ Lỗi (耒: nông cụ) + Ba (巴) — cái bừa (耙) nông dân kéo qua ruộng để san phẳng đất. | Gương Hán-Việt | 耙地 (bà địa) — bừa ruộng, san phẳng đất; 钉耙 (đinh bà) — cái bừa đinh | Mở khoá kiến thức | Biết 耙 (bà) mở khoá từ 耙地 (bà địa: bừa ruộng), 钉耙 (đinh bà: bừa đinh) và hình ảnh Trư Bát Giới cầm 钉耙 trong Tây Du Ký.", "Tự nguyên_Xie": "Theo Wiktionary, 耙 = 耒 (biểu nghĩa: nông cụ) + 巴 (biểu âm), là chữ hình thanh. Nghĩa: cái bừa (rake) — nông cụ dùng để phá vỡ đất cục và san phẳng mặt đất sau khi cày. Xuất hiện trong nông thư trung đại. Không thấy trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bừa 农具，用来碎土块和平地", "Hạng Tần Suất (Jun Da)": "4115.0", "Tần Suất % (Jun Da)": "99.7770976518", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耙", "Unihan_Traditional (Chữ Phồn thể)": "耙", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bà, bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ nông cụ làm đất hoặc làm động từ chỉ hành động bừa ruộng trong nông nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榕', '{"9000": "4116.0", "Chữ Trung Quốc": "榕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 容 | dung | biểu âm | cho âm róng/dung | 榕 = 木 (Mộc, biểu nghĩa: cây) + 容 (Dung, biểu âm); chữ hình thanh. Bộ mộc (木) chỉ đây là loài cây; 容 cho âm róng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": bộ Mộc (木: cây) mang âm Dung (容) — cây đa (榕) \"dung nạp\" tất cả: tán rộng bao trùm, rễ phụ rủ xuống khắp nơi. | Gương Hán-Việt | 榕树 (dung thụ) — cây đa; Phúc Châu biệt danh là 榕城 (Dung Thành) | Mở khoá kiến thức | Biết 榕 (dung) mở khoá từ 榕树 (dung thụ: cây đa) và 榕城 (Dung Thành: biệt danh Phúc Châu) — xuất hiện nhiều trong văn học và địa lý Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 榕 = 木 (biểu nghĩa: cây) + 容 (biểu âm), là chữ hình thanh. Nghĩa: cây đa (banyan tree). Cây đa có khả năng phát triển rễ phụ rủ xuống, tán rộng bao trùm. Cũng là biệt danh của thành phố Phúc Châu, tỉnh Phúc Kiến. Không thấy trong giáp cốt; xuất hiện trong thực vật chí trung đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây đa; Dung (tên khác của thành phố Phúc Châu, tỉnh Phúc Kiến, Trung Quốc); dung", "Hạng Tần Suất (Jun Da)": "4116.0", "Tần Suất % (Jun Da)": "99.7773586283", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榕", "Unihan_Traditional (Chữ Phồn thể)": "榕", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập để chỉ loài cây đa hoặc dùng trong tên gọi tắt của thành phố Phúc Châu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞑', '{"9000": "4117.0", "Chữ Trung Quốc": "鞑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 15 | nét | 鞑 | thát | tượng hình | chữ có bộ Cách (革) chỉ da thuộc; dùng trong tên dân tộc Thát Đát | 鞑 có bộ 革 (cách: da thuộc) liên quan đến người du mục sử dụng da thuộc. Phần âm/cấu trúc chưa xác định rõ. Chữ dùng chủ yếu trong từ 鞑靼 (Thát Đát). Wiktionary không có glyph origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thát\": bộ Cách (革: da) — người Thát Đát (鞑靼) là dân du mục thảo nguyên mặc da thú, trong lịch sử Trung Quốc được ghi là kẻ địch từ phương Bắc. | Gương Hán-Việt | 鞑靼 (thát đát) — người Tatars, dân tộc Thát Đát | Mở khoá kiến thức | Biết 鞑 (thát) mở khoá từ 鞑靼 (thát đát: Tatars) trong lịch sử, và 韃靼人 chỉ nhóm dân tộc gốc Mông-Thổ Nhĩ Kỳ ở Trung Á.", "Tự nguyên_Xie": "Wiktionary không có glyph origin cho 鞑. Chữ có bộ 革 (cách: da thuộc) — liên quan đến người du mục thảo nguyên. Dùng trong 鞑靼 (Tatars: người Thát Đát, dân tộc gốc Mông Cổ). Chữ tạo muộn để phiên âm tên dân tộc. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thát đát 韃靼,鞑靼)", "Hạng Tần Suất (Jun Da)": "4117.0", "Tần Suất % (Jun Da)": "99.7776196048", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 达", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革达", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "达", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞑", "Unihan_Traditional (Chữ Phồn thể)": "韃", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "thát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một bộ tộc du mục ở phía bắc Trung Quốc thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袤', '{"9000": "4118.0", "Chữ Trung Quốc": "袤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袤 | mậu | tượng hình | chữ có bộ Y (衣) — chiều dài theo hướng Nam Bắc; rộng dài | 袤 có bộ 衣 (y: quần áo) ẩn trong cấu trúc. Ý nghĩa chính: chiều dài theo hướng Nam Bắc (đối lập với 广/廣: chiều rộng theo hướng Đông Tây). Wiktionary không có glyph origin học thuật. chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": chiều dài mậu (袤) theo Nam Bắc — 广袤 là cả chiều ngang lẫn chiều dọc, nghĩa mênh mông bao la. | Gương Hán-Việt | 广袤 (quảng mậu) — rộng lớn mênh mông (quảng=ngang Đông-Tây, mậu=dọc Nam-Bắc) | Mở khoá kiến thức | Biết 袤 (mậu) mở khoá từ 广袤无垠 (quảng mậu vô ngân: rộng lớn không bờ bến) dùng mô tả đồng bằng, sa mạc, biển cả trong văn học.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có glyph origin chi tiết cho 袤. Nghĩa: rộng lớn; chiều dài theo hướng Nam Bắc (ngược lại với 广 chỉ chiều ngang). Tiểu triện có dạng gần chữ hiện đại. Dùng trong từ ghép 广袤 (quảng mậu: rộng lớn mênh mông). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rộng lớn; rộng về phương Nam Bắc (xem: quảng 廣)", "Hạng Tần Suất (Jun Da)": "4118.0", "Tần Suất % (Jun Da)": "99.7778795477", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 矛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣矛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "袤", "Unihan_Traditional (Chữ Phồn thể)": "袤", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ chiều dài nam bắc hoặc làm tính từ trong từ ghép chỉ sự rộng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谌', '{"9000": "4119.0", "Chữ Trung Quốc": "谌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 甚 | thậm | biểu âm | cho âm chén/thậm | 谌 = 言 (Ngôn, biểu nghĩa: lời nói) + 甚 (Thậm, biểu âm); chữ hình thanh. Bộ ngôn (言) chỉ liên quan đến lời nói/tín nghĩa; 甚 cho âm chén.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thầm\": bộ Ngôn (言: lời) + Thậm (甚: rất) — lời nói rất đáng tin (谌), sự thầm tín không lời hoa mỹ. | Gương Hán-Việt | 谌姓 (thầm tính) — họ Thầm; 可谌 (khả thầm) — đáng tin (văn ngôn) | Mở khoá kiến thức | Biết 谌 (thầm) mở khoá từ 谌姓 (họ Thầm) và dùng nhận ra chữ trong văn ngôn cổ điển nghĩa \"tin tưởng, thành thật\".", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 谌 = 言 (biểu nghĩa: lời nói) + 甚 (biểu âm), là chữ hình thanh. Nghĩa: tin tưởng, chân thành; cũng là họ người (họ Thầm). Kim văn và tiểu triện đã có dạng 諶. Nghĩa gốc trong văn ngôn: lời hứa đáng tin cậy, tin tưởng chắc chắn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tin tưởng", "Hạng Tần Suất (Jun Da)": "4119.0", "Tần Suất % (Jun Da)": "99.7781394906", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谌", "Unihan_Traditional (Chữ Phồn thể)": "諶", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "kham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ thể hiện sự thành thật hoặc làm động từ tin tưởng trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醺', '{"9000": "4120.0", "Chữ Trung Quốc": "醺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 21 | nét | 酉 | dậu | biểu nghĩa | bình rượu; bộ chỉ rượu | 熏 | huân | biểu âm | cho âm xūn/huân | 醺 = 酉 (Dậu, biểu nghĩa: rượu) + 熏 (Huân, biểu âm); chữ hình thanh. Bộ dậu (酉) chỉ liên quan đến rượu; 熏 cho âm xūn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": bộ Dậu (酉: rượu) + Huân (熏: hun khói) — say rượu (醺) như bị hun khói rượu, người ngây ngất huân huân. | Gương Hán-Việt | 醺醺 (huân huân) — ngà ngà say; 微醺 (vi huân) — hơi say, ngà ngà | Mở khoá kiến thức | Biết 醺 (huân) mở khoá từ 微醺 (vi huân: hơi say nhẹ, ngà ngà) và 醺醺大醉 (huân huân đại túy: say mèm) trong văn học và thơ ca.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 醺 = 酉 (biểu nghĩa: rượu) + 熏 (biểu âm), là chữ hình thanh. Nghĩa: say rượu, ngà ngà say. Tiểu triện có dạng gần chữ hiện đại. So sánh với 熏 (huân: hun khói) — cùng âm gốc, gợi hình ảnh khói rượu làm say. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "say rượu", "Hạng Tần Suất (Jun Da)": "4120.0", "Tần Suất % (Jun Da)": "99.7783994335", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 熏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉熏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醺", "Unihan_Traditional (Chữ Phồn thể)": "醺", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái say sưa hoặc động từ chỉ việc bị say do hơi rượu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秆', '{"9000": "4121.0", "Chữ Trung Quốc": "秆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 8 | nét | 秆 | cán | tượng hình | chữ giản thể của 稈, bộ Hòa (禾) chỉ cây lúa; thân cây lúa | 秆 là giản thể của 稈. Bộ 禾 (hòa: cây lúa) liên quan đến thân cây ngũ cốc. Wiktionary ghi 秆 = {{zh-see|稈}} — xem 稈. Tiểu triện và lưu thư thông có dạng 稈.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cán\": bộ Hòa (禾: cây lúa) — cán lúa (秆) là phần thân cây sau khi đã gặt hạt, tức rơm rạ khô. | Gương Hán-Việt | 稻秆 (đạo cán) — rơm rạ; 麦秆 (mạch cán) — rơm lúa mì; 秸秆 (giao cán) — thân cây ngũ cốc | Mở khoá kiến thức | Biết 秆 (cán) mở khoá từ 秸秆 (giao cán: rơm rạ, thân cây sau thu hoạch) dùng nhiều trong nông nghiệp và môi trường.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 秆 là giản thể của 稈. Theo Wiktionary, 稈 = 禾 (biểu nghĩa: cây lúa) + thành phần âm. Nghĩa: thân cây lúa, rơm rạ. Tiểu triện và lưu thư thông có dạng 稈. Thân cây lúa sau khi thu hoạch hạt được gọi là 秆/稈 (cán/rơm). chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuống lúa, thân cây lúa", "Hạng Tần Suất (Jun Da)": "4121.0", "Tần Suất % (Jun Da)": "99.7786588597", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秆", "Unihan_Traditional (Chữ Phồn thể)": "稈", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đứng độc lập hoặc làm yếu tố cấu tạo danh từ để chỉ thân cây của các loại cây lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徨', '{"9000": "4122.0", "Chữ Trung Quốc": "徨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 12 | nét | 徨 | hoàng | tượng hình | chữ có bộ Xích (彳) chỉ bước đi; do dự, lưỡng lự | 徨 có bộ 彳 (xích: bước đi nhỏ) liên quan đến hành động đi lại do dự. Phần âm/cấu trúc bên dưới chưa xác định rõ từ nguồn. Dùng chủ yếu trong từ 彷徨 (bàng hoàng). chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": bộ Xích (彳: bước đi) + Hoàng (黄/慌) — 彷徨 là bước đi bàng hoàng, lảo đảo do dự không biết đi đâu. | Gương Hán-Việt | 彷徨 (bàng hoàng) — do dự, lảo đảo, không biết định hướng | Mở khoá kiến thức | Biết 徨 (hoàng) mở khoá từ 彷徨 (bàng hoàng: do dự, không quyết định được) dùng trong văn học và mô tả tâm lý.", "Tự nguyên_Xie": "Wiktionary ghi nhận 徨 dùng trong 彷徨 (páng huáng: do dự, đi lại không yên). Bộ 彳 (xích: bước đi) chỉ hành động đi lại lưỡng lự. Không thấy trong giáp cốt văn; xuất hiện trong văn học Chiến Quốc. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bàng hoàng 彷徨)", "Hạng Tần Suất (Jun Da)": "4122.0", "Tần Suất % (Jun Da)": "99.778917769", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徨", "Unihan_Traditional (Chữ Phồn thể)": "徨", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp với chữ khác tạo thành tính từ hoặc động từ mô tả trạng thái bồn chồn, do dự. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橹', '{"9000": "4123.0", "Chữ Trung Quốc": "橹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 魯 | lỗ | biểu âm | cho âm lǔ/lỗ | 橹 = 木 (Mộc, biểu nghĩa: gỗ) + 魯 (Lỗ, biểu âm); chữ hình thanh. Bộ mộc (木) chỉ dụng cụ bằng gỗ; 魯 cho âm lǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": bộ Mộc (木: gỗ) mang âm Lỗ (魯) — cái mái chèo (橹) bằng gỗ đẩy con thuyền lướt sóng. | Gương Hán-Việt | 橹棹 (lỗ trạo) — mái chèo; 摇橹 (dao lỗ) — chèo thuyền | Mở khoá kiến thức | Biết 橹 (lỗ) mở khoá từ 摇橹 (dao lỗ: chèo thuyền bằng mái chèo) và 橹声 (lỗ thanh: tiếng mái chèo) trong thơ văn Giang Nam.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 橹 = 木 (biểu nghĩa: cây/gỗ) + 魯 (biểu âm), là chữ hình thanh. Nghĩa: mái chèo lớn (sculling oar); cũng có nghĩa cái mộc to (khiên, vũ khí phòng ngự thời cổ). Tiểu triện và lưu thư thông có dạng 櫓. Mái chèo làm từ gỗ để đẩy thuyền. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái mộc lớn; cái mái chèo", "Hạng Tần Suất (Jun Da)": "4123.0", "Tần Suất % (Jun Da)": "99.7791766784", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 鲁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木鲁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橹", "Unihan_Traditional (Chữ Phồn thể)": "㯭", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ dụng cụ chèo thuyền hoặc lá chắn lớn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翡', '{"9000": "4124.0", "Chữ Trung Quốc": "翡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 14 | nét | 翡 | phỉ | tượng hình | chim bói cá lông đỏ-xanh, từ đó chỉ ngọc phỉ thuý | 翡 là chữ tượng hình / dẫn xuất từ chữ 非 (phi) kết hợp với 羽 (vũ, lông chim). Không có nguồn phân tích hình thanh hoặc hội ý rõ ràng trong anchor; chữ này thường xuất hiện trong cụm 翡翠 (phỉ thuý).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": nhớ 翡 qua hình ảnh lông chim (羽-vũ) màu rực rỡ — đây chính là màu sắc của ngọc phỉ thuý quý báu. | Gương Hán-Việt | phỉ thuý (翡翠) — ngọc xanh lục quý giá | Mở khoá kiến thức | Biết 翡 mở khoá từ quan trọng nhất: 翡翠 (phỉ thuý) — loại ngọc/màu sắc xanh lục quen thuộc trong văn hoá Á Đông.", "Tự nguyên_Xie": "Tiểu triện | 翡 (phỉ): chữ Hán chỉ loài chim bói cá có lông màu đỏ-xanh đặc trưng, từ đó nghĩa mở rộng sang ngọc phỉ thuý quý giá. Anchor Wiktionary chỉ cung cấp {{Han etym}} mà không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật xác nhận cấu tạo hình thanh hay hội ý cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phí thuý 翡翠)", "Hạng Tần Suất (Jun Da)": "4124.0", "Tần Suất % (Jun Da)": "99.7794355877", "GavinGrover_Once (Chiết tự trực tiếp)": "非 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱非羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "非", "Unihan_Simplified (Chữ Giản thể)": "翡", "Unihan_Traditional (Chữ Phồn thể)": "翡", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loài chim lông xanh hoặc loại ngọc quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缨', '{"9000": "4125.0", "Chữ Trung Quốc": "缨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 缨 | anh | tượng hình | dải lụa đính vào mũ hoặc tua trang trí | 缨 là dạng giản thể của 纓, rút gọn từ 糹(纟) biểu nghĩa (sợi tơ) và 嬰(婴) biểu âm. Chữ hình thanh: bộ tơ sợi 纟 cho biết liên quan đến sợi vải, phần 婴 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": tơ lụa (纟) kết thành dải 缨 buộc dưới cằm — mũ quan ngày xưa luôn có dải 缨 để giữ mũ không rơi. | Gương Hán-Việt | anh (缨) — ít dùng độc lập trong tiếng Việt Hán-Việt hiện đại | Mở khoá kiến thức | Biết 缨 mở khoá các từ cổ điển về trang phục cung đình: 缨络 (anh lạc — tua trang trí), 缨帽 (mũ có dải).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缨 (anh) là giản thể của 纓. Theo Wiktionary, 纓 = 糹(biểu nghĩa: sợi tơ/vải) + 嬰(biểu âm). Chữ hình thanh, chỉ dải lụa hoặc dây đính vào mũ quan, cũng dùng chỉ tua trang trí. Dạng cổ thấy trong tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dải mũ", "Hạng Tần Suất (Jun Da)": "4125.0", "Tần Suất % (Jun Da)": "99.7796939803", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 婴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟婴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缨", "Unihan_Traditional (Chữ Phồn thể)": "纓", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ dây mũ hoặc tua rua trang trí trên mũ, giáo mác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锹', '{"9000": "4126.0", "Chữ Trung Quốc": "锹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 秋 | thu | biểu âm | 锹 = 金 (Kim, biểu nghĩa: kim loại) + 秋 (Thu, biểu âm); chữ hình thanh. Bộ kim 金 cho biết đây là dụng cụ bằng kim loại; phần 秋 cho âm gần với qiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; nhớ 锹 = kim loại (金) + thu hoạch (秋) → cái xẻng dùng để đào đất thu hoạch mùa màng. | Gương Hán-Việt | tiều (锹) — ít dùng trong tiếng Việt Hán-Việt | Mở khoá kiến thức | Biết 锹 mở khoá: 铁锹 (tiết tiều — xẻng sắt), 圆锹 (xẻng tròn) — các từ về nông cụ.", "Tự nguyên_Xie": "锹 (dạng cổ 鍬/鍫) là chữ hình thanh: 金 (biểu nghĩa — kim loại) + 秋 (biểu âm). Wiktionary ghi rõ: {{Han compound|金|t1=metal|秋|ls=psc}} — cái xẻng bằng kim loại. Đây là dụng cụ đào đất quen thuộc trong nông nghiệp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xẻng; đào", "Hạng Tần Suất (Jun Da)": "4126.0", "Tần Suất % (Jun Da)": "99.7799518561", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锹", "Unihan_Traditional (Chữ Phồn thể)": "鍫", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "thiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nông cụ đào đất hoặc làm động từ chỉ hành động xúc, đào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵇', '{"9000": "4127.0", "Chữ Trung Quốc": "嵇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 嵇 | kê | tượng hình | tên núi ở Hà Nam; họ người nổi tiếng trong lịch sử Trung Quốc | 嵇 không có phân tích cấu tạo từ anchor. Đây là chữ chủ yếu dùng làm địa danh (núi Kê) và họ người (Kê Khang — nhạc sĩ danh tiếng thời Tam Quốc). Chưa có nguồn học thuật xác nhận cấu tạo. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kê\": nhớ 嵇 qua Kê Khang (嵇康) — nhạc sĩ thiên tài thời Tam Quốc, chơi đàn cầm trước khi bị hành hình, tên họ gắn với núi Kê. | Gương Hán-Việt | kê (嵇) — chủ yếu trong họ người: Kê Khang (嵇康) | Mở khoá kiến thức | Biết 嵇 mở khoá tên riêng lịch sử: 嵇康 (Kê Khang) — một trong Trúc Lâm Thất Hiền nổi tiếng.", "Tự nguyên_Xie": "Tiểu triện | 嵇 (kê): chữ dùng chủ yếu cho địa danh — núi Kê ở Hà Nam — và họ người, nổi tiếng nhất là Kê Khang (嵇康, 223–262), nhạc sĩ và triết gia thời Tam Quốc. Anchor không có phân tích hình thanh hay hội ý. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "4127.0", "Tần Suất % (Jun Da)": "99.7802092151", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "嵇", "Unihan_Traditional (Chữ Phồn thể)": "嵇", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ tên núi cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圪', '{"9000": "4128.0", "Chữ Trung Quốc": "圪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất, đất cát | 乞 | khất | biểu âm | 圪 = 土 (Thổ, biểu nghĩa: đất) + 乞 (Khất, biểu âm); chữ hình thanh. Bộ thổ 土 gợi liên quan đến đất đai; phần 乞 cho âm gē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; nhớ 圪 = đất (土) + xin (乞) → cục đất nhỏ như người hành khất ngồi trên đất, dùng trong từ láy 圪塔 (cục nhỏ). | Gương Hán-Việt | ngật (圪) — không dùng độc lập trong Hán-Việt | Mở khoá kiến thức | Biết 圪 mở khoá các từ láy phương ngữ Bắc Kinh: 圪塔 (cục nhỏ), 圪节 (khớp nối nhỏ).", "Tự nguyên_Xie": "Tiểu triện | 圪 (gē) là chữ hình thanh theo Wiktionary: 土 (biểu nghĩa — đất) + 乞 (biểu âm). Chữ chủ yếu dùng trong các từ láy âm phương ngữ Bắc Kinh như 圪塔 (gētǎ — cục đất nhỏ), thường xuất hiện trong văn nói miền Bắc Trung Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khất đáp 圪塔)", "Hạng Tần Suất (Jun Da)": "4128.0", "Tần Suất % (Jun Da)": "99.7804660573", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圪", "Unihan_Traditional (Chữ Phồn thể)": "圪", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "khất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Danh từ | 名词 | Thường dùng làm tiền tố hoặc trợ từ trong phương ngôn miền Bắc Trung Quốc để cấu tạo từ. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髻', '{"9000": "4129.0", "Chữ Trung Quốc": "髻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 16 | nét | 髟 | biểu nghĩa | tóc dài | 吉 | cát | biểu âm | 髻 = 髟 (biểu nghĩa: tóc dài, bộ thủ) + 吉 (Cát, biểu âm); chữ hình thanh. Bộ 髟 cho biết liên quan đến tóc; phần 吉 cho âm jì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kế\": tóc dài (髟) búi lên thành nút cát tường (吉) — 髻 là búi tóc gọn gàng trên đỉnh đầu, biểu tượng của sự chỉnh tề trong lễ giáo. | Gương Hán-Việt | kế (髻) — trong từ Hán-Việt: 发髻 (phát kế — búi tóc) | Mở khoá kiến thức | Biết 髻 mở khoá: 发髻 (phát kế — búi tóc), 椎髻 (búi tóc búa), 双髻 (hai búi tóc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 髻 (kế) là chữ hình thanh theo Wiktionary: 髟 (biểu nghĩa — tóc dài) + 吉 (biểu âm). Chỉ kiểu búi tóc truyền thống được chải lên và buộc gọn trên đỉnh đầu hoặc sau gáy, phổ biến trong văn hoá Hán cổ đại cho cả nam lẫn nữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "búi tóc", "Hạng Tần Suất (Jun Da)": "4129.0", "Tần Suất % (Jun Da)": "99.7807213492", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髻", "Unihan_Traditional (Chữ Phồn thể)": "髻", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kế, kết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ búi tóc của phụ nữ thời cổ hoặc kiểu tóc búi cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗬', '{"9000": "4130.0", "Chữ Trung Quốc": "嗬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗬 | hô | tượng hình | thán từ biểu thị ngạc nhiên, thường viết bằng miệng 口 | 嗬 không có phân tích cấu tạo từ anchor. Chữ này hầu như chắc chắn gồm bộ 口 (khẩu — miệng) kết hợp phần biểu âm, nhưng nguồn Wiktionary không xác nhận. Dùng làm thán từ biểu thị ngạc nhiên. Chưa có nguồn học thuật xác nhận cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hô\": miệng (口) kêu lên \"hô!\" — 嗬 là âm thanh thoát ra từ miệng khi ngạc nhiên bất ngờ, giống như tiếng \"ô!\" trong tiếng Việt. | Gương Hán-Việt | hô (嗬) — ít dùng trong Hán-Việt chính thức | Mở khoá kiến thức | Biết 嗬 giúp đọc hiểu văn học cổ điển và tiểu thuyết Trung Quốc khi gặp thán từ biểu thị ngạc nhiên.", "Tự nguyên_Xie": "嗬 (hô) là thán từ miệng (có bộ 口). Anchor không có phân tích cấu tạo; Wiktionary không có mục từ riêng cho 嗬. Chữ tạo muộn, chủ yếu dùng trong văn nói/văn học để ghi âm tiếng kêu ngạc nhiên. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ô; ơ; ôi (thán từ biểu thị sự ngạc nhiên)", "Hạng Tần Suất (Jun Da)": "4130.0", "Tần Suất % (Jun Da)": "99.7809761242", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 荷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口荷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗬", "Unihan_Traditional (Chữ Phồn thể)": "嗬", "Pinyin_Xie": "hē", "Âm Hán Việt_Xie": "ha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng đầu câu làm thán từ để biểu thị sự ngạc nhiên. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辎', '{"9000": "4131.0", "Chữ Trung Quốc": "辎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 辎 | tư | tượng hình | xe có mui che dùng chở đồ quân nhu | 辎 là giản thể của 輜. Anchor không cung cấp phân tích hình thanh/hội ý chi tiết từ Wiktionary. Chữ gốc 輜 có bộ 車 (xa — xe) cho biết liên quan đến xe cộ. Cấu tạo đầy đủ chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": 辎 là xe (bộ 車/辶) chở đồ quân tư lương — hình ảnh đoàn xe chở lương thực theo sau đội quân trong chiến dịch. | Gương Hán-Việt | tư (辎) — trong từ Hán-Việt: 辎重 (tư trọng — quân nhu, hành lý nặng của quân đội) | Mở khoá kiến thức | Biết 辎 mở khoá: 辎重 (tư trọng — quân nhu/hành lý quân sự), 辎车 (xe chở đồ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 辎 (tư), dạng cổ 輜: xe có mui che dùng trong quân đội để chở quân nhu, lương thực. Anchor ghi usedForm là 輜 nhưng Wiktionary không phân tích cấu tạo chi tiết, chỉ có các định nghĩa. Chữ có bộ 車 (xe). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe chở đồ", "Hạng Tần Suất (Jun Da)": "4131.0", "Tần Suất % (Jun Da)": "99.7812303825", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 甾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车甾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辎", "Unihan_Traditional (Chữ Phồn thể)": "輜", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "truy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ hành lý hoặc xe quân sự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痣', '{"9000": "4132.0", "Chữ Trung Quốc": "痣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | biểu nghĩa | bệnh tật | 志 | chí | biểu âm | 痣 = 疒 (bộ thủ bệnh tật, biểu nghĩa) + 志 (Chí, biểu âm); chữ hình thanh. Bộ 疒 cho biết liên quan đến tình trạng da/bệnh; phần 志 cho âm zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": bệnh da (疒) có chí khí riêng (志) — 痣 là nốt ruồi hay vết bớt bẩm sinh, mỗi nốt ruồi như một \"dấu ấn\" trên cơ thể. | Gương Hán-Việt | chí (痣) — trong y học cổ: 黑痣 (hắc chí — nốt ruồi đen) | Mở khoá kiến thức | Biết 痣 mở khoá: 黑痣 (hắc chí — nốt ruồi đen), 胎痣 (thai chí — vết bớt bẩm sinh), 硃砂痣 (chu sa chí — nốt ruồi đỏ son).", "Tự nguyên_Xie": "痣 (chí) là chữ hình thanh theo Wiktionary: 疒 (biểu nghĩa — bệnh tật, tình trạng da) + 志 (biểu âm). Chỉ các điểm sắc tố trên da như nốt ruồi, vết bớt, tàn nhang. Các từ đồng nghĩa tiếng Quảng ghi là 癦. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt mụn cơm, nốt ruồi", "Hạng Tần Suất (Jun Da)": "4132.0", "Tần Suất % (Jun Da)": "99.7814846408", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 志", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒志", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "志", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痣", "Unihan_Traditional (Chữ Phồn thể)": "痣", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ nốt ruồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娩', '{"9000": "4133.0", "Chữ Trung Quốc": "娩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 娩 | miễn | tượng hình | sinh con; dáng dịu dàng | 娩 không có phân tích hình thanh/hội ý rõ ràng từ anchor Wiktionary. Chữ có bộ 女 (nữ — phụ nữ), nghĩa chính là sinh con (miǎn) và nghĩa phụ là dịu dàng (wǎn). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miễn\": người phụ nữ (女) vượt cạn — 娩 chỉ việc sinh nở, âm miễn/miǎn gợi cảm giác vất vả nhưng cũng giảm nhẹ (免 — giải phóng). | Gương Hán-Việt | miễn (娩) — trong y học: 分娩 (phân miễn — sinh nở, đẻ) | Mở khoá kiến thức | Biết 娩 mở khoá: 分娩 (phân miễn — sinh nở), 娩出 (miễn xuất — đẻ ra).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 娩 (miễn/miǎn): chữ có bộ 女 liên quan đến phụ nữ. Wiktionary ghi nhiều âm đọc: miǎn (sinh con), wǎn (dịu dàng), wàn/fàn (sinh sản). Anchor ghi thấy hình trong giáp cốt văn và tiểu triện. Cấu tạo chi tiết không được phân tích trong Wiktionary. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: uyển vãn 婉娩)", "Hạng Tần Suất (Jun Da)": "4133.0", "Tần Suất % (Jun Da)": "99.7817383823", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娩", "Unihan_Traditional (Chữ Phồn thể)": "娩", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "vãn, miễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp làm động từ chỉ việc sinh nở của phụ nữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谄', '{"9000": "4134.0", "Chữ Trung Quốc": "谄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 谄 | siểm | tượng hình | nịnh nọt, bộ 讠(言) gợi lời nói hoa mỹ giả tạo | 谄 là giản thể của 諂: 訁(讠) biểu nghĩa (lời nói) + phần biểu âm. Chữ hình thanh liên quan đến ngôn ngữ (bộ 言/讠), chỉ hành vi dùng lời lẽ ngọt ngào để nịnh bợ người trên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"siểm\": lời nói (讠) uốn éo siểm mị — 谄 là nịnh nọt, dùng lời nói để lấy lòng, hình ảnh chiếc lưỡi mềm mại không trung thực. | Gương Hán-Việt | siểm (谄) — trong Hán-Việt: 谄媚 (siểm mị — nịnh nọt), 谄笑 (siểm tiếu — cười nịnh) | Mở khoá kiến thức | Biết 谄 mở khoá: 谄媚 (siểm mị — nịnh hót), 谄笑 (cười nịnh), 阿谄 (a siểm — xu nịnh).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 谄 (siểm), dạng cổ 諂: giản thể từ 訁→讠 (biểu nghĩa — lời nói) với phần còn lại biểu âm. Chữ hình thanh chỉ hành vi nịnh hót, dùng lời ngon ngọt để lấy lòng người có quyền thế. Thấy hình trong đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nịnh nọt", "Hạng Tần Suất (Jun Da)": "4134.0", "Tần Suất % (Jun Da)": "99.7819921238", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 臽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠臽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谄", "Unihan_Traditional (Chữ Phồn thể)": "諂", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "siểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành vi nịnh bợ kẻ mạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛐', '{"9000": "4135.0", "Chữ Trung Quốc": "蛐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛐 | khúc | tượng hình | con dế; có bộ 虫 chỉ côn trùng | 蛐 không có phân tích cấu tạo từ anchor. Chữ chứa bộ 虫 (trùng — sâu bọ, côn trùng) và dùng chủ yếu trong từ 蛐蛐 (qūqu — con dế). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khúc\": con sâu (虫) kêu khúc khắc trong đêm — 蛐 (dùng trong 蛐蛐) là con dế, loài côn trùng nổi tiếng kêu đêm hè trong văn học Trung Quốc. | Gương Hán-Việt | khúc (蛐) — ít dùng độc lập trong Hán-Việt | Mở khoá kiến thức | Biết 蛐 mở khoá: 蛐蛐 (qūqu — con dế), 蛐蟮 (giun đất, phương ngữ).", "Tự nguyên_Xie": "蛐 (khúc): chữ chủ yếu dùng trong từ láy 蛐蛐 (qūqu) chỉ con dế. Anchor không có phân tích cấu tạo; Wiktionary không có mục từ riêng. Chứa bộ 虫 chỉ côn trùng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con dế", "Hạng Tần Suất (Jun Da)": "4135.0", "Tần Suất % (Jun Da)": "99.7822458653", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 曲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫曲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛐", "Unihan_Traditional (Chữ Phồn thể)": "蛐", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ chỉ con dế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹞', '{"9000": "4136.0", "Chữ Trung Quốc": "鹞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 䍃 | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鹞 = 䍃 (biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ điểu 鳥/鸟 cho biết đây là loài chim; phần 䍃 cho âm yào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; nhớ 鹞 = con chim (鳥) bay nhanh — đây là diều hâu nhỏ, từ này đã được vay mượn vào tiếng Việt thành \"diều\" (con diều hâu/diều giấy). | Gương Hán-Việt | diêu (鹞) — trong Hán-Việt: 鹞鹰 (diêu ưng — chim điêu ưng) | Mở khoá kiến thức | Biết 鹞 giúp hiểu nguồn gốc từ \"diều\" trong tiếng Việt — vay mượn trực tiếp từ 鷂 qua đường Hán-Việt.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 鹞 (dạng cổ 鷂) là chữ hình thanh theo Wiktionary: 䍃 (biểu âm) + 鳥 (biểu nghĩa — chim). Chỉ loài chim ưng nhỏ (diều hâu, chim điêu). Từ này còn được vay mượn sang tiếng Việt: diều (鷂→diều). Thấy hình trong đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "diều mướp, diều hâu, chim diêu", "Hạng Tần Suất (Jun Da)": "4136.0", "Tần Suất % (Jun Da)": "99.78249909", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鹞", "Unihan_Traditional (Chữ Phồn thể)": "鷂", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài chim săn mồi hoặc dùng trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翱', '{"9000": "4137.0", "Chữ Trung Quốc": "翱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 16 | nét | 翱 | ngao | tượng hình | bay lượn, dang rộng cánh; bộ 羽 gợi đôi cánh | 翱 không có phân tích cấu tạo chi tiết từ anchor. Chữ chứa bộ 羽 (vũ — lông/cánh chim), chỉ hành động bay lượn nhẹ nhàng, thường dùng trong 翱翔 (ngao tường — bay lượn tự do). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": cánh (羽) dang rộng ngao du — 翱 gợi hình ảnh con chim dang rộng đôi cánh lướt nhẹ trên cao, không vỗ cánh mà chỉ lướt theo gió. | Gương Hán-Việt | ngao (翱) — trong Hán-Việt: 翱翔 (ngao tường — bay lượn tự do) | Mở khoá kiến thức | Biết 翱 mở khoá: 翱翔 (ngao tường — bay lượn thư thái), cụm thường dùng trong thơ ca và ẩn dụ về tự do.", "Tự nguyên_Xie": "Lục thư thông | 翱 (ngao): chữ có bộ 羽 (lông chim, đôi cánh). Anchor Wiktionary chỉ có thông tin phát âm và định nghĩa: \"to spread wings and fly\". Không có phân tích hình thanh/hội ý. Thấy hình trong lục thư thông (Lưu Thư Thông). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liệng; lượn; bay lượn", "Hạng Tần Suất (Jun Da)": "4137.0", "Tần Suất % (Jun Da)": "99.7827517979", "GavinGrover_Once (Chiết tự trực tiếp)": "皋 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰皋羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翱", "Unihan_Traditional (Chữ Phồn thể)": "翱", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với chữ tường để chỉ hành động bay lượn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庖', '{"9000": "4138.0", "Chữ Trung Quốc": "庖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 8 | nét | 广 | nghiễm | biểu nghĩa | ngôi nhà, mái nhà | 包 | bao | biểu âm | 庖 = 广 (Nghiễm, biểu nghĩa: nhà) + 包 (Bao, biểu âm); chữ hình thanh. Bộ 广 cho biết đây là một không gian trong nhà; phần 包 cho âm páo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": ngôi nhà (广) chứa đồ bao bọc (包) — 庖 là gian bếp, nơi \"bao bọc\" và chế biến thực phẩm; nổi tiếng qua Bào Đinh (庖丁) trong Trang Tử. | Gương Hán-Việt | bào (庖) — trong Hán-Việt: 庖厨 (bào trù — gian bếp), 越俎代庖 (vượt trở đại bào — làm thay việc người khác) | Mở khoá kiến thức | Biết 庖 mở khoá: 庖丁 (Bào Đinh — người đầu bếp trong Trang Tử), 越俎代庖 (thành ngữ về làm việc người khác).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 庖 (bào) là chữ hình thanh theo Wiktionary: 广 (biểu nghĩa — ngôi nhà) + 包 (biểu âm). Chỉ gian bếp trong nhà (văn ngôn), hoặc người đầu bếp. Nổi tiếng qua thành ngữ 庖丁解牛 (Bào Đinh giải ngưu — người đầu bếp mổ trâu, ẩn dụ về kỹ năng điêu luyện) trong Trang Tử. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bếp", "Hạng Tần Suất (Jun Da)": "4138.0", "Tần Suất % (Jun Da)": "99.7830039891", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庖", "Unihan_Traditional (Chữ Phồn thể)": "庖", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn viết cổ để chỉ nhà bếp hoặc đầu bếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籁', '{"9000": "4139.0", "Chữ Trung Quốc": "籁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 籁 | lại | tượng hình | loại sáo tre cổ; âm thanh thiên nhiên; bộ 竹 gợi nhạc cụ bằng tre | 籁 không có phân tích hình thanh/hội ý chi tiết từ anchor. Chữ chứa bộ 竹 (trúc — tre), chỉ loại nhạc cụ hơi cổ đại làm bằng tre, và rộng nghĩa hơn là mọi âm thanh trong thiên nhiên. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": tre (竹) tạo ra mọi âm thanh lại — 籁 là tiếng sáo tre, rồi mở rộng thành mọi âm thanh thiên nhiên; 万籁俱寂 là khi cả vũ trụ im lặng. | Gương Hán-Việt | lại (籁) — trong Hán-Việt: 万籁 (vạn lại — muôn âm thanh), 天籁 (thiên lại — tiếng trời, âm thanh thiên nhiên) | Mở khoá kiến thức | Biết 籁 mở khoá: 天籁 (thiên lại — tiếng thiên nhiên), 万籁俱寂 (vạn lại câu tịch — im lặng hoàn toàn).", "Tự nguyên_Xie": "Tiểu triện | 籁 (lại), dạng cổ 籟: nhạc cụ hơi cổ đại làm bằng ống tre. Wiktionary ghi các định nghĩa: cây sáo cổ bằng tre, đồng nghĩa với 簫 (tiêu), và nghĩa chuyển là âm thanh/tiếng động. Chữ có bộ 竹. Nổi tiếng qua thành ngữ 万籁俱寂 (vạn lại câu tịch — mọi âm thanh đều im lặng). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tiêu", "Hạng Tần Suất (Jun Da)": "4139.0", "Tần Suất % (Jun Da)": "99.7832556635", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 赖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮赖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籁", "Unihan_Traditional (Chữ Phồn thể)": "籟", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lãi, lại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ âm thanh tự nhiên trong các cụm từ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓿', '{"9000": "4140.0", "Chữ Trung Quốc": "蓿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 宿 | túc | biểu âm | 蓿 = 艸/艹 (Tháu, biểu nghĩa: cỏ/thực vật) + 宿 (Túc, biểu âm); chữ hình thanh. Bộ 艹 cho biết đây là thực vật; phần 宿 cho âm gần với sù/xu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": cỏ (艹) ngủ lại (宿) — 蓿 chỉ cây cỏ linh lăng trong 苜蓿 (mục túc), loài cỏ du nhập từ Trung Á theo con đường tơ lụa nuôi ngựa chiến. | Gương Hán-Việt | túc (蓿) — chủ yếu trong từ: 苜蓿 (mục túc — cỏ linh lăng/alfalfa) | Mở khoá kiến thức | Biết 蓿 mở khoá: 苜蓿 (mục túc — alfalfa/cỏ linh lăng), một từ quan trọng trong lịch sử nông nghiệp và con đường tơ lụa.", "Tự nguyên_Xie": "蓿 là chữ hình thanh theo Wiktionary: 艸 (biểu nghĩa — cỏ) + 宿 (biểu âm). Chữ chỉ dùng trong từ 苜蓿 (mục túc — cây cỏ linh lăng/alfalfa, Medicago), một loài cây thức ăn gia súc quan trọng được truyền vào Trung Quốc từ Trung Á theo con đường tơ lụa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mục túc 苜蓿)", "Hạng Tần Suất (Jun Da)": "4140.0", "Tần Suất % (Jun Da)": "99.783506821", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 宿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹宿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓿", "Unihan_Traditional (Chữ Phồn thể)": "蓿", "Pinyin_Xie": "xu", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đi kèm với chữ mục để tạo thành danh từ chỉ loài cỏ chăn nuôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳗', '{"9000": "4141.0", "Chữ Trung Quốc": "鳗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳗 | man | tượng hình | con lươn biển; bộ 鱼 chỉ loài cá/thuỷ sản | 鳗 là giản thể của 鰻: 魚(鱼) biểu nghĩa (cá) + 曼 biểu âm. Chữ hình thanh chỉ con lươn/cá chình. Giản thể chỉ đổi 魚→鱼.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": cá (鱼) dài mướt mán — 鳗 là con lươn/cá chình, loài cá dài trơn trượt nổi tiếng trong ẩm thực Đông Á, đặc biệt là cơm lươn Nhật Bản. | Gương Hán-Việt | man (鳗) — trong Hán-Việt: 鳗鲡 (man ly — cá chình, lươn biển) | Mở khoá kiến thức | Biết 鳗 mở khoá: 鳗鱼 (man ngư — cá chình/lươn), 海鳗 (hải man — lươn biển).", "Tự nguyên_Xie": "鳗 (man), dạng cổ 鰻: giản thể của 鰻, chỉ đổi bộ 魚→鱼. Cấu tạo: 魚 (biểu nghĩa — cá) + 曼 (biểu âm). Chỉ con lươn biển (cá chình, eel). Phổ biến trong ẩm thực Nhật Bản (unagi) và Trung Quốc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: man ly 鰻鱺,鳗鲡)", "Hạng Tần Suất (Jun Da)": "4141.0", "Tần Suất % (Jun Da)": "99.7837579786", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳗", "Unihan_Traditional (Chữ Phồn thể)": "鰻", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loài cá chình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疟', '{"9000": "4142.0", "Chữ Trung Quốc": "疟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 8 | nét | 疟 | ngược | tượng hình | bệnh sốt rét; bộ 疒 chỉ bệnh tật | 疟 là giản thể của 瘧: bỏ bộ 虍 (hổ), giữ lại phần còn lại. Dạng cổ 瘧 = 疒 (biểu nghĩa — bệnh) + 虐 (biểu âm). Chữ hình thanh chỉ bệnh sốt rét, có lúc nóng lúc lạnh theo chu kỳ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngược\": bệnh (疒) ngược đãi cơ thể — 疟 là sốt rét, căn bệnh tàn bạo (ngược) khiến người bệnh lúc nóng lúc lạnh như bị hành hạ. | Gương Hán-Việt | ngược (疟) — trong y học Hán-Việt: 疟疾 (ngược tật — bệnh sốt rét) | Mở khoá kiến thức | Biết 疟 mở khoá: 疟疾 (ngược tật — malaria), 疟原虫 (ký sinh trùng sốt rét).", "Tự nguyên_Xie": "Tiểu triện | 疟 (ngược), dạng cổ 瘧: giản thể từ 瘧, bỏ bộ 虍. Dạng cổ: 疒 (biểu nghĩa — bệnh) + 虐 (biểu âm). Chỉ bệnh sốt rét (malaria) — bệnh có chu kỳ lên cơn nóng lạnh. Thấy hình trong tiểu triện. Đây là bệnh phổ biến trong lịch sử Trung Quốc cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh sốt rét", "Hạng Tần Suất (Jun Da)": "4142.0", "Tần Suất % (Jun Da)": "99.7840086194", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "疟", "Unihan_Traditional (Chữ Phồn thể)": "瘧", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "ngược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ bệnh sốt rét hoặc triệu chứng phát sốt phát rét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲇', '{"9000": "4143.0", "Chữ Trung Quốc": "鲇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 魚 | ngư | biểu nghĩa | cá | 占 | chiêm | biểu âm | 鲇 = 魚/鱼 (Ngư, biểu nghĩa: cá) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ ngư 鱼 cho biết đây là loài cá; phần 占 cho âm nián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niêm\": cá (鱼) chiêm bẩm (占) — 鲇 là cá trê/cá nheo, loài cá có ria mép dài như râu kẻ chiêm bẩm, sống dưới đáy bùn sông hồ. | Gương Hán-Việt | niêm (鲇) — trong Hán-Việt: 鲇鱼 (niêm ngư — cá trê) | Mở khoá kiến thức | Biết 鲇 mở khoá: 鲇鱼效应 (hiệu ứng cá trê — cạnh tranh kích thích phát triển), 鲇鱼上竹竿 (cá trê leo tre — việc không thể).", "Tự nguyên_Xie": "Tiểu triện | 鲇 (niêm/nián), dạng cổ 鮎: 魚 (biểu nghĩa — cá) + 占 (biểu âm). Chỉ loài cá trê (catfish), đặc biệt là loài Silurus asotus phổ biến ở vùng sông hồ Đông Á. Wiktionary ghi chú dạng 鯰 được dùng phổ biến hơn trong thực tế dù 鮎/鲇 là tiêu chuẩn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá măng, cá ngát, cá nheo, cá niêm", "Hạng Tần Suất (Jun Da)": "4143.0", "Tần Suất % (Jun Da)": "99.7842587434", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲇", "Unihan_Traditional (Chữ Phồn thể)": "鮎", "Pinyin_Xie": "nián", "Âm Hán Việt_Xie": "niêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài cá da trơn nước ngọt như cá nheo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚅', '{"9000": "4144.0", "Chữ Trung Quốc": "嚅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 17 | nét | 嚅 | nheo | tượng hình | nói luyên thuyên, ấp a ấp úng; bộ 口 gợi miệng nói | 嚅 không có phân tích hình thanh/hội ý chi tiết từ anchor. Chữ chứa bộ 口 (khẩu — miệng), dùng chủ yếu trong 囁嚅 (thiếp nheo — ấp úng, nói không rõ lời). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nheo\": miệng (口) nói nheo nhẹo không rõ — 嚅 dùng trong 囁嚅 (ấp úng), hình ảnh người vừa run sợ vừa cố nói mà không ra lời. | Gương Hán-Việt | nheo (嚅) — trong Hán-Việt: 囁嚅 (thiếp nheo — ấp úng, không nói rõ lời) | Mở khoá kiến thức | Biết 嚅 mở khoá: 囁嚅 (thiếp nheo — ấp úng), 嚅动 (nheo động — cử động môi nói nhỏ).", "Tự nguyên_Xie": "嚅 (nheo/rú): chữ có bộ 口 (miệng). Wiktionary chỉ có thông tin phát âm và định nghĩa: dùng trong tổ hợp 囁嚅. Không có phân tích hình thanh/hội ý. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói luyên thuyên", "Hạng Tần Suất (Jun Da)": "4144.0", "Tần Suất % (Jun Da)": "99.7847574411", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚅", "Unihan_Traditional (Chữ Phồn thể)": "嚅", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp thành từ ghép để tả điệu bộ muốn nói lại thôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘀', '{"9000": "4145.0", "Chữ Trung Quốc": "瘀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 疒 | biểu nghĩa | bệnh tật | 於 | ư | biểu âm | 瘀 = 疒 (bộ thủ bệnh tật, biểu nghĩa) + 於 (Ư, biểu âm); chữ hình thanh. Bộ 疒 cho biết liên quan đến bệnh/chấn thương; phần 於 cho âm yū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ứ\": bệnh (疒) ở (於) lại trong cơ thể — 瘀 là máu ứ đọng, như nước ứ không chảy được, gây bầm tím và đau nhức. | Gương Hán-Việt | ứ (瘀) — trong y học: 瘀血 (ứ huyết — máu ứ đọng), 瘀青 (bầm tím) | Mở khoá kiến thức | Biết 瘀 mở khoá: 瘀血 (ứ huyết — máu ứ đọng), 活血化瘀 (hoạt huyết hoá ứ — làm tan ứ huyết trong y học cổ truyền).", "Tự nguyên_Xie": "Tiểu triện | 瘀 (ứ/yū) là chữ hình thanh theo Wiktionary: 疒 (biểu nghĩa — bệnh tật) + 於 (biểu âm). Chỉ máu ứ đọng (hematoma, bầm tím) do chấn thương hoặc tuần hoàn kém. Khái niệm quan trọng trong y học cổ truyền Trung Quốc: 瘀血 (ứ huyết). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "máu đọng, máu ứ", "Hạng Tần Suất (Jun Da)": "4145.0", "Tần Suất % (Jun Da)": "99.7850065315", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 於", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒於", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "於", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘀", "Unihan_Traditional (Chữ Phồn thể)": "瘀", "Pinyin_Xie": "yū", "Âm Hán Việt_Xie": "ứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ vết máu bầm hoặc làm động từ chỉ sự ứ đọng dòng chảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颔', '{"9000": "4146.0", "Chữ Trung Quốc": "颔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 含 | hàm | biểu âm | 頁 | biểu nghĩa | đầu, phần đầu | 颔 = 含 (Hàm, biểu âm) + 頁 (biểu nghĩa: đầu/phần đầu); chữ hình thanh. Bộ 頁 cho biết liên quan đến đầu/khuôn mặt; phần 含 cho âm hàn/hàng gần với hàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãm\": đầu (頁) chứa (含) trong phần dưới — 颔 là cái cằm, phần \"chứa đựng\" của khuôn mặt nằm dưới cùng; khi gật đầu, cằm (颔) cúi xuống. | Gương Hán-Việt | hãm (颔) — trong Hán-Việt: 颔首 (hãm thủ — gật đầu), 双颔 (song hãm — hai quai hàm) | Mở khoá kiến thức | Biết 颔 mở khoá: 颔首 (hãm thủ — gật đầu đồng ý), 颔联 (hãm liên — câu 3-4 trong thất ngôn tứ tuyệt).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 颔 (hãm/hàn), dạng cổ 頷: 含 (biểu âm) + 頁 (biểu nghĩa — đầu). Chỉ phần cằm dưới (jaw/jowl). Thấy hình trong kim văn, đại triện và tiểu triện. Ngoài nghĩa cằm, còn có nghĩa gật đầu (动 — gật đầu bằng cằm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cằm", "Hạng Tần Suất (Jun Da)": "4146.0", "Tần Suất % (Jun Da)": "99.7852556219", "GavinGrover_Once (Chiết tự trực tiếp)": "含 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰含页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "含", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颔", "Unihan_Traditional (Chữ Phồn thể)": "頷", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bộ phận cằm hoặc làm động từ biểu thị sự gật đầu đồng ý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黜', '{"9000": "4147.0", "Chữ Trung Quốc": "黜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 17 | nét | 黑 | hắc | biểu nghĩa | màu đen | 出 | xuất | biểu âm | 黜 = 黑 (Hắc, biểu nghĩa: màu đen) + 出 (Xuất, biểu âm); chữ hình thanh. Bộ hắc 黑 gợi nghĩa bị bôi đen/hạ xuống; phần 出 cho âm chù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truất\": màu đen (黑) + đẩy ra (出) — 黜 là truất phế, tống cổ quan lại ra khỏi triều đình, \"bôi đen\" tên tuổi họ. | Gương Hán-Việt | truất (黜) — trong Hán-Việt: 黜免 (truất miễn — cách chức), 废黜 (phế truất — bãi bỏ, lật đổ) | Mở khoá kiến thức | Biết 黜 mở khoá: 废黜 (phế truất — phế bỏ), 黜免 (truất miễn — cách chức bãi miễn), 罢黜 (bãi truất — bãi bỏ).", "Tự nguyên_Xie": "Tiểu triện | 黜 (truất/chù) là chữ hình thanh theo Wiktionary: 黑 (biểu nghĩa — màu đen, ám chỉ bị hạ xuống, xấu xa) + 出 (biểu âm). Chỉ việc cách chức, phế truất, hạ bậc quan lại. Nghĩa gốc: bị \"bôi đen\" và đẩy ra ngoài khỏi triều đình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cách chức, phế truất", "Hạng Tần Suất (Jun Da)": "4147.0", "Tần Suất % (Jun Da)": "99.7855047124", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黜", "Unihan_Traditional (Chữ Phồn thể)": "黜", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "truất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động bãi chức, hạ bệ hoặc loại bỏ ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黠', '{"9000": "4148.0", "Chữ Trung Quốc": "黠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 18 | nét | 黠 | hạt | tượng hình | ranh mãnh, tinh khôn; bộ 黑 gợi ý tối tăm/ẩn giấu trí tuệ | 黠 không có phân tích hình thanh/hội ý chi tiết từ anchor. Chữ chứa bộ 黑 (hắc — màu đen), gợi ý trí khôn ẩn giấu trong bóng tối. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": đen (黑) mà sáng — 黠 chỉ người tinh khôn ranh mãnh, ẩn trí tuệ dưới vẻ ngoài tối tăm; không phải khôn ngoan trung thực mà là khéo léo, lanh lợi có phần quỷ quyệt. | Gương Hán-Việt | hạt (黠) — trong Hán-Việt: 狡黠 (giảo hạt — xảo quyệt ranh mãnh), 慧黠 (tuệ hạt — thông minh lanh lợi) | Mở khoá kiến thức | Biết 黠 mở khoá: 狡黠 (giảo hạt — ranh ma), 慧黠 (tuệ hạt — lanh lợi thông minh).", "Tự nguyên_Xie": "Tiểu triện | 黠 (hạt/xiá): chữ có bộ 黑. Wiktionary không có phân tích cấu tạo rõ ràng, chỉ ghi rfdef (cần định nghĩa thêm). Các từ ghép như 狡黠 (gian xảo ranh mãnh), 慧黠 (thông minh lanh lợi) cho thấy chữ chỉ sự tinh khôn có phần xảo quyệt. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng suốt, thông minh", "Hạng Tần Suất (Jun Da)": "4148.0", "Tần Suất % (Jun Da)": "99.7857538028", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黠", "Unihan_Traditional (Chữ Phồn thể)": "黠", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để miêu tả tính cách thông minh, lanh lợi nhưng có phần láu cá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濑', '{"9000": "4149.0", "Chữ Trung Quốc": "濑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 氵 | biểu nghĩa | nước | 賴 | biểu âm | 濑 = 氵(水) (biểu nghĩa: nước) + 賴 (biểu âm); chữ hình thanh. Bộ thủy 氵 cho biết liên quan đến dòng nước; phần 賴 cho âm lài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": nước (氵) chảy lại ào ào — 濑 là dòng nước xiết chảy qua cát đá, tạo tiếng ào ào; âm \"lại\" gợi âm thanh nước chảy mạnh. | Gương Hán-Việt | lại (濑) — trong địa danh và thơ văn: 濑水 (lại thủy — sông Lại chảy xiết) | Mở khoá kiến thức | Biết 濑 mở khoá từ vựng thơ ca cổ điển về thiên nhiên: 急濑 (cấp lại — thác nước xiết), 滩濑 (than lại — bãi đá ghềnh).", "Tự nguyên_Xie": "Tiểu triện | 濑 (lại), dạng cổ 瀨: 水 (biểu nghĩa — nước) + 賴 (biểu âm). Chỉ dòng nước chảy xiết trên cát hoặc đá, thác ghềnh chảy nhanh. Thấy hình trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy trên cát; chảy xiết; sông Lai", "Hạng Tần Suất (Jun Da)": "4149.0", "Tần Suất % (Jun Da)": "99.7860018597", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 赖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵赖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濑", "Unihan_Traditional (Chữ Phồn thể)": "瀨", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dòng nước chảy nhanh trên bãi đá cạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馁', '{"9000": "4150.0", "Chữ Trung Quốc": "馁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 10 | nét | 食 | thực | biểu nghĩa | thức ăn, ăn uống | 妥 | thoả | biểu âm | 馁 = 食 (Thực, biểu nghĩa: thức ăn) + 妥 (Thoả, biểu âm); chữ hình thanh. Bộ 食 cho biết liên quan đến ăn uống/thiếu ăn; phần 妥 cho âm gần với něi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỗi\": ăn uống (食) không thoả (妥) — 馁 là đói khát, nản lòng; \"thắng không kiêu, bại không nỗi\" (勝不驕，敗不餒) — câu danh ngôn nổi tiếng dùng chữ 馁. | Gương Hán-Việt | nỗi (馁) — trong Hán-Việt: 气馁 (khí nỗi — nản lòng, mất tinh thần) | Mở khoá kiến thức | Biết 馁 mở khoá: 气馁 (khí nỗi — nản lòng), 凍馁 (đống nỗi — lạnh và đói), 败不馁 (bại không nỗi — thua không nản).", "Tự nguyên_Xie": "馁 (nỗi), dạng cổ 餒: 食 (biểu nghĩa — thức ăn) + 妥 (biểu âm). Chỉ sự đói khát, mất tinh thần (nản lòng), và cá ươn thối. Ba nghĩa này liên quan đến sự \"thiếu hụt\" — thiếu ăn, thiếu tinh thần, thiếu sự tươi mới. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đói; đuối, kém; ươn, thối", "Hạng Tần Suất (Jun Da)": "4150.0", "Tần Suất % (Jun Da)": "99.7862493997", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 妥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣妥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馁", "Unihan_Traditional (Chữ Phồn thể)": "餒", "Pinyin_Xie": "něi", "Âm Hán Việt_Xie": "nỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ trạng thái nản chí, mất tinh thần hoặc thiếu thốn lương thực. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洵', '{"9000": "4151.0", "Chữ Trung Quốc": "洵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | biểu nghĩa | nước | 旬 | tuần | biểu âm | 洵 = 氵(水) (biểu nghĩa: nước) + 旬 (Tuần, biểu âm); chữ hình thanh. Bộ thủy 氵 cho biết gốc nghĩa liên quan đến nước; phần 旬 cho âm xún.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": nước (氵) chảy tuần hoàn rõ ràng (旬) — 洵 dùng trong văn ngôn với nghĩa \"thực sự, quả thật\"; 洵美 trong Kinh Thi nghĩa là \"thực sự đẹp đẽ\". | Gương Hán-Việt | tuần (洵) — trong văn ngôn: 洵美 (tuần mỹ — thực sự xinh đẹp, Kinh Thi) | Mở khoá kiến thức | Biết 洵 mở khoá ngôn ngữ Kinh Thi và thơ ca cổ điển: 洵美且仁 (tuần mỹ thả nhân — thực sự tốt đẹp và nhân từ).", "Tự nguyên_Xie": "Tiểu triện | 洵 (tuần/xún) là chữ hình thanh theo Wiktionary: 水 (biểu nghĩa — nước) + 旬 (biểu âm). Nghĩa chính trong văn học cổ là \"thực sự, quả thật\" (trạng từ), dùng nhiều trong Kinh Thi. Cũng là tên hai con sông cổ đại. Dạng gốc nghĩa nước sau chuyển sang dùng làm trạng từ khẳng định. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tin thực; xoáy nước", "Hạng Tần Suất (Jun Da)": "4151.0", "Tần Suất % (Jun Da)": "99.7864969398", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洵", "Unihan_Traditional (Chữ Phồn thể)": "洵", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Chữ này làm phó từ đứng trước động từ hoặc tính từ để khẳng định sự thật. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忐', '{"9000": "4152.0", "Chữ Trung Quốc": "忐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 上 | thượng | biểu ý | lên trên | 心 | tâm | biểu ý | trái tim | 忐 = 上 (Thượng: lên trên) + 心 (Tâm: trái tim); chữ hội ý. Tim nhảy lên — hình ảnh tim đập thình thịch khi lo lắng. Chữ hội ý cặp đôi với 忑 (tim đập xuống) trong từ 忐忑.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến; nhớ 忐 = tim (心) nhảy lên trên (上) — đây là nửa trên của 忐忑, khi lo lắng tim đập nhảy lên nhảy xuống không yên. | Gương Hán-Việt | thảm (忐) — chủ yếu trong từ: 忐忑 (thảm thắc — bất an, lo lắng) | Mở khoá kiến thức | Biết 忐 mở khoá: 忐忑不安 (thảm thắc bất an — lo lắng bồn chồn không yên), từ ghép quan trọng trong tiếng Trung.", "Tự nguyên_Xie": "忐 (thảm/tǎn) là chữ hội ý theo Wiktionary: 上 (lên trên) + 心 (trái tim). Tim đập lên — dùng chỉ trạng thái lo lắng, bồn chồn. Cặp đôi với 忑 (下心 — tim đập xuống) tạo thành 忐忑 (thảm thắc) chỉ sự bất an, lo lắng không yên. So sánh: hai chữ bổ sung nhau mô tả tim đập thình thịch. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thảm thắc 忐忑)", "Hạng Tần Suất (Jun Da)": "4152.0", "Tần Suất % (Jun Da)": "99.7867444799", "GavinGrover_Once (Chiết tự trực tiếp)": "上 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱上心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "上", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "忐", "Unihan_Traditional (Chữ Phồn thể)": "忐", "Pinyin_Xie": "tǎn", "Âm Hán Việt_Xie": "thảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ và hầu như chỉ dùng trong từ ghép để tả tâm trạng bồn chồn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忑', '{"9000": "4153.0", "Chữ Trung Quốc": "忑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忑 | thắc | tượng hình | tim đập xuống; lo lắng bất an; bộ 心 + 下 (tim hướng xuống) | 忑 không có phân tích cấu tạo từ anchor. Đây là cặp đôi với 忐 — nếu 忐 là tim đập lên (上心), thì 忑 có thể là tim đập xuống (下心 hoặc biến thể). Dùng hầu như chỉ trong 忐忑. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thắc\": nhớ 忑 qua cặp 忐忑 — nếu 忐 là tim nhảy lên, thì 忑 là tim rớt xuống; hai chữ cùng nhau mô tả tim đập thình thịch lo lắng. | Gương Hán-Việt | thắc (忑) — chủ yếu trong từ: 忐忑 (thảm thắc — bồn chồn lo lắng) | Mở khoá kiến thức | Biết 忑 cùng với 忐 mở khoá: 忐忑不安 (lo lắng bồn chồn không yên).", "Tự nguyên_Xie": "忑 (thắc/tè): cặp đôi không thể tách rời với 忐 trong từ 忐忑 (lo lắng bất an). Anchor không có phân tích cấu tạo; Wiktionary không có mục từ riêng cho 忑. Khả năng cao đây là chữ hội ý đối xứng với 忐 (上心 — tim lên), tức 下心 (tim xuống), nhưng chưa được xác nhận. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thảm thắc 忐忑)", "Hạng Tần Suất (Jun Da)": "4153.0", "Tần Suất % (Jun Da)": "99.7869915032", "GavinGrover_Once (Chiết tự trực tiếp)": "下 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱下心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "下", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "忑", "Unihan_Traditional (Chữ Phồn thể)": "忑", "Pinyin_Xie": "tè", "Âm Hán Việt_Xie": "thắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ trong từ ghép để miêu tả trạng thái tâm lý lo lắng, bất an. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砥', '{"9000": "4154.0", "Chữ Trung Quốc": "砥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 石 | thạch | biểu nghĩa | đá | 氐 | biểu âm | 砥 = 石 (Thạch, biểu nghĩa: đá) + 氐 (biểu âm); chữ hình thanh. Bộ thạch 石 cho biết liên quan đến đá; phần 氐 cho âm dǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"để\": đá (石) mài mịn dưới đáy (氐) — 砥 là hòn đá mài, từ đó nghĩa rộng ra là mài giũa, rèn luyện. 中流砥柱 — đá cột giữa dòng, tượng trưng cho người vững vàng không lay chuyển. | Gương Hán-Việt | để (砥) — trong Hán-Việt: 砥砺 (để lệ — mài giũa, rèn luyện), 中流砥柱 (trung lưu để trụ) | Mở khoá kiến thức | Biết 砥 mở khoá: 砥砺 (để lệ — mài giũa bản thân), 中流砥柱 (trung lưu để trụ — trụ cột vững vàng).", "Tự nguyên_Xie": "Tiểu triện | 砥 (để/dǐ) là chữ hình thanh theo Wiktionary: 石 (biểu nghĩa — đá) + 氐 (biểu âm). Nghĩa gốc là đá mài mịn (fine-grained whetstone). Nghĩa chuyển: mài giũa, rèn luyện bản thân, bằng phẳng. Nổi tiếng qua thành ngữ 中流砥柱 (trung lưu để trụ — trụ cột vững chắc giữa dòng nước chảy mạnh). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hòn đá mài; dùi mài", "Hạng Tần Suất (Jun Da)": "4154.0", "Tần Suất % (Jun Da)": "99.7872385265", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砥", "Unihan_Traditional (Chữ Phồn thể)": "砥", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ đá mài phẳng hoặc làm động từ với nghĩa mài giũa, rèn luyện bản thân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咂', '{"9000": "4155.0", "Chữ Trung Quốc": "咂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 咂 | táp | tượng hình | mút, húp; chép miệng; bộ 口 gợi miệng | 咂 không có phân tích hình thanh/hội ý chi tiết từ anchor. Chữ chứa bộ 口 (khẩu — miệng), chỉ hành động mút, húp hoặc chép miệng. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": miệng (口) táp vào mà mút — 咂 là hành động đặt miệng vào mà mút hoặc chép miệng, âm \"táp\" gợi đúng tiếng môi chạm vào thứ gì đó. | Gương Hán-Việt | táp (咂) — ít dùng độc lập trong Hán-Việt | Mở khoá kiến thức | Biết 咂 mở khoá: 咂嘴 (táp chủy — chép miệng, smack the lips), 咂摸 (táp ma — nếm thử/suy ngẫm).", "Tự nguyên_Xie": "咂 (táp/zā): chữ có bộ 口 (miệng). Anchor Wiktionary chỉ ghi {{Han etym}} mà không có phân tích cấu tạo. Chỉ hành động mút (suck), chép miệng, hoặc tra vào miệng nếm thử. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tra vào mồm", "Hạng Tần Suất (Jun Da)": "4155.0", "Tần Suất % (Jun Da)": "99.7874845162", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 匝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口匝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咂", "Unihan_Traditional (Chữ Phồn thể)": "咂", "Pinyin_Xie": "zā", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhấp môi uống nước hoặc tặc lưỡi để cảm nhận hương vị. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罹', '{"9000": "4156.0", "Chữ Trung Quốc": "罹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 16 | nét | 网 | võng | biểu ý | cái lưới | 忄 | biểu ý | trái tim | 隹 | biểu ý | con chim | 罹 = 网 (Võng: lưới) + 忄 (tâm: trái tim) + 隹 (con chim); chữ hội ý. Con chim sa lưới (trong lòng/tâm trạng) — hình ảnh tâm hồn mắc bẫy, sa vào khổ nạn. Chữ hội ý ba phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": con chim (隹) mắc lưới (网) trong lòng (忄) — 罹 là gặp hoạ, mắc bệnh, tâm hồn như chim sa lưới không thoát ra được. | Gương Hán-Việt | ly (罹) — trong Hán-Việt: 罹患 (ly hoạn — mắc bệnh), 罹难 (ly nạn — thiệt mạng vì tai nạn) | Mở khoá kiến thức | Biết 罹 mở khoá: 罹患 (ly hoạn — mắc bệnh), 罹难 (ly nạn — tử nạn), 罹病 (ly bệnh — mắc bệnh).", "Tự nguyên_Xie": "Tiểu triện | 罹 (ly/lí) là chữ hội ý theo Wiktionary: 网 (lưới) + 心/忄 (trái tim) + 隹 (chim). Hình ảnh: chim mắc lưới trong lòng — sa vào nỗi đau, mắc bệnh, gặp tai nạn. Wiktionary ghi chú: các nghĩa của chữ này thường viết bằng 離 trong văn học cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo lắng", "Hạng Tần Suất (Jun Da)": "4156.0", "Tần Suất % (Jun Da)": "99.7877305059", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 惟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒惟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罹", "Unihan_Traditional (Chữ Phồn thể)": "罹", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ đứng trước danh từ chỉ bệnh tật hoặc tai họa để biểu thị việc mắc phải tai ương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糠', '{"9000": "4157.0", "Chữ Trung Quốc": "糠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 17 | nét | 米 | mễ | biểu nghĩa | gạo, hạt gạo | 康 | khang | biểu âm | 糠 = 米 (Mễ, biểu nghĩa: gạo) + 康 (Khang, biểu âm); chữ hình thanh. Bộ mễ 米 cho biết liên quan đến gạo; phần 康 cho âm kāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khang\": gạo (米) đi qua khang trang (康) — nghịch lý thay, 糠 là cám trấu — phần bỏ đi khi xay gạo; tuy nhiên câu 糟糠之妻 nhắc nhở ta trân trọng người bên cạnh lúc khó khăn. | Gương Hán-Việt | khang (糠) — trong Hán-Việt: 糟糠 (tao khang — bã rượu và cám, ẩn dụ thời khó khăn), 糠秕 (khang bỉ — trấu và lép) | Mở khoá kiến thức | Biết 糠 mở khoá: 糟糠之妻 (tao khang chi thê — người vợ đã cùng nhau vượt khó), 米糠 (mễ khang — cám gạo).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 糠 (khang/kāng) là chữ hình thanh theo Wiktionary: 米 (biểu nghĩa — gạo) + 康 (biểu âm). Chỉ cám gạo, vỏ trấu — phần bỏ đi khi xay thóc thành gạo. Nghĩa chuyển: chất lượng kém, không đáng giá. Thấy hình trong giáp cốt văn (nhiều) và tiểu triện. Gắn với tục ngữ 糟糠之妻 (tao khang chi thê — vợ cùng khổ, người vợ đã ăn cám thời khốn khó). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cám, trấu", "Hạng Tần Suất (Jun Da)": "4157.0", "Tần Suất % (Jun Da)": "99.7879759789", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 康", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米康", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "康", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糠", "Unihan_Traditional (Chữ Phồn thể)": "穅", "Pinyin_Xie": "kāng", "Âm Hán Việt_Xie": "khang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần vỏ ngoài của hạt ngũ cốc sau khi xay xát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匝', '{"9000": "4158.0", "Chữ Trung Quốc": "匝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 5 | nét | 匝 | táp | tượng hình | vòng tròn, bao quanh; biến thể của 迊 | 匝 không có phân tích hình thanh/hội ý chi tiết. Theo Wiktionary, 匝 là biến thể hình học của 迊 từ thể thảo (cursive). Chữ chỉ một vòng tròn hoàn chỉnh, vây quanh. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": 匝 là một vòng hoàn toàn — như con đường vây quanh (bộ 匚 gợi hình khung bao), \"táp\" một vòng là đi hết một chu kỳ. | Gương Hán-Việt | táp (匝) — trong Hán-Việt: 周匝 (chu táp — vây quanh khắp nơi) | Mở khoá kiến thức | Biết 匝 mở khoá: 周匝 (chu táp — bao quanh), 匝地 (táp địa — khắp mặt đất), 匝月 (táp nguyệt — trọn một tháng).", "Tự nguyên_Xie": "匝 (táp/zā): Wiktionary ghi rõ đây là biến thể hình học của 迊 từ thể thảo (cursive script). Chỉ một vòng tròn hoàn chỉnh, bao quanh khắp nơi. Ví dụ: 周匝 (chu táp — vây quanh hết một vòng). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vòng; nuộc; vây quanh; khắp; khắp cả; khắp nơi", "Hạng Tần Suất (Jun Da)": "4158.0", "Tần Suất % (Jun Da)": "99.788220935", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 巾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚巾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匝", "Unihan_Traditional (Chữ Phồn thể)": "匝", "Pinyin_Xie": "zā", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Động từ | 动词 | Chữ này làm lượng từ để đếm số vòng quay hoặc làm động từ với nghĩa bao quanh, vây bọc. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偃', '{"9000": "4159.0", "Chữ Trung Quốc": "偃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 人 | nhân | biểu nghĩa | người | 匽 | biểu âm | 偃 = 人/亻 (Nhân, biểu nghĩa: người) + 匽 (biểu âm); chữ hình thanh. Bộ nhân 亻 cho biết liên quan đến tư thế/hành động của người; phần 匽 cho âm yǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ễnh\": người (亻) ễnh ra nằm xuống — 偃 là nằm ngửa hoặc dừng lại; ễnh cũng gợi hình ảnh ễnh ương nằm phơi bụng; 偃旗息鼓 là hạ cờ im trống. | Gương Hán-Việt | ễnh (偃) — trong Hán-Việt: 偃旗息鼓 (ễnh kỳ tức cổ — ngừng chiến), 偃武修文 (ễnh vũ tu văn — từ bỏ chiến tranh, phát triển văn hoá) | Mở khoá kiến thức | Biết 偃 mở khoá: 偃旗息鼓 (hạ cờ im trống), 偃武修文 (bỏ vũ tu văn).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 偃 (ễnh/yǎn) là chữ hình thanh theo Wiktionary: 人 (biểu nghĩa — người) + 匽 (biểu âm). Hai nghĩa chính: ngã ngửa/nằm xuống, và đình chỉ/dừng lại. Nổi tiếng qua thành ngữ 偃旗息鼓 (ễnh kỳ tức cổ — hạ cờ im trống, ngừng chiến) và 草偃风行 (thảo ễnh phong hành — cỏ rạp theo gió). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dừng, thôi, nghỉ; nằm; nép, xếp", "Hạng Tần Suất (Jun Da)": "4159.0", "Tần Suất % (Jun Da)": "99.7884658912", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 匽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻匽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偃", "Unihan_Traditional (Chữ Phồn thể)": "偃", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ tư thế nằm ngửa, ngã rạp xuống hoặc hành động đình chỉ, bãi bỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淙', '{"9000": "4160.0", "Chữ Trung Quốc": "淙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 水 | thủy | biểu nghĩa | nước | 宗 | tông | biểu âm | 淙 = 水/氵 (Thủy, biểu nghĩa: nước) + 宗 (Tông, biểu âm); chữ hình thanh. Bộ thủy 氵 cho biết liên quan đến nước/âm thanh nước; phần 宗 cho âm cóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": nước (氵) chảy tông tông — 淙 mô tả tiếng nước suối chảy ào ào, âm \"cóng-cóng\" như tiếng đàn nước thiên nhiên; 淙淙 là từ láy miêu tả âm thanh đó. | Gương Hán-Việt | tông (淙) — trong thơ ca: 淙淙 (tông tông — tiếng nước chảy ào ào) | Mở khoá kiến thức | Biết 淙 mở khoá: 淙淙 (tiếng nước chảy), 淙琤 (tông tranh — tiếng nước trong văn học).", "Tự nguyên_Xie": "Tiểu triện | 淙 (tông/cóng) là chữ hình thanh theo Wiktionary: 水 (biểu nghĩa — nước) + 宗 (biểu âm). Chỉ tiếng nước chảy ào ào, róc rách. Dùng chủ yếu trong từ láy 淙淙 (cóng cóng — tiếng nước chảy liên tục), thường xuất hiện trong thơ ca miêu tả suối nước trong. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy ào ào", "Hạng Tần Suất (Jun Da)": "4160.0", "Tần Suất % (Jun Da)": "99.7887108473", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淙", "Unihan_Traditional (Chữ Phồn thể)": "淙", "Pinyin_Xie": "cóng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này thường dùng làm từ tượng thanh mô tả âm thanh róc rách của dòng nước chảy. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纫', '{"9000": "4161.0", "Chữ Trung Quốc": "纫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纫 | nhẫn | tượng hình | xỏ kim; may vá; bộ 纟(糸) gợi sợi chỉ | 纫 không có phân tích hình thanh/hội ý chi tiết từ anchor. Chữ chứa bộ 纟 (mịch — sợi tơ/chỉ), chỉ hành động xỏ kim (穿针引线), khâu vá. Thấy hình trong bạch thư (silk manuscripts). Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫn\": sợi chỉ (纟) nhẫn nại xỏ vào kim — 纫 là xỏ chỉ vào kim, công việc đòi hỏi sự nhẫn nại và khéo léo; từ đó có 缝纫 (may vá), 缝纫机 (máy may). | Gương Hán-Việt | nhẫn (纫) — trong Hán-Việt: 缝纫 (phùng nhẫn — may vá), 感纫 (cảm nhẫn — biết ơn, văn ngôn) | Mở khoá kiến thức | Biết 纫 mở khoá: 缝纫 (phùng nhẫn — may vá), 缝纫机 (máy may), 纫佩 (nhẫn bội — đeo vào người, ẩn dụ ghi nhớ ơn).", "Tự nguyên_Xie": "Bạch thư | 纫 (nhẫn/rèn), dạng cổ 紉: chứa bộ 糸/纟 (sợi chỉ). Wiktionary ghi: xỏ kim, khâu vá, và trong văn học cổ còn có nghĩa kính ngưỡng (佩服). Thấy hình trong bạch thư (silk texts). Phổ biến trong từ 缝纫 (phùng nhẫn — may vá), 缝纫机 (máy may). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xâu kim (xỏ chỉ vào kim)", "Hạng Tần Suất (Jun Da)": "4161.0", "Tần Suất % (Jun Da)": "99.7889552867", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纫", "Unihan_Traditional (Chữ Phồn thể)": "紉", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhân, nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động xỏ chỉ qua kim hoặc khâu vá quần áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喏', '{"9000": "4162.0", "Chữ Trung Quốc": "喏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 喏 | nhạ | tượng hình | lời thưa kính; bộ 口 gợi miệng nói kính lời | 喏 không có phân tích hình thanh/hội ý chi tiết từ anchor. Chữ chứa bộ 口 (khẩu — miệng), chỉ lời thưa kính trọng đáp lại người bề trên, hoặc cử chỉ vái chào. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhạ\": miệng (口) thốt ra \"nhạ\" khi chào kính — 喏 là tiếng đáp \"dạ, vâng\" khi bề dưới thưa bề trên, như \"nhạ\" trong tiếng Việt cổ có nghĩa tương tự. | Gương Hán-Việt | nhạ (喏) — trong văn học cổ: 唱喏 (xướng nhạ — chào vái kính trọng), 打喏 (đả nhạ — vái chào) | Mở khoá kiến thức | Biết 喏 giúp đọc tiểu thuyết lịch sử Trung Quốc: 唱喏 (cúi đầu vái chào quan trên), 打喏 (vái chào lịch sự).", "Tự nguyên_Xie": "喏 (nhạ/nuò): chữ có bộ 口 (miệng). Anchor và Wiktionary không có mục từ riêng với phân tích cấu tạo. Chỉ lời thưa kính, đáp lời bề trên (\"dạ\", \"vâng\"), hoặc cử chỉ vái chào. Thường thấy trong tiểu thuyết và kịch lịch sử Trung Quốc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kính chào", "Hạng Tần Suất (Jun Da)": "4162.0", "Tần Suất % (Jun Da)": "99.7891997261", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 若", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口若", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喏", "Unihan_Traditional (Chữ Phồn thể)": "喏", "Pinyin_Xie": "nuò", "Âm Hán Việt_Xie": "nhạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Trợ từ | 助词 | Chữ này làm thán từ dùng để đáp lời người bề trên hoặc để thu hút sự chú ý của người khác. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闾', '{"9000": "4163.0", "Chữ Trung Quốc": "闾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 門 | môn | biểu nghĩa | cổng, cửa | 呂 | lã | biểu âm | 閭 = 門 (Môn, biểu nghĩa: cổng) + 呂 (Lã, biểu âm); chữ hình thanh. Phần Môn cho biết nghĩa liên quan đến cổng, cửa làng; phần Lã gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\": cổng làng (門) mang âm của Lã (呂) — cổng 25 hộ là một lư. | Gương Hán-Việt | \"lư\" trong \"lư lý\" (xóm làng) | Mở khoá kiến thức | Biết 闾 mở khoá các từ cổ văn như 閭里 (làng xóm), 閭巷 (phố hẻm), 倚閭 (đứng tựa cổng trông con).", "Tự nguyên_Xie": "Chữ hình thanh: 門 (cổng) biểu nghĩa, 呂 biểu âm. Nghĩa gốc là cổng ngõ xóm làng, sau mở rộng chỉ khu dân cư gồm 25 hộ gia đình — đơn vị hành chính thời cổ. Từ đó phái sinh nghĩa ''xóm làng, phố xá''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổng làng; lư (đơn vị hành chính, gồm 25 hộ)", "Hạng Tần Suất (Jun Da)": "4163.0", "Tần Suất % (Jun Da)": "99.7894441654", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闾", "Unihan_Traditional (Chữ Phồn thể)": "閭", "Pinyin_Xie": "lǘ", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cổng làng hoặc khu dân cư gồm hai mươi lăm hộ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祛', '{"9000": "4164.0", "Chữ Trung Quốc": "祛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 祛 | khư | tượng hình | bài trừ, đuổi đi | Chữ 祛 không có phân tích compound rõ ràng trong Wiktionary. Khả năng cao là hình thanh: bộ 示 (thị, biểu nghĩa: liên quan thần linh/nghi lễ) + phần biểu âm, nhưng cấu trúc chưa được xác nhận đầy đủ; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khư\": tưởng tượng một nghi lễ (示) xua ''khử'' điều xấu đi xa — khư bệnh, khư tà. | Gương Hán-Việt | \"khư\" trong \"khu trừ\" (loại trừ), \"khư phong\" (trừ phong hàn) | Mở khoá kiến thức | Biết 祛 mở khoá từ y học cổ như 祛除 (loại trừ), 祛风 (trừ phong), 祛痰 (tiêu đờm).", "Tự nguyên_Xie": "Wiktionary ghi nhận 祛 là chữ cổ nghĩa là ''xua đuổi, trừ bỏ''. Cấu tạo nội bộ chưa được phân tích rõ trong nguồn học thuật. Có thể liên quan đến bộ 示 (thị), gợi hành động trừ tà qua nghi lễ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bài trừ, đuổi đi", "Hạng Tần Suất (Jun Da)": "4164.0", "Tần Suất % (Jun Da)": "99.7896886048", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 去", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻去", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "去", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祛", "Unihan_Traditional (Chữ Phồn thể)": "祛", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các danh từ chỉ bệnh tật, tà ma để biểu thị việc loại bỏ chúng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛰', '{"9000": "4165.0", "Chữ Trung Quốc": "蛰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛰 | triệt | tượng hình | sâu trùng ẩn nấp dưới đất | 蛰 là dạng giản thể của 蟄. Chữ phồn thể 蟄 = 執 (chấp, biểu âm) + 虫 (trùng, biểu nghĩa: sâu bọ); chữ hình thanh. Dạng giản thể thay 執 bằng 执.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệt\": con sâu (虫) bị ''triệt'' vào lòng đất ngủ đông — hình ảnh Kinh Trập khi sâu ngủ yên. | Gương Hán-Việt | \"triệt\" trong \"kinh triệt\" (惊蛰, tiết sâu bọ thức dậy) | Mở khoá kiến thức | Biết 蛰 mở khoá từ như 蛰伏 (ẩn náu, chờ thời), 惊蛰 (tiết Kinh Trập), 蛰居 (sống ẩn dật).", "Tự nguyên_Xie": "蛰 là giản thể của 蟄. Chữ gốc 蟄 gồm 虫 (sâu bọ, biểu nghĩa) và 執 (biểu âm). Nghĩa gốc: sâu bọ, rắn rết ẩn nấp dưới đất vào mùa đông để tránh rét — hiện tượng ''ngủ đông''. Tiết khí ''Kinh Trập'' (惊蛰) là thời điểm sâu bọ bắt đầu thức dậy khi nghe tiếng sấm mùa xuân. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài sâu ở dưới đất; khả năng tiềm tàng", "Hạng Tần Suất (Jun Da)": "4165.0", "Tần Suất % (Jun Da)": "99.7899325274", "GavinGrover_Once (Chiết tự trực tiếp)": "执 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱执虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛰", "Unihan_Traditional (Chữ Phồn thể)": "蟄", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "trập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ trạng thái ẩn nấp hoặc ngủ đông của côn trùng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腼', '{"9000": "4166.0", "Chữ Trung Quốc": "腼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腼 | điện | tượng hình | bẽn lẽn, thẹn thùng | Chữ 腼 không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Dạng chữ có thể liên quan đến bộ 月/肉 (nhục, thân thể) nhưng chưa xác nhận; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điện\": mặt đỏ bừng (月/肉 — da thịt) vì xấu hổ — người 腼腆 là người hay đỏ mặt. | Gương Hán-Việt | \"điện\" trong \"điện điển\" (腼腆, bẽn lẽn) | Mở khoá kiến thức | Biết 腼 mở khoá từ 腼腆 (bẽn lẽn, nhút nhát) — tính từ miêu tả tính cách hay dùng trong văn học.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 腼. Nghĩa ghi nhận: bẽn lẽn, thẹn thùng, e thẹn. Thường dùng trong từ ghép 腼腆 (miǎntiǎn). Cấu tạo nội bộ chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẽn lẽn, thẹn thùng, e thẹn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 面", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月面", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "面", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腼", "Unihan_Traditional (Chữ Phồn thể)": "腼", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "điến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ mô tả dáng vẻ e thẹn và hay đi kèm trong từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涝', '{"9000": "4167.0", "Chữ Trung Quốc": "涝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 水 | thủy | biểu nghĩa | nước | 勞 | lao | biểu âm | 涝 = 氵(Thủy, biểu nghĩa: nước) + 勞 (Lao, biểu âm); chữ hình thanh. Phần thủy cho biết nghĩa liên quan đến nước, phần Lao gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": nước (氵) ''lao'' vào đồng ruộng, gây ngập úng — lao thiên tai. | Gương Hán-Việt | \"lao\" trong \"lao tai\" (涝灾, thiên tai lũ lụt) | Mở khoá kiến thức | Biết 涝 mở khoá từ 旱涝 (hạn hán và lũ lụt), 涝灾 (thiên tai ngập lụt), 受涝 (bị ngập).", "Tự nguyên_Xie": "Chữ hình thanh: 氵 (nước) biểu nghĩa, 勞 biểu âm. Nghĩa gốc: đất trũng bị ngập úng, mùa màng bị chìm trong nước. Trái nghĩa với 旱 (hạn hán). Dùng nhiều trong ngữ cảnh thiên tai lũ lụt: 涝灾 (thiên tai lũ lụt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngâm trong nước", "Hạng Tần Suất (Jun Da)": "4167.0", "Tần Suất % (Jun Da)": "99.7904198558", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涝", "Unihan_Traditional (Chữ Phồn thể)": "澇", "Pinyin_Xie": "lào", "Âm Hán Việt_Xie": "lạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ nạn úng lụt hoặc động từ chỉ việc đất đai bị ngập nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lào | / | lụt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thiên tai", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曜', '{"9000": "4168.0", "Chữ Trung Quốc": "曜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 18 | nét | 日 | nhật | biểu nghĩa | mặt trời | 翟 | địch | biểu âm | 曜 = 日 (Nhật, biểu nghĩa: mặt trời) + 翟 (Địch, biểu âm); chữ hình thanh. Phần Nhật cho biết nghĩa liên quan đến ánh sáng/mặt trời; phần Địch gợi âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệu\": mặt trời (日) rực rỡ như chim công (翟) xoè cánh — ánh diệu quang chói loà. | Gương Hán-Việt | \"diệu\" trong \"thất diệu\" (七曜, bảy thiên thể: nhật, nguyệt, ngũ tinh) | Mở khoá kiến thức | Biết 曜 mở khoá từ 七曜 (thất diệu — cơ sở đặt tên ngày trong tuần tiếng Nhật), 曜日 (ngày trong tuần, tiếng Nhật/Trung cổ văn).", "Tự nguyên_Xie": "Chữ hình thanh: 日 (mặt trời) biểu nghĩa, 翟 biểu âm. Nghĩa gốc: ánh sáng chói rực của mặt trời. Được dùng để chỉ các ngày trong tuần theo hệ thống thiên văn cổ: 七曜 (thất diệu) gồm mặt trời, mặt trăng và năm hành tinh nhìn thấy bằng mắt thường. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1456.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Địch (1396)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời/ 日 /chỉ ý) ở bên trái chữ Địch (số 1396 - chim trĩ/ 翟 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Địch chỉ âm, bộ Nhật chỉ ý. Diệu là sáng chói, rực rỡ, chiếu sáng. Cũng dùng làm tên gọi chung cho mặt trời mặt trăng và tinh tú (thất diệu).", "Nghĩa Tiếng Việt_Xie": "bóng sáng mặt trời; chói mắt", "Hạng Tần Suất (Jun Da)": "4168.0", "Tần Suất % (Jun Da)": "99.7906632616", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 翟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "曜", "Unihan_Traditional (Chữ Phồn thể)": "曜", "Pinyin_Xie": "yào", "Âm Hán Việt_Xie": "diệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ chỉ thiên thể phát sáng hoặc động từ chỉ sự chiếu sáng rực rỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厩', '{"9000": "4169.0", "Chữ Trung Quốc": "厩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 11 | nét | 广 | nghiễm | biểu nghĩa | mái nhà, công trình | 㲃 | biểu âm | 厩 = 广 (Nghiễm, biểu nghĩa: mái nhà, công trình xây dựng) + 㲃 (biểu âm); chữ hình thanh. Phần 广 cho thấy đây là một loại công trình; phần 㲃 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cứu\": công trình (广) để cứu ngựa khỏi mưa nắng — chuồng ngựa cứu. | Gương Hán-Việt | \"cứu\" trong \"mã cứu\" (马厩, chuồng ngựa) | Mở khoá kiến thức | Biết 厩 mở khoá từ 马厩 (chuồng ngựa), 厩肥 (phân chuồng), 御厩 (chuồng ngựa hoàng gia).", "Tự nguyên_Xie": "Chữ hình thanh: 广 (mái nhà) biểu nghĩa, 㲃 biểu âm. Nghĩa gốc: chuồng ngựa hoàng gia, nơi nuôi ngựa của vua chúa. Chữ xuất hiện trong kinh điển Nho gia như Mạnh Tử với hình ảnh ''chuồng có ngựa béo, dân có vẻ đói'' — ẩn dụ về bất công xã hội. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuồng ngựa", "Hạng Tần Suất (Jun Da)": "4169.0", "Tần Suất % (Jun Da)": "99.7909061506", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 既", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂既", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "既", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厩", "Unihan_Traditional (Chữ Phồn thể)": "廄", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nơi nhốt ngựa và thường đứng sau danh từ chỉ con vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疽', '{"9000": "4170.0", "Chữ Trung Quốc": "疽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 且 | thả | biểu âm | 疽 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 且 (Thả, biểu âm); chữ hình thanh. Phần 疒 cho biết đây là bệnh về da/cơ thể; phần 且 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": bệnh (疒) ''thư'' — ung nhọt ẩn sâu không thấy đỏ bên ngoài, như thư độc ngầm. | Gương Hán-Việt | \"thư\" trong \"ung thư\" (ung thư — liên quan ung nhọt), \"than thư\" (炭疽, bệnh anthrax) | Mở khoá kiến thức | Biết 疽 mở khoá từ y học 炭疽 (bệnh than, anthrax), 癰疽 (ung nhọt), 疽毒 (độc nhọt).", "Tự nguyên_Xie": "Chữ hình thanh: 疒 (bệnh) biểu nghĩa, 且 biểu âm. Nghĩa trong y học cổ truyền: nhọt sưng tấy dưới da nhưng không đỏ bên ngoài — loại ung nhọt sâu, khó thấy. Phân biệt với 癰 (ung, nhọt đỏ bên ngoài). Dùng trong từ 炭疽 (nhiệt thán — bệnh anthrax). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhọt sưng nhưng không đỏ", "Hạng Tần Suất (Jun Da)": "4170.0", "Tần Suất % (Jun Da)": "99.7911490396", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疽", "Unihan_Traditional (Chữ Phồn thể)": "疽", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại mụn nhọt độc hại trên cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闰', '{"9000": "4171.0", "Chữ Trung Quốc": "闰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 7 | nét | 門 | môn | biểu ý | cổng, cửa | 王 | vương | biểu ý | vua | 闰 = 門 (Môn, cổng) + 王 (Vương, vua); chữ hội ý. Ý nghĩa: nhà vua ở lại trong cung cổng vào ngày nhuận (ngày dư ra ngoài lịch âm 364 ngày), không ra ngoài thực hiện triều nghi — từ đó có nghĩa ''xen thêm, dư ra''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhuận\": vua (王) ngồi trong cổng cung (門) vào ngày nhuận dư — nhuận lịch. | Gương Hán-Việt | \"nhuận\" trong \"nhuận nguyệt\" (闰月, tháng nhuận), \"nhuận niên\" (闰年, năm nhuận) | Mở khoá kiến thức | Biết 闰 mở khoá từ 闰年 (năm nhuận), 闰月 (tháng nhuận), 闰秒 (giây nhuận).", "Tự nguyên_Xie": "Chữ hội ý: 門 (cổng cung điện) + 王 (nhà vua). Ý nghĩa xuất phát từ tập tục thời cổ: vào ngày nhuận — ngày ''dư ra'' ngoài chu kỳ âm lịch 364 ngày — nhà vua ở lại bên trong cổng cung, không thực hiện các nghi lễ thông thường. Từ đó 闰 có nghĩa ''xen thêm, thừa ra'' và chỉ tháng nhuận (闰月), năm nhuận (闰年). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xen vào giữa, thừa ra; nhuận (lịch)", "Hạng Tần Suất (Jun Da)": "4171.0", "Tần Suất % (Jun Da)": "99.7913919286", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 王", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "王", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闰", "Unihan_Traditional (Chữ Phồn thể)": "閏", "Pinyin_Xie": "rùn", "Âm Hán Việt_Xie": "nhuận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ để chỉ tháng hoặc năm có ngày thừa ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洄', '{"9000": "4172.0", "Chữ Trung Quốc": "洄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洄 | hói | tượng hình | nước xoáy, nước chảy vòng | 洄 có bộ 氵(thủy, nước) nhưng phân tích compound không rõ ràng trong nguồn học thuật. Khả năng là hình thanh với 回 biểu âm (âm huí) và 氵biểu nghĩa, nhưng chưa xác nhận; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hói\": nước (氵) chảy ''hồi'' vòng ngược lại — dòng nước hói xoáy. | Gương Hán-Việt | \"hói\" trong \"hói lưu\" (nước chảy ngược, dòng xoáy) | Mở khoá kiến thức | Biết 洄 mở khoá từ 洄游 (cá di cư ngược dòng), 洄想 (hồi tưởng — nghĩa mở rộng).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin chi tiết cho 洄. Nghĩa ghi nhận: nước chảy ngược, nước xoáy. Có thể liên quan đến 回 (quay vòng) với bộ 氵(nước), gợi ý nước chảy vòng lại. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy", "Hạng Tần Suất (Jun Da)": "4172.0", "Tần Suất % (Jun Da)": "99.7916348176", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 回", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "回", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洄", "Unihan_Traditional (Chữ Phồn thể)": "洄", "Pinyin_Xie": "huí", "Âm Hán Việt_Xie": "hồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dòng nước chảy xoáy hoặc cá bơi ngược dòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煊', '{"9000": "4173.0", "Chữ Trung Quốc": "煊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煊 | huyên | tượng hình | nắng ấm, sáng rực | Chữ 煊 không có phân tích cấu tạo rõ ràng trong nguồn học thuật. Có bộ 火 (hỏa, lửa) hoặc liên quan đến ánh sáng/nóng ấm, nhưng cấu trúc chưa xác nhận; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": lửa (火) sáng ''huyên náo'' rực rỡ — danh tiếng huyên hách lừng lẫy. | Gương Hán-Việt | \"huyên\" trong \"huyên hách\" (煊赫, hiển hách, lừng lẫy) | Mở khoá kiến thức | Biết 煊 mở khoá từ 煊赫 (huyên hách, lẫy lừng), thường dùng miêu tả danh tiếng hoặc quyền thế rực rỡ.", "Tự nguyên_Xie": "Wiktionary không có phân tích glyph-origin cho 煊. Nghĩa ghi nhận: nắng ấm, ánh sáng rực rỡ. Thường dùng trong từ ghép 煊赫 (huyên hách, hiển hách, lẫy lừng) với nghĩa chuyển là danh tiếng rực rỡ. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắng ấm", "Hạng Tần Suất (Jun Da)": "4173.0", "Tần Suất % (Jun Da)": "99.7918777066", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煊", "Unihan_Traditional (Chữ Phồn thể)": "煊", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thể hiện sự ấm áp của ánh mặt trời hoặc danh tiếng lẫy lừng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汐', '{"9000": "4174.0", "Chữ Trung Quốc": "汐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 氵 | thủy | biểu nghĩa | nước | 夕 | tịch | biểu âm | buổi tối, hoàng hôn | 汐 = 氵(Thủy, biểu nghĩa: nước) + 夕 (Tịch, biểu âm); chữ hình thanh. Phần 氵cho biết liên quan đến nước; phần 夕 (buổi tối) gợi âm và gợi ý thủy triều xuống vào buổi chiều tối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tách\": nước (氵) ''tách'' ra khi trời tối (夕) — thủy triều chiều rút ra. | Gương Hán-Việt | \"tách\" trong \"triều tách\" (潮汐, thủy triều) | Mở khoá kiến thức | Biết 汐 mở khoá từ 潮汐 (thủy triều), 朝汐 (triều lên sáng, triều xuống tối).", "Tự nguyên_Xie": "Chữ hình thanh: 氵 (nước) biểu nghĩa, 夕 (buổi tối) biểu âm. Nghĩa: thủy triều buổi tối/chiều (nước rút). Cặp với 朝 (triều) — thủy triều buổi sáng lên, 汐 buổi tối rút. Dùng trong từ 潮汐 (thủy triều — tổng hợp cả lên lẫn xuống). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước thuỷ triều buổi tối", "Hạng Tần Suất (Jun Da)": "4174.0", "Tần Suất % (Jun Da)": "99.7921200789", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 夕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵夕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汐", "Unihan_Traditional (Chữ Phồn thể)": "汐", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hiện tượng thủy triều dâng lên vào ban đêm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藓', '{"9000": "4175.0", "Chữ Trung Quốc": "藓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 藓 | tiển | tượng hình | rêu, địa y | Chữ 藓 có bộ 艹 (thảo, cỏ thực vật) gợi nghĩa liên quan thực vật. Phân tích cấu tạo đầy đủ chưa có trong nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiển\": cỏ (艹) ''tiển'' nhỏ bé bám trên đá ẩm ướt — rêu tiển mọc lặng lẽ. | Gương Hán-Việt | \"tiển\" trong \"đài tiển\" (苔藓, rêu và địa y) | Mở khoá kiến thức | Biết 藓 mở khoá từ 苔藓 (rêu và địa y), 苔藓植物 (ngành rêu — Bryophyta).", "Tự nguyên_Xie": "Wiktionary ghi nhận 藓 nghĩa là rêu, địa y (lichen/moss). Có bộ 艹 (thảo — thực vật). Thường dùng trong từ 苔藓 (rêu và địa y), chỉ các loài thực vật bậc thấp không mạch sống trên đất ẩm, đá, vỏ cây. Cấu tạo nội bộ chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây rêu", "Hạng Tần Suất (Jun Da)": "4175.0", "Tần Suất % (Jun Da)": "99.7923624511", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 鲜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹鲜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藓", "Unihan_Traditional (Chữ Phồn thể)": "蘚", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài rêu hoặc thực vật cấp thấp bám trên đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璜', '{"9000": "4176.0", "Chữ Trung Quốc": "璜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 𤣩 | ngọc | biểu nghĩa | ngọc, đá quý | 黃 | hoàng | biểu âm | 璜 = 𤣩/玉 (Ngọc, biểu nghĩa: ngọc, đá quý) + 黃 (Hoàng, biểu âm); chữ hình thanh. Phần ngọc cho biết đây là đồ vật bằng ngọc; phần Hoàng gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": ngọc (玉) màu hoàng (黃) hình bán nguyệt — lễ khí hoàng ngọc. | Gương Hán-Việt | \"hoàng\" trong \"bán hoàng\" (半璜, tấm ngọc bán nguyệt) | Mở khoá kiến thức | Biết 璜 mở khoá từ cổ văn và lễ nghi 六瑞 (lục thụy), các loại ngọc tế lễ trong Chu Lễ.", "Tự nguyên_Xie": "Chữ hình thanh: 玉 (ngọc) biểu nghĩa, 黃 biểu âm. Nghĩa: tấm ngọc hình bán nguyệt dùng trong lễ nghi thời cổ. Theo Lễ ký, 璜 là một trong sáu loại ngọc lễ (六瑞): được dùng để tế Bắc phương (huyền vũ). Màu đen — phương Bắc theo Ngũ Hành. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viên ngọc đeo", "Hạng Tần Suất (Jun Da)": "4176.0", "Tần Suất % (Jun Da)": "99.7926048233", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璜", "Unihan_Traditional (Chữ Phồn thể)": "璜", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại ngọc bội trang sức thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铬', '{"9000": "4177.0", "Chữ Trung Quốc": "铬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铬 | các | tượng hình | crom (nguyên tố Cr) | 铬 là chữ phiên âm hiện đại: bộ 钅/金 (kim, biểu nghĩa: kim loại) + 各 (các, biểu âm gợi âm ''gè''). Chữ hình thanh, được tạo để phiên dịch tên nguyên tố Chromium sang Hán tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"các\": kim loại (钅) ''các'' màu sắc — crom nổi tiếng vì tạo ra nhiều màu trong hợp chất. | Gương Hán-Việt | \"các\" trong hoá học: 铬 = crom (Chromium, Cr) | Mở khoá kiến thức | Biết 铬 mở khoá từ hoá học 铬钢 (thép crom), 铬合金 (hợp kim crom), 镀铬 (mạ crom).", "Tự nguyên_Xie": "铬 là chữ tạo muộn để phiên âm tên nguyên tố hoá học Chromium (Cr, số hiệu 24). Cấu tạo: 钅 (kim loại, biểu nghĩa) + 各 (biểu âm, gợi âm gè). Chromium được đặt tên theo tiếng Hy Lạp ''chroma'' (màu sắc) vì các hợp chất của nó có màu sắc đa dạng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố crôm, Cr", "Hạng Tần Suất (Jun Da)": "4177.0", "Tần Suất % (Jun Da)": "99.7928471956", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铬", "Unihan_Traditional (Chữ Phồn thể)": "鉻", "Pinyin_Xie": "gè", "Âm Hán Việt_Xie": "các", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng độc lập hoặc làm định ngữ trong các thuật ngữ hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渥', '{"9000": "4178.0", "Chữ Trung Quốc": "渥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước | 屋 | ốc | biểu âm | 渥 = 氵(Thủy, biểu nghĩa: nước) + 屋 (Ốc, biểu âm); chữ hình thanh. Phần thủy cho biết liên quan đến chất lỏng/ẩm ướt; phần Ốc gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ốc\": nước (氵) thấm vào mái ốc (屋) — ân nghĩa thấm sâu như mưa thấm nhà. | Gương Hán-Việt | \"ốc\" trong \"ốc ân\" (渥恩, ân sủng dày dặn) | Mở khoá kiến thức | Biết 渥 mở khoá từ cổ văn 渥恩 (ân sủng sâu dày), 渥丹 (màu đỏ đậm — tên địa danh Hoa Kỳ Wuhan dịch âm).", "Tự nguyên_Xie": "Chữ hình thanh: 氵 (nước) biểu nghĩa, 屋 biểu âm. Nghĩa gốc: thấm ướt, bôi phết (chất lỏng vào bề mặt). Nghĩa phái sinh: đậm đà, nồng hậu (trong thơ văn cổ chỉ ân đức sâu dày của vua ban cho bề tôi — 渥恩, ân sủng dày dặn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấm ướt; bôi, phết", "Hạng Tần Suất (Jun Da)": "4178.0", "Tần Suất % (Jun Da)": "99.7933314232", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 屋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵屋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渥", "Unihan_Traditional (Chữ Phồn thể)": "渥", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ trong văn viết cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靼', '{"9000": "4179.0", "Chữ Trung Quốc": "靼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 14 | nét | 靼 | đát | tượng hình | da mềm; thành phần trong 韃靼 (Tatar) | Chữ 靼 có bộ 革 (cách, da thuộc) biểu nghĩa và phần biểu âm. Cấu tạo đầy đủ chưa rõ trong nguồn học thuật; nghĩa chính là da thuộc mềm, và được dùng trong từ 韃靼 (Tatar — tên dân tộc du mục).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đát\": da thuộc (革) mềm của ''đát đát'' (韃靼) — người Tatar du mục cưỡi ngựa mặc da. | Gương Hán-Việt | \"đát\" trong \"đát đát\" (韃靼, người Tatar) | Mở khoá kiến thức | Biết 靼 mở khoá từ 韃靼 (Tatar), 韃靼海峽 (eo biển Tartary), 韃靼斯坦 (Tatarstan).", "Tự nguyên_Xie": "Wiktionary ghi nhận 靼 nghĩa là da mềm (soft leather). Có bộ 革 (da thuộc, cách). Nổi bật nhất qua từ 韃靼 (dá dá) — phiên âm Hán tự cho Tatar/Tartar, tên các dân tộc du mục Mông Cổ và Trung Á. Ngày nay còn trong địa danh 韃靼海峽 (eo biển Tartary, Nga-Nhật), 韃靼斯坦 (Tatarstan). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thát đát 韃靼)", "Hạng Tần Suất (Jun Da)": "4179.0", "Tần Suất % (Jun Da)": "99.7935732787", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靼", "Unihan_Traditional (Chữ Phồn thể)": "靼", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép để chỉ một tộc người cổ hoặc da đã thuộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酗', '{"9000": "4180.0", "Chữ Trung Quốc": "酗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 11 | nét | 酉 | dậu | biểu nghĩa | bình rượu, rượu | 凶 | hung | biểu âm | hung dữ, xấu | 酗 = 酉 (Dậu, biểu nghĩa: rượu) + 凶 (Hung, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 酉 cho nghĩa, 凶 cho âm xù. Có yếu tố ngữ nghĩa: 凶 (hung dữ) gợi cảnh người say rượu nổi hung. Chữ hình thanh có tính gợi ý mạnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hú\": rượu (酉) gặp hung dữ (凶) — uống say đến nổi loạn, hung hãn; 酗酒 là nát rượu. | Gương Hán-Việt | \"hú\" trong 酗酒 (hú tửu — nát rượu, uống rượu quá mức) | Mở khoá kiến thức | Biết 酗 mở khoá 酗酒 (nát rượu, nghiện rượu), 酗酒者 (người nghiện rượu).", "Tự nguyên_Xie": "Lục thư thông | Chữ 酗 (hú) là chữ hình thanh (ls=psc): bộ 酉 (Dậu — bình rượu) biểu nghĩa; 凶 (Hung) biểu âm xù. Wiktionary xác nhận dạng cổ là 䣱 trong Thuyết Văn (Shuowen). Hình lục thư thông được lưu tại hanziyuan.net. Nghĩa: uống rượu say mèm đến mức nổi hung; tình trạng nghiện rượu. Thường gặp trong 酗酒 (rượu chè be bét). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nát rượu, say rượu", "Hạng Tần Suất (Jun Da)": "4180.0", "Tần Suất % (Jun Da)": "99.7938146173", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 凶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉凶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酗", "Unihan_Traditional (Chữ Phồn thể)": "酗", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "hú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ liên kết với danh từ chỉ rượu để tạo thành cụm động tân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苓', '{"9000": "4181.0", "Chữ Trung Quốc": "苓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苓 | linh | tượng hình | nấm phục linh; cây cỏ linh | Chữ 苓 có bộ 艹 (thảo, cỏ thực vật) gợi nghĩa thực vật/nấm. Cấu tạo đầy đủ chưa rõ trong nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": cỏ (艹) linh thiêng — phục linh (茯苓) là nấm thuốc linh hồn của Đông y. | Gương Hán-Việt | \"linh\" trong \"phục linh\" (茯苓, nấm phục linh), \"linh chi\" (灵芝 — tương tự) | Mở khoá kiến thức | Biết 苓 mở khoá từ Đông y 茯苓 (phục linh), 猪苓 (trư linh — nấm thuốc khác), 苓桂 (linh quế — bài thuốc cổ).", "Tự nguyên_Xie": "Wiktionary ghi nhận 苓 liên quan đến các loại cây và nấm. Nổi bật nhất là 茯苓 (phục linh — Poria cocos, nấm phục linh), một vị thuốc quan trọng trong Đông y. Bộ 艹 (thảo) biểu nghĩa thực vật. Chưa có nguồn học thuật xác nhận cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây nấm", "Hạng Tần Suất (Jun Da)": "4181.0", "Tần Suất % (Jun Da)": "99.794055956", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苓", "Unihan_Traditional (Chữ Phồn thể)": "苓", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trong tên các loại thảo dược hoặc kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噤', '{"9000": "4182.0", "Chữ Trung Quốc": "噤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 噤 | gặm | tượng hình | ngậm miệng, run rẩy | Chữ 噤 có bộ 口 (khẩu, miệng) biểu nghĩa. Cấu tạo đầy đủ chưa rõ trong nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gặm\": miệng (口) ''gặm'' chặt vào nhau vì rét — run ''gặm răng'' ngậm thinh không nói. | Gương Hán-Việt | \"gặm\" trong \"gặm thanh\" (噤声, im lặng, ngậm miệng) | Mở khoá kiến thức | Biết 噤 mở khoá từ 噤声 (im lặng), 冷噤 (cơn rùng mình lạnh), thành ngữ 噤若寒蝉 (im như thóc vì sợ).", "Tự nguyên_Xie": "Wiktionary ghi nhận 噤 có hai nghĩa: (1) ngậm miệng, im lặng không nói được; (2) run rẩy, răng đập vào nhau (vì lạnh hoặc sợ). Bộ 口 (miệng) biểu nghĩa. Dùng trong 噤声 (im lặng), 冷噤 (rùng mình lạnh), 噤若寒蝉 (thành ngữ — im lặng như ve mùa đông, sợ không dám nói). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoá miệng", "Hạng Tần Suất (Jun Da)": "4182.0", "Tần Suất % (Jun Da)": "99.7942972946", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 禁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口禁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噤", "Unihan_Traditional (Chữ Phồn thể)": "噤", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "cấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc đứng độc lập để chỉ hành động im lặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咫', '{"9000": "4183.0", "Chữ Trung Quốc": "咫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 尺 | xích | biểu nghĩa | thước đo, đơn vị chiều dài | 只 | chỉ | biểu âm | 咫 = 尺 (Xích, biểu nghĩa: thước đo) + 只 (Chỉ, biểu âm); chữ hình thanh. Phần xích cho biết đây là đơn vị đo chiều dài; phần Chỉ gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": thước (尺) ''chỉ'' một khoảng tay — 咫尺 gần nhau trong tầm tay với. | Gương Hán-Việt | \"chỉ\" trong \"chỉ xích\" (咫尺, khoảng cách rất gần) | Mở khoá kiến thức | Biết 咫 mở khoá thành ngữ 咫尺天涯 (chỉ xích thiên nhai — gần trong gang tấc mà xa như trời biển), 近在咫尺 (rất gần).", "Tự nguyên_Xie": "Chữ hình thanh: 尺 (thước) biểu nghĩa, 只 biểu âm. Nghĩa: đơn vị đo chiều dài thời Chu, bằng 8 thốn (寸), tức khoảng 18–23 cm — bằng khoảng độ rộng của bàn tay. Thường dùng trong thành ngữ 咫尺 (chỉ xích) với nghĩa ''khoảng cách rất gần'' hoặc ngược lại ''khoảng cách dù gần vẫn như xa — cách trở''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỉ (đơn vị đo đời Chu, bằng 8 tấc)", "Hạng Tần Suất (Jun Da)": "4183.0", "Tần Suất % (Jun Da)": "99.7945381165", "GavinGrover_Once (Chiết tự trực tiếp)": "尺 + 只", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尺只", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "只", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尺", "Unihan_Simplified (Chữ Giản thể)": "咫", "Unihan_Traditional (Chữ Phồn thể)": "咫", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ đo chiều dài thời cổ hoặc làm danh từ trong các thành ngữ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椿', '{"9000": "4184.0", "Chữ Trung Quốc": "椿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 椿 | xuân | tượng hình | cây xuân (Toona sinensis) | Chữ 椿 có bộ 木 (mộc, cây gỗ) biểu nghĩa. Cấu tạo đầy đủ chưa rõ trong nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuân\": cây (木) mùa xuân (春) — đại xuân Trang Tử sống nghìn năm, tượng trưng cha trường thọ. | Gương Hán-Việt | \"xuân\" trong \"đại xuân\" (大椿, cây đại xuân Trang Tử), \"xuân đường\" (椿堂, kính xưng cha) | Mở khoá kiến thức | Biết 椿 mở khoá từ 椿树 (cây toon), 椿萱 (xuân huyên — cha và mẹ), 大椿 (đại xuân — tượng trưng cha sống lâu).", "Tự nguyên_Xie": "Wiktionary ghi nhận 椿 là loài cây Chinese toon (Toona sinensis). Bộ 木 (cây). Tên Hán-Việt ''xuân'' (春-liên quan mùa xuân) gợi đặc điểm cây ra lá non vào mùa xuân — lá non ăn được, có hương thơm đặc trưng trong ẩm thực Trung Hoa. Trong Trang Tử có hình tượng cây đại xuân (大椿) sống hàng nghìn năm — ẩn dụ cho sự trường thọ của cha. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây xuân", "Hạng Tần Suất (Jun Da)": "4184.0", "Tần Suất % (Jun Da)": "99.7947784216", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 春", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木春", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "春", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椿", "Unihan_Traditional (Chữ Phồn thể)": "椿", "Pinyin_Xie": "chūn", "Âm Hán Việt_Xie": "xuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập chỉ loài cây hoặc dùng trong văn chương để ẩn dụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲫', '{"9000": "4185.0", "Chữ Trung Quốc": "鲫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鲫 | tức | tượng hình | cá diếc | Chữ 鲫 có bộ 鱼/魚 (ngư, cá) biểu nghĩa. Phần còn lại gợi âm. Chữ hình thanh chỉ loài cá diếc (Carassius auratus gibelio). Cấu tạo đầy đủ chưa rõ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tức\": cá (鱼) ''tức'' trong ao — cá diếc tức tốc bơi trong ao làng. | Gương Hán-Việt | \"tức\" trong \"cá tức\" (鲫鱼, cá diếc) | Mở khoá kiến thức | Biết 鲫 mở khoá từ 鲫鱼 (cá diếc), 鲫鱼汤 (canh cá diếc — bài thuốc dân gian), 金鲫 (cá vàng).", "Tự nguyên_Xie": "鲫 là chữ hình thanh với bộ 鱼 (cá) biểu nghĩa. Nghĩa: cá diếc — loài cá nước ngọt phổ biến ở Đông Á (Carassius auratus), tổ tiên của cá vàng cảnh. Cá diếc là thực phẩm dân dã phổ biến ở Trung Quốc. Cấu tạo đầy đủ chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá diếc", "Hạng Tần Suất (Jun Da)": "4185.0", "Tần Suất % (Jun Da)": "99.7950182099", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 即", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼即", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "即", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲫", "Unihan_Traditional (Chữ Phồn thể)": "鯽", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ trong các món ăn liên quan đến cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锭', '{"9000": "4186.0", "Chữ Trung Quốc": "锭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 定 | định | biểu âm | 锭 = 钅/金 (Kim, biểu nghĩa: kim loại) + 定 (Định, biểu âm); chữ hình thanh. Phần kim cho biết đây là vật phẩm kim loại; phần Định gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": kim loại (钅) đúc thành thỏi ''định'' hình — thỏi vàng bạc đính. | Gương Hán-Việt | \"đính\" trong \"kim đính\" (金锭, thỏi vàng), \"ngân đính\" (银锭, thỏi bạc) | Mở khoá kiến thức | Biết 锭 mở khoá từ 金锭 (thỏi vàng), 银锭 (thỏi bạc), 碘锭 (viên iốt), 锭子 (con thoi dệt vải).", "Tự nguyên_Xie": "Chữ hình thanh: 钅 (kim loại) biểu nghĩa, 定 biểu âm. Nghĩa gốc: thoi vàng bạc đúc thành khối hình thuyền — đơn vị tiền tệ hoặc dự trữ kim loại quý thời xưa. Cũng chỉ con thoi dệt vải (hình dạng tương tự). Ngày nay thường dùng trong từ ghép hóa học như 碘锭 (viên iốt) hoặc đơn vị đếm kim loại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thoi vàng, thoi bạc; con thoi dệt vải", "Hạng Tần Suất (Jun Da)": "4186.0", "Tần Suất % (Jun Da)": "99.7952564479", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锭", "Unihan_Traditional (Chữ Phồn thể)": "錠", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ thỏi kim loại quý hoặc làm lượng từ cho các vật có hình thỏi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罔', '{"9000": "4187.0", "Chữ Trung Quốc": "罔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 8 | nét | 网 | võng | biểu nghĩa | cái lưới | 亡 | vong | biểu âm | 罔 = 网 (Võng, biểu nghĩa: cái lưới) + 亡 (Vong, biểu âm); chữ hình thanh. Phần võng gợi ý nghĩa lưới bẫy; phần vong gợi âm. Nghĩa mở rộng: lừa dối (giăng bẫy người), không có (như lưới rỗng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"võng\": lưới (网) ''vong'' mất đi — kẻ gian giăng lưới rồi ''võng'' không nhận tội. | Gương Hán-Việt | \"vóng\" trong \"võng cực\" (罔极, vô cùng), \"trí nhược võng văn\" (置若罔闻, làm lơ) | Mở khoá kiến thức | Biết 罔 mở khoá từ cổ văn 罔顾 (bất chấp), 置若罔闻 (làm như không nghe), 欺罔 (lừa dối).", "Tự nguyên_Xie": "Chữ hình thanh: 网 (lưới) biểu nghĩa, 亡 biểu âm. Nghĩa gốc: cái lưới. Phái sinh: (1) vu khống, lừa dối — giăng lưới hãm hại người; (2) không có, vô (cổ ngữ) — 罔极 (vô cùng), 置若罔闻 (làm như không nghe). Dùng nhiều trong cổ văn và thành ngữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1202.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Võng (122) Vong (173)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vong (số 173 - mất mát/chỉ âm) nằm bên trong chữ Võng (số 122 - cái lưới/ 罒 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vong chỉ âm, chữ Võng chỉ ý. Võng là cái lưới để bắt chim bắt cá. Cũng có ý chỉ sự mê muội, dối trá, hoặc không có.", "Nghĩa Tiếng Việt_Xie": "cái lưới; vu khống, lừa", "Hạng Tần Suất (Jun Da)": "4187.0", "Tần Suất % (Jun Da)": "99.7954946858", "GavinGrover_Once (Chiết tự trực tiếp)": "冂 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "罔", "Unihan_Traditional (Chữ Phồn thể)": "㒺", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Danh từ | 名词 | Thường làm phó từ phủ định đứng trước động từ hoặc làm động từ mang nghĩa lừa gạt. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锺', '{"9000": "4188.0", "Chữ Trung Quốc": "锺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 锺 | chung | tượng hình | tên riêng; chén rượu; tụ lại | 锺 là dạng giản thể đặc biệt của 鍾, chỉ dùng cho tên riêng (họ Chung). Phồn thể 鍾 = 金 (kim, kim loại) + 重 (trọng, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chung\": kim loại (金) ''chung'' đúc thành chén — họ Chung nổi tiếng trong lịch sử. | Gương Hán-Việt | \"chung\" trong \"chung tình\" (锺情, dốc lòng yêu), \"họ Chung\" (锺氏) | Mở khoá kiến thức | Biết 锺 mở khoá họ Chung (钟/锺 氏), 锺情 (dốc lòng yêu thương), và hiểu sự phân biệt 锺/钟 trong tiếng Trung.", "Tự nguyên_Xie": "锺 là giản thể của 鍾, nhưng chỉ dùng khi viết tên họ hoặc tên riêng — không phải dạng giản thể thông dụng của 鍾 (dùng 钟 cho mục đích thông thường). Phồn thể 鍾: 金 (kim loại) biểu nghĩa + 重 biểu âm. Nghĩa gốc: chén uống rượu bằng kim loại. Phái sinh: tụ hợp (锺情 — dồn tình cảm). Chủ yếu dùng như họ: 锺 (Chung). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chén uống rượu; tụ hợp lại; họ Chung", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 重", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅重", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "重", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锺", "Unihan_Traditional (Chữ Phồn thể)": "锺", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "chung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ chén rượu hoặc động từ với nghĩa tích tụ, tập trung tình cảm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匍', '{"9000": "4189.0", "Chữ Trung Quốc": "匍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 9 | nét | 勹 | bão | biểu nghĩa | bao bọc, hình người cúi | 甫 | phủ | biểu âm | 匍 = 勹 (Bão, biểu nghĩa: hình người cúi khom) + 甫 (Phủ, biểu âm); chữ hình thanh. Phần 勹 gợi hình dáng người bò sát đất; phần 甫 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bò\": người (勹) cúi thấp như 甫 — 匍匐 là bò trườn sát đất. | Gương Hán-Việt | \"bò\" trong \"bò bặc\" (匍匐, bò trườn sát đất) | Mở khoá kiến thức | Biết 匍 mở khoá từ 匍匐 (bò sát đất, trườn), 匍匐前进 (tiến lên bằng cách trườn).", "Tự nguyên_Xie": "Chữ hình thanh: 勹 (người cúi) biểu nghĩa, 甫 biểu âm. Nghĩa: bò, trườn sát đất. Chữ gần như chỉ xuất hiện trong từ ghép 匍匐 (pú fú — bò, trườn), miêu tả chuyển động cơ thể sát mặt đất như bò trẻ em hoặc người lính trườn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bồ bặc 匍匐)", "Hạng Tần Suất (Jun Da)": "4189.0", "Tần Suất % (Jun Da)": "99.7959706449", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "匍", "Unihan_Traditional (Chữ Phồn thể)": "匍", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ bặc tạo thành từ ghép để chỉ hành động bò trườn bằng tay chân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祗', '{"9000": "4190.0", "Chữ Trung Quốc": "祗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 示 | thị | biểu nghĩa | thần linh, tế lễ | 氐 | đê | biểu âm | 祗 = 示 (Thị, biểu nghĩa: thần linh, tế lễ) + 氐 (Đê, biểu âm); chữ hình thanh. Phần thị cho biết liên quan đến kính sợ thần thánh; phần 氐 gợi âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": trước thần (示) cúi đầu kính ''kỳ'' — lòng kỳ kính cẩn như trước tế đàn. | Gương Hán-Việt | \"kỳ\" trong \"kỳ kính\" (祗敬, cung kính) | Mở khoá kiến thức | Biết 祗 mở khoá từ cổ văn 祗敬 (kỳ kính — kính cẩn), 祗承 (vâng mệnh kính cẩn), hiểu văn bản Hán cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 示 (thần linh/tế lễ) biểu nghĩa, 氐 biểu âm. Nghĩa: cung kính, kính trọng — đặc biệt là thái độ kính cẩn trước thần thánh hoặc bậc trên. Dùng trong cổ văn và thơ văn Hán. Đôi khi nhầm với 祇 (kỳ — cũng nghĩa thần đất). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cung kính, kính trọng", "Hạng Tần Suất (Jun Da)": "4190.0", "Tần Suất % (Jun Da)": "99.7962083661", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祗", "Unihan_Traditional (Chữ Phồn thể)": "祗", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Thường làm phó từ đứng trước động từ để biểu thị sự tôn kính hoặc giới hạn duy nhất. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锰', '{"9000": "4191.0", "Chữ Trung Quốc": "锰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại | 孟 | mạnh | biểu âm | 锰 = 钅/金 (Kim, biểu nghĩa: kim loại) + 孟 (Mạnh, biểu âm); chữ hình thanh. Phần kim cho biết đây là kim loại; phần Mạnh gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạnh\": kim loại (钅) của người ''mạnh'' Mạnh Tử (孟) — mangan mạnh mẽ trong thép. | Gương Hán-Việt | \"mạnh\" trong hoá học: 锰 = mangan (Mn) | Mở khoá kiến thức | Biết 锰 mở khoá từ hoá học 锰钢 (thép mangan), 二氧化锰 (mangan điôxít), 高锰酸钾 (kali permanganat).", "Tự nguyên_Xie": "锰 là chữ tạo muộn để phiên âm tên nguyên tố Manganese (Mn, số hiệu 25). Cấu tạo: 钅 (kim loại, biểu nghĩa) + 孟 (biểu âm, gợi âm měng). Mangan được đặt tên theo vùng Magnesia ở Hy Lạp. Chữ tạo muộn trong thời hiện đại, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố mangan, Mn", "Hạng Tần Suất (Jun Da)": "4191.0", "Tần Suất % (Jun Da)": "99.7964455704", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 孟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅孟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锰", "Unihan_Traditional (Chữ Phồn thể)": "錳", "Pinyin_Xie": "měng", "Âm Hán Việt_Xie": "mãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ đứng độc lập hoặc làm định ngữ trong các thuật ngữ hóa học và luyện kim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岌', '{"9000": "4192.0", "Chữ Trung Quốc": "岌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 6 | nét | 山 | sơn | biểu nghĩa | núi | 及 | cập | biểu âm | 岌 = 山 (Sơn, biểu nghĩa: núi) + 及 (Cập, biểu âm); chữ hình thanh. Phần sơn cho biết liên quan đến núi/đỉnh cao; phần cập gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngập\": núi (山) ''ngập'' ngập trong nguy hiểm — 岌岌可危 như đỉnh núi sắp sụp. | Gương Hán-Việt | \"ngập\" trong \"ngập ngập khả nguy\" (岌岌可危, nguy hiểm cực kỳ) | Mở khoá kiến thức | Biết 岌 mở khoá thành ngữ 岌岌可危 (đang ở tình trạng vô cùng nguy hiểm).", "Tự nguyên_Xie": "Chữ hình thanh: 山 (núi) biểu nghĩa, 及 biểu âm. Nghĩa: núi cao chót vót, đỉnh núi nguy hiểm. Dùng chủ yếu trong từ ghép 岌岌 (ngập ngập) với nghĩa hiểm nguy, lung lay sắp đổ — đặc biệt trong thành ngữ 岌岌可危 (ngập ngập khả nguy: đang ở tình trạng nguy hiểm cực kỳ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao ngất", "Hạng Tần Suất (Jun Da)": "4192.0", "Tần Suất % (Jun Da)": "99.796682258", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岌", "Unihan_Traditional (Chữ Phồn thể)": "岌", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "ngập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ ghép để miêu tả trạng thái nguy kịch, không vững chãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馀', '{"9000": "4193.0", "Chữ Trung Quốc": "馀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 10 | nét | 馀 | dư | tượng hình | thừa, dư; ngoài ra | 馀 là dạng giản thể đặc biệt của 餘, chỉ dùng cho tên riêng (họ Dư). Phồn thể 餘 = 食 (thực, ăn) + 余 (dư, biểu âm); chữ hình thanh. Dạng giản thể thông dụng là 余.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dư\": ăn (食) ''dư'' còn thừa lại — người họ Dư mang theo ''sự dư dả''. | Gương Hán-Việt | \"dư\" trong \"dư thừa\" (余/馀, thừa ra), \"dư địa\" (余地, không gian còn lại) | Mở khoá kiến thức | Biết 馀/余 mở khoá từ 余地 (dư địa, chỗ còn lại), 余额 (số dư), 余波 (dư ba — hậu quả kéo dài), 业余 (nghiệp dư).", "Tự nguyên_Xie": "馀 là giản thể của 餘 nhưng chỉ dùng khi cần phân biệt họ 餘 khỏi họ 余. Phồn thể 餘: 食 (ăn uống) biểu nghĩa + 余 biểu âm. Nghĩa gốc: thức ăn còn dư lại sau bữa, sau đó mở rộng thành ''thừa ra, dư dả, ngoài ra''. Trong tiếng Trung hiện đại, 余 là dạng giản thể thông dụng; 馀 chỉ xuất hiện như họ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thừa; ngoài ra, thừa ra; nhàn rỗi; số lẻ ra; họ Dư", "Hạng Tần Suất (Jun Da)": "4193.0", "Tần Suất % (Jun Da)": "99.7969184288", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 余", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馀", "Unihan_Traditional (Chữ Phồn thể)": "餘", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Số từ | 数词 | Thường đứng sau số từ để chỉ số lượng ước lượng hoặc làm tính từ bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畹', '{"9000": "4194.0", "Chữ Trung Quốc": "畹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 13 | nét | 田 | điền | biểu nghĩa | ruộng, cánh đồng | 宛 | uyển | biểu âm | 畹 = 田 (Điền, biểu nghĩa: ruộng, cánh đồng) + 宛 (Uyển, biểu âm); chữ hình thanh. Phần điền cho biết đây là đơn vị đo diện tích ruộng; phần uyển gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": ruộng (田) cong ''uyển chuyển'' —畹町 thị trấn biên giới ruộng uốn khúc. | Gương Hán-Việt | \"uyển\" trong \"畹町\" (Wan Ding, địa danh Vân Nam) | Mở khoá kiến thức | Biết 畹 mở khoá từ 畹町 (địa danh Vân Nam nổi tiếng) và hiểu thơ Ly Tao của Khuất Nguyên.", "Tự nguyên_Xie": "Chữ hình thanh: 田 (ruộng) biểu nghĩa, 宛 biểu âm. Nghĩa: đơn vị đo diện tích ruộng thời cổ, bằng 20-30 mẫu (畝). Xuất hiện trong Kinh Sở (Ly Tao của Khuất Nguyên): 余既滋兰之九畹兮 (ta đã trồng lan chín畹). Ngày nay 畹 hầu như chỉ dùng trong địa danh 畹町 (Wan Ding — thị trấn ở Vân Nam). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ruộng hai mẫu", "Hạng Tần Suất (Jun Da)": "4194.0", "Tần Suất % (Jun Da)": "99.7971545997", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畹", "Unihan_Traditional (Chữ Phồn thể)": "畹", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ đo diện tích ruộng đất trong văn thơ cổ. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糯', '{"9000": "4195.0", "Chữ Trung Quốc": "糯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 20 | nét | 糯 | nhu | tượng hình | gạo nếp, mềm dẻo | Chữ 糯 có bộ 米 (mễ, gạo) biểu nghĩa, gợi liên quan đến gạo/lúa. Cấu tạo đầy đủ chưa rõ trong nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": gạo (米) ''nhu'' mềm dẻo — gạo nếp nhu nhuyễn khi nấu xôi. | Gương Hán-Việt | \"nhu\" trong \"nhu mễ\" (糯米, gạo nếp) | Mở khoá kiến thức | Biết 糯 mở khoá từ 糯米 (gạo nếp), 糯米酒 (rượu nếp), 糯米饭 (xôi), 糯玉米 (ngô nếp).", "Tự nguyên_Xie": "Wiktionary ghi nhận 糯 nghĩa là gạo nếp (glutinous rice). Bộ 米 (gạo). Đặc trưng của gạo nếp là dẻo và dính khi nấu. Dùng trong 糯米 (gạo nếp), 糯米酒 (rượu nếp), 糯玉米 (ngô nếp). Cấu tạo đầy đủ chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo nếp để cất rượu", "Hạng Tần Suất (Jun Da)": "4195.0", "Tần Suất % (Jun Da)": "99.7973897369", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糯", "Unihan_Traditional (Chữ Phồn thể)": "稬", "Pinyin_Xie": "nuò", "Âm Hán Việt_Xie": "nhu, noạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ gạo nếp hoặc làm định ngữ bổ nghĩa cho các món ăn làm từ nếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胫', '{"9000": "4196.0", "Chữ Trung Quốc": "胫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 肉 | nhục | biểu nghĩa | thịt, bộ phận cơ thể | 巠 | kinh | biểu âm | 胫 = 月/肉 (Nhục, biểu nghĩa: thịt, bộ phận cơ thể) + 巠 (Kinh, biểu âm); chữ hình thanh. Phần nhục cho biết đây là bộ phận cơ thể; phần 巠 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kinh\": thịt (月) cẳng ''kinh'' chạy — 不胫而走 nhanh như tin tức bay. | Gương Hán-Việt | \"kinh\" trong \"bất kinh nhi tẩu\" (不胫而走, lan truyền nhanh) | Mở khoá kiến thức | Biết 胫 mở khoá từ 胫骨 (xương chày), thành ngữ 不胫而走 (tin đồn lan nhanh không cần ai loan truyền).", "Tự nguyên_Xie": "Chữ hình thanh: 月/肉 (cơ thể) biểu nghĩa, 巠 biểu âm. Nghĩa: cẳng chân — phần chân từ đầu gối xuống mắt cá chân. Dùng trong thành ngữ 不胫而走 (bất kinh nhi tẩu — không có chân mà chạy, tức lan truyền nhanh) và từ giải phẫu 胫骨 (xương chày). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cẳng chân", "Hạng Tần Suất (Jun Da)": "4196.0", "Tần Suất % (Jun Da)": "99.7976248741", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "胫", "Unihan_Traditional (Chữ Phồn thể)": "脛", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "hĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận cơ thể, thường xuất hiện trong các thành ngữ liên quan đến chân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熠', '{"9000": "4197.0", "Chữ Trung Quốc": "熠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 15 | nét | 火 | hoả | biểu nghĩa | lửa, ánh sáng | 習 | tập | biểu âm | 熠 = 火 (Hoả, biểu nghĩa: lửa, ánh sáng) + 習 (Tập, biểu âm); chữ hình thanh. Phần hoả cho biết liên quan đến ánh sáng; phần Tập gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dập\": lửa (火) ''dập dìu'' nhấp nháy — 熠熠生辉 ánh sáng dập dìu rực rỡ. | Gương Hán-Việt | \"dập\" trong \"dập dập sinh huy\" (熠熠生辉, tỏa sáng lấp lánh) | Mở khoá kiến thức | Biết 熠 mở khoá từ 熠熠 (lấp lánh nhấp nháy), 熠熠生辉 (toả sáng rực rỡ).", "Tự nguyên_Xie": "Chữ hình thanh: 火 (lửa/ánh sáng) biểu nghĩa, 習 biểu âm. Nghĩa: sáng lấp lánh, nhấp nháy. Dùng trong từ ghép 熠熠 (sáng nhấp nháy), 熠熠生辉 (tỏa sáng lấp lánh — mô tả vẻ đẹp rực rỡ của ngọc ngà, sao trời, mắt đẹp). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng nhấp nháy", "Hạng Tần Suất (Jun Da)": "4197.0", "Tần Suất % (Jun Da)": "99.7978600114", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 習", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火習", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "習", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熠", "Unihan_Traditional (Chữ Phồn thể)": "熠", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ diệu tạo thành từ ghép để miêu tả ánh sáng lấp lánh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銮', '{"9000": "4198.0", "Chữ Trung Quốc": "銮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銮 | loan | tượng hình | chuông nhỏ trên xe ngựa vua; xe vua | 銮 là giản thể của 鑾. Phồn thể 鑾 = 龻 (phần trên, gợi âm) + 金 (kim, kim loại ở dưới, biểu nghĩa); chữ hình thanh. Chỉ chuông nhỏ gắn trên xe vua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": kim loại (金) kêu ''loan loan'' — chuông nhỏ trên xe vua tiếng keng keng. | Gương Hán-Việt | \"loan\" trong \"loan giá\" (銮驾, xe vua), \"loan điện\" (銮殿, điện vua) | Mở khoá kiến thức | Biết 銮 mở khoá từ cung đình 銮驾 (xe vua), 銮殿 (điện vua), 銮铃 (chuông loan trên xe vua).", "Tự nguyên_Xie": "銮 là giản thể của 鑾. Nghĩa: chuông nhỏ bằng kim loại gắn trên xe ngựa của hoàng đế, phát ra tiếng keng keng khi xe chạy. Từ đó 銮驾/鑾駕 (loan giá) chỉ xe vua — tiếng chuông loan như hiệu lệnh thiên tử. Dùng trong địa danh 承德避暑山庄, 銮殿 (điện loan). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chuông", "Hạng Tần Suất (Jun Da)": "4198.0", "Tần Suất % (Jun Da)": "99.7980951486", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銮", "Unihan_Traditional (Chữ Phồn thể)": "鑾", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép liên quan đến vua chúa hoặc nghi lễ hoàng gia. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沅', '{"9000": "4199.0", "Chữ Trung Quốc": "沅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thủy | biểu nghĩa | nước, sông | 元 | nguyên | biểu âm | 沅 = 氵(Thủy, biểu nghĩa: nước) + 元 (Nguyên, biểu âm); chữ hình thanh. Phần thủy cho biết đây là tên sông; phần nguyên gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyên\": nước (氵) chảy từ ''nguyên'' nguồn — sông Nguyên quê hương Khuất Nguyên. | Gương Hán-Việt | \"nguyên\" trong \"Nguyên giang\" (沅江, sông Nguyên ở Hồ Nam) | Mở khoá kiến thức | Biết 沅 mở khoá địa danh 沅江 (sông Nguyên), 沅陵 (huyện Nguyên Lăng), và hiểu thơ Khuất Nguyên.", "Tự nguyên_Xie": "Chữ hình thanh: 氵(nước) biểu nghĩa, 元 biểu âm. Là tên riêng chỉ sông Nguyên (沅江/沅水) — một trong những con sông lớn ở tỉnh Hồ Nam, đổ vào hồ Động Đình. Sông Nguyên nổi tiếng qua thơ Khuất Nguyên: 沅有芷兮澧有兰 (Sông Nguyên có bạch chỉ, sông Lễ có lan). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Nguyên", "Hạng Tần Suất (Jun Da)": "4199.0", "Tần Suất % (Jun Da)": "99.798329769", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沅", "Unihan_Traditional (Chữ Phồn thể)": "沅", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "nguyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh hoặc tên sông nước cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棣', '{"9000": "4200.0", "Chữ Trung Quốc": "棣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 隶 | lệ | biểu âm | 棣 = 木 (Mộc, biểu nghĩa: cây, gỗ) + 隶 (Lệ, biểu âm); chữ hình thanh. Phần mộc cho biết đây là loài cây; phần lệ gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": cây (木) đẹp như ''lệ'' — hoa thường đường lệ tượng trưng tình anh em lệ thuộc nhau. | Gương Hán-Việt | \"lệ\" trong \"thường lệ\" (常棣, cây thường đường lệ), \"lệnh lệ\" (令棣, em trai) | Mở khoá kiến thức | Biết 棣 mở khoá từ 棣棠 (cây Kerria), 常棣 (tình anh em Kinh Thi), 令棣 (cách gọi em trai lịch sự).", "Tự nguyên_Xie": "Chữ hình thanh: 木 (cây) biểu nghĩa, 隶 biểu âm. Nghĩa: cây đường lệ (Kerria japonica) hoặc cây anh đào. Xuất hiện nổi bật trong Kinh Thi: 常棣之华，鄂不韡韡 (花常棣 nở rộ — biểu tượng tình anh em gắn bó). Từ đó 棣 trở thành từ tôn xưng người anh em trai: 令棣 (em trai của anh/chị). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đường lệ 常棣)", "Hạng Tần Suất (Jun Da)": "4200.0", "Tần Suất % (Jun Da)": "99.7985643895", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 隶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木隶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棣", "Unihan_Traditional (Chữ Phồn thể)": "棣", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ loài cây hoặc làm tính từ trong từ ghép chỉ sự hòa nhã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旌', '{"9000": "4201.0", "Chữ Trung Quốc": "旌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 11 | nét | 㫃 | biểu nghĩa | cờ, phướn (bộ cờ hiệu) | 生 | sinh | biểu âm | 旌 = 㫃 (bộ cờ/phướn, biểu nghĩa: cờ hiệu) + 生 (Sinh, biểu âm); chữ hình thanh. Phần 㫃 cho biết đây là loại cờ; phần sinh gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": cờ (㫃) mọc lên ''tinh'' anh — cờ tinh biểu dương người xuất sắc. | Gương Hán-Việt | \"tinh\" trong \"tinh biểu\" (旌表, biểu dương), \"tinh kỳ\" (旌旗, cờ xí) | Mở khoá kiến thức | Biết 旌 mở khoá từ 旌旗 (cờ xí), 旌表 (biểu dương, khen thưởng), 旌别 (phân biệt, nhận biết).", "Tự nguyên_Xie": "Chữ hình thanh: 㫃 (cờ) biểu nghĩa, 生 biểu âm. Nghĩa gốc: cờ tinh — loại cờ trên đỉnh cắm lông chim, dùng trong quân đội cổ đại để ra hiệu và chỉ huy. Nghĩa phái sinh: biểu dương, công nhận (旌表 — biểu dương); phân biệt, nhận ra (旌别 — phân biệt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ tinh (cờ trên có cắm lông, dùng khi đi xứ); tiêu biểu", "Hạng Tần Suất (Jun Da)": "4201.0", "Tần Suất % (Jun Da)": "99.79879901", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旌", "Unihan_Traditional (Chữ Phồn thể)": "旌", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ loại cờ lệnh hoặc làm động từ biểu thị sự khen ngợi công lao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豌', '{"9000": "4202.0", "Chữ Trung Quốc": "豌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豆 | Số nét | 15 | nét | 豆 | đậu | biểu nghĩa | đậu, hạt đậu | 宛 | uyển | biểu âm | 豌 = 豆 (Đậu, biểu nghĩa: đậu, hạt đậu) + 宛 (Uyển, biểu âm); chữ hình thanh. Phần đậu cho biết đây là loại đậu; phần uyển gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": đậu (豆) cong ''uyển'' tròn — hạt đậu Hà Lan tròn uyển chuyển trong vỏ. | Gương Hán-Việt | \"uyển\" trong \"uyển đậu\" (豌豆, đậu Hà Lan) | Mở khoá kiến thức | Biết 豌 mở khoá từ 豌豆 (đậu Hà Lan), 豌豆苗 (mầm đậu Hà Lan), 豌豆黄 (bánh đậu Hà Lan).", "Tự nguyên_Xie": "Chữ hình thanh: 豆 (đậu) biểu nghĩa, 宛 biểu âm. Nghĩa: đậu Hà Lan (Pisum sativum). Chữ này hầu như chỉ dùng trong từ ghép 豌豆 (đậu Hà Lan). Theo một số nguồn, ''Hà Lan'' (wān) trong 豌 bắt nguồn từ vùng Hoàn (Uyển) ở Tây Vực — nơi loài đậu này được nhập vào Trung Quốc thời Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một giống đậu)", "Hạng Tần Suất (Jun Da)": "4202.0", "Tần Suất % (Jun Da)": "99.7990331136", "GavinGrover_Once (Chiết tự trực tiếp)": "豆 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豆宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豆", "Unihan_Simplified (Chữ Giản thể)": "豌", "Unihan_Traditional (Chữ Phồn thể)": "豌", "Pinyin_Xie": "wān", "Âm Hán Việt_Xie": "oản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ khi kết hợp để chỉ cây đậu Hà Lan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孢', '{"9000": "4203.0", "Chữ Trung Quốc": "孢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 8 | nét | 孢 | bào | tượng hình | bào tử — đơn vị sinh sản của nấm, tảo, dương xỉ | 孢 là chữ tạo muộn, không tách được thành phần hình-thanh rõ ràng từ nguồn học thuật. Chữ mang bộ 子 (tử) nhưng không có anchor Wiktionary; chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": bào tử — hạt giống nhỏ li ti của nấm hay dương xỉ, nhỏ như đứa trẻ (子) nằm gọn trong vỏ bọc. | Gương Hán-Việt | \"bào\" xuất hiện trong \"bào tử\" (孢子) — đơn vị sinh sản của nấm, rêu, dương xỉ. | Mở khoá kiến thức | Biết 孢 mở khoá: 孢子 (bào tử), 孢子囊 (túi bào tử), 孢子体 (thể bào tử).", "Tự nguyên_Xie": "孢 là chữ tạo muộn dùng để phiên âm khái niệm khoa học ''spore'' (bào tử). Không tìm thấy glyph origin trong Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bào tử 孢子)", "Hạng Tần Suất (Jun Da)": "4203.0", "Tần Suất % (Jun Da)": "99.7992672173", "GavinGrover_Once (Chiết tự trực tiếp)": "子 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰子包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孢", "Unihan_Traditional (Chữ Phồn thể)": "孢", "Pinyin_Xie": "bāo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ trong các thuật ngữ sinh học liên quan đến bào tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镭', '{"9000": "4204.0", "Chữ Trung Quốc": "镭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 镭 | lôi | tượng hình | nguyên tố radi (Ra) — chữ giản thể của 鐳 | 镭 là chữ giản thể của 鐳, được tạo bằng cách thay bộ 釒 (kim) thành 钅. Chữ gốc 鐳 = 釒(kim, biểu nghĩa: kim loại) + 雷(lôi, biểu âm: sấm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lôi\": âm 雷 (sấm sét) liên tưởng radium — nguyên tố phóng xạ mạnh như tia sét, bộ 钅 cho biết đây là kim loại. | Gương Hán-Việt | \"lôi\" xuất hiện trong \"lôi\" (雷 — sấm), họ hàng âm đọc với 镭 (radium). | Mở khoá kiến thức | Biết 镭 mở khoá: 镭射 (laser — dùng ở Hồng Kông/Đài Loan), 镭-226, các tên nguyên tố phóng xạ trong khoa học.", "Tự nguyên_Xie": "镭 giản hóa từ 鐳. Chữ gốc 鐳 gồm 釒 (kim loại, biểu nghĩa) và 雷 (lôi — sấm, biểu âm). Được dùng để phiên âm tên nguyên tố radium (Ra) do Marie Curie phát hiện năm 1898. Chữ tạo muộn thời hiện đại, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố rađi, Ra", "Hạng Tần Suất (Jun Da)": "4204.0", "Tần Suất % (Jun Da)": "99.7995008042", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 雷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅雷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镭", "Unihan_Traditional (Chữ Phồn thể)": "鐳", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc trong từ ghép để chỉ nguyên tố phóng xạ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驸', '{"9000": "4205.0", "Chữ Trung Quốc": "驸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 驸 | phò | tượng hình | ngựa phụ kéo bên cạnh xe; phò mã | 驸 là chữ giản thể, bộ 马 (mã, biểu nghĩa: ngựa) kết hợp với 付 (phó, biểu âm). Chữ hình thanh. Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ dạng phồn thể 駙.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phò\": phò mã — chữ 驸 là chữ của người đi bên cạnh (phụ 付) hoàng gia như ngựa phụ (马) kéo xe vua. | Gương Hán-Việt | \"phò\" xuất hiện trong \"phò mã\" (駙馬) — danh hiệu của người lấy công chúa nhà vua. | Mở khoá kiến thức | Biết 驸 mở khoá: 驸马 (phò mã — phò mã đô uý), 额驸 (ngạch phò — danh hiệu thời Thanh).", "Tự nguyên_Xie": "驸 giản hóa từ 駙. Chữ 駙 gồm 馬 (mã — ngựa, biểu nghĩa) và 付/副 (biểu âm). Nguyên nghĩa: con ngựa phụ buộc bên cạnh ngựa chính kéo xe. Nghĩa phái sinh: phò mã (駙馬 — người lấy công chúa). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngựa đóng kèm bên xe", "Hạng Tần Suất (Jun Da)": "4205.0", "Tần Suất % (Jun Da)": "99.799734391", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驸", "Unihan_Traditional (Chữ Phồn thể)": "駙", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ, phò", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong các danh xưng hoàng tộc hoặc chỉ ngựa phụ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腌', '{"9000": "4206.0", "Chữ Trung Quốc": "腌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腌 | yêm | tượng hình | ướp muối, muối dưa | 腌 có bộ 月/肉 (nhục, biểu nghĩa: thịt/thực phẩm) và 奄 (yểm, biểu âm). Wiktionary không có glyph chi tiết (chỉ {{Han etym}}); cấu trúc suy từ bộ thủ và dạng tương đồng. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\": bộ 月 (thịt) + âm 奄 — thịt được bọc kín (yêm) trong muối để ướp; nhớ \"yêm\" như \"ém\" thịt vào hũ muối. | Gương Hán-Việt | \"yêm\" ít dùng riêng lẻ trong tiếng Việt hiện đại; gặp trong thuật ngữ ẩm thực chuyên sâu. | Mở khoá kiến thức | Biết 腌 mở khoá: 腌制 (ướp muối/ngâm chua), 腌菜 (dưa muối), 腌肉 (thịt muối), 腌渍 (ngâm dưa).", "Tự nguyên_Xie": "腌 gồm bộ 月 (thịt/thực phẩm, biểu nghĩa) và 奄 (biểu âm). Nguyên nghĩa: ướp muối thực phẩm để bảo quản. Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ướp muối; mùi hôi thối", "Hạng Tần Suất (Jun Da)": "4206.0", "Tần Suất % (Jun Da)": "99.7999679779", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腌", "Unihan_Traditional (Chữ Phồn thể)": "腌", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ việc chế biến thức ăn bằng muối hoặc làm tính từ chỉ sự dơ bẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盹', '{"9000": "4207.0", "Chữ Trung Quốc": "盹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 目 | mục | biểu nghĩa | mắt | 屯 | đồn | biểu âm | 盹 = 目 (mục, biểu nghĩa: mắt) + 屯 (đồn, biểu âm). Chữ hình thanh: bộ 目 cho biết liên quan đến mắt; 屯 cho âm đọc gần dǔn. Nghĩa: nhắm mắt chợp ngủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đốn\": mắt (目) lờ đờ như trận địa đóng quân (屯) không di chuyển — chợp mắt một lúc rồi tỉnh lại. | Gương Hán-Việt | \"đốn\" ít dùng độc lập trong tiếng Việt; gặp trong từ \"đốn ngộ\" nghĩa khác. | Mở khoá kiến thức | Biết 盹 mở khoá: 打盹 (chợp mắt), 打盹儿 (ngủ gật), 盹儿 (giấc ngủ ngắn).", "Tự nguyên_Xie": "盹 gồm 目 (mắt, biểu nghĩa) và 屯 (biểu âm, gần âm dǔn). Nghĩa gốc: mắt lim dim, chợp ngủ ngắn. Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt lim dim", "Hạng Tần Suất (Jun Da)": "4207.0", "Tần Suất % (Jun Da)": "99.8002015648", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盹", "Unihan_Traditional (Chữ Phồn thể)": "盹", "Pinyin_Xie": "dǔn", "Âm Hán Việt_Xie": "truân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ trạng thái ngủ lơ mơ hoặc làm danh từ chỉ giấc ngủ ngắn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熵', '{"9000": "4208.0", "Chữ Trung Quốc": "熵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 15 | nét | 火 | hoả | biểu nghĩa | lửa, nhiệt | 商 | thương | biểu âm | thương số | 熵 = 火 (hoả, biểu nghĩa: lửa/nhiệt) + 商 (thương, biểu âm, âm shāng). Wiktionary ghi ls=ic và ls2=psc — vừa có yếu tố hội ý (火 nhiệt, 商 thương số → thương số nhiệt), vừa hình thanh. Chữ do Hồ Cương Phục (Hu Gangfu) tạo năm 1923 để dịch khái niệm entropy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": entropy (熵) = lửa (火) chia thương số (商) — đúng theo công thức vật lý dS = dQ/T; chữ được thiết kế để mang nghĩa khoa học chính xác. | Gương Hán-Việt | \"thương\" xuất hiện trong \"thương số\" (商), \"thương mại\" (商业) — âm đọc chung với 商. | Mở khoá kiến thức | Biết 熵 mở khoá: 熵增 (entropy tăng), 熵变 (biến đổi entropy), 熵值 (giá trị entropy), thuật ngữ nhiệt động lực học.", "Tự nguyên_Xie": "熵 do nhà vật lý Trung Quốc Hồ Cương Phục tạo năm 1923 để phiên dịch khái niệm ''entropy'' trong nhiệt động lực học. Chữ gồm 火 (nhiệt, biểu nghĩa) và 商 (thương số, vừa biểu âm vừa biểu nghĩa — entropy là thương số của nhiệt và nhiệt độ). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "En-tơ-rô-pi", "Hạng Tần Suất (Jun Da)": "4208.0", "Tần Suất % (Jun Da)": "99.8004351517", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 商", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火商", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "商", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熵", "Unihan_Traditional (Chữ Phồn thể)": "熵", "Pinyin_Xie": "shāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ biểu thị một khái niệm vật lý học về mức độ hỗn loạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镐', '{"9000": "4209.0", "Chữ Trung Quốc": "镐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镐 | cảo | tượng hình | cuốc chim; tên cổ đô Cảo Kinh | 镐 là chữ giản thể, bộ 钅 (kim, biểu nghĩa: kim loại) kết hợp với 高 (cao, biểu âm). Chữ hình thanh. Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảo\": chiếc cuốc chim (钅 kim loại) có cán cao (高) — dùng để đào đất đá cứng; cũng là tên kinh đô nhà Chu. | Gương Hán-Việt | \"cảo\" xuất hiện trong \"Cảo Kinh\" (镐京) — kinh đô nhà Tây Chu ở Thiểm Tây, Trung Quốc. | Mở khoá kiến thức | Biết 镐 mở khoá: 镐头 (cuốc chim), 镐京 (Cảo Kinh — cổ đô), 十字镐 (cuốc chữ thập).", "Tự nguyên_Xie": "镐 gồm 钅 (kim loại, biểu nghĩa) và 高 (cao, biểu âm). Nguyên nghĩa: dụng cụ đào bằng kim loại (cuốc chim). Cũng là tên cổ đô nhà Chu: 鎬京 (Cảo Kinh). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng loá; kinh đô đời nhà Chu (nay thuộc phía tây nam thành phố Tây An, tỉnh Thiểm Tây của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4209.0", "Tần Suất % (Jun Da)": "99.8006682218", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镐", "Unihan_Traditional (Chữ Phồn thể)": "鎬", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ nông cụ đào đất hoặc làm tính từ chỉ vẻ sáng sủa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馐', '{"9000": "4210.0", "Chữ Trung Quốc": "馐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 飠 | thực | biểu nghĩa | thức ăn | 羞 | tu | biểu âm | 馐 = 飠 (thực, biểu nghĩa: thức ăn) + 羞 (tu, biểu âm, âm xiū). Chữ hình thanh. Wiktionary ghi thêm ls2=ic: 羞 cũng mang nghĩa \"món ngon dâng lên\" — nên có thể xem vừa hình thanh vừa hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tu\": 飠 (ăn uống) + 羞 (tu — xấu hổ) → món ăn đẹp đến mức đầu bếp xấu hổ không dám dâng; nhớ \"tu\" như \"trân tu\" (珍馐) — cao lương mỹ vị. | Gương Hán-Việt | \"tu\" xuất hiện trong \"trân tu\" (珍馐) — cao lương mỹ vị, mỹ thực quý giá. | Mở khoá kiến thức | Biết 馐 mở khoá: 珍馐 (trân tu — mỹ thực), 珍馐百味 (trăm món ngon quý), thuật ngữ văn ngôn về ẩm thực.", "Tự nguyên_Xie": "馐 gồm 飠 (thực phẩm, biểu nghĩa) và 羞 (tu — biểu âm, âm xiū). Wiktionary ghi ls=psc và ls2=ic: 羞 vốn nghĩa là dâng món ngon, nên 馐 mang cả yếu tố biểu nghĩa — món ăn ngon dâng kính. Dùng trong văn ngôn để chỉ mỹ thực. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ ăn ngon", "Hạng Tần Suất (Jun Da)": "4210.0", "Tần Suất % (Jun Da)": "99.8009012919", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 羞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣羞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馐", "Unihan_Traditional (Chữ Phồn thể)": "饈", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "tu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ các món ăn mỹ vị hoặc làm động từ chỉ việc dâng thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘤', '{"9000": "4211.0", "Chữ Trung Quốc": "嘤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | miệng | 嬰 | anh | biểu âm | 嘤 = 口 (khẩu, biểu nghĩa: miệng/âm thanh) + 嬰 (anh, biểu âm, âm yīng). Chữ hình thanh. Dùng để mô phỏng tiếng chim kêu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": miệng (口) phát ra tiếng \"anh\" (嬰) — tiếng chim kêu líu lo; \"嘤鸣\" gợi âm thanh dịu nhẹ trong thơ cổ. | Gương Hán-Việt | \"anh\" xuất hiện trong \"anh\" (嬰 — hài nhi, vòng cổ), âm đọc chung với 嘤. | Mở khoá kiến thức | Biết 嘤 mở khoá: 嘤鸣 (tiếng chim hót — dùng trong thơ văn), 嘤嘤 (tiếng kêu líu lo), 嘤嘤啼哭 (khóc thút thít).", "Tự nguyên_Xie": "嘤 gồm 口 (miệng, biểu nghĩa) và 嬰 (anh — biểu âm). Dùng để mô phỏng tiếng chim hót, tiếng trẻ khóc. Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chim kêu", "Hạng Tần Suất (Jun Da)": "4211.0", "Tần Suất % (Jun Da)": "99.8011338452", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 婴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口婴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘤", "Unihan_Traditional (Chữ Phồn thể)": "嚶", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô phỏng âm thanh của chim chóc hoặc tiếng khóc nỉ non. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癞', '{"9000": "4212.0", "Chữ Trung Quốc": "癞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 18 | nét | 癞 | lại | tượng hình | bệnh phong, ghẻ lở | 癞 có bộ 疒 (nạch — bệnh tật, biểu nghĩa) kết hợp với 赖 (lại, biểu âm). Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ bộ thủ. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": bệnh tật (疒) mà người bệnh bị \"lại\" (赖 — ỳ ra, không đi được) vì da lở loét; \"lại\" gợi hình ảnh người cùi khổng thể tự chăm sóc bản thân. | Gương Hán-Việt | \"lại\" xuất hiện trong \"cùi lại\" (phong lại — bệnh phong cùi), \"lại tử\" (癞子 — người bị ghẻ lở). | Mở khoá kiến thức | Biết 癞 mở khoá: 癞蛤蟆 (con cóc — khẩu ngữ), 癞子 (người ghẻ lở), 癞皮狗 (chó ghẻ — ẩn dụ người hèn hạ).", "Tự nguyên_Xie": "癞 gồm 疒 (bệnh tật, biểu nghĩa) và 赖 (lại, biểu âm). Nguyên nghĩa: bệnh phong (leprosy), vẩy nến da đầu. Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh hủi; bị hói đầu", "Hạng Tần Suất (Jun Da)": "4212.0", "Tần Suất % (Jun Da)": "99.8013663985", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 赖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒赖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癞", "Unihan_Traditional (Chữ Phồn thể)": "癩", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ bệnh ngoài da hoặc tính từ mô tả trạng thái sần sùi, ghẻ lở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骰', '{"9000": "4213.0", "Chữ Trung Quốc": "骰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 13 | nét | 骰 | xúc | tượng hình | xúc xắc — con xí ngầu | 骰 có bộ 骨 (cốt — xương, biểu nghĩa) kết hợp với 殳 (thù, biểu âm). Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ bộ thủ 骨. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xúc\": xương (骨) được gọt thành khối vuông (殳) để tung lên — chính là xúc xắc; \"xúc xắc\" trong tiếng Việt vay mượn từ Hán-Việt này. | Gương Hán-Việt | \"xúc\" xuất hiện trong \"xúc xắc\" — viên đa diện dùng trong trò chơi; âm \"xúc\" gần với tóu (tóu dùng trong 骰子). | Mở khoá kiến thức | Biết 骰 mở khoá: 骰子 (xúc xắc), 掷骰子 (tung xúc xắc), 骰盅 (bình tung xúc xắc).", "Tự nguyên_Xie": "骰 gồm 骨 (xương, biểu nghĩa) và 殳 (thù, biểu âm). Nguyên nghĩa: xúc xắc làm bằng xương động vật. Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con xúc xắc", "Hạng Tần Suất (Jun Da)": "4213.0", "Tần Suất % (Jun Da)": "99.8015989518", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 殳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骰", "Unihan_Traditional (Chữ Phồn thể)": "骰", "Pinyin_Xie": "tóu", "Âm Hán Việt_Xie": "đầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ chỉ hành động lắc hoặc đổ xúc xắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韭', '{"9000": "4214.0", "Chữ Trung Quốc": "韭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韭 | Số nét | 9 | nét | 韭 | cửu | tượng hình | cây hẹ mọc trong đất | 韭 là chữ tượng hình: mô phỏng cây hẹ mọc trong đất (vạch ngang 一 là mặt đất, nét trên là thân lá hẹ). Wiktionary xác nhận: chữ tượng hình, vô quan hệ với 非.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cửu\": chữ 韭 trông như cây hẹ (cửu) nhô lên khỏi mặt đất — \"cửu\" đọc giống \"cửu\" (九 — chín), vì hẹ có thể cắt nhiều lần quanh năm. | Gương Hán-Việt | \"cửu\" xuất hiện trong \"cửu thái\" (韭菜 — cây hẹ), âm đọc trong Hán-Việt cổ điển. | Mở khoá kiến thức | Biết 韭 mở khoá: 韭菜 (hẹ), 韭黄 (hẹ vàng — hẹ trồng che tối), 韭花 (hoa hẹ), 韭菜盒子 (bánh hẹ).", "Tự nguyên_Xie": "韭 là chữ tượng hình, mô phỏng hình ảnh cây hẹ mọc trong đất — vạch ngang (一) là mặt đất, các nét trên là lá hẹ. Wiktionary nhấn mạnh 韭 không liên quan đến 非. Chữ xuất hiện từ thời cổ đại, có trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "925.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ cây hẹ mọc trên mặt đất (các nét ngang ở dưới là mặt đất, các nét sổ và phẩy là rễ và lá). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Cửu là rau hẹ.", "Nghĩa Tiếng Việt_Xie": "rau hẹ", "Hạng Tần Suất (Jun Da)": "4214.0", "Tần Suất % (Jun Da)": "99.8018309883", "GavinGrover_Once (Chiết tự trực tiếp)": "非 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱非一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "一", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "非", "Unihan_Simplified (Chữ Giản thể)": "韭", "Unihan_Traditional (Chữ Phồn thể)": "韭", "Pinyin_Xie": "jiǔ", "Âm Hán Việt_Xie": "cửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại rau hoặc làm định ngữ trong các cụm từ chỉ món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阖', '{"9000": "4215.0", "Chữ Trung Quốc": "阖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 13 | nét | 阖 | hạp | tượng hình | đóng lại, toàn bộ — giản thể của 闔 | 阖 là chữ giản thể của 闔, được tạo bằng cách thay bộ 門 thành 门. Chữ gốc 闔 = 門 (môn — cửa, biểu nghĩa) + 盍 (hạp, biểu âm). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": cửa (门) đóng lại hết (盍) — \"hạp\" gợi \"khép hạp\"; 阖家 = toàn nhà cùng nhau đóng cửa sum họp. | Gương Hán-Việt | \"hạp\" xuất hiện trong \"hạp gia\" (阖家 — toàn gia đình), \"hạp phủ\" (阖府 — toàn phủ). | Mở khoá kiến thức | Biết 阖 mở khoá: 阖家 (toàn gia đình), 阖家欢乐 (cả nhà vui vẻ), 阖眼 (nhắm mắt), 阖然长逝 (nhắm mắt ra đi).", "Tự nguyên_Xie": "阖 giản hóa từ 闔. Chữ gốc 闔 gồm 門 (cửa, biểu nghĩa) và 盍 (hạp, biểu âm). Nghĩa gốc: đóng cửa. Nghĩa phái sinh: toàn bộ, tất cả (阖家 — toàn gia đình). Wiktionary xác nhận dạng giản thể này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấp, đóng", "Hạng Tần Suất (Jun Da)": "4215.0", "Tần Suất % (Jun Da)": "99.8020630249", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 盍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阖", "Unihan_Traditional (Chữ Phồn thể)": "闔", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động đóng cửa hoặc làm tính từ bổ nghĩa cho gia đình, gia tộc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞑', '{"9000": "4216.0", "Chữ Trung Quốc": "瞑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 目 | mục | biểu nghĩa | mắt | 冥 | minh | biểu âm | tối tăm | 瞑 = 目 (mục, biểu nghĩa: mắt) + 冥 (minh, biểu âm và biểu nghĩa: tối tăm). Chữ hình thanh: bộ 目 chỉ liên quan đến mắt; 冥 cho âm míng và gợi bóng tối — nhắm mắt vào chỗ tối. Wiktionary xác nhận: nghĩa là nhắm mắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"manh\": mắt (目) chìm vào cõi tối (冥) — nhắm mắt lại; \"瞑目\" là nhắm mắt yên nghỉ, dùng khi nói về người đã khuất. | Gương Hán-Việt | \"manh\" xuất hiện trong \"manh mục\" (瞑目 — nhắm mắt, yên nghỉ), dùng nhiều trong văn ngôn. | Mở khoá kiến thức | Biết 瞑 mở khoá: 瞑目 (nhắm mắt — thường dùng khi nói người mất), 瞑想 (thiền định — dùng ở Nhật, ít dùng ở Trung), 死不瞑目 (chết không nhắm mắt — bất bình khi chết).", "Tự nguyên_Xie": "瞑 gồm 目 (mắt, biểu nghĩa) và 冥 (tối tăm, biểu âm). Wiktionary xác nhận: chữ hình thanh, nghĩa là nhắm mắt lại — mắt rơi vào bóng tối. Dùng trong văn ngôn cho giấc ngủ sâu hoặc cái chết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhắm mắt", "Hạng Tần Suất (Jun Da)": "4216.0", "Tần Suất % (Jun Da)": "99.8022950614", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 冥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目冥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞑", "Unihan_Traditional (Chữ Phồn thể)": "瞑", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với danh từ chỉ mắt để diễn tả trạng thái nhắm mắt hoặc qua đời. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裨', '{"9000": "4217.0", "Chữ Trung Quốc": "裨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裨 | bì | tượng hình | bổ sung, giúp ích; loại y phục phụ | 裨 có bộ 衤 (y — vải/quần áo, biểu nghĩa) kết hợp với 卑 (ti, biểu âm). Wiktionary có hai âm đọc: bì (giúp ích) và pí (quân phục phụ). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bì\": y phục (衤) bậc thấp (卑) — áo phụ, trang phục phụ; nghĩa phái sinh: giúp đỡ ở vị trí thấp hơn, bổ trợ. | Gương Hán-Việt | \"bì\" xuất hiện trong \"vô bì\" (无裨 — không ích lợi gì), \"bì ích\" (裨益 — lợi ích). | Mở khoá kiến thức | Biết 裨 mở khoá: 裨益 (lợi ích, bổ ích), 无裨于事 (không ích gì), 裨将 (phó tướng — tướng phụ).", "Tự nguyên_Xie": "裨 gồm 衤 (quần áo, biểu nghĩa) và 卑 (ti — thấp kém, biểu âm). Nghĩa 1: loại y phục phụ/nhỏ. Nghĩa 2: bổ sung, giúp ích (vô裨于事 — không ích gì). Wiktionary ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bổ ích; giúp đỡ; nhỏ", "Hạng Tần Suất (Jun Da)": "4217.0", "Tần Suất % (Jun Da)": "99.8025270979", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裨", "Unihan_Traditional (Chữ Phồn thể)": "裨", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ bổ trợ mang nghĩa giúp ích hoặc làm tính từ chỉ sự nhỏ bé, phụ trợ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宕', '{"9000": "4218.0", "Chữ Trung Quốc": "宕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 8 | nét | 宕 | đãng | tượng hình | vô độ, phóng túng; hang đá | 宕 có bộ 宀 (miên — mái nhà, biểu nghĩa) kết hợp với 石 (thạch — đá). Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ bộ thủ. Có thể là chữ hội ý: mái nhà trong đá → hang đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãng\": mái nhà (宀) trong hang đá (石) — nơi kẻ phóng đãng ẩn náu; \"đãng\" gợi \"phóng đãng\", sống không giới hạn như hang đá rộng lớn. | Gương Hán-Việt | \"đãng\" xuất hiện trong \"phóng đãng\" (放宕 — phóng túng), \"đãng\" (宕 — vô độ). | Mở khoá kiến thức | Biết 宕 mở khoá: 拖宕 (kéo dài, trì hoãn), 宕机 (máy tính bị treo/crash), 跌宕 (khởi phục, hồi hộp), 豪宕 (hào phóng).", "Tự nguyên_Xie": "宕 gồm 宀 (mái nhà) và 石 (đá). Nghĩa gốc: hang đá. Nghĩa phái sinh: phóng túng, sa đà, chậm trễ (拖宕 — kéo dài). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỏ lửng việc không làm xong", "Hạng Tần Suất (Jun Da)": "4218.0", "Tần Suất % (Jun Da)": "99.8027586177", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "石", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宕", "Unihan_Traditional (Chữ Phồn thể)": "宕", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự trì hoãn công việc hoặc tính từ chỉ lối sống phóng túng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戾', '{"9000": "4219.0", "Chữ Trung Quốc": "戾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戶 | Số nét | 8 | nét | 戾 | lệ | tượng hình | chó cúi mình chui qua cửa — hung dữ, lầm lỗi | 戾 là chữ hội ý: chó (犬) cúi xuống chui qua cửa (戶). Wiktionary xác nhận: chữ hội ý, nghĩa gốc là cúi người; từ đó phái sinh nghĩa cong quẹo, hung ác, lầm lỗi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": chó (犬) cúi mình chui qua cửa (戶) — con chó hung hăng cong người lách qua; \"lệ\" gợi \"乖戾\" (hung tàn, trái lẽ). | Gương Hán-Việt | \"lệ\" xuất hiện trong \"乖戾\" (quái lệ — hung tàn, trái lẽ), \"罪戾\" (tội lệ — lỗi lầm, tội lỗi). | Mở khoá kiến thức | Biết 戾 mở khoá: 乖戾 (hung hăng, trái khoáy), 罪戾 (tội lỗi), 暴戾 (bạo lực hung tàn), 鸢飞戾天 (diều bay đến tận trời).", "Tự nguyên_Xie": "戾 là chữ hội ý: mô tả con chó (犬) cúi mình (bending over) chui qua cửa (戶). Nghĩa gốc: cúi, uốn cong. Nghĩa phái sinh: hung dữ, sai trái, lầm lỗi, đến nơi. Wiktionary xác nhận phân tích hội ý này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1847.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hộ (063) Khuyển (094)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hộ (số 063 - cửa một cánh/ 戶) nằm trên bộ Khuyển (số 094 - con chó/ 犬). Hình ảnh con chó nằm canh ở dưới cánh cửa để trông nhà. Giải thích sự chuyển ý: Đây là chữ Hội ý. Con chó nằm ở cửa nhà để canh gác thì rất sủa dữ dội và hung dữ cắn người. Từ đó, Lệ mang nghĩa là ngang ngược, bạo ngược, dữ tợn, tội lỗi tày trời (bạo lệ, ngoan lệ).", "Nghĩa Tiếng Việt_Xie": "đến; thôi, dừng lại; định hẳn; ngang trái", "Hạng Tần Suất (Jun Da)": "4219.0", "Tần Suất % (Jun Da)": "99.8029901374", "GavinGrover_Once (Chiết tự trực tiếp)": "户 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴户犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "户", "Unihan_Simplified (Chữ Giản thể)": "戾", "Unihan_Traditional (Chữ Phồn thể)": "戾", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường làm tính từ chỉ tính cách hung bạo hoặc danh từ chỉ tội lỗi, hành vi sai trái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镌', '{"9000": "4220.0", "Chữ Trung Quốc": "镌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镌 | quyên | tượng hình | khắc, đục — dụng cụ chạm khắc | 镌 có bộ 钅 (kim, biểu nghĩa: kim loại) kết hợp với 隽/雋 (chuẩn/quyên, biểu âm). Wiktionary chỉ ghi {{Han etym}}, không có glyph chi tiết. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": dụng cụ kim loại (钅) khắc sâu — \"quyên\" gợi \"chuyên\" (khắc chuyên cần); 镌刻 là khắc vào đá, 镌心 là khắc vào tâm trí. | Gương Hán-Việt | \"quyên\" xuất hiện trong \"quyên khắc\" (镌刻 — chạm khắc), ít dùng độc lập trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 镌 mở khoá: 镌刻 (chạm khắc), 镌心 (khắc vào lòng), 镌降 (giáng chức — nghĩa cổ).", "Tự nguyên_Xie": "镌 gồm 钅 (kim loại, biểu nghĩa) và phần biểu âm gần juān. Nguyên nghĩa: dụng cụ chạm khắc bằng kim loại; từ đó phái sinh nghĩa: khắc, ghi khắc vào lòng. Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khắc; giáng chức, biếm xuống", "Hạng Tần Suất (Jun Da)": "4220.0", "Tần Suất % (Jun Da)": "99.8032216571", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 隽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅隽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镌", "Unihan_Traditional (Chữ Phồn thể)": "鐫", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "tuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bia đá, chữ viết hoặc chức vị bị giáng xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溟', '{"9000": "4221.0", "Chữ Trung Quốc": "溟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 水 | thủy | biểu nghĩa | nước | 冥 | minh | biểu âm | tối tăm | 溟 = 水/氵 (thủy, biểu nghĩa: nước) + 冥 (minh, biểu âm và biểu nghĩa: tối tăm, sâu thẳm). Chữ hình thanh. Nghĩa: biển mênh mông tối tăm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": nước (水) trong bóng tối (冥) — biển sâu thẳm tối tăm; \"minh\" gợi \"溟\" như \"Bắc Minh\" trong Trang Tử — biển phương Bắc huyền bí. | Gương Hán-Việt | \"minh\" xuất hiện trong \"Bắc minh\" (北溟 — biển phương Bắc trong Trang Tử), \"溟\" dùng trong văn ngôn. | Mở khoá kiến thức | Biết 溟 mở khoá: 溟漠 (mênh mông tối tăm), 北溟 (biển phương Bắc — điển cố Trang Tử), 溟溟 (tối tăm mù mịt).", "Tự nguyên_Xie": "溟 gồm 水 (nước, biểu nghĩa) và 冥 (tối tăm, biểu âm). Wiktionary xác nhận cấu trúc hình thanh. Nghĩa: biển lớn tối tăm, sâu thẳm; dùng trong văn ngôn để chỉ đại dương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biển; mưa nhỏ", "Hạng Tần Suất (Jun Da)": "4221.0", "Tần Suất % (Jun Da)": "99.8034526601", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 冥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵冥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溟", "Unihan_Traditional (Chữ Phồn thể)": "溟", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ vùng biển rộng lớn hoặc tính từ mô tả không gian mịt mù tăm tối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牍', '{"9000": "4222.0", "Chữ Trung Quốc": "牍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 片 | Số nét | 12 | nét | 牍 | độc | tượng hình | thẻ tre/gỗ dùng viết — văn thư cổ đại | 牍 là chữ giản thể của 牘, được tạo bằng cách thay 賣 bằng 卖. Chữ gốc 牘 = 片 (phiến — mảnh gỗ, biểu nghĩa) + 賣 (biểu âm). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": mảnh gỗ (片) viết đầy chữ — \"độc\" gợi \"văn độc\" (文牍 — công văn, giấy tờ); thẻ gỗ cổ đại là phương tiện ghi chép trước khi có giấy. | Gương Hán-Việt | \"độc\" xuất hiện trong \"văn độc\" (文牍 — công văn, giấy tờ hành chính), \"độc\" dùng trong thuật ngữ văn thư. | Mở khoá kiến thức | Biết 牍 mở khoá: 文牍 (văn thư, giấy tờ), 案牍 (hồ sơ công văn), 尺牍 (thư tín — thư viết trên thẻ gỗ).", "Tự nguyên_Xie": "牍 giản hóa từ 牘. Chữ gốc 牘 gồm 片 (mảnh gỗ, biểu nghĩa) và 賣 (biểu âm). Nguyên nghĩa: thẻ gỗ hoặc tre dùng để viết chữ thời cổ đại trước khi có giấy. Wiktionary xác nhận dạng giản thể này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thẻ (tre) viết văn thư", "Hạng Tần Suất (Jun Da)": "4222.0", "Tần Suất % (Jun Da)": "99.803683663", "GavinGrover_Once (Chiết tự trực tiếp)": "片 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰片卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "片", "Unihan_Simplified (Chữ Giản thể)": "牍", "Unihan_Traditional (Chữ Phồn thể)": "牘", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho các động từ đọc, viết hoặc lưu trữ tài liệu cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隽', '{"9000": "4223.0", "Chữ Trung Quốc": "隽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 10 | nét | 隽 | tuấn | tượng hình | mũi tên bắn trúng chim — tài năng xuất sắc; giản thể của 雋 | 隽 là chữ giản thể của 雋 (đã tồn tại như dạng biến thể). Chữ gốc 雋 = 隹 (chuy — chim, biểu nghĩa) + 弋 (dặc — mũi tên buộc dây). Hội ý: mũi tên bắn trúng chim → tài năng xuất sắc, thức ngon (thịt chim béo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuấn\": mũi tên (弋) bắn trúng chim (隹) — người tài bắn trúng đích; \"tuấn\" gợi \"tuấn kiệt\" (俊杰 — nhân tài), 隽永 là ý nghĩa sâu sắc bền lâu. | Gương Hán-Việt | \"tuấn\" xuất hiện trong \"tuấn vĩnh\" (隽永 — ý nghĩa sâu xa bền lâu), \"tuấn\" gần nghĩa với \"俊\" (tài hoa). | Mở khoá kiến thức | Biết 隽 mở khoá: 隽永 (ý nghĩa sâu xa, bền lâu), 隽语 (câu nói sâu sắc), 隽秀 (tài hoa thanh lịch).", "Tự nguyên_Xie": "隽 là dạng giản thể của 雋. Chữ gốc 雋 gồm 隹 (chim) và 弋 (mũi tên buộc dây). Hội ý: mũi tên bắn trúng chim — chim bắn được là loài béo ngon. Từ đó phái sinh nghĩa: tài năng xuất sắc, ý nghĩa sâu xa. Wiktionary xác nhận quan hệ giản/phồn thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt béo mập", "Hạng Tần Suất (Jun Da)": "4223.0", "Tần Suất % (Jun Da)": "99.803914666", "GavinGrover_Once (Chiết tự trực tiếp)": "隹 + 乃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱隹乃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "隽", "Unihan_Traditional (Chữ Phồn thể)": "雋", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "tuyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho văn chương, lời nói hoặc phẩm chất con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婊', '{"9000": "4224.0", "Chữ Trung Quốc": "婊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 表 | biểu | biểu âm | 婊 = 女 (nữ, biểu nghĩa: phụ nữ) + 表 (biểu, biểu âm, âm biǎo). Chữ hình thanh. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biểu\": nữ (女) + biểu (表 — bề ngoài) → người chỉ có bề ngoài, không có thực chất; dùng trong khẩu ngữ như từ chửi thề. | Gương Hán-Việt | \"biểu\" xuất hiện trong \"biểu\" (表 — bề ngoài, biểu lộ), âm đọc chung với 婊. | Mở khoá kiến thức | Biết 婊 mở khoá: 婊子 (từ tục — gái mại dâm, từ chửi), dùng chủ yếu trong khẩu ngữ thông tục.", "Tự nguyên_Xie": "婊 gồm 女 (phụ nữ, biểu nghĩa) và 表 (biểu, biểu âm, âm biǎo). Chữ được dùng trong khẩu ngữ để chỉ gái mại dâm hoặc dùng làm từ chửi (từ tục). Chữ tạo muộn, không có trong văn ngôn cổ điển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gái đĩ, gái điếm, gái nhà thổ", "Hạng Tần Suất (Jun Da)": "4224.0", "Tần Suất % (Jun Da)": "99.8041446354", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 表", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女表", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "表", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婊", "Unihan_Traditional (Chữ Phồn thể)": "婊", "Pinyin_Xie": "biǎo", "Âm Hán Việt_Xie": "biểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong các từ ghép chỉ người hoặc để chửi mắng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹄', '{"9000": "4225.0", "Chữ Trung Quốc": "鹄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鹄 | hộc | tượng hình | thiên nga; hồng hộc — chim lớn tầm cao | 鹄 có bộ 鸟 (điểu — chim) kết hợp với 告 (cáo, biểu âm, âm gǔ/hú). Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ bộ thủ. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộc\": chim (鸟) bay cao như tiếng hót (告) vang — hồng hộc có hoài bão vươn lên cao; \"鸿鹄之志\" là chí khí lớn lao không tầm thường. | Gương Hán-Việt | \"hộc\" xuất hiện trong \"hồng hộc\" (鸿鹄 — loài chim lớn, biểu tượng hoài bão), \"hộc\" dùng trong thành ngữ. | Mở khoá kiến thức | Biết 鹄 mở khoá: 鸿鹄之志 (hoài bão lớn lao), 鹄立 (đứng thẳng chờ đợi), 鹄候 (chờ đợi trân trọng).", "Tự nguyên_Xie": "鹄 gồm 鸟 (chim, biểu nghĩa) và 告 (biểu âm). Nguyên nghĩa: thiên nga hoặc hồng hộc — loài chim lớn bay cao. Dùng trong thành ngữ 鸿鹄之志 (chí khí của hồng hộc — hoài bão lớn lao). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim hộc, ngỗng trời", "Hạng Tần Suất (Jun Da)": "4225.0", "Tần Suất % (Jun Da)": "99.8043746048", "GavinGrover_Once (Chiết tự trực tiếp)": "告 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰告鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹄", "Unihan_Traditional (Chữ Phồn thể)": "鵠", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cốc, hộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng làm chủ ngữ hoặc tân ngữ trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埂', '{"9000": "4226.0", "Chữ Trung Quốc": "埂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 埂 | ghềnh | tượng hình | bờ đê, bờ ruộng nổi lên | 埂 có bộ 土 (thổ — đất, biểu nghĩa) kết hợp với 更/耕 (biểu âm, âm gěng). Wiktionary không có glyph origin cho 埂; cấu trúc suy từ bộ thủ 土. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ghềnh\": đất (土) đắp nổi lên — bờ ruộng, bờ đê; \"ghềnh\" gợi hình ảnh bờ đất gồ ghề ngăn nước giống ghềnh thác. | Gương Hán-Việt | \"ghềnh\" xuất hiện trong địa danh Việt Nam: ghềnh đá, bờ ghềnh — cùng hình ảnh đất đá nhô lên. | Mở khoá kiến thức | Biết 埂 mở khoá: 田埂 (bờ ruộng), 土埂 (bờ đất), 垄埂 (bờ ruộng bậc thang).", "Tự nguyên_Xie": "埂 gồm 土 (đất, biểu nghĩa) và thành phần biểu âm gần gěng. Nguyên nghĩa: bờ đê, bờ ruộng đắp bằng đất. Không có glyph origin trong Wiktionary. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hố nhỏ", "Hạng Tần Suất (Jun Da)": "4226.0", "Tần Suất % (Jun Da)": "99.8046040574", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埂", "Unihan_Traditional (Chữ Phồn thể)": "埂", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa hình, kết hợp với các từ chỉ đồng ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拄', '{"9000": "4227.0", "Chữ Trung Quốc": "拄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 主 | chủ | biểu âm | chủ nhân, chính | 拄 = 扌 (Thủ, biểu nghĩa: tay) + 主 (Chủ, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 手 (扌) cho nghĩa, 主 cho âm zhǔ. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụ\": tay (扌) chắc như chủ nhân (主) — chống đỡ, làm trụ cột đỡ lấy. | Gương Hán-Việt | \"trụ\" trong 拄杖 (trụ trượng — chống gậy); liên hệ với 柱 (trụ cột) | Mở khoá kiến thức | Biết 拄 mở khoá 拄杖 (chống gậy), 拄着拐杖 (chống nạng), 支拄 (chống đỡ).", "Tự nguyên_Xie": "Chữ 拄 (trụ) là chữ hình thanh (ls=psc): bộ 手 (扌 — Thủ) biểu nghĩa chỉ hành động tay; 主 (Chủ) biểu âm zhǔ. Nghĩa gốc: chống đỡ bằng tay, tựa vào; cầm gậy chống. Wiktionary xác nhận chữ cổ (mc=y, oc=y). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầm, chống đỡ", "Hạng Tần Suất (Jun Da)": "4227.0", "Tần Suất % (Jun Da)": "99.80483351", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拄", "Unihan_Traditional (Chữ Phồn thể)": "拄", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "trụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước danh từ chỉ công cụ hỗ trợ như gậy gộc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhǔ | / | dựa vào | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III | HSK | HSK 6 | · | Động từ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娲', '{"9000": "4228.0", "Chữ Trung Quốc": "娲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 娲 | oa | tượng hình | Nữ Oa — nữ thần sáng tạo trong thần thoại Trung Hoa | 娲 là chữ giản thể của 媧, được tạo bằng cách thay 咼 thành 呙. Chữ gốc 媧 = 女 (nữ, biểu nghĩa: phụ nữ) + 咼 (oa, biểu âm). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": nữ thần (女) mang âm oa (呙) — Nữ Oa, người mẹ của nhân loại trong thần thoại Trung Hoa, dùng đất sét nặn ra con người. | Gương Hán-Việt | \"oa\" xuất hiện trong \"Nữ Oa\" (女娲) — tên riêng, không dùng độc lập trong tiếng Việt. | Mở khoá kiến thức | Biết 娲 mở khoá: 女娲 (Nữ Oa — nữ thần thần thoại), 女娲补天 (Nữ Oa vá trời), 女娲造人 (Nữ Oa tạo người).", "Tự nguyên_Xie": "娲 giản hóa từ 媧. Chữ gốc 媧 gồm 女 (phụ nữ, biểu nghĩa) và 咼 (oa, biểu âm). Chữ dùng riêng cho tên riêng Nữ Oa (女娲) — nữ thần trong thần thoại Trung Hoa, người tạo ra loài người và vá trời. Wiktionary xác nhận dạng giản thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: Nữ Oa 女媧,女娲)", "Hạng Tần Suất (Jun Da)": "4228.0", "Tần Suất % (Jun Da)": "99.8050624458", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娲", "Unihan_Traditional (Chữ Phồn thể)": "媧", "Pinyin_Xie": "wā", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ dùng làm danh từ riêng trong tên gọi Nữ Oa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虬', '{"9000": "4229.0", "Chữ Trung Quốc": "虬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 7 | nét | 虬 | cù | tượng hình | rồng con chưa có sừng — giản thể của 虯 | 虬 là chữ giản thể của 虯. Chữ gốc 虯 có bộ 虫 (trùng — loài bò sát, biểu nghĩa) kết hợp với 丩 (biểu âm, âm jiū — cuộn xoắn). Wiktionary xác nhận dạng giản/phồn thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": rồng (虫) nhỏ cuộn xoắn (丩) — rồng con chưa đủ lông cánh; \"cù\" gợi \"cù lao\" hay hình ảnh vật cuộn tròn. 虬髯 là bộ râu xoắn cuộn của trang nam nhi. | Gương Hán-Việt | \"cù\" xuất hiện trong \"cù\" (虯 — rồng con), gần với \"cù lao\" trong địa danh Việt Nam. | Mở khoá kiến thức | Biết 虬 mở khoá: 虬髯 (râu xoắn cuộn), 虬枝 (cành cây xoắn vặn), 虬龙 (rồng xoắn).", "Tự nguyên_Xie": "虬 giản hóa từ 虯. Chữ gốc 虯 gồm 虫 (loài bò sát/rồng, biểu nghĩa) và 丩 (cuộn xoắn, biểu âm). Nguyên nghĩa: rồng con chưa có sừng, cuộn xoắn. Nghĩa phái sinh: cuộn quắn, rắn chắc (虬髯 — râu xoắn cuộn). Wiktionary xác nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cầu long 虯龍,虬龙)", "Hạng Tần Suất (Jun Da)": "4229.0", "Tần Suất % (Jun Da)": "99.8052913816", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虬", "Unihan_Traditional (Chữ Phồn thể)": "虯", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ rồng hoặc làm tính từ mô tả hình dáng uốn lượn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萱', '{"9000": "4230.0", "Chữ Trung Quốc": "萱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 宣 | tuyên | biểu âm | 萱 = 艹 (thảo, biểu nghĩa: cỏ/thực vật) + 宣 (tuyên, biểu âm, âm xuān). Chữ hình thanh. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": cỏ (艹) mang tiếng tuyên (宣) — hoa hiên vàng rực; \"萱堂\" là buồng mẹ vì mẹ trồng hoa này để quên sầu; \"huyên\" gợi \"huyên náo\" của tình mẹ ấm áp. | Gương Hán-Việt | \"huyên\" xuất hiện trong \"huyên đường\" (萱堂 — buồng mẹ, kính xưng mẹ), dùng trong thơ văn cổ điển. | Mở khoá kiến thức | Biết 萱 mở khoá: 萱堂 (buồng mẹ, kính xưng mẹ), 忘忧草/萱草 (hoa hiên — hoa quên sầu), 椿萱 (cha mẹ — tiêu và hiên).", "Tự nguyên_Xie": "萱 gồm 艹 (cỏ, biểu nghĩa) và 宣 (tuyên, biểu âm). Nguyên nghĩa: cây hoa hiên vàng (day lily, Hemerocallis). Dùng trong văn ngôn để chỉ mẹ (萱堂 — buồng của mẹ, vì mẹ thường trồng hoa hiên). Wiktionary xác nhận cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ huyên", "Hạng Tần Suất (Jun Da)": "4230.0", "Tần Suất % (Jun Da)": "99.8055198006", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萱", "Unihan_Traditional (Chữ Phồn thể)": "萱", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ thường xuất hiện trong thơ văn cổ hoặc dùng đặt tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啵', '{"9000": "4231.0", "Chữ Trung Quốc": "啵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 波 | ba | biểu âm | 啵 = 口 (khẩu, biểu nghĩa: miệng) + 波 (ba, biểu âm, âm bō). Chữ hình thanh. Dùng làm từ tượng thanh hoặc trợ từ ngữ khí trong tiếng Tứ Xuyên/tiếng Mandarin khẩu ngữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"\": miệng (口) phát ra tiếng ba (波) — âm \"bợp\" của nụ hôn; 啵 là âm hôn trong truyện tranh và tin nhắn yêu đương. | Gương Hán-Việt | \"ba\" xuất hiện trong \"ba\" (波 — sóng), âm đọc chung với 啵 trong Hán-Việt. | Mở khoá kiến thức | Biết 啵 mở khoá: 啵啵 (âm hôn, thể hiện tình cảm trong nhắn tin), dùng trong khẩu ngữ và tiếng lóng mạng xã hội.", "Tự nguyên_Xie": "啵 gồm 口 (miệng, biểu nghĩa) và 波 (ba, biểu âm). Wiktionary xác nhận cấu trúc hình thanh. Dùng làm từ tượng thanh (tiếng hôn, tiếng bật môi) hoặc trợ từ khẩu ngữ vùng Tứ Xuyên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cách, cạch, rắc (các tiếng động nhỏ); hút vào, hít vào; (thán từ)", "Hạng Tần Suất (Jun Da)": "4231.0", "Tần Suất % (Jun Da)": "99.8057477029", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 波", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口波", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "波", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啵", "Unihan_Traditional (Chữ Phồn thể)": "啵", "Pinyin_Xie": "bo", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Từ tượng thanh | 象声词 | Thường đứng ở cuối câu làm trợ từ ngữ khí hoặc mô phỏng âm thanh. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠡', '{"9000": "4232.0", "Chữ Trung Quốc": "蠡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 21 | nét | 蠡 | lãi | tượng hình | muôi gáo làm từ vỏ ốc; dùng gáo nhỏ đo biển — kiến thức hạn hẹp | 蠡 là chữ tổng hợp phức tạp; Wiktionary ghi {{Han etym}} không có glyph chi tiết. Có thể tích hợp bộ 虫 (trùng) trong phần dưới. Chữ dùng trong thành ngữ 以蠡测海 (dùng gáo nhỏ đo biển).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãi\": chiếc gáo nhỏ (蠡) dùng đo biển lớn — \"lãi\" gợi cách đo lường hạn hẹp; 以蠡测海 là cảnh báo về sự tự phụ khi kiến thức còn ít. | Gương Hán-Việt | \"lãi\" xuất hiện trong \"lãi\" (蠡 — muôi gáo, sâu mọt), ít dùng độc lập trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 蠡 mở khoá: 以蠡测海 (dùng gáo nhỏ đo biển — tự lượng sức quá nhỏ), 管窥蠡测 (nhìn qua ống, đo bằng gáo — kiến thức thiển cận).", "Tự nguyên_Xie": "蠡 có cấu trúc phức tạp, Wiktionary chỉ ghi {{Han etym}}. Nghĩa 1: muôi/gáo làm từ vỏ ốc. Nghĩa 2: loài sâu ăn gỗ (mọt). Dùng trong thành ngữ 以蠡测海 (dùng gáo nhỏ đo biển lớn — kiến thức hạn hẹp). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con mọt gỗ", "Hạng Tần Suất (Jun Da)": "4232.0", "Tần Suất % (Jun Da)": "99.8059756051", "GavinGrover_Once (Chiết tự trực tiếp)": "彖 + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彖䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彖", "Unihan_Simplified (Chữ Giản thể)": "蠡", "Unihan_Traditional (Chữ Phồn thể)": "蠡", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lê, lễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ trong văn ngôn cổ, thường dùng trong các thành ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芋', '{"9000": "4233.0", "Chữ Trung Quốc": "芋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艸 | tháo | biểu nghĩa | cỏ, thực vật | 于 | vu | biểu âm | 芋 = 艸/艹 (tháo, biểu nghĩa: cỏ/thực vật) + 于 (vu, biểu âm, âm yù). Chữ hình thanh. Wiktionary xác nhận: chỉ cây khoai môn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": cỏ (艸) mang âm vu (于) — cây vu (芋) là khoai môn; củ to bở dùng làm chè, nấu cháo. | Gương Hán-Việt | \"vu\" xuất hiện trong \"vu\" (于 — ở, tại), âm đọc chung với 芋 trong Hán-Việt. | Mở khoá kiến thức | Biết 芋 mở khoá: 芋头 (khoai môn), 芋艿 (khoai sọ — tiếng Thượng Hải), 芋泥 (kem khoai môn), 香芋 (khoai môn thơm).", "Tự nguyên_Xie": "芋 gồm 艸 (thực vật, biểu nghĩa) và 于 (vu, biểu âm). Nguyên nghĩa: cây khoai môn (taro). Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ở, cư trú", "Hạng Tần Suất (Jun Da)": "4233.0", "Tần Suất % (Jun Da)": "99.8062029906", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芋", "Unihan_Traditional (Chữ Phồn thể)": "芋", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "vu, dụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ thực vật, thường đứng làm tân ngữ hoặc kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胭', '{"9000": "4234.0", "Chữ Trung Quốc": "胭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 胭 | nhân | tượng hình | son phấn đỏ; má hồng | 胭 có bộ 月/肉 (nhục — thịt/cơ thể, biểu nghĩa) kết hợp với 咽 (yết, biểu âm, âm yān). Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ bộ thủ. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": cơ thể (月) được tô đỏ (bộ mặt) — son phấn; \"胭脂\" là má hồng son đỏ của người phụ nữ; \"nhân\" gợi sắc đỏ son trên da người. | Gương Hán-Việt | \"nhân\" xuất hiện trong \"yên chi\" (胭脂 — son phấn đỏ), gốc tiếng Hán-Việt. | Mở khoá kiến thức | Biết 胭 mở khoá: 胭脂 (son phấn đỏ, má hồng), 胭脂红 (màu đỏ son), 胭脂水粉 (phấn son — mỹ phẩm cổ đại).", "Tự nguyên_Xie": "胭 gồm 月/肉 (cơ thể, biểu nghĩa) và thành phần biểu âm gần yān. Nguyên nghĩa: son phấn đỏ (胭脂) dùng tô má. Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: yên chi 胭脂,臙脂)", "Hạng Tần Suất (Jun Da)": "4234.0", "Tần Suất % (Jun Da)": "99.8064298592", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胭", "Unihan_Traditional (Chữ Phồn thể)": "胭", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép với chữ chi để chỉ phấn son trang điểm của phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豺', '{"9000": "4235.0", "Chữ Trung Quốc": "豺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 10 | nét | 豸 | trại | biểu nghĩa | loài thú ăn thịt | 才 | tài | biểu âm | 豺 = 豸 (trại, biểu nghĩa: loài thú ăn thịt/dã thú) + 才 (tài, biểu âm, âm chái). Chữ hình thanh. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sài\": dã thú (豸) tài (才) giỏi săn mồi — con sài lang (豺狼) hung ác; \"sài\" gợi \"sài gòn\" hay \"sài\" trong \"sài lang\" (豺狼 — sói và chó sói hung tàn). | Gương Hán-Việt | \"sài\" xuất hiện trong \"sài lang\" (豺狼 — sói và lang — ẩn dụ kẻ tham tàn), ít dùng độc lập trong tiếng Việt. | Mở khoá kiến thức | Biết 豺 mở khoá: 豺狼 (sài lang — sói tham tàn), 豺狼当道 (sài lang chặn đường — kẻ hung ác cầm quyền), 豺虎 (sài hổ — thú dữ hung ác).", "Tự nguyên_Xie": "豺 gồm 豸 (loài thú ăn thịt, biểu nghĩa) và 才 (tài, biểu âm). Wiktionary xác nhận cấu trúc hình thanh. Nghĩa: chó sói — loài thú ăn thịt hung ác; dùng trong thành ngữ để chỉ kẻ hung tàn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chó sói", "Hạng Tần Suất (Jun Da)": "4235.0", "Tần Suất % (Jun Da)": "99.8066562111", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 才", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸才", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "才", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "豺", "Unihan_Traditional (Chữ Phồn thể)": "豺", "Pinyin_Xie": "chái", "Âm Hán Việt_Xie": "sài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ động vật, thường đi kèm với hổ báo để chỉ kẻ hung ác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啻', '{"9000": "4236.0", "Chữ Trung Quốc": "啻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 啻 | thế | tượng hình | chỉ, chỉ là; không hơn | 啻 có bộ 口 (khẩu — miệng, biểu nghĩa) kết hợp với 帝 (đế, biểu âm, âm chì). Wiktionary chỉ ghi {{Han etym}}, không có glyph chi tiết. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thế\": miệng (口) phát ra lời của đế vương (帝) — lời tuyên bố dứt khoát \"chỉ là\"; 不啻 = không chỉ là, hơn cả; \"thế\" gợi \"đế\" (bậc cao). | Gương Hán-Việt | \"thế\" xuất hiện trong \"bất thế\" (不啻 — không chỉ là), dùng trong văn ngôn. | Mở khoá kiến thức | Biết 啻 mở khoá: 不啻 (không chỉ là, hơn cả), 无啻 (không khác gì), 何啻 (há chỉ là).", "Tự nguyên_Xie": "啻 gồm 口 (miệng, biểu nghĩa) và 帝 (đế, biểu âm). Nghĩa: chỉ là, không hơn. Dùng trong văn ngôn trong cấu trúc phủ định 不啻 (không chỉ là, hơn cả). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "những", "Hạng Tần Suất (Jun Da)": "4236.0", "Tần Suất % (Jun Da)": "99.8068820462", "GavinGrover_Once (Chiết tự trực tiếp)": "帝 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱帝口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啻", "Unihan_Traditional (Chữ Phồn thể)": "啻", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "thí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này thường làm phó từ đứng trước động từ hoặc danh từ trong văn ngôn để biểu thị sự giới hạn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褛', '{"9000": "4237.0", "Chữ Trung Quốc": "褛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衣 | y | biểu nghĩa | quần áo | 婁 | lâu | biểu âm | 褛 = 衤 (y, biểu nghĩa: quần áo) + 婁 (lâu, biểu âm, âm lǚ). Chữ hình thanh. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": áo (衤) bị kéo lâu (婁) không giặt — quần áo rách rưới tả tơi; 衣衫褴褛 gợi hình ảnh người nghèo khó quần áo tơi tả. | Gương Hán-Việt | \"lâu\" xuất hiện trong \"lam lũ\" (褴褛 — quần áo rách rưới), âm đọc Hán-Việt gần với \"lâu\". | Mở khoá kiến thức | Biết 褛 mở khoá: 褴褛 (rách rưới tả tơi), 衣衫褴褛 (quần áo rách tơi tả), dùng để mô tả cảnh nghèo khó.", "Tự nguyên_Xie": "褛 gồm 衤 (quần áo, biểu nghĩa) và 婁 (lâu, biểu âm). Nghĩa: quần áo rách rưới, tả tơi. Dùng trong thành ngữ 衣衫褴褛 (quần áo rách tơi tả). Wiktionary xác nhận cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lam lũ 襤褸,褴褛)", "Hạng Tần Suất (Jun Da)": "4237.0", "Tần Suất % (Jun Da)": "99.8071078813", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褛", "Unihan_Traditional (Chữ Phồn thể)": "褸", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này chủ yếu làm tính từ khi kết hợp thành từ ghép để miêu tả quần áo rách rưới. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛆', '{"9000": "4238.0", "Chữ Trung Quốc": "蛆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 且 | thả | biểu âm | 蛆 = 虫 (trùng, biểu nghĩa: sâu bọ) + 且 (thả, biểu âm, âm qū). Chữ hình thanh. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": sâu bọ (虫) ngồi lại (且) chờ trong thịt thối — con dòi; \"thư\" gợi hình ảnh sinh vật ký sinh chờ đợi. | Gương Hán-Việt | \"thư\" xuất hiện trong \"thư\" (蛆 — dòi), ít dùng độc lập trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 蛆 mở khoá: 蛆虫 (con dòi), 生蛆 (sinh dòi), dùng trong ngữ cảnh vệ sinh thực phẩm hoặc ẩn dụ tiêu cực.", "Tự nguyên_Xie": "蛆 gồm 虫 (sâu bọ, biểu nghĩa) và 且 (thả, biểu âm). Wiktionary xác nhận cấu trúc hình thanh. Nghĩa: dòi — ấu trùng của ruồi, sống trong thịt thối. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con giòi; váng rượu", "Hạng Tần Suất (Jun Da)": "4238.0", "Tần Suất % (Jun Da)": "99.8073326829", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛆", "Unihan_Traditional (Chữ Phồn thể)": "蛆", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con giòi, thường làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柠', '{"9000": "4239.0", "Chữ Trung Quốc": "柠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柠 | linh | tượng hình | cây chanh vàng — giản thể của 檸 | 柠 là chữ giản thể của 檸. Chữ gốc 檸 = 木 (mộc, biểu nghĩa: cây) + 寧 (ninh, biểu âm, âm níng). Chữ hình thanh. Wiktionary chỉ ghi {{Han etym}}, không có glyph chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": cây (木) mang âm linh (寧 ninh) — cây chanh 柠檬 có vị chua thanh \"linh\"; \"linh\" gợi vị chanh thanh mát. | Gương Hán-Việt | \"linh\" xuất hiện trong \"linh mông\" (柠檬 — chanh vàng), âm đọc Hán-Việt. | Mở khoá kiến thức | Biết 柠 mở khoá: 柠檬 (chanh vàng — lemon), 柠檬茶 (trà chanh), 柠檬水 (nước chanh), 柠檬黄 (màu vàng chanh).", "Tự nguyên_Xie": "柠 giản hóa từ 檸. Chữ gốc 檸 gồm 木 (cây, biểu nghĩa) và 寧 (ninh, biểu âm). Dùng để phiên tên tiếng Anh ''lemon'' và chỉ cây chanh vàng (柠檬). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nịnh mông 檸檬,柠檬)", "Hạng Tần Suất (Jun Da)": "4239.0", "Tần Suất % (Jun Da)": "99.8075569676", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柠", "Unihan_Traditional (Chữ Phồn thể)": "檸", "Pinyin_Xie": "níng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong từ ghép để chỉ quả chanh hoặc cây chanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掰', '{"9000": "4240.0", "Chữ Trung Quốc": "掰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 手 | thủ | biểu nghĩa | bàn tay (trái) | 分 | phân | biểu ý | chia, tách ra | 手 | thủ | biểu nghĩa | bàn tay (phải) | 掰 = 手 (Thủ, tay trái) + 分 (Phân, chia tách) + 手 (Thủ, tay phải), ls=ic (hội ý). Wiktionary ghi rõ: hình ảnh hai bàn tay kéo căng về hai phía với 分 ở giữa — hội ý về hành động bẻ gãy, tách ra. Chữ hội ý tạo muộn, sáng tác gần đây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bẻ\": hai bàn tay (手…手) kéo căng chia đôi (分) — hành động bẻ gãy, tách rời. | Gương Hán-Việt | \"bẻ\" ít dùng trong tiếng Việt Hán-Việt; 掰 chủ yếu dùng mô tả hành động bẻ bằng tay | Mở khoá kiến thức | Biết 掰 mô tả chính xác hành động bẻ ngô, bẻ bánh mì, bẻ đũa bằng hai tay.", "Tự nguyên_Xie": "Chữ 掰 (bẻ) là chữ hội ý (ls=ic): hai bộ 手 (Thủ — bàn tay) hai bên + 分 (Phân — chia tách) ở giữa. Hình tượng hai bàn tay kéo căng hai phía để bẻ gãy một vật. Wiktionary ghi đây là chữ tạo rất muộn (\"very recent creation\" theo David Branner, 1999). Nghĩa gốc: dùng hai tay bẻ gãy, tách rời. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ, tẽ, tách ra, bửa ra", "Hạng Tần Suất (Jun Da)": "4240.0", "Tần Suất % (Jun Da)": "99.8077812524", "GavinGrover_Once (Chiết tự trực tiếp)": "龵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "掰", "Unihan_Traditional (Chữ Phồn thể)": "掰", "Pinyin_Xie": "bāi", "Âm Hán Việt_Xie": "bãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dùng tay bẻ hoặc tách vật gì đó ra. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bāi | / | bẻ | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篆', '{"9000": "4241.0", "Chữ Trung Quốc": "篆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 篆 | triện | tượng hình | chữ triện — kiểu chữ Trung Hoa cổ đại | 篆 có bộ 竹/⺮ (trúc, biểu nghĩa: tre/viết) kết hợp với 彖 (đoán, biểu âm). Wiktionary chỉ ghi {{Han etym}} không có glyph chi tiết; cấu trúc suy từ bộ thủ. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triện\": bút tre (竹) viết kiểu chữ trang trọng cổ đại — chữ triện; \"triện\" gợi \"con dấu triện\" trong tiếng Việt — dấu khắc chữ triện để đóng vào văn bản. | Gương Hán-Việt | \"triện\" xuất hiện trong \"triện\" (篆 — chữ triện), \"con dấu triện\" trong tiếng Việt vay mượn từ đây. | Mở khoá kiến thức | Biết 篆 mở khoá: 篆书 (chữ triện), 篆刻 (khắc triện — nghệ thuật khắc con dấu), 小篆 (tiểu triện), 大篆 (đại triện).", "Tự nguyên_Xie": "篆 gồm ⺮ (tre/viết, biểu nghĩa) và 彖 (đoán, biểu âm, âm gần zhuàn). Nguyên nghĩa: chữ triện — kiểu viết trên thẻ tre cổ đại. Có hai dạng chính: đại triện (大篆) và tiểu triện (小篆). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chữ triện", "Hạng Tần Suất (Jun Da)": "4241.0", "Tần Suất % (Jun Da)": "99.8080050203", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 彖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篆", "Unihan_Traditional (Chữ Phồn thể)": "篆", "Pinyin_Xie": "zhuàn", "Âm Hán Việt_Xie": "triện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ một lối viết chữ Hán cổ hoặc làm động từ chỉ việc khắc chữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倌', '{"9000": "4242.0", "Chữ Trung Quốc": "倌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 官 | quan | biểu âm | 倌 = 亻 (nhân, biểu nghĩa: người) + 官 (quan, biểu âm, âm guān). Chữ hình thanh. Wiktionary ghi thêm khả năng hội ý: 亻(người) + 官(dinh thự) → người hầu hạ trong dinh; nhưng chủ yếu là hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quản\": người (亻) làm việc trong dinh quan (官) — người hầu, người giữ ngựa; 堂倌 là người hầu bàn, 马倌 là người chăn ngựa. | Gương Hán-Việt | \"quản\" xuất hiện trong \"quản\" (官 — quan chức), âm đọc chung; 倌 nghĩa cụ thể hơn: người phục vụ. | Mở khoá kiến thức | Biết 倌 mở khoá: 马倌 (người chăn ngựa), 堂倌 (người hầu bàn), 羊倌 (người chăn dê).", "Tự nguyên_Xie": "倌 gồm 亻 (người, biểu nghĩa) và 官 (quan, biểu âm). Wiktionary xác nhận cấu trúc hình thanh. Nghĩa: người giữ ngựa, người hầu hạ gia súc; người làm dịch vụ nhỏ (tiếp tân, người phục vụ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người coi ngựa", "Hạng Tần Suất (Jun Da)": "4242.0", "Tần Suất % (Jun Da)": "99.8082282715", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倌", "Unihan_Traditional (Chữ Phồn thể)": "倌", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người làm nghề chăn nuôi gia súc thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咛', '{"9000": "4243.0", "Chữ Trung Quốc": "咛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 咛 | ninh | tượng hình | dặn dò ân cần, nhắc nhở | 咛 có bộ 口 (khẩu — miệng, biểu nghĩa) kết hợp với 宁/寧 (ninh, biểu âm, âm níng). Wiktionary chỉ ghi {{Han etym}}, không có glyph chi tiết. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ninh\": miệng (口) dặn dò yên lòng (宁) — nhắc nhở ân cần để người đi được ninh lòng; 叮咛 là dặn dò tha thiết của người thân trước lúc chia tay. | Gương Hán-Việt | \"ninh\" xuất hiện trong \"đinh ninh\" (叮咛 — dặn dò tha thiết), dùng trong văn học và khẩu ngữ. | Mở khoá kiến thức | Biết 咛 mở khoá: 叮咛 (dặn dò tha thiết), 叮咛嘱咐 (dặn dò căn dặn), dùng trong bối cảnh chia tay hoặc lời khuyên bảo.", "Tự nguyên_Xie": "咛 gồm 口 (miệng, biểu nghĩa) và 宁/寧 (ninh, biểu âm). Nghĩa: dặn dò ân cần, nhắc đi nhắc lại. Thường dùng trong 叮咛 (đinh ninh — dặn dò tha thiết). Wiktionary chỉ ghi {{Han etym}}, chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đinh ninh 叮嚀,叮咛)", "Hạng Tần Suất (Jun Da)": "4243.0", "Tần Suất % (Jun Da)": "99.8084515227", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咛", "Unihan_Traditional (Chữ Phồn thể)": "嚀", "Pinyin_Xie": "níng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường kết hợp thành từ ghép để chỉ việc dặn dò kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛭', '{"9000": "4244.0", "Chữ Trung Quốc": "蛭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 至 | chí | biểu âm | 蛭 = 虫 (trùng, biểu nghĩa: sâu bọ) + 至 (chí, biểu âm, âm zhì). Chữ hình thanh. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chấy\": sâu bọ (虫) đến bám (至 — đến nơi) hút máu — con đỉa; \"chấy\" gợi sinh vật ký sinh bám chặt, cũng như đỉa bám vào da. | Gương Hán-Việt | \"chấy\" xuất hiện trong \"chấy\" (蛭 — con đỉa), ít dùng độc lập trong tiếng Việt (\"đỉa\" phổ biến hơn). | Mở khoá kiến thức | Biết 蛭 mở khoá: 水蛭 (con đỉa), 蚂蟥 (đỉa lớn), 水蛭素 (hirudin — chất chống đông máu từ đỉa, dùng trong y học).", "Tự nguyên_Xie": "蛭 gồm 虫 (sâu bọ, biểu nghĩa) và 至 (chí, biểu âm). Wiktionary xác nhận cấu trúc hình thanh. Nghĩa: con đỉa — loài giun hút máu sống ở nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đỉa", "Hạng Tần Suất (Jun Da)": "4244.0", "Tần Suất % (Jun Da)": "99.8086747739", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛭", "Unihan_Traditional (Chữ Phồn thể)": "蛭", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con đỉa, thường đứng làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谡', '{"9000": "4245.0", "Chữ Trung Quốc": "谡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 谡 | túc | tượng hình | nổi lên, khởi lên | 谡 không có cấu trúc hình thanh rõ ràng trong dữ liệu hiện có. Chữ thuộc bộ 言 (ngôn), nhưng mối liên hệ giữa các thành phần chưa được xác định học thuật. Tạm xem là chữ tượng hình với nghĩa gốc: nổi lên, đứng dậy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": hình dung một người bỗng đứng thẳng dậy — nổi lên như từ đất. | Gương Hán-Việt | túc trong các tên riêng cổ (Mã Túc — danh tướng Tam Quốc bị trảm) | Mở khoá kiến thức | Biết 谡 mở khoá điển cố \"斬馬謖\" (Gia Cát Lượng chém Mã Túc) — thành ngữ chỉ kỷ luật nghiêm minh.", "Tự nguyên_Xie": "谡 (phồn thể 謖) là chữ cổ mang nghĩa nổi lên, đứng dậy. Wiktionary ghi nhận cách đọc Trung cổ suk1 (Quảng Đông), phù hợp với âm Hán-Việt. Cấu trúc nội tại chưa được phân tích rõ trong nguồn học thuật. chưa có nguồn học thuật đầy đủ về cấu tạo chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nổi lên, khởi lên; khép nép", "Hạng Tần Suất (Jun Da)": "4245.0", "Tần Suất % (Jun Da)": "99.8088975083", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 畟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠畟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谡", "Unihan_Traditional (Chữ Phồn thể)": "謖", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động đứng dậy hoặc làm tính từ miêu tả dáng vẻ kính cẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荨', '{"9000": "4246.0", "Chữ Trung Quốc": "荨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 尋 | tầm | biểu âm | tìm kiếm | 荨 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 尋 (Tầm, biểu âm); chữ hình thanh. Bộ 艹 xác định đây là loài thực vật; 尋 cho âm đọc gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tầm\": bộ 艹 (cỏ) + 尋 (tìm) — loài cỏ gai mà ta phải \"tìm\" cách tránh vì gây ngứa. | Gương Hán-Việt | tầm trong 蕁麻疹 (tầm ma chẩn — bệnh mề đay) | Mở khoá kiến thức | Biết 荨 mở khoá từ y học 荨麻疹 (xún má zhěn) — mề đay, bệnh dị ứng da phổ biến.", "Tự nguyên_Xie": "Tiểu triện | 荨 (phồn thể 蕁) là chữ hình thanh: 艹 (biểu nghĩa, cỏ) + 尋 (biểu âm). Wiktionary ghi cách đọc tán (âm 1) chỉ cây tri mẫu (Anemarrhena); cách đọc xún (âm 2, tiêu chuẩn Đại Lục) dùng trong 蕁麻疹 (mề đay). Trong tiểu triện đã thấy hình thức này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cỏ gai; lửa bốc lên", "Hạng Tần Suất (Jun Da)": "4246.0", "Tần Suất % (Jun Da)": "99.8091202427", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 寻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹寻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荨", "Unihan_Traditional (Chữ Phồn thể)": "蕁", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân thảo có lông ngứa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莞', '{"9000": "4247.0", "Chữ Trung Quốc": "莞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 完 | hoàn | biểu âm | hoàn chỉnh | 莞 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 完 (Hoàn, biểu âm); chữ hình thanh. Bộ 艹 xác định đây là loài thực vật thủy sinh; 完 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quản\": bộ 艹 (cỏ) + 完 (hoàn) — cây cói \"hoàn chỉnh\" đủ dùng để dệt chiếu. | Gương Hán-Việt | hoàn trong 东莞 (Đông Hoản — thành phố công nghiệp nổi tiếng Quảng Đông) | Mở khoá kiến thức | Biết 莞 mở khoá địa danh 东莞 (Đông Hoản) và từ 莞尔 (莞爾 — mỉm cười nhẹ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 莞 là chữ hình thanh: 艹 (biểu nghĩa, cỏ) + 完 (biểu âm). Wiktionary xác nhận cấu trúc Han compound này. Chữ chỉ cây cói (Scirpus lacustris) dùng đan chiếu, cũng là tên huyện Đông Hoản (东莞 Dōngguǎn). Hình thức tiểu triện và lục thư thông đã được lưu giữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ cói (dùng dệt chiếu); (tên huyện)", "Hạng Tần Suất (Jun Da)": "4247.0", "Tần Suất % (Jun Da)": "99.8093429771", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莞", "Unihan_Traditional (Chữ Phồn thể)": "莞", "Pinyin_Xie": "guǎn", "Âm Hán Việt_Xie": "quản, hoản, hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ dùng để dệt chiếu hoặc làm tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澹', '{"9000": "4248.0", "Chữ Trung Quốc": "澹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 氵 | thủy | biểu nghĩa | nước | 詹 | chiêm | biểu âm | nhiều lời | 澹 = 氵(Thủy, biểu nghĩa: nước) + 詹 (Chiêm, biểu âm); chữ hình thanh. Bộ 氵 gợi tính chất liên quan đến nước/tĩnh lặng; 詹 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": 氵(nước) + 詹 (chiêm) — mặt nước yên lặng như người \"đạm\" bạc, không xôn xao. | Gương Hán-Việt | đạm trong 澹泊 (đạm bạc — sống giản dị, không màng danh lợi) | Mở khoá kiến thức | Biết 澹 mở khoá thành ngữ 澹泊明志 (đạm bạc minh chí — sống đạm bạc để làm rõ chí hướng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 澹 là chữ hình thanh: 氵 (biểu nghĩa, nước) + 詹 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa gốc: nước yên tĩnh, phẳng lặng — từ đó mở rộng sang yên tĩnh, điềm đạm nói chung. Dạng đại triện và tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên lặng; họ Đạm", "Hạng Tần Suất (Jun Da)": "4248.0", "Tần Suất % (Jun Da)": "99.8095657114", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澹", "Unihan_Traditional (Chữ Phồn thể)": "澹", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm, đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả trạng thái yên tĩnh hoặc dòng nước chảy êm đềm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纭', '{"9000": "4249.0", "Chữ Trung Quốc": "纭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 糸 | mịch | biểu nghĩa | tơ lụa, sợi chỉ | 云 | vân | biểu âm | mây | 纭 = 糸 (Mịch, biểu nghĩa: tơ sợi) + 云 (Vân, biểu âm); chữ hình thanh. Bộ 糸 gợi hình ảnh nhiều sợi chỉ rối, 云 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": 糸 (tơ) + 云 (mây) — như cuộn tơ rối tung lên như mây, lộn xộn bất định. | Gương Hán-Việt | vân trong 纷纭 (phân vân — lộn xộn, đa đoan); 众说纷纭 (chúng thuyết phân vân — mọi người nói mỗi người một kiểu) | Mở khoá kiến thức | Biết 纭 mở khoá thành ngữ 众说纷纭 (chúng thuyết phân vân) — dùng khi diễn đạt ý kiến trái chiều, hỗn loạn.", "Tự nguyên_Xie": "纭 (phồn thể 紜) là chữ hình thanh: 糸 (biểu nghĩa, tơ sợi) + 云 (biểu âm). Wiktionary ghi nghĩa: đông đúc và lộn xộn. Hình ảnh tơ sợi rối như mây (云) gợi sự hỗn loạn, đông đúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lộn xộn", "Hạng Tần Suất (Jun Da)": "4249.0", "Tần Suất % (Jun Da)": "99.8097884458", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纭", "Unihan_Traditional (Chữ Phồn thể)": "紜", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ ghép để chỉ sự hỗn loạn hoặc nhiều ý kiến trái chiều. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潞', '{"9000": "4250.0", "Chữ Trung Quốc": "潞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 潞 | lộ | tượng hình | tên sông ở Bắc Trung Quốc | 潞 có bộ 氵(nước) nhưng cấu trúc nội tại không được xác định rõ trong nguồn. Đây là tên riêng địa lý — chỉ vùng sông Lộ (nay là vùng Vân Nam), dùng trong địa danh và tên người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộ\": 氵(nước) + thân chữ — dòng sông \"lộ\" (lộ ra, chảy về phía đông bắc Trung Quốc). | Gương Hán-Việt | lộ trong 潞江 (Lộ Giang — tên sông), 潞城 (Lộ Thành — địa danh Sơn Tây) | Mở khoá kiến thức | Biết 潞 mở khoá địa danh lịch sử 潞城 (Lộ Thành) và 城濮之战 (trận Thành Bộc thời Xuân Thu).", "Tự nguyên_Xie": "Tiểu triện | 潞 là địa danh chữ, chỉ đoạn trung-hạ lưu sông Salween chảy qua Vân Nam. Wiktionary không phân tích cấu trúc hình thanh cụ thể. Có thể bộ 氵 (nước) là yếu tố biểu nghĩa chỉ sông ngòi. Tiểu triện đã ghi nhận hình thức này. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Lộ", "Hạng Tần Suất (Jun Da)": "4250.0", "Tần Suất % (Jun Da)": "99.8100106634", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 路", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵路", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "路", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潞", "Unihan_Traditional (Chữ Phồn thể)": "潞", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ sông Lộ hoặc địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郅', '{"9000": "4251.0", "Chữ Trung Quốc": "郅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 至 | chí | biểu âm | đến, cực điểm | 邑 | ấp | biểu nghĩa | làng, ấp, địa danh | 郅 = 至 (Chí, biểu âm) + 邑/阝(Ấp, biểu nghĩa: địa danh/nơi chốn); chữ hình thanh. Bộ 邑 (biến thể 阝 bên phải) xác định đây liên quan địa danh hay trạng từ vị trí; 至 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chất\": 至 (đến cực điểm) + 阝 (nơi chốn) — nơi \"chí\" cực, hết mực tốt đẹp. | Gương Hán-Việt | chí trong 郅治 (chí trị — thời thái bình thịnh trị), 郅隆 (chí long — cực thịnh) | Mở khoá kiến thức | Biết 郅 mở khoá tên người (郅 là tên đặt cho con trai mang nghĩa cực tốt, thịnh vượng) và điển cố lịch sử 郅支单于.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 郅 là chữ hình thanh: 至 (biểu âm) + 邑 (biểu nghĩa, địa danh/nơi chốn). Wiktionary ghi nghĩa cổ: \"most; extremely\" (rất, hết mực). Nay dùng chủ yếu trong tên riêng. Tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rất, hết mực", "Hạng Tần Suất (Jun Da)": "4251.0", "Tần Suất % (Jun Da)": "99.8102323643", "GavinGrover_Once (Chiết tự trực tiếp)": "至 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰至阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "至", "Unihan_Simplified (Chữ Giản thể)": "郅", "Unihan_Traditional (Chữ Phồn thể)": "郅", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Danh từ | 名词 | Thường dùng làm phó từ đứng trước tính từ để biểu thị mức độ cao nhất hoặc làm họ người. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弋', '{"9000": "4252.0", "Chữ Trung Quốc": "弋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弋 | Số nét | 3 | nét | 弋 | dặc | tượng hình | cái cọc nhọn — hình ảnh gốc của chữ | 弋 là chữ tượng hình độc lập, chính là bộ thủ của mình. Wiktionary ghi: hình dạng cái cọc nhọn — dạng gốc của chữ 杙 (cái cọc). Giáp cốt văn, kim văn và đại triện đều ghi nhận hình thức này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dặc\": hình cái cọc nhọn cắm xuống đất — người xưa \"dặc\" (bắn tên có dây) để bắt chim. | Gương Hán-Việt | dặc trong 弋猎 (dặc liệp — săn bắn bằng cung tên); 弋获 (dặc hoạch — bắt được) | Mở khoá kiến thức | Biết 弋 mở khoá từ cổ văn 弋不射宿 (Khổng Tử không bắn chim ngủ) — thành ngữ về lòng nhân từ.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | 弋 là chữ tượng hình: hình vẽ một cái cọc nhọn (a sharp peg). Wiktionary xác nhận đây là dạng gốc của 杙 (cái cọc). Cùng nguồn với 才 và 尗. Nghĩa mở rộng sang bắt giữ, bắn cung (bắn tên có dây để lấy lại). Giáp cốt văn có hình thức rõ ràng nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "599.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình cái nỏ bắn tên thời xưa. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khắc họa mũi tên có buộc dây để bắn chim (Dặc).", "Nghĩa Tiếng Việt_Xie": "chiếm lấy", "Hạng Tần Suất (Jun Da)": "4252.0", "Tần Suất % (Jun Da)": "99.8104535483", "GavinGrover_Once (Chiết tự trực tiếp)": "㇂ + 一 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: built", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "㇂一丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "弋", "Unihan_Traditional (Chữ Phồn thể)": "弋", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động săn bắn hoặc đoạt lấy thứ gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飕', '{"9000": "4253.0", "Chữ Trung Quốc": "飕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 13 | nét | 飕 | sưu | tượng hình | tiếng gió vù vù | 飕 là chữ giản thể của 颼, bộ 风 (phong) thay thế bộ 風. Cấu trúc nội tại không được phân tích hình thanh cụ thể trong nguồn. Chữ thuộc nhóm chữ mô phỏng âm thanh liên quan gió.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sưu\": bộ 风 (gió) — âm gió \"sưu sưu\" lạnh buốt, như tiếng rít qua kẽ cửa. | Gương Hán-Việt | sưu trong 飕飕 (sưu sưu — tiếng gió rít); 飕飗 (sưu lưu — gió lạnh thổi) | Mở khoá kiến thức | Biết 飕 mở khoá từ tượng thanh 飕飕 (sōusōu) — âm gió lạnh trong thơ và văn xuôi cổ điển.", "Tự nguyên_Xie": "飕 là dạng giản thể của 颼, thay bộ 風 (phong) bằng 风. Wiktionary ghi đây là chữ giản hoá, tra cứu chính tại 颼. Âm thanh gió vù vù, lạnh buốt. Không có hình thức giáp cốt hay kim văn. chưa có nguồn học thuật về cấu tạo gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng gió vù vù", "Hạng Tần Suất (Jun Da)": "4253.0", "Tần Suất % (Jun Da)": "99.8106747323", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飕", "Unihan_Traditional (Chữ Phồn thể)": "颼", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Thường dùng làm động từ miêu tả tiếng gió thổi mạnh hoặc cảm giác lạnh buốt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螳', '{"9000": "4254.0", "Chữ Trung Quốc": "螳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 螳 | đường | tượng hình | con bọ ngựa (螳螂) | 螳 có bộ 虫 (trùng) là thành phần biểu nghĩa chỉ côn trùng, nhưng cấu trúc hình thanh nội tại không được xác định cụ thể trong nguồn. Chữ dùng chủ yếu trong tổ hợp 螳螂 (bọ ngựa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": bộ 虫 (trùng/côn trùng) — con côn trùng \"đường đường\" đứng thẳng chặn đường xe. | Gương Hán-Việt | đường trong 螳螂 (đường lang — bọ ngựa); 螳臂当车 (đường tý đương xa — bọ ngựa chặn xe, chỉ sức yếu đối đầu sức mạnh) | Mở khoá kiến thức | Biết 螳 mở khoá thành ngữ 螳臂当车 (đường tý đương xa) — chỉ người tự lượng sức không nổi mà liều lĩnh.", "Tự nguyên_Xie": "Tiểu triện | 螳 là chữ chỉ bọ ngựa, thuộc bộ 虫 (trùng). Wiktionary không cung cấp phân tích hình thành chữ cụ thể. Nghĩa chính là bọ ngựa (螳螂). Tiểu triện được ghi nhận. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đường lang 螳螂)", "Hạng Tần Suất (Jun Da)": "4254.0", "Tần Suất % (Jun Da)": "99.8108959164", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螳", "Unihan_Traditional (Chữ Phồn thể)": "螳", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ, hầu như chỉ xuất hiện trong từ ghép để chỉ con bọ ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胄', '{"9000": "4255.0", "Chữ Trung Quốc": "胄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 由 | do | biểu âm | từ, do | 胄 = 肉 (Nhục, biểu nghĩa: cơ thể/dòng dõi) + 由 (Do, biểu âm); chữ hình thanh. Wiktionary ghi 胄 phân kỳ từ dạng biến thể của 冑 (mũ trụ). Nay 胄 chỉ nghĩa dòng dõi, hậu duệ; 冑 chỉ mũ giáp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụ\": 肉 (cơ thể) + 由 (do/từ) — hậu duệ là người \"trụ\" cột kế thừa từ cơ thể (dòng máu) của tổ tiên. | Gương Hán-Việt | trụ trong 贵胄 (quý trụ — dòng dõi quý tộc); 华胄 (Hoa trụ — con cháu người Hoa) | Mở khoá kiến thức | Biết 胄 mở khoá từ cổ văn 贵胄 (quý tộc danh gia), 天潢贵胄 (thiên hoàng quý trụ — dòng dõi hoàng tộc).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 胄 là chữ hình thanh: 肉 (biểu nghĩa) + 由 (biểu âm). Wiktionary ghi nhận chữ này phân kỳ từ 冑 (mũ trụ). Nghĩa trong văn cổ: hậu duệ, con cháu (thế hệ tiếp nối). Kim văn và tiểu triện ghi nhận đầy đủ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũ trụ (đội cùng áo giáp)", "Hạng Tần Suất (Jun Da)": "4255.0", "Tần Suất % (Jun Da)": "99.8111165836", "GavinGrover_Once (Chiết tự trực tiếp)": "由 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱由月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胄", "Unihan_Traditional (Chữ Phồn thể)": "胄", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ mũ giáp của binh lính thời cổ hoặc hậu duệ của quý tộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟑', '{"9000": "4256.0", "Chữ Trung Quốc": "蟑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蟑 | chương | tượng hình | con gián (蟑螂) | 蟑 có bộ 虫 (trùng) là thành phần gợi nghĩa côn trùng, nhưng không có nguồn Wiktionary về cấu tạo hình thanh. Chữ dùng độc quyền trong tổ hợp 蟑螂 (con gián).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": bộ 虫 (trùng) — con côn trùng chạy \"chương\" (nhanh như chương pháp ghi lại) khắp sàn nhà. | Gương Hán-Việt | chương trong 蟑螂 (chương lang — con gián) | Mở khoá kiến thức | Biết 蟑 mở khoá từ thường dùng 蟑螂 (gián) — côn trùng gây hại phổ biến nhất trong gia đình.", "Tự nguyên_Xie": "蟑 không có nguồn Wiktionary về cấu tạo. Bộ 虫 (trùng) gợi đây là côn trùng. Chữ dùng chủ yếu trong 蟑螂 (zhāngláng — con gián). Không có hình thức cổ được ghi nhận. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: chương lang 蟑螂)", "Hạng Tần Suất (Jun Da)": "4256.0", "Tần Suất % (Jun Da)": "99.8113372509", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟑", "Unihan_Traditional (Chữ Phồn thể)": "蟑", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ, chủ yếu kết hợp tạo thành từ ghép chỉ con gián. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猥', '{"9000": "4257.0", "Chữ Trung Quốc": "猥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 犬 | khuyển | biểu nghĩa | chó | 畏 | uý | biểu âm | sợ hãi | 猥 = 犬 (Khuyển, biểu nghĩa: chó) + 畏 (Uý, biểu âm); chữ hình thanh. Bộ 犬/犭biểu thị hành vi thú vật hay tính khí xấu; 畏 cung cấp âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uý\": 犬 (chó) + 畏 (sợ hãi) — hành vi hèn hạ như chó sợ sệt, luôn tìm cách bẩn thỉu, dâm tục. | Gương Hán-Việt | uý trong 猥亵 (uý tiết — dâm ô, sàm sỡ); 猥琐 (uý toả — hèn hạ, bẩn thỉu) | Mở khoá kiến thức | Biết 猥 mở khoá từ pháp lý 猥亵 (dâm ô) và từ mô tả tính cách 猥琐 (hèn hạ, xấu xí về nhân cách).", "Tự nguyên_Xie": "Tiểu triện | 猥 là chữ hình thanh: 犬 (biểu nghĩa) + 畏 (biểu âm). Wiktionary ghi nghĩa cổ: đông đúc, nhiều; sau đó chuyển sang thấp hèn, dâm ô, tục tĩu. Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hèn, tạp nhạp", "Hạng Tần Suất (Jun Da)": "4257.0", "Tần Suất % (Jun Da)": "99.8115574014", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 畏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猥", "Unihan_Traditional (Chữ Phồn thể)": "猥", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "ổi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả tính cách hèn mọn hoặc hành vi bỉ ổi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宓', '{"9000": "4258.0", "Chữ Trung Quốc": "宓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 8 | nét | 宀 | miên | biểu nghĩa | mái nhà | 必 | tất | biểu âm | nhất định | 宓 = 宀 (Miên, biểu nghĩa: mái nhà) + 必 (Tất, biểu âm); chữ hình thanh. Wiktionary ghi ý nghĩa hình ảnh: ẩn trong nhà (hidden at home). Mái nhà + 必 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mật\": 宀 (mái nhà) + 必 (nhất định) — nhất định ở trong nhà, yên lặng, \"mật\" kín. | Gương Hán-Việt | mật trong 宓羲 (Mật Hy — tên khác của Phục Hy, thủy tổ văn hoá Trung Hoa) | Mở khoá kiến thức | Biết 宓 mở khoá tên cổ 宓妃 (Mật Phi — tiên nữ sông Lạc trong Lạc Thần Phú của Tào Thực).", "Tự nguyên_Xie": "Tiểu triện | 宓 là chữ hình thanh: 宀 (biểu nghĩa, mái nhà) + 必 (biểu âm). Wiktionary ghi hình ảnh gốc: ẩn dật trong nhà. Nghĩa: yên tĩnh, kín đáo. Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1065.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (040) Tất (364)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Miên (số 040 - mái nhà) che trên chữ Tất (số 364 - ắt hẳn/chỉ âm). Có nhà cửa che mưa nắng thì ắt hẳn sẽ an cư lạc nghiệp. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Tất chỉ âm, bộ Miên chỉ ý. Mật là yên ổn, yên lặng, ngừng nghỉ.", "Nghĩa Tiếng Việt_Xie": "yên lặng", "Hạng Tần Suất (Jun Da)": "4258.0", "Tần Suất % (Jun Da)": "99.8117775518", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宓", "Unihan_Traditional (Chữ Phồn thể)": "宓", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự yên tĩnh hoặc làm danh từ riêng chỉ họ người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昙', '{"9000": "4259.0", "Chữ Trung Quốc": "昙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 昙 | đàm | tượng hình | mây che khuất mặt trời, trời u ám | 昙 là dạng giản thể của 曇, thay bộ 雲 (mây) bằng 云. Cấu trúc gốc: 日 (mặt trời) + 雲/云 (mây) — mây che mặt trời, trời u ám. Nay chữ giản thể 昙 chủ yếu dùng trong tên riêng, nhất là 昙花 (hoa quỳnh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": 日 (mặt trời) bị mây che — trời \"đàm\" (u ám) chỉ chợt sáng rồi tắt, như 昙花一现. | Gương Hán-Việt | đàm trong 昙花一现 (đàm hoa nhất hiện — hoa quỳnh nở rồi tàn, chỉ điều tốt đẹp không bền) | Mở khoá kiến thức | Biết 昙 mở khoá thành ngữ 昙花一现 (đàm hoa nhất hiện) — thường dùng ví tài năng hay sự nghiệp xuất hiện rồi biến mất.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 昙 là dạng giản thể của 曇 (thay 雲 bằng 云). Wiktionary ghi: tra cứu chính tại 曇. Hình ảnh gốc: 日 (mặt trời) bị 雲 (mây) che khuất — trời u ám. Tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mây chùm", "Hạng Tần Suất (Jun Da)": "4259.0", "Tần Suất % (Jun Da)": "99.8119977023", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昙", "Unihan_Traditional (Chữ Phồn thể)": "曇", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ trong từ ghép để chỉ hoa quỳnh hoặc trạng thái nhiều mây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锏', '{"9000": "4260.0", "Chữ Trung Quốc": "锏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锏 | giản | tượng hình | cái giản — vũ khí ba cạnh | 锏 có bộ 钅(金, kim) gợi chất liệu kim loại, nhưng cấu trúc hình thanh nội tại không được phân tích trong nguồn. Phồn thể 鐧 cũng không có dữ liệu Han compound. Chữ chỉ loại vũ khí kim loại có 3 cạnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": bộ 钅(kim loại) — cây vũ khí kim loại \"giản\" dị về hình thức nhưng uy lực trong tay võ tướng. | Gương Hán-Việt | giản trong 锏法 (giản pháp — võ thuật dùng giản); 双锏 (song giản — đôi giản) | Mở khoá kiến thức | Biết 锏 mở khoá từ võ thuật và lịch sử: 双锏 (song giản) là vũ khí của danh tướng Tần Thúc Bảo trong Tùy Đường diễn nghĩa.", "Tự nguyên_Xie": "锏 (phồn thể 鐧) là vũ khí kim loại có tiết diện vuông hoặc tam giác, không có lưỡi bén. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Bộ 钅(kim) gợi chất liệu. chưa có nguồn học thuật về cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giản (một thứ binh khí, giống roi có 3 cạnh; vành sắt bọc bánh xe", "Hạng Tần Suất (Jun Da)": "4260.0", "Tần Suất % (Jun Da)": "99.8122178528", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 间", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅间", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "间", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锏", "Unihan_Traditional (Chữ Phồn thể)": "鐧", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại vũ khí cổ hoặc vành sắt bọc bánh xe. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟠', '{"9000": "4261.0", "Chữ Trung Quốc": "蟠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟠 | bàn | tượng hình | cuộn khúc, bàn xoáy | 蟠 có bộ 虫 (trùng) gợi nghĩa liên quan sinh vật/rồng rắn, nhưng cấu trúc hình thanh không được phân tích cụ thể trong nguồn. Wiktionary chỉ ghi {{Han etym}} mà không có Han compound. Tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàn\": bộ 虫 (trùng/rồng) — con rồng \"bàn\" khúc ẩn phục, cuộn tròn chờ thời. | Gương Hán-Việt | bàn trong 蟠龙 (bàn long — rồng cuộn); 蟠桃 (bàn đào — đào tiên cuộn — trong Tây Du Ký) | Mở khoá kiến thức | Biết 蟠 mở khoá từ cổ điển 蟠龙 (rồng cuộn, ẩn mình) và 蟠桃会 (hội đào tiên trong Tây Du Ký).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 蟠 có bộ 虫 (trùng) gợi hình ảnh sinh vật cuộn khúc. Wiktionary không cung cấp phân tích cấu trúc. Nghĩa: cuộn tròn, ẩn phục, chiếm cứ. Tiểu triện và lục thư thông ghi nhận hình thức này. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuộn khúc", "Hạng Tần Suất (Jun Da)": "4261.0", "Tần Suất % (Jun Da)": "99.8124380032", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟠", "Unihan_Traditional (Chữ Phồn thể)": "蟠", "Pinyin_Xie": "pán", "Âm Hán Việt_Xie": "bàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành động cuộn tròn hoặc làm tính từ mô tả trạng thái uốn khúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柑', '{"9000": "4262.0", "Chữ Trung Quốc": "柑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 甘 | cam | biểu âm | ngọt | 柑 = 木 (Mộc, biểu nghĩa: cây) + 甘 (Cam, biểu âm); chữ hình thanh. Bộ 木 xác định đây là cây ăn quả; 甘 (ngọt) cung cấp âm và cũng gợi vị ngọt của quả cam. Wiktionary lưu ý 柑 không liên quan 某 dù hình dạng tương tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cam\": 木 (cây) + 甘 (ngọt) — cây cho quả \"cam\" ngọt lịm; âm biểu nghĩa và biểu âm trùng nhau hoàn hảo. | Gương Hán-Việt | cam trong 柑橘 (cam quất — cam quýt); 柑橘类 (cam quất loại — họ cam quýt) | Mở khoá kiến thức | Biết 柑 mở khoá toàn bộ từ về cam quýt: 柑橘/橘子/橙子 — và ẩn dụ 苦尽甘来 (khổ tận cam lai — hết khổ đến ngọt).", "Tự nguyên_Xie": "柑 là chữ hình thanh: 木 (biểu nghĩa, cây) + 甘 (biểu âm). Wiktionary xác nhận cấu trúc này và lưu ý: tuy hình dạng tương tự 某 nhưng không cùng gốc. Nghĩa: cây cam quýt (tangerine). Âm Hán-Việt cam trùng với 甘 (ngọt) — cam vừa ngọt vừa là tên cây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cam", "Hạng Tần Suất (Jun Da)": "4262.0", "Tần Suất % (Jun Da)": "99.8128777874", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柑", "Unihan_Traditional (Chữ Phồn thể)": "柑", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "cam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại cây hoặc quả thuộc họ cam quýt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烯', '{"9000": "4263.0", "Chữ Trung Quốc": "烯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 火 | hoả | biểu nghĩa | lửa | 希 | hy | biểu âm | hy vọng, hiếm | 烯 = 火/灬 (Hoả, biểu nghĩa: lửa, liên quan năng lượng/hóa học) + 希 (Hy, biểu âm); chữ hình thanh. Bộ 火 gợi liên hệ hóa học (đốt cháy); 希 cung cấp âm. Đây là chữ tạo muộn dùng trong thuật ngữ hóa học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hy\": 火 (lửa/năng lượng) + 希 (hy hữu) — loại hydrocarbon \"hy\" hữu có liên kết đôi, cháy được. | Gương Hán-Việt | hy trong 乙烯 (ất hy — ethylene); 烯烃 (hy thăng — alkene); 乙烯基 (ất hy cơ — vinyl) | Mở khoá kiến thức | Biết 烯 mở khoá toàn bộ thuật ngữ hóa học alkene: 乙烯 (ethylene), 丙烯 (propylene), 苯乙烯 (styrene).", "Tự nguyên_Xie": "烯 là chữ hình thanh tạo muộn: 火 (biểu nghĩa, lửa/hóa học) + 希 (biểu âm, xī). Wiktionary xác nhận cấu trúc với ghi chú no_och2 (không có âm Thượng Cổ cho 希 trong ngữ cảnh này). Chữ tạo để phiên âm thuật ngữ alkene (các chất CnH2n). chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các chất anken (công thức hoá học: CnH2n)", "Hạng Tần Suất (Jun Da)": "4263.0", "Tần Suất % (Jun Da)": "99.8130974211", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 希", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火希", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烯", "Unihan_Traditional (Chữ Phồn thể)": "烯", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong hóa học để chỉ các hợp chất hydrocacbon có liên kết đôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匐', '{"9000": "4264.0", "Chữ Trung Quốc": "匐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 11 | nét | 匐 | bặc | tượng hình | bò sát đất, phủ phục | 匐 có bộ 勹 nhưng cấu trúc hình thanh nội tại không được phân tích cụ thể trong nguồn. Wiktionary chỉ liệt kê phát âm và cho biết chữ dùng độc quyền trong 匍匐 (bò sát đất). Đại triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bặc\": bộ 勹 (hình người cúi) — phủ \"bặc\" xuống sát đất, khom người bò. | Gương Hán-Việt | bặc trong 匍匐 (bồ bặc — bò sát đất, phủ phục); 匍匐前进 (bồ bặc tiền tiến — bò tiến về phía trước) | Mở khoá kiến thức | Biết 匐 mở khoá từ quân sự 匍匐前进 và thành ngữ 匍匐之救 (cứu giúp hết sức khẩn cấp, kể cả phải bò đến).", "Tự nguyên_Xie": "Đại triện | 匐 dùng chủ yếu trong 匍匐 (fúfú — bò sát đất, phủ phục). Wiktionary ghi chỉ dùng trong 匍匐. Bộ 勹 có thể gợi hình người cong khom. Đại triện được ghi nhận. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1840.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (020) Phúc (525)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Bao (số 020 - bao bọc/ 勹 /chỉ ý) bao bên ngoài chữ Phúc (số 525 - đầy đủ/ 畐 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phúc chỉ âm, bộ Bao chỉ ý. Bặc (Phục) là hành động phục xuống bò, trườn trên mặt đất (bồ phục - nằm bò).", "Nghĩa Tiếng Việt_Xie": "(xem: bồ bặc 匍匐)", "Hạng Tần Suất (Jun Da)": "4264.0", "Tần Suất % (Jun Da)": "99.8133170547", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 畐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹畐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "匐", "Unihan_Traditional (Chữ Phồn thể)": "匐", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "bặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ nhưng hầu như chỉ dùng trong từ ghép liên hợp chỉ hành động bò trườn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濮', '{"9000": "4265.0", "Chữ Trung Quốc": "濮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 17 | nét | 水 | thủy | biểu nghĩa | nước | 僕 | bộc | biểu âm | đầy tớ | 濮 = 水/氵(Thủy, biểu nghĩa: nước/sông) + 僕 (Bộc, biểu âm); chữ hình thanh. Bộ 氵 xác định đây là tên sông; 僕 cung cấp âm. Tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộc\": 氵(nước) + 僕 (đầy tớ) — sông \"bộc\" như người đầy tớ âm thầm phục vụ đất đai màu mỡ. | Gương Hán-Việt | bộc trong 桑间濮上 (tang gian bộc thượng — khúc nhạc đồi bại); 城濮之战 (thành bộc chi chiến — trận Thành Bộc 632 TCN) | Mở khoá kiến thức | Biết 濮 mở khoá điển cố lịch sử 城濮之战 (trận Thành Bộc, Tấn đánh Sở) và 桑间濮上 (âm nhạc đồi bại).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 濮 là chữ hình thanh: 水/氵(biểu nghĩa, nước) + 僕 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa: tên sông cổ (sông Bộc ở Sơn Đông); cũng là tên tộc người cổ (Pu). Trích Thượng Thư có nhắc đến người Bộc (濮人). Tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Bộc; tên một giống rợ", "Hạng Tần Suất (Jun Da)": "4265.0", "Tần Suất % (Jun Da)": "99.8135366884", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 僕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵僕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "僕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濮", "Unihan_Traditional (Chữ Phồn thể)": "濮", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên sông hoặc tên một bộ tộc cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟮', '{"9000": "4266.0", "Chữ Trung Quốc": "蟮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 虫 | trùng | biểu nghĩa | côn trùng, giun sán | 善 | thiện | biểu âm | thiện lành | 蟮 = 虫 (Trùng, biểu nghĩa: côn trùng/giun) + 善 (Thiện, biểu âm); chữ hình thanh. Bộ 虫 xác định đây là loài giun/lươn; 善 cung cấp âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": 虫 (giun) + 善 (thiện) — con giun lươn \"thiện\" ích cho đất, âm thầm làm việc tốt. | Gương Hán-Việt | thiện trong 蟮鱼 (thiện ngư — con lươn); 蟮子 (thiện tử — con giun đất) | Mở khoá kiến thức | Biết 蟮 giúp nhận ra bộ 虫 trong chữ chỉ sinh vật dưới đất; mở khoá ngữ nghĩa của các chữ 蛇, 蟒, 蚯 (giun dế).", "Tự nguyên_Xie": "蟮 là chữ hình thanh: 虫 (biểu nghĩa, giun/côn trùng) + 善 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa: loại giun đất, con lươn. Chữ dùng trong văn nói dân gian về sinh vật bò dưới đất. chưa có hình thức giáp cốt hay kim văn được ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lươn", "Hạng Tần Suất (Jun Da)": "4266.0", "Tần Suất % (Jun Da)": "99.8137563221", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 善", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫善", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "善", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟮", "Unihan_Traditional (Chữ Phồn thể)": "蟮", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con lươn hoặc con giun đất trong các từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祐', '{"9000": "4267.0", "Chữ Trung Quốc": "祐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 礻 | thị | biểu nghĩa | thần linh, lễ nghi | 右 | hữu | biểu âm | bên phải | 祐 = 礻(Thị, biểu nghĩa: thần linh/lễ nghi) + 右 (Hữu, biểu âm); chữ hình thanh. Bộ 礻(示) gợi sự phù hộ của thần linh; 右 cung cấp âm. Tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hựu\": 礻(thần) + 右 (phải/hữu) — thần linh đứng bên \"hữu\" (phải), ở bên phù hộ. | Gương Hán-Việt | hựu trong 神祐 (thần hựu — thần linh phù hộ); 天祐 (thiên hựu — trời phù hộ); 祐护 (hựu hộ — che chở) | Mở khoá kiến thức | Biết 祐 mở khoá các từ cầu phúc: 神祐, 天祐, 保祐 (bảo hựu) — tất cả đều mang nghĩa được trên cao che chở.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 祐 là chữ hình thanh: 礻(示, biểu nghĩa, thần linh) + 右 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa: sự phù hộ của thần linh, ban phúc lành. Tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phù hộ; giúp đỡ; phù trợ (thần linh)", "Hạng Tần Suất (Jun Da)": "4267.0", "Tần Suất % (Jun Da)": "99.813975439", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 右", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻右", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "右", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祐", "Unihan_Traditional (Chữ Phồn thể)": "祐", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "hựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự phù hộ, giúp đỡ của thần linh đối với con người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仄', '{"9000": "4268.0", "Chữ Trung Quốc": "仄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 4 | nét | 厂 | hán | biểu nghĩa | vách đá, mái đá | 夨 | trắc | biểu âm | người nghiêng đầu | 仄 = 厂 (Hán, biểu nghĩa: vách đá/mái đá) + 夨 (biểu âm: người nghiêng đầu); chữ hình thanh. Wiktionary ghi đây cũng có thể là hội ý (ls2=ic): người đứng nghiêng dưới vách đá — gợi nghĩa xiêu lệch, nghiêng. Tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trắc\": 厂 (vách) + 夨 (người nghiêng) — người đứng \"trắc\" (nghiêng) dưới vách đá, gợi âm trắc trong thơ Đường luật. | Gương Hán-Việt | trắc trong 仄声 (trắc thanh — âm trắc trong thi pháp); 仄押 (trắc áp — gieo vần trắc); 平仄 (bình trắc) | Mở khoá kiến thức | Biết 仄 mở khoá toàn bộ thi pháp Đường luật: 平仄 (bình trắc) là quy tắc phối âm cốt lõi của thơ Hán.", "Tự nguyên_Xie": "Tiểu triện | 仄 là chữ hình thanh kiêm hội ý: 厂 (vách đá, biểu nghĩa) + 夨 (người nghiêng đầu, biểu âm và cũng biểu ý). Wiktionary ghi: người nghiêng dưới vách đá — oblique, slanted. Âm Hán-Việt trắc cũng là thuật ngữ thanh điệu: âm trắc (tất cả thanh ngoài bình thanh). Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiêng ngả; âm trắc", "Hạng Tần Suất (Jun Da)": "4268.0", "Tần Suất % (Jun Da)": "99.8141945559", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 人", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "仄", "Unihan_Traditional (Chữ Phồn thể)": "仄", "Pinyin_Xie": "zè", "Âm Hán Việt_Xie": "trắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ trạng thái nghiêng lệch hoặc làm danh từ chỉ thanh trắc trong âm vận học. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偈', '{"9000": "4269.0", "Chữ Trung Quốc": "偈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 亻 | nhân | biểu nghĩa | người | 曷 | hạt | biểu âm | tại sao, bao giờ | 偈 = 亻(Nhân, biểu nghĩa: người) + 曷 (Hạt, biểu âm); chữ hình thanh. Bộ 亻gợi liên quan con người; 曷 cung cấp âm. Nghĩa lời kệ Phật giáo là mượn âm từ Sanskrit gāthā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kệ\": 亻(người) + 曷 (hạt) — người tu sĩ tụng \"kệ\" ngắn gọn súc tích để truyền đạo. | Gương Hán-Việt | kệ trong 偈语 (kệ ngữ — lời kệ); 偈颂 (kệ tụng — bài kệ); 说偈 (thuyết kệ — thuyết pháp bằng kệ) | Mở khoá kiến thức | Biết 偈 mở khoá toàn bộ thuật ngữ Phật học: kệ là thể thơ bốn câu hoặc ngắn hơn trong kinh điển Phật giáo Hán ngữ.", "Tự nguyên_Xie": "偈 là chữ hình thanh: 亻(biểu nghĩa, người) + 曷 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa lời kệ Phật giáo là phiên âm Sanskrit gāthā (kệ tụng). Trong Phật học Hán-Việt, kệ (偈) là thể thơ Phật giáo ngắn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời kệ (các bài thơ của Phật)", "Hạng Tần Suất (Jun Da)": "4269.0", "Tần Suất % (Jun Da)": "99.8144136728", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偈", "Unihan_Traditional (Chữ Phồn thể)": "偈", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kệ, khế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các bài thơ, bài kệ tụng kinh trong Phật giáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜃', '{"9000": "4270.0", "Chữ Trung Quốc": "蜃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 辰 | thìn | biểu âm | can Thìn (rồng) | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật | 蜃 = 辰 (Thìn, biểu âm) + 虫 (Trùng, biểu nghĩa: sinh vật/côn trùng); chữ hình thanh. Wiktionary ghi: có thể cũng là hội ý — 辰 vốn là công cụ nông nghiệp làm bằng vỏ sò, liên kết ý nghĩa với nghề nông và sò/ốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thần\": 辰 (Thìn/rồng) + 虫 (sinh vật) — con sinh vật huyền bí như rồng dưới biển, tạo ra ảo ảnh 蜃楼. | Gương Hán-Việt | thần trong 蜃楼 (thần lâu — lầu ảo giác); 海市蜃楼 (hải thị thần lâu — thành phố ảo trên biển, mirage) | Mở khoá kiến thức | Biết 蜃 mở khoá thành ngữ 海市蜃楼 (hải thị thần lâu) — dùng ví mộng ảo, hoang tưởng không thực tế.", "Tự nguyên_Xie": "Tiểu triện | 蜃 là chữ hình thanh: 辰 (biểu âm) + 虫 (biểu nghĩa). Wiktionary ghi thêm khả năng hội ý: 辰 vốn là công cụ làm bằng vỏ sò. Nghĩa: loài nhuyễn thể biển (sò, ốc, hến); trong thần thoại: con thủy quái biến hóa tạo ảo ảnh (蜃楼 — lầu mirage). Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loài ốc, sò, hến; đồ tế", "Hạng Tần Suất (Jun Da)": "4270.0", "Tần Suất % (Jun Da)": "99.8146327897", "GavinGrover_Once (Chiết tự trực tiếp)": "辰 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辰虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辰", "Unihan_Simplified (Chữ Giản thể)": "蜃", "Unihan_Traditional (Chữ Phồn thể)": "蜃", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "thận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài sò lớn hoặc con yêu quái biển theo truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箴', '{"9000": "4271.0", "Chữ Trung Quốc": "箴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 𥫗 | trúc | biểu nghĩa | tre, trúc | 咸 | hàm | biểu âm | tất cả, mặn | 箴 = 𥫗/竹 (Trúc, biểu nghĩa: tre) + 咸 (Hàm, biểu âm); chữ hình thanh. Wiktionary ghi: que tre nhọn dùng như kim châm. Nghĩa mở rộng sang lời khuyên răn (khắc trên thẻ tre để ghi nhớ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chăm\": 竹 (tre) + 咸 (hàm/tất cả) — que tre nhọn \"chăm\" châm vào tất cả lỗi sai để khuyên răn. | Gương Hán-Việt | chăm trong 箴言 (chăm ngôn — lời khuyên răn, châm ngôn); 箴规 (chăm quy — lời can gián) | Mở khoá kiến thức | Biết 箴 mở khoá từ 箴言 (châm ngôn/lời khuyên răn) — sách Châm Ngôn trong Kinh Thánh cũng dùng chữ này.", "Tự nguyên_Xie": "Tiểu triện | 箴 là chữ hình thanh: 竹 (biểu nghĩa, tre) + 咸 (biểu âm). Wiktionary ghi: que tre nhọn, đầu kim — a bamboo needle, probe. Từ đó mở rộng sang nghĩa can gián, khuyên răn (như kim châm vào trái tim). Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuyên răn; viết chữ hay khắc vào gỗ để trông làm gương; đơn vị đếm lông chim, bằng 10 cái", "Hạng Tần Suất (Jun Da)": "4271.0", "Tần Suất % (Jun Da)": "99.8148519066", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 咸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箴", "Unihan_Traditional (Chữ Phồn thể)": "箴", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ lời khuyên răn hoặc động từ mang nghĩa khuyên bảo, cảnh tỉnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粼', '{"9000": "4272.0", "Chữ Trung Quốc": "粼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 粦 | lân | biểu âm | ma trơi | 巜 | quái | biểu nghĩa | khe nước, dòng chảy nhỏ | 粼 = 粦 (Lân, biểu âm) + 巜 (biểu nghĩa: khe nước). Wiktionary xác nhận cấu trúc hình thanh này. Nghĩa: nước trong vắt chảy giữa các hòn đá — lấp lánh sáng trong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": 粦 (lân/lấp lánh) + 巜 (khe nước) — ánh nước \"lân\" lân lấp lánh qua kẽ đá. | Gương Hán-Việt | lân trong 粼粼 (lân lân — lấp lánh, ánh sáng trên nước); 波光粼粼 (ba quang lân lân — sóng nước lấp lánh) | Mở khoá kiến thức | Biết 粼 mở khoá thành ngữ thơ 波光粼粼 (ba quang lân lân) — hình ảnh thơ ca phổ biến diễn tả mặt nước lấp lánh.", "Tự nguyên_Xie": "粼 là chữ hình thanh: 粦 (biểu âm) + 巜 (biểu nghĩa, khe nước). Wiktionary xác nhận cấu trúc. Nghĩa: nước trong vắt, ánh sáng lấp lánh trên mặt nước giữa các hòn đá. Không có hình thức cổ được ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước ở giữa các hòn đá", "Hạng Tần Suất (Jun Da)": "4272.0", "Tần Suất % (Jun Da)": "99.8150710235", "GavinGrover_Once (Chiết tự trực tiếp)": "粦 + 巜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰粦巜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巜", "Unihan_Simplified (Chữ Giản thể)": "粼", "Unihan_Traditional (Chữ Phồn thể)": "粼", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ mô tả vẻ lấp lánh của nước chảy qua kẽ đá, hay gặp trong từ láy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗥', '{"9000": "4273.0", "Chữ Trung Quốc": "嗥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗥 | háo | tượng hình | tiếng gào, rú, tru | 嗥 có bộ 口 (khẩu) là thành phần biểu nghĩa gợi âm thanh/tiếng kêu, nhưng cấu trúc hình thanh nội tại không được phân tích cụ thể trong nguồn. Chữ thuộc nhóm mô phỏng âm thanh gào thét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"háo\": bộ 口 (miệng) — miệng mở rộng \"háo\" to gào thét, như tiếng sói tru. | Gương Hán-Việt | háo trong 嗥叫 (háo khiếu — gào thét); 狼嗥 (lang háo — tiếng sói tru); 鬼哭狼嗥 (quỷ khốc lang háo) | Mở khoá kiến thức | Biết 嗥 mở khoá thành ngữ 鬼哭狼嗥 (quỷ khốc lang háo — quỷ khóc sói rú, chỉ tiếng than thảm hoặc hỗn loạn tột cùng).", "Tự nguyên_Xie": "Tiểu triện | 嗥 (đồng nghĩa 噑) có bộ 口 gợi âm thanh. Wiktionary ghi cùng dạng với 噑. Nghĩa: gào, tru (như sói), khóc lóc. Tiểu triện được ghi nhận. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gào, gầm, rống, tru; kêu khóc", "Hạng Tần Suất (Jun Da)": "4273.0", "Tần Suất % (Jun Da)": "99.8152896236", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 皋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口皋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗥", "Unihan_Traditional (Chữ Phồn thể)": "嗥", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mô tả tiếng tru, gầm của thú dữ hoặc tiếng khóc lóc thảm thiết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褴', '{"9000": "4274.0", "Chữ Trung Quốc": "褴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 衣 | y | biểu nghĩa | quần áo | 監 | giám | biểu âm | giám sát | 褴 = 衣/衤 (Y, biểu nghĩa: quần áo) + 監 (Giám, biểu âm); chữ hình thanh. Bộ 衤(y) xác định liên quan quần áo; 監 cung cấp âm. Tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\": 衤(quần áo) + 監 (giám/kiểm tra) — quần áo bị \"lam\" nhàm, không qua nổi một lần kiểm tra vì đã tả tơi. | Gương Hán-Việt | lam trong 褴褛 (lam lũ — tả tơi, rách rưới); 衣衫褴褛 (y sam lam lũ — áo quần tả tơi) | Mở khoá kiến thức | Biết 褴 mở khoá từ thường dùng 褴褛 và thành ngữ 衣衫褴褛 — diễn tả sự nghèo đói, khốn khổ trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 褴 (phồn thể 襤) là chữ hình thanh: 衣 (biểu nghĩa, quần áo) + 監 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa: áo rách nát, không có viền — áo quần tả tơi. Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo không viền", "Hạng Tần Suất (Jun Da)": "4274.0", "Tần Suất % (Jun Da)": "99.8155082237", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 监", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤监", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "监", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褴", "Unihan_Traditional (Chữ Phồn thể)": "襤", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả trang phục rách rưới, tả tơi trong từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕨', '{"9000": "4275.0", "Chữ Trung Quốc": "蕨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕨 | quyết | tượng hình | cây dương xỉ (pteris aquilina) | 蕨 có bộ 艹 (thảo) là thành phần biểu nghĩa chỉ thực vật, nhưng cấu trúc hình thanh nội tại không được phân tích cụ thể trong nguồn ({{Han etym}} không có compound). Tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ 艹 (cỏ) — loài cây dương xỉ \"quyết\" (khỏe mạnh, dai sức, mọc khắp nơi từ rừng núi đến đồng bằng). | Gương Hán-Việt | quyết trong 蕨类植物 (quyết loại thực vật — thực vật dương xỉ); 蕨菜 (quyết thái — rau dương xỉ ăn được) | Mở khoá kiến thức | Biết 蕨 mở khoá thuật ngữ sinh học 蕨类植物 (Pteridophyta — ngành dương xỉ) và thực phẩm truyền thống 蕨菜 ở các vùng sơn cước.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 蕨 có bộ 艹 gợi đây là thực vật. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc. Nghĩa: cây dương xỉ (bracken fern, Pteridium aquilinum) — loài cây ăn được và làm thuốc. Tiểu triện và lục thư thông được ghi nhận. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau (để ăn)", "Hạng Tần Suất (Jun Da)": "4275.0", "Tần Suất % (Jun Da)": "99.815726307", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕨", "Unihan_Traditional (Chữ Phồn thể)": "蕨", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loài cây thuộc họ dương xỉ hoặc món ăn làm từ chúng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓟', '{"9000": "4276.0", "Chữ Trung Quốc": "蓟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓟 | kế | tượng hình | cây kế (cỏ dược liệu có gai) | 蓟 có bộ 艹 (thảo) gợi đây là thực vật, nhưng không có nguồn Wiktionary về cấu tạo hình thanh (usedForm và glyphOrigin đều null). Tiểu triện được ghi nhận nhưng chưa có phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kế\": bộ 艹 (cỏ) — cỏ \"kế\" có gai nhọn, dù gai góc vẫn là vị thuốc quý. | Gương Hán-Việt | kế trong 蓟州 (Kế Châu — địa danh cổ gần Bắc Kinh); 大蓟 (đại kế — cây đại kế trong y học cổ truyền) | Mở khoá kiến thức | Biết 蓟 mở khoá địa danh lịch sử 蓟 (kinh đô nước Yên), tên huyện 蓟州, và từ dược liệu 大蓟/小蓟 trong y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | 蓟 không có nguồn Wiktionary về cấu tạo. Bộ 艹 xác định đây là thực vật. Nghĩa: cây kế (Cirsium/Carduus — loài cỏ có gai, dùng làm thuốc). Cũng là địa danh cổ (蓟 — kinh đô nước Yên thời Chiến Quốc, nay là Bắc Kinh). Tiểu triện được ghi nhận. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ kế (dùng làm thuốc)", "Hạng Tần Suất (Jun Da)": "4276.0", "Tần Suất % (Jun Da)": "99.8159438736", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蓟", "Unihan_Traditional (Chữ Phồn thể)": "薊", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại cây thân thảo có gai dùng làm thuốc trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圩', '{"9000": "4277.0", "Chữ Trung Quốc": "圩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 土 | thổ | biểu nghĩa | đất | 于 | vu | biểu âm | ở, tại | 圩 = 土 (Thổ, biểu nghĩa: đất) + 于 (Vu, biểu âm); chữ hình thanh. Bộ 土 xác định liên quan đất/công trình đất; 于 cung cấp âm. Wiktionary so sánh với 圬 (trát tường).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vò\": 土 (đất) + 于 (ở/tại) — đất đắp \"vò\" (vo tròn lại) thành bờ đê để ngăn nước lũ. | Gương Hán-Việt | vò trong 圩田 (vò điền — ruộng đê, ruộng trong đê); 圩日 (vò nhật — ngày chợ phiên ở miền Nam) | Mở khoá kiến thức | Biết 圩 mở khoá khái niệm nông nghiệp 圩田 (đồng bằng được bảo vệ bởi đê) và từ địa phương 赶圩 (gǎn xū — đi chợ phiên ở Quảng Đông, Quảng Tây).", "Tự nguyên_Xie": "圩 là chữ hình thanh: 土 (biểu nghĩa, đất) + 于 (biểu âm). Wiktionary xác nhận và so sánh với 圬. Nghĩa: bờ đê, đất đắp ngăn lũ. Ở Nam Trung Quốc còn dùng để chỉ chợ họp định kỳ (圩日 — ngày chợ phiên). Chữ gốc không có hình thức cổ được ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ đập, bờ đê", "Hạng Tần Suất (Jun Da)": "4277.0", "Tần Suất % (Jun Da)": "99.8161614401", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圩", "Unihan_Traditional (Chữ Phồn thể)": "圩", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ đê bao quanh ruộng hoặc khu chợ vùng quê ở miền nam Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孪', '{"9000": "4278.0", "Chữ Trung Quốc": "孪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 9 | nét | 孪 | loan | tượng hình | sinh đôi, sinh đa thai | 孪 có bộ 子 (tử) gợi liên quan con trẻ, nhưng cấu trúc hình thanh của phồn thể 孿 không được phân tích cụ thể trong nguồn ({{Han etym}} không có compound). Tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": bộ 子 (con) — hai đứa con \"loan\" (loạn — cùng lúc), sinh đôi không thể tách rời. | Gương Hán-Việt | loan trong 孪生 (loan sinh — sinh đôi); 孪生兄弟 (loan sinh huynh đệ — anh em sinh đôi) | Mở khoá kiến thức | Biết 孪 mở khoá từ sinh học và cuộc sống 孪生 — và cả ẩn dụ 孪生城市 (thành phố kết nghĩa/twin cities).", "Tự nguyên_Xie": "Tiểu triện | 孪 (phồn thể 孿) có bộ 子 (con). Wiktionary không phân tích cấu trúc. Nghĩa: sinh đôi, đẻ hai con cùng lúc. Tiểu triện được ghi nhận. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẻ sinh đôi", "Hạng Tần Suất (Jun Da)": "4278.0", "Tần Suất % (Jun Da)": "99.8163784899", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孪", "Unihan_Traditional (Chữ Phồn thể)": "孿", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ trạng thái sinh đôi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杳', '{"9000": "4279.0", "Chữ Trung Quốc": "杳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu ý | cây | 日 | nhật | biểu ý | mặt trời | 杳 = 木 (Mộc, cây) + 日 (Nhật, mặt trời); chữ hội ý. Wiktionary ghi: mặt trời khuất dưới cây — tối tăm, u ám. So sánh với 杲 (日 trên 木 = sáng). Đây là cặp đối lập hội ý điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểu\": 日 (mặt trời) khuất dưới 木 (cây) — trời \"yểu\" tối, mờ mịt, xa khuất không thấy bóng người. | Gương Hán-Việt | yểu trong 杳无音信 (yểu vô âm tín — bặt tin không có); 杳然 (yểu nhiên — mờ mịt, xa khuất) | Mở khoá kiến thức | Biết 杳 mở khoá thành ngữ 杳无音信 (yểu vô âm tín) và 杳如黄鹤 (yểu như hoàng hạc — mất tăm như hạc vàng — điển cố thơ Thôi Hiệu).", "Tự nguyên_Xie": "Tiểu triện | 杳 là chữ hội ý: 木 (cây) + 日 (mặt trời) — mặt trời khuất dưới tán cây, tối tăm. Wiktionary xác nhận và so sánh với 杲 (mặt trời trên cây = sáng tỏ). Nghĩa: mờ mịt, xa xăm, lặng bặt. Tiểu triện được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mờ mịt, lặng bặt; sâu thẳm", "Hạng Tần Suất (Jun Da)": "4279.0", "Tần Suất % (Jun Da)": "99.8165955396", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱木日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杳", "Unihan_Traditional (Chữ Phồn thể)": "杳", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc kết hợp thành từ ghép để chỉ sự xa xăm, biệt vô âm tín. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魇', '{"9000": "4280.0", "Chữ Trung Quốc": "魇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 15 | nét | 魇 | yểm | tượng hình | mơ bị bóng đè, ác mộng | 魇 là dạng giản thể của 魘, thay bộ 厭 (yểm) bằng 厌. Cấu trúc gốc: 厭 (đè nén, chán ghét) + 鬼 (quỷ). Chữ mô tả trạng thái bị ác mộng, bóng đè. Tiểu triện và lục thư thông được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": bộ 鬼 (quỷ) + 厌 (đè) — con quỷ \"yểm\" xuống đè người khi ngủ, gây bóng đè. | Gương Hán-Việt | yểm trong 魇症 (yểm chứng — chứng bóng đè); 发魇 (phát yểm — bị bóng đè); 噩梦魇 (ác mộng yểm) | Mở khoá kiến thức | Biết 魇 mở khoá từ y học dân gian và văn học kinh dị 梦魇 (mộng yểm — bóng đè trong giấc mơ), 魇道 (yểm đạo).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 魇 là dạng giản thể của 魘 (thay 厭 bằng 厌). Wiktionary ghi: tra cứu tại 魘. Cấu trúc gốc: 厭 (đè/chán) + 鬼 (quỷ) — con quỷ đè lên người khi ngủ, gây ác mộng. Tiểu triện và lục thư thông được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mơ bị bóng đè", "Hạng Tần Suất (Jun Da)": "4280.0", "Tần Suất % (Jun Da)": "99.8168125894", "GavinGrover_Once (Chiết tự trực tiếp)": "厌 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厌鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魇", "Unihan_Traditional (Chữ Phồn thể)": "魘", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cơn ác mộng hoặc động từ chỉ trạng thái bị bóng đè khi ngủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荤', '{"9000": "4281.0", "Chữ Trung Quốc": "荤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 军 | quân | biểu âm | quân đội | 荤 = 艹 (Thảo, biểu nghĩa: thực vật) + 军 (Quân, biểu âm). Dạng phồn thể 葷 = 艸+軍. Wiktionary có glyphOrigin nhưng không ghi lsCodes rõ; cấu trúc phono-semantic hợp lý: 艸 chỉ loài rau/thực vật, 軍 gợi âm hūn. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": cây cỏ (艹) mạnh như quân đội (军) — rau hành hẹ tỏi mùi hăng, thức ăn mặn. | Gương Hán-Việt | \"huân\" trong 荤菜 (huân thái — đồ ăn mặn), 吃荤 (ăn mặn có thịt) | Mở khoá kiến thức | Biết 荤 mở khoá 荤菜 (đồ ăn mặn), 荤素 (mặn chay), 荤腥 (thức ăn tanh).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ 荤 (huân), phồn thể 葷, gồm bộ 艸 (艹 — Thảo) biểu nghĩa và 軍 (Quân) biểu âm hūn. Wiktionary xác nhận chữ cổ. Nghĩa gốc theo Phật giáo: các loại rau có mùi hăng mạnh (hành, tỏi, hẹ) bị cấm ăn trong chùa; mở rộng sang nghĩa thức ăn có thịt/cá (đối lập với 素 — chay). Đại triện và tiểu triện được lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thức cay, rau hăng (như hành, hẹ, tỏi,...); đĩa thịt; ăn mặn", "Hạng Tần Suất (Jun Da)": "4281.0", "Tần Suất % (Jun Da)": "99.8170291224", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荤", "Unihan_Traditional (Chữ Phồn thể)": "葷", "Pinyin_Xie": "hūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ các món ăn từ thịt cá hoặc tính từ chỉ tính chất đồ ăn mặn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诿', '{"9000": "4282.0", "Chữ Trung Quốc": "诿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 诿 | uỷ | tượng hình | đổ lỗi, thoái thác trách nhiệm | 诿 có bộ 讠(言) gợi liên quan lời nói/ngôn từ, nhưng cấu trúc hình thanh phồn thể 諉 không được phân tích cụ thể trong nguồn. Tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uỷ\": bộ 讠(lời nói) — dùng lời nói để \"uỷ\" (đẩy) trách nhiệm sang người khác, thoái thác. | Gương Hán-Việt | uỷ trong 推诿 (thôi uỷ — đùn đẩy trách nhiệm); 诿过 (uỷ quá — đổ lỗi cho người khác) | Mở khoá kiến thức | Biết 诿 mở khoá từ văn phòng thiết yếu 推诿 (đùn đẩy trách nhiệm) và 互相推诿 (互相推诿 — ai cũng đổ cho nhau).", "Tự nguyên_Xie": "Tiểu triện | 诿 (phồn thể 諉) có bộ 讠(言, lời nói). Wiktionary ghi phát âm và nghĩa nhưng không phân tích cấu trúc Han compound. Nghĩa: từ chối trách nhiệm, đổ lỗi cho người khác, thoái thác. Tiểu triện được ghi nhận. chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "từ chối", "Hạng Tần Suất (Jun Da)": "4282.0", "Tần Suất % (Jun Da)": "99.8172456553", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诿", "Unihan_Traditional (Chữ Phồn thể)": "諉", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "uỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ trách nhiệm để biểu thị việc thoái thác, đùn đẩy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簪', '{"9000": "4283.0", "Chữ Trung Quốc": "簪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簪 | trâm | tượng hình | cái trâm cài đầu bằng tre hoặc kim loại | 簪 có bộ 竹 (trúc) gợi vật liệu làm trâm (trâm tre), nhưng cấu trúc hình thanh nội tại không được phân tích cụ thể trong nguồn ({{Han etym}} không có compound). Tiểu triện được ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâm\": bộ 竹 (tre) — cái \"trâm\" cài đầu bằng tre, sau nâng lên thành vàng bạc ngọc — biểu tượng phụ nữ quý tộc. | Gương Hán-Việt | trâm trong 簪花 (trâm hoa — cài hoa lên đầu); 簪缨 (trâm anh — trâm và dây đai — chỉ tầng lớp quý tộc) | Mở khoá kiến thức | Biết 簪 mở khoá từ văn học cổ điển 簪缨世胄 (trâm anh thế trụ — dòng dõi quý tộc nhiều đời) và trang sức truyền thống.", "Tự nguyên_Xie": "Tiểu triện | 簪 có bộ 竹 (tre). Wiktionary không phân tích cấu trúc Han compound. Nghĩa: cái trâm cài đầu (hairpin) — vật dụng trang sức của phụ nữ cổ đại, cũng là biểu tượng của tầng lớp có học thức. Tiểu triện được ghi nhận. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái trâm cài đầu", "Hạng Tần Suất (Jun Da)": "4283.0", "Tần Suất % (Jun Da)": "99.8174621883", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 朁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮朁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簪", "Unihan_Traditional (Chữ Phồn thể)": "簪", "Pinyin_Xie": "zān", "Âm Hán Việt_Xie": "trâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cái trâm cài tóc hoặc làm động từ với nghĩa cài, giắt lên tóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氲', '{"9000": "4284.0", "Chữ Trung Quốc": "氲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 13 | nét | 氲 | uân | tượng hình | khí nặng, khí uất kết, sinh khí của thiên nhiên | 氲 có bộ 气 (khí) gợi liên quan đến khí, nhưng cấu trúc hình thanh nội tại không được phân tích cụ thể trong nguồn. Phồn thể 氳 cũng không có cấu trúc rõ ràng ngoài bộ 气. Chủ yếu dùng trong 氤氲.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uân\": bộ 气 (khí) — khí \"uân\" ấm áp mờ ảo của thiên nhiên, như sương mù nhẹ bao phủ núi rừng buổi sáng. | Gương Hán-Việt | uân trong 氤氲 (nhân uân — khí sinh động của thiên nhiên, mờ ảo); 氛氲 (phân uân — khói khí mờ ảo) | Mở khoá kiến thức | Biết 氲 mở khoá từ thơ cổ điển 氤氲 (yīn yūn) — hình ảnh thơ ca diễn tả bầu không khí linh thiêng, ấm áp, sinh khí tràn đầy.", "Tự nguyên_Xie": "氲 (phồn thể 氳) có bộ 气 (khí). Wiktionary ghi nghĩa: bầu không khí dày đặc, nặng nề; chủ yếu dùng trong 氤氲 (yīn yūn — khí sinh động của tự nhiên, hơi ấm mờ ảo). Không có hình thức cổ rõ ràng. chưa có nguồn học thuật về cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí nặng", "Hạng Tần Suất (Jun Da)": "4284.0", "Tần Suất % (Jun Da)": "99.8176782045", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氲", "Unihan_Traditional (Chữ Phồn thể)": "氳", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "uân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường kết hợp thành từ ghép để chỉ trạng thái khí mây mù bao phủ hoặc không khí ấm áp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摞', '{"9000": "4285.0", "Chữ Trung Quốc": "摞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 手 | thủ | biểu nghĩa | tay | 累 | luỵ | biểu âm | 摞 là chữ hình thanh (psc): 手 (Thủ, biểu nghĩa: tay) + 累 (Luỵ, biểu âm, cho âm đọc gần luò). Nghĩa gốc là dùng tay xếp chồng lên nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": 摞 — hình ảnh bàn tay (手) cứ chồng (累=lũy, chồng) mãi lên nhau, kết hợp thành một đống. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng cho chữ này trong tiếng Việt. | Mở khoá kiến thức | Biết 摞 giúp nhận diện động từ chỉ hành động xếp chồng vật thể trong văn xuôi hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary, 摞 là chữ hình thanh ghép bởi 手 (tay, biểu nghĩa) và 累 (biểu âm). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn — chỉ có hình thức tiểu triện trở về sau. Hành động dùng tay xếp chồng (摞) liên quan trực tiếp đến bộ thủ 手. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xếp, sắp; chồng, đống", "Hạng Tần Suất (Jun Da)": "4285.0", "Tần Suất % (Jun Da)": "99.8178937039", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摞", "Unihan_Traditional (Chữ Phồn thể)": "摞", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "loa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường dùng làm động từ chỉ hành động xếp chồng đồ vật hoặc làm lượng từ cho các xấp, chồng giấy sách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飒', '{"9000": "4286.0", "Chữ Trung Quốc": "飒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 9 | nét | 飒 | táp | tượng hình | chữ giản thể của 颯, chỉ âm thanh gió táp | 飒 là chữ giản thể của 颯. Dạng phồn thể 颯 gồm 風 (phong, gió) + 立 (lập, đứng), gợi hình ảnh gió đứng thổi ào ạt. Trong dạng giản thể, 風 được đơn giản hóa thành 风.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": 飒 — gió táp (飒) thổi mạnh, lá bay xào xạc, nghe như tiếng \"xạc xào\" của gió thu. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt tiếng Việt. | Mở khoá kiến thức | Biết 飒 giúp đọc từ 飒爽 (sàng, hào sảng) và nhận ra bộ 风 trong các chữ liên quan đến gió.", "Tự nguyên_Xie": "Tiểu triện | 飒 là dạng giản thể của 颯. Theo Wiktionary, 颯 gồm bộ 風 (gió) và 立 (đứng thẳng), gợi tiếng gió thổi mạnh vù vù. Dạng tiểu triện còn lưu lại trong di tích chữ viết cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng gió thổi vù vù; suy, tàn, rụng", "Hạng Tần Suất (Jun Da)": "4286.0", "Tần Suất % (Jun Da)": "99.8181092033", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "风", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "飒", "Unihan_Traditional (Chữ Phồn thể)": "䬃", "Pinyin_Xie": "sà", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả tiếng gió thổi hoặc kết hợp tạo từ chỉ phong thái phóng khoáng, oai phong. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镂', '{"9000": "4287.0", "Chữ Trung Quốc": "镂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 镂 | lâu | tượng hình | chữ giản thể của 鏤, chỉ hành động khắc chạm trên kim loại | 镂 là chữ giản thể của 鏤. Dạng phồn thể 鏤 là chữ hình thanh: 金 (Kim, biểu nghĩa: kim loại) + một thành phần biểu âm. Nghĩa chính là khắc chạm tinh xảo trên kim loại hoặc đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": 镂 — kim (金) khắc (鏤) trên đồng thau như thợ kim hoàn điêu khắc bức tranh lâu đài tinh xảo. | Gương Hán-Việt | Ít gặp trong từ Hán-Việt thông dụng; \"lâu\" thường gặp hơn trong 镂刻 (lâu khắc). | Mở khoá kiến thức | Biết 镂 giúp đọc thành ngữ 镂骨铭心 (khắc xương ghi lòng) và nhận ra bộ 钅(金) trong chữ kim loại.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, dạng phồn thể 鏤 là chữ hình thanh với bộ 金 (kim loại, biểu nghĩa) và thành phần biểu âm. Từ dạng tiểu triện còn lưu lại, chữ gốc mang nghĩa khắc chạm hoa văn tinh xảo — kỹ thuật quan trọng trong thủ công mỹ nghệ cổ Trung Hoa. Có dạng thay thế 𫷺 (⿸广射) trong kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thép; chạm, khắc; cái lũ", "Hạng Tần Suất (Jun Da)": "4287.0", "Tần Suất % (Jun Da)": "99.8183247027", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镂", "Unihan_Traditional (Chữ Phồn thể)": "鏤", "Pinyin_Xie": "lòu", "Âm Hán Việt_Xie": "lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong văn viết để chỉ việc chạm khắc hoa văn tinh xảo lên gỗ, đá hoặc kim loại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舀', '{"9000": "4288.0", "Chữ Trung Quốc": "舀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 10 | nét | 爪 | trảo | biểu nghĩa | tay, bàn tay cào xuống | 臼 | cối | biểu nghĩa | cối, đồ đựng lõm | 舀 là chữ hội ý (ic): 爪 (Trảo, tay/móng cào) + 臼 (Cối, đồ đựng hình lõm). Bàn tay (爪) chìa vào cái cối (臼) để múc — đó là nghĩa gốc \"múc, vét\" của 舀.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": 舀 — hình ảnh cái爪 (móng tay) múc vào臼 (cái cối) — múc nước từ chum sang xô. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 舀 giúp nhận diện bộ 臼 (cối) và từ 舀水 (múc nước) trong văn xuôi miêu tả sinh hoạt.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 舀 là chữ hội ý ghép bởi 爪 (tay, móng vuốt) và 臼 (cối, đồ đựng). Hình ảnh bàn tay chọc vào cái cối để vét ra chất lỏng hoặc thức ăn. Dạng đại triện còn lưu lại trong di tích. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1097.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (066) Cữu (136)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trảo (số 066 - móng vuốt/bàn tay/viết dạng 爫) ở trên bộ Cữu (số 136 - cái cối). Hình bàn tay thò vào trong cối để múc nước ra ngoài. Giải thích sự chuyển ý: Đây là chữ Hội ý. Yểu là múc nước từ bên trong sang bên ngoài hoặc từ bên này qua bên kia.", "Nghĩa Tiếng Việt_Xie": "múc nước bên nọ rót sang bên kia", "Hạng Tần Suất (Jun Da)": "4288.0", "Tần Suất % (Jun Da)": "99.8185391685", "GavinGrover_Once (Chiết tự trực tiếp)": "爫 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爫臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "舀", "Unihan_Traditional (Chữ Phồn thể)": "舀", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ chất lỏng để biểu thị hành động múc nước, múc canh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夙', '{"9000": "4289.0", "Chữ Trung Quốc": "夙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 夕 | Số nét | 6 | nét | 夙 | túc | tượng hình | người cầm mặt trăng, tượng trưng lễ bái trăng lúc sáng sớm | 夙 là chữ tượng hình. Giáp cốt văn vẽ hình người cầm/ôm mặt trăng (月) trong tay (丮), gợi cảnh người lao động hoặc cúng tế dưới ánh trăng chưa lặn — tức buổi sáng sớm tinh mơ. Về sau 月 bị lẫn thành 夕, và 丮 thu nhỏ thành 凡.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": 夙 — \"túc\" như \"tức tốc\", người dậy sớm (夙) như còn trăng (月) trên trời, chân tay đã bận rộn. | Gương Hán-Việt | \"Túc\" xuất hiện trong \"túc nguyện\" (夙愿, nguyện vọng ấp ủ từ lâu), \"túc thế\" (kiếp trước). | Mở khoá kiến thức | Biết 夙 mở khoá từ 夙愿 (túc nguyện — ước nguyện lâu đời), 夙夜 (sớm tối — suốt ngày đêm).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary, giáp cốt văn 夙 gồm 月 (mặt trăng) và 丮 (hình người cầm/ôm), gợi hình ảnh người thờ phụng trăng, hoặc người làm việc lúc bình minh khi trăng chưa lặn. Trong kim văn, 月 biến dạng thành 夕. Về sau 丮 thu rút thành 凡. Nghĩa phái sinh: sớm, từ xưa, cũ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sớm; ngày xưa, cũ", "Hạng Tần Suất (Jun Da)": "4289.0", "Tần Suất % (Jun Da)": "99.8187536344", "GavinGrover_Once (Chiết tự trực tiếp)": "𠘨 + 歹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𠘨歹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠘨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "夙", "Unihan_Traditional (Chữ Phồn thể)": "夙", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm định ngữ đứng trước danh từ để chỉ những thứ đã có từ lâu hoặc ước nguyện từ xưa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臧', '{"9000": "4290.0", "Chữ Trung Quốc": "臧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臣 | Số nét | 14 | nét | 臣 | thần | biểu nghĩa | con mắt nhìn xuống (hình ảnh nô lệ phục tùng) | 戈 | qua | biểu nghĩa | vũ khí, giáo mác | 臧 là chữ hội ý (ic): 臣 (Thần, biểu nghĩa: con mắt cúi nhìn — hình ảnh nô lệ) + 戈 (Qua, vũ khí). Nghĩa gốc là tù nhân bị bắt trong chiến tranh — nô lệ thời cổ đại Trung Hoa bị đâm mù một mắt. Về sau, thành phần âm 爿 được thêm vào, khiến Thuyết văn phân tích lại theo kiểu hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tang\": 臧 — người bị bắt làm nô (臣) dưới mũi giáo (戈) — \"tang\" như vết tang thương của kẻ bại trận. | Gương Hán-Việt | \"Tang\" ít gặp trong từ Hán-Việt thông dụng; xuất hiện trong tên người hoặc cổ văn. | Mở khoá kiến thức | Biết 臧 giúp hiểu lịch sử chữ 臣 (thần) và chữ 童 (đồng) — đều liên quan đến thân phận nô lệ cổ đại.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, giáp cốt văn 臧 ghép 臣 (mắt nhìn xuống, biểu trưng nô lệ) và 戈 (vũ khí/giáo). Nô lệ thời Trung Hoa cổ đại bị đâm mù mắt, do đó dùng bộ 臣. Phiên bản gốc là 𦣣. Sau đó thành phần âm 爿 được thêm vào ở giai đoạn muộn hơn, dẫn đến Thuyết văn Giải tự phân tích theo hình thanh (psc: 戕 biểu âm + 臣 biểu nghĩa). Nghĩa phái sinh: tốt, hay (có thể vay mượn âm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1428.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (204) Thần (169) Qua (062)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thần (số 169 - kẻ bề tôi/ 臣) nằm giữa bộ Tường (số 204 - cái mộc gỗ/ 爿) và bộ Qua (số 062 - cái mác/ 戈). Kẻ bề tôi (Thần) luôn sẵn sàng cầm vũ khí (Qua) và cái mộc (Tường) để bảo vệ quốc gia. Đó là điều tốt lành. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tang là sự tốt lành, tốt đẹp.", "Nghĩa Tiếng Việt_Xie": "hay, tốt", "Hạng Tần Suất (Jun Da)": "4290.0", "Tần Suất % (Jun Da)": "99.8189670666", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 臣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴臣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "臧", "Unihan_Traditional (Chữ Phồn thể)": "臧", "Pinyin_Xie": "zāng", "Âm Hán Việt_Xie": "tang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng trong văn ngôn làm tính từ chỉ sự tốt lành hoặc động từ biểu thị sự khen ngợi, đồng tình. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒿', '{"9000": "4291.0", "Chữ Trung Quốc": "蒿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒿 | hao | tượng hình | chỉ cây ngải, cây bồng — thực vật họ cúc | 蒿 có bộ 艹 (thảo, cỏ) và phần dưới mang âm đọc, nhưng cấu trúc chi tiết không được phân tích rõ trong nguồn. Là chữ chỉ loài thực vật — cây ngải cứu (Artemisia) và các cây tương tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hao\": 蒿 — cây hao (蒿) như cây ngải cứu mọc hoang trên đồng, mùi thơm nồng đặc trưng. | Gương Hán-Việt | \"Hao\" xuất hiện trong \"đồng hao\" (茼蒿) — rau cải cúc thông dụng trong bếp Việt. | Mở khoá kiến thức | Biết 蒿 giúp đọc 茼蒿 (đồng hao/rau cải cúc), 青蒿 (thanh hao — nguyên liệu thuốc sốt rét).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 蒿 chỉ cây Artemisia (ngải cứu, ngải hoa — wormwood/mugwort), một chi thực vật quan trọng trong y học cổ truyền. Dạng đại triện và tiểu triện còn lưu lại. Nghĩa mở rộng: bốc hơi, tỏa mùi thơm; cũng dùng trong thành ngữ chỉ mục ruỗng (蒿目). Chữ tạo muộn, chưa có phân tích hội ý/hình thanh rõ ràng từ Wiktionary. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đồng hao 茼蒿)", "Hạng Tần Suất (Jun Da)": "4291.0", "Tần Suất % (Jun Da)": "99.8191799821", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒿", "Unihan_Traditional (Chữ Phồn thể)": "蒿", "Pinyin_Xie": "hāo", "Âm Hán Việt_Xie": "hao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ chung các loại cây thuộc họ cúc, họ ngải hoặc làm thành phần trong tên cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貂', '{"9000": "4292.0", "Chữ Trung Quốc": "貂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 12 | nét | 豸 | trại | biểu nghĩa | bộ thú vật không chân (thú leo trèo, thú rừng) | 召 | thiệu | biểu âm | 貂 là chữ hình thanh (psc): 豸 (Trại, biểu nghĩa: bộ thú vật — chỉ loài thú mình dài, chân ngắn) + 召 (Thiệu, biểu âm, cho âm gần diāo). Chữ chỉ con chồn sable — loài thú có bộ lông quý giá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\": 貂 — con thú (豸) chồn quý, lông mềm như nhung, từng được dùng trang trí mũ quan. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng cho chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 貂 giúp đọc 貂皮 (lông chồn), 貂蝉 (Điêu Thuyền — mỹ nhân trong Tam Quốc) và nhận bộ 豸.", "Tự nguyên_Xie": "Theo Wiktionary, 貂 là chữ hình thanh ghép bộ 豸 (thú vật mình dài, biểu nghĩa) và 召 (biểu âm). Bộ 豸 thường chỉ các loài thú như chồn, báo, gấu trúc nhỏ. 貂 chỉ con chồn sable (Martes zibellina) — loài thú quý có bộ lông nâu đen mềm mại, từng là biểu tượng quý tộc và quyền lực ở Trung Hoa và Đông Á. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chồn", "Hạng Tần Suất (Jun Da)": "4292.0", "Tần Suất % (Jun Da)": "99.8193928976", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貂", "Unihan_Traditional (Chữ Phồn thể)": "貂", "Pinyin_Xie": "diāo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loài chồn hoặc các sản phẩm làm từ da và lông chồn quý hiếm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜥', '{"9000": "4293.0", "Chữ Trung Quốc": "蜥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜥 | tích | tượng hình | chỉ loài thằn lằn (蜥蜴), dùng độc lập trong 蜥蜴 | 蜥 có bộ 虫 (trùng, chỉ sâu bọ, động vật nhỏ) và phần biểu âm. Chữ chỉ dùng trong từ 蜥蜴 (tích dịch — thằn lằn). Cấu trúc chi tiết chưa được Wiktionary phân tích rõ theo hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": 蜥 — \"tích\" như tiếng bước chân nhỏ xíu, con thằn lằn (蜥蜴) tí tách chạy trên tường. | Gương Hán-Việt | \"Tích\" trong \"tích dịch\" (蜥蜴) — con thằn lằn; hiếm gặp độc lập. | Mở khoá kiến thức | Biết 蜥 giúp đọc 蜥蜴 (tích dịch — thằn lằn), 巨蜥 (cự tích — kỳ đà lớn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蜥 chỉ xuất hiện trong từ ghép 蜥蜴 (thằn lằn). Bộ 虫 (trùng) cho nghĩa là loài động vật nhỏ, bò sát. Dạng tiểu triện còn ghi lại trong hanziyuan. Chưa có nguồn học thuật rõ ràng về cấu trúc hình thanh/hội ý của chữ này. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tích dịch 蜥蜴)", "Hạng Tần Suất (Jun Da)": "4293.0", "Tần Suất % (Jun Da)": "99.8196052963", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 析", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫析", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "析", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜥", "Unihan_Traditional (Chữ Phồn thể)": "蜥", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng một mình mà kết hợp với chữ khác thành từ ghép chỉ con thằn lằn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹩', '{"9000": "4294.0", "Chữ Trung Quốc": "蹩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 敝 | tệ | biểu âm | 足 | túc | biểu nghĩa | chân | 蹩 là chữ hình thanh (psc): 足 (Túc, biểu nghĩa: chân) + 敝 (Tệ, biểu âm, cho âm gần bié). Nghĩa gốc là bị trặc chân, đi khập khiễng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biệt\": 蹩 — cái chân (足) bị trặc (敝=tệ hại), đi khập khiễng như người bị thương. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng cho chữ này. | Mở khoá kiến thức | Biết 蹩 giúp đọc 蹩脚 (kém cỏi, dở hơi), 蹩腿 (trặc chân).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蹩 là chữ hình thanh ghép bởi 敝 (biểu âm) và 足 (chân, biểu nghĩa). Dạng tiểu triện còn ghi lại trong hanziyuan. Nghĩa chính là bị bong gân hoặc đi khập khiễng; nghĩa rộng hơn là kém cỏi, vụng về (蹩脚). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiễng chân; đi khập khiễng", "Hạng Tần Suất (Jun Da)": "4294.0", "Tần Suất % (Jun Da)": "99.8198176949", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "蹩", "Unihan_Traditional (Chữ Phồn thể)": "蹩", "Pinyin_Xie": "bié", "Âm Hán Việt_Xie": "biệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ dáng đi khập khiễng hoặc kết hợp thành tính từ chỉ sự vụng về, chất lượng kém. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噼', '{"9000": "4295.0", "Chữ Trung Quốc": "噼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 噼 | tượng hình | chữ chỉ âm thanh nổ lốp bốp; không có phân tích hội ý/hình thanh rõ ràng | 噼 không có nguồn etymology từ Wiktionary. Bộ 口 (khẩu, miệng) gợi đây là chữ chỉ âm thanh. Chữ thường xuất hiện trong từ láy 噼啪 (pīpā) mô phỏng tiếng nổ lốp bốp. Chưa có nguồn học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phích\": 噼 — miệng (口) phát ra tiếng nổ \"bùm\", như pháo (噼啪) lốp bốp vào đêm giao thừa. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng cho chữ này. | Mở khoá kiến thức | Biết 噼 giúp đọc từ láy 噼啪 (lốp bốp) — mô tả âm thanh pháo nổ, lửa cháy, tiếng nước sôi.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 噼. Dựa vào cấu trúc: bộ 口 (miệng, âm thanh) gợi đây là chữ tượng thanh. Chữ thường dùng trong từ láy 噼啪 mô phỏng tiếng nổ lốp bốp (như pháo, lửa cháy). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bùm bùm; lốp bốp", "Hạng Tần Suất (Jun Da)": "4295.0", "Tần Suất % (Jun Da)": "99.8200295769", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噼", "Unihan_Traditional (Chữ Phồn thể)": "噼", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này thường dùng làm từ tượng thanh mô tả tiếng nổ hoặc tiếng đổ vỡ, thường lặp lại thành 噼里啪啦. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钛', '{"9000": "4296.0", "Chữ Trung Quốc": "钛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 金 | kim | biểu nghĩa | kim loại | 太 | thái | biểu âm | 钛 là chữ hình thanh (psc): 金 (Kim, biểu nghĩa: kim loại) + 太 (Thái, biểu âm, cho âm tài/tài). Chữ được tạo ra để phiên âm tên nguyên tố Titanium (Ti), bộ 钅(kim) xác định đây là kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\": 钛 — kim (金) + thái (太=lớn) → titan, kim loại \"siêu\" bền nhẹ dùng trong máy bay và cấy ghép y tế. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; trong tiếng Việt gọi là \"titan\". | Mở khoá kiến thức | Biết 钛 giúp đọc tên nguyên tố và nhận bộ 钅(金) trong các chữ chỉ kim loại hiện đại như 钚 (plutoni), 铀 (urani).", "Tự nguyên_Xie": "Theo Wiktionary, dạng phồn thể 鈦 là chữ hình thanh ghép bộ 金 (kim loại, biểu nghĩa) và 太 (biểu âm, âm tài). Chữ hiện đại, được tạo để đặt tên cho nguyên tố titan (Ti, số nguyên tử 22) — kim loại nhẹ, bền, màu bạc, dùng nhiều trong hàng không, y tế. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố titan, Ti", "Hạng Tần Suất (Jun Da)": "4296.0", "Tần Suất % (Jun Da)": "99.8202414588", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钛", "Unihan_Traditional (Chữ Phồn thể)": "鈦", "Pinyin_Xie": "tài", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học titan, thường dùng trong các thuật ngữ khoa học và công nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钚', '{"9000": "4297.0", "Chữ Trung Quốc": "钚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钚 | tượng hình | chữ chỉ nguyên tố plutoni (Pu), bộ 钅(kim) | 钚 có bộ 钅(金, kim loại) nhưng cấu trúc nội bộ không được Wiktionary phân tích chi tiết. Dạng phồn thể 鈈 tham chiếu chữ 娝. Chữ hiện đại, được tạo để đặt tên cho nguyên tố plutoni.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộ\": 钚 — kim loại (钅) nguy hiểm nhất hành tinh — plutoni, chất phóng xạ trong bom nguyên tử. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; tiếng Việt gọi là \"plutoni\". | Mở khoá kiến thức | Biết 钚 giúp nhận diện các chữ nguyên tố hiện đại và bộ 钅(金) trong hóa học Trung văn.", "Tự nguyên_Xie": "Theo Wiktionary, dạng phồn thể 鈈 có etymology tham chiếu đến 娝. Chữ hiện đại tạo ra để phiên âm nguyên tố Plutonium (Pu, số nguyên tử 94) — kim loại phóng xạ được dùng trong vũ khí hạt nhân và lò phản ứng. Bộ 钅(kim) xác định đây là kim loại. Chữ tạo muộn, chưa có nguồn học thuật rõ ràng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố plutoni, Pu", "Hạng Tần Suất (Jun Da)": "4297.0", "Tần Suất % (Jun Da)": "99.8204528239", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 不", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅不", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "不", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钚", "Unihan_Traditional (Chữ Phồn thể)": "鈈", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học phóng xạ plutoni, chủ yếu dùng trong lĩnh vực vật lý hạt nhân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獾', '{"9000": "4298.0", "Chữ Trung Quốc": "獾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 20 | nét | 獾 | tượng hình | con lửng/chuột trũi; dạng lục thư thông còn ghi lại | 獾 có bộ 犭(khuyển, chỉ thú vật) nhưng cấu trúc nội bộ không được Wiktionary phân tích chi tiết. Chữ tạo muộn, chỉ có dạng lục thư thông (Lục thư thông — biên soạn cuối triều Minh). Là chữ chỉ con lửng (badger).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": 獾 — con thú (犭) mập ú, đào hang ban đêm — con lửng với sọc đen trắng đặc trưng trên mặt. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; tiếng Việt gọi là \"con lửng\" hoặc \"chuột trũi\". | Mở khoá kiến thức | Biết 獾 giúp nhận bộ 犭(犬) trong các chữ chỉ thú vật và đọc tên động vật hoang dã trong văn bản khoa học.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 獾 chỉ con lửng (badger, Meles meles) — loài thú đào hang, mình thấp, đặc trưng sọc đen trắng trên đầu. Chỉ có dạng lục thư thông ghi lại — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ 犭chỉ đây là thú vật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chuột trũi, con lửng", "Hạng Tần Suất (Jun Da)": "4298.0", "Tần Suất % (Jun Da)": "99.8206636722", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獾", "Unihan_Traditional (Chữ Phồn thể)": "䝔", "Pinyin_Xie": "huān", "Âm Hán Việt_Xie": "hoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài thú ăn thịt cỡ nhỏ thuộc họ chồn, thường sống trong hang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濂', '{"9000": "4299.0", "Chữ Trung Quốc": "濂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 水 | thủy | biểu nghĩa | nước | 廉 | liêm | biểu âm | 濂 là chữ hình thanh (psc): 水 (Thủy, biểu nghĩa: nước) + 廉 (Liêm, biểu âm, cho âm lián). Chữ chỉ một dòng thác nước hoặc tên sông Liêm Khê ở Hồ Nam, Trung Quốc — nổi tiếng với học giả Chu Đôn Di thời Tống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": 濂 — dòng nước (水) trong sạch như liêm khiết (廉=liêm), gắn với suối Liêm Khê nơi Chu Đôn Di yêu hoa sen. | Gương Hán-Việt | Không phổ biến trong từ Hán-Việt thông dụng; xuất hiện trong \"Liêm Khê\" (濂溪) — tên hiệu học giả. | Mở khoá kiến thức | Biết 濂 giúp hiểu \"Liêm Lạc Quan Mân\" (濂洛關閩) — bốn dòng triết học lớn của Tống Nho.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 濂 là chữ hình thanh: bộ 水 (nước, biểu nghĩa) + 廉 (biểu âm). Nghĩa: thác nước; tên sông ở Hồ Nam. Sông Liêm Khê (濂溪) gắn với tên hiệu của Chu Đôn Di (周敦頤) — nhà triết học Tống Nho, tác giả bài phú Ái Liên Thuyết (yêu hoa sen). Chữ chỉ có dạng lục thư thông, tạo muộn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "suối Liêm", "Hạng Tần Suất (Jun Da)": "4299.0", "Tần Suất % (Jun Da)": "99.8208745205", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 廉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵廉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濂", "Unihan_Traditional (Chữ Phồn thể)": "濂", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên sông hoặc suối cổ ở Trung Quốc, thường dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铠', '{"9000": "4300.0", "Chữ Trung Quốc": "铠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 豈 | khải | biểu âm | 铠 là chữ hình thanh (psc): 金 (Kim, biểu nghĩa: kim loại) + 豈 (Khải, biểu âm, cho âm kǎi). Chữ giản thể của 鎧, chỉ áo giáp kim loại — loại giáp trụ bảo vệ chiến binh cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": 铠 — kim loại (金) đúc thành áo giáp (铠), tiếng gõ \"khải khải\" như kiếm sĩ mặc áo sắt tiến vào trận. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; \"khải giáp\" (鎧甲) đôi khi gặp trong văn học cổ. | Mở khoá kiến thức | Biết 铠 giúp đọc 铠甲 (áo giáp), 铠装 (bọc giáp), nhận bộ 钅(金) trong chữ vũ trang cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary, dạng phồn thể 鎧 là chữ hình thanh: bộ 金 (kim loại, biểu nghĩa) + 豈 (biểu âm). Nghĩa chỉ áo giáp — loại trang bị bảo hộ bằng kim loại của chiến binh thời cổ. Chỉ dùng trong từ ghép (no-solo), quan trọng nhất là 鎧甲 (áo giáp đầy đủ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo giáp dát đồng", "Hạng Tần Suất (Jun Da)": "4300.0", "Tần Suất % (Jun Da)": "99.8210853689", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铠", "Unihan_Traditional (Chữ Phồn thể)": "鎧", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ áo giáp sắt của binh lính thời xưa, thường xuất hiện trong từ ghép khải giáp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皙', '{"9000": "4301.0", "Chữ Trung Quốc": "皙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 13 | nét | 皙 | tích | tượng hình | chỉ làn da trắng sáng | 皙 có bộ 白 (bạch, trắng) và phần dưới mang âm đọc, nhưng cấu trúc chi tiết không được Wiktionary phân tích rõ. Chữ chỉ da trắng sáng trong văn học (Literary Chinese). Dạng tiểu triện còn ghi lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": 皙 — bộ 白 (trắng) + phần dưới; \"tích\" như \"tinh tế\" — làn da (皙) trắng tinh khiết. | Gương Hán-Việt | \"Tích\" ít dùng trong từ Hán-Việt thông dụng; gặp trong mỹ từ về nước da. | Mở khoá kiến thức | Biết 皙 giúp đọc 白皙 (bạch tích — da trắng sáng) trong văn học và miêu tả ngoại hình.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 皙 là tính từ cổ (literary) mô tả làn da trắng hoặc nhợt nhạt. Bộ 白 (trắng) gợi màu sắc. Chữ cũng có nghĩa cổ là một loại táo trắng. Dạng tiểu triện còn lưu lại. Chưa có phân tích hình thanh/hội ý rõ ràng từ Wiktionary. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "da trắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "析 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱析白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "析", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皙", "Unihan_Traditional (Chữ Phồn thể)": "皙", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả làn da trắng trẻo của con người, thường dùng trong từ ghép bạch tích. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霭', '{"9000": "4302.0", "Chữ Trung Quốc": "霭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 19 | nét | 雨 | vũ | biểu nghĩa | mưa, khí ẩm | 謁 | yết | biểu âm | 霭 là chữ hình thanh (psc): 雨 (Vũ, biểu nghĩa: mưa/khí ẩm) + 謁 (Yết, biểu âm, cho âm ǎi). Chữ giản thể của 靄, chỉ làn sương mù mờ ảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ải\": 霭 — bầu trời (雨=mưa/mây) ướt sũng, làn sương (霭) mờ ảo bao phủ núi non như tấm voan. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 霭 giúp đọc 云霭 (mây sương), 暖霭 (khói sương ấm áp) trong thơ văn cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, dạng phồn thể 靄 là chữ hình thanh: bộ 雨 (mưa/hơi ẩm, biểu nghĩa) + 謁 (biểu âm). Nghĩa: làn mù, khói sương nhẹ phủ trên mặt đất hoặc núi rừng. Dạng tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí mây; ngùn ngụt", "Hạng Tần Suất (Jun Da)": "4302.0", "Tần Suất % (Jun Da)": "99.8215070656", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 谒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨谒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霭", "Unihan_Traditional (Chữ Phồn thể)": "靄", "Pinyin_Xie": "ǎi", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ làn khói mây hoặc sương mù dày đặc, thường dùng trong văn chương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲈', '{"9000": "4303.0", "Chữ Trung Quốc": "鲈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鲈 | lư | tượng hình | chỉ con cá vược (bass/perch); chữ giản thể của 鱸 | 鲈 là chữ giản thể của 鱸. Bộ 鱼 (ngư, cá) xác định đây là loài cá. Cấu trúc nội bộ không được Wiktionary phân tích chi tiết — chữ tạo muộn để đặt tên loài cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\": 鲈 — cá (鱼) \"lư\" (vược), loài cá khiến nhà thơ Trương Hàn bỏ chức quan chỉ để về ăn cá vược nướng quê nhà. | Gương Hán-Việt | \"Lư\" trong \"lư ngư\" (鱸魚) — cá vược; thỉnh thoảng gặp trong thơ Hán-Việt cổ điển. | Mở khoá kiến thức | Biết 鲈 giúp đọc 鲈鱼 (cá vược), điển tích 思鱸 (nhớ cá vược — nỗi nhớ nhà) trong thơ cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 鱸 (dạng phồn thể) chỉ con cá vược (bass/perch) — loài cá nước ngọt và lợ nổi tiếng trong văn học Trung Hoa, đặc biệt gắn với điển tích nhà thơ Trương Hàn đời Tấn nhớ cá vược quê nhà mà bỏ quan về. Bộ 鱼 (ngư) xác định là cá. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá vược", "Hạng Tần Suất (Jun Da)": "4303.0", "Tần Suất % (Jun Da)": "99.8217179139", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲈", "Unihan_Traditional (Chữ Phồn thể)": "鱸", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá vược sống ở vùng nước lợ hoặc nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叵', '{"9000": "4304.0", "Chữ Trung Quốc": "叵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 叵 | tượng hình | gương của chữ 可 (có thể); nghĩa là không thể | 叵 là hình gương (mirror image) của chữ 可 (có thể). Theo Wiktionary, đây là cách tạo chữ bằng phản chiếu — 可 đảo ngược thành 叵, mang nghĩa phủ định (không thể). Cấu trúc sáng tạo độc đáo trong hệ thống chữ Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phả\": 叵 — là mặt gương của 可 (được phép), lật ngược lại thành không thể đoán (叵测) — tâm địa tối tăm. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; gặp trong thành ngữ cổ 居心叵测. | Mở khoá kiến thức | Biết 叵 giúp đọc thành ngữ 居心叵测 (tâm địa khó đoán), 叵耐 (không chịu được, đáng ghét).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 叵 là hình gương của 可 (có thể). Qua việc đảo chiều, chữ mang nghĩa phủ định: không thể, bất khả. Được dùng như từ viết tắt của 不可. Xuất hiện phổ biến trong thành ngữ 居心叵测 (tâm địa khó đoán). Dạng tiểu triện và lục thư thông còn ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không thể", "Hạng Tần Suất (Jun Da)": "4304.0", "Tần Suất % (Jun Da)": "99.8219282454", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "叵", "Unihan_Traditional (Chữ Phồn thể)": "叵", "Pinyin_Xie": "pǒ", "Âm Hán Việt_Xie": "phả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Chữ này làm phó từ phủ định mang nghĩa không thể, thường đứng trước động từ trong các từ ghép như phả trắc. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霾', '{"9000": "4305.0", "Chữ Trung Quốc": "霾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 22 | nét | 雨 | vũ | biểu nghĩa | mưa, khí quyển | 貍 | ly | biểu âm | 霾 là chữ hình thanh (psc): 雨 (Vũ, biểu nghĩa: hiện tượng khí quyển) + 貍 (Ly, biểu âm, cho âm mái/mái). Chữ chỉ hiện tượng bụi mù — mưa bụi ô nhiễm hoặc cát bụi dày đặc che khuất bầu trời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mai\": 霾 — trời (雨) phủ bụi (貍=ly — con cáo ẩn mình), 霾 như màn bụi mù dày đặc che khuất bầu trời thành phố. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; tiếng Việt gọi là \"sương mù ô nhiễm\", \"bụi mờ\". | Mở khoá kiến thức | Biết 霾 giúp đọc 雾霾 (sương mù ô nhiễm), 霾天 (ngày bụi mờ) — từ rất phổ biến trong báo chí Trung Quốc.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 霾 là chữ hình thanh ghép bộ 雨 (khí quyển, biểu nghĩa) và 貍 (biểu âm). Giáp cốt văn và tiểu triện còn ghi lại. Nghĩa gốc: mưa có lẫn bụi đất; ngày nay dùng chỉ sương mù ô nhiễm (雾霾) — hiện tượng chất lượng không khí kém do bụi mịn PM2.5. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bụi mù", "Hạng Tần Suất (Jun Da)": "4305.0", "Tần Suất % (Jun Da)": "99.822138577", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 貍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨貍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霾", "Unihan_Traditional (Chữ Phồn thể)": "霾", "Pinyin_Xie": "mái", "Âm Hán Việt_Xie": "mai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hiện tượng thời tiết bụi mù hoặc sương khói ô nhiễm tích tụ trong không khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泯', '{"9000": "4306.0", "Chữ Trung Quốc": "泯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泯 | mẫn | tượng hình | chỉ hành động hòa tan, tiêu biến vào nước; bộ 氵(thủy) | 泯 có bộ 氵(thủy, nước) xác định liên quan đến nước/tiêu biến. Cấu trúc chi tiết không được Wiktionary phân tích đầy đủ — chỉ có {{Han etym}} không khai triển. Chữ chỉ hành động biến mất hoàn toàn, xóa sạch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": 泯 — nước (氵) cuốn trôi mọi dấu tích, xóa sạch (泯灭) như mưa lũ cuốn phẳng bãi cát. | Gương Hán-Việt | \"Mẫn\" ít gặp độc lập; xuất hiện trong từ Hán-Việt \"泯灭\" (mẫn diệt — xóa sạch, tiêu biến). | Mở khoá kiến thức | Biết 泯 giúp đọc 泯灭 (xóa sạch, tiêu biến), 泯然 (tan biến không dấu vết).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 泯 chỉ có dẫn chiếu {{Han etym}} nhưng không khai triển chi tiết. Bộ 氵(thủy) gợi hình ảnh tan biến vào nước — như sóng lặng đi, như dấu vết bị xóa sạch. Dạng tiểu triện và lục thư thông còn ghi lại. Chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hết, phá huỷ", "Hạng Tần Suất (Jun Da)": "4306.0", "Tần Suất % (Jun Da)": "99.8223483918", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泯", "Unihan_Traditional (Chữ Phồn thể)": "冺", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị sự biến mất hoàn toàn, thường kết hợp thành các từ như mẫn diệt, mẫn một. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碴', '{"9000": "4307.0", "Chữ Trung Quốc": "碴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碴 | tượng hình | chỉ mảnh vỡ, chỗ mẻ; bộ 石 (đá) | 碴 có bộ 石 (thạch, đá) xác định liên quan đến đá/vật cứng. Không có nguồn etymology từ Wiktionary. Chữ tạo muộn, dùng trong khẩu ngữ Bắc Kinh chỉ mảnh vụn, chỗ mẻ, hoặc chuyện cãi vã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": 碴 — đá (石) vỡ vụn thành mảnh sắc (碴), hay dùng khẩu ngữ \"找碴儿\" — cố tình gây chuyện. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 碴 giúp hiểu khẩu ngữ Bắc Kinh: 找碴儿 (gây chuyện), 玻璃碴 (mảnh kính vỡ).", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 碴. Bộ 石 (đá) gợi nghĩa vỡ vụn, mảnh sắc nhọn. Chữ dùng nhiều trong khẩu ngữ Bắc Kinh: mảnh vỡ (如碴儿), chỗ mẻ (茬碴), hoặc chuyện cãi lộn (找碴儿). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mảnh vụn; chỗ mẻ, chỗ sứt; xỉ", "Hạng Tần Suất (Jun Da)": "4307.0", "Tần Suất % (Jun Da)": "99.8225576897", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碴", "Unihan_Traditional (Chữ Phồn thể)": "碴", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ các mảnh vỡ nhỏ hoặc vết nứt trên bề mặt đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸵', '{"9000": "4308.0", "Chữ Trung Quốc": "鸵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 鳥 | điểu | biểu nghĩa | chim | 它 | tha | biểu âm | 鸵 là chữ hình thanh (psc): 鳥 (Điểu, biểu nghĩa: chim) + 它 (Tha, biểu âm, cho âm tuó). Chữ chỉ con đà điểu (鸵鸟) — loài chim lớn nhất thế giới, không biết bay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": 鸵 — con chim (鳥) khổng lồ không bay được — đà điểu, cứ như nó \"tha\" (它) cái bụng to chạy trên sa mạc. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; tiếng Việt gọi là \"đà điểu\". | Mở khoá kiến thức | Biết 鸵 giúp đọc 鸵鸟 (đà điểu), 鸵鸟政策 (chính sách đà điểu = chính sách vùi đầu vào cát).", "Tự nguyên_Xie": "Theo Wiktionary, dạng phồn thể 鴕 là chữ hình thanh: bộ 鳥 (chim, biểu nghĩa) + 它 (biểu âm). Nghĩa: đà điểu. Chữ hiện đại, xuất hiện cùng với sự du nhập kiến thức về loài chim lớn châu Phi vào văn hoá Trung Hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đà điểu 駝鳥,鸵鸟)", "Hạng Tần Suất (Jun Da)": "4308.0", "Tần Suất % (Jun Da)": "99.8227669877", "GavinGrover_Once (Chiết tự trực tiếp)": "鸟 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鸟它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸵", "Unihan_Traditional (Chữ Phồn thể)": "鴕", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ trong từ ghép để chỉ loài chim đà điểu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峪', '{"9000": "4309.0", "Chữ Trung Quốc": "峪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 10 | nét | 山 | sơn | biểu nghĩa | núi | 谷 | cốc | biểu âm | thung lũng | 峪 là chữ hình thanh (psc), đồng thời có thể xem là hội ý: 山 (Sơn, biểu nghĩa: núi) + 谷 (Cốc, biểu âm + biểu nghĩa: thung lũng). Cả hai thành phần đều gợi địa hình núi non — khe núi, thung lũng giữa vách núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": 峪 — núi (山) + thung lũng (谷) = khe núi sâu hun hút, như Gia Dục Quan nổi tiếng. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; xuất hiện nhiều trong địa danh. | Mở khoá kiến thức | Biết 峪 giúp đọc 嘉峪关 (Gia Dục Quan — cửa ải Vạn Lý Trường Thành) và các địa danh miền núi Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 峪 là chữ hình thanh và cũng mang yếu tố hội ý: 山 (núi, biểu nghĩa) + 谷 (thung lũng, vừa biểu âm vừa biểu nghĩa). Nghĩa: thung lũng, khe núi. Chữ xuất hiện nhiều trong địa danh ở Bắc Trung Quốc như 嘉峪关 (Gia Dục Quan — cửa ải Vạn Lý Trường Thành). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thung lũng", "Hạng Tần Suất (Jun Da)": "4309.0", "Tần Suất % (Jun Da)": "99.8229757689", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 谷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山谷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峪", "Unihan_Traditional (Chữ Phồn thể)": "峪", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "cốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ địa hình thung lũng và thường xuất hiện trong các địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饕', '{"9000": "4310.0", "Chữ Trung Quốc": "饕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 22 | nét | 號 | hiệu | biểu âm | 食 | thực | biểu nghĩa | thức ăn, ăn | 饕 là chữ hình thanh (psc): 食 (Thực, biểu nghĩa: thức ăn/ăn) + 號 (Hiệu, biểu âm, cho âm tāo). Nghĩa gốc: tham ăn, tham lam; nổi tiếng qua từ 饕餮 (thao thiết) — con quái vật tham ăn trong huyền thoại Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": 饕 — ăn (食) tham như quái vật 饕餮 trong huyền thoại, miệng to nuốt chửng cả bàn tiệc. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; \"thao thiết\" (饕餮) đôi khi gặp trong văn học. | Mở khoá kiến thức | Biết 饕 giúp đọc 饕餮 (thao thiết — quái vật tham ăn), 老饕 (lão tao — kẻ sành ăn), 饕餮纹 (hoa văn thao thiết trên đồ đồng cổ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 饕 là chữ hình thanh: 號 (biểu âm) + 食 (thức ăn, biểu nghĩa). Kim văn và tiểu triện còn ghi lại. Nghĩa: tham ăn, tham lam, tàn nhẫn. 饕餮 là tên con quái vật trong thần thoại Trung Hoa — có miệng khổng lồ và lòng tham vô đáy, được khắc trên đồ đồng thời Thương-Chu. Nghĩa phái sinh: 老饕 — kẻ sành ăn (dùng hài hước). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thao thiết 饕餮)", "Hạng Tần Suất (Jun Da)": "4310.0", "Tần Suất % (Jun Da)": "99.8231840333", "GavinGrover_Once (Chiết tự trực tiếp)": "號 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱號食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "號", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "饕", "Unihan_Traditional (Chữ Phồn thể)": "饕", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự tham ăn hoặc kết hợp thành danh từ chỉ loài quái vật ham ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘁', '{"9000": "4311.0", "Chữ Trung Quốc": "瘁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 瘁 | tuỵ | tượng hình | chỉ trạng thái kiệt sức, tiều tụy; bộ 疒 (bệnh) | 瘁 có bộ 疒 (nạch, bệnh tật) xác định liên quan đến bệnh/mệt nhọc. Cấu trúc nội bộ không được Wiktionary phân tích chi tiết. Chữ chỉ trạng thái kiệt sức, mệt mỏi quá độ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuỵ\": 瘁 — bệnh (疒) kiệt sức, \"tuỵ\" như \"tiều tụy\" — người cống hiến hết mình (鞠躬尽瘁) đến tàn sức. | Gương Hán-Việt | \"Tuỵ\" trong \"tuỵ diệt\" ít dùng; \"tận tuỵ\" (尽瘁) đôi khi gặp trong văn cổ. | Mở khoá kiến thức | Biết 瘁 giúp đọc thành ngữ 鞠躬尽瘁 (cúc cung tận tụy — dốc sức cống hiến hết mình).", "Tự nguyên_Xie": "Theo Wiktionary, 瘁 chỉ có dẫn chiếu {{Han etym}} không khai triển chi tiết. Bộ 疒 (bệnh) xác định nghĩa liên quan đến thể trạng suy kiệt. Nghĩa: kiệt sức, mệt nhọc, tiều tụy. Dùng chủ yếu trong thành ngữ 鞠躬尽瘁 (cúc cung tận tụy — cống hiến hết mình đến kiệt sức). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ốm, mệt nhọc", "Hạng Tần Suất (Jun Da)": "4311.0", "Tần Suất % (Jun Da)": "99.8233917809", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘁", "Unihan_Traditional (Chữ Phồn thể)": "瘁", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tuỵ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ biểu thị trạng thái kiệt quệ về thể xác hoặc tinh thần do làm việc quá sức. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睢', '{"9000": "4312.0", "Chữ Trung Quốc": "睢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睢 | tượng hình | chỉ hành động ngửa mắt nhìn lên; bộ 目 (mắt) | 睢 có bộ 目 (mục, mắt) xác định liên quan đến hành động nhìn. Cấu trúc nội bộ không được Wiktionary phân tích chi tiết. Chữ chỉ hành động ngửa mắt nhìn lên/trợn mắt, và là tên sông Tuy (睢河) ở Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": 睢 — cặp mắt (目) trợn ngược lên (睢), hình ảnh người hung hăng phóng túng (恣睢). | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; gặp trong cổ văn qua 恣睢. | Mở khoá kiến thức | Biết 睢 giúp đọc thành ngữ 暴戾恣睢 (hung bạo phóng túng) và tên địa danh 睢阳 (Tuy Dương).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 睢 có âm đọc suī hoặc huī. Chỉ hành động trợn mắt nhìn lên. Cũng là tên riêng (sông Tuy). Dùng chủ yếu trong thành ngữ 暴戾恣睢 (bạo lệ tứ tuy — hung bạo phóng túng) và 恣睢 (tứ tuy — hung hăng tùy tiện). Dạng tiểu triện và lục thư thông còn ghi lại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tuy", "Hạng Tần Suất (Jun Da)": "4312.0", "Tần Suất % (Jun Da)": "99.8235995286", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睢", "Unihan_Traditional (Chữ Phồn thể)": "睢", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ tên sông hoặc động từ chỉ hành vi nhìn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬃', '{"9000": "4313.0", "Chữ Trung Quốc": "鬃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 18 | nét | 髟 | tiêu | biểu nghĩa | bộ chỉ tóc dài, lông dài | 宗 | tông | biểu âm | 鬃 là chữ hình thanh (psc): 髟 (Tiêu, biểu nghĩa: bộ chỉ lông tóc dài rủ xuống) + 宗 (Tông, biểu âm, cho âm zōng). Nghĩa: bờm (mane) — lông dài mọc trên cổ ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": 鬃 — bộ lông dài (髟) mọc theo dòng họ (宗=tông) của ngựa — bờm ngựa tung bay trong gió. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; tiếng Việt gọi là \"bờm ngựa\". | Mở khoá kiến thức | Biết 鬃 giúp đọc 马鬃 (bờm ngựa), 猪鬃 (lông lợn — dùng làm bàn chải cứng), nhận bộ 髟 trong chữ về tóc.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鬃 là chữ hình thanh: bộ 髟 (lông tóc dài, biểu nghĩa) + 宗 (biểu âm). Nghĩa gốc: bờm ngựa (馬鬃). Trong phương ngữ Min Nam, nghĩa mở rộng thành tóc (trên đầu người) hoặc tóc búi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờm", "Hạng Tần Suất (Jun Da)": "4313.0", "Tần Suất % (Jun Da)": "99.8238067594", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬃", "Unihan_Traditional (Chữ Phồn thể)": "騣", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần lông dài trên cổ hoặc lưng của một số loài động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迩', '{"9000": "4314.0", "Chữ Trung Quốc": "迩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迩 | nhĩ | tượng hình | chữ giản thể của 邇, chỉ gần gũi; bộ 辶 (di chuyển) | 迩 là chữ giản thể của 邇. Bộ 辶 (tẩu) chỉ sự di chuyển/tiếp cận. Cấu trúc chi tiết của 邇 không được Wiktionary phân tích đầy đủ — chỉ có {{Han etym}}. Chữ chỉ sự gần gũi, tiếp cận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhĩ\": 迩 — \"nhĩ\" như \"nay\" — 迩来 (từ gần đây đến nay); bước chân (辶) đến gần. | Gương Hán-Việt | \"Nhĩ\" ít gặp độc lập; xuất hiện trong \"遐迩\" (hà nhĩ — xa gần) trong văn học cổ. | Mở khoá kiến thức | Biết 迩 giúp đọc 遐迩 (xa gần), 迩来 (gần đây, dạo này), 远近闻名 tương đương.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 迩 là chữ giản thể của 邇. Bộ 辶 (di chuyển) gợi nghĩa đến gần, tiếp cận. Dạng tiểu triện và lục thư thông còn ghi lại. Dùng trong cổ văn và thành ngữ như 遐迩 (xa gần), 迩来 (gần đây). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gần, sát; tới gần", "Hạng Tần Suất (Jun Da)": "4314.0", "Tần Suất % (Jun Da)": "99.8240139902", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 尔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶尔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迩", "Unihan_Traditional (Chữ Phồn thể)": "邇", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm tính từ chỉ khoảng cách gần hoặc làm phó từ trong các cấu trúc cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纣', '{"9000": "4315.0", "Chữ Trung Quốc": "纣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纣 | trụ | tượng hình | chữ giản thể của 紂, chỉ dây buộc đuôi ngựa; nổi tiếng qua tên vua Trụ | 纣 là chữ giản thể của 紂. Bộ 纟(ty, sợi dây) xác định nghĩa gốc liên quan đến sợi/dây. Nghĩa gốc là dây buộc đuôi ngựa; nghĩa nổi tiếng nhất là tên Trụ Vương — bạo chúa cuối nhà Thương trong lịch sử Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụ\": 纣 — sợi dây (纟) bất nghĩa, như Trụ Vương (纣王) bạo chúa nhà Thương, cột buộc lịch sử tội ác. | Gương Hán-Việt | \"Trụ\" trong \"Trụ Vương\" (纣王) — tên vua bạo chúa cuối nhà Thương. | Mở khoá kiến thức | Biết 纣 giúp đọc 助纣为虐 (trợ trụ vi ngược — tiếp tay cho kẻ ác) và hiểu lịch sử nhà Thương.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 纣 là chữ giản thể của 紂. Dạng tiểu triện còn ghi lại. Nghĩa gốc: dây buộc đuôi ngựa (bộ 糸/纟). Nghĩa nổi tiếng: tên vua Trụ (紂王) — bạo chúa cuối cùng của nhà Thương, bị Chu Vũ Vương đánh bại (khoảng 1046 TCN). Trụ Vương trong lịch sử thường gắn với hình ảnh tàn bạo, xa hoa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người tàn nhẫn, bất nghĩa", "Hạng Tần Suất (Jun Da)": "4315.0", "Tần Suất % (Jun Da)": "99.8242212211", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 寸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纣", "Unihan_Traditional (Chữ Phồn thể)": "紂", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận yên ngựa hoặc dùng làm danh từ riêng chỉ bạo chúa thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夔', '{"9000": "4316.0", "Chữ Trung Quốc": "夔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 夊 | Số nét | 21 | nét | 夔 | quỳ | tượng hình | hình con quái vật một chân trong thần thoại cổ Trung Hoa | 夔 là chữ tượng hình phức tạp. Giáp cốt văn và tiểu triện ghi lại hình dạng sinh vật kỳ lạ một chân. Chữ chỉ con Quỳ (夔) — quái vật thần thoại như rồng nhưng chỉ có một chân, sống trong đá gỗ; cũng là tên nhạc quan thời Vua Thuấn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳ\": 夔 — con quái thần thoại một chân (夔), đứng không vững nhưng nhạc quan Quỳ lại làm chủ toàn bộ âm nhạc thiên hạ. | Gương Hán-Việt | \"Quỳ\" xuất hiện trong văn học cổ — \"Quỳ\" là nhạc quan thời Thuấn, biểu tượng tài năng nghệ thuật. | Mở khoá kiến thức | Biết 夔 giúp đọc điển tích nhạc quan Quỳ, tên đất Quỳ châu (夔州) trong Đường thi.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 夔 chỉ có {{Han etym}} nhưng giáp cốt văn và tiểu triện còn ghi lại. Đây là chữ cổ chỉ con Quỳ — sinh vật thần thoại mình như rồng, một chân, sống trong núi và đá. Ông Quỳ là nhạc quan nổi tiếng của vua Thuấn — được coi là tổ sư âm nhạc. Cũng là tên nước Quỳ thời nhà Chu và họ người. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con quỳ (một con như con rồng nhưng ở trong gỗ, đá, chỉ có một chân); ông Quỳ (một nhạc quan thời vua Thuấn ở Trung Quốc); nước Quỳ đời nhà Chu ở Trung Quốc; họ Quỳ", "Hạng Tần Suất (Jun Da)": "4316.0", "Tần Suất % (Jun Da)": "99.8244279351", "GavinGrover_Once (Chiết tự trực tiếp)": "丷 + 夒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丷夒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丷", "Unihan_Simplified (Chữ Giản thể)": "夔", "Unihan_Traditional (Chữ Phồn thể)": "夔", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "quỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài thần thú một chân trong truyền thuyết Trung Hoa cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垠', '{"9000": "4317.0", "Chữ Trung Quốc": "垠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất | 艮 | cấn | biểu âm | 垠 là chữ hình thanh (psc): 土 (Thổ, biểu nghĩa: đất) + 艮 (Cấn, biểu âm, cho âm yín). Nghĩa: bờ, biên giới đất — ranh giới tự nhiên như bờ sông, bờ vách núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hằn\": 垠 — đất (土) có bờ (艮=cứng rắn như đá), \"hằn\" như \"không có hằn\" (无垠) — bờ bãi vô tận. | Gương Hán-Việt | \"Hằn\" ít dùng độc lập; \"vô hằn\" (无垠) đôi khi gặp trong thơ Hán-Việt. | Mở khoá kiến thức | Biết 垠 giúp đọc 无垠 (vô hằn — bao la vô tận), 八垠 (bát hằn — tám phương trời đất) trong thơ văn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 垠 là chữ hình thanh: bộ 土 (đất, biểu nghĩa) + 艮 (biểu âm). Nghĩa: ranh giới, bờ, đê. Xuất hiện phổ biến trong từ 无垠 (vô hằn — vô tận, bao la) và trong thơ văn miêu tả địa hình. Dạng tiểu triện và lục thư thông còn ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ, biên", "Hạng Tần Suất (Jun Da)": "4317.0", "Tần Suất % (Jun Da)": "99.8246341324", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垠", "Unihan_Traditional (Chữ Phồn thể)": "垠", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ ranh giới hoặc rìa ngoài của một khoảng không gian rộng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饨', '{"9000": "4318.0", "Chữ Trung Quốc": "饨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 7 | nét | 饨 | tượng hình | chỉ thành phần trong 馄饨 (bánh bột nhân thịt); bộ 饣(食) | 饨 có bộ 饣(thực, thức ăn) xác định là thực phẩm. Chữ chỉ dùng trong từ 馄饨 (húntun/wonton — bánh sủi cảo nước). Cấu trúc nội bộ không được Wiktionary phân tích thêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độn\": 饨 — cơm (饣) gói nhân bột (饨) — như tô hoành thánh (馄饨) nóng hổi buổi sáng. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; tiếng Việt gọi là \"hoành thánh\" hoặc \"wonton\". | Mở khoá kiến thức | Biết 饨 giúp đọc 馄饨 (hoành thánh/wonton) và nhận bộ 饣(食) trong chữ thực phẩm.", "Tự nguyên_Xie": "Theo Wiktionary, dạng phồn thể 飩 chỉ dùng trong 餛飩 (húntun). Bộ 食 xác định đây là thực phẩm. Nghĩa: thành phần trong từ ghép 馄饨 — loại bánh bột mỏng bọc nhân thịt, luộc hoặc chiên, phổ biến khắp Trung Hoa và Đông Nam Á. Dạng tiểu triện còn ghi lại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bao", "Hạng Tần Suất (Jun Da)": "4318.0", "Tần Suất % (Jun Da)": "99.8248403297", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饨", "Unihan_Traditional (Chữ Phồn thể)": "飩", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ dùng trong từ ghép để chỉ món hoành thánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榭', '{"9000": "4319.0", "Chữ Trung Quốc": "榭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | gỗ, công trình gỗ | 射 | xạ | biểu âm | 榭 là chữ hình thanh (psc), đồng thời có yếu tố hội ý: 木 (Mộc, biểu nghĩa: gỗ/công trình gỗ) + 射 (Xạ, biểu âm + biểu nghĩa: bắn cung). Nghĩa gốc: đài bắn cung — công trình kiến trúc cổ xây trên đất cao, không có vách ngăn. Dần nghĩa rộng thành đình tạ, lầu các trên nền cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạ\": 榭 — gỗ (木) + bắn cung (射) = đình tạ trên nền cao, nơi văn nhân ngâm thơ ngắm cảnh như cổ thi \"歌台舞榭\". | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; \"đình tạ\" (亭榭) đôi khi gặp trong văn học cổ dịch sang tiếng Việt. | Mở khoá kiến thức | Biết 榭 giúp đọc 水榭 (đình tạ trên mặt nước), 歌台舞榭 (sân khấu ca múa trong cung đình) trong thơ văn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 榭 là chữ hình thanh ghép bởi 木 (gỗ, biểu nghĩa) và 射 (biểu âm). Cũng có yếu tố hội ý: 射 (bắn cung) + 木 (gỗ) = đài bắn cung bằng gỗ trên nền cao. Nghiên cứu của Vương và Dương (1923, 1965) xác nhận đây là loại kiến trúc cổ dùng cho lễ bắn cung — không gian mở, không chia phòng. Trong kim văn có dạng thay thế 𫷺 (⿸广射). Dạng tiểu triện và lục thư thông còn ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà xây trên đài", "Hạng Tần Suất (Jun Da)": "4319.0", "Tần Suất % (Jun Da)": "99.8250465269", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 射", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木射", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "射", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榭", "Unihan_Traditional (Chữ Phồn thể)": "榭", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng sau các từ chỉ kiến trúc hoặc địa danh để chỉ kiểu nhà chòi, lầu hóng mát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隍', '{"9000": "4320.0", "Chữ Trung Quốc": "隍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 阝 | phụ | biểu nghĩa | bộ 阜, đất/gò cao, tường thành | 皇 | hoàng | biểu âm | 隍 là chữ hình thanh (psc): 阝(阜, Phụ, biểu nghĩa: tường đất/gò cao, hào thành) + 皇 (Hoàng, biểu âm, cho âm huáng). Nghĩa: hào khô của thành — phần hào không có nước; cũng là tên thần thổ địa (城隍 — Thành Hoàng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": 隍 — bờ tường (阝) vàng (皇=hoàng) bao quanh thành, trong hào khô ấy ngự vị Thành Hoàng (城隍) giữ đất. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; \"Thành Hoàng\" (城隍) rất phổ biến trong tín ngưỡng dân gian Việt-Trung. | Mở khoá kiến thức | Biết 隍 giúp đọc 城隍 (Thành Hoàng — thần bảo hộ thành), 城隍庙 (Miếu Thành Hoàng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 隍 là chữ hình thanh: bộ 阜 (viết là 阝 ở vị trí trái, chỉ đất cao/tường thành) + 皇 (biểu âm). Nghĩa: hào khô (dry moat) bao quanh thành; và là tên vị thần bảo hộ thành thị Thành Hoàng (城隍) — một trong những thần linh phổ biến nhất trong tín ngưỡng dân gian Trung Hoa. Dạng tiểu triện và lục thư thông còn ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ao cạn trong thành", "Hạng Tần Suất (Jun Da)": "4320.0", "Tần Suất % (Jun Da)": "99.8252522074", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隍", "Unihan_Traditional (Chữ Phồn thể)": "隍", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ Thành để tạo thành danh từ ghép Thành Hoàng chỉ vị thần bảo hộ thành trì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娑', '{"9000": "4321.0", "Chữ Trung Quốc": "娑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 沙 | sa | biểu âm | 女 | nữ | biểu nghĩa | phụ nữ | 娑 là chữ hình thanh (psc): 女 (Nữ, biểu nghĩa: phụ nữ) + 沙 (Sa, biểu âm, cho âm suō). Chữ chỉ dùng trong từ 婆娑 — điệu múa xoay uyển chuyển, cành lá lay nhẹ nhàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": 娑 — người phụ nữ (女) xoay mình như cát (沙=sa) trong gió — điệu múa 婆娑 duyên dáng. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; \"bà sa\" (婆娑) đôi khi gặp trong thơ Hán-Việt. | Mở khoá kiến thức | Biết 娑 giúp đọc 婆娑 (bà sa — uyển chuyển, lay động) trong thơ tả vũ điệu hoặc cành lá.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 娑 là chữ hình thanh: bộ 女 (phụ nữ, biểu nghĩa) + 沙 (biểu âm). Dạng tiểu triện còn ghi lại. Chữ chỉ dùng trong từ 婆娑 (pó suō) — tả dáng múa lả lơi, cành lá đưa nhẹ nhàng trong gió. Hình ảnh gắn liền với nữ tính, uyển chuyển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bà sa 婆娑)", "Hạng Tần Suất (Jun Da)": "4321.0", "Tần Suất % (Jun Da)": "99.8254578879", "GavinGrover_Once (Chiết tự trực tiếp)": "沙 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱沙女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娑", "Unihan_Traditional (Chữ Phồn thể)": "娑", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng trong từ láy để miêu tả dáng múa thướt tha hoặc dáng cây cối lay động trước gió. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篝', '{"9000": "4322.0", "Chữ Trung Quốc": "篝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre | 冓 | biểu âm | 篝 là chữ hình thanh (psc): 竹 (Trúc, biểu nghĩa: tre) + 冓 (biểu âm, cho âm gōu). Nghĩa gốc: lồng tre, giỏ tre. Ngày nay phổ biến nhất trong từ 篝火 (lửa trại — lửa đốt trong lồng hoặc lửa trại ngoài trời).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quảu\": 篝 — tre (竹) đan thành lồng (篝), lồng đựng lửa — lửa trại (篝火) rực sáng đêm xuân. | Gương Hán-Việt | \"Quảu\" rất hiếm trong từ Hán-Việt thông dụng; chữ nổi tiếng hơn qua từ 篝火. | Mở khoá kiến thức | Biết 篝 giúp đọc 篝火 (lửa trại), 篝火晚会 (dạ hội lửa trại) — từ phổ biến trong văn hóa trẻ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 篝 là chữ hình thanh: bộ 竹 (tre, biểu nghĩa) + 冓 (biểu âm). Nghĩa gốc: lồng tre, khung tre. Nghĩa phái sinh phổ biến nhất: 篝火 (lửa trại) — ban đầu chỉ lửa đốt trong lồng tre để giữ ấm hoặc dẫn đường; nay chỉ lửa trại ngoài trời. Dạng tiểu triện và lục thư thông còn ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lồng phơi quần áo", "Hạng Tần Suất (Jun Da)": "4322.0", "Tần Suất % (Jun Da)": "99.8256635684", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 冓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篝", "Unihan_Traditional (Chữ Phồn thể)": "篝", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ chỉ lửa hoặc đèn để chỉ lồng đèn hoặc đống lửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榔', '{"9000": "4323.0", "Chữ Trung Quốc": "榔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 榔 | lang | tượng hình | chỉ cây cọ betel (cây cau dừa) hoặc cây phỉ; bộ 木 (gỗ) | 榔 có bộ 木 (mộc, gỗ/cây) xác định là loài thực vật. Cấu trúc nội bộ không được Wiktionary phân tích chi tiết — chỉ dùng trong từ ghép. Phổ biến nhất trong 槟榔 (cây cau, trầu không) và 榔头 (búa gỗ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": 榔 — cây (木) cau \"lang\" — 槟榔 (tân lang) là cây cau trầu phổ biến khắp Đài Loan và Đông Nam Á. | Gương Hán-Việt | \"Lang\" trong \"tân lang\" (槟榔) — cây cau; cũng có biến thể \"lăng\" và \"trang\". | Mở khoá kiến thức | Biết 榔 giúp đọc 槟榔 (tân lang — cây cau), 榔头 (búa gỗ) và nhận bộ 木 trong cây gỗ.", "Tự nguyên_Xie": "Theo Wiktionary, 榔 có hai âm đọc: láng và lǎng. Bộ 木 xác định là cây/gỗ. Chủ yếu dùng trong từ ghép: 槟榔 (binlang — cây cau/trầu không, phổ biến ở Đài Loan và Đông Nam Á) và 榔头 (búa gỗ). Chữ tạo muộn, chưa có nguồn học thuật phân tích hội ý/hình thanh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tân lang 檳榔,槟榔); (xem: lang đầu 榔頭)", "Hạng Tần Suất (Jun Da)": "4323.0", "Tần Suất % (Jun Da)": "99.8258687321", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 郎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木郎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榔", "Unihan_Traditional (Chữ Phồn thể)": "榔", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong các danh từ ghép để chỉ cây cau hoặc cái búa cầm tay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洌', '{"9000": "4324.0", "Chữ Trung Quốc": "洌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 洌 | rét | tượng hình | chỉ nước trong vắt; bộ 氵(thủy) | 洌 có bộ 氵(thủy, nước) xác định liên quan đến nước. Cấu trúc nội bộ không được Wiktionary phân tích chi tiết. Chữ chỉ nước trong vắt, lạnh sạch; cũng là dạng thay thế của 冽 (lạnh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rét\": 洌 — nước (氵) \"rét\" trong lành — dòng suối lạnh ngắt trong vắt (清洌) như nước giếng cổ. | Gương Hán-Việt | \"Rét\" ít gặp trong từ Hán-Việt thông dụng; đây là đọc âm Hán-Việt của 洌. | Mở khoá kiến thức | Biết 洌 giúp đọc 清洌 (nước trong lạnh), 甘洌 (ngọt mát trong lành) trong thơ văn miêu tả suối nguồn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 洌 là tính từ chỉ chất lỏng trong suốt, tinh khiết. Cũng là dạng thay thế của 冽 (lạnh). Dạng tiểu triện còn ghi lại. Xuất hiện trong cổ văn nổi tiếng như Ái Liên Thuyết của Chu Đôn Di (lân đó có câu 水陆草木之花... 予独爱莲之出淤泥而不染) và văn tả suối trong Đường thi. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước trong vắt", "Hạng Tần Suất (Jun Da)": "4324.0", "Tần Suất % (Jun Da)": "99.8260738958", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 列", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵列", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "列", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洌", "Unihan_Traditional (Chữ Phồn thể)": "洌", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm định ngữ đứng trước danh từ hoặc bổ ngữ sau động từ để miêu tả tính chất thanh khiết của nước hoặc rượu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浜', '{"9000": "4325.0", "Chữ Trung Quốc": "浜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thủy | biểu nghĩa | nước | 兵 | binh | biểu âm | lính | 浜 = 氵(Thủy, biểu nghĩa: nước) + 兵 (Binh, biểu âm); chữ hình thanh. Bộ nước chỉ nghĩa liên quan đến sông nước, 兵 cho âm đọc gần với bāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bang\": bộ 氵(nước) + 兵 (binh lính) — hình ảnh binh lính đóng quân bên kênh rạch để tàu đỗ bến. | Gương Hán-Việt | bang — ít dùng độc lập trong tiếng Việt Hán | Mở khoá kiến thức | Biết 浜 mở khoá từ như 浜田 (địa danh Nhật Bản dùng chữ này).", "Tự nguyên_Xie": "Chữ hình thanh: 氵(水) biểu nghĩa chỉ nước, 兵 biểu âm. Chỉ kênh nhỏ hoặc bờ biển nơi tàu thuyền đỗ lại. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật cụ thể ngoài cấu trúc hình thanh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kênh cho tàu bè đỗ", "Hạng Tần Suất (Jun Da)": "4325.0", "Tần Suất % (Jun Da)": "99.8262790595", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 兵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵兵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浜", "Unihan_Traditional (Chữ Phồn thể)": "浜", "Pinyin_Xie": "bāng", "Âm Hán Việt_Xie": "banh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ địa danh hoặc kênh rạch nhỏ ở vùng sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲑', '{"9000": "4326.0", "Chữ Trung Quốc": "鲑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鱼 | ngư | tượng hình | cá | 鲑 là chữ phức hợp bộ 魚/鱼 (Ngư, cá) làm gốc, nhưng cấu trúc phần phonetic không rõ trong dạng giản thể. Theo truyền thống 鮭 = 魚 + 圭 (biểu âm). Chữ hình thanh chỉ loài cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": bộ 鱼 (cá) — con cá hồi (salmon) đặc trưng của vùng biển phương Bắc, đọc như \"khuê\" tương tự 圭 (khuê). | Gương Hán-Việt | khuê — hiếm dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 鲑 mở khoá từ 鲑鱼 (guīyú — cá hồi) và văn ngôn chỉ thức ăn từ cá.", "Tự nguyên_Xie": "Truyền thống tự: 鮭 = 魚 (ngư, biểu nghĩa: cá) + 圭 (khuê, biểu âm). Chỉ cá hồi (salmon) hoặc cá nói chung trong văn ngôn. Wiktionary ghi nhiều âm đọc: guī (cá nói chung), xié (tên chung cho thức ăn từ cá), kuí (địa danh 鮭陽). chưa có nguồn glyph-origin cổ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá hồi", "Hạng Tần Suất (Jun Da)": "4326.0", "Tần Suất % (Jun Da)": "99.8264842232", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲑", "Unihan_Traditional (Chữ Phồn thể)": "鮭", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng trước các từ chỉ chủng loại cá để cấu tạo tên gọi cụ thể của loài cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谔', '{"9000": "4327.0", "Chữ Trung Quốc": "谔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 咢 | ngạc | biểu âm | 谔 = 讠(Ngôn, biểu nghĩa: lời nói) + 咢 (Ngạc, biểu âm); chữ hình thanh. Bộ ngôn chỉ nghĩa liên quan đến lời nói thẳng thắn, 咢 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": bộ 讠(lời nói) + âm ngạc — lời nói \"ngạc nhiên\" vì quá thẳng thắn, không ai dám nói như vậy. | Gương Hán-Việt | ngạc — ít dùng độc lập; thấy trong 谔谔 (ngạc ngạc: nói thẳng) | Mở khoá kiến thức | Biết 谔 mở khoá thành ngữ 侃侃谔谔 (kǎnkǎn''è''è — nói thẳng thắn mà không ngại).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 讠(言) biểu nghĩa chỉ lời nói, âm đọc từ 咢. Trong văn ngôn, 谔/諤 chỉ lời nói thẳng thắn, không ngại quyền thế — dùng trong thành ngữ 侃侃諤諤 (nói thẳng mà không khách sáo). Chữ tạo muộn (chỉ thấy hình Lục thư thông), chưa có glyph cổ rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời nói ngay thẳng", "Hạng Tần Suất (Jun Da)": "4327.0", "Tần Suất % (Jun Da)": "99.8266888701", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 咢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠咢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谔", "Unihan_Traditional (Chữ Phồn thể)": "諤", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng trong văn viết cổ để chỉ sự can ngăn thẳng thắn hoặc tính cách ngay thẳng chính trực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汩', '{"9000": "4328.0", "Chữ Trung Quốc": "汩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thủy | biểu nghĩa | nước | 曰 | viết | biểu âm | nói rằng | 汩 = 氵(Thủy, biểu nghĩa: nước) + 曰 (Viết, biểu âm); chữ hình thanh. Bộ nước chỉ nghĩa dòng chảy, 曰 cho âm gần với gǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốt\": bộ 氵(nước) + 曰 (viết/nói) — nước chảy \"ào ào\" như tiếng nói liên tục không dứt. | Gương Hán-Việt | cốt — hiếm dùng độc lập; văn ngôn 汩汩 (cốt cốt: tiếng nước chảy) | Mở khoá kiến thức | Biết 汩 mở khoá từ 汩汩 (gǔgǔ — âm thanh nước chảy) và thành ngữ cổ điển trong Sở từ.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 氵(水) biểu nghĩa chỉ nước, 曰 biểu âm. Tiểu triện đã thấy hình thức này. Trong Sở từ và Kinh thư, 汩 chỉ dòng nước chảy cuộn cuộn, dùng cho cả âm gǔ (loạn, nhấn chìm) lẫn yù (chảy nhanh). Wiktionary ghi 4 âm đọc khác nhau tùy ngữ cảnh cổ điển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuồn cuộn; ào ạt (nước chảy)", "Hạng Tần Suất (Jun Da)": "4328.0", "Tần Suất % (Jun Da)": "99.826893517", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 曰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵曰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汩", "Unihan_Traditional (Chữ Phồn thể)": "汩", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường dùng làm động từ miêu tả dòng nước chảy xiết hoặc làm phó từ trong từ láy tượng thanh chỉ tiếng nước chảy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浣', '{"9000": "4329.0", "Chữ Trung Quốc": "浣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 水 | thủy | biểu nghĩa | nước | 完 | hoàn | biểu âm | hoàn toàn | 浣 = 水 (Thủy, biểu nghĩa: nước) + 完 (Hoàn, biểu âm); chữ hình thanh. Bộ nước chỉ hành động giặt rửa, 完 cho âm gần với huàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoán\": bộ 水 (nước) + 完 (hoàn toàn) — giặt cho đến khi quần áo hoàn toàn sạch bằng nước. | Gương Hán-Việt | hoán — thấy trong \"hoán sa\" (浣紗: giặt lụa) của Tây Thi | Mở khoá kiến thức | Biết 浣 mở khoá từ 浣熊 (huànxióng — gấu mèo rửa thức ăn), 浣纱溪 (suối giặt lụa).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 水 biểu nghĩa chỉ nước, 完 (hoàn) biểu âm. Tiểu triện thấy hình thức này. Nghĩa gốc là giặt quần áo bên sông — thơ Vương Duy thế kỷ 8 có câu \"竹喧歸浣女\" (tiếng ồn ào nơi những cô gái đi giặt về). Ngoài ra, 浣 còn chỉ kỳ mười ngày trong tháng (thượng trung hạ浣). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giặt (quần áo)", "Hạng Tần Suất (Jun Da)": "4329.0", "Tần Suất % (Jun Da)": "99.8270981639", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浣", "Unihan_Traditional (Chữ Phồn thể)": "浣", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán, cán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ quần áo hoặc lụa là để chỉ hoạt động giặt giũ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舐', '{"9000": "4330.0", "Chữ Trung Quốc": "舐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舌 | Số nét | 10 | nét | 舌 | thiệt | biểu nghĩa | lưỡi | 氏 | thị | biểu âm | dòng họ | 舐 = 舌 (Thiệt, biểu nghĩa: lưỡi) + 氏 (Thị, biểu âm); chữ hình thanh. Bộ lưỡi chỉ hành động liếm, 氏 cho âm gần với shì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": bộ 舌 (lưỡi) + 氏 (thị — họ) — con vật dùng lưỡi liếm con cái của \"họ\" mình, như bò mẹ liếm bê con. | Gương Hán-Việt | thị — hiếm dùng độc lập; thành ngữ 舐犊 (thị độc: liếm bê — tình mẫu tử) | Mở khoá kiến thức | Biết 舐 mở khoá thành ngữ 舐犊情深 (tình mẹ thương con sâu nặng) và 老牛舐犊.", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 舌 biểu nghĩa chỉ lưỡi, 氏 biểu âm. Wiktionary ghi rằng Thuyết văn gốc dùng 舓 (phonetic 易) và 𦧇 (phonetic 也) — dạng 舐 với phonetic 氏 là hình thức chuẩn hóa sau. Nghĩa gốc: liếm bằng lưỡi. Thành ngữ 舐犊情深 (shì dú qíng shēn — tình mẹ liếm con bê: tình mẫu tử sâu nặng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếm", "Hạng Tần Suất (Jun Da)": "4330.0", "Tần Suất % (Jun Da)": "99.8273028108", "GavinGrover_Once (Chiết tự trực tiếp)": "舌 + 氏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舌氏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舌", "Unihan_Simplified (Chữ Giản thể)": "舐", "Unihan_Traditional (Chữ Phồn thể)": "舐", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ bộ phận cơ thể hoặc đồ vật để diễn tả hành động liếm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忻', '{"9000": "4331.0", "Chữ Trung Quốc": "忻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忄 | tâm | biểu nghĩa | tâm, lòng | 斤 | cân | biểu âm | cái rìu | 忻 = 忄(Tâm, biểu nghĩa: lòng) + 斤 (Cân, biểu âm); chữ hình thanh. Bộ tâm chỉ cảm xúc vui vẻ, 斤 cho âm đọc xīn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hân\": bộ 忄(lòng) + 斤 (cân — rìu) — lòng nhẹ như không có rìu chặt xuống, tức là lòng hân hoan vui vẻ. | Gương Hán-Việt | hân — thấy trong \"hân hoan\" (忻歡), \"hân hỉ\" | Mở khoá kiến thức | Biết 忻 mở khoá dạng cổ của 欣 (hân) — những từ chỉ niềm vui trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 忄(心) biểu nghĩa chỉ tấm lòng, 斤 biểu âm. Tiểu triện đã có hình thức này. Trong văn ngôn, 忻 là dị thể của 欣 (vui mừng). Sử ký dùng 忻 với nghĩa \"vui lòng ngưỡng mộ\" (所忻慕焉). Nghĩa gốc: lòng vui vẻ, hân hoan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "385.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Cân (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148 - tâm đứng) và chữ Cân (số 195 - cái rìu) . Hân là trạng thái vui vẻ, phấn khởi. Giải thích sự chuyển ý: Chữ Cân (cái rìu) chỉ âm, chữ Tâm (lòng) chỉ ý. Trạng thái trong lòng (Tâm) cảm thấy vui vẻ, hân hoan gọi là Hân. *(Biến âm Hán Việt: Cân -> Hân)*", "Nghĩa Tiếng Việt_Xie": "hơn hớn vui vẻ", "Hạng Tần Suất (Jun Da)": "4331.0", "Tần Suất % (Jun Da)": "99.8277110711", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忻", "Unihan_Traditional (Chữ Phồn thể)": "忻", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "hân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ biểu thị tâm trạng vui tươi hoặc làm động từ trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咻', '{"9000": "4332.0", "Chữ Trung Quốc": "咻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 咻 | hiu | tượng hình | tiếng kêu, la ó | 咻 là chữ tượng thanh/tượng hình tự — bộ 口 (khẩu) kết hợp để mô tả âm thanh la ó, giễu cợt. Cấu trúc chi tiết trong CHISE không rõ ràng, chỉ thấy trong hình thức hiện tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiu\": bộ 口 (miệng) — đám đông há miệng la \"hiu hiu\" giễu cợt ai đó. | Gương Hán-Việt | hiu — hiếm dùng độc lập trong từ Hán-Việt | Mở khoá kiến thức | Biết 咻 mở khoá cụm 咻咻 (xiūxiū — âm thanh vèo vèo, ào ào).", "Tự nguyên_Xie": "Chữ tượng thanh: bộ 口 liên quan đến miệng/âm thanh, nghĩa là la hét, giễu cợt. Wiktionary không có glyph origin cổ cho 咻. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giễu cợt", "Hạng Tần Suất (Jun Da)": "4332.0", "Tần Suất % (Jun Da)": "99.8279146844", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 休", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口休", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "休", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咻", "Unihan_Traditional (Chữ Phồn thể)": "咻", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "hưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Thường làm động từ chỉ hành động la hét, giễu cợt hoặc làm từ tượng thanh mô tả tiếng thở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹑', '{"9000": "4333.0", "Chữ Trung Quốc": "鹑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹑 | thuần | tượng hình | chim cút | 鹑 (giản thể của 鶉) là chữ chỉ loài chim, bộ 鸟/鳥 (điểu: chim). Cấu trúc chi tiết không rõ trong CHISE — chữ tạo muộn chuyên chỉ chim cút có lông đốm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": chim cút — loài chim \"thuần\" chất, sống dưới đất, không bay cao như các loài chim khác. | Gương Hán-Việt | thuần — thấy trong \"am thuần\" (鵪鶉: chim cút) | Mở khoá kiến thức | Biết 鹑 mở khoá từ 鹌鹑 (ānchún — chim cút) và thành ngữ 鹑衣百结 (áo rách như tổ đỉa).", "Tự nguyên_Xie": "鶉 xuất hiện trong Kinh thi (Thi kinh), chỉ loài chim cút có lông đốm: \"鶉之奔奔\" (chim cút chạy từng đôi). Trong văn ngôn, 懸鶉 (huyền thuần) chỉ áo rách như lông chim cút treo lơ lửng — ý nói nghèo khó. Wiktionary không có glyph origin cổ chi tiết. chưa có nguồn glyph học thuật. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: am thuần 鵪鶉,鹌鹑)", "Hạng Tần Suất (Jun Da)": "4333.0", "Tần Suất % (Jun Da)": "99.8281182978", "GavinGrover_Once (Chiết tự trực tiếp)": "享 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰享鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹑", "Unihan_Traditional (Chữ Phồn thể)": "鶉", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép để chỉ loài chim cút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唑', '{"9000": "4334.0", "Chữ Trung Quốc": "唑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 唑 | doạ | tượng hình | zôn/dôn — âm phiên âm hóa học | 唑 là chữ phiên âm hiện đại, không có cấu trúc hình thanh/hội ý cổ điển. Được tạo để phiên âm gốc -zole trong hóa học (imidazole, pyrazole...). Không có glyph origin trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doạ\": chữ tạo mới chỉ nhóm azole trong hóa học — nhớ bằng âm \"doa\" gần với \"zo\" trong \"azole\". | Gương Hán-Việt | doạ — chỉ dùng trong thuật ngữ hóa học phiên âm | Mở khoá kiến thức | Biết 唑 mở khoá tên hóa chất như 咪唑 (imidazole), 吡唑 (pyrazole), 噁唑 (oxazole).", "Tự nguyên_Xie": "唑 là chữ tạo mới trong tiếng Trung hiện đại, dùng để phiên âm đuôi \"-zole\" trong tên hóa chất (azole — nhóm hợp chất vòng nitrogen). Không có nguồn glyph cổ, không thấy trong giáp cốt/kim văn. chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "zôn; dôn (âm dùng phiên âm)", "Hạng Tần Suất (Jun Da)": "4334.0", "Tần Suất % (Jun Da)": "99.8283219111", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唑", "Unihan_Traditional (Chữ Phồn thể)": "唑", "Pinyin_Xie": "zuò", "Âm Hán Việt_Xie": "phệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học để phiên âm các hợp chất hữu cơ có vòng azole. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懋', '{"9000": "4335.0", "Chữ Trung Quốc": "懋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 17 | nét | 懋 | mậu | tượng hình | siêng năng, to lớn | 懋 có cấu trúc phức tạp — phần trên là 楙 (mậu: cây tươi tốt) và phần dưới là 心 (tâm). Hội ý: tâm lòng hướng đến sự tươi tốt, phát triển → siêng năng, vĩ đại. Không có lsCodes chi tiết từ CHISE.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": cây (楙) to tốt + tâm (心) — lòng người to lớn như cây rừng, chỉ sự vĩ đại và siêng năng. | Gương Hán-Việt | mậu — thấy trong \"mậu công\" (懋功: công trạng vĩ đại) | Mở khoá kiến thức | Biết 懋 mở khoá từ 懋勋 (công huân to lớn), 懋迁 (buôn bán hàng hóa xa) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 懋 xuất hiện trong kinh điển Trung Hoa cổ (Thư kinh), mang nghĩa siêng năng cần mẫn, khích lệ, và hùng vĩ. Tiểu triện đã có hình thức này. Wiktionary không có glyph origin chi tiết. Các cụm như 懋功 (mậu công: công lao to lớn), 懋迁 (mậu thiên: buôn bán). chưa có nguồn glyph học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuyên răn", "Hạng Tần Suất (Jun Da)": "4335.0", "Tần Suất % (Jun Da)": "99.8285250077", "GavinGrover_Once (Chiết tự trực tiếp)": "楙 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱楙心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "楙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "懋", "Unihan_Traditional (Chữ Phồn thể)": "懋", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ sự siêng năng hoặc làm động từ khuyên răn trong văn cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皎', '{"9000": "4336.0", "Chữ Trung Quốc": "皎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 11 | nét | 皎 | kiểu | tượng hình | trắng sáng | 皎 thuộc bộ 白 (bạch: trắng). Cấu trúc chi tiết không rõ trong CHISE — chữ mô tả ánh sáng trắng rực rỡ, đặc biệt là ánh trăng. Không có lsCodes từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểu\": bộ 白 (trắng) — ánh trăng \"kiểu\" sáng trắng tinh khiết, rực rỡ giữa đêm. | Gương Hán-Việt | kiểu — thấy trong \"kiểu kiểu\" (皎皎: trắng sáng rực rỡ) | Mở khoá kiến thức | Biết 皎 mở khoá từ 皎洁 (kiểu khiết: sáng trong), 皎皎 (rực rỡ) trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 皎 thuộc bộ 白 (trắng, sáng), chỉ ánh sáng trắng tinh, rực rỡ. Tiểu triện và Lục thư thông đã thấy hình thức này. Wiktionary không có glyph origin cổ chi tiết. Thơ cổ thường dùng 皎皎 (kiểu kiểu) để tả vầng trăng sáng: \"皎皎明月光\" — ánh trăng sáng ngời. chưa có nguồn học thuật cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trắng; sạch sẽ", "Hạng Tần Suất (Jun Da)": "4336.0", "Tần Suất % (Jun Da)": "99.8287281042", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皎", "Unihan_Traditional (Chữ Phồn thể)": "皎", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả ánh trăng sáng hoặc sự trong trắng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诒', '{"9000": "4337.0", "Chữ Trung Quốc": "诒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 台 | đài | biểu âm | đài | 诒 (giản thể từ 詒) = 讠(Ngôn, biểu nghĩa: lời) + 台 (Đài, biểu âm). Chữ hình thanh chỉ việc trao tặng lời hay/vật tốt cho người sau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": bộ 讠(lời) + 台 (đài) — lời hay \"để lại\" trên đài cao cho đời sau, như di sản lời dạy. | Gương Hán-Việt | di — thấy trong \"di mưu\" (诒谋: kế sách để lại), tương tự 遗 (di — để lại) | Mở khoá kiến thức | Biết 诒 mở khoá văn ngôn cổ về việc truyền kế sách, di sản cho đời sau.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 诒 là giản thể của 詒. Kim văn và tiểu triện đã có hình thức 詒. Nghĩa gốc: đưa tặng, để lại cho con cháu. Trong văn ngôn, 诒 thường dùng trong cụm 诒谋 (di mưu: kế sách để lại cho đời sau) hay 诒厥孙谋 (Kinh thi: để lại kế sách cho con cháu). chưa có nguồn glyph origin chi tiết ngoài kim văn/tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đưa tặng", "Hạng Tần Suất (Jun Da)": "4337.0", "Tần Suất % (Jun Da)": "99.828930684", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诒", "Unihan_Traditional (Chữ Phồn thể)": "詒", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ việc truyền lại cho đời sau hoặc ban tặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麾', '{"9000": "4338.0", "Chữ Trung Quốc": "麾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麻 | Số nét | 15 | nét | 麾 | huy | tượng hình | cờ hiệu, chỉ huy | 麾 có bộ 麻 (ma: gai dầu) làm gốc, kết hợp với các phần bên dưới mô tả hình cờ làm từ vải gai. Cấu trúc chi tiết không có trong CHISE (lsCodes rỗng). Chữ chỉ lá cờ chỉ huy trong quân đội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": cờ hiệu — vị tướng \"huy\" tay cầm cờ ra lệnh cho quân đội xông trận. | Gương Hán-Việt | huy — thấy trong \"huy hạ\" (麾下: cấp dưới), \"chỉ huy\" (指麾) | Mở khoá kiến thức | Biết 麾 mở khoá từ 麾下 (quân dưới trướng), 指麾 (chỉ huy) trong văn ngôn quân sự.", "Tự nguyên_Xie": "麾 chỉ lá cờ hiệu dùng để chỉ huy quân đội. Wiktionary không có glyph origin cổ chi tiết. Nghĩa mở rộng: vẫy cờ để chỉ huy, điều khiển. Thành ngữ 麾下 (huy hạ: dưới trướng, cấp dưới), 指麾 (chỉ huy). chưa có nguồn học thuật cổ điển về glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lá cờ; chỉ huy", "Hạng Tần Suất (Jun Da)": "4338.0", "Tần Suất % (Jun Da)": "99.829132747", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "麾", "Unihan_Traditional (Chữ Phồn thể)": "麾", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "huy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lá cờ lệnh hoặc làm động từ chỉ hành động ra hiệu chỉ huy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辏', '{"9000": "4339.0", "Chữ Trung Quốc": "辏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 辏 | tấu | tượng hình | bầu bánh xe, tụ hội | 辏 (giản thể của 輳) có bộ 车/車 (xa: xe). Cấu trúc truyền thống: 輳 = 車 (biểu nghĩa: xe) + 奏 (biểu âm: tấu). Chữ hình thanh chỉ phần nan hoa tụ về bầu bánh xe, nghĩa mở rộng là tụ tập đông đúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấu\": bộ 车 (xe) + 奏 (tấu nhạc) — hình ảnh các nan hoa tụ về bầu như ban nhạc \"tấu\" lên cùng nhau. | Gương Hán-Việt | tấu — thấy trong \"phúc tấu\" (辐辏: nan hoa tụ về, tức tụ tập đông) | Mở khoá kiến thức | Biết 辏 mở khoá từ 辐辏 (fúcòu — tụ tập đông đúc) dùng trong văn tả dân cư, thương mại phồn thịnh.", "Tự nguyên_Xie": "Đại triện | 輳 = 車 (xa, biểu nghĩa: xe) + 奏 (tấu, biểu âm). Đại triện đã có hình thức này. Nghĩa gốc: bầu bánh xe — nơi các nan hoa (輻) tụ về. Thành ngữ 辐辏 (fúcòu — các nan hoa tụ về bầu, tức là tụ tập đông đúc). chưa có nguồn glyph origin Wiktionary chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bầu bánh xe (chỗ đầu các nan hoa tụ lại); tụ họp đông đúc", "Hạng Tần Suất (Jun Da)": "4339.0", "Tần Suất % (Jun Da)": "99.8293342932", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "辏", "Unihan_Traditional (Chữ Phồn thể)": "輳", "Pinyin_Xie": "còu", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ sự tụ hội, tập trung của người hoặc vật về một điểm trung tâm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氐', '{"9000": "4340.0", "Chữ Trung Quốc": "氐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 氏 | Số nét | 5 | nét | 氏 | thị | dòng tộc, hình người cúi | 一 | nhất | một vạch nền | 氐 = 氏 (Thị, mô tả người cúi mình) + 一 (nét ngang ở dưới). Wiktionary mô tả: hình người cúi mình với vòng tròn/nét ngang bên dưới — có thể là người gieo hạt trên ruộng hoặc gốc rễ cây với dấu ở đáy. Đây là chữ tượng hình/chỉ sự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": 氏 (người cúi) + nét ngang bên dưới — người cúi sát xuống đất, chỉ cái nền/gốc rễ thấp nhất. | Gương Hán-Việt | đê — thấy trong \"đê tứ\" (氐四: sao Đê trong nhị thập bát tú) | Mở khoá kiến thức | Biết 氐 mở khoá sao Đê (một trong 28 sao), tộc người Đê trong lịch sử, và gốc chữ 柢 (đê — gốc rễ).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary mô tả 氐 = 氏 (người cúi, dòng tộc) + một vạch ngang bên dưới — mô tả người cúi xuống đất hoặc gốc cây với dấu ở dưới cùng (xem thêm 柢 — gốc rễ). Kim văn, đại triện, tiểu triện đều có hình thức này. Nghĩa: nền/gốc, cũng là tên tộc người 氐 (Đê) ở Tây Bắc Trung Quốc cổ, và sao Đê trong nhị thập bát tú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "850.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thị (679)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Dấu chấm (nét Chủ) ở dưới chữ Thị (số 679 - họ). Dấu chấm tượng trưng cho cái nền, cái gốc, cái căn bản cơ sở của một dòng họ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Đê là cái gốc, cái nền, cái căn bản.", "Nghĩa Tiếng Việt_Xie": "nền, gốc; sao Đê (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "4340.0", "Tần Suất % (Jun Da)": "99.8295353226", "GavinGrover_Once (Chiết tự trực tiếp)": "氏 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴氏丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氏", "Unihan_Simplified (Chữ Giản thể)": "氐", "Unihan_Traditional (Chữ Phồn thể)": "氐", "Pinyin_Xie": "dī", "Âm Hán Việt_Xie": "đê, để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ gốc rễ, tên chòm sao hoặc làm tính từ chỉ sự thấp kém. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冽', '{"9000": "4341.0", "Chữ Trung Quốc": "冽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 8 | nét | 冫 | băng | biểu nghĩa | băng lạnh | 列 | liệt | biểu âm | hàng liệt | 冽 = 冫(Băng, biểu nghĩa: băng/lạnh) + 列 (Liệt, biểu âm); chữ hình thanh. Bộ băng chỉ nghĩa lạnh buốt, 列 cho âm đọc liè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rét\": bộ 冫(băng) + 列 (liệt — hàng liệt) — cái lạnh \"rét\" buốt như hàng nghìn mũi nhọn băng đâm vào da. | Gương Hán-Việt | rét — thấy trong \"lẫm liệt\" (凛冽: lạnh buốt) — 冽 biến âm thành rét trong Hán-Việt | Mở khoá kiến thức | Biết 冽 mở khoá từ 凛冽 (lạnh buốt), 清冽 (nước lạnh trong) trong thơ văn cổ điển.", "Tự nguyên_Xie": "Chữ hình thanh: 冫(仌) biểu nghĩa chỉ băng/lạnh, 列 (liệt) biểu âm. Nghĩa gốc: lạnh buốt, cắt da. Dùng trong thơ cổ tả mùa đông: 凜冽 (lẫm liệt: lạnh buốt), 清冽 (thanh liệt: nước suối lạnh trong). Cũng là dị thể của 洌 (nước trong sạch). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hơi lạnh", "Hạng Tần Suất (Jun Da)": "4341.0", "Tần Suất % (Jun Da)": "99.829736352", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 列", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫列", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "列", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冽", "Unihan_Traditional (Chữ Phồn thể)": "冽", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ như gió, nước để tả cái lạnh buốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箕', '{"9000": "4342.0", "Chữ Trung Quốc": "箕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre trúc | 其 | kỳ | biểu âm | nó, đó | 箕 = 竹 (Trúc, biểu nghĩa: tre trúc) + 其 (Kỳ, biểu âm); chữ hình thanh. Bộ trúc chỉ vật liệu làm từ tre (giỏ, sọt), 其 cho âm đọc jī. Thực ra 箕 chuyên hóa từ 其 — chữ gốc 其 đã vẽ hình cái sàng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kia\": 竹 (trúc) + 其 (kỳ) — \"kia\" cái rổ tre đan bằng trúc dùng sàng gạo hay hốt rác. | Gương Hán-Việt | kia — thấy trong \"ky\" (箕: cái rổ, sao Kỳ trong nhị thập bát tú) | Mở khoá kiến thức | Biết 箕 mở khoá từ 簸箕 (bǒjī — cái rổ sàng), 箕踞 (ngồi xoạc chân — tư thế vô lễ) và sao Kỳ.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Wiktionary ghi 箕 là chuyên hóa của 其: chữ 其 nguyên là hình vẽ cái sàng/rổ tre (giáp cốt văn và kim văn thấy rõ). Sau khi 其 trở thành đại từ hư từ, người ta thêm 竹 vào để tạo 箕 mang nghĩa gốc là đồ đan bằng tre. Kim văn và tiểu triện đều thấy hình thức này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa tay, vằn tay; sọt rác; sao Ky (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "4342.0", "Tần Suất % (Jun Da)": "99.8299368647", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箕", "Unihan_Traditional (Chữ Phồn thể)": "箕", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki, cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vật dụng làm bằng tre nứa hoặc hình vân tay tròn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俚', '{"9000": "4343.0", "Chữ Trung Quốc": "俚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 里 | lý | biểu âm | làng, dặm | 俚 = 亻(Nhân, biểu nghĩa: người) + 里 (Lý, biểu âm); chữ hình thanh. Bộ nhân chỉ liên quan đến con người và xã hội, 里 cho âm đọc lǐ. Nghĩa: người dân gian, quê mùa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lái\": 亻(người) + 里 (làng) — người \"lái\" buôn từ làng quê lên, quê mùa mộc mạc chưa quen phong cách thành thị. | Gương Hán-Việt | lái — thấy trong \"lái ngữ\" (俚语: tiếng lóng, lời dân gian) | Mở khoá kiến thức | Biết 俚 mở khoá từ 俚语 (lǐyǔ — tiếng lóng/ngôn ngữ bình dân) rất quan trọng trong học tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 亻(人) biểu nghĩa chỉ người, 里 biểu âm. Tiểu triện đã thấy hình thức này. Nghĩa gốc: người thôn quê, phong cách dân gian. Từ 俚语 (lǐyǔ — ngôn ngữ bình dân, tiếng lóng) rất phổ biến trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dân gian; quê mùa", "Hạng Tần Suất (Jun Da)": "4343.0", "Tần Suất % (Jun Da)": "99.8301368605", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俚", "Unihan_Traditional (Chữ Phồn thể)": "俚", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ bổ nghĩa cho danh từ để chỉ sự dân dã hoặc thô tục. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汴', '{"9000": "4344.0", "Chữ Trung Quốc": "汴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 汴 | biện | tượng hình | sông Biện | 汴 thuộc bộ 氵(thủy), chỉ tên một con sông. Cấu trúc chi tiết không rõ trong CHISE. Chỉ có hình Lục thư thông, không thấy giáp cốt/kim văn — chữ tạo muộn làm địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": sông Biện — con sông chạy qua Biện Kinh (Khai Phong), kinh đô nhà Bắc Tống, nơi vẽ bức 清明上河图 nổi tiếng. | Gương Hán-Việt | biện — thấy trong \"Biện Kinh\" (汴京: kinh đô Tống), \"Biện Lương\" (汴梁) | Mở khoá kiến thức | Biết 汴 mở khoá địa danh lịch sử như 汴京 (Biện Kinh), 汴河 (sông Biện) và bức tranh 清明上河图.", "Tự nguyên_Xie": "Lục thư thông | 汴 là tên riêng của sông Biện ở tỉnh Hà Nam, Trung Quốc. Chỉ có hình Lục thư thông, không có glyph cổ. Thành phố Biện Lương (汴梁/汴京) — tức Khai Phong ngày nay — từng là kinh đô nhà Tống. Câu chuyện tranh vẽ \"清明上河图\" mô tả cảnh sầm uất trên sông Biện. chưa có nguồn glyph học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Biện", "Hạng Tần Suất (Jun Da)": "4344.0", "Tần Suất % (Jun Da)": "99.8303363396", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汴", "Unihan_Traditional (Chữ Phồn thể)": "汴", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh hoặc dòng sông cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宸', '{"9000": "4345.0", "Chữ Trung Quốc": "宸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 10 | nét | 宸 | thần | tượng hình | cung vua, ngai vàng | 宸 thuộc bộ 宀 (miên: mái nhà), kết hợp phần dưới chỉ cung điện to lớn. Cấu trúc chi tiết không rõ trong CHISE. Tiểu triện đã có hình thức này. Nghĩa: mái hiên, cung điện, cung vua — dùng trang trọng chỉ thiên tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thần\": bộ 宀 (mái nhà) — ngôi nhà của \"thần\" — tức là cung điện vua, nơi thiên tử ngự trị. | Gương Hán-Việt | thần — thấy trong \"thần cực\" (宸极: ngai vàng), \"tử thần\" (紫宸: cung tím của vua) | Mở khoá kiến thức | Biết 宸 mở khoá từ 宸旒 (mũ vua), 紫宸 (cung điện hoàng gia), 宸翰 (bút tích nhà vua) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 宸 thuộc bộ 宀 (mái nhà), chỉ mái hiên rộng của cung điện, nghĩa mở rộng thành cung vua/ngai vàng. Tiểu triện đã có hình thức này. Wiktionary không có glyph origin cổ chi tiết. Dùng trong thơ văn cung đình: 紫宸 (tử thần: cung tím), 宸旒 (thần lưu: mũ miện vua). chưa có nguồn học thuật cổ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cung vua", "Hạng Tần Suất (Jun Da)": "4345.0", "Tần Suất % (Jun Da)": "99.8305358186", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 辰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宸", "Unihan_Traditional (Chữ Phồn thể)": "宸", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "thần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ hoàng cung hoặc những gì liên quan đến hoàng đế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芍', '{"9000": "4346.0", "Chữ Trung Quốc": "芍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艸 | thảo | biểu nghĩa | cỏ cây | 勺 | thược | biểu âm | cái muôi | 芍 = 艸 (Thảo, biểu nghĩa: cỏ cây) + 勺 (Thược, biểu âm); chữ hình thanh. Bộ thảo chỉ đây là loài cây, 勺 cho âm đọc sháo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thược\": bộ 艸 (cây) + 勺 (thược — cái muôi) — cây thược dược, bông hoa đẹp như cái muôi múc vào lòng người. | Gương Hán-Việt | thược — thấy trong \"thược dược\" (芍药: hoa thược dược, mẫu đơn thảo) | Mở khoá kiến thức | Biết 芍 mở khoá từ 芍药 (sháoyào — thược dược, loài hoa/thuốc Đông y quan trọng).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 艸 biểu nghĩa chỉ cây cỏ, 勺 (thược) biểu âm. Tiểu triện đã có hình thức này. 芍 thường đứng một mình trong 芍药 (sháoyào — hoa mẫu đơn/thược dược), loài hoa quý trong văn hóa Trung Hoa. Tên cây thuốc quan trọng trong Đông y. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thược dược 芍药)", "Hạng Tần Suất (Jun Da)": "4346.0", "Tần Suất % (Jun Da)": "99.8307347809", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芍", "Unihan_Traditional (Chữ Phồn thể)": "芍", "Pinyin_Xie": "sháo", "Âm Hán Việt_Xie": "thược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong liên từ ghép chỉ loài hoa hoặc vị thuốc thược dược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捱', '{"9000": "4347.0", "Chữ Trung Quốc": "捱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 捱 | nhay | tượng hình | chịu đựng, kéo dài | 捱 thuộc bộ 扌(thủ: tay), chỉ hành động dùng sức chịu đựng, cố nán lại. Cấu trúc chi tiết không rõ trong CHISE. Nghĩa: chịu đựng gian khổ, kéo dài thời gian vượt qua khó khăn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhay\": bộ 扌(tay) — dùng tay \"nhay\" (bấu víu) vào thời gian, chịu đựng qua từng ngày khó khăn. | Gương Hán-Việt | nhay — ít dùng trong từ Hán-Việt chuẩn; phổ biến trong tiếng Quảng Đông | Mở khoá kiến thức | Biết 捱 mở khoá từ 捱打 (chịu đòn), 捱苦 (chịu cực), 捱日子 (sống qua ngày) trong phương ngữ Quảng Đông.", "Tự nguyên_Xie": "捱 thuộc bộ 扌(手), nghĩa gốc là chịu đựng, cố kéo dài qua gian khổ. Wiktionary ghi âm trung cổ (Middle Chinese) xác nhận âm ngai4 (Quảng Đông). Chữ phổ biến trong phương ngữ Quảng Đông: 捱打 (chịu đòn), 捱苦 (chịu cực). Không có glyph origin cổ chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chống cự", "Hạng Tần Suất (Jun Da)": "4347.0", "Tần Suất % (Jun Da)": "99.8309337432", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 厓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌厓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捱", "Unihan_Traditional (Chữ Phồn thể)": "捱", "Pinyin_Xie": "ái", "Âm Hán Việt_Xie": "nhai, ngai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị việc cố gắng chịu đựng gian khổ hoặc kéo dài thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摈', '{"9000": "4348.0", "Chữ Trung Quốc": "摈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 手 | thủ | biểu nghĩa | tay | 賓 | tân | biểu âm | khách | 摈 = 手 (Thủ, biểu nghĩa: tay) + 賓 (Tân, biểu âm); chữ hình thanh. Bộ tay chỉ hành động xua đuổi bằng tay, 賓 cho âm đọc bìn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": bộ 手 (tay) + 賓 (tân — khách) — dùng tay đuổi \"tân\" khách ra cửa, tức là ruồng đuổi, loại bỏ. | Gương Hán-Việt | tân — thấy trong \"tân khí\" (摈弃: loại bỏ, vứt đi) | Mở khoá kiến thức | Biết 摈 mở khoá từ 摈弃 (bìnqì — từ chối, loại bỏ) rất dùng trong văn viết hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 手 biểu nghĩa chỉ tay, 賓 (tân — khách) biểu âm. Tiểu triện đã có hình thức 擯. Nghĩa: đuổi đi, loại bỏ, từ chối. Nghịch lý thú vị: phonetic 賓 có nghĩa \"khách\" nhưng 摈 lại có nghĩa xua đuổi khách đi. Cụm phổ biến: 摈弃 (bìnqì — loại bỏ, vứt bỏ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ruồng đuổi", "Hạng Tần Suất (Jun Da)": "4348.0", "Tần Suất % (Jun Da)": "99.8311321887", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摈", "Unihan_Traditional (Chữ Phồn thể)": "擯", "Pinyin_Xie": "bìn", "Âm Hán Việt_Xie": "bấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ để chỉ hành động loại trừ hoặc ruồng rẫy ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簦', '{"9000": "4349.0", "Chữ Trung Quốc": "簦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簦 | đăng | tượng hình | cái ô lá, cây dù dài | 簦 thuộc bộ 竹 (trúc: tre), chỉ loại ô làm từ tre hoặc lá để che nắng mưa. Cấu trúc chi tiết không rõ trong CHISE. Không có glyph cổ — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đăng\": bộ 竹 (tre) — cây ô tre \"đăng\" lên vai người bán hàng rong che nắng. | Gương Hán-Việt | đăng — hiếm dùng độc lập; thấy trong \"đảm đăng\" (擔簦: vác ô — ý chỉ người đi bộ xa) | Mở khoá kiến thức | Biết 簦 mở khoá thành ngữ 擔簦 (đảm đăng: vác ô đi xa — người học trò nghèo du học).", "Tự nguyên_Xie": "簦 thuộc bộ 竹, chỉ loại ô/dù cán dài làm từ tre, dùng cho người bán hàng rong hoặc đi bộ. Wiktionary ghi âm dēng (Quan thoại), Middle Chinese dang1. Không có glyph cổ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ô (cái dù) lợp bằng lá để che nắng", "Hạng Tần Suất (Jun Da)": "4349.0", "Tần Suất % (Jun Da)": "99.8315290797", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簦", "Unihan_Traditional (Chữ Phồn thể)": "簦", "Pinyin_Xie": "dēng", "Âm Hán Việt_Xie": "đăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loại ô dù cổ làm bằng tre lá để che mưa nắng khi đi đường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箔', '{"9000": "4350.0", "Chữ Trung Quốc": "箔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箔 | bạc | tượng hình | rèm mành, tấm dát mỏng | 箔 thuộc bộ 竹 (trúc: tre), chỉ rèm làm từ tre hoặc tấm vật liệu dát mỏng. Cấu trúc chi tiết không rõ trong CHISE. Không có glyph cổ — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": bộ 竹 (tre) — những tấm tre \"bạc\" mỏng đan thành mành rèm hoặc cái khung nuôi tằm. | Gương Hán-Việt | bạc — thấy trong \"kim bạc\" (金箔: vàng lá), \"ngân bạc\" (银箔: bạc lá) | Mở khoá kiến thức | Biết 箔 mở khoá từ 金箔 (vàng lá), 铝箔 (giấy nhôm), 箔膜 (màng mỏng) trong kỹ thuật và đời sống.", "Tự nguyên_Xie": "箔 thuộc bộ 竹, nghĩa gốc là tấm rèm/màn làm từ tre mỏng, dùng cho người nuôi tằm hoặc làm vách ngăn. Nghĩa mở rộng: dát mỏng (kim箔 — vàng lá, 铝箔 — giấy nhôm). Không có glyph origin cổ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rèm, mành; dát mỏng", "Hạng Tần Suất (Jun Da)": "4350.0", "Tần Suất % (Jun Da)": "99.8317270084", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 泊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮泊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箔", "Unihan_Traditional (Chữ Phồn thể)": "箔", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ tấm rèm tre hoặc các lá kim loại được dát mỏng như vàng, bạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咝', '{"9000": "4351.0", "Chữ Trung Quốc": "咝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 咝 | tư | tượng hình | tiếng vèo vèo, rít | 咝 là giản thể của 噝, thuộc bộ 口 (khẩu: miệng), chỉ âm thanh rít vèo vèo như đạn bay hoặc rắn rít. Đây là chữ tượng thanh hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 口 (miệng/âm thanh) — tiếng \"tư tư\" rít vèo vèo như mũi tên hay đạn bay qua không khí. | Gương Hán-Việt | tư — hiếm dùng trong từ Hán-Việt chuẩn; chữ tượng thanh hiện đại | Mở khoá kiến thức | Biết 咝 mở khoá từ 咝咝 (sīsī — tiếng rít, vèo vèo) trong văn học hiện đại.", "Tự nguyên_Xie": "咝 là giản thể của 噝 — 噝 = 口 (khẩu) + 絲 (tư: tơ sợi, biểu âm). Chữ tượng thanh tạo muộn, chỉ âm thanh vèo vèo (đạn), rít (rắn), chíu chíu (tiếng chim). Không có glyph origin cổ. chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chíu chíu; vèo vèo; ti; như \"ti (tiếng bay vèo vèo)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "4351.0", "Tần Suất % (Jun Da)": "99.8319249371", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 丝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口丝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咝", "Unihan_Traditional (Chữ Phồn thể)": "噝", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Dùng làm từ tượng thanh mô phỏng tiếng gió rít hoặc tiếng kêu xì xì của loài rắn. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孀', '{"9000": "4352.0", "Chữ Trung Quốc": "孀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 20 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 霜 | sương | biểu âm | sương muối | 孀 = 女 (Nữ, biểu nghĩa: phụ nữ) + 霜 (Sương, biểu âm); chữ hình thanh. Bộ nữ chỉ đây là người phụ nữ, 霜 cho âm đọc shuāng. Hình ảnh người vợ góa lạnh lẽo như sương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sương\": 女 (nữ) + 霜 (sương muối) — người phụ nữ góa chồng cô đơn lạnh lẽo như sương giá mùa đông. | Gương Hán-Việt | sương — thấy trong \"sương phụ\" (孀妇: góa phụ), \"sương thê\" (孀妻: vợ góa) | Mở khoá kiến thức | Biết 孀 mở khoá từ 孀妇 (góa phụ), 孀居 (sống cô đơn sau khi chồng mất).", "Tự nguyên_Xie": "Chữ hình thanh: 女 biểu nghĩa chỉ phụ nữ, 霜 (sương muối) biểu âm. Nghĩa: người đàn bà góa chồng. Wiktionary không có glyph origin cổ chi tiết. Hình ảnh thơ: người góa phụ cô đơn lạnh lẽo như sương. chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "472.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Sương (471)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nữ (số 38 - phụ nữ) và chữ Sương (số 471 - sương giá) . Người phụ nữ (Nữ) mất chồng, cuộc đời trở nên lạnh lẽo lẻ loi như giọt sương giá (Sương) gọi là sương phụ (quả phụ). Giải thích sự chuyển ý: Chữ Sương (sương giá) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Người đàn bà (Nữ) góa chồng sống hiu quạnh (Sương).", "Nghĩa Tiếng Việt_Xie": "goá chồng", "Hạng Tần Suất (Jun Da)": "4352.0", "Tần Suất % (Jun Da)": "99.832122349", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 霜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女霜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "孀", "Unihan_Traditional (Chữ Phồn thể)": "孀", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "sương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ góa phụ hoặc tính từ bổ nghĩa cho danh từ chỉ phụ nữ góa chồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怏', '{"9000": "4353.0", "Chữ Trung Quốc": "怏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怏 | ương | tượng hình | tức giận, bất mãn | 怏 thuộc bộ 忄/心 (tâm: lòng), chỉ trạng thái tâm lý bất mãn, ưu uất. Cấu trúc chi tiết không rõ trong CHISE. Tiểu triện đã có hình thức này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ương\": bộ 忄(lòng) — lòng \"ương\" bướng, tức tối không vui, như đứa trẻ ương dỡ không được thỏa mãn. | Gương Hán-Việt | ương — thấy trong \"ương ương bất lạc\" (怏怏不乐: buồn bực không vui) | Mở khoá kiến thức | Biết 怏 mở khoá thành ngữ 怏怏不乐 (yàngyàng bùlè — bực bội buồn rầu) rất hay dùng.", "Tự nguyên_Xie": "Tiểu triện | 怏 thuộc bộ 忄(心), chỉ tâm trạng tức tối không hài lòng. Tiểu triện đã có hình thức này. Wiktionary không có glyph origin cổ chi tiết. Thành ngữ 怏怏不乐 (yàngyàng bùlè — buồn bực không vui) rất phổ biến. chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tấm tức, không thoả mãn", "Hạng Tần Suất (Jun Da)": "4353.0", "Tần Suất % (Jun Da)": "99.8323192441", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怏", "Unihan_Traditional (Chữ Phồn thể)": "怏", "Pinyin_Xie": "yàng", "Âm Hán Việt_Xie": "ưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường dùng làm tính từ biểu thị trạng thái không vui hoặc làm phó từ đứng trước động từ để chỉ thái độ hậm hực. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谝', '{"9000": "4354.0", "Chữ Trung Quốc": "谝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói | 扁 | thiên | biểu âm | dẹt, bằng | 谝 = 言 (Ngôn, biểu nghĩa: lời nói) + 扁 (Thiên, biểu âm); chữ hình thanh. Bộ ngôn chỉ nghĩa liên quan đến lời nói khéo léo/giả tạo, 扁 cho âm đọc piǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": bộ 言 (lời) + 扁 (thiên — dẹt) — lời nói \"dẹt\" không có chiều sâu, chỉ bề mặt ngọt ngào để đánh lừa người. | Gương Hán-Việt | thiên — hiếm dùng độc lập; văn ngôn chỉ lời khéo léo giả tạo | Mở khoá kiến thức | Biết 谝 mở khoá từ 谝言 (piǎnyán — lời đường mật giả tạo) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 言 biểu nghĩa chỉ lời nói, 扁 biểu âm. Tiểu triện đã có hình thức 諞. Nghĩa: lời nói ngọt ngào nhưng không chân thành, khoe khoang, lừa đảo. Wiktionary ghi âm pián và piǎn. chưa có nguồn học thuật glyph cổ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói khéo, lường gạt", "Hạng Tần Suất (Jun Da)": "4354.0", "Tần Suất % (Jun Da)": "99.8325156225", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谝", "Unihan_Traditional (Chữ Phồn thể)": "諞", "Pinyin_Xie": "piǎn", "Âm Hán Việt_Xie": "biển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong khẩu ngữ để chỉ hành vi khoe khoang hoặc nói năng khéo léo nhằm lấy lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砧', '{"9000": "4355.0", "Chữ Trung Quốc": "砧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 石 | thạch | biểu nghĩa | đá | 占 | chiêm | biểu âm | chiếm, xem bói | 砧 = 石 (Thạch, biểu nghĩa: đá) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ đá chỉ nghĩa liên quan đến vật bằng đá/kim loại cứng, 占 cho âm đọc zhēn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châm\": bộ 石 (đá) + 占 (chiêm) — tảng đá \"châm\" dùng để đập vải khi giặt; tiếng 寒砧 vang vọng trong đêm đông nhớ người xa. | Gương Hán-Việt | châm — thấy trong \"hàn châm\" (寒砧: tiếng đập vải mùa lạnh — thơ cổ) | Mở khoá kiến thức | Biết 砧 mở khoá từ 砧板 (thớt), 砧骨 (xương búa trong tai), 寒砧 (hình ảnh thơ cổ điển).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Chữ hình thanh: 石 biểu nghĩa chỉ đá, 占 (chiêm) biểu âm. Bạch thư (帛書) và tiểu triện đã có hình thức này. Nghĩa gốc: tảng đá/bệ để giặt, đập quần áo; mở rộng thành đe (anvil), thớt chặt. Thơ Đường thường dùng 寒砧 (hàn châm: tiếng đập vải trong đêm lạnh) gợi nhớ người thân đi xa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chày đá để giặt", "Hạng Tần Suất (Jun Da)": "4355.0", "Tần Suất % (Jun Da)": "99.8327114841", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砧", "Unihan_Traditional (Chữ Phồn thể)": "砧", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cái thớt hoặc phiến đá dùng để giặt giũ, đập áo ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馕', '{"9000": "4356.0", "Chữ Trung Quốc": "馕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 25 | nét | 食 | thực | biểu nghĩa | thức ăn | 囊 | nang | biểu âm | túi, bọc | 馕 = 食 (Thực, biểu nghĩa: thức ăn) + 囊 (Nang, biểu âm); chữ hình thanh. Bộ thực chỉ đây là loại thức ăn, 囊 cho âm đọc náng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nang\": bộ 食 (ăn) + 囊 (nang — túi bọc) — bánh naan \"nang\" tròn như cái túi phồng, thức ăn đặc trưng vùng Tân Cương. | Gương Hán-Việt | nang — hiếm dùng độc lập; chỉ bánh naan trong bối cảnh Tân Cương | Mở khoá kiến thức | Biết 馕 giúp đọc hiểu văn hóa ẩm thực Tân Cương và các bài viết về người Uyghur, Kazakh.", "Tự nguyên_Xie": "Chữ hình thanh: 食 biểu nghĩa chỉ thức ăn, 囊 biểu âm. Wiktionary ghi {{Han compound|食|囊|ls=psc}}. Nghĩa: bánh nướng naan của các dân tộc thiểu số vùng Tân Cương và Trung Á (Uyghur, Kazakh). Âm náng phiên âm từ tiếng Uyghur \"nan/naan\". chưa có nguồn glyph origin cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh nướng của các dân tộc Uây-ua, Ka-dắc (miền Tân Cương của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4356.0", "Tần Suất % (Jun Da)": "99.8329073456", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 囊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣囊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馕", "Unihan_Traditional (Chữ Phồn thể)": "饢", "Pinyin_Xie": "náng", "Âm Hán Việt_Xie": "nang, nãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loại bánh nướng dẹt của các dân tộc thiểu số vùng Tân Cương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耄', '{"9000": "4357.0", "Chữ Trung Quốc": "耄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 老 | Số nét | 10 | nét | 耄 | mạo | tượng hình | già nua 80-90 tuổi | 耄 thuộc bộ 老 (lão: già), phần dưới có 毛 (mao: lông). Hội ý: người già (老) có lông/tóc (毛) trắng — chỉ người già nua ở độ tuổi 80-90. Không có lsCodes chi tiết. Chữ tạo muộn, chỉ thấy trong Lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạo\": bộ 老 (già) + 毛 (lông trắng) — người già \"mạo\" đầu tóc bạc phơ, 80-90 tuổi mà vẫn còn đó. | Gương Hán-Việt | mạo — thấy trong \"mạo điệt\" (耄耋: tuổi già 80-90) | Mở khoá kiến thức | Biết 耄 mở khoá thành ngữ 耄耋之年 (mạo điệt chi niên — tuổi già 80-90) trong văn ngôn trang trọng.", "Tự nguyên_Xie": "Lục thư thông | 耄 thuộc bộ 老/耂, kết hợp 毛 bên dưới — có thể hội ý: người già tóc bạc trắng như lông. Lục thư thông đã có hình thức này. Wiktionary không có glyph origin cổ chi tiết. Nghĩa: người già 80-90 tuổi; trong thành ngữ 耄耋 (mào dié — 80+90 tuổi: già lão). chưa có nguồn học thuật cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "già nua (tám chín mươi tuổi)", "Hạng Tần Suất (Jun Da)": "4357.0", "Tần Suất % (Jun Da)": "99.8331032072", "GavinGrover_Once (Chiết tự trực tiếp)": "老 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱老毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "老", "Unihan_Simplified (Chữ Giản thể)": "耄", "Unihan_Traditional (Chữ Phồn thể)": "耄", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự già yếu hoặc làm danh từ chỉ người già từ tám mươi đến chín mươi tuổi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罂', '{"9000": "4358.0", "Chữ Trung Quốc": "罂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 14 | nét | 賏 | anh | biểu âm | 缶 | phẫu | biểu nghĩa | đồ gốm, bình | 罂 = 賏 (Anh, biểu âm) + 缶 (Phẫu, biểu nghĩa: đồ gốm); chữ hình thanh. Bộ phẫu (缶) chỉ đây là loại bình gốm, 賏 cho âm đọc yīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": bộ 缶 (bình gốm) + 賏 (anh) — cái bình \"anh\" miệng nhỏ bụng to, như bình hoa hình quả bầu. | Gương Hán-Việt | anh — thấy trong \"anh túc\" (罂粟: cây anh túc/thuốc phiện) | Mở khoá kiến thức | Biết 罂 mở khoá từ 罂粟 (yīngsù — hoa anh túc/thuốc phiện) quan trọng trong lịch sử và y học.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 缶 (phẫu) biểu nghĩa chỉ đồ gốm, 賏 biểu âm. Tiểu triện và Lục thư thông đã có hình thức 罌. Nghĩa gốc: bình cổ nhỏ bụng to (small-mouthed jar). Thành ngữ 罂粟 (yīngsù — cây thuốc phiện — hoa poppy). chưa có nguồn học thuật glyph origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bình miệng nhỏ bụng to", "Hạng Tần Suất (Jun Da)": "4358.0", "Tần Suất % (Jun Da)": "99.8332990688", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 缶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "罂", "Unihan_Traditional (Chữ Phồn thể)": "甖", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại bình gốm cổ có bụng to và cổ hẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漕', '{"9000": "4359.0", "Chữ Trung Quốc": "漕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thủy | biểu nghĩa | nước | 曹 | tào | biểu âm | đám, nhóm | 漕 = 氵(Thủy, biểu nghĩa: nước) + 曹 (Tào, biểu âm); chữ hình thanh. Bộ nước chỉ nghĩa vận chuyển bằng đường thủy, 曹 cho âm đọc cáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tào\": bộ 氵(nước) + 曹 (tào — quan tào/nhóm) — \"quan tào\" phụ trách vận chuyển lương thực \"tào\" theo đường nước đến kinh đô. | Gương Hán-Việt | tào — thấy trong \"tào vận\" (漕运: vận tải đường kênh/thủy lộ) | Mở khoá kiến thức | Biết 漕 mở khoá từ 漕运 (cáoyùn — vận tải đường thủy), 漕渠 (kênh vận tải) trong lịch sử kinh tế Trung Quốc.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 氵(水) biểu nghĩa chỉ nước, 曹 (tào) biểu âm. Đại triện và tiểu triện đã có hình thức này. Nghĩa gốc: vận chuyển lương thực bằng đường thủy. Hệ thống 漕运 (cáo vận — vận tải đường kênh) là xương sống kinh tế Trung Quốc thời phong kiến, đặc biệt triều Tống đến Thanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vận tải đường thuỷ", "Hạng Tần Suất (Jun Da)": "4359.0", "Tần Suất % (Jun Da)": "99.8334949303", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漕", "Unihan_Traditional (Chữ Phồn thể)": "漕", "Pinyin_Xie": "cáo", "Âm Hán Việt_Xie": "tào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc vận chuyển lương thực bằng đường thủy hoặc làm danh từ trong các từ ghép lịch sử. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沣', '{"9000": "4360.0", "Chữ Trung Quốc": "沣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 沣 | phong | tượng hình | sông Phong ở Thiểm Tây | 沣 (giản thể của 灃) thuộc bộ 氵(thủy: nước), chỉ tên riêng con sông. Cấu trúc chi tiết không rõ trong CHISE. Không có glyph cổ — chữ chuyên dùng làm địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": bộ 氵(nước) — sông \"Phong\" (Fēng), con sông bên cạnh kinh đô nhà Chu thời Tây Chu — đối xứng với kinh đô Hạo (鎬). | Gương Hán-Việt | phong — thấy trong \"Phong Kinh\" (沣京/丰京: kinh đô nhà Chu) | Mở khoá kiến thức | Biết 沣 giúp đọc lịch sử Tây Chu — kinh đô Phong-Hạo (沣镐: Fēng-Hào) của Văn Vương và Võ Vương.", "Tự nguyên_Xie": "沣 là giản thể của 灃 — sông Phong ở tỉnh Thiểm Tây. Wiktionary ghi: sông Feng chảy ở Thiểm Tây, và tên cổ của kinh đô Phong (豐) nhà Chu. Không có glyph origin cổ chi tiết. Cùng âm fēng với 丰, 风, 封. chưa có nguồn học thuật glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(như: phong thuỷ 灃水,沣水)", "Hạng Tần Suất (Jun Da)": "4360.0", "Tần Suất % (Jun Da)": "99.8336902751", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 丰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵丰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沣", "Unihan_Traditional (Chữ Phồn thể)": "灃", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ tên sông hoặc địa danh cụ thể tại Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栾', '{"9000": "4361.0", "Chữ Trung Quốc": "栾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 栾 | loan | tượng hình | cây loan, tròn xoe | 栾 (giản thể của 欒) là chữ chỉ tên một loài cây và phần kiến trúc của chuông. Cấu trúc chi tiết không rõ trong CHISE. Tiểu triện đã có hình thức 欒.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": cây loan — loài cây hoa vàng đẹp như phượng \"loan\" trong truyền thuyết, tán lá tròn xoe. | Gương Hán-Việt | loan — thấy trong \"loan thụ\" (栾树: cây hoa vàng Koelreuteria) | Mở khoá kiến thức | Biết 栾 giúp nhận dạng họ người 栾 (Loan) và loài cây 栾树 (cây hoa vàng) trong sách thực vật học.", "Tự nguyên_Xie": "Tiểu triện | 栾 là giản thể của 欒. Tiểu triện đã có hình thức 欒. Wiktionary ghi {{Han simp|欒}}. Nghĩa gốc: tên loài cây (Koelreuteria paniculata — cây hoa vàng); cũng chỉ hai góc miệng chuông. Họ Loan (栾) là họ người. chưa có nguồn glyph origin cụ thể ngoài tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây loan; tròn xoe; hai góc miệng chuông", "Hạng Tần Suất (Jun Da)": "4361.0", "Tần Suất % (Jun Da)": "99.8338856199", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栾", "Unihan_Traditional (Chữ Phồn thể)": "欒", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại cây thân gỗ hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榘', '{"9000": "4362.0", "Chữ Trung Quốc": "榘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 榘 | củ | tượng hình | cái khuôn thợ mộc, khuôn phép | 榘 là dị thể của 矩 (củ: cái khuôn/ê-ke). Thuộc bộ 木 (mộc: gỗ) kết hợp phần chỉ hình vuông. Tiểu triện đã có hình thức này. Chữ chuyên ngành thợ mộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củ\": bộ 木 (gỗ) — cái ê-ke gỗ \"củ\" của thợ mộc, dùng để vẽ góc vuông và giữ \"khuôn củ\" ngay ngắn. | Gương Hán-Việt | củ — thấy trong \"quy củ\" (规矩/规榘: khuôn phép, nề nếp) | Mở khoá kiến thức | Biết 榘 mở khoá dạng cổ của 矩 và từ 规矩 (quy củ — khuôn phép) quan trọng trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 榘 là dị thể cổ/phồn thể của 矩. Wiktionary ghi: {{zh-see|矩|v}} — 榘 chỉ là dạng cổ của 矩. Tiểu triện đã thấy. Nghĩa: cái ê-ke (công cụ tạo góc vuông của thợ mộc), mở rộng thành quy tắc/khuôn phép. Thành ngữ 规矩/规榘 (quy củ: khuôn phép, nề nếp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuôn; khuôn phép", "Hạng Tần Suất (Jun Da)": "2155.0", "Tần Suất % (Jun Da)": "97.6551696203", "GavinGrover_Once (Chiết tự trực tiếp)": "矩 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱矩木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "矩", "Unihan_Traditional (Chữ Phồn thể)": "榘", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ dụng cụ đo đạc hoặc ẩn dụ cho quy củ, phép tắc trong đời sống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烷', '{"9000": "4363.0", "Chữ Trung Quốc": "烷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 火 | hoả | biểu nghĩa | lửa | 完 | hoàn | biểu âm | đầy đủ; hoàn chỉnh | 烷 = 火 (Hoả, biểu nghĩa: lửa/nhóm liên quan đến năng lượng) + 完 (Hoàn, biểu âm); chữ hình thanh. Bộ 火 là ký hiệu thông dụng trong hoá học để đặt tên các hợp chất hydrocarbon.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": ghi nhớ bằng cấu trúc: 火 (lửa/năng lượng) + 完 (hoàn toàn bão hoà) = ankan, loại hydrocarbon bão hoà hoàn toàn, không có liên kết đôi. | Gương Hán-Việt | Chữ thuần hoá học, không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 烷 giúp nhận diện các tên hydrocarbon trong hoá học: 甲烷 (methane), 乙烷 (ethane), 丙烷 (propane).", "Tự nguyên_Xie": "Chữ hình thanh: 火 (hoả) biểu ý liên quan đến năng lượng/đốt cháy — đây là bộ thủ quy ước trong tiếng Trung để đặt tên các hợp chất hydrocarbon — và 完 (hoàn, âm wán) biểu âm cho chữ 烷 (wán). Chữ tạo muộn, dùng cho thuật ngữ hoá học hiện đại chỉ các chất ankan (CnH2n+2). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các chất alkan (công thức hoá học: CnH2n+2)", "Hạng Tần Suất (Jun Da)": "4363.0", "Tần Suất % (Jun Da)": "99.8342763094", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烷", "Unihan_Traditional (Chữ Phồn thể)": "烷", "Pinyin_Xie": "wán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học hữu cơ để chỉ nhóm hợp chất hydrocacbon no. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榷', '{"9000": "4364.0", "Chữ Trung Quốc": "榷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 榷 | 榷 | tượng hình | cầu độc mộc; độc quyền; đánh thuế | 榷 là chữ độc thể, không có phân tích hình thanh/hội ý rõ ràng trong Wiktionary. Bộ 木 (mộc) gợi ý liên quan đến gỗ — nguyên nghĩa là cầu gỗ độc mộc, sau mở rộng sang nghĩa độc quyền, đánh thuế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"榷\" — hình dung một cây cầu gỗ độc đạo (bộ 木): ai qua cầu phải nộp thuế — đó là độc quyền (榷). | Gương Hán-Việt | 商榷 (thương lượng, bàn bạc) — chữ 榷 còn giữ nghĩa bàn luận trong từ này. | Mở khoá kiến thức | Biết 榷 mở khoá 商榷 (bàn bạc, thương thảo) — từ vẫn dùng trong văn viết trang trọng tiếng Trung hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích thành phần. Từ ngữ cảnh lịch sử: 榷 nguyên chỉ cầu gỗ một tấm ván (cầu độc mộc), nghĩa bắc qua sông hẹp. Về sau dùng theo nghĩa bóng: nắm độc quyền (như chỉ có một con đường), rồi chỉ việc nhà nước độc quyền thu thuế hàng hoá (muối, rượu, trà). Chữ tạo muộn, chưa thấy glyph cổ đáng tin. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầu độc mộc; giữ độc quyền; đánh thuế", "Hạng Tần Suất (Jun Da)": "4364.0", "Tần Suất % (Jun Da)": "99.8344701039", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 隺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木隺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榷", "Unihan_Traditional (Chữ Phồn thể)": "榷", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "các", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ với nghĩa thương lượng, bàn bạc hoặc làm danh từ chỉ sự độc quyền thương mại thời phong kiến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俑', '{"9000": "4365.0", "Chữ Trung Quốc": "俑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 人 | nhân | biểu nghĩa | người | 用 | dụng | biểu âm | dùng | 俑 = 亻(Nhân, biểu nghĩa: người) + 用 (Dụng, biểu âm); chữ hình thanh. Bộ nhân 亻 chỉ hình người — đây là tượng người bằng gỗ/đất nung chôn theo người chết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dõng\": 亻(người) + 用 (dùng) = con người được \"dùng\" trong mộ chí — tượng hầu cận chôn theo người chết (俑). | Gương Hán-Việt | 兵馬俑 (binh mã dõng) — tượng binh lính và ngựa nung đất của Tần Thủy Hoàng. | Mở khoá kiến thức | Biết 俑 giúp đọc 兵馬俑 (bīngmǎyǒng) — tượng đất nung nổi tiếng nhất thế giới của Trung Quốc cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 人 (nhân, bộ biểu nghĩa chỉ người) + 用 (dụng, biểu âm). Chữ 俑 chỉ tượng gỗ hoặc đất nung hình người, dùng chôn theo người chết trong mộ táng. Wiktionary ghi rõ cấu trúc psc với 人 là phần biểu nghĩa và 用 là phần biểu âm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tượng gỗ", "Hạng Tần Suất (Jun Da)": "4365.0", "Tần Suất % (Jun Da)": "99.8346638983", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俑", "Unihan_Traditional (Chữ Phồn thể)": "俑", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng sau các từ chỉ chất liệu hoặc loại tượng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沱', '{"9000": "4366.0", "Chữ Trung Quốc": "沱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 水 | thủy | biểu nghĩa | nước | 它 | tha | biểu âm | 沱 = 氵(Thủy, biểu nghĩa: nước) + 它 (Tha, biểu âm); chữ hình thanh. Bộ thủy 氵 chỉ liên quan đến sông nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": 氵(nước) + 它 (tha — con rắn, uốn lượn) = dòng sông uốn khúc như rắn bò (沱). | Gương Hán-Việt | 涕泗滂沱 (thế tứ bàng đà) — nước mắt chảy tràn như sông lũ. | Mở khoá kiến thức | Biết 沱 giúp đọc thành ngữ 涕泗滂沱 (khóc sướt mướt) và địa danh 沱江 (sông Đà Giang ở Tứ Xuyên).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Chữ hình thanh: 水/氵 (thủy) biểu nghĩa — liên quan đến sông nước — và 它 (tha, âm tuó) biểu âm. Wiktionary xác nhận cấu trúc này. 沱 chỉ sông nhánh, nhánh sông, hoặc dòng chảy nhỏ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông nhánh", "Hạng Tần Suất (Jun Da)": "4366.0", "Tần Suất % (Jun Da)": "99.8348576927", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沱", "Unihan_Traditional (Chữ Phồn thể)": "沱", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng chỉ tên sông hoặc làm tính từ mô tả nước mắt rơi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缜', '{"9000": "4367.0", "Chữ Trung Quốc": "缜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 纟 | mịch | biểu nghĩa | tơ sợi | 真 | chân | biểu âm | thật; chân thật | 缜 là dạng giản thể của 縝. Hình thanh: 纟(mịch, biểu nghĩa: sợi tơ/dệt) + 真 (chân, biểu âm zhěn≈zhēn). Bộ mịch gợi ý chất vải dệt chặt chẽ, mịn màng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chân\": ghi nhớ: 纟(sợi) + 真 (chân thật, kỹ càng) = dệt kỹ, kín đáo, tỉ mỉ (缜密). | Gương Hán-Việt | 缜密 (zhěnmì) — tỉ mỉ, chặt chẽ; từ hay dùng trong văn viết trang trọng. | Mở khoá kiến thức | Biết 缜 mở khoá 缜密 (zhěnmì — tỉ mỉ, chu đáo) — từ thường dùng khi nhận xét tư duy logic hoặc kế hoạch kỹ lưỡng.", "Tự nguyên_Xie": "缜 là dạng giản thể của 縝 (糹→纟). Wiktionary dẫn {{Han simp}} không có phân tích nguồn gốc chi tiết hơn. Từ cấu trúc: 糹(sợi tơ) + 真 biểu âm, 縝 chỉ vải dệt mịn, kín; nghĩa mở rộng sang 縝密 (kỹ lưỡng, chặt chẽ). chưa có nguồn học thuật đầy đủ cho dạng 縝. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kín đáo, bền bỉ", "Hạng Tần Suất (Jun Da)": "4367.0", "Tần Suất % (Jun Da)": "99.8350514871", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缜", "Unihan_Traditional (Chữ Phồn thể)": "縝", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ trong các từ ghép như chân mật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹫', '{"9000": "4368.0", "Chữ Trung Quốc": "鹫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鹫 | 鹫 | tượng hình | chim kên kên, đại bàng | 鹫 là dạng giản thể của 鷲. Không có phân tích hình thanh/hội ý rõ ràng trong nguồn cổ điển. Bộ 鸟 (điểu) gợi đây là một loài chim lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tựu\": ghi nhớ qua bộ 鸟 (điểu, chim) + hình dáng chữ lớn, nặng nề như thân hình kên kên (鹫). | Gương Hán-Việt | 秃鹫 (tú jiù) — kên kên đầu trọc; linh鹫 (linh jiù) — đại bàng linh thiêng. | Mở khoá kiến thức | Biết 鹫 giúp nhận diện các tên chim săn mồi lớn: 秃鹫 (kên kên), 海鹫 (đại bàng biển), 兀鹫 (kền kền).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary cung cấp phiên âm và định nghĩa nhưng không phân tích cấu trúc nguồn gốc chữ 鷲/鹫. Đây là tên một loài chim săn mồi lớn (kên kên, đại bàng). Glyph cổ kim văn và tiểu triện tồn tại nhưng Wiktionary không giải thích thành phần. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim kên kên", "Hạng Tần Suất (Jun Da)": "4368.0", "Tần Suất % (Jun Da)": "99.8352452816", "GavinGrover_Once (Chiết tự trực tiếp)": "就 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱就鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "就", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹫", "Unihan_Traditional (Chữ Phồn thể)": "鷲", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "thứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp trong các từ chỉ loài chim săn mồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛳', '{"9000": "4369.0", "Chữ Trung Quốc": "蛳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛳 | 蛳 | tượng hình | loài ốc xoắn | 蛳 là dạng giản thể của 螄. Không có phân tích hình thanh/hội ý rõ ràng. Bộ 虫 (trùng) gợi đây là loài động vật nhỏ; chữ chủ yếu dùng trong từ ghép 螺蛳 (ốc xoắn nhỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": ghi nhớ: bộ 虫 (con trùng) + âm sī = 螺蛳 (con ốc xoắn nhỏ), món ăn nổi tiếng ở Quảng Tây (螺蛳粉). | Gương Hán-Việt | 螺蛳粉 (luósīfěn) — bún ốc nổi tiếng của Liễu Châu, Quảng Tây. | Mở khoá kiến thức | Biết 蛳 giúp nhận diện 螺蛳粉 (bún ốc Liễu Châu) — món ăn viral toàn cầu từ Trung Quốc.", "Tự nguyên_Xie": "Wiktionary cung cấp phiên âm cho 螄 nhưng không phân tích cấu trúc nguồn gốc. 蛳 (螄) chỉ xuất hiện trong từ ghép 螺蛳 — loài ốc nhỏ hình xoắn, phổ biến trong ẩm thực miền Nam Trung Quốc. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: loa si 螺螄,螺蛳)", "Hạng Tần Suất (Jun Da)": "4369.0", "Tần Suất % (Jun Da)": "99.8354385592", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 师", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫师", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "师", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛳", "Unihan_Traditional (Chữ Phồn thể)": "螄", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các chữ khác để tạo thành danh từ chỉ loài ốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剽', '{"9000": "4370.0", "Chữ Trung Quốc": "剽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 13 | nét | 剽 | 剽 | tượng hình | cướp bóc; nhanh nhẹn | 剽 không có phân tích hình thanh/hội ý từ Wiktionary. Nhìn cấu trúc: bộ 刀/刂 (đao) ở bên phải gợi liên quan đến dao, sắc bén, bạo lực; phần bên trái (票 biến thể) có thể là biểu âm. Nguyên nghĩa: dùng dao cướp giật, sau mở rộng sang cướp bóc/đạo văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": ghi nhớ: bộ 刂(dao) + 票 (bay vút) = kẻ cướp nhanh như tên bay, vung dao cướp đoạt (剽窃 = đạo văn). | Gương Hán-Việt | 剽窃 (piāoqiè) — đạo văn, đánh cắp chất xám người khác. | Mở khoá kiến thức | Biết 剽 mở khoá 剽窃 (đạo văn/plagiarism) và 剽悍 (dũng mãnh, hung hãn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích {{Han compound}} cho 剽. Từ cấu trúc quan sát: phần phải là 刂 (đao), phần trái gần với 票 (piào) là biểu âm khả năng cao — tạo chữ hình thanh không được ghi rõ. Nghĩa: lanh lẹ, dũng mãnh; cướp đoạt; đâm; đạo văn. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cướp bóc; nhanh nhẹn", "Hạng Tần Suất (Jun Da)": "4370.0", "Tần Suất % (Jun Da)": "99.8356313201", "GavinGrover_Once (Chiết tự trực tiếp)": "票 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰票刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剽", "Unihan_Traditional (Chữ Phồn thể)": "剽", "Pinyin_Xie": "piāo", "Âm Hán Việt_Xie": "phiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ trong các từ ghép như phiêu thiết hoặc làm tính từ chỉ sự nhanh nhẹn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衢', '{"9000": "4371.0", "Chữ Trung Quốc": "衢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 24 | nét | 行 | hàng | biểu nghĩa | đường đi; di chuyển | 瞿 | biểu âm | 衢 = 行 (Hàng, biểu nghĩa: đường xá, di chuyển) + 瞿 (biểu âm, âm qú); chữ hình thanh. Bộ hành 行 (bao quanh hai bên) chỉ con đường rộng lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cù\": ghi nhớ: bộ 行 (đường đi) bao quanh 瞿 (mắt đảo ngơ ngác tại ngã tư) = con đường rộng lớn nhiều hướng (衢). | Gương Hán-Việt | 通衢大道 (thông cù đại đạo) — đại lộ thông thương, đường cái lớn. | Mở khoá kiến thức | Biết 衢 giúp đọc địa danh 衢州 (Cù Châu) và các thành ngữ về đường lớn như 通衢大道, 大庭广衢.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 行 (hàng, biểu nghĩa: đường đi) bao quanh bên ngoài + 瞿 (biểu âm, âm qú). Wiktionary xác nhận cấu trúc psc. 衢 chỉ đường lớn, ngã tư, giao lộ quan trọng. Dùng nhiều trong tên địa danh như 衢州 (Cù Châu, Chiết Giang). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã tư", "Hạng Tần Suất (Jun Da)": "4371.0", "Tần Suất % (Jun Da)": "99.8358240809", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 瞿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行瞿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衢", "Unihan_Traditional (Chữ Phồn thể)": "衢", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ đường sá hoặc địa danh trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泗', '{"9000": "4372.0", "Chữ Trung Quốc": "泗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | biểu nghĩa | nước | 四 | tứ | biểu âm | bốn | 泗 = 氵(Thủy, biểu nghĩa: nước) + 四 (Tứ, biểu âm, âm sì); chữ hình thanh. Bộ thủy chỉ liên quan đến nước chảy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứa\": 氵(nước) + 四 (tứ — bốn) = nước chảy từ bốn phía mặt (mắt + mũi khi khóc), tức 涕泗. | Gương Hán-Việt | 涕泗横流 (thế tứa hoành lưu) — nước mắt nước mũi chảy tràn, khóc nức nở. | Mở khoá kiến thức | Biết 泗 giúp đọc 涕泗 (nước mắt lẫn nước mũi) trong thơ văn cổ điển và địa danh 泗水 (Tứ Thủy — quê hương Khổng Tử).", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 氵(thủy) biểu nghĩa — liên quan đến nước — và 四 (tứ, âm sì) biểu âm. Wiktionary xác nhận cấu trúc psc. 泗 có hai nghĩa: (1) nước mũi (từ cổ điển, dùng trong 涕泗 — nước mắt và nước mũi); (2) tên sông Tứ ở Sơn Đông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mũi; sông Tứ", "Hạng Tần Suất (Jun Da)": "4372.0", "Tần Suất % (Jun Da)": "99.8360168418", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 四", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵四", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "四", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泗", "Unihan_Traditional (Chữ Phồn thể)": "泗", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết cổ để chỉ nước mắt nước mũi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臊', '{"9000": "4373.0", "Chữ Trung Quốc": "臊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 肉 | nhục | biểu nghĩa | thịt, xác thịt | 喿 | biểu âm | 臊 = 月/肉 (Nhục, biểu nghĩa: thịt/mùi thịt) + 喿 (biểu âm, âm sāo); chữ hình thanh. Bộ nhục gợi ý mùi hôi tanh của thịt thiu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": ghi nhớ: 月/肉 (thịt) + 喿 (tiếng ồn ào xao xác) = mùi thịt tanh xộc lên, khiến người ta đỏ mặt thẹn thùng (害臊). | Gương Hán-Việt | 害臊 (hài sāo) — biết xấu hổ, ngại ngùng; 猪臊 (thịt heo mùi hôi). | Mở khoá kiến thức | Biết 臊 mở khoá 害臊 (ngại, thẹn — phương ngữ Bắc Kinh) và các từ mô tả mùi hôi thối trong ẩm thực Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 肉 (nhục, biểu nghĩa: thịt) + 喿 (biểu âm, âm sāo). Wiktionary xác nhận cấu trúc psc. 臊 có hai nghĩa chính: (1) mùi tanh hôi của thịt/cơ thể; (2) ngại ngùng, thẹn thùng (phương ngữ Bắc Kinh). Ví dụ 猪臊 (mùi thịt lợn hôi), 害臊 (biết thẹn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thẹn đỏ mặt", "Hạng Tần Suất (Jun Da)": "4373.0", "Tần Suất % (Jun Da)": "99.8362090858", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臊", "Unihan_Traditional (Chữ Phồn thể)": "臊", "Pinyin_Xie": "sāo", "Âm Hán Việt_Xie": "tao, táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ biểu thị trạng thái xấu hổ hoặc làm động từ gây bẽ mặt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘴', '{"9000": "4374.0", "Chữ Trung Quốc": "瘴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 疒 | biểu nghĩa | bệnh tật | 章 | chuong | biểu âm | 瘴 = 疒 (biểu nghĩa: bệnh tật) + 章 (Chương, biểu âm, âm zhàng≈zhāng); chữ hình thanh. Bộ 疒 là bộ thủ chỉ bệnh tật, thường thấy trong tên các bệnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chướng\": 疒 (bệnh) + 章 (chương — mạch lạc) = cái bệnh ngăn chặn \"mạch lạc\" của khí trời, tức khí độc chướng ngại (瘴气). | Gương Hán-Việt | 瘴气 (chướng khí) — khí độc rừng núi, khí trướng ngại gây bệnh. | Mở khoá kiến thức | Biết 瘴 mở khoá 瘴气 (khí độc), 烟瘴 (khói độc), 瘴疫 (dịch bệnh từ khí độc) — từ vựng y học cổ và miêu tả khí hậu rừng nhiệt đới.", "Tự nguyên_Xie": "Chữ hình thanh: 疒 (biểu nghĩa: bệnh tật) + 章 (chương, biểu âm, âm zhāng gần với zhàng). Wiktionary xác nhận cấu trúc psc. 瘴 chỉ khí độc bốc lên từ đầm lầy và rừng rậm nhiệt đới — nguyên nhân gây sốt rét và bệnh theo quan niệm cổ. Thường dùng trong 瘴气 (khí độc rừng núi), 烟瘴 (khói và khí độc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí độc (ở rừng núi)", "Hạng Tần Suất (Jun Da)": "4374.0", "Tần Suất % (Jun Da)": "99.8364008131", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘴", "Unihan_Traditional (Chữ Phồn thể)": "瘴", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "chướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ khác để chỉ khí độc như chướng khí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酚', '{"9000": "4375.0", "Chữ Trung Quốc": "酚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 11 | nét | 酉 | dấu | biểu nghĩa | nhóm chức oxi hoá (hoá học) | 分 | phân | biểu âm | chia tách | 酚 = 酉 (Dấu, biểu nghĩa: bộ thủ quy ước cho các hợp chất hữu cơ có oxi) + 分 (Phân, biểu âm, âm fēn); chữ hình thanh. Bộ 酉 là bộ thủ quy ước trong hoá học để đặt tên các nhóm chức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": ghi nhớ: 酉 (nhóm chức hữu cơ) + 分 (phân — âm fēn) = phenol (phê-nol), hợp chất quan trọng trong hoá hữu cơ. | Gương Hán-Việt | Chữ thuần hoá học, không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 酚 giúp nhận diện 苯酚 (phenol), 甲酚 (cresol), 酚类化合物 (hợp chất phenolic) trong hoá học hữu cơ.", "Tự nguyên_Xie": "Chữ hình thanh: 酉 (dấu, biểu nghĩa: nhóm chức oxi hoá — quy ước hoá học) + 分 (phân, âm fēn, biểu âm). Wiktionary xác nhận cấu trúc psc. 酚 là thuật ngữ hoá học hiện đại chỉ phenol (C6H5OH), hợp chất hữu cơ có nhóm hydroxyl (-OH) gắn vào vòng benzene. Chữ tạo sau khi tiếp thu hoá học phương Tây. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phenol (hoá học)", "Hạng Tần Suất (Jun Da)": "4375.0", "Tần Suất % (Jun Da)": "99.8365920236", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酚", "Unihan_Traditional (Chữ Phồn thể)": "酚", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chuyên ngành hóa học đứng độc lập hoặc trong tên hợp chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纾', '{"9000": "4376.0", "Chữ Trung Quốc": "纾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纾 | 纾 | tượng hình | giải gỡ; nới lỏng | 纾 là dạng giản thể của 紓. Bộ 纟(mịch, sợi tơ) gợi hình ảnh tháo gỡ sợi dây ràng buộc — giải thoát, nới lỏng. Wiktionary không cung cấp phân tích thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": ghi nhớ: 纟(sợi tơ bị cuốn chặt) = hành động tháo gỡ, nới lỏng, giải toả (纾困 = giải cứu khó khăn). | Gương Hán-Việt | 纾困 (shūkùn) — giải cứu khó khăn, tháo gỡ ràng buộc; 纾解 (shūjiě) — làm dịu, giảm bớt. | Mở khoá kiến thức | Biết 纾 mở khoá 纾困 (giải cứu khó khăn) và 纾解 (giải toả căng thẳng) — từ hay dùng trong văn kinh tế, chính sách.", "Tự nguyên_Xie": "Tiểu triện | 纾 là dạng giản thể của 紓. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Từ cấu trúc: bộ 糹/纟 (sợi tơ) + phần biểu âm, gợi ý nghĩa tháo gỡ ràng buộc. 纾 nghĩa là giải gỡ, làm dịu, nới lỏng, hoãn giải quyết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giải, gỡ; hoãn lại", "Hạng Tần Suất (Jun Da)": "4376.0", "Tần Suất % (Jun Da)": "99.8367832341", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 予", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟予", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "予", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纾", "Unihan_Traditional (Chữ Phồn thể)": "紓", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ sự khó khăn để biểu thị việc giảm nhẹ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晁', '{"9000": "4377.0", "Chữ Trung Quốc": "晁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 日 | nhật | biểu nghĩa | mặt trời; ngày | 兆 | trieu | biểu âm | điềm báo; triệu | 晁 = 日 (Nhật, biểu nghĩa: mặt trời) + 兆 (Triệu, biểu âm, âm zhào≈cháo); chữ hình thanh. Bộ nhật gợi liên quan đến ban mai, bình minh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triều\": ghi nhớ: 日 (mặt trời) + 兆 (triệu — điềm báo) = mặt trời ló dạng như điềm báo buổi sáng — 晁 nguyên nghĩa là bình minh; nay dùng làm họ tên. | Gương Hán-Việt | 晁盖 (Trào Cái) — anh hùng nổi tiếng trong Thủy Hử, thủ lĩnh đầu tiên của 梁山. | Mở khoá kiến thức | Biết 晁 giúp nhận ra 晁盖 trong Thủy Hử và họ 晁 (họ Trào) trong văn học cổ điển Trung Quốc.", "Tự nguyên_Xie": "Chữ hình thanh: 日 (nhật, biểu nghĩa: mặt trời) + 兆 (triệu, biểu âm, âm zhào gần cháo). Wiktionary ghi 晁 xuất hiện như dạng biến thể của 鼂 — một chữ cổ chỉ buổi sáng sớm. Nay 晁 chủ yếu dùng làm họ (họ Trào). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Trào", "Hạng Tần Suất (Jun Da)": "4377.0", "Tần Suất % (Jun Da)": "99.8369744446", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晁", "Unihan_Traditional (Chữ Phồn thể)": "晁", "Pinyin_Xie": "cháo", "Âm Hán Việt_Xie": "triều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm họ của người hoặc xuất hiện trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孛', '{"9000": "4378.0", "Chữ Trung Quốc": "孛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 7 | nét | 𣎵 | sự tăng trưởng, nảy mầm | 子 | tử | đứa trẻ; con | 孛 = 𣎵 (ký hiệu cổ chỉ sự tăng trưởng, nảy mầm) + 子 (Tử: đứa trẻ); chữ hội ý. Hình ảnh: đứa trẻ đang lớn mạnh, tràn đầy sinh khí — nguyên nghĩa là bừng bừng sinh lực, mạnh mẽ. Sau dùng riêng để chỉ sao chổi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bụt\": 𣎵(tăng trưởng) + 子 (tử: đứa trẻ) = đứa trẻ bùng phát sinh lực mạnh mẽ — rồi dùng cho sao chổi phóng nhanh như tia sáng (孛). | Gương Hán-Việt | 孛星 (bột tinh) — sao chổi; 悖 (bội/bụt) cùng gốc âm, nghĩa trái ngược/lầm lẫn. | Mở khoá kiến thức | Biết 孛 giúp nhận dạng 孛星 (sao chổi trong thiên văn cổ) và hiểu họ hàng chữ: 勃 (bột — bùng phát), 悖 (bội — trái lẽ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Chữ hội ý: 𣎵 (biểu thị sự tăng trưởng) + 子 (tử: đứa trẻ) — ý nghĩa gốc: phát triển mạnh mẽ, tràn đầy sức sống. Wiktionary ghi 孛 là dạng gốc của 勃 (bột: bùng phát, tràn trề). Glyph giáp cốt văn và kim văn đã được ghi nhận. Sau dùng để chỉ sao chổi (tiếng Trung cổ gọi sao chổi là 孛星 hay 彗孛). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1765.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thập (024) Mịch (014) Tử (039)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thập (số 024 - số mười/ 十), ở giữa là bộ Mịch (số 014 - che trùm/ 冖) và bên dưới là chữ Tử (số 039 - đứa trẻ/ 子). Giải thích sự chuyển ý: Bột là từ để chỉ sắc mặt đột nhiên biến sắc, hoặc cây cỏ đâm chồi này nảy lộc. Nghĩa cổ chỉ ngôi sao chổi có luồng khí bao quanh.", "Nghĩa Tiếng Việt_Xie": "sao chổi; bừng mặt", "Hạng Tần Suất (Jun Da)": "4378.0", "Tần Suất % (Jun Da)": "99.8371646216", "GavinGrover_Once (Chiết tự trực tiếp)": "十 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "孛", "Unihan_Traditional (Chữ Phồn thể)": "孛", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ sao chổi hoặc tính từ mô tả sắc mặt thay đổi đột ngột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炀', '{"9000": "4379.0", "Chữ Trung Quốc": "炀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 7 | nét | 炀 | 炀 | tượng hình | nấu chảy; rang; ngọn lửa | 炀 là dạng giản thể của 煬. Bộ 火 (hoả) gợi liên quan đến lửa và sức nóng. Wiktionary không cung cấp phân tích chi tiết hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dạng\": ghi nhớ: bộ 火 (lửa) + âm yáng = 隋炀帝 (Tùy Dạng Đế), ông vua Tùy triều như \"lửa đốt\" cả thiên hạ. | Gương Hán-Việt | 隋炀帝 (Tùy Dạng Đế) — Tùy Dương Đế, vua cuối nhà Tùy, người xây Đại Vận Hà. | Mở khoá kiến thức | Biết 炀 giúp nhận diện 隋炀帝 trong lịch sử Trung Quốc — vị vua nổi tiếng vừa xây Đại Vận Hà vừa là nguyên nhân diệt vong của nhà Tùy.", "Tự nguyên_Xie": "Tiểu triện | 炀 là dạng giản thể của 煬 (炀→煬 với phần 昜→𠃓 đơn giản hoá). Wiktionary dẫn {{Han simp}} không phân tích nguồn gốc. 煬 nghĩa: rang/nướng cháy; lửa ngập tràn; nung chảy kim loại. Nổi tiếng qua miếu hiệu 隋炀帝 (Tùy Dạng Đế — Tùy Dương Đế) — vị vua cuối Tùy triều bị coi là bạo quân. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu chảy", "Hạng Tần Suất (Jun Da)": "4379.0", "Tần Suất % (Jun Da)": "99.8373547985", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炀", "Unihan_Traditional (Chữ Phồn thể)": "煬", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết để chỉ việc nung chảy kim loại hoặc sưởi ấm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叁', '{"9000": "4380.0", "Chữ Trung Quốc": "叁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厶 | Số nét | 8 | nét | 叁 | 叁 | tượng hình | ba (dạng kế toán chống gian lận) | 叁 là dạng kế toán (大寫/đại tả) của 三, dùng trên văn kiện tài chính để chống sửa số. Không có phân tích hình thanh/hội ý rõ ràng — Wiktionary ghi {{rfe|zh}} (cần nghiên cứu thêm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tam\": ghi nhớ: 叁 là chữ số \"ba\" dùng trong hợp đồng, hoá đơn ngân hàng — khi thấy 叁 trên văn kiện tài chính Trung Quốc, đọc là ba (3). | Gương Hán-Việt | 叁 cặp với 三 (tam/ba) — giống như tiếng Việt dùng \"BẢY\" thay \"7\" trên séc. | Mở khoá kiến thức | Biết 叁 cùng bộ đại tả: 壹(1), 贰(2), 叁(3), 肆(4), 伍(5), 陆(6), 柒(7), 捌(8), 玖(9), 拾(10) — toàn bộ chữ số kế toán Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi {{rfe|zh}} — chưa có giải thích nguồn gốc đáng tin cậy cho 叁 (dạng đại tả của 叄). Đây là chữ số kế toán Trung Hoa dùng trên hoá đơn, hợp đồng, séc để tránh sửa số 三 thành 万 hay 五. Chữ tạo muộn cho mục đích thực tiễn. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ba, 3", "Hạng Tần Suất (Jun Da)": "4380.0", "Tần Suất % (Jun Da)": "99.8375444586", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 三", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱三", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "叁", "Unihan_Traditional (Chữ Phồn thể)": "叁", "Pinyin_Xie": "sān", "Âm Hán Việt_Xie": "tam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Dùng làm số từ trong các văn bản tài chính và ngân hàng để tránh tẩy xóa. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憩', '{"9000": "4381.0", "Chữ Trung Quốc": "憩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 恬 | điềm | yên tĩnh, tĩnh lặng | 息 | tức | nghỉ ngơi; hơi thở | 憩 = 恬 (Điềm, rút gọn, biểu ý: yên tĩnh, tĩnh lặng) + 息 (Tức: nghỉ ngơi, thở); chữ hội ý. Hai thành phần cùng nghĩa nghỉ ngơi, tĩnh lặng — kết hợp tạo chữ chỉ sự nghỉ ngơi hoàn toàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khế\": ghi nhớ: 恬 (điềm — yên lặng) + 息 (tức — thở, nghỉ) = nghỉ ngơi trong yên bình tuyệt đối (憩息, 小憩). | Gương Hán-Việt | 小憩 (tiểu tức) — nghỉ ngơi ngắn, chợt nghỉ một lúc. | Mở khoá kiến thức | Biết 憩 mở khoá 小憩 (nghỉ ngơi ngắn), 憩息 (nghỉ ngơi), 游憩 (giải trí nghỉ dưỡng) — từ vựng trang nhã thường thấy trong văn viết.", "Tự nguyên_Xie": "Chữ hội ý: 恬 (điềm, rút gọn, biểu ý: tĩnh lặng) + 息 (tức: nghỉ ngơi, thở). Wiktionary ghi lại khả năng chữ hội ý này, đồng thời lưu ý 憩 cũng có thể là hình thanh với 𠯑 làm biểu âm. Ý nghĩa tổng hợp: nghỉ ngơi trong yên tĩnh hoàn toàn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghỉ ngơi", "Hạng Tần Suất (Jun Da)": "4381.0", "Tần Suất % (Jun Da)": "99.837733602", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "憩", "Unihan_Traditional (Chữ Phồn thể)": "憇", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "khế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết hoặc kết hợp thành từ ghép để chỉ sự nghỉ ngơi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掬', '{"9000": "4382.0", "Chữ Trung Quốc": "掬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | biểu nghĩa | tay | 匊 | biểu âm | 掬 = 扌(Thủ, biểu nghĩa: tay) + 匊 (biểu âm, âm jū); chữ hình thanh. Bộ thủ 扌 chỉ hành động dùng tay — cụ thể là khum hai tay lại để nắm giữ hay vốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\": 扌(tay) + 匊 (vốc đầy) = khum hai bàn tay vốc nước hay cầm vật nhỏ (掬), như khi 笑容可掬 — nụ cười rạng rỡ tràn đầy. | Gương Hán-Việt | 笑容可掬 (tiếu dung khả cúc) — nụ cười tươi rói, rạng rỡ (như thể vốc được bằng tay). | Mở khoá kiến thức | Biết 掬 mở khoá 笑容可掬 — thành ngữ hay dùng khi tả người nở nụ cười rạng rỡ, thân thiện.", "Tự nguyên_Xie": "Chữ hình thanh: 扌(thủ, biểu nghĩa: tay) + 匊 (biểu âm, âm jū). Wiktionary xác nhận cấu trúc psc. 掬 nghĩa là khum hai tay lại nắm giữ hay vốc lấy vật gì — thường thấy trong 笑容可掬 (nụ cười tươi rói). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắm đồ vật trong tay", "Hạng Tần Suất (Jun Da)": "4382.0", "Tần Suất % (Jun Da)": "99.8379222286", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掬", "Unihan_Traditional (Chữ Phồn thể)": "掬", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ hành động vốc nước hoặc làm lượng từ chỉ lượng chứa trong hai bàn tay khum lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椤', '{"9000": "4383.0", "Chữ Trung Quốc": "椤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 椤 | 椤 | tượng hình | cây sa la (桫椤) | 椤 là dạng giản thể của 欏. Bộ 木 (mộc) gợi đây là một loài cây. Wiktionary chỉ ghi nhận chữ này trong từ ghép 桫欏 (sa la).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": ghi nhớ: 木 (cây) + 椤 = 桫椤 (cây dương xỉ khổng lồ thời khủng long — hóa thạch sống). | Gương Hán-Việt | 桫椤 (sa la) — cây dương xỉ thân gỗ, hóa thạch sống từ kỷ Jura. | Mở khoá kiến thức | Biết 椤 giúp nhận diện 桫椤 — cây dương xỉ thân gỗ cao, loài thực vật bảo tồn quý hiếm ở Trung Quốc và Việt Nam.", "Tự nguyên_Xie": "Wiktionary không phân tích nguồn gốc cấu trúc của 欏/椤. Chữ này chỉ xuất hiện trong từ ghép 桫椤/桫欏 — tên cây dương xỉ khổng lồ (tree fern), loài thực vật cổ đại còn sống sót từ kỷ Jura. Chữ tạo muộn. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sa la 桫欏,桫椤)", "Hạng Tần Suất (Jun Da)": "4383.0", "Tần Suất % (Jun Da)": "99.8381108551", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 罗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木罗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椤", "Unihan_Traditional (Chữ Phồn thể)": "欏", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên các loại cây, phổ biến nhất là cây sa la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啮', '{"9000": "4384.0", "Chữ Trung Quốc": "啮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啮 | 啮 | tượng hình | cắn đứt; gặm nhấm | 啮 là dạng giản thể của 齧. Bộ 口 (khẩu) gợi động tác miệng — cắn, gặm. Chữ gốc 齧 có bộ 齒 (xỉ: răng) rõ hơn về ý nghĩa. Wiktionary không cung cấp phân tích hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\": ghi nhớ: dạng gốc 齧 có bộ 齒 (răng) — đây là hành động răng cắn vào, gặm nhấm (啮齿动物 = động vật gặm nhấm). | Gương Hán-Việt | 啮齿动物 (niè chǐ dòng wù) — động vật gặm nhấm (chuột, sóc...). | Mở khoá kiến thức | Biết 啮 mở khoá 啮齿动物 (bộ gặm nhấm trong phân loại sinh học) và từ 啮合 (ăn khớp — kỹ thuật cơ khí).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 啮 là dạng giản thể của 齧 (齒→啮 — đơn giản hoá bộ 齒 thành 口). Wiktionary chỉ ghi {{Han etym}} không phân tích chi tiết. 齧 nguyên nghĩa: cắn, gặm bằng răng — liên quan đến động vật gặm nhấm và sự ăn mòn. Glyph tiểu triện và lục thư thông tồn tại nhưng không có giải thích nguồn gốc trong Wiktionary. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn đứt; ăn mòn", "Hạng Tần Suất (Jun Da)": "4384.0", "Tần Suất % (Jun Da)": "99.8382989649", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 齿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口齿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啮", "Unihan_Traditional (Chữ Phồn thể)": "嚙", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niết, khiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động gặm nhấm của động vật hoặc sự xói mòn của tự nhiên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畿', '{"9000": "4385.0", "Chữ Trung Quốc": "畿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 15 | nét | 田 | điền | biểu nghĩa | ruộng đất | 幾 | biểu âm | 畿 = 田 (Điền, biểu nghĩa: ruộng đất, lãnh thổ) + 幾 (biểu âm, rút gọn, âm jī); chữ hình thanh. Bộ điền 田 gợi ý đất đai xung quanh kinh đô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": ghi nhớ: 田 (ruộng đất) + 幾 (âm jī) = vùng ruộng đất vây quanh kinh đô (京畿 — khu vực thủ đô). | Gương Hán-Việt | 京畿 (kinh kỳ) — vùng thủ đô và phụ cận; trong lịch sử Việt Nam 京畿 chỉ vùng Thăng Long. | Mở khoá kiến thức | Biết 畿 mở khoá 京畿 (kinh kỳ — vùng thủ đô), 畿辅 (kỳ phụ — các huyện quanh kinh đô), 近畿 (cận kỳ — vùng Osaka-Kyoto ở Nhật Bản).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 田 (điền, biểu nghĩa: ruộng/lãnh thổ) + 幾 (rút gọn, biểu âm, âm jī). Wiktionary xác nhận cấu trúc psc. 畿 chỉ vùng đất xung quanh kinh đô, khu vực do thiên tử trực tiếp quản lý — trái với các vùng phong kiến bên ngoài. 京畿 (kinh kỳ) là từ ghép thông dụng nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ven đô; ngoại ô", "Hạng Tần Suất (Jun Da)": "4385.0", "Tần Suất % (Jun Da)": "99.8384870747", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "畿", "Unihan_Traditional (Chữ Phồn thể)": "畿", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn cổ để chỉ vùng đất trực thuộc sự quản lý của hoàng đế quanh kinh thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掸', '{"9000": "4386.0", "Chữ Trung Quốc": "掸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 掸 | 掸 | tượng hình | phủi bụi; dặn dò | 掸 là dạng giản thể của 撣. Bộ 扌(thủ) gợi hành động dùng tay phủi, quét. Wiktionary không cung cấp phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàn\": ghi nhớ: 扌(tay) + phần biểu âm = hành động vẩy tay phủi nhẹ bụi (掸灰尘 = phủi bụi). | Gương Hán-Việt | 掸灰尘 (dǎn huīchén) — phủi bụi; 掸子 (dǎnzi) — cái chổi lông phủi bụi. | Mở khoá kiến thức | Biết 掸 mở khoá 掸灰尘 (phủi bụi), 掸子 (chổi lông phủi bụi) — từ vựng thực dụng trong nhà bếp, dọn dẹp.", "Tự nguyên_Xie": "掸 là dạng giản thể của 撣. Wiktionary chỉ ghi {{Han etym}} không phân tích chi tiết. Có hai nghĩa chính: (1) phủi bụi, quét nhẹ (dùng chổi lông hay khăn); (2) tên gọi người Shan ở Myanmar — dân tộc Đức Ngang/Thái. Nghĩa thứ nhất phổ biến hơn trong cuộc sống hàng ngày. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răn bảo, dặn dò; phẩy, quét, phủi; nâng giữ", "Hạng Tần Suất (Jun Da)": "4386.0", "Tần Suất % (Jun Da)": "99.8386746677", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掸", "Unihan_Traditional (Chữ Phồn thể)": "撣", "Pinyin_Xie": "dǎn", "Âm Hán Việt_Xie": "đàn, đạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động phủi bụi hoặc danh từ chỉ dụng cụ quét bụi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镣', '{"9000": "4387.0", "Chữ Trung Quốc": "镣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 镣 | 镣 | tượng hình | cùm sắt, xích tay/chân | 镣 là dạng giản thể của 鐐. Bộ 钅(kim) gợi đây là vật bằng kim loại — cụ thể là cùm/xích sắt khoá tay chân tù nhân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": ghi nhớ: 钅(kim loại) = 镣铐 (cùm và khoá sắt) — bộ xích trói buộc tù nhân. | Gương Hán-Việt | 镣铐 (liào kào) — cùm và khoá, xiềng xích giam cầm. | Mở khoá kiến thức | Biết 镣 mở khoá 镣铐 (xiềng xích, cùm khoá) — thường dùng theo nghĩa bóng: 冲破镣铐 (phá bỏ xiềng xích — tự do).", "Tự nguyên_Xie": "Tiểu triện | 镣 là dạng giản thể của 鐐 (金→钅). Wiktionary dẫn {{Han simp}} không phân tích nguồn gốc chi tiết. 鐐 chỉ cùm sắt, xích chân tù nhân. Glyph tiểu triện tồn tại nhưng không có giải thích cấu trúc trong Wiktionary. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khoá sắt", "Hạng Tần Suất (Jun Da)": "4387.0", "Tần Suất % (Jun Da)": "99.8388622607", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镣", "Unihan_Traditional (Chữ Phồn thể)": "鐐", "Pinyin_Xie": "liào", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại xiềng xích, cùm chân bằng sắt thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骁', '{"9000": "4388.0", "Chữ Trung Quốc": "骁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 骁 | 骁 | tượng hình | ngựa khoẻ, dũng mãnh | 骁 là dạng giản thể của 驍. Bộ 马 (mã) gợi đây liên quan đến ngựa — cụ thể là ngựa khoẻ mạnh, xuất sắc; nghĩa mở rộng sang dũng mãnh, can đảm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": ghi nhớ: 马 (ngựa) + phần 尧 (âm xiāo) = 骁勇 (dũng mãnh như ngựa chiến tốt nhất), từ hay dùng khen tướng giỏi. | Gương Hán-Việt | 骁勇 (xiāo yǒng) — dũng mãnh, thiện chiến; 骁将 (xiāo jiàng) — dũng tướng. | Mở khoá kiến thức | Biết 骁 mở khoá 骁勇善战 (dũng mãnh thiện chiến), 骁将 (dũng tướng) — từ vựng lịch sử và quân sự.", "Tự nguyên_Xie": "Tiểu triện | 骁 là dạng giản thể của 驍 (馬→马, 堯→尧). Wiktionary dẫn {{Han simp}} không phân tích nguồn gốc. 驍 chỉ ngựa chiến khoẻ mạnh xuất sắc; nghĩa phái sinh: dũng mãnh, can đảm đặc biệt (dùng trong 骁勇 — dũng mãnh). Glyph tiểu triện tồn tại. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoẻ mạnh nhanh nhẹn", "Hạng Tần Suất (Jun Da)": "4388.0", "Tần Suất % (Jun Da)": "99.8390498537", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骁", "Unihan_Traditional (Chữ Phồn thể)": "驍", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "kiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ để miêu tả sự dũng mãnh, thiện chiến của tướng sĩ hoặc ngựa chiến. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椽', '{"9000": "4389.0", "Chữ Trung Quốc": "椽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 椽 | 椽 | tượng hình | đòn tay, xà gỗ chịu lực mái nhà | 椽 chỉ đòn tay — những thanh gỗ nằm ngang trên vì kèo đỡ mái nhà. Bộ 木 (mộc) gợi vật liệu gỗ. Wiktionary không cung cấp phân tích cấu trúc hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duyên\": ghi nhớ: 木 (gỗ) = 椽子 (đòn tay gỗ mái nhà); thành ngữ 大笔如椽 — ngòi bút to như đòn tay, ý khen văn tài lớn. | Gương Hán-Việt | 大笔如椽 (đại bút như thung) — ngòi bút to như đòn tay, văn tài xuất chúng. | Mở khoá kiến thức | Biết 椽 mở khoá 椽子 (đòn tay mái nhà), 椽梁 (xà và đòn tay) và thành ngữ 大笔如椽 (khen văn tài lớn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary cung cấp phiên âm chi tiết nhưng không phân tích cấu trúc nguồn gốc của 椽. Glyph tiểu triện và lục thư thông tồn tại. 椽 (chuán) chỉ rafter — thanh gỗ nằm nghiêng trên vì kèo đỡ ngói mái nhà. Thành ngữ 大笔如椽 (ngòi bút to như đòn tay) khen văn tài xuất sắc. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đòn tay", "Hạng Tần Suất (Jun Da)": "4389.0", "Tần Suất % (Jun Da)": "99.83923693", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 彖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椽", "Unihan_Traditional (Chữ Phồn thể)": "椽", "Pinyin_Xie": "chuán", "Âm Hán Việt_Xie": "chuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này thường làm danh từ chỉ đòn tay hoặc làm lượng từ cho gian nhà trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侗', '{"9000": "4390.0", "Chữ Trung Quốc": "侗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | biểu nghĩa | người | 同 | đồng | biểu âm | cùng nhau | 侗 = 亻(Nhân, biểu nghĩa: người) + 同 (Đồng, biểu âm, âm dòng≈tóng); chữ hình thanh. Bộ nhân 亻 chỉ liên quan đến người — cụ thể là người Đồng (Dong/Tung) hoặc trạng thái ngây thơ vô trí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": ghi nhớ: 亻(người) + 同 (đồng — cùng nhau) = dân tộc Đồng, người sống cùng nhau trong các làng bản truyền thống (侗族). | Gương Hán-Việt | 侗族 (Đồng tộc) — dân tộc Đồng ở tây nam Trung Quốc; 侗寨 (làng Đồng) — kiến trúc đặc trưng. | Mở khoá kiến thức | Biết 侗 mở khoá 侗族 (dân tộc Đồng), 侗寨 (làng Đồng), 鼓楼侗寨 (làng Đồng với cổ lâu) — văn hoá dân tộc thiểu số Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 亻(nhân, biểu nghĩa: người) + 同 (đồng, biểu âm, âm tóng gần dòng). Wiktionary xác nhận cấu trúc psc. 侗 có hai cách đọc: (1) dòng — tên dân tộc Đồng (Dong people) ở Quý Châu/Quảng Tây/Hồ Nam; (2) tǒng — ngây thơ, vô tri, thô lỗ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vô tri; ấu trĩ; ngớ ngẩn", "Hạng Tần Suất (Jun Da)": "4390.0", "Tần Suất % (Jun Da)": "99.8394240062", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侗", "Unihan_Traditional (Chữ Phồn thể)": "侗", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đồng, thống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự thành thật, ngây ngô hoặc làm danh từ chỉ tộc người Đồng ở Trung Quốc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滦', '{"9000": "4391.0", "Chữ Trung Quốc": "滦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 滦 | 滦 | tượng hình | sông Loan ở Hà Bắc | 滦 là dạng giản thể của 灤. Bộ 氵(thủy) gợi đây là tên sông. Wiktionary không cung cấp phân tích cấu trúc chi tiết cho chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": ghi nhớ: 氵(nước, sông) = 滦河 (Sông Loan ở Hà Bắc) — con sông cung cấp nước cho Bắc Kinh. | Gương Hán-Việt | 滦河 (Loan Hà) — sông Loan ở Hà Bắc, nguồn nước quan trọng của vùng Bắc Kinh. | Mở khoá kiến thức | Biết 滦 giúp nhận diện 滦河 (sông Loan), 滦州 (Loan Châu) và 开滦煤矿 (mỏ than Khai Loan nổi tiếng).", "Tự nguyên_Xie": "滦 là dạng giản thể của 灤. Wiktionary chỉ cung cấp phiên âm và nghĩa — không phân tích nguồn gốc cấu trúc. 滦河 (Sông Loan) là con sông lớn chảy qua tỉnh Hà Bắc, Trung Quốc, đổ ra Vịnh Bột Hải. Đây là tên riêng địa lý, không có nghĩa phái sinh. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Loan (ở tỉnh Hà Bắc của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4391.0", "Tần Suất % (Jun Da)": "99.8396105656", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 栾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵栾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "栾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滦", "Unihan_Traditional (Chữ Phồn thể)": "灤", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ sông Loan hoặc huyện Loan ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荩', '{"9000": "4392.0", "Chữ Trung Quốc": "荩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荩 | 荩 | tượng hình | cỏ tẫn; trung thành; than củi còn thừa | 荩 là dạng giản thể của 藎. Bộ 艹(thảo) gợi đây là một loại thực vật. Wiktionary không cung cấp phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẫn\": ghi nhớ: 艹(cỏ) + âm jìn = cỏ tẫn màu vàng dùng nhuộm, từ đó gợi nghĩa trung thành (藎臣 — tôi trung dùng mình phục vụ vua như cỏ dùng để nhuộm). | Gương Hán-Việt | 藎臣 (jìn chén) — vị tôi trung thành; 藎草 (jìn cǎo) — cỏ tẫn. | Mở khoá kiến thức | Biết 荩 mở khoá 藎臣 (vị tôi trung) trong văn học cổ điển — từ trang trọng chỉ bề tôi tận tụy trung thành.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 荩 là dạng giản thể của 藎. Wiktionary không phân tích cấu trúc nguồn gốc. 藎 nghĩa: (1) cỏ small carpetgrass (Arthraxon hispidus) — loại cỏ có màu vàng dùng nhuộm; (2) trung thành, trung thực (cổ ngữ); (3) than củi còn sót lại. Từ ghép 藎臣 (vị tôi trung) gợi nghĩa trung thành. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ tẫn (màu vàng, dùng để nhuộm); tiến lên; củi cháy còn thừa", "Hạng Tần Suất (Jun Da)": "4392.0", "Tần Suất % (Jun Da)": "99.839797125", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 尽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹尽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荩", "Unihan_Traditional (Chữ Phồn thể)": "藎", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ một loại cỏ hoặc tính từ thể hiện lòng trung thành trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泓', '{"9000": "4393.0", "Chữ Trung Quốc": "泓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 水 | thủy | biểu nghĩa | nước | 弘 | hoằng | biểu âm | rộng lớn; vĩ đại | 泓 = 氵(Thủy, biểu nghĩa: nước) + 弘 (Hoằng, biểu âm, âm hóng); chữ hình thanh. Bộ thủy kết hợp với 弘 (rộng lớn) gợi hình ảnh vực nước sâu rộng, trong veo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoằng\": ghi nhớ: 氵(nước) + 弘 (hoằng — rộng lớn) = 一泓清泉 (một dòng suối trong vắt rộng sâu) — hình ảnh thi ca quen thuộc. | Gương Hán-Việt | 一泓清泉 (nhất hoằng thanh tuyền) — một dòng suối trong vắt; 一泓秋水 (một mặt hồ thu trong trẻo). | Mở khoá kiến thức | Biết 泓 mở khoá lượng từ thi ca: 一泓清泉 (suối trong), 一泓秋水 (mặt hồ thu) — từ vựng trang nhã thường thấy trong thơ văn Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 水/氵(thủy, biểu nghĩa: nước) + 弘 (hoằng, biểu âm, âm hóng). Wiktionary xác nhận cấu trúc psc. 泓 chỉ vực nước sâu, trong leo lẻo; cũng dùng làm lượng từ đo khối nước trong (一泓清泉 — một dòng suối trong vắt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu thăm thẳm; trong leo lẻo", "Hạng Tần Suất (Jun Da)": "4393.0", "Tần Suất % (Jun Da)": "99.8399836845", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 弘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵弘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泓", "Unihan_Traditional (Chữ Phồn thể)": "泓", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Lượng từ | 量词 | Thường làm tính từ tả vẻ trong sâu của nước hoặc làm lượng từ cho dòng nước, vũng nước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚱', '{"9000": "4394.0", "Chữ Trung Quốc": "蚱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚱 | 蚱 | tượng hình | cào cào, châu chấu | 蚱 không có phân tích hình thanh/hội ý rõ ràng từ Wiktionary. Bộ 虫 (trùng) gợi đây là một loài côn trùng — cụ thể là 蚱蜢 (cào cào) hay 螞蚱 (châu chấu nhỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": ghi nhớ: bộ 虫 (côn trùng) + âm zhà = 蚱蜢 (con cào cào nhảy xa như tiếng zhà bật lên). | Gương Hán-Việt | 蚱蜢 (zhàměng) — cào cào; 螞蚱 (mǎzhà) — châu chấu nhỏ (phương ngữ). | Mở khoá kiến thức | Biết 蚱 giúp nhận diện 蚱蜢 (cào cào) và 螞蚱 (châu chấu nhỏ) trong văn học và tự nhiên học.", "Tự nguyên_Xie": "Wiktionary cung cấp phiên âm cho 蚱 nhưng không phân tích cấu trúc nguồn gốc. Chữ này chỉ dùng trong từ ghép: 蚱蜢 (cào cào) và 螞蚱 (phương ngữ: châu chấu nhỏ). Bộ 虫 (trùng) là bộ thủ phổ biến cho tên côn trùng. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trách mãnh 蚱蜢)", "Hạng Tần Suất (Jun Da)": "4394.0", "Tần Suất % (Jun Da)": "99.8401702439", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚱", "Unihan_Traditional (Chữ Phồn thể)": "蚱", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác làm danh từ để chỉ các loài côn trùng như châu chấu, cào cào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癜', '{"9000": "4395.0", "Chữ Trung Quốc": "癜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 18 | nét | 癜 | đẹn | tượng hình | bệnh nổi nốt ngoài da (điến) | 癜 chưa có dạng gốc (usedForm null) và không có phân tích cấu trúc. Bộ 疒 (nạch — bệnh tật) gợi đây là tên một loại bệnh da liễu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đẹn\": bộ 疒 (bệnh) = 白癜风 (bạch điến phong — bệnh bạch biến, da nổi đốm trắng). Chữ 癜 chỉ xuất hiện trong tên bệnh da liễu. | Gương Hán-Việt | 白癜风 (bạch điến phong) — bệnh bạch biến; da mất sắc tố thành đốm trắng. | Mở khoá kiến thức | Biết 癜 mở khoá 白癜风 (bệnh bạch biến/vitiligo) — từ chuyên môn y học da liễu.", "Tự nguyên_Xie": "Wiktionary không có mục từ cho 癜. Bộ 疒 (bệnh tật) là bộ thủ quy ước cho tên bệnh, gợi ý 癜 là tên bệnh da — cụ thể là erythema (ban đỏ) hoặc vitiligo (bạch biến, nổi đốm trắng trên da). Từ ghép thông dụng: 白癜风 (bạch điến phong — bệnh bạch biến). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh điến (nổi nốt ngoài da)", "Hạng Tần Suất (Jun Da)": "4395.0", "Tần Suất % (Jun Da)": "99.8403568033", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 殿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒殿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癜", "Unihan_Traditional (Chữ Phồn thể)": "癜", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền để chỉ các vết đốm, vết bớt ngoài da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酯', '{"9000": "4396.0", "Chữ Trung Quốc": "酯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 酉 | dấu | biểu nghĩa | nhóm chức oxi hoá hữu cơ | 旨 | chỉ | biểu âm | mục đích; ngon ngọt | 酯 = 酉 (Dấu, biểu nghĩa: nhóm chức hợp chất hữu cơ có oxi) + 旨 (Chỉ, biểu âm, âm zhǐ); chữ hình thanh. Bộ 酉 là bộ thủ quy ước trong hoá học Trung Quốc để đặt tên các nhóm chức hữu cơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": ghi nhớ: 酉 (nhóm chức hữu cơ) + 旨 (chỉ — ngon, âm zhǐ) = ester (este) — liên kết tạo hương thơm trong dầu hoa quả và mỡ động vật. | Gương Hán-Việt | Chữ thuần hoá học, không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 酯 giúp nhận diện 酯键 (liên kết ester), 酯化 (phản ứng ester hoá), 甘油酯 (glyceride) — từ vựng hoá học hữu cơ quan trọng.", "Tự nguyên_Xie": "Chữ hình thanh: 酉 (biểu nghĩa: nhóm chức hữu cơ) + 旨 (chỉ, biểu âm, âm zhǐ). Wiktionary xác nhận cấu trúc psc và ghi rõ: 酯 được tạo theo mô hình của 脂 (chất béo), lấy bộ 酉 từ các hợp chất oxi hoá khác như 醇 (rượu) và 酸 (axit), chỉ liên kết ester trong lipid như glyceride. Chữ tạo khi tiếp thu hoá học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ête (hoá học)", "Hạng Tần Suất (Jun Da)": "4396.0", "Tần Suất % (Jun Da)": "99.8405433628", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 旨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉旨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酯", "Unihan_Traditional (Chữ Phồn thể)": "酯", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ hợp chất este được tạo thành từ axit và rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癸', '{"9000": "4397.0", "Chữ Trung Quốc": "癸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 癶 | Số nét | 9 | nét | 癸 | quý | tượng hình | Quý — can thứ 10 trong Thập Thiên Can | 癸 là chữ tượng hình. Wiktionary ghi đây là chữ chỉ dụng cụ đo lường (có thể là dụng cụ đo bóng mặt trời), hoặc là dạng gốc của 戣 (giáo mác) hay 葵 (cây mallow). Bộ 癶 là bộ thủ — hai chân bước ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quý\": 癸 là can thứ 10 (cuối) trong 10 Thiên Can — nhớ vần: Giáp Ất Bính Đinh Mậu Kỷ Canh Tân Nhâm Quý (癸). Quý cũng là họ Quý trong tiếng Việt. | Gương Hán-Việt | 癸亥 (quý hợi) — năm Quý Hợi; 癸卯 (quý mão) — năm Quý Mão; 癸水 (quý thủy) — y học cổ: kinh nguyệt. | Mở khoá kiến thức | Biết 癸 (quý) giúp đọc lịch âm: 癸年 (năm Quý), 癸巳 (Quý Tỵ), 癸亥 (Quý Hợi) — can thứ 10 trong chu kỳ can chi.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Wiktionary ghi 癸 là chữ tượng hình ({{liushu|p}}) với ý nghĩa gốc chưa rõ. Các giả thuyết: (1) dụng cụ đo bóng mặt trời/xác định hướng và tiết đông chí; (2) dạng gốc của 戣 (giáo mác loại gwri); (3) dạng gốc của 葵 (cây mallow). Nay chỉ dùng để chỉ can thứ 10 trong Thập Thiên Can (Giáp Ất Bính Đinh Mậu Kỷ Canh Tân Nhâm Quý). Glyph giáp cốt văn, kim văn, bạch thư, tiểu triện đều đã được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Quý (ngôi thứ 10 hàng Can)", "Hạng Tần Suất (Jun Da)": "4397.0", "Tần Suất % (Jun Da)": "99.8409159649", "GavinGrover_Once (Chiết tự trực tiếp)": "癶 + 天", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱癶天", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "天", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "癶", "Unihan_Simplified (Chữ Giản thể)": "癸", "Unihan_Traditional (Chữ Phồn thể)": "癸", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Thường dùng làm danh từ chỉ thiên can thứ mười hoặc dùng như số từ chỉ thứ tự thứ mười. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚜', '{"9000": "4398.0", "Chữ Trung Quốc": "蚜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sâu | 牙 | nha | biểu âm | răng | 蚜 = 虫 (Trùng, biểu nghĩa: côn trùng) + 牙 (Nha, biểu âm, âm yá); chữ hình thanh. Bộ trùng 虫 gợi đây là loài côn trùng nhỏ — cụ thể là rệp cây (aphid) hút nhựa lá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhá\": 虫 (côn trùng) + 牙 (nha — răng) = con trùng dùng răng nhá (hút) nhựa lá cây — đó là con rệp (蚜虫). | Gương Hán-Việt | 蚜虫 (nhá trùng) — rệp cây, sâu cuốn lá; 棉蚜 (miên nhá) — rệp bông vải. | Mở khoá kiến thức | Biết 蚜 giúp nhận diện 蚜虫 (rệp cây — aphid), 棉蚜 (rệp bông), 麦蚜 (rệp lúa mì) — từ vựng nông nghiệp quan trọng.", "Tự nguyên_Xie": "Chữ hình thanh: 虫 (trùng, biểu nghĩa: côn trùng) + 牙 (nha, biểu âm, âm yá). Wiktionary xác nhận cấu trúc psc. 蚜 chỉ rệp cây (plant louse, aphid) — loài côn trùng nhỏ hút nhựa thực vật gây hại nông nghiệp. Thường dùng trong 蚜虫 (rệp cây). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sâu ăn lá cây", "Hạng Tần Suất (Jun Da)": "4398.0", "Tần Suất % (Jun Da)": "99.8411020075", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚜", "Unihan_Traditional (Chữ Phồn thể)": "蚜", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp tạo thành danh từ để chỉ loài rệp chuyên hút nhựa cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扪', '{"9000": "4399.0", "Chữ Trung Quốc": "扪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 6 | nét | 手 | thủ | biểu nghĩa | tay | 門 | môn | biểu âm | cổng, cửa | 扪 = 扌(Thủ, biểu nghĩa: tay) + 門 (Môn, biểu âm, âm mén); chữ hình thanh. Bộ thủ 扌 chỉ hành động sờ mó, vỗ nhẹ bằng tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"môn\": ghi nhớ: 扌(tay) + 門 (môn — cửa) = dùng tay gõ sờ cánh cửa lương tâm (扪心自问 — tự xét lương tâm). | Gương Hán-Việt | 扪心自问 (mun xīn zì wèn) — sờ lòng tự hỏi, tự xét lương tâm. | Mở khoá kiến thức | Biết 扪 mở khoá thành ngữ 扪心自问 (tự xét lương tâm) — cụm từ trang trọng hay dùng trong văn viết và diễn thuyết.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 手 (thủ, biểu nghĩa: tay) + 門 (môn, biểu âm, âm mén). Wiktionary xác nhận cấu trúc psc. 扪 (dạng giản của 捫) nghĩa là sờ, xoa, vỗ nhẹ, mò mẫm. Thành ngữ 扪心自问 (sờ lòng tự hỏi — tự xét lương tâm) là cách dùng phổ biến nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vỗ, sờ bắt", "Hạng Tần Suất (Jun Da)": "4399.0", "Tần Suất % (Jun Da)": "99.8412880502", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 门", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌门", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "门", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扪", "Unihan_Traditional (Chữ Phồn thể)": "捫", "Pinyin_Xie": "mén", "Âm Hán Việt_Xie": "môn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động sờ, vuốt hoặc tự suy xét lương tâm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庑', '{"9000": "4400.0", "Chữ Trung Quốc": "庑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 7 | nét | 庑 | 庑 | tượng hình | hành lang, mái hiên | 庑 là dạng giản thể của 廡. Bộ 广 (nghiễm — mái nhà rộng) gợi đây là một phần kiến trúc — cụ thể là hành lang hoặc mái hiên bên cạnh công trình chính. Wiktionary không cung cấp phân tích chi tiết hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": ghi nhớ: bộ 广 (mái rộng) = 廊庑 (hành lang và mái hiên xung quanh sân điện) — kiến trúc cung đình truyền thống. | Gương Hán-Việt | 廊庑 (láng wǔ) — hành lang và mái hiên trong kiến trúc cổ; 庑殿顶 (wǔdiàn dǐng) — mái điện thức (kiến trúc cổ Trung Quốc). | Mở khoá kiến thức | Biết 庑 mở khoá 廊庑 (hành lang mái hiên), 庑殿顶 (mái điện — loại mái cao cấp nhất trong kiến trúc cổ Trung Quốc).", "Tự nguyên_Xie": "Tiểu triện | 庑 là dạng giản thể của 廡. Wiktionary chỉ ghi {{Han etym}} không có phân tích nguồn gốc. Glyph tiểu triện tồn tại. 廡 chỉ hành lang/dãy nhà phụ ở hai bên sân chính của cung điện hay đền miếu. Cũng có nghĩa cây cối um tùm (cổ). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà giữa hai dãy nhà khác", "Hạng Tần Suất (Jun Da)": "4400.0", "Tần Suất % (Jun Da)": "99.8414740928", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 无", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广无", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "无", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庑", "Unihan_Traditional (Chữ Phồn thể)": "廡", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "vũ, vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dãy nhà phụ hoặc hành lang hai bên nhà chính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歆', '{"9000": "4401.0", "Chữ Trung Quốc": "歆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 13 | nét | 歆 | ham | tượng hình | yêu thích, say mê; xúc động | 歆 không có phân tích hình thanh/hội ý rõ ràng từ Wiktionary. Bộ 欠 (khiếm — hơi thở, ngáp) gợi hành động thở dài ngưỡng mộ hoặc vươn tới điều mình thích. Có thể là hình thanh với phần trái làm biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ham\": bộ 欠 (hơi thở, ngưỡng) = 歆慕 (ngưỡng mộ, say mê) — thở dài vì thích quá; 歆享 (thần linh hưởng lễ — nuốt hương khói vào). | Gương Hán-Việt | 歆慕 (ham mộ) — ngưỡng mộ, say mê; 歆享 (ham hưởng) — thần hưởng lễ vật. | Mở khoá kiến thức | Biết 歆 mở khoá 歆慕 (ngưỡng mộ trong lòng), 歆羡 (hâm mộ, ao ước) và 歆享 (thần hưởng lễ) — từ vựng trang nhã cổ điển.", "Tự nguyên_Xie": "Wiktionary chỉ cung cấp phiên âm và hợp từ mà không phân tích cấu trúc nguồn gốc 歆. Bộ 欠 (khiếm) thường chỉ hành động miệng/hơi thở (ngáp, hát, thở). 歆 nghĩa: yêu thích, mến mộ, xúc động; thần linh hưởng lễ vật. Họ hàng nghĩa: 歆慕 (ngưỡng mộ), 歆羡 (hâm mộ, thèm muốn). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hâm mộ, rung động", "Hạng Tần Suất (Jun Da)": "4401.0", "Tần Suất % (Jun Da)": "99.8416601354", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "歆", "Unihan_Traditional (Chữ Phồn thể)": "歆", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "hâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện sự ngưỡng mộ hoặc thần linh hưởng thụ lễ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝮', '{"9000": "4402.0", "Chữ Trung Quốc": "蝮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝮 | phục | tượng hình | loài rắn độc, mình ngắn đầu tam giác | 蝮 là chữ tượng hình chỉ loài rắn độc (rắn lục). Không đủ dữ liệu phân tích linh kiện — chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": rắn độc 蝮 nằm phục trong cỏ, chờ cắn — hình ảnh con rắn lục phục kích. | Gương Hán-Việt | phục xà (rắn phục) | Mở khoá kiến thức | Biết 蝮 mở khoá các từ chỉ loài rắn độc trong văn học cổ điển và y học cổ truyền.", "Tự nguyên_Xie": "Chữ 蝮 chỉ một loài rắn độc nguy hiểm (viper). Wiktionary không cung cấp nguồn gốc chữ viết chi tiết. Theo cấu trúc, bộ 虫 (trùng) chỉ loài sinh vật bò sát, nhưng phần còn lại chưa được phân tích rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài rắn độc", "Hạng Tần Suất (Jun Da)": "4402.0", "Tần Suất % (Jun Da)": "99.8418461781", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 复", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫复", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "复", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝮", "Unihan_Traditional (Chữ Phồn thể)": "蝮", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loài rắn độc nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹶', '{"9000": "4403.0", "Chữ Trung Quốc": "蹶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹶 | quyết | tượng hình | đạp lên, ngã, thất bại | 蹶 là chữ chỉ hành động đạp, ngã hoặc thất bại. Bộ 足 (túc) chỉ chân/bước đi, nhưng cấu trúc chi tiết chưa được xác nhận từ nguồn học thuật. Chưa có nguồn phân tích lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bước chân quyết liệt rồi vấp ngã — 蹶 là cái vấp ngã bất ngờ khi đang xông tới. | Gương Hán-Việt | quyết ngã (ngã nhào) | Mở khoá kiến thức | Biết 蹶 mở khoá các từ văn học cổ điển tả sự thất bại, sụp đổ, vấp ngã.", "Tự nguyên_Xie": "Chữ 蹶 mang nghĩa đạp lên, ngã ngựa, thất bại. Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích nguồn gốc chi tiết. Bộ 足 (túc — chân) gợi ý liên quan đến hành động của chân. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đạp lên; ngã, thất bại, đánh bại; đạp đổ; làm nản lòng, làm thất vọng; đá ra sau, đá hậu, gót", "Hạng Tần Suất (Jun Da)": "4403.0", "Tần Suất % (Jun Da)": "99.8420322207", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹶", "Unihan_Traditional (Chữ Phồn thể)": "蹶", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quệ, quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vấp ngã hoặc dùng chân đá ngược về sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弈', '{"9000": "4404.0", "Chữ Trung Quốc": "弈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 廾 | Số nét | 9 | nét | 弈 | dịch | tượng hình | chơi cờ vây | 弈 là chữ chỉ việc chơi cờ vây (Go). Wiktionary không cung cấp phân tích cấu trúc chi tiết. Chữ này xuất hiện trong văn học cổ với nghĩa đánh cờ. Chưa có nguồn học thuật xác nhận cấu trúc lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": đánh cờ 弈 là cuộc đấu trí dịch chuyển từng quân — 对弈 là hai người đối mặt trên bàn cờ. | Gương Hán-Việt | đối dịch (đánh cờ đối mặt) | Mở khoá kiến thức | Biết 弈 mở khoá từ 对弈 (đánh cờ) và các từ văn học cổ liên quan đến cờ vây.", "Tự nguyên_Xie": "Chữ 弈 trong văn học cổ điển Trung Hoa chỉ môn cờ vây (围棋). Wiktionary xác nhận đây là chữ văn ngôn dùng cho ''Go'' (board game) và động từ ''chơi cờ vây''. Không có phân tích nguồn gốc chữ viết chi tiết. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chơi cờ, đánh cờ", "Hạng Tần Suất (Jun Da)": "4404.0", "Tần Suất % (Jun Da)": "99.8422172298", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 艹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "弈", "Unihan_Traditional (Chữ Phồn thể)": "弈", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc chơi cờ hoặc làm danh từ chỉ bàn cờ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庋', '{"9000": "4405.0", "Chữ Trung Quốc": "庋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 7 | nét | 庋 | quỹ | tượng hình | cái giá để đồ, cất giữ | 庋 là chữ chỉ cái giá để đồ hoặc hành động cất giữ bảo tồn. Bộ 广 (nghiễm) gợi ý mái nhà/không gian che chắn, nhưng cấu trúc chi tiết chưa được xác nhận. Chưa có nguồn học thuật xác nhận lsCodes.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": cái quỹ/tủ 庋 để cất giữ đồ đạc trong nhà — dưới mái nhà rộng 广. | Gương Hán-Việt | quỹ tàng (cất giữ) | Mở khoá kiến thức | Biết 庋 mở khoá từ 庋藏 (cất giữ, bảo tồn) trong văn ngôn cổ điển.", "Tự nguyên_Xie": "Chữ 庋 chỉ cái giá để đồ hoặc hành động sắp xếp, cất giữ. Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Bộ 广 (nghiễm) gợi không gian trong nhà. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giá; giá (để đồ đạc); sắp đặt; bảo tồn; cất giữ", "Hạng Tần Suất (Jun Da)": "4405.0", "Tần Suất % (Jun Da)": "99.8424017221", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庋", "Unihan_Traditional (Chữ Phồn thể)": "庋", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái giá kệ hoặc làm động từ chỉ việc cất giữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喟', '{"9000": "4406.0", "Chữ Trung Quốc": "喟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 喟 | vị | tượng hình | tiếng thở dài | 喟 là chữ hình thanh: bộ 口 (khẩu — miệng) biểu nghĩa tiếng phát ra, phần còn lại biểu âm. Chữ chỉ tiếng thở dài sâu trong văn ngôn. Chưa có dữ liệu lsCodes đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": tiếng thở dài 喟 như nói ''vị'' — miệng 口 phát ra tiếng buồn bã ngậm ngùi. | Gương Hán-Việt | vị thán (than thở) | Mở khoá kiến thức | Biết 喟 mở khoá từ 喟然 (thở dài sâu) và 喟叹 (than thở) trong văn ngôn cổ.", "Tự nguyên_Xie": "Chữ 喟 chỉ hành động thở dài não nề trong văn học cổ (喟然 — thở dài sâu). Wiktionary xác nhận nghĩa ''to heave a sigh''. Bộ 口 (khẩu) chỉ âm thanh phát ra từ miệng. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng thở dài", "Hạng Tần Suất (Jun Da)": "4406.0", "Tần Suất % (Jun Da)": "99.8425856976", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 胃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口胃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喟", "Unihan_Traditional (Chữ Phồn thể)": "喟", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ diễn tả hành động thở dài khi than thở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滂', '{"9000": "4407.0", "Chữ Trung Quốc": "滂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 水 | thủy | biểu nghĩa | nước | 旁 | bàng | biểu âm | 滂 = 水 (Thủy, biểu nghĩa: nước) + 旁 (Bàng, biểu âm); chữ hình thanh. Bộ 水 chỉ nghĩa liên quan đến nước chảy ào ạt, 旁 cho âm đọc gần pāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bẵng\": mưa 滂 (bẵng đà 滂沱) như nước 水 ầm ầm từ hai bên 旁 đổ xuống không ngừng. | Gương Hán-Việt | bàng đà (mưa xối xả) | Mở khoá kiến thức | Biết 滂 mở khoá từ 滂沱 (mưa to như trút) — thành ngữ tả mưa lớn phổ biến.", "Tự nguyên_Xie": "Chữ 滂 là hình thanh: 水 (thủy — nước) biểu nghĩa, 旁 (bàng) biểu âm. Wiktionary xác nhận cấu trúc {{Han compound|水|旁|c1=s|c2=p|t1=water|ls=psc}}. Nghĩa gốc là nước chảy ào ạt, mưa xối xả — thường thấy trong từ 滂沱 (mưa như trút). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bàng đà 滂沱)", "Hạng Tần Suất (Jun Da)": "4407.0", "Tần Suất % (Jun Da)": "99.8427696731", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滂", "Unihan_Traditional (Chữ Phồn thể)": "滂", "Pinyin_Xie": "pāng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả trạng thái mưa rơi xối xả hoặc nước chảy tràn lan. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啕', '{"9000": "4408.0", "Chữ Trung Quốc": "啕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啕 | đào | tượng hình | tiếng than khóc, la hét | 啕 là chữ chỉ tiếng khóc la, than thở. Bộ 口 (khẩu) gợi ý âm thanh phát ra từ miệng, nhưng cấu trúc chi tiết chưa được xác nhận từ lsCodes. Chữ thường xuất hiện trong từ 嚎啕 (khóc rống).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": tiếng khóc 啕 vang lên như sóng đào — miệng 口 mở rộng gào thét nức nở. | Gương Hán-Việt | đào khốc (khóc la) | Mở khoá kiến thức | Biết 啕 mở khoá thành ngữ 嚎啕大哭 (khóc nức nở to tiếng) phổ biến trong văn học.", "Tự nguyên_Xie": "Chữ 啕 chỉ tiếng khóc la, than vãn to tiếng. Wiktionary ghi nghĩa ''to wail''. Bộ 口 (khẩu) biểu nghĩa âm thanh từ miệng. Chữ thường dùng trong 嚎啕大哭 (khóc nức nở). Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng than", "Hạng Tần Suất (Jun Da)": "4408.0", "Tần Suất % (Jun Da)": "99.8429531319", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啕", "Unihan_Traditional (Chữ Phồn thể)": "啕", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp tạo thành từ láy diễn tả tiếng khóc lớn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛎', '{"9000": "4409.0", "Chữ Trung Quốc": "蛎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 虫 | trùng | biểu nghĩa | sinh vật, côn trùng | 厲 | lẹ | biểu âm | 蛎 = 虫 (Trùng, biểu nghĩa: sinh vật biển) + 厲 (Lệ, biểu âm); chữ hình thanh. Bộ 虫 chỉ loài sinh vật (ở đây là hàu/sò biển), 厲 cho âm đọc gần lì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": con hàu 蛎 vỏ sắc như lệ (dao bén) — bộ 虫 cho thấy đây là sinh vật biển. | Gương Hán-Việt | mẫu lệ (con hàu biển) | Mở khoá kiến thức | Biết 蛎 mở khoá từ 牡蛎 (con hàu) — loại hải sản phổ biến trong ẩm thực.", "Tự nguyên_Xie": "蛎 là hình thanh: 虫 (trùng — sinh vật) biểu nghĩa, 厲 (lệ) biểu âm. Wiktionary xác nhận {{Han compound|虫|厲|ls=psc|c1=s|c2=p|t1=insect; bug; creature}}. Chữ chỉ con hàu (牡蛎 mǔlì) — loài nhuyễn thể hai mảnh vỏ sống ở biển. Dạng giản thể của 蠣. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mẫu lệ 牡蠣,牡蛎)", "Hạng Tần Suất (Jun Da)": "4409.0", "Tần Suất % (Jun Da)": "99.8431365906", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 厉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫厉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛎", "Unihan_Traditional (Chữ Phồn thể)": "蠣", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ con hàu hoặc các loài trai sò đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獭', '{"9000": "4410.0", "Chữ Trung Quốc": "獭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 16 | nét | 犬 | khuyển | biểu nghĩa | chó, thú vật | 賴 | lại | biểu âm | 獭 = 犭(Khuyển, biểu nghĩa: thú vật) + 賴 (Lại, biểu âm); chữ hình thanh. Bộ 犬/犭 chỉ loài thú (ở đây là rái cá), 賴 cho âm đọc gần tǎ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": rái cá 獭 là loài thú 犭 bơi lội tài tình, không ngại nước — cứ như chẳng cần lại ai cả. | Gương Hán-Việt | thủy lại (rái cá nước) | Mở khoá kiến thức | Biết 獭 mở khoá từ 水獭 (rái cá) và 旱獭 (chuột đất/marmot) trong văn học tự nhiên.", "Tự nguyên_Xie": "獭 là hình thanh: 犬 (khuyển — thú vật) biểu nghĩa, 賴 (lại) biểu âm. Wiktionary xác nhận {{Han compound|犬|賴|c1=s|c2=p|t1=dog|ls=psc}}. Chữ chỉ con rái cá (水獭 shuǐtǎ) — loài thú bán thủy sinh ăn cá. Dạng giản thể của 獺. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rái cá", "Hạng Tần Suất (Jun Da)": "4410.0", "Tần Suất % (Jun Da)": "99.8433195325", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 赖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭赖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獭", "Unihan_Traditional (Chữ Phồn thể)": "獺", "Pinyin_Xie": "tǎ", "Âm Hán Việt_Xie": "thát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài động vật có vú sống dưới nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槁', '{"9000": "4411.0", "Chữ Trung Quốc": "槁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 高 | cao | biểu âm | 槁 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 高 (Cao, biểu âm); chữ hình thanh. Bộ 木 chỉ cây cối khô héo, 高 cho âm đọc gần gǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cau\": cây 木 cao 高 mà khô héo 槁 — cau (槁) gợi cây cau khô cằn trơ trụi giữa trời. | Gương Hán-Việt | khô cau (gỗ khô, tàn tạ) | Mở khoá kiến thức | Biết 槁 mở khoá từ 枯槁 (khô héo, tàn tạ) và 形容槁木死灰 trong văn ngôn tả sự bạc bẽo.", "Tự nguyên_Xie": "槁 là hình thanh: 木 (mộc — cây) biểu nghĩa, 高 (cao) biểu âm. Wiktionary xác nhận {{Han compound|木|高|ls=psc|c1=s|c2=p|t1=tree}}. Nghĩa gốc là cây khô, gỗ héo khô — thường dùng trong văn ngôn tả sự tàn lụi. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khô; gỗ khô", "Hạng Tần Suất (Jun Da)": "4411.0", "Tần Suất % (Jun Da)": "99.8435024745", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槁", "Unihan_Traditional (Chữ Phồn thể)": "槀", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả trạng thái cây cối bị khô héo, mất sức sống. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翊', '{"9000": "4412.0", "Chữ Trung Quốc": "翊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 翊 | dực | tượng hình | giúp đỡ, hỗ trợ, bay | 翊 là chữ văn ngôn chỉ hành động giúp đỡ, hỗ trợ hoặc bay. Bộ 羽 (vũ — lông vũ/cánh) gợi ý hình ảnh bay lên. Cấu trúc chi tiết chưa được xác nhận từ lsCodes. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dực\": cánh 翊 — chữ dực gợi đôi cánh nâng đỡ, hỗ trợ ai đó bay lên cao. | Gương Hán-Việt | phụ dực (hỗ trợ, phò tá) | Mở khoá kiến thức | Biết 翊 mở khoá nghĩa phụ tá, hỗ trợ trong tên người và văn ngôn cổ.", "Tự nguyên_Xie": "Chữ 翊 chỉ hành động hỗ trợ, giúp đỡ hoặc bay lên trong văn ngôn. Wiktionary xác nhận nghĩa ''to assist, to help'' và liên quan đến hình ảnh cánh. Thường dùng làm tên người với hàm ý phụ tá, hỗ trợ. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kính trọng; giúp đỡ; bay", "Hạng Tần Suất (Jun Da)": "4412.0", "Tần Suất % (Jun Da)": "99.8436854164", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "翊", "Unihan_Traditional (Chữ Phồn thể)": "翊", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường dùng làm động từ với nghĩa phò tá hoặc làm tính từ trong tên người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龊', '{"9000": "4413.0", "Chữ Trung Quốc": "龊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 15 | nét | 齿 | xỉ | biểu nghĩa | răng | 龊 | xúc | tượng hình | bẩn thỉu, ti tiện | 龊 là giản thể của 齪, thay bộ 齒 (răng phồn thể) bằng 齿 (giản thể). Chữ chỉ sự bẩn thỉu, ti tiện — thường dùng trong từ 龌龊 (bẩn thỉu, đê tiện).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xúc\": 龊 (xúc) trong 龌龊 — răng 齿 bẩn tượng trưng cho người xúc phạm, hành vi ti tiện đáng khinh. | Gương Hán-Việt | ô xúc (bẩn thỉu, đê tiện) | Mở khoá kiến thức | Biết 龊 mở khoá từ 龌龊 (ô trọc, đê tiện, bẩn thỉu) — từ chỉ tính cách xấu xa.", "Tự nguyên_Xie": "龊 là giản thể của 齪, theo Wiktionary: {{Han simp|齪|f=齒|t=齿}}. Chữ gốc 齪 có bộ 齒 (răng) biểu nghĩa sự không sạch sẽ/bẩn thỉu — răng bẩn ám chỉ tính cách đê tiện. Thường xuất hiện trong từ 龌龊 (ô trọc, đê tiện). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ác xúc 齷齪,龌龊)", "Hạng Tần Suất (Jun Da)": "4413.0", "Tần Suất % (Jun Da)": "99.8438683583", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "足", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龊", "Unihan_Traditional (Chữ Phồn thể)": "齪", "Pinyin_Xie": "chuò", "Âm Hán Việt_Xie": "xúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong từ ghép để chỉ sự bẩn thỉu hoặc hèn hạ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邺', '{"9000": "4414.0", "Chữ Trung Quốc": "邺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 邺 | nghiệp | tượng hình | địa danh cổ | 邺 là giản thể của 鄴, thay 業 bằng 业. Bộ 阝(邑 — ấp/địa danh) biểu nghĩa địa điểm, 业/業 biểu âm. Chữ chỉ thành Nghiệp — kinh đô nhiều triều đại cổ đại Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiệp\": thành Nghiệp 邺 — nơi nghiệp lớn được gây dựng, kinh đô của nhiều triều đại hùng mạnh. | Gương Hán-Việt | Nghiệp thành (thành Nghiệp lịch sử) | Mở khoá kiến thức | Biết 邺 mở khoá tên địa danh lịch sử 邺城 (thành Nghiệp) quan trọng trong Tam Quốc chí.", "Tự nguyên_Xie": "邺 là giản thể của 鄴: {{Han simp|鄴|f=業|t=业}}. Chữ gốc 鄴 gồm 邑 (ấp — địa danh) + 業 (nghiệp) biểu âm. Chỉ thành Nghiệp (Yè) — kinh đô thời Tam Quốc, Đông Ngụy, Bắc Tề. Nay thuộc vùng giáp Hà Nam–Hà Bắc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "4414.0", "Tần Suất % (Jun Da)": "99.8440507835", "GavinGrover_Once (Chiết tự trực tiếp)": "业 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰业阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "业", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邺", "Unihan_Traditional (Chữ Phồn thể)": "鄴", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "nghiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ địa danh cổ hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莘', '{"9000": "4415.0", "Chữ Trung Quốc": "莘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莘 | tân | tượng hình | đông đúc, tên đất, loài cây | 莘 là chữ bộ 艹 (thảo — cỏ cây) kết hợp với phần dưới, nhưng cấu trúc lsCodes chưa được xác nhận. Chữ có nhiều nghĩa: tên địa danh, chỉ sự đông đúc, hoặc loài cây. Chưa có nguồn học thuật xác nhận đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": 莘莘学子 — đám đông học sinh tân tú 莘 như cỏ xanh mơn mởn, đông đúc tràn đầy sức sống. | Gương Hán-Việt | tân tân (đông đúc, chen chúc) | Mở khoá kiến thức | Biết 莘 mở khoá thành ngữ 莘莘学子 (đông đảo học sinh) phổ biến trong văn phong trang trọng.", "Tự nguyên_Xie": "Chữ 莘 có bộ 艹 (thảo — cỏ cây), gợi liên quan đến thực vật hoặc địa danh. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Một nghĩa phổ biến là tên địa danh 莘庄 (Tân Trang, Thượng Hải) và chỉ học sinh đông đúc trong 莘莘学子. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đông đúc, đàn, lũ", "Hạng Tần Suất (Jun Da)": "4415.0", "Tần Suất % (Jun Da)": "99.8442332086", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莘", "Unihan_Traditional (Chữ Phồn thể)": "莘", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sân, tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự đông đảo hoặc làm danh từ chỉ địa danh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燮', '{"9000": "4416.0", "Chữ Trung Quốc": "燮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 17 | nét | 又 | hựu | biểu nghĩa | tay | 辛 | tân | biểu nghĩa | công cụ/đau khổ | 炏 | biểu nghĩa | lửa | 燮 là chữ hội ý: một bàn tay (又 — hựu) cầm vật gì đó giữa nhiều ngọn lửa (炏). Ý nghĩa và cách giải thích chính xác vẫn chưa rõ ràng theo Wiktionary — có giả thuyết là dùi vào củi lửa, tạo sự hòa hợp qua lửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiếp\": đôi tay 又 điều hòa 燮 giữa lửa 炏 — hòa giải như dùng tay dàn xếp giữa các ngọn lửa nóng bỏng. | Gương Hán-Việt | điều tiếp (điều hòa, hòa hợp) | Mở khoá kiến thức | Biết 燮 mở khoá tên người và chức quan 燮理 (điều hòa, cai quản) trong văn ngôn cổ điển.", "Tự nguyên_Xie": "Trong giáp cốt văn, 燮 là chữ hội ý: bàn tay (又) cầm vật gì giữa ba hoặc nhiều ngọn lửa (火). Wiktionary ghi ''meaning and significance uncertain''. Các giả thuyết gồm: dùi vào củi, nấu chín bằng lửa, hoặc điều hòa bằng nhiệt. Nghĩa hiện đại là hòa hợp, điều hòa. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoà hợp, điều hoà", "Hạng Tần Suất (Jun Da)": "4416.0", "Tần Suất % (Jun Da)": "99.8444156338", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 又", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "燮", "Unihan_Traditional (Chữ Phồn thể)": "燮", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ với nghĩa điều hòa hoặc phối hợp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剁', '{"9000": "4417.0", "Chữ Trung Quốc": "剁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 剁 | đóa | tượng hình | chặt, băm nhỏ | 剁 là chữ chỉ hành động chặt, băm thịt. Bộ 刀/刂 (đao — dao) gợi ý dụng cụ cắt chặt. Cấu trúc chi tiết chưa được xác nhận từ lsCodes. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đóa\": tay đóa 剁 — cầm dao chặt mạnh lên thớt, tiếng đóa đóa nghe rất bếp núc. | Gương Hán-Việt | băm đóa (chặt băm) | Mở khoá kiến thức | Biết 剁 mở khoá từ 剁手 (chặt tay — tiếng lóng mua sắm quá tay) phổ biến trên mạng xã hội.", "Tự nguyên_Xie": "Chữ 剁 chỉ hành động chặt, băm (thịt, rau). Wiktionary không cung cấp nguồn gốc chữ viết. Bộ 刂 (đao — dao) biểu nghĩa hành động dùng dao, phần còn lại gợi âm. Đây là từ khẩu ngữ phổ biến trong bếp núc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chặt, băm", "Hạng Tần Suất (Jun Da)": "4417.0", "Tần Suất % (Jun Da)": "99.8445975422", "GavinGrover_Once (Chiết tự trực tiếp)": "朵 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰朵刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剁", "Unihan_Traditional (Chữ Phồn thể)": "剁", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "đóa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị hành động dùng dao chặt mạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觐', '{"9000": "4418.0", "Chữ Trung Quốc": "觐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 15 | nét | 觐 | cận | tượng hình | vào chầu, hầu kiến | 觐 là chữ chỉ hành động vào chầu thiên tử hoặc hầu kiến vua chúa. Bộ 见 (kiến — nhìn/gặp) gợi ý cuộc gặp gỡ trang trọng. Cấu trúc chi tiết chưa được xác nhận từ lsCodes. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cận\": vào cận 觐 — tiến đến gần 见 thiên tử để chầu kiến, lễ nghi trang trọng nhất triều đình. | Gương Hán-Việt | cận kiến (vào chầu, hầu kiến) | Mở khoá kiến thức | Biết 觐 mở khoá từ 朝觐 (vào chầu thiên tử, hành hương) và 觐见 (yết kiến) trong văn ngôn.", "Tự nguyên_Xie": "Chữ 觐 chỉ hành động vào chầu thiên tử, hầu kiến người đứng đầu tối cao. Wiktionary xác nhận nghĩa ''to have an audience with the Emperor, leader, president''. Bộ 见 (kiến) biểu nghĩa sự gặp gỡ trang trọng. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hầu hạ", "Hạng Tần Suất (Jun Da)": "4418.0", "Tần Suất % (Jun Da)": "99.8447794505", "GavinGrover_Once (Chiết tự trực tiếp)": "堇 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰堇见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觐", "Unihan_Traditional (Chữ Phồn thể)": "覲", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "cận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ việc triều kiến hoàng đế thời phong kiến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铛', '{"9000": "4419.0", "Chữ Trung Quốc": "铛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铛 | đang | tượng hình | tiếng kêu kim loại; cái chảo, xiềng xích | 铛 là chữ bộ 金/钅 (kim — kim loại) kết hợp phần biểu âm. Chữ có hai nghĩa: tiếng kêu leng keng của kim loại, hoặc cái chảo/xiềng xích. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đang\": tiếng đang 铛 — kim loại 钅 va vào nhau kêu đang đang, gợi tiếng xiềng xích leng keng. | Gương Hán-Việt | lang đang (xiềng xích kêu leng keng) | Mở khoá kiến thức | Biết 铛 mở khoá từ 锒铛入狱 (xiềng tay vào tù) — thành ngữ phổ biến trong văn học và báo chí.", "Tự nguyên_Xie": "Chữ 铛 thuộc bộ 钅 (kim — kim loại), chỉ tiếng kêu kim loại va chạm hoặc dụng cụ kim loại như chảo, xiềng. Wiktionary chỉ ghi {{Han etym}}. Thường xuất hiện trong từ 锒铛 (tiếng xiềng xích kêu). Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lang đang 鋃鐺,锒铛)", "Hạng Tần Suất (Jun Da)": "4419.0", "Tần Suất % (Jun Da)": "99.8449613589", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 当", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅当", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "当", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铛", "Unihan_Traditional (Chữ Phồn thể)": "鐺", "Pinyin_Xie": "dāng", "Âm Hán Việt_Xie": "sanh, đang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả tiếng kim loại hoặc danh từ chỉ xiềng xích. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谗', '{"9000": "4420.0", "Chữ Trung Quốc": "谗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói | 毚 | sàm | biểu âm | 谗 = 讠(Ngôn, biểu nghĩa: lời nói) + 毚 (Sàm, biểu âm); chữ hình thanh. Bộ 言/讠 chỉ lời nói, 毚 cho âm đọc gần chán — chỉ lời nói xấu, gièm pha người khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàm\": lời sàm 谗 — dùng miệng 讠 để sàm ngôn, gièm pha, nói xấu sau lưng người khác. | Gương Hán-Việt | sàm ngôn (lời gièm pha) | Mở khoá kiến thức | Biết 谗 mở khoá từ 谗言 (lời gièm pha), 谗害 (hãm hại bằng lời nói) trong văn học lịch sử.", "Tự nguyên_Xie": "谗 là hình thanh: 言 (ngôn — lời nói) biểu nghĩa, 毚 (sàm) biểu âm. Wiktionary xác nhận {{Han compound|言|毚|t1=speech|c1=s|c2=p|ls=psc}}. Nghĩa gốc là nói xấu, gièm pha — dùng lời 言 để hại người. Dạng giản thể của 讒. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói xấu, gièm pha", "Hạng Tần Suất (Jun Da)": "4420.0", "Tần Suất % (Jun Da)": "99.8451427505", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "谗", "Unihan_Traditional (Chữ Phồn thể)": "讒", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "sàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành vi nói xấu hoặc danh từ chỉ lời sàm ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镍', '{"9000": "4421.0", "Chữ Trung Quốc": "镍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镍 | niết | tượng hình | niken, nguyên tố Ni | 镍 là chữ bộ 钅 (kim — kim loại) kết hợp phần biểu âm, chỉ nguyên tố niken (Ni, số nguyên tử 28). Đây là chữ được tạo ra để phiên âm tên nguyên tố hóa học phương Tây. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niết\": niken 镍 — kim loại 钅 màu bạc niết (sáng bóng), dùng trong đồng xu và hợp kim. | Gương Hán-Việt | niết kim (kim loại niken) | Mở khoá kiến thức | Biết 镍 mở khoá các từ hóa học như 镍合金 (hợp kim niken), 镍钢 (thép niken).", "Tự nguyên_Xie": "Chữ 镍 được tạo ra để biểu thị nguyên tố niken (Nickel, Ni). Bộ 钅 (kim — kim loại) chỉ đây là kim loại, phần còn lại biểu âm gần niè. Wiktionary không cung cấp nguồn gốc cổ điển. Đây là chữ Hán tạo muộn cho thuật ngữ hóa học hiện đại. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kền, niken, Ni", "Hạng Tần Suất (Jun Da)": "4421.0", "Tần Suất % (Jun Da)": "99.8453241421", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 臬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅臬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镍", "Unihan_Traditional (Chữ Phồn thể)": "鎳", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nguyên tố hóa học niken trong công nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臃', '{"9000": "4422.0", "Chữ Trung Quốc": "臃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 臃 | ung | tượng hình | sưng to, phình ra | 臃 là chữ bộ 月/肉 (nhục — thịt/thân thể) kết hợp phần biểu âm, chỉ trạng thái sưng phình. Thường dùng trong từ 臃肿 (phình to, cồng kềnh). Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ung\": khối ung 臃 — thịt 月 phình to ung húp, tượng trưng cho sự cồng kềnh không hiệu quả. | Gương Hán-Việt | ung thũng (sưng to, phình nề) | Mở khoá kiến thức | Biết 臃 mở khoá từ 臃肿 (cồng kềnh, béo phì, biên chế thừa) — dùng cả nghĩa đen lẫn nghĩa bóng.", "Tự nguyên_Xie": "Chữ 臃 thuộc bộ 肉/月 (nhục — thân thể), chỉ trạng thái sưng to hoặc cồng kềnh. Wiktionary xác nhận ''used in 臃腫: obese, swollen, overstaffed''. Bộ 肉 biểu nghĩa liên quan đến thể xác. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sưng to", "Hạng Tần Suất (Jun Da)": "4422.0", "Tần Suất % (Jun Da)": "99.8455055336", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 雍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月雍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臃", "Unihan_Traditional (Chữ Phồn thể)": "臃", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái sưng phồng hoặc béo phì. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墒', '{"9000": "4423.0", "Chữ Trung Quốc": "墒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 墒 | thương | tượng hình | độ ẩm đất thích hợp cho hạt nảy mầm | 墒 là chữ nông nghiệp hiện đại bộ 土 (thổ — đất) kết hợp phần biểu âm, chỉ độ ẩm đất thích hợp cho hạt giống nảy mầm. Cấu trúc lsCodes chưa được xác nhận. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": đất 土 có thương lượng 墒 — độ ẩm vừa phải, đất thương hạt giống đủ để nảy mầm. | Gương Hán-Việt | địa thương (độ ẩm đất) | Mở khoá kiến thức | Biết 墒 mở khoá thuật ngữ nông nghiệp 墒情 (tình trạng độ ẩm đất), 保墒 (giữ ẩm đất).", "Tự nguyên_Xie": "Chữ 墒 chỉ độ ẩm đất thích hợp cho việc gieo hạt (soil moisture for germination). Wiktionary không cung cấp nguồn gốc. Bộ 土 (thổ — đất) biểu nghĩa. Đây là từ nông nghiệp chuyên ngành, chữ tạo muộn, chưa có nguồn cổ học xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "độ ẩm thích hợp (thích hợp cho hạt nẩy mầm)", "Hạng Tần Suất (Jun Da)": "4423.0", "Tần Suất % (Jun Da)": "99.8456864084", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 商", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土商", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "商", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墒", "Unihan_Traditional (Chữ Phồn thể)": "墒", "Pinyin_Xie": "shāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ lượng nước tích tụ trong đất nông nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晔', '{"9000": "4424.0", "Chữ Trung Quốc": "晔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 晔 | diệp | tượng hình | sáng chói, rực rỡ | 晔 là chữ bộ 日 (nhật — mặt trời) kết hợp phần biểu âm, chỉ ánh sáng rực rỡ. Wiktionary xác nhận nghĩa ''bright, shining, brilliant''. Thường dùng làm tên người với hàm ý rực rỡ, phát đạt. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệp\": ánh sáng 晔 (diệp) — mặt trời 日 chiếu rực rỡ như cánh diệp (lá) lấp lánh dưới nắng. | Gương Hán-Việt | quang diệp (sáng rực rỡ) | Mở khoá kiến thức | Biết 晔 mở khoá các tên người có hàm ý rực rỡ và từ văn ngôn tả ánh sáng.", "Tự nguyên_Xie": "Chữ 晔 thuộc bộ 日 (nhật — mặt trời), chỉ ánh sáng chói lọi, rực rỡ. Wiktionary xác nhận nghĩa văn ngôn ''bright, shining, flourishing''. Thường dùng làm tên người với nghĩa sáng sủa, thịnh vượng. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng chói, sáng rực; phát đạt, thịnh vượng", "Hạng Tần Suất (Jun Da)": "4424.0", "Tần Suất % (Jun Da)": "99.8458672832", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 华", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日华", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "华", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晔", "Unihan_Traditional (Chữ Phồn thể)": "曄", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "diệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ bổ nghĩa cho danh từ hoặc dùng trong tên người để chỉ sự vẻ vang. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燔', '{"9000": "4425.0", "Chữ Trung Quốc": "燔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 16 | nét | 火 | hoả | biểu nghĩa | lửa | 番 | phan | biểu âm | 燔 = 火 (Hoả, biểu nghĩa: lửa) + 番 (Phan, biểu âm); chữ hình thanh. Bộ 火 chỉ lửa/nướng bằng lửa, 番 cho âm đọc gần fán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": lửa 火 nướng 燔 — phàn (phàn nàn) khi thức ăn nướng bị cháy, nhưng 燔 chính là hành động nướng đó. | Gương Hán-Việt | thiêu phàn (đốt, nướng) | Mở khoá kiến thức | Biết 燔 mở khoá các từ văn ngôn tả lễ tế bằng lửa và phương pháp nấu nướng cổ đại.", "Tự nguyên_Xie": "燔 là hình thanh: 火 (hoả — lửa) biểu nghĩa, 番 (phan) biểu âm. Wiktionary xác nhận {{Han compound|火|番|c1=s|c2=p|t1=fire|ls=psc}}. Nghĩa gốc là nướng, quay thức ăn trên lửa — một trong các phương pháp nấu cổ xưa nhất. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nướng, quay", "Hạng Tần Suất (Jun Da)": "4425.0", "Tần Suất % (Jun Da)": "99.846048158", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "燔", "Unihan_Traditional (Chữ Phồn thể)": "燔", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ vật bị đốt hoặc làm vị ngữ trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘭', '{"9000": "4426.0", "Chữ Trung Quốc": "嘭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 嘭 | bành | tượng hình | tiếng bụp, thình thịch (tượng thanh) | 嘭 là chữ tượng thanh bộ 口 (khẩu) kết hợp phần biểu âm 彭, chỉ âm thanh va đập mạnh như tiếng súng nổ, tiếng đập cửa. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bành\": tiếng bành 嘭 — miệng 口 phát ra tiếng va chạm lớn như súng nổ hay cửa đóng mạnh. | Gương Hán-Việt | bành bành (tiếng đập, nổ) | Mở khoá kiến thức | Biết 嘭 mở khoá các từ tượng thanh tả tiếng động mạnh trong văn xuôi hiện đại.", "Tự nguyên_Xie": "Chữ 嘭 là từ tượng thanh chỉ âm thanh va chạm mạnh, bụp, thình thịch. Wiktionary không cung cấp nguồn gốc. Bộ 口 (khẩu) biểu nghĩa âm thanh. Đây là chữ tạo muộn dùng để mô phỏng tiếng động lớn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thình thịch, bụp (Tượng thanh)", "Hạng Tần Suất (Jun Da)": "4426.0", "Tần Suất % (Jun Da)": "99.846228516", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 彭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口彭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘭", "Unihan_Traditional (Chữ Phồn thể)": "嘭", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "bành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Từ tượng thanh này thường đứng độc lập hoặc làm trạng ngữ để mô tả âm thanh va đập mạnh. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涿', '{"9000": "4427.0", "Chữ Trung Quốc": "涿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 涿 | trác | tượng hình | nhỏ giọt; tên sông/địa danh | 涿 là chữ bộ 水/氵 (thủy — nước) kết hợp phần biểu âm, chỉ nước nhỏ giọt hoặc tên địa danh. Chữ nổi tiếng với tên 涿州 (Trác Châu) và 涿郡 (Trác Quận) — quê hương Lưu Bị. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": nước 涿 (trác) nhỏ giọt — cũng là tên vùng đất trác lập, nơi Lưu Bị sinh ra. | Gương Hán-Việt | Trác Châu (địa danh lịch sử) | Mở khoá kiến thức | Biết 涿 mở khoá địa danh 涿州、涿郡 quan trọng trong lịch sử Tam Quốc.", "Tự nguyên_Xie": "Chữ 涿 thuộc bộ 氵 (thủy — nước), chỉ nước nhỏ giọt hoặc dòng nước nhỏ. Wiktionary ghi nghĩa ''drip, dribble, trickle'' và tên địa danh. Nổi tiếng nhờ 涿县 (Trác Huyện) — quê của Lưu Bị trong Tam Quốc. Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Trác", "Hạng Tần Suất (Jun Da)": "4427.0", "Tần Suất % (Jun Da)": "99.8464088741", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 豖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵豖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涿", "Unihan_Traditional (Chữ Phồn thể)": "涿", "Pinyin_Xie": "zhuō", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong các địa danh cổ như Trác Quận hay Trác Lộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醯', '{"9000": "4428.0", "Chữ Trung Quốc": "醯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 19 | nét | 醯 | hê | tượng hình | giấm; acyl (hóa học) | 醯 là chữ bộ 酉 (dậu — rượu/lên men) kết hợp phần trên, chỉ giấm hoặc axit. Bộ 酉 thường chỉ các chất lên men như rượu, giấm. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hê\": giấm 醯 (hê) — nước lên men 酉 có vị chua hê hê, dùng trong bếp và y học cổ. | Gương Hán-Việt | hê tửu (giấm chua) | Mở khoá kiến thức | Biết 醯 mở khoá từ văn ngôn chỉ giấm và thuật ngữ hóa học 酰 (acyl) trong tiếng Trung hiện đại.", "Tự nguyên_Xie": "Chữ 醯 thuộc bộ 酉 (dậu — rượu/lên men), chỉ giấm trong văn ngôn. Wiktionary xác nhận nghĩa ''vinegar'' (văn ngôn) và ''acyl'' (hóa học, dùng ở Đài Loan). Bộ 酉 biểu nghĩa liên quan đến lên men. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giấm", "Hạng Tần Suất (Jun Da)": "4428.0", "Tần Suất % (Jun Da)": "99.8465892321", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "醯", "Unihan_Traditional (Chữ Phồn thể)": "醯", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "ê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đóng vai trò tân ngữ hoặc kết hợp tạo từ ghép chỉ các loại giấm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箩', '{"9000": "4429.0", "Chữ Trung Quốc": "箩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箩 | la | tượng hình | cái rá, giỏ tre | 箩 là giản thể của 籮, thay 羅 bằng 罗. Bộ 竹/⺮ (trúc — tre) biểu nghĩa đồ vật làm từ tre, phần còn lại biểu âm. Chỉ cái rá, giỏ tre dùng để vo gạo hoặc sàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": cái rá 箩 (la) — đan bằng tre ⺮ hình tròn như cái la (mõ), dùng vo gạo hàng ngày. | Gương Hán-Việt | trúc la (giỏ tre) | Mở khoá kiến thức | Biết 箩 mở khoá từ 箩筐 (giỏ tre lớn), 箩底 (đáy rổ — tiếng lóng người không ai muốn) trong tiếng Trung.", "Tự nguyên_Xie": "箩 là giản thể của 籮: {{Han simp|籮|f=羅|t=罗}}. Chữ gốc 籮 gồm 竹 (trúc — tre) biểu nghĩa và 羅 (la) biểu âm. Chỉ cái giỏ tre, rá vo gạo — dụng cụ truyền thống trong bếp Á Đông. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái rá vo gạo", "Hạng Tần Suất (Jun Da)": "4429.0", "Tần Suất % (Jun Da)": "99.8467690733", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 罗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮罗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箩", "Unihan_Traditional (Chữ Phồn thể)": "籮", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ dùng, thường kết hợp với lượng từ cá hoặc chỉ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄱', '{"9000": "4430.0", "Chữ Trung Quốc": "鄱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 14 | nét | 鄱 | bà | tượng hình | tên địa danh | 鄱 là chữ địa danh bộ 阝(邑 — ấp/địa điểm) kết hợp phần biểu âm. Chủ yếu dùng trong tên 鄱阳湖 (Hồ Bà Dương) — hồ nước ngọt lớn nhất Trung Quốc. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bà\": hồ Bà 鄱 Dương — mênh mông như bà rộng lớn, địa danh nổi tiếng nhất dùng chữ 鄱. | Gương Hán-Việt | Bà Dương (địa danh) | Mở khoá kiến thức | Biết 鄱 mở khoá tên 鄱阳湖 (Hồ Bà Dương) — hồ lớn nhất Trung Quốc, quan trọng trong địa lý và lịch sử.", "Tự nguyên_Xie": "Chữ 鄱 thuộc bộ 邑/阝 (ấp — địa điểm), chỉ địa danh. Wiktionary ghi {{Han etym}} không có chi tiết. Chữ nổi tiếng nhờ 鄱阳湖 (Hồ Bà Dương, Giang Tây) — hồ nước ngọt lớn nhất Trung Quốc. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "4430.0", "Tần Suất % (Jun Da)": "99.8469483977", "GavinGrover_Once (Chiết tự trực tiếp)": "番 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰番阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄱", "Unihan_Traditional (Chữ Phồn thể)": "鄱", "Pinyin_Xie": "pó", "Âm Hán Việt_Xie": "bà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng trong các địa danh như hồ Bà Dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睨', '{"9000": "4431.0", "Chữ Trung Quốc": "睨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睨 | nghễ | tượng hình | liếc nhìn, nhìn nghiêng | 睨 là chữ bộ 目 (mục — mắt) kết hợp phần biểu âm, chỉ hành động liếc nhìn, nhìn xiên. Bộ 目 biểu nghĩa liên quan đến mắt/nhìn. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghễ\": mắt 目 nghễ nghệt 睨 — liếc nhìn xiên xẹo, không nhìn thẳng vào mặt người. | Gương Hán-Việt | nghễ thị (nhìn nghiêng, liếc) | Mở khoá kiến thức | Biết 睨 mở khoá từ 睥睨 (liếc khinh thường, kiêu ngạo) trong văn học cổ điển.", "Tự nguyên_Xie": "Chữ 睨 thuộc bộ 目 (mục — mắt), chỉ hành động nhìn nghiêng, liếc. Wiktionary chỉ ghi {{Han etym}}. Bộ 目 biểu nghĩa liên quan đến thị giác. Nghĩa là liếc mắt không thẳng — thường hàm ý khinh thường hoặc chú ý lén. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghé trông, liếc", "Hạng Tần Suất (Jun Da)": "4431.0", "Tần Suất % (Jun Da)": "99.8471277222", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睨", "Unihan_Traditional (Chữ Phồn thể)": "睨", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nghễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi của mắt, thường đi kèm tân ngữ chỉ đối tượng bị nhìn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诤', '{"9000": "4432.0", "Chữ Trung Quốc": "诤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诤 | tranh | tượng hình | can ngăn, khuyên can thẳng thắn | 诤 là giản thể của 諍, thay 言 bằng 讠. Bộ 讠(ngôn — lời nói) biểu nghĩa lời can ngăn thẳng thắn, phần còn lại biểu âm. Chỉ hành động can gián chân thành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": lời tranh 诤 — dùng miệng 讠 tranh luận 争 để can ngăn, khuyên nhủ thẳng thắn. | Gương Hán-Việt | can tranh (can gián) | Mở khoá kiến thức | Biết 诤 mở khoá từ 诤友 (bạn thân dám nói thật), 诤言 (lời can gián thẳng thắn) trong văn ngôn.", "Tự nguyên_Xie": "诤 là giản thể của 諍: {{Han simp|諍|f=言|t=讠}}. Chữ gốc 諍 gồm 言 (ngôn — lời nói) biểu nghĩa và 争 (tranh) biểu âm/nghĩa bổ sung. Chỉ hành động can gián thẳng thắn — nói lời phản đối để giúp người sửa lỗi. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "can ngăn, khuyên can", "Hạng Tần Suất (Jun Da)": "4432.0", "Tần Suất % (Jun Da)": "99.8473065298", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 争", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠争", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "争", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诤", "Unihan_Traditional (Chữ Phồn thể)": "諍", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ đứng trước danh từ chỉ người được can ngăn hoặc làm danh từ chỉ lời can gián. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坳', '{"9000": "4433.0", "Chữ Trung Quốc": "坳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 幼 | ấu | biểu âm | 坳 = 土 (Thổ, biểu nghĩa: đất) + 幼 (Ấu, biểu âm); chữ hình thanh. Bộ 土 chỉ địa hình trũng xuống, 幼 cho âm đọc gần ào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ảo\": chỗ đất 土 ảo 坳 — lõm xuống như ảo ảnh, là ao hố tự nhiên trên địa hình. | Gương Hán-Việt | địa ảo (chỗ đất trũng) | Mở khoá kiến thức | Biết 坳 mở khoá từ 山坳 (thung lũng giữa núi) — địa hình phổ biến trong văn học và địa lý.", "Tự nguyên_Xie": "坳 là hình thanh: 土 (thổ — đất) biểu nghĩa, 幼 (ấu) biểu âm. Wiktionary xác nhận {{Han compound|土|幼|ls=psc|c1=s|c2=p|t1=earth}}. Nghĩa gốc là chỗ đất lõm, ao, hố — địa hình trũng xuống. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ đất trũng xuống, ao, hố", "Hạng Tần Suất (Jun Da)": "4433.0", "Tần Suất % (Jun Da)": "99.8474853375", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坳", "Unihan_Traditional (Chữ Phồn thể)": "㘭", "Pinyin_Xie": "ào", "Âm Hán Việt_Xie": "ao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ địa hình trũng, thường đứng sau các từ chỉ núi non để tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹭', '{"9000": "4434.0", "Chữ Trung Quốc": "鹭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鹭 | lộ | tượng hình | con cò, diệc | 鹭 là giản thể của 鷺, thay 鳥 bằng 鸟. Bộ 鸟 (điểu — chim) biểu nghĩa, phần trên biểu âm. Chỉ các loài chim cò, diệc (heron/egret) — chim lội nước trắng muốt quen thuộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộ\": con cò 鹭 (lộ) đứng lộ thiên — chim 鸟 trắng muốt đứng ven ao lộ hẳn ra giữa trời. | Gương Hán-Việt | lộ điểu (chim cò) | Mở khoá kiến thức | Biết 鹭 mở khoá từ 白鹭 (cò trắng/egret), 苍鹭 (diệc xám) và địa danh 厦门鹭岛.", "Tự nguyên_Xie": "鹭 là giản thể của 鷺: {{Han simp|鷺|f=鳥|t=鸟}}. Chữ gốc 鷺 gồm 鳥 (điểu — chim) biểu nghĩa, phần trên biểu âm. Chỉ các loài cò trắng (heron/egret) — hình ảnh quen thuộc trong thơ ca và tranh thủy mặc Trung Hoa. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cò", "Hạng Tần Suất (Jun Da)": "4434.0", "Tần Suất % (Jun Da)": "99.8476641451", "GavinGrover_Once (Chiết tự trực tiếp)": "路 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱路鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "路", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹭", "Unihan_Traditional (Chữ Phồn thể)": "鷺", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim, thường đi kèm lượng từ chỉ hoặc kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砷', '{"9000": "4435.0", "Chữ Trung Quốc": "砷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砷 | thân | tượng hình | nguyên tố asen, As | 砷 là chữ bộ 石 (thạch — đá/khoáng vật) kết hợp phần biểu âm 申, chỉ nguyên tố asen (As, số nguyên tử 33). Chữ tạo muộn để biểu thị nguyên tố hóa học. Bộ 石 biểu nghĩa chất khoáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thân\": asen 砷 (thân) — khoáng chất 石 độc hại nổi tiếng, âm đọc gần như thân (申). | Gương Hán-Việt | thân tố (nguyên tố asen) | Mở khoá kiến thức | Biết 砷 mở khoá thuật ngữ hóa học 砷化物 (arsenide), 砷中毒 (ngộ độc asen).", "Tự nguyên_Xie": "Chữ 砷 được tạo ra để biểu thị nguyên tố asen (Arsenic, As). Bộ 石 (thạch — đá/khoáng vật) biểu nghĩa, phần còn lại biểu âm. Wiktionary không cung cấp nguồn gốc cổ điển. Chữ tạo muộn cho thuật ngữ hóa học — chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố asen, As", "Hạng Tần Suất (Jun Da)": "4435.0", "Tần Suất % (Jun Da)": "99.8478429528", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 申", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石申", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "申", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砷", "Unihan_Traditional (Chữ Phồn thể)": "砷", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học, thường dùng trong văn bản khoa học hoặc y học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唏', '{"9000": "4436.0", "Chữ Trung Quốc": "唏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 希 | hy | biểu âm | 唏 = 口 (Khẩu, biểu nghĩa: miệng) + 希 (Hy, biểu âm); chữ hình thanh. Bộ 口 chỉ âm thanh phát ra từ miệng (tiếng thở dài, tiếng cười), 希 cho âm đọc gần xī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hơi\": miệng 口 thở hơi 唏 — tiếng hơi thở dài phát ra khi buồn bã hay thốt lên ngạc nhiên. | Gương Hán-Việt | hy thán (thở than) | Mở khoá kiến thức | Biết 唏 mở khoá từ 唏嘘 (tiếng thở dài thương cảm, than thở) — dùng phổ biến trong văn xuôi.", "Tự nguyên_Xie": "唏 là hình thanh: 口 (khẩu — miệng) biểu nghĩa, 希 (hy) biểu âm. Wiktionary xác nhận {{Han compound|口|希|ls=psc|t1=mouth|c1=s|c2=p}}. Nghĩa là thở dài, tiếng cười hoặc than thở — âm thanh phát ra qua miệng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "than thở", "Hạng Tần Suất (Jun Da)": "4436.0", "Tần Suất % (Jun Da)": "99.8480212437", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 希", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口希", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唏", "Unihan_Traditional (Chữ Phồn thể)": "唏", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi, hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Chữ này thường dùng làm động từ để diễn tả tiếng thở dài, than thở hoặc làm từ tượng thanh mô tả tiếng khóc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伲', '{"9000": "4437.0", "Chữ Trung Quốc": "伲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 伲 | ni | tượng hình | chúng mình, chúng tôi (phương ngữ Thượng Hải) | 伲 là chữ phương ngữ bộ 亻(nhân — người) kết hợp phần biểu âm, dùng trong tiếng Thượng Hải (Ngô ngữ) chỉ đại từ ''chúng mình/chúng tôi''. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ni\": chúng ni 伲 — trong tiếng Thượng Hải, 伲 là cách người 亻 nói ''bọn mình'' thân thiết. | Gương Hán-Việt | ngã ni (bọn tôi — phương ngữ) | Mở khoá kiến thức | Biết 伲 mở khoá đặc điểm phương ngữ Ngô (Thượng Hải) — giúp hiểu văn học và phim ảnh Thượng Hải.", "Tự nguyên_Xie": "Chữ 伲 là đại từ nhân xưng phương ngữ Ngô (Thượng Hải), nghĩa ''chúng mình/chúng tôi''. Bộ 亻 (nhân — người) biểu nghĩa liên quan đến con người. Wiktionary không cung cấp nguồn gốc. Chữ tạo muộn để ghi phương ngữ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chúng mình; chúng tôi", "Hạng Tần Suất (Jun Da)": "4437.0", "Tần Suất % (Jun Da)": "99.848198501", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 尼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻尼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伲", "Unihan_Traditional (Chữ Phồn thể)": "伲", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Chữ này là đại từ nhân xưng ngôi thứ nhất số nhiều dùng trong một số phương ngôn phía nam Trung Quốc. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猬', '{"9000": "4438.0", "Chữ Trung Quốc": "猬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sinh vật | 胃 | vị | biểu âm | 猬 = 虫 (Trùng, biểu nghĩa: sinh vật) + 胃 (Vị, biểu âm); chữ hình thanh. Bộ 虫 chỉ sinh vật nhỏ (ở đây là nhím), 胃 cho âm đọc gần wèi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": con nhím 猬 (vị) — sinh vật 虫 có dạ dày vị 胃 to, toàn thân phủ gai tua tủa. | Gương Hán-Việt | nhím vị (con nhím) | Mở khoá kiến thức | Biết 猬 mở khoá từ 刺猬 (con nhím) và thành ngữ 猬集 (tụ tập dày đặc như gai nhím).", "Tự nguyên_Xie": "猬 là hình thanh: 虫 (trùng — sinh vật) biểu nghĩa, 胃 (vị) biểu âm. Wiktionary xác nhận {{Han compound|虫|胃|ls=psc|c1=s|c2=p}}. Chữ chỉ con nhím (刺猬 cìwèi) — loài thú có gai. Nghĩa mở rộng: xúm xít, dày đặc (như gai nhím). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con dím, con nhím; xúm xít", "Hạng Tần Suất (Jun Da)": "4438.0", "Tần Suất % (Jun Da)": "99.8483757583", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 胃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭胃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猬", "Unihan_Traditional (Chữ Phồn thể)": "蝟", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài nhím, thường kết hợp với các chữ khác để chỉ các loài nhím cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琥', '{"9000": "4439.0", "Chữ Trung Quốc": "琥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 玉 | ngọc | biểu nghĩa | ngọc bích, đá quý | 虎 | hổ | biểu âm | 琥 = 玉/王 (Ngọc, biểu nghĩa: đá quý) + 虎 (Hổ, biểu âm); chữ hình thanh. Bộ 玉 chỉ vật liệu quý (hổ phách là nhựa cây hóa đá), 虎 cho âm đọc gần hǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hổ\": hổ phách 琥珀 — ngọc 玉 màu hổ (hổ hổ vàng cam) như mắt hổ đông đặc trong hàng triệu năm. | Gương Hán-Việt | hổ phách (amber) | Mở khoá kiến thức | Biết 琥 mở khoá từ 琥珀 (hổ phách/amber) — vật liệu quý trong trang sức và nghiên cứu khoa học.", "Tự nguyên_Xie": "琥 là hình thanh: 玉 (ngọc — đá quý) biểu nghĩa, 虎 (hổ) biểu âm. Wiktionary xác nhận {{Han compound|玉|虎|ls=psc|c1=s|c2=p|t1=jade}}. Chữ chỉ dùng trong từ 琥珀 (hổ phách — amber) — nhựa cây hóa thạch màu vàng cam quý giá. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hổ phách 琥珀)", "Hạng Tần Suất (Jun Da)": "4439.0", "Tần Suất % (Jun Da)": "99.8485530156", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 虎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王虎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琥", "Unihan_Traditional (Chữ Phồn thể)": "琥", "Pinyin_Xie": "hǔ", "Âm Hán Việt_Xie": "hổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ miếng ngọc khắc hình con hổ thời xưa hoặc dùng trong từ ghép hổ phách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殁', '{"9000": "4440.0", "Chữ Trung Quốc": "殁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 8 | nét | 殁 | một | tượng hình | chết, qua đời | 殁 là biến thể của 歿, bộ 歹 (đãi — xương/cái chết) kết hợp phần biểu âm. Chỉ cái chết trong văn ngôn trang trọng. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"một\": qua đời 殁 (một) — một người đã mất đi, không còn nữa, như ngọn đèn tắt lịm. | Gương Hán-Việt | tử một (qua đời) | Mở khoá kiến thức | Biết 殁 mở khoá từ văn ngôn 殁于 (mất vào năm), 病殁 (mất vì bệnh) trong văn bản lịch sử.", "Tự nguyên_Xie": "殁 là biến thể của 歿: ''Variant of 歿''. Chữ gốc 歿 gồm 歹 (đãi — xương/cái chết) biểu nghĩa. Dùng trong văn ngôn trang trọng chỉ cái chết — nhẹ nhàng hơn 死 (tử). Chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết, qua đời", "Hạng Tần Suất (Jun Da)": "4440.0", "Tần Suất % (Jun Da)": "99.8487302729", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 殳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殁", "Unihan_Traditional (Chữ Phồn thể)": "歿", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "một", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự qua đời, thường dùng trong văn viết trang trọng hoặc gia phả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚩', '{"9000": "4441.0", "Chữ Trung Quốc": "蚩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚩 | si | tượng hình | ngây ngô, ngu dại; tên riêng Xuy Vưu | 蚩 là chữ bộ 虫 (trùng) ở dưới kết hợp phần trên, chỉ sự ngây ngô, ngu dại. Cũng là tên của Xuy Vưu (蚩尤) — thủ lĩnh huyền thoại trong thần thoại Trung Hoa. Cấu trúc lsCodes chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": si ngốc 蚩 — chữ si (si mê/ngu dại) trong 蚩尤 (Xuy Vưu) người nổi tiếng là hung tợn và si cuồng. | Gương Hán-Việt | si ngốc (ngu dại) | Mở khoá kiến thức | Biết 蚩 mở khoá tên huyền thoại 蚩尤 (Xuy Vưu) trong thần thoại Trung Hoa và lịch sử cổ đại.", "Tự nguyên_Xie": "Chữ 蚩 chỉ sự ngu dốt, ngây ngô hoặc thô lỗ trong văn ngôn. Wiktionary xác nhận nghĩa ''ignorant, stupid, rude''. Nổi tiếng nhờ tên 蚩尤 (Xuy Vưu) — thần chiến tranh trong thần thoại Trung Hoa, đối thủ của Hoàng Đế. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngây ngô", "Hạng Tần Suất (Jun Da)": "4441.0", "Tần Suất % (Jun Da)": "99.8489075302", "GavinGrover_Once (Chiết tự trực tiếp)": "㞢 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㞢虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㞢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚩", "Unihan_Traditional (Chữ Phồn thể)": "蚩", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "xi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự ngây ngô, ngu muội hoặc dùng làm danh từ riêng trong truyền thuyết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泾', '{"9000": "4442.0", "Chữ Trung Quốc": "泾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泾 | kinh | tượng hình | tên sông Kinh, nhánh sông Vị | 泾 là chữ tượng hình / danh từ riêng chỉ tên sông Kinh (涇). Dạng giản thể từ 涇; bộ 氵(thủy) biểu nghĩa liên quan nước, phần còn lại 𢀖 vốn là 巠 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Kinh\": ba chấm nước 氵chảy về sông Kinh — con sông ranh giới nổi tiếng trong thành ngữ 泾渭分明. | Gương Hán-Việt | Kinh trong 泾渭分明 (Kinh Vị phân minh — ranh giới rõ ràng) | Mở khoá kiến thức | Biết 泾 mở khoá địa danh và thành ngữ 泾渭分明 — phân biệt rõ ràng như sông Kinh và sông Vị.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 泾 là dạng giản thể của 涇. Theo Wiktionary, chữ gốc 涇 là chữ hình thanh: bộ 氵(thủy, biểu nghĩa: nước) + 巠 (biểu âm). Nay dùng để chỉ sông Kinh ở tỉnh Cam Túc và Thiểm Tây, Trung Quốc — con sông nổi tiếng trong thành ngữ 泾渭分明 (Kinh Vị phân minh). Chữ tạo tương đối muộn, chưa rõ hình dạng trong giáp cốt văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kinh Hà (tên sông, bắt nguồn từ tỉnh Cam Túc, chảy vào tỉnh Thiểm Tây, Trung Quốc); huyện Kinh (ở tỉnh An Huy, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4442.0", "Tần Suất % (Jun Da)": "99.8490842707", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "泾", "Unihan_Traditional (Chữ Phồn thể)": "涇", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "kinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên sông Kinh Hà hoặc tên địa danh như huyện Kinh ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缥', '{"9000": "4443.0", "Chữ Trung Quốc": "缥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 糹 | mịch | biểu nghĩa | tơ, lụa | 票 | phiếu | biểu âm | (biểu âm gần piāo) | 缥 là chữ hình thanh: bộ 糹(mịch, biểu nghĩa: tơ lụa) + 票 (biểu âm, đọc gần piāo/piǎo). Nghĩa gốc là loại lụa màu xanh nhạt, sau mở rộng chỉ trạng thái mờ ảo, huyền diệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phiêu\": lụa 糹 bay phiêu piāo như tờ phiếu 票 trong gió — màu xanh nhạt huyền ảo, khó nắm bắt. | Gương Hán-Việt | Phiêu trong 縹緲 (phiêu diêu — hư ảo, mờ nhạt) | Mở khoá kiến thức | Biết 缥 mở khoá từ 缥缈/縹緲 (phiêu diêu) — dùng trong thơ ca chỉ cảnh vật mờ ảo.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缥 là dạng giản thể của 縹. Theo Wiktionary, chữ 縹 là chữ hình thanh (psc): bộ 糸 (tơ, biểu nghĩa) + 票 (biểu âm). Nghĩa gốc chỉ loại lụa màu xanh lam nhạt. Từ đó phát triển nghĩa bóng chỉ sự huyền ảo, mờ nhạt như trong 縹緲 (hư vô phiêu diêu). Chưa tìm thấy trong giáp cốt văn, hình ảnh tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mập mờ, huyền ảo", "Hạng Tần Suất (Jun Da)": "4443.0", "Tần Suất % (Jun Da)": "99.8492604944", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缥", "Unihan_Traditional (Chữ Phồn thể)": "縹", "Pinyin_Xie": "piāo", "Âm Hán Việt_Xie": "phiêu, phiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả màu xanh nhạt của lụa hoặc trạng thái mờ ảo, hư vô. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殓', '{"9000": "4444.0", "Chữ Trung Quốc": "殓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 11 | nét | 殓 | liệm | tượng hình | liệm xác người chết vào quan tài | 殓 là dạng giản thể của 殮. Chữ 殮 gồm bộ 歹 (歺, biểu nghĩa: xương, chết chóc) và phần biểu âm. Là chữ hình thanh liên quan đến tang lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Liệm\": bộ xương 歹 là dấu hiệu của cái chết — liệm xác vào quan tài là nghi lễ cuối cùng. | Gương Hán-Việt | Liệm trong 入殮 (nhập liệm — đặt thi hài vào quan tài), 收殮 (thu liệm) | Mở khoá kiến thức | Biết 殓 mở khoá từ 入殓 (nhập liệm), 大殓 (đại liệm) — nghi lễ tang ma Trung Quốc truyền thống.", "Tự nguyên_Xie": "殓 là dạng giản thể của 殮. Theo Wiktionary, chữ 殮 là chữ hình thanh: bộ 歹 (歺, biểu nghĩa: liên quan đến cái chết, xương người) + phần biểu âm liàn. Nghĩa là đặt thi hài vào quan tài để làm lễ mai táng. Dùng trong các từ như 入殮 (nhập liệm) và 收殮 (thu liệm). Chưa có dữ liệu giáp cốt hay kim văn cho chữ này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liệm xác", "Hạng Tần Suất (Jun Da)": "4444.0", "Tần Suất % (Jun Da)": "99.8494362014", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殓", "Unihan_Traditional (Chữ Phồn thể)": "殮", "Pinyin_Xie": "liàn", "Âm Hán Việt_Xie": "liệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ nghi thức khâm liệm người chết trước khi chôn cất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳅', '{"9000": "4445.0", "Chữ Trung Quốc": "鳅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳅 | thu | tượng hình | cá chạch, loài cá sống dưới bùn | 鳅 là dạng giản thể của 鰍. Chữ gốc 鰍 gồm bộ 魚 (ngư, biểu nghĩa: cá) + phần biểu âm qiū. Là chữ hình thanh chỉ loài cá chạch (loach).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thu\": bộ cá 鱼 + âm qiū — con cá chạch trơn tuột dưới bùn như bắt trượt tay. | Gương Hán-Việt | Thu trong 泥鳅 (nê thu — cá chạch bùn) | Mở khoá kiến thức | Biết 鳅 mở khoá từ 泥鳅 (nê thu — cá chạch) — loài cá quen thuộc trong ẩm thực Trung-Việt.", "Tự nguyên_Xie": "Lục thư thông | 鳅 là dạng giản thể của 鰍. Theo Wiktionary, chữ 鳅 đơn giản hoá từ 鰍 (thay 魚 bằng 鱼). Chữ 鰍 là hình thanh: bộ 魚 (ngư, cá) làm biểu nghĩa + phần biểu âm gần qiū. Cá chạch (泥鳅 ní qiū) là loài cá nhỏ sống trong bùn, thường dùng trong ẩm thực Á Đông. Chữ tạo tương đối muộn, chỉ thấy trong lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chạch; cá kì thu", "Hạng Tần Suất (Jun Da)": "4445.0", "Tần Suất % (Jun Da)": "99.8496119083", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳅", "Unihan_Traditional (Chữ Phồn thể)": "鰍", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá chạch sống ở bùn lầy, thường dùng trong từ ghép bùn thu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氰', '{"9000": "4446.0", "Chữ Trung Quốc": "氰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 12 | nét | 气 | khí | biểu nghĩa | khí, hơi | 青 | thanh | biểu âm | màu xanh (biểu âm qíng) | 氰 là chữ hình thanh: bộ 气 (khí, biểu nghĩa: khí thể) + 青 (thanh, biểu âm, đọc qīng gần qíng). Là ký tự hoá học tạo muộn để phiên âm \"cyanogen\" — chất khí độc CN₂.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thanh\": khí 气 màu xanh 青 — xyanogen (CN₂) là chất khí độc có mùi hạnh nhân đặc trưng. | Gương Hán-Việt | Thanh trong 氰化物 (thanh hoá vật — xyanua) | Mở khoá kiến thức | Biết 氰 mở khoá thuật ngữ hoá học 氰化物 (xyanua), 氢氰酸 (axit hydrocyanic) — thường gặp trong bài học hoá.", "Tự nguyên_Xie": "氰 là chữ hình thanh hiện đại (tân tạo để dùng trong hoá học): bộ 气 (khí, biểu nghĩa: khí thể) + 青 (thanh, biểu âm, đọc qīng gần với qíng trong tiếng Hán hiện đại). Chữ tạo để phiên âm từ \"cyanogen\" (xyanogen, CN₂) trong hoá học hiện đại. Chưa có nguồn giáp cốt hay kim văn. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất xyanogen (công thức hoá học: CN2)", "Hạng Tần Suất (Jun Da)": "4446.0", "Tần Suất % (Jun Da)": "99.8497870985", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氰", "Unihan_Traditional (Chữ Phồn thể)": "氰", "Pinyin_Xie": "qíng", "Âm Hán Việt_Xie": "tình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ trong hóa học hiện đại để chỉ hợp chất khí xyanogen hoặc gốc hóa học liên quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诋', '{"9000": "4447.0", "Chữ Trung Quốc": "诋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 诋 | để | tượng hình | vu cáo, phỉ báng, chửi mắng | 诋 là dạng giản thể của 詆. Chữ gốc 詆 gồm bộ 言 (ngôn, biểu nghĩa: lời nói) + phần biểu âm dǐ. Là chữ hình thanh chỉ hành vi vu cáo, phỉ báng bằng lời nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Để\": lời nói 讠nhọn như mũi tên dǐ — phỉ báng, bôi nhọ người khác. | Gương Hán-Việt | Để trong 诋毁 (để hủy — bôi nhọ, vu khống) | Mở khoá kiến thức | Biết 诋 mở khoá từ 诋毁 (để hủy — vu khống, bôi nhọ danh dự) — thường gặp trong ngữ cảnh pháp luật và tranh luận.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 诋 là dạng giản thể của 詆 (thay bộ 言 bằng 讠). Theo Wiktionary, chữ 诋/詆 có hình ảnh từ kim văn, tiểu triện và lục thư thông. Là chữ hình thanh: bộ 言 (ngôn, biểu nghĩa: lời nói) + phần biểu âm. Nghĩa là phỉ báng, mắng nhiếc, vu cáo người khác bằng lời. Dùng trong 诋毁 (để hủy — vu khống, bôi nhọ). Kim văn còn lưu lại hình dạng cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắng mỏ; vu cáo", "Hạng Tần Suất (Jun Da)": "4447.0", "Tần Suất % (Jun Da)": "99.8499622886", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诋", "Unihan_Traditional (Chữ Phồn thể)": "詆", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi nói xấu, phỉ báng người khác và thường mang tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刍', '{"9000": "4448.0", "Chữ Trung Quốc": "刍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彐 | Số nét | 5 | nét | 刍 | sô | tượng hình | tay cắt cỏ, bó cỏ làm thức ăn gia súc | 刍 là chữ tượng hình: hình ảnh bàn tay cầm và cắt cỏ. Trong giáp cốt văn và kim văn, chữ mô phỏng tay gặt cỏ từ đất. Nghĩa gốc là cắt cỏ làm thức ăn cho trâu ngựa. Chữ giản thể từ 芻.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Sô\": tượng hình tay cắt cỏ — từ 刍荛之见 (sô diêu chi kiến: ý kiến của người đốn củi cắt cỏ, dùng để khiêm tốn). | Gương Hán-Việt | Sô trong 刍议 (sô nghị — ý kiến khiêm tốn), 刍荛 (sô diêu — người cắt cỏ, đốn củi) | Mở khoá kiến thức | Biết 刍 mở khoá thành ngữ 刍荛之见 và từ 反刍 (phản sô — nhai lại, động vật nhai lại như trâu bò).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 刍 là dạng giản thể của 芻. Theo Wiktionary, chữ 芻 có hình ảnh từ giáp cốt văn, kim văn, bạch thư (lụa), đại triện và tiểu triện — là chữ có lịch sử từ rất sớm. Nguyên là tượng hình: hình bàn tay cắt cỏ. Nghĩa gốc là cắt cỏ, bó cỏ làm thức ăn trâu ngựa. Sau mở rộng chỉ cỏ, thức ăn gia súc. Thành ngữ 刍荛之见 (sô diêu chi kiến) nghĩa là ý kiến quê mùa, khiêm tốn tự hạ thấp mình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nuôi (trâu, ngựa) bằng cỏ", "Hạng Tần Suất (Jun Da)": "4448.0", "Tần Suất % (Jun Da)": "99.8501374788", "GavinGrover_Once (Chiết tự trực tiếp)": "⺈ + 彐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺈彐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺈", "Unihan_Simplified (Chữ Giản thể)": "刍", "Unihan_Traditional (Chữ Phồn thể)": "芻", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "sô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ cỏ khô hoặc động từ chỉ việc cắt cỏ nuôi súc vật trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芷', '{"9000": "4449.0", "Chữ Trung Quốc": "芷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芷 | chỉ | tượng hình | cây bạch chỉ, loại thảo dược | 芷 là chữ hình thanh: bộ 艸 (thảo, biểu nghĩa: cây cỏ) + 止 (chỉ, biểu âm, đọc zhǐ). Chỉ loài thảo dược angelica (bạch chỉ), thường dùng trong Đông y. Không có dữ liệu giáp cốt văn hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chỉ\": cỏ 艹 dừng 止 lại để ngửi — bạch chỉ (白芷) là thảo dược thơm ngát, mỗi lần đi ngang phải dừng lại. | Gương Hán-Việt | Chỉ trong 白芷 (bạch chỉ — vị thuốc Đông y), 蘭芷 (lan chỉ — lan và bạch chỉ trong thơ) | Mở khoá kiến thức | Biết 芷 mở khoá từ Đông y 白芷 (bạch chỉ) và thơ Sở Từ 蘭芷 — hai ngữ cảnh cổ điển quan trọng.", "Tự nguyên_Xie": "芷 là chữ hình thanh: bộ 艸 (thảo, biểu nghĩa: cây cỏ) + 止 (chỉ, biểu âm, đọc zhǐ, trùng âm). Theo Wiktionary, chữ chỉ loài cây angelica (Angelica dahurica), hay còn gọi là bạch chỉ (白芷) — một vị thuốc Đông y quan trọng dùng trị đau đầu, cảm lạnh, và lam thơm. Nổi tiếng trong thơ Sở Từ của Khuất Nguyên với hình ảnh 蘭芷 (lan chỉ — lan thơm và bạch chỉ). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bạch chỉ 白芷)", "Hạng Tần Suất (Jun Da)": "4449.0", "Tần Suất % (Jun Da)": "99.850312669", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 止", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "止", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芷", "Unihan_Traditional (Chữ Phồn thể)": "芷", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ một loài cỏ thơm dùng làm thuốc trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嶙', '{"9000": "4450.0", "Chữ Trung Quốc": "嶙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 15 | nét | 山 | sơn | biểu nghĩa | núi | 粦 | lân | biểu âm | (biểu âm, đọc lín) | 嶙 là chữ hình thanh: bộ 山 (sơn, biểu nghĩa: núi) + 粦 (lân, biểu âm, đọc lín). Chỉ núi non hiểm trở, cheo leo. Thường dùng trong từ 嶙峋 (lân tuân — núi đá lởm chởm, xương xẩu gầy gò).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lân\": núi 山 gầy như xương — 嶙峋 vẽ hình núi đá lởm chởm hoặc người gầy đến lộ xương sườn. | Gương Hán-Việt | Lân trong 嶙峋 (lân tuân — núi cheo leo, xương xẩu gầy gò) | Mở khoá kiến thức | Biết 嶙 mở khoá từ 嶙峋 — dùng cả cho địa hình và mô tả người gầy 瘦骨嶙峋 (xương xẩu gầy gò).", "Tự nguyên_Xie": "Tiểu triện | 嶙 là chữ hình thanh theo Wiktionary: bộ 山 (sơn, biểu nghĩa: núi) + 粦 (biểu âm, đọc lín). Nghĩa là núi non cheo leo, hiểm trở. Được biết nhiều qua từ 嶙峋 (lân tuân) mô tả núi đá lởm chởm hoặc người gầy xương xẩu. Còn có nghĩa 嶾嶙 (lǐn) trong phát âm thứ hai. Có hình ảnh tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lân tuân 嶙峋)", "Hạng Tần Suất (Jun Da)": "4450.0", "Tần Suất % (Jun Da)": "99.8504878591", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嶙", "Unihan_Traditional (Chữ Phồn thể)": "嶙", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ mô tả vẻ gồ ghề, lởm chởm của đất đá khi kết hợp thành từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逅', '{"9000": "4451.0", "Chữ Trung Quốc": "逅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 9 | nét | 辵 | xước | biểu nghĩa | đi, di chuyển | 后 | hậu | biểu âm | (biểu âm hòu/hòu) | 逅 là chữ hình thanh: bộ 辵 (xước, biểu nghĩa: di chuyển, đi đường) + 后 (hậu, biểu âm, đọc hòu). Chỉ sự gặp gỡ bất ngờ, không hẹn trước. Luôn dùng trong cặp 邂逅 (giải hậu — tình cờ gặp nhau).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hậu\": đường 辵 đi đến hậu 后 — gặp nhau không hẹn, như định mệnh đưa đẩy trong 邂逅. | Gương Hán-Việt | Hậu trong 邂逅 (giải hậu — tình cờ gặp nhau) | Mở khoá kiến thức | Biết 逅 mở khoá từ lãng mạn 邂逅 — gặp gỡ tình cờ, thường dùng trong văn học và thơ ca.", "Tự nguyên_Xie": "Tiểu triện | 逅 là chữ hình thanh theo Wiktionary: bộ 辵 (xước, biểu nghĩa: di chuyển) + 后 (hậu, biểu âm, đọc hòu). Có hình ảnh tiểu triện. Nghĩa là gặp gỡ bất ngờ, không hẹn. Chỉ dùng trong cặp 邂逅 (giải hậu), rất ít khi dùng độc lập. Là từ văn học mang sắc thái lãng mạn, định mệnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "không hẹn mà gặp", "Hạng Tần Suất (Jun Da)": "4451.0", "Tần Suất % (Jun Da)": "99.8506630493", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 后", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶后", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "后", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逅", "Unihan_Traditional (Chữ Phồn thể)": "逅", "Pinyin_Xie": "hòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị việc tình cờ gặp mặt, thường xuất hiện trong từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舫', '{"9000": "4452.0", "Chữ Trung Quốc": "舫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 10 | nét | 舟 | chu | biểu nghĩa | thuyền | 方 | phương | biểu âm | (biểu âm fāng/fǎng) | 舫 là chữ hình thanh: bộ 舟 (chu, biểu nghĩa: thuyền) + 方 (phương, biểu âm, đọc fāng gần fǎng). Chỉ loại thuyền sang trọng, du thuyền. Có hình ảnh tiểu triện và lục thư thông còn lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phương\": thuyền 舟 theo phương 方 — du thuyền sang trọng, thưởng ngoạn trên sông. | Gương Hán-Việt | Phương trong 画舫 (hoạ phương — thuyền hoa, thuyền trang trí đẹp) | Mở khoá kiến thức | Biết 舫 mở khoá từ 画舫 (hoạ phương — thuyền hoa), thường thấy trong văn học cổ điển và thơ Đường.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 舫 là chữ hình thanh theo Wiktionary: bộ 舟 (chu, biểu nghĩa: thuyền, ghe) + 方 (phương, biểu âm, đọc fāng). Nghĩa gốc là loại thuyền ghép đôi hoặc thuyền sang trọng. Sau chỉ thuyền nói chung, đặc biệt là du thuyền hay thuyền hoa được dùng để thưởng ngoạn. Có hình ảnh từ tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thuyền", "Hạng Tần Suất (Jun Da)": "4452.0", "Tần Suất % (Jun Da)": "99.8508382394", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舫", "Unihan_Traditional (Chữ Phồn thể)": "舫", "Pinyin_Xie": "fǎng", "Âm Hán Việt_Xie": "phảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại thuyền bè, đặc biệt là thuyền lớn dùng để dạo chơi trên sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呓', '{"9000": "4453.0", "Chữ Trung Quốc": "呓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 呓 | nghị | tượng hình | nói mê, nói sảng trong khi ngủ | 呓 là dạng giản thể của 囈. Chữ gốc 囈 gồm bộ 口 (khẩu, biểu nghĩa: miệng, lời nói) + phần biểu âm. Chỉ hành động nói mê, nói sảng khi đang ngủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nghị\": miệng 口 nói trong vô thức — 呓语 là những lời mê sảng, không có ý thức khi ngủ. | Gương Hán-Việt | Nghị trong 呓语 (nghị ngữ — nói mê, nói sảng) | Mở khoá kiến thức | Biết 呓 mở khoá từ 呓语 (nghị ngữ) — còn dùng ẩn dụ chỉ lời nói vô nghĩa, không tưởng.", "Tự nguyên_Xie": "呓 là dạng giản thể của 囈. Theo Wiktionary, chữ gốc 囈 là chữ hình thanh: bộ 口 (khẩu, miệng) biểu nghĩa + phần biểu âm. Nghĩa là nói mê, nói sảng khi ngủ (說夢話 shuō mènghuà). Thường dùng trong 呓语 (nghị ngữ — lời nói mê). Là chữ văn học, ít dùng trong văn thông thường. Chưa có nguồn học thuật chi tiết hơn về cấu trúc chữ này. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói mê, nói sảng", "Hạng Tần Suất (Jun Da)": "4453.0", "Tần Suất % (Jun Da)": "99.8510129128", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 艺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口艺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呓", "Unihan_Traditional (Chữ Phồn thể)": "囈", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động nói mê lúc ngủ hoặc làm danh từ chỉ lời nói sảng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唰', '{"9000": "4454.0", "Chữ Trung Quốc": "唰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 唰 | sát | tượng hình | tiếng xào xạc, rào rào (tượng thanh) | 唰 là chữ tượng thanh (onomatopeia): bộ 口 (khẩu, biểu nghĩa: âm thanh) + phần biểu âm shuā. Chỉ tiếng động xào xạc, rào rào như tiếng lá, tiếng nước chảy, tiếng lật trang sách nhanh. Không có dữ liệu etymologyAnchor từ Wiktionary. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Sát\": miệng 口 kêu \"shuā\" — tượng thanh tiếng xào xạc như lật trang sách hoặc tiếng mưa rào. | Gương Hán-Việt | Sát dùng ít trong tiếng Việt; 唰 chủ yếu là từ tượng thanh shuā trong tiếng Trung | Mở khoá kiến thức | Biết 唰 mở khoá cách diễn đạt âm thanh nhanh, đột ngột trong văn học và hội thoại hàng ngày.", "Tự nguyên_Xie": "唰 là chữ tượng thanh, không có nguồn Wiktionary chi tiết. Bộ 口 (khẩu) đóng vai trò gợi âm thanh; toàn bộ chữ mô phỏng tiếng xào xạc, rào rào hoặc tiếng cọ nhanh. Dùng như phó từ mô phỏng âm thanh: 唰地一声 (một tiếng xào xạc). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn, chưa có nguồn học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xào xạc; xào xào; rào rào", "Hạng Tần Suất (Jun Da)": "4454.0", "Tần Suất % (Jun Da)": "99.8511875862", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 刷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口刷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唰", "Unihan_Traditional (Chữ Phồn thể)": "唰", "Pinyin_Xie": "shuā", "Âm Hán Việt_Xie": "lạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô tả âm thanh nhanh, sắc như tiếng gió thổi qua lá hay tiếng nước chảy mạnh. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茁', '{"9000": "4455.0", "Chữ Trung Quốc": "茁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茁 | đốt | tượng hình | mầm cây nảy lên khỏi mặt đất, sinh sôi nảy nở | 茁 là chữ hình thanh: bộ 艸 (thảo, biểu nghĩa: cây cỏ) + phần biểu âm zhuó. Chỉ mầm cây nảy sinh, sinh sôi mạnh mẽ. Thường dùng trong 茁壮 (đốt tráng — khỏe mạnh, phát triển mạnh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đốt\": cỏ 艹 nảy đốt zhuó — từng đốt mầm vươn lên mạnh mẽ như 茁壮成长 (đốt tráng thành trưởng). | Gương Hán-Việt | Đốt trong 茁壮 (đốt tráng — khoẻ mạnh, phát triển tốt) | Mở khoá kiến thức | Biết 茁 mở khoá thành ngữ 茁壮成长 (đốt tráng thành trưởng — lớn lên khoẻ mạnh) — dùng phổ biến nói về trẻ em và cây cối.", "Tự nguyên_Xie": "茁 là chữ hình thanh: bộ 艸 (thảo, biểu nghĩa: cây cỏ) + phần biểu âm đọc zhuó. Theo Wiktionary, chữ dùng trong các từ 茁壮 (đốt tráng), 茁長 (đốt trưởng — lớn lên mạnh mẽ). Có thể liên quan đến hình ảnh mầm non vươn ra khỏi đất. Chưa tìm thấy chi tiết nguồn gốc học thuật cụ thể; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nảy mầm; sinh sôi, nảy nở", "Hạng Tần Suất (Jun Da)": "4455.0", "Tần Suất % (Jun Da)": "99.8513617428", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茁", "Unihan_Traditional (Chữ Phồn thể)": "茁", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "truất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ mô tả trạng thái cây cối hoặc động vật non đang phát triển khỏe mạnh, mập mạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馑', '{"9000": "4456.0", "Chữ Trung Quốc": "馑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 馑 | cận | tượng hình | nạn đói, mất mùa rau cỏ | 馑 là dạng giản thể của 饉. Chữ gốc 饉 gồm bộ 食 (thực, biểu nghĩa: thức ăn) + phần biểu âm jǐn. Là chữ hình thanh chỉ nạn đói do mất mùa rau cỏ. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cận\": thức ăn 食 gần 饉 cạn — nạn đói 饑饉 (cơ cận) là khi lương thực và rau cỏ đều cạn kiệt. | Gương Hán-Việt | Cận trong 饑饉 (cơ cận — nạn đói), 饑饉之歲 (cơ cận chi tuế — năm nạn đói) | Mở khoá kiến thức | Biết 馑 mở khoá từ 饥馑 (cơ cận — đói kém, nạn đói) — thường gặp trong lịch sử và văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 馑 là dạng giản thể của 饉. Theo Wiktionary, chữ 饉 là chữ có ghi chép từ cổ đại (fossil word): bộ 食 (thực, thức ăn) + phần biểu âm. Theo Thuyết Văn Giải Tự, 饑 (cơ) chỉ mất mùa ngũ cốc còn 饉 (cận) chỉ mất mùa rau cỏ — tuy nhiên sự phân biệt này không được kiểm chứng trong văn bản cổ. Nay 饑饉 (cơ cận) dùng chung chỉ nạn đói lớn. Có hình ảnh tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết đói; chôn", "Hạng Tần Suất (Jun Da)": "4456.0", "Tần Suất % (Jun Da)": "99.8515358994", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 堇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣堇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馑", "Unihan_Traditional (Chữ Phồn thể)": "饉", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ nạn đói hoặc làm tính từ mô tả tình trạng mất mùa, thiếu lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妫', '{"9000": "4457.0", "Chữ Trung Quốc": "妫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 妫 | quy | tượng hình | tên sông Quy; họ Quy (tên riêng) | 妫 là dạng giản thể của 嬀. Chữ gốc 嬀 gồm bộ 女 (nữ, biểu nghĩa: phụ nữ, hoặc dùng trong họ người) + phần biểu âm guī. Là tên riêng (tên sông, họ người) ở Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quy\": bộ nữ 女 mang tên guī — sông Quy và họ Quy gắn với hậu duệ của vua Thuấn trong lịch sử. | Gương Hán-Việt | Quy trong 妫姓 (quy tính — họ Quy, một trong những họ cổ nhất Trung Quốc) | Mở khoá kiến thức | Biết 妫 mở khoá 妫姓 (họ Quy) và 妫水 (sông Quy) — kiến thức lịch sử và văn hoá Trung Quốc.", "Tự nguyên_Xie": "妫 là dạng giản thể của 嬀. Theo Wiktionary, 嬀 liên quan đến 媯, đều là tên sông và họ người. Bộ 女 (nữ) trong các chữ tên riêng đôi khi mang tính quy ước chứ không phải luôn chỉ phụ nữ. Sông妫/嬀 ở tỉnh Hà Bắc (nay là sông Yongding thượng lưu). Họ Guī (妫) là một trong những họ cổ nhất Trung Quốc, gắn với hậu duệ vua Thuấn. Chưa có chi tiết etymology học thuật cụ thể; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Quy (ở tỉnh Hà Bắc của Trung Quốc); họ Quy", "Hạng Tần Suất (Jun Da)": "4457.0", "Tần Suất % (Jun Da)": "99.851710056", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 为", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女为", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "为", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妫", "Unihan_Traditional (Chữ Phồn thể)": "媯", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng làm họ người hoặc tên của một con sông cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骧', '{"9000": "4458.0", "Chữ Trung Quốc": "骧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 20 | nét | 骧 | tương | tượng hình | ngựa phi nước đại, ngẩng đầu cao | 骧 là dạng giản thể của 驤. Chữ gốc 驤 gồm bộ 馬 (mã, biểu nghĩa: ngựa) + phần biểu âm xiāng. Là chữ hình thanh chỉ ngựa phi nước đại trong tư thế hùng dũng, ngẩng đầu cao. Có hình ảnh tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tương\": ngựa 马 ngẩng cao đầu xiāng — 龙骧虎步 (long tương hổ bộ) mô tả tư thế oai phong như rồng. | Gương Hán-Việt | Tương trong 龙骧虎步 (long tương hổ bộ — dáng đi oai phong), 腾骧 (đằng tương — phi vọt lên) | Mở khoá kiến thức | Biết 骧 mở khoá thành ngữ 龙骧虎步 (long tương hổ bộ) và 云起龙骧 — hình ảnh oai phong trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 骧 là dạng giản thể của 驤. Theo Wiktionary, chữ 驤 là chữ hình thanh: bộ 馬 (mã, ngựa) biểu nghĩa + phần biểu âm đọc xiāng. Nghĩa là phi nước đại (gallop), ngẩng đầu cao. Dùng trong các thành ngữ 龍驤虎步 (long tương hổ bộ — bước đi oai phong như rồng và hổ), 龍驤虎視 (long tương hổ thị). Có hình ảnh từ tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa chạy nhanh mà cất cao đầu", "Hạng Tần Suất (Jun Da)": "4458.0", "Tần Suất % (Jun Da)": "99.8518842126", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骧", "Unihan_Traditional (Chữ Phồn thể)": "驤", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mô tả tư thế ngựa ngẩng cao đầu chạy nhanh hoặc ẩn dụ cho sự bay lượn, vươn lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苷', '{"9000": "4459.0", "Chữ Trung Quốc": "苷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cây cỏ | 甘 | cam | biểu âm | ngọt (biểu âm gān) | 苷 là chữ hình thanh: bộ 艹 (thảo, biểu nghĩa: thực vật) + 甘 (cam, biểu âm, đọc gān). Chỉ hợp chất glucoside trong thực vật, hay còn gọi là cam thảo (licorice). Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cam\": cỏ 艹 ngọt như 甘 — cây cam thảo ngọt, nguồn của các hợp chất glycoside trong Đông y. | Gương Hán-Việt | Cam trong 苷类 (cam loại — nhóm glycoside), gần với 甘草 (cam thảo — licorice) | Mở khoá kiến thức | Biết 苷 mở khoá thuật ngữ hoá học và Đông y: 苷类 (glycoside), 强心苷 (cardiac glycoside), 黄酮苷 (flavonoid glycoside).", "Tự nguyên_Xie": "Tiểu triện | 苷 là chữ hình thanh theo Wiktionary: bộ 艸 (thảo, biểu nghĩa: thực vật, cỏ cây) + 甘 (cam, biểu âm, đọc gān). Nghĩa gốc chỉ cây cam thảo (licorice). Trong hoá học hiện đại, 苷 (glycoside) là tên gọi chung cho các hợp chất đường kết hợp với phần phi đường trong tự nhiên. Có hình ảnh tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất glucô", "Hạng Tần Suất (Jun Da)": "4459.0", "Tần Suất % (Jun Da)": "99.8520578524", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苷", "Unihan_Traditional (Chữ Phồn thể)": "苷", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ trong hóa học hiện đại để chỉ các hợp chất glucozit hoặc dùng chỉ cam thảo trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擢', '{"9000": "4460.0", "Chữ Trung Quốc": "擢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 17 | nét | 擢 | trạc | tượng hình | nhấc lên, đề bạt, chọn lựa | 擢 là chữ hình thanh: bộ 手/扌 (thủ, biểu nghĩa: tay) + phần biểu âm zhuó. Chỉ hành động kéo lên, nhấc lên, hoặc đề bạt ai đó lên chức vụ cao hơn. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Trạc\": tay 扌kéo zhuó lên — 擢升 là đề bạt ai đó, tay nâng người tài lên địa vị cao. | Gương Hán-Việt | Trạc trong 擢升 (trạc thăng — thăng chức), 拔擢 (bạt trạc — đề bạt nhân tài) | Mở khoá kiến thức | Biết 擢 mở khoá từ trang trọng 擢升 (thăng chức) và 拔擢 (đề bạt) — thường dùng trong văn bản hành chính và lịch sử.", "Tự nguyên_Xie": "Tiểu triện | 擢 là chữ hình thanh theo Wiktionary: bộ 手 (thủ, bàn tay) biểu nghĩa + phần biểu âm đọc zhuó. Nghĩa gốc là kéo lên, nhấc lên. Mở rộng sang nghĩa chọn lựa, đề bạt nhân tài lên vị trí cao. Dùng trong 擢升 (trạc thăng — thăng chức, đề bạt) và 拔擢 (bạt trạc — chọn lọc, bổ nhiệm). Có hình ảnh tiểu triện còn lưu. Chữ thuần văn học, ít dùng trong văn thông thường. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhấc lên; bỏ đi", "Hạng Tần Suất (Jun Da)": "4460.0", "Tần Suất % (Jun Da)": "99.8522314922", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 翟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擢", "Unihan_Traditional (Chữ Phồn thể)": "擢", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ để chỉ hành động cất nhắc cán bộ hoặc kéo vật gì đó lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峋', '{"9000": "4461.0", "Chữ Trung Quốc": "峋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 9 | nét | 峋 | tuân | tượng hình | dãy núi lởm chởm, cheo leo | 峋 là chữ hình thanh: bộ 山 (sơn, biểu nghĩa: núi) + phần biểu âm xún. Chỉ núi non cheo leo, lởm chởm. Luôn dùng trong cặp 嶙峋 (lân tuân — núi đá lởm chởm, xương xẩu) với chữ 嶙.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tuân\": núi 山 dàng 峋 — 嶙峋 gợi hình ảnh xương núi nhô ra, hoặc người gầy đến lộ xương. | Gương Hán-Việt | Tuân trong 嶙峋 (lân tuân — lởm chởm), 傲骨嶙峋 (ngạo cốt lân tuân — cứng đầu, kiên cường) | Mở khoá kiến thức | Biết 峋 mở khoá cặp 嶙峋 — dùng cả cho địa hình núi và tính cách con người trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 峋 là chữ hình thanh theo Wiktionary: bộ 山 (sơn, biểu nghĩa: núi) + phần biểu âm đọc xún. Chỉ dùng trong kết hợp 嶙峋 (lân tuân) — mô tả núi đá lởm chởm hoặc người gầy xương lộ ra. Có hình ảnh tiểu triện còn lưu. Cặp chữ 嶙峋 xuất hiện nhiều trong thơ miêu tả cảnh núi non. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lân tuân 嶙峋)", "Hạng Tần Suất (Jun Da)": "4461.0", "Tần Suất % (Jun Da)": "99.852405132", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峋", "Unihan_Traditional (Chữ Phồn thể)": "峋", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ trong từ ghép để miêu tả hình dáng núi non hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袂', '{"9000": "4462.0", "Chữ Trung Quốc": "袂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 袂 | quyết | tượng hình | ống tay áo (cổ điển) | 袂 là chữ hình thanh: bộ 衣 (y, biểu nghĩa: quần áo) + phần biểu âm mèi. Chỉ ống tay áo (sleeve) trong trang phục cổ điển. Thường gặp trong thành ngữ 分袂 (phân quyết — chia tay, tạm biệt) và 联袂 (liên quyết — cùng nhau thực hiện).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quyết\": áo y 衣 tay dài — phân袂 là khoảnh khắc buông tay áo nhau mà chia tay, lưu luyến. | Gương Hán-Việt | Quyết trong 分袂 (phân quyết — chia tay), 联袂 (liên quyết — cùng nhau) | Mở khoá kiến thức | Biết 袂 mở khoá từ trang trọng 分袂 (chia tay lưu luyến) và 联袂 (cùng nhau thực hiện — thường dùng trong văn nghệ).", "Tự nguyên_Xie": "Tiểu triện | 袂 là chữ hình thanh theo Wiktionary: bộ 衣 (y, quần áo) biểu nghĩa + phần biểu âm mèi. Nghĩa là ống tay áo dài của y phục cổ điển. Hành động 分袂 (phân quyết) vốn có nghĩa đen là hai người cầm tay áo nhau rồi chia lìa, sau mang nghĩa chia tay, tạm biệt. Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tay áo", "Hạng Tần Suất (Jun Da)": "4462.0", "Tần Suất % (Jun Da)": "99.8525787718", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袂", "Unihan_Traditional (Chữ Phồn thể)": "袂", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "duệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò danh từ làm tân ngữ trong câu hoặc kết hợp để chỉ bộ phận trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懑', '{"9000": "4463.0", "Chữ Trung Quốc": "懑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 17 | nét | 懑 | muộn | tượng hình | buồn bã, phiền muộn trong lòng | 懑 là dạng giản thể của 懣. Chữ gốc 懣 gồm bộ 心 (tâm, biểu nghĩa: tâm trạng, cảm xúc) + phần biểu âm mèn. Là chữ hình thanh chỉ trạng thái nặng nề trong lòng, phiền muộn, bực bội. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Muộn\": lòng 心 nặng mèn — 憤懣 là cảm giác bực bội uất ức không thoát ra được. | Gương Hán-Việt | Muộn trong 憤懣 (phẫn muộn — tức giận bực bội), 怨懣 (oán muộn) | Mở khoá kiến thức | Biết 懑 mở khoá từ 憤懣 (phẫn muộn — uất ức, bực bội) — diễn đạt cảm xúc tiêu cực mạnh mẽ trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 懑 là dạng giản thể của 懣. Theo Wiktionary, chữ 懣 là chữ hình thanh: bộ 心 (tâm, trái tim/tâm trạng) biểu nghĩa + phần biểu âm mèn. Nghĩa là buồn bã, phiền muộn, bực bội trong lòng. Dùng trong 憤懣 (phẫn muộn — tức giận và bực bội), 怨懣 (oán muộn — oán hận). Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buồn bã", "Hạng Tần Suất (Jun Da)": "4463.0", "Tần Suất % (Jun Da)": "99.8527518948", "GavinGrover_Once (Chiết tự trực tiếp)": "满 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱满心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "满", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "懑", "Unihan_Traditional (Chữ Phồn thể)": "懣", "Pinyin_Xie": "mèn", "Âm Hán Việt_Xie": "muộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả tâm trạng u uất hoặc làm danh từ chỉ sự phẫn uất trong lòng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓑', '{"9000": "4464.0", "Chữ Trung Quốc": "蓑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓑 | toa | tượng hình | áo tơi làm từ cỏ/cói | 蓑 là chữ hình thanh: bộ 艸 (thảo, biểu nghĩa: cây cỏ) + phần biểu âm suō. Chỉ áo tơi truyền thống làm từ cỏ hoặc cói, dùng che mưa. Chỉ thấy trong lục thư thông, không có giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Toa\": cỏ 艹 che suō — áo tơi bện từ cỏ, hình ảnh người ngư ông mặc áo tơi đội nón lá trong mưa. | Gương Hán-Việt | Toa trong 蓑衣 (toa y — áo tơi), 蓑笠 (toa lạp — áo tơi và nón lá) | Mở khoá kiến thức | Biết 蓑 mở khoá thơ Đường 孤舟蓑笠翁 (Liễu Tông Nguyên) và từ 蓑衣 (áo tơi) trong văn học cổ điển.", "Tự nguyên_Xie": "Lục thư thông | 蓑 là chữ hình thanh theo Wiktionary: bộ 艸 (thảo, cỏ cây) biểu nghĩa + phần biểu âm đọc suō. Nghĩa là áo tơi (rain coat) làm từ cỏ, cói, hoặc rơm. Nổi tiếng trong câu thơ Đường nổi tiếng 孤舟蓑笠翁 (cô chu toa lạp ông — ông già đơn độc trên thuyền, mặc áo tơi đội nón lá). Chỉ thấy trong lục thư thông, không có hình ảnh cổ xưa hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1196.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Suy (1195)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ/chỉ ý) ở trên chữ Thôi/Suy (số 1195 - áo tang/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thôi chỉ âm, bộ Thảo chỉ ý. Soa là cái áo tơi làm bằng cỏ lá để che mưa, dùng trong nông nghiệp.", "Nghĩa Tiếng Việt_Xie": "áo tơi", "Hạng Tần Suất (Jun Da)": "4464.0", "Tần Suất % (Jun Da)": "99.852924501", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 衰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹衰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓑", "Unihan_Traditional (Chữ Phồn thể)": "簑", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "toa, thoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại áo mưa truyền thống, thường đứng sau lượng từ hoặc làm tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涞', '{"9000": "4465.0", "Chữ Trung Quốc": "涞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 涞 | thui | tượng hình | tên sông Lai ở tỉnh Hà Bắc | 涞 là dạng giản thể của 淶. Chữ gốc 淶 gồm bộ 水/氵 (thủy, biểu nghĩa: nước, sông) + phần biểu âm lái. Là tên riêng chỉ sông Lai (涞水) ở tỉnh Hà Bắc, Trung Quốc. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thui\": nước 氵chảy về lái — sông Lai (涞水) ở Hà Bắc, Trung Quốc, tên địa lý đặc thù. | Gương Hán-Việt | Thui trong 涞水 (thui thủy — sông Lai, địa danh Hà Bắc) | Mở khoá kiến thức | Biết 涞 chủ yếu hữu ích cho địa lý Trung Quốc: 涞源 (huyện Lai Nguyên) và 涞水 (huyện Lai Thủy) ở Bảo Định, Hà Bắc.", "Tự nguyên_Xie": "Tiểu triện | 涞 là dạng giản thể của 淶. Theo Wiktionary, chữ 淶 gồm bộ 水 (thủy, biểu nghĩa: nước) + phần biểu âm lai. Là tên sông Lai (涞水) và địa danh 涞源、涞水 ở tỉnh Hà Bắc. Hán Việt đọc là ''thui'' — khá hiếm và không phổ biến trong từ vựng thông thường. Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Lai", "Hạng Tần Suất (Jun Da)": "4465.0", "Tần Suất % (Jun Da)": "99.8532691967", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 来", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵来", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "来", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涞", "Unihan_Traditional (Chữ Phồn thể)": "淶", "Pinyin_Xie": "lái", "Âm Hán Việt_Xie": "lai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ riêng dùng làm địa danh, thường đi kèm với các từ chỉ sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祉', '{"9000": "4466.0", "Chữ Trung Quốc": "祉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 8 | nét | 示 | thị | biểu nghĩa | bàn thờ, thần linh | 止 | chỉ | biểu âm | (biểu âm zhǐ) | 祉 là chữ hình thanh: bộ 示 (thị, biểu nghĩa: bàn thờ, ân huệ từ thần linh) + 止 (chỉ, biểu âm, đọc zhǐ). Nghĩa là phúc lành, hạnh phúc do thần linh ban tặng. Thường dùng trong 福祉 (phúc chỉ — phúc lợi, hạnh phúc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chỉ\": thần 示 dừng zhǐ lại ban phúc — 福祉 là điều tốt lành thần linh dừng lại trao cho người. | Gương Hán-Việt | Chỉ trong 福祉 (phúc chỉ — phúc lợi, hạnh phúc) | Mở khoá kiến thức | Biết 祉 mở khoá từ quan trọng 福祉 (phúc lợi, hạnh phúc) — dùng phổ biến trong chính sách xã hội và văn bản trang trọng.", "Tự nguyên_Xie": "祉 là chữ hình thanh theo Wiktionary: bộ 示 (thị, biểu nghĩa: bàn thờ, ân huệ thần) + 止 (chỉ, biểu âm, đọc zhǐ). Nghĩa là hạnh phúc, phúc lành, may mắn được ban tặng từ thần linh. Phổ biến nhất trong từ 福祉 (phúc chỉ — phúc lợi, hạnh phúc). Cũng dùng trong 祉祿 (chỉ lộc), 休祉 (hưu chỉ). Không có hình ảnh cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc", "Hạng Tần Suất (Jun Da)": "4466.0", "Tần Suất % (Jun Da)": "99.8534412862", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 止", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "止", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祉", "Unihan_Traditional (Chữ Phồn thể)": "祉", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong các từ ghép mang ý nghĩa chúc tụng, cầu may mắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踹', '{"9000": "4467.0", "Chữ Trung Quốc": "踹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 踹 | suyễn | tượng hình | đá mạnh, giẫm đạp | 踹 là chữ hình thanh: bộ 足 (túc, biểu nghĩa: chân) + phần biểu âm chuài/zhuì. Chỉ hành động đá mạnh bằng chân hoặc giẫm đạp. Thường dùng trong văn nói và văn thông thường. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Suyễn\": chân 足 đá chuài — 踹 là cú đá mạnh bằng gót chân, tiếng chuài vang. | Gương Hán-Việt | Suyễn trong 踹门 (suyễn môn — đá cửa mở toang) | Mở khoá kiến thức | Biết 踹 mở khoá từ hành động mạnh mẽ: 踹门 (đá cửa), 踹飞 (đá bay) — thường gặp trong mô tả hành động trong văn và phim.", "Tự nguyên_Xie": "踹 là chữ hình thanh theo Wiktionary: bộ 足 (túc, chân) biểu nghĩa + phần biểu âm đọc chuài. Nghĩa là đá mạnh bằng gót hoặc bàn chân (kick), giẫm (trample). Dùng phổ biến trong tiếng Trung thông thường, không phải chữ văn học. Chưa có chi tiết cấu trúc học thuật đầy đủ; chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá; giẫm; đạp; hủy hoại; phá hoại; phá hỏng", "Hạng Tần Suất (Jun Da)": "4467.0", "Tần Suất % (Jun Da)": "99.8536133756", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踹", "Unihan_Traditional (Chữ Phồn thể)": "踹", "Pinyin_Xie": "chuài", "Âm Hán Việt_Xie": "suỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động của chân, thường mang theo tân ngữ chỉ đối tượng bị tác động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chuài | / | đá | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掇', '{"9000": "4468.0", "Chữ Trung Quốc": "掇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 手 | thủ | biểu nghĩa | tay | 叕 | chuyết | biểu âm | (biểu âm duō/zhuó) | 掇 là chữ hình thanh: bộ 手 (thủ, biểu nghĩa: tay) + 叕 (chuyết, biểu âm, đọc zhuó). Chỉ hành động nhặt lên, hứng lấy, thu thập bằng tay. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Suốt\": tay 手 nhặt duō — 拾掇 (thập suốt) là thu dọn, sắp xếp lại những thứ vương vãi. | Gương Hán-Việt | Suốt trong 拾掇 (thập suốt — dọn dẹp, thu gom), 掇拾 (suốt thập) | Mở khoá kiến thức | Biết 掇 mở khoá từ thông dụng 拾掇 (dọn dẹp, thu gom) — dùng phổ biến trong tiếng Trung phương Bắc.", "Tự nguyên_Xie": "Tiểu triện | 掇 là chữ hình thanh theo Wiktionary: bộ 手 (thủ, biểu nghĩa: bàn tay) + 叕 (biểu âm, đọc zhuó). Nghĩa gốc là nhặt lên, hứng lấy bằng tay. Mở rộng sang nghĩa thu thập, chọn lựa. Dùng trong 拾掇 (thập suốt — dọn dẹp, thu gom), 掇拾 (suốt thập — lượm nhặt). Có hình ảnh tiểu triện còn lưu. Hán-Việt đọc là ''suốt'' theo slug. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhặt lấy; hứng lấy; cướp bóc; chọn lựa; đâm, xiên", "Hạng Tần Suất (Jun Da)": "4468.0", "Tần Suất % (Jun Da)": "99.8537844315", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掇", "Unihan_Traditional (Chữ Phồn thể)": "掇", "Pinyin_Xie": "duō", "Âm Hán Việt_Xie": "xuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động thu dọn, nhặt nhạnh đồ vật hoặc cất nhắc nhân sự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沏', '{"9000": "4469.0", "Chữ Trung Quốc": "沏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thủy | biểu nghĩa | nước | 切 | tiết | biểu âm | (biểu âm qiē/qī) | 沏 là chữ hình thanh: bộ 氵(thủy, biểu nghĩa: nước) + 切 (tiết, biểu âm, đọc qiē gần qī). Nghĩa là pha trà bằng nước sôi. Dùng trong 沏茶 (tiết trà — pha trà). Có thêm hai cách đọc: qū (rưới dầu nóng) và qiè (tiếng nước bắn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tiết\": nước 氵cắt qī vào trà — 沏茶 là rót nước nóng vào tách, pha trà thơm ngon. | Gương Hán-Việt | Tiết trong 沏茶 (tiết trà — pha trà) | Mở khoá kiến thức | Biết 沏 mở khoá từ thực dụng 沏茶 (pha trà) và cách nói lịch sự 沏一杯茶 (pha một tách trà) — cần thiết khi mô tả nghi lễ trà Trung Quốc.", "Tự nguyên_Xie": "沏 là chữ hình thanh theo Wiktionary: bộ 水 (thủy, nước, viết tắt 氵) biểu nghĩa + 切 (tiết/thiết, biểu âm, đọc qī). Nghĩa chính là pha, ngâm (trà) bằng nước nóng. Cũng dùng nghĩa rưới dầu nóng (qū) và tiếng nước bắn ra (qiè). Phổ biến nhất trong 沏茶 (pha trà). Chưa có hình ảnh cổ đại; chữ tạo tương đối muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "pha (trà) bằng nước sôi", "Hạng Tần Suất (Jun Da)": "4469.0", "Tần Suất % (Jun Da)": "99.8539554874", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 切", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵切", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "切", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沏", "Unihan_Traditional (Chữ Phồn thể)": "沏", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm với danh từ chỉ trà để diễn tả hành động pha chế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qī | / | pha | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诳', '{"9000": "4470.0", "Chữ Trung Quốc": "诳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 诳 | cuồng | tượng hình | lừa dối, nói dối, đánh lừa | 诳 là dạng giản thể của 誑. Chữ gốc 誑 gồm bộ 言 (ngôn, biểu nghĩa: lời nói) + phần biểu âm kuáng. Là chữ hình thanh chỉ hành động lừa dối, nói dối. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cuồng\": lời 讠cuồng kuáng — nói dối điên cuồng, đánh lừa người khác bằng ngôn từ. | Gương Hán-Việt | Cuồng trong 欺诳 (khi cuồng — lừa gạt), 诳言 (cuồng ngôn — lời nói dối) | Mở khoá kiến thức | Biết 诳 mở khoá từ văn học 欺诳 và 诳语 (cuồng ngữ — lời nói dối) — thường thấy trong văn bản cổ điển và tôn giáo (Phật giáo có 妄语/诳语).", "Tự nguyên_Xie": "Tiểu triện | 诳 là dạng giản thể của 誑. Theo Wiktionary, chữ 誑 là chữ hình thanh: bộ 言 (ngôn, lời nói) biểu nghĩa + phần biểu âm đọc kuáng. Nghĩa là lừa dối, nói dối, đánh lừa. Dùng trong 欺诳 (khi cuồng — lừa gạt), 诳言 (cuồng ngôn — lời nói dối). Là chữ văn học, ít dùng trong văn thông thường so với 骗 (piàn). Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lừa dối, nói dối", "Hạng Tần Suất (Jun Da)": "4470.0", "Tần Suất % (Jun Da)": "99.8541265433", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 狂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠狂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诳", "Unihan_Traditional (Chữ Phồn thể)": "誑", "Pinyin_Xie": "kuáng", "Âm Hán Việt_Xie": "cuống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành vi lừa dối người khác hoặc làm danh từ chỉ lời nói dối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噫', '{"9000": "4471.0", "Chữ Trung Quốc": "噫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh từ miệng | 意 | ý | biểu âm | (biểu âm yì/yī) | 噫 là chữ hình thanh: bộ 口 (khẩu, biểu nghĩa: miệng, âm thanh) + 意 (ý, biểu âm, đọc yì gần yī). Có hai nghĩa chính: thán từ biểu đạt buồn tiếc/ngạc nhiên (yī), và ợ hơi (ài). Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ý\": miệng 口 bật lên ý yī — tiếng than 噫！của Khổng Tử khi mất học trò yêu Nhan Hồi. | Gương Hán-Việt | Ý trong 噫嗚 (ý ô — ôi ô, than vãn), 噫嘻 (ý hi — thán từ) | Mở khoá kiến thức | Biết 噫 mở khoá ngữ cảnh Luận Ngữ và văn học cổ điển, cũng như tiếng ợ hơi (噫气) trong y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | 噫 là chữ hình thanh theo Wiktionary: bộ 口 (khẩu, miệng) biểu nghĩa + 意 (ý, biểu âm, đọc yì). Có nhiều cách đọc: yī (thán từ — ôi, chao!), ài (ợ hơi), yì (liên từ cổ). Nổi tiếng qua câu trong Luận Ngữ: 噫！天喪予！ (Ôi! Trời phá ta!) — Khổng Tử than khi Nhan Hồi mất. Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôi, chao (thán từ)", "Hạng Tần Suất (Jun Da)": "4471.0", "Tần Suất % (Jun Da)": "99.8542975991", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 意", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口意", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "意", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噫", "Unihan_Traditional (Chữ Phồn thể)": "噫", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Chữ này thường đứng đầu câu để biểu thị sự cảm thán, ngạc nhiên hoặc thở dài. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饽', '{"9000": "4472.0", "Chữ Trung Quốc": "饽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 10 | nét | 饽 | bột | tượng hình | bánh bột, bánh bao; bọt trà | 饽 là dạng giản thể của 餑. Chữ gốc 餑 gồm bộ 食 (thực, biểu nghĩa: thức ăn) + phần biểu âm bō. Là chữ hình thanh chỉ bánh bột (steamed bun, pastry) hoặc bọt trà. Thường dùng trong 饽饽 (bánh bao, bánh ngọt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bột\": thức ăn 食 bột bō — 饽饽 là bánh bao, bánh bột tròn mềm xốp. | Gương Hán-Việt | Bột trong 饽饽 (bột bột — bánh bao, bánh ngọt) | Mở khoá kiến thức | Biết 饽 mở khoá từ phương ngữ 饽饽 (bánh bao/bánh ngọt Bắc Kinh) và 香饽饽 (hương bột bột — người/vật được mọi người tranh nhau).", "Tự nguyên_Xie": "饽 là dạng giản thể của 餑. Theo Wiktionary, chữ 餑 gồm bộ 食 (thực, thức ăn) biểu nghĩa + phần biểu âm đọc bō. Nghĩa chính là 饽饽 (bō bo) — bánh bao hoặc các loại bánh ngọt. Nghĩa phụ là bọt hoặc bã nổi trên mặt trà. Chữ phương ngữ Bắc Kinh, không dùng phổ biến ngoài từ 饽饽. Không có hình ảnh cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bột", "Hạng Tần Suất (Jun Da)": "4472.0", "Tần Suất % (Jun Da)": "99.854468655", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 孛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣孛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饽", "Unihan_Traditional (Chữ Phồn thể)": "餑", "Pinyin_Xie": "bō", "Âm Hán Việt_Xie": "bột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với các từ khác để chỉ các loại bánh làm từ bột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饪', '{"9000": "4473.0", "Chữ Trung Quốc": "饪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 7 | nét | 饣 | thực | biểu nghĩa | ăn, thức ăn | 壬 | nhâm | biểu âm | can Nhâm (thiên can thứ 9) | 饪 = 饣 (Thực, biểu nghĩa: thức ăn) + 壬 (Nhâm, biểu âm). Dạng giản thể của 飪 (phồn thể). Wiktionary ghi là giản thể của 飪 — không có phân tích ls riêng. Cấu trúc phono-semantic: 食 (饣) cho nghĩa, 壬 cho âm rèn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫm\": thức ăn (饣) qua bàn tay nhâm (壬) chăm chút — công việc nấu nướng, chế biến. | Gương Hán-Việt | \"nhẫm\" trong 烹饪 (phanh nhẫm — nấu nướng, nghệ thuật ẩm thực) | Mở khoá kiến thức | Biết 饪 mở khoá 烹饪 (nấu nướng, ẩm thực), 烹饪技术 (kỹ thuật nấu ăn).", "Tự nguyên_Xie": "Tiểu triện | Chữ 饪 (nhẫm), phồn thể 飪, là dạng giản thể gồm bộ 食 (饣 — Thực) biểu nghĩa và 壬 (Nhâm) biểu âm rèn. Nghĩa gốc: nấu chín thức ăn, chế biến ẩm thực. Hình tiểu triện được lưu tại hanziyuan.net. Thường gặp trong 烹饪 (nấu nướng, ẩm thực). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu nướng", "Hạng Tần Suất (Jun Da)": "4473.0", "Tần Suất % (Jun Da)": "99.8546391941", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 壬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣壬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饪", "Unihan_Traditional (Chữ Phồn thể)": "飪", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng trong các từ ghép liên quan đến ẩm thực và nấu nướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绺', '{"9000": "4474.0", "Chữ Trung Quốc": "绺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 糹 | mịch | biểu nghĩa | tơ, sợi | 咎 | cữu | biểu âm | (biểu âm jiù/liǔ) | 绺 là dạng giản thể của 綹. Chữ gốc 綹 gồm bộ 糸 (mịch, biểu nghĩa: tơ sợi) + 咎 (cữu, biểu âm, đọc jiù gần liǔ). Là chữ hình thanh chỉ cuộn chỉ, chùm tơ; đơn vị đo đếm sợi tơ (20 sợi). Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mịch\": tơ 糸 cuộn liǔ như lãnh đai — 一绺头发 (một mớ tóc), một cuộn tơ chải mượt. | Gương Hán-Việt | Mịch trong 割绺 (cát mịch — móc túi, nghĩa đen cắt chùm tơ) | Mở khoá kiến thức | Biết 绺 mở khoá lượng từ đặc biệt cho tơ/tóc/len: 一绺头发 (một mớ tóc), 一绺丝线 (một cuộn chỉ).", "Tự nguyên_Xie": "Tiểu triện | 绺 là dạng giản thể của 綹. Theo Wiktionary, chữ 綹 là chữ hình thanh: bộ 糸 (mịch, tơ sợi) biểu nghĩa + 咎 (biểu âm, đọc jiù). Nghĩa là cuộn tơ, chùm sợi (skein), hay đơn vị đo tơ lụa. Dùng như lượng từ cho chùm tơ, tóc, len. Cũng có nghĩa nếp nhăn. Dùng trong 割绺 (cắt trộm — móc túi, kẻ cắp) — từ tiếng lóng phương ngữ. Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "20 sợi tơ; cuộn chỉ; chòm, món, túm", "Hạng Tần Suất (Jun Da)": "4474.0", "Tần Suất % (Jun Da)": "99.8548097332", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 咎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟咎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绺", "Unihan_Traditional (Chữ Phồn thể)": "綹", "Pinyin_Xie": "liǔ", "Âm Hán Việt_Xie": "lữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này thường làm lượng từ cho tóc, râu hoặc các sợi tơ kết lại thành búi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谘', '{"9000": "4475.0", "Chữ Trung Quốc": "谘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 咨 | tư | biểu âm | bàn bạc, tư vấn (biểu âm zī) | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 谘 là dạng giản thể của 諮. Chữ gốc 諮 là chữ hội ý kiêm hình thanh: bộ 言 (ngôn, biểu nghĩa: lời nói) + 咨 (tư, biểu âm, cũng mang nghĩa bàn bạc). Chỉ việc bàn bạc, tư vấn, trình báo chính thức. Là chữ trang trọng dùng trong văn bản chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tư\": lời 言 bàn 咨 — 谘询 là tư vấn, hỏi ý kiến người có chuyên môn. | Gương Hán-Việt | Tư trong 谘询 (tư tuân — tư vấn, hỏi ý kiến), 谘商 (tư thương — thương lượng) | Mở khoá kiến thức | Biết 谘 mở khoá từ 谘询 (tư vấn, hỏi ý kiến) và 谘商 (thương lượng) — dùng trong văn bản hành chính trang trọng.", "Tự nguyên_Xie": "谘 là dạng giản thể của 諮. Theo Wiktionary, chữ 諮 là chữ hội ý kiêm hình thanh (ls=psc, ls2=ic): bộ 言 (ngôn, biểu nghĩa: lời nói) + 咨 (tư, vừa là biểu âm vừa là biểu nghĩa: bàn bạc). Nghĩa đồng với 咨 (tư): bàn bạc, tư vấn. Chỉ dùng như biến thể của 咨, đặc biệt trong văn bản hành chính và ngoại giao. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bàn bạc, tư vấn; tường trình", "Hạng Tần Suất (Jun Da)": "4475.0", "Tần Suất % (Jun Da)": "99.8549797555", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 咨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠咨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谘", "Unihan_Traditional (Chữ Phồn thể)": "諮", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong các ngữ cảnh trang trọng như hội ý hoặc tư vấn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飧', '{"9000": "4476.0", "Chữ Trung Quốc": "飧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 夕 | tịch | biểu nghĩa | buổi tối, hoàng hôn | 食 | thực | biểu nghĩa | thức ăn, ăn uống | 飧 là chữ hội ý: bộ 夕 (tịch, buổi tối, hoàng hôn) + 食 (thực, thức ăn). Ý nghĩa kết hợp: bữa ăn buổi tối, bữa tối. Là ví dụ đẹp của chữ hội ý Trung Quốc: tối (夕) + ăn (食) = bữa tối (飧). Có hình ảnh lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tôn\": tối 夕 + ăn 食 = bữa tối 飧 — hội ý đẹp: khi mặt trời lặn (夕) thì đến giờ ăn (食). | Gương Hán-Việt | Tôn trong 饔飧 (ông tôn — bữa sáng và bữa tối, miếng ăn hàng ngày), 风飧露宿 (phong tôn lộ túc) | Mở khoá kiến thức | Biết 飧 mở khoá thành ngữ 风飧露宿 (ăn gió nằm sương — gian lao phiêu dạt) và 饔飧不继 (ông tôn bất kế — thiếu ăn).", "Tự nguyên_Xie": "Lục thư thông | 飧 là chữ hội ý theo Wiktionary: 夕 (tịch, buổi tối, hoàng hôn) + 食 (thực, thức ăn). Nghĩa kết hợp là bữa ăn tối, bữa cơm chiều. Cũng có nghĩa cơm ngâm nước (immerse cooked grain in water). Dùng trong từ cổ điển 饔飧 (ông tôn — bữa sáng và bữa tối, kiếm ăn hàng ngày). Thành ngữ 风飧露宿 (phong tôn lộ túc) nghĩa là phải ăn uống qua loa dưới gió giữa trời — chỉ gian khổ. Có hình ảnh lục thư thông còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn chín", "Hạng Tần Suất (Jun Da)": "4476.0", "Tần Suất % (Jun Da)": "99.855149261", "GavinGrover_Once (Chiết tự trực tiếp)": "夕 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夕食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "食", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夕", "Unihan_Simplified (Chữ Giản thể)": "飧", "Unihan_Traditional (Chữ Phồn thể)": "飧", "Pinyin_Xie": "sūn", "Âm Hán Việt_Xie": "sôn, tôn, san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ bữa ăn tối hoặc động từ chỉ việc ăn cơm chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迳', '{"9000": "4477.0", "Chữ Trung Quốc": "迳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迳 | kính | tượng hình | lối đi hẹp; thẳng tắp; giản thể dùng trong tên riêng | 迳 là dạng giản thể của 逕, chỉ dùng trong địa danh và tên người ở Trung Quốc đại lục. Chữ gốc 逕 gồm bộ 辵 (biểu nghĩa: đi đường) + 巠 (biểu âm). Chỉ con đường nhỏ, hẹp, hoặc trực tiếp thẳng không vòng vo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Kính\": đường 辵 thẳng jìng — 迳 chỉ dùng cho địa danh như 迳口 (cổng đường hẹp), không dùng trong văn thường. | Gương Hán-Việt | Kính trong 迳直 (kính trực — thẳng thắn, không vòng vèo, nghĩa của 逕直) | Mở khoá kiến thức | Biết 迳 chủ yếu hữu ích cho địa danh: nhận ra trong tên địa phương Trung Quốc, không nhầm với 径 (đường mòn thông thường).", "Tự nguyên_Xie": "迳 là dạng giản thể của 逕. Theo Wiktionary, chữ 迳 dùng 𢀖 thay cho 巠 (Han simp). Chữ 逕 gốc là hình thanh: bộ 辵 (xước, đi) biểu nghĩa + 巠 (biểu âm). Theo ghi chú Wiktionary, ở Trung Quốc đại lục, chữ 迳 chỉ được dùng trong địa danh và tên người, không dùng cho nghĩa thông thường (đường mòn) — trong đó dùng 径 (jìng). Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lối đi hẹp; thẳng tắp", "Hạng Tần Suất (Jun Da)": "4477.0", "Tần Suất % (Jun Da)": "99.8553187666", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "迳", "Unihan_Traditional (Chữ Phồn thể)": "逕", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "kính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Động từ | 动词 | Chữ này làm danh từ chỉ lối đi nhỏ hoặc làm phó từ với nghĩa là trực tiếp, đi thẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铡', '{"9000": "4478.0", "Chữ Trung Quốc": "铡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铡 | trát | tượng hình | dao cắt cỏ, dụng cụ chặt cỏ khô | 铡 là dạng giản thể của 鍘. Chữ gốc 鍘 gồm bộ 金 (kim, biểu nghĩa: kim loại) + phần biểu âm zhá. Là chữ hình thanh chỉ loại dao lớn/máy chặt cỏ khô làm thức ăn gia súc, hoặc dùng để hành hình (dao trảm). Không có dữ liệu Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Trát\": kim 金 chặt zhá — 铡刀 là lưỡi dao lớn cắt cỏ hoặc hành hình, nổi tiếng trong truyện Bao Công. | Gương Hán-Việt | Trát trong 铡刀 (trát đao — dao chặt cỏ; dao hành hình của Bao Công) | Mở khoá kiến thức | Biết 铡 mở khoá từ 铡草 (chặt cỏ) và hình ảnh văn hoá 包青天 dùng 铡 — kiến thức văn hoá dân gian Trung Quốc.", "Tự nguyên_Xie": "铡 là dạng giản thể của 鍘. Không có nguồn Wiktionary chi tiết cho chữ này. Bộ 金 (kim, kim loại) biểu nghĩa, phần còn lại biểu âm zhá. Nghĩa là máy/dao cắt cỏ (铡草 — cắt cỏ khô), hoặc dao hình trảm trong hình phạt cổ. Nổi tiếng qua 铡刀 (dao chặt cỏ) và trong văn hoá dân gian Trung Quốc qua hình ảnh 包青天 dùng 铡 để hành hình kẻ có tội. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt cỏ", "Hạng Tần Suất (Jun Da)": "4478.0", "Tần Suất % (Jun Da)": "99.8554877553", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 则", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅则", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "则", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铡", "Unihan_Traditional (Chữ Phồn thể)": "鍘", "Pinyin_Xie": "zhá", "Âm Hán Việt_Xie": "trát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này vừa làm danh từ chỉ loại dao lớn cắt cỏ vừa làm động từ cho hành động cắt bằng loại dao này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枞', '{"9000": "4479.0", "Chữ Trung Quốc": "枞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 從 | tòng | biểu âm | (biểu âm cōng/zōng) | 枞 là dạng giản thể của 樅. Chữ gốc 樅 là chữ hình thanh: bộ 木 (mộc, biểu nghĩa: cây) + 從 (tòng, biểu âm, đọc cōng). Chỉ cây linh sam (fir tree), loài cây lá kim thường xanh. Có hình ảnh tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tòng\": cây 木 mọc theo tòng từng cây — cây linh sam (枞树) thẳng đứng vươn cao như đội ngũ. | Gương Hán-Việt | Tòng trong 枞树 (tòng thụ — cây linh sam), 枞阳 (Tòng Dương — địa danh An Huy) | Mở khoá kiến thức | Biết 枞 mở khoá từ 枞树 (cây linh sam) và địa danh 枞阳 ở An Huy — dùng cho thực vật học và địa lý.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 枞 là dạng giản thể của 樅. Theo Wiktionary, chữ 樅 là chữ hình thanh: bộ 木 (mộc, cây) biểu nghĩa + 從 (tòng, biểu âm, đọc cōng). Nghĩa là cây linh sam (fir tree). Cũng đọc là zōng trong địa danh 樅陽/枞阳 (Tòng Dương) — một huyện thuộc thành phố Đồng Lăng, tỉnh An Huy. Có hình ảnh tiểu triện và lục thư thông còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tung, cây linh sam; chót vót; khua, đánh", "Hạng Tần Suất (Jun Da)": "4479.0", "Tần Suất % (Jun Da)": "99.8556562273", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 从", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木从", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枞", "Unihan_Traditional (Chữ Phồn thể)": "樅", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "tung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ một họ cây lá kim giống cây thông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熨', '{"9000": "4480.0", "Chữ Trung Quốc": "熨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 15 | nét | 尉 | uý | biểu âm và ý | quan uý — cũng gợi hành động dùng sức nặng ép xuống | 火 | hoả | biểu nghĩa | lửa, nhiệt | 熨 = 尉 (Uý, biểu âm và ý phụ) + 火 (Hoả, biểu nghĩa: lửa). Wiktionary chỉ ghi {{Han etym}} không có chi tiết ls. Cấu trúc: 火 cho nghĩa (dùng nhiệt để là phẳng vải), 尉 gợi âm yùn và ý nghĩa dùng vật nặng ép xuống. Chữ có thể là hình thanh hoặc hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uý\": lửa (火) nóng như quan uý (尉) oai phong — bàn là nóng lướt qua làm phẳng vải. | Gương Hán-Việt | \"uý\" trong 熨斗 (uý đẩu — cái bàn là); cũng đọc \"ủi\" theo nghĩa dân gian Hán-Việt | Mở khoá kiến thức | Biết 熨 mở khoá 熨斗 (bàn là), 熨平 (là phẳng), 熨烫 (là quần áo).", "Tự nguyên_Xie": "Chữ 熨 (uý) gồm bộ 火 (Hoả — lửa) và 尉 (Uý). Wiktionary chỉ ghi {{Han etym}} chung. Cấu trúc gợi ý: 火 biểu nghĩa chỉ dùng nhiệt; 尉 biểu âm yùn. Nghĩa: dùng bàn là nóng để là phẳng vải vóc. Chưa có nguồn học thuật xác nhận cấu trúc ls đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "là cho phẳng", "Hạng Tần Suất (Jun Da)": "4480.0", "Tần Suất % (Jun Da)": "99.8558241824", "GavinGrover_Once (Chiết tự trực tiếp)": "尉 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱尉火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熨", "Unihan_Traditional (Chữ Phồn thể)": "熨", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uất, uý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành động dùng nhiệt để làm phẳng quần áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yùn | / | ủi | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋈', '{"9000": "4481.0", "Chữ Trung Quốc": "鋈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋈 | ốc | tượng hình | đồng trắng; mạ bạc bằng đồng trắng | 鋈 là chữ hình thanh: bộ 金 (kim, biểu nghĩa: kim loại) + phần biểu âm wù. Chỉ đồng trắng (silver-plated metal) hoặc việc mạ kim loại bằng đồng trắng. Là chữ rất hiếm, chủ yếu xuất hiện trong văn bản cổ điển. Có hình ảnh tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ốc\": kim 金 sáng wù — 鋈 là kim loại mạ trắng sáng bóng, xuất hiện trong Kinh Thi mô tả xe ngựa hoàng tộc. | Gương Hán-Việt | Ốc trong 鋈续 (ốc tục — phụ tùng xe ngựa mạ đồng trắng, Kinh Thi) | Mở khoá kiến thức | Biết 鋈 mở khoá trích dẫn Kinh Thi 钩膺鋈续 — kiến thức văn học cổ điển và vật liệu kim loại cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 鋈 là chữ hình thanh theo Wiktionary: bộ 金 (kim, kim loại) biểu nghĩa + phần biểu âm đọc wù. Nghĩa là đồng trắng, hoặc mạ bằng đồng trắng. Xuất hiện trong Kinh Thi (诗经): 钩膺鋈续 — mô tả đồ trang trí xe ngựa mạ bạc. Là chữ rất cổ và hiếm. Có hình ảnh tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng trắng; mạ bằng đồng trắng", "Hạng Tần Suất (Jun Da)": "4481.0", "Tần Suất % (Jun Da)": "99.8559916208", "GavinGrover_Once (Chiết tự trực tiếp)": "沃 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱沃金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋈", "Unihan_Traditional (Chữ Phồn thể)": "鋈", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ việc mạ một lớp kim loại sáng lên bề mặt vật dụng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荭', '{"9000": "4482.0", "Chữ Trung Quốc": "荭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荭 | hồng | tượng hình | cỏ hồng, prince''s feather (Polygonum orientale) | 荭 là dạng giản thể của 葒. Chữ gốc 葒 gồm bộ 艸 (thảo, biểu nghĩa: cây cỏ) + phần biểu âm hóng. Là chữ hình thanh chỉ cây cỏ hồng (Polygonum orientale, hay còn gọi là cây rau muống đỏ), một loài thực vật hàng năm với lá to và hoa đỏ hoặc trắng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hồng\": cỏ 艹 màu hồng — 荭草 là cây cỏ hồng hoa đỏ, quả dùng làm thuốc Đông y. | Gương Hán-Việt | Hồng trong 荭草 (hồng thảo — cây cỏ hồng), 水荭 (thuỷ hồng — cỏ hồng mọc ven nước) | Mở khoá kiến thức | Biết 荭 mở khoá tên thực vật 荭草 (Polygonum orientale) và 水荭 — dùng trong Đông y và thực vật học.", "Tự nguyên_Xie": "荭 là dạng giản thể của 葒. Theo Wiktionary, chữ 葒 gồm bộ 艸 (thảo, cỏ cây) biểu nghĩa + phần biểu âm đọc hóng. Chỉ loài cây Polygonum orientale (Prince''s-feather) — cây mọc hàng năm, lá to, hoa đỏ/trắng, quả dùng làm thuốc. Trong hoá học, cũng chỉ hợp chất rubicene. Chưa có nguồn học thuật chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ hồng (mọc hàng năm, lá to, hoa đỏ hoặc trắng, quả có thể làm thuốc); rau muống", "Hạng Tần Suất (Jun Da)": "4482.0", "Tần Suất % (Jun Da)": "99.8561590592", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 红", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹红", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "红", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荭", "Unihan_Traditional (Chữ Phồn thể)": "葒", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong tên gọi các loại thực vật thân thảo có hoa màu đỏ hoặc hồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赊', '{"9000": "4483.0", "Chữ Trung Quốc": "赊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 11 | nét | 貝 | bối | biểu nghĩa | vỏ sò, tiền tệ | 余 | dư | biểu âm | thừa, dư | 赊 = 貝 (Bối, biểu nghĩa: vỏ sò/tiền tệ) + 余 (Dư, biểu âm); chữ hình thanh. Phần 貝 chỉ nghĩa giao dịch tiền bạc, phần 余 cho âm đọc gần shē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xa\": tiền (貝) để dư (余) về sau — mua chịu, trả xa mới xong, xa xỉ mà chưa có tiền ngay. | Gương Hán-Việt | \"xa\" trong 赊账 (xa trướng — nợ chịu) | Mở khoá kiến thức | Biết 赊 (xa) mở khoá 赊账 (nợ chịu), 赊欠 (mua thiếu), 赊销 (bán chịu).", "Tự nguyên_Xie": "Tiểu triện | Chữ 赊 vốn viết là 賖 — chữ hình thanh gồm 貝 (bối, biểu nghĩa: vỏ sò/tiền) và 余 (dư, biểu âm). Thời Trung cổ xuất hiện dạng tục 𧶟 với âm phù 舍 gần âm hơn, nhưng không phổ biến. Dạng hiện hành 賒 xuất hiện cuối Minh–đầu Thanh với âm phù 佘 tương đồng âm. Dạng giản thể 赊 giữ cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mua chịu trả dần; xa xôi; lâu dài; xa xỉ", "Hạng Tần Suất (Jun Da)": "4483.0", "Tần Suất % (Jun Da)": "99.8563259808", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 佘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝佘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赊", "Unihan_Traditional (Chữ Phồn thể)": "賒", "Pinyin_Xie": "shē", "Âm Hán Việt_Xie": "xa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ việc mua bán nợ hoặc làm tính từ trong văn cổ chỉ sự xa xôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俦', '{"9000": "4484.0", "Chữ Trung Quốc": "俦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 俦 | trù | tượng hình | người bạn đồng hành — dạng giản thể của 儔 | 俦 là giản thể của 儔. Anchor không cung cấp phân tích hình-thanh rõ ràng cho thành phần nội bộ. Chữ gốc 儔 có bộ 亻 (nhân) và âm phù, chỉ người bạn cùng loại, cùng địa vị. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": người cùng bọn — trù bị, tính toán cùng nhau, bạn đồng hành trong hành trình. | Gương Hán-Việt | \"trù\" trong 俦侣 (trù lữ — bạn đồng hành) | Mở khoá kiến thức | Biết 俦 (trù) mở khoá 俦侣 (bạn đồng hành), 无与伦俦 (vô song, không ai sánh bằng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 俦 là giản thể của 儔. Wiktionary ghi 儔 có hai âm: chóu (nghĩa: bạn đồng hành, người cùng loại, người ngang hàng; cũng dùng như đại từ nghi vấn ''ai'') và dào (nghĩa cổ liên quan đến vật che). Anchor không cung cấp phân tích hình-thanh rõ ràng. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lũ, bọn", "Hạng Tần Suất (Jun Da)": "4484.0", "Tần Suất % (Jun Da)": "99.8564929024", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俦", "Unihan_Traditional (Chữ Phồn thể)": "儔", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết để chỉ bạn bè hoặc những người cùng hàng ngũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戛', '{"9000": "4485.0", "Chữ Trung Quốc": "戛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 11 | nét | 𦣻 | biểu nghĩa | đầu (phần đầu cây giáo) | 戈 | qua | biểu nghĩa | giáo, vũ khí | 戛 = 𦣻 (đầu, biểu nghĩa) + 戈 (Qua, biểu nghĩa: giáo); chữ hội ý. Hai thành phần kết hợp bằng nghĩa: đầu + giáo = cái giáo dài có đầu nhọn. Wiktionary xác nhận ls=ic (hội ý).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giát\": đầu (𦣻) cắm vào giáo (戈) — cây giáo dài, tiếng gõ khẽ lưỡi kim loại kêu \"giát\" rồi dừng bặt. | Gương Hán-Việt | \"giát\" trong 戛然而止 (giát nhiên nhi chỉ — dừng đột ngột) | Mở khoá kiến thức | Biết 戛 (giát) mở khoá thành ngữ 戛然而止 (dừng bặt đột ngột), 戛戛 (khó khăn; tiếng cọ sát).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 戛 là chữ hội ý gồm 𦣻 (đầu) và 戈 (qua, giáo): phần đầu cắm vào cây giáo = vũ khí giáo dài. Nghĩa mở rộng sang động từ gõ nhẹ, đánh khẽ (như tiếng gõ nhẹ vào vật cứng). Thành ngữ 戛然而止 (âm thanh dừng đột ngột) là cách dùng phổ biến nhất trong văn học hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh nhẹ, gõ nhẹ; cái giáo dài", "Hạng Tần Suất (Jun Da)": "4485.0", "Tần Suất % (Jun Da)": "99.856659824", "GavinGrover_Once (Chiết tự trực tiếp)": "𦣻 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𦣻戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦣻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戛", "Unihan_Traditional (Chữ Phồn thể)": "戛", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "kiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động gõ nhẹ hoặc phát ra âm thanh cọ xát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湎', '{"9000": "4486.0", "Chữ Trung Quốc": "湎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | biểu nghĩa | nước (tam điểm thủy) | 面 | diện | biểu âm | mặt | 湎 = 氵 (tam điểm thủy, biểu nghĩa: nước) + 面 (Diện, biểu âm); chữ hình thanh. Bộ nước chỉ nghĩa liên quan đến chất lỏng/rượu, phần 面 cho âm đọc gần miǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giờn\": nước (氵) phủ lên mặt (面) — say rượu đến mức mặt chìm vào nước, không thể thoát ra. | Gương Hán-Việt | \"giờn\" trong 沉湎 (trầm giờn — chìm đắm vào rượu/thú vui) | Mở khoá kiến thức | Biết 湎 (giờn) mở khoá 沉湎 (say đắm), 耽湎 (mê đắm), 荒湎 (bỏ bê vì mê đắm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary phân tích 湎 là chữ hình thanh gồm 水/氵 (biểu nghĩa: nước) và 面 (biểu âm). Nghĩa văn ngôn: đắm mình vào rượu, buông mình vào thú vui. Từ ghép cổ 沉湎 (chìm đắm vào rượu), 耽湎 đều mang sắc thái tiêu cực. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "say rượu; say đắm", "Hạng Tần Suất (Jun Da)": "4486.0", "Tần Suất % (Jun Da)": "99.8568262288", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 面", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵面", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "面", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湎", "Unihan_Traditional (Chữ Phồn thể)": "湎", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "miện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ chỉ sự chìm đắm vào rượu chè hay dục vọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幺', '{"9000": "4487.0", "Chữ Trung Quốc": "幺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 幺 | Số nét | 3 | nét | 幺 | yêu | tượng hình | sợi tơ nhỏ — hình vẽ cuộn tơ mảnh | 幺 là chữ tượng hình — mô phỏng hình cuộn sợi tơ nhỏ. Wiktionary xác nhận đây là hình vẽ sợi tơ (liushu p = tượng hình). So sánh với 糸 (mịch) cùng nguồn gốc hình sợi chỉ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêu\": hình sợi tơ nhỏ xíu — yêu là nhỏ, mảnh mai như sợi chỉ mỏng nhất. | Gương Hán-Việt | \"yêu\" trong 幺幺 (yêu yêu — nhỏ bé, yếu đuối) | Mở khoá kiến thức | Biết 幺 (yêu) mở khoá bộ 幺 trong 幻 (huyễn — ảo), 幼 (ấu — nhỏ), 幽 (u — u tối).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary xác nhận 幺 là chữ tượng hình, mô tả sợi tơ mảnh. So sánh với 糸. Nghĩa gốc: nhỏ bé, mảnh mai như sợi tơ. Trong tiếng Trung hiện đại, 幺 còn dùng để đọc số 1 trong ngữ cảnh quân sự hoặc số điện thoại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "238.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình mô phỏng sợi tơ nhỏ bé.", "Nghĩa Tiếng Việt_Xie": "nhỏ bé", "Hạng Tần Suất (Jun Da)": "4487.0", "Tần Suất % (Jun Da)": "99.8569926336", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "幺", "Unihan_Traditional (Chữ Phồn thể)": "么", "Pinyin_Xie": "yāo", "Âm Hán Việt_Xie": "yêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Số từ | 数词 | Thường làm tính từ chỉ sự nhỏ bé hoặc làm số từ thay thế cho số một khi đọc số điện thoại, quân bài. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凇', '{"9000": "4488.0", "Chữ Trung Quốc": "凇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 10 | nét | 凇 | tùng | tượng hình | băng đá đóng trên cành cây mùa đông | 凇 không có phân tích thành phần rõ ràng trong anchor. Chữ có bộ 冫 (băng) bên trái gợi nghĩa liên quan đến băng đá, nhưng Wiktionary không cung cấp phân tích hình-thanh. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tùng\": băng (冫) trên cành thông — 雾凇 là hiện tượng sương muối hóa băng trắng xóa trên cành cây giữa đông. | Gương Hán-Việt | \"tùng\" trong 雾凇 (vụ tùng — sương muối đóng băng trên cây) | Mở khoá kiến thức | Biết 凇 (tùng) mở khoá 雾凇 (sương muối đóng băng trên cây), 雨凇 (mưa băng trên cành).", "Tự nguyên_Xie": "Anchor không cung cấp phân tích hình-thanh cho 凇. Chữ có bộ 冫 (nước/băng) gợi nghĩa liên quan đến hiện tượng băng đóng. Nghĩa: chùm băng đóng trên cành cây (雾凇 — sương muối đóng băng, 雨凇 — mưa đóng băng). Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giọt nước đóng băng", "Hạng Tần Suất (Jun Da)": "4488.0", "Tần Suất % (Jun Da)": "99.8571585216", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 松", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫松", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "松", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "凇", "Unihan_Traditional (Chữ Phồn thể)": "凇", "Pinyin_Xie": "sōng", "Âm Hán Việt_Xie": "tùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ hiện tượng băng giá bám trên cây cối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芪', '{"9000": "4489.0", "Chữ Trung Quốc": "芪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芪 | kỳ | tượng hình | loại cỏ dùng làm thuốc — hoàng kỳ | 芪 không có phân tích thành phần rõ ràng trong anchor (Wiktionary chỉ ghi {{Han etym}} không có nội dung). Chữ có bộ 艹 (thảo — cỏ) bên trên gợi đây là loài thực vật. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": cỏ (艹) kỳ diệu — hoàng kỳ là vị thuốc đặc biệt trong đông y, bổ khí hư, tăng cường miễn dịch. | Gương Hán-Việt | \"kỳ\" trong 黄芪 (hoàng kỳ — vị thuốc đông y) | Mở khoá kiến thức | Biết 芪 (kỳ) mở khoá 黄芪 (hoàng kỳ — astragalus), 炙芪 (chích kỳ — hoàng kỳ chế).", "Tự nguyên_Xie": "Tiểu triện | Anchor chỉ ghi {{Han etym}} không có nội dung phân tích. Chữ 芪 có bộ 艹 (thảo — cỏ, cây) biểu nghĩa, gợi đây là loài thực vật dùng làm thuốc. Hoàng kỳ (黄芪) là vị thuốc đông y nổi tiếng. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoàng kỳ (vị thuốc đông y)", "Hạng Tần Suất (Jun Da)": "4489.0", "Tần Suất % (Jun Da)": "99.8573244097", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 氏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹氏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芪", "Unihan_Traditional (Chữ Phồn thể)": "芪", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong tên gọi các loại thảo dược đông y như hoàng kỳ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觯', '{"9000": "4490.0", "Chữ Trung Quốc": "觯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 15 | nét | 角 | giác | biểu nghĩa | sừng, chén rượu bằng sừng | 單 | đơn | biểu âm | đơn chiếc | 觯 = 角 (Giác, biểu nghĩa: sừng/chén rượu) + 單 (Đơn, biểu âm); chữ hình thanh. Phần 角 chỉ đây là đồ dùng liên quan đến sừng, phần 單 cho âm đọc gần zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": sừng (角) đơn (單) chiếc — chén rượu nhỏ làm từ sừng, dùng một mình trong nghi lễ cung đình. | Gương Hán-Việt | \"chí\" trong 觯爵 (chí tước — các loại chén rượu cổ) | Mở khoá kiến thức | Biết 觯 (chí) mở khoá từ vựng cổ về đồ nghi lễ: 觯爵 (chén rượu), 觚觯 (các loại chén đồng xanh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 觶 (phồn thể) là chữ hình thanh gồm 角 (biểu nghĩa: sừng) và 單 (biểu âm). Nghĩa lịch sử: loại chén đồng nhỏ, tròn, dùng trong nghi lễ thời cổ đại Trung Hoa. Một trong tám loại chén rượu cổ, thường dùng trong lễ tế. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vò rượu bằng gỗ", "Hạng Tần Suất (Jun Da)": "4490.0", "Tần Suất % (Jun Da)": "99.8574902977", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觯", "Unihan_Traditional (Chữ Phồn thể)": "觶", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại dụng cụ uống rượu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龌', '{"9000": "4491.0", "Chữ Trung Quốc": "龌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 17 | nét | 龌 | ác | tượng hình | răng cắn chặt — chật hẹp, dơ bẩn | 龌 là giản thể của 齷, đơn giản hóa bộ 齒 thành 齿. Wiktionary chỉ ghi {{Han simp|齷|f=齒|t=齿}} mà không cung cấp phân tích thành phần gốc. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ của chữ gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ác\": răng (齿) cắn chặt, chật hẹp — ác cảm vì bẩn thỉu, đê tiện, không gian chật hẹp đến ngột ngạt. | Gương Hán-Việt | \"ác\" trong 龌龊 (ác xúc — bẩn thỉu, đê tiện) | Mở khoá kiến thức | Biết 龌 (ác) mở khoá 龌龊 (bẩn thỉu, đê tiện, chật hẹp) — cụm duy nhất thường gặp.", "Tự nguyên_Xie": "龌 là dạng giản thể của 齷. Wiktionary chỉ ghi đây là biến thể giản hóa (Han simp) của 齷, thay bộ 齒 bằng 齿. Chữ gốc 齷 liên quan đến răng (bộ 齒), nghĩa là chật hẹp, dơ bẩn. 龌龊 là cụm cố định nghĩa là bẩn thỉu, đê tiện. Chưa có nguồn học thuật xác nhận chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ác xúc 齷齪,龌龊)", "Hạng Tần Suất (Jun Da)": "4491.0", "Tần Suất % (Jun Da)": "99.8576561857", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 屋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿屋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龌", "Unihan_Traditional (Chữ Phồn thể)": "齷", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Hầu như chỉ dùng làm tính từ khi kết hợp thành từ ghép để chỉ sự bẩn thỉu hoặc đê tiện. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挞', '{"9000": "4492.0", "Chữ Trung Quốc": "挞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 挞 | thát | tượng hình | tay đánh roi — giản thể của 撻 | 挞 là giản thể của 撻. Anchor ghi {{Han etym}} không có phân tích nội dung. Chữ có bộ 手/扌 (thủ — tay) biểu nghĩa, gợi hành động dùng tay đánh. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thát\": tay (扌) quất roi mạnh — thát là đánh, trừng phạt bằng đòn roi. | Gương Hán-Việt | \"thát\" trong 挞伐 (thát phạt — đánh phạt, chinh phạt) | Mở khoá kiến thức | Biết 挞 (thát) mở khoá 挞伐 (đánh phạt, chinh phạt), 鞭挞 (roi đánh, phê phán mạnh mẽ).", "Tự nguyên_Xie": "Tiểu triện | 挞 là giản thể của 撻. Anchor chỉ ghi {{Han etym}} không có nội dung phân tích. Chữ có bộ 扌 (tay) biểu nghĩa, gợi hành động dùng roi/gậy đánh. Nghĩa: đánh bằng roi, trừng phạt, cũng nghĩa là nhanh chóng. 挞伐 là đánh phạt kẻ thù. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh bằng roi; nhanh chóng, mau", "Hạng Tần Suất (Jun Da)": "4492.0", "Tần Suất % (Jun Da)": "99.857821557", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 达", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌达", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "达", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挞", "Unihan_Traditional (Chữ Phồn thể)": "撻", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "thát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động đánh đập, trừng phạt bằng roi vọt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬴', '{"9000": "4493.0", "Chữ Trung Quốc": "嬴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 16 | nét | 嬴 | doanh | tượng hình | họ Doanh — tên dòng họ hoàng tộc nhà Tần | 嬴 không có phân tích thành phần rõ ràng trong anchor. Chữ có bộ 女 (nữ) ở dưới, nhưng Wiktionary không cung cấp phân tích hình-thanh chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doanh\": họ Doanh — dòng họ của Tần Thủy Hoàng (嬴政), doanh thắng thiên hạ, lập nên đế chế đầu tiên. | Gương Hán-Việt | \"doanh\" trong 嬴政 (Doanh Chính — tên thật của Tần Thủy Hoàng) | Mở khoá kiến thức | Biết 嬴 (doanh) mở khoá 嬴政 (Tần Thủy Hoàng), 嬴余 (thừa thắng), và khái niệm về họ tộc cổ đại Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary không cung cấp phân tích hình-thanh cho 嬴. Chữ ghi hai nghĩa cổ: có thừa/đầy đủ; và họ Doanh — họ của Tần Thủy Hoàng (嬴政). 嬴 là một trong Bát đại cổ tính (tám họ lớn thượng cổ). Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Doanh; đầy, thừa", "Hạng Tần Suất (Jun Da)": "4493.0", "Tần Suất % (Jun Da)": "99.8579869282", "GavinGrover_Once (Chiết tự trực tiếp)": "𣎆 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𣎆女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣎆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嬴", "Unihan_Traditional (Chữ Phồn thể)": "嬴", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "doanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ họ người hoặc làm tính từ chỉ sự dư thừa trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苻', '{"9000": "4494.0", "Chữ Trung Quốc": "苻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | biểu nghĩa | cỏ, thực vật | 付 | pho | biểu âm | trao cho, phó thác | 苻 = 艹 (thảo đầu, biểu nghĩa: cỏ/thực vật) + 付 (Pho, biểu âm); chữ hình thanh. Phần 艹 chỉ đây là loài cỏ/cây, phần 付 cho âm đọc gần fú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\": cỏ (艹) phó (付) thác — loài cỏ phù mang ý nghĩa linh thiêng, cũng là họ của vua Tiền Tần nổi tiếng. | Gương Hán-Việt | \"phù\" trong 苻坚 (Phù Kiên — vua Tiền Tần) | Mở khoá kiến thức | Biết 苻 (phù) mở khoá tên lịch sử 苻坚 (Phù Kiên), cụm 萑苻 (đầm lầy nơi trộm cướp ẩn náu).", "Tự nguyên_Xie": "Wiktionary phân tích 苻 là chữ hình thanh gồm 艹 (biểu nghĩa: cỏ) và 付 (biểu âm). Nghĩa: một loài cỏ (solanum lyratum hoặc nymphoides peltata). Cũng dùng làm họ tên (苻坚 — vua Tiền Tần). Thêm nghĩa: dạng thay thế của 莩 (màng bên trong ống lau sậy) và 符 (phù hiệu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cò phù, cỏ mắt quỷ", "Hạng Tần Suất (Jun Da)": "4494.0", "Tần Suất % (Jun Da)": "99.8581522995", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 付", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹付", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "付", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苻", "Unihan_Traditional (Chữ Phồn thể)": "苻", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cỏ hoặc dùng làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘁', '{"9000": "4495.0", "Chữ Trung Quốc": "嘁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嘁 | thích | tượng hình | tiếng xì xào, thì thầm — dùng để bắt chước âm thanh | 嘁 không có phân tích thành phần rõ ràng trong anchor. Chữ có bộ 口 (khẩu — miệng) biểu nghĩa, gợi liên quan đến âm thanh/tiếng nói. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thích\": miệng (口) phát tiếng thích thích — 嘁嘁喳喳 là tiếng xì xào thì thầm, tiếng ồn ào nhỏ. | Gương Hán-Việt | \"thích\" trong 嘁嘁喳喳 (thích thích tra tra — xì xào, thì thầm) | Mở khoá kiến thức | Biết 嘁 (thích) mở khoá 嘁嘁喳喳 (xì xào thì thầm), 嘁哩喀喳 (ầm ĩ, huyên náo).", "Tự nguyên_Xie": "Anchor chỉ ghi {{Han etym}} không có nội dung phân tích, và Wiktionary chú thích rfdef (cần định nghĩa thêm). Chữ có bộ 口 (miệng) biểu nghĩa, gợi âm thanh. Dùng trong cụm 嘁嘁喳喳 (thì thầm xì xào) và 嘁哩喀喳 (tiếng ầm ĩ). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thích tra 嘁喳)", "Hạng Tần Suất (Jun Da)": "4495.0", "Tần Suất % (Jun Da)": "99.8583176707", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 戚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口戚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘁", "Unihan_Traditional (Chữ Phồn thể)": "嘁", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này thường dùng trong từ láy tượng thanh để mô tả tiếng nói chuyện nhỏ to, thì thầm. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞯', '{"9000": "4496.0", "Chữ Trung Quốc": "鞯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 鞯 | tiên | tượng hình | đệm lót yên ngựa — giản thể của 韉 | 鞯 là giản thể của 韉. Anchor không cung cấp phân tích thành phần rõ ràng. Chữ có bộ 革 (cách — da thuộc) biểu nghĩa, gợi đây là vật dụng bằng da liên quan đến yên ngựa. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiên\": da (革) lót dưới yên — tiên là cái đệm da lót yên ngựa, giúp ngựa không bị đau lưng khi cưỡi dài ngày. | Gương Hán-Việt | \"tiên\" trong 鞍鞯 (yên tiên — yên và đệm lót ngựa) | Mở khoá kiến thức | Biết 鞯 (tiên) mở khoá 鞍鞯 (yên và đệm lót), 马鞯 (đệm lót ngựa).", "Tự nguyên_Xie": "Tiểu triện | Anchor ghi 鞯 là giản thể, dạng phồn thể là 韉. Wiktionary không cung cấp phân tích hình-thanh cho 韉. Nghĩa: đệm lót đặt dưới yên ngựa để bảo vệ lưng ngựa. Thường xuất hiện trong cụm 鞍鞯 (yên và đệm lót). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đệm lót yên ngựa", "Hạng Tần Suất (Jun Da)": "4496.0", "Tần Suất % (Jun Da)": "99.8584830419", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 荐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革荐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞯", "Unihan_Traditional (Chữ Phồn thể)": "韉", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tấm đệm đặt dưới yên ngựa để tránh cọ xát làm đau lưng ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肽', '{"9000": "4497.0", "Chữ Trung Quốc": "肽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | ⺼ | biểu nghĩa | thịt (bộ nhục biến thể) | 太 | thái | biểu âm | quá, rất | 肽 = ⺼ (bộ nhục — thịt, biểu nghĩa) + 太 (Thái, biểu âm); chữ hình thanh. Phần ⺼ chỉ nghĩa liên quan đến chất hữu cơ sinh học, phần 太 cho âm đọc gần tài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\": thịt (⺼) thái ra — peptide là chuỗi amino acid được \"thái nhỏ\" từ protein, bộ nhục + thái = thuật ngữ sinh hóa. | Gương Hán-Việt | \"thái\" trong 多肽 (đa thái — polypeptide) | Mở khoá kiến thức | Biết 肽 (thái) mở khoá 多肽 (polypeptide), 二肽 (dipeptide), 多肽链 (chuỗi polypeptide).", "Tự nguyên_Xie": "Wiktionary phân tích 肽 là chữ hình thanh gồm 肉/⺼ (biểu nghĩa: thịt/chất hữu cơ) và 太 (biểu âm, âm đọc tài). Đây là chữ tạo muộn để ký âm thuật ngữ hóa học. Nghĩa: peptide — hợp chất chuỗi amino acid. Chữ thuần kỹ thuật, không có lịch sử cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "peptit (hoá học, sinh học)", "Hạng Tần Suất (Jun Da)": "4497.0", "Tần Suất % (Jun Da)": "99.8586478964", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肽", "Unihan_Traditional (Chữ Phồn thể)": "肽", "Pinyin_Xie": "tài", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ các chuỗi peptit cấu tạo nên protein. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恸', '{"9000": "4498.0", "Chữ Trung Quốc": "恸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 恸 | thống | tượng hình | đau thương sâu sắc — giản thể của 慟 | 恸 là giản thể của 慟. Anchor không cung cấp phân tích thành phần rõ ràng. Chữ có bộ 忄 (tâm — tâm trí, trái tim) biểu nghĩa, gợi cảm xúc đau thương. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thống\": tim (忄) thống khổ — thống là đau đớn tột cùng, khóc lóc vì mất đi điều gì đó quan trọng nhất. | Gương Hán-Việt | \"thống\" trong 慟哭 (thống khốc — khóc nức nở vì đau thương) | Mở khoá kiến thức | Biết 恸 (thống) mở khoá 慟哭 (khóc nức nở), 悲恸 (bi thương tột độ), 大恸 (vô cùng đau thương).", "Tự nguyên_Xie": "Tiểu triện | 恸 là giản thể của 慟. Wiktionary không cung cấp phân tích hình-thanh cho 慟 trong anchor. Nghĩa: đau thương sâu sắc, bi thảm thống thiết. 慟哭 là khóc nức nở vì đau buồn tột cùng. Thường dùng trong văn ngôn và văn học cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thương quá", "Hạng Tần Suất (Jun Da)": "4498.0", "Tần Suất % (Jun Da)": "99.8588122341", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 动", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄动", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "动", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恸", "Unihan_Traditional (Chữ Phồn thể)": "慟", "Pinyin_Xie": "tòng", "Âm Hán Việt_Xie": "đỗng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ việc khóc lóc thảm thiết hoặc làm tính từ biểu thị trạng thái cực kỳ đau buồn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迨', '{"9000": "4499.0", "Chữ Trung Quốc": "迨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迨 | đãi | tượng hình | kịp đến, đuổi theo — bộ辵(đi) + ý nghĩa đạt tới | 迨 không có phân tích thành phần rõ ràng trong anchor (chỉ ghi {{Han etym}} không có nội dung). Chữ có bộ 辶/辵 (sước — đi) biểu nghĩa, gợi hành động di chuyển theo kịp. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": đi (辶) đến kịp — đãi là đợi kịp lúc, theo kịp thời điểm trước khi quá muộn. | Gương Hán-Việt | \"đãi\" trong 迨至 (đãi chí — cho đến khi) | Mở khoá kiến thức | Biết 迨 (đãi) mở khoá 迨至 (cho đến khi), 迨及 (kịp đến, nhân lúc), 迨夫 (đến lúc — liên từ văn ngôn).", "Tự nguyên_Xie": "Anchor chỉ ghi {{Han etym}} không có nội dung phân tích. Chữ có bộ 辶 (đi) biểu nghĩa. Nghĩa văn ngôn: đuổi kịp, đến kịp, cho đến lúc. Thường dùng như liên từ cổ điển: 迨至 (cho đến khi), 迨夫 (đến lúc). Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "theo kịp; đuổi", "Hạng Tần Suất (Jun Da)": "4499.0", "Tần Suất % (Jun Da)": "99.858976055", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迨", "Unihan_Traditional (Chữ Phồn thể)": "迨", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Giới từ | 介词 | Liên từ | 连词 | Chữ này thường làm giới từ hoặc liên từ trong văn ngôn để biểu thị mốc thời gian hoặc điều kiện. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钰', '{"9000": "4500.0", "Chữ Trung Quốc": "钰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 玉 | ngọc | biểu âm | ngọc bích | 钰 = 金 (Kim, biểu nghĩa: kim loại/vàng) + 玉 (Ngọc, biểu âm); chữ hội ý kiêm hình thanh (ic+psc). Phần 金 chỉ đây là vật quý liên quan đến kim loại, phần 玉 vừa cho âm vừa bổ nghĩa (ngọc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngọc\": vàng (金) kết hợp ngọc (玉) — kho báu quý hiếm, thường dùng đặt tên con gái như lời chúc quý giá. | Gương Hán-Việt | \"ngọc\" trong 钰石 (ngọc thạch — đá quý) | Mở khoá kiến thức | Biết 钰 (ngọc) mở khoá ý nghĩa quý báu trong tên người, liên quan đến 金 (kim) và 玉 (ngọc) — biểu tượng phú quý.", "Tự nguyên_Xie": "Wiktionary phân tích 鈺 (phồn thể) là chữ hội ý kiêm hình thanh gồm 金 (biểu nghĩa: kim loại/vàng) và 玉 (biểu âm và nghĩa: ngọc). Nghĩa lịch sử: vàng và ngọc, báu vật; cũng nghĩa là kim loại cứng. Từ điển cổ 五音集韻 ghi: kết hợp kim và ngọc thành 鈺. Chữ tạo muộn, thường dùng làm tên người. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ kim loại)", "Hạng Tần Suất (Jun Da)": "4500.0", "Tần Suất % (Jun Da)": "99.8591398758", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 玉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅玉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钰", "Unihan_Traditional (Chữ Phồn thể)": "鈺", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ngọc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ kim loại quý và thường được dùng đặt tên người với ý nghĩa trân quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('儆', '{"9000": "4501.0", "Chữ Trung Quốc": "儆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 人 | nhân | biểu nghĩa | người | 敬 | kính | biểu âm | kính trọng, cẩn trọng | 儆 = 人/亻 (Nhân, biểu nghĩa: người) + 敬 (Kính, biểu âm); chữ hình thanh. Phần 亻 chỉ đây là hành động liên quan đến con người, phần 敬 cho âm đọc gần jǐng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảnh\": người (亻) kính (敬) cẩn — cảnh giới, đề phòng, nhắc nhở người cần cẩn thận như sự kính trọng mang tính phòng ngừa. | Gương Hán-Việt | \"cảnh\" trong 儆戒 (cảnh giới — cảnh báo, răn đe) | Mở khoá kiến thức | Biết 儆 (cảnh) mở khoá 儆戒 (cảnh báo, răn đe), 儆示 (làm gương cảnh cáo), 儆醒 (tỉnh thức, giữ gìn).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 儆 là chữ hình thanh gồm 人/亻 (biểu nghĩa: người) và 敬 (biểu âm). Nghĩa: cảnh báo, đề phòng, nhắc nhở người khác cẩn trọng. Thường dùng trong 儆戒 (cảnh giới), 儆示 (làm gương cảnh cáo). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đề phòng, phòng ngừa", "Hạng Tần Suất (Jun Da)": "4501.0", "Tần Suất % (Jun Da)": "99.8593031799", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 敬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻敬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "儆", "Unihan_Traditional (Chữ Phồn thể)": "儆", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp thành từ ghép như cảnh tỉnh, răn đe kẻ khác để làm gương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觎', '{"9000": "4502.0", "Chữ Trung Quốc": "觎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 13 | nét | 俞 | du | biểu âm | đồng ý, cho phép | 見 | kiến | biểu nghĩa | nhìn, thấy | 觎 = 俞 (Du, biểu âm) + 見 (Kiến, biểu nghĩa: nhìn); chữ hình thanh. Phần 見 chỉ nghĩa liên quan đến việc nhìn/thèm muốn, phần 俞 cho âm đọc gần yú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": nhìn (見) du ngoạn mà thèm —觊觎 là nhòm ngó, thèm khát điều không thuộc về mình, mắt nhìn ham muốn. | Gương Hán-Việt | \"du\" trong 觊觎 (kĩ du — nhòm ngó, thèm muốn chiếm đoạt) | Mở khoá kiến thức | Biết 觎 (du) mở khoá 觊觎 (nhòm ngó quyền lực/tài sản), 觊觎之心 (lòng tham nhòm ngó).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 覦 (phồn thể) là chữ hình thanh gồm 俞 (biểu âm) và 見 (biểu nghĩa: nhìn). Nghĩa: thèm muốn, nhòm ngó, muốn chiếm đoạt. Thường dùng trong 觊觎 (kì du — nhòm ngó, thèm khát quyền lực hoặc vật quý). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "muốn được", "Hạng Tần Suất (Jun Da)": "4502.0", "Tần Suất % (Jun Da)": "99.8594659673", "GavinGrover_Once (Chiết tự trực tiếp)": "俞 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰俞见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觎", "Unihan_Traditional (Chữ Phồn thể)": "覦", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm với chữ Ký thành Ký du để chỉ sự dòm ngó, mưu đồ bất chính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讫', '{"9000": "4503.0", "Chữ Trung Quốc": "讫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 5 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 乞 | khất | biểu âm | xin, cầu xin | 讫 = 言/讠 (Ngôn, biểu nghĩa: lời nói) + 乞 (Khất, biểu âm); chữ hình thanh. Phần 言 chỉ liên quan đến hành động ngôn ngữ/hoàn thành lời, phần 乞 cho âm đọc gần qì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngật\": lời (言) xin (乞) đã nói xong — ngật là đã hoàn thành, kết thúc, không còn gì để nói hay làm thêm. | Gương Hán-Việt | \"ngật\" trong 收讫 (thu ngật — đã thu đủ/xong) | Mở khoá kiến thức | Biết 讫 (ngật) mở khoá 收讫 (đã thu xong), 付讫 (đã thanh toán), 验讫 (đã kiểm tra xong).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary phân tích 訖 (phồn thể) là chữ hình thanh gồm 言 (biểu nghĩa: lời nói) và 乞 (biểu âm). Nghĩa: làm xong, kết thúc, đến hết. Dùng trong tài chính cổ đại: 收讫 (đã thu xong), 付讫 (đã thanh toán xong). Cũng dùng như giới từ cổ: cho đến, từ... đến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm xong, chấm dứt", "Hạng Tần Suất (Jun Da)": "4503.0", "Tần Suất % (Jun Da)": "99.8596287546", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讫", "Unihan_Traditional (Chữ Phồn thể)": "訖", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "ngật, cật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Chữ này thường đứng sau động từ khác để chỉ hành động đã hoàn tất hoặc dùng trong hóa đơn thương mại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滓', '{"9000": "4504.0", "Chữ Trung Quốc": "滓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | biểu nghĩa | nước (tam điểm thủy) | 宰 | tể | biểu âm | giết mổ, quan cai trị | 滓 = 氵 (tam điểm thủy, biểu nghĩa: nước/chất lỏng) + 宰 (Tể, biểu âm); chữ hình thanh. Phần 氵 chỉ nghĩa liên quan đến chất lỏng/cặn bã trong nước, phần 宰 cho âm đọc gần zǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": nước (氵) sau khi tể (宰) — sau khi cắt xẻ thịt, phần cặn bã đọng lại ở đáy nước là 滓. | Gương Hán-Việt | \"tỉ\" trong 渣滓 (tra tỉ — cặn bã, xỉ) | Mở khoá kiến thức | Biết 滓 (tỉ) mở khoá 渣滓 (cặn bã, xỉ), 茶滓 (bã trà), 滓秽 (cặn dơ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 滓 là chữ hình thanh gồm 水/氵 (biểu nghĩa: nước) và 宰 (biểu âm). Nghĩa: cặn, xỉ, bã — phần dư đọng lại sau khi lọc hoặc đun sôi chất lỏng. 渣滓 (bã cặn), 茶滓 (bã trà) là cách dùng phổ biến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cặn, đục", "Hạng Tần Suất (Jun Da)": "4504.0", "Tần Suất % (Jun Da)": "99.8597910251", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 宰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵宰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滓", "Unihan_Traditional (Chữ Phồn thể)": "滓", "Pinyin_Xie": "zǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần chất thải lắng xuống đáy sau khi lọc hoặc lắng nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僮', '{"9000": "4505.0", "Chữ Trung Quốc": "僮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 亻 | biểu nghĩa | người (bộ nhân đứng) | 童 | đồng | biểu âm | trẻ em, đồng tử | 僮 = 亻 (biểu nghĩa: người) + 童 (Đồng, biểu âm); chữ hình thanh. Phần 亻 chỉ đây là con người, phần 童 cho âm đọc tóng và gợi nghĩa (trẻ con làm tiểu đồng, hầu nhỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": người (亻) trẻ (童) hầu hạ — đồng là đứa trẻ phục vụ, tiểu đồng trong nhà quý tộc. | Gương Hán-Việt | \"đồng\" trong 僮仆 (đồng bộc — tiểu đồng, người hầu nhỏ) | Mở khoá kiến thức | Biết 僮 (đồng) mở khoá 僮仆 (tiểu đồng), 书僮 (đứa hầu trông nom sách vở), 僮僕 (đám đầy tớ nhỏ).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Wiktionary phân tích 僮 là chữ hình thanh gồm 人/亻 (biểu nghĩa: người) và 童 (biểu âm). Nghĩa: đứa trẻ hầu hạ, tiểu đồng — người phục vụ trẻ tuổi. Khác với 童 (đồng) là trẻ em nói chung, 僮 nhấn mạnh vai trò phục vụ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứa trẻ", "Hạng Tần Suất (Jun Da)": "4505.0", "Tần Suất % (Jun Da)": "99.8599532956", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僮", "Unihan_Traditional (Chữ Phồn thể)": "僮", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người hầu nhỏ tuổi trong nhà hoặc dùng để chỉ tộc người Choang ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媾', '{"9000": "4506.0", "Chữ Trung Quốc": "媾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | phụ nữ, nữ giới | 冓 | biểu âm | 媾 = 女 (Nữ, biểu nghĩa: phụ nữ) + 冓 (biểu âm, âm đọc gòu); chữ hình thanh. Phần 女 chỉ nghĩa liên quan đến hôn nhân/quan hệ nam nữ, phần 冓 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\": nữ (女) cấu kết — kết hôn để gắn kết hai gia tộc, hoặc đàm phán hòa bình. | Gương Hán-Việt | \"cấu\" trong 媾和 (cấu hòa — giảng hòa, ký hòa ước) | Mở khoá kiến thức | Biết 媾 (cấu) mở khoá 媾和 (giảng hòa), 交媾 (giao hợp), 姻媾 (hôn nhân liên minh).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary phân tích 媾 là chữ hình thanh gồm 女 (biểu nghĩa: phụ nữ) và 冓 (biểu âm). Nghĩa gốc: kết hôn giữa các họ hàng gần (hôn nhân củng cố quan hệ gia tộc). Nghĩa mở rộng: giảng hòa, đàm phán hòa bình; giao hợp. 媾和 là ký hòa ước. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kết hôn; giảng hoà; hợp lại", "Hạng Tần Suất (Jun Da)": "4506.0", "Tần Suất % (Jun Da)": "99.8601155662", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 冓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "媾", "Unihan_Traditional (Chữ Phồn thể)": "媾", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị việc kết giao, giao hợp sinh lý hoặc giảng hòa giữa các bên tranh chấp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龇', '{"9000": "4507.0", "Chữ Trung Quốc": "龇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 14 | nét | 龇 | tư | tượng hình | nhe răng, nhăn răng — giản thể của 齜 | 龇 là giản thể của 齜, đơn giản hóa bộ 齒 thành 齿. Wiktionary chỉ ghi {{Han simp|齜|f=齒|t=齿}} mà không cung cấp phân tích thành phần gốc. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": răng (齿) nhe ra — tư là nhăn nhó nhe răng, như khi đau hoặc tức giận. | Gương Hán-Việt | \"tư\" trong 龇牙咧嘴 (tư nha liệt chủy — nhe răng nhăn mặt) | Mở khoá kiến thức | Biết 龇 (tư) mở khoá 龇牙 (nhe răng), 龇牙咧嘴 (nhăn mặt nhe răng vì đau hoặc tức).", "Tự nguyên_Xie": "Tiểu triện | 龇 là dạng giản thể của 齜. Wiktionary chỉ ghi đây là biến thể giản hóa (Han simp), thay bộ 齒 bằng 齿. Nghĩa: nhe răng, nhăn răng (như khi tức giận hoặc đau). 龇牙咧嘴 là thành ngữ miêu tả nhăn mặt nhe răng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhe răng, nhăn răng", "Hạng Tần Suất (Jun Da)": "4507.0", "Tần Suất % (Jun Da)": "99.8602778367", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龇", "Unihan_Traditional (Chữ Phồn thể)": "齜", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "sài, thử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ vị ngữ trong câu, hay đi kèm với từ chỉ bộ phận cơ thể như răng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胯', '{"9000": "4508.0", "Chữ Trung Quốc": "胯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 胯 | khoa | tượng hình | vùng háng, xương chậu — bộ 月/肉 (thịt) + âm phù | 胯 không có phân tích thành phần rõ ràng trong anchor (chỉ ghi {{Han etym}} không có nội dung). Chữ có bộ 月/⺼ (nhục — thịt) biểu nghĩa, gợi liên quan đến bộ phận cơ thể. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoa\": thịt (月) vùng khoa chân — khoa là vùng háng, xương chậu — liên tưởng thành ngữ 胯下之辱 (nhục chui háng người — Hàn Tín nhẫn nhục). | Gương Hán-Việt | \"khoa\" trong 胯下之辱 (khoa hạ chi nhục — nỗi nhục chui qua háng) | Mở khoá kiến thức | Biết 胯 (khoa) mở khoá 胯下 (dưới háng), 跨胯 (chân dang rộng), thành ngữ 胯下之辱.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Anchor chỉ ghi {{Han etym}} không có nội dung. Chữ có bộ 月/⺼ (nhục — thịt) biểu nghĩa, gợi bộ phận cơ thể. Nghĩa: xương hông, vùng háng, bẹn, đùi trong. 胯下之辱 là thành ngữ nổi tiếng về Hàn Tín chui qua háng kẻ thù — nhẫn nhục chờ thời. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dưới bẹn, háng", "Hạng Tần Suất (Jun Da)": "4508.0", "Tần Suất % (Jun Da)": "99.8604395905", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胯", "Unihan_Traditional (Chữ Phồn thể)": "胯", "Pinyin_Xie": "kuà", "Âm Hán Việt_Xie": "khóa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ bộ phận cơ thể, đứng sau các từ chỉ vị trí hoặc làm tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涮', '{"9000": "4509.0", "Chữ Trung Quốc": "涮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 刷 | xoát | biểu âm | chải, quét | 涮 = 氵 (Thuỷ, biểu nghĩa: nước) + 刷 (Xoát, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 水 (氵) cho nghĩa, 刷 cho âm shuàn. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuyến\": nước (氵) quét qua (刷) thức ăn — nhúng, chần; cũng là súc rửa nhanh. | Gương Hán-Việt | \"xuyến\" ít dùng độc lập trong tiếng Việt; 涮 gặp trong 涮火锅 (nhúng lẩu) | Mở khoá kiến thức | Biết 涮 mở khoá 涮火锅 (ăn lẩu kiểu nhúng), 涮羊肉 (thịt cừu lẩu Bắc Kinh), 涮锅子 (nhúng nồi lẩu).", "Tự nguyên_Xie": "Chữ 涮 (xuyến) là chữ hình thanh (ls=psc): bộ 水 (氵 — Thuỷ) biểu nghĩa chỉ nước; 刷 (Xoát) biểu âm shuàn. Nghĩa gốc: rửa qua nước, súc miệng; mở rộng sang nghĩa nhúng thức ăn vào nước sôi (như lẩu). Thường gặp trong 涮火锅 (nhúng lẩu) và 涮羊肉 (thịt cừu nhúng lẩu Bắc Kinh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gột, súc, rửa qua loa; tái, nhúng, trần", "Hạng Tần Suất (Jun Da)": "4509.0", "Tần Suất % (Jun Da)": "99.8606013442", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 刷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵刷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涮", "Unihan_Traditional (Chữ Phồn thể)": "涮", "Pinyin_Xie": "shuàn", "Âm Hán Việt_Xie": "xuyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ vị ngữ biểu thị hành động nhúng đồ ăn vào nước sôi hoặc rửa qua loa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shuàn | / | chần | / | shuàn | / | tráng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绾', '{"9000": "4510.0", "Chữ Trung Quốc": "绾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绾 | oản | tượng hình | bó buộc, xâu lại — bộ 糸 (sợi chỉ) + âm phù | 绾 là giản thể của 綰. Anchor không cung cấp phân tích thành phần rõ ràng. Chữ có bộ 糸/纟 (mịch — sợi chỉ, vải) biểu nghĩa, gợi hành động dùng sợi để buộc, xâu. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oản\": sợi chỉ (纟) oán kết — oản là buộc chặt, xâu chuỗi lại, búi tóc thành búi tròn. | Gương Hán-Việt | \"oản\" trong 绾结 (oản kết — buộc thắt lại) | Mở khoá kiến thức | Biết 绾 (oản) mở khoá 绾结 (buộc thắt), 绾发 (búi tóc), 绾辖 (kiểm soát/giữ lại).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích hình-thanh cho 綰 trong anchor. Nghĩa: buộc, thắt nút, xâu chuỗi lại; cũng nghĩa là kiểm soát. Từ ghép cổ 綰結 (buộc thắt), 綰髮 (búi tóc). Chưa có nguồn học thuật xác nhận chi tiết cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bó buộc; mắc vào, xâu vào", "Hạng Tần Suất (Jun Da)": "4510.0", "Tần Suất % (Jun Da)": "99.860763098", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绾", "Unihan_Traditional (Chữ Phồn thể)": "綰", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "oản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ vị ngữ biểu thị hành động buộc, búi tóc hoặc thắt nút dây. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杈', '{"9000": "4511.0", "Chữ Trung Quốc": "杈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 叉 | xoa | biểu âm | chạc hai, nĩa | 杈 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 叉 (Xoa, biểu âm); chữ hình thanh. Phần 木 chỉ đây là vật liên quan đến cây/gỗ, phần 叉 cho âm đọc chā và gợi hình dạng chạc/nhánh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xoa\": cây (木) chạc xoa — xoa là nhánh cây chia đôi hình chữ Y, cũng là cái nang cày hai chạc. | Gương Hán-Việt | \"xoa\" trong 树杈 (thụ xoa — nhánh cây, chạc cây) | Mở khoá kiến thức | Biết 杈 (xoa) mở khoá 树杈 (chạc cây), 木杈 (thanh gỗ có chạc), 干杈 (cành khô phân nhánh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 杈 là chữ hình thanh gồm 木 (biểu nghĩa: cây/gỗ) và 叉 (biểu âm). Nghĩa: chạc cây (nơi cành tách ra), nhánh cây; cũng là công cụ nông nghiệp có nhiều răng như cái nĩa lớn. Cả âm chā và chà đều xuất hiện trong từ điển. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nang cây, chạc cây", "Hạng Tần Suất (Jun Da)": "4511.0", "Tần Suất % (Jun Da)": "99.8609248517", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 叉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木叉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杈", "Unihan_Traditional (Chữ Phồn thể)": "杈", "Pinyin_Xie": "chā", "Âm Hán Việt_Xie": "xoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ bộ phận của cây hoặc dụng cụ có hình chạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赳', '{"9000": "4512.0", "Chữ Trung Quốc": "赳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 9 | nét | 赳 | củ | tượng hình | hùng dũng, mạnh mẽ — bộ 走 (chạy) + ý dũng mãnh | 赳 không có phân tích thành phần rõ ràng trong anchor (Wiktionary không cung cấp Han compound). Chữ có bộ 走 (tẩu — chạy) biểu nghĩa, gợi hành động di chuyển mạnh bạo. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củ\": chạy (走) mạnh — củ là hùng dũng, mạnh mẽ như chiến binh xốc tới không lùi bước. | Gương Hán-Việt | \"củ\" trong 赳赳武夫 (củ củ vũ phu — người lính hùng dũng) | Mở khoá kiến thức | Biết 赳 (củ) mở khoá 赳赳 (hùng dũng mạnh mẽ), 赳赳武夫 (người lính dũng cảm).", "Tự nguyên_Xie": "Tiểu triện | Anchor không cung cấp phân tích hình-thanh cho 赳. Chữ có bộ 走 (chạy) biểu nghĩa. Wiktionary ghi hai âm: jiū (mạnh mẽ, dũng cảm — thường dùng trong 赳赳) và jiù (hình dạng rồng vươn cổ). 赳赳武夫 là cụm miêu tả võ sĩ dũng mãnh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hùng dũng", "Hạng Tần Suất (Jun Da)": "4512.0", "Tần Suất % (Jun Da)": "99.8610866054", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 丩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走丩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "赳", "Unihan_Traditional (Chữ Phồn thể)": "赳", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp trong các từ ghép mô tả dáng vẻ oai vệ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斛', '{"9000": "4513.0", "Chữ Trung Quốc": "斛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 斗 | Số nét | 11 | nét | 斛 | hộc | tượng hình | cái hộc đong thóc — đơn vị đo khô | 斛 không có phân tích thành phần rõ ràng trong anchor (Wiktionary không cung cấp Han compound). Chữ có bộ 斗 (đấu — đơn vị đo lường) liên quan đến ý nghĩa đơn vị đo. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộc\": cái hộc (đấu) đong thóc — hộc là đơn vị đo ngũ cốc cổ đại, bằng 10 đấu. | Gương Hán-Việt | \"hộc\" trong 石斛 (thạch hộc — phong lan dược liệu quý) | Mở khoá kiến thức | Biết 斛 (hộc) mở khoá 石斛 (phong lan thạch hộc — dendrobium), đơn vị đo cổ 斛 trong văn học sử liệu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Anchor không cung cấp phân tích hình-thanh cho 斛. Chữ có bộ 斗 (đấu — đơn vị đo khô). Nghĩa: đơn vị đo hạt khô, bằng khoảng 5 hoặc 10 đấu (đấu). Cũng dùng trong 石斛 (thạch hộc) — tên một loại phong lan dược liệu quý. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hộc đựng thóc; hộc (đơn vị đo, bằng 10 đấu)", "Hạng Tần Suất (Jun Da)": "4513.0", "Tần Suất % (Jun Da)": "99.8612483592", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "斛", "Unihan_Traditional (Chữ Phồn thể)": "斛", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này thường dùng làm danh từ chỉ đồ vật hoặc lượng từ đo lường dung tích thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觥', '{"9000": "4514.0", "Chữ Trung Quốc": "觥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 13 | nét | 觥 | cung | tượng hình | chén rượu lớn bằng sừng trâu — bộ 角 + dạng hình thú | 觥 không có phân tích thành phần rõ ràng trong anchor (chỉ ghi {{Han etym}} không có nội dung). Chữ có bộ 角 (giác — sừng) biểu nghĩa, gợi chén rượu làm từ sừng hoặc hình sừng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cung\": sừng (角) to như cung — cung là chén sừng trâu lớn, dùng uống rượu trong tiệc tưng bừng. | Gương Hán-Việt | \"cung\" trong 觥筹交错 (cung trù giao thác — tiệc rượu náo nhiệt) | Mở khoá kiến thức | Biết 觥 (cung) mở khoá 觥筹交错 (chén đũa lẫn lộn — tiệc rượu tưng bừng), 举觥 (nâng chén lớn).", "Tự nguyên_Xie": "Tiểu triện | Anchor chỉ ghi {{Han etym}} không có nội dung. Chữ có bộ 角 (sừng). Nghĩa: loại chén rượu lớn làm từ sừng trâu, có hình con vật — dùng trong tiệc rượu cổ đại. 觥筹交错 là thành ngữ miêu tả cảnh tiệc tùng tưng bừng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chén rượu bằng sừng trâu", "Hạng Tần Suất (Jun Da)": "4514.0", "Tần Suất % (Jun Da)": "99.8614101129", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觥", "Unihan_Traditional (Chữ Phồn thể)": "觥", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "quang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ vật dụng đựng rượu thời cổ, xuất hiện nhiều trong văn thơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疸', '{"9000": "4515.0", "Chữ Trung Quốc": "疸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疸 | đớn | tượng hình | bệnh vàng da — bộ 疒 (bệnh tật) | 疸 không có phân tích thành phần rõ ràng trong anchor (chỉ ghi {{Han etym}} không có nội dung). Chữ có bộ 疒 (nạch — bệnh tật) biểu nghĩa, gợi liên quan đến bệnh. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đớn\": bệnh (疒) đớn đau — đớn là chứng bệnh vàng da, da và mắt vàng do gan mật có vấn đề. | Gương Hán-Việt | \"đớn\" trong 黄疸 (hoàng đớn — bệnh vàng da) | Mở khoá kiến thức | Biết 疸 (đớn) mở khoá 黄疸 (hoàng đản — jaundice), 黄疸病 (bệnh vàng da).", "Tự nguyên_Xie": "Tiểu triện | Anchor chỉ ghi {{Han etym}} không có nội dung. Chữ có bộ 疒 (bệnh tật) biểu nghĩa. Nghĩa: bệnh hoàng đản (vàng da) — 黄疸 (hoàng đãn). Cũng nghĩa là các rối loạn dạ dày. Trong y học cổ truyền, đây là triệu chứng gan mật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chứng bệnh đản", "Hạng Tần Suất (Jun Da)": "4515.0", "Tần Suất % (Jun Da)": "99.8615718667", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疸", "Unihan_Traditional (Chữ Phồn thể)": "疸", "Pinyin_Xie": "dǎn", "Âm Hán Việt_Xie": "đản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ bệnh lý, hay kết hợp với các từ khác để tạo thành tên bệnh cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卞', '{"9000": "4516.0", "Chữ Trung Quốc": "卞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卜 | Số nét | 4 | nét | 卞 | biện | tượng hình | nóng nảy, bồn chồn — biến thể của 弁 (mũ lễ) | 卞 là biến thể của 弁. Wiktionary dẫn chứng sách cổ: 弁 bị viết méo thành 卞 qua chữ lệ thư. Chưa có phân tích thành phần độc lập — toàn bộ chữ là biến dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": chữ mũ (弁) viết méo — biện là nóng nảy, bồn chồn; cũng là họ nổi tiếng của Biện Hòa người dâng ngọc Hòa Thị Bích. | Gương Hán-Việt | \"biện\" trong 卞和 (Biện Hòa — người dâng viên ngọc quý) | Mở khoá kiến thức | Biết 卞 (biện) mở khoá họ 卞 (Biện), 卞急 (nóng vội), điển cố 卞和献璧 (Biện Hòa dâng ngọc).", "Tự nguyên_Xie": "Wiktionary dẫn 段玉裁 chú thích: 弁 bị viết méo thành 卞 qua quá trình lệ biến (biến hóa của chữ lệ thư). Trích: 弁之譌俗爲卞，由隸書而貤謬也 (Bính viết sai ra Biện là do lệ thư mà biến lệch). Nghĩa: nóng nảy, bồn chồn; cũng là họ tên (卞和 — Biện Hòa, người tìm ra ngọc bích). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nóng nảy, bồn chồn", "Hạng Tần Suất (Jun Da)": "4516.0", "Tần Suất % (Jun Da)": "99.8617331037", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亠", "Unihan_Simplified (Chữ Giản thể)": "卞", "Unihan_Traditional (Chữ Phồn thể)": "卞", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ họ người hoặc làm tính từ mô tả tính cách nóng nảy trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愠', '{"9000": "4517.0", "Chữ Trung Quốc": "愠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 愠 | uẩn | tượng hình | giận dữ, ấm ức — biến thể giản hóa của 慍 | 愠 là biến thể giản hóa của 慍, xuất hiện trong từ điển Long Khám Thủ Giám (997 SCN) và được chính thức hóa năm 1965. Wiktionary xác nhận đây là dạng giản thể svt (simplified variant). Chữ có bộ 忄 (tâm) biểu nghĩa — cảm xúc giận dữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": tim (忄) uẩn giận — uẩn ức là ấm ức giận dữ bên trong, như Khổng Tử: người không hiểu ta mà ta không giận. | Gương Hán-Việt | \"uẩn\" trong 愠怒 (uẩn nộ — giận dữ) | Mở khoá kiến thức | Biết 愠 (uẩn) mở khoá 愠怒 (giận dữ), 愠色 (vẻ mặt giận dỗi), câu Luận ngữ 人不知而不愠.", "Tự nguyên_Xie": "Wiktionary ghi 愠 là biến thể giản hóa không chính thống của 慍, xuất hiện trong 龍龕手鑑 (997 SCN). Chính thức hóa bởi PRC năm 1965 theo Xin Zixing. Cũng là dạng ưu tiên ở Hồng Kông cho chữ phồn thể. Nghĩa: giận dỗi, bực bội. Câu nổi tiếng: 人不知而不愠 (người không biết mà không giận) — Luận ngữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giận, hờn", "Hạng Tần Suất (Jun Da)": "4517.0", "Tần Suất % (Jun Da)": "99.8618943406", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愠", "Unihan_Traditional (Chữ Phồn thể)": "慍", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ trạng thái cảm xúc hoặc tính từ bổ nghĩa cho nét mặt, thái độ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拮', '{"9000": "4518.0", "Chữ Trung Quốc": "拮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 拮 | cất | tượng hình | tay và miệng cùng bận rộn — bộ 手 + âm phù | 拮 không có phân tích thành phần rõ ràng trong anchor (chỉ ghi {{Han etym}} không có nội dung). Chữ có bộ 扌 (thủ — tay) biểu nghĩa, gợi hành động lao động. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cất\": tay (扌) cất nhấc mãi không đủ — cất là khó nhọc, 拮据 là túng thiếu tiền bạc, tay lao động mà vẫn thiếu. | Gương Hán-Việt | \"cất\" trong 拮据 (cất cứ — túng thiếu, thiếu tiền) | Mở khoá kiến thức | Biết 拮 (cất) mở khoá 拮据 (túng thiếu, eo hẹp tiền bạc) — cụm thường gặp nhất.", "Tự nguyên_Xie": "Tiểu triện | Anchor chỉ ghi {{Han etym}} không có nội dung. Chữ có bộ 扌 (tay) biểu nghĩa. Nghĩa: tay và miệng cùng bận rộn làm việc, lao khổ. 拮据 là thành ngữ phổ biến nghĩa là túng thiếu, thiếu tiền. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tay và miệng cùng làm", "Hạng Tần Suất (Jun Da)": "4518.0", "Tần Suất % (Jun Da)": "99.8620550608", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拮", "Unihan_Traditional (Chữ Phồn thể)": "拮", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ xuất hiện trong từ ghép để chỉ sự túng thiếu về tiền bạc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庠', '{"9000": "4519.0", "Chữ Trung Quốc": "庠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 9 | nét | 广 | nghiễm | biểu nghĩa | mái hiên rộng, tòa nhà | 羊 | dương | biểu âm | con dê | 庠 = 广 (Nghiễm, biểu nghĩa: mái hiên/tòa nhà) + 羊 (Dương, biểu âm); chữ hình thanh. Phần 广 chỉ đây là công trình kiến trúc, phần 羊 cho âm đọc gần xiáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\": nhà (广) dê (羊) hiền lành — tường là trường học làng, nơi đào tạo học sinh hiền lành như dê. | Gương Hán-Việt | \"tường\" trong 庠序 (tường tự — trường học địa phương cổ) | Mở khoá kiến thức | Biết 庠 (tường) mở khoá 庠序 (hệ thống trường làng thời Chu), 庠生 (học sinh trường làng dự thi hương).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary phân tích 庠 là chữ hình thanh gồm 广 (biểu nghĩa: mái nhà/tòa nhà) và 羊 (biểu âm). Nghĩa: trường học làng (thời cổ đại Trung Hoa). 庠序 là hệ thống giáo dục địa phương thời Chu. 庠生 là học sinh trường làng được ghi danh trong kỳ thi hương. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trường học", "Hạng Tần Suất (Jun Da)": "4519.0", "Tần Suất % (Jun Da)": "99.862215781", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庠", "Unihan_Traditional (Chữ Phồn thể)": "庠", "Pinyin_Xie": "xiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ trường học thời xưa, xuất hiện trong các từ ghép cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烨', '{"9000": "4520.0", "Chữ Trung Quốc": "烨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 烨 | diệp | tượng hình | sáng rực rỡ — giản thể của 燁 (bộ 火 + 華) | 烨 là giản thể của 燁, thay bộ 華 bằng 华. Wiktionary chỉ ghi {{Han simp|燁|f=華|t=华}} mà không cung cấp phân tích thành phần gốc. Chữ gốc 燁 có bộ 火 (lửa) biểu nghĩa, gợi ánh sáng rực rỡ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệp\": lửa (火) rực sáng như hoa — diệp là sáng chói rực rỡ, lửa bùng lên chói ngời. | Gương Hán-Việt | \"diệp\" trong 烨烨 (diệp diệp — sáng rực rỡ) | Mở khoá kiến thức | Biết 烨 (diệp) mở khoá 烨烨 (rực rỡ chói ngời), thường dùng đặt tên con trai với ý nghĩa sáng ngời.", "Tự nguyên_Xie": "Tiểu triện | 烨 là giản thể của 燁. Wiktionary chỉ ghi Han simp, thay bộ 華 bằng 华. Chữ gốc 燁 có bộ 火 (lửa) biểu nghĩa, gợi ánh sáng chói lòa. Nghĩa: sáng rực rỡ, chói lóa, lửa bùng cháy. Thường dùng trong tên người (寓意: sáng ngời như lửa). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng chói, rực rỡ", "Hạng Tần Suất (Jun Da)": "4520.0", "Tần Suất % (Jun Da)": "99.8623765011", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 华", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火华", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "华", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烨", "Unihan_Traditional (Chữ Phồn thể)": "㷸", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "diệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả sự rực rỡ, thường dùng trong văn viết hoặc đặt tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龢', '{"9000": "4521.0", "Chữ Trung Quốc": "龢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龠 | Số nét | 22 | nét | 龢 | hòa | tượng hình | hòa hợp, êm ái — bộ 龠 (sáo nhạc nhiều ống) thổi cùng hòa âm | 龢 không có anchor Wiktionary (glyphOrigin là null). Chữ có bộ 龠 (nhược — sáo nhiều ống lỗ) biểu nghĩa, gợi âm nhạc hòa tấu. Đây là dạng cổ của 和. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hòa\": sáo nhiều lỗ (龠) phát ra âm hòa — hòa là hài hòa, êm ái như nhiều ống sáo cùng thổi. | Gương Hán-Việt | \"hòa\" trong 龢鸣 (hòa minh — tiếng hòa vang) | Mở khoá kiến thức | Biết 龢 (hòa) là dạng cổ của 和, mở khoá hiểu chữ 和 sâu hơn qua hình ảnh âm nhạc hòa tấu.", "Tự nguyên_Xie": "Kim văn | Anchor không có glyphOrigin (null). Chữ 龢 có bộ 龠 (sáo nhiều ống lỗ) biểu nghĩa — tiếng sáo nhiều ống phát ra hòa âm đẹp. Đây là dạng cổ xưa của 和 (hòa). Kim văn cho thấy chữ đã có từ thời đồng. Chưa có nguồn học thuật xác nhận chi tiết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn đủ để xác nhận phân tích hình-thanh. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùng, và; trộn lẫn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "龠 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龠禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龠", "Unihan_Simplified (Chữ Giản thể)": "龢", "Unihan_Traditional (Chữ Phồn thể)": "龢", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hoà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này là dạng cổ của chữ Hòa, dùng làm tính từ chỉ sự hài hòa hoặc động từ chỉ sự hòa hợp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菠', '{"9000": "4522.0", "Chữ Trung Quốc": "菠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菠 | ba | tượng hình | rau bina — bộ 艹 (cỏ) + âm phù | 菠 không có phân tích thành phần rõ ràng trong anchor (Wiktionary không cung cấp Han compound). Chữ có bộ 艹 (thảo — cỏ/rau) biểu nghĩa. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": cỏ (艹) ba lăng — ba là âm phiên từ tiếng Phạn/Ba Tư, 菠菜 là rau bina từ xứ Ba Tư du nhập vào Trung Quốc. | Gương Hán-Việt | \"ba\" trong 菠菜 (ba thái — rau bina) | Mở khoá kiến thức | Biết 菠 (ba) mở khoá 菠菜 (rau bina), 菠萝 (quả dứa/khóm), 菠萝蜜 (mít).", "Tự nguyên_Xie": "Anchor không cung cấp phân tích hình-thanh cho 菠. Chữ có bộ 艹 (cỏ/rau) biểu nghĩa. Nghĩa: dùng trong tên thực vật — 菠菜 (rau bina/rau chân vịt), 菠萝 (dứa/khóm). Chữ thuần chức năng phiên âm. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ba lăng 菠薐)", "Hạng Tần Suất (Jun Da)": "4522.0", "Tần Suất % (Jun Da)": "99.8626974247", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 波", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹波", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "波", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菠", "Unihan_Traditional (Chữ Phồn thể)": "菠", "Pinyin_Xie": "bō", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ dùng làm danh từ trong các từ ghép chỉ tên rau như ba thái hoặc ba lăng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窈', '{"9000": "4523.0", "Chữ Trung Quốc": "窈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 穴 | huyệt | biểu nghĩa | hang, hố, cái hốc | 幼 | ấu | biểu âm | nhỏ, non nớt | 窈 = 穴 (Huyệt, biểu nghĩa: hang/hố sâu) + 幼 (Ấu, biểu âm); chữ hình thanh. Phần 穴 chỉ nghĩa sâu thẳm, u kín, phần 幼 cho âm đọc gần yǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểu\": hang (穴) sâu nhỏ (幼) — yểu điệu là duyên dáng kín đáo như hốc hang sâu thẳm, ẩn sâu vẻ đẹp. | Gương Hán-Việt | \"yểu\" trong 窈窕 (yểu thiệu — duyên dáng, yểu điệu) | Mở khoá kiến thức | Biết 窈 (yểu) mở khoá 窈窕 (yểu điệu duyên dáng), câu Kinh Thi 窈窕淑女，君子好逑.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary phân tích 窈 là chữ hình thanh gồm 穴 (biểu nghĩa: hang/hố) và 幼 (biểu âm). Nghĩa: sâu thẳm, u tối, khuất kín. Cũng nghĩa là dáng điệu duyên dáng tinh tế của người phụ nữ. 窈窕淑女 là câu nổi tiếng trong Kinh Thi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu xa", "Hạng Tần Suất (Jun Da)": "4523.0", "Tần Suất % (Jun Da)": "99.8628576281", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窈", "Unihan_Traditional (Chữ Phồn thể)": "窈", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vẻ đẹp kín đáo, sâu lắng của người phụ nữ hoặc cảnh vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罄', '{"9000": "4524.0", "Chữ Trung Quốc": "罄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 17 | nét | 殸 | khánh | biểu âm | tiếng chuông | 缶 | phẫu | biểu nghĩa | bình gốm, đồ gốm rỗng | 罄 là chữ hình thanh: 缶 (Phẫu, biểu nghĩa: đồ gốm rỗng) + 殸 (Khánh, biểu âm). Ý nghĩa gốc là đồ gốm cạn hết — từ đó mở rộng sang ''hết sạch, cạn kiệt''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khánh\": bình gốm (缶) đã rỗng đến mức kêu vang như chuông khánh — tất cả đều ''cạn sạch''. | Gương Hán-Việt | khánh trong 告罄 (cáo khánh — thông báo đã hết hàng) | Mở khoá kiến thức | Biết 罄 mở khoá 告罄 (hết hàng), 售罄 (bán sạch), 罄竹難書 (tội ác chồng chất không kể hết).", "Tự nguyên_Xie": "Tiểu triện | 罄 là chữ hình thanh, theo Wiktionary: 殸 cho âm, 缶 (bình gốm) cho nghĩa. Hình ảnh gốc là bình gốm rỗng hoàn toàn — từ đó nghĩa mở rộng thành ''cạn kiệt, hết nhẵn''. Thành ngữ 罄竹難書 (khánh trúc nan thư) nghĩa đen là ''chặt hết tre cũng không đủ chép'' — để chỉ tội ác chồng chất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ rỗng ở trong; hết nhẵn, cạn kiệt", "Hạng Tần Suất (Jun Da)": "4524.0", "Tần Suất % (Jun Da)": "99.8630173147", "GavinGrover_Once (Chiết tự trực tiếp)": "殸 + 缶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殸缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罄", "Unihan_Traditional (Chữ Phồn thể)": "罄", "Pinyin_Xie": "qìng", "Âm Hán Việt_Xie": "khánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ hoặc động từ đứng sau động từ khác để chỉ trạng thái cạn kiệt, hết sạch. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囤', '{"9000": "4525.0", "Chữ Trung Quốc": "囤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 7 | nét | 囤 | đồn | tượng hình | hộp/thùng chứa thóc gạo, hàng tích trữ | 囤 là chữ tượng hình — hình dạng một vật chứa tròn (□ bên ngoài + 屯 bên trong). Không có anchor Wiktionary chi tiết về cấu trúc hình thanh/hội ý; cấu trúc gợi hình một thùng chứa (囗) tích lũy hàng hóa (屯).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồn\": cái thùng (囗) đầy ắp hàng tích trữ (屯) — như đồn trú quân lương để dự phòng. | Gương Hán-Việt | đồn trong 囤积 (đồn tích — tích trữ, đầu cơ hàng hóa) | Mở khoá kiến thức | Biết 囤 mở khoá 囤积 (tích trữ/đầu cơ), 囤货 (tích trữ hàng), 粮囤 (thùng thóc).", "Tự nguyên_Xie": "囤 (Hán-Việt: đồn) chỉ thùng chứa, kho dự trữ — đặc biệt là thóc gạo. Không có nguồn Wiktionary chi tiết về glyph origin. Dựa vào cấu trúc: 囗 (vòng bao ngoài = đồ vật) + 屯 (tích lũy) gợi ý hình ảnh tích trữ bên trong. chưa có nguồn học thuật xác nhận cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vựa để đựng thóc", "Hạng Tần Suất (Jun Da)": "4525.0", "Tần Suất % (Jun Da)": "99.8631764845", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囤", "Unihan_Traditional (Chữ Phồn thể)": "囤", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "độn, đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ chứa thóc hoặc động từ chỉ hành động tích trữ hàng hóa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弁', '{"9000": "4526.0", "Chữ Trung Quốc": "弁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 廾 | Số nét | 5 | nét | 厶 | biểu nghĩa | mũ (hình dạng cái mũ đặt lên đầu) | 廾 | trấp | biểu nghĩa | hai tay đưa lên | 弁 là chữ hội ý: 廾 (Trấp, hai tay đưa lên) + 厶 (hình cái mũ) — hình ảnh hai tay đặt mũ lên đầu ai đó. Chữ hội ý (ls=ic), không có phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": hai tay (廾) cẩn thận đặt mũ lễ (厶) lên đầu — nghi lễ đội mũ quan biện. | Gương Hán-Việt | biện trong 弁言 (biện ngôn — lời tựa, lời mở đầu) | Mở khoá kiến thức | Biết 弁 mở khoá 弁言 (lời tựa), 武弁 (võ quan đội mũ), 弁冕 (mũ quan tước).", "Tự nguyên_Xie": "弁 là chữ hội ý theo Wiktionary: 廾 (hai tay) + 厶 (hình mũ) — cảnh hai tay đội mũ lên đầu người. Nghĩa gốc là mũ lễ, mũ của quan lại thời cổ. Sau đó mở rộng sang nghĩa ''lời mở đầu'' (như bài tựa đặt trước sách) và ''tước hiệu nhỏ''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1716.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tư (028) Củng (055)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tư (số 028 - riêng tư/ 厶) ở trên chữ Củng (số 055 - chắp tay/ 廾). Trông giống hình ảnh vị võ quan hai tay nâng cái mũ để đội lên đầu. Giải thích sự chuyển ý: Đây là chữ Hội ý. Biện là chiếc mũ da đội đầu của các vị quan võ thời xưa. (Khác với mũ Cù của quan văn).", "Nghĩa Tiếng Việt_Xie": "mũ lớn của quan văn và quan võ", "Hạng Tần Suất (Jun Da)": "4526.0", "Tần Suất % (Jun Da)": "99.8633356544", "GavinGrover_Once (Chiết tự trực tiếp)": "厶 + 艹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厶艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厶", "Unihan_Simplified (Chữ Giản thể)": "弁", "Unihan_Traditional (Chữ Phồn thể)": "弁", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ loại mũ cổ hoặc động từ với nghĩa đặt ở phía trước, làm lời mở đầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奘', '{"9000": "4527.0", "Chữ Trung Quốc": "奘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 10 | nét | 壯 | tráng | biểu âm | mạnh mẽ, to lớn | 大 | đại | biểu nghĩa | lớn, to | 奘 là chữ hình thanh: 大 (Đại, biểu nghĩa: lớn) + 壯 (Tráng, biểu âm). Nghĩa chỉ vóc dáng to lớn, đặc biệt dùng để chỉ người hoặc vật thể đồ sộ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạng\": 大 (to lớn) kết hợp với 壯 (tráng kiện) — người to lớn hùng tráng, như Đường Tăng Huyền Tạng đủ sức vượt vạn dặm. | Gương Hán-Việt | tạng trong 玄奘 (Huyền Tạng — pháp danh Đường Tăng) | Mở khoá kiến thức | Biết 奘 chủ yếu mở khoá 玄奘 (Huyền Tạng), nhân vật lịch sử nổi tiếng trong Tây Du Ký.", "Tự nguyên_Xie": "奘 (Hán-Việt: tạng) là chữ hình thanh theo Wiktionary: 壯 (tráng) cho âm, 大 (đại, lớn) cho nghĩa. Chữ chỉ sự to lớn, đồ sộ. Nổi tiếng nhất qua pháp danh Đường Tăng — Huyền Trang (玄奘), vị cao tăng Đường triều đi thỉnh kinh từ Ấn Độ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn", "Hạng Tần Suất (Jun Da)": "4527.0", "Tần Suất % (Jun Da)": "99.8634948242", "GavinGrover_Once (Chiết tự trực tiếp)": "壯 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱壯大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奘", "Unihan_Traditional (Chữ Phồn thể)": "奘", "Pinyin_Xie": "zàng", "Âm Hán Việt_Xie": "trang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vóc dáng to lớn, thường gặp trong tên riêng như Đường Tam Tạng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咣', '{"9000": "4528.0", "Chữ Trung Quốc": "咣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng — chỉ âm thanh phát ra | 光 | quang | biểu âm | biểu âm: quang/guāng | 咣 là chữ hình thanh: 口 (Khẩu, biểu nghĩa: âm thanh/miệng) + 光 (Quang, biểu âm). Chữ mô phỏng tiếng động lớn, đanh, như tiếng va đập hay tiếng súng nổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quàng\": miệng (口) phát ra âm 光 (quang) — tiếng ''quàng'' vang lớn như tiếng cửa đập mạnh. | Gương Hán-Việt | quàng trong tiếng Việt phương ngữ: tiếng động oang oang | Mở khoá kiến thức | Biết 咣 giúp nhận biết nhóm chữ tượng thanh có 口 + âm tiết gần âm tiếng tạo ra.", "Tự nguyên_Xie": "咣 là chữ hình thanh Việt-Hán (theo Wiktionary, mục vi): 口 (miệng/âm thanh) + 光 (cho âm quang). Dùng trong tiếng Việt phương ngữ để ghi âm tiếng ''oang oang'' — tiếng động mạnh, đanh. Cũng là từ tượng thanh trong tiếng Trung hiện đại chỉ tiếng va đập lớn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hay nói; tiếng khua chiêng trống oang oang", "Hạng Tần Suất (Jun Da)": "4528.0", "Tần Suất % (Jun Da)": "99.863653994", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咣", "Unihan_Traditional (Chữ Phồn thể)": "咣", "Pinyin_Xie": "guāng", "Âm Hán Việt_Xie": "quang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này là từ tượng thanh mô phỏng tiếng va đập mạnh của cửa hoặc vật kim loại. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缫', '{"9000": "4529.0", "Chữ Trung Quốc": "缫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 缫 | táo | tượng hình | kéo tơ từ kén tằm | 缫 là chữ có bộ 糸 (tơ/sợi) nhưng cấu trúc chi tiết không có trong anchor. Dựa vào cấu trúc tổng thể: bộ 糸 (biểu nghĩa: tơ sợi) + phần còn lại biểu âm. Không có Wiktionary glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": bộ 糸 (tơ) — đôi tay khéo léo kéo sợi tơ mảnh từ kén tằm, nhẹ nhàng và kiên nhẫn như người thợ ươm tơ. | Gương Hán-Việt | táo trong 缫丝 (táo ti — ươm tơ, kéo tơ) | Mở khoá kiến thức | Biết 缫 mở khoá 缫丝 (kéo tơ từ kén), 缫丝机 (máy kéo tơ), các từ liên quan đến nghề tơ lụa.", "Tự nguyên_Xie": "缫 (Hán-Việt: táo) nghĩa là kéo tơ từ kén tằm (reeling silk from cocoon). Không có Wiktionary glyph origin chi tiết trong anchor. Chữ thuộc bộ 糸 (tơ), cho thấy liên quan đến ngành dệt tơ lụa. Nghề ươm tơ tằm là một trong những nghề thủ công cổ truyền quan trọng nhất của Trung Hoa. chưa có nguồn học thuật xác nhận glyph cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ươm tơ (kéo tơ ở kén ra)", "Hạng Tần Suất (Jun Da)": "4529.0", "Tần Suất % (Jun Da)": "99.8638131638", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 巢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟巢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缫", "Unihan_Traditional (Chữ Phồn thể)": "繅", "Pinyin_Xie": "sāo", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hoạt động sản xuất tơ lụa thủ công hoặc công nghiệp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腴', '{"9000": "4530.0", "Chữ Trung Quốc": "腴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腴 | du | tượng hình | bụng dưới, phần thịt mỡ bụng | 腴 thuộc bộ 肉/月 (thịt) nhưng anchor không cung cấp cấu trúc cụ thể. Chữ chỉ phần thịt mỡ vùng bụng, từ đó nghĩa mở rộng thành ''béo tốt, mập mạp'' (người) và ''màu mỡ, phì nhiêu'' (đất). chưa có nguồn học thuật xác nhận glyph cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": bộ 肉 (thịt) — phần bụng đầy đặn, mỡ màng — người du dưỡng, đất du dưỡng (màu mỡ). | Gương Hán-Việt | du trong 丰腴 (phong du — đầy đặn, phong phú) | Mở khoá kiến thức | Biết 腴 mở khoá 丰腴 (đầy đặn, phong phú), 肥腴 (béo tốt), 沃腴 (đất màu mỡ) trong văn học cổ điển.", "Tự nguyên_Xie": "腴 (Hán-Việt: du) chỉ phần thịt mỡ bụng, từ đó mở rộng sang nghĩa ''béo tốt'' (về người) và ''đất màu mỡ''. Không có Wiktionary glyph origin chi tiết. Chữ thuộc bộ 肉 (thịt), phù hợp với nghĩa về thể chất. Trong văn học cổ thường gặp cụm 沃腴 (mảnh đất phì nhiêu). chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ sệ bụng; béo tốt; ruột lợn, ruột chó", "Hạng Tần Suất (Jun Da)": "4530.0", "Tần Suất % (Jun Da)": "99.8639723336", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 臾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月臾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腴", "Unihan_Traditional (Chữ Phồn thể)": "腴", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả đất đai màu mỡ hoặc cơ thể đầy đặn, béo tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缈', '{"9000": "4531.0", "Chữ Trung Quốc": "缈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缈 | diểu | tượng hình | mờ ảo, xa xa khó thấy | 缈 thuộc bộ 糸 (tơ/sợi mỏng) nhưng anchor không cung cấp cấu trúc chi tiết. Liên quan đến 渺 và 眇 (đều chỉ sự nhỏ bé, mờ xa). Bộ 糸 gợi hình sợi tơ mỏng mảnh bay xa, biến mất vào không trung. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diểu\": sợi tơ (糸) mỏng manh trôi xa, diệu viễn — hình ảnh sương khói mờ ảo không nắm bắt được. | Gương Hán-Việt | diểu trong 缥缈 (phiêu diểu — huyền ảo, mờ ảo) | Mở khoá kiến thức | Biết 缈 mở khoá 缥缈 (phiêu diểu), 虚无缥缈 (hư vô phiêu diểu — mơ hồ, không thực) trong thơ văn.", "Tự nguyên_Xie": "缈 (Hán-Việt: diểu) chỉ sự mờ ảo, xa xa khó thấy, không rõ ràng. Không có Wiktionary glyph origin. Thường gặp trong 缥缈/飘渺 (phiêu diểu — mờ ảo, huyền ảo). Bộ 糸 gợi hình sợi tơ mỏng mảnh biến mất dần. chưa có nguồn học thuật xác nhận glyph cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mù mịt, thăm thẳm", "Hạng Tần Suất (Jun Da)": "4531.0", "Tần Suất % (Jun Da)": "99.8641309867", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 眇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟眇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缈", "Unihan_Traditional (Chữ Phồn thể)": "緲", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "diểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ hoặc kết hợp thành từ ghép như phiêu diểu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喵', '{"9000": "4532.0", "Chữ Trung Quốc": "喵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng — chỉ âm thanh | 苗 | miêu | biểu âm | biểu âm: miêu/miāo | 喵 là chữ hình thanh: 口 (Khẩu, biểu nghĩa: âm thanh/tiếng kêu) + 苗 (Miêu, biểu âm). Là từ tượng thanh hiện đại mô phỏng tiếng mèo kêu ''meo''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mếu\": miệng (口) mèo kêu âm 苗 (miêu) — tiếng ''meo meo'' của mèo, dễ nhớ vì phát âm giống nhau. | Gương Hán-Việt | mếu/miêu trong 喵喵叫 (mèo kêu meo meo) | Mở khoá kiến thức | Biết 喵 mở khoá ngôn ngữ mạng Trung Quốc: 喵星人 (người hành tinh mèo — cách gọi mèo dễ thương), 喵主子 (chủ tể mèo).", "Tự nguyên_Xie": "喵 là chữ hình thanh theo Wiktionary: 口 (âm thanh) + 苗 (Miêu, biểu âm). Chữ tương đối mới, dùng để ghi âm tiếng mèo kêu — không có dạng giáp cốt hay kim văn. Trong tiếng Trung hiện đại và ngôn ngữ mạng, 喵 còn được dùng để chỉ mèo nói chung hay thể hiện sự dễ thương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng mèo kêu meo meo", "Hạng Tần Suất (Jun Da)": "4532.0", "Tần Suất % (Jun Da)": "99.8642891229", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 苗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口苗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "苗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喵", "Unihan_Traditional (Chữ Phồn thể)": "喵", "Pinyin_Xie": "miāo", "Âm Hán Việt_Xie": "miêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Chữ này dùng làm từ mô phỏng âm thanh tiếng mèo kêu hoặc làm thán từ biểu thị sự dễ thương. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潢', '{"9000": "4533.0", "Chữ Trung Quốc": "潢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | biểu nghĩa | nước, sông | 黄 | hoàng | biểu âm | vàng, màu vàng | 潢 là chữ hình thanh: 氵(biểu nghĩa: nước/sông) + 黄 (Hoàng, biểu âm). Nghĩa gốc là hồ nước, ao lớn, hoặc dòng nước vàng đục — từ đó dùng để đặt tên địa danh và chỉ nghề sơn phết, tô màu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": nước (氵) màu vàng (黄) — ao hồ trang hoàng vàng óng, hay nghề 装潢 trang trí nhà cửa. | Gương Hán-Việt | hoàng trong 装潢 (trang hoàng — trang trí, thiết kế nội thất) | Mở khoá kiến thức | Biết 潢 mở khoá 装潢 (trang hoàng/thiết kế nội thất), 潢池 (ao vàng), từ thường gặp trong ngành xây dựng trang trí.", "Tự nguyên_Xie": "潢 (Hán-Việt: hoàng) là chữ hình thanh theo Wiktionary: 氵 (nước) + 黄 (Hoàng, biểu âm). Nghĩa gốc là ao hồ, vùng nước đọng. Ngoài ra còn dùng theo nghĩa 潢池 (ao/hồ vàng), và trong 装潢 (trang hoàng — trang trí, sơn phết) — nghề đóng bìa sách thời xưa dùng nước hồ vàng để phết giấy. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ao", "Hạng Tần Suất (Jun Da)": "4533.0", "Tần Suất % (Jun Da)": "99.8644472592", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潢", "Unihan_Traditional (Chữ Phồn thể)": "潢", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ ao hồ hoặc làm động từ với nghĩa trang trí, tô điểm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遛', '{"9000": "4534.0", "Chữ Trung Quốc": "遛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 13 | nét | 辵 | biểu nghĩa | bước đi, đi đường | 留 | lưu | biểu âm | ở lại, lưu giữ | 遛 là chữ hình thanh: 辵 (biểu nghĩa: bước đi) + 留 (Lưu, biểu âm). Ý nghĩa là đi tản bộ chậm rãi — bước đi mà ''lưu lại'' từng bước, không vội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bước đi (辵) mà lưu (留) lại thong thả — dắt chó đi dạo, không vội không vàng. | Gương Hán-Việt | lưu trong 遛狗 (lưu cẩu — dắt chó đi dạo) | Mở khoá kiến thức | Biết 遛 mở khoá 遛狗 (dắt chó đi dạo), 遛弯 (tản bộ, đi lòng vòng), 遛马 (dắt ngựa đi lại).", "Tự nguyên_Xie": "遛 (Hán-Việt: lưu) là chữ hình thanh theo Wiktionary: 辵 (bước đi) + 留 (Lưu, biểu âm). Nghĩa là dắt (chó, ngựa) đi dạo, hoặc tự mình tản bộ. Hình ảnh đi bộ chậm rãi, từng bước, không vội vàng — bước mà ''lưu'' lại từng khoảnh khắc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứng dừng lại không tiến lên nữa", "Hạng Tần Suất (Jun Da)": "4534.0", "Tần Suất % (Jun Da)": "99.8646053954", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遛", "Unihan_Traditional (Chữ Phồn thể)": "遛", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm tân ngữ chỉ thú cưng hoặc địa điểm đi dạo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | liù | / | dạo chơi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào I | New HSK 7-9 | · | Động vật và côn trùng", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柚', '{"9000": "4535.0", "Chữ Trung Quốc": "柚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 由 | do | biểu âm | do, từ đó | 柚 là chữ hình thanh: 木 (Mộc, biểu nghĩa: cây/gỗ) + 由 (Do, biểu âm). Chỉ loại cây bưởi (柚子 yòuzi) hoặc gỗ teak (柚木).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dâu\": cây (木) có âm 由 (do) — trái bưởi 柚子 tròn to, màu vàng, xuất hiện nhiều vào Tết Trung Thu. | Gương Hán-Việt | dâu trong 柚子 (dâu tử — quả bưởi); 柚木 (dâu mộc — gỗ teak) | Mở khoá kiến thức | Biết 柚 mở khoá 柚子 (bưởi — trái cây phổ biến trong Tết Trung Thu), 柚木 (gỗ teak), 沙田柚 (bưởi Sa Điền).", "Tự nguyên_Xie": "柚 (Hán-Việt: dâu) là chữ hình thanh theo Wiktionary: 木 (cây) + 由 (Do, biểu âm). Chỉ hai loại cây khác nhau tùy đọc âm: yòu = quả bưởi (Citrus maxima), yóu = cây teak (Tectona grandis, gỗ quý). Cả hai đều là thực vật, phù hợp với bộ 木. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con thoi (để dệt vải)", "Hạng Tần Suất (Jun Da)": "4535.0", "Tần Suất % (Jun Da)": "99.8647635317", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柚", "Unihan_Traditional (Chữ Phồn thể)": "柚", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "dữu, trục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ quả bưởi hoặc con thoi trong khung cửi dệt vải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郏', '{"9000": "4536.0", "Chữ Trung Quốc": "郏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 8 | nét | 郏 | giáp | tượng hình | địa danh, tên đất | 郏 chứa bộ 阝(邑, chỉ địa phương/thành ấp) — đây là chữ dùng chủ yếu trong địa danh. Anchor không có cấu trúc chi tiết. Bộ 邑 ở bên phải là dấu hiệu chữ liên quan đến vùng đất, địa danh. chưa có nguồn học thuật xác nhận glyph cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": bộ 阝(ấp/địa phương) — tên một vùng đất ở Hà Nam — nhớ như ''giáp ranh, giáp danh một vùng đất''. | Gương Hán-Việt | giáp trong 郏县 (Giáp huyện — huyện Giáp tỉnh Hà Nam) | Mở khoá kiến thức | Biết 郏 chủ yếu giúp đọc địa danh: 郏县 (huyện Giáp, Hà Nam) trong văn bản lịch sử và địa lý Trung Quốc.", "Tự nguyên_Xie": "郏 (Hán-Việt: giáp) là chữ dùng trong địa danh, chủ yếu trong tên huyện Giáp (郏县) tại tỉnh Hà Nam, Trung Quốc. Bộ 邑/阝 chỉ thành ấp/địa phương. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "4536.0", "Tần Suất % (Jun Da)": "99.8649211511", "GavinGrover_Once (Chiết tự trực tiếp)": "夹 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夹阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郏", "Unihan_Traditional (Chữ Phồn thể)": "郟", "Pinyin_Xie": "jiá", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng chỉ địa danh cổ hoặc dùng trong họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荻', '{"9000": "4537.0", "Chữ Trung Quốc": "荻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 荻 | địch | tượng hình | cây lau sậy (Miscanthus sacchariflorus) | 荻 thuộc bộ 艹 (thảo — cỏ, cây cỏ) nhưng anchor không cung cấp cấu trúc chi tiết hơn. Bộ 艹 biểu nghĩa chỉ thực vật. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận glyph cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": cỏ (艹) lau sậy cao mọc ven sông — hình ảnh 芦荻萧萧 (lau sậy xào xạc) trong thơ thu cổ điển. | Gương Hán-Việt | địch trong 芦荻 (lô địch — lau sậy) trong thơ văn cổ điển | Mở khoá kiến thức | Biết 荻 mở khoá 芦荻 (lau sậy — hình ảnh thơ mùa thu), tên loài thực vật trong văn học cổ Trung Hoa.", "Tự nguyên_Xie": "荻 (Hán-Việt: địch) chỉ cây lau sậy Amur silvergrass (Miscanthus sacchariflorus) — loại cỏ cao lớn mọc ven sông hồ. Không có Wiktionary glyph origin. Bộ 艹 (thảo) xác nhận đây là thực vật. Trong thơ cổ Trung Hoa, 芦荻 (lô địch — lau sậy) thường gợi cảnh buồn thu, chia ly. chưa có nguồn học thuật xác nhận glyph cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ địch (một loại có giống lau)", "Hạng Tần Suất (Jun Da)": "4537.0", "Tần Suất % (Jun Da)": "99.8650787706", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 狄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹狄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荻", "Unihan_Traditional (Chữ Phồn thể)": "荻", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân thảo giống như cây lau sậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藜', '{"9000": "4538.0", "Chữ Trung Quốc": "藜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藜 | lê | tượng hình | cây rau dền (goosefoot, Chenopodium album) | 藜 thuộc bộ 艹 (thảo) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 艹 biểu nghĩa chỉ thực vật. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lê\": cỏ dại (艹) thanh đạm — người ẩn sĩ chống gậy cây lê (藜杖) đi giữa đồng hoang. | Gương Hán-Việt | lê trong 藜杖 (lê trượng — gậy cây lê, gậy của người ẩn sĩ) | Mở khoá kiến thức | Biết 藜 mở khoá 藜杖 (gậy cây lê), 藜藿 (rau dền nghèo khó) trong văn học cổ điển về ẩn cư, thanh đạm.", "Tự nguyên_Xie": "藜 (Hán-Việt: lê) chỉ cây rau dền/goosefoot (Chenopodium album) — loại cây dại ăn được, thường mọc hoang. Trong văn học cổ, 藜杖 (gậy cây lê) là vật tùy thân của người ẩn sĩ. Không có Wiktionary glyph origin chi tiết. Bộ 艹 xác nhận là thực vật. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tật lê 蒺藜,蒺蔾)", "Hạng Tần Suất (Jun Da)": "4538.0", "Tần Suất % (Jun Da)": "99.8652363901", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 黎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹黎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藜", "Unihan_Traditional (Chữ Phồn thể)": "藜", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại rau dại hoặc cây thảo dùng làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琨', '{"9000": "4539.0", "Chữ Trung Quốc": "琨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 琨 | côn | tượng hình | ngọc quý đẹp | 琨 thuộc bộ 王/玉 (ngọc bích) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 玉 biểu nghĩa chỉ đồ ngọc. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": bộ ngọc (玉) — viên ngọc quý sáng bóng, thường dùng đặt tên con trai mang nghĩa cao quý, tinh anh. | Gương Hán-Việt | côn trong 琨瑶 (côn dao — ngọc quý đẹp) trong thơ văn cổ | Mở khoá kiến thức | Biết 琨 giúp nhận biết nhóm chữ bộ 玉 chỉ loại ngọc: 琨, 琼, 琛, 珂 — thường dùng đặt tên người.", "Tự nguyên_Xie": "琨 (Hán-Việt: côn) có nghĩa là ngọc đẹp, ngọc quý (trong văn học cổ). Không có Wiktionary glyph origin chi tiết. Bộ 玉 (ngọc) xác nhận liên quan đến đá quý, đồ ngọc. Chữ này chủ yếu dùng trong tên người (đặc biệt nam) mang ý nghĩa quý giá, cao quý. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc côn", "Hạng Tần Suất (Jun Da)": "4539.0", "Tần Suất % (Jun Da)": "99.8653940095", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琨", "Unihan_Traditional (Chữ Phồn thể)": "琨", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ ngọc quý, thường dùng trong tên người hoặc văn chương cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镳', '{"9000": "4540.0", "Chữ Trung Quốc": "镳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 镳 | tiêu | tượng hình | hàm thiếc ngựa, dây cương | 镳 thuộc bộ 钅/金 (kim loại) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 金 biểu nghĩa chỉ đồ kim loại. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": kim loại (钅) hàm ngựa — 分道扬镳 (phân đạo dương tiêu): mỗi con ngựa nhai hàm riêng, mỗi người đi đường riêng. | Gương Hán-Việt | tiêu trong 分道扬镳 (phân đạo dương tiêu — chia đường ai đi đường nấy) | Mở khoá kiến thức | Biết 镳 mở khoá thành ngữ 分道扬镳 (chia tay, mỗi người theo con đường riêng) — rất phổ biến trong văn viết tiếng Trung.", "Tự nguyên_Xie": "镳 (Hán-Việt: tiêu) nghĩa là hàm thiếc (horse bit) — miếng kim loại đặt vào miệng ngựa để điều khiển. Theo ngữ cảnh, nghĩa mở rộng chỉ ngựa nói chung. Không có Wiktionary glyph origin chi tiết. Nổi tiếng trong thành ngữ 分道扬镳 (phân đạo dương tiêu — mỗi người đi một đường). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hàm thiết ngựa; cái phi tiêu (một loại ám khí)", "Hạng Tần Suất (Jun Da)": "4540.0", "Tần Suất % (Jun Da)": "99.8655511122", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 麃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅麃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镳", "Unihan_Traditional (Chữ Phồn thể)": "鑣", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận hàm thiếc ngựa hoặc vũ khí phóng đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雉', '{"9000": "4541.0", "Chữ Trung Quốc": "雉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 13 | nét | 雉 | trĩ | tượng hình | chim trĩ (pheasant) | 雉 chứa bộ 隹 (chim ngắn đuôi) — Wiktionary không cung cấp thêm cấu trúc. Đây là tượng hình hoặc hội ý chỉ loài chim trĩ. Bộ 隹 biểu nghĩa chỉ loài chim. chưa có nguồn học thuật xác nhận glyph cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": bộ chim (隹) — chim trĩ đực sặc sỡ, cánh đuôi dài đẹp như cầu vồng, khó quên. | Gương Hán-Việt | trĩ trong 野雉 (dã trĩ — chim trĩ hoang), 锦雉 (cẩm trĩ — chim trĩ lông đẹp) | Mở khoá kiến thức | Biết 雉 mở khoá 野雉 (chim trĩ hoang), 雉堞 (chỗ có lỗ châu mai trên tường thành) trong văn học và lịch sử Trung Hoa.", "Tự nguyên_Xie": "雉 (Hán-Việt: trĩ) chỉ chim trĩ (pheasant) — loài chim với bộ lông sặc sỡ, đặc biệt con trống. Bộ 隹 (chim ngắn đuôi) xác nhận là loài chim. Không có Wiktionary glyph origin chi tiết. Trong văn học cổ, 雉 còn là đơn vị đo chiều dài tường thành (1 雉 = 3 trượng dài, 1 trượng cao). chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chim trĩ, con dẽ", "Hạng Tần Suất (Jun Da)": "4541.0", "Tần Suất % (Jun Da)": "99.8657076981", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "雉", "Unihan_Traditional (Chữ Phồn thể)": "雉", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim trĩ hoặc dùng trong văn cảnh cổ chỉ bức tường thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橐', '{"9000": "4542.0", "Chữ Trung Quốc": "橐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 石 | thạch | biểu âm | đá | 橐 là chữ hình thanh theo Wiktionary: ban đầu là tượng hình (hình chiếc túi có đáy), sau được chuẩn hóa thành cấu trúc 石 (biểu âm) + phần chỉ túi (biểu nghĩa). Chữ tạo muộn, chưa thấy rõ trong giáp cốt/kim văn với dạng ổn định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": hình chiếc túi bao tải — con lạc đà (橐驼) lưng gù như cái túi khổng lồ chứa hàng. | Gương Hán-Việt | thác trong 橐驼 (thác đà — lạc đà) và 行橐 (hành thác — hành lý, tư trang) | Mở khoá kiến thức | Biết 橐 mở khoá 橐驼 (lạc đà), 行橐 (hành lý), 橐囊 (bao tải) trong văn học cổ.", "Tự nguyên_Xie": "橐 (Hán-Việt: thác) trong chữ giáp cốt là tượng hình: hình chiếc túi có đáy, so sánh với 𣒚, 束, 東. Sau đó chuyển sang hình thanh với 石 biểu âm. Nghĩa chính là cái túi lớn, bao tải. Thường gặp trong 行橐 (hành trang), 橐驼 (lạc đà — lưng mang túi). Theo Wiktionary anchor: hình tượng túi với đáy trong chữ cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái túi không có đáy; đồ rèn đúc", "Hạng Tần Suất (Jun Da)": "4542.0", "Tần Suất % (Jun Da)": "99.8658637672", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "橐", "Unihan_Traditional (Chữ Phồn thể)": "橐", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại túi không đáy hoặc túi da đựng đồ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骈', '{"9000": "4543.0", "Chữ Trung Quốc": "骈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 馬 | mã | biểu nghĩa | ngựa | 并 | tinh | biểu âm | sánh ngang, đứng cạnh nhau | 骈 là chữ hình thanh: 馬 (Mã, biểu nghĩa: ngựa) + 并 (Tinh/Bính, biểu âm). Nghĩa gốc là hai ngựa song song kéo xe, từ đó mở rộng sang ''sóng đôi, song hành'' và đặc biệt chỉ thể văn biền ngẫu (骈文) — lối viết đối câu từng cặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biền\": hai con ngựa (馬) sóng đôi (并) kéo xe — biền ngẫu, sóng đôi đẹp đều như văn biền ngẫu. | Gương Hán-Việt | biền trong 骈文 (biền văn — thể văn biền ngẫu), 骈俪 (biền lệ — đối ngẫu) | Mở khoá kiến thức | Biết 骈 mở khoá 骈文 (biền văn), 骈俪 (đối ngẫu), 骈枝 (nhánh sinh đôi) trong văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "骈 (Hán-Việt: biền) là chữ hình thanh theo Wiktionary: 馬 (ngựa) + 并 (song song, biểu âm). Hình ảnh hai ngựa kéo xe song song — biểu tượng cho sự sóng đôi, đối xứng. 骈文 (biền văn) là thể văn cổ viết thành từng cặp câu đối xứng về cả âm điệu lẫn nghĩa, đặc biệt thịnh hành thời Nam Bắc triều. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hai ngựa đóng kèm nhau (chạy song song); song song, đối nhau, sát nhau, liền nhau", "Hạng Tần Suất (Jun Da)": "4543.0", "Tần Suất % (Jun Da)": "99.8661753887", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骈", "Unihan_Traditional (Chữ Phồn thể)": "駢", "Pinyin_Xie": "pián", "Âm Hán Việt_Xie": "biền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ việc ghép đôi hoặc làm tính từ mô tả thể văn biền ngẫu song hành. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛉', '{"9000": "4544.0", "Chữ Trung Quốc": "蛉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蛉 | linh | tượng hình | côn trùng nhỏ (chuồn chuồn, ve nhỏ) | 蛉 thuộc bộ 虫 (côn trùng) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 虫 biểu nghĩa chỉ côn trùng. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": con côn trùng (虫) nhỏ linh hoạt — 蜻蛉 (chuồn chuồn linh) bay nhẹ nhàng trên mặt nước. | Gương Hán-Việt | linh trong 蜻蛉 (thanh linh — chuồn chuồn), 螟蛉 (minh linh — con nuôi) | Mở khoá kiến thức | Biết 蛉 mở khoá 蜻蛉 (chuồn chuồn), 螟蛉之子 (con nuôi, con nhận nuôi) — thành ngữ quan trọng trong văn học.", "Tự nguyên_Xie": "蛉 (Hán-Việt: linh) chỉ loài côn trùng nhỏ, thường gặp trong 蜻蛉 (chuồn chuồn) và 螟蛉 (sâu bướm — con của người nuôi dưỡng). Không có Wiktionary glyph origin chi tiết. Bộ 虫 xác nhận là côn trùng. 螟蛉之子 (螟蛉chi tử — con nuôi) là thành ngữ chỉ con nuôi. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tinh linh 蜻蛉)", "Hạng Tần Suất (Jun Da)": "4544.0", "Tần Suất % (Jun Da)": "99.866330941", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛉", "Unihan_Traditional (Chữ Phồn thể)": "蛉", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ và thường xuất hiện trong các từ ghép chỉ tên loài côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艮', '{"9000": "4545.0", "Chữ Trung Quốc": "艮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艮 | Số nét | 6 | nét | 目 | mục | biểu nghĩa | mắt | 人 | nhân | biểu nghĩa | người | 艮 là chữ hội ý theo Wiktionary: 目 (mục, mắt) + 人 (nhân, người) — hình ảnh một người ngoảnh đầu nhìn lại. Ý nghĩa gốc là ''cứng đầu, không nghe lời'', từ đó mở rộng sang ''dừng lại, giới hạn''. Là một trong 8 quẻ trong Bát Quái (quẻ Cấn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấn\": mắt (目) của người (人) quay nhìn lại — bướng bỉnh, cứng đầu như núi (quẻ Cấn trong Bát Quái). | Gương Hán-Việt | cấn trong 艮卦 (cấn quái — quẻ Cấn trong Bát Quái, biểu tượng núi) | Mở khoá kiến thức | Biết 艮 mở khoá quẻ Cấn (Bát Quái), 艮背 (cấn bối — kiểm soát lưng/cảm xúc, từ Kinh Dịch), 性格艮 (tính cứng, bướng).", "Tự nguyên_Xie": "艮 (Hán-Việt: cấn) là chữ hội ý theo Wiktionary (nghiên cứu của Ji Xusheng, 2004): 目 (mắt) + 人 (người) — người quay đầu nhìn lại, gợi ý sự bướng bỉnh hoặc đứng lại không tiến. Là một trong 8 quẻ Bát Quái (艮為山 — quẻ Cấn là núi): tĩnh lặng, dừng lại. Liên quan gần với 見 nhưng không phải một chữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "681.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dân (680)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét ngang nằm ở trong chữ Dân (số 680), phần dưới được viết biến đi. Giải thích sự chuyển ý: Đây là chữ Hội ý. Người dân (Dân) nếu có ranh giới/nền tảng vững vàng thì sẽ bền chắc. Cấn là cứng cỏi, bền chắc, cũng là tên một quẻ trong bát quái.", "Nghĩa Tiếng Việt_Xie": "quẻ Cấn (phúc uyển) trong Kinh Dịch (chỉ có vạch trên liền, tượng Sơn (núi), tượng trưng cho con trai út, hành Thổ, tuổi Sửu, hướng Đông và Bắc)", "Hạng Tần Suất (Jun Da)": "4545.0", "Tần Suất % (Jun Da)": "99.8664864933", "GavinGrover_Once (Chiết tự trực tiếp)": "𢀳 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𢀳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "艮", "Unihan_Traditional (Chữ Phồn thể)": "艮", "Pinyin_Xie": "gěn", "Âm Hán Việt_Xie": "cấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ một quẻ trong bát quái hoặc làm tính từ chỉ tính cách cứng cỏi, bướng bỉnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搽', '{"9000": "4546.0", "Chữ Trung Quốc": "搽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 搽 | trà | tượng hình | thoa, bôi (kem, dầu) lên da | 搽 thuộc bộ 扌(手, tay) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 扌 biểu nghĩa chỉ hành động tay. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trà\": bàn tay (扌) nhẹ nhàng trà (thoa) kem lên mặt — cử chỉ chăm sóc da dịu dàng như rót trà. | Gương Hán-Việt | trà trong 搽脸 (trà diện — thoa mặt), 搽粉 (trà phấn — thoa phấn) | Mở khoá kiến thức | Biết 搽 mở khoá 搽脸 (thoa mặt), 搽粉 (thoa phấn), 搽药 (bôi thuốc) — từ vựng chăm sóc cá nhân.", "Tự nguyên_Xie": "搽 (Hán-Việt: trà) nghĩa là bôi, thoa — dùng tay phết đều lên bề mặt da (kem, dầu, phấn). Không có Wiktionary glyph origin chi tiết. Bộ 扌 (tay) xác nhận là hành động dùng tay. Khác với 涂 (tú — bôi tô rộng) và 抹 (mạt — phết mỏng), 搽 mang sắc thái nhẹ nhàng, cẩn thận hơn. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bôi, thoa", "Hạng Tần Suất (Jun Da)": "4546.0", "Tần Suất % (Jun Da)": "99.8666415289", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 茶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌茶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "茶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搽", "Unihan_Traditional (Chữ Phồn thể)": "搽", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "trà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các danh từ chỉ thuốc mỡ, phấn hoặc kem dưỡng da. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濡', '{"9000": "4547.0", "Chữ Trung Quốc": "濡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 17 | nét | 水 | thủy | biểu nghĩa | nước | 需 | nhu | biểu âm | cần thiết | 濡 là chữ hình thanh: 水/氵 (Thủy, biểu nghĩa: nước) + 需 (Nhu, biểu âm). Nghĩa là thấm ướt, ẩm ướt — nước ngấm vào làm ướt đẫm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhụa\": nước (水) thấm vào như 需 (cần) — 相濡以沫: hai con cá cùng thở sương nhau khi bể cạn — yêu thương đùm bọc. | Gương Hán-Việt | nhụa trong 相濡以沫 (tương nhu dĩ mạt — cùng nhau vượt khó, giúp đỡ nhau trong hoạn nạn) | Mở khoá kiến thức | Biết 濡 mở khoá 相濡以沫 (thành ngữ yêu thương đùm bọc), 濡湿 (làm ướt), 浸濡 (thấm ướt).", "Tự nguyên_Xie": "濡 (Hán-Việt: nhụa) là chữ hình thanh theo Wiktionary: 水 (nước) + 需 (Nhu, biểu âm). Nghĩa chính là thấm ướt, thấm đẫm — nước thấm vào. Thành ngữ 相濡以沫 (tương nhu dĩ mạt — cùng nhau ướt sương, nghĩa bóng: giúp đỡ nhau trong hoàn cảnh khó khăn) là một trong những thành ngữ đẹp nhất tiếng Trung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Nhu; thấm ướt", "Hạng Tần Suất (Jun Da)": "4547.0", "Tần Suất % (Jun Da)": "99.8667965644", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濡", "Unihan_Traditional (Chữ Phồn thể)": "濡", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động làm ướt hoặc làm tính từ mô tả trạng thái ẩm ướt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寮', '{"9000": "4548.0", "Chữ Trung Quốc": "寮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 15 | nét | 宀 | biểu nghĩa | mái nhà, nhà ở | 尞 | biểu âm | biểu âm: liêu/liáo | 寮 là chữ hình thanh: 宀 (biểu nghĩa: mái nhà) + 尞 (biểu âm: liêu/liáo). Nghĩa là căn lều, nhà tạm, chỗ ở nhỏ đơn giản — từ đó mở rộng sang đồng liêu (colleague, người cùng làm việc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": mái nhà (宀) tạm bợ liêu xiêu — 同寮 là người cùng chia sẻ mái lều, tức đồng nghiệp/bạn cùng phòng. | Gương Hán-Việt | liêu trong 同寮 (đồng liêu — đồng nghiệp, bạn cùng phòng), 寮屋 (liêu ốc — nhà tạm) | Mở khoá kiến thức | Biết 寮 mở khoá 同寮 (đồng liêu/đồng nghiệp), 寮屋 (nhà tạm, cũi), 官寮 (quan liêu — văn phòng quan lại).", "Tự nguyên_Xie": "寮 (Hán-Việt: liêu) là chữ hình thanh theo Wiktionary: 宀 (mái nhà) + 尞 (biểu âm). Nghĩa gốc là lều tranh, nhà ở tạm bợ. Từ đó xuất hiện nghĩa ''đồng liêu'' (寮友/同寮 — bạn cùng phòng, đồng nghiệp ở chung). Trong phương ngữ Quảng Đông, 寮屋 là nhà tạm của người lao động. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa sổ nhỏ", "Hạng Tần Suất (Jun Da)": "4548.0", "Tần Suất % (Jun Da)": "99.8669515999", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "寮", "Unihan_Traditional (Chữ Phồn thể)": "寮", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nơi ở của tăng ni hoặc các lán trại, phòng ốc nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柩', '{"9000": "4549.0", "Chữ Trung Quốc": "柩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柩 | cữu | tượng hình | quan tài (đặc biệt khi có thi thể bên trong) | 柩 thuộc bộ 木 (gỗ) — quan tài làm từ gỗ. Anchor không cung cấp cấu trúc chi tiết hơn. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận glyph cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\": gỗ (木) bao bọc — 灵柩 (linh cữu) là cỗ quan tài linh thiêng, ngôn ngữ tôn kính trong tang lễ. | Gương Hán-Việt | cữu trong 灵柩 (linh cữu — quan tài có thi thể, linh cữu) | Mở khoá kiến thức | Biết 柩 mở khoá 灵柩 (linh cữu), 棺柩 (quan cữu — quan tài) trong ngôn ngữ tang lễ trang trọng tiếng Trung.", "Tự nguyên_Xie": "柩 (Hán-Việt: cữu) chỉ quan tài có chứa thi thể bên trong, phân biệt với 棺 (quan — hòm gỗ trống). Không có Wiktionary glyph origin chi tiết. Bộ 木 (gỗ) xác nhận liên quan đến gỗ. Thường gặp trong 灵柩 (linh cữu — linh cữu, quan tài chứa thi thể), ngôn ngữ tang lễ trang trọng. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo quan (mặc cho người chết)", "Hạng Tần Suất (Jun Da)": "4549.0", "Tần Suất % (Jun Da)": "99.8671066355", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 匛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木匛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柩", "Unihan_Traditional (Chữ Phồn thể)": "柩", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với các động từ di chuyển để chỉ linh cữu của người đã khuất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佗', '{"9000": "4550.0", "Chữ Trung Quốc": "佗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 人 | nhân | biểu nghĩa | người | 它 | tha | biểu âm | nó, cái kia | 佗 là chữ hình thanh: 人/亻 (Nhân, biểu nghĩa: người) + 它 (Tha, biểu âm). Có nhiều nghĩa: (1) người khác, (2) gánh vác, mang trên lưng, (3) thành phần trong địa danh ''Đà'' (như sông Đà).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": người (人) mang theo 它 — như Hoa Đà (华佗) thần y gánh vác sứ mệnh cứu người. | Gương Hán-Việt | đà trong 华佗 (Hoa Đà — thần y Tam Quốc), 佗载 (đà tái — gánh vác) | Mở khoá kiến thức | Biết 佗 mở khoá 华佗 (Hoa Đà — tên thần y nổi tiếng), 佗载 (gánh vác) trong lịch sử và văn học Tam Quốc.", "Tự nguyên_Xie": "佗 (Hán-Việt: đà) là chữ hình thanh theo Wiktionary: 人 (người) + 它 (Tha, biểu âm). Nghĩa cổ: ''người kia, người khác'' — tương tự 他. Cũng có nghĩa là gánh, cõng (mang nặng trên lưng người). Thường gặp trong tên nhân vật lịch sử: 华佗 (Hoa Đà — thần y nổi tiếng thời Tam Quốc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cõng trên lưng", "Hạng Tần Suất (Jun Da)": "4550.0", "Tần Suất % (Jun Da)": "99.8672611542", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佗", "Unihan_Traditional (Chữ Phồn thể)": "佗", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Đại từ | 代词 | Thường dùng làm động từ chỉ hành động mang vác hoặc làm đại từ mang nghĩa là cái khác, người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啷', '{"9000": "4551.0", "Chữ Trung Quốc": "啷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啷 | lắng | tượng hình | tiếng động leng keng, lách cách | 啷 thuộc bộ 口 (miệng/âm thanh) nhưng anchor không cung cấp cấu trúc chi tiết. Không có Wiktionary glyph origin. Là từ tượng thanh mô phỏng tiếng động kim loại leng keng. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lắng\": miệng (口) phát âm ''lắng'' — tiếng chìa khóa khua leng keng trong túi xách. | Gương Hán-Việt | lắng trong 叮啷 (đinh lắng — tiếng leng keng), 哐啷 (quàng lắng — tiếng đổ vỡ) | Mở khoá kiến thức | Biết 啷 mở khoá nhóm từ tượng thanh tiếng Trung: 叮啷, 哐啷, 稀里哗啦 — dùng nhiều trong văn viết miêu tả âm thanh.", "Tự nguyên_Xie": "啷 (Hán-Việt: lắng) là từ tượng thanh chỉ tiếng kim loại va chạm kêu leng keng, lách cách. Không có Wiktionary glyph origin. Bộ 口 biểu nghĩa chỉ âm thanh phát ra. Thường kết hợp thành 叮啷 (ding-lang — tiếng leng keng) hoặc 哐啷 (tiếng đổ vỡ mạnh). chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trên dưới; khoảng; độ (thường dùng cho tuổi tác)", "Hạng Tần Suất (Jun Da)": "4551.0", "Tần Suất % (Jun Da)": "99.867415673", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 郎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口郎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啷", "Unihan_Traditional (Chữ Phồn thể)": "啷", "Pinyin_Xie": "lāng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Trợ từ | 助词 | Thường dùng làm từ tượng thanh mô tả tiếng kim khí va chạm hoặc làm trợ từ biểu thị khoảng chừng. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诜', '{"9000": "4552.0", "Chữ Trung Quốc": "诜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诜 | thân | tượng hình | đông đảo, tụ họp đông | 诜 là dạng giản thể của 詵. Bộ 讠(言, lời nói) nhưng anchor không cung cấp cấu trúc chi tiết. Không có Wiktionary glyph origin riêng — chữ này chuyển hướng đến 詵. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thân\": bộ 讠(lời nói) — nhiều tiếng nói hòa lẫn, đông đảo như 詵詵 (thân thân — tụ họp đông vui). | Gương Hán-Việt | thân trong 詵詵 (thân thân — đông đảo tụ tập, trong thơ kinh Thi) | Mở khoá kiến thức | Biết 诜/詵 giúp đọc Kinh Thi cổ: 詵詵 xuất hiện trong bài thơ chỉ cảnh gia đình sum họp đông đúc.", "Tự nguyên_Xie": "诜 (Hán-Việt: thân) là dạng giản thể của 詵. Theo Wiktionary, 诜 chỉ là redirect đến 詵 (không có glyph origin riêng). 詵詵 (thân thân) có nghĩa là đông đảo, tụ tập nhiều. Nghĩa khác: tốt đẹp, trang nhã. Không phổ biến trong tiếng Trung hiện đại. chưa có nguồn học thuật xác nhận glyph. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hỏi", "Hạng Tần Suất (Jun Da)": "4552.0", "Tần Suất % (Jun Da)": "99.867569675", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 先", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "先", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诜", "Unihan_Traditional (Chữ Phồn thể)": "詵", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ trong từ láy để miêu tả cảnh tượng người đi lại đông đúc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偻', '{"9000": "4553.0", "Chữ Trung Quốc": "偻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 人 | nhân | biểu nghĩa | người | 婁 | lâu | biểu âm | người phụ nữ gày yếu | 偻 là chữ hình thanh: 人/亻 (Nhân, biểu nghĩa: người) + 婁 (Lâu, biểu âm). Nghĩa là gù lưng, còng xuống — dáng người uốn cong không thẳng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": người (人) còng (婁) — dáng đi lòm khom, như người bệnh 佝偻 (câu lâu) thiếu canxi cúi người. | Gương Hán-Việt | lâu trong 佝偻 (câu lâu — bệnh còng lưng, rickets), 伛偻 (ủ lâu — khom lưng) | Mở khoá kiến thức | Biết 偻 mở khoá 佝偻病 (bệnh còi xương/bệnh còng lưng ở trẻ em), từ y học quan trọng trong tiếng Trung.", "Tự nguyên_Xie": "偻 (Hán-Việt: lâu) là chữ hình thanh theo Wiktionary: 人 (người) + 婁 (Lâu, biểu âm). Nghĩa chính là gù lưng, còng lưng. Thường gặp trong 佝偻 (câu lâu — bệnh còng lưng, bệnh còi xương) và 伛偻 (ủ lâu — khom lưng). Cũng có nghĩa là mau chóng (còng người đi nhanh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gù lưng, còng lưng", "Hạng Tần Suất (Jun Da)": "4553.0", "Tần Suất % (Jun Da)": "99.8678771621", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偻", "Unihan_Traditional (Chữ Phồn thể)": "僂", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu, lũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả dáng người gù hoặc động từ chỉ hành động khom lưng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夯', '{"9000": "4554.0", "Chữ Trung Quốc": "夯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 5 | nét | 夯 | bổng | tượng hình | đầm đất (dụng cụ); nện, đóng mạnh | 夯 là chữ hội ý/hợp thành từ 大力 (đại lực — sức mạnh lớn). Theo Wiktionary: cấu tạo từ 大 (lớn) + 力 (sức lực). Hình ảnh sức mạnh lớn nện xuống — như chiếc đầm dùng để nện chặt đất. Không có dạng tượng hình cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổng\": 大 (to) + 力 (sức) = sức lực to lớn nện bổng xuống đất — đầm đất nện chặt như bổng búa nặng. | Gương Hán-Việt | bổng — chữ ít dùng trong văn bản Hán-Việt; thường gặp trong tiếng Trung hiện đại như 夯实 (đầm chặt) | Mở khoá kiến thức | Biết 夯 mở khoá 夯实 (đầm chặt, củng cố vững chắc — dùng rộng rãi nghĩa bóng), 夯土 (đất đầm nện), 打夯 (nện đầm).", "Tự nguyên_Xie": "夯 là chữ hội ý tạo bởi 大 (đại, lớn) + 力 (lực, sức lực) — hình ảnh sức mạnh lớn nện xuống. Nghĩa là đầm đất, nện chặt; cũng dùng cho dụng cụ đầm đất. Theo Wiktionary glyph origin: ''Compound of 大力''. Chữ thuần Trung, Hán-Việt đọc là bổng hoặc không có âm HV chuẩn thông dụng. chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dùng sức để nâng; vật nặng; cái đầm nện đất", "Hạng Tần Suất (Jun Da)": "4554.0", "Tần Suất % (Jun Da)": "99.8680301305", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "夯", "Unihan_Traditional (Chữ Phồn thể)": "夯", "Pinyin_Xie": "hāng", "Âm Hán Việt_Xie": "bổn, hãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động nện đất hoặc danh từ chỉ cái đầm đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闱', '{"9000": "4555.0", "Chữ Trung Quốc": "闱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 7 | nét | 闱 | vi | tượng hình | cửa hậu cung, phòng thi cử | 闱 chứa bộ 门/門 (cổng/cửa) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 门 biểu nghĩa chỉ cửa, cổng. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": bộ cửa (门) — cổng vào hậu cung hoặc trường thi, chỉ những người được phép mới qua. | Gương Hán-Việt | vi trong 入闱 (nhập vi — vào trường thi), 闱场 (vi trường — trường thi khoa cử) | Mở khoá kiến thức | Biết 闱 mở khoá 入闱 (vào trường thi), 闱墨 (bài thi xuất sắc được in), 春闱 (xuân vi — kỳ thi mùa xuân) trong lịch sử khoa cử Trung Hoa.", "Tự nguyên_Xie": "闱 (Hán-Việt: vi) nghĩa là cửa hậu của cung điện, phòng riêng trong hậu cung. Từ đó mở rộng sang chỉ trường thi (闱场 — nơi thi cử). Không có Wiktionary glyph origin chi tiết. Bộ 门 (cửa) xác nhận liên quan đến không gian có cửa. Thường gặp trong 科闱 (khoa thi cũ), 入闱 (vào trường thi). chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa nách& (cung thất); trường thi", "Hạng Tần Suất (Jun Da)": "4555.0", "Tần Suất % (Jun Da)": "99.8681830989", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闱", "Unihan_Traditional (Chữ Phồn thể)": "闈", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ khoa cử như xuân vi, thu vi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谖', '{"9000": "4556.0", "Chữ Trung Quốc": "谖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 爰 | vươn | biểu âm | thay đổi, chuyển sang | 谖 là chữ hình thanh: 言/讠 (Ngôn, biểu nghĩa: lời nói) + 爰 (Vươn, biểu âm). Nghĩa là nói dối, lừa gạt bằng lời; cũng có nghĩa là quên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": lời nói (言) thay đổi (爰) — lời lẽ huyên thiên, quên đi hay lừa gạt — 谖草 là hoa ''quên sầu''. | Gương Hán-Việt | huyên trong 谖草 (huyên thảo — hoa kim châm/hoa hiên, hoa quên sầu) | Mở khoá kiến thức | Biết 谖 mở khoá 谖草 (hoa kim châm — biểu tượng ''quên mẹ'' trong Kinh Thi), 欺谖 (lừa dối) trong văn học cổ.", "Tự nguyên_Xie": "谖 (Hán-Việt: huyên) là chữ hình thanh theo Wiktionary: 言 (lời nói) + 爰 (Vươn/Viên, biểu âm). Nghĩa là (1) lừa dối, nói dối; (2) quên đi. Chữ cổ điển, ít dùng trong tiếng Trung hiện đại. Thường gặp trong thơ cổ: 谖草 (hoa huyên thảo — hoa quên sầu, Hemerocallis). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quên; lừa dối", "Hạng Tần Suất (Jun Da)": "4556.0", "Tần Suất % (Jun Da)": "99.8683355505", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 爰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠爰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谖", "Unihan_Traditional (Chữ Phồn thể)": "諼", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để chỉ việc quên hoặc lừa gạt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枸', '{"9000": "4557.0", "Chữ Trung Quốc": "枸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 句 | câu | biểu âm | câu (biểu âm gǒu/jǔ/jù) | 枸 là chữ hình thanh: 木 (Mộc, biểu nghĩa: cây/gỗ) + 句 (Câu, biểu âm). Chỉ nhiều loại cây khác nhau tùy đọc âm, phổ biến nhất là kỷ tử (枸杞 gǒuqǐ — quả kỷ tử).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cú\": cây (木) âm 句 (câu/cú) — 枸杞 là ''cây kỷ tử'', quả đỏ nhỏ bồi bổ sức khỏe trong Đông y Trung Hoa. | Gương Hán-Việt | cú trong 枸杞 (cú kỷ — kỷ tử, wolfberry) | Mở khoá kiến thức | Biết 枸 mở khoá 枸杞 (kỷ tử — quả đỏ bổ dưỡng), 枸杞子 (hạt kỷ tử), 枸橘 (cây cam gai) trong Đông y và ẩm thực.", "Tự nguyên_Xie": "枸 (Hán-Việt: cú) là chữ hình thanh theo nguồn: 木 (cây) + 句 (Câu, biểu âm). Tùy âm đọc, chỉ các loại cây khác nhau: gǒu = kỷ tử (枸杞), jǔ = loại cây có gai (枸橘). Phổ biến nhất trong tiếng Trung hiện đại là 枸杞 (kỷ tử — wolfberry, quả đỏ bổ dưỡng trong Đông y). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cẩu kỷ (quả dùng làm thuốc); cây gỗ dựng đứng", "Hạng Tần Suất (Jun Da)": "4557.0", "Tần Suất % (Jun Da)": "99.8686404538", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枸", "Unihan_Traditional (Chữ Phồn thể)": "枸", "Pinyin_Xie": "gǒu", "Âm Hán Việt_Xie": "cẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong tên gọi các loại cây như cẩu kỷ hoặc chỉ cây gỗ cong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膑', '{"9000": "4558.0", "Chữ Trung Quốc": "膑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 14 | nét | 膑 | tẫn | tượng hình | xương bánh chè; hình phạt cắt xương bánh chè | 膑 thuộc bộ 肉/月 (thịt/cơ thể) nhưng anchor không cung cấp cấu trúc chi tiết. Bộ 月/肉 biểu nghĩa chỉ phần thân thể. Không có Wiktionary glyph origin chi tiết. Là dạng thay thế của 髕 (xương bánh chè). chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẫn\": bộ thịt/cơ thể — 膑刑 là hình phạt tàn khốc, nhớ qua Tôn Tẫn (孙膑) — thiên tài bị cắt bánh chè mà vẫn viết Binh pháp lừng danh. | Gương Hán-Việt | tẫn trong 孙膑 (Tôn Tẫn — nhà quân sự Chiến Quốc), 膑刑 (tẫn hình — hình phạt cổ đại) | Mở khoá kiến thức | Biết 膑 mở khoá 孙膑 (Tôn Tẫn — tác giả Tôn Tẫn Binh pháp), 膑刑 trong lịch sử hình phạt Trung Hoa cổ đại.", "Tự nguyên_Xie": "膑 (Hán-Việt: tẫn) là hình thức thay thế của 髕, chỉ xương bánh chè. Thời cổ đại Trung Quốc, 膑刑 (tẫn hình) là hình phạt chặt xương bánh chè — một trong ''ngũ hình'' cổ đại. Tên tuổi gắn với Tôn Tẫn (孙膑) — nhà quân sự thiên tài Chiến Quốc bị đối thủ Bàng Quyên hãm hại cắt xương bánh chè. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương bánh chè, xương đầu gối; hình phạt chặt xương bánh chè", "Hạng Tần Suất (Jun Da)": "4558.0", "Tần Suất % (Jun Da)": "99.8687929054", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膑", "Unihan_Traditional (Chữ Phồn thể)": "臏", "Pinyin_Xie": "bìn", "Âm Hán Việt_Xie": "bận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bộ phận cơ thể hoặc động từ chỉ hình phạt chặt xương đầu gối thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虻', '{"9000": "4559.0", "Chữ Trung Quốc": "虻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虻 | mãnh | tượng hình | ruồi trâu, mòng (Tabanus) | 虻 thuộc bộ 虫 (côn trùng) nhưng anchor không cung cấp cấu trúc chi tiết hơn. Bộ 虫 biểu nghĩa chỉ côn trùng. Không có Wiktionary glyph origin chi tiết. chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãnh\": con côn trùng (虫) hung mãnh — ruồi trâu (虻) đốt mạnh, hút máu người và gia súc. | Gương Hán-Việt | mãnh trong 虻虫 (mãnh trùng — ruồi trâu khô dùng làm thuốc Đông y) | Mở khoá kiến thức | Biết 虻 mở khoá 虻虫 (vị thuốc Đông y), 牛虻 (ruồi trâu — Gadfly, cũng là biệt danh của Socrates phương Đông), 蚊虻 (muỗi và mòng).", "Tự nguyên_Xie": "虻 (Hán-Việt: mãnh) chỉ ruồi trâu, mòng — loài côn trùng hút máu lớn (Tabanus). Không có Wiktionary glyph origin chi tiết. Bộ 虫 xác nhận là côn trùng. Trong y học cổ Trung Hoa, 虻虫 (mòng trâu khô) là dược liệu dùng làm tan máu đông. chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con nhặng, con ruồi trâu, con mòng; bối mẫu", "Hạng Tần Suất (Jun Da)": "4559.0", "Tần Suất % (Jun Da)": "99.868945357", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 亡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫亡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虻", "Unihan_Traditional (Chữ Phồn thể)": "虻", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "manh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm yếu tố cấu tạo từ chỉ các loài côn trùng hút máu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筠', '{"9000": "4560.0", "Chữ Trung Quốc": "筠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 均 | quân | biểu âm | đều, cân bằng | 筠 là chữ hình thanh: 竹 (Trúc, biểu nghĩa: tre/trúc) + 均 (Quân, biểu âm). Nghĩa là lớp da ngoài của cây tre — phần vỏ xanh bóng, dai và đẹp. Từ đó dùng như tên thơ cho tre nói chung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": tre (竹) quân bình (均) — lớp vỏ tre xanh bóng đều đẹp, biểu tượng phẩm chất quân tử kiên định. | Gương Hán-Việt | quân trong 竹筠 (trúc quân — vỏ tre, da tre) và tên riêng 筠 trong văn hóa đặt tên | Mở khoá kiến thức | Biết 筠 mở khoá nghĩa thơ của tre trong văn học Trung Hoa: vỏ tre xanh mịn = phẩm hạnh cao quý. Thường gặp trong tên người và thơ ca.", "Tự nguyên_Xie": "筠 (Hán-Việt: quân) là chữ hình thanh theo Wiktionary: 竹 (tre) + 均 (Quân, biểu âm). Nghĩa gốc là lớp vỏ xanh bóng ngoài cây tre, biểu tượng của sự thanh khiết và bền bỉ. Trong văn học và tên người, 筠 mang vẻ đẹp tinh tế của cây tre — thường dùng đặt tên nữ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cật tre già", "Hạng Tần Suất (Jun Da)": "4560.0", "Tần Suất % (Jun Da)": "99.8690978086", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 均", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮均", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "均", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筠", "Unihan_Traditional (Chữ Phồn thể)": "筠", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn thơ để chỉ cật tre xanh hoặc tượng trưng cho khí tiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埽', '{"9000": "4561.0", "Chữ Trung Quốc": "埽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 埽 | tảo | tượng hình | cái chổi quét đất | 埽 là chữ tạo muộn, chưa thấy cấu trúc hình thanh/hội ý rõ ràng trong nguồn học thuật. Hanziyuan ghi nhận dạng tiểu triện. Chữ liên quan đến bộ 土 (thổ, đất) và hành động quét dọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảo\": bộ 土 (đất) gợi hình ảnh quét sạch mặt đất — tảo là quét, dọn sạch. | Gương Hán-Việt | tảo trong \"tảo mộ\" (quét mộ), \"thanh tảo\" (dọn sạch) | Mở khoá kiến thức | Biết 埽 (tảo) mở khoá nhóm chữ chỉ hành động dọn dẹp, liên quan bộ 土 và khái niệm làm sạch.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi nhận phát âm, không có phân tích cấu trúc chi tiết. Chữ 埽 dùng chỉ hành động quét dọn hoặc cái chổi. Chưa có nguồn học thuật xác nhận cấu tạo chữ cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quét; cái chổi", "Hạng Tần Suất (Jun Da)": "4561.0", "Tần Suất % (Jun Da)": "99.8692497434", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 帚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土帚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埽", "Unihan_Traditional (Chữ Phồn thể)": "埽", "Pinyin_Xie": "sào", "Âm Hán Việt_Xie": "tảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động quét dọn hoặc danh từ chỉ cái chổi, bờ đê. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笞', '{"9000": "4562.0", "Chữ Trung Quốc": "笞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笞 | xuy | tượng hình | roi tre dùng để đánh phạt | 笞 là chữ tạo muộn. Bộ 竹 (trúc, tre) ở trên gợi vật liệu làm roi; phần dưới 台 (đài) có thể mang âm. Wiktionary không có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuy\": bộ 竹 (tre) trên đầu — xuy là roi tre dùng để đánh phạt trong luật cổ. | Gương Hán-Việt | xuy trong \"tiên xuy\" (đánh roi), \"đình xuy\" (đánh roi ở sân quan) | Mở khoá kiến thức | Biết 笞 (xuy) mở khoá nhóm chữ luật hình cổ Trung Quốc, các loại hình phạt thể xác.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu tạo chi tiết cho 笞. Chữ dùng chỉ roi tre hoặc hành động đánh roi, một hình phạt trong luật cổ Trung Quốc. Chưa có nguồn học thuật xác nhận cấu tạo cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh roi, vọt roi", "Hạng Tần Suất (Jun Da)": "4562.0", "Tần Suất % (Jun Da)": "99.8694016783", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笞", "Unihan_Traditional (Chữ Phồn thể)": "笞", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc đánh roi hoặc danh từ chỉ hình phạt xuy hình thời cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臾', '{"9000": "4563.0", "Chữ Trung Quốc": "臾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 8 | nét | 𦥑 | biểu nghĩa | hai bàn tay | 人 | nhân | biểu nghĩa | người | 臾 là chữ hội ý (ls=ic): 𦥑 (hai bàn tay) kết hợp với 人 (nhân, người) — hình ảnh hai bàn tay kéo lê một người. Đây là chữ gốc biểu đạt hành động kéo, lôi; sau được dùng trong \"須臾\" (tu du) nghĩa là khoảnh khắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": hai bàn tay kéo lê người — khoảnh khắc (須臾/tu du) ngắn như một cái giật người. | Gương Hán-Việt | du trong \"tu du\" (須臾 — khoảnh khắc), \"tu du chi gian\" (trong chớp mắt) | Mở khoá kiến thức | Biết 臾 (du) mở khoá cụm \"須臾\" (tu du) — thành ngữ chỉ thời gian rất ngắn trong văn ngôn.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 臾 là chữ hội ý: 𦥑 (hai bàn tay) + 人 (người), miêu tả cảnh hai tay kéo lôi một người. So sánh với 曳 (kéo). Nghĩa gốc là kéo, lôi; nghĩa phái sinh chỉ khoảnh khắc ngắn (須臾 — tu du). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tu du 須臾)", "Hạng Tần Suất (Jun Da)": "4563.0", "Tần Suất % (Jun Da)": "99.8695536131", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴人臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "臾", "Unihan_Traditional (Chữ Phồn thể)": "臾", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với tu tạo thành từ ghép tu du để chỉ một lát, một chốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婀', '{"9000": "4564.0", "Chữ Trung Quốc": "婀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 婀 | a | tượng hình | người phụ nữ duyên dáng, uyển chuyển | 婀 chứa bộ 女 (nữ, phụ nữ) ở trái; phần phải 可 hoặc biến thể. Wiktionary dẫn đến dạng gốc 娿, không có phân tích hình thanh rõ ràng. Chữ dùng chủ yếu trong \"婀娜\" (a na — uyển chuyển, duyên dáng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"a\": bộ 女 (nữ) — \"a\" trong \"a na\" (婀娜) gợi hình ảnh người phụ nữ uyển chuyển như cành liễu. | Gương Hán-Việt | a trong \"a na\" (婀娜 — uyển chuyển), \"a na đa tư\" (dáng vẻ yêu kiều) | Mở khoá kiến thức | Biết 婀 (a) mở khoá từ \"婀娜\" (a na) — tính từ cổ điển chỉ dáng đi uyển chuyển trong thơ văn Hán-Việt.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Wiktionary dẫn dạng gốc 娿 nhưng không cung cấp phân tích cấu tạo học thuật chi tiết. Chữ 婀 gắn với bộ 女 (nữ), biểu đạt vẻ đẹp mềm mại, uyển chuyển của phụ nữ. Dùng hầu như chỉ trong từ ghép 婀娜. Chưa có nguồn học thuật xác nhận cấu tạo cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: a na 婀娜)", "Hạng Tần Suất (Jun Da)": "4564.0", "Tần Suất % (Jun Da)": "99.8697050311", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 阿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女阿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婀", "Unihan_Traditional (Chữ Phồn thể)": "娿", "Pinyin_Xie": "ē", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ nạ để tạo thành từ láy a nạ chỉ dáng điệu thướt tha của phụ nữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珞', '{"9000": "4565.0", "Chữ Trung Quốc": "珞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 王 | vương | biểu nghĩa | ngọc | 各 | cac | biểu âm | 珞 là chữ hình thanh (ls=psc): 王 (vương, ở đây biểu nghĩa ngọc) + 各 (cac, biểu âm). Bộ 王 trong chữ ngọc thực ra là biến thể của 玉 (ngọc), không phải \"vua\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": ngọc (王/玉) phát âm theo 各 (cac) — lạc là hạt ngọc trong chuỗi trang sức quý (瓔珞/anh lạc). | Gương Hán-Việt | lạc trong \"anh lạc\" (瓔珞 — chuỗi ngọc), \"lạc lạc\" (珞珞 — vững chắc như đá) | Mở khoá kiến thức | Biết 珞 (lạc) mở khoá \"瓔珞\" (anh lạc) — chuỗi ngọc đeo cổ xuất hiện nhiều trong văn học và Phật giáo.", "Tự nguyên_Xie": "Theo Wiktionary, 珞 là chữ hình thanh: 王/玉 (ngọc, biểu nghĩa) + 各 (cac, biểu âm). Chữ dùng chỉ loại chuỗi ngọc trang sức, xuất hiện trong \"瓔珞\" (anh lạc — chuỗi ngọc đeo cổ) và \"賽璐珞\" (tên phiên âm celluloid). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuỗi ngọc", "Hạng Tần Suất (Jun Da)": "4565.0", "Tần Suất % (Jun Da)": "99.8698559324", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珞", "Unihan_Traditional (Chữ Phồn thể)": "珞", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng trong từ ghép lạc dịch để chỉ chuỗi ngọc quý đeo ở cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粑', '{"9000": "4566.0", "Chữ Trung Quốc": "粑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粑 | ba | tượng hình | loại bánh từ ngũ cốc, đặc biệt là tsamba Tây Tạng | 粑 chứa bộ 米 (mễ, gạo/ngũ cốc) ở trái; phần phải 巴 (ba) có thể vừa biểu âm vừa gợi nghĩa (gắn kết). Wiktionary không có dữ liệu cấu tạo. Chữ gần như chỉ dùng trong \"糌粑\" (tán ba — tsamba, lương thực truyền thống Tây Tạng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": bộ 米 (gạo) + âm 巴 (ba) — ba là bánh ngũ cốc, nhớ qua \"糌粑\" (tán ba) tsamba Tây Tạng. | Gương Hán-Việt | ba trong \"tán ba\" (糌粑 — tsamba), \"ba ba\" (粑粑 — bánh ngô/ngũ cốc ở miền Nam) | Mở khoá kiến thức | Biết 粑 (ba) mở khoá \"糌粑\" (tán ba) — lương thực đặc trưng Tây Tạng và \"粑粑\" — tên gọi dân gian cho bánh ngũ cốc.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary. 粑 có bộ 米 (gạo, ngũ cốc) biểu nghĩa và 巴 biểu âm. Chữ dùng chủ yếu trong \"糌粑\" (tán ba), chỉ loại bột rang làm từ lúa mạch — lương thực chính của người Tây Tạng. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ta ba 糌粑)", "Hạng Tần Suất (Jun Da)": "4566.0", "Tần Suất % (Jun Da)": "99.8700068337", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粑", "Unihan_Traditional (Chữ Phồn thể)": "粑", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đứng sau danh từ chỉ nguyên liệu để tạo thành tên các loại bánh bột như ba ba, ngô ba. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怵', '{"9000": "4567.0", "Chữ Trung Quốc": "怵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 心 | tâm | biểu nghĩa | tim, tâm trí | 朮 | biểu âm | 怵 là chữ hình thanh (ls=psc): 心 (tâm, biểu nghĩa: cảm xúc/nội tâm) + 朮 (biểu âm). Chữ biểu đạt trạng thái sợ hãi, lo âu trong lòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truột\": tim (心/tâm) run sợ theo âm 朮 — truột là cảm giác tim như trượt khỏi lồng ngực khi sợ hãi. | Gương Hán-Việt | truột trong \"truật inertia\" (怵惕 — sợ hãi, lo âu), thành ngữ \"怵目驚心\" (trông thấy mà kinh hãi) | Mở khoá kiến thức | Biết 怵 (truột) mở khoá thành ngữ \"怵目驚心\" (chù mục kinh tâm — trông thấy mà kinh hoàng) và \"發怵\" (phát sợ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 怵 là chữ hình thanh: 心 (tim, biểu nghĩa) + 朮 (biểu âm). Nghĩa gốc là sợ hãi, hoảng loạn. Có nghĩa phụ: buồn đau, và trong cách đọc khác (xù) là dụ dỗ, quyến rũ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ hãi; doạ nạt", "Hạng Tần Suất (Jun Da)": "4567.0", "Tần Suất % (Jun Da)": "99.8701572181", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 术", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄术", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "术", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怵", "Unihan_Traditional (Chữ Phồn thể)": "怵", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "truật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ tâm lý biểu thị sự sợ hãi hoặc làm bổ ngữ trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绻', '{"9000": "4568.0", "Chữ Trung Quốc": "绻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绻 | quyển | tượng hình | cuộn lại, quấn quít | 绻 chứa bộ 糸 (mịch/ty, sợi chỉ) biểu nghĩa; phần phải 卷 (quyển) có thể biểu âm. Wiktionary không cung cấp phân tích cấu tạo học thuật. Chữ dùng chủ yếu trong \"繾綣\" (khiển quyển — quấn quít, không rời nhau).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyển\": bộ 糸 (sợi chỉ) cuộn xoắn — quyển là những sợi tình cảm quấn quít không rời trong \"繾綣\" (khiển quyển). | Gương Hán-Việt | quyển trong \"khiển quyển\" (繾綣 — quấn quít, lưu luyến), \"quyển quyển\" (綣綣 — tình cảm mặn nồng) | Mở khoá kiến thức | Biết 绻 (quyển) mở khoá \"繾綣\" (khiển quyển) — thành ngữ thơ văn chỉ tình cảm sâu nặng, không nỡ rời xa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không phân tích cấu tạo chi tiết cho 绻. Bộ 糸 (sợi chỉ) gợi nghĩa cuộn quấn, sợi dây vấn vít. Dùng trong \"繾綣\" chỉ tình cảm quyến luyến, khó dứt. Chưa có nguồn học thuật xác nhận cấu tạo cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giới hạn trong một dặm", "Hạng Tần Suất (Jun Da)": "4568.0", "Tần Suất % (Jun Da)": "99.8703076026", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绻", "Unihan_Traditional (Chữ Phồn thể)": "綣", "Pinyin_Xie": "quǎn", "Âm Hán Việt_Xie": "quyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ luyến để tạo thành từ quyển luyến chỉ sự lưu luyến không rời. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殒', '{"9000": "4569.0", "Chữ Trung Quốc": "殒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 11 | nét | 殒 | vẫn | tượng hình | chết, mất mạng | 殒 chứa bộ 歹 (ngạt/đãi, xương chết, biểu nghĩa: cái chết) ở bên trái; phần phải 员 (viên) có thể biểu âm. Wiktionary không cung cấp phân tích hình thanh cụ thể. Chữ chỉ cái chết, qua đời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": bộ 歹 (xương chết) — vẫn mạng là mất mạng, \"殞命\" (vẫn mạng) chính là cái chết trong văn ngôn. | Gương Hán-Việt | vẫn trong \"vẫn mạng\" (殞命 — mất mạng), \"yểu vẫn\" (夭殞 — chết trẻ) | Mở khoá kiến thức | Biết 殒 (vẫn) mở khoá cụm \"殞命\" (vẫn mạng — chết) và nhóm chữ bộ 歹 chỉ cái chết trong văn ngôn.", "Tự nguyên_Xie": "Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo chi tiết. Bộ 歹 (xương chết) biểu nghĩa; phần còn lại gợi âm. Nghĩa gốc là chết, qua đời — dùng trong văn ngôn. Cũng dùng thay cho 隕 (rơi xuống từ trời). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mất; rụng", "Hạng Tần Suất (Jun Da)": "4569.0", "Tần Suất % (Jun Da)": "99.8704579871", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 员", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹员", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "员", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殒", "Unihan_Traditional (Chữ Phồn thể)": "殞", "Pinyin_Xie": "yǔn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong văn viết cổ để chỉ cái chết hoặc sự suy vong. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觊', '{"9000": "4570.0", "Chữ Trung Quốc": "觊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 10 | nét | 豈 | khải | biểu âm | 見 | kiến | biểu nghĩa | nhìn, trông thấy | 觊 là chữ hình thanh (ls=psc): 見 (kiến, biểu nghĩa: nhìn, quan sát) + 豈 (khải, biểu âm). Nghĩa là thèm muốn, ngóng trông — nhìn với lòng khao khát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ký\": mắt (見/kiến) nhìn chằm chằm theo âm 豈 (khải) — ký là cái nhìn thèm muốn trong \"覬覦\" (ký du). | Gương Hán-Việt | ký trong \"ký du\" (覬覦 — thèm muốn, nhòm ngó), \"ký hạnh\" (覬倖 — hi vọng may mắn) | Mở khoá kiến thức | Biết 觊 (ký) mở khoá \"覬覦\" (ký du) — từ văn ngôn chỉ thèm muốn, nhòm ngó tài sản/địa vị người khác.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 觊 là chữ hình thanh: 見 (kiến, biểu nghĩa: nhìn) + 豈 (khải, biểu âm). Nghĩa là ngóng trông, thèm muốn điều gì đó chưa có. Thường dùng trong \"覬覦\" (ký du — thèm muốn, nhòm ngó để chiếm đoạt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hy vọng; mong muốn; khao khát", "Hạng Tần Suất (Jun Da)": "4570.0", "Tần Suất % (Jun Da)": "99.8706083716", "GavinGrover_Once (Chiết tự trực tiếp)": "岂 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰岂见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觊", "Unihan_Traditional (Chữ Phồn thể)": "覬", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ mang tân ngữ để chỉ việc nhòm ngó, mưu đồ đoạt lấy thứ gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崂', '{"9000": "4571.0", "Chữ Trung Quốc": "崂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 10 | nét | 崂 | lao | tượng hình | tên núi ở Sơn Đông | 崂 chứa bộ 山 (sơn, núi) biểu nghĩa; phần phải 劳 (lao) biểu âm. Chữ tạo muộn, dùng riêng cho địa danh Lao Sơn (崂山) ở tỉnh Sơn Đông, Trung Quốc. Wiktionary không có dữ liệu cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": bộ 山 (núi) phát âm theo 劳 (lao) — lao chính là tên núi Lao Sơn (崂山) nổi tiếng ở Sơn Đông. | Gương Hán-Việt | lao trong \"Lao Sơn\" (崂山 — núi Lao, Thanh Đảo) | Mở khoá kiến thức | Biết 崂 (lao) mở khoá địa danh \"崂山\" (Lao Sơn) — ngọn núi ven biển nổi tiếng tại Thanh Đảo.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary. Chữ 崂 gồm bộ 山 (núi) biểu nghĩa và 劳 biểu âm — chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chữ dùng riêng cho địa danh Lao Sơn (崂山) tại Thanh Đảo, Sơn Đông. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lao Sơn (tên núi ở tỉnh Sơn Đông Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4571.0", "Tần Suất % (Jun Da)": "99.870758756", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崂", "Unihan_Traditional (Chữ Phồn thể)": "嶗", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh núi Lao Sơn ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颧', '{"9000": "4572.0", "Chữ Trung Quốc": "颧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 23 | nét | 颧 | quyền | tượng hình | xương gò má | 颧 chứa bộ 頁 (hiệt, đầu/mặt) biểu nghĩa; phần trái 雚 (quan) biểu âm. Chữ tạo muộn chỉ xương gò má (顴骨). Wiktionary không có phân tích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyền\": bộ 頁 (mặt) + âm 雚 — quyền cốt (顴骨) là xương gò má, điểm nhô cao trên khuôn mặt. | Gương Hán-Việt | quyền trong \"quyền cốt\" (顴骨 — xương gò má) | Mở khoá kiến thức | Biết 颧 (quyền) mở khoá \"顴骨\" (quyền cốt — xương gò má) — từ giải phẫu học thường gặp.", "Tự nguyên_Xie": "Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật. Chữ 颧 gồm bộ 頁 (mặt/đầu) biểu nghĩa và 雚 biểu âm — chỉ phần xương nhô cao ở hai bên mặt (gò má). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương gò má", "Hạng Tần Suất (Jun Da)": "4572.0", "Tần Suất % (Jun Da)": "99.8709086237", "GavinGrover_Once (Chiết tự trực tiếp)": "雚 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雚页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颧", "Unihan_Traditional (Chữ Phồn thể)": "顴", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương gò má trên khuôn mặt người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗑', '{"9000": "4573.0", "Chữ Trung Quốc": "嗑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗑 | hạp | tượng hình | cắn vỡ bằng răng cửa; quẻ Hạp trong Kinh Dịch | 嗑 chứa bộ 口 (khẩu, miệng) biểu nghĩa; phần phải 盍 (hạp) biểu âm. Chữ chỉ hành động cắn bằng răng cửa hoặc là tên quẻ Phệ Hạp (噬嗑) trong Kinh Dịch. Wiktionary không có phân tích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": miệng (口) cắn vỡ — hạp là cắn, như quẻ Phệ Hạp (噬嗑) trong Kinh Dịch. | Gương Hán-Việt | hạp trong \"phệ hạp\" (噬嗑 — quẻ 21 Kinh Dịch), \"hạp nha\" (嗑牙 — chuyện trò lải nhải) | Mở khoá kiến thức | Biết 嗑 (hạp) mở khoá \"噬嗑\" (phệ hạp — quẻ Kinh Dịch về luật pháp/trừng phạt) và nhóm chữ bộ 口.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật cho 嗑. Chữ gồm bộ 口 (miệng) và 盍 (hạp) biểu âm. Dùng trong quẻ Phệ Hạp (噬嗑, quẻ 21 Kinh Dịch — cắn vỡ hạt bằng răng) và trong phương ngữ chỉ chuyện trò (嗑牙). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quẻ Hạp trong Kinh Dịch (cắn vỡ hạt bằng răng cửa)", "Hạng Tần Suất (Jun Da)": "4573.0", "Tần Suất % (Jun Da)": "99.8710584914", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 盍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗑", "Unihan_Traditional (Chữ Phồn thể)": "嗑", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ biểu thị hành động cắn hạt dưa hoặc nói chuyện phiếm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榛', '{"9000": "4574.0", "Chữ Trung Quốc": "榛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | cây | 秦 | tần | biểu âm | 榛 là chữ hình thanh (ls=psc): 木 (mộc, biểu nghĩa: cây) + 秦 (tần, biểu âm). Chữ chỉ cây phỉ (hazel) hoặc bụi cây rậm rạp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trăn\": cây (木/mộc) phát âm theo 秦 (tần) — trăn là cây phỉ hoặc bụi rậm, \"榛莽\" (trăn mãng) là cỏ cây um tùm. | Gương Hán-Việt | trăn trong \"trăn tử\" (榛子 — hạt phỉ), \"trăn mãng\" (榛莽 — bụi rậm), \"trăn vu\" (榛蕪 — cỏ dại um tùm) | Mở khoá kiến thức | Biết 榛 (trăn) mở khoá \"榛子\" (hạt phỉ) và nhóm chữ bộ 木 chỉ cây cối trong thực vật học.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 榛 là chữ hình thanh: 木 (cây, biểu nghĩa) + 秦 (tần, biểu âm). Nghĩa chính là cây phỉ (Corylus heterophylla), hạt phỉ; cũng chỉ bụi cây rậm rạp, um tùm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây trăn; bụi cây; vướng vít", "Hạng Tần Suất (Jun Da)": "4574.0", "Tần Suất % (Jun Da)": "99.8712083591", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 秦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木秦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榛", "Unihan_Traditional (Chữ Phồn thể)": "榛", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trăn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây bụi có quả ăn được hoặc chỉ nơi hoang dã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昱', '{"9000": "4575.0", "Chữ Trung Quốc": "昱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 昱 | dục | tượng hình | ánh sáng mặt trời, ngày mai | 昱 chứa bộ 日 (nhật, mặt trời) ở trên và 立 (lập, đứng) ở dưới. Wiktionary không cung cấp phân tích hình thanh cụ thể. Chữ biểu đạt ánh sáng rực rỡ, ban mai — và nghĩa là ngày mai (biến thể của 翌).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": mặt trời (日/nhật) đứng (立/lập) tỏa sáng — dục là ánh sáng ban mai, \"ngày mai\" trong văn cổ. | Gương Hán-Việt | dục trong \"chiêu dục\" (昭昱 — rực sáng), tên người và địa danh dùng chữ 昱 | Mở khoá kiến thức | Biết 昱 (dục) mở khoá nhóm chữ bộ 日 chỉ ánh sáng và thời gian trong thơ văn cổ điển.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 昱 gồm 日 (mặt trời) và 立 (đứng), gợi hình ảnh mặt trời đứng chiếu sáng. Nghĩa là ánh sáng rực rỡ; cũng dùng thay cho 翌 (ngày mai) trong văn ngôn. Hanziyuan có giáp cốt/kim văn cho thấy chữ cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngày mai", "Hạng Tần Suất (Jun Da)": "4575.0", "Tần Suất % (Jun Da)": "99.8713582268", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昱", "Unihan_Traditional (Chữ Phồn thể)": "昱", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ chỉ sự sáng sủa hoặc dùng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜴', '{"9000": "4576.0", "Chữ Trung Quốc": "蜴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜴 | dịch | tượng hình | thằn lằn (dùng trong 蜥蜴) | 蜴 chứa bộ 虫 (trùng, côn trùng/sinh vật nhỏ) biểu nghĩa; phần phải 易 (dịch) biểu âm. Wiktionary không có phân tích cấu tạo chi tiết. Chữ dùng hầu như chỉ trong \"蜥蜴\" (tích dịch — thằn lằn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": bộ 虫 (sinh vật) + âm 易 (dịch) — dịch trong \"tích dịch\" (蜥蜴) là con thằn lằn. | Gương Hán-Việt | dịch trong \"tích dịch\" (蜥蜴 — thằn lằn) | Mở khoá kiến thức | Biết 蜴 (dịch) mở khoá \"蜥蜴\" (tích dịch — thằn lằn) và nhóm chữ bộ 虫 chỉ bò sát/động vật nhỏ.", "Tự nguyên_Xie": "Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật. Chữ 蜴 gồm bộ 虫 (sinh vật) biểu nghĩa và 易 (dịch) biểu âm. Dùng gần như độc quyền trong \"蜥蜴\" (tích dịch — thằn lằn). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tích dịch 蜥蜴)", "Hạng Tần Suất (Jun Da)": "4576.0", "Tần Suất % (Jun Da)": "99.8715075777", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜴", "Unihan_Traditional (Chữ Phồn thể)": "蜴", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng trong từ ghép tích dịch để chỉ loài thằn lằn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳝', '{"9000": "4577.0", "Chữ Trung Quốc": "鳝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鳝 | thiện | tượng hình | con lươn | 鳝 chứa bộ 魚 (ngư, cá) biểu nghĩa; phần phải 善 (thiện) biểu âm. Chữ tạo muộn chỉ con lươn (Monopterus albus). Wiktionary không có phân tích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": bộ 魚 (cá) + âm 善 (thiện) — thiện là con lươn, loài \"cá thiện\" sống lặng lẽ dưới bùn. | Gương Hán-Việt | thiện trong \"hoàng thiện\" (黄鳝 — con lươn vàng), \"thiện ngư\" (鳝鱼 — lươn) | Mở khoá kiến thức | Biết 鳝 (thiện) mở khoá \"黄鳝\" (hoàng thiện — lươn vàng) và nhóm chữ bộ 魚 chỉ các loài thủy sản.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật. Chữ 鳝 gồm bộ 魚 (cá) biểu nghĩa và 善 (thiện) biểu âm — chỉ con lươn, loài cá không vảy sống dưới bùn. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lươn", "Hạng Tần Suất (Jun Da)": "4577.0", "Tần Suất % (Jun Da)": "99.8716569286", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 善", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼善", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "善", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳝", "Unihan_Traditional (Chữ Phồn thể)": "鱓", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các món ăn từ lươn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噙', '{"9000": "4578.0", "Chữ Trung Quốc": "噙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 噙 | gầm | tượng hình | ngậm trong miệng | 噙 chứa bộ 口 (khẩu, miệng) biểu nghĩa; phần phải 禽 (cầm) biểu âm. Wiktionary không có dữ liệu cấu tạo. Chữ chỉ hành động ngậm, giữ thứ gì đó trong miệng mà không nuốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gầm\": miệng (口) giữ chặt như chim (禽/cầm) tha mồi — gầm là ngậm, giữ thứ gì trong miệng không buông. | Gương Hán-Việt | gầm trong \"gầm lệ\" (噙泪 — ngậm lệ, cố không khóc) | Mở khoá kiến thức | Biết 噙 (gầm) mở khoá hình ảnh \"噙泪\" (ngậm lệ) — hình ảnh văn học chỉ cố kìm nước mắt.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary. Chữ 噙 gồm bộ 口 (miệng) biểu nghĩa và 禽 (cầm) biểu âm — chỉ hành động ngậm, giữ trong miệng. Chữ tạo muộn. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngậm trong miệng", "Hạng Tần Suất (Jun Da)": "4578.0", "Tần Suất % (Jun Da)": "99.8718057627", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 禽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口禽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噙", "Unihan_Traditional (Chữ Phồn thể)": "噙", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ như nước mắt hoặc vật ngậm trong miệng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淼', '{"9000": "4579.0", "Chữ Trung Quốc": "淼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước | 水 | thủy | biểu nghĩa | nước | 水 | thủy | biểu nghĩa | nước | 淼 là chữ hội ý đặc biệt: ba chữ 水 (thủy, nước) chồng lên nhau — ba nước tạo thành biển cả mênh mông. Cấu trúc tăng cấp (三叠字) biểu đạt sự rộng lớn vô tận của nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diểu\": ba chữ 水 (thủy) — diểu là sóng nước mênh mông, \"淼淼\" (diểu diểu) gợi cảnh biển hồ bát ngát. | Gương Hán-Việt | diểu trong \"diểu diểu\" (淼淼 — mênh mông), \"hạo diểu\" (浩淼 — rộng lớn) | Mở khoá kiến thức | Biết 淼 (diểu) mở khoá nhóm chữ ba lần lặp (三叠字) biểu đạt nghĩa tăng cấp và thơ văn tả cảnh nước.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 淼 được tạo từ ba chữ 水 (nước) — cấu trúc ba lần lặp (三叠) biểu đạt nghĩa tăng cấp: nước nhiều đến mức mênh mông. Nghĩa là rộng lớn, bát ngát (của nước). Dùng trong thơ văn chỉ cảnh sông hồ bao la. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mênh mông; rộng lớn (nước)", "Hạng Tần Suất (Jun Da)": "4579.0", "Tần Suất % (Jun Da)": "99.8719545968", "GavinGrover_Once (Chiết tự trực tiếp)": "水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "淼", "Unihan_Traditional (Chữ Phồn thể)": "淼", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "diểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả cảnh sông nước bao la hoặc dùng đặt tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矾', '{"9000": "4580.0", "Chữ Trung Quốc": "矾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 8 | nét | 石 | thạch | biểu nghĩa | đá, khoáng vật | 凡 | phàm | biểu âm | 矾 là chữ hình thanh (ls=psc): 石 (thạch, biểu nghĩa: đá/khoáng vật) + 凡 (phàm, biểu âm). Chữ chỉ phèn — hợp chất khoáng có sulfate kép, dùng trong y học và hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": khoáng thạch (石) phát âm theo 凡 (phàm) — phàn là phèn, loại khoáng thạch kết tinh dùng trong hóa học và y học. | Gương Hán-Việt | phàn trong \"minh phàn\" (明矾 — phèn chua), \"phàn thạch\" (矾石 — đá phèn) | Mở khoá kiến thức | Biết 矾 (phàn) mở khoá \"明矾\" (minh phàn — phèn chua, alum) và nhóm chữ hóa học có bộ 石.", "Tự nguyên_Xie": "Theo Wiktionary, 矾 là chữ hình thanh: 石 (đá/khoáng vật, biểu nghĩa) + 凡 (phàm, biểu âm). Chữ 矾 là dạng giản thể của 礬, chỉ phèn — hợp chất khoáng chất dạng tinh thể (alum). Dùng trong hóa học và y học truyền thống. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phèn (hoá học)", "Hạng Tần Suất (Jun Da)": "4580.0", "Tần Suất % (Jun Da)": "99.8721029142", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矾", "Unihan_Traditional (Chữ Phồn thể)": "礬", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loại phèn hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硼', '{"9000": "4581.0", "Chữ Trung Quốc": "硼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 石 | thạch | biểu nghĩa | đá, khoáng vật | 朋 | bằng | biểu âm | 硼 là chữ hình thanh (ls=psc): 石 (thạch, biểu nghĩa: khoáng vật) + 朋 (bằng, biểu âm). Chữ tạo muộn, là tên phiên âm cho nguyên tố Boron (B, số hiệu 5) trong hệ thống danh pháp hóa học Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": khoáng (石) phát âm theo 朋 (bằng) — bằng là boron (B), nguyên tố phiên âm theo chữ Hán. | Gương Hán-Việt | bằng trong \"bằng sa\" (硼砂 — borax/hàn the), \"bằng toan\" (硼酸 — axit boric) | Mở khoá kiến thức | Biết 硼 (bằng) mở khoá \"硼砂\" (hàn the/borax) và \"硼酸\" (axit boric) — nhóm chữ hóa học bộ 石.", "Tự nguyên_Xie": "Theo Wiktionary, 硼 là chữ hình thanh: 石 (khoáng vật, biểu nghĩa) + 朋 (bằng, biểu âm, không có âm cổ đại). Chữ tạo muộn để phiên âm tên nguyên tố Boron trong hóa học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "boron, B", "Hạng Tần Suất (Jun Da)": "4581.0", "Tần Suất % (Jun Da)": "99.8722512315", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硼", "Unihan_Traditional (Chữ Phồn thể)": "硼", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong hóa học để chỉ nguyên tố boron hoặc các hợp chất của nó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囿', '{"9000": "4582.0", "Chữ Trung Quốc": "囿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 9 | nét | 囿 | hựu | tượng hình | vườn thú, vườn nuôi thú để chơi | 囿 chứa bộ 囗 (vi, vòng bao quanh) biểu nghĩa; bên trong 有 (hữu) biểu âm. Hình ảnh khu vực bao quanh (囗) có vật nuôi bên trong — tức vườn thú hoàng gia. Nghĩa phái sinh: bị giới hạn, bị bó buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hựu\": vòng bao (囗) chứa đựng (有/hữu) — hựu là vườn thú hoàng gia, nghĩa phái sinh: bị giam cầm trong khuôn khổ. | Gương Hán-Việt | hựu trong \"hựu vu\" (囿于 — bị giới hạn bởi), \"uyển hựu\" (苑囿 — vườn thú hoàng gia) | Mở khoá kiến thức | Biết 囿 (hựu) mở khoá \"囿于\" (bị giới hạn bởi) — cụm thường gặp trong văn viết và \"苑囿\" (vườn thú cổ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Hanziyuan có giáp cốt và kim văn. Chữ 囿 gồm 囗 (vòng bao) + 有 (hữu) biểu âm — nguyên nghĩa là vườn thú hoàng gia thời cổ. Nghĩa phái sinh là bị hạn chế, bị bó hẹp. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vườn nuôi thú để chơi", "Hạng Tần Suất (Jun Da)": "4582.0", "Tần Suất % (Jun Da)": "99.8723995488", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囿", "Unihan_Traditional (Chữ Phồn thể)": "囿", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ vườn thú hoặc làm động từ mang nghĩa bị giới hạn trong phạm vi nào đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泅', '{"9000": "4583.0", "Chữ Trung Quốc": "泅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 水 | thủy | biểu nghĩa | nước | 囚 | tù | biểu âm | 泅 là chữ hình thanh (ls=psc): 水 (thủy, biểu nghĩa: nước) + 囚 (tù, biểu âm). Hình ảnh người bơi trong nước — tức bơi lội. Phần biểu âm 囚 (tù) cũng gợi hình người bị vây bọc bởi nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tù\": nước (水/thủy) bao quanh người tù (囚/tù) — tù là bơi, cơ thể bị nước bao bọc khi lội qua sông. | Gương Hán-Việt | tù trong \"phù tù\" (浮泅 — bơi lội), \"tù thủy\" (泅水 — bơi qua nước) | Mở khoá kiến thức | Biết 泅 (tù) mở khoá \"泅水\" (tù thủy — bơi) và \"泅渡\" (tù độ — bơi qua sông) — từ văn học quân sự.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 泅 là chữ hình thanh: 水 (nước, biểu nghĩa) + 囚 (tù, biểu âm). Nghĩa là bơi lội — đặc biệt bơi vượt sông. Phần 囚 (người bị vòng bao quanh) hợp với 水 gợi hình người bơi giữa nước. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bơi lội", "Hạng Tần Suất (Jun Da)": "4583.0", "Tần Suất % (Jun Da)": "99.8725473494", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 囚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵囚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泅", "Unihan_Traditional (Chữ Phồn thể)": "泅", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "tù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành vi bơi lội, có thể kết hợp thành từ ghép như tù thủy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邂', '{"9000": "4584.0", "Chữ Trung Quốc": "邂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 16 | nét | 辵 | biểu nghĩa | đi, di chuyển | 解 | giải | biểu âm | 邂 là chữ hình thanh (ls=psc): 辵 (sước, biểu nghĩa: di chuyển, đi đường) + 解 (giải, biểu âm). Chữ dùng duy nhất trong \"邂逅\" (giải cấu — tình cờ gặp gỡ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": đi đường (辵/sước) gặp nhau theo âm 解 (giải) — giải là cuộc gặp gỡ tình cờ trong \"邂逅\" (giải cấu). | Gương Hán-Việt | giải trong \"giải cấu\" (邂逅 — tình cờ gặp), \"giải cấu tương phùng\" (邂逅相逢 — tình cờ gặp nhau) | Mở khoá kiến thức | Biết 邂 (giải) mở khoá \"邂逅\" (giải cấu) — từ cổ điển chỉ cuộc gặp gỡ ngẫu nhiên, duyên trời định.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 邂 là chữ hình thanh: 辵 (di chuyển, biểu nghĩa) + 解 (giải, biểu âm). Chữ dùng hầu như chỉ trong \"邂逅\" (giải cấu — gặp gỡ tình cờ, không hẹn trước). Hình ảnh gặp nhau trên đường đi một cách ngẫu nhiên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: giải cấu 邂逅)", "Hạng Tần Suất (Jun Da)": "4584.0", "Tần Suất % (Jun Da)": "99.8726951499", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 解", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶解", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "邂", "Unihan_Traditional (Chữ Phồn thể)": "邂", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Hầu như chỉ xuất hiện trong từ ghép giải cấu để chỉ sự gặp gỡ bất ngờ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钜', '{"9000": "4585.0", "Chữ Trung Quốc": "钜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钜 | cự | tượng hình | lớn, sắt cứng, cái móc sắt | 钜 chứa bộ 金 (kim, sắt/kim loại) biểu nghĩa; phần phải 巨 (cự) vừa biểu âm vừa biểu nghĩa (lớn). Chữ chỉ sắt cứng chất lượng cao, hoặc vật gì lớn lao. Wiktionary không cung cấp phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": kim loại (金) lớn (巨/cự) — cự là sắt cứng khổng lồ; \"钜富\" (cự phú) là người giàu lớn. | Gương Hán-Việt | cự trong \"cự phú\" (钜富 — người giàu lớn), \"cự nhân\" (钜人 — người lớn, danh nhân) | Mở khoá kiến thức | Biết 钜 (cự) mở khoá nhóm \"cự\" (巨/钜) chỉ sự lớn lao và địa danh lịch sử \"Cự Lộc\" (钜鹿/巨鹿).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật. Chữ 钜 gồm 金 (kim loại) + 巨 (cự, lớn) — chỉ sắt tốt, cứng; hoặc vật gì lớn lao, đồ sộ. Dùng trong địa danh (钜野 — Cự Dã) và nghĩa \"lớn\" trong văn ngôn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lớn; sắt cứng; cái móc", "Hạng Tần Suất (Jun Da)": "4585.0", "Tần Suất % (Jun Da)": "99.8728429505", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钜", "Unihan_Traditional (Chữ Phồn thể)": "鉅", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ quy mô to lớn hoặc làm danh từ chỉ sắt tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠹', '{"9000": "4586.0", "Chữ Trung Quốc": "蠹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 24 | nét | 橐 | biểu âm | 䖵 | biểu nghĩa | côn trùng | 蠹 là chữ hình thanh (ls=psc): 䖵 (trùng kép, biểu nghĩa: côn trùng) + 橐 (biểu âm). Chữ chỉ con mọt — loài côn trùng đục khoét giấy, vải, gỗ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đố\": côn trùng (䖵) ăn mọt theo âm 橐 — đố là con mọt, \"thư đố\" (書蠹) là mọt sách, kẻ chỉ đọc sách mà không biết dùng. | Gương Hán-Việt | đố trong \"thư đố\" (書蠹 — mọt sách), \"đố quốc\" (蠹國 — hại nước), \"hà đố\" (河蠹 — hà mã/kẻ ăn bám) | Mở khoá kiến thức | Biết 蠹 (đố) mở khoá \"蠹國\" (đố quốc — kẻ hại nước) và \"書蠹\" (thư đố — mọt sách) — từ văn ngôn quan trọng.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蠹 là chữ hình thanh: 橐 (biểu âm) + 䖵 (côn trùng kép, biểu nghĩa). Nghĩa gốc là con mọt ăn giấy sách (silverfish) hay mọt gỗ. Nghĩa phái sinh là kẻ hại, phần tử phá hoại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con mọt", "Hạng Tần Suất (Jun Da)": "4586.0", "Tần Suất % (Jun Da)": "99.872990751", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蠹", "Unihan_Traditional (Chữ Phồn thể)": "蠹", "Pinyin_Xie": "dù", "Âm Hán Việt_Xie": "đố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ loài sâu mọt hoặc làm động từ với nghĩa ẩn dụ là đục khoét, làm hao mòn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垩', '{"9000": "4587.0", "Chữ Trung Quốc": "垩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 垩 | ác | tượng hình | đất sét trắng, phấn, vôi trắng | 垩 chứa bộ 土 (thổ, đất) ở dưới; phần trên 亚 (á) biểu âm. Chữ chỉ loại đất sét trắng hoặc phấn dùng để trát tường. Wiktionary cung cấp thông tin phát âm đầy đủ nhưng không phân tích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ác\": đất (土) màu trắng — ác là phấn trắng, \"白垩\" (bạch ác) là phấn trắng và tên thời kỳ địa chất Cretaceous. | Gương Hán-Việt | ác trong \"bạch ác\" (白垩 — phấn trắng, thời Cretaceous), \"ác thất\" (垩室 — căn phòng quét trắng) | Mở khoá kiến thức | Biết 垩 (ác) mở khoá \"白垩紀\" (bạch ác kỷ — kỷ Phấn trắng/Cretaceous) — thuật ngữ địa chất học quan trọng.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 垩 gồm 土 (đất) + 亚 (á) biểu âm — chỉ phấn hoặc đất sét trắng dùng quét tường. Dùng trong \"白垩\" (bạch ác — phấn trắng, thời kỳ Cretaceous). Hanziyuan có dạng tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất thó trắng, đất sét trắng; trát bùn", "Hạng Tần Suất (Jun Da)": "4587.0", "Tần Suất % (Jun Da)": "99.8731380348", "GavinGrover_Once (Chiết tự trực tiếp)": "亚 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亚土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垩", "Unihan_Traditional (Chữ Phồn thể)": "堊", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ đất thó trắng hoặc làm động từ chỉ việc quét vôi, tô vẽ tường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乩', '{"9000": "4588.0", "Chữ Trung Quốc": "乩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 乙 | Số nét | 6 | nét | 乩 | ki | tượng hình | bói xem, đồng bóng | 乩 là chữ tạo muộn, cấu trúc không rõ ràng. Wiktionary không có dữ liệu. Chữ dùng chỉ hình thức bói toán cổ đại — dùng que bút viết chữ trên cát/tro để xem điềm (扶乩 — phù ki, cầu cơ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ki\": chữ tạo muộn, chưa thấy trong giáp cốt/kim văn — ki là bói toán, \"扶乩\" (phù ki) là cầu cơ xin điềm. | Gương Hán-Việt | ki trong \"phù ki\" (扶乩 — cầu cơ, bói toán bằng que viết) | Mở khoá kiến thức | Biết 乩 (ki) mở khoá \"扶乩\" (phù ki — cầu cơ) — hình thức tín ngưỡng dân gian phổ biến trong văn hóa Hoa.", "Tự nguyên_Xie": "Không có dữ liệu nguồn gốc từ Wiktionary. Chữ 乩 là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Dùng trong \"扶乩\" (phù ki — cầu cơ, xin điềm) — hình thức bói toán dùng que viết chữ trên cát. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bói xem đúng sai", "Hạng Tần Suất (Jun Da)": "4588.0", "Tần Suất % (Jun Da)": "99.873284285", "GavinGrover_Once (Chiết tự trực tiếp)": "占 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰占乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乚", "Unihan_Simplified (Chữ Giản thể)": "乩", "Unihan_Traditional (Chữ Phồn thể)": "乩", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ trong hoạt động bói toán hoặc làm danh từ trong các từ ghép chỉ dụng cụ bói. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗝', '{"9000": "4589.0", "Chữ Trung Quốc": "嗝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng | 鬲 | biểu âm | 嗝 là chữ hình thanh (ls=psc): 口 (khẩu, biểu nghĩa: miệng) + 鬲 (biểu âm). Chữ chỉ tiếng nấc hoặc ợ hơi — âm thanh phát ra từ miệng khi khí từ dạ dày trào lên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": miệng (口/khẩu) phát âm theo 鬲 (cách) — cách là tiếng ợ/nấc phát ra từ miệng. | Gương Hán-Việt | cách trong \"ợ cách\" (打嗝 — ợ hơi, nấc), \"cách cách\" (嗝嗝 — tiếng nấc liên tục) | Mở khoá kiến thức | Biết 嗝 (cách) mở khoá \"打嗝\" (đả cách — ợ hơi/nấc) và nhóm chữ bộ 口 chỉ âm thanh từ miệng.", "Tự nguyên_Xie": "Theo Wiktionary, 嗝 là chữ hình thanh: 口 (miệng, biểu nghĩa) + 鬲 (biểu âm). Nghĩa là ợ hơi hoặc nấc cụt — tiếng phát ra từ miệng khi khí dạ dày bị đẩy lên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấc, ợ", "Hạng Tần Suất (Jun Da)": "4589.0", "Tần Suất % (Jun Da)": "99.8734305352", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗝", "Unihan_Traditional (Chữ Phồn thể)": "嗝", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ tiếng nấc hoặc kết hợp với động từ để chỉ hành động nấc, ợ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淦', '{"9000": "4590.0", "Chữ Trung Quốc": "淦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 水 | thủy | biểu nghĩa | nước | 金 | kim | biểu âm | 淦 là chữ hình thanh (ls=psc): 水 (thủy, biểu nghĩa: nước) + 金 (kim, biểu âm). Chữ chỉ tên sông Cam (淦水) ở Giang Tây, Trung Quốc; cũng có thể chỉ nước rỉ vào thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cám\": nước (水/thủy) theo âm 金 (kim) — cám là tên sông Cam (淦水) chảy qua tỉnh Giang Tây. | Gương Hán-Việt | cám trong \"Cám Thủy\" (淦水 — sông Cam), \"Cao An\" (高安, tên cũ gắn với sông Cám) | Mở khoá kiến thức | Biết 淦 (cám) mở khoá địa danh sông Cam ở Giang Tây và nhóm chữ bộ 水 chỉ sông ngòi.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 淦 là chữ hình thanh: 水 (nước, biểu nghĩa) + 金 (kim, biểu âm). Nghĩa gốc có thể là nước rỉ vào thuyền hoặc tên sông. Dùng chủ yếu trong địa danh tên sông Cam (淦水) và thành phố Cao An (thuộc vùng sông Cam). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Cam", "Hạng Tần Suất (Jun Da)": "4590.0", "Tần Suất % (Jun Da)": "99.8735767854", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淦", "Unihan_Traditional (Chữ Phồn thể)": "淦", "Pinyin_Xie": "gàn", "Âm Hán Việt_Xie": "cam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ riêng chỉ tên sông hoặc làm động từ chỉ việc nước rò rỉ vào thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樽', '{"9000": "4591.0", "Chữ Trung Quốc": "樽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | gỗ | 尊 | tôn | biểu âm | 樽 là chữ hình thanh (ls=psc): 木 (mộc, biểu nghĩa: gỗ) + 尊 (tôn, biểu âm). Chữ chỉ bình/chén rượu làm bằng gỗ; sau dùng cho bình rượu nói chung, thường gặp trong thơ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": gỗ (木/mộc) theo âm 尊 (tôn) — tôn là bình rượu gỗ; \"đối ảnh thành tam nhân\" (對影成三人) — Lý Bạch ngồi một mình với trăng và bình 樽. | Gương Hán-Việt | tôn trong \"kim tôn\" (金樽 — bình rượu vàng), \"tôn tửu\" (樽酒 — rượu trong bình) | Mở khoá kiến thức | Biết 樽 (tôn) mở khoá \"金樽\" (kim tôn — bình rượu vàng) trong thơ Lý Bạch và nhóm chữ bộ 木 chỉ đồ dùng.", "Tự nguyên_Xie": "Theo Wiktionary, 樽 là chữ hình thanh: 木 (gỗ, biểu nghĩa) + 尊 (tôn, biểu âm). Nghĩa là bình rượu, chén rượu — đặc biệt loại làm bằng gỗ. Xuất hiện nhiều trong thơ Đường tả cảnh uống rượu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chén", "Hạng Tần Suất (Jun Da)": "4591.0", "Tần Suất % (Jun Da)": "99.8737225188", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樽", "Unihan_Traditional (Chữ Phồn thể)": "樽", "Pinyin_Xie": "zūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ dụng cụ uống rượu hoặc làm lượng từ cho rượu trong văn thơ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诮', '{"9000": "4592.0", "Chữ Trung Quốc": "诮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 诮 | tiếu | tượng hình | chỉ trích, nói mát, chế nhạo | 诮 chứa bộ 言 (ngôn, lời nói) biểu nghĩa; phần phải 肖 (tiếu) biểu âm. Chữ chỉ hành động chỉ trích, trách móc bằng lời — nói khéo để châm biếm hoặc trách phạt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiếu\": lời (言/ngôn) sắc bén như âm 肖 (tiếu) — tiếu là chỉ trích bằng ngôn từ, nói mát nói xéo trong văn ngôn. | Gương Hán-Việt | tiếu trong \"cơ tiếu\" (譏誚 — châm biếm), \"đế tiếu\" (詆誚 — chỉ trích) | Mở khoá kiến thức | Biết 诮 (tiếu) mở khoá nhóm chữ bộ 言 chỉ hành động nói trách cứ trong văn ngôn cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 诮 gồm 言 (lời nói) biểu nghĩa và 肖 (tiếu) biểu âm — chỉ chỉ trích, trách cứ bằng lời trong văn ngôn. Hanziyuan có dạng tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói mát, nói xoa dịu", "Hạng Tần Suất (Jun Da)": "4592.0", "Tần Suất % (Jun Da)": "99.8738672186", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诮", "Unihan_Traditional (Chữ Phồn thể)": "誚", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "tiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước đối tượng bị trách móc hoặc kết hợp thành từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揆', '{"9000": "4593.0", "Chữ Trung Quốc": "揆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 揆 | quẫy | tượng hình | đo lường, suy xét; thủ tướng | 揆 chứa bộ 手 (thủ, tay) biểu nghĩa; phần phải 癸 (quý) biểu âm. Chữ chỉ hành động đo lường, cân nhắc bằng tay; nghĩa phái sinh chỉ người lãnh đạo chính phủ (thủ tướng). Wiktionary không có phân tích cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quẫy\": tay (手) đo lường — quẫy là cân nhắc bằng tay, \"閣揆\" (các quẫy) là người đứng đầu nội các. | Gương Hán-Việt | quẫy trong \"các quẫy\" (閣揆 — thủ tướng), \"nhất quẫy\" (一揆 — một mực, nhất quán) | Mở khoá kiến thức | Biết 揆 (quẫy) mở khoá \"閣揆\" (thủ tướng trong văn ngôn) và \"度揆\" (đo lường, cân nhắc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 揆 gồm 手 (tay) biểu nghĩa và 癸 biểu âm — nghĩa gốc là đo lường, suy đoán. Nghĩa trọng yếu: 阁揆 (các quẫy) — thủ tướng/thủ lĩnh chính phủ trong văn ngôn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đo lường", "Hạng Tần Suất (Jun Da)": "4593.0", "Tần Suất % (Jun Da)": "99.8740114017", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揆", "Unihan_Traditional (Chữ Phồn thể)": "揆", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc suy xét, quản lý hoặc làm danh từ chỉ người đứng đầu triều chính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啐', '{"9000": "4594.0", "Chữ Trung Quốc": "啐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啐 | chót | tượng hình | nếm thử; nhổ nước bọt; tặc lưỡi khinh thường | 啐 chứa bộ 口 (khẩu, miệng) biểu nghĩa; phần phải 卒 (tốt) biểu âm. Chữ chỉ nhiều nghĩa liên quan đến miệng: nếm thử, nhổ, hoặc phát ra âm khinh thường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chót\": miệng (口/khẩu) phát ra theo âm 卒 (tốt) — chót là nếm thử hay nhổ, hành động miệng dứt khoát. | Gương Hán-Việt | chót trong \"chót ẩm\" (啐飲 — nếm một chút rượu), \"thảo chót\" (嘈啐 — ồn ào hỗn độn) | Mở khoá kiến thức | Biết 啐 (chót) mở khoá \"啐啄\" (chót trác — gõ vỏ trứng từ trong và ngoài cùng lúc — ẩn dụ thầy-trò cùng khai ngộ) và nhóm chữ bộ 口.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 啐 gồm 口 (miệng) biểu nghĩa và 卒 (tốt) biểu âm. Nghĩa: nếm thử, nhổ nước bọt, hoặc tặc lưỡi khinh thường. Hanziyuan có dạng tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nếm thử", "Hạng Tần Suất (Jun Da)": "4594.0", "Tần Suất % (Jun Da)": "99.8741555847", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啐", "Unihan_Traditional (Chữ Phồn thể)": "啐", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "thối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thán từ | 叹词 | Thường dùng làm động từ chỉ hành động nhổ nước bọt tỏ ý khinh bỉ hoặc làm thán từ biểu thị sự chê bai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淅', '{"9000": "4595.0", "Chữ Trung Quốc": "淅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thủy | biểu nghĩa | nước | 析 | tích | biểu âm | 淅 là chữ hình thanh (ls=psc): 氵 (thủy, biểu nghĩa: nước) + 析 (tích, biểu âm). Chữ chỉ tiếng mưa rơi nhẹ (淅沥 — tích lịch) hoặc nước vo gạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": nước (氵/thủy) theo âm 析 (tích) — tích trong \"tích lịch\" (淅沥) là tiếng mưa nhẹ rơi lách tách. | Gương Hán-Việt | tích trong \"tích lịch\" (淅沥 — tiếng mưa nhỏ), \"tích lịch lịch\" (淅沥沥 — mưa rỉ rả) | Mở khoá kiến thức | Biết 淅 (tích) mở khoá \"淅沥\" (tích lịch — tiếng mưa rơi nhỏ giọt) — từ thơ văn tả cảnh mưa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 淅 là chữ hình thanh: 水/氵 (nước, biểu nghĩa) + 析 (tích, biểu âm). Nghĩa là vo gạo (trong văn ngôn); phổ biến hơn trong \"淅沥\" chỉ tiếng mưa nhỏ giọt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tiếng mưa rơi); nước vo gạo", "Hạng Tần Suất (Jun Da)": "4595.0", "Tần Suất % (Jun Da)": "99.8742997678", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 析", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵析", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "析", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淅", "Unihan_Traditional (Chữ Phồn thể)": "淅", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường làm động từ chỉ việc vo gạo hoặc kết hợp từ láy để mô tả tiếng mưa rơi, gió thổi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榉', '{"9000": "4596.0", "Chữ Trung Quốc": "榉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 榉 | cử | tượng hình | cây cử (Zelkova), cây sồi Nhật | 榉 chứa bộ 木 (mộc, cây) biểu nghĩa; phần trên 举 (cử) biểu âm. Chữ chỉ cây Zelkova — loài cây lá rộng họ du (elm), gỗ quý. Wiktionary không cung cấp phân tích cấu tạo học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cử\": cây (木/mộc) theo âm 举 (cử) — cử là cây cử (Zelkova), gỗ cứng quý dùng làm đồ nội thất. | Gương Hán-Việt | cử trong \"cử thụ\" (榉树 — cây Zelkova), \"sơn mao cử\" (山毛榉 — cây sồi Nhật/beech) | Mở khoá kiến thức | Biết 榉 (cử) mở khoá \"榉树\" (cây Zelkova) và \"山毛榉\" (sơn mao cử — cây beech) trong thực vật học.", "Tự nguyên_Xie": "Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 榉 gồm 木 (cây) + 举 (cử) biểu âm. Chỉ cây Zelkova serrata — loài cây lá rộng quý hiếm. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cử, cây sồi", "Hạng Tần Suất (Jun Da)": "4596.0", "Tần Suất % (Jun Da)": "99.8744439508", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 举", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木举", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "举", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榉", "Unihan_Traditional (Chữ Phồn thể)": "櫸", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "cử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loại cây thuộc họ dẻ, sồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馗', '{"9000": "4597.0", "Chữ Trung Quốc": "馗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 首 | Số nét | 11 | nét | 馗 | quỳ | tượng hình | đường thông tới 9 ngả; (Chung Quỳ) | 馗 chứa bộ 首 (thủ, đầu) biểu nghĩa; phần trái 九 (cửu, chín) biểu nghĩa phụ/biểu âm. Chữ gốc chỉ con đường thông ra chín ngả. Sau được dùng làm tên \"Chung Quỳ\" (鐘馗 — thần trừ tà ma trong dân gian Trung Quốc). Hanziyuan có dạng tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳ\": đầu đường (首) + chín (九) ngả — quỳ là ngã chín đường; tên của Chung Quỳ (鐘馗) — thần đuổi quỷ. | Gương Hán-Việt | quỳ trong \"Chung Quỳ\" (鐘馗 — vị thần trừ tà), \"quỳ lộ\" (馗路 — đường lớn chín ngả) | Mở khoá kiến thức | Biết 馗 (quỳ) mở khoá \"鐘馗\" (Chung Quỳ — thần đuổi quỷ) và hình ảnh văn hóa dân gian Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận phát âm nhưng không có phân tích cấu tạo học thuật chi tiết. Chữ 馗 gồm 首 (đầu/đầu đường) + 九 (chín) — nguyên nghĩa là con đường chín ngả. Được dùng làm tên \"Chung Quỳ\" (鍾馗/鐘馗) — vị thần trừ quỷ trong tín ngưỡng dân gian. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đường thông tới 9 ngả", "Hạng Tần Suất (Jun Da)": "4597.0", "Tần Suất % (Jun Da)": "99.8745876171", "GavinGrover_Once (Chiết tự trực tiếp)": "九 + 首", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴九首", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "首", "Unihan_Simplified (Chữ Giản thể)": "馗", "Unihan_Traditional (Chữ Phồn thể)": "馗", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "quỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ đường sá thông thoáng hoặc dùng trong tên riêng như Chung Quỳ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辔', '{"9000": "4598.0", "Chữ Trung Quốc": "辔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 辔 | bí | tượng hình | dây cương ngựa | 辔 là giản thể của 轡. Theo Wiktionary, Han simp từ 轡 với 絲→丝, 車→车. Dây cương ngựa là vật dùng để điều khiển ngựa. Chữ gốc 轡 gồm phần liên quan đến sợi dây và xe/ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": sợi dây (丝) + xe ngựa (车) — bí là dây cương, người cầm 辔 (bí) điều khiển ngựa chiến. | Gương Hán-Việt | bí trong \"cương bí\" (韁辔 — dây cương), \"phân bí\" (分辔 — chia đường, chia tay nhau khi cưỡi ngựa) | Mở khoá kiến thức | Biết 辔 (bí) mở khoá \"韁辔\" (cương bí — dây cương) và \"辔头\" (bí đầu — bộ dây cương đầu ngựa).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 辔 là giản thể của 轡, rút gọn từ 絲 (ty, sợi dây) → 丝 và 車 (xa, xe) → 车. Chữ 轡/辔 chỉ dây cương ngựa — đồ dùng bằng sợi dây và da để điều khiển ngựa. Hanziyuan có dạng tiểu triện của chữ phồn thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cương ngựa", "Hạng Tần Suất (Jun Da)": "4598.0", "Tần Suất % (Jun Da)": "99.8747312834", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "辔", "Unihan_Traditional (Chữ Phồn thể)": "轡", "Pinyin_Xie": "pèi", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho các động từ điều khiển ngựa như cầm, giật dây cương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暹', '{"9000": "4599.0", "Chữ Trung Quốc": "暹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 15 | nét | 日 | nhật | biểu nghĩa | mặt trời | 進 | tiến | biểu nghĩa | tiến lên | 暹 là chữ hội ý (ls=ic): 日 (nhật, mặt trời) + 進 (tiến, tiến lên) — hình ảnh mặt trời mọc lên cao. Nghĩa là mặt trời mọc; được dùng chủ yếu trong \"暹羅\" (Xiêm La — tên cũ của Thái Lan).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xiêm\": mặt trời (日/nhật) tiến lên (進/tiến) — xiêm là mặt trời mọc, \"Xiêm La\" (暹羅) là đất nước của mặt trời mọc — tên cũ của Thái Lan. | Gương Hán-Việt | xiêm trong \"Xiêm La\" (暹羅 — Thái Lan), \"Xiêm La quốc\" (暹羅國 — vương quốc Xiêm) | Mở khoá kiến thức | Biết 暹 (xiêm) mở khoá \"暹羅\" (Xiêm La — tên lịch sử của Thái Lan) trong lịch sử và địa lý Đông Nam Á.", "Tự nguyên_Xie": "Theo Wiktionary, 暹 là chữ hội ý: 日 (mặt trời) + 進 (tiến lên) — nghĩa là mặt trời mọc lên. Dùng chủ yếu trong \"暹羅\" (Xiêm La — Siam/Thái Lan). Cũng có nghĩa lịch sử chỉ vương quốc Ayutthaya của Thái Lan. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bóng mặt trời; (xem: xiêm la 暹羅)", "Hạng Tần Suất (Jun Da)": "4599.0", "Tần Suất % (Jun Da)": "99.8748749496", "GavinGrover_Once (Chiết tự trực tiếp)": "進 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴進日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "進", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暹", "Unihan_Traditional (Chữ Phồn thể)": "暹", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "xiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ mặt trời mọc hoặc làm danh từ riêng trong tên gọi nước Xiêm La cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骛', '{"9000": "4600.0", "Chữ Trung Quốc": "骛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 12 | nét | 骛 | vụ | tượng hình | chạy lồng, ngựa phi nhanh; chạy theo mục tiêu | 骛 là giản thể của 騖. Chứa bộ 马 (mã, ngựa) biểu nghĩa; phần trên 敄 hoặc 务 biểu âm. Wiktionary ghi nhận 骛 là dạng giản thể của 騖. Chữ chỉ ngựa phi nhanh loạn xạ; nghĩa phái sinh là chạy theo, ham muốn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vụ\": ngựa (马/mã) phi lồng — vụ là chạy đua, \"好高骛遠\" (háo cao vụ viễn) là ham cao vọng xa. | Gương Hán-Việt | vụ trong \"hạo cao vụ viễn\" (好高骛遠 — tham vọng viển vông), \"phù vụ\" (浮骛 — rong ruổi, không định hướng) | Mở khoá kiến thức | Biết 骛 (vụ) mở khoá thành ngữ \"好高骛遠\" (háo cao vụ viễn — ham xa vọng cao) rất phổ biến trong tiếng Trung hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 骛 là giản thể của 騖 (mã+敄). Nghĩa gốc là ngựa phi nhanh, chạy loạn. Nghĩa phái sinh: \"好高骛远\" (háo gāo wù yuǎn) — tham vọng viển vông, chạy theo điều xa tầm tay. Hanziyuan có dạng tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy lồng; phóng túng", "Hạng Tần Suất (Jun Da)": "4600.0", "Tần Suất % (Jun Da)": "99.8750186159", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骛", "Unihan_Traditional (Chữ Phồn thể)": "騖", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "vụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong văn ngôn để chỉ việc đuổi theo danh lợi hoặc mục tiêu một cách mù quáng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱿', '{"9000": "4601.0", "Chữ Trung Quốc": "鱿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 12 | nét | 鱿 | du | tượng hình | cá mực (dạng giản thể của 魷) | 鱿 là dạng giản thể của 魷 (魚 + 由). Dạng gốc 魷 là chữ hình thanh: 魚 (ngư, biểu nghĩa: cá) + 由 (do, biểu âm). Dạng giản thể hợp nhất thành 鱿, không tách phân tích rõ ràng theo cấu trúc thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": con cá (鱼) bơi tự do như chữ \"du\" — cá mực trôi nhẹ nhàng trong nước. | Gương Hán-Việt | du trong \"鱿鱼\" (cá mực) | Mở khoá kiến thức | Biết 鱿 mở khoá từ 鱿鱼 (mực ống) — món ăn phổ biến trong ẩm thực Trung Hoa và Việt Nam.", "Tự nguyên_Xie": "鱿 là dạng giản thể của 魷, theo Wiktionary: {{Han simp|魷|f=魚|t=鱼}}. Chữ gốc 魷 là hình thanh: 魚 (cá) biểu nghĩa + 由 biểu âm. Chỉ loài cá mực (mực ống). Không có dữ liệu giáp cốt hay kim văn riêng cho dạng giản thể này. Chưa có nguồn học thuật riêng cho dạng 鱿. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá mực", "Hạng Tần Suất (Jun Da)": "4601.0", "Tần Suất % (Jun Da)": "99.8751622822", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 尤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼尤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鱿", "Unihan_Traditional (Chữ Phồn thể)": "魷", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "vưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng trước các từ khác để chỉ các món ăn hoặc sản phẩm chế biến từ mực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苫', '{"9000": "4602.0", "Chữ Trung Quốc": "苫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 苫 | chôm | tượng hình | chiếu rơm, cỏ tranh dùng lợp mái | 苫 là chữ độc thể, cấu trúc thành phần không được phân tích rõ trong nguồn học thuật. Chữ liên quan đến thảo mộc (艸/草) và chỉ loại chiếu rơm hoặc cỏ tranh dùng để lợp mái, che phủ. Chưa có nguồn học thuật về hội ý hay hình thanh cụ thể cho chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chôm\": cỏ tranh \"chôm chỉa\" khắp mái nhà — loại cỏ dùng lợp mái (苫), âm đọc Hán-Việt là chôm. | Gương Hán-Việt | chôm trong \"苫布\" (tấm bạt che phủ) | Mở khoá kiến thức | Biết 苫 mở khoá từ 苫布 (tấm bạt), 茅苫 (tranh lợp mái) trong văn học cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 苫 có hai cách đọc: shàn (動từ: dùng chiếu rơm che phủ) và shān (danh từ: chiếu rơm, tranh lợp mái). Cấu trúc thành phần không được ghi nhận rõ ràng — chữ tạo muộn, không có dữ liệu giáp cốt. Tiểu triện còn lưu hình. Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại cỏ như cỏ tranh", "Hạng Tần Suất (Jun Da)": "4602.0", "Tần Suất % (Jun Da)": "99.8753054316", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苫", "Unihan_Traditional (Chữ Phồn thể)": "苫", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "thiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động dùng tranh tre hoặc bạt để che phủ đồ vật tránh mưa nắng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犷', '{"9000": "4603.0", "Chữ Trung Quốc": "犷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 6 | nét | 犷 | quảng | tượng hình | chất phác, thô kệch, hung hãn | 犷 là chữ độc thể, dạng giản thể của 獷. Cấu trúc thành phần không được ghi nhận rõ ràng trong nguồn học thuật — chưa có nguồn học thuật về hội ý hay hình thanh cụ thể. Cần tham chiếu truyền thống 獷 để hiểu đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quảng\": âm rộng mở như \"quảng\" — con thú hoang dã (犬) thô kệch, hung hãn, không chịu khuôn khổ; chữ tạo muộn, dạng giản thể của 獷. | Gương Hán-Việt | quảng trong \"粗獷\" (thô lỗ, hung hãn) | Mở khoá kiến thức | Biết 犷 mở khoá từ 粗犷 (thô kệch, hung hãn) thường dùng trong văn miêu tả tính cách.", "Tự nguyên_Xie": "Tiểu triện | 犷 là dạng giản thể của 獷. Nguồn Wiktionary không ghi nhận cấu trúc hội ý hay hình thanh cụ thể cho chữ này. Chữ tạo muộn, chưa thấy phân tích rõ ràng trong giáp cốt hay kim văn. Nghĩa gốc chỉ sự hung hãn, thô kệch, chất phác. Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất phác, tục tằn, thô kệch; hung ác, hung hãn", "Hạng Tần Suất (Jun Da)": "4603.0", "Tần Suất % (Jun Da)": "99.8754485811", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 广", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "广", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "犷", "Unihan_Traditional (Chữ Phồn thể)": "獷", "Pinyin_Xie": "guǎng", "Âm Hán Việt_Xie": "quánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp với các từ khác để miêu tả tính cách mạnh mẽ, thô mộc hoặc phong cảnh hoang sơ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獠', '{"9000": "4604.0", "Chữ Trung Quốc": "獠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 15 | nét | 犬 | khuyển | biểu nghĩa | thú, con vật | 尞 | liêu | biểu âm | 獠 = 犬 (Khuyển, biểu nghĩa: thú/con vật) + 尞 (Liêu, biểu âm); chữ hình thanh. Phần 犬 cho biết nghĩa liên quan đến thú, phần 尞 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": con thú (犬) săn đêm dưới đuốc lửa (尞) — hình ảnh đi săn ban đêm, âm đọc theo 尞 (liêu). | Gương Hán-Việt | liêu trong \"獠牙\" (răng nanh) | Mở khoá kiến thức | Biết 獠 mở khoá từ 獠牙 (răng nanh) và các từ cổ chỉ sắc tộc thiểu số trong sử sách Hán văn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 獠 là chữ hình thanh (hình thanh): 犬 (thú) là phần biểu nghĩa, 尞 là phần biểu âm. Chữ ban đầu chỉ hành động săn thú ban đêm dưới ánh đuốc. Có hình tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răng nanh", "Hạng Tần Suất (Jun Da)": "4604.0", "Tần Suất % (Jun Da)": "99.8755917306", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獠", "Unihan_Traditional (Chữ Phồn thể)": "獠", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ trong tổ hợp để chỉ chiếc răng nanh dài và nhọn của thú dữ hoặc quái vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詈', '{"9000": "4605.0", "Chữ Trung Quốc": "詈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 网 | võng | biểu nghĩa | lưới, bẫy | 言 | ngôn | biểu nghĩa | lời nói | 詈 = 网 (Võng, biểu nghĩa: lưới/bẫy) + 言 (Ngôn, biểu nghĩa: lời nói); chữ hội ý. Lưới (网) kết hợp với lời nói (言) tạo thành hình ảnh dùng ngôn từ như tấm lưới để bẫy, mắng nhiếc người khác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lị\": tưởng tượng chiếc lưới (网) được ném bằng lời nói (言) — mắng chửi như giăng bẫy người khác. | Gương Hán-Việt | lị trong \"thóa mạ\" (mắng chửi) | Mở khoá kiến thức | Biết 詈 mở khoá các từ cổ và văn học liên quan đến lời mắng nhiếc, thóa mạ trong Hán văn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 詈 là chữ hội ý (hội ý): 网 (lưới) + 言 (lời nói/lời nói). Hình ảnh chiếc lưới (网) có thể ám chỉ hành động trừng phạt người sau khi bị mắng chửi — vì trong thời cổ, lời chửi rủa bị coi là vi phạm pháp luật. Dạng gốc của chữ là 𧧧. Chưa thấy dạng giáp cốt hay kim văn rõ ràng cho chữ này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắng khéo (không mắng thẳng)", "Hạng Tần Suất (Jun Da)": "4605.0", "Tần Suất % (Jun Da)": "99.8757348801", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "詈", "Unihan_Traditional (Chữ Phồn thể)": "詈", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ trong văn viết cổ để chỉ hành vi dùng lời lẽ thô bạo để lăng mạ người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竦', '{"9000": "4606.0", "Chữ Trung Quốc": "竦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 12 | nét | 竦 | tủng | tượng hình | kính sợ, khép mình, đứng thẳng | 竦 là chữ độc thể, cấu trúc thành phần không được phân tích rõ trong nguồn học thuật. Chữ thường được dùng trong cụm 毛骨竦然 (toàn thân rởn gai ốc). Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tủng\": sợ đến \"tủng\" cả người — như trong \"毛骨竦然\" toàn thân rởn gai ốc. | Gương Hán-Việt | tủng trong \"毛骨竦然\" (toàn thân rởn gai ốc) | Mở khoá kiến thức | Biết 竦 mở khoá thành ngữ 毛骨竦然 (rùng mình sợ hãi) thường gặp trong văn học Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không ghi nhận cấu trúc thành phần (hội ý hay hình thanh) rõ ràng cho 竦. Tiểu triện còn lưu hình. Nghĩa gốc: kính sợ, đứng thẳng nghiêm cẩn, rởn gai ốc. Thường gặp trong cụm 毛骨竦然 (toàn thân rởn gai ốc vì sợ hãi). Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ, động", "Hạng Tần Suất (Jun Da)": "4606.0", "Tần Suất % (Jun Da)": "99.8758780296", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竦", "Unihan_Traditional (Chữ Phồn thể)": "竦", "Pinyin_Xie": "sǒng", "Âm Hán Việt_Xie": "tủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ để biểu thị trạng thái cung kính, sợ hãi hoặc đứng thẳng người nghiêm trang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篙', '{"9000": "4607.0", "Chữ Trung Quốc": "篙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 高 | cao | biểu âm | 篙 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 高 (Cao, biểu âm); chữ hình thanh. Phần 竹 cho biết vật dụng làm từ tre, phần 高 cung cấp âm đọc gần với gāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gàu\": cây sào tre (竹) cao (高) dùng chèo thuyền — âm Hán-Việt là \"gàu\" theo phần 高 (cao). | Gương Hán-Việt | gàu trong \"船篙\" (sào chèo thuyền) | Mở khoá kiến thức | Biết 篙 mở khoá từ 船篙 (sào thuyền), 撑篙 (chống sào) thường gặp trong thơ văn miêu tả cảnh sông nước.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 篙 là chữ hình thanh: 竹 (tre) là phần biểu nghĩa, 高 là phần biểu âm. Chỉ cây sào tre dùng để chèo thuyền. Đại triện và tiểu triện còn lưu hình. Cây sào làm từ tre (竹), âm đọc theo 高 (gāo → gàu trong Hán-Việt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sào chèo thuyền", "Hạng Tần Suất (Jun Da)": "4607.0", "Tần Suất % (Jun Da)": "99.8760206623", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篙", "Unihan_Traditional (Chữ Phồn thể)": "篙", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây sào dài bằng tre hoặc gỗ dùng để đẩy thuyền đi trên sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诨', '{"9000": "4608.0", "Chữ Trung Quốc": "诨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诨 | hổn | tượng hình | lời đùa giỡn (dạng giản thể của 諢) | 诨 là dạng giản thể của 諢 (言 + 軍 → 讠 + 军). Dạng gốc 諢 là chữ hình thanh: 言 (ngôn, biểu nghĩa: lời nói) + 軍 (quân, biểu âm). Dạng giản thể hợp nhất thành 诨, cấu trúc hình thanh vẫn ngầm hiểu. Chưa có nguồn học thuật riêng xác nhận cấu trúc dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hổn\": nói lời \"hổn\" láo bông lơn — 诨 chỉ những câu đùa giỡn táo bạo trên sân khấu hý kịch. | Gương Hán-Việt | hổn trong \"插诨\" (pha trò, chen câu đùa) | Mở khoá kiến thức | Biết 诨 mở khoá từ 插诨 (pha trò) và 诨名 (biệt danh hài hước) trong văn học sân khấu cổ điển.", "Tự nguyên_Xie": "诨 là dạng giản thể của 諢, Wiktionary ghi: {{Han simp|諢|f=言|t=讠|f2=軍|t2=军}}. Chữ gốc 諢 là hình thanh: 言 (lời nói) biểu nghĩa + 軍 (quân) biểu âm. Nghĩa: lời đùa giỡn, pha trò, nói bông lơn. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật riêng cho dạng giản thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói đùa, pha trò", "Hạng Tần Suất (Jun Da)": "4608.0", "Tần Suất % (Jun Da)": "99.876163295", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诨", "Unihan_Traditional (Chữ Phồn thể)": "諢", "Pinyin_Xie": "hùn", "Âm Hán Việt_Xie": "ngộn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ những lời nói đùa cợt, hài hước hoặc biệt danh không chính thức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铰', '{"9000": "4609.0", "Chữ Trung Quốc": "铰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 交 | giao | biểu âm | 铰 = 金 (Kim, biểu nghĩa: kim loại) + 交 (Giao, biểu âm); chữ hình thanh. Phần 金 cho biết vật dụng bằng kim loại (kéo, bản lề), phần 交 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảo\": cái kéo kim loại (金) hai lưỡi giao nhau (交) — âm Hán-Việt là \"giảo\", chữ hình thanh. | Gương Hán-Việt | giảo trong \"铰刀\" (dao khoét, dao cắt) | Mở khoá kiến thức | Biết 铰 mở khoá từ 铰刀 (dao khoét lỗ), 铰链 (bản lề) trong kỹ thuật và đời thường.", "Tự nguyên_Xie": "Theo Wiktionary, 铰 (dạng giản thể của 鉸) là chữ hình thanh: 金 (kim loại) biểu nghĩa + 交 (giao) biểu âm. Chỉ kéo cắt hoặc bản lề kim loại. Không có dữ liệu giáp cốt hay kim văn riêng cho chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kéo", "Hạng Tần Suất (Jun Da)": "4609.0", "Tần Suất % (Jun Da)": "99.8763054109", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铰", "Unihan_Traditional (Chữ Phồn thể)": "鉸", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động dùng kéo để cắt đứt các vật liệu như vải, giấy hoặc kim loại mỏng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馄', '{"9000": "4610.0", "Chữ Trung Quốc": "馄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 11 | nét | 馄 | hồn | tượng hình | bánh vằn thắn (dạng giản thể của 餛) | 馄 là dạng giản thể của 餛. Dạng gốc 餛 gồm 飠 (thực, biểu nghĩa: thức ăn) + 昆 (côn, biểu âm). Dạng giản thể 馄 dùng 饣 thay 飠, cấu trúc hình thanh vẫn còn ngầm hiểu. Chưa có nguồn học thuật riêng xác nhận cấu trúc dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồn\": bánh \"hồn\" = hồn vía trong từng viên vằn thắn — 馄饨 (hún tun) phát âm gần với \"hồn độn\". | Gương Hán-Việt | hồn trong \"馄饨\" (vằn thắn, hoành thánh) | Mở khoá kiến thức | Biết 馄 mở khoá từ 馄饨 (vằn thắn) — món ăn Trung Hoa phổ biến ở Việt Nam.", "Tự nguyên_Xie": "馄 là dạng giản thể của 餛, Wiktionary ghi: chỉ dùng trong 餛飩 (vằn thắn). Chữ gốc 餛 là hình thanh: 飠 (thức ăn) biểu nghĩa + âm biểu theo 昆 (côn). Trong tiếng Việt, món này được gọi là \"vằn thắn\" hoặc \"hoành thánh\". Không có dữ liệu giáp cốt hay kim văn cho chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hồn đồn 餛飩,馄饨)", "Hạng Tần Suất (Jun Da)": "4610.0", "Tần Suất % (Jun Da)": "99.8764475268", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馄", "Unihan_Traditional (Chữ Phồn thể)": "餛", "Pinyin_Xie": "hún", "Âm Hán Việt_Xie": "hồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như luôn kết hợp với chữ đồn để tạo thành tên món ăn hoành thánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜚', '{"9000": "4611.0", "Chữ Trung Quốc": "蜚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜚 | bay | tượng hình | loài gián, sâu ăn lúa; cũng thông với 飛 (bay) | 蜚 là chữ độc thể, cấu trúc thành phần không được phân tích rõ trong nguồn học thuật. Tiểu triện và lục thư thông còn lưu hình. Chữ có nhiều âm đọc: fěi (蜚蠊 - con gián), fēi (thông 飛 - bay). Chưa có nguồn học thuật xác nhận cấu trúc hội ý hay hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bay\": 蜚 đọc là \"bay\" — như 飛 (bay), chữ này từng thông nghĩa với 飛, chỉ con vật bay và bò (gián). | Gương Hán-Việt | bay trong \"蜚語\" (lời đồn bay xa), \"蜚聲\" (tiếng tăm bay xa) | Mở khoá kiến thức | Biết 蜚 mở khoá thành ngữ 流言蜚語 (tin đồn thất thiệt) và 蜚聲中外 (nổi tiếng trong ngoài nước).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 蜚 có nhiều nghĩa và âm đọc: (1) fěi — dùng trong 蜚蠊 (con gián); (2) fēi — dạng khác của 飛 (bay), xuất hiện trong văn cổ như Sử ký. Chữ cũng chỉ một loài thú huyền thoại. Tiểu triện và lục thư thông còn lưu hình. Cấu trúc nội tại không được ghi nhận rõ. Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài sâu ăn lúa", "Hạng Tần Suất (Jun Da)": "4611.0", "Tần Suất % (Jun Da)": "99.8765896427", "GavinGrover_Once (Chiết tự trực tiếp)": "非 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱非虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "非", "Unihan_Simplified (Chữ Giản thể)": "蜚", "Unihan_Traditional (Chữ Phồn thể)": "蜚", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi, phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ trong văn viết để chỉ tin đồn thất thiệt lan truyền nhanh chóng trong dư luận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峒', '{"9000": "4612.0", "Chữ Trung Quốc": "峒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 9 | nét | 峒 | động | tượng hình | hang núi, động núi | 峒 là chữ độc thể, cấu trúc thành phần không được phân tích rõ trong nguồn học thuật. Chữ có hai âm đọc: dòng (hang núi, tên gọi dân tộc thiểu số miền nam Trung Quốc) và tóng (dùng trong địa danh 崆峒). Chưa có nguồn học thuật xác nhận cấu trúc hội ý hay hình thanh cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"động\": 峒 là hang núi (động) — như động Phong Nha, âm Hán-Việt \"động\" gợi ngay hình ảnh hang núi sâu thẳm. | Gương Hán-Việt | động trong \"崆峒\" (núi Không Đồng) và \"黎峒\" (hang của người Lê) | Mở khoá kiến thức | Biết 峒 mở khoá địa danh 崆峒 (núi nổi tiếng ở Cam Túc) và từ cổ chỉ các nhóm dân tộc thiểu số.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi nhận 峒 có hai cách đọc: (1) dòng — trong văn học chỉ hang núi, cũng chỉ các dân tộc thiểu số miền nam Trung Quốc trong thời cổ; (2) tóng — chỉ dùng trong 崆峒, tên núi tại Cam Túc. Lục thư thông còn lưu hình. Cấu trúc nội tại không được ghi nhận rõ. Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hang núi; (xem: không động 崆峒)", "Hạng Tần Suất (Jun Da)": "4612.0", "Tần Suất % (Jun Da)": "99.8767317586", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峒", "Unihan_Traditional (Chữ Phồn thể)": "峒", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "động", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ hang động tự nhiên hoặc địa danh vùng núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滢', '{"9000": "4613.0", "Chữ Trung Quốc": "滢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 水 | thủy | biểu nghĩa | nước | 瑩 | doanh | biểu âm | 滢 = 水 (Thủy, biểu nghĩa: nước) + 瑩 (Doanh, biểu âm); chữ hình thanh. Phần 水 cho biết liên quan đến nước, phần 瑩 cung cấp âm đọc. Dạng giản thể của 瀅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doanh\": nước (水) trong như ngọc doanh (瑩) — 滢 gợi hình ảnh dòng nước trong vắt, lấp lánh. | Gương Hán-Việt | doanh trong \"滢滢\" (trong vắt) | Mở khoá kiến thức | Biết 滢 mở khoá từ 滢滢 (nước trong vắt) và các từ miêu tả vẻ đẹp của nước trong thơ văn cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 滢 (dạng giản thể của 瀅) là chữ hình thanh: 水 (nước) biểu nghĩa + 瑩 biểu âm. Nghĩa: nước trong vắt, trong leo lẻo, sáng bóng. Có thể đọc yíng, yìng, hoặc jiōng. Không có dữ liệu giáp cốt hay kim văn riêng cho chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trong, trong leo lẻo, trong vắt", "Hạng Tần Suất (Jun Da)": "4613.0", "Tần Suất % (Jun Da)": "99.8768738745", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 莹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵莹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滢", "Unihan_Traditional (Chữ Phồn thể)": "瀅", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả vẻ trong sạch của nước hoặc dùng đặt tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琬', '{"9000": "4614.0", "Chữ Trung Quốc": "琬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 玉 | ngọc | biểu nghĩa | ngọc | 宛 | uyển | biểu âm | 琬 = 玉 (Ngọc, biểu nghĩa: ngọc) + 宛 (Uyển, biểu âm); chữ hình thanh. Phần 玉 cho biết liên quan đến ngọc, phần 宛 cung cấp âm đọc gần với wǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": viên ngọc (玉) mềm mại uyển chuyển (宛) — 琬 là ngọc bảng có ánh sáng nhẹ nhàng, âm Hán-Việt là \"uyển\". | Gương Hán-Việt | uyển trong \"琬琰\" (ngọc quý cao quý) | Mở khoá kiến thức | Biết 琬 mở khoá từ 琬琰 (ngọc quý) và 琬圭 (ngọc khuê tròn dùng trong lễ nghi cung đình).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 琬 là chữ hình thanh: 玉 (ngọc) biểu nghĩa + 宛 biểu âm. Chỉ loại ngọc bảng tròn dùng trong lễ nghi, ngọc có ánh sáng mềm mại. Tiểu triện còn lưu hình. Thường ghép với 琰 thành 琬琰 chỉ ngọc quý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viên ngọc đã mài nhẵn", "Hạng Tần Suất (Jun Da)": "4614.0", "Tần Suất % (Jun Da)": "99.8770154737", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琬", "Unihan_Traditional (Chữ Phồn thể)": "琬", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ ngọc quý không có góc cạnh hoặc dùng trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靓', '{"9000": "4615.0", "Chữ Trung Quốc": "靓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 青 | Số nét | 12 | nét | 靓 | tịnh | tượng hình | trang điểm, trang sức; yên tĩnh (dạng giản thể của 靚) | 靓 là dạng giản thể của 靚 (青 + 見). Dạng gốc 靚 gồm 青 (thanh, biểu nghĩa: xanh/màu sắc) + 見 (kiến, biểu nghĩa: nhìn thấy). Có thể hiểu là hội ý: nhìn (見) thấy màu sắc (青) — trang điểm để được nhìn ngắm. Dạng giản thể 靓 đơn giản hóa phần 見 thành 见.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tịnh\": cô gái tịnh trang (靓) — trang điểm yên lặng trước gương, âm Hán-Việt là \"tịnh\". | Gương Hán-Việt | tịnh trong \"靓妆\" (tịnh trang — trang điểm đẹp) | Mở khoá kiến thức | Biết 靓 mở khoá từ 靓妆 (trang điểm đẹp) và 靓丽 (xinh đẹp) thường gặp trong báo chí và văn học hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 靓 là dạng giản thể của 靚, Wiktionary ghi: {{Han simp|靚|f=見|t=见}}. Chữ gốc 靚 gồm 青 + 見. Tiểu triện và lục thư thông còn lưu hình. Có nhiều âm đọc: jìng (trang điểm, yên tĩnh) và liàng (tiếng Quảng Đông: đẹp). Không có dữ liệu giáp cốt hay kim văn riêng. Chưa có nguồn học thuật xác nhận rõ cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "son phấn trang sức", "Hạng Tần Suất (Jun Da)": "4615.0", "Tần Suất % (Jun Da)": "99.8771570728", "GavinGrover_Once (Chiết tự trực tiếp)": "青 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰青见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "青", "Unihan_Simplified (Chữ Giản thể)": "靓", "Unihan_Traditional (Chữ Phồn thể)": "靚", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "tịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ vẻ đẹp thanh lịch hoặc động từ chỉ việc trang điểm son phấn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狻', '{"9000": "4616.0", "Chữ Trung Quốc": "狻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 10 | nét | 狻 | toan | tượng hình | con thú huyền thoại (狻猊) giống sư tử | 狻 là chữ độc thể, cấu trúc thành phần không được phân tích rõ trong nguồn học thuật. Chữ chỉ dùng trong 狻猊 (suāní) — tên một loài thú huyền thoại trong thần thoại Trung Hoa, được miêu tả giống sư tử. Tiểu triện và lục thư thông còn lưu hình. Chưa có nguồn học thuật xác nhận cấu trúc thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toan\": con thú \"toan nghi\" (狻猊) — mãnh thú huyền thoại oai hùng như sư tử, âm Hán-Việt là \"toan\". | Gương Hán-Việt | toan trong \"狻猊\" (toan nghi — loài thú huyền thoại giống sư tử) | Mở khoá kiến thức | Biết 狻 mở khoá từ 狻猊 (toan nghi) — loài thú huyền thoại thường xuất hiện trong nghệ thuật trang trí đình chùa cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 狻 chỉ dùng trong từ ghép 狻猊 (và 狻麑) — tên loài thú huyền thoại. Tiểu triện và lục thư thông còn lưu hình. Nghĩa gốc không được làm rõ ngoài ngữ cảnh từ ghép này. Cấu trúc nội tại không được ghi nhận. Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "do dự", "Hạng Tần Suất (Jun Da)": "4616.0", "Tần Suất % (Jun Da)": "99.8772981551", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狻", "Unihan_Traditional (Chữ Phồn thể)": "狻", "Pinyin_Xie": "suān", "Âm Hán Việt_Xie": "toan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác làm danh từ chỉ loài sư tử hoặc con nghê thần thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璨', '{"9000": "4617.0", "Chữ Trung Quốc": "璨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 17 | nét | 玉 | ngọc | biểu nghĩa | ngọc, đá quý | 粲 | xán | biểu âm | 璨 = 玉 (Ngọc, biểu nghĩa: ngọc/đá quý) + 粲 (Xán, biểu âm); chữ hình thanh. Phần 玉 cho biết liên quan đến ngọc, phần 粲 cung cấp âm đọc gần với càn/càn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xán\": ngọc (玉) lấp lánh xán lạn (粲) — 璨 gợi hình ảnh ánh ngọc rực rỡ, âm Hán-Việt là \"xán\". | Gương Hán-Việt | xán trong \"璀璨\" (rực rỡ, xán lạn) | Mở khoá kiến thức | Biết 璨 mở khoá thành ngữ 璀璨 (rực rỡ lấp lánh) thường dùng trong văn học và báo chí tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 璨 là chữ hình thanh: 玉 (ngọc) biểu nghĩa + 粲 biểu âm. Nghĩa: ánh sáng lấp lánh của ngọc, ngọc đẹp, sáng rực. Tiểu triện còn lưu hình. Thường ghép với 璀 thành 璀璨 (rực rỡ, lấp lánh). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thôi xán 璀璨)", "Hạng Tần Suất (Jun Da)": "4617.0", "Tần Suất % (Jun Da)": "99.8774392375", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 粲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王粲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璨", "Unihan_Traditional (Chữ Phồn thể)": "璨", "Pinyin_Xie": "càn", "Âm Hán Việt_Xie": "xán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ trong từ ghép để miêu tả vẻ sáng ngời của ngọc hay ánh sáng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犟', '{"9000": "4618.0", "Chữ Trung Quốc": "犟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 16 | nét | 強 | càng | biểu âm | 牛 | ngưu | biểu nghĩa | bò, gia súc | 犟 = 強 (Càng, biểu âm) + 牛 (Ngưu, biểu nghĩa: bò/gia súc); chữ hình thanh. Phần 牛 cho biết tính cố chấp như bò, phần 強 cung cấp âm đọc gần với jiàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": con bò (牛) cứng cương (強) không chịu nghe lời — 犟 chỉ sự cố chấp, bướng bỉnh như bò. | Gương Hán-Việt | cương trong \"倔犟\" (cố chấp, bướng bỉnh) | Mở khoá kiến thức | Biết 犟 mở khoá từ 犟劲 (khí thế cứng đầu), 犟嘴 (cãi lại) và 倔犟 (bướng bỉnh) trong tiếng Trung hàng ngày.", "Tự nguyên_Xie": "Theo Wiktionary, 犟 là chữ hình thanh: 強 biểu âm + 牛 (bò) biểu nghĩa. Hình ảnh con bò (牛) ương ngạnh, không chịu đi theo — gợi nghĩa cố chấp, bướng bỉnh. Không có dữ liệu giáp cốt hay kim văn cho chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố chấp; ương ngạnh; sắt đá; cứng đầu; không nghe lời khuyên", "Hạng Tần Suất (Jun Da)": "4618.0", "Tần Suất % (Jun Da)": "99.8775803198", "GavinGrover_Once (Chiết tự trực tiếp)": "强 + 牛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱强牛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "强", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犟", "Unihan_Traditional (Chữ Phồn thể)": "犟", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "cường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ biểu thị tính khí cứng đầu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸬', '{"9000": "4619.0", "Chữ Trung Quốc": "鸬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 盧 | lư | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鸬 = 盧 (Lư, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Phần 鳥 cho biết đây là loài chim, phần 盧 cung cấp âm đọc. Dạng giản thể của 鸕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lô\": con chim (鳥) lô tư (盧) — cò cốc đen đứng trên thuyền của ngư dân, âm Hán-Việt là \"lô\". | Gương Hán-Việt | lô trong \"鸬鹚\" (lô từ — cò cốc) | Mở khoá kiến thức | Biết 鸬 mở khoá từ 鸬鹚 (cò cốc) — loài chim được ngư dân Trung Hoa huấn luyện bắt cá từ hàng nghìn năm nay.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鸬 (dạng giản thể của 鸕) là chữ hình thanh: 盧 biểu âm + 鳥 (chim) biểu nghĩa. Chỉ dùng trong 鸕鶿/鸬鹚 — con cò cốc (chim cormorant), loài chim thường được huấn luyện để đánh cá. Tiểu triện còn lưu hình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lô tư 鸕鷀,鸕鷥,鸬鸬,鸬鸶)", "Hạng Tần Suất (Jun Da)": "4619.0", "Tần Suất % (Jun Da)": "99.8777208854", "GavinGrover_Once (Chiết tự trực tiếp)": "卢 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卢鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸬", "Unihan_Traditional (Chữ Phồn thể)": "鸕", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp tạo thành danh từ chỉ loài chim cốc chuyên lặn bắt cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螨', '{"9000": "4620.0", "Chữ Trung Quốc": "螨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螨 | mạn | tượng hình | ve, bọ ve (mite/tick) | 螨 là dạng giản thể của 蟎, nguồn gốc là chữ quốc tự Nhật Bản (kokuji), không phải chữ Hán truyền thống có phân tích hội ý hay hình thanh theo chuẩn Trung Hoa. Cấu trúc thành phần không được ghi nhận trong nguồn Hán ngữ học thuật. Chưa có nguồn học thuật xác nhận cấu trúc thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": con ve (螨) lan mạn khắp nơi — bọ ve sinh sản nhanh, \"mạn\" gợi sự lan tràn khắp nơi. | Gương Hán-Việt | mạn trong \"尘螨\" (bọ bụi nhà) và \"螨虫\" (bọ ve) | Mở khoá kiến thức | Biết 螨 mở khoá từ 螨虫 (bọ ve), 尘螨 (bọ bụi nhà), 毛囊螨 (bọ nang lông) thường gặp trong y học và đời sống.", "Tự nguyên_Xie": "Wiktionary ghi nhận 蟎 (dạng phồn thể của 螨) là chữ quốc tự Nhật Bản (ja-etym-kokuji), không có lịch sử Hán ngữ cổ điển. Chữ được mượn vào tiếng Trung để chỉ ve/bọ ve (mite/tick). Không có dữ liệu giáp cốt, kim văn hay tiểu triện Trung Hoa cho chữ này. Chưa có nguồn học thuật Hán học xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ve (loài ve hút máu người hay súc vật)", "Hạng Tần Suất (Jun Da)": "4620.0", "Tần Suất % (Jun Da)": "99.8778614509", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "螨", "Unihan_Traditional (Chữ Phồn thể)": "蟎", "Pinyin_Xie": "mǎn", "Âm Hán Việt_Xie": "mãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loài ve hoặc mạt nhỏ ký sinh trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芩', '{"9000": "4621.0", "Chữ Trung Quốc": "芩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芩 | cầm | tượng hình | cỏ cầm, cỏ như lau sậy; cây hoàng cầm (黃芩) | 芩 là chữ độc thể, cấu trúc thành phần không được phân tích rõ trong nguồn học thuật. Đại triện còn lưu hình. Chữ chỉ loại cây cỏ giống lau sậy, phổ biến nhất trong từ 黃芩 (hoàng cầm — cây thuốc Đông y). Chưa có nguồn học thuật xác nhận cấu trúc hội ý hay hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầm\": cỏ cầm (芩) mọc ngoài đồng — như trong Kinh Thi hươu ăn cỏ cầm; âm Hán-Việt là \"cầm\", gợi sự nhẹ nhàng của cỏ hoang. | Gương Hán-Việt | cầm trong \"黃芩\" (hoàng cầm — dược liệu Đông y) | Mở khoá kiến thức | Biết 芩 mở khoá từ 黃芩 (hoàng cầm) — thảo dược Đông y nổi tiếng dùng thanh nhiệt giải độc.", "Tự nguyên_Xie": "Đại triện | Wiktionary ghi nhận 芩 có hai cách đọc: qín (loài cây như lau sậy, dùng trong 黃芩) và yín (dạng khác của 荶). Xuất hiện trong Kinh Thi: \"呦呦鹿鳴，食野之芩\" (hươu kêu, ăn cỏ cầm ngoài đồng). Đại triện còn lưu hình. Cấu trúc thành phần không được ghi nhận rõ. Chưa có nguồn học thuật xác nhận cấu trúc thành phần. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ cầm", "Hạng Tần Suất (Jun Da)": "4621.0", "Tần Suất % (Jun Da)": "99.8780014997", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芩", "Unihan_Traditional (Chữ Phồn thể)": "芩", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại cỏ cổ hoặc vị thuốc đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘹', '{"9000": "4622.0", "Chữ Trung Quốc": "嘹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 嘹 | rêu | tượng hình | âm thanh lanh lảnh, vang xa | 嘹 là chữ tượng hình/chỉ sự kết hợp của bộ 口 (khẩu, miệng) và phần còn lại chỉ âm thanh; nguồn gốc cấu trúc chưa được ghi rõ trong Wiktionary. Chưa có dữ liệu lsCodes; xử lý như chữ tự thân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rêu\": âm thanh lanh lảnh vọng xa như tiếng chim hót trên mái rêu phong — trong trẻo, ngân dài. | Gương Hán-Việt | rêu trong \"rêu rao\" — tiếng rao lanh lảnh, vang vọng | Mở khoá kiến thức | Biết 嘹 mở khoá từ 嘹亮 (liáo liàng — vang vọng, trong trẻo), thường dùng khi mô tả giọng hát hoặc tiếng kèn.", "Tự nguyên_Xie": "Theo Wiktionary, 嘹 dùng để mô tả âm thanh trong trẻo và du dương. Cấu trúc chi tiết không được ghi nhận trong nguồn học thuật hiện có. Chữ này xuất hiện chủ yếu trong từ ghép 嘹亮 (liáo liàng, âm vang vang, trong trẻo). Chưa có nguồn học thuật đầy đủ về giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng inh ỏi, tiếng lanh lảnh", "Hạng Tần Suất (Jun Da)": "4622.0", "Tần Suất % (Jun Da)": "99.8781415485", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘹", "Unihan_Traditional (Chữ Phồn thể)": "嘹", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả âm thanh hoặc tiếng hát cao vút, trong trẻo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锟', '{"9000": "4623.0", "Chữ Trung Quốc": "锟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锟 | côn | tượng hình | thanh kiếm cổ quý hiếm, côn ngô | 锟 có cấu trúc chi tiết không được ghi nhận đầy đủ trong Wiktionary (lsCodes rỗng). Chữ xuất hiện chủ yếu trong từ ghép 锟铻 (côn ngô) chỉ thanh kiếm báu cổ đại. Xử lý như chữ tự thân do thiếu dữ liệu cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": thanh kiếm quý (锟) mang tên côn ngô — vũ khí huyền thoại sắc bén như kim loại (钅) tốt nhất. | Gương Hán-Việt | côn trong \"côn ngô\" (锟铻) — thanh kiếm báu trong truyền thuyết cổ Trung Hoa | Mở khoá kiến thức | Biết 锟 mở khoá từ 锟铻 (kūn wú — côn ngô, kiếm báu huyền thoại) trong văn học cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 锟 (dạng truyền thống 錕) chỉ xuất hiện trong từ ghép 錕鋙/锟铻 (kūn wú — côn ngô), là tên thanh kiếm quý báu trong truyền thuyết cổ đại Trung Hoa. Cấu trúc glyph chi tiết không được ghi nhận; chưa có nguồn học thuật về giáp cốt hay kim văn riêng cho chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: côn ngô 錕鋙,锟铻)", "Hạng Tần Suất (Jun Da)": "4623.0", "Tần Suất % (Jun Da)": "99.8782815972", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锟", "Unihan_Traditional (Chữ Phồn thể)": "錕", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ loại sắt tốt hoặc gươm báu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜇', '{"9000": "4624.0", "Chữ Trung Quốc": "蜇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 折 | chiết | biểu âm | gãy, bẻ | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 蜇 = 折 (Chiết, biểu âm) + 虫 (Trùng, biểu nghĩa: côn trùng/sinh vật); chữ hình thanh. Phần 虫 chỉ đây là sinh vật, phần 折 cho âm gần với zhē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xít\": con vật (虫) gãy/đâm vào (折) như mũi châm — con sứa hay ong đốt bạn một cái xít. | Gương Hán-Việt | xít trong tên dân gian — tiếng kêu khi bị đốt bất ngờ | Mở khoá kiến thức | Biết 蜇 mở khoá từ 蜇伤 (bị đốt/cắn), 海蜇 (con sứa biển), 蜇人 (đốt người).", "Tự nguyên_Xie": "Theo Wiktionary, 蜇 là chữ hình thanh: 虫 (trùng, côn trùng/sinh vật) làm phần biểu nghĩa, 折 làm phần biểu âm. 蜇 chỉ hành động đốt, cắn của côn trùng, sứa hoặc các sinh vật có gai độc; cũng dùng để chỉ con sứa (hải triết). Cấu trúc phản ánh mối liên hệ giữa sinh vật và hành động tấn công. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sứa; đốt, cắn", "Hạng Tần Suất (Jun Da)": "4624.0", "Tần Suất % (Jun Da)": "99.878421646", "GavinGrover_Once (Chiết tự trực tiếp)": "折 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱折虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "折", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜇", "Unihan_Traditional (Chữ Phồn thể)": "蜇", "Pinyin_Xie": "zhē", "Âm Hán Việt_Xie": "triết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ chỉ đối tượng bị đốt hoặc làm danh từ trong từ ghép chỉ con sứa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洹', '{"9000": "4625.0", "Chữ Trung Quốc": "洹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | biểu nghĩa | ba chấm thủy, chỉ nước | 亘 | hằng | biểu âm | kéo dài, liên tục | 洹 = 氵(ba chấm thủy, biểu nghĩa: nước) + 亘 (Hằng, biểu âm); chữ hình thanh. Phần 氵chỉ đây là tên sông, phần 亘 cho âm gần với huán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": dòng sông (氵) uốn quanh mãi (亘 — kéo dài liên tục) như sông Hoàn chảy qua vùng đất Hà Nam. | Gương Hán-Việt | hoàn trong \"hoàn lưu\" — dòng nước chảy vòng quanh liên tục | Mở khoá kiến thức | Biết 洹 mở khoá địa danh 洹水 (sông Hoàn) và thuật ngữ Phật giáo 須陀洹 (Tu-đà-hoàn).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 洹 là chữ hình thanh: 水/氵 (nước) làm phần biểu nghĩa, 亘 làm phần biểu âm. 洹 là tên con sông Hoàn (洹水/洹河) ở tỉnh Hà Nam, Trung Quốc, còn gọi là sông An Dương (安陽河). Trong Phật giáo, 洹 xuất hiện trong từ 須陀洹 (Tu-đà-hoàn, quả vị đầu tiên trong Phật giáo). Kim văn ghi nhận hình dạng sớm của chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên một con sông ở tỉnh Hà Nam của Trung Quốc (còn gọi là sông An Dương 安陽,安阳)", "Hạng Tần Suất (Jun Da)": "4625.0", "Tần Suất % (Jun Da)": "99.878561178", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 亘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵亘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洹", "Unihan_Traditional (Chữ Phồn thể)": "洹", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ tên sông hoặc địa danh cổ ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栉', '{"9000": "4626.0", "Chữ Trung Quốc": "栉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 節 | tiết | biểu âm | đốt, mắt | 栉 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 節 (Tiết, biểu âm); chữ hình thanh. Phần 木 cho biết vật dụng làm bằng gỗ, phần 節 cho âm đọc gần với zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiệt\": cái lược gỗ (木) có nhiều răng đều như những đốt tre (節) — chải tóc từng sợi một. | Gương Hán-Việt | tiệt trong \"tiệt trừ\" — loại bỏ từng cái một, như lược chải sạch tóc rối | Mở khoá kiến thức | Biết 栉 mở khoá từ 栉比 (chí bǐ — dày đặc như răng lược), 栉风沐雨 (dãi dầu mưa nắng, nghĩa bóng gian khổ).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 栉 (dạng truyền thống 櫛) là chữ hình thanh: 木 (mộc, gỗ) làm phần biểu nghĩa chỉ chất liệu, 節 làm phần biểu âm. Cái lược xưa thường được làm từ tre hoặc gỗ, nên bộ 木 phù hợp. Giáp cốt văn và kim văn ghi nhận hình dạng cái lược có răng đều. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lược; chải tóc", "Hạng Tần Suất (Jun Da)": "4626.0", "Tần Suất % (Jun Da)": "99.87870071", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 节", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木节", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "节", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栉", "Unihan_Traditional (Chữ Phồn thể)": "櫛", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cái lược hoặc động từ trong các thành ngữ cổ như tiệt phong mộc vũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俪', '{"9000": "4627.0", "Chữ Trung Quốc": "俪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 人 | nhân | biểu nghĩa | người | 麗 | lệ | biểu âm | đẹp đẽ, rực rỡ | 俪 = 亻(Nhân, biểu nghĩa: người) + 麗 (Lệ, biểu âm); chữ hình thanh. Phần 亻chỉ đây liên quan đến người, phần 麗 cho âm lì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": hai người (亻) đẹp đẽ (麗) sóng đôi — cặp vợ chồng lệ hình thành từ sự kết hợp của tình yêu. | Gương Hán-Việt | lệ trong \"phu lệ\" (夫俪) — vợ chồng, cặp đôi trang nhã | Mở khoá kiến thức | Biết 俪 mở khoá từ 伉俪 (kháng lệ — vợ chồng), 俪影 (bóng dáng đôi lứa) trong văn học.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 俪 (dạng truyền thống 儷) là chữ hình thanh: 人/亻 (nhân, người) làm phần biểu nghĩa, 麗 (lệ, đẹp) làm phần biểu âm. 俪 chỉ cặp đôi, vợ chồng, hai người sóng đôi bên nhau. Tiểu triện và lục thư thông ghi nhận hình dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đôi, vợ chồng", "Hạng Tần Suất (Jun Da)": "4627.0", "Tần Suất % (Jun Da)": "99.8788397252", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 丽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻丽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俪", "Unihan_Traditional (Chữ Phồn thể)": "儷", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ vợ chồng hoặc tính từ trong văn biền ngẫu thể hiện sự sóng đôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钍', '{"9000": "4628.0", "Chữ Trung Quốc": "钍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 金 | kim | biểu nghĩa | kim loại | 土 | thổ | biểu âm | đất | 钍 = 金 (Kim, biểu nghĩa: kim loại) + 土 (Thổ, biểu âm); chữ hình thanh. Phần 金 chỉ đây là nguyên tố kim loại, phần 土 cho âm tǔ — đặt tên phiên âm cho thorium (Th).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thổ\": kim loại (金) khai thác từ đất (土) — thorium lấy tên từ âm thổ, nguyên tố phóng xạ trong lòng đất. | Gương Hán-Việt | thổ trong \"thổ địa\" — đất đai, nơi chứa kim loại quặng | Mở khoá kiến thức | Biết 钍 mở khoá ký hiệu nguyên tố Th (thorium) trong bảng tuần hoàn, dùng trong năng lượng hạt nhân.", "Tự nguyên_Xie": "Theo Wiktionary, 钍 (dạng truyền thống 釷) là chữ hình thanh tạo muộn để phiên âm tên nguyên tố hóa học thorium (Th, số nguyên tử 90): 金 (kim loại) làm phần biểu nghĩa, 土 (thổ, âm tǔ) làm phần biểu âm. Đây là chữ tạo muộn thời cận đại, chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố thori, Th", "Hạng Tần Suất (Jun Da)": "4628.0", "Tần Suất % (Jun Da)": "99.8789787404", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钍", "Unihan_Traditional (Chữ Phồn thể)": "釷", "Pinyin_Xie": "tǔ", "Âm Hán Việt_Xie": "thổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ nguyên tố kim loại phóng xạ Thori trong hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锨', '{"9000": "4629.0", "Chữ Trung Quốc": "锨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锨 | tiêm | tượng hình | cái xẻng, công cụ đào đất bằng kim loại | 锨 thiếu dữ liệu glyph origin từ Wiktionary (anchor null). Chữ có bộ 钅(kim loại) và phần còn lại chỉ công cụ; xử lý như chữ tự thân do thiếu cấu trúc lsCodes. Chưa có nguồn học thuật về cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêm\": cái xẻng kim loại (锨) — lưỡi tiêm nhọn cắm thẳng vào đất, xúc lên từng mảnh. | Gương Hán-Việt | tiêm trong \"tiêm nhọn\" — lưỡi xẻng nhọn đâm vào đất | Mở khoá kiến thức | Biết 锨 mở khoá từ 铁锨 (tiě xiān — cái xẻng sắt), 锨头 (xiān tóu — đầu xẻng) dùng trong nông nghiệp.", "Tự nguyên_Xie": "Nguồn Wiktionary không ghi nhận glyph origin cho 锨. Đây là chữ chỉ cái xẻng, dụng cụ lao động bằng kim loại dùng để đào đất hoặc xúc vật liệu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xẻng", "Hạng Tần Suất (Jun Da)": "4629.0", "Tần Suất % (Jun Da)": "99.8791172388", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 欣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅欣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锨", "Unihan_Traditional (Chữ Phồn thể)": "鍁", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "hân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ công cụ lao động cầm tay dùng để xúc đất cát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑁', '{"9000": "4630.0", "Chữ Trung Quốc": "瑁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 𤣩 | biểu nghĩa | ba chấm ngọc, chỉ ngọc quý | 冒 | mạo | biểu âm | đội lên, mạo hiểm | 瑁 = 𤣩(ba chấm ngọc, biểu nghĩa: ngọc) + 冒 (Mạo, biểu âm); chữ hình thanh. Phần 𤣩chỉ đây là đồ vật bằng ngọc, phần 冒 cho âm mào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\": mảnh ngọc (𤣩) đội lên (冒) như mai đồi mồi — 玳瑁 đẹp như ngọc quý trên biển. | Gương Hán-Việt | mao trong tên đồi mồi 玳瑁 — loài rùa biển có mai ngọc quý | Mở khoá kiến thức | Biết 瑁 mở khoá từ 玳瑁 (đại mội — đồi mồi), dùng trong trang sức và y học cổ truyền.", "Tự nguyên_Xie": "Theo Wiktionary, 瑁 là chữ hình thanh: 玉/𤣩 (ngọc) làm phần biểu nghĩa, 冒 (mạo, âm mào) làm phần biểu âm. 瑁 chỉ mảnh ngọc quý; nổi tiếng nhất trong từ 玳瑁 (đại mội). Chưa tìm thấy dấu vết trong giáp cốt văn; xuất hiện từ thời tiểu triện. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đại mội 玳瑁)", "Hạng Tần Suất (Jun Da)": "4630.0", "Tần Suất % (Jun Da)": "99.8792557372", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 冒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王冒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑁", "Unihan_Traditional (Chữ Phồn thể)": "瑁", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ loại ngọc quý thời cổ hoặc mai rùa đại mồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壹', '{"9000": "4631.0", "Chữ Trung Quốc": "壹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 士 | Số nét | 12 | nét | 壺 | hồ | biểu nghĩa | bình/hũ, dáng tròn đầy | 吉 | cát | biểu âm | tốt lành, cát lợi | 壹 = 壺 (Hồ, biểu nghĩa) + 吉 (Cát, biểu âm); chữ hình thanh theo Thuyết Văn. Phần 壺 (bình tròn kín, đầy ắp) gợi nghĩa chuyên nhất, đầy đủ; phần 吉 cho âm đọc gần với yī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhất\": bình hồ (壺) kín cát (吉) — số một viết phức tạp, chuyên nhất không gian lận được. | Gương Hán-Việt | nhất trong \"nhất trí\" — đồng lòng nhất trí, chuyên nhất một ý | Mở khoá kiến thức | Biết 壹 mở khoá chữ số pháp lý: 壹(1), 贰(2), 叁(3), 肆(4) — dùng trong hợp đồng và tờ tiền.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 壹 là chữ hình thanh theo Thuyết Văn (Shuowen): 壺 (hồ, bình tròn) làm phần biểu nghĩa, 吉 (cát) làm phần biểu âm. 壹 là dạng phức tạp của 一, dùng trong tài chính và văn bản pháp lý để tránh sửa chữa gian lận. Trong văn ngôn, 壹 còn mang nghĩa trung thành, chuyên nhất. Đại triện ghi nhận hình dạng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuyên nhất; hợp làm một; bế tắc; 1, một (như: nhất 一, dùng để viết trong văn tự)", "Hạng Tần Suất (Jun Da)": "4631.0", "Tần Suất % (Jun Da)": "99.8793937188", "GavinGrover_Once (Chiết tự trực tiếp)": "士 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "壹", "Unihan_Traditional (Chữ Phồn thể)": "壹", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "nhất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Tính từ | 形容词 | Dùng làm số từ trong văn bản tài chính để tránh tẩy xóa hoặc làm tính từ chỉ sự đồng nhất. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痿', '{"9000": "4632.0", "Chữ Trung Quốc": "痿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 痿 | oải | tượng hình | bại liệt, mất khả năng vận động | 痿 thiếu lsCodes cấu trúc từ Wiktionary. Chữ có bộ 疒 (bệnh) và thành phần chỉ sự mềm nhão; cấu trúc chi tiết không ghi nhận. Xử lý như chữ tự thân do thiếu dữ liệu. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oải\": cơ thể bị bệnh (疒) trở nên oải mềm, liệt hẳn — không nhấc nổi một ngón tay. | Gương Hán-Việt | oải trong tiếng Việt thông thường — mệt mỏi, uể oải, không còn sức lực | Mở khoá kiến thức | Biết 痿 mở khoá từ 痿痹 (oải tý — liệt và tê), 阳痿 (dương oải — rối loạn cương dương) trong y học cổ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 痿 thuộc lĩnh vực y học cổ truyền Trung Hoa (TCM), chỉ trạng thái mất sinh lực, bại liệt, không cử động được. Âm Trung cổ và thượng cổ được ghi nhận (mc=y, oc=y). Tiểu triện ghi nhận hình dạng. Cấu trúc chi tiết không được Wiktionary làm rõ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị liệt, không cử động được", "Hạng Tần Suất (Jun Da)": "4632.0", "Tần Suất % (Jun Da)": "99.8795317005", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痿", "Unihan_Traditional (Chữ Phồn thể)": "痿", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "nuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả trạng thái cơ thể bị tê liệt hoặc làm danh từ chỉ chứng bệnh liệt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竑', '{"9000": "4633.0", "Chữ Trung Quốc": "竑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 9 | nét | 竑 | hoành | tượng hình | rộng lớn, bao la, đo lường | 竑 thiếu lsCodes cấu trúc từ Wiktionary. Chữ có bộ 立 (đứng) và thành phần phụ, nhưng không có glyph origin chi tiết. Xử lý như chữ tự thân do thiếu dữ liệu cấu trúc. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoành\": rộng ngang (竑) bao la — đứng thẳng (立) nhìn bốn phương thấy không gian mênh mông. | Gương Hán-Việt | hoành trong \"hoành tráng\" — rộng lớn, bao la, vĩ đại | Mở khoá kiến thức | Biết 竑 mở khoá nghĩa rộng lớn/đo lường; chữ hiếm, thường xuất hiện trong tên người Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 竑 có pinyin hóng, âm Trung cổ và thượng cổ được ghi nhận (mc=y, oc=y) nhưng định nghĩa không rõ ràng (rfdef). Chữ mang nghĩa rộng lớn, bao la, dùng trong tên người. Cấu trúc chi tiết không được ghi nhận đầy đủ. Chưa có nguồn học thuật về giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rộng lớn; đo lường", "Hạng Tần Suất (Jun Da)": "4633.0", "Tần Suất % (Jun Da)": "99.8796696821", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 厷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立厷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竑", "Unihan_Traditional (Chữ Phồn thể)": "竑", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả sự rộng lớn hoặc động từ chỉ việc đo đạc trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粕', '{"9000": "4634.0", "Chữ Trung Quốc": "粕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粕 | phách | tượng hình | bã rượu, cặn thóc sau khi chưng cất | 粕 thiếu glyph origin từ Wiktionary (anchor null). Chữ có bộ 米 (gạo) và thành phần phụ, nhưng cấu trúc chi tiết không ghi nhận. Xử lý như chữ tự thân do thiếu lsCodes. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phách\": bã gạo (米) còn lại sau khi ép, như cái phách trống rỗng — chỉ giữ lại tinh hoa, bỏ phần phách dư. | Gương Hán-Việt | phách trong \"tao phách\" (糟粕) — bã rượu, phần vô dụng sau khi chắt lọc tinh hoa | Mở khoá kiến thức | Biết 粕 mở khoá từ 糟粕 (tao phách — bã rượu, nghĩa bóng: phần dở/lỗi thời trong văn hóa).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không ghi nhận glyph origin cho 粕. Chữ chỉ bã rượu, cặn còn lại sau khi chưng cất; thường xuất hiện trong từ ghép 糟粕 (tao phách — bã rượu, chỉ phần vô dụng/phần dở của sự vật). Tiểu triện ghi nhận hình dạng chữ. Chữ tạo muộn, chưa thấy rõ trong giáp cốt văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tao phách 糟粕)", "Hạng Tần Suất (Jun Da)": "4634.0", "Tần Suất % (Jun Da)": "99.879807147", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粕", "Unihan_Traditional (Chữ Phồn thể)": "粕", "Pinyin_Xie": "pò", "Âm Hán Việt_Xie": "phách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ tao thành từ ghép tao phách để chỉ chất cặn bã hoặc thứ vô giá trị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犄', '{"9000": "4635.0", "Chữ Trung Quốc": "犄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 12 | nét | 犄 | ki | tượng hình | sừng bò, góc nhô ra của gia súc | 犄 thiếu lsCodes cấu trúc từ Wiktionary. Chữ có bộ 牛 (bò) và thành phần phụ gợi sừng hoặc góc; cấu trúc chi tiết không ghi nhận. Xử lý như chữ tự thân do thiếu dữ liệu. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ki\": sừng con bò (牛) nhô lên như góc nhọn — hai sừng đối xứng thành thế 犄角, hai cánh quân kẹp địch. | Gương Hán-Việt | ki trong \"cơ giác\" (犄角) — góc, sừng, thế trận hai cánh | Mở khoá kiến thức | Biết 犄 mở khoá từ 犄角 (sừng/góc), 犄角之勢 (thế sừng bò — chiến thuật hai cánh quân).", "Tự nguyên_Xie": "Theo Wiktionary, 犄 có hai âm đọc: jī (cơ) và yī (y). Âm jī xuất hiện trong từ ghép 犄角 (sừng bò, góc) và 犄角之勢 (thế sừng bò — thế trận chia hai cánh). Âm yī chỉ trâu bò bị thiến trong văn cổ. Cấu trúc chi tiết không được Wiktionary ghi nhận đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cơ giác 犄角)", "Hạng Tần Suất (Jun Da)": "4635.0", "Tần Suất % (Jun Da)": "99.8799446118", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犄", "Unihan_Traditional (Chữ Phồn thể)": "犄", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ trong từ ghép chỉ góc hoặc sừng của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘙', '{"9000": "4636.0", "Chữ Trung Quốc": "瘙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 疒 | biểu nghĩa | bộ bệnh, chỉ bệnh tật | 蚤 | tao | biểu âm | con bọ chét | 瘙 = 疒(bộ bệnh, biểu nghĩa) + 蚤 (Tao, biểu âm); chữ hình thanh. Phần 疒 chỉ đây là bệnh, phần 蚤 (con bọ chét) cho âm gần với sào và gợi hình ảnh ngứa ngáy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": bệnh (疒) do bọ chét (蚤) cắn — ngứa tao tao không ngừng, đúng là chứng ghẻ lở. | Gương Hán-Việt | tao trong \"tao bạo\" — khó chịu, dữ dội như cơn ngứa ghẻ | Mở khoá kiến thức | Biết 瘙 mở khoá từ 瘙癢 (tao dưỡng — ngứa ngáy), 瘙痹 (tao tý — ngứa và tê).", "Tự nguyên_Xie": "Theo Wiktionary, 瘙 là chữ hình thanh: 疒 (bộ bệnh) làm phần biểu nghĩa, 蚤 (bọ chét) làm phần biểu âm. 瘙 chỉ bệnh ghẻ lở, ngứa ngáy (scabies). Việc dùng 蚤 (bọ chét) làm phần biểu âm cũng gợi liên tưởng đến ký sinh trùng gây ngứa. Âm Trung cổ và thượng cổ được ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh ghẻ; ghẻ lở", "Hạng Tần Suất (Jun Da)": "4636.0", "Tần Suất % (Jun Da)": "99.8800820766", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 蚤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒蚤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘙", "Unihan_Traditional (Chữ Phồn thể)": "瘙", "Pinyin_Xie": "sào", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ bệnh ngoài da gây ngứa hoặc động từ chỉ cảm giác ngứa ngáy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饯', '{"9000": "4637.0", "Chữ Trung Quốc": "饯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 8 | nét | 饯 | tiễn | tượng hình | tiệc tiễn biệt, rượu tiễn đưa | 饯 là dạng giản thể của 餞: bộ 饣(thực, ăn uống) + 戋 (tiền, biểu âm). Chữ hình thanh: phần ăn uống gợi bữa tiệc, phần biểu âm gần với jiàn. Cấu trúc lsCodes không ghi nhận chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễn\": bữa ăn (饣) tiễn đưa (戋 — nhỏ dần đi xa) — mâm rượu tiễn người thân lên đường. | Gương Hán-Việt | tiễn trong \"tiễn biệt\" — chia tay, đưa tiễn người ra đi | Mở khoá kiến thức | Biết 饯 mở khoá từ 饯行 (tiễn hành — tiệc tiễn đường), 饯别 (tiễn biệt — tiệc chia tay).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 饯 là dạng giản thể của 餞, được rút gọn từ 飠→饣 và 戔→戋. 餞 là chữ gốc chỉ tiệc tiễn biệt, rượu tiễn đưa người đi xa. Tiểu triện ghi nhận hình dạng 餞. Chữ phản ánh phong tục tổ chức bữa ăn/uống rượu để tiễn người lên đường. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiễn đưa; rượu tiễn biệt", "Hạng Tần Suất (Jun Da)": "4637.0", "Tần Suất % (Jun Da)": "99.8802190247", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 戋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣戋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饯", "Unihan_Traditional (Chữ Phồn thể)": "餞", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ để chỉ hành động bày tiệc rượu tiễn người đi xa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抟', '{"9000": "4638.0", "Chữ Trung Quốc": "抟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 抟 | đoàn | tượng hình | vo tròn bằng tay, nắn thành cục | 抟 là dạng giản thể của 摶: bộ 扌(thủ, tay) + 専/专 (chuyên, biểu âm). Chữ hình thanh: phần tay gợi hành động nắn, vo; phần biểu âm cho âm tuán. Cấu trúc lsCodes không ghi nhận chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoàn\": bàn tay (扌) chuyên tâm (专) vo tròn — đoàn kết như nắm cơm vo chặt. | Gương Hán-Việt | đoàn trong \"đoàn kết\" — cùng nhau vo thành một khối vững chắc | Mở khoá kiến thức | Biết 抟 mở khoá từ 抟饭 (vo cơm nắm), 抟风 (vo gió — hình ảnh chim bằng trong Trang Tử).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 抟 là dạng giản thể của 摶, rút gọn từ 専→专. 摶 là chữ chỉ hành động vo tròn, nắn bằng tay — như vo cơm, nắn đất sét. Tiểu triện ghi nhận hình dạng 摶. Chữ cũng xuất hiện trong văn học qua hình ảnh chim bằng (Zhuangzi) vo gió bay lên. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vo tròn bằng tay", "Hạng Tần Suất (Jun Da)": "4638.0", "Tần Suất % (Jun Da)": "99.8803559728", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 专", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌专", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "专", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抟", "Unihan_Traditional (Chữ Phồn thể)": "摶", "Pinyin_Xie": "tuán", "Âm Hán Việt_Xie": "đoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động dùng tay nặn hoặc vo tròn các vật mềm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衲', '{"9000": "4639.0", "Chữ Trung Quốc": "衲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衲 | nẹp | tượng hình | áo vá, áo cà sa của nhà sư | 衲 thiếu lsCodes cấu trúc từ Wiktionary. Chữ có bộ 衤(y, quần áo) và thành phần phụ; cấu trúc chi tiết không ghi nhận đầy đủ. Xử lý như chữ tự thân do thiếu dữ liệu. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nẹp\": áo (衤) nẹp vá từng mảnh — cà sa của nhà sư được may từ trăm mảnh vải cũ, mỗi miếng là một nẹp khiêm nhường. | Gương Hán-Việt | nẹp trong \"áo nẹp\" — vải may viền, chắp vá; áo cà sa vá nhiều mảnh | Mở khoá kiến thức | Biết 衲 mở khoá từ 老衲 (lão nẹp — nhà sư tự xưng), 百衲衣 (áo trăm mảnh vá), 衲僧 (nhà tu).", "Tự nguyên_Xie": "Theo Wiktionary, 衲 liên quan đến quần áo (bộ 衤) và hành động vá, chắp. Âm Trung cổ và thượng cổ được ghi nhận (mc=y, oc=y). Các từ ghép quan trọng: 老衲 (lão nạp — nhà sư tự xưng), 百衲衣 (trăm mảnh vá — áo vá từ nhiều mảnh vải), 衲僧 (nạp tăng — nhà tu). Cấu trúc chi tiết chưa được Wiktionary ghi nhận. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vá, chắp; áo của sư; (tiếng tự xưng mình)", "Hạng Tần Suất (Jun Da)": "4639.0", "Tần Suất % (Jun Da)": "99.8804929208", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衲", "Unihan_Traditional (Chữ Phồn thể)": "衲", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "nạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ áo của nhà sư hoặc làm đại từ tự xưng khiêm tốn của tăng lữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踮', '{"9000": "4640.0", "Chữ Trung Quốc": "踮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踮 | điểm | tượng hình | đứng nhón gót, đứng bằng mũi chân | 踮 thiếu glyph origin từ Wiktionary (anchor null). Chữ có bộ 足 (túc, chân) và thành phần gợi điểm tiếp xúc nhỏ; cấu trúc chi tiết không ghi nhận. Xử lý như chữ tự thân do thiếu dữ liệu. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điểm\": bàn chân (足) chỉ chạm một điểm nhỏ xuống đất — đứng nhón gót như múa ba lê. | Gương Hán-Việt | điểm trong \"điểm chân\" — chạm nhẹ đầu ngón chân, nhón gót | Mở khoá kiến thức | Biết 踮 mở khoá từ 踮脚 (nhón gót), 踮脚尖 (đứng bằng đầu ngón chân) — thường dùng khi mô tả nhìn trộm hoặc múa.", "Tự nguyên_Xie": "Wiktionary không ghi nhận glyph origin cho 踮. Chữ có bộ 足 (chân) làm gợi ý nghĩa liên quan đến chân/đi lại. 踮脚 (diǎn jiǎo) là từ thông dụng chỉ hành động nhón gót chân, đứng bằng đầu ngón. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đứng bằng mũi chân (gót nhón lên), đứng nhón gót", "Hạng Tần Suất (Jun Da)": "4640.0", "Tần Suất % (Jun Da)": "99.8806293521", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 店", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊店", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "店", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踮", "Unihan_Traditional (Chữ Phồn thể)": "踮", "Pinyin_Xie": "diǎn", "Âm Hán Việt_Xie": "điểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bộ phận chân để miêu tả tư thế kiễng gót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龅', '{"9000": "4641.0", "Chữ Trung Quốc": "龅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 13 | nét | 齿 | xỉ | biểu nghĩa | răng | 包 | bao | biểu âm | 龅 là giản thể của 齙, gồm 齿 (xỉ — răng, biểu nghĩa) và 包 (bao, biểu âm). Chữ hình thanh: 包 cho âm bāo, 齿 chỉ nghĩa răng nhô ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bao\": bộ răng (齿) bọc ra ngoài như gói (包) — răng vẩu nhô ra như hàng hoá bị đóng gói sai. | Gương Hán-Việt | bao — \"龅牙\" (bāo yá) là răng vẩu | Mở khoá kiến thức | Biết 龅 mở khoá từ 龅牙 (răng vẩu) trong văn bản y tế nha khoa hoặc mô tả ngoại hình.", "Tự nguyên_Xie": "龅 là giản thể của 齙. Chữ gốc 齙 dùng bộ 齒 (răng) làm thành phần biểu nghĩa, 包 (bao) làm thành phần biểu âm — hình thanh chỉ tình trạng răng nhô ra ngoài. Dạng giản thể thay 齒 bằng 齿. Chưa có nguồn học thuật riêng cho dạng giản thể này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răng vẩu", "Hạng Tần Suất (Jun Da)": "4641.0", "Tần Suất % (Jun Da)": "99.8807657834", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龅", "Unihan_Traditional (Chữ Phồn thể)": "齙", "Pinyin_Xie": "bāo", "Âm Hán Việt_Xie": "bao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả đặc điểm răng bị hô hoặc vẩu ra phía trước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愎', '{"9000": "4642.0", "Chữ Trung Quốc": "愎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | tâm — tâm lý, tính cách | 复 | phục | biểu âm | 愎 gồm bộ 忄 (tâm — tâm lý, biểu nghĩa) và 复 (phục, biểu âm). Chữ hình thanh chỉ tính cách cứng đầu, không chịu nghe lời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bức\": trái tim (忄) cứng như đá, lặp đi lặp lại (复) không thay đổi — tính ương bướng. | Gương Hán-Việt | bức — \"刚愎\" (cương bức) nghĩa là cứng đầu | Mở khoá kiến thức | Biết 愎 mở khoá thành ngữ 刚愎自用 (cương bức tự dụng — tự cao tự đại, không nghe ai).", "Tự nguyên_Xie": "愎 là chữ hình thanh: bộ 忄 (tâm) chỉ đây là tính cách tâm lý, 复 (phục) cho âm gần gũi. Nghĩa gốc là ương ngạnh, cố chấp, không chịu nghe lời khuyên can. Thường gặp trong thành ngữ 刚愎自用 (cương bức tự dụng — cứng đầu tự dùng ý mình). Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ương ngạnh, bướng", "Hạng Tần Suất (Jun Da)": "4642.0", "Tần Suất % (Jun Da)": "99.8809011811", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 复", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄复", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "复", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愎", "Unihan_Traditional (Chữ Phồn thể)": "愎", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "phức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả tính cách ngoan cố, tự làm theo ý mình mà bất chấp khuyên can. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馥', '{"9000": "4643.0", "Chữ Trung Quốc": "馥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 香 | Số nét | 18 | nét | 香 | hương | biểu nghĩa | hương thơm | 复 | phục | biểu âm | 馥 = 香 (hương — hương thơm, biểu nghĩa) + 复 (phục, biểu âm). Chữ hình thanh chỉ mùi hương nồng nàn, đậm đà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phức\": hương thơm (香) lặp lại nhiều lần (复) — hương nồng nàn lan tỏa khắp nơi. | Gương Hán-Việt | phức — \"馥郁\" (phức uất) là hương thơm nồng nàn | Mở khoá kiến thức | Biết 馥 mở khoá 馥郁 (phức uất — hương thơm ngào ngạt) trong văn học cổ điển.", "Tự nguyên_Xie": "馥 là chữ hình thanh từ Wiktionary: 香 (hương) làm thành phần biểu nghĩa chỉ mùi thơm, 复 (phục) làm thành phần biểu âm. Nghĩa gốc là mùi hương đậm đà, nồng nàn. Thường dùng trong thơ văn cổ điển để mô tả hương hoa cỏ hay nước hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hương thơm, thơm phức", "Hạng Tần Suất (Jun Da)": "4643.0", "Tần Suất % (Jun Da)": "99.8810365788", "GavinGrover_Once (Chiết tự trực tiếp)": "香 + 复", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰香复", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "复", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "香", "Unihan_Simplified (Chữ Giản thể)": "馥", "Unihan_Traditional (Chữ Phồn thể)": "馥", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả mùi hương hoa cỏ thơm ngát lan tỏa đậm đà. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梏', '{"9000": "4644.0", "Chữ Trung Quốc": "梏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | gỗ | 告 | cáo | biểu âm | 梏 = 木 (mộc — gỗ, biểu nghĩa) + 告 (cáo, biểu âm). Chữ hình thanh chỉ cái gông gỗ tra vào cổ tay tội nhân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốc\": tấm gỗ (木) tra lên tay như một bản cáo trạng (告) — gông cùm tội nhân. | Gương Hán-Việt | cốc — \"桎梏\" (chất cốc) là xiềng xích, gông cùm | Mở khoá kiến thức | Biết 梏 mở khoá 桎梏 (chất cốc — xiềng xích, sự ràng buộc) trong văn học cổ.", "Tự nguyên_Xie": "梏 là chữ hình thanh theo Wiktionary: 木 (mộc — gỗ) làm thành phần biểu nghĩa vì gông là đồ vật bằng gỗ, 告 (cáo) làm thành phần biểu âm. Nghĩa gốc là xiềng xích, gông cùm bằng gỗ dùng để trói tay tội nhân. Mở rộng chỉ sự ràng buộc, giam cầm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gông bằng gỗ", "Hạng Tần Suất (Jun Da)": "4644.0", "Tần Suất % (Jun Da)": "99.8811714597", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梏", "Unihan_Traditional (Chữ Phồn thể)": "梏", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dụng cụ cùm tay chân thời xưa hoặc động từ chỉ sự kìm kẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讣', '{"9000": "4645.0", "Chữ Trung Quốc": "讣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 4 | nét | 言 | ngôn | biểu nghĩa | lời nói, thông báo | 卜 | bốc | biểu âm | 讣 = 言 (ngôn — lời nói/thông báo, biểu nghĩa) + 卜 (bốc, biểu âm). Chữ hình thanh chỉ thông báo tin buồn về cái chết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phó\": dùng lời (言) bói (卜) điều chẳng lành — thông báo tin người mất. | Gương Hán-Việt | phó — \"讣告\" (phó cáo) là cáo phó, tin buồn | Mở khoá kiến thức | Biết 讣 mở khoá 讣告 (phó cáo — cáo phó) và 讣闻 (phó văn — tin buồn) trong báo chí, văn phòng.", "Tự nguyên_Xie": "讣 là chữ hình thanh theo Wiktionary (Digital Shinjigen 2017): 言 (ngôn — lời nói) làm thành phần biểu nghĩa vì đây là hành động thông báo bằng lời, 卜 (bốc) làm thành phần biểu âm. Nghĩa gốc là thông báo tin chết chóc, phó cáo (báo tin buồn). Thường dùng trong 讣告 (phó cáo — cáo phó). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tin buồn; báo tin có tang", "Hạng Tần Suất (Jun Da)": "4645.0", "Tần Suất % (Jun Da)": "99.8813058238", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讣", "Unihan_Traditional (Chữ Phồn thể)": "訃", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phó", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ báo tin có người qua đời hoặc danh từ chỉ tờ cáo phó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邝', '{"9000": "4646.0", "Chữ Trung Quốc": "邝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 5 | nét | 邝 | khoáng | tượng hình | họ người, chữ tạo muộn | 邝 là chữ tạo muộn dùng làm họ người. Cấu trúc gồm 广 (quảng) và bộ 阝(ấp) nhưng không có phân tích hình thanh hay hội ý chuẩn từ nguồn học thuật. Chưa có nguồn học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoáng\": chữ họ người vùng Quảng Đông — khoáng đãng như đất trời phương Nam. | Gương Hán-Việt | khoáng — dùng làm họ \"邝\" (họ Khoáng) | Mở khoá kiến thức | Biết 邝 giúp nhận ra họ người Hoa kiều gốc Quảng Đông trong danh sách tên.", "Tự nguyên_Xie": "邝 chủ yếu dùng làm họ người (họ Khoáng) tại vùng Hoa Nam và cộng đồng Hoa kiều. Không có phân tích Wiktionary chi tiết về cấu tạo. Chưa có nguồn học thuật xác nhận. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Quảng", "Hạng Tần Suất (Jun Da)": "4646.0", "Tần Suất % (Jun Da)": "99.881440188", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰广阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "邝", "Unihan_Traditional (Chữ Phồn thể)": "鄺", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "quảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艿', '{"9000": "4647.0", "Chữ Trung Quốc": "艿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 5 | nét | 艿 | nãi | tượng hình | rau muống nhỏ, thực vật | 艿 là chữ đơn giản gồm bộ 艹 (thảo — cây cỏ) với nét 乃 (nãi) bên dưới. Cấu trúc hình thanh: 艹 biểu nghĩa (thực vật), 乃 biểu âm. Chưa có nguồn học thuật chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nãi\": cây cỏ (艹) với âm nãi — loại rau nhỏ mọc hoang như tên gọi. | Gương Hán-Việt | nãi — dùng trong tên địa phương hoặc thực vật học | Mở khoá kiến thức | Biết 艿 giúp đọc tên một số loại rau hoặc địa danh có chứa bộ 艹.", "Tự nguyên_Xie": "艿 gồm bộ 艹 (thảo — cây cỏ) làm thành phần biểu nghĩa, 乃 (nãi) làm thành phần biểu âm — hình thanh chỉ loại rau muống nhỏ hoặc rong biển. Cũng dùng trong tên địa danh (茭艿). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vu nãi 芋艿)", "Hạng Tần Suất (Jun Da)": "4647.0", "Tần Suất % (Jun Da)": "99.8815745521", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 乃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹乃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "艿", "Unihan_Traditional (Chữ Phồn thể)": "艿", "Pinyin_Xie": "nǎi", "Âm Hán Việt_Xie": "nãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ cây khoai sọ hoặc các loại cỏ mới mọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趺', '{"9000": "4648.0", "Chữ Trung Quốc": "趺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 足 | túc | biểu nghĩa | chân, bàn chân | 夫 | phu | biểu âm | 趺 = 足 (túc — chân/bàn chân, biểu nghĩa) + 夫 (phu, biểu âm). Chữ hình thanh chỉ mu bàn chân hoặc tư thế ngồi xếp bằng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": bàn chân (足) của người đàn ông (夫) — mu chân, tư thế ngồi thiền xếp bằng. | Gương Hán-Việt | phu — \"趺坐\" (phu tọa) là ngồi xếp bằng kiểu thiền | Mở khoá kiến thức | Biết 趺 mở khoá 趺坐 (phu tọa — ngồi xếp bằng) trong văn bản Phật giáo.", "Tự nguyên_Xie": "趺 là chữ hình thanh theo Wiktionary: 足 (túc — bàn chân) làm thành phần biểu nghĩa, 夫 (phu) làm thành phần biểu âm. Nghĩa gốc là mu bàn chân (đồng nghĩa với 跗). Mở rộng chỉ tư thế ngồi xếp bằng (趺坐) trong thiền định. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mu bàn chân", "Hạng Tần Suất (Jun Da)": "4648.0", "Tần Suất % (Jun Da)": "99.8817089162", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 夫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊夫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趺", "Unihan_Traditional (Chữ Phồn thể)": "趺", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mu bàn chân hoặc động từ trong cụm từ chỉ tư thế ngồi thiền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲟', '{"9000": "4649.0", "Chữ Trung Quốc": "鲟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鱼 | ngư | biểu nghĩa | cá | 寻 | tầm | biểu âm | 鲟 = 鱼 (ngư — cá, biểu nghĩa) + 寻 (tầm, biểu âm). Chữ hình thanh chỉ cá tầm, loài cá lớn nước ngọt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tầm\": con cá (鱼) đáng tìm kiếm (寻) nhất — cá tầm quý hiếm cho trứng caviar. | Gương Hán-Việt | tầm — \"鲟鱼\" (tầm ngư) là cá tầm | Mở khoá kiến thức | Biết 鲟 mở khoá 鲟鱼 (tầm ngư — cá tầm) và 鲟鱼子酱 (tầm ngư tử tương — caviar) trong ẩm thực.", "Tự nguyên_Xie": "鲟 là chữ hình thanh: 鱼 (ngư — cá) làm thành phần biểu nghĩa, 寻 (tầm) làm thành phần biểu âm. Nghĩa là cá tầm (sturgeon), loài cá lớn sống ở sông và biển Bắc Á, nổi tiếng vì trứng caviar. Không có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá tầm (dài hơn một trượng)", "Hạng Tần Suất (Jun Da)": "4649.0", "Tần Suất % (Jun Da)": "99.8818432804", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 寻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼寻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲟", "Unihan_Traditional (Chữ Phồn thể)": "鱘", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loài cá tầm cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剜', '{"9000": "4650.0", "Chữ Trung Quốc": "剜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 10 | nét | 宛 | uyển | biểu âm | 刂 | đao | biểu nghĩa | dao, lưỡi dao | 剜 = 宛 (uyển, biểu âm) + 刂 (đao — dao, biểu nghĩa). Chữ hình thanh: lưỡi dao (刂) cho nghĩa khoét cắt, 宛 cho âm oan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oan\": lưỡi dao (刂) uốn cong (宛) khoét vào — động tác múc, khoét bằng dao. | Gương Hán-Việt | oan — \"剜肉\" (oan nhục) là khoét thịt | Mở khoá kiến thức | Biết 剜 mở khoá thành ngữ 剜肉补疮 (oan nhục bổ sang — giải pháp tệ hơn vấn đề) trong văn học.", "Tự nguyên_Xie": "剜 là chữ hình thanh theo Wiktionary: 宛 (uyển) làm thành phần biểu âm, 刂 (đao — dao) làm thành phần biểu nghĩa. Nghĩa gốc là khoét, đục, múc (dùng dao hay vật nhọn khoét vào). Ví dụ: 剜肉补疮 (oan nhục bổ sang — khoét thịt vá vết thương, chỉ giải pháp tệ hơn vấn đề). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoét", "Hạng Tần Suất (Jun Da)": "4650.0", "Tần Suất % (Jun Da)": "99.8819771277", "GavinGrover_Once (Chiết tự trực tiếp)": "宛 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰宛刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剜", "Unihan_Traditional (Chữ Phồn thể)": "剜", "Pinyin_Xie": "wān", "Âm Hán Việt_Xie": "oan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bộ phận hoặc vật bị khoét bỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绉', '{"9000": "4651.0", "Chữ Trung Quốc": "绉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 芻 | sô | biểu âm | 绉 = 糸 (mịch — sợi tơ/vải, biểu nghĩa) + 芻 (sô, biểu âm). Chữ hình thanh chỉ loại vải lụa có nếp nhăn, vải crêpe.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trứu\": sợi tơ (糸) nhăn nhúm như cỏ khô (芻) — vải lụa có nếp nhăn. | Gương Hán-Việt | trứu — \"绉纱\" (trứu sa) là vải lụa có nếp nhăn | Mở khoá kiến thức | Biết 绉 mở khoá 绉纱 (trứu sa — vải crepe) và 绸缎 trong thuật ngữ dệt may Trung Quốc.", "Tự nguyên_Xie": "绉 là chữ hình thanh theo Wiktionary: 糸 (mịch — sợi tơ, vải) làm thành phần biểu nghĩa, 芻 (sô) làm thành phần biểu âm. Nghĩa gốc là loại vải lụa mỏng có nếp nhăn tự nhiên, tức vải crêpe. Mở rộng chỉ trạng thái nhăn nheo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải nhỏ", "Hạng Tần Suất (Jun Da)": "4651.0", "Tần Suất % (Jun Da)": "99.8821109751", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 刍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟刍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绉", "Unihan_Traditional (Chữ Phồn thể)": "縐", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ loại vải dệt nhăn hoặc làm tính từ mô tả bề mặt nhăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罅', '{"9000": "4652.0", "Chữ Trung Quốc": "罅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 17 | nét | 虖 | hô | biểu âm | 缶 | phẫu | biểu nghĩa | bình, chum đất nung | 罅 = 虖 (hô, biểu âm) + 缶 (phẫu — bình đất nung, biểu nghĩa). Chữ hình thanh: chum vò (缶) bị nứt tạo thành kẽ hở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạ\": cái chum đất (缶) kêu hô hô (虖) vì bị nứt — vết nứt, kẽ hở. | Gương Hán-Việt | hạ — \"罅隙\" (hạ khích) là kẽ hở, vết nứt | Mở khoá kiến thức | Biết 罅 mở khoá 罅隙 (hạ khích — kẽ hở, lỗ hổng) trong văn học và kỹ thuật xây dựng.", "Tự nguyên_Xie": "罅 là chữ hình thanh: 缶 (phẫu — bình/chum đất nung) làm thành phần biểu nghĩa vì bình vò hay bị nứt, 虖 (hô) làm thành phần biểu âm. Nghĩa gốc là vết nứt, kẽ hở trong bình gốm hay tường vách. Mở rộng chỉ mọi kẽ nứt, khe hở. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ nứt, vết nứt", "Hạng Tần Suất (Jun Da)": "4652.0", "Tần Suất % (Jun Da)": "99.8822448224", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 虖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶虖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罅", "Unihan_Traditional (Chữ Phồn thể)": "罅", "Pinyin_Xie": "xià", "Âm Hán Việt_Xie": "há", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ khe hở vật lý hoặc kẽ hở trong lập luận, kế hoạch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笥', '{"9000": "4653.0", "Chữ Trung Quốc": "笥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笥 | tứ | tượng hình | giỏ tre đựng đồ | 笥 gồm bộ 竹 (trúc — tre) và 司 (ti) bên dưới. Cấu trúc hình thanh: 竹 biểu nghĩa (đồ vật bằng tre), 司 biểu âm. Chỉ loại giỏ tre hay hộp tre đựng quần áo, đồ ăn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": tre (竹) quản (司) đồ vật — giỏ tre đựng quần áo, hộp tre. | Gương Hán-Việt | tứ — \"箱笥\" (tương tứ) là hòm rương, hộp đựng đồ | Mở khoá kiến thức | Biết 笥 giúp đọc các mô tả đồ vật gia dụng cổ trong văn học Hán.", "Tự nguyên_Xie": "笥 là chữ hình thanh: bộ 竹 (trúc — tre) làm thành phần biểu nghĩa vì đây là vật dụng đan từ tre, 司 (ti) làm thành phần biểu âm. Nghĩa gốc là giỏ tre, hộp tre dùng đựng quần áo hay đồ ăn. Chưa có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọt vuông, thùng vuông", "Hạng Tần Suất (Jun Da)": "4653.0", "Tần Suất % (Jun Da)": "99.8823786698", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 司", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮司", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "司", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笥", "Unihan_Traditional (Chữ Phồn thể)": "笥", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ đồ dùng bằng tre hình vuông để đựng sách vở hoặc quần áo thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衩', '{"9000": "4654.0", "Chữ Trung Quốc": "衩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 8 | nét | 衣 | y | biểu nghĩa | quần áo | 叉 | xoa | biểu âm | 衩 = 衣 (y — quần áo, biểu nghĩa) + 叉 (xoa, biểu âm). Chữ hình thanh chỉ đường xẻ ở gấu quần áo, tà áo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xoa\": vải (衣) xẻ chữ Y (叉) ở gấu — đường xẻ tà áo dài. | Gương Hán-Việt | xoa — \"开衩\" (khai xoa) là xẻ tà | Mở khoá kiến thức | Biết 衩 mở khoá 开衩 (khai xoa — xẻ tà), 衩口 trong thuật ngữ thời trang.", "Tự nguyên_Xie": "衩 là chữ hình thanh theo Wiktionary: 衣 (y — quần áo) làm thành phần biểu nghĩa, 叉 (xoa) làm thành phần biểu âm. Nghĩa gốc là đường xẻ tà ở hem quần áo (open seam of a garment). Phổ biến trong mô tả thời trang như 开衩 (khai xoa — xẻ tà). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường xẻ; chỗ xẻ tà áo", "Hạng Tần Suất (Jun Da)": "4654.0", "Tần Suất % (Jun Da)": "99.8825120003", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 叉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤叉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衩", "Unihan_Traditional (Chữ Phồn thể)": "衩", "Pinyin_Xie": "chǎ", "Âm Hán Việt_Xie": "sái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ phần xẻ tà ở hai bên sườn áo dài hoặc áo sườn xám. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姣', '{"9000": "4655.0", "Chữ Trung Quốc": "姣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 交 | giao | biểu âm | 姣 = 女 (nữ — phụ nữ, biểu nghĩa) + 交 (giao, biểu âm). Chữ hình thanh chỉ vẻ đẹp duyên dáng của người phụ nữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": người phụ nữ (女) giao tiếp khéo léo (交) — nét đẹp duyên dáng, quyến rũ. | Gương Hán-Việt | giao — \"姣好\" (giao hảo) là xinh đẹp | Mở khoá kiến thức | Biết 姣 mở khoá 姣好 (giao hảo — xinh đẹp), 姣美 (giao mỹ) trong văn học cổ điển.", "Tự nguyên_Xie": "姣 là chữ hình thanh theo Wiktionary: 女 (nữ — phụ nữ) làm thành phần biểu nghĩa, 交 (giao) làm thành phần biểu âm. Nghĩa gốc là xinh đẹp, duyên dáng (chỉ phụ nữ đẹp). Cũng dùng trong 姣好 (giao hảo — xinh đẹp) và 姣美 (giao mỹ — mỹ lệ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẹp", "Hạng Tần Suất (Jun Da)": "4655.0", "Tần Suất % (Jun Da)": "99.8826448141", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姣", "Unihan_Traditional (Chữ Phồn thể)": "姣", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ phụ nữ hoặc làm vị ngữ trong câu miêu tả dung mạo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Vẻ bề ngoài", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斫', '{"9000": "4656.0", "Chữ Trung Quốc": "斫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 斤 | Số nét | 9 | nét | 斫 | chước | tượng hình | chặt bằng rìu | 斫 gồm bộ 斤 (cân — rìu, dao) và 石 (thạch — đá) bên trái. Cấu trúc hình thanh hoặc hội ý: rìu (斤) chặt vào đá (石) — động tác chặt mạnh. Chưa có phân tích Wiktionary chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chước\": lưỡi rìu (斤) chặt vào đá (石) — tiếng chước mạnh khi bổ củi. | Gương Hán-Việt | chước — \"斫琴\" (chước cầm) là đẽo đàn quyền trong câu chuyện Bá Nha | Mở khoá kiến thức | Biết 斫 mở khoá điển tích 斫琴 (chước cầm — Bá Nha đập đàn) và 斫丧 (chước táng — tàn phá) trong văn học.", "Tự nguyên_Xie": "斫 gồm 斤 (cân — rìu, dao lớn) làm thành phần biểu nghĩa và 石 (thạch) có thể làm biểu âm hoặc hội ý. Nghĩa gốc là chặt, bổ bằng dao rìu (đặc biệt là chặt gỗ hay đá). Dùng nhiều trong thơ văn cổ như 斫琴 (chước cầm — đẽo đàn), 斫木 (chặt cây). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chặt, đẵn (cây)", "Hạng Tần Suất (Jun Da)": "4656.0", "Tần Suất % (Jun Da)": "99.8827776279", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "斫", "Unihan_Traditional (Chữ Phồn thể)": "斫", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "chước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động chặt cây hoặc đẽo gỗ bằng dụng cụ sắc bén. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹗', '{"9000": "4657.0", "Chữ Trung Quốc": "鹗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 咢 | ngạc | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鹗 = 咢 (ngạc, biểu âm) + 鳥 (điểu — chim, biểu nghĩa). Chữ hình thanh chỉ chim ưng bắt cá (osprey).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": con chim (鳥) kêu ngạc ngạc (咢) — chim ưng bắt cá hét to khi săn mồi. | Gương Hán-Việt | ngạc — \"鱼鹗\" (ngư ngạc) là chim ưng bắt cá | Mở khoá kiến thức | Biết 鹗 mở khoá hình ảnh con chim trong thơ Kinh Thi và văn học cổ điển Trung Quốc.", "Tự nguyên_Xie": "鹗 là chữ hình thanh theo Wiktionary: 鳥 (điểu — chim) làm thành phần biểu nghĩa, 咢 (ngạc) làm thành phần biểu âm. Nghĩa là chim diều hâu bắt cá (osprey, Pandion haliaetus). Đây là loài chim xuất hiện trong Kinh Thi với hình ảnh biểu tượng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim ngạc (mỏ ngắn, sống ở mặt nước, bắt tôm cá)", "Hạng Tần Suất (Jun Da)": "4657.0", "Tần Suất % (Jun Da)": "99.8829104417", "GavinGrover_Once (Chiết tự trực tiếp)": "咢 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咢鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹗", "Unihan_Traditional (Chữ Phồn thể)": "鶚", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài chim săn mồi sống gần nước trong văn chương cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爻', '{"9000": "4658.0", "Chữ Trung Quốc": "爻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 爻 | Số nét | 4 | nét | 乂 | nghệ | hai nét chéo | 乂 | nghệ | hai nét chéo | 爻 = 乂 + 乂, hai chữ 乂 (nghệ) xếp chồng nhau — hai cặp nét chéo. Đây là chữ hội ý tượng trưng cho hai dãy que bói (yarrow stalks) hoặc hai đôi que tre dùng trong bói kinh Dịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": hai chữ X xếp chồng (乂乂) — hình ảnh hai vạch bói trong Kinh Dịch, mỗi vạch gọi là một hào. | Gương Hán-Việt | hào — \"爻辞\" (hào từ) là lời giải thích từng vạch quẻ trong Kinh Dịch | Mở khoá kiến thức | Biết 爻 mở khoá 六爻 (lục hào — sáu vạch quẻ), 爻辞 (hào từ), 变爻 (biến hào) trong Kinh Dịch.", "Tự nguyên_Xie": "爻 là chữ hội ý theo Wiktionary: gồm hai 乂 (nghệ) xếp chồng, mỗi 乂 là hai nét chéo giao nhau. Có hai cách giải thích: (1) hai cặp que bói cỏ thi dùng trong lễ bói quẻ (xem thêm 學 và 覺 có liên quan); (2) hai cặp tre xếp lại. Nghĩa là vạch quẻ trong Kinh Dịch — mỗi quẻ gồm sáu hào (六爻). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "544.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hựu (40)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai chữ Hựu (số 40 - bàn tay). Hình ảnh đôi bàn tay phía trên đang uốn nắn, hướng dẫn đôi bàn tay phía dưới làm việc. Giải thích sự chuyển ý: Từ hành động cầm tay chỉ việc, Hào mang ý nghĩa là sự mô phỏng, bắt chước theo mẫu mực.", "Nghĩa Tiếng Việt_Xie": "hào (trong king Dịch, một quái có 6 hào)", "Hạng Tần Suất (Jun Da)": "4658.0", "Tần Suất % (Jun Da)": "99.8831755525", "GavinGrover_Once (Chiết tự trực tiếp)": "乂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴乂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "爻", "Unihan_Traditional (Chữ Phồn thể)": "爻", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các vạch âm dương cấu thành nên các quẻ trong Kinh Dịch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猕', '{"9000": "4659.0", "Chữ Trung Quốc": "猕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 猕 | di | tượng hình | khỉ, vượn | 猕 gồm bộ 犭(khuyển — thú vật) và 弥 (di) bên phải. Cấu trúc hình thanh: 犭biểu nghĩa (thú vật), 弥 biểu âm. Chỉ loài khỉ Macaca (khỉ đuôi dài).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": thú vật (犭) lang di di — con khỉ Macaca nhảy nhót linh hoạt. | Gương Hán-Việt | di — \"猕猴\" (di hầu) là khỉ Macaca; \"猕猴桃\" (di hầu đào) là quả kiwi | Mở khoá kiến thức | Biết 猕 mở khoá 猕猴 (di hầu — khỉ) và 猕猴桃 (di hầu đào — kiwi) trong văn học và ẩm thực.", "Tự nguyên_Xie": "猕 là chữ hình thanh: bộ 犭(khuyển — thú vật bốn chân) làm thành phần biểu nghĩa, 弥 (di) làm thành phần biểu âm. Nghĩa là khỉ thuộc giống Macaca. Thường dùng trong 猕猴 (di hầu — khỉ đuôi dài) và 猕猴桃 (di hầu đào — kiwi, quả dưa leo leo mà khỉ ưa ăn). Chưa có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khỉ Ma-các", "Hạng Tần Suất (Jun Da)": "4659.0", "Tần Suất % (Jun Da)": "99.8833078495", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 弥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭弥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猕", "Unihan_Traditional (Chữ Phồn thể)": "獼", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong các từ ghép chỉ loài khỉ hoặc quả kiwi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晗', '{"9000": "4660.0", "Chữ Trung Quốc": "晗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 11 | nét | 日 | nhật | biểu nghĩa | mặt trời, ánh sáng | 含 | hàm | biểu âm | 晗 = 日 (nhật — mặt trời, biểu nghĩa) + 含 (hàm, biểu âm). Chữ hình thanh chỉ khoảng thời gian trước bình minh, khi mặt trời còn chưa ló dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": mặt trời (日) còn ngậm (含) trong bóng đêm — khoảnh khắc tờ mờ trước bình minh. | Gương Hán-Việt | hàm — \"晗光\" là ánh sáng tờ mờ sáng sớm | Mở khoá kiến thức | Biết 晗 giúp đọc tên riêng người Trung Quốc và nhận ra ngữ nghĩa bình minh trong thơ văn.", "Tự nguyên_Xie": "晗 là chữ hình thanh: 日 (nhật — mặt trời) làm thành phần biểu nghĩa vì liên quan đến ánh sáng bình minh, 含 (hàm) làm thành phần biểu âm. Nghĩa gốc là lúc tờ mờ sáng, trước khi mặt trời mọc (pre-dawn). Thường dùng trong tên riêng tại Trung Quốc hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trời hửng sáng, trời hé sáng", "Hạng Tần Suất (Jun Da)": "4660.0", "Tần Suất % (Jun Da)": "99.8834401464", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 含", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日含", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "含", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晗", "Unihan_Traditional (Chữ Phồn thể)": "晗", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ chỉ trạng thái trời sáng hoặc dùng đặt tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铩', '{"9000": "4661.0", "Chữ Trung Quốc": "铩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铩 | sát | tượng hình | giáo dài, bị thương | 铩 gồm bộ 钅(kim — kim loại) và 杀 (sát) bên phải. Cấu trúc hình thanh: 钅biểu nghĩa (vũ khí kim loại), 杀 biểu âm. Chỉ cây giáo dài hoặc ý nghĩa bị thương tổn, tổn hại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sát\": kim loại (钅) để sát thương (杀) — cây giáo dài; cũng chỉ bị gãy cánh, tổn thương. | Gương Hán-Việt | sát — \"铩羽\" (sát vũ) là bị gãy cánh, bị thất bại | Mở khoá kiến thức | Biết 铩 mở khoá thành ngữ 铩羽而归 (sát vũ nhi quy — cánh gãy trở về, thất bại quay về).", "Tự nguyên_Xie": "铩 là chữ hình thanh: bộ 钅(kim — kim loại) làm thành phần biểu nghĩa vì là vũ khí kim loại, 杀 (sát) làm thành phần biểu âm. Nghĩa gốc là cây giáo dài (lance/spear). Cũng dùng theo nghĩa bóng: bị tổn thương, bị đánh gãy cánh (铩羽 — sát vũ). Chưa có nguồn Wiktionary chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại giáo dài; tàn phá, rách nát, tổn thương", "Hạng Tần Suất (Jun Da)": "4661.0", "Tần Suất % (Jun Da)": "99.8835724434", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 杀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅杀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铩", "Unihan_Traditional (Chữ Phồn thể)": "鎩", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ vũ khí cổ hoặc làm động từ trong từ ghép chỉ sự tổn thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窕', '{"9000": "4662.0", "Chữ Trung Quốc": "窕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 11 | nét | 穴 | huyệt | biểu nghĩa | hang, hốc | 兆 | triệu | biểu âm | 窕 = 穴 (huyệt — hang hốc, biểu nghĩa) + 兆 (triệu, biểu âm). Chữ hình thanh chỉ sự sâu xa, thăm thẳm; cũng chỉ vẻ thướt tha, mềm mại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điều\": hang sâu (穴) tỏa ra muôn triệu (兆) vẻ đẹp — vẻ thướt tha, duyên dáng như hang hốc sâu thẳm. | Gương Hán-Việt | điều — \"窈窕\" (yểu điều) là dáng người thướt tha, mềm mại | Mở khoá kiến thức | Biết 窕 mở khoá 窈窕淑女 (yểu điều thục nữ — cô gái thướt tha đức hạnh) trong Kinh Thi.", "Tự nguyên_Xie": "窕 là chữ hình thanh theo Wiktionary: 穴 (huyệt — hang, hốc sâu) làm thành phần biểu nghĩa, 兆 (triệu) làm thành phần biểu âm. Nghĩa gốc là sâu xa, thăm thẳm. Mở rộng chỉ vẻ thướt tha, mềm mại duyên dáng — thường thấy trong 窈窕 (yểu điều — dáng người thướt tha). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ; tốt đẹp", "Hạng Tần Suất (Jun Da)": "4662.0", "Tần Suất % (Jun Da)": "99.8837047404", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窕", "Unihan_Traditional (Chữ Phồn thể)": "窕", "Pinyin_Xie": "tiǎo", "Âm Hán Việt_Xie": "điệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường đi liền với yểu để tả vẻ đẹp kín đáo của phụ nữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仨', '{"9000": "4663.0", "Chữ Trung Quốc": "仨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | 仨 | tam | tượng hình | ba (khẩu ngữ) | 仨 gồm bộ 亻(nhân — người) và 三 (tam — ba). Hội ý đơn giản: ba người — số đếm khẩu ngữ. Chữ tạo muộn, dùng trong tiếng Bắc Kinh để chỉ số ba không chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tam\": người (亻) và số ba (三) kết hợp — ba người, đơn giản như vậy trong khẩu ngữ Bắc Kinh. | Gương Hán-Việt | tam — 仨 là cách nói ba (3) trong khẩu ngữ Bắc Kinh | Mở khoá kiến thức | Biết 仨 giúp hiểu khẩu ngữ Bắc Kinh và phương ngữ Quan Thoại miền Bắc trong hội thoại tự nhiên.", "Tự nguyên_Xie": "仨 là chữ tạo muộn trong tiếng Bắc Kinh (giọng Quan Thoại miền Bắc), gồm 亻(nhân — người) và 三 (tam — ba). Đây là từ khẩu ngữ chỉ số ba, tương đương 三个 (ba cái/người). Không có nguồn Wiktionary hay hình học cổ. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ba, 3", "Hạng Tần Suất (Jun Da)": "4663.0", "Tần Suất % (Jun Da)": "99.8838365206", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 三", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻三", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "三", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仨", "Unihan_Traditional (Chữ Phồn thể)": "仨", "Pinyin_Xie": "sā", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Chữ này làm số từ biểu thị số lượng là ba và không cần lượng từ đi kèm. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搡', '{"9000": "4664.0", "Chữ Trung Quốc": "搡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搡 | tảng | tượng hình | đẩy mạnh | 搡 gồm bộ 扌(thủ — tay) và 嗓 bị rút gọn hay 桑 (tang). Cấu trúc hình thanh: 扌biểu nghĩa (hành động tay), phần còn lại biểu âm. Chỉ động tác đẩy mạnh bằng hai tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảng\": tay (扌) đẩy tảng đá — động tác đẩy mạnh, xô ngã người khác. | Gương Hán-Việt | tảng — \"推搡\" (thôi tảng) là xô đẩy qua lại | Mở khoá kiến thức | Biết 搡 mở khoá 推搡 (thôi tảng — xô đẩy, chen lấn) trong miêu tả đám đông.", "Tự nguyên_Xie": "搡 là chữ hình thanh: bộ 扌(thủ — tay) làm thành phần biểu nghĩa, phần biểu âm bên phải (liên quan đến âm sǎng). Nghĩa là đẩy mạnh bằng tay (push forcefully), đặc biệt là đẩy người khác. Chủ yếu dùng trong phương ngữ và khẩu ngữ. Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẩy mạnh ra; ném mạnh đi", "Hạng Tần Suất (Jun Da)": "4664.0", "Tần Suất % (Jun Da)": "99.8839683009", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 桑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌桑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搡", "Unihan_Traditional (Chữ Phồn thể)": "搡", "Pinyin_Xie": "sǎng", "Âm Hán Việt_Xie": "táng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dùng tay đẩy mạnh người hoặc vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崴', '{"9000": "4665.0", "Chữ Trung Quốc": "崴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 崴 | ổi | tượng hình | núi không bằng phẳng; bong gân | 崴 gồm bộ 山 (sơn — núi) và 威 (uy) bên trên. Cấu trúc hình thanh: 山 biểu nghĩa (địa hình, núi non), 威 biểu âm. Chỉ địa hình gập ghềnh hoặc bong gân mắt cá chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ổi\": bước trên núi (山) uy (威) nghi gập ghềnh — hay bị lật cổ chân, bong gân. | Gương Hán-Việt | ổi — \"崴脚\" (ổi cước) là bong gân cổ chân | Mở khoá kiến thức | Biết 崴 mở khoá 崴脚 (ổi cước — trẹo cổ chân) trong khẩu ngữ hàng ngày.", "Tự nguyên_Xie": "崴 là chữ hình thanh: bộ 山 (sơn — núi) làm thành phần biểu nghĩa, 威 (uy) làm thành phần biểu âm. Nghĩa 1 (wēi): địa hình gập ghềnh, không bằng phẳng — dùng trong tên địa danh như 崴嵬 (ổi ngôi — núi gập ghềnh). Nghĩa 2 (wǎi): bong gân mắt cá chân — khẩu ngữ phổ biến. Chưa có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao ngất", "Hạng Tần Suất (Jun Da)": "4665.0", "Tần Suất % (Jun Da)": "99.8841000811", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 威", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山威", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "威", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崴", "Unihan_Traditional (Chữ Phồn thể)": "崴", "Pinyin_Xie": "wǎi", "Âm Hán Việt_Xie": "uy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ việc khớp xương bị lệch hoặc làm tính từ tả địa hình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酢', '{"9000": "4666.0", "Chữ Trung Quốc": "酢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 12 | nét | 酉 | dậu | biểu nghĩa | bình rượu, đồ đựng rượu | 乍 | sạ | biểu âm | 酢 = 酉 (dậu — bình rượu, biểu nghĩa) + 乍 (sạ, biểu âm). Chữ hình thanh chỉ giấm (vinegar) hoặc động tác chúc rượu đáp lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạc\": bình rượu (酉) đột nhiên (乍) hóa chua — rượu lên men thành giấm, vị chua. | Gương Hán-Việt | tạc — \"酢浆草\" (tạc tương thảo) là cỏ me đất | Mở khoá kiến thức | Biết 酢 giúp đọc tên thực vật 酢浆草 (cỏ me đất) và hiểu 醋 (giấm) trong ẩm thực.", "Tự nguyên_Xie": "酢 là chữ hình thanh theo Wiktionary (Digital Shinjigen 2017): 酉 (dậu — bình/đồ đựng rượu) làm thành phần biểu nghĩa, 乍 (sạ) làm thành phần biểu âm. Nghĩa gốc là giấm (vinegar) — rượu lên men thành chua. Cũng có nghĩa là rót rượu đáp lễ (tân khách đáp lễ chủ nhà). Dạng phồn thể là 醋. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khách rót rượu cho chủ", "Hạng Tần Suất (Jun Da)": "4666.0", "Tần Suất % (Jun Da)": "99.8842318613", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酢", "Unihan_Traditional (Chữ Phồn thể)": "酢", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "tạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ nghi thức mời rượu hoặc làm danh từ chỉ chất giấm chua. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檄', '{"9000": "4667.0", "Chữ Trung Quốc": "檄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 敫 | giác | biểu âm | 檄 = 木 (mộc — gỗ/cây, biểu nghĩa) + 敫 (giác, biểu âm). Chữ hình thanh: gỗ (木) liên quan đến thẻ tre/gỗ viết thư; 敫 cho âm xí/hịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hịch\": tấm thẻ gỗ (木) viết lời giục giã (敫) — tờ hịch kêu gọi xuất trận. | Gương Hán-Việt | hịch — \"檄文\" (hịch văn) là bài hịch, tuyên cáo chiến tranh | Mở khoá kiến thức | Biết 檄 mở khoá 檄文 (hịch văn), 传檄 (truyền hịch — truyền hịch thư), 飞檄 (phi hịch — hịch khẩn) trong lịch sử và văn học.", "Tự nguyên_Xie": "檄 là chữ hình thanh theo Wiktionary: 木 (mộc — gỗ) làm thành phần biểu nghĩa vì thư lệnh xưa được viết trên thẻ gỗ tre, 敫 (giác) làm thành phần biểu âm. Nghĩa gốc là hịch — văn thư kêu gọi chiến đấu, tuyên bố tội trạng hoặc triệu tập quân binh. Ví dụ nổi tiếng: 讨武氏檄 (Hịch thảo phạt Võ Tắc Thiên) của Lạc Tân Vương. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiếu hịch, lời kêu gọi dân chúng", "Hạng Tần Suất (Jun Da)": "4667.0", "Tần Suất % (Jun Da)": "99.8843631247", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 敫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木敫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檄", "Unihan_Traditional (Chữ Phồn thể)": "檄", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "hịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ thể văn thư cổ động hoặc làm động từ phát lệnh kêu gọi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佞', '{"9000": "4668.0", "Chữ Trung Quốc": "佞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 仁 | nhân | biểu âm | 女 | nữ | biểu nghĩa | phụ nữ | 佞 = 仁 (nhân, biểu âm) + 女 (nữ — phụ nữ, biểu nghĩa). Chữ hình thanh: 女 cho nghĩa liên quan đến duyên dáng, khéo miệng; 仁 cho âm nịnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nịnh\": miệng lưỡi phụ nữ (女) khéo léo nhân từ (仁) — nghệ thuật nịnh hót, nói ngọt để lấy lòng. | Gương Hán-Việt | nịnh — \"佞臣\" (nịnh thần) là gian thần xu nịnh | Mở khoá kiến thức | Biết 佞 mở khoá 佞臣 (nịnh thần), 谄佞 (siểm nịnh — nịnh hót), 奸佞 (gian nịnh — gian thần) trong sử học.", "Tự nguyên_Xie": "佞 là chữ hình thanh theo Wiktionary: 仁 (nhân) làm thành phần biểu âm, 女 (nữ) làm thành phần biểu nghĩa. Nghĩa gốc là khéo ăn nói (eloquent). Về sau mang nghĩa tiêu cực: nịnh hót, xu nịnh, dùng lời lẽ ngọt ngào để lấy lòng cấp trên. Ví dụ: 佞臣 (nịnh thần — tên gian thần xu nịnh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "67.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Nữ (60)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Nhân (lòng thương - số 42) và chữ Nữ (số 60) . Phụ nữ có lòng nhân, lời nói nhẹ nhàng khéo léo sinh ra nịnh.", "Nghĩa Tiếng Việt_Xie": "tài giỏi; nịnh nọt", "Hạng Tần Suất (Jun Da)": "4668.0", "Tần Suất % (Jun Da)": "99.8844943881", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 𡚬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻𡚬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡚬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佞", "Unihan_Traditional (Chữ Phồn thể)": "佞", "Pinyin_Xie": "nìng", "Âm Hán Việt_Xie": "nịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Chữ này làm tính từ chỉ tính cách gian nịnh hoặc làm động từ chỉ hành vi nịnh hót. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孑', '{"9000": "4669.0", "Chữ Trung Quốc": "孑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 3 | nét | 孑 | kiệt | tượng hình | cô đơn, đơn độc | 孑 là chữ đơn giản, biến thể của 子 (tử — đứa trẻ) thiếu nét ngang. Hình tượng đứa trẻ mất một tay — gợi ý sự đơn độc, thiếu hụt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiệt\": đứa trẻ (子) mất một tay — một mình, đơn độc, chỉ còn lại một. | Gương Hán-Việt | kiệt — \"孑立\" (kiệt lập) là đứng một mình độc lập | Mở khoá kiến thức | Biết 孑 mở khoá 孑立 (kiệt lập — đứng đơn độc), 孑孑 (kiệt kiệt — nổi bật) và 孑然 (kiệt nhiên — hoàn toàn một mình).", "Tự nguyên_Xie": "孑 là biến thể của 子 (tử) với một nét bị lược bỏ. Hình tượng đứa trẻ cụt tay (thiếu nét ngang) — tượng trưng cho sự đơn độc, lẻ loi. Nghĩa là một mình, đơn độc; còn sót lại. Dùng trong 孑立 (kiệt lập — đứng một mình), 孑孑 (kiệt kiệt — nổi bật). Chưa có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đơn chiếc, lẻ loi, trơ chọi; vật thẳng mà ngắn", "Hạng Tần Suất (Jun Da)": "4669.0", "Tần Suất % (Jun Da)": "99.8846256515", "GavinGrover_Once (Chiết tự trực tiếp)": "子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: msp", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "孑", "Unihan_Traditional (Chữ Phồn thể)": "孑", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự đơn độc hoặc làm danh từ chỉ con lăng quăng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璀', '{"9000": "4670.0", "Chữ Trung Quốc": "璀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 璀 | thôi | tượng hình | rực rỡ, lấp lánh (của đá quý) | 璀 gồm bộ 王/玉 (ngọc — ngọc, đá quý) và 崔 (thôi) bên phải. Cấu trúc hình thanh: 玉 biểu nghĩa (đá quý), 崔 biểu âm. Chỉ ánh sáng lấp lánh của đá quý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": ngọc (玉) chói sáng rực thôi thôi (崔) — ánh lấp lánh của đá quý. | Gương Hán-Việt | thôi — \"璀璨\" (thôi xán) là rực rỡ, lấp lánh | Mở khoá kiến thức | Biết 璀 mở khoá 璀璨 (thôi xán — rực rỡ lấp lánh) trong văn học và miêu tả trang sức.", "Tự nguyên_Xie": "璀 là chữ hình thanh: bộ 玉/王 (ngọc — đá quý) làm thành phần biểu nghĩa, 崔 (thôi) làm thành phần biểu âm. Nghĩa gốc là sự lấp lánh, rực rỡ của ngọc đá. Thường dùng trong 璀璨 (thôi xán — rực rỡ lấp lánh). Chưa có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thôi xán 璀璨)", "Hạng Tần Suất (Jun Da)": "4670.0", "Tần Suất % (Jun Da)": "99.884756915", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 崔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王崔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璀", "Unihan_Traditional (Chữ Phồn thể)": "璀", "Pinyin_Xie": "cuǐ", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ và hầu như luôn kết hợp với chữ xán để tả ánh sáng rực rỡ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岷', '{"9000": "4671.0", "Chữ Trung Quốc": "岷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 岷 | mân | tượng hình | tên núi, tên sông ở Tứ Xuyên | 岷 gồm bộ 山 (sơn — núi) và 民 (dân) bên phải. Cấu trúc hình thanh: 山 biểu nghĩa (núi), 民 biểu âm. Là tên riêng chỉ dãy núi岷山 và sông岷江 ở Tứ Xuyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mân\": núi (山) của dân (民) Tứ Xuyên — dãy núi Mân Sơn hùng vĩ. | Gương Hán-Việt | mân — \"岷山\" (Mân Sơn) là dãy núi; \"岷江\" (Mân Giang) là sông Mân | Mở khoá kiến thức | Biết 岷 giúp đọc địa danh 岷山, 岷江 trong địa lý và lịch sử Tứ Xuyên.", "Tự nguyên_Xie": "岷 là chữ hình thanh: 山 (sơn — núi) làm thành phần biểu nghĩa, 民 (dân) làm thành phần biểu âm. Nghĩa là tên địa danh tại tỉnh Tứ Xuyên, Trung Quốc: 岷山 (Mân Sơn — dãy núi Mân) và 岷江 (Mân Giang — sông Mân). Không có nghĩa thông thường ngoài tên địa danh. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "4671.0", "Tần Suất % (Jun Da)": "99.8848876616", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岷", "Unihan_Traditional (Chữ Phồn thể)": "岷", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "dân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ riêng để chỉ địa danh như núi Mân Sơn hoặc sông Mân Giang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舛', '{"9000": "4672.0", "Chữ Trung Quốc": "舛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舛 | Số nét | 6 | nét | 夊 | suy | bước chân chậm | 𡕒 | bàn chân | 舛 = 夊 (suy — bàn chân bước chậm) + 𡕒 (bàn chân hướng ngược). Chữ hội ý: hai bàn chân hướng cùng chiều — trái với 步 (hai chân hướng khác chiều tiến lên). Hình ảnh hai chân bước lệch, trái khoáy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suyễn\": hai bàn chân cùng hướng nhưng không tiến được — trái khoáy, lận đận, số phận không may. | Gương Hán-Việt | suyễn — \"多舛\" (đa suyễn) là nhiều trắc trở, lận đận | Mở khoá kiến thức | Biết 舛 mở khoá 命运多舛 (mệnh vận đa suyễn — số phận nhiều gian truân) và 乖舛 (quai suyễn — trái khoáy).", "Tự nguyên_Xie": "舛 là chữ hội ý theo Wiktionary: gồm 夊 và 𡕒 — hai bàn chân hướng cùng phía (không tiến được). Khác với 步 (bộ — hai chân bước về phía trước) và 夅 (chân hướng xuống). Nghĩa gốc là sai lầm, trái khoáy, không thuận. Dùng trong 乖舛 (quai suyễn — trái khoáy, không may) và 命运多舛 (mệnh vận đa suyễn — số phận nhiều trắc trở). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "942.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tịch (036) Khóa (896)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tịch (số 036 - chiều tối) và chữ Khóa (số 896 - vượt qua/ngược với Truy). Tịch là buổi tối trái ngược với sáng, Khóa là đi trước trái ngược với đi sau (Truy). Giải thích sự chuyển ý: Đây là chữ Hội ý. Suyễn là trái ngược, tương phản.", "Nghĩa Tiếng Việt_Xie": "ngang trái; lẫn lộn", "Hạng Tần Suất (Jun Da)": "4672.0", "Tần Suất % (Jun Da)": "99.8850184082", "GavinGrover_Once (Chiết tự trực tiếp)": "夕 + 㐄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夕㐄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夕", "Unihan_Simplified (Chữ Giản thể)": "舛", "Unihan_Traditional (Chữ Phồn thể)": "舛", "Pinyin_Xie": "chuǎn", "Âm Hán Việt_Xie": "suyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ để chỉ sự trắc trở hoặc không thuận lợi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邕', '{"9000": "4673.0", "Chữ Trung Quốc": "邕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 10 | nét | 邕 | ung | tượng hình | hòa hợp; tên địa danh (Nam Ninh) | 邕 gồm bộ 邑 (ấp — thành ấp) được biến thể kết hợp với phần trên. Chữ tạo muộn dùng chủ yếu làm tên địa danh cho thành phố Nam Ninh (邕宁). Chưa có phân tích hình học cụ thể từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ung\": âm ung ung hài hòa như tiếng nhạc — hoặc tên cổ của thành phố Nam Ninh. | Gương Hán-Việt | ung — \"邕江\" (Ung Giang) là sông chảy qua Nam Ninh | Mở khoá kiến thức | Biết 邕 giúp đọc địa danh liên quan đến Nam Ninh và Quảng Tây trong địa lý lịch sử.", "Tự nguyên_Xie": "邕 là tên riêng chỉ vùng đất Nam Ninh, Quảng Tây, Trung Quốc (tên cổ là 邕州). Cũng là dạng cổ/thay thế của 雍 (ung — hòa hợp, hài hòa). Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông chảy xung quanh ấp; châu Ung (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4673.0", "Tần Suất % (Jun Da)": "99.8851491549", "GavinGrover_Once (Chiết tự trực tiếp)": "巛 + 邑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巛邑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巛", "Unihan_Simplified (Chữ Giản thể)": "邕", "Unihan_Traditional (Chữ Phồn thể)": "邕", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ địa danh hoặc tính từ thể hiện sự hòa hợp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闿', '{"9000": "4674.0", "Chữ Trung Quốc": "闿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 闿 | khải | tượng hình | mở ra | 闿 gồm bộ 門 (môn — cửa) và 豈 (khải) bên trong. Cấu trúc hình thanh: 門 biểu nghĩa (cửa, mở cửa), 豈 biểu âm. Chỉ hành động mở ra (cửa, con đường).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": cánh cửa (門) khải hoàn mở rộng — mở ra, khai thông. | Gương Hán-Việt | khải — \"闿辟\" (khải tịch) là khai mở, mở mang bờ cõi | Mở khoá kiến thức | Biết 闿 giúp đọc văn ngôn cổ điển với nghĩa mở ra, khai thông trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "闿 là chữ hình thanh: 門 (môn — cửa) làm thành phần biểu nghĩa vì chỉ hành động mở cửa, 豈 (khải) làm thành phần biểu âm. Nghĩa là mở ra (to open), đặc biệt trong văn học cổ. Dùng trong 闿辟 (khải tịch — khai mở đất đai) hoặc như dạng cổ của 开 (khai). Chưa có nguồn Wiktionary chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mở mang", "Hạng Tần Suất (Jun Da)": "4674.0", "Tần Suất % (Jun Da)": "99.8852799015", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闿", "Unihan_Traditional (Chữ Phồn thể)": "闓", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành động mở mang hoặc làm tính từ chỉ tính chất ôn hòa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铂', '{"9000": "4675.0", "Chữ Trung Quốc": "铂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 铂 | bạch | tượng hình | bạch kim (platinum) | 铂 gồm bộ 钅(kim — kim loại) và 白 (bạch — trắng) bên phải. Cấu trúc hình thanh: 钅biểu nghĩa (kim loại), 白 biểu âm và biểu nghĩa (kim loại màu trắng bạc). Chỉ nguyên tố Platinum (Pt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạch\": kim loại (钅) màu trắng (白) — bạch kim, kim loại quý nhất. | Gương Hán-Việt | bạch — \"铂金\" (bạch kim) là platinum, kim loại quý màu trắng | Mở khoá kiến thức | Biết 铂 mở khoá 铂金 (bạch kim — platinum) trong hóa học, trang sức và công nghiệp.", "Tự nguyên_Xie": "铂 là chữ hình thanh: bộ 钅(kim — kim loại) làm thành phần biểu nghĩa, 白 (bạch — trắng) vừa làm biểu âm vừa gợi màu sắc trắng bạc của platinum. Đây là chữ tạo mới để phiên âm/dịch nghĩa nguyên tố Platinum (Pt, số nguyên tử 78). Nghĩa là bạch kim — kim loại quý màu trắng bạc. Chữ tạo muộn, không có trong văn học cổ. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bạch kim, nguyên tố platin, Pt", "Hạng Tần Suất (Jun Da)": "4675.0", "Tần Suất % (Jun Da)": "99.8854101314", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 白", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铂", "Unihan_Traditional (Chữ Phồn thể)": "鉑", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học hoặc chất liệu chế tác trang sức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霁', '{"9000": "4676.0", "Chữ Trung Quốc": "霁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 14 | nét | 雨 | vũ | biểu nghĩa | mưa | 齐 | tề | biểu âm | 霁 = 雨 (vũ — mưa, biểu nghĩa) + 齐 (tề, biểu âm). Chữ giản thể của 霽. Hình thanh: bộ mưa (雨) chỉ liên quan đến thời tiết, 齐 cho âm tề/tế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": mưa (雨) tề tề rút đi (齐) — trời tạnh hẳn sau cơn mưa, lòng dịu lại. | Gương Hán-Việt | tế — \"雨霁\" (vũ tế) là sau khi mưa tạnh; \"霁颜\" (tế nhan) là mặt giãn ra, hết giận | Mở khoá kiến thức | Biết 霁 mở khoá 雨霁 (vũ tế — mưa tạnh), 云霁 (vân tế), 霁颜 (tế nhan — hết giận) trong thơ văn.", "Tự nguyên_Xie": "霁 là giản thể của 霽. Chữ gốc 霽 gồm 雨 (vũ — mưa) làm thành phần biểu nghĩa, 齊 (tề) làm thành phần biểu âm. Nghĩa là trời tạnh mưa, ánh sáng sau cơn mưa. Mở rộng chỉ cơn giận tan biến (霁颜 — tế nhan). Dạng giản thể thay 齊 bằng 齐. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa tạnh", "Hạng Tần Suất (Jun Da)": "4676.0", "Tần Suất % (Jun Da)": "99.8855403612", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霁", "Unihan_Traditional (Chữ Phồn thể)": "霽", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ thời tiết tạnh ráo hoặc trạng thái nguôi giận của con người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犒', '{"9000": "4677.0", "Chữ Trung Quốc": "犒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 14 | nét | 牛 | ngưu | biểu nghĩa | trâu, bò | 高 | cao | biểu âm | 犒 = 牛 (ngưu — trâu bò, biểu nghĩa) + 高 (cao, biểu âm). Chữ hình thanh: giết trâu bò để khao thưởng quân sĩ — hành động khao quân bằng thức ăn tốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khao\": trâu bò (牛) ngon bậc nhất (高) dùng để khao quân — tiệc thưởng quân sĩ sau chiến thắng. | Gương Hán-Việt | khao — \"犒劳\" (khao lao) là khao thưởng; \"犒赏\" (khao thưởng) là ban thưởng | Mở khoá kiến thức | Biết 犒 mở khoá 犒劳 (khao lao — khao thưởng), 犒赏三军 (khao thưởng tam quân) trong văn học lịch sử.", "Tự nguyên_Xie": "犒 là chữ hình thanh theo Wiktionary: 牛 (ngưu — trâu/bò) làm thành phần biểu nghĩa vì xưa kia thưởng quân bằng cách mổ trâu bò thiết đãi, 高 (cao) làm thành phần biểu âm. Nghĩa gốc là khao thưởng binh lính bằng thức ăn (reward troops with food and drink). Dùng trong 犒劳 (khao lao), 犒赏 (khao thưởng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "442.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngưu (74) Cao (224)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ngưu (số 93 - con bò) và chữ Cao (số 189 - cao lớn) . Giết con bò (Ngưu) mập mạp cao (Cao) lớn để thiết đãi, ăn mừng gọi là khao thưởng, khao quân. Giải thích sự chuyển ý: Chữ Cao (cao lớn) chỉ âm, chữ Ngưu (con bò) chỉ ý. Dùng thịt trâu bò (Ngưu) để thiết đãi, ban thưởng cho quân lính gọi là khao quân (Khao). *(Biến âm Hán Việt: Cao -> Khao)*", "Nghĩa Tiếng Việt_Xie": "khao thưởng, chiêu đãi", "Hạng Tần Suất (Jun Da)": "4677.0", "Tần Suất % (Jun Da)": "99.8856700743", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犒", "Unihan_Traditional (Chữ Phồn thể)": "犒", "Pinyin_Xie": "kào", "Âm Hán Việt_Xie": "khao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mang tân ngữ chỉ người hoặc tập thể được nhận phần thưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馏', '{"9000": "4678.0", "Chữ Trung Quốc": "馏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 饣 | thực | biểu nghĩa | thức ăn, nấu ăn | 留 | lưu | biểu âm | 馏 = 饣(thực — thức ăn/nấu ăn, biểu nghĩa) + 留 (lưu, biểu âm). Chữ hình thanh chỉ việc hấp lại thức ăn để làm nóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lựu\": thức ăn (饣) giữ lại (留) để hấp nóng thêm — hấp lại cơm, chưng cất rượu. | Gương Hán-Việt | lựu — \"蒸馏\" (chưng lựu) là chưng cất; \"馏饭\" (lựu phạn) là hấp lại cơm | Mở khoá kiến thức | Biết 馏 mở khoá 蒸馏 (chưng lựu — chưng cất/distillation) trong hóa học và 馏饭 trong nấu ăn.", "Tự nguyên_Xie": "馏 là giản thể của 餾. Chữ gốc 餾 gồm 飠 (thực — thức ăn) làm thành phần biểu nghĩa, 留 (lưu) làm thành phần biểu âm. Nghĩa là hấp lại thức ăn đã nguội để làm nóng (re-steam food). Cũng dùng trong chưng cất (蒸馏 — chưng lựu). Dạng giản thể thay 飠 bằng 饣. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơm đã chín", "Hạng Tần Suất (Jun Da)": "4678.0", "Tần Suất % (Jun Da)": "99.8857992706", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馏", "Unihan_Traditional (Chữ Phồn thể)": "餾", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ phương pháp nấu nướng hoặc kỹ thuật hóa học chưng cất chất lỏng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阈', '{"9000": "4679.0", "Chữ Trung Quốc": "阈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 阈 | vực | tượng hình | ngưỡng cửa, giới hạn | 阈 gồm bộ 门 (môn — cửa) và 或 (hoặc) bên trong. Cấu trúc hình thanh: 门 biểu nghĩa (cửa, ngưỡng), 或 biểu âm. Chỉ ngưỡng cửa hoặc giới hạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vực\": cánh cửa (门) với ranh giới lưỡng (或) — ngưỡng cửa, giới hạn; vừa trong vừa ngoài. | Gương Hán-Việt | vực — \"阈值\" (vực trị) là giá trị ngưỡng; \"感觉阈\" (cảm giác vực) là ngưỡng cảm giác | Mở khoá kiến thức | Biết 阈 mở khoá 阈值 (vực trị — threshold value) trong khoa học, kỹ thuật và tâm lý học.", "Tự nguyên_Xie": "阈 là chữ hình thanh: 门 (môn — cửa) làm thành phần biểu nghĩa vì ngưỡng cửa là phần dưới cùng của khung cửa, 或 (hoặc) làm thành phần biểu âm. Nghĩa gốc là ngưỡng cửa, bậc cửa. Mở rộng chỉ ngưỡng giới hạn trong khoa học (threshold): 阈值 (vực trị — giá trị ngưỡng). Chưa có nguồn Wiktionary chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ngưỡng cửa; ngăn cách", "Hạng Tần Suất (Jun Da)": "4679.0", "Tần Suất % (Jun Da)": "99.8859284669", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 或", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门或", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "或", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阈", "Unihan_Traditional (Chữ Phồn thể)": "閾", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "vực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ khác để chỉ giới hạn vật lý hoặc tâm lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麋', '{"9000": "4680.0", "Chữ Trung Quốc": "麋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 17 | nét | 麋 | mi | tượng hình | con nai lớn, hươu sừng lớn | 麋 là chữ tượng hình — vốn vẽ hình con nai (麋鹿) với bộ lông dày. Chưa có nguồn phân tích hội ý/hình thanh từ Wiktionary, nên chỉ ghi nhận bộ 鹿 (lộc) mà chữ thuộc về.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\" (麋鹿): bộ 鹿 (nai) nhắc đây là loài thú — con nai lớn đặc trưng của rừng Trung Hoa cổ. | Gương Hán-Việt | 麋鹿 (mi lộc) — con nai lớn | Mở khoá kiến thức | Biết 麋 mở khoá: 麋鹿 (hươu sừng lớn), 麋集 (tụ hội đông đúc như đàn nai).", "Tự nguyên_Xie": "麋 (mí) chỉ loài nai lớn 麋鹿 (hươu sừng lớn/nai trầm hương). Chữ thuộc bộ 鹿 (lộc — nai/hươu). Chưa có nguồn học thuật chi tiết trên Wiktionary về cấu trúc nội tại của chữ này. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nai; con nai", "Hạng Tần Suất (Jun Da)": "4680.0", "Tần Suất % (Jun Da)": "99.8860576632", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麋", "Unihan_Traditional (Chữ Phồn thể)": "麋", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm thành phần cấu tạo tên các loài hươu nai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麒', '{"9000": "4681.0", "Chữ Trung Quốc": "麒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 19 | nét | 麒 | kì | tượng hình | kỳ lân — con thú thần thoại mang vảy và sừng | 麒 là chữ chỉ riêng trong tổ hợp 麒麟 (kỳ lân). Bộ 鹿 (lộc) cho thấy đây là loài thú giống nai thần thoại. Chưa có phân tích hình thanh/hội ý chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kì\" (麒麟 — kỳ lân): bộ 鹿 (nai) + hình thức thần thoại — kỳ lân chỉ xuất hiện khi có minh quân trị vì. | Gương Hán-Việt | 麒麟 (kỳ lân) — con thú thần thoại điềm lành | Mở khoá kiến thức | Biết 麒 mở khoá: 麒麟 (kỳ lân), 麒麟座 (chòm sao Kỳ Lân), 麒麟兒 (đứa trẻ tài năng như kỳ lân).", "Tự nguyên_Xie": "麒 (qí) chỉ xuất hiện trong từ 麒麟 — con kỳ lân trong thần thoại Trung Hoa, biểu tượng của điềm lành và bậc minh quân. Wiktionary chỉ ghi nhận 麒 dùng trong 麒麟, không phân tích cấu trúc nội tại. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn với nghĩa độc lập. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: kỳ lân 麒麟)", "Hạng Tần Suất (Jun Da)": "4681.0", "Tần Suất % (Jun Da)": "99.8861868594", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麒", "Unihan_Traditional (Chữ Phồn thể)": "麒", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như luôn đi kèm với chữ Lân để tạo thành từ ghép chỉ linh vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苁', '{"9000": "4682.0", "Chữ Trung Quốc": "苁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苁 | thung | tượng hình | cỏ thung — loại cây thuốc | 苁 là dạng giản thể của 蓯. Bộ 艸 (thảo) cho thấy đây là loài thực vật. Chưa có phân tích hình thanh/hội ý chi tiết từ Wiktionary cho dạng giản thể này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thung\" (苁蓉): bộ 艸 (cỏ) — 肉苁蓉 là loài cây thảo dược quý như nhân sâm của sa mạc Gobi. | Gương Hán-Việt | 苁蓉 (thung dung) — cỏ thung, nhục thung dung | Mở khoá kiến thức | Biết 苁 mở khoá: 苁蓉 (thung dung), 肉苁蓉 (nhục thung dung — thảo dược bổ thận).", "Tự nguyên_Xie": "苁 (cōng) là dạng giản thể của 蓯, dùng chủ yếu trong từ 肉苁蓉 (nhục thung dung) — một loại cây ký sinh thuốc quý mọc ở sa mạc. Theo Wiktionary (mục 蓯), chữ gốc dùng trong 蓯蓉 với âm cōng, và còn dùng trong 蘢蓯 (cây lau mọc rậm rạp). Chưa có nguồn học thuật chi tiết về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ thung", "Hạng Tần Suất (Jun Da)": "4682.0", "Tần Suất % (Jun Da)": "99.8863155389", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 从", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹从", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苁", "Unihan_Traditional (Chữ Phồn thể)": "蓯", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong y học cổ truyền để chỉ một vị thuốc thảo dược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摁', '{"9000": "4683.0", "Chữ Trung Quốc": "摁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 摁 | ấn | tượng hình | bấm, ấn bằng tay | 摁 là chữ hiện đại, không có nguồn Wiktionary. Bộ 手 (thủ — tay) gợi ý hành động dùng tay. Chưa có phân tích cấu trúc từ học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấn\" (摁): bộ 手 (tay) — ngón tay ấn xuống mạnh như bấm nút chuông. | Gương Hán-Việt | 摁 dùng trong văn nói: 摁门铃 (bấm chuông cửa) | Mở khoá kiến thức | Biết 摁 mở khoá: 摁门铃 (bấm chuông cửa), 摁下去 (ấn xuống), 摁住 (giữ chặt bằng cách ấn).", "Tự nguyên_Xie": "摁 (èn) là chữ bạch thoại hiện đại chỉ hành động bấm/ấn bằng ngón tay hoặc lòng bàn tay. Chữ tạo muộn, không thấy trong giáp cốt/kim văn, không có nguồn học thuật từ Wiktionary. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bấm, ấn", "Hạng Tần Suất (Jun Da)": "4683.0", "Tần Suất % (Jun Da)": "99.8864442184", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 恩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌恩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "恩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摁", "Unihan_Traditional (Chữ Phồn thể)": "摁", "Pinyin_Xie": "èn", "Âm Hán Việt_Xie": "ân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm tân ngữ chỉ nút bấm hoặc bề mặt cần đè. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涔', '{"9000": "4684.0", "Chữ Trung Quốc": "涔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 涔 | sầm | tượng hình | nước mưa đọng, ướt đẫm | 涔 thuộc bộ 水 (thủy — nước), gợi ý liên quan đến nước/mưa. Wiktionary có mục 涔 nhưng không phân tích cấu trúc hình thanh/hội ý rõ ràng. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sầm\" (涔): bộ 水 (nước) — 汗涔涔 mồ hôi chảy ướt đẫm như mưa sầm xuống. | Gương Hán-Việt | 涔涔 (sầm sầm) — ướt đẫm, chảy liên tục | Mở khoá kiến thức | Biết 涔 mở khoá: 涔涔 (ướt đẫm), 汗涔涔 (mồ hôi đầm đìa), 泪涔涔 (nước mắt tuôn chảy).", "Tự nguyên_Xie": "涔 (cén) theo Wiktionary chỉ trạng thái ẩm ướt do mưa, nước tích tụ, hay nước mắt chảy dài. Dùng trong văn học cổ: 涔涔 (ướt đẫm), 汗涔涔 (mồ hôi đầm đìa), 泪涔涔 (nước mắt chảy). Chữ thuộc bộ 水 nhưng chưa có phân tích cấu trúc nội tại rõ ràng từ Wiktionary. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mưa đọng; vũng nước; lụt, ngập", "Hạng Tần Suất (Jun Da)": "4684.0", "Tần Suất % (Jun Da)": "99.8865728979", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 岑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵岑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涔", "Unihan_Traditional (Chữ Phồn thể)": "涔", "Pinyin_Xie": "cén", "Âm Hán Việt_Xie": "sầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả mồ hôi hoặc nước mắt rơi đầm đìa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宥', '{"9000": "4685.0", "Chữ Trung Quốc": "宥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 9 | nét | 宥 | hựu | tượng hình | tha thứ, rộng lòng | 宥 thuộc bộ 宀 (miên — mái nhà), gợi ý sự che chở, bảo bọc. Wiktionary có mục 宥 nhưng không phân tích cấu trúc hình thanh/hội ý cụ thể. Nghĩa \"tha thứ, rộng thứ\" liên quan đến sự bao dung như mái nhà che chở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hựu\" (宥恕): bộ 宀 (mái nhà) — tha thứ là đưa người lầm lỗi vào dưới mái nhà che chở của mình. | Gương Hán-Việt | 宥恕 (hựu thứ) — tha thứ, rộng thứ | Mở khoá kiến thức | Biết 宥 mở khoá: 宥恕 (tha thứ), 宽宥 (khoan hồng), 特宥 (đặc ân tha tội), 赦宥 (tha xá).", "Tự nguyên_Xie": "宥 (yòu) có nghĩa tha thứ, rộng thứ, bao dung. Theo Wiktionary, chữ xuất hiện từ thời cổ với ý nghĩa tha tội, khoan hồng — dùng nhiều trong văn ngôn: 宥恕 (rộng thứ), 宽宥 (khoan hồng), 特宥 (đặc ân tha tội). Chưa có phân tích cấu trúc nội tại rõ ràng. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rộng thứ, tha thứ", "Hạng Tần Suất (Jun Da)": "4685.0", "Tần Suất % (Jun Da)": "99.8867015774", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宥", "Unihan_Traditional (Chữ Phồn thể)": "宥", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "hựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để biểu thị sự khoan dung. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妍', '{"9000": "4686.0", "Chữ Trung Quốc": "妍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 幵 | biểu âm | thành phần biểu âm | 妍 = 女 (Nữ, biểu nghĩa: phụ nữ) + 幵 (biểu âm); chữ hình thanh. Bộ 女 gợi ý vẻ đẹp của người phụ nữ, 幵 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngơn\" (妍丽): 女 (nữ) + 幵 (biểu âm) — người phụ nữ đẹp rạng rỡ như mùa xuân đua nở. | Gương Hán-Việt | 妍丽 (ngơn lệ) — xinh đẹp rực rỡ; 百花争妍 (bách hoa tranh ngơn) — trăm hoa đua sắc | Mở khoá kiến thức | Biết 妍 mở khoá: 妍丽 (xinh đẹp), 妍媸 (đẹp xấu), 百花争妍 (trăm hoa đua nở).", "Tự nguyên_Xie": "妍 (yán) theo Wiktionary là chữ hình thanh: 女 (nữ — phụ nữ, biểu nghĩa) + 幵 (biểu âm). Nghĩa gốc là xinh đẹp, quyến rũ — dùng trong văn học cổ điển để miêu tả vẻ đẹp rực rỡ. Trái nghĩa với 媸 (xấu xí). Xuất hiện trong các thành ngữ như 百花争妍 (trăm hoa đua nở), 争妍献媚 (đua nhau khoe sắc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tươi tỉnh, xinh đẹp", "Hạng Tần Suất (Jun Da)": "4686.0", "Tần Suất % (Jun Da)": "99.8868302569", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妍", "Unihan_Traditional (Chữ Phồn thể)": "妍", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "nghiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để tả vẻ đẹp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铤', '{"9000": "4687.0", "Chữ Trung Quốc": "铤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại, vàng bạc | 廷 | đình | biểu âm | thành phần biểu âm | 铤 = 金 (Kim, biểu nghĩa: kim loại) + 廷 (Đình, biểu âm); chữ hình thanh. Bộ 金 chỉ chất liệu là kim loại, 廷 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đĩnh\" (铤而走险): 金 (kim loại) + 廷 (biểu âm) — thanh kim loại thoi bạc, liều lĩnh như thẳng tắp lao vào nguy hiểm. | Gương Hán-Việt | 铤而走险 (đĩnh nhi tẩu hiểm) — liều lĩnh đường nguy hiểm | Mở khoá kiến thức | Biết 铤 mở khoá: 铤而走险 (liều đi đường nguy hiểm), 金铤 (thoi vàng), 银铤 (nén bạc).", "Tự nguyên_Xie": "铤 (dìng), dạng truyền thống là 鋌, theo Wiktionary là chữ hình thanh: 金 (kim — kim loại, biểu nghĩa) + 廷 (đình — triều đình, biểu âm). Nghĩa gốc là thoi kim loại, thanh kim loại đúc — vàng thoi, bạc nén. Thường dùng trong thành ngữ 铤而走险 (liều lĩnh đi vào con đường nguy hiểm). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thoi vàng, thoi bạc; con thoi dệt vải", "Hạng Tần Suất (Jun Da)": "4687.0", "Tần Suất % (Jun Da)": "99.8869589364", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铤", "Unihan_Traditional (Chữ Phồn thể)": "鋌", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các thoi kim loại quý dùng trong giao thương thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锷', '{"9000": "4688.0", "Chữ Trung Quốc": "锷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 锷 | ngạc | tượng hình | lưỡi dao, mũi kiếm | 锷 thuộc bộ 金 (kim — kim loại), chỉ lưỡi sắc của vũ khí. Wiktionary có mục 鍔 (dạng phồn thể) nhưng không phân tích cấu trúc nội tại. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\" (锷锷): bộ 金 (kim loại) — lưỡi kiếm sắc bén như hàm cá sấu 鳄 (ngạc) cắn mồi. | Gương Hán-Việt | 藏锋敛锷 (tàng phong liễm ngạc) — giấu lưỡi sắc, ẩn tài năng | Mở khoá kiến thức | Biết 锷 mở khoá: 廉锷 (lưỡi liêm), 藏锋敛锷 (ẩn tài giấu sắc).", "Tự nguyên_Xie": "锷 (è), dạng truyền thống là 鍔, theo Wiktionary là từ văn học cổ chỉ lưỡi kiếm/dao sắc bén. Dùng trong 廉锷 (lưỡi liêm), 藏锋敛锷 (giấu lưỡi thu sắc bén — ẩn tài đức). Chưa có phân tích cấu trúc hình thanh/hội ý từ Wiktionary. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lưỡi dao, mũi dao", "Hạng Tần Suất (Jun Da)": "4688.0", "Tần Suất % (Jun Da)": "99.8870876159", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 咢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅咢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锷", "Unihan_Traditional (Chữ Phồn thể)": "鍔", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ vũ khí để cấu tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗲', '{"9000": "4689.0", "Chữ Trung Quốc": "嗲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng | 爹 | tía | biểu âm | thành phần biểu âm | 嗲 = 口 (Khẩu, biểu nghĩa: miệng) + 爹 (Tía, biểu âm); chữ hình thanh. Bộ 口 cho thấy liên quan đến lời nói/giọng nói, 爹 (bố) cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niá\" (嗲): 口 (miệng) + 爹 (tía/bố) — giọng nói ỏn ẻn như con nít gọi bố: \"Tía ơi tía~\". | Gương Hán-Việt | 撒嗲 (tán niá) — làm nũng, nũng nịu | Mở khoá kiến thức | Biết 嗲 mở khoá: 撒嗲 (làm nũng), 嗲声嗲气 (giọng ỏn ẻn cưng chiều), 嗲嗲 (ông nội — tiếng Thượng Hải).", "Tự nguyên_Xie": "嗲 (diǎ) theo Wiktionary là chữ hình thanh: 口 (khẩu — miệng, biểu nghĩa) + 爹 (tía — bố, biểu âm). Chữ xuất phát từ phương ngữ Thượng Hải, chỉ giọng nói cưng chiều, ỏn ẻn, thường dùng để mô tả cách nói của trẻ nhỏ hoặc người cố tình làm nũng. 撒嗲 nghĩa là làm nũng, đòi nng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uốn éo; ỏn ẻn; đặc biệt; tốt", "Hạng Tần Suất (Jun Da)": "4689.0", "Tần Suất % (Jun Da)": "99.8872157786", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 爹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口爹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗲", "Unihan_Traditional (Chữ Phồn thể)": "嗲", "Pinyin_Xie": "diǎ", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả giọng nói hoặc dáng vẻ nũng nịu của phụ nữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恽', '{"9000": "4690.0", "Chữ Trung Quốc": "恽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 恽 | uẩn | tượng hình | họ Uẩn; lo lắng, suy nghĩ | 恽 là dạng giản thể của 惲. Theo Wiktionary, 惲 = 心 (tâm — tâm hồn) + 軍 (quân). Dạng giản thể thay 軍 bằng 军. Là chữ hình thanh với bộ 心 biểu nghĩa (cảm xúc) và 军 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\" (恽): bộ 心 (tâm) + 军 (biểu âm) — họ Uẩn mang trong lòng (心) nỗi lo toan sâu kín. | Gương Hán-Việt | 恽代英 (Uẩn Đại Anh) — nhà cách mạng nổi tiếng | Mở khoá kiến thức | Biết 恽 mở khoá: 恽代英 (Uẩn Đại Anh), 恽寿平 (Uẩn Thọ Bình — họa sĩ danh tiếng nhà Thanh).", "Tự nguyên_Xie": "恽 (yùn) là dạng giản thể của 惲, theo Wiktionary giản hóa từ 軍 thành 军. Chữ gốc 惲 có bộ 心 (tâm — tâm hồn, biểu nghĩa) + 軍 (quân, biểu âm). Ngày nay chủ yếu dùng làm họ người (họ Uẩn). Nghĩa gốc là suy nghĩ, bàn luận, lo lắng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Uẩn", "Hạng Tần Suất (Jun Da)": "4690.0", "Tần Suất % (Jun Da)": "99.8873439414", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恽", "Unihan_Traditional (Chữ Phồn thể)": "惲", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chủ yếu dùng làm danh từ riêng để chỉ họ người hoặc tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麂', '{"9000": "4691.0", "Chữ Trung Quốc": "麂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 13 | nét | 麂 | hoẵng | tượng hình | con hoẵng — loài hươu nhỏ | 麂 thuộc bộ 鹿 (lộc — nai, hươu), chỉ một loài hươu nhỏ gọi là hoẵng (con hoẵng). Wiktionary chỉ ghi {{Han etym}} mà không phân tích cấu trúc chi tiết. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoẵng\" (麂): bộ 鹿 (nai) — con hoẵng là loài nai nhỏ nhất trong họ Cervidae, chạy nhanh như chớp. | Gương Hán-Việt | 麂子 (hoẵng tử) — con hoẵng; 麂皮 (da hoẵng) — da lộn | Mở khoá kiến thức | Biết 麂 mở khoá: 麂皮 (da lộn — vải da hoẵng), 麂子 (con hoẵng).", "Tự nguyên_Xie": "麂 (jǐ) chỉ loài hươu nhỏ, gọi là hoẵng hay nai hoẵng, sống trong rừng Đông Nam Á và Trung Hoa. Chữ thuộc bộ 鹿 (lộc). Wiktionary chỉ ghi {{Han etym}}, chưa có phân tích cấu trúc nội tại. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hoẵng", "Hạng Tần Suất (Jun Da)": "4691.0", "Tần Suất % (Jun Da)": "99.8874721041", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麂", "Unihan_Traditional (Chữ Phồn thể)": "麂", "Pinyin_Xie": "jǐ", "Âm Hán Việt_Xie": "kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài động vật hoang dã thuộc họ hươu nai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赝', '{"9000": "4692.0", "Chữ Trung Quốc": "赝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 16 | nét | 赝 | nghiễm | tượng hình | đồ giả, hàng giả, đồ nhái | 赝 thuộc bộ 厂 (hán — vách núi/mái hiên), nhưng cấu trúc chi tiết chưa được Wiktionary phân tích rõ ràng. Nghĩa là đồ giả, đồ nhái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiễm\" (赝品): nhớ chữ 赝 là đồ NHÁI — giống thật nhưng không phải thật, như bức tranh giả được bày dưới mái nhà (厂). | Gương Hán-Việt | 赝品 (nghiễm phẩm) — hàng giả, đồ nhái | Mở khoá kiến thức | Biết 赝 mở khoá: 赝品 (hàng giả), 赝本 (bản sao chép giả), 赝鼎 (đồ nhái), 赝币 (tiền giả).", "Tự nguyên_Xie": "赝 (yàn), dạng phồn thể 贗, theo Wiktionary có âm cổ và chỉ nghĩa đồ giả mạo, đồ hàng nhái. Dùng trong: 赝品 (hàng giả), 赝本 (bản chép giả), 赝鼎 (cái đỉnh giả — chỉ đồ nhái nói chung), 赝币 (tiền giả). Chưa có phân tích cấu trúc nội tại chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ giả, hàng giả", "Hạng Tần Suất (Jun Da)": "4692.0", "Tần Suất % (Jun Da)": "99.88759975", "GavinGrover_Once (Chiết tự trực tiếp)": "雁 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴雁贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赝", "Unihan_Traditional (Chữ Phồn thể)": "贋", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nhạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ hàng giả hoặc đồ nhái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胛', '{"9000": "4693.0", "Chữ Trung Quốc": "胛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 甲 | giáp | biểu âm | thành phần biểu âm | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 胛 = 肉 (Nhục, biểu nghĩa: thịt/cơ thể) + 甲 (Giáp, biểu âm); chữ hình thanh. Bộ 肉 (月旁) chỉ bộ phận cơ thể, 甲 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\" (肩胛): 肉 (thịt cơ thể) + 甲 (giáp — biểu âm) — bả vai là \"lớp giáp\" thịt che chắn sau lưng. | Gương Hán-Việt | 肩胛 (kiên giáp) — bả vai; 肩胛骨 (kiên giáp cốt) — xương bả vai | Mở khoá kiến thức | Biết 胛 mở khoá: 肩胛 (bả vai), 肩胛骨 (xương bả vai), 羊胛 (bả vai cừu — tên món ăn).", "Tự nguyên_Xie": "胛 (jiǎ) theo Wiktionary là chữ hình thanh: 肉 (nhục — thịt/cơ thể, biểu nghĩa) + 甲 (giáp — biểu âm). Nghĩa là bả vai, xương bả vai. Dùng trong: 肩胛 (vai, bả vai), 肩胛骨 (xương bả vai). Âm Hán cổ gần với 甲 (jiǎ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bả vai", "Hạng Tần Suất (Jun Da)": "4693.0", "Tần Suất % (Jun Da)": "99.8877273959", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胛", "Unihan_Traditional (Chữ Phồn thể)": "胛", "Pinyin_Xie": "jiǎ", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ khác làm danh từ chỉ bộ phận xương bả vai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哂', '{"9000": "4694.0", "Chữ Trung Quốc": "哂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 西 | tây | biểu âm | thành phần biểu âm | 哂 = 口 (Khẩu, biểu nghĩa: miệng) + 西 (Tây, biểu âm); chữ hình thanh. Bộ 口 chỉ hành động của miệng (cười), 西 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỉnh\" (哂纳): 口 (miệng) + 西 (biểu âm) — nụ cười khẽ khi nhận quà: \"哂纳\" là cách nói lịch sự. | Gương Hán-Việt | 哂纳 (thỉnh nạp) — vui lòng nhận (cách nói khiêm tốn) | Mở khoá kiến thức | Biết 哂 mở khoá: 哂纳 (xin vui lòng nhận), 哂笑 (mỉm cười coi thường), 请哂纳 (kính xin nhận lấy).", "Tự nguyên_Xie": "哂 (shěn) theo Wiktionary là chữ hình thanh: 口 (khẩu — miệng, biểu nghĩa) + 西 (tây — biểu âm). Nghĩa là mỉm cười, hay cười nhạo. Dùng trong văn học cổ điển: 哂纳 (nhận lấy với nụ cười — cách nói khiêm tốn khi tặng quà), 哂笑 (mỉm cười coi thường). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỉm cười", "Hạng Tần Suất (Jun Da)": "4694.0", "Tần Suất % (Jun Da)": "99.8878545251", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哂", "Unihan_Traditional (Chữ Phồn thể)": "哂", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "sẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn cổ thể hiện thái độ cười nhẹ hoặc tự giễu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撷', '{"9000": "4695.0", "Chữ Trung Quốc": "撷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 撷 | hiệp | tượng hình | hái, ngắt, lấy bằng tay | 撷 là dạng giản thể của 擷. Bộ 手 (扌) chỉ hành động dùng tay. Wiktionary có mục 擷 nhưng không phân tích cấu trúc hình thanh/hội ý cụ thể. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\" (采撷): bộ 手 (扌 — tay) — đưa tay hái những bông hoa đẹp nhất trong vườn. | Gương Hán-Việt | 采撷 (thải hiệp) — hái lấy, thu thập; 撷取 (hiệp thủ) — trích chọn | Mở khoá kiến thức | Biết 撷 mở khoá: 采撷 (hái lấy), 撷取 (trích lấy), 撷英 (chọn lấy tinh hoa).", "Tự nguyên_Xie": "撷 (xié), dạng phồn thể 擷, theo Wiktionary có nghĩa hái, ngắt, lấy — dùng trong văn cổ. Trong 采撷 (hái lấy, thu thập), 撷取 (trích lấy, chọn lấy). Còn có nghĩa phương ngữ Mân Nam là vẫy tay, bay phất. Chưa có phân tích cấu trúc chi tiết từ học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hái, ngắt", "Hạng Tần Suất (Jun Da)": "4695.0", "Tần Suất % (Jun Da)": "99.8879811374", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 颉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌颉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "颉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撷", "Unihan_Traditional (Chữ Phồn thể)": "擷", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường dùng trong văn viết để chỉ hành động hái hoa hoặc thu lượm tinh hoa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呶', '{"9000": "4696.0", "Chữ Trung Quốc": "呶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 呶 | nao | tượng hình | tiếng la hét, ồn ào | 呶 thuộc bộ 口 (khẩu — miệng), chỉ tiếng la hét ồn ào. Wiktionary có mục 呶 nhưng không phân tích cấu trúc hình thanh/hội ý cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nao\" (呶呶不休): bộ 口 (miệng) — miệng la hét ầm ĩ không ngừng, nao nao loạn cả tai. | Gương Hán-Việt | 呶呶不休 (nao nao bất hưu) — lải nhải không ngừng | Mở khoá kiến thức | Biết 呶 mở khoá: 呶呶 (lải nhải), 呶呶不休 (nói dai không nghỉ), 喧呶 (ồn ào huyên náo).", "Tự nguyên_Xie": "呶 (náo) theo Wiktionary chỉ sự ồn ào, la hét. Dùng trong: 呶呶 (nói dai không ngừng), 呶呶不休 (lải nhải không nghỉ), 喧呶 (ồn ào náo nhiệt). Âm cổ trung cổ gần với náo. Chưa có phân tích cấu trúc nội tại chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng la hét", "Hạng Tần Suất (Jun Da)": "4696.0", "Tần Suất % (Jun Da)": "99.8881077498", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 奴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口奴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呶", "Unihan_Traditional (Chữ Phồn thể)": "呶", "Pinyin_Xie": "náo", "Âm Hán Việt_Xie": "nao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để miêu tả trạng thái ồn ào, huyên náo của đám đông. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噘', '{"9000": "4697.0", "Chữ Trung Quốc": "噘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 噘 | quyết | tượng hình | bĩu môi, cong môi ra | 噘 thuộc bộ 口 (khẩu — miệng), chỉ hành động bĩu môi. Chữ hiện đại, không có nguồn Wiktionary. Chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\" (噘嘴): bộ 口 (miệng) — miệng bĩu ra như con vịt: 噘嘴 bĩu môi tỏ vẻ bực bội. | Gương Hán-Việt | 噘嘴 (quyết chủy) — bĩu môi | Mở khoá kiến thức | Biết 噘 mở khoá: 噘嘴 (bĩu môi), 嘟噘 (chu miệng bĩu môi).", "Tự nguyên_Xie": "噘 (juē) là chữ bạch thoại hiện đại chỉ hành động bĩu môi, cong môi ra. Chữ tạo muộn, không có nguồn học thuật từ Wiktionary. Bộ 口 (miệng) biểu thị đây là hành động của miệng. Thường dùng trong: 噘嘴 (bĩu môi, cau mày), thể hiện bực bội hoặc làm nũng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bĩu môi, cong môi", "Hạng Tần Suất (Jun Da)": "4697.0", "Tần Suất % (Jun Da)": "99.8882343621", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噘", "Unihan_Traditional (Chữ Phồn thể)": "噘", "Pinyin_Xie": "juē", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị động tác cong môi hoặc bĩu môi để thể hiện thái độ giận dỗi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懔', '{"9000": "4698.0", "Chữ Trung Quốc": "懔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 16 | nét | 忄 | biểu nghĩa | tâm, cảm xúc | 稟 | bẩm | biểu âm | thành phần biểu âm | 懔 = 忄 (biểu nghĩa: tâm/cảm xúc) + 稟 (Bẩm, biểu âm); chữ hình thanh. Bộ 忄 (bộ tâm biến thể) gợi ý trạng thái cảm xúc kính sợ, 稟 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lẫm\" (懔然): 忄(tâm) + 稟 (biểu âm) — lòng rùng mình kính sợ như nhận lệnh trên (稟 — bẩm báo cấp trên). | Gương Hán-Việt | 懔然 (lẫm nhiên) — rùng mình kính sợ | Mở khoá kiến thức | Biết 懔 mở khoá: 懔然 (kính sợ rùng mình), 懔懔 (lo sợ run rẩy), 交懔恂 (run sợ lo lắng).", "Tự nguyên_Xie": "懔 (lǐn), dạng truyền thống 懍, theo Wiktionary là chữ hình thanh: 忄 (tâm — cảm xúc, biểu nghĩa) + 稟 (bẩm — biểu âm). Nghĩa là e ngại, kính sợ, rợn người. Dùng trong văn học: 懔然 (rùng mình kính sợ), 懔懔 (lo sợ run rẩy). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "e ngại, kính sợ", "Hạng Tần Suất (Jun Da)": "4698.0", "Tần Suất % (Jun Da)": "99.8883609745", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 禀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄禀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "懔", "Unihan_Traditional (Chữ Phồn thể)": "懍", "Pinyin_Xie": "lǐn", "Âm Hán Việt_Xie": "lẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ thể hiện trạng thái kính sợ hoặc lo sợ trước uy thế lớn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栎', '{"9000": "4699.0", "Chữ Trung Quốc": "栎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 樂 | lạc | biểu âm | thành phần biểu âm | 栎 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 樂 (Lạc, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là loài cây, 樂 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\" (栎树): 木 (cây) + 樂 (biểu âm lạc/lịch) — cây sồi vững chắc như niềm vui (樂) kiên định không lay chuyển. | Gương Hán-Việt | 栎树 (lịch thụ) — cây sồi | Mở khoá kiến thức | Biết 栎 mở khoá: 栎树 (cây sồi), 麻栎 (cây sồi gai), 栎阳 (Lịch Dương — địa danh).", "Tự nguyên_Xie": "栎 (lì), dạng phồn thể 櫟, theo Wiktionary là chữ hình thanh: 木 (mộc — cây/gỗ, biểu nghĩa) + 樂 (lạc — biểu âm). Nghĩa gốc là cây sồi/cây lịch (chestnut-leaved oak) — loài cây rụng lá họ Fagaceae. Gỗ sồi rắn chắc dùng làm than. Tên tỉnh/địa danh 栎阳 (Lịch Dương). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lịch, cây sồi; nạo, cạo", "Hạng Tần Suất (Jun Da)": "4699.0", "Tần Suất % (Jun Da)": "99.8884875869", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栎", "Unihan_Traditional (Chữ Phồn thể)": "櫟", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại cây thân gỗ lớn thuộc họ sồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桎', '{"9000": "4700.0", "Chữ Trung Quốc": "桎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ | 至 | chí | biểu âm | thành phần biểu âm | 桎 = 木 (Mộc, biểu nghĩa: gỗ) + 至 (Chí, biểu âm); chữ hình thanh. Bộ 木 chỉ vật bằng gỗ (cùm chân), 至 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuối\" (桎梏): 木 (gỗ) + 至 (chí — biểu âm) — cùm gỗ đến tận cùng (至) giam hãm đôi chân. | Gương Hán-Việt | 桎梏 (chuối cốc) — gông xiềng, ràng buộc | Mở khoá kiến thức | Biết 桎 mở khoá: 桎梏 (gông xiềng — cả nghĩa đen và bóng), 解除桎梏 (thoát khỏi ràng buộc).", "Tự nguyên_Xie": "桎 (zhì) theo Wiktionary là chữ hình thanh: 木 (mộc — gỗ, biểu nghĩa) + 至 (chí — biểu âm). Nghĩa là cái cùm chân làm bằng gỗ dùng để trói buộc tù nhân. Thường dùng trong 桎梏 (cùm xích, gông xiềng — cả nghĩa đen lẫn nghĩa bóng là ràng buộc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cùm; cái cùm chân", "Hạng Tần Suất (Jun Da)": "4700.0", "Tần Suất % (Jun Da)": "99.8886141992", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桎", "Unihan_Traditional (Chữ Phồn thể)": "桎", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ dụng cụ cùm chân thời xưa, thường đi đôi với còng tay trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霰', '{"9000": "4701.0", "Chữ Trung Quốc": "霰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 20 | nét | 霰 | tản | tượng hình | hạt tuyết nhỏ, tuyết hạt cứng | 霰 thuộc bộ 雨 (vũ — mưa), chỉ loại mưa đặc biệt — hạt tuyết nhỏ cứng (snow pellets). Wiktionary chỉ ghi {{Han etym}}, chưa phân tích cấu trúc nội tại. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tản\" (霰): bộ 雨 (mưa) — hạt tuyết nhỏ tản mát xuống như muối trắng, vừa cứng vừa lăn. | Gương Hán-Việt | 霰雪 (tản tuyết) — tuyết hạt | Mở khoá kiến thức | Biết 霰 mở khoá: 霰雪 (tuyết hạt), 飞霰 (hạt tuyết bay), 冰霰 (hạt băng tuyết nhỏ).", "Tự nguyên_Xie": "霰 (sǎn) chỉ hạt tuyết nhỏ cứng (snow pellets/graupel) — khác với tuyết bông (雪) mềm và mưa đá (冰雹) lớn. Chữ thuộc bộ 雨 (mưa). Wiktionary chỉ ghi {{Han etym}}, chưa có phân tích cấu trúc. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt tuyết", "Hạng Tần Suất (Jun Da)": "4701.0", "Tần Suất % (Jun Da)": "99.8887408116", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 散", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨散", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "散", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霰", "Unihan_Traditional (Chữ Phồn thể)": "霰", "Pinyin_Xie": "sǎn", "Âm Hán Việt_Xie": "tản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ hiện tượng thời tiết hạt tuyết nhỏ rơi xuống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飨', '{"9000": "4702.0", "Chữ Trung Quốc": "飨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 飨 | hưởng | tượng hình | thết đãi long trọng, tế lễ tập thể | 飨 là dạng giản thể của 饗. Thuộc bộ 食 (thực — thức ăn). Wiktionary chỉ ghi {{Han etym}}, chưa có phân tích cấu trúc chi tiết. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hưởng\" (飨宴): bộ 食 (ăn) — thết đãi long trọng là để mọi người cùng được hưởng (享/飨) thức ăn ngon. | Gương Hán-Việt | 飨宴 (hưởng yến) — yến tiệc long trọng; 飨士 (hưởng sĩ) — thết đãi quân sĩ | Mở khoá kiến thức | Biết 飨 mở khoá: 飨宴 (yến tiệc), 飨士 (thết đãi binh sĩ), 飨祭 (tế lễ tập thể).", "Tự nguyên_Xie": "飨 (xiǎng), dạng phồn thể 饗, theo Wiktionary thuộc bộ 食 (ăn). Nghĩa gốc là tổ chức yến tiệc long trọng, thết đãi khách hoặc tổ chức tế lễ tập thể. Xuất hiện trong 飨宴 (yến tiệc long trọng), 飨士 (thết đãi binh sĩ). Chữ cổ, dùng trong văn ngôn và lễ nghi. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thết đãi long trọng; tế tập thể", "Hạng Tần Suất (Jun Da)": "4702.0", "Tần Suất % (Jun Da)": "99.8888674239", "GavinGrover_Once (Chiết tự trực tiếp)": "乡 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰乡食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "飨", "Unihan_Traditional (Chữ Phồn thể)": "饗", "Pinyin_Xie": "xiǎng", "Âm Hán Việt_Xie": "hưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ việc dâng cúng lễ vật lên thần linh hoặc thiết đãi khách quý. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揄', '{"9000": "4703.0", "Chữ Trung Quốc": "揄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | biểu nghĩa | tay | 俞 | du | biểu âm | thành phần biểu âm | 揄 = 扌 (biểu nghĩa: tay) + 俞 (Du, biểu âm); chữ hình thanh. Bộ 扌 (tay) chỉ hành động dùng tay kéo/dắt, 俞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\" (揶揄): 扌(tay) + 俞 (du — biểu âm) — dùng tay kéo kéo chọc ghẹo (揶揄) người ta như trò đùa. | Gương Hán-Việt | 揶揄 (gia du) — diễu cợt, chọc ghẹo; 揄扬 (du dương) — ca ngợi tán dương | Mở khoá kiến thức | Biết 揄 mở khoá: 揶揄 (diễu cợt), 揄扬 (ca ngợi), 揄袂 (vung tay áo).", "Tự nguyên_Xie": "揄 (yú) theo Wiktionary là chữ hình thanh: 手 (thủ — tay, biểu nghĩa, dạng biến 扌) + 俞 (du — biểu âm). Nghĩa chính trong văn cổ là kéo lấy, nâng lên, múc ra. Thành ngữ 揶揄 (diễu cợt, chọc ghẹo). Còn dùng trong 揄扬 (ca ngợi, tán dương). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dắt, kéo", "Hạng Tần Suất (Jun Da)": "4703.0", "Tần Suất % (Jun Da)": "99.8889935195", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揄", "Unihan_Traditional (Chữ Phồn thể)": "揄", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thường dùng trong văn cổ với nghĩa dắt kéo hoặc khen ngợi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噔', '{"9000": "4704.0", "Chữ Trung Quốc": "噔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 噔 | đằng | tượng hình | tiếng thình thịch, huỳnh huỵch (từ tượng thanh) | 噔 thuộc bộ 口 (khẩu), chủ yếu là chữ tượng thanh mô tả tiếng va đập nặng nề. Chữ hiện đại, không có nguồn Wiktionary. Chưa có phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\" (噔噔): bộ 口 (miệng/âm thanh) — tiếng chân bước nặng đằng đằng: 噔噔噔 bước lên cầu thang. | Gương Hán-Việt | 噔噔 (đằng đằng) — tiếng thình thịch bước chân | Mở khoá kiến thức | Biết 噔 mở khoá: 噔噔 (tiếng bước chân nặng), 噔地一声 (một tiếng thình), 噔噔噔 (bước chân liên tiếp).", "Tự nguyên_Xie": "噔 (dēng) là chữ bạch thoại tượng thanh, mô tả tiếng va chạm nặng, tiếng bước chân nặng nề: thình thịch, huỳnh huỵch. Chữ tạo muộn, không có nguồn học thuật từ Wiktionary. Dùng trong: 噔噔 (tiếng bước chân thình thịch), 噔地一声 (một tiếng huỳnh huỵch). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thình thịch, huỳnh huỵch", "Hạng Tần Suất (Jun Da)": "4704.0", "Tần Suất % (Jun Da)": "99.8891196151", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噔", "Unihan_Traditional (Chữ Phồn thể)": "噔", "Pinyin_Xie": "dēng", "Âm Hán Việt_Xie": "đăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Dùng làm từ tượng thanh mô phỏng tiếng động trầm đục như tiếng bước chân hoặc tiếng gõ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娣', '{"9000": "4705.0", "Chữ Trung Quốc": "娣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 弟 | đệ | biểu âm | em trai — thành viên nhỏ trong gia đình | 娣 = 女 (Nữ, biểu nghĩa: phụ nữ) + 弟 (Đệ, biểu âm — cũng gợi ý ý nghĩa em nhỏ trong gia đình); có thể đọc là hội ý hoặc hình thanh. Chữ chỉ người em dâu — người phụ nữ nhỏ hơn trong gia đình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đệ\" (娣): 女 (nữ) + 弟 (đệ — em) — em dâu là người phụ nữ (女) giữ vai trò em (弟) trong gia đình chồng. | Gương Hán-Việt | 娣妇 (đệ phụ) — em dâu; 姒娣 (tự đệ) — chị dâu em dâu | Mở khoá kiến thức | Biết 娣 mở khoá: 娣妇 (em dâu), 姒娣 (chị dâu và em dâu — người phụ nữ cùng giá trị trong gia đình).", "Tự nguyên_Xie": "娣 (dì) theo Wiktionary là chữ hội ý/hình thanh: 女 (nữ — phụ nữ) + 弟 (đệ — em trai, thành viên nhỏ hơn trong gia đình). Nghĩa là em dâu (em vợ hoặc vợ của em chồng). Bộ 女 biểu nghĩa giới tính, 弟 vừa biểu âm vừa gợi ý vai vế nhỏ hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "em dâu", "Hạng Tần Suất (Jun Da)": "4705.0", "Tần Suất % (Jun Da)": "99.8892457106", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娣", "Unihan_Traditional (Chữ Phồn thể)": "娣", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ người em dâu hoặc em gái của vợ trong gia đình truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薏', '{"9000": "4706.0", "Chữ Trung Quốc": "薏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艹 | biểu nghĩa | cỏ, thực vật | 意 | ý | biểu âm | thành phần biểu âm | 薏 = 艹 (biểu nghĩa: cỏ/thực vật) + 意 (Ý, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loài cỏ/cây, 意 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"é\" (薏苡): 艹 (cỏ) + 意 (ý — biểu âm) — hạt ý dĩ (薏苡) nhỏ xinh như những hạt ý tưởng sáng tạo. | Gương Hán-Việt | 薏苡 (é dĩ) — ý dĩ, bo bo; 薏仁 (é nhân) — hạt bo bo | Mở khoá kiến thức | Biết 薏 mở khoá: 薏苡 (ý dĩ/bo bo), 薏仁 (hạt bo bo), 薏米 (gạo bo bo), 薏苡之谤 (điển tích vu khống).", "Tự nguyên_Xie": "薏 (yì) theo Wiktionary là chữ hình thanh: 艸 (thảo — cỏ, biểu nghĩa, dạng biến 艹) + 意 (ý — biểu âm). Nghĩa gốc là hạt nhân hoa sen. Phổ biến hơn trong từ 薏苡 (ý dĩ) hay 薏仁/薏米 — hạt bo bo dùng làm thực phẩm và thuốc. 薏苡之谤 là điển tích về sự vu khống sai lầm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ý dĩ 薏苡)", "Hạng Tần Suất (Jun Da)": "4706.0", "Tần Suất % (Jun Da)": "99.8893712894", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 意", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹意", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "意", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薏", "Unihan_Traditional (Chữ Phồn thể)": "薏", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ thường dùng trong tên gọi của cây ý dĩ, một loại thảo dược. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忝', '{"9000": "4707.0", "Chữ Trung Quốc": "忝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 天 | thiên | biểu âm | thành phần biểu âm | 心 | tâm | biểu nghĩa | tâm, lòng | 忝 = 天 (Thiên, biểu âm) + 心 (Tâm, biểu nghĩa: tâm/lòng); chữ hình thanh. Bộ 心 gợi ý trạng thái tâm lý (xấu hổ/nhục), 天 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỏm\" (忝列): 心 (lòng) + 天 (biểu âm) — lòng thấy nhục (忝) vì biết mình chưa xứng với vị trí dưới trời (天). | Gương Hán-Việt | 忝列 (thỏm liệt) — thẹn thùng được liệt vào; 忝居 (thỏm cư) — thẹn đang giữ vị trí | Mở khoá kiến thức | Biết 忝 mở khoá: 忝列 (khiêm tốn nói mình được xếp vào), 忝居 (khiêm tốn nói mình đang ở vị trí nào đó).", "Tự nguyên_Xie": "忝 (tiǎn) theo Wiktionary là chữ hình thanh: 天 (thiên — biểu âm) + 心 (tâm — lòng/tâm hồn, biểu nghĩa). Nghĩa là nhục nhã, xấu hổ — thường dùng theo cách tự khiêm: 忝列 (thẹn thùng được xếp vào), 忝居 (thẹn thùng đang ở vị trí). Là cách nói khiêm tốn trong văn cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "158.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thiên (20) Tâm (148)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thiên (số 20) ở trên chữ Tâm (số 148) . Kẻ trong lòng thấy thẹn nhục thì muốn lẩn tránh, không muốn cho thiên hạ thấy mình. Giải thích sự chuyển ý: Chữ Thiên (trời) chỉ âm, chữ Tâm (lòng) chỉ ý. Làm việc trái với lương tâm (Tâm) và đạo lý của trời (Thiên) thì sẽ cảm thấy thẹn thùng, xấu hổ (Thiểm). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Thiên và chữ Thiểm có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Thiên và Thiểm).*", "Nghĩa Tiếng Việt_Xie": "nhục", "Hạng Tần Suất (Jun Da)": "4707.0", "Tần Suất % (Jun Da)": "99.8894968682", "GavinGrover_Once (Chiết tự trực tiếp)": "天 + 㣺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱天㣺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㣺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "天", "Unihan_Simplified (Chữ Giản thể)": "忝", "Unihan_Traditional (Chữ Phồn thể)": "忝", "Pinyin_Xie": "tiǎn", "Âm Hán Việt_Xie": "thiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Thường dùng làm phó từ đặt trước động từ để biểu thị sự khiêm tốn, tự hổ thẹn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咤', '{"9000": "4708.0", "Chữ Trung Quốc": "咤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 乇 | biểu âm | thành phần biểu âm | 咤 = 口 (Khẩu, biểu nghĩa: miệng) + 乇 (biểu âm); chữ hình thanh. Bộ 口 chỉ âm thanh từ miệng (tiếng quát/than), 乇 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\" (叱咤): 口 (miệng) + 乇 (biểu âm) — tiếng quát lớn như Na Tra (哪吒) ra oai trên chiến trường. | Gương Hán-Việt | 叱咤 (sất tra) — quát tháo, ra oai; 哪咤 (Na Tra) — nhân vật thần thoại | Mở khoá kiến thức | Biết 咤 mở khoá: 叱咤风云 (làm mưa làm gió), 哪咤 (Na Tra), 咤嗟 (tiếng than thở kêu trời).", "Tự nguyên_Xie": "咤 (zhà), dạng cổ là 吒, theo Wiktionary là chữ hình thanh: 口 (khẩu — miệng, biểu nghĩa) + 乇 (biểu âm). Nghĩa gốc là quát mắng, la hét lớn tiếng, tiếng thở than. Nổi tiếng trong tên nhân vật thần thoại 哪吒/哪咤 (Na Tra). Trong 叱咤 (quát tháo, ra oai). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng than thở", "Hạng Tần Suất (Jun Da)": "4708.0", "Tần Suất % (Jun Da)": "99.889622447", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 宅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口宅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咤", "Unihan_Traditional (Chữ Phồn thể)": "咤", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc kết hợp thành từ ghép để chỉ hành động than thở hoặc quát tháo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗵', '{"9000": "4709.0", "Chữ Trung Quốc": "嗵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗵 | thông | tượng hình | tiếng thình thình, thịch thịch (tượng thanh) | 嗵 thuộc bộ 口 (khẩu), là chữ tượng thanh hiện đại mô tả tiếng va đập nặng. Chữ tạo muộn, không có nguồn Wiktionary. Chưa có phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\" (嗵嗵): bộ 口 (âm thanh) — tiếng đập thình thình vang lên như trống trận THÔNG THÔNG THÔNG. | Gương Hán-Việt | 嗵嗵 (thông thông) — tiếng thình thình liên tục | Mở khoá kiến thức | Biết 嗵 mở khoá: 嗵嗵 (tiếng thình thình), 嗵地一声 (một tiếng thịch).", "Tự nguyên_Xie": "嗵 (tōng) là chữ bạch thoại tượng thanh, mô tả tiếng nặng đập xuống: thình thình, thịch thịch. Chữ tạo muộn, không có nguồn Wiktionary. Bộ 口 biểu thị đây là âm thanh. Thường viết lặp 嗵嗵 để mô tả tiếng đập liên tục. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thình thình; thình thịch (từ tượng thanh)", "Hạng Tần Suất (Jun Da)": "4709.0", "Tần Suất % (Jun Da)": "99.889747509", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 通", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口通", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "通", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗵", "Unihan_Traditional (Chữ Phồn thể)": "嗵", "Pinyin_Xie": "tōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Dùng làm từ tượng thanh mô phỏng tiếng vật nặng rơi hoặc tiếng trống đánh liên tiếp. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迤', '{"9000": "4710.0", "Chữ Trung Quốc": "迤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迤 | di | tượng hình | thế đất quanh co, kéo dài theo hướng xiên | 迤 thuộc bộ 辵 (着 — đi, vận động), gợi ý sự di chuyển theo đường quanh co. Wiktionary có mục nhưng không phân tích cấu trúc hình thanh/hội ý cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\" (逶迤): bộ 辵 (vận động) — con đường di di uốn lượn theo sườn núi như dòng sông quanh co. | Gương Hán-Việt | 逶迤 (uy di) — kéo dài uốn lượn | Mở khoá kiến thức | Biết 迤 mở khoá: 逶迤 (uốn lượn dài dằng dặc), 迤逦 (uốn khúc liên miên), 坦迤 (rộng phẳng trải dài).", "Tự nguyên_Xie": "迤 (yí/yǐ) theo Wiktionary có nghĩa kéo dài theo hướng nghiêng xiên, uốn lượn. Trong thành ngữ 逶迤 (uyên di — kéo dài uốn lượn), chỉ núi non, đường sá uốn khúc liên miên. Còn có âm yǐ với nghĩa hướng về phía. Chưa có phân tích cấu trúc nội tại chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thế đất quanh co", "Hạng Tần Suất (Jun Da)": "4710.0", "Tần Suất % (Jun Da)": "99.889872571", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迤", "Unihan_Traditional (Chữ Phồn thể)": "迤", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di, dĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả địa hình quanh co hoặc kết hợp trong từ ghép chỉ sự kéo dài liên tiếp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贲', '{"9000": "4711.0", "Chữ Trung Quốc": "贲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 9 | nét | 卉 | 훼 | biểu âm | thành phần biểu âm | 貝 | bối | biểu nghĩa | vỏ sò — tượng trưng cho của cải, trang sức | 贲 = 卉 (biểu âm) + 貝 (Bối, biểu nghĩa: vỏ sò/trang sức quý); chữ hình thanh. Bộ 貝 gợi ý vẻ rực rỡ như trang sức quý, 卉 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\" (贲卦): 貝 (vỏ sò rực rỡ) + 卉 (biểu âm) — sự rực rỡ lộng lẫy như vỏ sò óng ánh trong Kinh Dịch. | Gương Hán-Việt | 贲卦 (bí quái) — quẻ Bí trong Kinh Dịch; 贲然 (bí nhiên) — rực rỡ, huy hoàng | Mở khoá kiến thức | Biết 贲 mở khoá: 贲卦 (quẻ Bí — Kinh Dịch), 贲然 (rực rỡ), 虎贲 (hổ bôn — lính tinh nhuệ mạnh mẽ).", "Tự nguyên_Xie": "贲 (bēn/bì), dạng phồn thể 賁, theo Wiktionary là chữ hình thanh: 卉 (biểu âm, đọc bì *prals) + 貝 (bối — vỏ sò/của cải, biểu nghĩa). Nghĩa gốc là rực rỡ, sáng sủa — như trang sức vỏ sò rực rỡ. Âm bēn (*pɯːn) mượn từ từ đồng âm 奔 (chạy). Dùng làm quẻ trong Kinh Dịch: quẻ Bí (賁卦). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rực rỡ, sáng sủa", "Hạng Tần Suất (Jun Da)": "4711.0", "Tần Suất % (Jun Da)": "99.889997633", "GavinGrover_Once (Chiết tự trực tiếp)": "十 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "贲", "Unihan_Traditional (Chữ Phồn thể)": "賁", "Pinyin_Xie": "bēn", "Âm Hán Việt_Xie": "bôn, bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm định ngữ để chỉ sự rực rỡ, long trọng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胪', '{"9000": "4712.0", "Chữ Trung Quốc": "胪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胪 | lư | tượng hình | bày xếp, liệt kê; bụng trước | 胪 là dạng giản thể của 臚. Thuộc bộ 肉 (月旁), gợi ý bụng/cơ thể. Wiktionary có mục 臚 với nghĩa bụng, da, bày xếp, liệt kê nhưng không phân tích cấu trúc hình thanh/hội ý chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\" (鸿胪): bộ 肉/月 (cơ thể) — 鸿胪寺 là cơ quan ngoại giao, bày xếp (胪) lễ nghi tiếp đón khách nước ngoài. | Gương Hán-Việt | 鸿胪寺 (hồng lư tự) — cơ quan ngoại giao triều đình; 胪传 (lư truyền) — xướng danh | Mở khoá kiến thức | Biết 胪 mở khoá: 鸿胪寺 (Hồng Lư Tự), 胪列 (liệt kê), 胪传 (xướng danh thi cử), 胪陈 (trình bày).", "Tự nguyên_Xie": "胪 (lú), dạng phồn thể 臚, theo Wiktionary chỉ bụng trước, da, và hành động bày xếp liệt kê. Dùng trong: 臚传/臚唱 (xướng danh to — lệ thi cử cổ), 鸿胪寺 (Hồng Lư Tự — cơ quan ngoại giao triều đình), 臚列 (liệt kê bày ra), 臚陈 (trình bày). Chưa có phân tích cấu trúc chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bày xếp; truyền, gọi; bụng trước", "Hạng Tần Suất (Jun Da)": "4712.0", "Tần Suất % (Jun Da)": "99.890122695", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胪", "Unihan_Traditional (Chữ Phồn thể)": "臚", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước danh từ để chỉ việc trình bày hoặc liệt kê sự việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍪', '{"9000": "4713.0", "Chữ Trung Quốc": "鍪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 敄 | biểu âm | thành phần biểu âm | 金 | kim | biểu nghĩa | kim loại | 鍪 = 敄 (biểu âm) + 金 (Kim, biểu nghĩa: kim loại); chữ hình thanh. Bộ 金 chỉ vật bằng kim loại (mũ sắt/nồi sắt), 敄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mâu\" (兜鍪): 金 (kim loại) + 敄 (biểu âm) — chiếc mũ sắt (兜鍪) bảo vệ đầu chiến binh dũng mãnh trên chiến trường. | Gương Hán-Việt | 兜鍪 (đâu mâu) — mũ giáp sắt của chiến binh | Mở khoá kiến thức | Biết 鍪 mở khoá: 兜鍪 (mũ giáp sắt), 兜鍪铁甲 (mũ giáp sắt toàn bộ).", "Tự nguyên_Xie": "鍪 (móu) theo Wiktionary là chữ hình thanh: 敄 (biểu âm) + 金 (kim — kim loại, biểu nghĩa). Nghĩa là nồi sắt nhỏ, và đặc biệt là mũ sắt chiến đấu. Thường gặp trong từ 兜鍪 (đâu mâu — mũ giáp sắt của chiến binh cổ đại). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đâu mâu 兜鍪)", "Hạng Tần Suất (Jun Da)": "4713.0", "Tần Suất % (Jun Da)": "99.890247757", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍪", "Unihan_Traditional (Chữ Phồn thể)": "鍪", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ loại mũ hoặc dùng trong từ ghép để chỉ mũ giáp quân đội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泸', '{"9000": "4714.0", "Chữ Trung Quốc": "泸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泸 | lư | tượng hình | tên sông ở tỉnh Giang Tây | 泸 là dạng giản thể của 瀘. Thuộc bộ 水 (thủy — nước), chỉ địa danh sông ngòi. Wiktionary ghi là giản thể hóa từ 瀘 (f=盧→t=卢). Chưa có phân tích cấu trúc độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\" (泸州): bộ 水 (nước/sông) — 泸州 là thành phố bên sông Lư, nổi tiếng với rượu Lư Châu Lão Giáo. | Gương Hán-Việt | 泸州 (Lư Châu) — thành phố ở Tứ Xuyên; 泸水 (Lư Thủy) — tên sông | Mở khoá kiến thức | Biết 泸 mở khoá: 泸州 (Lư Châu — thành phố), 泸水 (Lư Thủy — sông), 泸州老窖 (rượu Lư Châu Lão Giáo).", "Tự nguyên_Xie": "泸 (lú) là dạng giản thể của 瀘, theo Wiktionary giản hóa bộ phận 盧 thành 卢. Tên một dòng sông ở tỉnh Giang Tây và Tứ Xuyên, Trung Quốc. Cũng là tên của địa danh 泸州 (Lư Châu — thành phố ở Tứ Xuyên), nổi tiếng với rượu Lư Châu Lão Giáo. Chưa có phân tích cấu trúc nội tại chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên sông)", "Hạng Tần Suất (Jun Da)": "4714.0", "Tần Suất % (Jun Da)": "99.890372819", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泸", "Unihan_Traditional (Chữ Phồn thể)": "瀘", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng đứng trước các từ chỉ sông ngòi hoặc địa danh để định danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔫', '{"9000": "4715.0", "Chữ Trung Quốc": "蔫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | biểu nghĩa | cỏ, thực vật | 焉 | yên | biểu âm | thành phần biểu âm | 蔫 = 艹 (biểu nghĩa: cỏ/thực vật) + 焉 (Yên, biểu âm); chữ hình thanh. Bộ 艹 chỉ thực vật, 焉 cho âm đọc. Nghĩa là héo tàn, ủ rũ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yên\" (蔫): 艹 (cỏ) + 焉 (yên — biểu âm) — cây héo ủ rũ yên lặng như 焉 đứng im không cựa quậy. | Gương Hán-Việt | 蔫头耷脑 (yên đầu đáp não) — đầu rũ ủ rũ | Mở khoá kiến thức | Biết 蔫 mở khoá: 蔫头耷脑 (ủ rũ thiếu sinh khí), 蔫坏 (hiền lành bề ngoài nhưng thực xấu xa), 蔫了 (héo rồi, ủ rũ rồi).", "Tự nguyên_Xie": "蔫 (niān) theo Wiktionary là chữ hình thanh: 艸 (thảo — cỏ/thực vật, biểu nghĩa, dạng biến 艹) + 焉 (yên — biểu âm). Nghĩa gốc là cây héo tàn, rũ xuống. Nghĩa mở rộng chỉ người ủ rũ, thiếu sinh khí. Thường dùng trong: 蔫头耷脑 (rũ đầu ủ tai — vẻ mệt mỏi ủ rũ), 蔫坏 (tuy vẻ hiền lành nhưng thực ra xấu xa). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "héo (cây); ủ rũ", "Hạng Tần Suất (Jun Da)": "4715.0", "Tần Suất % (Jun Da)": "99.8904973642", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 焉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹焉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔫", "Unihan_Traditional (Chữ Phồn thể)": "蔫", "Pinyin_Xie": "niān", "Âm Hán Việt_Xie": "yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng sau danh từ để miêu tả trạng thái héo úa của hoa cỏ hoặc tinh thần con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刈', '{"9000": "4716.0", "Chữ Trung Quốc": "刈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 4 | nét | 乂 | biểu âm | thành phần biểu âm/ý nghĩa — lưỡi hái | 刀 | đao | biểu nghĩa | dao, lưỡi cắt | 刈 = 乂 (biểu âm, cũng gợi ý hình ảnh lưỡi hái) + 刂/刀 (Đao, biểu nghĩa: dao); có thể xem là hình thanh kết hợp hội ý. Bộ 刀 (đao) và 乂 cùng gợi ý hành động cắt cỏ bằng lưỡi hái.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\" (刈草): 刀 (dao) + 乂 (lưỡi hái) — lưỡi dao hái cắt cỏ nghệ thuật: một nhát thẳng như nghiệt. | Gương Hán-Việt | 刈草 (nghệ thảo) — cắt cỏ; 刈获 (nghệ hoạch) — gặt hái thu hoạch | Mở khoá kiến thức | Biết 刈 mở khoá: 刈草 (cắt cỏ), 刈获 (thu hoạch), 刈麦 (gặt lúa mì).", "Tự nguyên_Xie": "刈 (yì) theo Wiktionary vốn viết là 乂, sau thêm bộ 刀 (đao — dao/lưỡi cắt). Chữ 乂 vốn dĩ đã mang hình ảnh lưỡi hái, nên 刀 thêm vào vừa biểu nghĩa vừa cụ thể hóa nghĩa cắt cỏ. Nghĩa là cắt cỏ, gặt lúa, cắt bằng lưỡi hái. Dùng trong: 刈草 (cắt cỏ), 刈获 (thu hoạch gặt hái). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt cỏ", "Hạng Tần Suất (Jun Da)": "4716.0", "Tần Suất % (Jun Da)": "99.8906219095", "GavinGrover_Once (Chiết tự trực tiếp)": "乂 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰乂刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刈", "Unihan_Traditional (Chữ Phồn thể)": "刈", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ngải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ đứng trước danh từ chỉ cây cỏ, lúa má để biểu thị hành động cắt, gặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僖', '{"9000": "4717.0", "Chữ Trung Quốc": "僖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 人 | nhân | biểu nghĩa | người | 喜 | hỷ | biểu âm | thành phần biểu âm | 僖 = 人/亻 (Nhân, biểu nghĩa: người) + 喜 (Hỷ, biểu âm); chữ hình thanh. Bộ 人 chỉ đây là trạng thái của người, 喜 cho âm đọc và gợi ý nghĩa vui mừng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hi\" (僖): 亻(người) + 喜 (hỷ — vui) — người tràn đầy niềm vui hớn hở, như thụy hiệu Hi Công. | Gương Hán-Việt | 鲁僖公 (Lỗ Hi Công) — thụy hiệu vua Lỗ | Mở khoá kiến thức | Biết 僖 mở khoá: 鲁僖公 (Lỗ Hi Công — vua nước Lỗ), 晋僖公 (Tấn Hi Công).", "Tự nguyên_Xie": "僖 (xī) theo Wiktionary là chữ hình thanh: 人 (nhân — người, biểu nghĩa) + 喜 (hỷ — vui mừng, biểu âm). Nghĩa là vui mừng, hớn hở. Dùng làm thụy hiệu vua chúa: 鲁僖公 (Lỗ Hi Công). Cũng dùng làm tên người. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui mừng; vui vẻ", "Hạng Tần Suất (Jun Da)": "4717.0", "Tần Suất % (Jun Da)": "99.8907464547", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 喜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻喜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僖", "Unihan_Traditional (Chữ Phồn thể)": "僖", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả tâm trạng vui vẻ hoặc dùng làm thụy hiệu trong tên riêng của vua chúa thời xưa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咿', '{"9000": "4718.0", "Chữ Trung Quốc": "咿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 伊 | y | biểu âm | thành phần biểu âm | 咿 = 口 (Khẩu, biểu nghĩa: miệng) + 伊 (Y, biểu âm); chữ hình thanh. Bộ 口 chỉ âm thanh từ miệng, 伊 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\" (咿喔): 口 (miệng) + 伊 (y — biểu âm) — tiếng \"y ốc\" gà gáy sáng, hay tiếng đọc sách lao xao \"y ô\" trong lớp học. | Gương Hán-Việt | 咿喔 (y ốc) — tiếng gà gáy; 咿哦 (y ô) — tiếng đọc sách lao xao | Mở khoá kiến thức | Biết 咿 mở khoá: 咿喔 (tiếng gà), 咿哦 (tiếng đọc sách), 咿咿呀呀 (tiếng tập nói của em bé).", "Tự nguyên_Xie": "咿 (yī) theo Wiktionary là chữ hình thanh: 口 (khẩu — miệng, biểu nghĩa) + 伊 (y — biểu âm). Chủ yếu dùng trong từ 咿喔 (y ốc — tiếng gà trống gáy) và 咿哦 (y ô — tiếng lao xao đọc sách). Cũng mô tả tiếng cọ kẽo kẹt của xe gỗ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: y ốc 咿喔)", "Hạng Tần Suất (Jun Da)": "4718.0", "Tần Suất % (Jun Da)": "99.8908709999", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 伊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口伊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咿", "Unihan_Traditional (Chữ Phồn thể)": "吚", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường kết hợp với các từ tượng thanh khác để mô tả tiếng trẻ con khóc cười hoặc tiếng động cơ, chèo thuyền. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹌', '{"9000": "4719.0", "Chữ Trung Quốc": "鹌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 奄 | ăm | biểu âm | thành phần biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鹌 = 奄 (Ăm, biểu âm) + 鳥/鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鳥 chỉ đây là loài chim, 奄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ám\" (鹌鹑): 鳥 (chim) + 奄 (biểu âm) — chim cút nhỏ ám mình trong cỏ (奄 — che phủ), khó phát hiện. | Gương Hán-Việt | 鹌鹑 (ám thuần) — chim cút | Mở khoá kiến thức | Biết 鹌 mở khoá: 鹌鹑 (chim cút), 鹌鹑蛋 (trứng cút), 鹌鹑肉 (thịt chim cút).", "Tự nguyên_Xie": "鹌 (ān), dạng phồn thể 鵪, theo Wiktionary là chữ hình thanh: 奄 (ăm — biểu âm) + 鳥 (điểu — chim, biểu nghĩa). Nghĩa là chim cút (Coturnix coturnix) — loài chim nhỏ sống trong đồng ruộng. Dùng trong từ 鹌鹑 (ān chún — chim cút). Chim cút nổi tiếng trong văn hóa Trung Hoa vì trứng và thịt ngon. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim cút", "Hạng Tần Suất (Jun Da)": "4719.0", "Tần Suất % (Jun Da)": "99.8909955451", "GavinGrover_Once (Chiết tự trực tiếp)": "奄 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰奄鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹌", "Unihan_Traditional (Chữ Phồn thể)": "鵪", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và chủ yếu xuất hiện trong từ ghép chỉ loài chim cút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗪', '{"9000": "4720.0", "Chữ Trung Quốc": "嗪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗪 | tần | tượng hình | âm tiết phiên dịch, chứa miệng 口 gợi phát âm | 嗪 là chữ tạo muộn, dùng để phiên âm tên hoá học (đặc biệt trong tên vòng pyrazine, piperazine). Không có phân tích hình-thanh hay hội-ý rõ ràng từ nguồn học thuật; chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tần\": miệng (口) phát ra âm thanh xa lạ — chữ dùng để phiên dịch tên hóa học như piperazine. | Gương Hán-Việt | tần — hiếm dùng độc lập, thường xuất hiện trong tên hóa học phiên âm | Mở khoá kiến thức | Biết 嗪 giúp nhận ra các tên hóa học vòng nitơ trong tiếng Trung như 哌嗪, 吡嗪.", "Tự nguyên_Xie": "嗪 không có nguồn glyph-origin từ Wiktionary. Chữ chứa bộ 口 (khẩu), gợi liên quan đến âm thanh hoặc lời nói. Chủ yếu dùng làm yếu tố phiên âm trong tên hoá học tiếng Trung như 哌嗪 (piperazine), 吡嗪 (pyrazine). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm đọc; chữ dùng để dịch âm", "Hạng Tần Suất (Jun Da)": "4720.0", "Tần Suất % (Jun Da)": "99.8911195735", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 秦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口秦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗪", "Unihan_Traditional (Chữ Phồn thể)": "嗪", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "tần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong các thuật ngữ hóa học dịch âm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茏', '{"9000": "4721.0", "Chữ Trung Quốc": "茏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 龍 | long | biểu âm | (cho âm) | 茏 = 艸 (Tháu, biểu nghĩa: cỏ/thực vật) + 龍 (Long, biểu âm). Chữ hình thanh: bộ 艸 chỉ thực vật, 龍 cho âm đọc lóng. Dạng cổ viết 蘢.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\" (theo âm 龍/long): cỏ (艸) sum sê như rồng (龍) cuộn xanh — hình ảnh thảm thực vật rậm rạp. | Gương Hán-Việt | lung — ít dùng độc lập, thường trong 蔥茏 (sum sê xanh tươi) | Mở khoá kiến thức | Biết 茏 giúp đọc các từ thơ ca cổ điển miêu tả thiên nhiên xanh mướt như 蔥茏, 茏蓯.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 茏 (dạng cổ 蘢) là chữ hình thanh: bộ 艸 (tháu) biểu nghĩa ''cỏ/thực vật'', thành phần 龍 (long) cho âm. Chữ dùng trong từ ghép 蔥蘢 (sum sê, xanh tươi) và 蘢蔥 (cây cỏ tốt tươi). Mang nghĩa cỏ mọc cao, rậm rạp, xanh mướt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sum sê, xanh tươi, tốt tươi", "Hạng Tần Suất (Jun Da)": "4721.0", "Tần Suất % (Jun Da)": "99.8912430852", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茏", "Unihan_Traditional (Chữ Phồn thể)": "蘢", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ mô tả cây cối xanh tươi hoặc làm danh từ chỉ một loại cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茯', '{"9000": "4722.0", "Chữ Trung Quốc": "茯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茯 | phục | tượng hình | nấm phục linh mọc ngầm dưới đất, bộ 艸 gợi thực vật | 茯 có bộ 艸 (tháu) biểu nghĩa thực vật, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Chữ chủ yếu xuất hiện trong từ 茯苓 (phục linh) — loại nấm dược liệu quý. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": nấm (艸) phục (茯) linh — ẩn dưới đất như ''nằm phục'', chính là vị thuốc quý phục linh. | Gương Hán-Việt | phục — trong ''phục linh'' (茯苓), vị thuốc bổ dưỡng nổi tiếng | Mở khoá kiến thức | Biết 茯 giúp nhận diện vị thuốc 茯苓 (phục linh) trong các bài thuốc y học cổ truyền.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 茯 chỉ được dùng trong từ 茯苓 (phục linh, china root) — loại nấm dược liệu quan trọng trong y học cổ truyền Trung Hoa. Bộ 艸 gợi liên quan đến thực vật/nấm, nhưng cấu trúc chi tiết không được ghi chép rõ ràng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phục linh 茯苓)", "Hạng Tần Suất (Jun Da)": "4722.0", "Tần Suất % (Jun Da)": "99.8913665968", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 伏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹伏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茯", "Unihan_Traditional (Chữ Phồn thể)": "茯", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép chỉ vị thuốc phục linh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岫', '{"9000": "4723.0", "Chữ Trung Quốc": "岫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 山 | sơn | biểu nghĩa | núi | 由 | do | biểu âm | (cho âm) | 岫 = 山 (Sơn, biểu nghĩa: núi) + 由 (Do, biểu âm). Chữ hình thanh: bộ 山 chỉ địa hình núi, thành phần 由 cho âm xiù. Nghĩa gốc là đỉnh núi hoặc hang động trong núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụ\" (theo nghĩa từ 由): núi (山) có lối vào bên trong — hình ảnh hang động ẩn sâu trong vách núi. | Gương Hán-Việt | tụ — ít dùng trong tiếng Việt hiện đại, thường trong cụm 岫幌 (bức rèm hang động) trong thơ cổ | Mở khoá kiến thức | Biết 岫 giúp đọc thơ cổ điển Trung Hoa miêu tả cảnh núi non như 出岫 (mây bay ra từ núi), 山岫 (hang núi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 岫 là chữ hình thanh: 山 (sơn, núi) biểu nghĩa, 由 (do) cho âm. Mang nghĩa đỉnh núi, hang núi. Trong phương ngữ Mân Nam còn dùng với nghĩa ''tổ, hang ổ của thú vật''. Chữ xuất hiện nhiều trong thơ văn cổ điển miêu tả phong cảnh thiên nhiên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hang núi; ngọn núi tròn", "Hạng Tần Suất (Jun Da)": "4723.0", "Tần Suất % (Jun Da)": "99.8914901085", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岫", "Unihan_Traditional (Chữ Phồn thể)": "岫", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hang động hoặc đỉnh núi trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵘', '{"9000": "4724.0", "Chữ Trung Quốc": "嵘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 山 | sơn | biểu nghĩa | núi | 榮 | vinh | biểu âm | (cho âm) | 嵘 = 山 (Sơn, biểu nghĩa: núi) + 榮 (Vinh, biểu âm). Chữ hình thanh: bộ 山 chỉ núi non, thành phần 榮 cho âm róng. Dạng cổ viết 嶸.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vanh\" (theo âm 榮): núi (山) vươn cao như 荣/vinh — hình ảnh đỉnh núi chọc trời, sừng sững. | Gương Hán-Việt | vanh — thường gặp trong 崢嶸 (tranh vanh) miêu tả núi hiểm trở hoặc thời kỳ gian khổ | Mở khoá kiến thức | Biết 嵘 giúp hiểu 崢嶸岁月 (những tháng năm gian khó nhưng đáng nhớ) — thành ngữ phổ biến.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 嵘 (dạng cổ 嶸) là chữ hình thanh: 山 (sơn) biểu nghĩa, 榮 (vinh) cho âm. Mang nghĩa núi cao chót vót, hiểm trở. Chủ yếu dùng trong từ ghép 崢嶸 (tranh vanh, chengróng) — mô tả địa hình núi non hiểm trở, hoặc tượng trưng cho giai đoạn gian nan vất vả. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tranh vanh 崢嶸,峥嵘)", "Hạng Tần Suất (Jun Da)": "4724.0", "Tần Suất % (Jun Da)": "99.8916136201", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 荣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山荣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵘", "Unihan_Traditional (Chữ Phồn thể)": "嶸", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "vanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ, thường kết hợp thành từ láy để tả núi non hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轱', '{"9000": "4725.0", "Chữ Trung Quốc": "轱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轱 | cô | tượng hình | bánh xe, bộ 車 gợi phương tiện di chuyển | 轱 có bộ 車 (xa) biểu nghĩa xe/bánh xe, nhưng Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Dạng cổ 軲. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": bánh xe (車) lăn cô độc — chữ chính là âm tiết đầu của 轱辘 (bánh xe lăn tròn). | Gương Hán-Việt | cô — ít dùng độc lập, thường trong 轱辘 (bánh xe, ròng rọc) | Mở khoá kiến thức | Biết 轱 giúp nhận ra 轱辘 (bánh xe), từ thường xuất hiện trong văn học miêu tả xe cộ thời cổ.", "Tự nguyên_Xie": "Wiktionary ghi 轱 (dạng cổ 軲) với {{Han etym}} nhưng không có phân tích cấu trúc. Bộ 車 (xa) gợi liên quan đến xe và bánh xe. Chủ yếu dùng trong từ 轱辘 (gū lù) — bánh xe, ròng rọc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh xe", "Hạng Tần Suất (Jun Da)": "4725.0", "Tần Suất % (Jun Da)": "99.8917371318", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轱", "Unihan_Traditional (Chữ Phồn thể)": "軲", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong từ ghép chỉ bánh xe hoặc xe cộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怼', '{"9000": "4726.0", "Chữ Trung Quốc": "怼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 對 | đỗi | biểu âm | (cho âm) | 心 | tâm | biểu nghĩa | tim, cảm xúc | 怼 = 對 (Đỗi, biểu âm) + 心 (Tâm, biểu nghĩa: tim/cảm xúc). Chữ hình thanh: bộ 心 chỉ cảm xúc trong lòng, 對 cho âm duì. Dạng cổ 懟. Nghĩa gốc là oán hận, căm ghét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đối\" (theo 對): lòng (心) đối lập, oán thù — cảm giác ghét bỏ người ''đối diện''. | Gương Hán-Việt | đối — ít dùng trong tiếng Việt theo nghĩa oán giận; chủ yếu dùng trong khẩu ngữ Trung Quốc hiện đại | Mở khoá kiến thức | Biết 怼 giúp hiểu khẩu ngữ Trung Quốc hiện đại — chữ rất hay xuất hiện trên mạng xã hội với nghĩa ''cãi lại'', ''chọc tức''.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 怼 (dạng cổ 懟) là chữ hình thanh: 對 (đỗi) cho âm, 心 (tâm) biểu nghĩa cảm xúc. Nghĩa cổ điển: oán hận, căm thù. Trong tiếng Trung hiện đại (khẩu ngữ), còn mang nghĩa ''chọc tức'', ''phản bác'', ''cãi nhau''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "oán giận", "Hạng Tần Suất (Jun Da)": "4726.0", "Tần Suất % (Jun Da)": "99.8918606434", "GavinGrover_Once (Chiết tự trực tiếp)": "对 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱对心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "对", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "怼", "Unihan_Traditional (Chữ Phồn thể)": "懟", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "đỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện thái độ oán giận hoặc chỉ trích gay gắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铨', '{"9000": "4727.0", "Chữ Trung Quốc": "铨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铨 | thuyên | tượng hình | bộ 金 gợi kim loại/cân đo, cân nhắc phẩm chất | 铨 có bộ 金 (kim) biểu nghĩa kim loại/cân đo, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết cho 铨/銓. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyên\": kim loại (金) dùng làm cân — cân nhắc tài năng để tuyển chọn quan lại. | Gương Hán-Việt | thuyên — trong 铨选 (thuyên tuyển, tuyển dụng quan lại theo phẩm cấp) | Mở khoá kiến thức | Biết 铨 giúp hiểu các thuật ngữ hành chính cổ điển Trung Hoa như 铨叙 (xếp loại phẩm cấp), 铨选 (tuyển dụng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 铨 (dạng cổ 銓) với nghĩa: ước lượng, lựa chọn quan lại. Bộ 金 (kim) gợi cân đo, đong lường bằng kim loại. Trong hành chính cổ đại, 铨 là thuật ngữ chỉ việc cân nhắc, bổ nhiệm quan chức. Cấu trúc chi tiết chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cân nhắc", "Hạng Tần Suất (Jun Da)": "4727.0", "Tần Suất % (Jun Da)": "99.8919841551", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铨", "Unihan_Traditional (Chữ Phồn thể)": "銓", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc tuyển chọn, đánh giá năng lực của quan lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昕', '{"9000": "4728.0", "Chữ Trung Quốc": "昕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 昕 | hân | tượng hình | bộ 日 gợi mặt trời buổi sáng sớm, ánh bình minh | 昕 có bộ 日 (nhật) biểu nghĩa mặt trời/ban ngày, nhưng Wiktionary không phân tích cấu trúc hình-thanh hay hội-ý chi tiết. Nghĩa cổ điển: lúc tảng sáng, bình minh. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hân\": mặt trời (日) hân hoan mọc lên — khoảnh khắc tảng sáng đầy niềm vui khi ánh bình minh ló dạng. | Gương Hán-Việt | hân — ít dùng trong tiếng Việt hiện đại, thường dùng làm tên người (Xīn/Hân — bình minh tươi sáng) | Mở khoá kiến thức | Biết 昕 giúp hiểu nghĩa tên người Trung Hoa chứa chữ này: Xīn/昕 thường gợi ý bình minh, tươi sáng, khởi đầu tốt đẹp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 昕 (bộ 日) với nghĩa cổ điển: bình minh, tảng sáng. Xuất hiện trong thơ văn cổ điển Trung Hoa chỉ khoảnh khắc giao thoa giữa đêm và ngày. Cấu trúc chi tiết không được Wiktionary ghi rõ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng sớm, rạng đông", "Hạng Tần Suất (Jun Da)": "4728.0", "Tần Suất % (Jun Da)": "99.8921066332", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昕", "Unihan_Traditional (Chữ Phồn thể)": "昕", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "hân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ thời gian sáng sớm hoặc làm tính từ chỉ sự sáng sủa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郢', '{"9000": "4729.0", "Chữ Trung Quốc": "郢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 呈 | trình | biểu âm | (cho âm) | 邑 | ấp | biểu nghĩa | thành ấp, địa danh | 郢 = 呈 (Trình, biểu âm) + 邑 (Ấp, biểu nghĩa: thành ấp/địa danh). Chữ hình thanh: bộ 邑 chỉ địa danh/thành trì, 呈 cho âm. Đây là tên riêng chỉ thành Dĩnh — kinh đô nước Sở thời Chiến Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dĩnh\": ấp (邑) trình bày vẻ đẹp — kinh thành Dĩnh, nơi các thi nhân nước Sở như Khuất Nguyên từng sống. | Gương Hán-Việt | dĩnh — trong 郢都 (Dĩnh Đô, kinh đô nước Sở), 郢中 (trong thành Dĩnh) | Mở khoá kiến thức | Biết 郢 giúp hiểu lịch sử nước Sở và các tác phẩm như Sở Từ của Khuất Nguyên — 郢 là biểu tượng văn hoá Sở.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 郢 là chữ hình thanh: 邑 (ấp) biểu nghĩa địa danh, 呈 (trình) cho âm. Là tên kinh đô nước Sở (楚) thời Chiến Quốc, nằm ở tỉnh Hồ Bắc ngày nay (huyện Giang Lăng). Chữ xuất hiện nhiều trong thơ văn lịch sử Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thành Dĩnh (kinh đô nước Sở)", "Hạng Tần Suất (Jun Da)": "4729.0", "Tần Suất % (Jun Da)": "99.8922285944", "GavinGrover_Once (Chiết tự trực tiếp)": "呈 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰呈阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郢", "Unihan_Traditional (Chữ Phồn thể)": "郢", "Pinyin_Xie": "yǐng", "Âm Hán Việt_Xie": "dĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh cổ hoặc kinh đô nước Sở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咩', '{"9000": "4730.0", "Chữ Trung Quốc": "咩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 咩 | mị | tượng hình | bộ 口 gợi tiếng kêu, mô phỏng tiếng be be của dê con | 咩 không có nguồn glyph-origin từ Wiktionary. Bộ 口 (khẩu) gợi âm thanh, tiếng kêu. Chữ mô phỏng tiếng kêu ''be be'' (miē) của dê — là chữ tượng thanh. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": miệng (口) phát ra tiếng ''miē miē'' — tiếng kêu be be của dê con mới sinh. | Gương Hán-Việt | mị — ít dùng trong tiếng Việt; trong tiếng Trung dùng mô phỏng tiếng dê kêu | Mở khoá kiến thức | Biết 咩 giúp nhận ra tiếng tượng thanh trong tiếng Trung — chữ này cũng hay dùng trong tiếng Quảng Đông như trợ từ nghi vấn.", "Tự nguyên_Xie": "咩 không có nguồn glyph-origin từ Wiktionary. Bộ 口 (khẩu) kết hợp gợi tiếng kêu. Chữ mô phỏng tiếng be be của dê non — đây là chữ tượng thanh (onomatopoeia). Trong tiếng Quảng Đông, còn dùng như trợ từ nghi vấn cuối câu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng dê con kêu be be; mẹ; họ Mị", "Hạng Tần Suất (Jun Da)": "4730.0", "Tần Suất % (Jun Da)": "99.8923505557", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咩", "Unihan_Traditional (Chữ Phồn thể)": "咩", "Pinyin_Xie": "miē", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô phỏng tiếng kêu của loài dê. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馊', '{"9000": "4731.0", "Chữ Trung Quốc": "馊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 馊 | tẩu | tượng hình | bộ 食 gợi thức ăn; chỉ thức ăn bị ôi thiu | 馊 có bộ 食 (thực) biểu nghĩa thức ăn, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Dạng cổ 餿. Nghĩa gốc: thức ăn bị chua, ôi thiu. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": thức ăn (食) bị bỏ đi — cơm thiu, canh chua mùi hắc, ăn vào có hại. | Gương Hán-Việt | tẩu — ít dùng trong tiếng Việt; trong tiếng Trung thường gặp trong 馊了 (ôi rồi), 馊主意 (ý tưởng tệ) | Mở khoá kiến thức | Biết 馊 giúp nhận ra các từ miêu tả thức ăn hư hỏng như 馊了, 馊水 (nước thải thực phẩm) và cả nghĩa bóng 馊主意.", "Tự nguyên_Xie": "Wiktionary ghi 馊 (dạng cổ 餿): tính từ chỉ thức ăn bị chua, thiu, ôi. Cũng dùng với nghĩa cơ thể có mùi hôi do mồ hôi, hoặc tượng trưng cho ý tưởng tệ (''馊主意''). Bộ 食 (thực) gợi liên quan đến thức ăn. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "meo chua, ôi, thiu", "Hạng Tần Suất (Jun Da)": "4731.0", "Tần Suất % (Jun Da)": "99.892472517", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馊", "Unihan_Traditional (Chữ Phồn thể)": "餿", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ hoặc sau động từ để miêu tả thức ăn bị ôi thiu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髡', '{"9000": "4732.0", "Chữ Trung Quốc": "髡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 13 | nét | 髡 | côn | tượng hình | bộ 髟 gợi tóc; chỉ hình phạt cạo đầu | 髡 có bộ 髟 (phiêu) biểu nghĩa tóc, nhưng Wiktionary không cung cấp phân tích cấu trúc chi tiết hơn. Nghĩa gốc: hình phạt cổ đại — cạo trọc đầu người bị xử phạt. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": mái tóc (髟) bị cắt trụi — hình phạt cổ xưa nhục nhã vì tóc được coi là phần thân thể cha mẹ cho. | Gương Hán-Việt | côn — ít dùng trong tiếng Việt; trong tiếng Trung gặp trong văn sử như 髡刑 (hình phạt cạo đầu) | Mở khoá kiến thức | Biết 髡 giúp hiểu các hình phạt cổ đại Trung Hoa trong ngũ hình — 髡 là một trong những hình phạt nhẹ nhất nhưng gây mất danh dự.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 髡: hình phạt cổ đại Trung Hoa là cạo trọc đầu người nam. Nghĩa phái sinh: nhà sư Phật giáo (vì đầu cạo trọc), và nghĩa bóng: cắt cành tỉa cây. Trong phương ngữ Mân Nam còn dùng nghĩa cạo, gọt, nạo. Bộ 髟 (phiêu) gợi tóc. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt tóc; cây trụi lá", "Hạng Tần Suất (Jun Da)": "4732.0", "Tần Suất % (Jun Da)": "99.8925944783", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 兀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髡", "Unihan_Traditional (Chữ Phồn thể)": "髡", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "khôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ chỉ hành động cạo đầu hoặc làm danh từ chỉ hình phạt cạo đầu thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澧', '{"9000": "4733.0", "Chữ Trung Quốc": "澧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 水 | thủy | biểu nghĩa | nước, sông | 豊 | lễ | biểu âm | (cho âm) | 澧 = 水 (Thủy, biểu nghĩa: nước/sông) + 豊 (Lễ, biểu âm). Chữ hình thanh: bộ 水 chỉ sông nước, 豊 cho âm lǐ. Là tên sông ở tỉnh Hồ Nam, Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lễ\": nước (水) lễ nghĩa — tên dòng sông thanh khiết ở Hồ Nam, mang vẻ đẹp trang nghiêm. | Gương Hán-Việt | lễ — trong 澧水 (Lễ Thủy, sông Lishui), 澧县 (huyện Lễ) | Mở khoá kiến thức | Biết 澧 giúp nhận ra tên địa danh ở Hồ Nam như 澧水, 澧县 — quan trọng trong địa lý lịch sử Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 澧 là chữ hình thanh: 水 (thủy, nước) biểu nghĩa, 豊 (lễ) cho âm. Là tên của sông Lishui (澧水) ở tỉnh Hồ Nam, và tên huyện Lý (澧县) ở Hồ Nam. Ngoài ra còn là dạng dị thể của 醴 (lǐ — mật ong ngọt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên sông)", "Hạng Tần Suất (Jun Da)": "4733.0", "Tần Suất % (Jun Da)": "99.8927164396", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 豊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵豊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澧", "Unihan_Traditional (Chữ Phồn thể)": "澧", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ riêng, chủ yếu dùng làm địa danh hoặc tên sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苣', '{"9000": "4734.0", "Chữ Trung Quốc": "苣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苣 | cự | tượng hình | bộ 艸 gợi thực vật; loại rau diếp/xà lách | 苣 có bộ 艸 (tháu) biểu nghĩa cây cỏ, nhưng Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cấu trúc chi tiết. Chủ yếu dùng trong từ 莴苣 (wōjù — xà lách) và 苣荬菜. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": cỏ (艸) cự lớn — cây rau xà lách lớn, lá xanh mướt, ăn sống trong 莴苣. | Gương Hán-Việt | cự — trong 莴苣 (oa cự, xà lách), 苣荬菜 (rau diếp dại) | Mở khoá kiến thức | Biết 苣 giúp nhận ra 莴苣 (xà lách) trên thực đơn hoặc ở chợ Trung Quốc — rau phổ biến trong ẩm thực.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Wiktionary ghi 苣 là chữ chỉ loại rau trong họ xà lách. Bộ 艸 (tháu) biểu nghĩa cây cỏ thực vật. Xuất hiện nhiều nhất trong từ 莴苣 (wōjù — xà lách/rau diếp cuộn). Có nguồn hình ảnh giáp cốt văn và triện văn khá phong phú. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: oa cự 萵苣,莴苣)", "Hạng Tần Suất (Jun Da)": "4734.0", "Tần Suất % (Jun Da)": "99.8928378841", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苣", "Unihan_Traditional (Chữ Phồn thể)": "苣", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong các từ ghép chỉ các loại rau như rau diếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濯', '{"9000": "4735.0", "Chữ Trung Quốc": "濯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 17 | nét | 氵 | thủy | biểu nghĩa | nước | 翟 | địch | biểu âm | (cho âm) | 濯 = 氵(Thủy, biểu nghĩa: nước) + 翟 (Địch, biểu âm). Chữ hình thanh: bộ 氵chỉ nước, 翟 cho âm zhuó. Nghĩa gốc: giặt rũ, rửa sạch bằng nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trạc\": nước (氵) chảy mạnh như 翟/địch — hành động giặt rũ, rửa trôi mọi thứ. | Gương Hán-Việt | trạc — trong 濯足 (rửa chân), 濯洗 (giặt rũ) — ngôn ngữ thơ ca cổ điển | Mở khoá kiến thức | Biết 濯 giúp hiểu câu thơ nổi tiếng ''Canglang chi shui qing xi, ke yi zhuo wu ying'' (Sông Thương Lang trong thì giặt mũ) — biểu tượng khí tiết thanh cao.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 濯 là chữ hình thanh: 水 (thủy, nước, viết tắt thành 氵) biểu nghĩa, 翟 (địch) cho âm — ý nghĩa là rửa sạch bằng nước. Xuất hiện trong thơ cổ điển với nghĩa giặt rũ, tẩy sạch. Trong 濯足 (giặt chân) hay 濯缨 (giặt dải mũ — ẩn dụ thanh tẩy khí tiết). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giặt giũ, rửa", "Hạng Tần Suất (Jun Da)": "4735.0", "Tần Suất % (Jun Da)": "99.8929593286", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 翟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濯", "Unihan_Traditional (Chữ Phồn thể)": "濯", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các từ chỉ nước hoặc hành động làm sạch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盥', '{"9000": "4736.0", "Chữ Trung Quốc": "盥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 16 | nét | 𦥑 | (hai bàn tay) | biểu ý | đôi tay | 水 | thủy | biểu ý | nước | 皿 | mãnh | biểu ý | cái bát/chậu đựng | 盥 là chữ hội ý: 𦥑 (đôi bàn tay) + 水 (nước) + 皿 (chậu đựng) — hình ảnh hai bàn tay được rót nước từ chậu để rửa. Đây là chữ hội ý điển hình miêu tả hành động rửa tay/mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": hai tay (𦥑) cầm nước (水) từ bát (皿) — cảnh rửa tay sạch sẽ, nghi lễ thanh tẩy trước mỗi bữa ăn hay lễ tế. | Gương Hán-Việt | quán — trong 盥洗 (quán tẩy, rửa tay/mặt), 盥洗室 (phòng vệ sinh) | Mở khoá kiến thức | Biết 盥 giúp hiểu 盥洗室 (phòng rửa mặt/vệ sinh) — từ trang trọng hay gặp trên bảng hiệu khách sạn, văn phòng.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Theo Wiktionary, 盥 là chữ hội ý: 𦥑 (đôi bàn tay) + 水 (nước) + 皿 (chậu/bình) — hình ảnh hai bàn tay được rửa bằng nước từ bình chậu. Nghĩa gốc: rửa tay, rửa mặt. Nghĩa phái sinh: chậu rửa. Chữ có dạng giáp cốt văn và kim văn, cho thấy đây là hoạt động vệ sinh quan trọng từ thời thượng cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rửa sạch; cái chậu", "Hạng Tần Suất (Jun Da)": "4736.0", "Tần Suất % (Jun Da)": "99.8930807731", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "盥", "Unihan_Traditional (Chữ Phồn thể)": "盥", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc rửa tay chân hoặc làm danh từ chỉ chậu rửa thời cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囡', '{"9000": "4737.0", "Chữ Trung Quốc": "囡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 6 | nét | 囡 | nữu | tượng hình | chữ 女 (người nữ) được vây trong khung 囗 — đứa trẻ gái được bao bọc trong nhà | 囡 không có nguồn glyph-origin từ Wiktionary. Nhìn trực quan: 女 (người nữ) nằm trong 囗 (khung bao quanh) — gợi hình ảnh đứa con gái nhỏ được ôm ấp, bao bọc trong lòng nhà. Chữ dùng trong phương ngữ Ngô (Thượng Hải) chỉ trẻ con, con gái. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữu\": người nữ (女) được vòng tay (囗) ôm trọn — hình ảnh đứa trẻ gái nhỏ được che chở trong lòng. | Gương Hán-Việt | nữu — ít dùng trong tiếng Việt; trong tiếng Thượng Hải/Ngô 囡囡 (nān nān) là cách gọi yêu trẻ con, con gái | Mở khoá kiến thức | Biết 囡 giúp hiểu tiếng lóng phương ngữ Ngô — 囡囡 là từ âu yếm gọi con gái nhỏ, rất phổ biến ở Thượng Hải.", "Tự nguyên_Xie": "囡 không có nguồn glyph-origin từ Wiktionary. Hình dạng trực quan: 女 (nữ, người phụ nữ) bên trong 囗 (khung vây quanh) — gợi đứa trẻ gái nhỏ được bao bọc. Chủ yếu dùng trong phương ngữ Ngô (Thượng Hải, Tô Châu) chỉ trẻ con (不分男女) hoặc riêng con gái. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trẻ con; trẻ em; con nít", "Hạng Tần Suất (Jun Da)": "4737.0", "Tần Suất % (Jun Da)": "99.8932017009", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囡", "Unihan_Traditional (Chữ Phồn thể)": "囡", "Pinyin_Xie": "nān", "Âm Hán Việt_Xie": "nam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong khẩu ngữ phương nam để gọi con trẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砺', '{"9000": "4738.0", "Chữ Trung Quốc": "砺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砺 | lệ | tượng hình | bộ 石 gợi đá; đá mài sắc bén | 砺 có bộ 石 (thạch) biểu nghĩa đá, nhưng Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cấu trúc chi tiết. Dạng cổ 礪. Nghĩa gốc: hòn đá mài lớn, dùng mài sắc vũ khí hoặc dụng cụ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": đá (石) mài sắc lưỡi — hòn đá lớn dùng để mài kiếm, và nghĩa bóng là rèn luyện bản thân đến sắc bén. | Gương Hán-Việt | lệ — trong 砥砺 (để lệ, rèn giũa bản thân), 磨砺 (mài giũa, tôi luyện) | Mở khoá kiến thức | Biết 砺 giúp hiểu 砥砺奋进 (mài giũa bản thân, phấn chấn tiến lên) — khẩu hiệu phổ biến trong văn phong chính thức Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 砺 (dạng cổ 礪) với nghĩa: đá mài to (whetstone), mài sắc. Bộ 石 (thạch) biểu nghĩa đá. Trong thành ngữ hay dùng nghĩa bóng: rèn luyện, mài giũa phẩm chất. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hòn đá mài to", "Hạng Tần Suất (Jun Da)": "4738.0", "Tần Suất % (Jun Da)": "99.8933226286", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 厉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石厉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砺", "Unihan_Traditional (Chữ Phồn thể)": "礪", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ đá mài hoặc làm động từ với nghĩa mài giũa, rèn luyện bản thân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佘', '{"9000": "4739.0", "Chữ Trung Quốc": "佘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 人 | nhân | biểu nghĩa | người | 示 | thị | biểu âm | (cho âm) | 佘 = 人 (Nhân, biểu nghĩa: người) + 示 (Thị, biểu âm). Chữ hình thanh: bộ 人 chỉ con người, 示 cho âm shé. Theo Wiktionary, chữ này phái sinh từ 余 và 舍, được phân biệt vào thời Hán, dùng chủ yếu làm họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xà\": người (人) thị uy — họ người nổi tiếng trong tiểu thuyết võ hiệp Trung Hoa, gắn với Bà Thái Quân nhà họ Dương. | Gương Hán-Việt | xà — trong họ 佘太君 (Xà Thái Quân), nhân vật lịch sử/văn học Trung Hoa | Mở khoá kiến thức | Biết 佘 giúp nhận ra họ Xà trong văn học và lịch sử Trung Hoa — một trong những họ đặc biệt ít phổ biến.", "Tự nguyên_Xie": "Theo Wiktionary, 佘 được phái sinh từ 余 (dư) và 舍 (xá) vào khoảng thời Hán — có thể là chữ hình thanh 人 (nhân, người) + 示 (thị, biểu âm). Dùng chủ yếu làm họ người (họ Xà/Xư). Họ 佘 nổi tiếng trong lịch sử qua gia đình tướng quân Dương (Dương Lệnh Công) qua hình tượng Bà Thái Quân họ 佘. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Xà", "Hạng Tần Suất (Jun Da)": "4739.0", "Tần Suất % (Jun Da)": "99.8934430395", "GavinGrover_Once (Chiết tự trực tiếp)": "人 + 示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱人示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "示", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "佘", "Unihan_Traditional (Chữ Phồn thể)": "佘", "Pinyin_Xie": "shé", "Âm Hán Việt_Xie": "xà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ riêng, hầu như chỉ dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谶', '{"9000": "4740.0", "Chữ Trung Quốc": "谶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 谶 | sấm | tượng hình | bộ 讠(言) gợi lời nói/tiên tri; lời sấm truyền | 谶 có bộ 讠(言) biểu nghĩa lời nói, nhưng Wiktionary ghi 谶 là dạng giản thể của 讖 (từ 訁+讖). Không cung cấp phân tích hình-thanh chi tiết riêng. Nghĩa gốc: lời sấm ngôn, lời tiên tri bí ẩn. Chưa có nguồn học thuật đầy đủ về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấm\": lời (言) từ cõi thiêng — sấm ngôn bí ẩn tiên đoán vận mệnh, được viết ra để cảnh báo thế nhân. | Gương Hán-Việt | sấm — trong 谶语 (sấm ngữ, lời tiên tri), 谶纬 (sấm vĩ, học thuyết sấm ngôn) | Mở khoá kiến thức | Biết 谶 giúp hiểu khái niệm 谶语 (lời tiên tri nghiệm ứng) — thường xuất hiện trong tiểu thuyết cổ đại và phim lịch sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 谶 là dạng giản thể của 讖, với bộ 讠(言) biểu nghĩa lời nói. Nghĩa: lời sấm ngôn, lời tiên tri bí ẩn, thường mang tính cảnh báo hoặc điềm báo trong văn hoá Trung Hoa cổ đại. Trong lịch sử, 谶纬 (sấm vĩ) là truyền thống sấm ngôn chính trị. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lời sấm ngôn, lời tiên tri", "Hạng Tần Suất (Jun Da)": "4740.0", "Tần Suất % (Jun Da)": "99.8935634504", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 韱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠韱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谶", "Unihan_Traditional (Chữ Phồn thể)": "讖", "Pinyin_Xie": "chèn", "Âm Hán Việt_Xie": "sấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ những lời tiên tri hoặc điềm báo trước điềm lành dữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弑', '{"9000": "4741.0", "Chữ Trung Quốc": "弑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弋 | Số nét | 12 | nét | 殺 | sát | biểu nghĩa | giết, sát hại (dạng viết tắt) | 式 | thức | biểu âm | (cho âm) | 弑 = 殺 (Sát, biểu nghĩa: giết, dạng viết tắt) + 式 (Thức, biểu âm). Chữ hình thanh: thành phần của 殺 biểu nghĩa hành động giết, 式 cho âm shì. Dạng cổ 弒. Nghĩa đặc biệt: giết người trên như vua, cha mẹ — tội ác nặng nhất trong đạo đức Nho giáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thí\": sát (殺) theo thức/nghi thức — không phải giết thường, mà là kẻ dưới cung thí bề trên — tội ác tày trời trong Nho giáo. | Gương Hán-Việt | thí — trong 弑君 (thí quân, giết vua), 弑父 (thí phụ, giết cha) | Mở khoá kiến thức | Biết 弑 giúp đọc các văn bản lịch sử và tiểu thuyết cổ điển — 弑君 là sự kiện chính trị trọng đại trong biên niên sử Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 弑 (dạng cổ 弒) là chữ hình thanh: thành phần của 殺 (sát, giết) biểu nghĩa, 式 (thức) cho âm. Mang nghĩa đặc biệt: thí — kẻ dưới giết người trên (thần giết vua, con giết cha mẹ). Đây là tội ác nghiêm trọng nhất theo Nho giáo, vi phạm đồng thời cả trung và hiếu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thí; giết (thần giết vua, con giết cha mẹ)", "Hạng Tần Suất (Jun Da)": "4741.0", "Tần Suất % (Jun Da)": "99.8936838614", "GavinGrover_Once (Chiết tự trực tiếp)": "杀 + 式", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰杀式", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "式", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "杀", "Unihan_Simplified (Chữ Giản thể)": "弑", "Unihan_Traditional (Chữ Phồn thể)": "弒", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mang sắc thái trang trọng, chỉ hành vi sát hại người có địa vị cao hơn mình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楂', '{"9000": "4742.0", "Chữ Trung Quốc": "楂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楂 | tra | tượng hình | bộ 木 gợi cây/gỗ; cây sơn tra (táo gai) hoặc bè gỗ | 楂 có bộ 木 (mộc) biểu nghĩa cây/gỗ, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Có hai âm: chá (bè gỗ, cành cây) và zhā (cây sơn tra, táo gai). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": cây (木) tra — cây sơn tra với quả chua đỏ rực, quen thuộc trong ẩm thực và y học Trung Hoa. | Gương Hán-Việt | tra — trong 山楂 (sơn tra, táo gai), 山楂糕 (bánh sơn tra) | Mở khoá kiến thức | Biết 楂 giúp nhận ra 山楂 (sơn tra) trên thực đơn, ở chợ Trung Quốc — vị quả chua phổ biến trong đồ uống, kẹo và thuốc.", "Tự nguyên_Xie": "Wiktionary ghi 楂 có hai âm: chá (bè gỗ, cành cây, dạng biến thể của 槎) và zhā (cây táo gai/sơn tra — hawthorn). Bộ 木 (mộc) biểu nghĩa cây gỗ. Hay gặp nhất trong 山楂 (táo gai, sơn tra) — loại quả chua phổ biến trong ẩm thực Trung Hoa. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tra", "Hạng Tần Suất (Jun Da)": "4742.0", "Tần Suất % (Jun Da)": "99.8938042723", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楂", "Unihan_Traditional (Chữ Phồn thể)": "楂", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong tên các loại cây quả như sơn tra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翦', '{"9000": "4743.0", "Chữ Trung Quốc": "翦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 15 | nét | 翦 | tiễn | tượng hình | bộ 羽 gợi lông vũ; dùng lông vũ/dao sắc để cắt gọt | 翦 có bộ 羽 (vũ) biểu nghĩa lông/cánh, nhưng Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cấu trúc chi tiết. Nghĩa gốc: kéo, cắt đứt. Cũng là họ người (Tiễn). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễn\": lông vũ (羽) bị cắt đứt — hình ảnh kéo sắc cắt đứt cánh chim, gợi nghĩa tiêu diệt dứt khoát. | Gương Hán-Việt | tiễn — trong 翦灭 (tiễn diệt, tiêu diệt), 翦除 (tiễn trừ, loại bỏ) | Mở khoá kiến thức | Biết 翦 giúp đọc văn bản lịch sử — 翦灭 hay dùng miêu tả việc tiêu diệt thế lực đối địch trong sử sách cổ điển.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi 翦 với {{Han etym}} nhưng không có phân tích cấu trúc. Bộ 羽 (vũ, lông vũ) biểu nghĩa. Nghĩa: cái kéo, cắt đứt. Nghĩa phái sinh: tiêu diệt. Cũng dùng làm họ người (họ Tiễn 翦). Chỉ có hình ảnh lục thư thông, chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt đứt; cái kéo", "Hạng Tần Suất (Jun Da)": "4743.0", "Tần Suất % (Jun Da)": "99.8939246833", "GavinGrover_Once (Chiết tự trực tiếp)": "前 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱前羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "前", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翦", "Unihan_Traditional (Chữ Phồn thể)": "翦", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang tân ngữ với nghĩa cắt xén hoặc tiêu diệt kẻ địch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怩', '{"9000": "4744.0", "Chữ Trung Quốc": "怩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怩 | náy | tượng hình | bộ 心 gợi cảm xúc xấu hổ, ngượng ngùng trong lòng | 怩 có bộ 心 (tâm) biểu nghĩa cảm xúc, nhưng Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Chủ yếu dùng trong từ 忸怩 (niǔ ní) — xấu hổ, ngại ngùng. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"náy\": lòng (心) náy nang, ngại ngùng — cảm giác thẹn thùng khó nói thành lời trong 忸怩. | Gương Hán-Việt | náy — trong 忸怩 (náy nang, thẹn thùng), cặp từ cổ điển miêu tả sự xấu hổ | Mở khoá kiến thức | Biết 怩 giúp nhận ra 忸怩 (thẹn thùng, xấu hổ) — từ hay dùng trong văn học miêu tả tâm lý nhân vật e thẹn.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi 怩 với {{Han etym}} nhưng không có phân tích cấu trúc. Bộ 心 (tâm) biểu nghĩa cảm xúc trong lòng. Chủ yếu dùng trong 忸怩 (niǔ ní — xấu hổ, ngượng ngùng, thẹn thùng). Có dạng hình đại triện và tiểu triện. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nữu ni 忸怩)", "Hạng Tần Suất (Jun Da)": "4744.0", "Tần Suất % (Jun Da)": "99.8940445774", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 尼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄尼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怩", "Unihan_Traditional (Chữ Phồn thể)": "怩", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "ni", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với nữu thành từ láy nữu ni để làm tính từ chỉ sự ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠼', '{"9000": "4745.0", "Chữ Trung Quốc": "蠼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 26 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 矍 | quắc | biểu âm | (cho âm) | 蠼 = 虫 (Trùng, biểu nghĩa: côn trùng) + 矍 (Quắc, biểu âm). Chữ hình thanh: bộ 虫 chỉ côn trùng, 矍 cho âm qú. Chủ yếu dùng trong 蠼螋 (cù sưu) — loài côn trùng bọ kẹp (earwig).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": sâu (虫) quắc đuôi kẹp — con bọ kẹp 蠼螋 với đôi đuôi nhọn như kẹp sắt, sống ở xó tối. | Gương Hán-Việt | quắc — trong 蠼螋 (quắc tẩu, bọ kẹp/earwig) | Mở khoá kiến thức | Biết 蠼 giúp nhận ra 蠼螋 (bọ kẹp) khi đọc sách khoa học tự nhiên hoặc văn học mô tả côn trùng.", "Tự nguyên_Xie": "Theo Wiktionary, 蠼 là chữ hình thanh: 虫 (trùng, côn trùng) biểu nghĩa, 矍 (quắc) cho âm. Chỉ dùng trong từ 蠼螋 (qú sōu — bọ kẹp, earwig) — loài côn trùng sống ở nơi ẩm ướt, có đôi kẹp ở đuôi đặc trưng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cù sưu (loài côn trùng thường sống ở nơi ẩm ướt)", "Hạng Tần Suất (Jun Da)": "4745.0", "Tần Suất % (Jun Da)": "99.8941644716", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 矍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫矍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠼", "Unihan_Traditional (Chữ Phồn thể)": "蠼", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "quặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường kết hợp với sưu để chỉ loài côn trùng sống nơi ẩm ướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霏', '{"9000": "4746.0", "Chữ Trung Quốc": "霏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 16 | nét | 霏 | phay | tượng hình | bộ 雨 gợi mưa; chỉ mưa tuyết rơi lả tả, lất phất | 霏 có bộ 雨 (vũ) biểu nghĩa mưa, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Nghĩa gốc: mưa/tuyết rơi lả tả, lất phất. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phay\": mưa (雨) phay phơi rơi — hạt mưa bay lất phất, tuyết rơi nhẹ nhàng lả tả trong thơ ca cổ điển. | Gương Hán-Việt | phay — trong 霏霏 (phay phay, mưa tuyết lả tả), 烟霏 (mây khói lất phất) | Mở khoá kiến thức | Biết 霏 giúp đọc thơ ca cổ điển Trung Hoa — 霏霏 là từ láy nổi tiếng miêu tả mưa tuyết liên miên.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 霏 (bộ 雨) với nghĩa: mưa hoặc tuyết rơi lả tả, lất phất. Hay dùng trong 霏霏 (fēifēi — mưa tuyết dày đặc liên hồi). Xuất hiện nhiều trong thơ cổ điển miêu tả cảnh mưa tuyết mùa đông. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lả tả, lã chã, lất phất (mưa, tuyết)", "Hạng Tần Suất (Jun Da)": "4746.0", "Tần Suất % (Jun Da)": "99.8942843657", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霏", "Unihan_Traditional (Chữ Phồn thể)": "霏", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả trạng thái mưa tuyết rơi lả tả hoặc sương mù dày đặc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楹', '{"9000": "4747.0", "Chữ Trung Quốc": "楹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楹 | doanh | tượng hình | bộ 木 gợi gỗ/cây; cột gỗ đứng trước sảnh đường | 楹 có bộ 木 (mộc) biểu nghĩa gỗ, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Nghĩa gốc: cột (đặc biệt là cột phía trước của sảnh đường). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doanh\": gỗ (木) đứng doanh doanh — cột gỗ cao thẳng trước cửa đền đài, biểu tượng vẻ trang nghiêm của kiến trúc cổ. | Gương Hán-Việt | doanh — trong 楹联 (doanh liên, câu đối trên cột), 楹柱 (cột trụ) | Mở khoá kiến thức | Biết 楹 giúp hiểu 楹联 (câu đối treo trên cột trụ) — thể thơ văn truyền thống Trung Hoa rất phổ biến dịp Tết.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 楹 (bộ 木) với nghĩa: cột trụ (đặc biệt phía trước sảnh đường lớn). Cũng dùng như đơn vị đếm tòa nhà/phòng (literary). Trong phương ngữ Mân Nam còn nghĩa là đòn tay (purlin). Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cột nhà", "Hạng Tần Suất (Jun Da)": "4747.0", "Tần Suất % (Jun Da)": "99.8944042599", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 盈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木盈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楹", "Unihan_Traditional (Chữ Phồn thể)": "楹", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "doanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ cột nhà hoặc làm lượng từ để đếm số gian nhà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讴', '{"9000": "4748.0", "Chữ Trung Quốc": "讴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讴 | âu | tượng hình | bộ 讠(言) gợi lời nói/giọng hát; ca hát cùng nhau | 讴 là dạng giản thể của 謳, từ 訁(言) + 區. Bộ 讠(言) biểu nghĩa lời nói/giọng ca. Không cung cấp phân tích cấu trúc chi tiết riêng. Nghĩa gốc: ca hát, những bài dân ca.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": lời (言) ngân âu âu — tiếng hát dân gian cất lên đồng thanh, vui tươi và tự nhiên. | Gương Hán-Việt | âu — trong 讴歌 (âu ca, ca ngợi bằng tiếng hát) | Mở khoá kiến thức | Biết 讴 giúp hiểu 讴歌 (ca ngợi) — từ hay dùng trong văn phong trang trọng, nghĩa ca hát để tôn vinh.", "Tự nguyên_Xie": "Wiktionary ghi 讴 là dạng giản thể của 謳 (với 言+區). Bộ 言/讠biểu nghĩa lời nói/giọng ca. Nghĩa: ca hát (nhiều người cùng hát), dân ca. Chữ hay xuất hiện trong thơ ca cổ điển miêu tả tiếng hát dân gian. Dạng giản thể, cấu trúc gốc chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùng hát; tiếng trẻ con", "Hạng Tần Suất (Jun Da)": "4748.0", "Tần Suất % (Jun Da)": "99.8945236372", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讴", "Unihan_Traditional (Chữ Phồn thể)": "謳", "Pinyin_Xie": "ōu", "Âm Hán Việt_Xie": "âu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động ca hát hoặc làm danh từ chỉ khúc hát dân ca. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锲', '{"9000": "4749.0", "Chữ Trung Quốc": "锲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 钅 | kim | biểu nghĩa | kim loại | 契 | khế | biểu âm | hợp đồng, khắc | 锲 = 钅 (Kim, biểu nghĩa: kim loại) + 契 (Khế, biểu âm). Dạng phồn thể 鍥 = 金+契. Wiktionary ghi rõ ls=psc (hình thanh): 金 (钅) cho nghĩa (dụng cụ kim loại), 契 cho âm qiè. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiết\": dao kim loại (钅) khắc theo hợp đồng (契) — cắt khắc không ngừng; 锲而不舍 là kiên trì đến cùng. | Gương Hán-Việt | \"khiết\" trong 锲而不舍 (khiết nhi bất xả — kiên trì không bỏ cuộc) | Mở khoá kiến thức | Biết 锲 mở khoá 锲而不舍 (kiên trì không từ bỏ), 锲刻 (khắc chạm).", "Tự nguyên_Xie": "Tiểu triện | Chữ 锲 (khiết), phồn thể 鍥, là chữ hình thanh (ls=psc): bộ 金 (钅 — Kim) biểu nghĩa chỉ dụng cụ kim loại dùng để cắt khắc; 契 (Khế) biểu âm qiè. Nghĩa gốc: cái liềm nhỏ; hành động cắt khắc bằng kim loại. Tiểu triện được lưu tại hanziyuan.net. Nổi tiếng nhất qua thành ngữ 锲而不舍 (kiên trì không bỏ cuộc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái liềm; 2 cắt đứt", "Hạng Tần Suất (Jun Da)": "4749.0", "Tần Suất % (Jun Da)": "99.8946430146", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锲", "Unihan_Traditional (Chữ Phồn thể)": "鍥", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ việc chạm khắc trên kim loại hoặc đá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慵', '{"9000": "4750.0", "Chữ Trung Quốc": "慵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 14 | nét | 慵 | thuồng | tượng hình | bộ 心 gợi cảm xúc; trạng thái lười biếng mệt mỏi trong lòng | 慵 có bộ 心 (tâm) biểu nghĩa cảm xúc/tâm trạng, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Nghĩa gốc: lười biếng, uể oải, mệt mỏi (từ tiếng Hán Trung Cổ trở đi). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuồng\": lòng (心) thuồng lờ, uể oải — cảm giác không muốn làm gì, nằm dài mà không buồn nhúc nhích. | Gương Hán-Việt | thuồng — trong 慵懒 (uể oải), 慵倦 (mệt mỏi lười biếng) | Mở khoá kiến thức | Biết 慵 giúp đọc thơ Đường Tống và văn học hiện đại — 慵懒 là từ rất hay dùng để miêu tả buổi sáng cuối tuần thư giãn.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 慵 (bộ 心) với nghĩa: lười biếng, uể oải, mệt mỏi. Chữ xuất hiện ít nhất từ thời Trung Cổ tiếng Trung. Hay dùng trong 慵懒 (uể oải lười nhác) và thành ngữ 意懒心慵 (lòng ý đều uể oải). Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mệt mỏi; lười biếng; biếng nhác", "Hạng Tần Suất (Jun Da)": "4750.0", "Tần Suất % (Jun Da)": "99.8947618752", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 庸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄庸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "慵", "Unihan_Traditional (Chữ Phồn thể)": "慵", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị trạng thái lười nhác hoặc mệt mỏi thiếu sức sống. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胝', '{"9000": "4751.0", "Chữ Trung Quốc": "胝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 胝 | đì | tượng hình | bộ 月(肉) gợi thịt/da; vết chai cứng trên tay chân | 胝 có bộ 月(肉) biểu nghĩa thịt/da người, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Nghĩa: chai, cứng da (callus). Chủ yếu dùng trong 胼胝 (biền đì). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đì\": thịt (肉) đì cứng lại — da thịt chai cứng sau năm tháng lao động, biểu tượng sự gian khổ cần cù. | Gương Hán-Việt | đì — trong 胼胝 (biền đì, chai tay chai chân), 手足胼胝 (tay chân chai đầy) | Mở khoá kiến thức | Biết 胝 giúp hiểu thành ngữ 胼手胝足 (tay chân đầy chai) — miêu tả người lao động cực nhọc trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 胝 (bộ 月/肉) với nghĩa: vết chai, sần cứng trên tay hoặc chân (callus, callosities). Chủ yếu dùng trong 胼胝 (pián zhī — bàn tay/chân chai cứng do lao động). Cụm 手胼足胝 (tay bàn chân chai) miêu tả người lao động cực khổ. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: biền chi 胼胝)", "Hạng Tần Suất (Jun Da)": "4751.0", "Tần Suất % (Jun Da)": "99.8948807358", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胝", "Unihan_Traditional (Chữ Phồn thể)": "胝", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường đi kèm với biền để chỉ các vết chai sạn trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砭', '{"9000": "4752.0", "Chữ Trung Quốc": "砭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砭 | bàm | tượng hình | bộ 石 gợi đá; kim bằng đá dùng trong y học cổ đại | 砭 có bộ 石 (thạch) biểu nghĩa đá, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Nghĩa gốc: kim đá (stone needle) dùng trong châm cứu cổ đại; nghĩa phái sinh: khuyên bảo, phê phán xây dựng. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàm\": đá (石) bàm vào — kim đá thời cổ xưa dùng châm cứu, từ đó 针砭 (châm biếm) có nghĩa phê phán để chữa bệnh xã hội. | Gương Hán-Việt | bàm — trong 针砭 (châm biếm, phê phán xây dựng), 砭石 (kim đá châm cứu) | Mở khoá kiến thức | Biết 砭 giúp hiểu từ nguyên của 针砭时弊 (châm biếm thói xấu thời đại) — thành ngữ thường dùng trong bình luận xã hội.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 砭 (bộ 石) với các nghĩa: kim đá dùng trong châm cứu y học cổ truyền Trung Hoa; đâm bằng kim đó; chữa bệnh; khuyên bảo/phê phán xây dựng. Thành ngữ 针砭 (châm biếm — châm chỉ trị bệnh) từ nghĩa đen của kim đá đã phát triển thành nghĩa bóng phê phán xây dựng. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kim bằng đá", "Hạng Tần Suất (Jun Da)": "4752.0", "Tần Suất % (Jun Da)": "99.8949995963", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 乏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石乏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砭", "Unihan_Traditional (Chữ Phồn thể)": "砭", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ kim đá chữa bệnh hoặc làm động từ chỉ việc châm chích, phê phán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潍', '{"9000": "4753.0", "Chữ Trung Quốc": "潍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 潍 | duy | tượng hình | bộ 水 gợi sông nước; tên sông và địa danh ở Sơn Đông | 潍 có bộ 水 (thủy) biểu nghĩa sông nước, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Dạng cổ 濰. Nghĩa: sông Duy (Weishui) và địa danh Duy Phường (Weifang) ở tỉnh Sơn Đông. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duy\": nước (水) duy nhất chảy qua vùng đất — sông Duy, gắn với thành phố Duy Phường nổi tiếng với diều truyền thống. | Gương Hán-Việt | duy — trong 潍河 (Duy Hà, sông Duy), 潍坊 (Duy Phường, thành phố diều) | Mở khoá kiến thức | Biết 潍 giúp nhận ra địa danh 潍坊 (Weifang) — thành phố nổi tiếng nhất thế giới về diều truyền thống Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 潍 (dạng cổ 濰) với nghĩa: sông Duy (潍河/濰河) ở tỉnh Sơn Đông; huyện/tiểu khu Duy (潍县/濰縣) — nay là thành phố Duy Phường (潍坊). Bộ 水 (thủy) biểu nghĩa sông nước. Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên sông)", "Hạng Tần Suất (Jun Da)": "4753.0", "Tần Suất % (Jun Da)": "99.8951179401", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 维", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵维", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "维", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潍", "Unihan_Traditional (Chữ Phồn thể)": "濰", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "duy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng trong địa danh như tên sông hoặc tên thành phố Duy Phường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杵', '{"9000": "4754.0", "Chữ Trung Quốc": "杵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 午 | ngọ | biểu âm | (cho âm; cũng gợi hình cái chày) | 杵 = 木 (Mộc, biểu nghĩa: gỗ) + 午 (Ngọ, biểu âm và hình). Theo Wiktionary, có thể phân tích là hội ý (ic) hoặc hình thanh (psc): 木 chỉ chất liệu gỗ, 午 vừa cho âm vừa gợi hình cái chày. Nghĩa gốc: cái chày gỗ, vật dụng để giã, dã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngỏ\": gỗ (木) hình ngọ/chày — cái chày gỗ thon dài dùng giã gạo, giã thuốc, biểu tượng lao động thủ công. | Gương Hán-Việt | ngỏ — trong 杵臼 (ngỏ cữu, chày và cối), 杵歌 (bài hát giã gạo) | Mở khoá kiến thức | Biết 杵 giúp hiểu 杵臼之交 (tình bạn như chày với cối — gắn kết khăng khít) — thành ngữ miêu tả tình bạn thân thiết dù khác nhau.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 杵 có thể là hội ý hoặc hình thanh: 木 (mộc, gỗ) + 午 (ngọ) — 午 vừa cho âm chǔ vừa gợi hình cái chày. Nghĩa: cái chày gỗ dùng để giã (thuốc, gạo, vải). Hay gặp trong 杵臼 (chày và cối), 杵歌 (bài hát khi giã). Hình ảnh cổ điển của lao động nông thôn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1255.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Ngọ (301)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - gỗ/chỉ ý) ở bên trái chữ Ngọ (số 301 - can Ngọ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngọ chỉ âm, bộ Mộc chỉ ý. Xử là cái chày làm bằng gỗ để giã gạo.", "Nghĩa Tiếng Việt_Xie": "cái chầy, cái chày", "Hạng Tần Suất (Jun Da)": "4754.0", "Tần Suất % (Jun Da)": "99.8952362839", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 午", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木午", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "午", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杵", "Unihan_Traditional (Chữ Phồn thể)": "杵", "Pinyin_Xie": "chǔ", "Âm Hán Việt_Xie": "xử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái chày hoặc làm động từ chỉ hành động đâm, chọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樾', '{"9000": "4755.0", "Chữ Trung Quốc": "樾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | cây | 越 | việt | biểu âm | (cho âm) | 樾 = 木 (Mộc, biểu nghĩa: cây) + 越 (Việt, biểu âm). Chữ hình thanh: bộ 木 chỉ cây cối, 越 cho âm yuè. Nghĩa gốc: bóng mát của cây, đặc biệt bóng của hai hàng cây hai bên đường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẹt\": cây (木) việt/vẹt — tán cây xanh che mát con đường, tạo bóng vẹt mát dịu cho người đi. | Gương Hán-Việt | vẹt — ít dùng trong tiếng Việt; trong tiếng Trung gặp trong thơ cổ 修樾 (hàng cây xanh mát) | Mở khoá kiến thức | Biết 樾 giúp đọc thơ cổ điển miêu tả cảnh quan thiên nhiên — 绿樾, 树樾 là những từ đẹp gợi bóng mát xanh mướt.", "Tự nguyên_Xie": "Theo Wiktionary, 樾 là chữ hình thanh: 木 (mộc, cây) biểu nghĩa, 越 (việt) cho âm. Nghĩa cổ điển: bóng mát của cây (đặc biệt trong văn học gợi cảnh đường cây xanh mát). Hay dùng trong thơ ca miêu tả con đường có bóng cây che phủ, bình yên và thơ mộng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ bóng rợp của hai cây; được người khác che chở", "Hạng Tần Suất (Jun Da)": "4755.0", "Tần Suất % (Jun Da)": "99.8953546277", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 越", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木越", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "越", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樾", "Unihan_Traditional (Chữ Phồn thể)": "樾", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "việt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn thơ cổ để chỉ bóng mát của cây cối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帼', '{"9000": "4756.0", "Chữ Trung Quốc": "帼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 11 | nét | 帼 | quắc | tượng hình | bộ 巾 gợi vải/khăn; đồ trang sức vải trên đầu của phụ nữ | 帼 có bộ 巾 (cân) biểu nghĩa vải/khăn, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Dạng cổ 幗. Nghĩa gốc: đồ trang sức trên đầu phụ nữ thời cổ đại. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": khăn (巾) quắc — vật trang sức trên đầu phụ nữ, biểu tượng của giới nữ trong thành ngữ 巾帼英雄. | Gương Hán-Việt | quắc — trong 巾帼 (khăn+mũ phụ nữ, ẩn dụ chỉ phụ nữ), 巾帼英雄 (anh hùng phụ nữ) | Mở khoá kiến thức | Biết 帼 giúp hiểu 巾帼英雄 (nữ anh hùng) — thành ngữ rất phổ biến trong văn học và truyền thông Trung Quốc ca ngợi phụ nữ xuất sắc.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 帼 (dạng cổ 幗) với nghĩa: đồ trang sức/mũ đầu của phụ nữ thời lịch sử. Bộ 巾 (cân) biểu nghĩa vải/khăn. Hay gặp trong 巾帼 (khăn/mũ phụ nữ — ẩn dụ chỉ phụ nữ nói chung), 巾帼英雄 (anh hùng nữ). Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một thứ đồ trang sức trên đầu của phụ nữ", "Hạng Tần Suất (Jun Da)": "4756.0", "Tần Suất % (Jun Da)": "99.8954724547", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 国", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾国", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "国", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帼", "Unihan_Traditional (Chữ Phồn thể)": "幗", "Pinyin_Xie": "guó", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ mũ khăn hoặc đại diện cho phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碣', '{"9000": "4757.0", "Chữ Trung Quốc": "碣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碣 | yết | tượng hình | bộ 石 gợi đá; tảng đá lớn đứng một mình có khắc chữ | 碣 có bộ 石 (thạch) biểu nghĩa đá, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Nghĩa gốc: tảng đá lớn đứng đơn độc (thường có khắc chữ/văn bia). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yết\": đá (石) trơ trọi — tảng đá lớn đứng một mình giữa cánh đồng, có khắc văn bia kỷ niệm sự kiện lịch sử. | Gương Hán-Việt | yết — trong 碣石 (yết thạch, đá bia), nổi tiếng trong thơ Tào Tháo ''Đông lâm yết thạch'' | Mở khoá kiến thức | Biết 碣 giúp đọc thơ Tào Tháo — 碣石 là địa danh lịch sử nổi tiếng trong bài thơ 观沧海.", "Tự nguyên_Xie": "Đại triện | Wiktionary ghi 碣 (bộ 石) với nghĩa: tảng đá lớn có khắc văn tự (inscribed stone tablet). Còn dùng nghĩa: bậc thang (trong phương ngữ Mân Nam). Bộ 石 (thạch) biểu nghĩa đá. Có dạng đại triện. Cấu trúc chi tiết chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hòn đá trơ trọi một mình", "Hạng Tần Suất (Jun Da)": "4757.0", "Tần Suất % (Jun Da)": "99.8955902817", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碣", "Unihan_Traditional (Chữ Phồn thể)": "碣", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các bia đá hoặc cột đá lớn dựng ngoài trời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诌', '{"9000": "4758.0", "Chữ Trung Quốc": "诌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 诌 | trâu | tượng hình | bộ 讠(言) gợi lời nói; nói linh tinh, bịa đặt | 诌 là dạng giản thể của 謅 (với 言+芻 rút gọn thành 刍). Bộ 讠(言) biểu nghĩa lời nói. Nghĩa gốc: nói bừa, bịa chuyện, bịa đặt lời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": lời (言) trâu tróc bịa đặt — nói lung tung, bịa chuyện như ngoa ngoắt, không đáng tin. | Gương Hán-Việt | trâu — ít dùng trong tiếng Việt; trong tiếng Trung 诌 thường dùng trong tự trào như 胡诌 (bịa bậy), 诌几句 (nói linh tinh vài câu) | Mở khoá kiến thức | Biết 诌 giúp nhận ra cách khiêm nhường tự trào trong tiếng Trung — 诌几句 (nói linh tinh vài câu) là cách nói khiêm tốn khi chia sẻ ý kiến.", "Tự nguyên_Xie": "Wiktionary ghi 诌 là dạng giản thể của 謅 — từ 言 (lời nói) + 芻 giản thành 刍. Nghĩa: chơi chữ, nói linh tinh, bịa đặt, nói bậy. Cũng có nghĩa tiếng trẻ con nói (onomatopoeia). Dạng giản thể, cấu trúc gốc chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bảo nhỏ, nhắc nhỏ", "Hạng Tần Suất (Jun Da)": "4758.0", "Tần Suất % (Jun Da)": "99.895707592", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 刍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠刍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诌", "Unihan_Traditional (Chữ Phồn thể)": "謅", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước tân ngữ để diễn tả hành vi nói dối hoặc bịa chuyện. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徕', '{"9000": "4759.0", "Chữ Trung Quốc": "徕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 10 | nét | 徕 | lai | tượng hình | bộ 彳 gợi đi lại; dụ dỗ người đến, an ủi | 徕 có bộ 彳 (xích) biểu nghĩa đi lại/bước đi, nhưng Wiktionary không cung cấp phân tích hình-thanh hay hội-ý chi tiết. Dạng cổ 徠. Nghĩa gốc: đến từ nơi khác; an ủi, khuyến khích người đến. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lai\": đi (彳) lai rai đến — khuyến khích người đến, dụ dỗ hay an ủi để kéo người về phía mình. | Gương Hán-Việt | lai — trong 招徕 (chiêu lại, thu hút khách), 往徕 (qua lại) | Mở khoá kiến thức | Biết 徕 giúp nhận ra 招徕 (thu hút khách hàng) — thuật ngữ kinh doanh/thương mại thường gặp trong tiếng Trung.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi 徕 (dạng cổ 徠): nghĩa 1 (lái): đến từ một nơi đến nơi này; nghĩa 2 (lài): an ủi, vỗ về. Bộ 彳 (xích) biểu nghĩa đi lại. Hay gặp trong 招徕 (chiêu lại — thu hút khách hàng), 劳徕 (an ủi vỗ về người lao động). Cấu trúc chi tiết chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "an ủi", "Hạng Tần Suất (Jun Da)": "4759.0", "Tần Suất % (Jun Da)": "99.8958249022", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 来", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳来", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "来", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徕", "Unihan_Traditional (Chữ Phồn thể)": "徠", "Pinyin_Xie": "lái", "Âm Hán Việt_Xie": "lại, lai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong các từ ghép mang nghĩa chiêu mộ hoặc thu hút khách hàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胴', '{"9000": "4760.0", "Chữ Trung Quốc": "胴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ 月 là dạng viết tắt của 肉) | 同 | đồng | biểu âm | (cho âm) | 胴 = 月(肉) (Nguyệt/Nhục, biểu nghĩa: thịt/thân thể) + 同 (Đồng, biểu âm). Chữ hình thanh: bộ 月(肉) chỉ thịt/thân thể, 同 cho âm dòng. Nghĩa gốc: ruột già; thân người (torso).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": thân (肉) đồng nhau — cái torso, phần thân mình trung tâm nơi các cơ quan chứa bên trong. | Gương Hán-Việt | đồng — ít dùng trong tiếng Việt; trong 胴体 (đồng thể, thân người/thân xác) | Mở khoá kiến thức | Biết 胴 giúp nhận ra 胴体 (thân xác, torso) — từ hay gặp trong văn học và y học khi mô tả cơ thể người.", "Tự nguyên_Xie": "Theo Wiktionary, 胴 là chữ hình thanh: 肉 (nhục, thịt, viết tắt là 月) biểu nghĩa, 同 (đồng) cho âm. Mang nghĩa ruột già (large intestine) và thân người (torso). Có dạng chữ bộ 月(肉), biểu thị bộ phận cơ thể. Trong tiếng Nhật mượn chữ này với nghĩa thân người rất phổ biến. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thân người; ruột già", "Hạng Tần Suất (Jun Da)": "4760.0", "Tần Suất % (Jun Da)": "99.8959422124", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胴", "Unihan_Traditional (Chữ Phồn thể)": "胴", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đỗng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học hoặc sinh học để chỉ phần thân của cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钴', '{"9000": "4761.0", "Chữ Trung Quốc": "钴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钴 | cô | tượng hình | nguyên tố coban, Co | 钴 là chữ tạo muộn để phiên âm tên nguyên tố cobalt. Wiktionary chỉ ghi {{Han etym}} không chi tiết. Bộ 金 (kim) nhiều khả năng là yếu tố biểu nghĩa chỉ kim loại; phần âm không xác định rõ. Chưa thể phân loại hình thanh hay hội ý chắc chắn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": kim loại (bộ 金) + âm cô — coban là kim loại màu xanh xám, nhớ qua chất cô đọng màu xanh đặc trưng. | Gương Hán-Việt | cô trong coban (钴 — nguyên tố Co) | Mở khoá kiến thức | Biết 钴 giúp nhận ra nhóm chữ tên nguyên tố hoá học dùng bộ 金 trong tiếng Trung.", "Tự nguyên_Xie": "钴 (phồn thể 鈷) là chữ tạo muộn để ghi tên nguyên tố cobalt (Co). Wiktionary không cung cấp phân tích tự nguyên chi tiết. Bộ 金 gợi ý đây là kim loại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố coban, Co", "Hạng Tần Suất (Jun Da)": "4761.0", "Tần Suất % (Jun Da)": "99.8960595227", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钴", "Unihan_Traditional (Chữ Phồn thể)": "鈷", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học để chỉ nguyên tố kim loại cô-ban. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裟', '{"9000": "4762.0", "Chữ Trung Quốc": "裟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裟 | sa | tượng hình | áo cà sa của tăng sĩ Phật giáo | 裟 gần như chỉ xuất hiện trong 袈裟. Wiktionary không ghi phân tích cấu trúc. Bộ 衣 (y) có thể là yếu tố biểu nghĩa chỉ quần áo. Chữ tạo muộn, chưa có phân tích tự nguyên học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": bộ 衣 (quần áo) + âm sa — áo sa 裟 của nhà sư, luôn đi kèm 袈 thành cụm 袈裟 (ca sa) quen thuộc. | Gương Hán-Việt | sa trong \"ca sa\" (袈裟 — áo cà sa tăng sĩ Phật giáo) | Mở khoá kiến thức | Biết 裟 giúp nhận ra từ 袈裟 trong văn học Phật giáo và truyện cổ Trung-Việt.", "Tự nguyên_Xie": "裟 chỉ dùng trong 袈裟 (jiā shā), phiên âm từ tiếng Phạn kāṣāya, chỉ áo cà sa tăng sĩ Phật giáo. Wiktionary không cung cấp phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ca sa 袈裟)", "Hạng Tần Suất (Jun Da)": "4762.0", "Tần Suất % (Jun Da)": "99.8961768329", "GavinGrover_Once (Chiết tự trực tiếp)": "沙 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱沙衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "裟", "Unihan_Traditional (Chữ Phồn thể)": "裟", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ và hầu như chỉ xuất hiện trong từ ghép để chỉ áo cà sa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啶', '{"9000": "4763.0", "Chữ Trung Quốc": "啶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啶 | đính | tượng hình | âm tố trong tên hoá học pyridine, pyrimidine | 啶 là chữ tạo muộn dùng để phiên âm tên vòng hoá học chứa nitơ. Không có phân tích tự nguyên từ Wiktionary. Bộ 口 (khẩu) thường xuất hiện trong chữ phiên âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": bộ 口 + âm đính — chữ chuyên dùng trong tên vòng hoá học chứa nitơ như pyridine 吡啶, pyrimidine 嘧啶. | Gương Hán-Việt | đính trong \"mật đính\" (嘧啶 — pyrimidine, base nitơ trong DNA) | Mở khoá kiến thức | Biết 啶 giúp đọc tên các hợp chất hoá học hữu cơ vòng nitơ trong tài liệu Trung văn khoa học.", "Tự nguyên_Xie": "啶 là chữ tạo muộn, không có lịch sử tự hình cổ đại. Dùng làm âm tố trong tên hợp chất vòng dị nhân chứa nitơ: pyridine (吡啶) và pyrimidine (嘧啶). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mật đính 嘧啶)", "Hạng Tần Suất (Jun Da)": "4763.0", "Tần Suất % (Jun Da)": "99.8962941431", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啶", "Unihan_Traditional (Chữ Phồn thể)": "啶", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong hóa học hữu cơ để cấu tạo tên các hợp chất vòng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铣', '{"9000": "4764.0", "Chữ Trung Quốc": "铣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | kim | biểu nghĩa | kim loại | 先 | tiên | biểu âm | trước, đầu tiên | 铣 là dạng giản thể của 銑 (thay 釒 bằng 钅). Chữ hình thanh: bộ 钅 (kim) biểu nghĩa chỉ kim loại; phần âm phù cho âm đọc xǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩy\": 钅 (kim loại) + âm phù — máy phay 铣 dùng để \"tẩy\" gọt bề mặt kim loại cho nhẵn bóng. | Gương Hán-Việt | tẩy trong \"tẩy sàng\" (铣床 — máy phay, thiết bị gia công cơ khí) | Mở khoá kiến thức | Biết 铣 giúp đọc thuật ngữ cơ khí: 铣床 (máy phay), 铣刀 (dao phay), 铣削 (phay gọt).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 铣 là dạng giản thể của 銑, đơn giản hoá bộ 釒 thành 钅. Chữ hình thanh với bộ kim loại 钅 biểu nghĩa. Trong tiếng Trung hiện đại dùng chỉ máy phay (milling machine) hoặc gang (hợp kim sắt-carbon). Wiktionary không cung cấp phân tích tự nguyên đầy đủ cho dạng phồn thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gang (hợp kim của sắt và carbon)", "Hạng Tần Suất (Jun Da)": "4764.0", "Tần Suất % (Jun Da)": "99.8964109365", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 先", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "先", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铣", "Unihan_Traditional (Chữ Phồn thể)": "銑", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "tiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc gia công cắt gọt kim loại bằng máy phay. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铱', '{"9000": "4765.0", "Chữ Trung Quốc": "铱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 衣 | y | biểu âm | áo | 铱 (phồn thể 銥) là chữ hình thanh: bộ 金 (kim) biểu nghĩa chỉ đây là kim loại; 衣 (y, đọc yī) biểu âm cung cấp âm đọc yī gần khớp với âm của nguyên tố iridium.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\": 金 (kim loại) + 衣 (y, biểu âm) — iridium là kim loại quý hiếm và cứng nhất, bền như lớp giáp 衣 bảo hộ. | Gương Hán-Việt | y trong \"y\" (铱 — iridium Ir, kim loại bạch kim nhóm) | Mở khoá kiến thức | Biết 铱 giúp nhận ra nhóm chữ tên nguyên tố hoá học dùng bộ 金 + âm phù trong tiếng Trung.", "Tự nguyên_Xie": "铱 (phồn thể 銥) là chữ hình thanh do 金 (kim, kim loại, biểu nghĩa) + 衣 (y, biểu âm, đọc yī) tạo thành. Bộ 金 xác định đây là kim loại; 衣 cho âm yī. Chữ được tạo để phiên âm tên nguyên tố iridium (Ir) trong tiếng Trung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố iridi, Ir", "Hạng Tần Suất (Jun Da)": "4765.0", "Tần Suất % (Jun Da)": "99.89652773", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铱", "Unihan_Traditional (Chữ Phồn thể)": "銥", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong khoa học để chỉ nguyên tố kim loại chuyển tiếp y-ri-đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楫', '{"9000": "4766.0", "Chữ Trung Quốc": "楫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | cây gỗ | 咠 | biểu âm | 楫 là chữ hình thanh: bộ 木 (mộc) biểu nghĩa chỉ đây là vật dụng bằng gỗ; 咠 biểu âm cung cấp âm đọc jí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": 木 (gỗ) + âm phù — mái chèo gỗ 楫 trong thành ngữ 中流击楫 (trung lưu kích tập — đập mái chèo giữa dòng, biểu lộ chí khí mạnh mẽ). | Gương Hán-Việt | tập trong \"chu tập\" (舟楫 — thuyền và mái chèo) | Mở khoá kiến thức | Biết 楫 mở khoá cụm 舟楫 và thành ngữ 中流击楫 trong thơ văn cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 楫 là chữ hình thanh gồm 木 (mộc, gỗ, biểu nghĩa) + 咠 (biểu âm). Nghĩa gốc là mái chèo (oar, paddle) bằng gỗ để chèo thuyền. Trong văn học cổ điển 楫 còn dùng như động từ \"chèo thuyền\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mái chèo phía trước", "Hạng Tần Suất (Jun Da)": "4766.0", "Tần Suất % (Jun Da)": "99.8966445234", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 咠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木咠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楫", "Unihan_Traditional (Chữ Phồn thể)": "楫", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mái chèo hoặc làm động từ chỉ việc chèo thuyền trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赭', '{"9000": "4767.0", "Chữ Trung Quốc": "赭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 赤 | Số nét | 15 | nét | 赭 | chả | tượng hình | màu đỏ nâu, đất đỏ son | 赭 có bộ 赤 (xích, đỏ) biểu nghĩa liên quan đến màu đỏ. Wiktionary chỉ ghi {{Han etym}}. Cấu trúc chi tiết không xác định được; khả năng là hình thanh với bộ 赤 biểu nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chả\": bộ 赤 (đỏ) — màu đỏ đất son 赭 gợi sắc nâu đỏ đặc trưng của đất pigment thiên nhiên dùng trong hội hoạ. | Gương Hán-Việt | chả trong \"chả thạch\" (赭石 — đá son, pigment tự nhiên màu đỏ nâu) | Mở khoá kiến thức | Biết 赭 giúp đọc từ vựng màu sắc và khoáng vật trong hoạ luận, bản thảo cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 赭 mang bộ 赤 (xích, đỏ), gợi ý trực tiếp đến nghĩa màu đỏ nâu (ochre). Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đỏ son; đất đỏ", "Hạng Tần Suất (Jun Da)": "4767.0", "Tần Suất % (Jun Da)": "99.8967613169", "GavinGrover_Once (Chiết tự trực tiếp)": "赤 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赤者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "赤", "Unihan_Simplified (Chữ Giản thể)": "赭", "Unihan_Traditional (Chữ Phồn thể)": "赭", "Pinyin_Xie": "zhě", "Âm Hán Việt_Xie": "giả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ màu sắc đỏ đất hoặc danh từ chỉ đất đỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碛', '{"9000": "4768.0", "Chữ Trung Quốc": "碛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碛 | tích | tượng hình | bãi cát sỏi, sa mạc | 碛 (phồn thể 磧) có bộ 石 (thạch, đá) biểu nghĩa chỉ địa hình gồm đá và cát. Wiktionary chỉ ghi {{Han etym}}, không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ 石 (đá) — bãi đá cát 碛 như sa mạc Trung Á, nơi đoàn lữ hành tích lũy gian khổ trên Con đường Tơ lụa. | Gương Hán-Việt | tích trong \"sa tích\" (沙碛 — bãi cát sa mạc, hay gặp trong thơ Đường) | Mở khoá kiến thức | Biết 碛 giúp đọc địa danh sa mạc và cảnh quan trong thơ Đường như 大碛 (đại tích).", "Tự nguyên_Xie": "Tiểu triện | 碛 (phồn thể 磧) mang bộ 石 (thạch, đá), chỉ địa hình bãi cát sỏi hoặc sa mạc. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bãi sa mạc, bãi cát giữa sông", "Hạng Tần Suất (Jun Da)": "4768.0", "Tần Suất % (Jun Da)": "99.8968775935", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 责", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石责", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "责", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碛", "Unihan_Traditional (Chữ Phồn thể)": "磧", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ bãi cát nổi giữa sông hoặc vùng sa mạc đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酊', '{"9000": "4769.0", "Chữ Trung Quốc": "酊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 9 | nét | 酊 | đính | tượng hình | say rượu, trong từ 酩酊 | 酊 có bộ 酉 (dậu) biểu nghĩa chỉ rượu và trạng thái say. Wiktionary chỉ ghi {{Han etym}}, không phân tích chi tiết cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": bộ 酉 (rượu) — 酊 trong 酩酊大醉, hình dung người say mèm nghiêng ngả. | Gương Hán-Việt | đính trong \"mính đính\" (酩酊 — say khướt, say mèm hoàn toàn) | Mở khoá kiến thức | Biết 酊 giúp nhận ra cụm 酩酊大醉 trong văn học và hội thoại hàng ngày.", "Tự nguyên_Xie": "酊 mang bộ 酉 (dậu, rượu), biểu thị liên quan đến rượu. Chủ yếu dùng trong 酩酊 (mính đính — say khướt). Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mính đính 酩酊)", "Hạng Tần Suất (Jun Da)": "4769.0", "Tần Suất % (Jun Da)": "99.8969938702", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酊", "Unihan_Traditional (Chữ Phồn thể)": "酊", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh, đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường kết hợp thành từ ghép chỉ trạng thái say khướt hoặc làm danh từ chỉ cồn thuốc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魑', '{"9000": "4770.0", "Chữ Trung Quốc": "魑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 19 | nét | 鬼 | quỷ | biểu nghĩa | ma quỷ | 离 | ly | biểu âm | 魑 là chữ hình thanh: bộ 鬼 (quỷ) biểu nghĩa chỉ loại yêu quái; 离 (ly) biểu âm cung cấp âm đọc chī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": 鬼 (quỷ) + 离 (ly, biểu âm) — ly quỷ 魑 là yêu tinh núi hình hổ, trong 魑魅魍魉 (bốn loại ma quỷ cổ đại). | Gương Hán-Việt | ly trong \"ly mị\" (魑魅 — yêu quái núi rừng) | Mở khoá kiến thức | Biết 魑 giúp nhận ra thành ngữ 魑魅魍魉 (ly mị vọng lượng) — mọi loại ma quỷ, tà ác.", "Tự nguyên_Xie": "魑 là chữ hình thanh gồm 鬼 (quỷ, ma quỷ, biểu nghĩa) + 离 (biểu âm). Nghĩa gốc chỉ loại yêu quái núi rừng hình hổ. Thường gặp trong cụm 魑魅魍魉 (ly mị vọng lượng — các loại ma quỷ rừng núi sông hồ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ma quỷ", "Hạng Tần Suất (Jun Da)": "4770.0", "Tần Suất % (Jun Da)": "99.8971101468", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魑", "Unihan_Traditional (Chữ Phồn thể)": "魑", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "si", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép để chỉ các loài ma quỷ, yêu quái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醛', '{"9000": "4771.0", "Chữ Trung Quốc": "醛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 酉 | dậu | biểu nghĩa | nhóm chức oxi hoá | 荃 | biểu âm | cây thơm | 醛 là chữ kết hợp hội ý và hình thanh: 酉 (dậu, biểu nghĩa nhóm chức oxi hoá) + 荃 (biểu âm quán/quán, đọc quán). Tên aldehyde mang hương thơm của nhiều hợp chất, nên 荃 (cây thơm) cũng có nghĩa biểu ý. Wiktionary liệt kê cả ls=ic và ls=psc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toàn\": 酉 (nhóm chức hoá học) + 荃 (cây thơm, biểu âm) — aldehyde 醛 nổi tiếng vì mùi thơm đặc trưng. | Gương Hán-Việt | toàn trong \"toàn\" (醛 — aldehyde, nhóm chức -CHO trong hoá học hữu cơ) | Mở khoá kiến thức | Biết 醛 giúp đọc tên hợp chất hoá học hữu cơ: 甲醛 (formaldehyde), 乙醛 (acetaldehyde).", "Tự nguyên_Xie": "醛 là chữ kết hợp hai cách phân tích: hội ý (酉 biểu nhóm chức + 荃 cây thơm, gợi hương thơm của aldehyde) và hình thanh (酉 biểu nghĩa + 荃 biểu âm quán). Được tạo để phiên dịch thuật ngữ aldehyde trong hoá học hữu cơ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "aldehyde (hoá học)", "Hạng Tần Suất (Jun Da)": "4771.0", "Tần Suất % (Jun Da)": "99.8972264235", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 荃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉荃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醛", "Unihan_Traditional (Chữ Phồn thể)": "醛", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ hợp chất hữu cơ an-đê-hít. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剐', '{"9000": "4772.0", "Chữ Trung Quốc": "剐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 9 | nét | 剐 | quả | tượng hình | lăng trì, róc thịt khỏi xương | 剐 là dạng dị thể của 剮. Cấu trúc không rõ ràng từ Wiktionary. Bộ 刀 (đao) có thể biểu nghĩa liên quan đến cắt. Chữ tạo muộn, không có phân tích tự nguyên học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\": bộ 刀 (dao) + âm quả — hình phạt 剐 (lăng trì) là cực hình cắt từng phần cơ thể, ghê tởm nhất trong hình luật cổ đại. | Gương Hán-Việt | quả trong \"lăng trì\" (凌迟/剐 — hình phạt cắt thịt từng phần, nay chỉ còn trong sử sách) | Mở khoá kiến thức | Biết 剐 giúp đọc văn bản lịch sử và pháp luật cổ đại Trung Hoa về các hình phạt xưa.", "Tự nguyên_Xie": "剐 là dạng dị thể không chính thức của 剮, đơn giản hoá bộ 咼 thành 呙. Liên quan đến hình phạt lăng trì — cắt, róc thịt. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lăng trì, hình phạt róc thịt", "Hạng Tần Suất (Jun Da)": "4772.0", "Tần Suất % (Jun Da)": "99.8973421834", "GavinGrover_Once (Chiết tự trực tiếp)": "呙 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰呙刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剐", "Unihan_Traditional (Chữ Phồn thể)": "剮", "Pinyin_Xie": "guǎ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động xẻo thịt hoặc thi hành hình phạt lăng trì. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畦', '{"9000": "4773.0", "Chữ Trung Quốc": "畦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 11 | nét | 田 | điền | biểu nghĩa | ruộng đồng | 圭 | quê | biểu âm | 畦 là chữ hình thanh: bộ 田 (điền) biểu nghĩa chỉ đây là phần đất canh tác; 圭 (quê) biểu âm cung cấp âm đọc qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": 田 (ruộng) + 圭 (quê, biểu âm) — thửa ruộng 畦 được chia ô vuông vắn như viên ngọc khuê, gọn gàng có trật tự. | Gương Hán-Việt | khuê trong \"thái khuê\" (菜畦 — luống rau, thửa rau) | Mở khoá kiến thức | Biết 畦 giúp đọc văn bản nông nghiệp và thơ điền viên, như 菜畦 (luống rau), 花畦 (luống hoa).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 畦 là chữ hình thanh gồm 田 (điền, ruộng, biểu nghĩa) + 圭 (quê, biểu âm). Nghĩa gốc là phần đất ruộng được chia ô theo luống, hoặc đơn vị diện tích bằng 25-50 mẫu (畝). Còn có nghĩa là chia ruộng thành từng ô để canh tác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thửa ruộng, luống rau; 50 mẫu", "Hạng Tần Suất (Jun Da)": "4773.0", "Tần Suất % (Jun Da)": "99.8974579432", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畦", "Unihan_Traditional (Chữ Phồn thể)": "畦", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "huề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ luống rau hoặc làm lượng từ cho luống, thửa ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陂', '{"9000": "4774.0", "Chữ Trung Quốc": "陂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阜 | phụ | biểu nghĩa | gò đất, núi đất | 皮 | bì | biểu âm | da | 陂 là chữ hình thanh: bộ 阜 (phụ) biểu nghĩa chỉ địa hình dốc núi; 皮 (bì) biểu âm cung cấp âm đọc bēi/pí/pō.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bê\": 阜 (gò đất) + 皮 (bì, biểu âm) — sườn dốc 陂 như lớp da bọc ngoài quả đồi, dẫn nước xuống ao hồ. | Gương Hán-Việt | bê trong \"bê\" (陂 — sườn núi, bờ ao, hay gặp trong địa danh) | Mở khoá kiến thức | Biết 陂 giúp đọc địa danh và thơ sơn thuỷ: 陂塘 (ao hồ), 高陂 (tên địa danh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 陂 là chữ hình thanh gồm 阜 (phụ, gò đất/núi đất, biểu nghĩa) + 皮 (bì, biểu âm). Nghĩa chính là sườn núi, bờ ao hoặc hồ chứa nước. Có nhiều cách đọc: bēi (sườn núi), pí (tên riêng), pō (xiên lệch). Gặp trong tên địa danh và thơ văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dốc, nghiêng, chếch; cái dốc, sườn núi", "Hạng Tần Suất (Jun Da)": "4774.0", "Tần Suất % (Jun Da)": "99.8975737031", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陂", "Unihan_Traditional (Chữ Phồn thể)": "陂", "Pinyin_Xie": "bēi", "Âm Hán Việt_Xie": "bi, pha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ đê đập, ao hồ hoặc tính từ chỉ sự nghiêng lệch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闶', '{"9000": "4775.0", "Chữ Trung Quốc": "闶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 7 | nét | 闶 | kháng | tượng hình | cao lớn, đồ sộ; cửa | 闶 (phồn thể 閌) có bộ 門 (môn, cửa) biểu nghĩa. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc chi tiết không xác định được. Chữ ít dùng, chủ yếu trong từ ghép 閌閬.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kháng\": bộ 門 (cửa) — cửa cao đồ sộ 闶 gợi hình cổng lớn của dinh thự hay cung điện. | Gương Hán-Việt | kháng trong \"kháng lãng\" (閌閬 — cao lớn, đồ sộ) | Mở khoá kiến thức | Biết 闶 giúp nhận ra từ ghép 閌閬 trong văn học cổ tả kiến trúc nguy nga.", "Tự nguyên_Xie": "Tiểu triện | 闶 (phồn thể 閌) mang bộ 門 (môn, cửa), gợi ý liên quan đến cửa hoặc không gian cao rộng. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao lớn, đồ sộ", "Hạng Tần Suất (Jun Da)": "4775.0", "Tần Suất % (Jun Da)": "99.897689463", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闶", "Unihan_Traditional (Chữ Phồn thể)": "閌", "Pinyin_Xie": "kāng", "Âm Hán Việt_Xie": "khang, kháng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả không gian cao rộng hoặc kiến trúc đồ sộ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阄', '{"9000": "4776.0", "Chữ Trung Quốc": "阄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 10 | nét | 阄 | cưu | tượng hình | thăm, rút thăm | 阄 là dạng giản thể của 鬮, đơn giản hoá 龜 thành 龟 và 鬥 thành 门. Phồn thể 鬮 là chữ hội ý phức tạp. Giản thể 阄 dùng bộ 门 (cửa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cưu\": dạng giản của 鬮 — rút thăm 阄 là phương pháp phân chia công bằng, cưu mang số phận. | Gương Hán-Việt | cưu trong \"bắt cưu\" (抓阄 — rút thăm, bắt thăm) | Mở khoá kiến thức | Biết 阄 giúp nhận ra từ 抓阄 (bắt thăm) trong văn nói và hội thoại hàng ngày.", "Tự nguyên_Xie": "Tiểu triện | 阄 là dạng giản thể của 鬮, đơn giản hoá bằng cách thay 龜 (rùa) bằng 龟 và 鬥 (đấu) bằng 门. Phồn thể 鬮 có thể nguyên liên quan đến việc dùng rùa (卜卦) để bói thăm trong cổ đại. Nghĩa là rút thăm, bắt thăm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rút lấy, gắp lấy", "Hạng Tần Suất (Jun Da)": "4776.0", "Tần Suất % (Jun Da)": "99.8978052228", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 龟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门龟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阄", "Unihan_Traditional (Chữ Phồn thể)": "鬮", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "cưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ lá thăm hoặc kết hợp làm động từ bắt thăm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祚', '{"9000": "4777.0", "Chữ Trung Quốc": "祚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 礻 | kỳ | biểu nghĩa | thần linh, lễ tế | 乍 | sạ | biểu âm | 祚 là chữ hình thanh: bộ 礻 (kỳ, biến thể của 示) biểu nghĩa chỉ liên quan đến thần linh/phúc lành; 乍 (sạ) biểu âm cung cấp âm đọc zuò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tộ\": 礻 (thần linh) + 乍 (sạ, biểu âm) — phúc tộ 祚 là ân điển của thần thánh ban cho triều đại, nên mới gắn với ngôi vua. | Gương Hán-Việt | tộ trong \"quốc tộ\" (國祚 — vận nước, tuổi thọ triều đại) | Mở khoá kiến thức | Biết 祚 giúp đọc văn bản lịch sử và chính trị cổ đại: 國祚 (vận nước), 踐祚 (lên ngôi).", "Tự nguyên_Xie": "Đại triện | 祚 là chữ hình thanh gồm 礻 (示, biểu nghĩa thần linh/phúc lành) + 乍 (biểu âm). Nghĩa gốc là phúc lành, vận mệnh tốt; sau mở rộng sang nghĩa ngôi vua, triều đại. Gặp trong văn học cổ điển với nghĩa \"vận nước\", \"ngôi báu\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngôi vua, triều vua; vận nước; phúc", "Hạng Tần Suất (Jun Da)": "4777.0", "Tần Suất % (Jun Da)": "99.8979204659", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 乍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻乍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祚", "Unihan_Traditional (Chữ Phồn thể)": "祚", "Pinyin_Xie": "zuò", "Âm Hán Việt_Xie": "tộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ chỉ vận mệnh quốc gia hoặc ngôi vị hoàng đế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹘', '{"9000": "4778.0", "Chữ Trung Quốc": "鹘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 鹘 | cốt | tượng hình | chim ưng, chim cắt; một loài chim | 鹘 (phồn thể 鶻) có bộ 鳥 (điểu, chim) biểu nghĩa. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc đầy đủ không xác định được; chữ ít dùng ngoài tên chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốt\": bộ 鳥 (chim) + âm cốt — chim cắt 鹘 nổi tiếng trong thơ Đường tả chiến trận và săn bắn, mạnh mẽ như cốt cách chiến binh. | Gương Hán-Việt | cốt trong \"hồi cốt\" (回鶻 — Hồi Hột, tên bộ tộc Turk trong lịch sử Trung Á) | Mở khoá kiến thức | Biết 鹘 giúp đọc tên bộ tộc 回鶻 (Hồi Hột/Uyghur) và thơ văn tả chiến trận và săn bắn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鹘 (phồn thể 鶻) mang bộ 鳥 (điểu, chim), chỉ loài chim cắt (falcon). Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loài chim hung ác)", "Hạng Tần Suất (Jun Da)": "4778.0", "Tần Suất % (Jun Da)": "99.898035709", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "鹘", "Unihan_Traditional (Chữ Phồn thể)": "鶻", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "hốt, cốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loài chim săn mồi hoặc tính từ trong từ ghép chỉ sự mơ hồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泱', '{"9000": "4779.0", "Chữ Trung Quốc": "泱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泱 | ương | tượng hình | mênh mông, bao la; hơi nước bốc lên | 泱 có bộ 水/氵 (thuỷ) biểu nghĩa chỉ liên quan đến nước. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc hình thanh hay hội ý không xác định rõ từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ương\": bộ 氵 (nước) + âm ương — 泱泱大国 (ương ương đại quốc) gợi hình quốc gia mênh mông như biển cả. | Gương Hán-Việt | ương trong \"ương ương\" (泱泱 — bao la, mênh mông, dùng trong 泱泱大国) | Mở khoá kiến thức | Biết 泱 giúp nhận ra cụm 泱泱大国 (ương ương đại quốc — quốc gia mênh mông, cường thịnh) trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 泱 mang bộ 氵 (thuỷ, nước), liên quan đến nước bao la hoặc hơi nước bốc lên. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí bốc ngùn ngụt", "Hạng Tần Suất (Jun Da)": "4779.0", "Tần Suất % (Jun Da)": "99.8981504353", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泱", "Unihan_Traditional (Chữ Phồn thể)": "泱", "Pinyin_Xie": "yāng", "Âm Hán Việt_Xie": "ương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng trước danh từ để miêu tả cảnh sông nước bao la. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趄', '{"9000": "4780.0", "Chữ Trung Quốc": "趄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 12 | nét | 趄 | thư | tượng hình | bước đi khó khăn, do dự; nghiêng lệch | 趄 có bộ 走 (tẩu) biểu nghĩa chỉ hành động đi lại. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc đầy đủ không xác định. Chữ ít dùng độc lập, chủ yếu trong từ ghép 趑趄, 趔趄.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": bộ 走 (đi) + âm thư — bước chân 趄 trong 趑趄 (tư thư) gợi hình người do dự, bước đi chần chừ không dứt khoát. | Gương Hán-Việt | thư trong \"thư\" (趄 — bước đi khó khăn, do dự; trong 趔趄 — loạng choạng) | Mở khoá kiến thức | Biết 趄 giúp nhận ra từ ghép 趑趄 (tư thư — do dự không tiến) và 趔趄 (liệt thư — loạng choạng) trong văn học.", "Tự nguyên_Xie": "趄 mang bộ 走 (tẩu, đi), liên quan đến cách đi lại khó khăn, do dự. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tư thư 趑趄); (xem: liệt thư 趔趄)", "Hạng Tần Suất (Jun Da)": "4780.0", "Tần Suất % (Jun Da)": "99.8982651616", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趄", "Unihan_Traditional (Chữ Phồn thể)": "趄", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ và thường xuất hiện trong các từ láy chỉ dáng đi không vững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骅', '{"9000": "4781.0", "Chữ Trung Quốc": "骅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 9 | nét | 骅 | hoa | tượng hình | ngựa tốt, ngựa quý | 骅 (phồn thể 驊) có bộ 馬 (mã) biểu nghĩa chỉ ngựa. Wiktionary ghi {{Han etym}} không chi tiết. Chữ chỉ dùng trong 驊騮 (hoa lưu — tên loài ngựa quý).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\": bộ 馬 (ngựa) + âm hoa — ngựa hoa 骅 chỉ giống ngựa thuần chủng quý như hoa nở, gặp trong 驊騮 (hoa lưu). | Gương Hán-Việt | hoa trong \"hoa lưu\" (驊騮 — giống ngựa quý thuần chủng) | Mở khoá kiến thức | Biết 骅 giúp nhận ra từ 驊騮 (hoa lưu) trong thơ văn cổ tả ngựa quý và anh hùng.", "Tự nguyên_Xie": "Đại triện | 骅 (phồn thể 驊) mang bộ 馬 (mã, ngựa), chỉ loài ngựa tốt quý. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chỉ dùng trong 驊騮 (hoa lưu — giống ngựa thuần chủng nổi tiếng). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hoa lưu 驊驑,驊騮)", "Hạng Tần Suất (Jun Da)": "4781.0", "Tần Suất % (Jun Da)": "99.8983798879", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 华", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马华", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "华", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骅", "Unihan_Traditional (Chữ Phồn thể)": "驊", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ các giống ngựa chiến dũng mãnh thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陲', '{"9000": "4782.0", "Chữ Trung Quốc": "陲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 10 | nét | 阜 | phụ | biểu nghĩa | gò đất, núi đất | 垂 | thuỳ | biểu âm | rủ xuống | 陲 là chữ hình thanh: bộ 阜 (phụ) biểu nghĩa chỉ địa hình vùng biên giới núi đất; 垂 (thuỳ) biểu âm cung cấp âm đọc chuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuỳ\": 阜 (đất dốc) + 垂 (thuỳ, biểu âm) — biên giới 陲 là vùng đất \"thuỳ\" xuống ở rìa ngoài lãnh thổ, xa xôi hiu quạnh. | Gương Hán-Việt | thuỳ trong \"biên thuỳ\" (边陲 — vùng biên giới, miền biên cương) | Mở khoá kiến thức | Biết 陲 giúp đọc từ 边陲 (biên thuỳ) trong thơ Đường và văn bản địa lý lịch sử.", "Tự nguyên_Xie": "Tiểu triện | 陲 là chữ hình thanh gồm 阜 (phụ, gò đất/núi, biểu nghĩa) + 垂 (thuỳ, biểu âm). Nghĩa là biên giới, vùng biên cương. Gặp trong thơ Đường và văn cổ trong từ 边陲 (biên thuỳ — vùng biên giới). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biên giới", "Hạng Tần Suất (Jun Da)": "4782.0", "Tần Suất % (Jun Da)": "99.8984946142", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陲", "Unihan_Traditional (Chữ Phồn thể)": "陲", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "thùy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp với các từ chỉ phương hướng để chỉ vùng biên cương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郧', '{"9000": "4783.0", "Chữ Trung Quốc": "郧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 郧 | vân | tượng hình | nước Vân thời xưa; huyện Vân (Hồ Bắc) | 郧 là dạng giản thể của 鄖, đơn giản hoá 員 thành 员. Bộ 邑 (ấp) biểu nghĩa chỉ địa danh/nước. Chữ dùng làm tên địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": bộ 邑 (ấp, địa danh) + âm vân — Vân 郧 là tên huyện ở Hồ Bắc, nơi tìm thấy hoá thạch người cổ đại Trung Quốc (Vân Nhân). | Gương Hán-Việt | vân trong \"Vân Huyện\" (郧县 — Huyện Vân, Hồ Bắc, Trung Quốc) | Mở khoá kiến thức | Biết 郧 giúp đọc địa danh và lịch sử tỉnh Hồ Bắc, đặc biệt về khảo cổ học người tiền sử.", "Tự nguyên_Xie": "Tiểu triện | 郧 là dạng giản thể của 鄖, thay 員 bằng 员. Bộ 邑 (ấp) chỉ đây là địa danh, tên một nước cổ hoặc huyện. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Vân thời xưa; huyện Vân", "Hạng Tần Suất (Jun Da)": "4783.0", "Tần Suất % (Jun Da)": "99.8986088237", "GavinGrover_Once (Chiết tự trực tiếp)": "员 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰员阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "员", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "郧", "Unihan_Traditional (Chữ Phồn thể)": "鄖", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng để chỉ địa danh hoặc tên nước thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倜', '{"9000": "4784.0", "Chữ Trung Quốc": "倜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 周 | chu | biểu âm | chu vi, xung quanh | 倜 là chữ hình thanh: bộ 亻 (nhân) biểu nghĩa chỉ đây là phẩm chất của người; 周 (chu) biểu âm. Đáng chú ý: Từ điển Thuyết Văn gốc không có chữ này — Từ Huyền thêm vào sau nhưng không nhận ra 周 là âm phù do sự khác biệt âm học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truật\": 亻 (người) + 周 (chu, biểu âm) — người 倜 傥 (truật đảng) là người phóng khoáng, hào sảng không bị ràng buộc tục lệ. | Gương Hán-Việt | truật trong \"truật đảng\" (倜傥 — phóng khoáng, hào hoa, tự do thoải mái) | Mở khoá kiến thức | Biết 倜 giúp nhận ra từ 倜傥 (truật đảng — hào hoa phóng khoáng) trong thơ văn và văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 倜 là chữ hình thanh gồm 亻 (nhân, người, biểu nghĩa) + 周 (chu, biểu âm). Chữ này không có trong bản gốc Thuyết Văn; Từ Huyền thêm vào nhưng không nhận ra 周 là âm phù do sự khác biệt âm vị học giữa 周 và 倜 trong tiếng Hán trung cổ. Nghĩa là mạnh mẽ, hào phóng, phóng khoáng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mạnh mẽ, mãnh liệt", "Hạng Tần Suất (Jun Da)": "4784.0", "Tần Suất % (Jun Da)": "99.8987230332", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倜", "Unihan_Traditional (Chữ Phồn thể)": "倜", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ và hầu như chỉ xuất hiện trong từ ghép thích thảng để tả người phóng khoáng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呤', '{"9000": "4785.0", "Chữ Trung Quốc": "呤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 呤 | gầm | tượng hình | tiếng nói nhỏ; purine (hoá học) | 呤 có bộ 口 (khẩu) biểu nghĩa liên quan đến âm thanh hoặc lời nói. Wiktionary ghi {{Han etym}} không chi tiết. Chữ dùng trong thuật ngữ hoá học (嘌呤 — purine) và từ cổ chỉ giọng nói nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gầm\": bộ 口 (miệng) + âm gầm — 呤 dùng trong 嘌呤 (purine), hợp chất hoá học quan trọng trong DNA và RNA. | Gương Hán-Việt | gầm trong \"tiêu gầm\" (嘌呤 — purine, base nitơ trong axit nucleic) | Mở khoá kiến thức | Biết 呤 giúp đọc thuật ngữ hoá học và y học: 嘌呤 (purine), 蝶呤 (pterin).", "Tự nguyên_Xie": "呤 mang bộ 口 (khẩu, miệng/tiếng), liên quan đến âm thanh. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng nói nhỏ nhẹ", "Hạng Tần Suất (Jun Da)": "4785.0", "Tần Suất % (Jun Da)": "99.8988372427", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呤", "Unihan_Traditional (Chữ Phồn thể)": "呤", "Pinyin_Xie": "lìng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này làm danh từ trong hóa học hoặc dùng làm từ mô phỏng âm thanh thì thầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燧', '{"9000": "4786.0", "Chữ Trung Quốc": "燧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 16 | nét | 火 | hoả | biểu nghĩa | lửa | 遂 | toại | biểu âm | đạt được, tiến hành | 燧 là chữ hình thanh: bộ 火 (hoả) biểu nghĩa chỉ đây là vật liên quan đến lửa; 遂 (toại) biểu âm cung cấp âm đọc suì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toại\": 火 (lửa) + 遂 (toại, biểu âm) — đá lửa 燧 của Toại Nhân (燧人氏) — con người đầu tiên trong thần thoại Trung Hoa phát minh ra cách tạo lửa. | Gương Hán-Việt | toại trong \"phong toại\" (烽燧 — đài lửa hiệu, tín hiệu khói lửa biên phòng) | Mở khoá kiến thức | Biết 燧 giúp đọc từ 燧人氏 (Toại Nhân) và 烽燧 (đài lửa hiệu) trong văn bản lịch sử và thần thoại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 燧 là chữ hình thanh gồm 火 (hoả, lửa, biểu nghĩa) + 遂 (toại, biểu âm). Nghĩa gốc là đá lửa (flintstone) dùng để đánh lửa, hoặc đuốc tín hiệu (beacon fire). Còn có nghĩa bó đuốc. Liên quan đến Toại Nhân (燧人氏) — vị thần thoại người đầu tiên dạy loài người tạo ra lửa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ để lấy lửa; bó đuốc", "Hạng Tần Suất (Jun Da)": "4786.0", "Tần Suất % (Jun Da)": "99.8989514523", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "燧", "Unihan_Traditional (Chữ Phồn thể)": "燧", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "toại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các công cụ tạo lửa hoặc đài lửa báo động thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铉', '{"9000": "4787.0", "Chữ Trung Quốc": "铉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 铉 | huyễn | tượng hình | thanh xuyên qua tai đỉnh để khiêng vạc | 铉 (phồn thể 鉉) có bộ 金 (kim) biểu nghĩa chỉ đây là công cụ kim loại. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc hình thanh hay hội ý không xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": bộ 金 (kim loại) + âm huyễn — thanh 铉 xuyên qua tai vạc đỉnh, dùng để khiêng chiếc đỉnh quý trong nghi lễ cổ đại. | Gương Hán-Việt | huyễn trong \"ngọc huyễn\" (玉鉉 — thanh ngọc xuyên vạc, đồ lễ khí quý) | Mở khoá kiến thức | Biết 铉 giúp hiểu văn bản lễ chế và khảo cổ Trung Hoa về các đồ đỉnh quý.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 铉 (phồn thể 鉉) mang bộ 金 (kim, kim loại), chỉ dụng cụ bằng kim loại dùng để khiêng vạc đỉnh (ding cauldron). Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xuyên tai đỉnh (vạc ba chân)", "Hạng Tần Suất (Jun Da)": "4787.0", "Tần Suất % (Jun Da)": "99.8990656618", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铉", "Unihan_Traditional (Chữ Phồn thể)": "鉉", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận của chiếc vạc đồng cổ hoặc dùng đặt tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粲', '{"9000": "4788.0", "Chữ Trung Quốc": "粲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 13 | nét | 米 | mễ | biểu âm | gạo | 粲 là chữ hình thanh theo Wiktionary: 𣦼 (biểu âm) + 米 (mễ, biểu nghĩa gạo). Nghĩa gốc là gạo giã kỹ, trắng sáng; mở rộng sang nghĩa tươi sáng, rõ ràng, nụ cười rạng rỡ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xán\": 米 (gạo trắng) + âm phù — gạo trắng tinh 粲 gợi sắc trắng sáng rực rỡ, như nụ cười xán lạn 粲然一笑. | Gương Hán-Việt | xán trong \"xán nhiên\" (粲然 — rạng rỡ, tươi sáng, nụ cười đẹp) | Mở khoá kiến thức | Biết 粲 giúp nhận ra từ 粲然 (xán nhiên — rạng rỡ) trong thơ văn cổ điển tả vẻ đẹp.", "Tự nguyên_Xie": "粲 là chữ hình thanh gồm 𣦼 (biểu âm) + 米 (mễ, gạo, biểu nghĩa). Nghĩa gốc là gạo đã giã kỹ trắng sáng; từ đó mở rộng sang nghĩa tươi sáng đẹp đẽ, rõ ràng minh bạch, cười phì cười. Wiktionary ghi {{Han etym}} không chi tiết ngoài cấu trúc cơ bản. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo đã giã kỹ; tươi sáng, đẹp đẽ; rõ ràng, minh bạch; cười, phì cười", "Hạng Tần Suất (Jun Da)": "4788.0", "Tần Suất % (Jun Da)": "99.8991793545", "GavinGrover_Once (Chiết tự trực tiếp)": "𣦼 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𣦼米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣦼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粲", "Unihan_Traditional (Chữ Phồn thể)": "粲", "Pinyin_Xie": "càn", "Âm Hán Việt_Xie": "xán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Chữ này làm tính từ để miêu tả vẻ rực rỡ hoặc làm động từ chỉ nụ cười tươi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骶', '{"9000": "4789.0", "Chữ Trung Quốc": "骶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 14 | nét | 骶 | đê | tượng hình | xương cùng, xương cụt (giải phẫu) | 骶 có bộ 骨 (cốt, xương) biểu nghĩa chỉ đây là xương. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc hình thanh hay hội ý không xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đê\": bộ 骨 (xương) + âm đê — xương 骶 (xương cùng) là xương ở \"đáy\" cột sống, thấp nhất như âm đê vậy. | Gương Hán-Việt | đê trong \"tý đê\" (髀骶 — xương hông và xương cùng) | Mở khoá kiến thức | Biết 骶 giúp đọc thuật ngữ giải phẫu học: 骶骨 (xương cùng), 骶椎 (đốt sống cùng).", "Tự nguyên_Xie": "骶 mang bộ 骨 (cốt, xương), chỉ xương cùng/xương cụt (sacrum) trong giải phẫu. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "húc nhau", "Hạng Tần Suất (Jun Da)": "4789.0", "Tần Suất % (Jun Da)": "99.8992930472", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骶", "Unihan_Traditional (Chữ Phồn thể)": "骶", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong thuật ngữ y học để chỉ phần xương cùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峁', '{"9000": "4790.0", "Chữ Trung Quốc": "峁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 8 | nét | 峁 | mão | tượng hình | đồi đất vàng tròn ở Tây Bắc Trung Quốc | 峁 có bộ 山 (sơn) biểu nghĩa chỉ đây là dạng địa hình. Không có phân tích tự nguyên từ Wiktionary. Chữ tạo muộn, mô tả địa hình đặc trưng vùng hoàng thổ Tây Bắc Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mão\": bộ 山 (núi) + âm mão — đồi hoàng thổ 峁 tròn như mũ (mão), đặc trưng vùng đất vàng Thiểm Tây, Cam Túc. | Gương Hán-Việt | mão trong \"mão\" (峁 — đồi hoàng thổ tròn, địa hình đặc trưng Tây Bắc Trung Quốc) | Mở khoá kiến thức | Biết 峁 giúp đọc văn bản địa lý, địa chất về vùng hoàng thổ (黄土高原) Tây Bắc Trung Quốc.", "Tự nguyên_Xie": "峁 là chữ tạo muộn không có lịch sử tự hình cổ đại. Wiktionary không cung cấp phân tích tự nguyên. Bộ 山 (sơn) chỉ đây là dạng địa hình. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng đồi đất vàng ở miền Tây Bắc Trung Quốc", "Hạng Tần Suất (Jun Da)": "4790.0", "Tần Suất % (Jun Da)": "99.8994062232", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 卯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山卯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峁", "Unihan_Traditional (Chữ Phồn thể)": "峁", "Pinyin_Xie": "mǎo", "Âm Hán Việt_Xie": "mão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một dạng địa hình đồi đất đặc thù ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忸', '{"9000": "4791.0", "Chữ Trung Quốc": "忸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忸 | nữu | tượng hình | xấu hổ, mắc cỡ; chủ yếu trong 忸怩 | 忸 có bộ 忄/心 (tâm) biểu nghĩa chỉ trạng thái tâm lý. Wiktionary ghi {{Han etym}} không chi tiết. Chủ yếu dùng trong từ ghép 忸怩 (nữu ni — xấu hổ, ngượng ngùng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữu\": bộ 忄 (tâm) + âm nữu — trạng thái 忸怩 (nữu ni) là vẻ xấu hổ ngượng ngùng trong lòng, đỏ mặt không dám nói thẳng. | Gương Hán-Việt | nữu trong \"nữu ni\" (忸怩 — xấu hổ ngượng ngùng, e thẹn) | Mở khoá kiến thức | Biết 忸 giúp nhận ra từ 忸怩 và 忸怩作态 (giả vờ ngượng ngùng) thường gặp trong văn học miêu tả tính cách.", "Tự nguyên_Xie": "Lục thư thông | 忸 mang bộ 忄 (tâm, tình cảm/tâm lý), chỉ trạng thái xấu hổ ngượng ngùng. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nữu ni 忸怩)", "Hạng Tần Suất (Jun Da)": "4791.0", "Tần Suất % (Jun Da)": "99.8995193991", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忸", "Unihan_Traditional (Chữ Phồn thể)": "忸", "Pinyin_Xie": "niǔ", "Âm Hán Việt_Xie": "nữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ biểu thị sự ngượng ngùng và hay kết hợp thành từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渌', '{"9000": "4792.0", "Chữ Trung Quốc": "渌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 渌 | lục | tượng hình | nước trong, nước sạch | 渌 có bộ 氵 (thuỷ) biểu nghĩa chỉ liên quan đến nước. Không có phân tích tự nguyên từ Wiktionary. Chữ tạo muộn mô tả nước trong sạch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": bộ 氵 (nước) + âm lục — nước trong xanh 渌 như lá lục, gợi hình suối trong vắt ở chốn thôn quê. | Gương Hán-Việt | lục trong \"lục thuỷ\" (渌水 — nước trong, suối trong xanh) | Mở khoá kiến thức | Biết 渌 giúp đọc thơ phong cảnh và từ điển cổ tả vẻ nước trong.", "Tự nguyên_Xie": "渌 là chữ tạo muộn mang bộ 氵 (thuỷ, nước), chỉ nước trong, nước sạch hoặc hành động lọc nước. Wiktionary không cung cấp phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước trong, nước sạch", "Hạng Tần Suất (Jun Da)": "4792.0", "Tần Suất % (Jun Da)": "99.8996325751", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渌", "Unihan_Traditional (Chữ Phồn thể)": "淥", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ để tả nước trong suốt hoặc làm động từ chỉ việc lọc nước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骞', '{"9000": "4793.0", "Chữ Trung Quốc": "骞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 13 | nét | 骞 | khiên | tượng hình | ngẩng cao, bay lên; thiếu, sứt mẻ | 骞 (phồn thể 騫) có bộ 馬 (mã) biểu nghĩa chỉ ngựa. Wiktionary ghi {{Han etym}} không chi tiết. Chữ ít dùng độc lập, nổi tiếng qua tên người Trương Khiên (张骞) — sứ giả con đường tơ lụa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiên\": bộ 馬 (ngựa) + âm khiên — Trương Khiên (张骞) cưỡi ngựa khiên dẫn đường mở Con đường Tơ lụa, bay cao như con chim soaring. | Gương Hán-Việt | khiên trong \"Trương Khiên\" (张骞 — nhà thám hiểm Hán mở đường sang Tây Vực) | Mở khoá kiến thức | Biết 骞 giúp nhận ra tên Trương Khiên (张骞) — nhân vật lịch sử quan trọng mở đầu Con đường Tơ lụa.", "Tự nguyên_Xie": "骞 (phồn thể 騫) mang bộ 馬 (mã, ngựa). Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiếu, sứt mẻ; hất lên, ngẩng lên; giật lấy; tội lỗi; ngựa hèn", "Hạng Tần Suất (Jun Da)": "4793.0", "Tần Suất % (Jun Da)": "99.899745751", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "骞", "Unihan_Traditional (Chữ Phồn thể)": "騫", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động bay cao hoặc làm tính từ chỉ sự sứt mẻ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髭', '{"9000": "4794.0", "Chữ Trung Quốc": "髭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 16 | nét | 須 | tua | biểu nghĩa | râu | 此 | thử | biểu âm | 髭 ban đầu là tượng hình vẽ người có ria mép nổi bật. Sau đó được viết thành 頿/頾 — hình thanh với 須 (tua, râu) biểu nghĩa + 此 (thử) biểu âm. Dạng hiện đại dùng bộ 髟 (tóc dài) thay 須. Wiktionary ghi rõ lịch sử tiến hoá tự hình này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": 髟 (tóc) + 此 (thử, biểu âm) — ria mép 髭 chỉ chùm lông trên môi, người \"tư\" thế thường để ria cho oai phong. | Gương Hán-Việt | tư trong \"tư tu\" (髭鬚 — ria mép và râu) | Mở khoá kiến thức | Biết 髭 giúp phân biệt 髭 (ria mép) với 鬚 (râu cằm) và 鬓 (tóc mai) trong miêu tả ngoại hình.", "Tự nguyên_Xie": "Kim văn | Đại triện | 髭 ban đầu là tượng hình vẽ người với ria mép nổi bật. Về sau viết lại thành 頿/頾 (須 biểu nghĩa + 此 biểu âm). Dạng hiện đại dùng bộ 髟 (tóc/lông) + 此 (biểu âm). Nghĩa chuyên chỉ ria mép (mustache) — tóc trên môi trên, phân biệt với 鬚 (toàn bộ râu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ria mép; râu; râu mép", "Hạng Tần Suất (Jun Da)": "4794.0", "Tần Suất % (Jun Da)": "99.899858927", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髭", "Unihan_Traditional (Chữ Phồn thể)": "髭", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ chỉ hành động để hoặc cạo râu mép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戡', '{"9000": "4795.0", "Chữ Trung Quốc": "戡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 13 | nét | 甚 | tham | biểu âm | rất, lắm | 戈 | qua | biểu nghĩa | kích, vũ khí có lưỡi ngang | 戡 là chữ hình thanh: bộ 戈 (qua, kích) biểu nghĩa chỉ đây là hành động quân sự; 甚 (tham) biểu âm cung cấp âm đọc kān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kham\": 戈 (vũ khí) + 甚 (tham, biểu âm) — kham loạn 戡乱 là dùng vũ lực bình định loạn lạc, thể hiện sức kham chịu và kiên quyết. | Gương Hán-Việt | kham trong \"kham loạn\" (戡乱 — bình định loạn lạc, dẹp loạn) | Mở khoá kiến thức | Biết 戡 giúp đọc văn bản lịch sử và quân sự: 戡乱 (kham loạn — dẹp loạn).", "Tự nguyên_Xie": "Bạch thư | Đại triện | 戡 là chữ hình thanh gồm 甚 (tham, biểu âm) + 戈 (qua, kích, biểu nghĩa). Bộ 戈 xác định đây là hành động quân sự — bình định, dẹp loạn. Nghĩa là đánh thắng, bình định (subdue, quell). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết, đánh được", "Hạng Tần Suất (Jun Da)": "4795.0", "Tần Suất % (Jun Da)": "99.8999721029", "GavinGrover_Once (Chiết tự trực tiếp)": "甚 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甚戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戡", "Unihan_Traditional (Chữ Phồn thể)": "戡", "Pinyin_Xie": "kān", "Âm Hán Việt_Xie": "kham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ giặc giã để chỉ việc dẹp loạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钨', '{"9000": "4796.0", "Chữ Trung Quốc": "钨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 金 | kim | biểu nghĩa | kim loại | 烏 | ô | biểu âm | quạ, màu đen | 钨 (phồn thể 鎢) là chữ hình thanh: bộ 金 (kim) biểu nghĩa chỉ đây là kim loại; 烏 (ô) biểu âm cung cấp âm đọc wū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": 金 (kim loại) + 烏 (ô, biểu âm) — vonfram 钨 có màu xám đen như quạ 烏, điểm nóng chảy cao nhất trong tất cả các nguyên tố. | Gương Hán-Việt | ô trong \"ô\" (钨 — vonfram W, kim loại có điểm nóng chảy cao nhất) | Mở khoá kiến thức | Biết 钨 giúp đọc thuật ngữ công nghiệp: 钨钢 (thép vonfram), 钨丝 (sợi vonfram trong bóng đèn).", "Tự nguyên_Xie": "钨 (phồn thể 鎢) là chữ hình thanh gồm 金 (kim, kim loại, biểu nghĩa) + 烏 (ô, biểu âm, đọc wū). Chữ được tạo để phiên âm tên nguyên tố tungsten/wolfram (W) trong tiếng Trung. Bộ 金 xác định đây là kim loại; 烏 cho âm wū. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố vonfram, W", "Hạng Tần Suất (Jun Da)": "4796.0", "Tần Suất % (Jun Da)": "99.9000847621", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 乌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅乌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钨", "Unihan_Traditional (Chữ Phồn thể)": "鎢", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nguyên tố hóa học hoặc chất liệu cấu thành vật dụng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谲', '{"9000": "4797.0", "Chữ Trung Quốc": "谲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 谲 | quyệt | tượng hình | lừa lọc, quỷ quyệt, xảo trá | 谲 (phồn thể 譎) có bộ 言 (ngôn) biểu nghĩa chỉ liên quan đến lời nói/ngôn ngữ theo cách xảo trá. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc không xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyệt\": bộ 言 (lời nói) + âm quyệt — người quyệt 谲 dùng lời nói xảo trá để lừa đảo, như sóng gió biến ảo 波谲云诡. | Gương Hán-Việt | quyệt trong \"quyệt\" (谲诈 — gian trá, xảo quyệt) | Mở khoá kiến thức | Biết 谲 giúp nhận ra thành ngữ 波谲云诡 (ba quyệt vân quỷ — biến đổi khó lường) và từ 诡谲 (quỷ quyệt).", "Tự nguyên_Xie": "谲 (phồn thể 譎) mang bộ 言 (ngôn, lời nói), gợi ý liên quan đến ngôn từ lừa đảo, xảo quyệt. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lừa lọc, quỷ quyệt", "Hạng Tần Suất (Jun Da)": "4797.0", "Tần Suất % (Jun Da)": "99.9001974212", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 矞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠矞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谲", "Unihan_Traditional (Chữ Phồn thể)": "譎", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép chỉ sự gian trá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苋', '{"9000": "4798.0", "Chữ Trung Quốc": "苋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苋 | hiện | tượng hình | cây rau dền (Amaranthus tricolor) | 苋 là dạng giản thể của 莧, đơn giản hoá 見 thành 见. Bộ 艸/艹 (thảo) biểu nghĩa chỉ đây là thực vật. Cấu trúc đầy đủ không phân tích chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiện\": bộ 艹 (cỏ cây) + 见 (nhìn thấy) — rau dền 苋 lá đỏ tím hiện rõ trong vườn rau, màu sắc nổi bật dễ nhận ra ngay. | Gương Hán-Việt | hiện trong \"hiện thái\" (苋菜 — rau dền, loại rau lá đỏ tím phổ biến) | Mở khoá kiến thức | Biết 苋 giúp đọc tên rau củ trong thực đơn và tài liệu nông nghiệp Trung văn.", "Tự nguyên_Xie": "Tiểu triện | 苋 là dạng giản thể của 莧 (thay 見 bằng 见). Bộ 艹 (thảo, cỏ cây) chỉ đây là loại thực vật. Nghĩa là cây rau dền (Amaranthus tricolor), loại rau phổ biến. Wiktionary không cung cấp phân tích tự nguyên chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây rau dền", "Hạng Tần Suất (Jun Da)": "4798.0", "Tần Suất % (Jun Da)": "99.9003100804", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苋", "Unihan_Traditional (Chữ Phồn thể)": "莧", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "hiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với từ chỉ màu sắc để gọi tên rau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锃', '{"9000": "4799.0", "Chữ Trung Quốc": "锃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锃 | chắng | tượng hình | bóng sáng loáng sau khi đánh bóng | 锃 (phồn thể 鋥) có bộ 金 (kim) biểu nghĩa chỉ kim loại. Wiktionary ghi {{Han etym}} không chi tiết. Cấu trúc không xác định rõ. Chữ ít dùng, chủ yếu trong 锃亮 (sáng bóng loáng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chắng\": bộ 金 (kim loại) + âm chắng — kim loại 锃 sáng bóng chắng như gương sau khi lau chùi kỹ. | Gương Hán-Việt | chắng trong \"chắng lượng\" (锃亮 — sáng bóng loáng, bóng như gương) | Mở khoá kiến thức | Biết 锃 giúp nhận ra từ 锃亮 (sáng bóng loáng) và 锃光瓦亮 trong văn miêu tả đồ vật sạch bóng.", "Tự nguyên_Xie": "锃 (phồn thể 鋥) mang bộ 金 (kim, kim loại), chỉ vật dụng kim loại sáng bóng sau khi đánh bóng. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng loáng; sáng bóng; xiềng; như \"xiềng xích\" (vhn)", "Hạng Tần Suất (Jun Da)": "4799.0", "Tần Suất % (Jun Da)": "99.9004227395", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锃", "Unihan_Traditional (Chữ Phồn thể)": "鋥", "Pinyin_Xie": "zèng", "Âm Hán Việt_Xie": "tránh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả độ sáng bóng của kim loại hoặc đồ vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜊', '{"9000": "4800.0", "Chữ Trung Quốc": "蜊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, động vật nhỏ | 利 | lợi | biểu âm | sắc bén, lợi nhuận | 蜊 là chữ hình thanh: bộ 虫 (trùng) biểu nghĩa chỉ đây là động vật nhỏ/thủy sinh; 利 (lợi) biểu âm cung cấp âm đọc lí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lị\": 虫 (động vật) + 利 (lợi, biểu âm) — con trai 蜊 trong 蛤蜊 (cáp lị) là hải sản lị (có lợi), vỏ cứng hai mảnh. | Gương Hán-Việt | lị trong \"cáp lị\" (蛤蜊 — con trai, nghêu biển) | Mở khoá kiến thức | Biết 蜊 giúp nhận ra từ 蛤蜊 (con trai, nghêu) trong thực đơn hải sản và ẩm thực Trung Quốc.", "Tự nguyên_Xie": "蜊 là chữ hình thanh gồm 虫 (trùng, động vật nhỏ, biểu nghĩa) + 利 (lợi, biểu âm). Nghĩa là con trai/con nghêu (clam). Thường gặp trong từ ghép 蛤蜊 (cáp lị — con trai/nghêu, loại hải sản phổ biến). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cáp lị 蛤蜊)", "Hạng Tần Suất (Jun Da)": "4800.0", "Tần Suất % (Jun Da)": "99.9005353987", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 利", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫利", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜊", "Unihan_Traditional (Chữ Phồn thể)": "蜊", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như chỉ xuất hiện trong từ ghép chỉ loài nghêu sò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幄', '{"9000": "4801.0", "Chữ Trung Quốc": "幄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 12 | nét | 幄 | ác | tượng hình | lều trướng có màn che | 幄 là chữ tạo muộn, chưa thấy cấu trúc thành phần rõ trong giáp cốt hay kim văn. Chữ thuộc bộ 巾 (cân — vải), biểu thị lều có màn che. Chưa xác định rõ hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ác\": hình ảnh tấm màn vải (巾) che lều trướng — nơi các tướng lĩnh vạch mưu kế bên trong 帷幄. | Gương Hán-Việt | 帷幄 (duy ác) — màn trướng, nơi bàn mưu; 運籌帷幄 (vận trù duy ác) — mưu tính trong màn trướng | Mở khoá kiến thức | Biết 幄 mở khoá từ 帷幄 (duy ác — trướng phủ mưu lược) và thành ngữ 運籌帷幄 (điều binh khiển tướng từ phía sau).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary không cung cấp nguồn gốc cụ thể cho 幄. Dựa vào cấu trúc, 幄 thuộc bộ 巾 (cân, vải), liên quan đến lều vải, màn trướng. Chữ xuất hiện chủ yếu trong từ 帷幄 (duy ác — màn trướng, trướng phủ nơi bàn việc quân). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái màn", "Hạng Tần Suất (Jun Da)": "4801.0", "Tần Suất % (Jun Da)": "99.9006475411", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 屋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾屋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幄", "Unihan_Traditional (Chữ Phồn thể)": "幄", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại màn trướng lớn dùng trong quân đội xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闼', '{"9000": "4802.0", "Chữ Trung Quốc": "闼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 闼 | thát | tượng hình | cửa nhỏ bên trong | 闼 (phồn thể: 闥) là chữ tạo muộn chưa rõ cấu trúc thành phần từ lsCodes. Chữ thuộc bộ 門 (môn — cửa), biểu thị cửa nhỏ bên trong hoặc cửa hậu. Chưa xác định hình thanh hay hội ý từ nguồn Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thát\": cửa (門) nhỏ bên trong cung điện — 排闥 (bài thát) là đẩy thẳng cửa vào, hành động táo bạo. | Gương Hán-Việt | 排闥 (bài thát) — đẩy cửa bước vào; 閨闥 (khuê thát) — cửa phòng khuê nữ | Mở khoá kiến thức | Biết 闼 mở khoá từ 排闥 (bài thát — đột ngột xông vào) và 宮闥 (cung thát — cửa cung điện).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 闥 là cửa nhỏ, cửa trong — \"small door; inner door\". Trong văn cổ 《錢神論》 thời Tây Tấn có câu dùng 紫闥 (tử thát) chỉ cửa cung điện màu tím. Chưa có phân tích hình thanh hay hội ý rõ ràng từ nguồn học thuật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa ngách trong cung", "Hạng Tần Suất (Jun Da)": "4802.0", "Tần Suất % (Jun Da)": "99.9007596835", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 达", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门达", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "达", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闼", "Unihan_Traditional (Chữ Phồn thể)": "闥", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "thát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ lối đi hoặc cửa nhỏ trong các kiến trúc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戕', '{"9000": "4803.0", "Chữ Trung Quốc": "戕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 8 | nét | 爿 | tường | biểu âm | nửa cây gỗ chẻ đôi (biểu âm) | 戈 | qua | biểu nghĩa | vũ khí — giáo mác | 戕 = 爿 (Tường, biểu âm) + 戈 (Qua, biểu nghĩa: vũ khí). Chữ hình thanh (psc): bộ 戈 chỉ nghĩa sát thương bằng vũ khí, 爿 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\": giáo mác (戈) bổ xuống như chẻ cây (爿) — hình ảnh sát hại bằng vũ khí lạnh. | Gương Hán-Việt | 戕害 (tường hại) — làm tổn hại; 自戕 (tự tường) — tự làm hại mình | Mở khoá kiến thức | Biết 戕 mở khoá từ 戕害 (tường hại — tàn hại) và 自戕 (tự tường — tự huỷ hoại).", "Tự nguyên_Xie": "Theo Wiktionary, 戕 là chữ hình thanh: 爿 (c1=p, biểu âm) + 戈 (c2=s, biểu nghĩa — dagger-axe, giáo mác). Bộ 戈 chỉ vũ khí, mang nghĩa sát hại, tàn hại. 戕 có nghĩa là giết, làm hại, tàn phá. Dùng trong văn ngôn như 戕害 (tổn hại). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết hại", "Hạng Tần Suất (Jun Da)": "4803.0", "Tần Suất % (Jun Da)": "99.9008718258", "GavinGrover_Once (Chiết tự trực tiếp)": "爿 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爿戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爿", "Unihan_Simplified (Chữ Giản thể)": "戕", "Unihan_Traditional (Chữ Phồn thể)": "戕", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc kết hợp thành từ ghép để chỉ hành vi tàn hại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骊', '{"9000": "4804.0", "Chữ Trung Quốc": "骊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 10 | nét | 馬 | mã | biểu nghĩa | ngựa | 麗 | lệ | biểu âm | đẹp (cho âm) | 骊 (phồn thể: 驪) = 馬 (Mã, biểu nghĩa: ngựa) + 麗 (Lệ, biểu âm). Chữ hình thanh (psc): bộ 馬 chỉ loài ngựa, 麗 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": con ngựa (馬) đẹp như vẻ lệ (麗) — đặc chỉ ngựa đen tuyền quý giá. | Gương Hán-Việt | 驪山 (Lệ Sơn) — núi ở Thiểm Tây; 驪歌 (lệ ca) — bài hát tiễn biệt | Mở khoá kiến thức | Biết 骊 mở khoá từ 骊山 (Lệ Sơn — núi lịch sử), 骊歌 (lệ ca — bài tiễn biệt) và từ ngữ về ngựa đen.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 驪 là chữ hình thanh: 馬 (c1=s, biểu nghĩa — horse) + 麗 (c2=p, biểu âm). 驪 chỉ ngựa màu đen tuyền. Trong thư tịch cổ, 驪山 (Lệ Sơn) — ngọn núi nổi tiếng ở Thiểm Tây. Chữ còn gặp trong 驪歌 (lệ ca — bài hát tiễn biệt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa ô", "Hạng Tần Suất (Jun Da)": "4804.0", "Tần Suất % (Jun Da)": "99.9009839682", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 丽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马丽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骊", "Unihan_Traditional (Chữ Phồn thể)": "驪", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ ngựa đen hoặc làm tính từ bổ nghĩa trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虢', '{"9000": "4805.0", "Chữ Trung Quốc": "虢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 15 | nét | 爪 | trảo | móng vuốt, bàn tay | 攴 | phác | tay cầm gậy đánh | 虎 | hổ | hổ | 虢 có cấu trúc phức tạp. Một thuyết: hai bàn tay (寽) dang ra hai bên con hổ (虎) — nguyên hình của 鞹 (da thú). Thuyết 《說文》 cho là hình thanh: 寽 (biểu âm) + 虎 (biểu nghĩa), nhưng không được học giới đồng thuận rộng rãi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": tên nước chư hầu thời Tây Chu — hình ảnh hai tay (爪) chế ngự hổ (虎), biểu trưng quyền lực. | Gương Hán-Việt | 虢國 (Quắc quốc) — nước Quắc thời Tây Chu; 假途滅虢 (giả đồ diệt Quắc) — mượn đường diệt nước | Mở khoá kiến thức | Biết 虢 mở khoá thành ngữ 假途滅虢 (giả đồ diệt Quắc — mượn cớ để diệt) và tri thức lịch sử thời Tây Chu.", "Tự nguyên_Xie": "Theo Wiktionary, một thuyết (Lâm Nghị Quang) cho 虢 là chữ tượng hình: hai bàn tay (寽) bóc lột da hổ (虎), nguyên hình của 鞹 (da thú đã thuộc). 《說文》 xếp là hình thanh: 寽 + 虎, nhưng giới học thuật không đồng thuận. 虢 là tên nhiều nước chư hầu thời Tây Chu (1050-770 TCN), nằm ở Thiểm Tây và Hồ Nam. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Quắc", "Hạng Tần Suất (Jun Da)": "4805.0", "Tần Suất % (Jun Da)": "99.9010961106", "GavinGrover_Once (Chiết tự trực tiếp)": "寽 + 虎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰寽虎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "寽", "Unihan_Simplified (Chữ Giản thể)": "虢", "Unihan_Traditional (Chữ Phồn thể)": "虢", "Pinyin_Xie": "guó", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ tên nước chư hầu thời Chu hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烩', '{"9000": "4806.0", "Chữ Trung Quốc": "烩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 烩 | hối | tượng hình | nấu chung nhiều nguyên liệu | 烩 (phồn thể: 燴) là chữ tạo muộn, chưa có cấu trúc thành phần rõ từ nguồn học thuật. Chữ thuộc bộ 火 (hoả — lửa), biểu thị phương pháp nấu ăn dùng lửa. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hối\": lửa (火) nấu hầm hỗn hợp — 大雜燴 (đại tạp hối) là nồi thập cẩm mọi thứ đổ vào. | Gương Hán-Việt | 大雜燴 (đại tạp hối) — hỗn tạp, lộn xộn; 燴飯 (hối phạn) — cơm chan nước hầm | Mở khoá kiến thức | Biết 烩 mở khoá từ 大杂烩 (đại tạp hối — thập cẩm) và 烩饭 (hối phạn — cơm thập cẩm).", "Tự nguyên_Xie": "Wiktionary ghi 燴 có nghĩa: to ragout, to braise (nấu hầm, om). Còn chỉ món ăn lịch sử gồm cá nướng tái rồi thái mỏng như tataki. Từ phổ biến nhất là 大雜燴 (đại tạp hối — nồi lẩu thập cẩm, chuyển nghĩa: hỗn độn). Chưa có phân tích nguồn gốc chữ từ học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu hỗn tạp, nấu chung", "Hạng Tần Suất (Jun Da)": "4806.0", "Tần Suất % (Jun Da)": "99.9012077362", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烩", "Unihan_Traditional (Chữ Phồn thể)": "燴", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ phương pháp nấu ăn bằng cách cho nhiều nguyên liệu vào ninh nhừ cùng nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傥', '{"9000": "4807.0", "Chữ Trung Quốc": "傥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 12 | nét | 傥 | thảng | tượng hình | nếu, giả sử | 傥 (phồn thể: 儻) là chữ tạo muộn thuộc bộ 亻(nhân — người). Chưa có cấu trúc thành phần rõ ràng từ nguồn học thuật. Thường gặp trong từ 倜儻 (thận thảng — phong lưu, hào phóng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảng\": người (亻) hành xử tự do thoải mái như nếu (thảng) muốn — 倜儻 là phong cách hào phóng không bị gò bó. | Gương Hán-Việt | 倜儻 (thận thảng) — phong lưu hào phóng; 儻來 (thảng lai) — đến một cách tình cờ | Mở khoá kiến thức | Biết 傥 mở khoá từ 倜傥 (thận thảng — phong lưu tài tử) và thành ngữ về tính cách phóng khoáng.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 儻 có nghĩa là if, supposing, in case (nếu, giả sử). Thường gặp trong 倜儻 (thận thảng — phong lưu tài hoa, không bị ràng buộc) và 儻來 (thảng lai — đến tình cờ). Chưa có phân tích nguồn gốc chữ cụ thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giả sử; bất ngờ, không mong muốn", "Hạng Tần Suất (Jun Da)": "4807.0", "Tần Suất % (Jun Da)": "99.9013193618", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 党", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻党", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "党", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傥", "Unihan_Traditional (Chữ Phồn thể)": "儻", "Pinyin_Xie": "tǎng", "Âm Hán Việt_Xie": "thảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Phó từ | 副词 | Thường làm liên từ biểu thị giả thuyết hoặc phó từ chỉ sự đột ngột trong văn viết cổ. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妲', '{"9000": "4808.0", "Chữ Trung Quốc": "妲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 8 | nét | 妲 | dát | tượng hình | tên riêng phụ nữ | 妲 thuộc bộ 女 (nữ — phụ nữ). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chủ yếu dùng làm tên riêng, nổi tiếng nhất là 妲己 (Đát Kỷ) — sủng phi của vua Trụ nhà Thương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dát\": chữ nữ (女) gắn với tên 妲己 (Đát Kỷ) — người đẹp tai tiếng trong Phong Thần, biểu tượng hồ ly quyến rũ. | Gương Hán-Việt | 妲己 (Đát Kỷ) — sủng phi Trụ Vương, nhân vật Phong Thần Diễn Nghĩa | Mở khoá kiến thức | Biết 妲 mở khoá tên 妲己 (Đát Kỷ) — nhân vật lịch sử-thần thoại nổi tiếng Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không kèm phân tích cụ thể cho 妲. Chữ thuộc bộ 女 (nữ), dùng chủ yếu làm tên riêng. Nổi tiếng nhất là 妲己 (Đát Kỷ) — sủng phi của Trụ Vương, nhân vật phản diện trong Phong Thần Diễn Nghĩa. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "4808.0", "Tần Suất % (Jun Da)": "99.9014309873", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妲", "Unihan_Traditional (Chữ Phồn thể)": "妲", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong tên người, tiêu biểu là nàng Đát Kỷ thời Thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绌', '{"9000": "4809.0", "Chữ Trung Quốc": "绌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 绌 | truất | tượng hình | thiếu hụt, không đủ | 绌 (phồn thể: 絀) thuộc bộ 糸 (mịch — sợi chỉ, vải). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ có nghĩa thiếu hụt, không đủ — thường gặp trong 相形見絀 (tương hình kiến truất — so sánh thấy mình kém cỏi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truất\": sợi chỉ (糸) bị thiếu — 相形見絀 (tương hình kiến truất) là tự thấy mình kém khi so sánh. | Gương Hán-Việt | 相形見絀 (tương hình kiến truất) — so sánh thấy kém; 支絀 (chi truất) — chi tiêu thiếu hụt | Mở khoá kiến thức | Biết 绌 mở khoá từ 相形见绌 (tương hình kiến truất — thua kém khi so sánh) và 左支右绌 (bị động, túng thiếu).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 絀 có các nghĩa: insufficient (thiếu), deep red (đỏ thẫm, nghĩa cổ), sew/stitch (may, khâu, nghĩa cổ), cũng là dị thể của 黜 (cách chức). Chữ thuộc bộ 糸 (sợi chỉ). Nghĩa thông dụng hiện đại là thiếu hụt trong 相形見絀. Chưa có nguồn học thuật đầy đủ về nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiếu, không đủ", "Hạng Tần Suất (Jun Da)": "4809.0", "Tần Suất % (Jun Da)": "99.9015426129", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绌", "Unihan_Traditional (Chữ Phồn thể)": "絀", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "truất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ sự thiếu thốn, không đủ hoặc động từ chỉ sự bãi chức, giảm bớt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桠', '{"9000": "4810.0", "Chữ Trung Quốc": "桠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桠 | a | tượng hình | nhánh cây, chạc cây | 桠 là dạng giản thể của 椏, thay phần 亞 bằng 亚. Chữ thuộc bộ 木 (mộc — cây). 椏 biểu thị cành cây, chạc cây — chỗ phân nhánh. Chưa có phân tích hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"a\": cây (木) có chạc phân nhánh — 枝桠 (chi a) là các nhánh cây nhỏ trải ra như bàn tay. | Gương Hán-Việt | 枝桠 (chi a) — cành nhánh cây; 树桠 (thụ a) — chạc cây | Mở khoá kiến thức | Biết 桠 mở khoá từ 枝桠 (chi a — cành nhánh nhỏ) trong thơ ca và văn miêu tả thiên nhiên.", "Tự nguyên_Xie": "Wiktionary ghi 桠 là dạng giản thể của 椏 (thay 亞→亚). 椏 chỉ nhánh cây, chỗ phân nhánh của cây. Bộ 木 (mộc) biểu thị sự liên quan đến cây cối. Cấu trúc gốc chưa được phân tích học thuật đầy đủ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạc cây", "Hạng Tần Suất (Jun Da)": "4810.0", "Tần Suất % (Jun Da)": "99.9016542385", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桠", "Unihan_Traditional (Chữ Phồn thể)": "椏", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ nơi cành cây chia nhánh hoặc chạc cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袈', '{"9000": "4811.0", "Chữ Trung Quốc": "袈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袈 | cà | tượng hình | áo cà sa Phật giáo | 袈 thuộc bộ 衣 (y — áo). Chữ chỉ dùng trong 袈裟 (cà sa) — áo của tăng ni Phật giáo, mượn âm từ tiếng Phạn kasāya. Wiktionary không cung cấp cấu trúc thành phần chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cà\": áo (衣) của nhà sư — 袈裟 (cà sa) là tấm vải vàng nâu quấn quanh người tu hành Phật giáo. | Gương Hán-Việt | 袈裟 (cà sa) — áo cà sa của tăng ni Phật giáo | Mở khoá kiến thức | Biết 袈 mở khoá từ 袈裟 (cà sa) — trang phục biểu tượng của tăng ni Phật giáo Đông Á.", "Tự nguyên_Xie": "Wiktionary ghi 袈 chỉ dùng trong 袈裟, phiên âm từ tiếng Phạn kasāya (nghĩa là màu sắc đặc biệt của vải nhuộm — vàng đất, nâu đỏ). Áo cà sa là trang phục truyền thống của tăng ni Phật giáo. Chữ được tạo ra để phiên âm, không có cấu trúc ý nghĩa riêng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ca sa 袈裟)", "Hạng Tần Suất (Jun Da)": "4811.0", "Tần Suất % (Jun Da)": "99.9017658641", "GavinGrover_Once (Chiết tự trực tiếp)": "加 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱加衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "袈", "Unihan_Traditional (Chữ Phồn thể)": "袈", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "cà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ sa để tạo thành danh từ chỉ áo cà sa của tăng ni Phật giáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎗', '{"9000": "4812.0", "Chữ Trung Quốc": "鎗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎗 | thương | tượng hình | vũ khí có cán dài, tiếng kim loại va chạm | 鎗 thuộc bộ 金 (kim — kim loại). Không có dữ liệu Wiktionary cho 鎗. Chữ cổ chỉ vũ khí có cán dài (giáo thương) hoặc tiếng kim loại kêu vang. Là dạng phồn thể/cổ thể của 枪 (súng, giáo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": kim loại (金) rèn thành giáo dài — 鎗 là dạng cổ của 枪 (súng/giáo), âm thanh kim loại vang. | Gương Hán-Việt | 鎗 là cổ thể của 枪 (thương) — giáo, vũ khí cán dài; tiếng kim loại va chạm | Mở khoá kiến thức | Biết 鎗 mở khoá cổ văn về vũ khí và hiểu mối liên hệ với 枪 (thương) hiện đại.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Không có dữ liệu Wiktionary cho 鎗. Chữ thuộc bộ 金 (kim loại), cổ thể liên quan đến 枪 (thương — giáo, súng). 鎗 xuất hiện trong kim văn và tiểu triện, biểu thị vũ khí cán dài hoặc tiếng kim loại va nhau. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "súng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 倉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金倉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎗", "Unihan_Traditional (Chữ Phồn thể)": "鎗", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại vũ khí như súng hoặc giáo mác thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薮', '{"9000": "4813.0", "Chữ Trung Quốc": "薮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薮 | tẩu | tượng hình | vùng đầm lầy cỏ rậm, chỗ tụ họp | 薮 (phồn thể: 藪) thuộc bộ 艹 (thảo — cỏ). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chỉ vùng đầm lầy cỏ rậm, nơi tụ tập — thường dùng ẩn dụ như 渊薮 (uyên tẩu — nơi tụ hội của kẻ xấu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": cỏ (艹) um tùm vùng đầm — 渊薮 (uyên tẩu) là vực sâu cỏ rậm, ẩn dụ nơi tụ tập tội lỗi. | Gương Hán-Việt | 渊薮 (uyên tẩu) — sào huyệt, nơi tụ tập (xấu); 藪泽 (tẩu trạch) — đầm lầy | Mở khoá kiến thức | Biết 薮 mở khoá từ 渊薮 (uyên tẩu — sào huyệt tội phạm) và từ địa lý 薮泽 (đầm lầy).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể cho 藪. Chữ thuộc bộ 艹 (thảo), biểu thị vùng đầm lầy um tùm cỏ cây. Thường dùng ẩn dụ: 渊薮 (uyên tẩu — sào huyệt, nơi tụ tập). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chằm lớn, cái đầm; nơi tụ tập; nơi thôn dã", "Hạng Tần Suất (Jun Da)": "4813.0", "Tần Suất % (Jun Da)": "99.9019885985", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 数", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹数", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "数", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薮", "Unihan_Traditional (Chữ Phồn thể)": "藪", "Pinyin_Xie": "sǒu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ đầm lầy nhiều cỏ hoặc nghĩa bóng là nơi tụ tập của người hay vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揿', '{"9000": "4814.0", "Chữ Trung Quốc": "揿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 欽 | khâm | biểu âm | kính trọng (cho âm) | 揿 (phồn thể: 撳) = 扌 (Thủ, biểu nghĩa: tay) + 欽 (Khâm, biểu âm). Chữ hình thanh (psc): bộ 扌 chỉ hành động dùng tay, 欽 cho âm đọc. Nghĩa: ấn, nhấn xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khâm\": bàn tay (扌) ấn xuống kính trọng như 欽 (khâm) — 揿铃 là nhấn chuông gọi cửa. | Gương Hán-Việt | 揿铃 (khâm linh) — ấn chuông; 揿钮 (khâm nữu) — nhấn nút | Mở khoá kiến thức | Biết 揿 mở khoá từ 揿铃 (ấn chuông) và 揿钮 (nhấn nút) trong văn nói miền Nam.", "Tự nguyên_Xie": "Theo Wiktionary, 撳 là chữ hình thanh: 手/扌 (c1=s, biểu nghĩa — hand, tay) + 欽 (c2=p, biểu âm). Nghĩa là ấn xuống, nhấn (nút bấm). Thường dùng trong tiếng Quảng Đông và văn nói miền Nam Trung Quốc. Ví dụ: 揿铃 (ấn chuông), 揿电钮 (nhấn nút điện). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đè mạnh", "Hạng Tần Suất (Jun Da)": "4814.0", "Tần Suất % (Jun Da)": "99.9020997073", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 钦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌钦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "钦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揿", "Unihan_Traditional (Chữ Phồn thể)": "搇", "Pinyin_Xie": "qìn", "Âm Hán Việt_Xie": "khấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động dùng ngón tay ấn hoặc đè mạnh xuống nút, chuông. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杲', '{"9000": "4815.0", "Chữ Trung Quốc": "杲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 日 | nhật | mặt trời | 木 | mộc | cây | 杲 = 日 (Nhật) + 木 (Mộc). Chữ hội ý (ic): mặt trời (日) chiếu sáng trên ngọn cây (木) — hình ảnh bình minh chói chang. Đây là cách tạo chữ bằng kết hợp ý nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt: chữ không có đọc Hán-Việt chuẩn. Nhớ qua hình: mặt trời (日) ngồi trên ngọn cây (木) — bình minh rực rỡ, ánh sáng chiếu từ trên xuống. | Gương Hán-Việt | 杲杲 (cảo cảo) — sáng rực rỡ (từ láy văn học) | Mở khoá kiến thức | Biết 杲 mở khoá từ 杲杲 (cảo cảo — sáng chói) trong thơ ca cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 杲 là chữ hội ý: 日 (t1=sun, mặt trời) + 木 (t2=tree, cây) — mặt trời rực sáng trên ngọn cây. Nghĩa: (văn học) mặt trời sáng chói. Cũng có nghĩa trắng (văn học). Là họ tên người. Thường gặp trong 杲杲 (láo láo — sáng rực rỡ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng; cao", "Hạng Tần Suất (Jun Da)": "4815.0", "Tần Suất % (Jun Da)": "99.9022108161", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "杲", "Unihan_Traditional (Chữ Phồn thể)": "杲", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ để miêu tả ánh sáng mặt trời rực rỡ hoặc thời tiết quang đãng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肓', '{"9000": "4816.0", "Chữ Trung Quốc": "肓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肓 | hoang | tượng hình | vùng giữa tim và cơ hoành | 肓 thuộc bộ 肉/月 (nhục — thịt). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chỉ vùng cơ thể giữa tim và cơ hoành trong y học cổ truyền Trung Hoa — nơi được cho là thuốc không thể tới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoang\": vùng cơ thể (月/肉) \"hoang vắng\" nơi thuốc không thể đến — 病入膏肓 là bệnh đã vào vùng tử huyệt. | Gương Hán-Việt | 膏肓 (cao hoang) — vùng bất trị; 病入膏肓 (bệnh nhập cao hoang) — bệnh đã vô phương cứu chữa | Mở khoá kiến thức | Biết 肓 mở khoá thành ngữ 病入膏肓 (bệnh nhập cao hoang — không thể cứu chữa) dùng rất phổ biến.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 肓 chỉ vùng giữa tim (heart) và cơ hoành (diaphragm) theo y học cổ truyền Trung Hoa (TCM), được coi là không thể chữa trị bằng thuốc. Phân biệt với 盲 (mù). Thành ngữ nổi tiếng: 病入膏肓 (bệnh nhập cao hoang — bệnh đến mức không thể chữa). Chưa có nguồn học thuật đầy đủ về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng dưới tim và trên cơ hoành", "Hạng Tần Suất (Jun Da)": "4816.0", "Tần Suất % (Jun Da)": "99.9023219249", "GavinGrover_Once (Chiết tự trực tiếp)": "亡 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亡月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肓", "Unihan_Traditional (Chữ Phồn thể)": "肓", "Pinyin_Xie": "huāng", "Âm Hán Việt_Xie": "hoang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ bộ phận sâu kín trong cơ thể, thường xuất hiện trong thành ngữ bệnh nhập cao hoang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厝', '{"9000": "4817.0", "Chữ Trung Quốc": "厝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 10 | nét | 厂 | hán | biểu nghĩa | vách đá, mái nhà | 昔 | tích | biểu âm | ngày xưa (cho âm) | 厝 = 厂 (Hán, biểu nghĩa: vách đá/mái nhà che) + 昔 (Tích, biểu âm). Chữ hình thanh (psc): bộ 厂 chỉ nơi trú ngụ/đặt để, 昔 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xó\": mái đá (厂) như ngày xưa (昔) — vừa có nghĩa nhà (tiếng Mân Nam), vừa là nơi đặt tạm quan tài. | Gương Hán-Việt | 厝火积薪 (xó hoả tích tân) — đặt lửa dưới đống củi, nguy hiểm tiềm ẩn | Mở khoá kiến thức | Biết 厝 mở khoá thành ngữ 厝火积薪 (nguy hiểm tiềm tàng) và địa danh tiếng Mân Nam.", "Tự nguyên_Xie": "Theo Wiktionary, 厝 là chữ hình thanh: 厂 (c1=s, biểu nghĩa) + 昔 (c2=p, biểu âm). Nghĩa gốc: để tạm quan tài trước khi chôn. Trong tiếng Mân Nam (Đài Loan, Phúc Kiến), 厝 có nghĩa là nhà (đặc biệt gặp trong địa danh 埔厝, tên đường). Hán-Việt xó/xó xỉnh từ âm cuò. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "để, đặt; quàn (người chết chưa kịp chôn còn để một chỗ)", "Hạng Tần Suất (Jun Da)": "4817.0", "Tần Suất % (Jun Da)": "99.9024325169", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 昔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厝", "Unihan_Traditional (Chữ Phồn thể)": "厝", "Pinyin_Xie": "cuò", "Âm Hán Việt_Xie": "thố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ chỉ việc đặt tạm quan tài trước khi chôn cất chính thức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莅', '{"9000": "4818.0", "Chữ Trung Quốc": "莅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莅 | lị | tượng hình | đến nơi, đến dự (nghi lễ) | 莅 thuộc bộ 艹 (thảo). Wiktionary ghi chữ này được tìm thấy trong 《玉篇》 và 《廣韻》 — các từ điển lịch sử. Năm 1956, CHND Trung Hoa chính thức xác định 莅 là chính thể, thay thế các dị thể 蒞 và 涖. Cấu trúc nội bộ chưa được phân tích học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lị\": đến nơi (như cỏ/艹 lan tới) — 莅临 (lị lâm) là cách nói trang trọng khi quan chức/khách quý đến thăm. | Gương Hán-Việt | 莅临 (lị lâm) — đến dự (trang trọng); 莅任 (lị nhiệm) — nhận chức | Mở khoá kiến thức | Biết 莅 mở khoá từ 莅临 (lị lâm — quang lâm) và 莅任 (lị nhiệm — đến nhậm chức) trong văn phong hành chính.", "Tự nguyên_Xie": "Theo Wiktionary, 莅 được ghi nhận trong 《玉篇》 và 《廣韻》. Năm 1956, CHND Trung Hoa trong bảng chỉnh lý dị thể tự lần một chính thức xác nhận 莅 là chính thể, 蒞 và 涖 là dị thể. Chữ có nghĩa: đến nơi (đặc biệt trong ngữ cảnh trang trọng như 莅临 — đến dự). Chưa có nguồn học thuật đầy đủ về nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đến", "Hạng Tần Suất (Jun Da)": "4818.0", "Tần Suất % (Jun Da)": "99.9025431089", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 位", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹位", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "位", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莅", "Unihan_Traditional (Chữ Phồn thể)": "涖", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm với các từ chỉ chức vụ hoặc địa điểm như lị nhậm, lị lâm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氤', '{"9000": "4819.0", "Chữ Trung Quốc": "氤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 10 | nét | 氤 | nhân | tượng hình | khí mù mịt, không khí nặng nề | 氤 thuộc bộ 气 (khí — khí). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chỉ xuất hiện trong 氤氳 (nhân uẩn — khói mù đầy, hơi nước mịt mờ). Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": khí (气) bao phủ dày đặc — 氤氳 (nhân uẩn) là làn khói sương mịt mờ huyền ảo, thường gặp trong thơ tả cảnh. | Gương Hán-Việt | 氤氳 (nhân uẩn) — khói sương mịt mờ, khí bao phủ dày đặc | Mở khoá kiến thức | Biết 氤 mở khoá từ 氤氳 (nhân uẩn — mù sương huyền ảo) trong thơ ca miêu tả thiên nhiên.", "Tự nguyên_Xie": "Wiktionary ghi 氤 có nghĩa là misty and heavy atmosphere (bầu không khí mù mịt, nặng nề). Chỉ dùng trong 氤氳 (nhân uẩn). Thuộc bộ 气 (khí). Từ 氤氳 miêu tả sương khói dày đặc, hơi thở của đất trời — thường dùng trong thơ ca. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sự phát ra ma thuật", "Hạng Tần Suất (Jun Da)": "4819.0", "Tần Suất % (Jun Da)": "99.902653701", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 因", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气因", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "因", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氤", "Unihan_Traditional (Chữ Phồn thể)": "氤", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ uân tạo thành từ láy nhân uân để tả cảnh sương khói mờ ảo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缙', '{"9000": "4820.0", "Chữ Trung Quốc": "缙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 缙 | tấn | tượng hình | màu đỏ tươi, dải lụa đỏ | 缙 (phồn thể: 縉) thuộc bộ 糸 (mịch — sợi chỉ, vải). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chỉ dải lụa đỏ hoặc màu đỏ tươi, thường gặp trong 縉紳 (tấn thân — quan lại có dải lụa đỏ, giới quý tộc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấn\": sợi lụa (糸) đỏ dắt vào thắt lưng — 縉紳 (tấn thân) là quan lại có dải lụa đỏ, biểu trưng giai cấp quý tộc. | Gương Hán-Việt | 縉紳 (tấn thân) — quan lại quý tộc; 簪纓縉紳 (châm anh tấn thân) — giới quan liêu | Mở khoá kiến thức | Biết 缙 mở khoá từ 缙绅 (tấn thân — quan lại) và hiểu văn hóa quan phục Trung Hoa cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{rfdef}} không có định nghĩa rõ. Hợp từ nổi tiếng: 縉紳 (tấn thân — quan lại, quý tộc) và 簪纓縉紳 (châm anh tấn thân — giới quan lại ăn mặc sang trọng). Chữ thuộc bộ 糸, liên quan đến dải lụa màu đỏ của quan phục. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Jin", "Hạng Tần Suất (Jun Da)": "4820.0", "Tần Suất % (Jun Da)": "99.902764293", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 晋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟晋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缙", "Unihan_Traditional (Chữ Phồn thể)": "縉", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại lụa đỏ thời xưa, thường dùng trong từ ghép tấn thân chỉ quan lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衮', '{"9000": "4821.0", "Chữ Trung Quốc": "衮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 衣 | y | biểu nghĩa | áo | 㕣 | biểu âm | (cho âm, biến thể của 公) | 衮 (phồn thể: 袞) = 衣 (Y, biểu nghĩa: áo) + 㕣/公 (biểu âm). Chữ hình thanh (psc): bộ 衣 chỉ trang phục, phần âm cho đọc. Chỉ áo long bào của hoàng đế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổn\": áo (衣) trang trọng nhất — long bào của hoàng đế. 袞袞諸公 (cổn cổn chư công) ám chỉ giới quan lại đầy đủ áo mão. | Gương Hán-Việt | 龍袞 (long cổn) — long bào hoàng đế; 袞袞 (cổn cổn) — liên tiếp, đông đúc (chỉ quan lại) | Mở khoá kiến thức | Biết 衮 mở khoá từ 龙衮 (long bào), 衮衮诸公 (quan lại đông đảo) trong văn ngôn chính luận.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 袞 là chữ hình thanh: 衣 (c1=s, biểu nghĩa — clothes, áo) + 公/㕣 (c2=p, biểu âm). Nghĩa: ceremonial robe worn by the emperor (long bào lễ nghi của hoàng đế). Từ 龍袞 (long cổn) — áo long bào thêu rồng. 袞袞諸公 (cổn cổn chư công) — các quan lại đầy đủ áo bào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "723.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Công (722) Y (042)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Công (số 722 - của chung/chỉ âm) ở trên (và xen giữa) chữ Y (số 042 - áo). Quần áo (Y) mặc khi làm việc chung (Công). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Công chỉ âm, bộ Y chỉ ý. Cổn là cái áo lễ phục của nhà vua mặc khi tế lễ. *(Ghi chú: Có cách viết khác thay chữ Tư (厶) trong Công bằng Khẩu (口) thành 袞)*.", "Nghĩa Tiếng Việt_Xie": "Gon", "Hạng Tần Suất (Jun Da)": "4821.0", "Tần Suất % (Jun Da)": "99.9028743682", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 公", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣公", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "衮", "Unihan_Traditional (Chữ Phồn thể)": "袞", "Pinyin_Xie": "gǔn", "Âm Hán Việt_Xie": "cổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ trang phục tế lễ thêu rồng của vua chúa ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诟', '{"9000": "4822.0", "Chữ Trung Quốc": "诟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诟 | cấu | tượng hình | mắng chửi, xỉ nhục | 诟 là dạng giản thể của 詬, thay 言 bằng 讠. Wiktionary xác nhận đây là giản hóa: {{Han simp|詬|f=言|t=讠}}. Thuộc bộ 讠/言 (ngôn — lời nói). Nghĩa: mắng chửi, xỉ nhục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấu\": lời nói (讠) đanh ác chỉ trích — 诟病 (cấu bệnh) là vạch ra lỗi lầm, chỉ trích gay gắt. | Gương Hán-Việt | 诟病 (cấu bệnh) — chỉ trích, phê phán khuyết điểm; 羞诟 (tu cấu) — xấu hổ bị mắng | Mở khoá kiến thức | Biết 诟 mở khoá từ 诟病 (cấu bệnh — chỉ trích, bị dư luận phê phán) dùng rất phổ biến trong báo chí.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 诟 là dạng giản thể của 詬 (cấu — mắng chửi). Theo Wiktionary, đây là rút gọn bộ 言 thành 讠. Nghĩa gốc: mắng nhiếc, xỉ nhục người khác. Thường gặp trong 诟病 (cấu bệnh — chỉ trích, vạch lỗi). Chưa có phân tích sâu về nguồn gốc chữ gốc 詬. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cảm giác xấu hổ", "Hạng Tần Suất (Jun Da)": "4822.0", "Tần Suất % (Jun Da)": "99.9029844435", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 后", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠后", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "后", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诟", "Unihan_Traditional (Chữ Phồn thể)": "詬", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang nghĩa lăng mạ hoặc làm danh từ chỉ sự sỉ nhục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旖', '{"9000": "4823.0", "Chữ Trung Quốc": "旖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 方 | Số nét | 14 | nét | 㫃 | biểu nghĩa | cờ phướn (bộ thủ) | 奇 | cơ | biểu âm | kỳ lạ (cho âm) | 旖 = 㫃 (biểu nghĩa: cờ, phướn) + 奇 (Cơ, biểu âm). Chữ hình thanh (psc): bộ 㫃 chỉ cờ bay phấp phới, 奇 cho âm đọc. Chỉ dùng trong 旖旎 (ỷ nỉ — uyển chuyển, mềm mại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ỷ\": cờ (㫃) lay động kỳ ảo (奇) — 旖旎 (ỷ nỉ) là vẻ đẹp uyển chuyển, mềm mại như dải lụa trong gió. | Gương Hán-Việt | 旖旎 (ỷ nỉ) — uyển chuyển, thướt tha; 風光旖旎 (phong quang ỷ nỉ) — phong cảnh đẹp mềm mại | Mở khoá kiến thức | Biết 旖 mở khoá từ 旖旎 (ỷ nỉ — uyển chuyển) và thành ngữ 风光旖旎 trong thơ ca tả cảnh.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 旖 là chữ hình thanh: 㫃 (c1=s, biểu nghĩa — cờ) + 奇 (c2=p, biểu âm). Chỉ dùng trong 旖旎 (ỷ nỉ). 旖旎 miêu tả sự uyển chuyển, mềm mại, thướt tha — như dải cờ lay động trong gió. Phổ biến trong thơ ca và văn xuôi miêu tả cảnh đẹp: 旖旎風光 (phong cảnh uyển chuyển). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thướt tha", "Hạng Tần Suất (Jun Da)": "4823.0", "Tần Suất % (Jun Da)": "99.9030945187", "GavinGrover_Once (Chiết tự trực tiếp)": "方 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旖", "Unihan_Traditional (Chữ Phồn thể)": "旖", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ ni tạo thành từ láy ỷ ni để miêu tả vẻ đẹp mềm mại của phong cảnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硒', '{"9000": "4824.0", "Chữ Trung Quốc": "硒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 石 | thạch | biểu nghĩa | đá, khoáng vật | 西 | tây | biểu âm | phía tây (cho âm) | 硒 = 石 (Thạch, biểu nghĩa: đá/khoáng vật) + 西 (Tây, biểu âm). Chữ hình thanh (psc): bộ 石 chỉ khoáng chất, 西 cho âm đọc xī. Chữ hiện đại tạo ra để phiên dịch tên nguyên tố hóa học Selenium (Se).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt: chữ không có đọc Hán-Việt chuẩn. Nhớ qua cấu trúc: đá/khoáng (石) + phương tây (西) âm xī — nguyên tố Selenium phát hiện ở phương Tây. | Gương Hán-Việt | 硒元素 (tây nguyên tố) — nguyên tố selen; 富硒 (phú tây) — giàu selen | Mở khoá kiến thức | Biết 硒 mở khoá từ 富硒食品 (thực phẩm giàu selen) và tên hóa học nguyên tố Se.", "Tự nguyên_Xie": "Theo Wiktionary, 硒 là chữ hình thanh hiện đại: 石 (c1=s, biểu nghĩa — stone/mineral) + 西 (c2=p, biểu âm). Nghĩa: selenium (selen — nguyên tố hóa học Se, số nguyên tử 34). Chữ được tạo ra trong thế kỷ 19-20 để phiên dịch tên nguyên tố khoa học phương Tây sang chữ Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố selen, Se", "Hạng Tần Suất (Jun Da)": "4824.0", "Tần Suất % (Jun Da)": "99.9032045939", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硒", "Unihan_Traditional (Chữ Phồn thể)": "硒", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tây", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành hóa học để chỉ nguyên tố phi kim selen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唁', '{"9000": "4825.0", "Chữ Trung Quốc": "唁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 言 | ngôn | biểu âm | lời (cho âm) | 唁 = 口 (Khẩu, biểu nghĩa: miệng/lời nói) + 言 (Ngôn, biểu âm). Chữ hình thanh (psc): bộ 口 chỉ hành động nói, 言 cho âm đọc. Nghĩa: đến viếng, nói lời chia buồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngon\": miệng (口) nói lời (言) chia buồn — 吊唁 (điếu ngon) là đến viếng người mất, nói lời thăm hỏi gia đình. | Gương Hán-Việt | 吊唁 (điếu ngon) — phúng viếng; 唁电 (ngon điện) — điện chia buồn | Mở khoá kiến thức | Biết 唁 mở khoá từ 吊唁 (điếu ngon — phúng viếng) và 唁电 (ngon điện — điện chia buồn) trong nghi lễ tang.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 唁 là chữ hình thanh: 口 (c1=s, biểu nghĩa — mouth, miệng) + 言 (c2=p, biểu âm). Nghĩa: to offer condolences (chia buồn, phúng viếng). Hợp từ phổ biến: 吊唁 (điếu ngon — phúng viếng), 唁电 (ngon điện — điện chia buồn), 慰唁 (uý ngon — an ủi chia buồn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viếng (việc tang ma)", "Hạng Tần Suất (Jun Da)": "4825.0", "Tần Suất % (Jun Da)": "99.9033141524", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唁", "Unihan_Traditional (Chữ Phồn thể)": "唁", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nghiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ dùng trong nghi thức tang lễ để bày tỏ lòng thương tiếc đối với gia quyến người đã khuất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬗', '{"9000": "4826.0", "Chữ Trung Quốc": "嬗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 16 | nét | 嬗 | thiện | tượng hình | biến đổi, nhường ngôi | 嬗 thuộc bộ 女 (nữ). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ có nghĩa: tiến hóa, biến đổi; hoặc nhường ngôi (đồng nghĩa với 禪). Thường gặp trong 嬗變 (thiện biến — chuyển hóa, biến đổi dần dần).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": bộ nữ (女) trong chữ biến đổi — 嬗變 (thiện biến) là sự chuyển hóa từ từ, như thế hệ tiếp nối thay nhau. | Gương Hán-Việt | 嬗變 (thiện biến) — biến đổi, chuyển hóa; 遞嬗 (đệ thiện) — thay thế nhau lần lượt | Mở khoá kiến thức | Biết 嬗 mở khoá từ 嬗变 (thiện biến — biến đổi/chuyển hóa) dùng trong lý luận xã hội và triết học.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 嬗 có hai nghĩa: (văn học) to evolve, to transform (tiến hóa, biến đổi); và alt form của 禪 (to abdicate — nhường ngôi). Chữ thuộc bộ 女. Hợp từ: 嬗變 (thiện biến — biến đổi, chuyển hóa), 遞嬗 (đệ thiện — lần lượt thay thế). Chưa có nguồn học thuật đầy đủ về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thay đổi", "Hạng Tần Suất (Jun Da)": "4826.0", "Tần Suất % (Jun Da)": "99.9034237108", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嬗", "Unihan_Traditional (Chữ Phồn thể)": "嬗", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự thay thế, chuyển giao quyền lực hoặc sự tiến hóa tự nhiên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硎', '{"9000": "4827.0", "Chữ Trung Quốc": "硎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硎 | hình | tượng hình | đá mài, đá nhám | 硎 thuộc bộ 石 (thạch — đá). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chỉ đá mài (whetstone) và động từ mài, giũa. Nổi tiếng qua thành ngữ 新硎初試 (tân hình sơ thí — mới mài xong lần đầu thử — ý người tài mới ra nghề).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hình\": đá (石) mài hình thành sắc bén — 新硎初試 (tân hình sơ thí) là người tài năng mới ra mắt lần đầu. | Gương Hán-Việt | 新硎初試 (tân hình sơ thí) — người tài mới ra mắt; 發硎 (phát hình) — lần đầu dùng dao mới mài | Mở khoá kiến thức | Biết 硎 mở khoá thành ngữ 新硎初试 (tân hình sơ thí — nhân tài mới ra trường bắt đầu thể hiện).", "Tự nguyên_Xie": "Wiktionary ghi 硎 có nghĩa: whetstone (đá mài) và to whet, to grind, to polish (mài, giũa, đánh bóng). Hợp từ: 發硎 (phát hình — lần đầu mài dao), 新硎初試 (tân hình sơ thí — dao mới mài lần đầu thử). Chưa có phân tích cấu trúc học thuật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá mài dao", "Hạng Tần Suất (Jun Da)": "4827.0", "Tần Suất % (Jun Da)": "99.9035332693", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 刑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石刑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硎", "Unihan_Traditional (Chữ Phồn thể)": "硎", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "hình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ hòn đá mài dao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裱', '{"9000": "4828.0", "Chữ Trung Quốc": "裱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 衣 | y | biểu nghĩa | áo, vải | 表 | biểu | biểu âm | bề mặt, bên ngoài (cho âm) | 裱 = 衣 (Y, biểu nghĩa: áo/vải) + 表 (Biểu, biểu âm). Chữ hình thanh (psc): bộ 衣 chỉ vật liệu vải/giấy dùng để bồi, 表 cho âm đọc. Nghĩa: bồi giấy/tranh/cuộn; dán cửa sổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bíu\": vải (衣) bồi lên bề mặt (表) — 裱画 (bíu hoạ) là nghề bồi tranh, đóng khung tranh truyền thống. | Gương Hán-Việt | 裝裱 (trang bíu) — đóng khung tranh; 裱糊 (bíu hồ) — dán giấy | Mở khoá kiến thức | Biết 裱 mở khoá từ 装裱 (trang bíu — đóng khung tranh) và 裱糊 (bíu hồ — dán giấy tường).", "Tự nguyên_Xie": "Theo Wiktionary, 裱 là chữ hình thanh: 衣 (t1=clothes, biểu nghĩa — áo/vải) + 表 (c2=p, biểu âm). Nghĩa: loại khăn quàng ngoài áo (phụ nữ); bồi dán bản đồ, tranh cuộn, dán cửa sổ. Hợp từ: 裝裱 (trang bíu — đóng khung tranh), 裱糊 (bíu hồ — dán giấy tường). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bồi; đắp; đóng khung; dán vách; bồi tường; bồi giấy; dán giấy (lên trần nhà)", "Hạng Tần Suất (Jun Da)": "4828.0", "Tần Suất % (Jun Da)": "99.9036428277", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 表", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤表", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "表", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裱", "Unihan_Traditional (Chữ Phồn thể)": "裱", "Pinyin_Xie": "biǎo", "Âm Hán Việt_Xie": "biểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ tranh ảnh để biểu thị hành động bồi hoặc dán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颦', '{"9000": "4829.0", "Chữ Trung Quốc": "颦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 十 | Số nét | 21 | nét | 颦 | tần | tượng hình | cau mày, nhíu mày | 颦 (phồn thể: 顰) thuộc bộ 页 (hiệt — đầu). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Chữ chỉ hành động cau mày, nhíu mày — thường gặp trong thành ngữ 東施效顰 (Đông Thi hiệu tần — bắt chước vụng về).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tần\": mày đầu (页) cau lại — 東施效顰 (Đông Thi hiệu tần) là thành ngữ nổi tiếng về bắt chước không đúng chỗ. | Gương Hán-Việt | 東施效顰 (Đông Thi hiệu tần) — bắt chước vụng về; 一顰一笑 (nhất tần nhất tiếu) — mỗi nét biểu cảm | Mở khoá kiến thức | Biết 颦 mở khoá thành ngữ 东施效颦 (Đông Thi hiệu tần — bắt chước không đúng cách) và 一颦一笑.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 顰 có nghĩa: (văn học) to frown, to knit one''s brows (cau mày). Hợp từ: 東施效顰 (Đông Thi hiệu tần — Đông Thi bắt chước Tây Thi cau mày cho đẹp nhưng lại thêm xấu), 顰眉 (tần mi — cau mày), 一顰一笑 (nhất tần nhất tiếu — từng cái cau mày nụ cười). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhăn mặt", "Hạng Tần Suất (Jun Da)": "4829.0", "Tần Suất % (Jun Da)": "99.9037523862", "GavinGrover_Once (Chiết tự trực tiếp)": "频 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱频卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "频", "Unihan_Simplified (Chữ Giản thể)": "颦", "Unihan_Traditional (Chữ Phồn thể)": "顰", "Pinyin_Xie": "pín", "Âm Hán Việt_Xie": "tần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mô tả hành động nhíu mày hoặc nhăn mặt khi lo âu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靥', '{"9000": "4830.0", "Chữ Trung Quốc": "靥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 15 | nét | 靥 | yểm | tượng hình | lúm đồng tiền, vết chấm trên má | 靥 là dạng giản thể của 靨, thay phần 厭 bằng 厌. Thuộc bộ 面 (diện — mặt). Nghĩa: lúm đồng tiền trên má, hoặc nét duyên trên mặt. Chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": nét trên mặt (面) quyến rũ — 靥 là lúm đồng tiền trên má, điểm duyên đặc trưng của mỹ nhân trong thơ văn cổ điển. | Gương Hán-Việt | 酒靥 (tửu yểm) — lúm đồng tiền; 笑靥 (tiếu yểm) — nụ cười có lúm đồng tiền | Mở khoá kiến thức | Biết 靥 mở khoá từ 笑靥 (tiếu yểm — nụ cười có lúm đồng tiền) và 酒靥 trong miêu tả sắc đẹp.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 靥 là dạng giản thể của 靨 (yểm — lúm đồng tiền). Chữ thuộc bộ 面 (mặt). Trong văn học, 靥 chỉ nét duyên dáng trên gương mặt phụ nữ, đặc biệt lúm đồng tiền. Gặp trong 酒靥 (tửu yểm — lúm đồng tiền). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúm đồng tiền (trên má); nốt ruồi", "Hạng Tần Suất (Jun Da)": "4830.0", "Tần Suất % (Jun Da)": "99.9039709863", "GavinGrover_Once (Chiết tự trực tiếp)": "厌 + 面", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厌面", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "面", "Unihan_Simplified (Chữ Giản thể)": "靥", "Unihan_Traditional (Chữ Phồn thể)": "靨", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "yếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ lúm đồng tiền trên má khi cười. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纥', '{"9000": "4831.0", "Chữ Trung Quốc": "纥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 6 | nét | 纥 | hột | tượng hình | nút thắt trên sợi chỉ, dân tộc Hồi Hột | 纥 (phồn thể: 紇) thuộc bộ 糸 (mịch — sợi chỉ). Wiktionary không cung cấp cấu trúc thành phần chi tiết. Nghĩa: nút thắt trên sợi; dùng trong tên 回紇 (Hồi Hột — dân tộc Uyghur cổ đại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hột\": sợi chỉ (糸) có nút thắt — 回紇 (Hồi Hột) là tên dân tộc Uyghur cổ đại, và cha của Khổng Tử tên là 叔梁紇. | Gương Hán-Việt | 回紇 (Hồi Hột) — dân tộc Uyghur cổ đại; 叔梁紇 (Thúc Lương Hột) — cha của Khổng Tử | Mở khoá kiến thức | Biết 纥 mở khoá tên 回纥 (Hồi Hột — Uyghur) trong lịch sử Đường đại và tên cha Khổng Tử.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 紇 có các nghĩa: knot (nút thắt); dùng trong 回紇 (Hồi Hột — Uyghur); dùng trong tên 叔梁紇 (cha của Khổng Tử). Chữ thuộc bộ 糸 (sợi chỉ). Tên 回紇 là phiên âm từ tiếng Thổ Nhĩ Kỳ cổ. Chưa có nguồn học thuật đầy đủ về nguồn gốc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi tơ rủ xuống; núm, nơ, gút, nút", "Hạng Tần Suất (Jun Da)": "4831.0", "Tần Suất % (Jun Da)": "99.9040800279", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纥", "Unihan_Traditional (Chữ Phồn thể)": "紇", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "hột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các chữ khác tạo thành danh từ chỉ nút thắt hoặc cục u. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煨', '{"9000": "4832.0", "Chữ Trung Quốc": "煨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 火 | hoả | biểu nghĩa | lửa | 畏 | uý | biểu âm | sợ hãi (cho âm) | 煨 = 火 (Hoả, biểu nghĩa: lửa) + 畏 (Uý, biểu âm). Chữ hình thanh (psc): bộ 火 chỉ phương pháp dùng lửa/nhiệt độ thấp để nấu, 畏 cho âm đọc wēi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oi\": lửa (火) nhỏ le lói như sợ (畏) tắt — 煨 là nấu hầm lửa nhỏ liu riu, hoặc vùi trong tro. | Gương Hán-Việt | 煨燼 (oi tẫn) — cháy thành tro; 煨乾就濕 (oi can tựu thấp) — hi sinh vì con cái | Mở khoá kiến thức | Biết 煨 mở khoá từ 煨汤 (oi thang — canh hầm) và thành ngữ 煨乾就濕 về đức hi sinh của người mẹ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 煨 là chữ hình thanh: 火 (c1=s, biểu nghĩa — fire) + 畏 (c2=p, biểu âm). Nghĩa: to stew, to simmer (hầm, om); to roast in ashes (nướng trong tro). Cũng có nghĩa: tro, than. Hợp từ: 煨燼 (oi tẫn — cháy thành tro), 煨乾就濕 (oi can tựu thấp — chịu khổ vì con cái, nói về mẹ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nướng", "Hạng Tần Suất (Jun Da)": "4832.0", "Tần Suất % (Jun Da)": "99.9041890696", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 畏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煨", "Unihan_Traditional (Chữ Phồn thể)": "煨", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "ổi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ thực phẩm để chỉ cách nấu bằng tro nóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礴', '{"9000": "4833.0", "Chữ Trung Quốc": "礴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 21 | nét | 礴 | bác | tượng hình | mênh mông, đồ sộ | 礴 thuộc bộ 石 (thạch — đá). Không có dữ liệu Wiktionary. Chỉ dùng trong 磅礴 (bàng bác — hùng vĩ, đồ sộ, mênh mông). Chữ tạo muộn chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\": đá (石) to như trời đất — 磅礴 (bàng bác) là từ dùng để tả khí thế hùng vĩ không gì cản được. | Gương Hán-Việt | 磅礴 (bàng bác) — hùng vĩ, đồ sộ; 气势磅礴 (khí thế bàng bác) — khí thế hùng mạnh | Mở khoá kiến thức | Biết 礴 mở khoá từ 磅礴 (bàng bác — hùng vĩ) và 气势磅礴 (khí thế mạnh mẽ) trong văn viết trang trọng.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary cho 礴. Chữ thuộc bộ 石 (đá), chỉ dùng trong 磅礴 (bàng bác) — từ láy miêu tả khí thế hùng vĩ, rộng lớn, đồ sộ. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bàn bạc 磐礡)", "Hạng Tần Suất (Jun Da)": "4833.0", "Tần Suất % (Jun Da)": "99.9042981113", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 薄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石薄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "薄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礴", "Unihan_Traditional (Chữ Phồn thể)": "礡", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ Bàng để tạo thành tính từ mô tả khí thế bao la, hùng vĩ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏖', '{"9000": "4834.0", "Chữ Trung Quốc": "鏖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏖 | áo | tượng hình | chiến đấu ác liệt, kịch chiến | 鏖 thuộc bộ 金 (kim — kim loại). Wiktionary chỉ ghi {{Han etym}} không có phân tích. Chữ chỉ xuất hiện trong 鏖戰 (áo chiến — trận chiến ác liệt) và 鏖兵 (áo binh — giao chiến quyết liệt). Chữ tạo muộn chưa thấy rõ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": kim loại (金) vang lên trong kịch chiến — 鏖戰 (áo chiến) là trận đánh ác liệt không ngừng, tiếng vũ khí vang trời. | Gương Hán-Việt | 鏖戰 (áo chiến) — kịch chiến, giao chiến ác liệt; 鏖兵 (áo binh) — hăng hái chiến đấu | Mở khoá kiến thức | Biết 鏖 mở khoá từ 鏖战 (áo chiến — đánh nhau ác liệt) trong văn chiến tranh và thể thao.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể cho 鏖. Chữ thuộc bộ 金 (kim loại), biểu thị tiếng vũ khí kim loại va chạm trong chiến trận ác liệt. Thường gặp trong 鏖戰 (áo chiến — trận chiến ác liệt). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trận đánh quyết liệt; rầm rĩ", "Hạng Tần Suất (Jun Da)": "4834.0", "Tần Suất % (Jun Da)": "99.9044071529", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "鏖", "Unihan_Traditional (Chữ Phồn thể)": "鏖", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ trận chiến để thể hiện sự khốc liệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝈', '{"9000": "4835.0", "Chữ Trung Quốc": "蝈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蝈 | quắc | tượng hình | con dế mèn, con dế | 蝈 thuộc bộ 虫 (trùng — côn trùng). Không có dữ liệu Wiktionary. Chữ chỉ loài côn trùng giống dế, tiếng kêu vang — 蝈蝈 (quắc quắc) là tên gọi con dế mèn trong tiếng Bắc Kinh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quắc\": côn trùng (虫) kêu vang quắc quắc — 蝈蝈 là con dế mèn Bắc Kinh, vật nuôi truyền thống để nghe tiếng kêu. | Gương Hán-Việt | 蝈蝈 (quắc quắc) — con dế mèn, loài côn trùng kêu vang | Mở khoá kiến thức | Biết 蝈 mở khoá từ 蝈蝈 (quắc quắc — dế mèn) và văn hóa nuôi dế Bắc Kinh truyền thống.", "Tự nguyên_Xie": "Tiểu triện | Không có dữ liệu Wiktionary cho 蝈. Chữ thuộc bộ 虫 (côn trùng). 蝈 chỉ con dế mèn (katydid/cricket), đặc biệt loài có tiếng kêu vang. 蝈蝈 (quắc quắc) là tên thông dụng ở miền Bắc Trung Quốc, con vật nuôi thú vị trong văn hóa dân gian Bắc Kinh. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lâu quắc 螻蟈,蝼蝈)", "Hạng Tần Suất (Jun Da)": "4835.0", "Tần Suất % (Jun Da)": "99.9045156778", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 国", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫国", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "国", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝈", "Unihan_Traditional (Chữ Phồn thể)": "蟈", "Pinyin_Xie": "guō", "Âm Hán Việt_Xie": "quắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con dế mèn hoặc con muỗm trong tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笏', '{"9000": "4836.0", "Chữ Trung Quốc": "笏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笏 | hốt | tượng hình | thẻ bài quan triều | 笏 thuộc bộ 竹 (trúc — tre). Wiktionary chỉ ghi {{Han etym}} không có phân tích. Chữ chỉ tấm thẻ hình chữ nhật bằng ngà voi, gỗ hoặc ngọc — quan lại cầm khi vào chầu để ghi chú lệnh vua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hốt\": thẻ tre (竹) quan triều cầm trong tay — 朝笏 (triều hốt) là vật bất ly thân của quan lại Trung Hoa khi vào chầu. | Gương Hán-Việt | 朝笏 (triều hốt) — thẻ bài quan triều; 象笏 (tượng hốt) — thẻ bài làm bằng ngà voi | Mở khoá kiến thức | Biết 笏 mở khoá từ 朝笏 (triều hốt — thẻ bài quan triều) và 象笏 (ngà voi — thẻ bài cao cấp) trong lịch sử triều đình.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể cho 笏. Chữ thuộc bộ 竹 (tre), biểu thị vật dụng làm từ tre hoặc vật liệu cứng. 笏 là tấm thẻ quan (ivory/wooden tablet) quan lại cầm khi vào triều — để ghi chú hoặc che mặt trước thiên tử. Chữ xuất hiện từ đại triện và tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hốt (các quan dùng khi vào trầu)", "Hạng Tần Suất (Jun Da)": "4836.0", "Tần Suất % (Jun Da)": "99.9046242027", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 勿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮勿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笏", "Unihan_Traditional (Chữ Phồn thể)": "笏", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ cái hốt bằng ngọc hoặc gỗ của quan lại thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羿', '{"9000": "4837.0", "Chữ Trung Quốc": "羿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 9 | nét | 羽 | vu | biểu nghĩa | lông vũ, cánh | 幵 | biểu âm | (cho âm) | 羿 = 羽 (Vũ, biểu nghĩa: lông vũ/cánh) + 幵 (biểu âm). Chữ hình thanh (psc): bộ 羽 liên quan đến cung tên có lông (mũi tên có cánh lông), 幵 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": lông vũ (羽) trên mũi tên — 后羿 (Hậu Nghệ) là xạ thủ huyền thoại dùng cung tên bắn rơi chín mặt trời. | Gương Hán-Việt | 后羿 (Hậu Nghệ) — cung thủ thần thoại; 后羿射日 (Hậu Nghệ xạ nhật) — bắn rơi chín mặt trời | Mở khoá kiến thức | Biết 羿 mở khoá thần thoại 后羿射日 (Hậu Nghệ bắn mặt trời) — một trong bốn thần thoại lớn Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 羿 là chữ hình thanh: 羽 (c1=s, biểu nghĩa — feather) + 幵 (c2=p, biểu âm). Nghĩa: tên của cung thủ huyền thoại 后羿 (Hậu Nghệ) — người đã bắn rơi chín mặt trời. Cũng là họ tên người. 后羿射日 (Hậu Nghệ xạ nhật) là một trong những thần thoại nổi tiếng nhất Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "4837.0", "Tần Suất % (Jun Da)": "99.9047327276", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 艹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "羿", "Unihan_Traditional (Chữ Phồn thể)": "羿", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ nhân vật Hậu Nghệ trong thần thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼐', '{"9000": "4838.0", "Chữ Trung Quốc": "鼐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼎 | Số nét | 14 | nét | 乃 | nãi | biểu âm | đó, bèn (cho âm) | 鼎 | đỉnh | biểu nghĩa | đỉnh — vạc ba chân | 鼐 = 乃 (Nãi, biểu âm) + 鼎 (Đỉnh, biểu nghĩa: đỉnh ba chân cổ đại). Chữ hình thanh (psc): bộ 鼎 chỉ loại vạc ba chân bằng đồng, 乃 cho âm đọc. Nghĩa: cái đỉnh/vạc lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nãi\": vạc đỉnh (鼎) to lớn — 鼎鼐 (đỉnh nãi) là ẩn dụ về tể tướng lo liệu triều chính như điều phối nấu nướng trong vạc lớn. | Gương Hán-Việt | 鼎鼐 (đỉnh nãi) — tể tướng (ẩn dụ); 調和鼎鼐 (điều hòa đỉnh nãi) — lo liệu triều chính | Mở khoá kiến thức | Biết 鼐 mở khoá từ 鼎鼐 (đỉnh nãi — ẩn dụ tể tướng) và hiểu biểu tượng 鼎 trong văn hóa Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鼐 là chữ hình thanh: 乃 (c1=p, biểu âm) + 鼎 (c2=s, biểu nghĩa). Nghĩa: a big ding (cái đỉnh lớn) — vạc ba chân bằng đồng cổ đại cỡ lớn dùng nấu thức ăn và tế lễ. Hợp từ: 鼎鼐 (đỉnh nãi — đỉnh và nãi; ẩn dụ tể tướng), 調和鼎鼐 (điều hoà đỉnh nãi — lo việc nấu nướng tể tướng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vạc lớn", "Hạng Tần Suất (Jun Da)": "4838.0", "Tần Suất % (Jun Da)": "99.9048407357", "GavinGrover_Once (Chiết tự trực tiếp)": "乃 + 鼎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱乃鼎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼎", "Unihan_Simplified (Chữ Giản thể)": "鼐", "Unihan_Traditional (Chữ Phồn thể)": "鼐", "Pinyin_Xie": "nài", "Âm Hán Việt_Xie": "nãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ loại vạc lớn ba chân hai tai thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湟', '{"9000": "4839.0", "Chữ Trung Quốc": "湟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 湟 | hoàng | tượng hình | tên sông Hoàng Thủy | 湟 thuộc bộ 水/氵 (thuỷ — nước). Không có dữ liệu Wiktionary. Chữ chỉ sông Hoàng Thủy (湟水) — nhánh lớn của sông Hoàng Hà ở Thanh Hải, Cam Túc. Chữ tạo muộn chưa thấy cấu trúc thành phần rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": nước (氵) chảy ở vùng cao nguyên — 湟水 (Hoàng Thủy) là sông lớn nuôi dưỡng người Tạng và người Hồi ở Thanh Hải. | Gương Hán-Việt | 湟水 (Hoàng Thủy) — sông Hoàng Thủy ở Thanh Hải; 湟中 (Hoàng Trung) — địa danh Thanh Hải | Mở khoá kiến thức | Biết 湟 mở khoá địa danh 湟水 (Hoàng Thủy) và 湟中 (Hoàng Trung) ở tỉnh Thanh Hải Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Không có dữ liệu Wiktionary cho 湟. Chữ thuộc bộ 氵 (nước), dùng chủ yếu trong địa danh: 湟水 (Hoàng Thủy — sông ở Thanh Hải), 湟中 (Hoàng Trung — huyện ở Thanh Hải), 湟源 (Hoàng Nguyên — huyện ở Thanh Hải). Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Hoàng Thuỷ (ở tỉnh Thanh Hải của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4839.0", "Tần Suất % (Jun Da)": "99.9049487438", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湟", "Unihan_Traditional (Chữ Phồn thể)": "湟", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ riêng trong địa danh như sông Hoàng Thủy hoặc quận Hoàng Trung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甑', '{"9000": "4840.0", "Chữ Trung Quốc": "甑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 16 | nét | 甑 | tăng | tượng hình | dụng cụ nấu cơm bằng hơi nước làm từ đất | 甑 là chữ tượng hình / chỉ sự, biểu thị dụng cụ nấu cơm bằng hơi nước. Anchor Wiktionary chỉ cho biết {{Han etym}} không có thông tin cụ thể về thành phần; chữ này thuộc nhóm chỉ sự. Hán-Việt đọc là ''tăng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": chiếc nồi đất xưa dùng để đồ xôi — hơi nước bốc lên, cơm chín dần. | Gương Hán-Việt | 甑 hiếm dùng trong tiếng Việt Hán-Việt hiện đại; gặp trong từ cổ 甑釜 (tăng phủ) chỉ đồ nấu ăn. | Mở khoá kiến thức | Biết 甑 giúp hiểu các từ cổ về đồ dùng nhà bếp trong thư tịch Hán-Nôm.", "Tự nguyên_Xie": "Tiểu triện | 甑 (tăng) là chữ cổ chỉ loại nồi đất dùng để đồ (hấp) cơm. Theo triện văn, chữ mô tả hình dạng chiếc siêu/nồi có lỗ thoát hơi ở đáy, đặt trên vạc nước sôi. Chưa có nguồn Wiktionary chi tiết về cấu trúc thành phần; confidence thấp. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái siêu sành, cái nồi đất", "Hạng Tần Suất (Jun Da)": "4840.0", "Tần Suất % (Jun Da)": "99.9050567518", "GavinGrover_Once (Chiết tự trực tiếp)": "曾 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰曾瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "甑", "Unihan_Traditional (Chữ Phồn thể)": "甑", "Pinyin_Xie": "zèng", "Âm Hán Việt_Xie": "tắng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ nấu nướng thời cổ dùng để hấp chín thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炜', '{"9000": "4841.0", "Chữ Trung Quốc": "炜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 炜 | vĩ | tượng hình | ánh sáng đỏ rực, lửa sáng | 炜 không có dữ liệu thành phần từ anchor. Chữ thuộc bộ 火 (hoả), gợi liên quan đến lửa và ánh sáng. Chưa có nguồn học thuật xác nhận cấu trúc; confidence thấp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": bộ Hoả (🔥 lửa) tỏa ánh đỏ rực — 炜 như ngọn đuốc sáng rỡ. | Gương Hán-Việt | 炜 thường gặp trong tên người Trung Quốc; Hán-Việt ''vĩ'' cũng dùng trong tên tiếng Việt. | Mở khoá kiến thức | Biết 炜 giúp nhận diện các chữ tên người liên quan đến ánh sáng, rực rỡ.", "Tự nguyên_Xie": "Tiểu triện | 炜 (vĩ) là chữ hình thanh, bộ 火 (hoả, lửa) kết hợp với phần biểu âm. Nghĩa gốc là ánh lửa đỏ rực, màu đỏ sáng. Không có dữ liệu Wiktionary anchor; dựa trên cấu trúc bộ thủ, chữ tạo muộn, chưa thấy trong giáp cốt. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đỏ lửng, sáng sủa", "Hạng Tần Suất (Jun Da)": "4841.0", "Tần Suất % (Jun Da)": "99.9051647599", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炜", "Unihan_Traditional (Chữ Phồn thể)": "煒", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vẻ rực rỡ của ánh sáng hoặc lửa, thường dùng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煲', '{"9000": "4842.0", "Chữ Trung Quốc": "煲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煲 | bao | tượng hình | cái nồi tròn thành đứng dùng để nấu | 煲 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 火 (hoả), liên quan đến nấu nướng bằng lửa. Đây là chữ Quảng Đông phổ biến, tạo tương đối muộn. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bao\": cái nồi (煲) ôm bọc thức ăn từ bốn phía — lửa từ dưới, hơi nóng bao quanh. | Gương Hán-Việt | 煲 phổ biến trong ẩm thực Quảng Đông: 煲仔饭 (cơm niêu đất), 煲汤 (nấu canh). | Mở khoá kiến thức | Biết 煲 giúp hiểu thực đơn và công thức nấu ăn Quảng Đông: 煲仔饭, 砂锅煲.", "Tự nguyên_Xie": "煲 (bao) là chữ xuất xứ từ tiếng Quảng Đông (粵語), chỉ loại nồi tròn thành đứng dùng để hầm, ninh. Không có dữ liệu Wiktionary anchor; chữ tạo muộn, chưa thấy trong giáp cốt văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nồi; nồi tròn (thành đứng)", "Hạng Tần Suất (Jun Da)": "4842.0", "Tần Suất % (Jun Da)": "99.905272768", "GavinGrover_Once (Chiết tự trực tiếp)": "保 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱保火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "保", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煲", "Unihan_Traditional (Chữ Phồn thể)": "煲", "Pinyin_Xie": "bāo", "Âm Hán Việt_Xie": "bảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái nồi đất hoặc làm động từ chỉ việc hầm, ninh thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bāo | / | đun sôi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锉', '{"9000": "4843.0", "Chữ Trung Quốc": "锉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 钅 | kim | biểu nghĩa | kim loại | 坐 | toạ | biểu âm | ngồi | 锉 là chữ hình thanh (psc): bộ 钅 (Kim, biểu nghĩa: kim loại) + thành phần biểu âm. Đây là chữ giản thể của 銼. Cấu trúc cho thấy một dụng cụ kim loại (cái giũa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toả\": bộ Kim (钅) — cái giũa (锉) dùng để mài nhẵn kim loại, tiếng kêu xoèn xoẹt. | Gương Hán-Việt | 锉 ít dùng trong tiếng Việt Hán-Việt; gặp trong kỹ thuật 锉刀 (giũa/dũa). | Mở khoá kiến thức | Biết 锉 giúp đọc tài liệu kỹ thuật về gia công kim loại: 锉刀, 锉削.", "Tự nguyên_Xie": "Tiểu triện | 锉 là chữ giản thể của 銼 (cuò), cấu trúc {{Han simp|銼|f=釒|t=钅}} — bộ Kim (金/钅, kim loại) ghép với phần biểu âm. 銼 nghĩa gốc là cái giũa (dụng cụ mài kim loại), cũng có nghĩa là cái vạc lớn trong cổ văn. Chữ tạo muộn, không có dạng giáp cốt. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giũa; giũa; cái vạc lớn", "Hạng Tần Suất (Jun Da)": "4843.0", "Tần Suất % (Jun Da)": "99.9053807761", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锉", "Unihan_Traditional (Chữ Phồn thể)": "剉", "Pinyin_Xie": "cuò", "Âm Hán Việt_Xie": "toả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ giũa kim loại hoặc làm động từ chỉ hành động giũa, mài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笕', '{"9000": "4844.0", "Chữ Trung Quốc": "笕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 竹 | trúc | biểu nghĩa | tre | 见 | kiến | biểu âm | nhìn thấy | 笕 là chữ giản thể của 筧, hình thanh (psc): bộ 竹 (Trúc, biểu nghĩa: tre) + 见 (Kiến, biểu âm). Cấu trúc cho thấy đây là vật dụng làm từ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiển\": bộ Trúc (竹) — ống tre (笕) dẫn nước từ nguồn về làng, tiếng nước chảy róc rách. | Gương Hán-Việt | 笕 ít dùng trong tiếng Việt hiện đại; gặp trong mô tả kiến trúc truyền thống. | Mở khoá kiến thức | Biết 笕 giúp hiểu các từ về hệ thống dẫn nước bằng tre trong văn hóa cổ Trung Hoa.", "Tự nguyên_Xie": "笕 là chữ giản thể của 筧 (jiǎn), theo cấu trúc {{Han simp|筧|f=見|t=见}} — bộ Trúc (竹) kết hợp với 見 biểu âm. 筧 nghĩa gốc là ống máng tre dùng để dẫn nước. Đây là kỹ thuật truyền thống dẫn nước của người Trung Quốc cổ đại. Chữ tạo muộn, không có dạng giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ống máng tre", "Hạng Tần Suất (Jun Da)": "4844.0", "Tần Suất % (Jun Da)": "99.9054887842", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "见", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笕", "Unihan_Traditional (Chữ Phồn thể)": "筧", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ máng tre hoặc ống dẫn nước từ trên núi xuống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喑', '{"9000": "4845.0", "Chữ Trung Quốc": "喑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng | 音 | âm | biểu âm | âm thanh | 喑 là chữ hình thanh (psc): bộ 口 (Khẩu, biểu nghĩa: miệng) + 音 (Âm, biểu âm). Kết hợp miệng và âm thanh nhưng chỉ trạng thái mất tiếng — sự nghịch lý tạo nên nghĩa câm, mất giọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ầm\": miệng (口) có âm thanh (音) bên trong mà không thốt ra được — 喑 là câm lặng, mất tiếng. | Gương Hán-Việt | 喑 gặp trong từ cổ 喑哑 (ầm á) — câm điếc, không nói được. | Mở khoá kiến thức | Biết 喑 giúp đọc văn học cổ điển Trung Quốc mô tả sự im lặng hoặc mất tiếng.", "Tự nguyên_Xie": "Tiểu triện | 喑 (ầm) là chữ hình thanh: bộ 口 (miệng) biểu nghĩa + 音 (âm thanh) biểu âm. Nghĩa gốc là câm, mất tiếng, im lặng không nói. Wiktionary có dữ liệu {{Han etym}} nhưng không có chi tiết cấu trúc; dựa trên phân tích bộ thủ và âm đọc. Confidence ở mức medium. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mất tiếng; mất giọng; câm lặng; im lặng không nói", "Hạng Tần Suất (Jun Da)": "4845.0", "Tần Suất % (Jun Da)": "99.9055962755", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "音", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喑", "Unihan_Traditional (Chữ Phồn thể)": "喑", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "âm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ trạng thái câm lặng hoặc động từ chỉ việc im lặng không nói. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嶂', '{"9000": "4846.0", "Chữ Trung Quốc": "嶂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 14 | nét | 山 | sơn | biểu nghĩa | núi | 章 | chương | biểu âm | bài, chương | 嶂 là chữ hình thanh (psc): bộ 山 (Sơn, biểu nghĩa: núi) + 章 (Chương, biểu âm). Cấu trúc chỉ dạng núi cao hiểm trở, như những bức tường đá dựng đứng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chướng\": bộ Sơn (山) + Chương (章) — ngọn núi (嶂) như những trang sách đá dựng đứng ngăn trời. | Gương Hán-Việt | 嶂 gặp trong thơ cổ: 层峦叠嶂 (tầng phong điệp chướng) — núi non trùng điệp. | Mở khoá kiến thức | Biết 嶂 giúp đọc thơ văn cổ điển mô tả cảnh núi non hùng vĩ.", "Tự nguyên_Xie": "嶂 (chướng) là chữ hình thanh: bộ 山 (núi) biểu nghĩa + 章 biểu âm. Nghĩa gốc là ngọn núi cao dựng đứng như bức vách. Wiktionary có dữ liệu {{Han etym}} nhưng không có phân tích chi tiết; dựa trên cấu trúc bộ thủ. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọn núi cao và to", "Hạng Tần Suất (Jun Da)": "4846.0", "Tần Suất % (Jun Da)": "99.9057037668", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嶂", "Unihan_Traditional (Chữ Phồn thể)": "嶂", "Pinyin_Xie": "zhàng", "Âm Hán Việt_Xie": "chướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ những ngọn núi cao dựng đứng như bức tường thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浔', '{"9000": "4847.0", "Chữ Trung Quốc": "浔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thuỷ | biểu nghĩa | nước | 寻 | tầm | biểu âm | tìm kiếm | 浔 là chữ hình thanh (psc): bộ 氵(Thuỷ, biểu nghĩa: nước) + 寻 (Tầm, biểu âm). Chữ chỉ vùng bờ nước, bến sông — nơi tìm kiếm bên dòng sông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tầm\": bộ Thuỷ (氵) + Tầm (寻) — bến sông (浔) nơi người tầm vọng bờ xa, sóng nước mênh mang. | Gương Hán-Việt | 浔 xuất hiện trong địa danh 浔阳 (Tầm Dương) — tên cổ của Cửu Giang, nổi tiếng qua bài thơ 琵琶行 của Bạch Cư Dị. | Mở khoá kiến thức | Biết 浔 giúp hiểu các địa danh Giang Tây (浔阳, 浔江) và thơ Đường về sông nước.", "Tự nguyên_Xie": "Tiểu triện | 浔 (tầm) là chữ hình thanh: bộ 氵(nước) biểu nghĩa + 寻 biểu âm. Nghĩa gốc là bờ nước, bến sông; cũng là tên gọi khác của vùng Cửu Giang (九江) ở Giang Tây. Wiktionary có dữ liệu anchor nhưng không phân tích cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bến sông; sông Tầm; vùng Cửu Giang (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4847.0", "Tần Suất % (Jun Da)": "99.9058112581", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 寻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵寻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浔", "Unihan_Traditional (Chữ Phồn thể)": "潯", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bờ sông hoặc bến nước, thường xuất hiện trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弭', '{"9000": "4848.0", "Chữ Trung Quốc": "弭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 9 | nét | 弓 | cung | biểu nghĩa | cây cung | 耳 | nhĩ | biểu âm | tai | 弭 là chữ hình thanh (psc): bộ 弓 (Cung, biểu nghĩa: cây cung) + 耳 (Nhĩ, biểu âm). Nghĩa gốc là chuôi cung (đầu cung có nấc dắt dây). Sau này mở nghĩa thành dừng lại, chấm dứt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": bộ Cung (弓) + Nhĩ (耳 tai) — cái tai cung (弭) là nấc gỗ ở đầu cung giữ dây không bung — dừng lại, ngăn chặn. | Gương Hán-Việt | 弭 gặp trong văn cổ: 弭兵 (di binh) — đình chiến; 消弭 (tiêu di) — xóa bỏ, dập tắt. | Mở khoá kiến thức | Biết 弭 giúp đọc văn ngôn cổ mô tả việc dừng chiến tranh, loại bỏ nguy hiểm: 弭兵, 消弭.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 弭 (di/nhĩ) là chữ hình thanh theo Wiktionary: {{Han compound|弓|耳|c1=s|c2=p|t1=bow|ls=psc}} — bộ Cung (弓) biểu nghĩa + Nhĩ (耳) biểu âm. Nghĩa gốc là chuôi cung (chỗ dắt dây cung). Phần tai cung gợi hình ảnh cái móc nhỏ giữ dây cung. Sau nghĩa mở rộng thành ''dừng lại, chấm dứt''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuôi cung, cán cung", "Hạng Tần Suất (Jun Da)": "4848.0", "Tần Suất % (Jun Da)": "99.9059187494", "GavinGrover_Once (Chiết tự trực tiếp)": "弓 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弭", "Unihan_Traditional (Chữ Phồn thể)": "弭", "Pinyin_Xie": "mǐ", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ với nghĩa tiêu trừ, dẹp yên loạn lạc hoặc làm danh từ chỉ phần cuối của cánh cung. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妪', '{"9000": "4849.0", "Chữ Trung Quốc": "妪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 区 | âu | biểu âm | khu vực | 妪 là chữ hình thanh (psc): bộ 女 (Nữ, biểu nghĩa: người phụ nữ) + 区 (Âu, biểu âm). Đây là giản thể của 嫗. Chữ chỉ người phụ nữ lớn tuổi, bà lão.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": bộ Nữ (女) + Âu (区) — bà lão (妪) như người phụ nữ đã qua nhiều vùng đất (区), trải sương gió cuộc đời. | Gương Hán-Việt | 妪 gặp trong văn cổ: 老妪 (lão âu) — bà già; 村妪 (thôn âu) — bà lão thôn quê. | Mở khoá kiến thức | Biết 妪 giúp đọc truyện ngắn và văn học cổ điển có nhân vật bà lão: 老妪, 邻妪.", "Tự nguyên_Xie": "Tiểu triện | 妪 là giản thể của 嫗 (yù), theo Wiktionary: {{Han simp|嫗|f=區|t=区}}, dạng hiện tại là {{Han compound|女|t1=woman|区|ls=psc|c1=s|c2=p}}. Bộ Nữ (女) biểu nghĩa + 区 biểu âm (thay cho 區 cổ). 嫗 nghĩa gốc là bà lão, người phụ nữ lớn tuổi. Cũng có nghĩa thứ yếu là người mẹ (mẹ của loài chim ấp trứng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mẹ", "Hạng Tần Suất (Jun Da)": "4849.0", "Tần Suất % (Jun Da)": "99.9060262408", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妪", "Unihan_Traditional (Chữ Phồn thể)": "嫗", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người phụ nữ lớn tuổi hoặc người mẹ trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锂', '{"9000": "4850.0", "Chữ Trung Quốc": "锂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại | 里 | lý | biểu âm | trong, lý | 锂 là chữ hình thanh (psc): bộ 金 (Kim, biểu nghĩa: kim loại) + 里 (Lý, biểu âm). Cấu trúc cho thấy đây là một nguyên tố kim loại được đặt tên theo âm đọc gần giống 里.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lý\": bộ Kim (金) + Lý (里) — lithium (锂) là kim loại nhẹ nhất, nhỏ bé như ''bên trong'' (里) nhưng mang năng lượng lớn trong pin. | Gương Hán-Việt | 锂 dùng trong khoa học: 锂电池 (lý điện trì) — pin lithium. | Mở khoá kiến thức | Biết 锂 giúp đọc tài liệu khoa học và công nghệ pin: 锂电池, 锂离子.", "Tự nguyên_Xie": "锂 (lý) là chữ hình thanh hiện đại theo Wiktionary: {{Han compound|金|里|c1=s|t1=metal|c2=p|ls=psc|no_och2=1}} — bộ Kim (金) biểu nghĩa + 里 biểu âm. Chữ được tạo ra trong thế kỷ 19 để phiên âm tên nguyên tố Lithium (Li) sang tiếng Trung. Không có dạng cổ đại (giáp cốt, kim văn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố liti, Li", "Hạng Tần Suất (Jun Da)": "4850.0", "Tần Suất % (Jun Da)": "99.9061337321", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锂", "Unihan_Traditional (Chữ Phồn thể)": "鋰", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học liti, thường dùng trong các thuật ngữ khoa học hoặc tên pin. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苡', '{"9000": "4851.0", "Chữ Trung Quốc": "苡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 苡 | dĩ | tượng hình | cây ý dĩ (Job''s tears) | 苡 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 艹 (thảo, cỏ), chỉ một loài cây. Anchor chỉ cho biết {{Han etym}} không có phân tích cụ thể. Dùng trong tên gọi cây 薏苡 (ý dĩ, job''s tears).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dĩ\": cây 苡 — hạt ý dĩ (薏苡) người Việt quen dùng nấu chè, bổ tỳ vị. | Gương Hán-Việt | 苡 xuất hiện trong tên cây 薏苡 (ý dĩ) — hạt bo bo, dùng trong y học cổ truyền và ẩm thực. | Mở khoá kiến thức | Biết 苡 giúp nhận diện tên cây 薏苡 trong thực đơn và toa thuốc đông y.", "Tự nguyên_Xie": "苡 (dĩ) là chữ cổ thuộc bộ 艹 (cỏ), chỉ cây 薏苡 (ý dĩ, còn gọi là hạt bo bo). Wiktionary chỉ có {{Han etym}} không có phân tích cấu trúc chi tiết. Chữ này chủ yếu xuất hiện trong tên ghép 薏苡 và 芣苡. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phù dĩ 芣苡); (xem: ý dĩ 薏苡)", "Hạng Tần Suất (Jun Da)": "4851.0", "Tần Suất % (Jun Da)": "99.9062407066", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 以", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹以", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "以", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苡", "Unihan_Traditional (Chữ Phồn thể)": "苡", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "dĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đi kèm với chữ khác để tạo thành danh từ chỉ cây hoặc hạt ý dĩ dùng làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孳', '{"9000": "4852.0", "Chữ Trung Quốc": "孳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 12 | nét | 兹 | tư | biểu âm | này, ở đây | 子 | tử | biểu nghĩa | đứa trẻ, con | 孳 là chữ hình thanh (psc): 兹 (Tư, biểu âm) + 子 (Tử, biểu nghĩa: đứa con). Hình ảnh những đứa trẻ sinh ra và lớn lên gợi nghĩa sinh sản, tăng trưởng liên tục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": Tư (兹) + Tử (子 con) — 孳 là sinh sôi nảy nở không ngừng, đàn con ngày càng đông. | Gương Hán-Việt | 孳 gặp trong văn cổ: 孳生 (tư sinh) — sinh sôi; 孳息 (tư tức) — sinh lợi, tiền lãi; 孳孳 (tư tư) — chăm chỉ không ngừng. | Mở khoá kiến thức | Biết 孳 giúp đọc văn ngôn về sinh sản, nông nghiệp và tài chính cổ: 孳生, 孳息.", "Tự nguyên_Xie": "Tiểu triện | 孳 (tư) là chữ hình thanh theo Wiktionary: {{Han compound|兹|子|ls=psc|c1=p|c2=s|t2=child}} — 兹 biểu âm + 子 (đứa con) biểu nghĩa. Nghĩa gốc là sinh sôi, sản xuất, tạo ra. Chữ xuất hiện từ thời Xuân Thu, biểu thị sự sinh trưởng liên tục không ngừng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sản xuất, sinh ra, làm ra", "Hạng Tần Suất (Jun Da)": "4852.0", "Tần Suất % (Jun Da)": "99.9063476811", "GavinGrover_Once (Chiết tự trực tiếp)": "兹 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱兹子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孳", "Unihan_Traditional (Chữ Phồn thể)": "孳", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị sự sinh sôi nảy nở, thường kết hợp thành từ ghép như tư sinh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颏', '{"9000": "4853.0", "Chữ Trung Quốc": "颏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 12 | nét | 亥 | hợi | biểu âm | giờ Hợi (con lợn) | 頁 | hiệt | biểu nghĩa | đầu, mặt | 颏 là chữ hình thanh (psc): 亥 (Hợi, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu/mặt). Chữ chỉ phần cằm (phía dưới mặt người), lấy bộ Hiệt biểu nghĩa cho vùng đầu mặt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": bộ Hiệt (頁 đầu mặt) + Hợi (亥) — 颏 là phần cằm dưới khuôn mặt, chỗ vuốt khi suy nghĩ. | Gương Hán-Việt | 颏 gặp trong y học: 下颏 (hạ hà) — phần hàm dưới; 颏下 (hà hạ) — vùng dưới cằm. | Mở khoá kiến thức | Biết 颏 giúp đọc tài liệu y học và mô tả khuôn mặt: 下颏, 颏部.", "Tự nguyên_Xie": "Tiểu triện | 颏 (hà/hợi) là chữ hình thanh theo Wiktionary: {{Han compound|亥|頁|ls=psc|c1=p|c2=s}} — 亥 biểu âm + 頁 (đầu/mặt) biểu nghĩa. Nghĩa là phần dưới cằm, cằm dưới. Chữ xuất hiện trong y học và mô tả giải phẫu khuôn mặt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dưới cằm", "Hạng Tần Suất (Jun Da)": "4853.0", "Tần Suất % (Jun Da)": "99.9064546556", "GavinGrover_Once (Chiết tự trực tiếp)": "亥 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亥页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颏", "Unihan_Traditional (Chữ Phồn thể)": "頦", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "hài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cằm trên khuôn mặt, thường dùng trong khẩu ngữ hoặc y học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醴', '{"9000": "4854.0", "Chữ Trung Quốc": "醴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 20 | nét | 醴 | lễ | tượng hình | rượu ngọt, rượu nếp | 醴 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 酉 (rượu), gợi đến rượu ngọt, nước ngọt từ suối. Anchor Wiktionary chỉ có {{Han etym}} không phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lễ\": bộ Dậu (酉 rượu) — 醴 là rượu ngọt dâng lên thần linh trong nghi lễ, ngọt nhưng trang nghiêm. | Gương Hán-Việt | 醴 gặp trong văn cổ: 醴酒 (lễ tửu) — rượu ngọt; 醴泉 (lễ tuyền) — suối nước ngọt. | Mở khoá kiến thức | Biết 醴 giúp đọc kinh điển và thư tịch về lễ nghi: 牲醴, 醴泉 trong Kinh Thư, Thi Kinh.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | 醴 (lễ) là chữ thuộc bộ 酉 (rượu), nghĩa gốc là rượu nếp ngọt ít cồn, loại rượu ngọt dùng trong lễ tế. Cũng có nghĩa là nước suối ngọt. Có dạng giáp cốt, kim văn và triện văn. Wiktionary chỉ có {{Han etym}} không chi tiết; dựa trên bộ thủ và ngữ cảnh văn hóa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu nếp, rượu ngọt", "Hạng Tần Suất (Jun Da)": "4854.0", "Tần Suất % (Jun Da)": "99.9065616302", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 豊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉豊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醴", "Unihan_Traditional (Chữ Phồn thể)": "醴", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại rượu ngọt làm từ xôi nếp hoặc nguồn nước ngọt lành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渚', '{"9000": "4855.0", "Chữ Trung Quốc": "渚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 渚 | chã | tượng hình | bãi đất nhỏ giữa sông, bến nước | 渚 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 氵(thuỷ, nước), chỉ bãi đất nhỏ giữa dòng sông hoặc bờ nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chã\": bộ Thuỷ (氵) — 渚 là bãi cát nhỏ giữa sông, nơi chim nước đậu nghỉ ngơi bên dòng chảy. | Gương Hán-Việt | 渚 gặp trong thơ cổ: 烟渚 (yên chã) — bãi sông trong sương khói; 洲渚 (châu chã) — bãi cồn và bến. | Mở khoá kiến thức | Biết 渚 giúp đọc thơ Đường và Tống mô tả cảnh sông nước: 烟渚, 江渚, 洲渚.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 渚 (chã) là chữ thuộc bộ 氵(nước), nghĩa gốc là bãi đất nhỏ nổi giữa sông (islet), bờ nước. Wiktionary chỉ có {{Han etym}} không chi tiết. Chữ xuất hiện sớm trong thơ văn cổ, đặc biệt trong Kinh Thi và thơ Đường. Dựa trên cấu trúc bộ thủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bến nước", "Hạng Tần Suất (Jun Da)": "4855.0", "Tần Suất % (Jun Da)": "99.9067750624", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渚", "Unihan_Traditional (Chữ Phồn thể)": "渚", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "chử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bãi đất nhỏ nổi lên giữa sông hoặc bến nước trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轭', '{"9000": "4856.0", "Chữ Trung Quốc": "轭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 8 | nét | 车 | xa | biểu nghĩa | xe | 厄 | ách | biểu âm | hiểm trở, khó khăn | 轭 là chữ giản thể của 軛, hình thanh (psc): bộ 车 (Xa, biểu nghĩa: xe) + 厄 (Ách, biểu âm). Cái ách xe (thanh gỗ đặt lên cổ ngựa để kéo xe) — chính là nghĩa của chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": bộ Xa (车 xe) + Ách (厄) — cái ách (轭) kìm hãm ngựa vào xe, tiếng Việt còn dùng ''ách'' theo nghĩa đó. | Gương Hán-Việt | 轭 tương ứng với từ ''ách'' trong tiếng Việt: ách áp bức, ách đô hộ. | Mở khoá kiến thức | Biết 轭 giúp liên kết từ Hán-Việt ''ách'' với hình ảnh cụ thể: cái ách trên cổ ngựa.", "Tự nguyên_Xie": "轭 là giản thể của 軛 (è), theo cấu trúc {{Han simp|軛|f=車|t=车}} — bộ Xa (車/车, xe) biểu nghĩa + phần biểu âm. 軛 nghĩa gốc là cái ách xe, thanh gỗ đặt trên cổ ngựa trâu để buộc vào xe kéo. Hình ảnh con vật bị kìm hãm bởi cái ách gợi nghĩa mở rộng: ách đặt lên vai ai đó. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vai xe", "Hạng Tần Suất (Jun Da)": "4856.0", "Tần Suất % (Jun Da)": "99.9068815202", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 厄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车厄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轭", "Unihan_Traditional (Chữ Phồn thể)": "軛", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái ách đặt lên cổ trâu bò hoặc động từ chỉ sự kìm kẹp, khống chế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹬', '{"9000": "4857.0", "Chữ Trung Quốc": "鹬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 矞 | duật | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鹬 là chữ hình thanh (psc): 矞 (Duật, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Cấu trúc rõ ràng: bộ Điểu cho biết đây là loài chim, còn 矞 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duật\": bộ Điểu (鳥 chim) + Duật (矞) — chim dẽ giun (鹬) nổi tiếng qua câu ''Duật và trai tranh nhau, ngư ông hưởng lợi''. | Gương Hán-Việt | 鹬 nổi tiếng trong thành ngữ 鹬蚌相争，渔人得利 — tương đương ''ngư ông đắc lợi'' trong tiếng Việt. | Mở khoá kiến thức | Biết 鹬 giúp hiểu nguồn gốc thành ngữ 鹬蚌相争 và các chữ về loài chim trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 鹬 (duật) là chữ hình thanh theo Wiktionary: {{Han compound|矞|鳥|ls=psc|c1=p|c2=s}} — 矞 biểu âm + 鳥 (chim) biểu nghĩa. Chỉ loài chim dẽ giun (snipe/sandpiper), còn gọi là chim bói cá (kingfisher). Nổi tiếng qua thành ngữ 鹬蚌相争，渔人得利 (Ngư ông đắc lợi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim dẽ giun", "Hạng Tần Suất (Jun Da)": "4857.0", "Tần Suất % (Jun Da)": "99.9069879779", "GavinGrover_Once (Chiết tự trực tiếp)": "矞 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矞鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹬", "Unihan_Traditional (Chữ Phồn thể)": "鷸", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim lội nước, nổi tiếng trong câu thành ngữ duật bàng tương tranh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚝', '{"9000": "4858.0", "Chữ Trung Quốc": "蚝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚝 | hào | tượng hình | con hàu, con sò biển | 蚝 không có dữ liệu anchor thành phần. Là chữ giản hoá từ 蠔 (c. 1927), thuộc bộ 虫 (trùng, côn trùng/động vật nhỏ). Chữ tạo muộn, chưa có trong giáp cốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": bộ Trùng (虫) — con hàu (蚝) là loài ''trùng'' biển sống trong vỏ cứng, thịt ngọt mặn vị biển cả. | Gương Hán-Việt | 蚝 phổ biến trong ẩm thực Quảng Đông: 蚝油 (hào du) — dầu hào; 生蚝 (sinh hào) — hàu sống. | Mở khoá kiến thức | Biết 蚝 giúp đọc thực đơn và công thức nấu ăn Quảng Đông: 蚝油, 生蚝, 蚝仔粥.", "Tự nguyên_Xie": "蚝 là chữ giản hoá từ 蠔 (háo), được đơn giản hoá khoảng năm 1927. Theo Wiktionary: ''Simplified from 𧐢 (c. 1927).'' Chữ chỉ con hàu (oyster), một loài nhuyễn thể biển quan trọng trong ẩm thực. Chữ tạo muộn, không có dạng giáp cốt; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sò, con hàu", "Hạng Tần Suất (Jun Da)": "4858.0", "Tần Suất % (Jun Da)": "99.9070944356", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚝", "Unihan_Traditional (Chữ Phồn thể)": "蠔", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con hàu biển, thường dùng trong tên các món ăn hải sản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膘', '{"9000": "4859.0", "Chữ Trung Quốc": "膘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | 肉 | nhục | biểu nghĩa | thịt, xác thịt | 票 | phiếu | biểu âm | phiếu, vé | 膘 là chữ hình thanh (psc): bộ 肉 (Nhục, biểu nghĩa: thịt) + 票 (Phiếu, biểu âm). Chữ chỉ lớp mỡ dưới da của gia súc, động vật béo mập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ Nhục (肉 thịt) + Phiếu (票) — lớp mỡ dày (膘) trên thân con vật — 肥膘 (phì tiêu) — mỡ dày béo ú. | Gương Hán-Việt | 膘 gặp trong văn mô tả gia súc: 长膘 (trưởng tiêu) — tích mỡ; 肥膘 (phì tiêu) — mỡ béo. | Mở khoá kiến thức | Biết 膘 giúp đọc tài liệu nông nghiệp và ẩm thực mô tả chất lượng thịt: 肥膘, 长膘.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 膘 (tiêu) là chữ hình thanh theo Wiktionary: {{Han compound|肉|票|ls=psc|t1=flesh, meat|c1=s|c2=p}} — bộ Nhục (肉/月, thịt) biểu nghĩa + 票 biểu âm. Nghĩa gốc là lớp mỡ dày, dùng cho gia súc béo mập. Từ có dạng triện văn và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "béo (dùng cho động vật)", "Hạng Tần Suất (Jun Da)": "4859.0", "Tần Suất % (Jun Da)": "99.9073068343", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膘", "Unihan_Traditional (Chữ Phồn thể)": "膘", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lớp mỡ hoặc độ béo tốt của gia súc như trâu, bò, ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邛', '{"9000": "4860.0", "Chữ Trung Quốc": "邛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 5 | nét | 邛 | cùng | tượng hình | tên địa danh, núi Cùng Lai ở Tứ Xuyên | 邛 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 邑 (ấp, địa danh), chỉ tên đất ở Tứ Xuyên. Anchor có dạng kim văn, triện văn và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cùng\": 邛 là địa danh cổ ở Tứ Xuyên, nơi có núi Cùng Lai và đường tơ lụa cổ đại. | Gương Hán-Việt | 邛 gặp trong địa danh lịch sử: 邛崃 (Cùng Lai) — thành phố ở Tứ Xuyên; 邛都 (Cùng Đô) — thành cổ. | Mở khoá kiến thức | Biết 邛 giúp đọc lịch sử Con đường Tơ lụa và địa lý cổ đại Tứ Xuyên.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 邛 (cùng) là chữ địa danh, thuộc bộ 邑 (ấp). Nghĩa gốc là tên vùng đất hoặc núi Cùng Lai ở tỉnh Tứ Xuyên, Trung Quốc. Wiktionary chỉ có {{Han etym}} không chi tiết. Có dạng kim văn và triện văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cùng Lai (tên núi, ở tỉnh Tứ Xuyên, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4860.0", "Tần Suất % (Jun Da)": "99.9074127753", "GavinGrover_Once (Chiết tự trực tiếp)": "工 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰工阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "工", "Unihan_Simplified (Chữ Giản thể)": "邛", "Unihan_Traditional (Chữ Phồn thể)": "邛", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh cổ hoặc tên núi ở tỉnh Tứ Xuyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痨', '{"9000": "4861.0", "Chữ Trung Quốc": "痨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | nạch | biểu nghĩa | bệnh, ốm | 勞 | lao | biểu âm | lao động, vất vả | 痨 là chữ hình thanh (psc): bộ 疒 (Nạch, biểu nghĩa: bệnh) + 勞 (Lao, biểu âm). Chữ chỉ bệnh lao (tuberculosis) — căn bệnh làm người kiệt sức, hao mòn từ từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": bộ Bệnh (疒) + Lao (勞 vất vả) — bệnh lao (痨) hao mòn người bệnh ngày qua ngày, như thể bị cưỡng lao dịch không ngừng. | Gương Hán-Việt | 痨 tương ứng ''lao'' trong tiếng Việt: bệnh lao (结核病), lao phổi. | Mở khoá kiến thức | Biết 痨 giúp đọc tài liệu y học cổ và hiện đại về bệnh lao: 肺痨, 痨病, 痨虫.", "Tự nguyên_Xie": "Tiểu triện | 痨 (lao) là chữ hình thanh theo Wiktionary: {{Han compound|疒|勞|c1=s|c2=p|t1=sickness|ls=psc}} — bộ Nạch (疒, bệnh) biểu nghĩa + 勞 biểu âm. Nghĩa là bệnh lao phổi (tuberculosis), căn bệnh truyền nhiễm nguy hiểm thời xưa. Âm đọc giống 劳 (lao động) gợi hình ảnh bệnh nhân kiệt sức như người lao dịch. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh lao", "Hạng Tần Suất (Jun Da)": "4861.0", "Tần Suất % (Jun Da)": "99.9075187162", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痨", "Unihan_Traditional (Chữ Phồn thể)": "癆", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ chỉ hoạt động y tế hoặc kết hợp thành từ ghép chỉ bệnh tật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褡', '{"9000": "4862.0", "Chữ Trung Quốc": "褡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褡 | đáp | tượng hình | áo trấn thủ, túi vải dài | 褡 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 衣 (y, quần áo), chỉ loại túi vải dài đeo qua vai hoặc áo trấn thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": bộ Y (衣 quần áo) — 褡 là túi vải dài đeo vai, đặt (đáp) lên vai để mang theo tiền bạc, đồ dùng. | Gương Hán-Việt | 褡 gặp trong từ 褡裢 (đáp liên) — túi vải dài đeo qua vai, dùng để đựng tiền và đồ vật. | Mở khoá kiến thức | Biết 褡 giúp nhận diện từ 褡裢 trong văn học và lịch sử về trang phục, đồ dùng cổ đại.", "Tự nguyên_Xie": "褡 (đáp) là chữ thuộc bộ 衣 (quần áo), chỉ loại túi vải dài đeo qua vai (褡裢 dā lián) hoặc áo trấn thủ. Wiktionary có {{Han etym}} nhưng không chi tiết. Có dạng cổ. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo trấn thủ", "Hạng Tần Suất (Jun Da)": "4862.0", "Tần Suất % (Jun Da)": "99.9076246572", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 荅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤荅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褡", "Unihan_Traditional (Chữ Phồn thể)": "褡", "Pinyin_Xie": "dā", "Âm Hán Việt_Xie": "đáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ để chỉ các loại túi, áo khoác truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耦', '{"9000": "4863.0", "Chữ Trung Quốc": "耦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 15 | nét | 耒 | lồi | biểu nghĩa | cái cày | 禺 | ngung | biểu âm | vùng đất | 耦 là chữ hình thanh (psc): bộ 耒 (Lồi, biểu nghĩa: cái cày) + 禺 (Ngung, biểu âm). Chữ chỉ việc hai người cùng cày song song — Wiktionary ghi thêm: ''paired working in the fields''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngẫu\": bộ Lồi (耒 cày) + Ngung (禺) — 耦 là hai người cùng cày một thửa ruộng — cặp đôi làm việc song hành. | Gương Hán-Việt | 耦 gặp trong văn cổ: 耦耕 (ngẫu canh) — cày đôi; liên hệ ngẫu nhiên (偶然) — 耦 và 偶 đồng âm. | Mở khoá kiến thức | Biết 耦 giúp phân biệt với 偶 (ngẫu, thường gặp hơn); cả hai đều chỉ thành đôi, thành cặp.", "Tự nguyên_Xie": "Tiểu triện | 耦 (ngẫu) là chữ hình thanh theo Wiktionary: {{Han compound|耒|禺|c1=s|c2=p|t1=tilling tool|ls=psc}}, paired working in the fields. Bộ 耒 (cày) biểu nghĩa + 禺 biểu âm. Nghĩa gốc là hai người cùng cày bên nhau, làm ruộng đôi. Nghĩa mở rộng: thành đôi, đối nhau, cặp đôi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hai người cùng cày; hai người; đối nhau", "Hạng Tần Suất (Jun Da)": "4863.0", "Tần Suất % (Jun Da)": "99.9077305981", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 禺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒禺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耦", "Unihan_Traditional (Chữ Phồn thể)": "耦", "Pinyin_Xie": "ǒu", "Âm Hán Việt_Xie": "ngẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Thường làm danh từ chỉ cặp đôi hoặc số từ chỉ số chẵn trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覃', '{"9000": "4864.0", "Chữ Trung Quốc": "覃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 襾 | Số nét | 12 | nét | 覃 | đàm | tượng hình | lan rộng, sâu xa; cũng là họ người | 覃 không có dữ liệu anchor thành phần chi tiết. Wiktionary ghi ''Appears as 𪉷 in the small seal script.'' Chữ có dạng kim văn, triện văn. Nghĩa gốc là lan tới, ơn lây, sâu rộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàm\": 覃 như ân huệ lan toả — ơn sâu thấm xa như nước ngầm chảy ngầm khắp đất. | Gương Hán-Việt | 覃 gặp trong văn cổ: 覃恩 (đàm ân) — ân huệ lan rộng; 覃及 (đàm cập) — lan tới, đến nơi. | Mở khoá kiến thức | Biết 覃 giúp đọc chiếu lệnh và thư tịch cổ mô tả ân đức của vua lan khắp: 覃恩, 覃及.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 覃 (đàm) là chữ cổ, xuất hiện dạng 𪉷 trong tiểu triện. Có dạng kim văn và triện văn. Nghĩa gốc là lan rộng, sâu xa, ân đức lan khắp. Wiktionary không có phân tích cấu trúc chi tiết. Chữ cũng dùng làm họ người. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1631.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Á (146) Tảo (072)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Á (số 146 - che đậy/ 襾) ở trên chữ Tảo (số 072 - buổi sáng sớm/ 早). Giải thích sự chuyển ý: Đàm mang ý nghĩa là sâu sắc, sâu xa. Đồng thời có nghĩa là kéo dài tới, lan rộng tới, kịp đến (đàm ân). (Chữ này cũng hay được dùng làm họ Đàm).", "Nghĩa Tiếng Việt_Xie": "lan tới; ơn lây; sâu rộng", "Hạng Tần Suất (Jun Da)": "4864.0", "Tần Suất % (Jun Da)": "99.9078365391", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 早", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀早", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "早", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "覃", "Unihan_Traditional (Chữ Phồn thể)": "覃", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ trong văn ngôn để chỉ sự lan rộng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馔', '{"9000": "4865.0", "Chữ Trung Quốc": "馔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 巽 | rốn | biểu âm | quẻ Tốn (phong) | 食 | thực | biểu nghĩa | ăn, thức ăn | 馔 là chữ hình thanh (psc): 巽 (Tốn, biểu âm) + 食 (Thực, biểu nghĩa: ăn, thức ăn). Chữ chỉ tiệc cỗ thịnh soạn, bữa ăn sang trọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"soạn\": bộ Thực (食 ăn) + Tốn (巽) — 馔 là bữa tiệc soạn sẵn, cỗ bàn thịnh soạn đãi khách. | Gương Hán-Việt | 馔 gặp trong văn cổ: 肴馔 (hào soạn) — các món ăn ngon; 珍馔 (trân soạn) — món ăn quý. | Mở khoá kiến thức | Biết 馔 giúp đọc văn ngôn mô tả tiệc cỗ và ẩm thực cung đình: 珍馔, 肴馔.", "Tự nguyên_Xie": "Tiểu triện | 馔 (soạn) là chữ hình thanh theo Wiktionary: {{Han compound|ls=psc|巽|食|c1=p|c2=s|t2=food}} — 巽 biểu âm + 食 (ăn/thức ăn) biểu nghĩa. Nghĩa gốc là thức ăn, bữa tiệc; cũng có nghĩa là ăn uống (dạng động từ). Có dạng triện văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỗ, tiệc; thịnh soạn", "Hạng Tần Suất (Jun Da)": "4865.0", "Tần Suất % (Jun Da)": "99.9080479042", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 巽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣巽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馔", "Unihan_Traditional (Chữ Phồn thể)": "饌", "Pinyin_Xie": "zhuàn", "Âm Hán Việt_Xie": "soạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các món ăn ngon hoặc làm động từ trong văn viết cổ chỉ việc chuẩn bị thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篾', '{"9000": "4866.0", "Chữ Trung Quốc": "篾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 竹 | trúc | biểu nghĩa | tre | 蔑 | miệt | biểu âm | khinh thường | 篾 là chữ hình thanh (psc): bộ 竹 (Trúc, biểu nghĩa: tre) + 蔑 (Miệt, biểu âm, viết tắt). Wiktionary ghi: {{Han compound|竹|蔑|ls=psc|c1=s|c2=p|abb2=y|t1=bamboo}}. Chữ chỉ nan tre, cật tre (phần vỏ cứng bên ngoài cây tre dùng để đan).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miệt\": bộ Trúc (竹 tre) + Miệt (蔑) — nan tre (篾) mỏng như sợi chỉ, đan thành rổ rá, bền bỉ và dẻo dai. | Gương Hán-Việt | 篾 dùng trong thủ công: 竹篾 (trúc miệt) — nan tre; 篾席 (miệt tịch) — chiếu tre. | Mở khoá kiến thức | Biết 篾 giúp đọc tài liệu thủ công nghiệp về đồ tre đan: 竹篾, 篾条, 篾席.", "Tự nguyên_Xie": "篾 (miệt) là chữ hình thanh theo Wiktionary: {{Han compound|竹|蔑|ls=psc|c1=s|c2=p|abb2=y|t1=bamboo}} — bộ Trúc (竹) biểu nghĩa + 蔑 viết tắt biểu âm. Nghĩa gốc là cật tre, nan tre mỏng dùng để đan rổ, rá, lồng. Không có dạng cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cật tre", "Hạng Tần Suất (Jun Da)": "4866.0", "Tần Suất % (Jun Da)": "99.9081533284", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "篾", "Unihan_Traditional (Chữ Phồn thể)": "篾", "Pinyin_Xie": "miè", "Âm Hán Việt_Xie": "miệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các danh từ khác để chỉ đồ dùng làm từ tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兖', '{"9000": "4867.0", "Chữ Trung Quốc": "兖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 8 | nét | 兖 | duyện | tượng hình | châu Duyện — địa danh cổ ở Sơn Đông, Trung Quốc | 兖 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 儿 hoặc là chữ độc lập dùng làm tên địa danh. Chủ yếu xuất hiện trong 兖州 (Duyện Châu) ở Sơn Đông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duyện\": 兖 là tên một trong Cửu Châu thời cổ đại — Duyện Châu nằm giữa Sơn Đông, đất bằng phẳng ven sông. | Gương Hán-Việt | 兖 xuất hiện trong tên địa danh: 兖州 (Duyện Châu) — thành phố thuộc tỉnh Sơn Đông. | Mở khoá kiến thức | Biết 兖 giúp nhận diện địa danh lịch sử 兖州 và đọc sử sách mô tả Cửu Châu.", "Tự nguyên_Xie": "兖 (duyện) là chữ địa danh, chỉ châu Duyện — một trong Cửu Châu thời cổ đại, thuộc vùng Sơn Đông ngày nay. Wiktionary chỉ có {{Han etym}} không chi tiết. Chữ xuất hiện trong Kinh Thư (Thư Kinh) mô tả Cửu Châu. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "châu Duyện (thuộc tỉnh Sơn Đông và Trực Lệ, Trung Quốc)", "Hạng Tần Suất (Jun Da)": "4867.0", "Tần Suất % (Jun Da)": "99.9082582358", "GavinGrover_Once (Chiết tự trực tiếp)": "六 + 允", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱六允", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "允", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "六", "Unihan_Simplified (Chữ Giản thể)": "兖", "Unihan_Traditional (Chữ Phồn thể)": "兗", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "duyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ một trong chín châu thời cổ đại của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阋', '{"9000": "4868.0", "Chữ Trung Quốc": "阋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 鬥 | đấu | biểu nghĩa | đánh nhau, tranh đấu | 兒 | nhi | biểu âm | đứa trẻ, con | 阋 là chữ hình thanh (psc): bộ 鬥 (Đấu, biểu nghĩa: đánh nhau) + 兒 (Nhi, biểu âm). Wiktionary ghi ls=psc và ls2=ic — vừa hình thanh vừa có thể đọc là hội ý. Chữ chỉ cãi vã, xô xát giữa anh em.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hích\": bộ Đấu (鬥 chiến đấu) + Nhi (兒 đứa trẻ) — 阋 là cãi nhau, anh em trong nhà tranh giành lẫn nhau. | Gương Hán-Việt | 阋 nổi tiếng trong thành ngữ 兄弟阋于墙，外御其侮 — anh em dù bất hòa trong nhà vẫn đoàn kết chống ngoại xâm. | Mở khoá kiến thức | Biết 阋 giúp hiểu thành ngữ 兄弟阋于墙 và đọc kinh điển về đạo huynh đệ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 阋 (hích) là chữ hình thanh/hội ý theo Wiktionary: {{Han compound|鬥|兒|ls=psc|ls2=ic|c1=s|c2=p}} — bộ Đấu (鬥, tranh đấu) biểu nghĩa + 兒 biểu âm. Nghĩa là cãi nhau, đánh nhau, đặc biệt giữa anh em trong nhà. Nổi tiếng qua thành ngữ 兄弟阋于墙 (huynh đệ hích vu tường). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cãi nhau, đánh nhau", "Hạng Tần Suất (Jun Da)": "4868.0", "Tần Suất % (Jun Da)": "99.9083631431", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阋", "Unihan_Traditional (Chữ Phồn thể)": "鬩", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "huých", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn, phổ biến nhất trong thành ngữ chỉ sự bất hòa trong gia đình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遨', '{"9000": "4869.0", "Chữ Trung Quốc": "遨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 13 | nét | 辶 | sước | biểu nghĩa | đi bộ, bước đi | 敖 | ngào | biểu âm | ngao du, lang thang | 遨 là chữ hình thanh (psc) kiêm hội ý (ic): bộ 辶 (Sước, biểu nghĩa: đi bộ) + 敖 (Ngào, biểu âm và cũng biểu nghĩa: ngao du). Wiktionary ghi cả ls=psc và ls2=ic. Chữ chỉ đi chơi thong dong, ngao du tự do.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": bộ Sước (辶 đi) + Ngào (敖 lang thang) — 遨 là ngao du bốn phương, thảnh thơi như mây trắng. | Gương Hán-Việt | 遨 gặp trong thành ngữ: 遨游 (ngao du) — đi chơi thong dong; 遨翔 (ngao tường) — bay lượn tự do. | Mở khoá kiến thức | Biết 遨 giúp hiểu từ 遨游 (ngao du) và các từ mô tả sự tự do, thong dong trong thơ cổ.", "Tự nguyên_Xie": "遨 (ngao) là chữ hình thanh kiêm hội ý theo Wiktionary: {{Han compound|辵|敖|alt1=辶|t1=walk|t2=ramble|ls=psc|c1=s|c2=p|ls2=ic}} — 辶 (đi bộ) biểu nghĩa + 敖 (ngao du) biểu âm và cũng gợi nghĩa. Nghĩa là đi chơi ung dung, ngao du không mục đích cụ thể. Chữ rõ nghĩa từ cấu trúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi chơi ung dung", "Hạng Tần Suất (Jun Da)": "4869.0", "Tần Suất % (Jun Da)": "99.9084680505", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 敖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶敖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遨", "Unihan_Traditional (Chữ Phồn thể)": "遨", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với các từ chỉ sự di chuyển để diễn tả việc đi du ngoạn tự do. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爰', '{"9000": "4870.0", "Chữ Trung Quốc": "爰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 爪 | Số nét | 9 | nét | 爫 | trảo | bàn tay (trên) | 丨 | đường thẳng | 又 | hựu | bàn tay (dưới) | 爰 là chữ hội ý (ic): 爫 (Trảo, bàn tay trên) + 丨 (đường thẳng) + 又 (Hựu, bàn tay phải). Wiktionary mô tả: ''two hands holding or pulling something, possibly indicating to pull, the original form of 援.'' Hai bàn tay kéo một vật — gợi hành động chuyển đổi, từ đó nghĩa là bởi vậy, vì thế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vươn\": hai bàn tay (爫 và 又) chụm vào kéo (丨) — 爰 là vươn tay kéo, rồi nghĩa hư hoá thành ''bởi vậy, vì thế'' trong văn ngôn. | Gương Hán-Việt | 爰 gặp trong văn ngôn: 爰及 (vươn cập) — đến tận; 爰居 (vươn cư) — ở đó; 爰始 (vươn thuỷ) — bắt đầu từ đó. | Mở khoá kiến thức | Biết 爰 giúp đọc kinh điển và chiếu lệnh cổ: từ kết nối trong văn ngôn như 爰及, 爰居.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 爰 (vươn) là chữ hội ý (ic) theo Wiktionary: {{Han compound|爪|t1=hand|alt1=爫|丨|t2=|又|t3=hand|ls=ic}} — hai bàn tay cầm hay kéo vật gì đó. Có thể là dạng gốc của 援 (cứu trợ, kéo lên). Nghĩa hiện đại là từ kết nối ''bèn, vì thế''. Có dạng kim văn, đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1291.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (087) Nhất (001) Hữu (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trảo (số 087 - vuốt/ 爫) ở trên bộ Nhất (一) và chữ Hữu (số 029 - tay/ 友). Hai tay cầm lấy một vật truyền cho nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Viên nghĩa đen là lôi kéo, cầm nắm. Sau được mượn làm hư từ mang nghĩa là bèn, bèn làm (viết thư hoán cải).", "Nghĩa Tiếng Việt_Xie": "bèn, bởi vậy, cho nên", "Hạng Tần Suất (Jun Da)": "4870.0", "Tần Suất % (Jun Da)": "99.9085729579", "GavinGrover_Once (Chiết tự trực tiếp)": "爫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "爰", "Unihan_Traditional (Chữ Phồn thể)": "爰", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Đại từ | 代词 | Giới từ | 介词 | Thường làm liên từ đứng đầu vế câu trong văn ngôn để biểu thị quan hệ nhân quả hoặc tiếp nối. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痂', '{"9000": "4871.0", "Chữ Trung Quốc": "痂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疒 | nạch | biểu nghĩa | bệnh, ốm | 加 | gia | biểu âm | thêm vào | 痂 là chữ hình thanh (psc): bộ 疒 (Nạch, biểu nghĩa: bệnh/thương tích) + 加 (Gia, biểu âm). Chữ chỉ vảy da hình thành khi vết thương khô lại và đóng vảy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gia\": bộ Bệnh (疒) + Gia (加 thêm vào) — vảy da (痂) như lớp được thêm vào trên vết thương, bảo vệ da đang lành. | Gương Hán-Việt | 痂 ít dùng trong tiếng Việt Hán-Việt; ''vảy'' là cách gọi thông dụng. | Mở khoá kiến thức | Biết 痂 giúp đọc tài liệu y học: 结痂 (kết gia) — đóng vảy, lên da non.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 痂 (gia) là chữ hình thanh theo Wiktionary: {{Han compound|疒|加|ls=psc|c1=s|c2=p}} — bộ Nạch (疒, bệnh/thương tích) biểu nghĩa + 加 biểu âm. Nghĩa là vảy da (scab) — lớp da cứng hình thành trên vết thương đang lành. Có dạng đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vẩy (chỗ chảy máu rồi đóng vẩy)", "Hạng Tần Suất (Jun Da)": "4871.0", "Tần Suất % (Jun Da)": "99.9086778653", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痂", "Unihan_Traditional (Chữ Phồn thể)": "痂", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "già", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ làm tân ngữ cho động từ kết vảy hoặc đứng một mình chỉ vết vảy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艄', '{"9000": "4872.0", "Chữ Trung Quốc": "艄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 13 | nét | 艄 | sao | tượng hình | đuôi thuyền, lái thuyền | 艄 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 舟 (thuyền), chỉ phần đuôi thuyền nơi đặt bánh lái. Anchor chỉ có {{Han etym}} không phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": bộ Chu (舟 thuyền) — 艄 là đuôi thuyền, nơi người lái đứng điều hướng; 艄公 (sao công) là ông lái đò. | Gương Hán-Việt | 艄 gặp trong từ 艄公 (sao công) — ông chèo đò, người lái thuyền. | Mở khoá kiến thức | Biết 艄 giúp nhận diện từ 艄公 (lái đò) và 船艄 (đuôi thuyền) trong văn học mô tả sông nước.", "Tự nguyên_Xie": "艄 (sao) là chữ thuộc bộ 舟 (thuyền), chỉ phần đuôi thuyền (stern) hoặc người lái ở phần đuôi. Wiktionary chỉ có {{Han etym}} không chi tiết. Không có dạng cổ đại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đuôi thuyền", "Hạng Tần Suất (Jun Da)": "4872.0", "Tần Suất % (Jun Da)": "99.9087827727", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艄", "Unihan_Traditional (Chữ Phồn thể)": "艄", "Pinyin_Xie": "shāo", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần đuôi thuyền hoặc bánh lái của thuyền bè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耨', '{"9000": "4873.0", "Chữ Trung Quốc": "耨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 16 | nét | 耒 | lồi | biểu nghĩa | cái cày | 辱 | nhục | biểu âm | nhục nhã | 耨 là chữ hình thanh (psc): bộ 耒 (Lồi, biểu nghĩa: cái cày/công cụ làm đất) + 辱 (Nhục, biểu âm). Chữ chỉ cái dầm (cuốc xới để làm cỏ), và động tác làm cỏ ruộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nậu\": bộ Lồi (耒 cày) + Nhục (辱) — 耨 là cái dầm làm cỏ ruộng, mỗi nhát cuốc nhọc nhằn như bị nhục dưới nắng hè. | Gương Hán-Việt | 耨 gặp trong văn cổ: 耕耨 (canh nậu) — cày và làm cỏ; 耒耨 (lồi nậu) — dụng cụ nông nghiệp. | Mở khoá kiến thức | Biết 耨 giúp đọc Kinh Thư và văn ngôn nông nghiệp: 耕耨, 锄耨.", "Tự nguyên_Xie": "Lục thư thông | 耨 (nậu) là chữ hình thanh theo Wiktionary: {{Han compound|耒|辱|ls=psc|c1=s|c2=p|t1=plough}} — bộ Lồi (耒, cày) biểu nghĩa + 辱 biểu âm. Nghĩa là cái dầm (công cụ làm cỏ), hoặc động tác cuốc xới để nhổ cỏ dại. Chỉ có dạng lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái dầm (để làm cỏ); làm cỏ", "Hạng Tần Suất (Jun Da)": "4873.0", "Tần Suất % (Jun Da)": "99.90888768", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 辱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒辱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耨", "Unihan_Traditional (Chữ Phồn thể)": "耨", "Pinyin_Xie": "nòu", "Âm Hán Việt_Xie": "nậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hoạt động làm cỏ hoặc danh từ chỉ nông cụ làm cỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沤', '{"9000": "4874.0", "Chữ Trung Quốc": "沤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 沤 | âu | tượng hình | bọt nước; ngâm (ủ trong nước) | 沤 là chữ giản thể của 漚, bộ 氵(thuỷ). Anchor chỉ cho biết {{Han simp|f=區|t=区}} không phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": bộ Thuỷ (氵nước) — 沤 là bọt nước nổi lên mặt, hay ngâm vật vào nước lâu ngày cho mềm/ủ. | Gương Hán-Việt | 沤 gặp trong nông nghiệp: 沤肥 (âu phì) — ủ phân hữu cơ; 沤麻 (âu ma) — ngâm đay. | Mở khoá kiến thức | Biết 沤 giúp đọc tài liệu nông nghiệp hữu cơ: 沤肥, 沤田 (ủ phân, ngâm ruộng).", "Tự nguyên_Xie": "Tiểu triện | 沤 là giản thể của 漚 (ōu/òu), theo cấu trúc {{Han simp|f=區|t=区}}. Bộ 氵(nước) kết hợp với phần biểu âm. Nghĩa: (1) bọt nước (nổi trên mặt nước); (2) ngâm, ủ trong nước (như ủ phân, ngâm sợi đay). Có dạng triện văn. Chữ tạo sau giáp cốt. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bọt nước", "Hạng Tần Suất (Jun Da)": "4874.0", "Tần Suất % (Jun Da)": "99.9089920706", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 区", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵区", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沤", "Unihan_Traditional (Chữ Phồn thể)": "漚", "Pinyin_Xie": "ōu", "Âm Hán Việt_Xie": "ẩu, âu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc ngâm ủ chất hữu cơ hoặc làm danh từ chỉ bong bóng nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邋', '{"9000": "4875.0", "Chữ Trung Quốc": "邋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 18 | nét | 邋 | lạp | tượng hình | luộm thuộm, bừa bãi, không gọn gàng | 邋 không có dữ liệu anchor thành phần chi tiết. Chữ thuộc bộ 辶 (sước, đi bộ). Có dạng giáp cốt, triện văn và lục thư thông. Nghĩa chính là luộm thuộm, bừa bãi; âm đọc lā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\": 邋 là người đi lại (辶) luộm thuộm, bừa bãi — 邋遢 (lā ta) là từ miêu tả người lôi thôi lếch thếch. | Gương Hán-Việt | 邋 gặp chủ yếu trong từ 邋遢 (lạp tà) — luộm thuộm, bẩn thỉu, không chỉnh tề. | Mở khoá kiến thức | Biết 邋 giúp nhận diện và dùng từ 邋遢 trong hội thoại hàng ngày.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | 邋 (lạp) là chữ có dạng giáp cốt, triện văn và lục thư thông. Có hai âm đọc: liè (văn ngôn, cổ nghĩa) và lā (hiện đại, nghĩa luộm thuộm). Wiktionary có {{Han etym}} không chi tiết về cấu trúc. Thường gặp trong từ 邋遢 (lā ta) — bẩn thỉu, luộm thuộm. Chưa có phân tích học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "luộm thuộm, không gọn gàng", "Hạng Tần Suất (Jun Da)": "4875.0", "Tần Suất % (Jun Da)": "99.9090964612", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 巤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶巤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "邋", "Unihan_Traditional (Chữ Phồn thể)": "邋", "Pinyin_Xie": "lā", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ tháp thành từ láy tính từ chỉ sự luộm thuộm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焓', '{"9000": "4876.0", "Chữ Trung Quốc": "焓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 火 | hoả | biểu nghĩa | lửa, nhiệt | 含 | hàm | biểu âm | chứa bên trong | 焓 là chữ hình thanh (psc) kiêm hội ý (ic): bộ 火 (Hoả, biểu nghĩa: lửa/nhiệt) + 含 (Hàm, biểu âm và cũng biểu nghĩa: chứa bên trong). Wiktionary ghi ls=ic và ls2=psc — nhiệt hàm là lượng nhiệt chứa bên trong hệ thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầm\": bộ Hoả (火 lửa) + Hàm (含 chứa) — 焓 là nhiệt hàm: lượng nhiệt ''hầm'' bên trong, ẩn chứa trong hệ thống nhiệt động. | Gương Hán-Việt | 焓 dùng trong khoa học: 焓变 (hầm biến) — biến thiên enthalpy; 生成焓 (sinh thành hầm) — enthalpy hình thành. | Mở khoá kiến thức | Biết 焓 giúp đọc tài liệu nhiệt động lực học và hóa học: 焓变, 焓值, 生成焓.", "Tự nguyên_Xie": "焓 (hầm) là chữ hình thanh kiêm hội ý theo Wiktionary: {{Han compound|火|含|ls=ic|ls2=psc|c1=s|c2=p|t1=fire|t2=to contain inside|tr2=hán}} — bộ Hoả (火, lửa/nhiệt) biểu nghĩa + 含 (chứa bên trong) biểu âm và biểu nghĩa. Chữ được tạo ra để dịch khái niệm Enthalpy trong nhiệt động lực học: lượng nhiệt chứa trong hệ thống. Không có dạng cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiệt hàm, lượng chứa nhiệt", "Hạng Tần Suất (Jun Da)": "4876.0", "Tần Suất % (Jun Da)": "99.9092008518", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 含", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火含", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "含", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焓", "Unihan_Traditional (Chữ Phồn thể)": "焓", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên ngành vật lý và hóa học để chỉ hàm lượng nhiệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秣', '{"9000": "4877.0", "Chữ Trung Quốc": "秣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 末 | mạt | biểu âm | 秣 gồm 禾 (Hòa, biểu nghĩa: lúa/ngũ cốc) và 末 (Mạt, biểu âm). Đây là chữ hình thanh — 禾 chỉ loại vật liệu, 末 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": lúa (禾) dùng làm thức ăn cho ngựa — mạt lúa, cỏ khô nuôi ngựa chiến. | Gương Hán-Việt | mạt — ít dùng trong tiếng Việt hiện đại, xuất hiện trong thành ngữ \"lệ binh mạt mã\" (厲兵秣馬: mài gươm cho ngựa ăn no — chuẩn bị chiến tranh). | Mở khoá kiến thức | Biết 秣 mở khoá thành ngữ 厲兵秣馬 (luyện binh mạt mã: tích cực chuẩn bị cho trận chiến).", "Tự nguyên_Xie": "Lục thư thông | Chữ 秣 thuộc bộ 禾 (lúa), chỉ cỏ khô hoặc thức ăn cho ngựa. Theo cấu trúc hình thanh, 禾 biểu nghĩa liên quan đến ngũ cốc, còn phần âm gợi cách đọc. Chưa có nguồn học thuật từ Wiktionary về nguồn gốc chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thóc cho ngựa ăn", "Hạng Tần Suất (Jun Da)": "4877.0", "Tần Suất % (Jun Da)": "99.9093052424", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秣", "Unihan_Traditional (Chữ Phồn thể)": "秣", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc cho ngựa ăn hoặc danh từ chỉ thức ăn của ngựa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昶', '{"9000": "4878.0", "Chữ Trung Quốc": "昶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 9 | nét | 昶 | xướng | tượng hình | ngày dài, sáng rõ | 昶 là chữ độc thể, bộ 日 (mặt trời) ở trên, gợi ý liên quan đến ánh sáng ban ngày. Wiktionary không cung cấp phân tích cấu trúc rõ ràng nên xếp dạng tượng hình, có thể là hội ý giữa 日 và 永 (dài lâu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xướng\": mặt trời (日) chiếu suốt ngày dài — ngày \"xướng\" lên, sáng mãi không tắt. | Gương Hán-Việt | xướng — rất ít dùng trong tiếng Việt hiện đại; chủ yếu thấy trong tên riêng người Trung Quốc. | Mở khoá kiến thức | Biết 昶 giúp nhận ra các chữ liên quan đến ánh sáng ban ngày và tên người có ý nghĩa tươi sáng, lâu dài.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ 昶 (chǎng) mang nghĩa ngày dài, sáng rõ. Trong kim văn và tiểu triện đã xuất hiện dạng này. Có lẽ kết hợp 日 (mặt trời) với yếu tố gợi sự kéo dài, nhưng Wiktionary không ghi cấu trúc hình thanh/hội ý cụ thể. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngày dài", "Hạng Tần Suất (Jun Da)": "4878.0", "Tần Suất % (Jun Da)": "99.909409633", "GavinGrover_Once (Chiết tự trực tiếp)": "永 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴永日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "永", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昶", "Unihan_Traditional (Chữ Phồn thể)": "昶", "Pinyin_Xie": "chǎng", "Âm Hán Việt_Xie": "sưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự thông suốt, sáng sủa hoặc dùng làm danh từ trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窣', '{"9000": "4879.0", "Chữ Trung Quốc": "窣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 13 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng | 卒 | tốt | biểu âm | binh lính, đột ngột | 窣 có bộ 穴 (Huyệt: hang, lỗ hổng) ở trên. Theo cấu trúc có thể là hình thanh — 穴 biểu nghĩa (vọt ra từ hang), phần dưới biểu âm. Wiktionary không ghi cấu trúc chi tiết. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốt\": từ hang (穴) bỗng vọt ra — tiếng窣窣 xào xạc như chuột chạy trong hang. | Gương Hán-Việt | tuất — ít dùng trong tiếng Việt; xuất hiện trong từ ghép mô tả tiếng động nhỏ. | Mở khoá kiến thức | Biết 窣 giúp nhận ra các từ mô tả tiếng động nhỏ và chuyển động lén lút: 窸窣 (xào xạc), 窣地 (đột nhiên).", "Tự nguyên_Xie": "Tiểu triện | Chữ 窣 (sū) nghĩa là vọt ra khỏi hang hoặc tiếng xào xạc, huyên náo nhỏ. Bộ 穴 gợi ý liên quan đến hang hốc. Tiểu triện đã có dạng này. Wiktionary không cung cấp phân tích hình thanh/hội ý cụ thể. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vọt ra khỏi hang; tiếng huyên náo", "Hạng Tần Suất (Jun Da)": "4879.0", "Tần Suất % (Jun Da)": "99.9097217713", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窣", "Unihan_Traditional (Chữ Phồn thể)": "窣", "Pinyin_Xie": "sū", "Âm Hán Việt_Xie": "tốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này làm từ tượng thanh mô tả tiếng động nhỏ hoặc động từ chỉ hành động vọt ra đột ngột. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绦', '{"9000": "4880.0", "Chữ Trung Quốc": "绦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 攸 | du | biểu âm | 糸 | mịch | biểu nghĩa | tơ, sợi | 绦 = 攸 (Du, biểu âm) + 糸 (Mịch, biểu nghĩa: tơ sợi). Chữ hình thanh — 糸 chỉ chất liệu tơ lụa, 攸 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": sợi tơ (糸) bện thành dải — đao kiếm thường có dây tơ bằng chữ 绦 buộc chuôi. | Gương Hán-Việt | đao — ít dùng độc lập trong tiếng Việt; xuất hiện trong \"sán đao\" (giun dải/sán lá). | Mở khoá kiến thức | Biết 绦 mở khoá: 絛蟲 (sán dây/tapeworm), 絲絛 (dây tơ), 絛子 (dây bện).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 绦 (dạng phồn thể 絛) là chữ hình thanh: 攸 biểu âm, 糸 (tơ sợi) biểu nghĩa. Tiểu triện đã có dạng này. Nghĩa gốc là dây bện từ tơ lụa, dải thắt lưng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây bằng sợi tơ", "Hạng Tần Suất (Jun Da)": "4880.0", "Tần Suất % (Jun Da)": "99.9098251283", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 条", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟条", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "条", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绦", "Unihan_Traditional (Chữ Phồn thể)": "絛", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại dây dệt bằng tơ sợi dùng để trang trí hoặc buộc áo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俎', '{"9000": "4881.0", "Chữ Trung Quốc": "俎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 俎 | trở | tượng hình | bàn thờ tế lễ, thớt | 俎 là chữ tượng hình — mô phỏng cái bàn tế thịt (altar) với chân bàn ở trái và bình đựng ở phải. Không phân tích thành hình thanh hay hội ý theo cấu trúc đơn giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trở\": hình ảnh bàn tế (俎) — thịt trên bàn thờ, dao trên thớt — \"thân làm thịt trên thớt người\" (dao trở ngư nhục 刀俎魚肉). | Gương Hán-Việt | trở — xuất hiện trong thành ngữ \"đao trở ngư nhục\" (刀俎魚肉: dao và thớt — kẻ yếu trong tay kẻ mạnh). | Mở khoá kiến thức | Biết 俎 mở khoá thành ngữ 越俎代庖 (vượt qua thớt thay bếp — làm thay việc người khác) và 刀俎魚肉.", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 俎 là chữ tượng hình ({{liushu|p}}): hình vẽ bàn tế lễ đặt thịt, chân bàn ở bên trái, bình đựng ở bên phải. Kim văn, bạch thư và tiểu triện đều lưu dạng này. Dùng trong nghi lễ tế tự thời cổ đại, về sau có nghĩa là thớt chặt thịt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thớt", "Hạng Tần Suất (Jun Da)": "4881.0", "Tần Suất % (Jun Da)": "99.9099284853", "GavinGrover_Once (Chiết tự trực tiếp)": "仌 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰仌且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "仌", "Unihan_Simplified (Chữ Giản thể)": "俎", "Unihan_Traditional (Chữ Phồn thể)": "俎", "Pinyin_Xie": "zǔ", "Âm Hán Việt_Xie": "trở", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong các thành ngữ cổ hoặc từ ghép chỉ việc giết mổ, tế lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榫', '{"9000": "4882.0", "Chữ Trung Quốc": "榫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 榫 | thốn | tượng hình | mộng gỗ, chỗ ghép nối | 榫 có bộ 木 (mộc: gỗ) ở trái, phần phải biểu âm. Wiktionary không cung cấp phân tích cấu trúc rõ ràng, nhưng theo quy luật hình thanh phổ biến, đây có thể là chữ hình thanh với 木 biểu nghĩa. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thốn\": gỗ (木) lồng vào nhau chắc chắn — \"thốn\" như thốn tim, mộng gỗ khớp vào ổ không lay chuyển. | Gương Hán-Việt | thốn — hầu như không dùng trong tiếng Việt; 榫 là từ kỹ thuật mộc chuyên ngành. | Mở khoá kiến thức | Biết 榫 mở khoá từ vựng kỹ thuật mộc: 榫眼 (lỗ mộng), 卯榫 (mộng âm dương), 榫頭 (đầu mộng).", "Tự nguyên_Xie": "Chữ 榫 (sǔn) mang nghĩa mộng gỗ — phần lồi ghép vào lỗ (mộng âm dương). Bộ 木 (gỗ) gợi chất liệu. Wiktionary không ghi nguồn gốc chi tiết. Đây là chữ có lịch sử dùng trong nghề mộc truyền thống. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tra ngàm, tra mộng gỗ", "Hạng Tần Suất (Jun Da)": "4882.0", "Tần Suất % (Jun Da)": "99.9100313256", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 隼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木隼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榫", "Unihan_Traditional (Chữ Phồn thể)": "榫", "Pinyin_Xie": "sǔn", "Âm Hán Việt_Xie": "chuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bộ phận mộng gỗ hoặc làm động từ chỉ việc đục mộng, ghép mộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟪', '{"9000": "4883.0", "Chữ Trung Quốc": "蟪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟪 | huệ | tượng hình | loài ve sầu nhỏ (蟪蛄) | 蟪 có bộ 虫 (côn trùng) ở trái. Cấu trúc đầy đủ không được Wiktionary ghi rõ. Theo bộ 虫, đây là chữ liên quan đến côn trùng. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huệ\": côn trùng (虫) nhỏ bé — con 蟪蛄 chỉ sống một mùa, không biết xuân thu (Trang Tử). | Gương Hán-Việt | huệ — ít dùng trong tiếng Việt; 蟪蛄 xuất hiện trong văn học cổ điển (Trang Tử). | Mở khoá kiến thức | Biết 蟪 giúp đọc câu nổi tiếng của Trang Tử: 蟪蛄不知春秋 (ve nhỏ không biết xuân thu — kiến thức hữu hạn).", "Tự nguyên_Xie": "Tiểu triện | Chữ 蟪 (huì) chỉ xuất hiện trong từ ghép 蟪蛄 — một loại ve sầu nhỏ. Bộ 虫 chỉ côn trùng. Wiktionary không ghi nguồn gốc chi tiết. Tiểu triện đã có dạng này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: huệ cô 蟪蛄)", "Hạng Tần Suất (Jun Da)": "4883.0", "Tần Suất % (Jun Da)": "99.9101341658", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 惠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫惠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟪", "Unihan_Traditional (Chữ Phồn thể)": "蟪", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "huệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ, hầu như chỉ dùng trong từ ghép huệ cô để chỉ loài ve sầu đoản mệnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稗', '{"9000": "4884.0", "Chữ Trung Quốc": "稗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 稗 | bại | tượng hình | cỏ lồng vực, cỏ dại giống lúa | 稗 có bộ 禾 (lúa, ngũ cốc) ở trái — chỉ loại cây giống lúa. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Theo cấu trúc, đây có thể là hình thanh với 禾 biểu nghĩa. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bại\": lúa (禾) giả — cỏ bại trận lẫn vào ruộng lúa, nhỏ nhặt, không đáng kể. | Gương Hán-Việt | bại — xuất hiện trong \"tì quan bại sử\" (稗官野史: sử không chính thống, giai thoại dân gian). | Mở khoá kiến thức | Biết 稗 mở khoá: 稗官野史 (tì quan dã sử: giai thoại, tiểu thuyết dân gian), 稗草 (cỏ lồng vực).", "Tự nguyên_Xie": "Tiểu triện | Chữ 稗 (bài) chỉ cỏ lồng vực (cỏ dại mọc lẫn trong ruộng lúa, rất khó phân biệt). Bộ 禾 gợi sự liên quan đến lúa/ngũ cốc. Tiểu triện đã có dạng này. Wiktionary không ghi nguồn gốc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ cỏ)", "Hạng Tần Suất (Jun Da)": "4884.0", "Tần Suất % (Jun Da)": "99.9102364892", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稗", "Unihan_Traditional (Chữ Phồn thể)": "稗", "Pinyin_Xie": "bài", "Âm Hán Việt_Xie": "bại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ loài cỏ dại hoặc làm tính từ đứng trước danh từ để chỉ tính chất không chính thống, dân gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謇', '{"9000": "4885.0", "Chữ Trung Quốc": "謇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 謇 | kiển | tượng hình | nói ngắc ngứ, ngay thẳng | 謇 có bộ 言 (ngôn: lời nói) ở dưới. Cấu trúc trên không rõ, Wiktionary không ghi hình thanh/hội ý cụ thể. Bộ 言 gợi liên quan đến lời nói, ngôn ngữ. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiển\": lời nói (言) khó ra — người kiển miệng nói ngắc ngứ nhưng lòng ngay thẳng. | Gương Hán-Việt | kiển — hầu như không dùng trong tiếng Việt hiện đại; xuất hiện trong văn học cổ với nghĩa khó nói, can gián. | Mở khoá kiến thức | Biết 謇 giúp đọc văn cổ điển có nghĩa nói ngắc ngứ hoặc can gián trung thực: 謇謇諤諤 (thẳng thắn can gián).", "Tự nguyên_Xie": "Chữ 謇 (jiǎn) mang hai nghĩa: nói ngắc ngứ/ấp úng và ngay thẳng dũng cảm. Bộ 言 (lời nói) ở dưới. Wiktionary không ghi nguồn gốc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khó nói; lời nói ngay thẳng", "Hạng Tần Suất (Jun Da)": "4885.0", "Tần Suất % (Jun Da)": "99.9103388127", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "謇", "Unihan_Traditional (Chữ Phồn thể)": "謇", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ bổ nghĩa cho lời nói ngay thẳng hoặc trạng thái nói năng khó khăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氩', '{"9000": "4886.0", "Chữ Trung Quốc": "氩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 10 | nét | 气 | khí | biểu nghĩa | khí, hơi | 亚 | á | biểu âm | 氩 = 气 (Khí, biểu nghĩa: khí thể) + 亚 (Á, biểu âm). Đây là chữ hình thanh hiện đại, được tạo ra để phiên âm tên nguyên tố hóa học Argon (Ar) — 气 chỉ đây là chất khí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không có đọc chuẩn: 氩 là tên hóa học của Argon — khí (气) trơ, chiếm ~1% khí quyển Trái Đất. | Gương Hán-Việt | á — phiên âm kỹ thuật hóa học, không dùng trong tiếng Việt thông thường. | Mở khoá kiến thức | Biết 氩 giúp nhận ra tên các nguyên tố khí trong tiếng Trung: 氧 (oxy), 氢 (hydro), 氮 (nitơ), 氦 (heli), 氩 (argon).", "Tự nguyên_Xie": "氩 là chữ tạo mới trong tiếng Trung hiện đại để biểu thị nguyên tố Argon (Ar, số hiệu 18). Cấu trúc hình thanh: 气 (khí) biểu nghĩa — chỉ đây là chất khí; phần âm biểu âm \"yà\". Không có nguồn gốc cổ điển. Chưa có nguồn học thuật từ Wiktionary. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố Argon (hoá học)", "Hạng Tần Suất (Jun Da)": "4886.0", "Tần Suất % (Jun Da)": "99.9104411362", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 亚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气亚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氩", "Unihan_Traditional (Chữ Phồn thể)": "氬", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "á", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chuyên ngành hóa học, thường đứng độc lập hoặc kết hợp tạo tên hợp chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锴', '{"9000": "4887.0", "Chữ Trung Quốc": "锴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại, sắt | 皆 | giai | biểu âm | 锴 = 金 (Kim, biểu nghĩa: kim loại) + 皆 (Giai, biểu âm). Chữ hình thanh — 金 chỉ đây là loại kim loại tốt, 皆 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": kim loại (金) tốt như giai (皆) — 锴 chỉ loại sắt thượng hạng, cứng và tinh khiết. | Gương Hán-Việt | khải — hầu như không dùng trong tiếng Việt; xuất hiện trong tên người (Từ Khải — 徐鍇, học giả nổi tiếng thời Ngũ Đại). | Mở khoá kiến thức | Biết 锴 giúp nhận ra tên học giả Từ Khải (徐鍇), tác giả sách Thuyết Văn Hệ Truyện (說文繫傳).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (dạng phồn thể 鍇), 锴 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 皆 biểu âm. Nghĩa là sắt tốt chất lượng cao. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắt tốt; vững chắc, kiên cố", "Hạng Tần Suất (Jun Da)": "4887.0", "Tần Suất % (Jun Da)": "99.9106457831", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锴", "Unihan_Traditional (Chữ Phồn thể)": "鍇", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loại sắt chất lượng tốt, chủ yếu dùng trong văn ngôn hoặc đặt tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龉', '{"9000": "4888.0", "Chữ Trung Quốc": "龉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 15 | nét | 齿 | xỉ | biểu nghĩa | răng | 吾 | ngô | biểu âm | 龉 (giản thể của 齬) = 齿 (Xỉ, biểu nghĩa: răng) + phần biểu âm. Wiktionary ghi đây là chữ giản hoá từ 齬 — bộ 齒/齿 chỉ liên quan đến răng. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngữ\": răng (齿) không khớp nhau — khi người ta \"ngữ\" nhau, ý kiến không ăn khớp như hàm răng lệch. | Gương Hán-Việt | ngữ — ít dùng trong tiếng Việt; xuất hiện trong từ ghép 龃龉 (sự bất đồng, không thuận). | Mở khoá kiến thức | Biết 龉 mở khoá từ ghép 龃龉 (trở ngữ: sự bất đồng, ý kiến không ăn khớp nhau).", "Tự nguyên_Xie": "Tiểu triện | 龉 là chữ giản thể của 齬, bộ 齒 (răng) thay bằng 齿. Nghĩa là răng không khớp, lồi lõm không đều. Về sau dùng trong thành ngữ 龃龉 (sự bất đồng, không ăn khớp). Wiktionary ghi {{Han simp}} không có phân tích gốc xa hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trở ngữ 齟齬,龃龉)", "Hạng Tần Suất (Jun Da)": "4888.0", "Tần Suất % (Jun Da)": "99.9107481065", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龉", "Unihan_Traditional (Chữ Phồn thể)": "齬", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "ngữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp với chữ trở tạo thành từ láy chỉ sự bất đồng ý kiến hoặc răng mọc lệch. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烃', '{"9000": "4889.0", "Chữ Trung Quốc": "烃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hỏa | biểu nghĩa | lửa — gợi năng lượng, nhiên liệu | 烃 | kinh | tượng hình | hydrocarbon | 烃 = 火/灬 (Hỏa, biểu nghĩa: lửa/năng lượng) + phần biểu âm. Đây là chữ hóa học hiện đại, 火 chỉ đây là hợp chất dễ cháy. Wiktionary chỉ ghi {{Han etym}} không chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khinh\": lửa (火) từ phân tử carbon — 烃 là hydrocarbon, xăng dầu đều là hợp chất kinh này. | Gương Hán-Việt | kinh — thuật ngữ hóa học, không dùng trong tiếng Việt thông thường. | Mở khoá kiến thức | Biết 烃 giúp đọc thuật ngữ hóa học: 烃类 (hydrocarbon), 烷烃 (ankan), 烯烃 (anken), 炔烃 (ankyn).", "Tự nguyên_Xie": "烃 là chữ tạo mới trong tiếng Trung hiện đại để biểu thị hydrocarbon (hợp chất gồm carbon và hydrogen). Bộ 火 (lửa) biểu nghĩa — chỉ đây là hợp chất dễ cháy, có nhiệt năng. Wiktionary không có nguồn gốc cổ điển. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hydrocacbon (hoá học)", "Hạng Tần Suất (Jun Da)": "4889.0", "Tần Suất % (Jun Da)": "99.91085043", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "烃", "Unihan_Traditional (Chữ Phồn thể)": "烴", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "hĩnh, thinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chuyên ngành hóa học, dùng để cấu tạo tên các hợp chất hữu cơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俣', '{"9000": "4890.0", "Chữ Trung Quốc": "俣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 俣 | ngữ | tượng hình | cao lớn, to lớn | 俣 có bộ 亻(người) ở trái, gợi liên quan đến con người. Wiktionary ghi đây là biến thể của chữ Nhật 俟. Cấu trúc hình thanh không xác định rõ. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngũ\": người (亻) cao lớn — 俣俣 mô tả người hoặc vật to lớn, hùng dũng. | Gương Hán-Việt | ngữ — hầu như không dùng trong tiếng Việt; rất hiếm trong tiếng Trung hiện đại. | Mở khoá kiến thức | Biết 俣 giúp nhận ra chữ hiếm mô tả vóc dáng to lớn trong văn cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 俣 là biến thể dạng của 俟 trong tiếng Nhật, thường bị nhầm là chữ quốc tự Nhật. Trong tiếng Trung, 俣 mang nghĩa cao lớn, to lớn. Tiểu triện đã có dạng này. Chưa có nguồn học thuật đầy đủ về nguồn gốc Trung Hoa. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao lớn, to lớn", "Hạng Tần Suất (Jun Da)": "4890.0", "Tần Suất % (Jun Da)": "99.9109522367", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俣", "Unihan_Traditional (Chữ Phồn thể)": "俁", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả ngoại hình cao lớn của con người, thường dùng trong văn học cổ hoặc tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬷', '{"9000": "4891.0", "Chữ Trung Quốc": "嬷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 17 | nét | 嬷 | ma | tượng hình | mẹ đẻ, vú già, bà lão | 嬷 có bộ 女 (phụ nữ) ở trái. Wiktionary không có mục cho 嬷. Theo bộ 女, đây là chữ chỉ người phụ nữ lớn tuổi hoặc người chăm sóc. Có thể là hình thanh với 女 biểu nghĩa. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ma\": người phụ nữ (女) gọi là \"ma\" — 嬷嬷 là cách gọi thân mật bà vú già, người chăm con. | Gương Hán-Việt | ma — không dùng trong tiếng Việt; 嬷嬷 là từ phương ngôn miền Bắc Trung Quốc. | Mở khoá kiến thức | Biết 嬷 giúp hiểu từ 嬷嬷 trong phim cổ trang Trung Quốc — người vú già, bảo mẫu trong cung đình.", "Tự nguyên_Xie": "嬷 (mā) là chữ thông tục dùng để chỉ mẹ đẻ, vú già hoặc người phụ nữ lớn tuổi chăm sóc con trẻ. Bộ 女 chỉ đây là người phụ nữ. Wiktionary không có mục từ này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mẹ đẻ; chỉ người phụ nữ đứng tuổi hoặc chị em của cha mẹ; vú già", "Hạng Tần Suất (Jun Da)": "4891.0", "Tần Suất % (Jun Da)": "99.9110540433", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 麽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女麽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嬷", "Unihan_Traditional (Chữ Phồn thể)": "嬤", "Pinyin_Xie": "mā", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ xưng hô trong gia đình hoặc chỉ người phụ nữ lớn tuổi làm việc hầu hạ ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肱', '{"9000": "4892.0", "Chữ Trung Quốc": "肱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | ⺼ | nhục | biểu nghĩa | thịt, thân thể | 厷 | hoành | biểu âm | 肱 = ⺼/肉 (Nhục, biểu nghĩa: thịt/thân thể) + 厷 (Hoành, biểu âm). Chữ hình thanh — ⺼ chỉ đây là bộ phận thân thể, 厷 vốn là chữ gốc. Wiktionary ghi 厷 là dạng gốc của 肱.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quăng\": cánh tay thịt (⺼) cứng chắc — \"quăng\" như cú ném mạnh từ cánh tay khỏe. | Gương Hán-Việt | quăng — ít dùng trong tiếng Việt; xuất hiện trong thành ngữ cổ \"cổ quăng\" (股肱: chân tay đắc lực của vua). | Mở khoá kiến thức | Biết 肱 mở khoá: 股肱 (cổ quăng: chân tay đắc lực), 曲肱而枕 (gối đầu lên cánh tay — an bần lạc đạo), 肱骨 (xương cánh tay).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 肱 là chữ hình thanh: 肉 (⺼, thịt/thân thể) biểu nghĩa, 厷 biểu âm — thực ra 厷 là dạng gốc của chữ này. Nghĩa là cánh tay trên (từ khuỷu tay đến vai). Tiểu triện đã có dạng này. Trong Luận Ngữ, Khổng Tử dùng \"曲肱\" (gối đầu lên cánh tay). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh tay", "Hạng Tần Suất (Jun Da)": "4892.0", "Tần Suất % (Jun Da)": "99.91115585", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 厷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月厷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肱", "Unihan_Traditional (Chữ Phồn thể)": "肱", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "quăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ bộ phận cơ thể hoặc người trợ thủ đắc lực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸢', '{"9000": "4893.0", "Chữ Trung Quốc": "鸢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 8 | nét | 鳥 | điểu | biểu nghĩa | chim | 戈 | qua | biểu âm | 鸢 (phồn thể 鳶) = 鳥 (Điểu, biểu nghĩa: chim) + 戈 (Qua, biểu âm). Wiktionary ghi \"có thể\" là hình thanh — 鳥 chỉ đây là loài chim, 戈 cho âm. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diên\": chim (鳥) cầm giáo (戈) trên trời — diều hâu bay lượn như mũi giáo xuyên gió. | Gương Hán-Việt | diên — ít dùng trong tiếng Việt; 鸢 xuất hiện trong thơ cổ và tên địa danh Ôn Châu (温州别称鸢都). | Mở khoá kiến thức | Biết 鸢 giúp nhận ra từ 纸鸢 (con diều giấy) và biệt danh thành phố Ôn Châu (鸢都).", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary (dạng phồn thể 鳶), có thể là chữ hình thanh: 鳥 (chim) biểu nghĩa, 戈 biểu âm. Đại triện đã có dạng này. Nghĩa là diều hâu (Milvus), loài chim săn mồi bay lượn cao. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim diều hâu", "Hạng Tần Suất (Jun Da)": "4893.0", "Tần Suất % (Jun Da)": "99.9112576567", "GavinGrover_Once (Chiết tự trực tiếp)": "弋 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱弋鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弋", "Unihan_Simplified (Chữ Giản thể)": "鸢", "Unihan_Traditional (Chữ Phồn thể)": "鳶", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học hoặc tên các loài chim, diều giấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笫', '{"9000": "4894.0", "Chữ Trung Quốc": "笫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 𥫗 | trúc | biểu nghĩa | tre, trúc | 𠂔 | biểu âm | 笫 = 𥫗/竹 (Trúc, biểu nghĩa: tre) + 𠂔 (biểu âm). Chữ hình thanh — 竹 chỉ đây là vật liệu làm từ tre, phần âm cho cách đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tử\": tre (竹) đan thành đệm nằm — 笫 là tấm phản tre trong phòng ngủ cổ đại. | Gương Hán-Việt | tử — hầu như không dùng trong tiếng Việt; xuất hiện trong từ cổ \"sàng tử\" (床笫: giường phản, chỗ ngủ riêng tư). | Mở khoá kiến thức | Biết 笫 mở khoá từ 床笫之私 (phòng the, chuyện riêng tư vợ chồng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 笫 là chữ hình thanh: 竹 (tre) biểu nghĩa, 𠂔 biểu âm. Nghĩa là tấm đệm làm từ nan tre mỏng, dùng lót giường. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đệm lót giường", "Hạng Tần Suất (Jun Da)": "4894.0", "Tần Suất % (Jun Da)": "99.9113594633", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "笫", "Unihan_Traditional (Chữ Phồn thể)": "笫", "Pinyin_Xie": "zǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ giường chiếu hoặc chuyện phòng the. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痤', '{"9000": "4895.0", "Chữ Trung Quốc": "痤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | nạch | biểu nghĩa | bệnh, đau | 坐 | tọa | biểu âm | 痤 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 坐 (Tọa, biểu âm). Chữ hình thanh — 疒 chỉ đây là bệnh ngoài da, 坐 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tọa\": bệnh (疒) ngồi (坐) trên mặt — 痤瘡 (mụn trứng cá) là \"bệnh ngồi lì\" trên da. | Gương Hán-Việt | toạ — ít dùng trong tiếng Việt; 痤瘡 là thuật ngữ y khoa cho mụn trứng cá. | Mở khoá kiến thức | Biết 痤 mở khoá thuật ngữ y khoa: 痤瘡 (toạ sang: mụn trứng cá/acne).", "Tự nguyên_Xie": "Tiểu triện | Chữ 痤 (cuó) có bộ 疒 (bệnh) biểu nghĩa, chỉ liên quan đến tình trạng da. Wiktionary chỉ ghi thông tin phát âm, không phân tích nguồn gốc. Tiểu triện đã có dạng này. Nghĩa hiện đại phổ biến là mụn trứng cá (痤瘡). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: toạ sang 痤瘡)", "Hạng Tần Suất (Jun Da)": "4895.0", "Tần Suất % (Jun Da)": "99.91146127", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痤", "Unihan_Traditional (Chữ Phồn thể)": "痤", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "toạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền và hiện đại để chỉ các loại mụn trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菏', '{"9000": "4896.0", "Chữ Trung Quốc": "菏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây | 河 | hà | biểu âm | sông | 菏 = 艸/艹 (Tháu, biểu nghĩa: thực vật) + 河 (Hà, biểu âm). Chữ hình thanh — 艹 chỉ liên quan đến thực vật/địa danh có cây cỏ, 河 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": cây cỏ (艹) ven sông (河) — sông Hà ở Sơn Đông, tên gọi 菏澤. | Gương Hán-Việt | hà — ít dùng trong tiếng Việt; chủ yếu trong địa danh 菏澤 (Hà Trạch/Heze). | Mở khoá kiến thức | Biết 菏 giúp nhận ra địa danh 菏澤 (Heze) — thành phố nổi tiếng với hoa mẫu đơn ở tỉnh Sơn Đông.", "Tự nguyên_Xie": "Theo Wiktionary, 菏 là chữ hình thanh: 艸 (cỏ/cây) biểu nghĩa, 河 biểu âm. Nghĩa là tên một con sông ở tỉnh Sơn Đông, Trung Quốc — nay là 菏澤 (Heze). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hà trạch 菏澤,菏泽)", "Hạng Tần Suất (Jun Da)": "4896.0", "Tần Suất % (Jun Da)": "99.9116643666", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 河", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹河", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "河", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菏", "Unihan_Traditional (Chữ Phồn thể)": "菏", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong địa danh như Hà Trạch ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莆', '{"9000": "4897.0", "Chữ Trung Quốc": "莆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莆 | bo | tượng hình | loại cây huyền thoại; cỏ phồ | 莆 có bộ 艹 (cỏ/cây) ở trên. Wiktionary không ghi cấu trúc hình thanh/hội ý. Theo bộ 艹, đây là chữ chỉ loại thực vật. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồ\": cây cỏ (艹) mọc ven nước — 莆 liên quan đến cỏ bồ và địa danh Phổ Điền/Hưng Hóa. | Gương Hán-Việt | bồ — xuất hiện trong 莆田 (Bồ Điền/Phổ Điền: tên địa danh ở Phúc Kiến). | Mở khoá kiến thức | Biết 莆 giúp nhận ra địa danh 莆田 (Putian/Phổ Điền) ở tỉnh Phúc Kiến — nổi tiếng đồ gỗ và đình chùa.", "Tự nguyên_Xie": "Tiểu triện | Chữ 莆 (pú) có hai nghĩa: dạng viết khác của 蒲 (cỏ bồ/phồ) và tên tắt của 莆田 (thành phố ở Phúc Kiến). Trong văn cổ, 萐莆 là tên loại cây huyền thoại. Tiểu triện đã có dạng này. Wiktionary không ghi nguồn gốc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiệp phủ 萐莆)", "Hạng Tần Suất (Jun Da)": "4897.0", "Tần Suất % (Jun Da)": "99.9117656565", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莆", "Unihan_Traditional (Chữ Phồn thể)": "莆", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "phủ, bồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng trong địa danh như Bồ Điền hoặc tên các loài cây cỏ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芨', '{"9000": "4898.0", "Chữ Trung Quốc": "芨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 芨 | cập | tượng hình | cây bạch cập (兰科) | 芨 có bộ 艹 (cỏ/cây) ở trên. Wiktionary không ghi cấu trúc chi tiết. Bộ 艹 chỉ đây là loại thực vật. Chưa có nguồn học thuật xác nhận cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấp\": cây cỏ (艹) dùng làm thuốc — 白芨 là loại lan cầm máu, cấp cứu kịp thời. | Gương Hán-Việt | cập — thuật ngữ thảo dược, không dùng trong tiếng Việt thông thường. | Mở khoá kiến thức | Biết 芨 giúp nhận ra tên thảo dược: 白芨 (bạch cập: củ lan đất dùng cầm máu trong đông y).", "Tự nguyên_Xie": "Tiểu triện | Chữ 芨 (jī/jí) xuất hiện trong tên hai loại cây thuốc: 白芨 (Bletilla striata — lan đất, dùng trong đông y cầm máu) và 芨芨草 (cỏ lông kiếm mọc ở đồng bằng kiềm). Bộ 艹 chỉ thực vật. Tiểu triện đã có dạng này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bạch cập 白芨)", "Hạng Tần Suất (Jun Da)": "4898.0", "Tần Suất % (Jun Da)": "99.9118669463", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芨", "Unihan_Traditional (Chữ Phồn thể)": "芨", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loại thảo dược như bạch cập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阕', '{"9000": "4899.0", "Chữ Trung Quốc": "阕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 12 | nét | 阕 | khuyết | tượng hình | kết thúc, đoạn thơ/nhạc | 阕 (phồn thể 闋) có bộ 門 (cổng) và các phần bên trong. Wiktionary ghi 阕 thường bị nhầm với 闕. Cấu trúc chi tiết không được phân tích. Bộ 門 gợi sự đóng lại, kết thúc. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuyết\": cổng (門) đóng lại — nhạc đã ngừng, bài ca kết thúc. Một \"khuyết\" là một khúc nhạc. | Gương Hán-Việt | khuyết — ít dùng trong tiếng Việt; 阕 là lượng từ dùng đếm bài thơ tứ, khúc nhạc cổ. | Mở khoá kiến thức | Biết 阕 giúp đọc thơ từ cổ điển: \"一阕\" (một khúc), \"服阕\" (hết tang — sau thời gian để tang).", "Tự nguyên_Xie": "Chữ 阕 (phồn thể 闋, que) nghĩa là chấm dứt, kết thúc; cũng dùng làm lượng từ đếm khúc nhạc, đoạn thơ. Bộ 門 gợi cánh cửa đóng lại. Wiktionary ghi cấu trúc không đủ để phân tích hình thanh/hội ý rõ ràng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hết, xong; đoạn, bài, khúc hát", "Hạng Tần Suất (Jun Da)": "4899.0", "Tần Suất % (Jun Da)": "99.9119682362", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阕", "Unihan_Traditional (Chữ Phồn thể)": "闋", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "khuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm lượng từ cho bài hát, bài từ hoặc động từ chỉ sự kết thúc. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砣', '{"9000": "4900.0", "Chữ Trung Quốc": "砣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砣 | đà | tượng hình | quả cân đá, con lăn đá | 砣 có bộ 石 (đá) ở trái. Wiktionary không có mục từ 砣. Theo bộ 石, đây là chữ chỉ vật bằng đá. Phần phải có thể biểu âm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": đá (石) nặng lăn đi — 砣 là quả cân hoặc đá lăn dùng để nghiền, ép. | Gương Hán-Việt | đà — hầu như không dùng trong tiếng Việt; 砣 là từ miêu tả dụng cụ nặng bằng đá. | Mở khoá kiến thức | Biết 砣 giúp nhận ra từ 秤砣 (quả cân của cân đĩa truyền thống Trung Quốc).", "Tự nguyên_Xie": "Chữ 砣 (tuó) mang nghĩa quả cân đá hoặc con lăn đá nặng. Bộ 石 (đá) biểu nghĩa. Wiktionary không có mục từ này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả cân; quả lăn", "Hạng Tần Suất (Jun Da)": "4900.0", "Tần Suất % (Jun Da)": "99.9120695261", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砣", "Unihan_Traditional (Chữ Phồn thể)": "砣", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ quả cân của cân tiểu ly hoặc vật nặng hình tròn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碜', '{"9000": "4901.0", "Chữ Trung Quốc": "碜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碜 | sẩm | tượng hình | lẫn cát, xấu xí | 碜 (phồn thể 磣) có bộ 石 (đá) ở trái, gợi ý liên quan đến đất cát. Wiktionary không ghi cấu trúc hình thanh/hội ý rõ ràng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thảm\": đá (石) lẫn trong cơm — ăn phải sạn, xấu hổ, \"sẩm\" mặt. | Gương Hán-Việt | sẩm — không dùng trong tiếng Việt; 碜 là từ phương ngôn miền Bắc Trung Quốc chỉ sự xấu xí, bẽ mặt. | Mở khoá kiến thức | Biết 碜 giúp hiểu từ khẩu ngữ miền Bắc: 寒磣 (hàn sẩm: xấu xí, kém cỏi), 可磣 (khả sẩm: đáng xấu hổ).", "Tự nguyên_Xie": "Chữ 碜 (phồn thể 磣, chěn) nghĩa là thức ăn lẫn cát sạn, xấu xí, bẽ mặt. Bộ 石 gợi đất cát, sạn. Wiktionary chỉ ghi thông tin phát âm và nghĩa, không phân tích nguồn gốc. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xấu xí, bẽ mặt, khó coi", "Hạng Tần Suất (Jun Da)": "4901.0", "Tần Suất % (Jun Da)": "99.912170816", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碜", "Unihan_Traditional (Chữ Phồn thể)": "磣", "Pinyin_Xie": "chěn", "Âm Hán Việt_Xie": "sầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả cảm giác ghê răng do sạn hoặc sự xấu xí, khó coi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼹', '{"9000": "4902.0", "Chữ Trung Quốc": "鼹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 23 | nét | 鼠 | thử | biểu nghĩa | chuột | 晏 | yến | biểu âm | 鼹 = 鼠 (Thử, biểu nghĩa: chuột) + 晏 (Yến, biểu âm). Chữ hình thanh — 鼠 chỉ đây là loài gặm nhấm, 晏 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yển\": chuột (鼠) yên (晏) trong đất — chuột chũi sống âm thầm dưới đất, không muốn bị nhìn thấy. | Gương Hán-Việt | yến — ít dùng trong tiếng Việt; 鼹鼠 là từ chỉ con chuột chũi. | Mở khoá kiến thức | Biết 鼹 giúp nhận ra 鼹鼠 (chuột chũi) — xuất hiện trong dụ ngôn cổ điển Trang Tử về giới hạn ham muốn.", "Tự nguyên_Xie": "Theo Wiktionary, 鼹 là chữ hình thanh: 鼠 (chuột) biểu nghĩa, 晏 biểu âm. Nghĩa là chuột chũi — loài gặm nhấm đào hang dưới đất. Không có hình ảnh etymology. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuột đồng", "Hạng Tần Suất (Jun Da)": "4902.0", "Tần Suất % (Jun Da)": "99.9122721059", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 晏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠晏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼹", "Unihan_Traditional (Chữ Phồn thể)": "鼴", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong tên gọi các loài động vật gặm nhấm sống dưới đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猷', '{"9000": "4903.0", "Chữ Trung Quốc": "猷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 13 | nét | 猷 | du | tượng hình | mưu kế, đạo nghĩa | 猷 có bộ 犬 (chó) và phần trên. Wiktionary không ghi cấu trúc hình thanh/hội ý cụ thể. Bộ 犬 có thể liên quan đến hành động, mưu trí. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": mưu kế như con chó (犬) khôn ngoan — 猷 là sách lược của người lãnh đạo. | Gương Hán-Việt | du — ít dùng trong tiếng Việt; xuất hiện trong văn cổ với nghĩa kế sách vĩ đại: 鴻猷 (hồng du: kế sách lớn). | Mở khoá kiến thức | Biết 猷 giúp đọc văn cổ: 大猷 (đại du: mưu lược lớn), 深謀遠猷 (sâu mưu xa kế).", "Tự nguyên_Xie": "Lục thư thông | Chữ 猷 (yóu) mang nghĩa mưu kế, kế hoạch, con đường. Có hình ảnh Lục thư thông. Wiktionary không phân tích cấu trúc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưu kế; đạo; vẽ", "Hạng Tần Suất (Jun Da)": "4903.0", "Tần Suất % (Jun Da)": "99.9124741689", "GavinGrover_Once (Chiết tự trực tiếp)": "酋 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酋犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犬", "Unihan_Simplified (Chữ Giản thể)": "猷", "Unihan_Traditional (Chữ Phồn thể)": "猷", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong văn viết cổ để chỉ mưu lược hoặc kế sách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竽', '{"9000": "4904.0", "Chữ Trung Quốc": "竽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 9 | nét | 竽 | vu | tượng hình | nhạc cụ hơi cổ đại (loại kèn lau) | 竽 có bộ 竹 (trúc: tre) ở trên — chỉ đây là nhạc cụ làm bằng tre. Wiktionary không ghi cấu trúc hình thanh/hội ý. Theo bộ 竹, đây là chữ tượng hình hay hình thanh với 竹 biểu nghĩa. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": nhạc cụ tre (竹) thổi lên — 濫竽充數: thổi vu mà không biết thổi, chen vào chỗ không xứng. | Gương Hán-Việt | vu — ít dùng trong tiếng Việt; xuất hiện trong thành ngữ 濫竽充數 (lạm vu sung số). | Mở khoá kiến thức | Biết 竽 mở khoá thành ngữ 濫竽充數 (lạm vu sung số: kẻ bất tài chen vào hàng có tài — điển tích từ Hàn Phi Tử).", "Tự nguyên_Xie": "Tiểu triện | Chữ 竽 (yú) chỉ loại nhạc cụ hơi cổ đại của Trung Quốc — bộ 竹 (tre) cho biết làm từ ống tre. Tiểu triện đã có dạng này. Wiktionary không ghi cấu trúc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vu (một loại nhạc cụ)", "Hạng Tần Suất (Jun Da)": "4904.0", "Tần Suất % (Jun Da)": "99.912574942", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "竽", "Unihan_Traditional (Chữ Phồn thể)": "竽", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại nhạc cụ thổi làm bằng ống tre thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舸', '{"9000": "4905.0", "Chữ Trung Quốc": "舸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舸 | kha | tượng hình | thuyền lớn | 舸 có bộ 舟 (thuyền) ở trái. Wiktionary không có mục từ 舸. Theo bộ 舟, đây là chữ chỉ loại thuyền. Phần phải có thể biểu âm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": thuyền (舟) lớn — 舸 là thuyền mành to đi biển, mạnh mẽ như tên \"kha\". | Gương Hán-Việt | kha — hầu như không dùng trong tiếng Việt; 舸 xuất hiện trong thơ cổ miêu tả thuyền bè. | Mở khoá kiến thức | Biết 舸 giúp đọc thơ cổ điển miêu tả cảnh sông nước: 百舸爭流 (trăm thuyền đua lướt — Mao Trạch Đông).", "Tự nguyên_Xie": "Tiểu triện | Chữ 舸 (gě) mang nghĩa thuyền lớn, bè to. Bộ 舟 (thuyền) biểu nghĩa. Tiểu triện đã có dạng này. Wiktionary không có mục từ này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền mành, thuyền to", "Hạng Tần Suất (Jun Da)": "4905.0", "Tần Suất % (Jun Da)": "99.9126757151", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舸", "Unihan_Traditional (Chữ Phồn thể)": "舸", "Pinyin_Xie": "gě", "Âm Hán Việt_Xie": "khả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn thơ để chỉ các loại thuyền lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诓', '{"9000": "4906.0", "Chữ Trung Quốc": "诓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诓 | khuông | tượng hình | lừa dối, nói dối | 诓 (phồn thể 誆) = 讠/訁 (ngôn: lời nói) + 匡 (biểu âm). Wiktionary ghi đây là chữ giản hoá của 誆. Chữ hình thanh — 言/讠 chỉ đây là lời nói dối, 匡 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuông\": lời nói (讠) che \"khuông\" thật — 诓 là nói dối, lừa gạt người khác. | Gương Hán-Việt | khuông — không dùng trong tiếng Việt; 诓 là từ thông tục tiếng Trung chỉ hành vi lừa gạt. | Mở khoá kiến thức | Biết 诓 giúp hiểu khẩu ngữ tiếng Trung: 诓人 (lừa người), 诓骗 (lừa bịp).", "Tự nguyên_Xie": "诓 là chữ giản thể của 誆. Wiktionary ghi {{Han simp}} — chữ gốc 誆 dùng 訁 (ngôn), nay viết giản thành 讠. Nghĩa là lừa dối bằng lời nói. Không có phân tích nguồn gốc xa hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói dối, lừa dối", "Hạng Tần Suất (Jun Da)": "4906.0", "Tần Suất % (Jun Da)": "99.9127759714", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 匡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠匡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诓", "Unihan_Traditional (Chữ Phồn thể)": "誆", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "cuống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ đứng trước tân ngữ để chỉ hành vi lừa gạt ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錾', '{"9000": "4907.0", "Chữ Trung Quốc": "錾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錾 | tạm | tượng hình | đục chạm kim loại | 錾 (phồn thể 鏨) có bộ 金 (kim loại) và phần biểu âm. Wiktionary chỉ ghi thông tin phát âm và nghĩa, không phân tích cấu trúc. Theo bộ 金, đây là dụng cụ kim loại. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tàm\": kim loại (金) dùng để khắc — 錾 là mũi đục chạm khắc, \"tạm\" thời ép vào bề mặt. | Gương Hán-Việt | tạm — không dùng trong tiếng Việt; thuật ngữ thủ công mỹ nghệ kim hoàn. | Mở khoá kiến thức | Biết 錾 giúp đọc từ vựng kim hoàn thủ công: 錾刀 (dao đục), 錾子 (mũi đục), 錾花 (khắc hoa văn).", "Tự nguyên_Xie": "Tiểu triện | Chữ 錾 (phồn thể 鏨, zàn) nghĩa là cái đục, dao chạm — dụng cụ khắc trên đá hoặc kim loại; cũng là động từ \"khắc, chạm\". Tiểu triện đã có dạng này. Wiktionary không phân tích nguồn gốc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khắc; chạm (trên đá hoặc vàng bạc); cái đục; dao chạm", "Hạng Tần Suất (Jun Da)": "4907.0", "Tần Suất % (Jun Da)": "99.9128762277", "GavinGrover_Once (Chiết tự trực tiếp)": "斩 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱斩金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錾", "Unihan_Traditional (Chữ Phồn thể)": "鏨", "Pinyin_Xie": "zàn", "Âm Hán Việt_Xie": "tạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ dụng cụ đục hoặc làm động từ chỉ hành động chạm khắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淬', '{"9000": "4908.0", "Chữ Trung Quốc": "淬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thủy | biểu nghĩa | nước | 卒 | tốt | biểu âm | 淬 = 氵/水 (Thủy, biểu nghĩa: nước) + 卒 (Tốt, biểu âm). Chữ hình thanh — 水 chỉ hành động nhúng vào chất lỏng, 卒 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rót\": nước (氵) rót vào thép nóng — 淬火 (tôi luyện) là kỹ thuật làm cứng thép bằng cách nhúng vào nước. | Gương Hán-Việt | rót — ít dùng trong tiếng Việt; 淬 là thuật ngữ luyện kim và ẩn dụ về rèn luyện bản thân. | Mở khoá kiến thức | Biết 淬 mở khoá: 淬火 (tôi luyện thép), 淬礪 (mài giũa, rèn luyện), 淬鍊 (tôi luyện — cả nghĩa đen và bóng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 淬 là chữ hình thanh: 水 (氵, nước) biểu nghĩa, 卒 biểu âm. Nghĩa gốc là tôi thép — nhúng kim loại nung đỏ vào nước/dầu để làm cứng. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhúng vào nước; nhuộm; phạm", "Hạng Tần Suất (Jun Da)": "4908.0", "Tần Suất % (Jun Da)": "99.9129759672", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淬", "Unihan_Traditional (Chữ Phồn thể)": "淬", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "thối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ việc nhúng kim loại nóng vào nước để tôi luyện. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隗', '{"9000": "4909.0", "Chữ Trung Quốc": "隗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 阝 | phụ | biểu nghĩa | gò đất, núi nhỏ | 鬼 | quỷ | biểu âm | 隗 = 阝/阜 (Phụ, biểu nghĩa: gò đất/núi) + 鬼 (Quỷ, biểu âm). Chữ hình thanh — 阜 chỉ liên quan đến địa hình, 鬼 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngỗi\": gò đất (阝) cao như quỷ (鬼) — 隗 là núi cao lồng lộng, cũng là họ nổi tiếng trong sử Trung Quốc. | Gương Hán-Việt | ngỗi — hầu như không dùng trong tiếng Việt; 隗 chủ yếu là họ người (Ngỗi Kiến 隗囂, Trần Ân 隗嚣). | Mở khoá kiến thức | Biết 隗 giúp nhận ra họ Ngỗi trong lịch sử Trung Quốc, đặc biệt giai đoạn Đông Hán.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 隗 là chữ hình thanh: 阜 (阝, gò đất) biểu nghĩa, 鬼 biểu âm. Nghĩa là cao lớn, vời vợi; cũng là họ người (họ Ngỗi). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Ngỗi", "Hạng Tần Suất (Jun Da)": "4909.0", "Tần Suất % (Jun Da)": "99.9130757068", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隗", "Unihan_Traditional (Chữ Phồn thể)": "隗", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "ngôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng chỉ họ người hoặc làm tính từ tả dáng núi cao dốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悌', '{"9000": "4910.0", "Chữ Trung Quốc": "悌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 忄 | tâm | biểu nghĩa | tâm, lòng | 弟 | đệ | biểu âm | em trai | 悌 = 忄/心 (Tâm, biểu nghĩa: lòng, tâm) + 弟 (Đệ, biểu âm). Chữ hình thanh — 心 chỉ đây là đức tính, tình cảm, 弟 cho âm đọc. Trong kinh điển trước Tần, thường viết là 弟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đễ\": lòng (忄) kính yêu anh như em (弟) — đễ là đức hạnh kính trọng anh chị, cùng hiếu thành 孝悌. | Gương Hán-Việt | đễ — xuất hiện trong \"hiếu đễ\" (孝悌: hiếu thuận cha mẹ và kính yêu anh chị) — đức hạnh căn bản Nho giáo. | Mở khoá kiến thức | Biết 悌 mở khoá: 孝悌 (hiếu đễ: đức tính căn bản), 愷悌 (khải đễ: khoan hòa nhân từ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 悌 là chữ hình thanh: 心 (忄, tâm) biểu nghĩa, 弟 biểu âm. Trong kinh điển trước Tần thường viết là 弟. Nghĩa là kính yêu anh, thuận hòa với anh em — một trong những đức tính Nho giáo (孝悌: hiếu đễ). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuận theo", "Hạng Tần Suất (Jun Da)": "4910.0", "Tần Suất % (Jun Da)": "99.9131754463", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悌", "Unihan_Traditional (Chữ Phồn thể)": "悌", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "đễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ hoặc danh từ chỉ đức tính kính nhường anh chị trong gia đình. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姘', '{"9000": "4911.0", "Chữ Trung Quốc": "姘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 9 | nét | 姘 | bình | tượng hình | quan hệ ngoài hôn nhân | 姘 có bộ 女 (phụ nữ) ở trái. Wiktionary không ghi cấu trúc hình thanh/hội ý chi tiết. Theo bộ 女 và âm đọc, có thể là hình thanh. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": người phụ nữ (女) ghép lại không chính danh — 姘居 là sống chung ngoài giá thú. | Gương Hán-Việt | bình — không dùng trong tiếng Việt; 姘 là từ thông tục chỉ quan hệ ngoài hôn nhân ở Thượng Hải. | Mở khoá kiến thức | Biết 姘 giúp hiểu từ vựng thông tục: 姘頭 (người tình ngoài giá thú), 姘居 (sống chung không cưới).", "Tự nguyên_Xie": "Tiểu triện | Chữ 姘 (pīn) mang nghĩa quan hệ nam nữ ngoài hôn nhân, ngoại tình. Bộ 女 chỉ liên quan đến người phụ nữ. Tiểu triện đã có dạng này. Wiktionary không phân tích nguồn gốc chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trai gái dan díu với nhau", "Hạng Tần Suất (Jun Da)": "4911.0", "Tần Suất % (Jun Da)": "99.9132751858", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姘", "Unihan_Traditional (Chữ Phồn thể)": "姘", "Pinyin_Xie": "pīn", "Âm Hán Việt_Xie": "phanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ để chỉ việc nam nữ chung sống không hợp pháp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槭', '{"9000": "4912.0", "Chữ Trung Quốc": "槭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây | 戚 | thích | biểu âm | 槭 = 木 (Mộc, biểu nghĩa: cây) + 戚 (Thích, biểu âm); chữ hình thanh — bộ Mộc chỉ loài cây, 戚 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thích\" (cây phong): bộ Mộc (木) + Thích (戚, biểu âm) — cây 木 mang theo chiếc rìu 戚, lá phong sắc đỏ như lưỡi dao mùa thu. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 槭 giúp nhận ra từ 槭树 (cây phong) trong văn học và địa danh Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 木 (mộc) chỉ loại cây, thành phần 戚 cho âm. Tiểu triện còn lưu lại dạng chữ này. 槭 chỉ cây phong (maple), nổi tiếng với lá đỏ mùa thu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây túc", "Hạng Tần Suất (Jun Da)": "4912.0", "Tần Suất % (Jun Da)": "99.9133749254", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 戚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木戚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槭", "Unihan_Traditional (Chữ Phồn thể)": "槭", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "sắc, túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loại cây phong trong thực vật học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邈', '{"9000": "4913.0", "Chữ Trung Quốc": "邈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 17 | nét | 辶 | sước | biểu nghĩa | đi, chuyển động | 貌 | mạo | biểu âm | diện mạo | 邈 = 辶 (Sước, biểu nghĩa: chuyển động, đi xa) + 貌 (Mạo, biểu âm); chữ hình thanh — bộ Sước gợi ý nghĩa xa xôi, 貌 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miểu\" (xa vời): bộ đường 辶 kết hợp gương mặt 貌 — gặp ai đó từ xa chỉ thấy diện mạo mờ nhạt. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 邈 giúp đọc các từ cổ điển như 邈若山河 (xa như núi sông), 渺邈 (xa xôi mơ hồ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 辵 (sước, viết tắt 辶) nghĩa là đi chuyển, 貌 (mạo) cho âm. Tiểu triện ghi nhận dạng này. 邈 mang nghĩa xa vời, cách biệt — như hành trình không dứt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa tít, xa vời", "Hạng Tần Suất (Jun Da)": "4913.0", "Tần Suất % (Jun Da)": "99.9134746649", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 貌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶貌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "邈", "Unihan_Traditional (Chữ Phồn thể)": "邈", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "mạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng trước danh từ hoặc sau động từ để tả không gian xa xăm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婕', '{"9000": "4914.0", "Chữ Trung Quốc": "婕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 疌 | tiệp | biểu âm | 婕 = 女 (Nữ, biểu nghĩa: phụ nữ) + 疌 (Tiệp, biểu âm); chữ hình thanh — bộ Nữ chỉ đây là chữ liên quan đến phụ nữ, 疌 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiệp\" (trong 婕妤): bộ Nữ + thành phần nhanh nhẹn 疌 — người cung nữ tài sắc lanh lợi trong cung đình nhà Hán. | Gương Hán-Việt | Tiệp — dùng trong \"tiệp dư\" (婕妤), danh hiệu cung phi thời Hán. | Mở khoá kiến thức | Biết 婕 giúp đọc sử Trung Hoa: 婕妤 là tước vị phi tần, 班婕妤 là nữ thi sĩ nổi tiếng triều Hán.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 女 (nữ) chỉ phụ nữ, 疌 (tiệp) cho âm đọc. Tiểu triện còn lưu. 婕 dùng hầu như chỉ trong danh hiệu 婕妤 (tiệp dư) — một trong những danh hiệu phi tần thời Hán. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiệp dư 婕妤)", "Hạng Tần Suất (Jun Da)": "4914.0", "Tần Suất % (Jun Da)": "99.9135744044", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 疌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女疌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婕", "Unihan_Traditional (Chữ Phồn thể)": "婕", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ trong từ ghép chỉ chức vị cung nữ hoặc làm tính từ chỉ vẻ đẹp của phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歙', '{"9000": "4915.0", "Chữ Trung Quốc": "歙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 16 | nét | 歙 | hấp | tượng hình | miệng há ra hít vào | 歙 là chữ tự thân, cấu tạo phức tạp — bộ Khiếm (欠, há miệng thở) kết hợp với các thành phần khác. Wiktionary không cung cấp phân tích hình thanh/hội ý rõ ràng cho chữ này; chữ tạo muộn, chưa thấy trong giáp cốt văn cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hấp\" (hít vào): chữ có bộ Khiếm (欠) — miệng há — gợi hình ảnh hít vào một hơi dài. | Gương Hán-Việt | Hấp — dùng trong \"hấp thụ\" nghĩa là hút vào, tiếp nhận. | Mở khoá kiến thức | Biết 歙 giúp nhận ra địa danh 歙县 (huyện Hấp, An Huy) và 徽歙 trong nghiên cứu lịch sử thư pháp Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Anchor Wiktionary chỉ ghi {{Han etym}} không có phân tích cấu trúc. Tiểu triện và Lục thư thông còn lưu dạng chữ. 歙 mang nghĩa hít vào, hút vào; cũng là tên huyện Hấp ở tỉnh An Huy (Trung Quốc). Chưa có nguồn học thuật phân tích rõ cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hấp thụ; hút vào", "Hạng Tần Suất (Jun Da)": "4915.0", "Tần Suất % (Jun Da)": "99.9136736272", "GavinGrover_Once (Chiết tự trực tiếp)": "翕 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰翕欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "歙", "Unihan_Traditional (Chữ Phồn thể)": "歙", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "hấp, thiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động thu hẹp, khép lại hoặc hút khí vào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稹', '{"9000": "4916.0", "Chữ Trung Quốc": "稹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 稹 | chẩn | tượng hình | cây cỏ mọc dày đặc | 稹 có bộ Hòa (禾, lúa, cây cỏ) nhưng cấu trúc chi tiết không được Wiktionary phân tích rõ. Có thể liên quan đến 縝 (chẩn, dày mịn). Chữ tạo muộn, chưa có phân tích hình thanh/hội ý đầy đủ từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\" (cây cỏ um tùm): bộ Hòa (禾) gợi bụi cây — hình dung những bụi lúa, cỏ mọc chen chúc dày đặc. | Gương Hán-Việt | Chẩn — ít dùng trong tiếng Việt hiện đại; thấy trong tên thi nhân Nguyên Chẩn (元稹) đời Đường. | Mở khoá kiến thức | Biết 稹 giúp nhận ra tên nhà thơ 元稹 (Nguyên Chẩn) — bạn thơ của Bạch Cư Dị, tác giả truyện 莺莺传.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không có phân tích cấu trúc. 稹 mang nghĩa thực vật mọc dày, um tùm; cũng là dạng thay thế của 縝 (dày mịn). Bộ 禾 (hòa) gợi liên hệ thực vật. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cỏ mọc thành bụi", "Hạng Tần Suất (Jun Da)": "4916.0", "Tần Suất % (Jun Da)": "99.9137728499", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稹", "Unihan_Traditional (Chữ Phồn thể)": "稹", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái cây cối mọc dày đặc, xum xuê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹴', '{"9000": "4917.0", "Chữ Trung Quốc": "蹴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 足 | túc | biểu nghĩa | bàn chân | 就 | tựu | biểu âm | 蹴 = 足 (Túc, biểu nghĩa: bàn chân) + 就 (Tựu, biểu âm); chữ hình thanh — bộ Túc chỉ hành động của chân, 就 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\" (chân đá): bộ Túc (足) + 就 (tựu, đến nơi) — một cái đá chân là đến đích ngay, như 一蹴而就. | Gương Hán-Việt | Túc — ít thấy độc lập; dùng trong 蹴鞠 (túc cúc) và thành ngữ 一蹴而就. | Mở khoá kiến thức | Biết 蹴 giúp đọc thành ngữ 一蹴而就 (nhất túc nhi tựu: một bước là xong) và 蹴鞠 (túc cúc: đá bóng thời xưa).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: bộ 足 (túc, bàn chân) chỉ hành động dùng chân, 就 (tựu) cho âm. Đại triện và Tiểu triện còn lưu. 蹴 mang nghĩa đá, giẫm đạp — dùng trong 蹴鞠 (đá cầu, môn thể thao cổ đại tiền thân bóng đá) và thành ngữ 一蹴而就 (một bước là xong). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bước xéo gót, rảo bước; đá lật đi; vẻ kính cần", "Hạng Tần Suất (Jun Da)": "4917.0", "Tần Suất % (Jun Da)": "99.9138720727", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 就", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊就", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "就", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹴", "Unihan_Traditional (Chữ Phồn thể)": "蹴", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "xúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dùng chân đá hoặc giẫm đạp lên vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砒', '{"9000": "4918.0", "Chữ Trung Quốc": "砒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 石 | thạch | biểu nghĩa | đá, khoáng chất | 比 | tỷ | biểu âm | 砒 = 石 (Thạch, biểu nghĩa: đá, khoáng chất) + 比 (Tỷ, biểu âm); chữ hình thanh — bộ Thạch chỉ nguồn gốc khoáng chất, 比 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\" (thạch tín): bộ Thạch (石) so sánh (比) — khoáng 砒霜 trắng như đá nhưng cực độc, phi thường nguy hiểm. | Gương Hán-Việt | Không có âm Hán-Việt thông dụng riêng; nhận qua từ 砒霜 (thạch tín). | Mở khoá kiến thức | Biết 砒 giúp nhận ngay từ 砒霜 (thạch tín, asen trioxid) trong y học cổ truyền và văn học trinh thám Trung Hoa.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 石 (thạch, đá) chỉ đây là chất khoáng, 比 (tỷ) cho âm. 砒 chỉ asen (arsenic), thường gặp trong 砒霜 (thạch tín — oxit asen trắng, chất độc nổi tiếng trong lịch sử). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "A-sen (arsenicum, kí hiệu: AS); thạch tín; nhân ngôn", "Hạng Tần Suất (Jun Da)": "4918.0", "Tần Suất % (Jun Da)": "99.9139707786", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砒", "Unihan_Traditional (Chữ Phồn thể)": "砒", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ chất độc hóa học hoặc khoáng vật độc hại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痈', '{"9000": "4919.0", "Chữ Trung Quốc": "痈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 痈 | ung | tượng hình | nhọt sưng viêm | 痈 là dạng giản thể của 癰 (ung — nhọt, áp-xe). Dạng gốc 癰 = 疒 (bệnh) + 雝 (ung, biểu âm). Giản thể thay 雝 bằng 用 (dụng) để đơn giản hóa tự dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ung\" (nhọt, áp-xe): bộ bệnh 疒 + dùng 用 — \"dùng\" (利用) bộ bệnh để chỉ nhọt sưng cần điều trị. | Gương Hán-Việt | Ung — dùng trong \"ung nhọt\" (nhọt sưng), \"ung thư\" có gốc nghĩa từ đây. | Mở khoá kiến thức | Biết 痈 giúp đọc thuật ngữ y học cổ truyền: 痈肿 (ung thũng — sưng mưng mủ), 内痈 (nội ung — áp-xe nội tạng).", "Tự nguyên_Xie": "Tiểu triện | 痈 là dạng giản thể của 癰. Chữ gốc 癰 = bộ 疒 (bệnh) + 雝 (ung) cho âm. Giản thể hóa: 雝 → 用. Tiểu triện còn lưu dạng gốc. 痈 chỉ nhọt sưng viêm, áp-xe — loại tổn thương da do vi khuẩn gây ra, có mủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ung, nhọt sưng đỏ", "Hạng Tần Suất (Jun Da)": "4919.0", "Tần Suất % (Jun Da)": "99.9140694846", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 用", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒用", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "用", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痈", "Unihan_Traditional (Chữ Phồn thể)": "癰", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại mụn nhọt độc, sưng tấy trên cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镏', '{"9000": "4920.0", "Chữ Trung Quốc": "镏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | kim loại | 留 | lưu | biểu âm | 镏 = 金 (Kim, biểu nghĩa: kim loại) + 留 (Lưu, biểu âm); chữ hình thanh — bộ Kim chỉ đây là vật phẩm kim loại, 留 cho âm đọc gần với 镏 (liú).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\" (chiếc nhẫn ở lại): bộ Kim (金) + Lưu (留, ở lại) — chiếc nhẫn vàng lưu mãi trên ngón tay. | Gương Hán-Việt | Lưu — thấy trong 镏金 (lưu kim: mạ vàng) và tên nguyên tố hóa học lutetium. | Mở khoá kiến thức | Biết 镏 giúp đọc 镏金 (mạ vàng, lưu kim) và thuật ngữ hóa học 镥 (lutetium, Lu).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh, dạng gốc là 鎦: bộ 金 (kim, kim loại) + 留 (lưu) cho âm. Tiểu triện còn lưu dạng phồn thể 鎦. 镏 mang nghĩa nồi cổ, nhẫn vàng, cũng dùng để chỉ nguyên tố lutetium (Lu) trong hóa học hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại nồi thời xưa; chiếc nhẫn", "Hạng Tần Suất (Jun Da)": "4920.0", "Tần Suất % (Jun Da)": "99.9141681906", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镏", "Unihan_Traditional (Chữ Phồn thể)": "鎦", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu, lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ khi chỉ việc mạ vàng hoặc làm danh từ chỉ chiếc nhẫn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羯', '{"9000": "4921.0", "Chữ Trung Quốc": "羯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 15 | nét | 羊 | dương | biểu nghĩa | dê, cừu | 曷 | hạt | biểu âm | 羯 = 羊 (Dương, biểu nghĩa: dê/cừu) + 曷 (Hạt, biểu âm); chữ hình thanh — bộ Dương chỉ đây liên quan đến loài dê/cừu, 曷 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiết\" (dê thiến): bộ Dương (羊) + Hạt (曷, hỏi) — người ta hỏi: \"con dê đực đã thiến này đâu?\" — đó là 羯. | Gương Hán-Việt | Kiết/Yết — dùng trong 羯鼓 (kiết cổ: loại trống) và 羯族 (tộc Yết trong lịch sử). | Mở khoá kiến thức | Biết 羯 giúp đọc sử Ngũ Hồ loạn Hoa: 羯族 (tộc Yết) lập nước Hậu Triệu, và nhạc khí 羯鼓.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 羊 (dương, dê/cừu) chỉ loài vật, 曷 (hạt) cho âm. Tiểu triện còn lưu. 羯 mang hai nghĩa: (1) con dê đực đã thiến; (2) tộc Yết (Jié) — một trong Ngũ Hồ xâm nhập Trung Nguyên thời loạn thế. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con dê đã thiến; người Yết", "Hạng Tần Suất (Jun Da)": "4921.0", "Tần Suất % (Jun Da)": "99.9142668965", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羯", "Unihan_Traditional (Chữ Phồn thể)": "羯", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "yết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài dê đã thiến hoặc một dân tộc thiểu số thời cổ đại ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豕', '{"9000": "4922.0", "Chữ Trung Quốc": "豕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 7 | nét | 豕 | thỉ | tượng hình | con lợn | 豕 là chữ tượng hình độc lập — hình vẽ con lợn (heo) trên giáp cốt văn, mô tả cơ thể, bốn chân và đuôi con lợn. Là bộ thủ Khang Hy số 152.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỉ\" (con lợn): nhìn vào chữ 豕 — thấy hình con lợn đứng ngang, bốn chân và cái đuôi cong ở phía sau. | Gương Hán-Việt | Thỉ — dùng trong \"thỉ giải\" (豕解: phân tích sai, lầm lợn thành heo rừng), và nhiều chữ ghép như 豪 (hào), 豚 (đồn). | Mở khoá kiến thức | Biết 豕 (thỉ) mở khoá hàng chục chữ có bộ Thỉ: 豪 (hào), 豚 (đồn), 象 (tượng), 家 (gia — nhà có lợn dưới mái).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Chữ tượng hình: trên giáp cốt văn và kim văn, 豕 vẽ hình con lợn với thân mình, bốn chân và đuôi cụp. Liên quan đến 亥 (hợi — lợn trong 12 địa chi), 𢑓 (lợn đực), và 豖 (lợn thiến). Giáp cốt văn còn lưu rõ hình vẽ con lợn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "72.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình con lợn được vẽ đứng.", "Nghĩa Tiếng Việt_Xie": "con lợn, con heo", "Hạng Tần Suất (Jun Da)": "4922.0", "Tần Suất % (Jun Da)": "99.9143656025", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + 𧰨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一𧰨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𧰨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "豕", "Unihan_Traditional (Chữ Phồn thể)": "豕", "Pinyin_Xie": "shǐ", "Âm Hán Việt_Xie": "thỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con lợn, thường dùng trong văn viết cổ hoặc làm bộ thủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲂', '{"9000": "4923.0", "Chữ Trung Quốc": "鲂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 12 | nét | 鲂 | phòng | tượng hình | cá mè | 鲂 là dạng giản thể của 魴 (phòng — cá mè). Chữ gốc 魴 = 魚 (ngư, cá) + 方 (phương, biểu âm); chữ hình thanh. Giản thể thay 魚 bằng 鱼.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phòng\" (cá mè): cá 鱼 + phương 方 — cá mè có thân hình vuông vắn (方, phương), bơi thành đàn theo khuôn khổ. | Gương Hán-Việt | Phòng — ít dùng độc lập; thấy trong kinh thi 衡门之下，可以栖迟，泌之洋洋，可以乐饥。岂其食鱼，必河之鲂. | Mở khoá kiến thức | Biết 鲂 giúp đọc Kinh Thi và tên món ăn Trung Hoa: 鲂鱼 (cá mè) xuất hiện trong nhiều bài thơ cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鲂 là giản thể của 魴. Chữ gốc 魴 = bộ 魚 (ngư, cá) + 方 (phương) cho âm. Tiểu triện còn lưu dạng phồn thể. 鲂 (魴) chỉ cá mè (bream) — loài cá nước ngọt phổ biến trong kinh thi và ẩm thực Trung Hoa cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá mè", "Hạng Tần Suất (Jun Da)": "4923.0", "Tần Suất % (Jun Da)": "99.9144643084", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 方", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲂", "Unihan_Traditional (Chữ Phồn thể)": "魴", "Pinyin_Xie": "fáng", "Âm Hán Việt_Xie": "phường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nước ngọt tương tự cá mè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓖', '{"9000": "4924.0", "Chữ Trung Quốc": "蓖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓖 | tỳ | tượng hình | cây thầu dầu | 蓖 có bộ Thảo (艹, cỏ cây) ở trên và 篦 (bí, lược dày) ở dưới — nhưng cấu trúc chi tiết không được Wiktionary phân tích. Chữ dùng hầu như chỉ trong 蓖麻 (cây thầu dầu). Chưa có nguồn học thuật phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\" (cây thầu dầu): bộ Thảo (艹) + hình chiếc lược bí (篦) — lá thầu dầu xẻ thùy như răng lược. | Gương Hán-Việt | Tỳ ma — dùng trong \"tỳ ma\" (蓖麻: cây thầu dầu). | Mở khoá kiến thức | Biết 蓖 giúp nhận ngay từ 蓖麻 (thầu dầu), 蓖麻油 (dầu thầu dầu), 蓖麻毒素 (ricin — chất độc từ hạt).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} không phân tích cấu trúc rõ. Bộ Thảo (艹) gợi đây là loài cây. 蓖 dùng chủ yếu trong 蓖麻 (thầu dầu, Ricinus communis) — cây cho dầu thầu dầu, hạt chứa ricin cực độc. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tỳ ma 蓖麻)", "Hạng Tần Suất (Jun Da)": "4924.0", "Tần Suất % (Jun Da)": "99.9145624976", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蓖", "Unihan_Traditional (Chữ Phồn thể)": "蓖", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, hầu như chỉ dùng trong từ ghép để chỉ cây thầu dầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匦', '{"9000": "4925.0", "Chữ Trung Quốc": "匦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 8 | nét | 匦 | quỹ | tượng hình | chiếc hòm nhỏ | 匦 có bộ Phương (匚, cái hộp, hòm) — bộ thủ chỉ đồ vật hình hộp. Cấu trúc chi tiết bên trong không được Wiktionary phân tích. Dạng phồn thể là 匭. Chưa có nguồn học thuật phân tích đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\" (cái hòm): bộ Phương (匚) là cái hộp — hòm kiến nghị thời Võ Tắc Thiên, ai cũng có thể bỏ thư vào. | Gương Hán-Việt | Quỹ — ít dùng trong tiếng Việt; thấy trong 匦院 (quỹ viện: cơ quan tiếp nhận kiến nghị thời Đường). | Mở khoá kiến thức | Biết 匦 giúp đọc tư liệu lịch sử đời Đường: 匦函 (hòm kiến nghị) và 匦院 (văn phòng tiếp dân), sáng kiến của Võ Tắc Thiên.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} và giải nghĩa là \"small box\" (hòm nhỏ). Bộ Phương (匚) chỉ hình hộp chứa đựng. 匦 (匭) nổi tiếng qua 匦函 (quỹ hàm) — hòm thư tố cáo, kiến nghị thời Đường Võ Tắc Thiên. Chưa có nguồn học thuật phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hòm", "Hạng Tần Suất (Jun Da)": "4925.0", "Tần Suất % (Jun Da)": "99.9146606868", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 轨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚轨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "轨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匦", "Unihan_Traditional (Chữ Phồn thể)": "匭", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại hòm, hộp nhỏ dùng để đựng thư từ hoặc phiếu bầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笤', '{"9000": "4926.0", "Chữ Trung Quốc": "笤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笤 | giậu | tượng hình | cái chổi | 笤 có bộ Trúc (竹, ⺮) — gợi dụng cụ làm từ tre. Cấu trúc chi tiết bên trong không được Wiktionary hay anchor ghi lại. Dùng chủ yếu trong 笤帚 (chổi). Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giậu\" (cái chổi): bộ Trúc (竹) trên đầu — cái chổi tre quét nhà, hình dáng như hàng giậu tre. | Gương Hán-Việt | Giậu — ít dùng độc lập; thấy trong \"điều trửu\" (笤帚: cái chổi nhỏ). | Mở khoá kiến thức | Biết 笤 giúp đọc 笤帚 (điều trửu: chổi nhỏ) trong văn học dân gian và tục ngữ Trung Hoa.", "Tự nguyên_Xie": "Không có anchor etymology từ Wiktionary. Bộ Trúc (竹) gợi dụng cụ làm từ tre/cây. 笤 dùng trong 笤帚 (điều trửu: cái chổi) — dụng cụ quét nhà làm từ cành cây/cỏ khô. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: điều trửu 笤帚)", "Hạng Tần Suất (Jun Da)": "4926.0", "Tần Suất % (Jun Da)": "99.914758876", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笤", "Unihan_Traditional (Chữ Phồn thể)": "笤", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong từ ghép để chỉ cái chổi quét nhà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峥', '{"9000": "4927.0", "Chữ Trung Quốc": "峥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 9 | nét | 山 | sơn | biểu nghĩa | núi | 爭 | tranh | biểu âm | 峥 = 山 (Sơn, biểu nghĩa: núi) + 爭 (Tranh, biểu âm); chữ hình thanh — bộ Sơn chỉ địa hình núi cao, 爭 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\" (núi tranh giành độ cao): bộ Sơn (山) + Tranh (爭) — những ngọn núi tranh nhau vươn lên trời, vừa cao vừa hiểm. | Gương Hán-Việt | Tranh — dùng trong \"tranh vanh\" (峥嵘: cao vút, nổi bật). | Mở khoá kiến thức | Biết 峥 giúp đọc thành ngữ 峥嵘岁月 (tuế nguyệt tranh vanh: những năm tháng hào hùng) và thơ cổ điển Trung Hoa tả cảnh núi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh, dạng gốc là 崢: bộ 山 (sơn, núi) chỉ địa hình cao vút, 爭 (tranh) cho âm. Tiểu triện và Lục thư thông còn lưu. 峥 mang nghĩa núi cao chót vót; dùng trong 峥嵘 (tranh vanh: cao vút, nổi bật, rực rỡ) và thành ngữ 岁月峥嵘 (tuế nguyệt tranh vanh: năm tháng hào hùng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tranh vanh 崢嶸,峥嵘)", "Hạng Tần Suất (Jun Da)": "4927.0", "Tần Suất % (Jun Da)": "99.9148565484", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 争", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山争", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "争", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峥", "Unihan_Traditional (Chữ Phồn thể)": "崢", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ trong từ ghép để miêu tả núi non cao vút hoặc sự xuất chúng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徭', '{"9000": "4928.0", "Chữ Trung Quốc": "徭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 13 | nét | 徭 | dao | tượng hình | lao dịch cưỡng bức | 徭 có bộ Xích (彳, bước đi) gợi người lao động phải đi xa làm dịch. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ. Chưa có nguồn học thuật phân tích cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dao\" (lao dịch): bộ Xích (彳, đi bước) — người dân phải cuốc bộ đi xa để làm lao dịch cho triều đình. | Gương Hán-Việt | Dao — dùng trong \"dao dịch\" (徭役: lao dịch cưỡng bức) và \"dao phú\" (徭賦: thuế và lao dịch). | Mở khoá kiến thức | Biết 徭 giúp đọc sử Việt và sử Trung: 徭役 (dao dịch) là thuật ngữ then chốt về chế độ phong kiến, xuất hiện trong mọi bộ chính sử.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có phân tích cấu trúc. Bộ Xích (彳) gợi người phải đi/lao động. 徭 mang nghĩa lao dịch — nghĩa vụ lao động cưỡng bức do nhà nước phong kiến áp đặt lên dân. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt làm việc", "Hạng Tần Suất (Jun Da)": "4928.0", "Tần Suất % (Jun Da)": "99.9149542207", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "徭", "Unihan_Traditional (Chữ Phồn thể)": "徭", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "dao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các công việc lao dịch cưỡng bách thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浃', '{"9000": "4929.0", "Chữ Trung Quốc": "浃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 浃 | giáp | tượng hình | ướt đẫm, thấm khắp | 浃 là dạng giản thể của 浹. Chữ gốc 浹 = 氵 (thủy, nước) + 夾 (giáp, biểu âm) — chữ hình thanh. Nghĩa: thấm ướt khắp người, bão hòa. Cấu trúc chi tiết bên trong anchor không phân tích rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\" (ướt đẫm): bộ Thủy (氵) + giáp (夾, kẹp) — nước kẹp lấy toàn thân, ướt đẫm từ đầu đến chân như 汗流浃背. | Gương Hán-Việt | Giáp — dùng trong \"giáp bối\" (浃背) trong thành ngữ 汗流浃背. | Mở khoá kiến thức | Biết 浃 giúp đọc thành ngữ 汗流浃背 (hán lưu giáp bối: mồ hôi đẫm lưng) — diễn đạt sự lo lắng, sợ hãi hoặc làm việc nặng.", "Tự nguyên_Xie": "Tiểu triện | 浃 là dạng giản thể của 浹. Wiktionary chỉ ghi pronunciation không phân tích cấu trúc. Bộ Thủy (氵) chỉ liên quan đến nước/ướt, 夾 (giáp) cho âm. Nổi tiếng qua thành ngữ 汗流浃背 (hán lưu giáp bối: mồ hôi chảy ướt đẫm lưng). Chưa có nguồn học thuật phân tích cấu tạo đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ướt đẫm; thấm vào; quanh hết một vòng; thấu suốt; hoà hợp", "Hạng Tần Suất (Jun Da)": "4929.0", "Tần Suất % (Jun Da)": "99.9150518931", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 夹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵夹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浃", "Unihan_Traditional (Chữ Phồn thể)": "浹", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "tiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ sự thấm ướt hoặc làm tính từ chỉ sự chu đáo, khắp lượt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烊', '{"9000": "4930.0", "Chữ Trung Quốc": "烊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 火 | hoả | biểu nghĩa | lửa, ngọn lửa | 羊 | dương | biểu âm | 烊 = 火 (Hoả, biểu nghĩa: lửa) + 羊 (Dương, biểu âm); chữ hình thanh — bộ Hoả chỉ liên quan đến nhiệt/nấu chảy, 羊 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rang\" (nấu chảy): lửa 火 nung con dê 羊 — nhiệt độ cao từ lửa làm chảy kim loại, như con dê bị rang trong lửa. | Gương Hán-Việt | Rang — ít dùng độc lập trong tiếng Việt. | Mở khoá kiến thức | Biết 烊 giúp đọc từ 打烊 (đả ráng: đóng cửa hàng cuối ngày) — dùng phổ biến ở Thượng Hải và miền Nam Trung Quốc.", "Tự nguyên_Xie": "Chữ hình thanh, ban đầu là dị thể của 煬 (ráng — đun nóng/hun khói). Bộ 火 (hoả, lửa) chỉ liên quan đến nhiệt, 羊 (dương) cho âm. Wiktionary xác nhận: \"Originally an alternative form of 煬\". 烊 mang nghĩa nấu chảy, nung chảy kim loại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu chảy, nung chảy", "Hạng Tần Suất (Jun Da)": "4930.0", "Tần Suất % (Jun Da)": "99.9151495655", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烊", "Unihan_Traditional (Chữ Phồn thể)": "烊", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ quá trình nung chảy kim loại hoặc tan chảy của chất rắn dưới nhiệt độ cao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窸', '{"9000": "4931.0", "Chữ Trung Quốc": "窸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 16 | nét | 窸 | tất | tượng hình | tiếng xào xạc nhỏ | 窸 có bộ Huyệt (穴, hang/lỗ hổng) gợi âm thanh phát ra từ góc khuất. Cấu trúc chi tiết bên trong không được Wiktionary phân tích. Dùng chủ yếu trong 窸窣 (tất tốt: tiếng xào xạc). Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\" (tiếng xào xạc): bộ Huyệt (穴) — âm thanh nhỏ từ trong hang, cái gì đó đang cựa quậy trong bóng tối. | Gương Hán-Việt | Tất — ít dùng độc lập; thấy trong \"tất tốt\" (窸窣: tiếng xào xạc). | Mở khoá kiến thức | Biết 窸 giúp đọc từ tượng thanh 窸窣 (tiếng xào xạc) trong văn học mô tả âm thanh thiên nhiên và đêm tối.", "Tự nguyên_Xie": "Wiktionary chỉ ghi pronunciation không phân tích cấu trúc. Bộ Huyệt (穴) gợi âm thanh nhỏ từ góc khuất. 窸 dùng trong 窸窣 và 窸窸窣窣 — mô phỏng tiếng xào xạc nhẹ nhàng như lá khô hay quần áo cọ vào nhau. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng huyên náo không yên", "Hạng Tần Suất (Jun Da)": "4931.0", "Tần Suất % (Jun Da)": "99.9153443935", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 悉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴悉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窸", "Unihan_Traditional (Chữ Phồn thể)": "窸", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này thường kết hợp tạo thành từ ghép tượng thanh mô tả tiếng động nhỏ và nhẹ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酆', '{"9000": "4932.0", "Chữ Trung Quốc": "酆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 20 | nét | 豐 | phong | biểu âm | 阝 | ấp | biểu nghĩa | vùng đất, thành ấp | 酆 = 豐 (Phong, biểu âm) + 阝 (Ấp, biểu nghĩa: vùng đất, thành ấp — dạng viết tắt của 邑); chữ hình thanh — bộ Ấp chỉ đây là tên địa danh, 豐 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\" (đất Phong): bộ Ấp (阝, đất đai) + Phong (豐) — vùng đất phong phú trù phú, kinh đô của Chu Văn Vương. | Gương Hán-Việt | Phong — dùng trong địa danh 酆都 (Phong Đô: thành phố của người chết trong tín ngưỡng Đạo giáo). | Mở khoá kiến thức | Biết 酆 giúp đọc tư liệu lịch sử Tây Chu và Đạo giáo: 酆都 (Phong Đô) là \"âm phủ\" trong tín ngưỡng dân gian Trung Hoa.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 邑 (ấp, thành ấp, viết tắt là 阝) chỉ đây là địa danh, 豐 (phong) cho âm. Giáp cốt văn, Kim văn, Tiểu triện đều còn lưu. 酆 chỉ đất Phong — kinh đô của Chu Văn Vương trước khi thống nhất thiên hạ, nay thuộc tỉnh Thiểm Tây. Cũng là họ Phong. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất Phong (kinh đô của nhà Chu dưới thời Chu Văn Vương, nay thuộc tỉnh Quảng Tây của Trung Quốc); họ Phong", "Hạng Tần Suất (Jun Da)": "4932.0", "Tần Suất % (Jun Da)": "99.9154415491", "GavinGrover_Once (Chiết tự trực tiếp)": "豐 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豐阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "酆", "Unihan_Traditional (Chữ Phồn thể)": "酆", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ địa danh cổ thời nhà Chu hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缢', '{"9000": "4933.0", "Chữ Trung Quốc": "缢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 缢 | ế | tượng hình | thắt cổ | 缢 là dạng giản thể của 縊 (ế — thắt cổ). Chữ gốc 縊 = 糹 (mi, sợi dây/lụa) + 益 (ích, biểu âm); chữ hình thanh. Giản thể thay 糹 bằng 纟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\" (thắt cổ): bộ Sợi (纟) + ích (益, thêm vào) — thêm sợi dây vào cổ — cách thắt cổ chết. | Gương Hán-Việt | Ế — dùng trong \"ế tử\" (缢死: chết do thắt cổ) trong sử liệu. | Mở khoá kiến thức | Biết 缢 giúp đọc sử liệu: 自缢 (tự ế: tự treo cổ) xuất hiện nhiều trong Nhị thập tứ sử khi ghi cái chết của quan lại và hậu phi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缢 là dạng giản thể của 縊. Chữ gốc 縊 = bộ 糹 (mi, sợi/lụa) + 益 (ích) cho âm. Tiểu triện và Lục thư thông còn lưu. 缢 (縊) mang nghĩa thắt cổ — dùng sợi dây siết cổ để tự vẫn hoặc hành quyết, một hình thức trong sử học Trung Hoa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thắt cổ", "Hạng Tần Suất (Jun Da)": "4933.0", "Tần Suất % (Jun Da)": "99.9155387047", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缢", "Unihan_Traditional (Chữ Phồn thể)": "縊", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động thắt cổ hoặc treo cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褓', '{"9000": "4934.0", "Chữ Trung Quốc": "褓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褓 | bìu | tượng hình | tã lót, khăn quấn trẻ sơ sinh | 褓 có bộ Y (衣/衤, quần áo) gợi vải vóc. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ. Dùng chủ yếu trong 襁褓 (cưỡng bảo: tã lót, giai đoạn sơ sinh). Chưa có nguồn học thuật phân tích cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bìu\" (tã lót): bộ Y (衣) — mảnh vải quấn quanh trẻ sơ sinh, gọi là 褓; còn nhỏ như trong 襁褓. | Gương Hán-Việt | Bìu — dùng trong \"cưỡng bìu\" (襁褓: còn trong tã, giai đoạn sơ sinh). | Mở khoá kiến thức | Biết 褓 giúp đọc thành ngữ 在襁褓中 (đang còn trong tã) và 褓母 (bảo mẫu: vú nuôi) trong văn học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi pronunciation không phân tích cấu trúc. Bộ Y (衣) chỉ đây là vải/trang phục. 褓 (褓) mang nghĩa tã lót, khăn quấn trẻ sơ sinh; dùng trong 襁褓 (cưỡng bảo: giai đoạn còn trong tã) và biểu đạt ấu thơ, sơ sinh. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cưỡng bảo 襁褓)", "Hạng Tần Suất (Jun Da)": "4934.0", "Tần Suất % (Jun Da)": "99.9156358603", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 保", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤保", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "保", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褓", "Unihan_Traditional (Chữ Phồn thể)": "緥", "Pinyin_Xie": "bǎo", "Âm Hán Việt_Xie": "bảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong từ ghép để chỉ tã lót hoặc việc bọc trẻ sơ sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚨', '{"9000": "4935.0", "Chữ Trung Quốc": "蚨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚨 | phù | tượng hình | loài bọ nước; đồng tiền | 蚨 có bộ Trùng (虫, côn trùng/sâu bọ) gợi đây là một loài sinh vật nhỏ. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ. Dùng trong 青蚨 (thanh phù: một loại bọ nước, sau chỉ tiền bạc). Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phù\" (bọ nước hóa tiền): bộ Trùng (虫) — con bọ xanh 青蚨 theo truyền thuyết có thể sinh ra tiền, nên 青蚨 trở thành từ thơ chỉ tiền bạc. | Gương Hán-Việt | Phù — thấy trong \"thanh phù\" (青蚨: bọ nước xanh/tiền). | Mở khoá kiến thức | Biết 蚨 giúp đọc thơ văn cổ điển khi tác giả dùng 青蚨 (thanh phù) để nói về tiền bạc theo lối ẩn dụ văn chương.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi pronunciation không phân tích cấu trúc. Bộ Trùng (虫) chỉ đây là loài côn trùng/sâu bọ. 蚨 dùng trong 青蚨 (thanh phù — loài bọ nước xanh, theo truyền thuyết có thể sinh ra tiền; sau dùng để chỉ tiền bạc nói chung). Cũng dùng trong 蚨蝶 (phù điệp: con bướm). Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thanh phù 青蚨)", "Hạng Tần Suất (Jun Da)": "4935.0", "Tần Suất % (Jun Da)": "99.9157330159", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 夫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫夫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚨", "Unihan_Traditional (Chữ Phồn thể)": "蚨", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong văn cổ để chỉ một loài côn trùng hoặc ẩn dụ cho tiền bạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翳', '{"9000": "4936.0", "Chữ Trung Quốc": "翳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 17 | nét | 殹 | biểu âm | 羽 | vu | biểu nghĩa | lông vũ | 翳 = 殹 (biểu âm) + 羽 (Vu, biểu nghĩa: lông vũ); chữ hình thanh — bộ Vu chỉ đây liên quan đến lông/vũ trang trí xe, 殹 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\" (che lấp): bộ Lông vũ (羽) che khuất — chiếc lọng lông vũ che bóng, như màng mây che mặt trời hay màng đục che mắt. | Gương Hán-Việt | Ế — dùng trong \"ế chướng\" (翳障: vật che khuất, cũng chỉ bệnh mắt). | Mở khoá kiến thức | Biết 翳 giúp đọc y học cổ truyền: 目翳 (mục ế: màng đục trên mắt), 眼翳 (nhãn ế), và thơ văn tả cảnh bóng tối.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 殹 cho âm, bộ 羽 (vu, lông vũ) chỉ đây liên quan đến lông vũ/che phủ. Đại triện và Tiểu triện còn lưu. 翳 mang nhiều nghĩa: bóng mát/che khuất; màng đục trên mắt (nebula/cataract); lá chắn bằng lông vũ trên xe thời cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lọng, cái quạt lông; che lấp", "Hạng Tần Suất (Jun Da)": "4936.0", "Tần Suất % (Jun Da)": "99.9158301715", "GavinGrover_Once (Chiết tự trực tiếp)": "殹 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殹羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翳", "Unihan_Traditional (Chữ Phồn thể)": "瞖", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự che khuất hoặc làm danh từ chỉ cái lọng che mưa nắng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趔', '{"9000": "4937.0", "Chữ Trung Quốc": "趔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 13 | nét | 趔 | liệt | tượng hình | xiêu vẹo, không tiến được | 趔 có bộ Tẩu (走, chạy/đi) gợi hành động di chuyển. Cấu trúc chi tiết bên trong không được Wiktionary hay anchor ghi lại. Dùng trong 趔趄 (liệt thư: xiêu vẹo không vững, bước đi lảo đảo). Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\" (lảo đảo): bộ Tẩu (走) gợi bước đi — bước chân xiêu vẹo như người say rượu, không tiến được thẳng hàng. | Gương Hán-Việt | Liệt — ít dùng độc lập; thấy trong \"liệt thư\" (趔趄: lảo đảo không vững). | Mở khoá kiến thức | Biết 趔 giúp đọc từ 趔趄 (lảo đảo, xiêu vẹo) trong văn học mô tả dáng đi của người say, người già yếu hoặc bị thương.", "Tự nguyên_Xie": "Không có anchor etymology từ Wiktionary. Bộ Tẩu (走) gợi hành động đi lại. 趔 dùng trong 趔趄 (liệt thư: bước đi lảo đảo, xiêu vẹo, không vững chân) — mô tả người mất thăng bằng. Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: liệt thư 趔趄)", "Hạng Tần Suất (Jun Da)": "4937.0", "Tần Suất % (Jun Da)": "99.9159273272", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 列", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走列", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "列", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趔", "Unihan_Traditional (Chữ Phồn thể)": "趔", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu làm động từ khi kết hợp thành từ ghép mô tả dáng đi loạng choạng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炔', '{"9000": "4938.0", "Chữ Trung Quốc": "炔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 火 | hoả | biểu nghĩa | lửa, dễ cháy | 夬 | biểu âm | 炔 = 火 (Hoả, biểu nghĩa: lửa/dễ cháy) + 夬 (biểu âm); chữ hình thanh — bộ Hoả chỉ tính chất dễ cháy, 夬 cho âm đọc (cũng là phần âm của 缺: thiếu hụt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\" (alkyne dễ cháy): lửa 火 + thiếu (夬 từ 缺) — alkyne dễ bắt lửa (火) và thiếu 2 hydro (夬) so với alkene cùng dãy, quyết định cấu trúc hóa học. | Gương Hán-Việt | Không có từ Hán-Việt thông dụng; nhận qua thuật ngữ hóa học 炔烃 (alkyne). | Mở khoá kiến thức | Biết 炔 giúp đọc hóa học hữu cơ Trung văn: 炔烃 (alkyne), 乙炔 (ethylene — khí axetylen), 炔烯 (tên gọi trong chuỗi đồng đẳng).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 火 (hoả, lửa) chỉ tính dễ cháy, 夬 cho âm (cũng là phần âm của 缺 — thiếu hụt). Wiktionary giải thích: chữ được đặt ra để chỉ alkyne (hợp chất hữu cơ) — dễ cháy (火) và thiếu 2 hydro so với alkene cùng dãy đồng đẳng (夬 từ 缺: thiếu). Đây là chữ tạo mới cho thuật ngữ hóa học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các chất alkin (công thức hoá học: CnH2n-2)", "Hạng Tần Suất (Jun Da)": "4938.0", "Tần Suất % (Jun Da)": "99.916023966", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炔", "Unihan_Traditional (Chữ Phồn thể)": "炔", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "khuyết, quế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong thuật ngữ hóa học để chỉ các hợp chất ankin. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誊', '{"9000": "4939.0", "Chữ Trung Quốc": "誊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 誊 | đằng | tượng hình | chép lại, sao chép | 誊 là dạng giản thể của 謄 (đằng — chép lại). Chữ gốc 謄 = 言 (ngôn, lời/chữ) + 滕 (đằng, biểu âm); chữ hình thanh. Giản thể đơn giản hóa phần trên, bỏ bộ Nguyệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\" (chép lại cho sạch): bộ Ngôn (言) gợi chữ viết — leo thang (đằng: trèo lên) từ bản nháp sang bản sạch, chép lại cẩn thận. | Gương Hán-Việt | Đằng — dùng trong \"đằng tả\" (誊写: chép lại, sao chép). | Mở khoá kiến thức | Biết 誊 giúp đọc 誊写 (đằng tả: sao chép), 誊清 (đằng thanh: chép sang bản sạch) — thuật ngữ hành chính và văn phòng.", "Tự nguyên_Xie": "Tiểu triện | 誊 là dạng giản thể của 謄. Chữ gốc 謄 = bộ 言 (ngôn, chữ/lời) + 滕 (đằng) cho âm. Tiểu triện còn lưu dạng gốc. 誊 (謄) mang nghĩa chép lại, sao chép cho rõ ràng hơn — từ bản nháp sang bản sạch, hoặc chép văn bản. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sao chép cho rõ ràng hơn", "Hạng Tần Suất (Jun Da)": "4939.0", "Tần Suất % (Jun Da)": "99.9161206048", "GavinGrover_Once (Chiết tự trực tiếp)": "龹 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龹言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誊", "Unihan_Traditional (Chữ Phồn thể)": "謄", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ để chỉ hành động chép lại văn bản. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赜', '{"9000": "4940.0", "Chữ Trung Quốc": "赜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 15 | nét | 赜 | trách | tượng hình | sâu xa, uyên thâm | 赜 có bộ Phương (匚, hộp/hòm) gợi thứ gì đó ẩn chứa bên trong. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ. Dạng phồn thể là 賾. Chưa có nguồn học thuật phân tích cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\" (sâu xa uyên thâm): bộ Phương (匚, cái hộp) — điều uyên thâm như cất giấu trong hộp kín, phải khám phá mới biết. | Gương Hán-Việt | Trách — dùng trong \"thám trách\" (探赜: khám phá điều sâu xa) trong triết học cổ điển. | Mở khoá kiến thức | Biết 赜 giúp đọc Hệ từ truyện trong Kinh Dịch: 探赜索隐 (thám trách tố ẩn) — một thành ngữ triết học về việc tìm hiểu lẽ huyền vi.", "Tự nguyên_Xie": "Wiktionary chỉ ghi pronunciation và định nghĩa không phân tích cấu trúc. Bộ Phương (匚) gợi thứ ẩn kín. 赜 (賾) mang nghĩa uyên thâm, sâu xa, huyền bí — dùng trong triết học Kinh Dịch: 探赜索隐 (thám trách tố ẩn: khám phá điều sâu xa ẩn khuất). Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu xa, uẩn khúc", "Hạng Tần Suất (Jun Da)": "4940.0", "Tần Suất % (Jun Da)": "99.9162172436", "GavinGrover_Once (Chiết tự trực tiếp)": "𦣞 + 责", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𦣞责", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "责", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "𦣞", "Unihan_Simplified (Chữ Giản thể)": "赜", "Unihan_Traditional (Chữ Phồn thể)": "賾", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự sâu sắc hoặc làm danh từ chỉ những điều uẩn khúc thâm sâu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仃', '{"9000": "4941.0", "Chữ Trung Quốc": "仃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 4 | nét | 人 | nhân | biểu nghĩa | người | 丁 | đinh | biểu âm | 仃 = 亻 (Nhân, biểu nghĩa: người — dạng viết tắt của 人) + 丁 (Đinh, biểu âm); chữ hình thanh — bộ Nhân chỉ đây liên quan đến con người, 丁 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đừng\" (người đứng trơ): bộ Nhân (亻) + Đinh (丁, cây đinh) — người đứng trơ như cây đinh đóng chặt, cô đơn không ai bên cạnh. | Gương Hán-Việt | Đừng — dùng trong \"linh đình\" (伶仃: cô độc không nơi nương tựa). | Mở khoá kiến thức | Biết 仃 giúp đọc 伶仃 (linh đình: côi cút cô đơn) và địa danh 伶仃岛 (đảo Linh Đình, gần Hồng Kông).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 人 (nhân, người, viết tắt 亻) chỉ đây liên quan đến con người, 丁 (đinh) cho âm. 仃 mang nghĩa cô đơn, đơn độc — dùng trong 伶仃 (linh đình: cô độc không nơi nương tựa). Bài thơ nổi tiếng 零丁洋 của Văn Thiên Tường có cùng âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh đinh 伶仃)", "Hạng Tần Suất (Jun Da)": "4941.0", "Tần Suất % (Jun Da)": "99.9163138824", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仃", "Unihan_Traditional (Chữ Phồn thể)": "仃", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ và thường chỉ dùng trong từ ghép để mô tả trạng thái cô đơn trơ trọi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勖', '{"9000": "4942.0", "Chữ Trung Quốc": "勖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 11 | nét | 勖 | húc | tượng hình | khuyến khích, cố gắng | 勖 có bộ Lực (力, sức lực) gợi hành động dùng sức. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ. Dùng trong 勖勉 (húc miễn: khuyến khích, động viên). Chưa có nguồn học thuật phân tích cấu tạo đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"húc\" (cổ vũ cố gắng): bộ Lực (力) — dùng sức mạnh để húc về phía trước, cổ vũ người khác nỗ lực không ngừng. | Gương Hán-Việt | Húc — dùng trong văn ngôn \"húc miễn\" (勖勉: cổ vũ, động viên). | Mở khoá kiến thức | Biết 勖 giúp đọc văn ngôn và thư tín trang trọng: 勖勉 và 勖励 là từ khuyến khích dùng trong lời khuyên trang nghiêm.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary chỉ ghi pronunciation không phân tích cấu trúc. Bộ Lực (力) gợi sức lực, nỗ lực. 勖 mang nghĩa khuyến khích, cổ vũ, động viên — dùng trong văn ngôn: 勖勉 (húc miễn), 勖励 (húc lệ). Lục thư thông còn lưu dạng chữ. Chưa có nguồn học thuật phân tích cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố gắng", "Hạng Tần Suất (Jun Da)": "4942.0", "Tần Suất % (Jun Da)": "99.9164105213", "GavinGrover_Once (Chiết tự trực tiếp)": "冒 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冒力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "勖", "Unihan_Traditional (Chữ Phồn thể)": "勖", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "úc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn viết cổ để khích lệ hoặc khuyên nhủ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葺', '{"9000": "4943.0", "Chữ Trung Quốc": "葺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葺 | tập | tượng hình | lợp mái, tu bổ | 葺 có bộ Thảo (艹, cỏ cây) gợi vật liệu cỏ/rơm dùng để lợp mái. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ (chỉ ghi {{Han etym}}). Có thể chứa 耳 (nhĩ) hoặc 咠. Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\" (lợp mái): bộ Thảo (艹) — chồng cỏ rơm lên mái nhà từng lớp, \"tập\" chồng như những trang sách. | Gương Hán-Việt | Tập — dùng trong \"tu tập\" (修葺: sửa chữa, tu bổ nhà cửa, công trình). | Mở khoá kiến thức | Biết 葺 giúp đọc từ 修葺 (tu tập: sửa sang nhà cửa, công trình) trong văn bản hành chính và văn học Hán Nôm.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} không phân tích cấu trúc. Bộ Thảo (艹) gợi vật liệu cỏ/rơm dùng để lợp mái nhà. Tiểu triện còn lưu. 葺 mang nghĩa lợp mái bằng cỏ rơm; mở rộng sang sửa chữa, tu bổ — dùng trong 修葺 (tu tập: sửa chữa, tu bổ nhà cửa). Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tu bổ lại; chồng chất", "Hạng Tần Suất (Jun Da)": "4943.0", "Tần Suất % (Jun Da)": "99.9165071601", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 咠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹咠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葺", "Unihan_Traditional (Chữ Phồn thể)": "葺", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động sửa chữa hoặc lợp lại mái nhà. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚴', '{"9000": "4944.0", "Chữ Trung Quốc": "蚴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚴 | ấu | tượng hình | ấu trùng, sâu non | 蚴 có bộ Trùng (虫, côn trùng/sâu) gợi đây là sinh vật ký sinh. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ. Dùng trong 毛蚴 (mao ấu), 尾蚴 (vĩ ấu) — các giai đoạn ấu trùng sán lá. Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấu\" (ấu trùng): bộ Trùng (虫) + âm ấu — con sâu còn nhỏ, giai đoạn ấu trùng của ký sinh trùng. | Gương Hán-Việt | Ấu — dùng trong thuật ngữ y học \"ấu trùng\" (蚴: giai đoạn ấu của sán lá). | Mở khoá kiến thức | Biết 蚴 giúp đọc thuật ngữ ký sinh trùng học: 毛蚴 (mao ấu: miracidium), 尾蚴 (vĩ ấu: cercaria), 蚴虫 (ấu trùng sán).", "Tự nguyên_Xie": "Wiktionary chỉ ghi pronunciation và định nghĩa không phân tích cấu trúc. Bộ Trùng (虫) chỉ đây là côn trùng/ký sinh trùng. 蚴 chỉ ấu trùng — đặc biệt là ấu trùng sán lá (tapeworm larva, cercaria) trong y học ký sinh trùng. Dùng trong 毛蚴 (miracidium), 尾蚴 (cercaria). Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấu trùng (của loài trùng hút máu.)", "Hạng Tần Suất (Jun Da)": "4944.0", "Tần Suất % (Jun Da)": "99.9166037989", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚴", "Unihan_Traditional (Chữ Phồn thể)": "蚴", "Pinyin_Xie": "yòu", "Âm Hán Việt_Xie": "u", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong sinh học để chỉ giai đoạn ấu trùng của giun sán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泷', '{"9000": "4945.0", "Chữ Trung Quốc": "泷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 氵 | thủy | biểu nghĩa | nước | 龍 | long | biểu âm | 泷 = 氵 (Thủy, biểu nghĩa: nước — dạng viết tắt của 水) + 龍 (Long, biểu âm); chữ hình thanh — bộ Thủy chỉ đây liên quan đến nước/dòng chảy, 龍 cho âm đọc (giản thể 龙).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\" (nước chảy xiết): bộ Thủy (氵) + Long (龍) — con rồng quẫy trong nước, tạo ra dòng chảy mạnh như thác lũ. | Gương Hán-Việt | Lung — ít dùng độc lập; thấy trong địa danh 泷水 (nước Lung, tỉnh Quảng Đông). | Mở khoá kiến thức | Biết 泷 giúp đọc địa danh Quảng Đông: 泷水 và các tên gọi thác nước trong thơ cổ tả cảnh thiên nhiên hùng vĩ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Chữ hình thanh, dạng gốc là 瀧: bộ 水 (thủy, nước, viết tắt 氵) chỉ dòng chảy, 龍 (long) cho âm. Giáp cốt văn, Tiểu triện và Lục thư thông còn lưu. 泷 (瀧) mang nghĩa nước chảy xiết qua thác; cũng là tên sông/địa danh ở Quảng Đông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chảy xiết", "Hạng Tần Suất (Jun Da)": "4945.0", "Tần Suất % (Jun Da)": "99.9167004377", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泷", "Unihan_Traditional (Chữ Phồn thể)": "瀧", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lang, lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ tên sông hoặc làm tính từ mô tả dòng nước chảy cuồn cuộn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛴', '{"9000": "4946.0", "Chữ Trung Quốc": "蛴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sâu bọ | 齊 | tày | biểu âm | 蛴 = 虫 (Trùng, biểu nghĩa: côn trùng, sâu bọ) + 齊 (Tày, biểu âm); chữ hình thanh — bộ Trùng chỉ đây là loài sâu/ấu trùng, 齊 cho âm đọc. Dạng phồn thể là 蠐.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tề\" (con sùng): bộ Trùng (虫) + Tề (齊, ngang hàng) — những con sùng nằm hàng hàng lớp lớp trong đất, đều tăm tắp. | Gương Hán-Việt | Tề — dùng trong \"tề tào\" (蛴螬: con sùng trong đất) và \"thu tề\" (蝤蛴: cổ trắng mịn như sâu trắng trong Kinh Thi). | Mở khoá kiến thức | Biết 蛴 giúp đọc Kinh Thi: 蝤蛴 (thu tề) là hình ảnh ẩn dụ về cổ trắng ngà của người đẹp — xuất hiện trong Bội phong, Thạc nhân.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh, dạng gốc là 蠐: bộ 虫 (trùng, côn trùng) chỉ đây là loài sâu bọ, 齊 (tày) cho âm. Tiểu triện còn lưu. 蛴 (蠐) mang nghĩa ấu trùng, sâu non — dùng trong 蛴螬 (tề tào: con sùng/ấu trùng bọ hung trong đất) và 蝤蛴 (thu tề: con sâu trắng — cách nói về cổ trắng mịn trong Kinh Thi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tề tào 蠐螬,蛴螬)", "Hạng Tần Suất (Jun Da)": "4946.0", "Tần Suất % (Jun Da)": "99.9167970765", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛴", "Unihan_Traditional (Chữ Phồn thể)": "蠐", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "tề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và chủ yếu xuất hiện trong từ ghép để chỉ một loại côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媸', '{"9000": "4947.0", "Chữ Trung Quốc": "媸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 媸 | si | tượng hình | xấu xí (phụ nữ) | 媸 có bộ Nữ (女) gợi đây miêu tả phụ nữ. Cấu trúc chi tiết bên trong không được Wiktionary phân tích rõ (chỉ ghi {{Han etym}}). Dùng trong 媸妍 (si nghiên: xấu đẹp) và thành ngữ 不知媸妍. Chưa có nguồn học thuật phân tích cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\" (xấu xí): bộ Nữ (女) — người phụ nữ si (chứ không nghiên/đẹp); 媸妍 là cặp đối nghĩa xấu-đẹp trong văn học cổ. | Gương Hán-Việt | Si — dùng trong \"si nghiên\" (媸妍: xấu đẹp) và thành ngữ cổ điển. | Mở khoá kiến thức | Biết 媸 giúp đọc thơ văn cổ điển Trung Hoa: 媸妍 (si nghiên: xấu đẹp), 不辨媸妍 (không phân biệt xấu đẹp — chỉ người không có con mắt thẩm mỹ).", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không phân tích cấu trúc. Bộ Nữ (女) chỉ đây miêu tả ngoại hình phụ nữ. 媸 mang nghĩa xấu xí (về tướng mạo phụ nữ) — đối nghĩa với 妍 (nghiên: xinh đẹp). Dùng trong 媸妍 (xấu đẹp) và thành ngữ 不辨媸妍 (không phân biệt xấu đẹp). Chưa có nguồn học thuật phân tích cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xấu xí (tướng mạo)", "Hạng Tần Suất (Jun Da)": "4947.0", "Tần Suất % (Jun Da)": "99.9169898374", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 蚩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女蚩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "媸", "Unihan_Traditional (Chữ Phồn thể)": "媸", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "xi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ dùng để chê bai diện mạo của người phụ nữ trong văn học cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俳', '{"9000": "4948.0", "Chữ Trung Quốc": "俳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 非 | phi | biểu âm | 俳 = 亻 (Nhân, biểu nghĩa: người — dạng viết tắt của 人) + 非 (Phi, biểu âm); chữ hình thanh — bộ Nhân chỉ đây liên quan đến con người/nghề diễn, 非 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bài\" (nghệ nhân): bộ Nhân (亻) + Phi (非, trái phải/phê phán) — người đứng giữa ranh giới đúng/sai để diễn hài, làm khán giả cười. | Gương Hán-Việt | Bài — dùng trong \"bài ưu\" (俳優: diễn viên hài kịch cổ) và \"bài cú\" (俳句: haiku). | Mở khoá kiến thức | Biết 俳 giúp đọc 俳句 (bài cú: haiku — thể thơ Nhật 5-7-5), 俳優 (bài ưu: diễn viên), 俳諧 (bài hài: thơ hài hước).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 人 (nhân, người, viết tắt 亻) chỉ người/nghề, 非 (phi) cho âm. Tiểu triện còn lưu. 俳 mang nghĩa diễn viên hài kịch thời cổ, vở diễn giải trí; cũng có nghĩa hài hước, buồn cười. Nổi bật qua 俳句 (haiku Nhật — thể thơ vay mượn từ Trung Hoa), 俳優 (diễn viên). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "do dự, phân vân", "Hạng Tần Suất (Jun Da)": "4948.0", "Tần Suất % (Jun Da)": "99.9170854426", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俳", "Unihan_Traditional (Chữ Phồn thể)": "俳", "Pinyin_Xie": "pái", "Âm Hán Việt_Xie": "bài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ người diễn kịch vui hoặc làm tính từ trong từ ghép chỉ sự do dự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诖', '{"9000": "4949.0", "Chữ Trung Quốc": "诖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诖 | quải | tượng hình | lầm lỡ, bị lừa | 诖 là dạng giản thể của 詿 (quải — lầm lỡ). Chữ gốc 詿 = 言 (ngôn, lời nói) + 卦 (quải, biểu âm); chữ hình thanh. Giản thể thay 言 bằng 讠.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quải\" (bị lừa lầm): bộ Ngôn (讠) + Quải (卦, quẻ bói) — bị lời nói của thầy bói quải (lừa) vào con đường sai lầm. | Gương Hán-Việt | Quải — dùng trong \"quải ngộ\" (诖误: liên lụy oan uổng do người khác gây ra). | Mở khoá kiến thức | Biết 诖 giúp đọc sử liệu: 诖误 (quải ngộ) là thuật ngữ pháp lý cổ — bị liên lụy oan vì lời nói/hành động của người khác.", "Tự nguyên_Xie": "Tiểu triện | 诖 là dạng giản thể của 詿. Wiktionary xác nhận: {{Han simp|詿|f=言|t=讠}}. Chữ gốc 詿 = bộ 言 (ngôn, lời/ngôn ngữ) + 卦 (quải) cho âm. Tiểu triện còn lưu. 诖 mang nghĩa lầm lỡ, bị người khác lừa dối vào chỗ sai — dùng trong 诖误 (quải ngộ: liên lụy vì lầm lỡ, bị oan do người khác). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lầm, lừa dối", "Hạng Tần Suất (Jun Da)": "4949.0", "Tần Suất % (Jun Da)": "99.9171810479", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诖", "Unihan_Traditional (Chữ Phồn thể)": "詿", "Pinyin_Xie": "guà", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn với nghĩa là lừa gạt hoặc bị liên lụy vào việc xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茑', '{"9000": "4950.0", "Chữ Trung Quốc": "茑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 茑 | điểu | tượng hình | cây ký sinh leo như tơ hồng, thường mọc bám vào cây khác | 茑 là chữ giản thể của 蔦. Dạng cổ 蔦 gồm bộ 艸 (thảo, biểu nghĩa: cây cỏ) và 鳥 (điểu, biểu âm). Chữ hình thanh. Chữ hiện đại 茑 lược bỏ nét, chỉ còn gốc thảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điểu\" (chim): tưởng tượng một loài cây leo như con chim bám chặt cành cây — đó là cây 茑, loài thực vật ký sinh leo cuốn. | Gương Hán-Việt | điểu trong từ 蔦蘿 (điểu la — cây tơ hồng hoa đỏ) | Mở khoá kiến thức | Biết 茑 (điểu) giúp nhận ra nhóm cây ký sinh/leo trong thực vật học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ gốc là 蔦 (hình thanh): bộ 艸 chỉ loại thực vật, phần 鳥 (điểu) cho âm đọc. Wiktionary ghi nhận 蔦 chỉ cây thường xuân leo (ivy) hoặc các loài ký sinh như tầm gửi. Chưa có nguồn khảo cứu cụ thể về nguồn gốc hình dạng cổ. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây điểu (một thứ cây mọc từng bụi như cỏ thố ty)", "Hạng Tần Suất (Jun Da)": "4950.0", "Tần Suất % (Jun Da)": "99.9172766531", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茑", "Unihan_Traditional (Chữ Phồn thể)": "蔦", "Pinyin_Xie": "niǎo", "Âm Hán Việt_Xie": "điểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ một loại cây ký sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逡', '{"9000": "4951.0", "Chữ Trung Quốc": "逡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逡 | tuân | tượng hình | lùi bước, rút lui dè dặt | 逡 chưa có dữ liệu cấu tạo chi tiết trong kho CHISE. Theo cấu trúc chung, chữ gồm bộ 辵 (xước, chỉ sự di chuyển) kết hợp phần biểu âm. Chữ hội ý hoặc hình thanh — chưa xác định rõ loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuân\": hình dung người tuân lệnh cẩn trọng lùi từng bước — 逡 là bước lùi dè dặt đó. | Gương Hán-Việt | tuân trong 逡巡 (tuân tuần — do dự, lưỡng lự) | Mở khoá kiến thức | Biết 逡 mở ra 逡巡 (tuân tuần) — thành ngữ chỉ sự do dự không dám tiến bước.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 逡 mang nghĩa lùi bước, rút lui (retreat, withdraw, fall back). Âm đọc có biến thể qūn/xùn/suō. Chưa có phân tích glyph origin cụ thể trong nguồn học thuật. Chưa có nguồn học thuật về cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lùi lại, rút lại", "Hạng Tần Suất (Jun Da)": "4951.0", "Tần Suất % (Jun Da)": "99.9173722584", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逡", "Unihan_Traditional (Chữ Phồn thể)": "逡", "Pinyin_Xie": "qūn", "Âm Hán Việt_Xie": "thuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước động từ khác để chỉ hành động thoái lui hoặc do dự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孱', '{"9000": "4952.0", "Chữ Trung Quốc": "孱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 12 | nét | 孱 | sàn | tượng hình | yếu đuối, hèn nhát, không có sức mạnh | 孱 chưa có dữ liệu cấu tạo chi tiết trong kho CHISE. Chữ thuộc bộ 子 (tử). Hình dạng có thể liên quan đến người (子) trong hoàn cảnh yếu ớt, nhưng chưa có phân tích học thuật xác nhận. Chữ hội ý hoặc hình thanh — chưa rõ loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàn\": nghĩ đến người gầy sàn sạt, yếu không đứng vững — 孱 là sự yếu đuối thể xác lẫn tinh thần. | Gương Hán-Việt | sàn trong 孱弱 (sàn nhược — yếu đuối) | Mở khoá kiến thức | Biết 孱 mở ra 孱弱 (sàn nhược), 孱夫 (sàn phu — kẻ yếu hèn).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi nhận 孱 mang nghĩa yếu đuối (weak, frail, feeble) với hai âm đọc chính: chán (yếu ớt, nhỏ bé) và càn (trong 孱頭 — kẻ nhút nhát). Không có phân tích glyph origin cụ thể. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yếu đuối; hèn kém; quẫn bách", "Hạng Tần Suất (Jun Da)": "4952.0", "Tần Suất % (Jun Da)": "99.9174678636", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 孨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸孨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "孱", "Unihan_Traditional (Chữ Phồn thể)": "孱", "Pinyin_Xie": "càn", "Âm Hán Việt_Xie": "sàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả sự yếu ớt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砦', '{"9000": "4953.0", "Chữ Trung Quốc": "砦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 砦 | sách | tượng hình | đồn lũy, trại lính trên núi rào bằng gỗ đá | 砦 chưa có dữ liệu cấu tạo trong kho CHISE và Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích. Chữ thuộc bộ 石 (thạch). Dạng chữ 寨 (sách) phổ biến hơn là biến thể cùng nghĩa. Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": tưởng tượng đá (石) xếp thành tường rào — 砦 là đồn lũy đá kiên cố trên núi. | Gương Hán-Việt | sách trong 山砦 (sơn sách — trại núi), đồng nghĩa 寨 | Mở khoá kiến thức | Biết 砦 nhận ra biến thể 寨 (sách) — từ hay dùng trong tên địa danh và lịch sử quân sự.", "Tự nguyên_Xie": "Wiktionary chỉ có marker {{Han etym}} mà không có phân tích cụ thể cho 砦. Chữ mang nghĩa đồn lũy, trại quân trên núi (stockade, fort). Biến thể 寨 phổ biến hơn trong văn hiện đại. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(chỗ ở núi, lấy gỗ rào chung quanh để ở)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砦", "Unihan_Traditional (Chữ Phồn thể)": "砦", "Pinyin_Xie": "zhài", "Âm Hán Việt_Xie": "trại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ công trình phòng thủ bằng gỗ ở vùng núi hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跸', '{"9000": "4954.0", "Chữ Trung Quốc": "跸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 跸 | tất | tượng hình | dẹp đường để vua đi; xa giá hoàng đế | 跸 là giản thể của 蹕. Chữ gốc 蹕 gồm bộ 足 (túc, biểu nghĩa: chân, đi lại) và phần biểu âm. Chữ hình thanh. Nghĩa chỉ nghi thức dọn đường khi vua xuất cung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": chân (足) vua bước đến đâu thì đường tất phải được dọn sạch — 跸 là lệnh dẹp đường cho xa giá. | Gương Hán-Việt | tất trong 驻跸 (trú tất — vua dừng chân), 扈跸 (hộ tất — hộ tống xa giá) | Mở khoá kiến thức | Biết 跸 mở ra ngữ cảnh nghi lễ hoàng gia cổ điển: 驻跸, 清跸, 扈跸.", "Tự nguyên_Xie": "Lục thư thông | Chữ gốc là 蹕 (hình thanh): bộ 足 chỉ sự di chuyển, phần còn lại cho âm. Wiktionary ghi rõ: dùng trong văn ngôn chỉ việc dọn đường, cấm người qua lại khi hoàng đế tuần du (to clear the way when an emperor tours); cũng chỉ xa giá hoặc nơi vua dừng nghỉ. Chữ tạo muộn dùng trong nghi lễ triều đình. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường cấm để cho vua đi; đứng một chân", "Hạng Tần Suất (Jun Da)": "4954.0", "Tần Suất % (Jun Da)": "99.9176590741", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 毕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊毕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跸", "Unihan_Traditional (Chữ Phồn thể)": "蹕", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong nghi thức cung đình xưa hoặc làm danh từ chỉ sự dẹp đường. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祜', '{"9000": "4955.0", "Chữ Trung Quốc": "祜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 礻 | thị | biểu nghĩa | thần linh, tế tự | 古 | cổ | biểu âm | cũ, xưa | 祜 = 礻(Thị, biểu nghĩa: thần linh) + 古 (Cổ, biểu âm); chữ hình thanh. Bộ 礻 chỉ lĩnh vực thần thánh, phúc lành; 古 cho âm gần với hù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗ\": thần (礻) ban phúc lành — 祜 là ân sủng thiêng liêng từ trời cao, âm 古 gợi điều cổ xưa bền vững. | Gương Hán-Việt | hỗ trong 薄祜 (bạc hỗ — phúc mỏng, số phận kém may) | Mở khoá kiến thức | Biết 祜 mở ra nhóm chữ phúc lành: 福, 祚, 禄 — tất cả đều có bộ 礻.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary ghi rõ: Hán tự hình thanh gồm 示 (礻, biểu nghĩa: thần linh) và 古 (biểu âm). Nghĩa: phúc lành từ trời ban xuống (favor from heaven; blessing). Đồng nghĩa với 福, 祝福, 祚. Hình dạng tiểu triện và kim văn đều xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc", "Hạng Tần Suất (Jun Da)": "4955.0", "Tần Suất % (Jun Da)": "99.9177546794", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祜", "Unihan_Traditional (Chữ Phồn thể)": "祜", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn viết cổ để chỉ phúc lành do trời đất ban cho. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伉', '{"9000": "4956.0", "Chữ Trung Quốc": "伉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 伉 | kháng | tượng hình | ngang hàng, sánh đôi; vợ chồng | 伉 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 亻(nhân). Có thể là hình thanh với 亻biểu nghĩa (người) và phần còn lại biểu âm, nhưng chưa có phân tích học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kháng\": hai người (亻) ngang hàng kháng cự nhau — 伉 là sự tương đương, xứng đôi, như vợ chồng sánh vai. | Gương Hán-Việt | kháng trong 伉儷 (kháng lệ — vợ chồng), 伉直 (kháng trực — thẳng thắn) | Mở khoá kiến thức | Biết 伉 mở ra từ 伉儷 — từ trang trọng chỉ vợ chồng trong văn chương.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 伉 mang nhiều nghĩa: sánh ngang (to match, be equal to), cao lớn mạnh mẽ (tall, strong), thẳng thắn (upright), và trong một số phương ngữ nghĩa là ''và'' (and). Thành ngữ nổi bật: 伉儷 (kháng lệ — vợ chồng). Chưa có phân tích glyph origin chi tiết. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sánh đôi cùng nhau, vợ chồng", "Hạng Tần Suất (Jun Da)": "4956.0", "Tần Suất % (Jun Da)": "99.9178497679", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伉", "Unihan_Traditional (Chữ Phồn thể)": "伉", "Pinyin_Xie": "kàng", "Âm Hán Việt_Xie": "kháng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ hoặc động từ trong từ ghép để chỉ sự tương xứng, ngang hàng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溴', '{"9000": "4957.0", "Chữ Trung Quốc": "溴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thủy | biểu nghĩa | nước, chất lỏng | 臭 | xú | biểu âm | hôi thối, mùi khó chịu | 溴 = 氵(Thủy, biểu nghĩa: chất lỏng) + 臭 (Xú, biểu âm và biểu nghĩa: hôi thối); chữ hội ý kiêm hình thanh. Wiktionary ghi nhận hai cách phân tích: ls=ic (hội ý: chất lỏng có mùi hôi) và ls=psc (hình thanh: 臭 cho âm). Bromine (Br) là chất lỏng màu nâu đỏ có mùi hắc — cấu tạo chữ hoàn toàn phù hợp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tú\": nước (氵) mà xú (臭 — hôi) — 溴 là brom, chất lỏng nâu đỏ sặc mùi trong hóa học. | Gương Hán-Việt | tú trong 溴素 (tú tố — nguyên tố brom Br) | Mở khoá kiến thức | Biết 溴 giúp nhận ra ngay tên hóa học: 溴素 (Br), 溴化物 (bromide) trong sách hóa học Trung Quốc.", "Tự nguyên_Xie": "Wiktionary phân tích hai lớp: (1) Hội ý — 氵 (nước/chất lỏng) + 臭 (hôi thối) → chất lỏng có mùi hắc; (2) Hình thanh — 臭 cho âm đọc xiù. Bromine được đặt tên bằng chữ này vì đây là nguyên tố phi kim dạng lỏng duy nhất ở nhiệt độ phòng, có mùi hắc đặc trưng. Chữ hiện đại tạo khoảng thế kỷ 19 khi phiên dịch thuật ngữ hóa học phương Tây vào tiếng Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hơi nước; Brôm, Br", "Hạng Tần Suất (Jun Da)": "4957.0", "Tần Suất % (Jun Da)": "99.9179448563", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 臭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵臭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溴", "Unihan_Traditional (Chữ Phồn thể)": "溴", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "xú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong hóa học để chỉ nguyên tố phi kim Brôm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屐', '{"9000": "4958.0", "Chữ Trung Quốc": "屐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 10 | nét | 履 | lý | biểu nghĩa | giày dép | 支 | chi | biểu âm | nhánh, chống đỡ | 屐 = 履 (Lý, biểu nghĩa: giày) + 支 (Chi, biểu âm); chữ hình thanh. Theo Thuyết văn: 屐 là loại giày gỗ có răng ở đáy. Bộ 履 chỉ loại dép/giày, 支 cho âm gần với jī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kị\": đôi guốc gỗ (履) chống (支) bước leo núi — 屐 là guốc gỗ kẽo kẹt của ẩn sĩ trong thơ cổ. | Gương Hán-Việt | kị trong 木屐 (mộc kị — guốc gỗ), 谢公屐 (Tạ Công kị — guốc leo núi của Tạ Linh Vận) | Mở khoá kiến thức | Biết 屐 mở ra 木屐 (guốc gỗ Nhật Bản/Trung Quốc) và hình ảnh thơ cổ người ẩn sĩ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary dẫn Thuyết văn: hình thanh gồm 履 (giày, biểu nghĩa) và 支 (biểu âm). 屐 chỉ loại guốc gỗ (wooden clogs) dùng phổ biến ở vùng Quảng Đông, Phúc Kiến, và đặc biệt Nhật Bản (geta). Tiếng Thái vay mượn thành เกี๊ยะ. Trong thơ Lý Bạch và Tạ Linh Vận, guốc gỗ là hình ảnh người ẩn sĩ leo núi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các guốc gỗ", "Hạng Tần Suất (Jun Da)": "4958.0", "Tần Suất % (Jun Da)": "99.9180399448", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "屐", "Unihan_Traditional (Chữ Phồn thể)": "屐", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ để chỉ đôi guốc gỗ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飚', '{"9000": "4959.0", "Chữ Trung Quốc": "飚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 16 | nét | 飚 | tiêu | tượng hình | gió lốc xoáy, cuồng phong | 飚 là giản thể của 飈. Chữ gốc 飈 gồm bộ 風 (phong, gió) kết hợp với phần biểu âm/nghĩa. Chữ hiện đại 飚 lược giản bộ 風 thành 风. Chỉ loại gió xoáy mạnh, cuồng phong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": gió (风) xoáy vút tiêu lên cao — 飚 là cơn lốc xoáy, cuồng phong đột ngột. | Gương Hán-Việt | tiêu trong 飙升 (tiêu thăng — tăng vọt), 飚风 (tiêu phong — lốc xoáy) | Mở khoá kiến thức | Biết 飚 mở ra 飙升 (tăng vọt như lốc) — từ dùng rộng trong kinh tế, thể thao hiện đại.", "Tự nguyên_Xie": "Wiktionary ghi 飚 là giản thể của 飈, xem mục 飈 để tra cứu đầy đủ. Chữ gốc chỉ gió lốc (whirlwind). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Nguồn hanziyuan không có hình ảnh cho chữ này. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gió cuốn", "Hạng Tần Suất (Jun Da)": "4959.0", "Tần Suất % (Jun Da)": "99.9181350332", "GavinGrover_Once (Chiết tự trực tiếp)": "风 + 焱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴风焱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "风", "Unihan_Simplified (Chữ Giản thể)": "飚", "Unihan_Traditional (Chữ Phồn thể)": "飈", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "biểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ luồng gió mạnh hoặc làm định ngữ bổ nghĩa cho danh từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛞', '{"9000": "4960.0", "Chữ Trung Quốc": "蛞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 𠯑 | biểu âm | (phần biểu âm không còn dùng độc lập) | 蛞 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 𠯑 (biểu âm); chữ hình thanh. Bộ 虫 chỉ loại sinh vật nhỏ bé, phần 𠯑 cho âm đọc kuò. Thường xuất hiện trong tổ hợp 蛞蝓 (sên trần).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoát\": con sâu (虫) trườn khoát ra — 蛞 là con sên trần nhầy nhụa, trườn mình ướt át. | Gương Hán-Việt | khoát trong 蛞蝓 (khoát du — con sên trần) | Mở khoá kiến thức | Biết 蛞 chỉ cần nhớ 蛞蝓 — con sên không vỏ hay gặp trong vườn rau.", "Tự nguyên_Xie": "Wiktionary ghi: hình thanh gồm 虫 (biểu nghĩa: sâu bọ) và 𠯑 (biểu âm). Chữ gần như chỉ dùng trong tổ hợp 蛞蝓 (sên trần, slug) và 蛞螻 (sâu dế). Chưa có phân tích lịch sử hình dạng cụ thể. Chữ tạo muộn phục vụ tên sinh vật học. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khoát du 蛞蝓)", "Hạng Tần Suất (Jun Da)": "4960.0", "Tần Suất % (Jun Da)": "99.9182301217", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛞", "Unihan_Traditional (Chữ Phồn thể)": "蛞", "Pinyin_Xie": "kuò", "Âm Hán Việt_Xie": "khoát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ khi kết hợp thành từ ghép chỉ các loài bò sát nhỏ như sên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掮', '{"9000": "4961.0", "Chữ Trung Quốc": "掮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 掮 | khiêng | tượng hình | vác, gánh trên vai; làm môi giới | 掮 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 手/扌(thủ, tay). Theo ngữ nghĩa: tay (扌) vác vật lên vai. Chưa có phân tích học thuật xác nhận cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiêng\": tay (扌) khiêng vật nặng lên vai — 掮 là động tác vác vai, rồi mở rộng thành người môi giới (vác tin giữa hai bên). | Gương Hán-Việt | khiêng trong 掮客 (khiêng khách — người môi giới, cò mồi) | Mở khoá kiến thức | Biết 掮 mở ra 掮客 — từ chỉ người môi giới không chính thức, thường gặp trong văn cảnh thương mại.", "Tự nguyên_Xie": "Wiktionary ghi: 掮 có nghĩa gốc chưa rõ (rfdef). Tiếng Mân Nam Xiamen/Đài Loan: khaiⁿ — vác một đầu đòn gánh. Từ phái sinh quan trọng: 掮客 (môi giới, cò mồi) — người vác/chuyền thông tin giữa hai bên. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gánh vác", "Hạng Tần Suất (Jun Da)": "4961.0", "Tần Suất % (Jun Da)": "99.9184197819", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 肩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌肩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掮", "Unihan_Traditional (Chữ Phồn thể)": "掮", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để chỉ hành động mang vác hoặc làm trung gian môi giới. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崆', '{"9000": "4962.0", "Chữ Trung Quốc": "崆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 崆 | không | tượng hình | tên núi Không Đồng; hang núi trống rỗng | 崆 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 山 (sơn, núi). Chủ yếu dùng trong địa danh 崆峒 (Không Đồng — ngọn núi nổi tiếng ở Cam Túc). Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"không\": núi (山) rỗng không bên trong — 崆 gợi hình ảnh hang núi Không Đồng, địa linh của đạo gia. | Gương Hán-Việt | không trong 崆峒 (Không Đồng — tên núi thiêng đạo giáo) | Mở khoá kiến thức | Biết 崆 chủ yếu để đọc địa danh 崆峒山 — ngọn núi đạo giáo nổi tiếng.", "Tự nguyên_Xie": "Wiktionary ghi nhận 崆 chủ yếu dùng trong tên riêng và địa danh. Âm đọc kōng. 崆峒 (Không Đồng Sơn) là núi thiêng trong đạo giáo Trung Quốc ở tỉnh Cam Túc. Chưa có phân tích glyph origin cụ thể. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: không động 崆峒)", "Hạng Tần Suất (Jun Da)": "4962.0", "Tần Suất % (Jun Da)": "99.9185143535", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 空", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山空", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崆", "Unihan_Traditional (Chữ Phồn thể)": "崆", "Pinyin_Xie": "kōng", "Âm Hán Việt_Xie": "không", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ riêng trong địa danh cổ hoặc tên núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庾', '{"9000": "4963.0", "Chữ Trung Quốc": "庾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 庾 | dũ | tượng hình | kho thóc ngoài trời; đơn vị đo thể tích lúa cổ | 庾 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 广 (nghiễm, mái che). Có thể là hình ảnh kho thóc có mái che đơn giản. Chưa xác định rõ hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũ\": mái che (广) rộng dũ xuống bảo vệ đống thóc — 庾 là kho thóc ngoài trời của nông dân thời xưa. | Gương Hán-Việt | dũ trong 庾澄慶 (Dũ Trừng Khánh — tên nghệ danh Harlem Yu) | Mở khoá kiến thức | Biết 庾 nhận ra họ Dũ trong lịch sử Trung Quốc và là đơn vị đo nông nghiệp cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 庾 mang nghĩa: (1) đống thóc lộ thiên hoặc kho thóc hở (open-air granary, pile of grain); (2) đơn vị đo thể tích cổ đại (bằng 16 đấu). Cũng là họ người — nổi tiếng nhất là Harlem Yu (庾澄慶). Chưa có phân tích glyph origin chi tiết. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vựa; dữu (đơn vị đo, bằng 16 đấu)", "Hạng Tần Suất (Jun Da)": "4963.0", "Tần Suất % (Jun Da)": "99.9186089252", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 臾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广臾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庾", "Unihan_Traditional (Chữ Phồn thể)": "庾", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "dữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ kho thóc hoặc làm lượng từ đo lường dung tích thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橛', '{"9000": "4964.0", "Chữ Trung Quốc": "橛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 橛 | cột | tượng hình | cái cọc gỗ dùng buộc gia súc hoặc dùng làm hàm thiết ngựa | 橛 chưa có dữ liệu cấu tạo trong CHISE và Wiktionary chỉ ghi {{Han etym}} không có phân tích. Chữ thuộc bộ 木 (mộc, gỗ). Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cột\": gỗ (木) đóng thành cột cọc — 橛 là chiếc cọc gỗ nhỏ cắm xuống đất để buộc trâu bò. | Gương Hán-Việt | cột trong 橛子 (cột tử — cái cọc), 蹶 (궐 — vấp ngã, chữ đồng âm) | Mở khoá kiến thức | Biết 橛 nhận ra nhóm vật dụng gỗ nhỏ trong nông nghiệp và chuồng trại cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ có marker {{Han etym}} mà không có phân tích cụ thể cho 橛. Chữ mang nghĩa cái cọc gỗ (post, stake) hoặc hàm thiết ngựa (axle/bit). Bộ 木 chỉ chất liệu gỗ. Chưa có nguồn học thuật về cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cọc buộc giữ súc vật; cái hàm thiết ngựa; chặt cây", "Hạng Tần Suất (Jun Da)": "4964.0", "Tần Suất % (Jun Da)": "99.9187034969", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橛", "Unihan_Traditional (Chữ Phồn thể)": "橛", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vật có dạng cọc gỗ nhỏ cắm xuống đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矸', '{"9000": "4965.0", "Chữ Trung Quốc": "矸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 8 | nét | 石 | thạch | biểu nghĩa | đá | 干 | can | biểu âm | can, khô | 矸 = 石 (Thạch, biểu nghĩa: đá) + 干 (Can, biểu âm); chữ hình thanh. Bộ 石 chỉ chất liệu đá khoáng, phần 干 cho âm đọc gān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"can\": đá (石) can thiệp vào than — 矸 là đá xít vô ích lẫn lộn trong mỏ than, khiến khai thác thêm khó. | Gương Hán-Việt | can trong 矸石 (can thạch — đá xít khai mỏ) | Mở khoá kiến thức | Biết 矸 là thuật ngữ khai mỏ quan trọng: 矸石 (đá xít) xuất hiện trong báo cáo môi trường ngành than.", "Tự nguyên_Xie": "Wiktionary xác nhận: hình thanh gồm 石 (đá, biểu nghĩa) và 干 (biểu âm). 矸 chỉ đá xít, đá lẫn trong than đá (gangue rock), là loại đá vô ích lẫn lộn trong mỏ khoáng sản. Thuật ngữ khai mỏ: 矸石 (gān shí) — đá xít khai thác than. Chưa có nguồn học thuật về lịch sử hình dạng cụ thể. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá lẫn trong than đá, đá bìa", "Hạng Tần Suất (Jun Da)": "4965.0", "Tần Suất % (Jun Da)": "99.9187980686", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矸", "Unihan_Traditional (Chữ Phồn thể)": "矸", "Pinyin_Xie": "gān", "Âm Hán Việt_Xie": "can", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong các thuật ngữ địa chất hoặc khai khoáng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸨', '{"9000": "4966.0", "Chữ Trung Quốc": "鸨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 9 | nét | 鸨 | bảo | tượng hình | chim bảo (bustard) — loài chim lớn đồng bằng; người phụ nữ làm chủ kỹ viện | 鸨 là giản thể của 鴇. Chữ gốc 鴇 thuộc bộ 鳥 (điểu, chim). Chưa có dữ liệu cấu tạo chi tiết trong CHISE. Chữ hình thanh hoặc hình tượng, chưa xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảo\": con chim bảo (鴇) to lớn như vàng bảo — 鸨 vừa là loài chim đồng bằng, vừa là ẩn dụ dân gian cho người phụ nữ quản lý nhà kỹ. | Gương Hán-Việt | bảo trong 老鸨 (lão bảo — bà chủ nhà kỹ), 鴇羽 (bảo vũ — cánh chim bảo, từ Kinh Thi) | Mở khoá kiến thức | Biết 鸨 nhận ra ngay 老鸨 trong văn học cổ và kịch bản lịch sử Trung Quốc.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi nhận 鴇 (chữ gốc): chim bảo (bustard — loài chim lớn sống đồng cỏ, nổi tiếng trong Kinh Thi); nghĩa mở rộng: chủ kỹ viện (procuress, female brothel-keeper); cũng chỉ ngựa đốm đen trắng. Đại triện và tiểu triện đều có hình ảnh chứng nhận. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim bảo (giống con mòng, tương truyền là giống rất dâm)", "Hạng Tần Suất (Jun Da)": "4966.0", "Tần Suất % (Jun Da)": "99.9188926403", "GavinGrover_Once (Chiết tự trực tiếp)": "𠤏 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𠤏鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠤏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸨", "Unihan_Traditional (Chữ Phồn thể)": "鴇", "Pinyin_Xie": "bǎo", "Âm Hán Việt_Xie": "bảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim lội nước hoặc dùng để chỉ chủ nhà chứa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圻', '{"9000": "4967.0", "Chữ Trung Quốc": "圻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 斤 | cân | biểu âm | cân, rìu | 圻 = 土 (Thổ, biểu nghĩa: đất) + 斤 (Cân, biểu âm); chữ hình thanh. Bộ 土 chỉ đất, ranh giới lãnh thổ; 斤 cho âm đọc qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kì\": đất (土) phân chia ranh giới kì lạ — 圻 là đường biên giới, mốc lãnh thổ được vạch trên đất. | Gương Hán-Việt | kì trong 圻疆 (kì cương — biên cương lãnh thổ) | Mở khoá kiến thức | Biết 圻 nhận ra nhóm chữ ranh giới/lãnh thổ trong văn chính trị cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận: hình thanh gồm 土 (đất, biểu nghĩa) và 斤 (biểu âm). 圻 mang nghĩa ranh giới, biên giới lãnh thổ (border, boundary). Cũng đọc là yín trong một số phương ngữ. Tiểu triện đã ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "261.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (255) Cân (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thổ (số 255) và chữ Cân (số 196) . Đất (thổ) bị kẻ xâm lược dùng rìu sức mạnh (cân) chia cắt thành các vùng, các kỳ (vd: Nam Kỳ, Bắc Kỳ). Giải thích sự chuyển ý: Chữ Cân (cái rìu) chỉ âm, chữ Thổ (đất) chỉ ý. Dùng rìu (Cân) đánh dấu trên đất (Thổ) để chia ranh giới, bờ cõi (Kỳ). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Cân và chữ Kỳ có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Cân và Kỳ).*", "Nghĩa Tiếng Việt_Xie": "giới hạn; bờ biển", "Hạng Tần Suất (Jun Da)": "4967.0", "Tần Suất % (Jun Da)": "99.9189872119", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "圻", "Unihan_Traditional (Chữ Phồn thể)": "圻", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ ranh giới hoặc vùng đất bao quanh kinh đô thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缂', '{"9000": "4968.0", "Chữ Trung Quốc": "缂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缂 | khắc | tượng hình | sợi ngang trong vải dệt; kỹ thuật dệt gấm cắt sợi | 缂 là giản thể của 緙. Chữ thuộc bộ 糸 (mịch, sợi tơ). Chưa có dữ liệu cấu tạo chi tiết trong CHISE. Chủ yếu dùng trong thuật ngữ nghề dệt: 缂丝 (gấm thêu cắt sợi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khắc\": sợi tơ (糸) khắc thành hoa văn — 缂 là kỹ thuật dệt gấm bậc thầy, mỗi sợi ngang khắc một màu riêng. | Gương Hán-Việt | khắc trong 缂丝 (khắc ti — lụa gấm cắt sợi, di sản dệt Trung Quốc) | Mở khoá kiến thức | Biết 缂 mở ra 缂丝 — kỹ thuật dệt lụa cao cấp nhất Trung Quốc, di sản UNESCO.", "Tự nguyên_Xie": "Wiktionary ghi 緙 mang nghĩa sợi ngang trong đồ dệt (woof of a woven item). Âm đọc kè. Kỹ thuật 緙絲 (缂丝) là nghệ thuật dệt lụa đặc biệt của Trung Quốc — mỗi màu sắc được tạo bằng cách dệt từng đoạn sợi riêng lẻ, tạo ra bức tranh hai mặt giống nhau. Di sản phi vật thể UNESCO. Chưa có phân tích glyph origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi khổ của đồ dệt", "Hạng Tần Suất (Jun Da)": "4968.0", "Tần Suất % (Jun Da)": "99.9190817836", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 革", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟革", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "革", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缂", "Unihan_Traditional (Chữ Phồn thể)": "緙", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ kỹ thuật dệt tơ lụa thủ công truyền thống của Trung Quốc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒯', '{"9000": "4969.0", "Chữ Trung Quốc": "蒯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒯 | khoái | tượng hình | cỏ khoái dùng dệt vải; họ Khoái | 蒯 chưa có dữ liệu nguồn gốc trong Wiktionary (glyphOrigin null). Chữ thuộc bộ 艸 (thảo, cây cỏ). Dựa vào bộ thủ, có thể là hình thanh hoặc chỉ thị, nhưng không có nguồn xác nhận. Chỉ có hình lục thư thông (Lục thư thông) từ hanziyuan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\": cỏ (艸) mọc khoái chí um tùm — 蒯 là loài cỏ lác cứng dùng đan chiếu dệt vải thô thời xưa. | Gương Hán-Việt | khoái trong họ Khoái (蒯通 — Khoái Thông, mưu sĩ thời Hán) | Mở khoá kiến thức | Biết 蒯 nhận ra họ Khoái trong lịch sử Hán Sở: Khoái Thông (蒯通) là mưu sĩ khuyên Hàn Tín phản Lưu Bang.", "Tự nguyên_Xie": "Lục thư thông | Không có phân tích glyph origin từ Wiktionary cho 蒯. Chữ mang nghĩa cỏ khoái — một loại cỏ lác dùng để dệt chiếu, vải thô. Cũng là họ người (họ Khoái). Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ khoái (dùng dệt vải); họ Khoái", "Hạng Tần Suất (Jun Da)": "4969.0", "Tần Suất % (Jun Da)": "99.9191763553", "GavinGrover_Once (Chiết tự trực tiếp)": "萠 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰萠刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "萠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "蒯", "Unihan_Traditional (Chữ Phồn thể)": "蒯", "Pinyin_Xie": "kuǎi", "Âm Hán Việt_Xie": "khoái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ dai hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诹', '{"9000": "4970.0", "Chữ Trung Quốc": "诹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 言 | ngôn | biểu nghĩa | nói, thảo luận | 取 | thủ | biểu âm | lấy, chọn | 诹 = 言 (Ngôn, biểu nghĩa: lời nói, thảo luận) + 取 (Thủ, biểu âm và biểu nghĩa: chọn lấy); chữ hình thanh kiêm hội ý. Wiktionary ghi nhận cả ls=psc và ls=ic: nói chuyện (言) để chọn lựa (取) — tham khảo ý kiến. Chữ dùng trong văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": dùng lời (言) thủ thỉ như con trâu — 诹 là hành động hỏi han, tham khảo người khác để chọn điều tốt nhất. | Gương Hán-Việt | trâu trong 诹吉 (trâu cát — chọn ngày tốt lành) | Mở khoá kiến thức | Biết 诹 mở ra 诹吉 — từ dùng trong nghi lễ hôn nhân, lễ lạt khi chọn ngày tốt.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary phân tích hai lớp: (1) Hình thanh — 言 biểu nghĩa: nói, thảo luận; 取 biểu âm; (2) Hội ý — lời nói + chọn lựa = tham khảo, hỏi ý kiến. Chữ gốc là 諏. 诹吉 (zōu jí) là thành ngữ chỉ chọn ngày tốt. 诹访 (諏訪) là địa danh ở Nhật Bản. Tiểu triện đã ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chọn ngày tốt", "Hạng Tần Suất (Jun Da)": "4970.0", "Tần Suất % (Jun Da)": "99.9192704102", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 取", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠取", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诹", "Unihan_Traditional (Chữ Phồn thể)": "諏", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "tưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn viết cổ để chỉ việc hội ý hoặc chọn ngày lành. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啭', '{"9000": "4971.0", "Chữ Trung Quốc": "啭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 啭 | chuyển | tượng hình | tiếng chim hót líu lo, trầm bổng du dương | 啭 là giản thể của 囀 (thay 轉→转). Chữ gốc 囀 gồm bộ 口 (khẩu, miệng/tiếng) và 轉 (chuyển, quay vần) biểu âm. Chữ hình thanh: miệng (口) phát ra âm thanh vần (轉) — tiếng chim hót luyến láy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyển\": miệng (口) chuyển vần điệu liên tục — 啭 là tiếng chim hót vần vút lên xuống như giai điệu. | Gương Hán-Việt | chuyển trong 啼啭 (đề chuyển — tiếng chim hót lảnh lót), 啭鸣 (chuyển minh — hót véo von) | Mở khoá kiến thức | Biết 啭 mở ra ngữ cảnh thơ thiên nhiên Đường Tống: tiếng chim xuân trong vườn.", "Tự nguyên_Xie": "Wiktionary ghi 啭 là giản thể của 囀, xem mục 囀. Chữ gốc 囀 mô tả tiếng chim hót trầm bổng (sing, chirp, warble, twitter). Cấu trúc hình thanh: 口 (tiếng nói, âm thanh) + 轉/转 (biểu âm: quay, vần). Hình ảnh thơ: tiếng chim xuân líu lo vần vần trong thơ Đường Tống. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng trầm bổng", "Hạng Tần Suất (Jun Da)": "4971.0", "Tần Suất % (Jun Da)": "99.9193644651", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 转", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口转", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "转", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啭", "Unihan_Traditional (Chữ Phồn thể)": "囀", "Pinyin_Xie": "zhuàn", "Âm Hán Việt_Xie": "chuyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ miêu tả tiếng chim hót líu lo hoặc làm danh từ chỉ âm thanh đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饧', '{"9000": "4972.0", "Chữ Trung Quốc": "饧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 6 | nét | 饧 | đường | tượng hình | kẹo mạch nha; mật đường; bột dẻo mềm | 饧 là giản thể của 餳. Chữ thuộc bộ 食 (thực, ăn uống). Chưa có dữ liệu cấu tạo chi tiết trong CHISE. Chữ liên quan đến thức ăn ngọt, dẻo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": ăn (食) đường mạch nha ngọt lịm — 饧 là kẹo mật dẻo dính, ngọt sắc dân dã. | Gương Hán-Việt | đường trong 餳糖 (đường đường — đường mạch nha), 饧眼 (đường nhãn — mắt lờ đờ buồn ngủ) | Mở khoá kiến thức | Biết 饧 mở ra hình ảnh kẹo mạch nha dân gian và từ mô tả trạng thái mơ màng: 餳眼.", "Tự nguyên_Xie": "Wiktionary ghi nhận 餳: (1) kẹo mạch nha, mật (treacle, molasses, syrup); (2) bột/kẹo mềm dẻo sau khi để lâu; (3) buồn ngủ, mơ màng. Âm đọc xíng (phổ biến hơn) và táng (= 糖). Chưa có phân tích glyph origin cụ thể. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẹo mạch nha", "Hạng Tần Suất (Jun Da)": "4972.0", "Tần Suất % (Jun Da)": "99.91945852", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饧", "Unihan_Traditional (Chữ Phồn thể)": "餳", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường làm danh từ chỉ kẹo mạch nha hoặc làm tính từ chỉ trạng thái uể oải, mềm nhũn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镉', '{"9000": "4973.0", "Chữ Trung Quốc": "镉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 镉 | cách | tượng hình | nguyên tố cadmium (Cd) — kim loại độc hại màu trắng bạc | 镉 là giản thể của 鎘. Chữ thuộc bộ 金 (kim, kim loại). Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể. Là chữ tạo muộn phục vụ phiên dịch tên nguyên tố hóa học phương Tây vào tiếng Hán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": kim (金) loại cứng rắn cách biệt — 镉 là cadmium, kim loại độc hại cách ly khỏi môi trường sống. | Gương Hán-Việt | cách trong 镉污染 (cách ô nhiễm — ô nhiễm cadmium), 镉电池 (cách điện trì — pin cadmium) | Mở khoá kiến thức | Biết 镉 đọc tên nguyên tố Cd trong sách hóa học và báo cáo môi trường Trung Quốc.", "Tự nguyên_Xie": "Wiktionary chỉ có marker {{Han etym}} cho 鎘 mà không có phân tích. Chữ gồm bộ 金 (kim loại, biểu nghĩa) — phần còn lại biểu âm gé. Cadmium (Cd) được đặt tên bằng chữ này trong hóa học Hán ngữ. Kim loại nặng, độc hại, dùng trong pin Ni-Cd. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố cadmi, Cd", "Hạng Tần Suất (Jun Da)": "4973.0", "Tần Suất % (Jun Da)": "99.9195525749", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镉", "Unihan_Traditional (Chữ Phồn thể)": "鎘", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nguyên tố hóa học Cd, thường dùng trong lĩnh vực khoa học kỹ thuật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸪', '{"9000": "4974.0", "Chữ Trung Quốc": "鸪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 古 | cổ | biểu âm | cũ, xưa | 鳥 | điểu | biểu nghĩa | chim | 鸪 = 古 (Cổ, biểu âm) + 鳥/鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鳥 chỉ loài chim, phần 古 cho âm đọc gū. Chữ gốc là 鴣.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": con chim (鳥) hót tiếng cô cô — 鸪 là chim cô, tên dùng trong tổ hợp 鷓鴣 (chim cát cô rừng nhiệt đới). | Gương Hán-Việt | cô trong 鷓鸪 (giá cô — chim cát cô), 鵓鸪 (bột cô — bồ câu hoang) | Mở khoá kiến thức | Biết 鸪 mở ra 鷓鴣 — loài chim hay xuất hiện trong thơ Tống và tên từ bài (鷓鴣天).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận: hình thanh gồm 古 (biểu âm) và 鳥 (chim, biểu nghĩa). Chữ gốc 鴣 chủ yếu dùng trong tên loài chim: 鷓鴣 (chim cát cô — francolin, loài chim rừng châu Á) và 鵓鴣 (bồ câu hoang). Tiểu triện đã ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim cô", "Hạng Tần Suất (Jun Da)": "4974.0", "Tần Suất % (Jun Da)": "99.9196466298", "GavinGrover_Once (Chiết tự trực tiếp)": "古 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰古鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸪", "Unihan_Traditional (Chữ Phồn thể)": "鴣", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các chữ khác để tạo thành danh từ chỉ tên loài chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛩', '{"9000": "4975.0", "Chữ Trung Quốc": "蛩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛩 | cùng | tượng hình | dế mèn; châu chấu; sinh vật huyền thoại | 蛩 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 虫 (trùng, sâu bọ). Hình dạng có thể gồm bộ 虫 và phần âm, nhưng chưa có phân tích học thuật xác nhận. Chữ mang nhiều nghĩa tùy ngữ cảnh văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cùng\": con sâu (虫) hót cùng đêm lạnh — 蛩 là tiếng dế mèn đêm thu buồn bã trong thơ cổ. | Gương Hán-Việt | cùng trong 寒蛩 (hàn cùng — dế mùa lạnh), 秋蛩 (thu cùng — dế mùa thu), 吟蛩 (ngâm cùng — dế ngâm nga) | Mở khoá kiến thức | Biết 蛩 nhận ra hình ảnh thơ: tiếng dế đêm thu là ẩn dụ cho nỗi cô đơn và tao nhã trong thơ Đường Tống.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 蛩 mang hai âm đọc: qióng (dế mèn, châu chấu; tên sinh vật huyền thoại 蛩蛩) và gǒng (rết — nghĩa đã lỗi thời). Tiểu triện và lục thư thông đều có hình ảnh. Chưa có phân tích glyph origin chi tiết. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con châu chấu; con sâu lúa", "Hạng Tần Suất (Jun Da)": "4975.0", "Tần Suất % (Jun Da)": "99.9197406847", "GavinGrover_Once (Chiết tự trực tiếp)": "巩 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巩虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛩", "Unihan_Traditional (Chữ Phồn thể)": "蛩", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong văn thơ cổ để chỉ con dế mèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠖', '{"9000": "4976.0", "Chữ Trung Quốc": "蠖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蠖 | oắc | tượng hình | sâu bướm thước (inchworm) — co duỗi từng bước để di chuyển | 蠖 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 虫 (trùng). Chủ yếu dùng trong tổ hợp 尺蠖 (xích oắc — con sâu thước) và thành ngữ 蠖屈求伸. Chưa xác định rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oắc\": con sâu (虫) co oắc người lại rồi duỗi ra — 蠖 là sâu đo, ẩn dụ kiên nhẫn chờ thời. | Gương Hán-Việt | oắc trong 尺蠖 (xích oắc — sâu đo), 蠖屈求伸 (oắc khuất cầu thân — co mình chờ thời) | Mở khoá kiến thức | Biết 蠖 mở ra thành ngữ 蠖屈求伸 — người tạm thời thu mình lại để sau vươn lên.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi: 蠖 là viết tắt của 尺蠖 (inchworm — sâu đo, sâu thước). Âm đọc huò; một âm đọc khác yuè chỉ dùng trong 蠖略. Tiểu triện và lục thư thông đều có hình ảnh. Chưa có phân tích glyph origin chi tiết. Chữ chủ yếu sống trong thành ngữ 蠖屈求伸: co lại để rồi duỗi ra — ẩn dụ cho sự chờ thời cơ. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: xích oách 尺蠖); (xem: oách khuất 蠖屈)", "Hạng Tần Suất (Jun Da)": "4976.0", "Tần Suất % (Jun Da)": "99.9198347396", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠖", "Unihan_Traditional (Chữ Phồn thể)": "蠖", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "oách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ loài sâu đo hoặc ẩn dụ về sự co duỗi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劭', '{"9000": "4977.0", "Chữ Trung Quốc": "劭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 7 | nét | 劭 | thiệu | tượng hình | khuyến khích, nỗ lực; xuất sắc, cao thượng | 劭 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 力 (lực, sức mạnh). Có thể là hình thanh với 力 biểu nghĩa (sức, khuyến khích) và phần còn lại biểu âm, nhưng chưa có phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiệu\": dùng sức (力) thiệu dương người khác — 劭 là lời khuyến khích cao thượng, nâng đỡ đức hạnh người. | Gương Hán-Việt | thiệu trong 年高德劭 (niên cao đức thiệu — tuổi cao đức trọng), 劭农 (thiệu nông — khuyến khích nông nghiệp) | Mở khoá kiến thức | Biết 劭 mở ra cụm 年高德劭 — câu khen tặng người cao tuổi có đức hạnh trong văn chương lễ nghi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 劭 mang nghĩa: (1) khuyến khích (to encourage — văn ngôn); (2) tốt, xuất sắc (good, eminent). Thành ngữ: 年高德劭 (niên cao đức thiệu — tuổi cao đức trọng). Tiểu triện và lục thư thông đều có hình ảnh. Chưa có phân tích glyph origin chi tiết. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuyên gắng; tốt; cao", "Hạng Tần Suất (Jun Da)": "4977.0", "Tần Suất % (Jun Da)": "99.9200223326", "GavinGrover_Once (Chiết tự trực tiếp)": "召 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰召力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "劭", "Unihan_Traditional (Chữ Phồn thể)": "劭", "Pinyin_Xie": "shào", "Âm Hán Việt_Xie": "thiệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ biểu thị sự tốt đẹp, cao thượng hoặc làm động từ khuyên răn trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哐', '{"9000": "4978.0", "Chữ Trung Quốc": "哐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 哐 | khuông | tượng hình | tiếng loảng xoảng, tiếng kim loại va chạm mạnh | 哐 chưa có dữ liệu nguồn gốc trong Wiktionary (glyphOrigin null). Chữ thuộc bộ 口 (khẩu, miệng — chỉ âm thanh). Là chữ tượng thanh (onomatopoeia): bộ 口 biểu thị đây là âm thanh, phần còn lại cho âm đọc kuāng mô phỏng tiếng va đập. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuông\": miệng (口) phát ra tiếng khuông — 哐 là tiếng loảng xoảng, tiếng đập ầm vào vật cứng. | Gương Hán-Việt | khuông trong 哐当 (khuông đang — tiếng loảng xoảng, ầm), 哐哐 (khuông khuông — tiếng gõ ầm ầm) | Mở khoá kiến thức | Biết 哐 nhận ra nhóm chữ tượng thanh bộ 口: 哐, 哗, 哒, 咣 — đều mô phỏng tiếng động cụ thể.", "Tự nguyên_Xie": "Không có phân tích glyph origin từ Wiktionary cho 哐. Chữ là tượng thanh thuần túy: mô phỏng tiếng kim loại hay vật cứng va chạm mạnh (loảng xoảng, ầm). Bộ 口 chỉ âm thanh, phần còn lại tái tạo âm kuāng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loảng xoảng (từ tượng thanh)", "Hạng Tần Suất (Jun Da)": "4978.0", "Tần Suất % (Jun Da)": "99.9201158707", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 匡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口匡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哐", "Unihan_Traditional (Chữ Phồn thể)": "哐", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Dùng làm từ tượng thanh mô tả tiếng va đập lớn của kim loại hoặc cửa gỗ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崧', '{"9000": "4979.0", "Chữ Trung Quốc": "崧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi | 松 | tùng | biểu âm | cây thông | 崧 = 山 (Sơn, biểu nghĩa: núi) + 松 (Tùng, biểu âm); chữ hình thanh. Bộ 山 chỉ núi cao, phần 松 cho âm sōng. Mang nghĩa núi cao lộng lẫy, núi lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tùng\": núi (山) cao vút như cây tùng — 崧 là ngọn núi hùng vĩ, sừng sững như rừng tùng bách. | Gương Hán-Việt | tùng trong 崧高 (tùng cao — bài thơ Kinh Thi ca ngợi núi cao), biến thể của 嵩 | Mở khoá kiến thức | Biết 崧 nhận ra mối liên hệ với 嵩山 (Tung Sơn) — một trong Ngũ Nhạc của Trung Hoa.", "Tự nguyên_Xie": "Wiktionary xác nhận: hình thanh gồm 山 (núi, biểu nghĩa) và 松 (biểu âm). 崧 mang nghĩa núi cao, lộng lẫy (high mountain, lofty, eminent). Là dạng biến thể của 嵩 (tên núi Tung Sơn 嵩山 — ngọn núi thiêng ở Hà Nam). Chưa có hình ảnh etymology. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Bài hát", "Hạng Tần Suất (Jun Da)": "4979.0", "Tần Suất % (Jun Da)": "99.9202094088", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 松", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山松", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "松", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崧", "Unihan_Traditional (Chữ Phồn thể)": "崧", "Pinyin_Xie": "sōng", "Âm Hán Việt_Xie": "tùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả núi non cao vút hoặc dùng làm danh từ trong tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杼', '{"9000": "4980.0", "Chữ Trung Quốc": "杼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 杼 | trữ | tượng hình | thoi dệt vải; loài sồi; thuôn dài | 杼 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 木 (mộc, gỗ). Có thể là hình thanh với bộ 木 biểu nghĩa (vật dụng gỗ) và phần còn lại biểu âm, nhưng chưa xác nhận từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": gỗ (木) trữ lại thành cái thoi — 杼 là con thoi dệt vải, nhắc đến điển tích Mạnh Mẫu gương mẫu dạy con. | Gương Hán-Việt | trữ trong 机杼 (cơ trữ — khung cửi và thoi dệt), 断机杼 (đoạn cơ trữ — cắt thoi dạy con) | Mở khoá kiến thức | Biết 杼 mở ra điển tích 断机杼 của Mạnh Mẫu — hình mẫu người mẹ hi sinh dạy con trong văn hóa Á Đông.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 杼 mang nhiều nghĩa: (1) thoi dệt vải (shuttle of loom); (2) thuôn dài (narrow); (3) đầu dài; (4) cây sồi bụi (scrub oak); (5) mỏng. Nổi tiếng qua điển tích: Mạnh Mẫu cắt thoi (断机杼) để dạy con chuyên cần. Tiểu triện và lục thư thông đều có hình ảnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thoi dệt vải", "Hạng Tần Suất (Jun Da)": "4980.0", "Tần Suất % (Jun Da)": "99.9203029469", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 予", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木予", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "予", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杼", "Unihan_Traditional (Chữ Phồn thể)": "杼", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ dụng cụ dệt vải, thường xuất hiện trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棂', '{"9000": "4981.0", "Chữ Trung Quốc": "棂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 棂 | ranh | tượng hình | chấn song cửa sổ; ô cửa chạm khắc | 棂 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 木 (mộc, gỗ). Chữ gốc là 欞, liên quan đến 櫺. Chủ yếu chỉ các thanh gỗ song song hoặc hoa văn chạm khắc trên cửa sổ truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ranh\": gỗ (木) chia thành từng ô ranh giới — 棂 là chấn song cửa sổ, những thanh gỗ chạm khắc tinh tế phân chia ánh sáng. | Gương Hán-Việt | ranh trong 棂格 (ranh cách — ô chấn song), 棂星门 (Ranh Tinh Môn — cổng Linh Tinh ở Văn Miếu) | Mở khoá kiến thức | Biết 棂 nhận ra thuật ngữ kiến trúc cổ: cổng Linh Tinh (棂星门) trước Văn Miếu ở Hà Nội và Trung Quốc.", "Tự nguyên_Xie": "Wiktionary ghi 棂 là dạng biến thể của 欞 (và 櫺). Âm đọc líng. Chữ chỉ chấn song cửa sổ chạm khắc hoa văn (carved or patterned window sills/grills) trong kiến trúc cổ Trung Quốc. Chưa có phân tích glyph origin chi tiết. Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chấn song cửa sổ", "Hạng Tần Suất (Jun Da)": "4981.0", "Tần Suất % (Jun Da)": "99.920396485", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 灵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木灵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "棂", "Unihan_Traditional (Chữ Phồn thể)": "櫺", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các thanh gỗ ngang dọc trên khuôn cửa sổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螫', '{"9000": "4982.0", "Chữ Trung Quốc": "螫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 赦 | xá | biểu âm | tha tội, tha thứ | 虫 | trùng | biểu nghĩa | sâu bọ | 螫 = 赦 (Xá, biểu âm) + 虫 (Trùng, biểu nghĩa: sâu bọ); chữ hình thanh. Bộ 虫 chỉ côn trùng có nọc, phần 赦 cho âm đọc shì. Tiểu triện và lục thư thông đều có hình ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thích\": con sâu (虫) đốt xá — 螫 là cú đốt của ong/nhện, nọc độc tiêm vào da thịt. | Gương Hán-Việt | thích trong 螫伤 (thích thương — vết đốt của côn trùng), 蠍螫 (yết thích — nọc bọ cạp) | Mở khoá kiến thức | Biết 螫 mở ra thuật ngữ y tế: 螫伤 (vết côn trùng đốt) và các thành ngữ cảnh báo nguy hiểm.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary xác nhận: hình thanh gồm 赦 (biểu âm) và 虫 (sâu bọ, biểu nghĩa). 螫 mang nghĩa đốt, chích (to sting, to bite) của côn trùng có nọc như ong, nhện, bọ cạp. Văn ngôn và tiếng Hokkien dùng phổ biến. Cũng dùng cho hành động mổ của vịt ngỗng trong tiếng Chương Châu Hokkien. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nọc độc", "Hạng Tần Suất (Jun Da)": "4982.0", "Tần Suất % (Jun Da)": "99.9204900231", "GavinGrover_Once (Chiết tự trực tiếp)": "赦 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱赦虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螫", "Unihan_Traditional (Chữ Phồn thể)": "螫", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động côn trùng dùng ngòi độc để chích hoặc đốt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龃', '{"9000": "4983.0", "Chữ Trung Quốc": "龃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 13 | nét | 龃 | trở | tượng hình | răng không khớp; bất hòa, mâu thuẫn | 龃 là giản thể của 齟 (thay 齒→齿). Chữ thuộc bộ 齿 (xỉ, răng). Chữ gốc 齟 gồm bộ 齒 (răng, biểu nghĩa) và phần biểu âm. Chữ hình thanh. Chủ yếu dùng trong tổ hợp 龃龉 (trở ngữ — bất hòa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trở\": răng (齿) trở trăn không khớp — 龃 là hàm răng lộn xộn, ẩn dụ cho sự bất đồng không thể hòa hợp. | Gương Hán-Việt | trở trong 龃龉 (trở ngữ — bất hòa, lục đục), 齟齬 (phồn thể) | Mở khoá kiến thức | Biết 龃 mở ra thành ngữ 龃龉 — từ chỉ sự bất hòa, xung khắc thường dùng trong văn chính trị và ngoại giao.", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi 龃 là giản thể của 齟, xem mục 齟. Chữ 齟 chỉ hàm răng không khớp (irregular teeth), từ đó mở rộng nghĩa: bất đồng, mâu thuẫn (discord). Tổ hợp 龃龉 là thành ngữ quan trọng chỉ sự bất hòa, lục đục. Lục thư thông có hình ảnh. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trở ngữ 齟齬,龃龉)", "Hạng Tần Suất (Jun Da)": "4983.0", "Tần Suất % (Jun Da)": "99.9205835612", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龃", "Unihan_Traditional (Chữ Phồn thể)": "齟", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "trở", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ trong từ ghép để chỉ sự bất đồng hoặc không ăn khớp nhau. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饔', '{"9000": "4984.0", "Chữ Trung Quốc": "饔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 22 | nét | 饔 | ung | tượng hình | bữa cơm sáng; thức ăn đã nấu chín (đặc biệt là thịt) | 饔 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 食 (thực, ăn uống). Kim văn và tiểu triện đều có hình ảnh. Chưa xác định rõ hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ung\": ăn (食) buổi sáng ung dung — 饔 là bữa ăn sáng, thức ăn nấu chín mà người hầu dọn lên cho chủ. | Gương Hán-Việt | ung trong 饔飧 (ung thoán — bữa sáng và bữa tối), 饔飧不继 (ung thoán bất kế — miếng ăn bữa trước chẳng còn bữa sau) | Mở khoá kiến thức | Biết 饔 mở ra thành ngữ 饔飧不继 — chỉ cảnh nghèo khó không đủ ăn.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi nhận 饔: (1) thức ăn đã nấu chín, đặc biệt là thịt (cooked food, especially meat); (2) bữa ăn sáng (breakfast). Kim văn (bronze) và tiểu triện đều có hình ảnh chứng nhận. Thành ngữ: 饔飧 (ung thoán — bữa sáng và bữa tối); 饔飧不继 (ung thoán bất kế — không đủ ăn). Chưa có phân tích glyph origin chi tiết. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bữa cơm sáng", "Hạng Tần Suất (Jun Da)": "4984.0", "Tần Suất % (Jun Da)": "99.9206770993", "GavinGrover_Once (Chiết tự trực tiếp)": "雍 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雍食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "饔", "Unihan_Traditional (Chữ Phồn thể)": "饔", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn viết cổ để chỉ bữa cơm sáng hoặc đồ ăn đã nấu chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遑', '{"9000": "4985.0", "Chữ Trung Quốc": "遑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 遑 | hoàng | tượng hình | thư nhàn, rảnh rỗi; vội vàng; làm sao (trong câu hỏi tu từ) | 遑 chưa có dữ liệu cấu tạo trong CHISE. Chữ thuộc bộ 辵 (xước, đi lại). Có thể gồm bộ 辵 biểu nghĩa (đi, di chuyển) và phần biểu âm, nhưng chưa có phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": bước chân (辵) hoàng mang vội vã — 遑 là trạng thái không có thời gian rảnh, quá bận rộn đến mức hoảng loạn. | Gương Hán-Việt | hoàng trong 不遑 (bất hoàng — không kịp, bận không có thời gian), 遑论 (hoàng luận — huống chi, không nói đến) | Mở khoá kiến thức | Biết 遑 mở ra 不遑多让 (bất hoàng đa nhượng — không kém cạnh gì), 遑论 (huống chi là...).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 遑 mang nghĩa trong văn ngôn: (1) thời gian rảnh, thư thái (free time, leisure); (2) vội vàng, hấp tấp (hurried, hasty); (3) làm sao (trong câu hỏi tu từ how/how can); (4) biến thể của 徨 và 惶. Tiểu triện đã có hình ảnh. Thành ngữ: 不遑 (bất hoàng — không kịp, không có thời gian). | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kíp, gấp; nhàn rỗi", "Hạng Tần Suất (Jun Da)": "4985.0", "Tần Suất % (Jun Da)": "99.9207706374", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遑", "Unihan_Traditional (Chữ Phồn thể)": "遑", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm phó từ đứng trước động từ trong câu hỏi tu từ để biểu thị không có thời gian rảnh làm việc gì. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颢', '{"9000": "4986.0", "Chữ Trung Quốc": "颢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 18 | nét | 景 | canh | biểu nghĩa | ánh sáng ban ngày, cảnh vật | 頁 | hiệt | biểu nghĩa | đầu, tóc | 颢 = 景 (Canh, biểu nghĩa: ánh sáng ban ngày) + 頁 (Hiệt, biểu nghĩa: đầu/tóc); chữ hội ý. Theo Thuyết văn giải tự chú: ánh sáng mặt trời rực rỡ chiếu lên mái tóc trắng — tượng trưng cho sự trắng sáng. Chữ hội ý, không phải hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạo\": ánh sáng (景) soi đầu bạc (頁) — 颢 là màu trắng rực rỡ, hình ảnh trời đất bao la sáng ngời. | Gương Hán-Việt | hạo trong 颢气 (hạo khí — khí trời trong sáng bao la), 颢颢 (hạo hạo — trắng sáng rực rỡ) | Mở khoá kiến thức | Biết 颢 nhận ra nhóm chữ hạo-trắng trong văn ngôn: 皓, 浩, 颢 — đều chỉ sự rực sáng, trong trẻo bao la.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi rõ: hội ý gồm 景 (ánh sáng ban ngày) và 頁 (đầu/tóc). Theo Thuyết văn giải tự chú: biểu trưng ánh nắng rực rỡ và mái tóc trắng bạc — chỉ sự trắng sáng, rực rỡ. 顥 mang nghĩa trắng và sáng (white and shining). Tiểu triện đã ghi nhận. Chữ gốc là 顥, giản thể 颢. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hạo hạo 顥顥,颢颢)", "Hạng Tần Suất (Jun Da)": "4986.0", "Tần Suất % (Jun Da)": "99.9208641755", "GavinGrover_Once (Chiết tự trực tiếp)": "景 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰景页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "景", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颢", "Unihan_Traditional (Chữ Phồn thể)": "顥", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ để miêu tả ánh sáng trắng hoặc bầu trời bao la, thường xuất hiện trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腱', '{"9000": "4987.0", "Chữ Trung Quốc": "腱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 建 | kiến | biểu âm | xây dựng, lập | 腱 = 肉/月 (Nhục, biểu nghĩa: thịt, mô cơ thể) + 建 (Kiến, biểu âm); chữ hình thanh. Wiktionary ghi rõ: nguyên gốc là 䇟, sau thêm bộ 肉. Bộ 肉 chỉ mô sinh học, phần 建 cho âm jiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiện\": thịt (肉) kiện cường xây dựng sức mạnh — 腱 là sợi gân nối cơ với xương, nền tảng vận động. | Gương Hán-Việt | kiện trong 肌腱 (cơ kiện — gân cơ), 腱子 (kiện tử — bắp thịt/gân cổ chân trâu bò) | Mở khoá kiến thức | Biết 腱 mở ra 肌腱 (gân cơ), 腱鞘 (bao gân) — thuật ngữ y tế quan trọng trong chấn thương thể thao.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận: 腱 gốc là 䇟. Hình thanh gồm 肉 (thịt/cơ thể, biểu nghĩa) và 建 (biểu âm). Tiểu triện đã ghi nhận cấu trúc này. 腱 chỉ gân (tendon) — mô liên kết nối cơ với xương. Thành phần quan trọng trong giải phẫu học và y học Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầu gân", "Hạng Tần Suất (Jun Da)": "4987.0", "Tần Suất % (Jun Da)": "99.9209571969", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 建", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月建", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "建", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腱", "Unihan_Traditional (Chữ Phồn thể)": "腱", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "kiện, kiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần mô liên kết sợi dai nối cơ với xương trong giải phẫu học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襁', '{"9000": "4988.0", "Chữ Trung Quốc": "襁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 17 | nét | 衤 | y | biểu nghĩa | y phục, vải | 強 | cường | biểu âm | mạnh (phonetic) | 襁 là chữ hình thanh: 衤 (Y, biểu nghĩa: vải, y phục) kết hợp với 強/强 (Cường, biểu âm). Tổng hợp lại chỉ dải vải rộng dùng địu trẻ em trên lưng. Cấu trúc hình thanh — âm mượn từ 強, nghĩa từ bộ vải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cưỡng\": tưởng tượng mẹ ''cưỡng'' (bất chấp mệt mỏi) vẫn dùng dải vải 衤 địu con — 襁 là dải vải địu trẻ. | Gương Hán-Việt | cưỡng — ít dùng độc lập; thường thấy trong 襁褓 (cưỡng bảo): khăn quấn, tã lót trẻ sơ sinh | Mở khoá kiến thức | Biết 襁 giúp hiểu 襁褓 (qiǎng bǎo / cưỡng bảo) — thành ngữ chỉ thời thơ ấu, tuổi sơ sinh trong văn chương.", "Tự nguyên_Xie": "Chữ 襁 (qiǎng) chỉ dải vải rộng dùng để địu trẻ sơ sinh trên lưng, hoặc động từ ''địu trẻ''. Thường xuất hiện trong từ ghép 襁褓 (qiǎng bǎo) — tã lót, khăn quấn trẻ sơ sinh. Chữ dùng bộ 衤 (vải, y phục) làm phần biểu nghĩa, âm mượn từ một thành phần phát âm tương tự. Nguồn Wiktionary xác nhận đây là chữ hình thanh, chưa có nguồn học thuật rõ ràng về lớp glyph cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái địu trẻ sau lưng", "Hạng Tần Suất (Jun Da)": "4988.0", "Tần Suất % (Jun Da)": "99.9210502182", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 强", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤强", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "强", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襁", "Unihan_Traditional (Chữ Phồn thể)": "繦", "Pinyin_Xie": "qiǎng", "Âm Hán Việt_Xie": "cưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ tấm vải hoặc dây đai dùng để bọc và địu trẻ nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忾', '{"9000": "4989.0", "Chữ Trung Quốc": "忾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忾 | khái | tượng hình | chữ giản thể của 愾; tự thân là ký hiệu cảm xúc | 忾 là dạng giản thể của 愾. Chữ 愾 gồm bộ 心 (tâm, biểu nghĩa: tâm hồn, cảm xúc) và 气 (khí, biểu âm). Đây là chữ hình thanh: tâm trạng phẫn uất, căm ghét kẻ thù. Dạng giản thể 忾 lược bỏ bộ 心 viết tách, nhập vào dạng 忄.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khái\": 忾 chứa bộ 忄 (tim) — khi ''khái'' (phẫn khái, căm phẫn) tim bùng lửa căm thù kẻ địch. | Gương Hán-Việt | khái — xuất hiện trong 敵忾 (địch khái): căm thù kẻ thù chung; 同仇敵忾 (đồng cừu địch khái): cùng chung lòng căm phẫn | Mở khoá kiến thức | Biết 忾 giúp hiểu thành ngữ 同仇敵忾 — cùng lòng căm thù kẻ địch, dùng trong văn chính trị và văn học.", "Tự nguyên_Xie": "忾 (kài) là dạng giản thể của 愾, nghĩa là ''oán hận, căm ghét, tức giận''. Âm thứ hai là xì (hí), nghĩa ''thở dài''. Wiktionary ghi nhận chữ 愾 gồm bộ 心 (tâm, cảm xúc) và thành phần biểu âm. Chữ 忾 thường xuất hiện trong 同仇敵愾/忾 — cùng lòng căm thù kẻ địch. Cấu trúc hình thanh, chưa có dữ liệu glyph cổ rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "căm thù; căm ghét; căm giận", "Hạng Tần Suất (Jun Da)": "4989.0", "Tần Suất % (Jun Da)": "99.9211427227", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 气", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄气", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "气", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忾", "Unihan_Traditional (Chữ Phồn thể)": "愾", "Pinyin_Xie": "kài", "Âm Hán Việt_Xie": "hất, khái, hi, khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ hoặc động từ trong các từ ghép chỉ lòng căm thù quân địch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濠', '{"9000": "4990.0", "Chữ Trung Quốc": "濠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 17 | nét | 氵 | thủy | biểu nghĩa | nước | 豪 | hào | biểu âm | hào kiệt (phonetic) | 濠 là chữ hình thanh: 氵 (Thủy, biểu nghĩa: nước) + 豪 (Hào, biểu âm). Chữ chỉ hào nước — con hào, rãnh nước bao quanh thành trì. Âm đọc mượn từ 豪, nghĩa gắn với nước qua 氵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": 氵 (nước) + 豪 (hào kiệt) — vị ''hào kiệt'' nào cũng cần hào nước bao quanh thành để bảo vệ; 濠 = hào thành đầy nước. | Gương Hán-Việt | hào — xuất hiện trong 濠沟 (hào câu): hào rãnh; 濠州 (Hào Châu): địa danh lịch sử | Mở khoá kiến thức | Biết 濠 giúp đọc điển cố 濠梁之辩 (Hào Lương chi biện) — cuộc tranh luận triết học của Trang Tử; cũng liên kết với 壕 (hào lũy chiến trường).", "Tự nguyên_Xie": "濠 (háo) nghĩa là hào nước, hào thành, rãnh. Wiktionary xác nhận: 濠 = 氵 (nước, biểu nghĩa) + 豪 (biểu âm). Dạng biến thể của 壕 (hào — hào lũy). Địa danh nổi tiếng: 濠州 (Hào Châu, tên cổ của Phượng Dương, quê nhà Chu Nguyên Chương). Trong điển cố 濠梁之辩 (cuộc tranh luận trên cầu Hào) — cuộc đối thoại nổi tiếng giữa Trang Tử và Huệ Tử về sự hiểu biết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "419.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Hào (348)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Hào (số 348 - hào kiệt) . Đào rãnh cho nước (Thủy) bao quanh thành lũy vững chắc như anh hào (Hào) để bảo vệ gọi là hào nước. Giải thích sự chuyển ý: Chữ Hào (hào kiệt) chỉ âm, chữ Thủy (nước) chỉ ý. Rãnh nước (Thủy) đào quanh thành trì (Hào).", "Nghĩa Tiếng Việt_Xie": "hào xây quanh thành", "Hạng Tần Suất (Jun Da)": "4990.0", "Tần Suất % (Jun Da)": "99.9212352273", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 豪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵豪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濠", "Unihan_Traditional (Chữ Phồn thể)": "濠", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ hào nước sâu bao quanh thành trì để phòng thủ hoặc làm địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牝', '{"9000": "4991.0", "Chữ Trung Quốc": "牝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 6 | nét | 牛 | ngưu | biểu nghĩa | trâu bò, gia súc | 匕 | tỷ | biểu âm | cái thìa (phonetic) | 牝 là chữ hình thanh: 牛 (Ngưu, biểu nghĩa: gia súc, con vật) + 匕 (Tỷ, biểu âm). Chỉ gia súc cái, con vật cái nói chung. Đối nghĩa với 牡 (mẫu — con đực). Cấu trúc hình thanh, âm từ 匕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẫn\": 牛 (trâu bò) + 匕 (cái thìa — hình cong, gợi nữ tính) — con trâu cái, giống cái của gia súc. | Gương Hán-Việt | tẫn — trong 牝牡 (tẫn mẫu): đực-cái; 牝鸡 (tẫn kê): gà mái; 牝马 (tẫn mã): ngựa cái | Mở khoá kiến thức | Biết 牝 giúp đọc văn ngôn cổ: 牝牡 (đực cái), 牝鸡司晨 (gà mái gáy sáng — ẩn dụ người phụ nữ lấn át).", "Tự nguyên_Xie": "牝 (pìn) chỉ con vật giống cái, gia súc cái. Wiktionary ghi: 牝 = 牛 (gia súc, biểu nghĩa) + 匕 (biểu âm). Đây là chữ cổ đối lập với 牡 (mẫu — con đực). Trong Kinh Dịch, 牝 mang tính âm, nhu, đất (khôn). Thành ngữ 牝牡 (tẫn mẫu) chỉ cặp đực-cái. Chữ hình thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cái (loài chim)", "Hạng Tần Suất (Jun Da)": "4991.0", "Tần Suất % (Jun Da)": "99.9213277318", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "牝", "Unihan_Traditional (Chữ Phồn thể)": "牝", "Pinyin_Xie": "pìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm tính từ hạn định đứng trước danh từ chỉ động vật để xác định giới tính cái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛄', '{"9000": "4992.0", "Chữ Trung Quốc": "蛄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 古 | cổ | biểu âm | cổ xưa (phonetic) | 蛄 là chữ hình thanh: 虫 (Trùng, biểu nghĩa: côn trùng, sâu bọ) + 古 (Cổ, biểu âm). Chữ chỉ dế nhũi (mole cricket) hoặc tép vỏ cứng (mantis shrimp 虾蛄). Cấu trúc hình thanh đơn giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\": con 虫 (sâu) + 古 (âm cổ/gū) — con dế nhũi ''cổ'' (gū) kêu đào đất từ thời ''cổ'' xưa. | Gương Hán-Việt | cổ — xuất hiện trong 蝼蛄 (lâu cổ): dế nhũi; 虾蛄 (hà cổ): tôm tích | Mở khoá kiến thức | Biết 蛄 giúp nhận diện 蝼蛄 (lóugū) — dế nhũi trong thành ngữ 蟪蛄不知春秋 (ve sầu nhỏ không biết xuân thu — ý chỉ tầm nhìn ngắn hạn, từ Nam Hoa Kinh).", "Tự nguyên_Xie": "蛄 (gū) chỉ loài dế nhũi (蝼蛄, lóugū) — loại côn trùng đào đất, hay phá hoại rễ cây. Cũng dùng trong 虾蛄 (xiāgū) — tép tích / tôm tích, giáp xác nhỏ. Wiktionary xác nhận cấu trúc: 虫 (côn trùng, biểu nghĩa) + 古 (biểu âm). Chữ hình thanh thuần túy. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lâu cô 螻蛄,蝼蛄; huệ cô 蟪蛄)", "Hạng Tần Suất (Jun Da)": "4992.0", "Tần Suất % (Jun Da)": "99.9214202363", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛄", "Unihan_Traditional (Chữ Phồn thể)": "蛄", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ và hầu như chỉ xuất hiện trong các từ ghép tên gọi loài côn trùng như lâu cô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲆', '{"9000": "4993.0", "Chữ Trung Quốc": "鲆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 鱼 | ngư | biểu nghĩa | cá | 平 | bình | biểu nghĩa | phẳng | 鲆 là chữ hội ý: 鱼 (Ngư, cá) + 平 (Bình, phẳng) — con cá phẳng, cá dẹt. Wiktionary xác nhận ls=ic (hội ý): ''a flat fish, a flounder''. Tên chữ mô tả hình dạng đặc trưng của loài cá bơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": 鱼 (cá) + 平 (bằng phẳng) — con cá ''bình'' (phẳng dẹt) nằm sát đáy biển; 鲆 = cá bơn. | Gương Hán-Việt | bình — ít dùng độc lập; 牙鲆 (nha bình): cá bơn hàm — loại cá bơn phổ biến ở Đông Á | Mở khoá kiến thức | Biết 鲆 giúp nhận diện tên các loài cá biển trong văn bản thủy sản, ẩm thực Trung Hoa; liên kết với họ cá bơn (Bothidae).", "Tự nguyên_Xie": "鲆 (píng) chỉ cá bơn thuộc họ Bothidae — loài cá thân dẹt nằm nghiêng dưới đáy biển. Wiktionary ghi rõ: 鱼 (cá, biểu nghĩa) + 平 (phẳng, biểu nghĩa) = cá phẳng, hội ý. Đây là chữ hội ý thuần túy, mô tả đặc điểm hình dạng. Chữ được tạo muộn để đặt tên khoa học cho loài cá bơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá bơn vỉ ôliu", "Hạng Tần Suất (Jun Da)": "4993.0", "Tần Suất % (Jun Da)": "99.9215127409", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲆", "Unihan_Traditional (Chữ Phồn thể)": "鮃", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ chung các loài cá thân bẹt thuộc họ cá bơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗄', '{"9000": "4994.0", "Chữ Trung Quốc": "嗄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng, giọng nói | 夏 | hạ | biểu âm | mùa hạ (phonetic) | 嗄 là chữ hình thanh: 口 (Khẩu, biểu nghĩa: miệng, giọng nói) + 夏 (Hạ, biểu âm). Chữ chỉ giọng khàn khàn, khàn tiếng. Âm phonetic từ 夏 (shà/xià).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": 口 (miệng) + 夏 (hạ, nóng bức) — mùa hạ nóng, la hét nhiều khiến giọng trở nên khàn ''á á''; 嗄 = khàn tiếng. | Gương Hán-Việt | á — trong 嗄声 (á thanh): giọng khàn; 嘻嘻嗄嗄 (hí hí á á): tiếng cười ồn ào huyên náo | Mở khoá kiến thức | Biết 嗄 giúp đọc từ miêu tả âm thanh trong văn học: giọng khàn, tiếng ồn ào; liên kết với bộ 口 trong các chữ âm thanh.", "Tự nguyên_Xie": "嗄 (shà) nghĩa là giọng khàn, khàn tiếng. Âm thứ hai là á (tiếng kêu ngắn, thán từ trong tiếng Mân Nam). Wiktionary: 嗄 = 口 (miệng, biểu nghĩa) + 夏 (biểu âm). Chữ hình thanh, mô tả âm thanh phát ra từ miệng. Thường dùng trong từ ghép mô tả tiếng cười to, huyên náo (嘻嘻嗄嗄). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "a, ô (tiếng trợ ngữ)", "Hạng Tần Suất (Jun Da)": "4994.0", "Tần Suất % (Jun Da)": "99.9216047286", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 夏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口夏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗄", "Unihan_Traditional (Chữ Phồn thể)": "嗄", "Pinyin_Xie": "á", "Âm Hán Việt_Xie": "chới, hạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Trợ từ | 助词 | Tính từ | 形容词 | Chữ này thường dùng làm thán từ biểu thị sự ngạc nhiên hoặc làm tính từ mô tả giọng nói bị khản. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灏', '{"9000": "4995.0", "Chữ Trung Quốc": "灏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 21 | nét | 灏 | hạo | tượng hình | dạng giản thể của 灝; rộng lớn, mênh mông, sữa đậu nành | 灏 là dạng giản thể của 灝. Chữ phồn thể 灝 gồm bộ 氵 (thủy, nước) và thành phần phức tạp bên phải. Wiktionary ghi đây là biến thể của 浩 (hạo — rộng lớn). Cấu trúc cụ thể chưa có phân tích hình thanh/hội ý rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạo\": 灏 mang ý nghĩa ''hạo nhiên'' — rộng lớn bao la như trời đất; thường dùng đặt tên với hàm nghĩa cao thượng, rộng rãi. | Gương Hán-Việt | hạo — 灏气 (hạo khí): khí rộng lớn; 灝瀚 (hạo hãn): mênh mông rộng lớn; thường dùng trong tên người | Mở khoá kiến thức | Biết 灏 giúp đọc tên người Trung Hoa mang ý nghĩa ''rộng lớn, bao la''; liên kết với nhóm 浩/皓/顥 đồng âm hào.", "Tự nguyên_Xie": "灏 (hào) có hai nghĩa chính: (1) sữa đậu nành; (2) dạng thay thế của 浩 — rộng lớn, bao la. Cũng là biến thể của 皓/顥 — trắng sáng. Wiktionary liệt kê 灝溔 (hạo yểu — rộng mênh mông). Chữ tạo muộn, thường dùng làm tên người (ý nghĩa: rộng lớn, bao la). Nguồn glyph cổ chưa rõ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mênh mông", "Hạng Tần Suất (Jun Da)": "4995.0", "Tần Suất % (Jun Da)": "99.9216967164", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 颢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵颢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "颢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "灏", "Unihan_Traditional (Chữ Phồn thể)": "灝", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ mô tả sự rộng lớn bao la của sông nước hoặc dùng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疥', '{"9000": "4996.0", "Chữ Trung Quốc": "疥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 9 | nét | 疥 | giới | tượng hình | ghẻ, bệnh da do ký sinh trùng; bộ 疒 (bệnh) + 介 (biểu âm) | 疥 gồm bộ 疒 (nạch — biểu nghĩa: bệnh tật) và 介 (giới — biểu âm). Là chữ hình thanh: bộ 疒 chỉ đây là bệnh da, 介 cho âm đọc. Wiktionary chưa có phân tích hội ý/hình thanh rõ, nhưng cấu trúc 疒+介 là hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": bộ 疒 (bệnh) gợi người nằm bệnh + 介 (âm giới/jiè) — bệnh ghẻ ''giới'' khiến người ta gãi ngứa liên tục. | Gương Hán-Việt | giới — 疥疮 (giới sang): bệnh ghẻ; 疥癣 (giới tiển): ghẻ lác; 疥虫 (giới trùng): ký sinh trùng gây ghẻ | Mở khoá kiến thức | Biết 疥 giúp đọc văn y học cổ truyền và hiện đại: 疥疮 (bệnh ghẻ), 疥虫 (con ghẻ); liên kết với bộ 疒 trong các bệnh da.", "Tự nguyên_Xie": "疥 (jiè) chỉ bệnh ghẻ (scabies) — bệnh da do ký sinh trùng Sarcoptes gây ra, gây ngứa dữ dội. Cũng dùng cho bệnh mange ở động vật. Bộ 疒 (nạch) biểu nghĩa ''bệnh'', 介 (jiè) biểu âm. Thành ngữ 疥癞 (ghẻ lác). Chưa có dữ liệu glyph cổ từ Wiktionary; cấu trúc hình thanh, confidence medium. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghẻ lở", "Hạng Tần Suất (Jun Da)": "4996.0", "Tần Suất % (Jun Da)": "99.9217881874", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 介", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒介", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "介", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疥", "Unihan_Traditional (Chữ Phồn thể)": "疥", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ bệnh ghẻ hoặc các vết lở loét ngoài da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苜', '{"9000": "4997.0", "Chữ Trung Quốc": "苜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 目 | mục | biểu âm | mắt (phonetic) | 苜 là chữ hình thanh: 艹 (Thảo, biểu nghĩa: cỏ, thực vật) + 目 (Mục, biểu âm). Chỉ loài cỏ 苜蓿 (alfalfa / cỏ ba lá). Âm đọc mượn từ 目, nghĩa gắn với thực vật qua 艹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mục\": 艹 (cỏ) + 目 (mắt — âm mục) — loài cỏ mang âm ''mục'', chính là cỏ linh lăng 苜蓿, thức ăn của ngựa quý từ Tây Vực. | Gương Hán-Việt | mục — chỉ dùng trong 苜蓿 (mục túc): cỏ linh lăng (alfalfa) | Mở khoá kiến thức | Biết 苜 giúp nhận diện 苜蓿 (mùxu / mục túc) — cỏ linh lăng, loài cây từ thời Hán nhập vào Trung Hoa; xuất hiện trong sử liệu về con đường tơ lụa.", "Tự nguyên_Xie": "苜 (mù) chỉ xuất hiện trong tên cỏ 苜蓿 (mùxu) — cỏ linh lăng (alfalfa, Medicago sativa). Đây là từ phiên âm từ tiếng Ba Tư/Trung Á ''buksuk'', du nhập vào Trung Hoa qua con đường tơ lụa cùng với ngựa Fergana thời Hán Vũ Đế. Wiktionary xác nhận cấu trúc: 艹 (thực vật, biểu nghĩa) + 目 (biểu âm). Chữ hình thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mục túc 苜蓿)", "Hạng Tần Suất (Jun Da)": "4997.0", "Tần Suất % (Jun Da)": "99.9218796583", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "目", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苜", "Unihan_Traditional (Chữ Phồn thể)": "苜", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu kết hợp với chữ túc để tạo thành danh từ chỉ loài cỏ linh lăng làm thức ăn gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荞', '{"9000": "4998.0", "Chữ Trung Quốc": "荞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 乔 | kiều | biểu âm | cao, kiều (phonetic) | 荞 là dạng giản thể của 蕎. Chữ gốc 蕎 gồm 艹 (thảo, biểu nghĩa: thực vật) + 喬 (kiều, biểu âm). Chữ hình thanh. Giản thể đơn giản hóa 喬 → 乔.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": 艹 (cỏ) + 乔 (âm kiều/qiáo) — cây cỏ mang âm ''kiều'', chính là kiều mạch, nguyên liệu làm mì soba nổi tiếng. | Gương Hán-Việt | kiều — 荞麦 (kiều mạch): cây kiều mạch (buckwheat); 荞麦面 (kiều mạch diện): mì kiều mạch | Mở khoá kiến thức | Biết 荞 giúp nhận diện 荞麦 (kiều mạch) trên thực đơn, nhãn thực phẩm; liên kết với mì soba Nhật Bản cùng nguồn gốc.", "Tự nguyên_Xie": "荞 (qiáo) là dạng giản thể của 蕎, chỉ cây kiều mạch (buckwheat). Wiktionary: giản thể từ 蕎 với 喬 → 乔. Cây kiều mạch (荞麦 / 蕎麥) là ngũ cốc phổ biến ở Trung Hoa, dùng làm mì kiều mạch, bánh. Chữ hình thanh: 艹 (thực vật) + 乔/喬 (biểu âm). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa tám đen", "Hạng Tần Suất (Jun Da)": "4998.0", "Tần Suất % (Jun Da)": "99.9219711293", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 乔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹乔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荞", "Unihan_Traditional (Chữ Phồn thể)": "荍", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng trước các từ khác để chỉ cây kiều mạch hoặc các sản phẩm từ kiều mạch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘣', '{"9000": "4999.0", "Chữ Trung Quốc": "嘣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 嘣 | băng | tượng hình | tượng thanh: tiếng bụp, nổ, đập; tương tự 崩 (băng — sụp đổ) | 嘣 là chữ tượng thanh (onomatopoeia). Wiktionary ghi chú nó dùng âm tham chiếu từ 崩 (bēng). Chữ gồm bộ 口 (khẩu — miệng, âm thanh) và thành phần 朋 hoặc cấu trúc tương tự. Thuần túy mô tả âm thanh bụp, nổ, đập nhịp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"băng\": 嘣 nghe như tiếng ''bụp'' — viên kẹo nổ trong miệng, quả bóng vỡ, hay tim đập mạnh đều là 嘣嘣! | Gương Hán-Việt | băng — 嘣嘣跳 (băng băng khiêu): đập thình thịch (tim); 嘣的一声 (băng đích nhất thanh): một tiếng bụp | Mở khoá kiến thức | Biết 嘣 giúp đọc văn miêu tả âm thanh trong tiểu thuyết hiện đại; liên kết với nhóm tượng thanh bộ 口.", "Tự nguyên_Xie": "嘣 (bēng) là tượng thanh chỉ tiếng đập, nổ bụp, thổi vỡ. Wiktionary tham chiếu âm của 崩 (bēng — sụp đổ). Chữ dùng bộ 口 (miệng, âm thanh) kết hợp thành phần phonetic. Thường dùng trong văn nói, mô tả âm thanh như: tiếng tim đập 嘣嘣跳, tiếng nổ 嘣的一声. Chữ tạo muộn, không có glyph cổ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng kêu thình thịch, tiếng kêu đùng đùng", "Hạng Tần Suất (Jun Da)": "4999.0", "Tần Suất % (Jun Da)": "99.9220626003", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 崩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口崩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘣", "Unihan_Traditional (Chữ Phồn thể)": "嘣", "Pinyin_Xie": "bēng", "Âm Hán Việt_Xie": "băng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô tả tiếng nổ hoặc tiếng động đột ngột, sắc gọn. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夤', '{"9000": "5000.0", "Chữ Trung Quốc": "夤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 夕 | Số nét | 14 | nét | 夤 | dần | tượng hình | đêm khuya sâu; leo bám thế lực; chưa có nguồn học thuật rõ ràng về cấu trúc | 夤 thiếu dữ liệu cấu trúc rõ ràng từ nguồn học thuật. Chữ chỉ xuất hiện trong 夤夜 (đêm khuya sâu) và 夤缘 (leo bám bằng quan hệ thế lực). Chưa có nguồn học thuật; cấu trúc chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dần\": 夤 gợi ''dần dần'' vào đêm khuya sâu — 夤夜 là khi mọi người đã ngủ, chỉ còn tiếng ''dần dần'' của đêm tối. | Gương Hán-Việt | dần — 夤夜 (dần dạ): đêm khuya sâu; 夤缘 (dần duyên): leo bám thế lực bằng quan hệ | Mở khoá kiến thức | Biết 夤 giúp đọc văn học cổ điển Trung Hoa: 夤夜 (đêm sâu), 夤缘攀附 (leo bám bằng quyền lực) — thành ngữ phê phán cơ hội chủ nghĩa.", "Tự nguyên_Xie": "夤 (yín) có hai nghĩa chính trong văn ngôn: (1) 夤夜 — đêm khuya, nửa đêm sâu; (2) 夤缘 / 夤緣 — leo bám, trèo cao nhờ quan hệ thế lực (nghĩa xấu). Wiktionary không cung cấp phân tích cấu tạo chữ chi tiết. Chưa có nguồn học thuật rõ ràng về glyph cổ và cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiến lên; chỗ thắt lưng", "Hạng Tần Suất (Jun Da)": "5000.0", "Tần Suất % (Jun Da)": "99.9221540712", "GavinGrover_Once (Chiết tự trực tiếp)": "夕 + 寅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱夕寅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夕", "Unihan_Simplified (Chữ Giản thể)": "夤", "Unihan_Traditional (Chữ Phồn thể)": "夤", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "dần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ với nghĩa leo bám, nịnh bợ để tiến thân hoặc làm tính từ chỉ sự sâu xa, đêm khuya. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
